// scripts/gen-lessons.ts が自動生成する。手で直さない（元は data/lessons-*.ts。直したら npm run gen:lessons）。
import type { Lesson } from '../lesson-types';

const rows: string[] = [
"{\"id\":\"eigo_01_bunpo_kihon\",\"studyPeriod\":\"小6前半\",\"subject\":\"eigo\",\"title\":\"英語の基本文型と時制の完全マスター\",\"description\":\"入試の核心！5文型と時制のルールを体系的に学ぶ\",\"keyPoints\":[\"5文型：SV／SVC（S＝C）／SVO／SVOO（人＋物）／SVOC（O＝C）。動詞の後ろの語で見分ける\",\"be動詞は現在 am(I)／is(3人称単数)／are(you・複数)、過去 was／were。一般動詞は三単現で-s/-es（go→goes, have→has）\",\"過去形の不規則変化は「原形・過去形・過去分詞」をセットで暗記（go-went-gone / see-saw-seen 等）\",\"未来は will＋原形（その場の意志・予測）と be going to＋原形（前から決めた予定・根拠ある予測）\",\"現在完了 have/has＋過去分詞：継続 for/since、完了 just/already/yet、経験 ever/never/once。yesterday・〜agoなど過去の一点とは併用不可\",\"受動態は be動詞＋過去分詞（＋by〜）。be interested in／be known for／be made of／be covered with など前置詞セットで暗記\",\"仮定法過去 If＋過去形（be動詞はwere）, 主語＋would/could/might＋原形。仮定法過去完了 If＋had＋過去分詞\"],\"order\":1,\"sections\":[{\"heading\":\"1. 5文型の理解\",\"mangaId\":\"eigo_01_bunkeigo_manga\",\"body\":\"英語の文はすべて「5つの文型」に分類できる。これを理解すると、どんな長い文でも構造が見えてくる。\\n\\n■ 第1文型 SV（主語＋動詞）\\n主語が何かをするだけの最もシンプルな形。\\n例）He runs.（彼は走る）\\n例）The sun rises.（太陽が昇る）\\n例）Birds fly in the sky.（鳥たちは空を飛ぶ）\\n★ ポイント：修飾語（in the sky など）はあっても文型には含めない。\\n\\n■ 第2文型 SVC（主語＋動詞＋補語）\\n「S＝C（主語と補語がイコール）」になる形。be動詞や「〜になる・〜のように見える」という動詞が使われる。\\n例）She is kind.（彼女は親切だ ※she＝kind）\\n例）He became a doctor.（彼は医者になった）\\n例）The food smells good.（その食べ物はいいにおいがする）\\n★ ポイント：動詞の後ろが「形容詞」か「名詞」なら補語（C）になる。\\n\\n■ 第3文型 SVO（主語＋動詞＋目的語）\\n「Sが〜をVする」という形。目的語は動詞が表す動作の対象。\\n例）I love you.（私はあなたを愛している）\\n例）She reads books every day.（彼女は毎日本を読む）\\n例）We play soccer after school.（私たちは放課後サッカーをする）\\n⚠ 注意：「目的語」は名詞（人・もの）のみ。形容詞は目的語にならない。\\n\\n■ 第4文型 SVOO（主語＋動詞＋目的語①＋目的語②）\\n「SがO①にO②をVする」という形。目的語が2つある。\\n例）He gave me a book.（彼は私に本をくれた ※me＝目的語①、a book＝目的語②）\\n例）My mother made me lunch.（母は私に昼食を作ってくれた）\\n例）She told us the news.（彼女は私たちにニュースを教えてくれた）\\n★ ポイント：第4文型は「give＋人＋もの」の形に変換できる動詞で使われる（give/show/teach/tell/buy/make/send）。\\n\\n■ 第5文型 SVOC（主語＋動詞＋目的語＋補語）\\n「SがOをCにする・CとVする」という形。O＝Cの関係が成り立つ。\\n例）She made me happy.（彼女は私を幸せにした ※me＝happy）\\n例）We call him Ken.（私たちは彼をケンと呼ぶ）\\n例）They found the test easy.（彼らはそのテストが簡単だとわかった）\\n\\n■ 文型の見分け方まとめ\\n①動詞の後ろに何もない → SV（第1文型）\\n②動詞の後ろが「形容詞か名詞」でS＝C → SVC（第2文型）\\n③動詞の後ろに「名詞ひとつ」 → SVO（第3文型）\\n④動詞の後ろに「名詞＋名詞」 → SVOO（第4文型）\\n⑤動詞の後ろに「名詞＋形容詞or名詞」でO＝C → SVOC（第5文型）\\n⚠ 注意：第3文型と第4文型・第5文型の区別が入試で最も問われる。「O＝C」かどうかを確認しよう。\",\"figureId\":\"xf_eigo_01_bunpo_kihon\"},{\"heading\":\"2. 現在形・過去形・未来形\",\"body\":\"■ be動詞の活用\\n現在形：am（I）／is（he/she/it）／are（you/we/they）\\n過去形：was（I/he/she/it）／were（you/we/they）\\n例）I am a student. → I was a student.\\n例）She is happy. → She was happy.\\n\\n■ 一般動詞の現在形\\n・三人称単数（he/she/it）が主語のとき → 動詞に-sまたは-esをつける\\n・それ以外（I/you/we/they）→ 原形のまま\\n例）I play tennis. / He plays tennis.\\n例）She watches TV every night. （watch → watches）\\n⚠ 注意：go→goes / do→does / have→has など不規則なものも覚える。\\n\\n■ 一般動詞の過去形（規則変化）\\n■ -ed をつけるパターン：\\n・そのまま＋ed：play→played / want→wanted / help→helped\\n・eで終わる語＋d：like→liked / live→lived / use→used\\n・子音字＋y→yをiに変えて＋ed：study→studied / try→tried / carry→carried\\n・短母音＋子音字→子音字を重ねて＋ed：stop→stopped / plan→planned / drop→dropped\\n\\n■ 不規則変化動詞（重要49語）\\ngo→went / come→came / see→saw / do→did / have→had / make→made\\nget→got / give→gave / take→took / know→knew / think→thought\\nwrite→wrote / read→read（発音はred）/ run→ran / eat→ate\\nbuy→bought / bring→brought / teach→taught / catch→caught\\nfind→found / feel→felt / keep→kept / leave→left / meet→met\\nsay→said / speak→spoke / stand→stood / swim→swam / wear→wore\\nbegin→began / break→broke / choose→chose / drive→drove / fall→fell\\nforget→forgot / grow→grew / hold→held / hurt→hurt / mean→meant\\nput→put / send→sent / sit→sat / sleep→slept / tell→told\\nwin→won / lose→lost / understand→understood / become→became / hear→heard\\n\\n★ ポイント：入試では原形・過去形・過去分詞の3つをセットで覚える。\\n\\n■ 未来形：will vs be going to\\n・will＋原形：その場で決めたこと・予測・意志\\n例）I will help you. / It will rain tomorrow.\\n・be going to＋原形：前から決めていた計画・目に見えてわかる予測\\n例）I am going to study abroad next year.（前から決めていた）\\n例）Look at those clouds. It's going to rain.（今にも降りそう）\\n⚠ 注意：入試では「will」「be going to」どちらも「〜するつもりだ」と訳せるが、文脈で使い分ける。\"},{\"heading\":\"3. 進行形と完了形\",\"body\":\"■ 現在進行形（is/are + -ing）\\n「今ちょうど〜しているところだ」という意味。一時的な動作を表す。\\n形：am/is/are ＋ 動詞のing形\\n例）I am studying English now.（私は今英語を勉強しているところだ）\\n例）She is running in the park.（彼女は公園を走っているところだ）\\n\\n■ -ing形の作り方\\n・そのまま＋ing：play→playing / run→running（語末の子音を重ねる）\\n・eで終わる語はeをとって＋ing：make→making / write→writing\\n・ie→yに変えて＋ing：die→dying / lie→lying\\n\\n■ 過去進行形（was/were + -ing）\\n「〜していたところだった」という過去のある時点での動作。\\n例）I was sleeping when he called.（彼が電話したとき、私は眠っていた）\\n例）They were playing soccer at 3 p.m.（午後3時に彼らはサッカーをしていた）\\n\\n■ 現在完了形（have/has ＋ 過去分詞）の3用法\\n①経験用法「〜したことがある」：ever/never/before/once/twice などと一緒に使う\\n例）I have visited Tokyo twice.（私は東京を2回訪れたことがある）\\n例）Have you ever eaten sushi?（あなたはすし食べたことがありますか）\\n例）She has never been abroad.（彼女は一度も外国に行ったことがない）\\n\\n②継続用法「（ずっと）〜している」：since/for と一緒に使う\\n例）I have lived here for five years.（私は5年間ここに住んでいる）\\n例）She has been sick since last Monday.（彼女は先週の月曜日からずっと病気だ）\\n★ ポイント：for は「期間」（for three days）、since は「起点」（since 2020）。\\n\\n③完了用法「〜してしまった・〜したところだ」：already/yet/just などと一緒に使う\\n例）I have already finished my homework.（私はもう宿題を終えた）\\n例）Have you eaten lunch yet?（もう昼食を食べましたか）\\n例）She has just come home.（彼女はちょうど帰宅したところだ）\\n\\n⚠ 注意：現在完了形は「過去の一点を示す言葉（yesterday/last year/〜ago）」とは一緒に使えない。\\n×I have visited Tokyo last year.\\n○I visited Tokyo last year.（過去形を使う）\"},{\"heading\":\"4. 受動態（受け身）\",\"body\":\"受動態とは「〜される・〜された」という意味を表す形。能動態（主語が動作をする）と受動態（主語が動作をされる）の使い分けが入試でよく問われる。\\n\\n■ 受動態の基本形\\nbe動詞 ＋ 過去分詞（＋ by 〜）\\n例）This book is read by many people.（この本は多くの人に読まれている）\\n例）This cake was made by my mother.（このケーキは母によって作られた）\\n\\n■ 能動態 → 受動態への変換ルール\\n①能動態の目的語（O）を受動態の主語にする\\n②動詞をbe動詞＋過去分詞に変える\\n③能動態の主語は「by ＋ 主語（目的格）」で文末に置く\\n例）Ken painted this picture.（能動）\\n→ This picture was painted by Ken.（受動）\\n\\n例）They speak English in Australia.（能動）\\n→ English is spoken in Australia by them.（受動）※by themは省略可\\n\\n■ 時制ごとの受動態の形\\n・現在形：is/are ＋ 過去分詞\\n例）This room is cleaned every day.\\n・過去形：was/were ＋ 過去分詞\\n例）The window was broken yesterday.\\n・現在完了：have/has been ＋ 過去分詞\\n例）The letter has been written.\\n・助動詞：助動詞 ＋ be ＋ 過去分詞\\n例）This work must be done today.\\n\\n■ by 以外の前置詞を使う受動態（重要熟語）\\n・be known to 〜：〜に知られている\\n例）He is known to everyone in town.\\n・be known for 〜：〜で有名だ\\n例）Kyoto is known for its beautiful temples.\\n・be interested in 〜：〜に興味がある\\n例）I am interested in science.\\n・be surprised at 〜：〜に驚く\\n例）She was surprised at the news.\\n・be made from 〜：〜から作られる（原料が変化）\\n例）Wine is made from grapes.\\n・be made of 〜：〜から作られる（材料が変化しない）\\n例）This desk is made of wood.\\n・be covered with 〜：〜で覆われている\\n例）The mountain is covered with snow.\\n⚠ 注意：前置詞のセットは丸ごと覚える。入試では前置詞の選択問題が頻出。\"},{\"heading\":\"5. 入試例題（時制・受動態）\",\"body\":\"以下の問題を解いて、時制と受動態の理解を確認しよう。\\n\\n【問題1】（　）内から適切な語を選び、文を完成させなさい。\\nI ( have visited / visited / was visiting ) this museum three times.\\n\\n【解答】have visited\\n【解説】three times（3回）は「経験」を表す現在完了形のサインワード。yesterday などの過去の一点を示す語がないため、現在完了形を使う。\\n\\n【問題2】次の文を受動態に書き換えなさい。\\nTom made this chair.\\n\\n【解答】This chair was made by Tom.\\n【解説】① this chair（目的語）を主語にする ② made → was made（過去の受動態）③ Tom → by Tom で文末に。\\n\\n【問題3】（　）に適切な前置詞を入れなさい。\\nShe is interested (    ) playing the piano.\\n\\n【解答】in\\n【解説】be interested in 〜は「〜に興味がある」という重要熟語。後ろに動詞が来る場合は動名詞（-ing形）にする。\\n例）be interested in swimming / be interested in cooking\\n\\n★ 入試対策ポイント：\\n■ 時制のキーワードを覚える：already/yet/just/ever/never/for/since→現在完了、yesterday/last year/ago→過去形\\n■ 受動態の前置詞セットは丸暗記：be known for / be interested in / be surprised at / be made of / be made from\\n■ 能動態→受動態の変換は手順を守って確実に行う\"},{\"heading\":\"★ MAXレベル：複合時制と仮定法\",\"body\":\"■ 時制の一致（sequence of tenses）\\n主節が過去形のとき、従属節（that節など）の動詞も過去形（または過去完了形）に変える。これを「時制の一致」という。\\n\\n例）I think (that) he is busy.（現在形→現在形）\\n→ I thought (that) he was busy.（過去形→過去形）\\n\\n例）She says (that) she will come.（現在→未来）\\n→ She said (that) she would come.（過去→would）\\n\\n⚠ 注意：「不変の真理」や「習慣的事実」は時制の一致を受けない。\\n例）He said (that) the earth goes around the sun.（地球は太陽の周りを回る＝不変の真理）\\n\\n■ 仮定法過去（現在の事実と反対のことを仮定する）\\n形：If ＋ S ＋ 過去形（be動詞はwere）, S ＋ would/could/might ＋ 原形\\n意味：「もし〜ならば、…するのになぁ」（現実はそうではない）\\n例）If I were a bird, I could fly freely.\\n（もし私が鳥なら、自由に飛べるのになぁ→実際は人間）\\n例）If I had more money, I would buy that car.\\n（もしお金がもっとあれば、あの車を買うのになぁ→実際はお金がない）\\n\\n★ ポイント：仮定法ではI/he/she など人称に関係なくbe動詞はwereを使う。\\n（口語ではwasも使われるが、入試ではwereが正式）\\n\\n■ 仮定法過去完了（過去の事実と反対のことを仮定する）\\n形：If ＋ S ＋ had ＋ 過去分詞, S ＋ would/could/might ＋ have ＋ 過去分詞\\n意味：「もし〜していたならば、…していたのになぁ」（過去の後悔・反実仮想）\\n例）If I had studied harder, I would have passed the exam.\\n（もし一生懸命勉強していたら、試験に合格できたのになぁ→実際は不合格）\\n例）If she had left earlier, she could have caught the train.\\n（もっと早く出発していたら、電車に乗れたのになぁ）\\n\\n■ 仮定法とI wishの組み合わせ（入試頻出）\\nI wish ＋ 仮定法過去：「〜だったらいいのになぁ」（現在の事実への願望）\\n例）I wish I were taller.（背がもっと高ければいいのになぁ）\\nI wish ＋ 仮定法過去完了：「〜だったらよかったのになぁ」（過去への後悔）\\n例）I wish I had studied harder.（もっと勉強しておけばよかったなぁ）\\n\\n⚠ 入試の罠：仮定法は「形（過去形・過去完了形）が使われているのに現在や過去のことを言っている」という見た目との矛盾がポイント。文脈で見抜く練習をしよう。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_02_meishi_daimeishi\",\"studyPeriod\":\"小6前半\",\"subject\":\"eigo\",\"title\":\"名詞・代名詞・冠詞の完全理解\",\"description\":\"細かいがよく出る！冠詞と代名詞の使い分けをマスター\",\"keyPoints\":[\"可算名詞は複数形-s/-es・a/anがつく。不可算名詞（water/money/information/advice/news/homework）はa/an・複数形にできない\",\"many＋可算、much＋不可算、a lot ofは両方OK。few/a few＋可算、little/a little＋不可算\",\"someは肯定文と勧誘・依頼、anyは否定文・疑問文で使う\",\"a/anは初出「1つの」、theは既出・特定・世界に1つ（the sun/the moon）。a/anは発音で選ぶ（an hour, a university）\",\"人称代名詞の格：主格I／所有格my（名詞の前）／目的格me／所有代名詞mine（名詞の代わり）\",\"one/another/the other/others/the others の使い分け。全2つなら one と the other\",\"再帰代名詞 -self/-selves。by oneself は「ひとりで・独力で」\"],\"order\":2,\"sections\":[{\"heading\":\"1. 可算名詞と不可算名詞\",\"body\":\"名詞は「数えられる名詞（可算名詞）」と「数えられない名詞（不可算名詞）」に分かれる。この区別が冠詞・数量表現の使い方に直結するため、入試で頻出。\\n\\n■ 可算名詞（countable noun）\\n・1つ・2つと数えられるもの\\n例）book（本）/ apple（リンゴ）/ cat（猫）/ student（生徒）/ chair（いす）\\n・単数形にはa/anをつける、複数形は語尾に-sまたは-esをつける\\n例）a book → two books / an apple → five apples\\n\\n■ 不可算名詞（uncountable noun）\\n・数えられないもの（液体・素材・抽象概念・まとまりとして扱うもの）\\n例）water（水）/ milk（牛乳）/ rice（米）/ money（お金）/ information（情報）\\n　　music（音楽）/ news（ニュース）/ advice（助言）/ homework（宿題）\\n⚠ 注意：news・information・advice・homeworkはよく「複数のように見えるがsをつけない」不可算名詞の代表例。\\n×two informations　○two pieces of information\\n×a news　　　　　 ○a piece of news\\n\\n■ 数量表現の使い分け\\n・many ＋ 可算名詞の複数形：多くの〜（数えられるもの）\\n例）many books / many students\\n・much ＋ 不可算名詞：多くの〜（数えられないもの）\\n例）much water / much money\\n・a lot of / lots of ＋ 可算・不可算どちらも可：多くの〜\\n例）a lot of books / a lot of water\\n・few ＋ 可算名詞：ほとんど〜ない（否定的ニュアンス）\\n例）few students came to the party.（ほとんど生徒が来なかった）\\n・a few ＋ 可算名詞：少しある（肯定的ニュアンス）\\n例）I have a few friends in Tokyo.（東京に少し友達がいる）\\n・little ＋ 不可算名詞：ほとんど〜ない\\n例）He has little money.（彼はほとんどお金がない）\\n・a little ＋ 不可算名詞：少しある\\n例）I have a little time now.（今少し時間がある）\\n\\n■ someとanyの違い\\n・some：肯定文と「依頼・勧誘の疑問文」に使う\\n例）I have some books.（肯定）/ Would you like some coffee?（勧誘）\\n・any：否定文と疑問文に使う\\n例）Do you have any questions?（疑問）/ I don't have any money.（否定）\\n★ ポイント：Shall I give you some help? のように申し出のときはsomeを使う。\"},{\"heading\":\"2. 冠詞（a/an/the）の使い方\",\"body\":\"冠詞は英語の中でも特に日本人が苦手とする分野。ルールを整理して確実に得点しよう。\\n\\n■ a（an）の使い方\\n・初めて話題に出てくる名詞（初出）につける\\n例）I have a dog.（私は犬を飼っている→初めて出てきた）\\n・「1つの」という意味で使う\\n例）Give me a pencil.（1本鉛筆をください）\\n・aは子音始まりの語の前、anは母音（a/i/u/e/o）始まりの語の前\\n例）a book / a cat / a university（ユニバーシティ→発音はyu→子音扱い）\\n例）an apple / an hour（アワー→hは発音しない→母音扱い）\\n⚠ 注意：スペルではなく「発音」で判断する。\\n\\n■ the の使い方\\n・2回目以降に登場する名詞（既出・特定）につける\\n例）I have a dog. The dog is very cute.（最初はa、2回目からtheになる）\\n・文脈から特定できるもの\\n例）Please close the door.（その場にあるドアが特定されている）\\n・世界に1つしかないもの\\n例）the sun / the moon / the earth / the sky\\n・方角・海洋・川・山脈・諸島などの固有名詞\\n例）the Pacific Ocean / the Nile / the Alps / the Philippines\\n・楽器を演奏するとき\\n例）I play the piano. / She plays the violin.\\n・序数詞（1番目・2番目…）の前\\n例）the first / the second\\n\\n■ 冠詞が不要な場合\\n・固有名詞（人名・国名・都市名）：Japan / Tokyo / Tom（× the Japan）\\n・スポーツ・遊び：I play soccer.（× play the soccer）\\n・食事：We have lunch at noon.（× the lunch）\\n・交通手段：by bus / by train / by car\\n・抽象名詞・物質名詞（一般的な意味で使うとき）：I love music. / Time is money.\\n\\n★ ポイントまとめ：\\n・初出 → a/an\\n・2回目以降・特定 → the\\n・世界に1つ・固有名詞的扱い → the\\n・スポーツ・食事・固有名詞 → 冠詞不要\",\"figureId\":\"xf_eigo_02_meishi_daimeishi\"},{\"heading\":\"3. 人称代名詞と格変化\",\"mangaId\":\"eigo_02_daimeishi_manga\",\"body\":\"人称代名詞は文の中での役割（格）によって形が変わる。入試では空欄補充で格を選ぶ問題が頻出。\\n\\n■ 格変化一覧表\\n　人称／主格（〜は/が）／所有格（〜の）／目的格（〜を/に）／所有代名詞（〜のもの）\\n　1人称単数 … 主格（〜は/が）はI／所有格（〜の）はmy／目的格（〜を/に）はme／所有代名詞（〜のもの）はmine\\n　2人称単数 … 主格（〜は/が）はyou／所有格（〜の）はyour／目的格（〜を/に）はyou／所有代名詞（〜のもの）はyours\\n　3人称単数（男） … 主格（〜は/が）はhe／所有格（〜の）はhis／目的格（〜を/に）はhim／所有代名詞（〜のもの）はhis\\n　3人称単数（女） … 主格（〜は/が）はshe／所有格（〜の）はher／目的格（〜を/に）はher／所有代名詞（〜のもの）はhers\\n　3人称単数（もの） … 主格（〜は/が）はit／所有格（〜の）はits／目的格（〜を/に）はit／所有代名詞（〜のもの）は―\\n　1人称複数 … 主格（〜は/が）はwe／所有格（〜の）はour／目的格（〜を/に）はus／所有代名詞（〜のもの）はours\\n　2人称複数 … 主格（〜は/が）はyou／所有格（〜の）はyour／目的格（〜を/に）はyou／所有代名詞（〜のもの）はyours\\n　3人称複数 … 主格（〜は/が）はthey／所有格（〜の）はtheir／目的格（〜を/に）はthem／所有代名詞（〜のもの）はtheirs\\n\\n■ 格の使い方\\n・主格：動詞の主語になる → He is my brother.\\n・所有格：名詞の前に置く → This is my bag.\\n・目的格：動詞や前置詞の後ろに置く → She loves him. / This is for us.\\n・所有代名詞：名詞の代わりになる → This bag is mine.（= my bag）\\n\\n例）This is ( my / mine ) book. → my（後ろに名詞bookがあるから所有格）\\n例）This book is ( my / mine ). → mine（後ろに名詞がないから所有代名詞）\\n\\n■ 再帰代名詞（-self / -selves）\\nmyself / yourself / himself / herself / itself / ourselves / yourselves / themselves\\n①再帰用法：動詞の動作が主語自身に戻る場合\\n例）He hurt himself.（彼は自分自身を傷つけた）\\n例）She looked at herself in the mirror.（彼女は鏡で自分を見た）\\n②強調用法：主語・目的語を強調する（省略しても文意は変わらない）\\n例）I myself cooked this dish.（私自身がこの料理を作った）\\n例）She did the work herself.（彼女はその仕事を自分でした）\\n\\n⚠ 注意：by oneself は「ひとりで・独力で」という熟語。\\n例）She lives by herself.（彼女はひとりで暮らしている）\"},{\"heading\":\"4. 指示代名詞・不定代名詞\",\"mangaId\":\"eigo_02_shiji_daimeishi_manga\",\"body\":\"■ 指示代名詞\\n・this（これ）/ that（あれ）→ 単数\\n・these（これら）/ those（あれら）→ 複数\\n・近いものにはthis/these、遠いものにはthat/thoseを使う\\n例）This is my pen. / That is her bag.\\n例）These are my books. / Those are her shoes.\\n\\n★ that/those が「前出の名詞の繰り返しを避ける」ときに使われる用法\\n例）The climate of Osaka is warmer than that of Sapporo.\\n（that = the climate のくり返しを避けている）\\n\\n■ one / ones（前出の名詞の代用）\\n同じ種類のものを指すが、特定ではない（不特定の名詞を代用）\\n・one → 単数の可算名詞の代用\\n・ones → 複数の可算名詞の代用\\n例）I need a pen. Do you have one?（one＝ a pen の代用、特定のものではない）\\n例）I like the red ones better than the blue ones.（ones＝flowers等の複数名詞）\\n⚠ 注意：it は特定のものを指す（= the pen）、one は不特定（= a pen）\\n\\n■ other / another / others / the others の使い分け\\n4つの使い分けは入試で最も問われるポイントのひとつ。\\n\\n・another：「もう一つ（の）」→ 不特定の1つ（可算名詞単数の前）\\n例）I'd like another cup of tea.（もう1杯お茶をください）\\n\\n・other ＋ 名詞：「他の〜」→ 特定されていない複数\\n例）Do you have any other questions?（他に質問はありますか）\\n\\n・others（= other + 複数名詞の代わり）：「他の人々・他のもの」→ 不特定の複数\\n例）Some students like math, and others like English.（ある生徒は数学が好きで、他の人々は英語が好き）\\n\\n・the others：「残りすべて」→ 全体から一部を除いた残り全員・全部\\n例）I have three pens. One is red, and the others are blue.（1本は赤で、残りの2本はすべて青だ）\\n\\n★ 覚え方：全部で3つの場合 → one / another / the other（残りの1つ）\\n　　　　　全部で4つ以上の場合 → one / some / the others（残り全部）\"},{\"heading\":\"5. 入試例題\",\"body\":\"以下の問題を解いて、名詞・代名詞・冠詞の理解を確認しよう。\\n\\n【問題1】（　）内から正しいものを選びなさい。\\nMy father gave me ( a / the / × ) useful advice about my future.\\n\\n【解答】×（冠詞なし）\\n【解説】adviceは不可算名詞なのでa/anはつけられない。また初出・特定でもないのでtheも不要。「some useful advice」「a piece of advice」なら正しい。\\n\\n【問題2】（　）に適切な代名詞を入れなさい。\\nThat is not my umbrella. Mine is black. Where is (    )?\\n\\na) you   b) your   c) yours   d) yourself\\n\\n【解答】c) yours\\n【解説】「あなたのものはどこですか」という文。後ろに名詞がなく、所有代名詞（yours）を使う。yourは後ろに名詞が必要。\\n\\n【問題3】（　）に適切な語を選びなさい。\\nI have two cats. One is white, and (    ) is black.\\n\\na) other   b) another   c) the other   d) the others\\n\\n【解答】c) the other\\n【解説】全部で2匹のとき、1匹を「one」で示したら、残りの1匹は「the other」（残りのもう一方）。「the others」は残り全部（3つ以上の残り）。\\n\\n★ 入試対策ポイント：\\n■ 不可算名詞（information/advice/news/homework）にはa/anをつけない\\n■ 所有格（my）は名詞の前に、所有代名詞（mine）は名詞の代わりに\\n■ one/another/the other/others/the othersの使い分けは図で整理して覚える\"},{\"heading\":\"★ MAXレベル：複数形の例外と数量表現の精密使い分け\",\"body\":\"■ 不規則複数形（重要語一覧）\\n・child → children（子ども）\\n・man → men（男性） / woman → women（女性）\\n・foot → feet（足）/ tooth → teeth（歯）/ goose → geese（ガチョウ）\\n・mouse → mice（ネズミ） / louse → lice（シラミ）\\n・ox → oxen（雄牛）\\n・単複同形（単数と複数が同じ形）\\n　sheep → sheep / fish → fish / deer → deer / series → series / species → species\\n⚠ 注意：「fish」はふつう単複同形だが、種類のちがう魚をまとめて言うときは fishes ともなる。\\n\\n■ 常に複数形で使われる名詞（s がないと意味が変わる）\\n・scissors（はさみ）/ glasses（眼鏡）/ pants（ズボン）/ stairs（階段）\\n・これらは「a pair of 〜」で数える\\n例）a pair of scissors / two pairs of glasses\\n\\n■ 数量表現の精密な使い分け\\n・a few ≒「少しある」（肯定的）／few ≒「ほとんどない」（否定的）\\n例）I have a few friends here.（少し友達がいる → 良かった）\\n例）I have few friends here.（ほとんど友達がいない → 寂しい）\\n\\n・quite a few ＝「かなり多くの」（可算名詞、肯定的）\\n例）Quite a few people attended the meeting.（かなり多くの人が参加した）\\n⚠ 注意：「quite a few」は「ほんの少し」ではなく「かなり多く」という意味。見た目に騙されないこと。\\n\\n■ every / each / both / neither の使い方\\n・every ＋ 単数名詞：「すべての〜」全体をひとまとまりとして見る\\n例）Every student in our class studies hard.（動詞は単数形のstudies）\\n・each ＋ 単数名詞：「それぞれの〜」個々を強調\\n例）Each child has their own room.（動詞はhas）\\n・both ＋ 複数名詞：「両方の〜」（2つの対象）\\n例）Both students passed the exam.（動詞はpassed）\\n・neither ＋ 単数名詞：「どちらも〜ない」（2つのうちどちらも否定）\\n例）Neither student passed the exam.（どちらの生徒も合格しなかった）\\n・either ＋ 単数名詞：「どちらか一方の〜」\\n例）Either plan is fine.（どちらの計画でもいい）\\n\\n⚠ 入試の罠：every/each/either/neither のあとの動詞は単数扱い。both のあとは複数扱い。\\n×Every students are... → ○Every student is...\\n×Both student is... → ○Both students are...\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_03_dokkai\",\"studyPeriod\":\"小6後半・直前\",\"subject\":\"eigo\",\"title\":\"長文読解の攻略技術\",\"description\":\"入試英語の配点No.1！長文を速く正確に読む\",\"keyPoints\":[\"本文を読む前に設問・選択肢を先読みし、どこに答えがあるか予測する\",\"各段落の最初の文（topic sentence）に要点がある。時間がなければ各段落の頭を読む\",\"However/But＝逆接（後ろに主張）、Therefore/So＝結論、For example＝具体例、In addition＝追加\",\"知らない単語は文脈・言い換え・接頭辞接尾辞で推測（un-/re-/pre-、-tion/-ful/-less/-ly）\",\"内容一致は選択肢のキーワードを本文で探し、言い換え（visited＝went to 等）と主語・時・場所のすり替えに注意\",\"指示語（it/they/this）は直前1〜2文から探し、代入して意味が通るか確認\",\"Whyの答えはBecause〜。疑問詞に対応した内容を主語＋動詞の完全な文で答え、質問の時制に合わせる\"],\"order\":3,\"sections\":[{\"heading\":\"1. 長文読解の基本戦略\",\"body\":\"入試英語の長文読解は配点が最も高く、ここで差がつく。闇雲に最初から読み始めるのではなく、戦略的なアプローチが必要だ。\\n\\n■ 先読みの手順（最重要）\\n①まず設問（問い）と選択肢をすべて読む\\n②どこに答えが書いてあるかを予測する\\n③本文を読みながら答えを探す\\n\\n例）「第3段落の内容に合うものを選べ」という設問があれば、第3段落を重点的に読む。\\n先読みを習慣にするだけで読解の速度と正確さが格段に上がる。\\n\\n■ 段落ごとの中心文（topic sentence）の見つけ方\\n英語の文章は「各段落の最初の文（またはまとめの最後の文）が中心文（topic sentence）」になる論理構造が基本。\\n・最初の文：その段落で何を言うかを予告する\\n・中間の文：具体例・理由・補足説明\\n・最後の文：まとめ・次の段落へのつなぎ\\n\\n★ ポイント：topic sentenceを読むだけで段落の内容がわかる。時間が足りないときはtopic sentenceだけ読んで問いに答えることもできる。\\n\\n■ 接続詞による論理構造の把握\\n接続詞・接続副詞は文章の「流れのサイン」。読み方が変わるポイントで必ず止まって確認する。\\n\\n・However（しかし）→ 前の内容と逆のことが来る（重要な反転ポイント）\\n例）I like cats. However, I'm allergic to them.\\n\\n・Therefore / So（だから・したがって）→ 前の内容の結論が来る\\n例）He studied hard. Therefore, he passed the exam.\\n\\n・For example / For instance（たとえば）→ 前の内容の具体例が来る\\n例）Many animals hibernate. For example, bears sleep through winter.\\n\\n・In addition / Also / Furthermore（さらに・加えて）→ 同じ方向の内容が追加される\\n\\n・Although / Though / Even though（〜だけれども）→ 逆接のかたまりを作る\\n\\n⚠ 注意：Howeverが出てきたら前後の内容が逆になる。設問で「筆者の主張はどれか」と聞かれたときはHoweverの後ろに答えがあることが多い。\",\"figureId\":\"xf_eigo_03_dokkai\",\"mangaId\":\"eigo_03_dokkai_xm\"},{\"heading\":\"2. 語彙から文意を推測する方法\",\"body\":\"知らない単語が出てきても諦めない。文脈と語の成り立ちから意味を推測できる。\\n\\n■ 文脈（前後の文）からの推測\\n知らない単語があっても、その前後の文から意味を絞り込む。\\n\\n例）The scientist made a remarkable discovery. Her finding surprised everyone in the world.\\n→ \\\"discovery\\\" が何かわからなくても \\\"Her finding surprised everyone\\\" から「発見・発見したもの」と推測できる。\\n\\n■ 逆接・言い換えを使った推測\\n・However・but・on the other hand の後ろは反対の意味\\n例）He was very frugal; however, his brother was lavish.\\n→ frugal と lavish が逆の意味とわかる。brotherが「贅沢な」人なら frugal は「倹約的な」。\\n\\n・or・that is・in other words の後ろは言い換え（同義語）\\n例）She was loquacious, or talkative, at the party.\\n→ loquacious = talkative（おしゃべりな）とわかる。\\n\\n■ 接頭語（prefix）の意味\\n・un- / in- / im- / dis- ：否定・反対\\n例）unhappy（不幸な）/ impossible（不可能な）/ disagree（反対する）\\n・re- ：再び\\n例）replay（再び演じる）/ reuse（再利用する）/ return（戻る）\\n・pre- ：前もって\\n例）preview（試写）/ prepare（準備する）/ predict（予測する）\\n・mis- ：誤って\\n例）mistake（誤り）/ misunderstand（誤解する）\\n\\n■ 接尾語（suffix）の意味\\n・-tion / -sion：名詞（動作・状態）\\n例）education（教育）/ decision（決定）/ information（情報）\\n・-ment：名詞（結果・状態）\\n例）improvement（向上）/ movement（運動）/ excitement（興奮）\\n・-ness：名詞（性質・状態）\\n例）happiness（幸福）/ kindness（親切）/ darkness（暗さ）\\n・-ful：形容詞（〜に満ちた）\\n例）beautiful / helpful / colorful / careful\\n・-less：形容詞（〜がない）\\n例）careless（不注意な）/ homeless（家のない）/ useless（役に立たない）\\n・-ly：副詞（〜の方法で）\\n例）quickly / carefully / suddenly / fortunately\\n\\n★ ポイント：接頭語・接尾語がわかると初見の単語でも品詞と大まかな意味が推測できる。\"},{\"heading\":\"3. 設問タイプ別の解法\",\"body\":\"長文読解の設問にはいくつかのパターンがある。それぞれの解き方を覚えておくと確実に正解できる。\\n\\n■ 内容一致（T/F型・選択型）の解法\\n「本文の内容と合うものはどれか」「正しいものを選べ」という問い。\\n手順：\\n①選択肢の中のキーワードを本文の中で探す\\n②選択肢の文と本文の対応箇所を一語一語比較する\\n③言い換えに注意：同じ意味でも別の単語・表現が使われることがある\\n\\n例）選択肢：Tom visited Paris last year.\\n　　本文：Tom went to France in 2023.\\n→ visited＝went to、Paris＝France（Parisはフランスの都市）、last year＝in 2023、と対応している。\\n\\n⚠ 注意：「少し内容が変えてある誤り選択肢」に気をつける。主語・動作・時間・場所のどれか一つが違うことが多い。\\n例）本文：She gave him a book. → 誤り選択肢：He gave her a book.（主語と目的語が逆）\\n\\n■ 空所補充（linking word）の解法\\n「（　　）に入る最も適切な語句を選べ」という問い。\\n手順：\\n①空所の前後の文の論理関係を確認する（逆接？追加？理由？）\\n②その関係に合う接続語を選ぶ\\n\\n・逆接：However / But / Although / Nevertheless\\n・追加：In addition / Also / Furthermore / Moreover\\n・理由：Because / Since\\n・結果：Therefore / As a result\\n・例示：For example / For instance\\n\\n■ 表題選択問題（タイトル・テーマ）の解法\\n「この文章のタイトルとして最も適切なものはどれか」という問い。\\n手順：\\n①各段落のtopic sentenceを読む\\n②最後の段落（まとめの段落）を特に重視する\\n③広すぎず狭すぎない、本文全体をカバーするものを選ぶ\\n\\n⚠ 注意：一部の段落の内容しか反映していない選択肢は不正解。本文全体のテーマを選ぶ。\\n\\n■ 指示語問題（itやtheyが指すものを答える）\\n「下線部のitが指すものは何か」という問い。\\n手順：\\n①itやtheyより前の文から探す（通常1〜2文前にある）\\n②見つかったら代入して意味が通るか確認する\\n\\n例）I saw a dog. It was barking loudly. → It = a dog\"},{\"heading\":\"4. 記述問題（日本語・英語で答える）\",\"body\":\"記述問題は自分の言葉で答えるタイプで、差がつきやすい問題。形式とコツを覚えておく。\\n\\n■ 英語で答える場合\\n・必ず「主語＋動詞」を含めた完全な文で答える\\n・質問文の語を使って答える（使い回しOK）\\n・疑問詞で始まる質問→その疑問詞に対応した内容を答える\\n\\n例）Why did he go to the library?（なぜ彼は図書館に行ったのか）\\n→ Because he wanted to study English.（英語を勉強したかったから）\\n\\n例）What did she find in the box?（彼女は箱の中で何を見つけたか）\\n→ She found an old photo.（古い写真を見つけた）\\n\\n★ ポイント：\\n・Whoで聞かれたら「人」を答える\\n・Whereで聞かれたら「場所」を答える\\n・Whenで聞かれたら「時間・時期」を答える\\n・Howで聞かれたら「方法・状態」を答える\\n・Why は Because〜で答える（必ずBecauseから始める）\\n\\n■ 日本語で答える場合\\n・本文の対応箇所を見つけて、その日本語訳を基本にする\\n・補足が必要な場合は文脈から補う\\n・「〜について」「〜という理由で」などをつけて自然な日本語にする\\n・字数制限がある場合：超えないことが原則、不足しすぎても減点\\n\\n■ 字数制限に合わせたまとめ方\\n・長めに書いたものを削る方向で調整する\\n・「なぜなら〜だから」など理由の部分で字数を調整\\n・「〜ということ」などの体言止めを避け、「〜だから」「〜している」で終わる文にする\\n\\n⚠ 注意：英語で答えるとき、質問が過去形ならば答えも過去形にする。\\n例）Did she go to school? → Yes, she did. / No, she didn't.\\n例）Where does he live? → He lives in Osaka.（現在形で聞かれたら現在形で）\"},{\"heading\":\"5. 入試例題（読解）\",\"body\":\"以下の英文を読んで、問いに答えなさい。\\n\\n【英文】\\nEvery year, millions of people around the world try to learn a new language. Some do it for work, and others do it for travel or personal interest. However, many people give up before they can speak the language well. One reason is that they try to study too much grammar at the beginning. Instead, language experts suggest that listening and speaking should come first.\\n\\nChildren learn their first language not by studying textbooks, but by listening to people around them and trying to speak. In the same way, adult learners can improve their language skills by watching movies, listening to music, and having conversations with native speakers.\\n\\nOf course, grammar is also important. But it is more effective to learn grammar rules naturally, through real examples, than to memorize every rule from a book. The most successful language learners enjoy the process of learning, not just the goal of becoming fluent.\\n\\n【問題1】なぜ多くの人が新しい言語を習得する前に諦めてしまうのか、日本語で説明しなさい。（20字程度）\\n\\n【解答例】最初から文法を勉強しすぎてしまうから。\\n\\n【解説】第1段落の\\\"One reason is that they try to study too much grammar at the beginning.\\\"に対応。\\n\\n【問題2】下線部の \\\"In the same way\\\" は何と同じ方法を指すか。日本語で答えなさい。\\n\\n【解答例】周りの人の話を聞いて、話そうとすること。\\n\\n【解説】直前の \\\"listening to people around them and trying to speak\\\" が指す内容。\\n\\n【問題3】この文章のタイトルとして最も適切なものはどれか。\\na) The Importance of Grammar in Language Learning\\nb) How to Become Fluent in a Week\\nc) Effective Ways to Learn a New Language\\nd) Why Children Are Better Language Learners\\n\\n【解答】c)\\n【解説】文章全体が「言語学習の効果的な方法」について述べている。a)は一側面のみ、b)・d)は本文に合わない。\"},{\"heading\":\"★ MAXレベル：論説文・グラフ付き読解\",\"body\":\"■ グラフ・図表と組み合わせた読解問題\\n近年の入試では「グラフや表の読み取り」と「英文読解」を組み合わせた問題が増えている。\\n\\n解法のポイント：\\n①まずグラフの「タイトル・縦軸・横軸・単位」を確認する\\n②本文中にグラフに言及している箇所を探す（\\\"According to the chart...\\\" / \\\"As shown in the graph...\\\"）\\n③本文とグラフの数値・傾向を照合する\\n\\nよく使われるグラフ表現：\\n・increase / rise / go up：増加する\\n・decrease / fall / drop / go down：減少する\\n・remain stable / stay the same：変わらない\\n・reach a peak / reach the highest point：最高値に達する\\n・roughly / approximately：おおよそ〜\\n例）The number of users increased by about 30% in 2023.\\n\\n⚠ 注意：グラフの数値と本文の記述が食い違っているのが「誤りの選択肢」として使われることがある。必ず両方を照合する。\\n\\n■ 複数の文章を比較する形式\\n英語で「AとBの2つの文章を読んで答える」という形式。\\n\\n解法のポイント：\\n①両方の文章を読んでから設問を見る\\n②「AもBも述べていること」「Aだけが述べていること」「Bだけが述べていること」を整理する\\n③「どちらの意見に賛成か・その理由」という記述問題が出ることがある\\n\\n■ 日英の論理展開の違い（重要な背景知識）\\n・英語の文章：「結論・主張→理由・根拠→具体例」の順（演繹型）\\n　最初の段落に「この文章で言いたいこと」がある（topic sentenceファースト）\\n・日本語の文章：「背景→詳細→結論」の順（帰納型）\\n　最後に結論が来ることが多い\\n\\nこの違いを知っておくと、英語の長文を読むスピードが大幅に上がる。最初の段落・各段落の最初の文を特に重視して読む習慣をつけよう。\\n\\n★ 入試で問われる背景知識テーマ（頻出分野）\\n■ 環境問題：global warming / climate change / carbon dioxide / recycle\\n■ 国際理解：multicultural society / diversity / exchange student\\n■ テクノロジー：artificial intelligence / SNS / online shopping / digital divide\\n■ 健康・福祉：mental health / volunteer / elderly people / medical care\\nこれらのテーマに関する英単語を事前に覚えておくと長文が圧倒的に読みやすくなる。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_04_eibun\",\"studyPeriod\":\"小6後半・直前\",\"subject\":\"eigo\",\"title\":\"英作文・英文並び替えの攻略\",\"description\":\"配点が高い英作文を自信を持って書けるようにする\",\"keyPoints\":[\"英語の基本語順は S＋V＋O＋場所＋時間。動詞は主語のすぐ後ろに置く\",\"否定文：be動詞＋not／do(does/did)＋not＋原形／助動詞＋not＋原形\",\"疑問文：Do/Does/Did＋主語＋原形、疑問詞＋do/does/did＋主語＋原形\",\"間接疑問文は「疑問詞＋主語＋動詞」の普通の語順（I know where she lives.）\",\"並び替え頻出構文：There is/are〜、It takes 〜 to…、It is 〜 for 人 to…\",\"自由英作文は序論(I think〜)→本論(First/For example)→結論(In conclusion)の三段構成\",\"三単現のs・過去形・冠詞・文頭大文字・文末ピリオドのミスを最後に必ず点検\"],\"order\":4,\"sections\":[{\"heading\":\"1. 英文の基本語順\",\"body\":\"英語と日本語は語順が大きく異なる。英語では「誰が→何をする→何を（誰に）→どこで→いつ」という基本の語順がある。\\n\\n■ 日本語と英語の語順の違い\\n日本語：私は　昨日　図書館で　英語を　勉強した。\\n英語：I studied English at the library yesterday.\\n→ 英語では動詞（studied）が早い位置に来る。\\n\\n■ 基本語順のルール\\nS（主語）+ V（動詞）+ O（目的語）+ 場所 + 時間\\n例）I eat lunch at school every day.（私は毎日学校で昼食を食べる）\\n例）She studied math in her room last night.（彼女は昨夜自分の部屋で数学を勉強した）\\n★ ポイント：「場所」より「時間」を後ろに置くのが自然な英語。\\n\\n■ 修飾語の位置\\n・形容詞は名詞の前に置く（日本語と同じ）\\n例）a beautiful flower（美しい花）/ an interesting book（面白い本）\\n・副詞の位置（動詞の前・文の最後）\\n例）She always studies hard.（alwaysは一般動詞の前）\\n例）She is always kind.（be動詞の後ろ）\\n頻度副詞の語順：always / usually / often / sometimes / rarely / never\\n　→ 一般動詞の前、be動詞の後ろ\\n\\n■ 否定文の作り方\\n・be動詞：be動詞 ＋ not\\n例）She is not busy. / I was not tired.\\n・一般動詞：do/does/did ＋ not ＋ 原形\\n例）I do not like math. / She does not play tennis. / He did not go there.\\n・助動詞：助動詞 ＋ not ＋ 原形\\n例）I cannot swim. / She should not eat too much.\\n⚠ 注意：三単現では「does not」を使い、動詞は原形に戻る。\\n× She doesn't likes cats. → ○ She doesn't like cats.\\n\\n■ 疑問文の語順\\n・be動詞：be動詞 ＋ 主語\\n例）Is she happy? / Were they at home?\\n・一般動詞：Do/Does/Did ＋ 主語 ＋ 動詞の原形\\n例）Do you like music? / Does he play soccer? / Did she come here?\\n・疑問詞がある場合：疑問詞 ＋ do/does/did ＋ 主語 ＋ 原形\\n例）Where do you live? / What did she say?\"},{\"heading\":\"2. 並び替え問題の解き方\",\"body\":\"並び替え問題は「正しい英語の語順を知っているか」を問う問題。手順に従えば確実に解ける。\\n\\n■ 並び替えの手順\\n①まず「動詞」を探す（時制・形に注意）\\n②動詞に合う「主語」を特定する\\n③目的語・補語・修飾語を配置する\\n④全体を読んで意味が通るか確認する\\n\\n■ 疑問文の語順（要注意）\\n疑問文では語順が変わるため特に注意。\\n\\nDo/Does/Did ＋ 主語 ＋ 動詞の原形 ～?\\n例）（you / do / music / like）→ Do you like music?\\n\\n疑問詞を使う場合：疑問詞 ＋ do/does/did ＋ 主語 ＋ 原形\\n例）（does / where / she / live）→ Where does she live?\\n\\nWH疑問文でbe動詞を使う場合：疑問詞 ＋ be動詞 ＋ 主語\\n例）（is / who / that / man）→ Who is that man?\\n\\n■ 間接疑問文（疑問文が別の文に組み込まれた形）\\n間接疑問文では疑問文の語順（倒置）を使わず、「疑問詞＋主語＋動詞」の普通の語順になる。\\n\\n・直接疑問文：Where does she live?\\n・間接疑問文：I don't know where she lives.（語順が普通の文と同じ）\\n\\n例）Do you know what time it is?（今何時か知っていますか？）\\n例）I wonder why he was late.（なぜ彼が遅刻したのか不思議だ）\\n⚠ 注意：間接疑問文の中では疑問文の語順にしない。これが入試で最もよく出る落とし穴。\\n\\n■ 並び替え問題の頻出パターン\\n・There is/are 〜：「〜がある」\\n例）There are many students in the classroom.\\n・It takes 〜 to：「〜するのに…かかる」\\n例）It takes an hour to go to school by bus.\\n・It is 〜 for 人 to：「人が〜することは…だ」\\n例）It is important for us to study English.\\n★ ポイント：これらのパターンはかたまりで覚えてしまうと並び替えが楽になる。\",\"figureId\":\"xf_eigo_04_eibun\",\"mangaId\":\"eigo_04_eibun_xm\"},{\"heading\":\"3. 条件英作文（日本語から英訳）\",\"body\":\"「次の日本語を英語にしなさい」という条件英作文は指定された語数や条件の中で英文を作る問題。\\n\\n■ 日→英の変換手順\\n①日本語の意味を確認する\\n②英語の主語と動詞を決める（どの文型になるかも考える）\\n③適切な時制・語形を選ぶ（過去・現在・未来・進行形・完了形）\\n④修飾語（場所・時間）を加える\\n⑤語数をカウントし、指定に合わせる\\n\\n例）「私は先週、友達と映画を見た。」→ I watched a movie with my friend last week.\\n\\n■ 省略できる情報と省略できない情報\\n・省略できない：主語（私は）・動詞（〜した）・目的語（映画を）\\n・調整できる：修飾語（先週・友達と）は字数に合わせて省略可\\n\\n例）「できるだけ早く」→ as soon as possible（省略せず使う重要表現）\\n例）「何年もの間」→ for many years / for years\\n\\n■ よく使えるパターン表現（丸ごと覚える）\\n■ 意見を言う：I think (that)～ / In my opinion, ～\\n例）I think that English is very important.\\n\\n■ 重要性を述べる：It is important/necessary to ～\\n例）It is important to sleep enough every night.\\n\\n■ 経験を述べる：I have never ～ / I have always ～ / I've been to ～\\n例）I have never been to Hokkaido.\\n\\n■ したいことを述べる：I want to ～ / I would like to ～\\n例）I want to travel around the world in the future.\\n\\n■ 比較：A is more ～ than B / I prefer A to B\\n例）Summer is hotter than winter in Japan.\\n\\n⚠ 注意：英作文で「絶対に避けるミス」\\n・三単現のsを忘れる（She likes, He plays）\\n・過去形を間違える（go→went, see→saw）\\n・文末のピリオドを忘れる\\n・大文字で始まるのを忘れる\"},{\"heading\":\"4. 自由英作文（意見・体験を書く）\",\"body\":\"「あなたの意見を英語で書きなさい」という自由英作文は、構成（ストラクチャー）を守ることが高得点のカギ。\\n\\n■ 三段構成（基本フォーマット）\\n①序論（Introduction）：意見・立場を述べる\\n②本論（Body）：理由・具体例を書く\\n③結論（Conclusion）：意見をまとめる\\n\\n■ 序論で使える表現\\n・I think (that)～ because ～（〜だと思う、なぜなら〜だから）\\n例）I think that studying abroad is a good experience because you can learn about different cultures.\\n\\n・In my opinion, ～（私の意見では）\\n例）In my opinion, it is very important to keep the environment clean.\\n\\n■ 本論で使える表現（具体例・理由）\\n・First, / First of all,（まず）\\n例）First, I can meet many people from different countries.\\n\\n・Second, / Also, / In addition,（次に・また・加えて）\\n例）Also, I can improve my English skills by speaking with native speakers.\\n\\n・For example, / For instance,（たとえば）\\n例）For example, many students who study abroad say they become more independent.\\n\\n■ 結論で使える表現\\n・In conclusion, / To sum up,（まとめると）\\n例）In conclusion, I think studying abroad is a wonderful opportunity for students.\\n\\n・That is why I believe ～（そういうわけで私は〜と考える）\\n例）That is why I believe that everyone should try to learn a foreign language.\\n\\n■ つなぎ言葉（Linking Words）一覧\\n・追加：Also / In addition / Furthermore / Moreover（さらに）\\n・逆接：However / On the other hand / But（しかし・一方で）\\n・理由：Because / Since / As（〜だから）\\n・結果：Therefore / So / As a result（だから・その結果）\\n・例示：For example / For instance（たとえば）\\n\\n★ 60語程度の英作文の目安：\\n序論2文（15語程度）＋本論3〜4文（30語程度）＋結論2文（15語程度）＝計60語前後\"},{\"heading\":\"5. 入試例題（英作文）\",\"body\":\"以下の問題を解いて、英作文の技術を確認しよう。\\n\\n【問題1】次の語句を並び替えて、正しい英文を作りなさい。（1語不要）\\n（know / I / she / where / don't / lives / does）\\n\\n【解答】I don't know where she lives.（\\\"does\\\" が不要）\\n【解説】間接疑問文では「疑問詞＋主語＋動詞」の語順になる。\\\"where does she live\\\"（疑問文の語順）ではなく\\\"where she lives\\\"（普通の語順）にする。三単現のsをlivesに忘れずにつける。\\n\\n【問題2】次の日本語を英語にしなさい。（6語以上で答えること）\\n「私は将来、英語の先生になりたいと思っています。」\\n\\n【解答例】I want to be an English teacher in the future.（10語）\\n【別解】I hope to become an English teacher when I grow up.（11語）\\n【解説】「〜になりたい」= want to be / hope to become。「将来」= in the future / when I grow up。「英語の先生」= an English teacher（冠詞anを忘れない）。\\n\\n【問題3】次のテーマについて、60語程度の英語で自分の意見を書きなさい。\\n「スマートフォンは子どもにとって良いものか、悪いものか？」\\n\\n【解答例】\\nI think that smartphones are useful for children. First, they can learn many things by searching the internet. For example, I often use my phone to look up new words when I study English. However, we should not use smartphones too much. In conclusion, if children use them wisely, smartphones are a helpful tool.（54語）\\n【ポイント】First→For example→However→In conclusionの流れで論理的に展開している。\"},{\"heading\":\"★ MAXレベル：複雑な構文と論理的英文\",\"body\":\"■ 関係代名詞（who / which / that / whose）\\n関係代名詞は「2つの文をつなぐ接着剤」。後ろから前の名詞を修飾する。\\n\\n・who：先行詞が「人」の場合\\n例）I know a man. He speaks five languages.\\n→ I know a man who speaks five languages.（5ヶ国語を話す男性を知っている）\\n\\n・which：先行詞が「もの・動物」の場合\\n例）I read a book. It was very interesting.\\n→ I read a book which was very interesting.（とても面白い本を読んだ）\\n\\n・that：人・ものどちらにも使える（who/whichの代わり）\\n例）She is the girl that I met yesterday.\\n\\n・whose：先行詞の「所有」を表す（〜の）\\n例）I have a friend whose father is a doctor.（父が医者の友達がいる）\\n\\n■ 関係代名詞の省略\\n目的格の関係代名詞（who(m)/which/that）は省略できる。\\n例）This is the book (that) I bought yesterday.（昨日買った本）\\n例）She is the girl (who) I met at the party.（パーティで会った女の子）\\n\\n■ 分詞構文（上級文法）\\n現在分詞（-ing）または過去分詞を使って副詞節を短縮する表現。\\n・能動・進行の意味：〜しながら、〜して\\n例）Walking along the river, I found a beautiful flower.（川に沿って歩いていると〜）\\n・完了・受動の意味：〜された、〜してしまって\\n例）Having finished my homework, I played video games.（宿題を終えて〜）\\n⚠ 注意：分詞の意味上の主語は主節の主語と一致する必要がある。\\n\\n■ 比較の複合表現\\n・not as ～ as ...：...ほど〜ではない\\n例）This book is not as difficult as that one.（この本はあの本ほど難しくない）\\n・the ＋ 比較級, the ＋ 比較級：〜すればするほど〜だ\\n例）The harder you study, the better your grades will be.（一生懸命勉強すればするほど成績が上がる）\\n・比較級 ＋ and ＋ 比較級：ますます〜\\n例）It's getting hotter and hotter.（ますます暑くなっている）\\n例）More and more people use smartphones.（ますます多くの人がスマートフォンを使っている）\\n\\n★ 入試でよく問われる複雑な構文パターン\\n■ It seems that ～：〜のようだ\\n例）It seems that he is busy.（彼は忙しそうだ）\\n■ so ～ that ...:とても〜なので...だ\\n例）She was so tired that she fell asleep at once.\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_05_bunpo_oyo\",\"studyPeriod\":\"小6後半・直前\",\"subject\":\"eigo\",\"title\":\"不定詞・動名詞・関係詞・接続詞の応用\",\"description\":\"中学英語の集大成！複雑な文を作る文法を完全習得\",\"keyPoints\":[\"不定詞（to＋原形）の3用法：名詞的「〜すること」／形容詞的「〜すべき」／副詞的「〜するために」\",\"too 〜 to…「〜すぎて…できない」、〜 enough to…「…するのに十分〜だ」\",\"動名詞（-ing）「〜すること」。enjoy/finish/stop/mindは動名詞、want/hope/decideは不定詞を目的語にとる\",\"関係代名詞 who(人)/which(もの)/that/whose で名詞を後ろから修飾。目的格は省略できる\",\"接続詞＋主語＋動詞で副詞節をつくる（when/if/because/although）。時・条件の副詞節は未来でも現在形\",\"so 〜 that…「とても〜なので…」、It seems that〜「〜のようだ」などの重要構文\",\"比較の複合表現：not as 〜 as…、the＋比較級, the＋比較級、比較級 and 比較級\"],\"order\":5,\"sections\":[{\"heading\":\"1. 不定詞（to＋原形）の3用法\",\"body\":\"不定詞は中学英語の中でも最も多用される文法で、入試では毎年必ず出題される。3つの用法を確実に区別しよう。\\n\\n■ ①名詞的用法：「〜すること」\\n文の主語・目的語・補語になる。\\n例）To study English is important.（英語を勉強することは大切だ）→ 主語\\n例）I want to become a doctor.（私は医者になりたい）→ 目的語\\n例）My dream is to travel the world.（私の夢は世界を旅することだ）→ 補語\\n★ ポイント：\\\"It is ～ to ...\\\" の形もよく使われる。\\n例）It is fun to play tennis.（テニスをすることは楽しい）\\n\\n■ ②形容詞的用法：「〜するための・〜すべき」\\n前の名詞を後ろから修飾する。\\n例）I need a book to read.（読むための本が必要だ ※book を修飾）\\n例）I have a lot of things to do.（すべき事がたくさんある）\\n例）Please give me something to eat.（何か食べるものをください）\\n★ ポイント：「名詞 ＋ to ＋ 原形」のかたまりで後ろから名詞を修飾する。\\n\\n■ ③副詞的用法：「〜するために・〜して」\\n動詞・形容詞・文全体を修飾する。\\n例）I go to school to study.（勉強するために学校に行く）→ 目的\\n例）I am happy to see you.（あなたに会えて嬉しい）→ 感情の原因\\n例）He grew up to be a scientist.（彼は成長して科学者になった）→ 結果\\n\\n■ 3用法の見分け方\\n①文の主語・目的語・補語になっている → 名詞的用法\\n②前に名詞があり、その名詞を修飾している → 形容詞的用法\\n③動詞や形容詞を修飾している（目的・原因・結果）→ 副詞的用法\\n\\n■ too ～ to 構文・enough to 構文（頻出）\\n・too ～ to 原形：「〜すぎて…できない」\\n例）This box is too heavy to carry.（この箱は重すぎて運べない）\\n例）He is too young to drive a car.（彼は若すぎて車を運転できない）\\n・形容詞/副詞 ＋ enough to 原形：「〜するのに十分〜だ」\\n例）She is tall enough to reach the shelf.（彼女は棚に届くのに十分な高さだ）\\n例）I don't have enough money to buy that bag.（あのバッグを買うのに十分なお金がない）\",\"figureId\":\"xf_eigo_05_bunpo_oyo\"},{\"heading\":\"2. 動名詞（-ing形）の用法\",\"body\":\"動名詞は動詞にingをつけて名詞として使う形。不定詞（to＋原形）と混同しやすいため、使い分けを完全にマスターしよう。\\n\\n■ 動名詞の基本用法\\n・主語になる：「〜すること」\\n例）Swimming is fun.（水泳は楽しい）\\n・目的語になる：「〜すること」\\n例）I enjoy reading books.（私は本を読むことが好きだ）\\n・前置詞の後ろに来る：「〜すること」\\n例）Thank you for helping me.（手伝ってくれてありがとう）\\n例）I'm good at playing the piano.（私はピアノが得意だ）\\n\\n■ 動名詞を目的語にとる動詞（不定詞は使えない）\\n丸ごと覚える！入試最頻出。\\n・enjoy（楽しむ）：I enjoy playing video games.\\n・finish（終える）：She finished doing her homework.\\n・mind（気にする）：Do you mind opening the window?\\n・avoid（避ける）：He avoids eating junk food.\\n・give up（やめる）：Don't give up trying.\\n・stop（やめる）：She stopped talking.（talking をやめた）\\n★ 覚え方：「エンジョイ・フィニッシュ・マインド・アボイド・ギブアップ」\\n\\n■ 不定詞を目的語にとる動詞（動名詞は使えない）\\n・want（〜したい）：I want to go abroad.\\n・hope（〜を望む）：She hopes to become a singer.\\n・decide（〜を決める）：He decided to study harder.\\n・plan（〜を計画する）：We plan to visit Nara.\\n・expect（〜を期待する）：I expect to see you soon.\\n・promise（〜を約束する）：She promised to call me.\\n\\n■ 意味が変わる動詞（最重要・入試頻出）\\n同じ動詞でも、後ろに動名詞か不定詞かで意味が変わる。\\n・remember ＋ -ing：（過去に）〜したことを覚えている\\n例）I remember meeting her before.（以前彼女に会ったことを覚えている）\\n・remember ＋ to 原形：（これから）〜することを忘れずに\\n例）Remember to call me tonight.（今夜私に電話することを忘れずに）\\n\\n・forget ＋ -ing：〜したことを忘れる（過去のこと）\\n例）I'll never forget visiting Kyoto.（京都を訪れたことを決して忘れない）\\n・forget ＋ to 原形：〜することを忘れる（未来のこと）\\n例）I forgot to turn off the light.（電気を消すのを忘れた）\\n\\n・try ＋ -ing：試しに〜してみる\\n例）Try eating this cake.（このケーキを試しに食べてみて）\\n・try ＋ to 原形：〜しようとする（しようとするが難しい）\\n例）He tried to open the door.（彼はドアを開けようとした）\"},{\"heading\":\"3. 関係代名詞（who/which/that）\",\"body\":\"関係代名詞は「2つの文を1つにつなぐ」ための文法。後ろから前の名詞（先行詞）を説明する。\\n\\n■ 主格の関係代名詞（関係代名詞が節の主語になる）\\n先行詞が「人」→ who、「もの・動物」→ which、どちらも → that\\n\\n例）I have a friend. She speaks French.\\n→ I have a friend who speaks French.（フランス語を話す友達がいる）\\n\\n例）This is the book. It changed my life.\\n→ This is the book which/that changed my life.（私の人生を変えた本だ）\\n\\n■ 目的格の関係代名詞（関係代名詞が節の目的語になる）\\n先行詞が「人」→ who(m)、「もの・動物」→ which、どちらも → that\\n※目的格の関係代名詞は省略できる\\n\\n例）She is the teacher. I respect her most.\\n→ She is the teacher who(m) I respect most.\\n→ She is the teacher I respect most.（省略形）\\n\\n例）Is this the book? You were talking about it.\\n→ Is this the book which/that you were talking about?\\n\\n■ 所有格の関係代名詞 whose（〜の）\\n先行詞が人・ものどちらでも使える。\\n\\n例）I have a friend. His father is a doctor.\\n→ I have a friend whose father is a doctor.（父が医者の友達がいる）\\n\\n⚠ 注意：whose の後ろは「名詞」が来る。\\\"whose ＋ 名詞\\\"のかたまりで使う。\\n\\n■ 関係代名詞の省略\\n目的格（who(m)/which/that）は省略できる。\\n例）This is the movie (that) I watched yesterday.（昨日見た映画だ）\\n主格（who/which/that）は省略できない。\\n例）I have a dog that is very friendly.（省略不可）\\n\\n■ 非制限用法（コンマ＋which）\\nコンマの後のwhichは、前の節全体や名詞に補足説明を加える。\\n例）He passed the exam, which surprised everyone.（彼は試験に合格した、そのことはみんなを驚かせた）\\n★ ポイント：「, which」の形で前の文全体を受ける。このwhichはthatに変えられない。\"},{\"heading\":\"4. 接続詞と副詞節\",\"mangaId\":\"eigo_05_setsuzokushi_manga\",\"body\":\"接続詞は「文と文をつなぐ言葉」。副詞節を作る接続詞は意味と時制のルールが入試で問われる。\\n\\n■ 時を表す接続詞\\n・when：〜するとき\\n例）When I was young, I lived in Osaka.（幼い頃、私は大阪に住んでいた）\\n・while：〜している間\\n例）She listened to music while she was studying.（勉強している間、音楽を聴いた）\\n・before：〜する前に\\n例）Wash your hands before you eat.（食べる前に手を洗いなさい）\\n・after：〜した後に\\n例）She went to bed after she finished her homework.（宿題を終えた後に寝た）\\n・since：〜してから（ずっと）\\n例）I have lived here since I was born.（生まれてからずっとここに住んでいる）\\n・until/till：〜するまで（ずっと）\\n例）Wait here until I come back.（私が戻るまでここで待って）\\n\\n■ 条件を表す接続詞\\n・if：もし〜なら\\n例）If it rains, I will stay home.（雨が降ったら、家にいます）\\n・unless：〜でない限り（if not の意味）\\n例）I won't go unless it stops raining.（雨がやまない限り行かない）\\n\\n■ 理由を表す接続詞\\n・because：〜なので（理由を強く主張）\\n例）I was late because the train was delayed.\\n・since/as：〜なので（理由を軽く述べる）\\n例）Since it was cold, I wore a jacket.\\n\\n■ 譲歩を表す接続詞\\n・although / though / even though：〜だけれども\\n例）Although she was tired, she continued to work.（疲れていたが、働き続けた）\\n例）Even though it was raining, we played tennis.（雨が降っていたが、テニスをした）\\n⚠ 注意：although/though/even though は but と一緒に使わない。\\n× Although she was tired, but she continued.（×）\\n○ Although she was tired, she continued.（○）\\n\\n■ 時制のルール（副詞節では未来でも現在形）\\n時・条件を表す副詞節では、未来のことでも現在形を使う。\\n例）If it is sunny tomorrow, I will go swimming.（明日晴れたら、泳ぎに行く）\\n× If it will be sunny tomorrow, I will go...（×）\\n例）When she comes, please tell me.（彼女が来たら教えて）\\n× When she will come...（×）\\n⚠ 注意：これは入試で最も問われる時制の落とし穴の一つ。\"},{\"heading\":\"5. 入試例題（文法・構文）\",\"body\":\"以下の問題を解いて、不定詞・動名詞・関係詞・接続詞の理解を確認しよう。\\n\\n【問題1】（　）内から適切な語を選びなさい。\\nShe finished ( to write / writing ) her report.\\n\\n【解答】writing\\n【解説】finish は後ろに動名詞（-ing形）をとる動詞。\\\"finish to write\\\" とは言えない。同様に：enjoy / avoid / give up / mind も動名詞のみ。\\n\\n【問題2】次の文の（　）に適切な関係代名詞を入れなさい。\\nThis is the camera (　　) I bought in Osaka.\\n\\n【解答】that（または which）\\n【解説】先行詞は \\\"the camera\\\"（もの）→ which か that を使う。この関係代名詞は目的格（bought の目的語の代わり）なので省略することもできる。\\n\\n【問題3】（　）内から適切な語を選びなさい。\\nI will go to the park (　　) it stops raining.\\n\\na) after   b) until   c) because   d) although\\n\\n【解答】a) after\\n【解説】「雨がやんだ後に公園に行く」という文脈。after「〜した後に」が正しい。until は「〜するまで（ずっと）」なので\\\"I will stay home until it stops raining\\\"のような否定・継続の文に使う。\\n\\n★ 入試対策ポイント：\\n■ 動名詞のみの動詞：enjoy/finish/mind/avoid/give up\\n■ 不定詞のみの動詞：want/hope/decide/plan/expect/promise\\n■ 意味が変わる動詞：remember/forget/try（-ing vs to）\\n■ 時・条件の副詞節：未来でも現在形を使う\\n■ 関係代名詞：先行詞が人→who、もの→which、どちらも→that\"},{\"heading\":\"★ MAXレベル：仮定法・話法・複雑な関係詞\",\"body\":\"■ 仮定法（if節の応用）\\n仮定法は「現実とは違う仮定」を表す文法。現在の事実と反対のことを言うには「過去形」を使う。\\n\\n・仮定法過去：現在の反実仮想\\n形：If ＋ S ＋ 過去形（be動詞は were）, S ＋ would/could/might ＋ 原形\\n例）If I were a bird, I could fly.（もし鳥なら、飛べるのになぁ→実際は人間）\\n例）If I had more money, I would buy that car.（お金があれば買うのに）\\n\\n・I wish ＋ 仮定法：「〜だったらいいのになぁ」\\n例）I wish I could swim.（泳げたらいいのになぁ）\\n例）I wish I were taller.（もっと背が高ければいいのになぁ）\\n\\n■ 話法（直接話法 → 間接話法）\\n人が言ったことを「別の人に伝える」ときの変換ルール。\\n直接話法：\\\"I am busy,\\\" he said.（彼は「忙しい」と言った）\\n間接話法：He said (that) he was busy.（彼は忙しいと言った）\\n\\n変換のルール：\\n①that節の中の動詞は時制の一致を受ける（主節が過去→従属節も過去）\\n②人称代名詞（I→he/she、you→I/he）を変える\\n③時・場所を表す語も変わる：now→then / today→that day / here→there\\n\\n例）She said, \\\"I will come tomorrow.\\\"\\n→ She said (that) she would come the next day.\\n\\n例）He said to me, \\\"Do you live here?\\\"\\n→ He asked me if I lived there.（Yes/No疑問文 → if/whether節に）\\n\\n■ 関係副詞（where/when/why/how）\\n関係副詞は場所・時・理由・方法を表す副詞節を作る。\\n・where：場所を表す先行詞のとき\\n例）This is the house where I was born.（私が生まれた家だ）\\n・when：時を表す先行詞のとき\\n例）I remember the day when we first met.（初めて会った日を覚えている）\\n・why：reason が先行詞のとき\\n例）I don't know the reason why she was angry.（なぜ彼女が怒っていたかわからない）\\n・how：「方法」を表す（先行詞なしで使う）\\n例）This is how she learned English.（これが彼女が英語を学んだ方法だ）\\n\\n⚠ 注意：関係副詞の後ろは「完全な文（主語と動詞がそろっている文）」が来る。関係代名詞の後ろは「不完全な文（主語か目的語が欠けている文）」が来る。これが見分けのポイント。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_06_listening_speaking\",\"studyPeriod\":\"小6後半・直前\",\"subject\":\"eigo\",\"title\":\"リスニング対策と英語表現の幅を広げる\",\"description\":\"入試リスニング・会話表現・語彙強化の総まとめ\",\"keyPoints\":[\"リスニングは放送が始まる前に設問・選択肢・イラストに目を通しておく\",\"会話の決まり文句：May I help you? / How about 〜? / Why don't we 〜? / Shall I 〜?\",\"依頼 Could you 〜?、許可 May I 〜?、提案 Let's 〜／Shall we 〜? を場面で使い分ける\",\"電話・買い物・道案内など場面別の定型応答を覚える\",\"数字・時刻・曜日・値段は聞き取りで狙われるので即座に理解できるようにする\",\"頻出熟語（look forward to / be good at / take care of / get to 等）をセットで暗記\"],\"order\":6,\"sections\":[{\"heading\":\"1. リスニングの基本戦略\",\"body\":\"リスニングは「準備」が命。放送が始まる前に何をするかで得点が大きく変わる。\\n\\n■ 放送前の準備（先読み）\\n①問題用紙が配られたら、すぐに設問と選択肢を全て読む\\n②設問の種類（何を聞いているか）を確認する\\n　→「いつ」→ 時間・日付に注目する\\n　→「どこ」→ 場所名に注目する\\n　→「誰が」→ 人名・立場に注目する\\n　→「何を」→ 目的語・行動に注目する\\n③放送で流れやすいキーワードを予測してマーク\\n\\n■ 聞きながらのメモ術\\n・数字（電話番号・時間・金額・日付）は必ずメモする\\n例）\\\"The train leaves at 8:45.\\\"→「8:45」とメモ\\n・固有名詞（人名・地名・店名）もメモする\\n・会話の流れをつかむ（誰が話しているか・何について話しているか）\\n\\n★ ポイント：全ての単語を理解しようとしない。重要な情報（数字・固有名詞・動詞）に集中する。\\n\\n■ 聞き取れなかった部分の補完方法\\n・前後の文脈から推測する\\n・選択肢と照合する（「これはないはず」という消去法）\\n・会話の最後の発言に答えがあることが多い\\n\\n■ 入試リスニングで問われやすい場面\\n①電話での会話（時間・待ち合わせ場所・メッセージ）\\n②店での会話（値段・商品・数量）\\n③道案内（left/right/straight/turn/across from）\\n④学校・日常生活の会話（予定・行動・感想）\\n⑤インタビュー・放送（アナウンス・ニュース）\\n\\n■ リスニング頻出表現\\n・I beg your pardon? / Pardon?（もう一度おっしゃっていただけますか）\\n・Could you speak more slowly?（もっとゆっくり話してください）\\n・I see. / I understand.（なるほど・わかりました）\\n・Hold on, please.（少々お待ちください）\\n・Speaking.（電話で「私です」と答えるとき）\"},{\"heading\":\"2. 会話表現・決まり文句\",\"body\":\"入試の会話問題では「決まり文句」を知っているかどうかで差がつく。場面ごとにパターンを覚えよう。\\n\\n■ 申し出（Offer）の表現\\n・Shall I help you?（手伝いましょうか？）\\n・Shall I carry your bag?（バッグを持ちましょうか？）\\n・Would you like me to open the window?（窓を開けましょうか？）\\n→ 返答：Yes, please.（はい、お願いします）/ No, thank you. I'm fine.（結構です）\\n\\n■ 依頼（Request）の表現\\n・Could you help me?（手伝ってもらえますか？）\\n・Would you open the door, please?（ドアを開けていただけますか？）\\n・Would you mind closing the window?（窓を閉めてもらえますか？）\\n→ Would you mind -ing? の返答に注意：\\n　 肯定（いいよ）→ Of course not. / Not at all. / Certainly.（否定で答える！）\\n　 断る → I'm sorry, but I'm busy now.\\n⚠ 注意：Would you mind -ing? は「〜してもらえますか？」という依頼。Notで答えると「はい（いいよ）」になる。入試でここを間違える人が多い。\\n\\n■ 提案（Suggestion）の表現\\n・Why don't we go to the library?（図書館に行きませんか？）\\n・How about eating out tonight?（今夜外食しませんか？）\\n・Let's play tennis after school.（放課後テニスをしよう）\\n→ 返答：Sounds good. / That's a great idea.（いいですね）\\n\\n■ 断り方（Refusing）の表現\\n・I'm sorry, but I can't.（すみませんが、できません）\\n・I'd love to, but I have a piano lesson.（行きたいけれど、ピアノのレッスンがあります）\\n・Maybe next time.（また今度）\\n\\n■ 感謝と返答\\n・Thank you (very much) / Thanks a lot. → You're welcome. / Not at all. / My pleasure.\\n■ 謝罪と返答\\n・I'm sorry. / I apologize. → That's okay. / Don't worry about it. / No problem.\\n■ 場所を聞く・教える\\n・Excuse me. Could you tell me the way to the station?（駅への道を教えてもらえますか）\\n・Go straight and turn left at the first corner.（まっすぐ行って最初の角を左に曲がる）\\n・It's on your right.（右手にあります）\",\"figureId\":\"xf_eigo_06_listening_speaking\",\"mangaId\":\"eigo_06_listening_speaking_xm\"},{\"heading\":\"3. 頻出英語表現のパターン\",\"body\":\"会話や作文で使える「パターン表現」は丸ごと覚えると即使える。入試頻出のものを厳選した。\\n\\n■ 時間・期間を表す表現\\n・It takes ＋ 時間 ＋ to 〜：〜するのに…かかる\\n例）It takes about an hour to get to the airport.（空港まで約1時間かかる）\\n例）It took me two hours to finish the test.（テストを終えるのに2時間かかった）\\n\\n■ 人にとっての難しさ・重要さを表す表現\\n・It is ＋ 形容詞 ＋ for 人 ＋ to 〜：人が〜することは…だ\\n例）It is important for us to protect the environment.（環境を守ることは私たちにとって重要だ）\\n例）It is difficult for me to speak English fluently.（流暢に英語を話すことは私には難しい）\\n例）It is easy for children to use smartphones.（子どもがスマートフォンを使うことは簡単だ）\\n\\n■ 経験・状態を表す現在完了形の表現\\n・have been to 〜：〜へ行ったことがある\\n例）I have been to Australia twice.（私はオーストラリアに2回行ったことがある）\\n⚠ 注意：have gone to〜は「行ってしまった（今はここにいない）」という意味。\\n例）She has gone to France.（彼女はフランスに行ってしまった→今はここにいない）\\n\\n■ 楽しみにする・興味を持つ表現\\n・look forward to -ing：〜を楽しみにしている（to のあとは動名詞）\\n例）I'm looking forward to seeing you again.（またあなたに会うのを楽しみにしている）\\n例）She is looking forward to the summer vacation.（夏休みを楽しみにしている）\\n⚠ 注意：to の後ろが動詞なら-ing形（動名詞）にする！「to ＋ 原形」（不定詞）ではない。\\n\\n■ その他の重要パターン\\n・be used to -ing：〜することに慣れている\\n例）I'm used to getting up early.（早起きに慣れている）\\n・be afraid of -ing：〜することを恐れる\\n例）She is afraid of speaking in public.（人前で話すことが怖い）\\n・spend ＋ 時間 ＋ -ing：〜するのに時間を使う\\n例）He spent two hours doing his homework.（宿題に2時間使った）\\n・have difficulty -ing：〜することが難しい・苦手だ\\n例）I have difficulty understanding English jokes.（英語のジョークを理解するのが難しい）\"},{\"heading\":\"4. 入試頻出単語・熟語500\",\"body\":\"入試に頻出するカテゴリ別の重要語彙と熟語をまとめた。毎日少しずつ覚えよう。\\n\\n■ 自然・環境（Nature & Environment）\\nenvironment（環境）/ nature（自然）/ climate（気候）/ weather（天気）\\nforest（森）/ ocean（海）/ river（川）/ mountain（山）/ island（島）\\npollution（汚染）/ recycle（リサイクルする）/ energy（エネルギー）\\nprotect（守る）/ destroy（破壊する）/ global warming（地球温暖化）\\n\\n■ 社会・生活（Society & Daily Life）\\nculture（文化）/ tradition（伝統）/ community（地域社会）/ society（社会）\\nvolunteer（ボランティア）/ hospital（病院）/ school（学校）/ factory（工場）\\ntechnology（技術）/ transportation（交通）/ communication（コミュニケーション）\\npopulation（人口）/ education（教育）/ government（政府）\\n\\n■ 感情・性格（Emotions & Character）\\nhappy / sad / angry / surprised / excited / tired / bored / nervous\\nkind（親切な）/ honest（正直な）/ brave（勇敢な）/ patient（忍耐強い）\\ncurious（好奇心のある）/ creative（創造的な）/ confident（自信のある）\\n\\n■ 動作（Actions & Verbs）\\nimprove（上達する）/ achieve（達成する）/ succeed（成功する）/ fail（失敗する）\\nrealize（気づく）/ understand（理解する）/ communicate（伝える）\\ndevelop（発達する）/ contribute（貢献する）/ influence（影響を与える）\\nsolve（解決する）/ discover（発見する）/ create（作る）/ support（支援する）\\n\\n■ よく出る熟語（Phrasal Verbs & Idioms）\\n・be good at 〜：〜が得意だ\\n例）She is good at playing the guitar.\\n・be interested in 〜：〜に興味がある\\n例）He is interested in history.\\n・take care of 〜：〜の世話をする\\n例）She takes care of her grandmother.\\n・look up 〜：〜を調べる\\n例）Look up the word in the dictionary.\\n・give up：〜をあきらめる\\n例）Don't give up your dream.\\n・put on：〜を着る / take off：〜を脱ぐ\\n・find out：〜を見つける・明らかにする\\n・turn on：〜をつける / turn off：〜を消す\\n・come true：（夢が）実現する\\n例）My dream came true.\\n・in fact：実は・実際に\\n・at first：最初は\\n・all of a sudden：突然\\n・as soon as possible：できるだけ早く\"},{\"heading\":\"5. 入試例題（リスニング型・会話文）\",\"body\":\"以下の問題は「会話文の空所補充」と「場面別応答選択」のリスニング型演習。声に出して読んで練習しよう。\\n\\n【会話文の空所補充：問題1〜3】\\n\\n【問題1】次の会話の（　　）に入る最も適切な文を選びなさい。\\nA: Excuse me. Could you tell me the way to the library?\\nB: (　　)\\nA: Thank you very much.\\n\\na) Yes, I'm sorry.\\nb) Sure. Go straight and turn left at the second corner.\\nc) I don't have a library card.\\nd) The library is my favorite place.\\n\\n【解答】b)\\n【解説】道を尋ねられたときの返答。Go straight / turn left などの道案内の表現が正しい答え。\\n\\n【問題2】次の会話の（　　）に入る最も適切な文を選びなさい。\\nA: Would you mind helping me with this bag?\\nB: (　　)\\n\\na) Yes, I do.\\nb) Not at all. Let me help you.\\nc) I don't mind asking you.\\nd) Yes, please.\\n\\n【解答】b)\\n【解説】Would you mind -ing? は「〜してもらえますか？」という依頼。承諾するときは \\\"Not at all.\\\" または \\\"Of course not.\\\" で答える。\\\"Yes\\\"は「はい、気にします（断る）」の意味になるので注意。\\n\\n【問題3】次の会話の（　　）に入る最も適切な文を選びなさい。\\nA: I'm sorry I'm late. I missed the bus.\\nB: (　　)\\nA: Thank you. I'll be more careful next time.\\n\\na) That's a good idea!\\nb) Don't worry about it. It happens.\\nc) I'm sorry to hear that.\\nd) How long did it take?\\n\\n【解答】b)\\n【解説】謝罪に対する返答。\\\"Don't worry about it.\\\" / \\\"That's okay.\\\" / \\\"No problem.\\\" が自然な応答。Aが「次は気をつけます」と言っているので、受け入れてもらったことがわかる。\\n\\n★ まとめ：よく問われる会話パターン\\n■ 道案内：Go straight / turn right/left / on your right/left / across from\\n■ 依頼への応答：Of course. / Certainly. / I'm sorry, but I can't.\\n■ 提案への応答：Sounds good. / That's a great idea. / I'd love to, but...\\n■ 謝罪への応答：That's okay. / No problem. / Don't worry.\"},{\"heading\":\"★ MAXレベル：語彙の深掘りと文化的背景\",\"body\":\"■ 同義語・類義語の細かい違い\\n入試では「同じような意味でもニュアンスが違う語の選択」が問われる。\\n\\n・big / large / huge / enormous（大きい）\\n　big：日常的・口語的（a big problem / a big house）\\n　large：少しフォーマル・量・規模（a large country / a large amount）\\n　huge：非常に大きい（a huge building / a huge success）\\n　enormous：圧倒的に大きい・量が非常に多い（enormous pressure / enormous wealth）\\n\\n・smart / clever / intelligent / wise（賢い）\\n　smart：頭の回転が速い・スタイリッシュ（a smart student）\\n　clever：巧みな・機転が利く（a clever trick）\\n　intelligent：知能が高い・論理的（an intelligent person）\\n　wise：経験から来る賢さ・判断力がある（a wise decision）\\n\\n・say / tell / speak / talk（話す）\\n　say：〜と言う（内容を直接引用・報告：She said \\\"Hello.\\\"）\\n　tell：（人に）〜を告げる（tell ＋ 人：Tell me your name.）\\n　speak：（言語や聴衆に向けて）話す（speak English / speak to the class）\\n　talk：会話する・雑談する（talk with friends / talk about the trip）\\n\\n■ 語源から覚える語彙（etymology）\\n語源を知ると、初見の単語でも意味が推測できる。\\n\\n・rupt ＝「壊れる・破裂する」\\n　interrupt（邪魔する＝inter（間に）＋ rupt）\\n　disrupt（混乱させる＝dis（分離）＋ rupt）\\n　erupt（噴火する＝e（外へ）＋ rupt）\\n　bankrupt（倒産した＝bank ＋ rupt）\\n\\n・port ＝「運ぶ」\\n　transport（輸送する）/ import（輸入する）/ export（輸出する）/ report（報告する）\\n　portable（持ち運べる）/ support（支える）\\n\\n・dict ＝「言う」\\n　dictionary（辞書）/ predict（予測する）/ contradict（矛盾する）\\n　indicate（示す）/ dedicate（捧げる）\\n\\n■ 英語圏の文化・習慣（入試背景知識問題）\\n入試では英語圏の文化的慣習を問う長文が出る。知識として押さえておこう。\\n\\n・Thanksgiving（感謝祭）：11月の第4木曜日、アメリカの伝統的な祝日。七面鳥を食べる。\\n・Halloween（ハロウィン）：10月31日。子どもが仮装して \\\"Trick or treat!\\\" と言ってお菓子をもらう。\\n・Christmas（クリスマス）：12月25日。プレゼントを交換する習慣。サンタクロース（Santa Claus）。\\n・チップ（Tipping）：アメリカではレストランでの飲食後に15〜20%のチップを払う習慣がある。\\n・呼びかけ方（Addressing）：英語圏では先生をファーストネームで呼ぶ文化がある（\\\"Mr./Ms. ＋ 苗字\\\"の場合も）。日本の「先生」に直接相当する英語はない。\\n・Small talk（世間話）：英語圏では初対面での挨拶に天気の話題がよく使われる（\\\"Lovely weather today!\\\"）。\\n\\n⚠ 注意：これらの文化背景は「英文を読む文脈」として機能する。内容一致問題や空所補充の解釈に役立つ。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_07_alphabet_phonics\",\"studyPeriod\":\"小4\",\"subject\":\"eigo\",\"title\":\"アルファベット・フォニックス・ローマ字\",\"description\":\"英語のいちばん最初！文字・音・ローマ字の基礎を固める\",\"keyPoints\":[\"アルファベット大文字26・小文字26を正しく書く。b/d・p/q の向き、n/h の高さに注意\",\"フォニックス：aは/æ/(apple)などの基本音。母音字＋子音字＋e で母音がアルファベット読みになる（cake, bike, home）\",\"ローマ字ヘボン式：し＝shi、ち＝chi、つ＝tsu、ふ＝fu、じ＝ji（パスポート・駅名はヘボン式）\",\"訓令式（si/ti/tu）とヘボン式（shi/chi/tsu）の違いを区別する\",\"文頭・固有名詞・I（私は）は必ず大文字で書く\",\"母音字は a, i, u, e, o の5つ。それ以外は子音字\"],\"order\":7,\"sections\":[{\"heading\":\"1. アルファベットの大文字と小文字\",\"body\":\"英語はアルファベット26文字ですべての単語を作る。まずは大文字（Capital letter）と小文字（Small letter）をセットで覚えよう。\\n\\n■ アルファベット26文字（大文字→小文字）\\nA a ／ B b ／ C c ／ D d ／ E e ／ F f ／ G g\\nH h ／ I i ／ J j ／ K k ／ L l ／ M m ／ N n\\nO o ／ P p ／ Q q ／ R r ／ S s ／ T t ／ U u\\nV v ／ W w ／ X x ／ Y y ／ Z z\\n\\n■ 母音（vowel）と子音（consonant）\\n・母音は5つ：a・i・u・e・o\\n・それ以外の21文字はすべて子音\\n★ ポイント：この「母音」を知っていると、a と an の使い分け（母音の前は an）などのルールがわかる。\\n\\n■ 大文字を使う場所（入試でも問われる基本ルール）\\n①文のいちばん最初の文字\\n　例）This is a pen.（Tを大文字に）\\n②人の名前・地名・国名（固有名詞）の最初の文字\\n　例）Tom ／ Japan ／ Osaka ／ Mt. Fuji\\n③I（私は）はいつでも大文字\\n　例）Yes, I am. ／ Tom and I are friends.\\n④曜日・月の名前の最初の文字\\n　例）Monday ／ April ／ Sunday\\n⑤言語・国民を表す語\\n　例）English ／ Japanese\\n\\n⚠ 注意：文の途中でも I はいつも大文字。i と小文字で書くのは間違い。\\n\\n■ まちがえやすい形の文字\\n・b と d（左右が逆）\\n・p と q（上下・左右が逆）\\n・小文字の a と o、n と h の高さのちがい\\n★ 4本線のノートを使うとき、b・d・h・k・l・t は上の段まで、g・j・p・q・y は下の段まで伸ばす、と覚えると形がそろう。\"},{\"heading\":\"2. フォニックス（文字と音のルール）\",\"body\":\"フォニックス（Phonics）とは「文字と音の関係のルール」のこと。これを知ると、はじめて見る単語もローマ字読みではなく英語の音で読めるようになる。\\n\\n■ 子音の基本の音（アルファベット読みとちがう「音」）\\nb →「ブ」 ／ c →「ク」 ／ d →「ドゥ」 ／ f →「フ」\\ng →「グ」 ／ h →「ハ」 ／ j →「ヂュ」 ／ k →「ク」\\nl →「ル」 ／ m →「ム」 ／ n →「ンヌ」 ／ p →「プ」\\nr →「ゥル」 ／ s →「ス」 ／ t →「トゥ」 ／ v →「ヴ」\\nw →「ゥ」 ／ y →「ィ」 ／ z →「ズ」\\n★ ポイント：名前の読み方（ビー・シー…）と、単語の中での音（ブ・ク…）はちがう。フォニックスでは「音」のほうを使う。\\n\\n■ 母音の短い音（短母音）\\na →「ア」（cat キャット）\\ni →「イ」（sit スィット）\\nu →「ア」（cup カップ）\\ne →「エ」（pen ペン）\\no →「オ」（box ボックス）\\n\\n■ 3文字の単語を音でつなげて読む練習\\nc-a-t → ク・ア・トゥ → cat（ねこ）\\nd-o-g → ドゥ・オ・グ → dog（いぬ）\\nb-i-g → ブ・イ・グ → big（大きい）\\nr-u-n → ゥル・ア・ンヌ → run（走る）\\n★ ポイント：1文字ずつの音をなめらかにつなげると単語の発音になる。\\n\\n■ 単語の最後に e がつくと母音が「名前読み」になる（マジックe）\\n・cap（キャップ・ぼうし）→ cape（ケイプ・岬）　a が「エイ」に\\n・kit（キット）→ kite（カイト・たこ）　i が「アイ」に\\n・not（ノット）→ note（ノウト・メモ）　o が「オウ」に\\n・cut（カット）→ cute（キュート・かわいい）　u が「ユー」に\\n⚠ 注意：最後の e 自体は読まない（発音しない）。前の母音を「アルファベットの名前の音」に変える役目。\\n\\n■ 2文字で1つの音になるもの（重要）\\nsh →「シュ」（ship 船）／ ch →「チ」（chair いす）\\nth →「ス／ズ」（think 考える ／ this これ）\\nph →「フ」（phone 電話）／ ck →「ク」（duck あひる）\\n★ フォニックスを知っていると、つづり（スペル）を覚えるのもぐんと楽になる。\",\"figureId\":\"xf_eigo_07_alphabet_phonics\",\"mangaId\":\"eigo_07_alphabet_phonics_xm\"},{\"heading\":\"3. ローマ字（訓令式とヘボン式）\",\"body\":\"ローマ字は「日本語をアルファベットで書く」ためのもの。英語そのものではないが、名前や地名を書くときに必要で、小学校でも学ぶ。\\n\\n■ ローマ字の基本（母音＋子音の組み合わせ）\\n・母音：a（あ）・i（い）・u（う）・e（え）・o（お）\\n・子音＋母音で1音：ka き→ki く→ku け→ke こ→ko\\n例）さくら → sakura ／ ねこ → neko ／ とけい → tokei\\n\\n■ 五十音のローマ字（訓令式）\\nか行 ka ki ku ke ko ／ さ行 sa si su se so\\nた行 ta ti tu te to ／ な行 na ni nu ne no\\nは行 ha hi hu he ho ／ ま行 ma mi mu me mo\\nや行 ya (i) yu (e) yo ／ ら行 ra ri ru re ro\\nわ行 wa (o) ／ ん n\\n\\n■ 訓令式とヘボン式のちがい（重要）\\n学校のテストは「訓令式」が基本だが、パスポートや駅名などの実生活では「ヘボン式」が使われる。ちがう部分だけ覚えよう。\\n　音／訓令式／ヘボン式\\n　し … 訓令式はsi／ヘボン式はshi\\n　ち … 訓令式はti／ヘボン式はchi\\n　つ … 訓令式はtu／ヘボン式はtsu\\n　ふ … 訓令式はhu／ヘボン式はfu\\n　じ … 訓令式はzi／ヘボン式はji\\n　しゃ … 訓令式はsya／ヘボン式はsha\\n　ちゃ … 訓令式はtya／ヘボン式はcha\\n例）ふじさん → 訓令式 huzisan ／ ヘボン式 Fujisan\\n\\n■ のばす音・つまる音・「ん」の書き方\\n・のばす音（長音）：訓令式は母音の上に「＾」（ô）、ヘボン式は「ō」のように上に横棒をつけるか、のばさず書く\\n　例）おおさか → Osaka ／ とうきょう → Tokyo（ヘボン式では長音記号を省くことが多い）\\n・つまる音（促音「っ」）：次の子音を重ねる\\n　例）きっぷ → kippu ／ がっこう → gakkou（gakkô）\\n・はねる音「ん」：n で書く。ただし b・p・m の前は m にすることがある（ヘボン式）\\n　例）しんぶん → shinbun ／ ぐんま → Gunma（Gumma）\\n\\n⚠ 注意：人名・地名は最初の文字を大文字にする。\\n例）Tanaka Taro ／ Nihon（Japan）／ Kyoto\"},{\"heading\":\"4. 単語を正しく書くための基本ルール\",\"body\":\"英語を書くときには、日本語にはない「書き方のきまり」がいくつもある。ここでミスをなくそう。\\n\\n■ 単語と単語の間はスペースを空ける\\n英語は単語ごとに区切って書く。くっつけて書いてはいけない。\\n○ I am a student.\\n× Iamastudent.\\n\\n■ 文の終わりには符号（ピリオド・クエスチョンマーク）をつける\\n・ふつうの文（肯定文・否定文）→ ピリオド「.」\\n　例）I like dogs.\\n・質問の文（疑問文）→ クエスチョンマーク「?」\\n　例）Do you like dogs?\\n・強い気持ちの文（感嘆文など）→ エクスクラメーションマーク「!」\\n　例）What a nice day!\\n\\n■ コンマ（,）の使い方\\n・ものを並べるとき（3つ以上）\\n　例）I have a pen, a book, and a ruler.\\n・呼びかけや返事のあと\\n　例）Yes, I do. ／ Hi, Tom.\\n\\n■ 短縮形（アポストロフィ ' を使う）\\n話し言葉やくだけた文でよく使う。\\n・I am → I'm ／ You are → You're ／ He is → He's\\n・is not → isn't ／ are not → aren't ／ do not → don't\\n・does not → doesn't ／ cannot → can't ／ will not → won't\\n例）I'm a student. ／ She isn't busy. ／ I don't know.\\n★ ポイント：短縮形の「'」は省いた文字の場所に置く（is not → isn'tのo が消える）。\\n\\n■ 名前や 's（アポストロフィ エス）で「〜の」を表す\\n・人やものの持ち主を表すとき、名前のあとに 's をつける\\n　例）Tom's book（トムの本）／ my mother's car（母の車）\\n　例）the dog's name（その犬の名前）\\n\\n⚠ よくあるミスまとめ\\n・文の最初を小文字で書く → ×（大文字にする）\\n・I を i と書く → ×\\n・ピリオドやクエスチョンマークを忘れる → 減点されやすい\\n・単語をくっつけて書く → ×\"},{\"heading\":\"5. 練習問題（文字・音・ローマ字）\",\"body\":\"これまで学んだことを問題で確認しよう。\\n\\n【問題1】次の単語の最初の文字は、a と an のどちらがつくか答えなさい。\\n① (   ) apple　② (   ) book　③ (   ) orange　④ (   ) cat\\n\\n【解答】① an　② a　③ an　④ a\\n【解説】母音（a・i・u・e・o）で始まる語には an、子音で始まる語には a をつける。apple・orange は母音で始まるので an。\\n\\n【問題2】次のローマ字（ヘボン式）を日本語（ひらがな）に直しなさい。\\n① Fujisan　② Tokyo　③ shashin\\n\\n【解答】① ふじさん　② とうきょう　③ しゃしん\\n【解説】ヘボン式では し＝shi、ふ＝fu、しゃ＝sha。読みにくいときは子音＋母音に区切って考える（sha-shin）。\\n\\n【問題3】次の文をただしく書き直しなさい。（大文字・スペース・符号に注意）\\niamtom\\n\\n【解答】I am Tom.\\n【解説】①文の最初 I は大文字　②単語の間はスペース　③人の名前 Tom は大文字　④文の終わりにピリオド。\\n\\n【問題4】次の語を短縮形に直しなさい。\\n① I am　② is not　③ do not\\n\\n【解答】① I'm　② isn't　③ don't\\n【解説】アポストロフィ「'」は消した文字の場所に入れる。\\n\\n★ まとめ\\n■ 大文字を使う場所：文頭・名前・地名・曜日/月・I\\n■ フォニックス：文字は「名前」と「音」の2つの読み方がある\\n■ ローマ字：学校は訓令式、実生活はヘボン式（shi/chi/tsu/fu…）\\n■ 書き方：単語の間はスペース、文末に符号、I はいつも大文字\"},{\"heading\":\"★ MAXレベル：発音記号と特殊なつづり\",\"body\":\"■ 発音記号（辞書に書いてある記号）\\n辞書で単語を引くと [ ] の中に発音記号が書いてある。読めると正しい発音がわかる。\\n・[i:] 長い「イー」：see [si:] ／ eat [i:t]\\n・[i] 短い「イ」：sit [sit] ／ big [big]\\n・[æ] 口を大きく開けた「ア」：cat [kæt] ／ apple [æpl]\\n・[ə] あいまいな「ア」（シュワー）：about [əbáut] ／ banana [bənǽnə]\\n・[θ] 舌を歯で軽くはさむ「ス」：think ／ [ð] 濁った「ズ」：this\\n★ ポイント：[ˈ] や [´] はアクセント（強く読む場所）を表す。英語はアクセントの位置がとても大切。\\n\\n■ サイレントレター（読まないつづり）\\n英語には「書くのに読まない文字」がある。丸ごと覚える。\\n・k を読まない：know（ノウ）／ knife（ナイフ）／ knee（ニー）\\n・b を読まない：comb（コウム・くし）／ climb（クライム・登る）\\n・w を読まない：write（ライト・書く）／ wrong（ロング・まちがい）\\n・h を読まない：hour（アワー・時間）／ honest（オネスト・正直な）\\n・gh を読まない：night（ナイト）／ light（ライト）／ high（ハイ）\\n\\n■ 同じつづりでも読み方が変わる例\\n・ea →「イー」（eat, sea, tea）だが「エ」（bread パン, head 頭）のこともある\\n・ou →「アウ」（house, out）だが「ウー」（you, group）のことも\\n・oo →「ウー」（moon, food）だが短い「ウ」（book, good）のことも\\n⚠ 注意：英語のつづりと発音は例外が多い。フォニックスは「基本の読み方」であって、100%ではない。よく出る例外は個別に覚える。\\n\\n■ アクセントの位置で意味・品詞が変わる語（上級）\\n同じつづりでも、強く読む場所で品詞が変わる単語がある。\\n・présent（名詞・形容詞「贈り物・現在の」）／ presént（動詞「贈る・発表する」）\\n・récord（名詞「記録」）／ recórd（動詞「記録する」）\\n・óbject（名詞「物・目的」）／ objéct（動詞「反対する」）\\n★ 高校英語や難関中学の発音問題で問われる。「名詞は前、動詞は後ろにアクセント」というパターンが多い。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_08_be_ippan_doushi\",\"studyPeriod\":\"小5前半\",\"subject\":\"eigo\",\"title\":\"be動詞と一般動詞の基礎\",\"description\":\"英文づくりの土台！2種類の動詞と肯定・否定・疑問を完全マスター\",\"keyPoints\":[\"be動詞は am(I)／is(3人称単数)／are(you・複数)。「〜です・〜にいる（ある）」を表す\",\"一般動詞は動作「〜する」。三人称単数現在は-s/-esをつける（plays, watches, has, goes）\",\"否定文：be動詞＋not／don't(doesn't)＋動詞の原形\",\"疑問文：Is/Are＋主語〜?／Do(Does)＋主語＋動詞の原形〜?\",\"1つの文にbe動詞と一般動詞を両方は入れない（× I am play soccer.）\",\"答え方：Yes, I am.／No, I'm not.／Yes, I do.／No, I don't.\"],\"order\":8,\"sections\":[{\"heading\":\"1. be動詞（am / is / are）の使い方\",\"body\":\"英語の動詞には大きく2種類ある。「be動詞」と「一般動詞」だ。まずは be動詞から学ぼう。\\n\\n■ be動詞とは\\nbe動詞は「〜です・〜にいる／ある」という意味を表す動詞。主語（〜は）によって形が変わる。\\n\\n■ be動詞の使い分け（現在形）\\n　主語／be動詞／例文\\n　I（私は） … be動詞はam／例文はI am a student.（私は生徒です）\\n　you（あなたは） … be動詞はare／例文はYou are kind.（あなたは親切です）\\n　he / she / it（彼・彼女・それは） … be動詞はis／例文はHe is my friend.（彼は私の友達です）\\n　we / you / they（私たち・あなたたち・彼らは） … be動詞はare／例文はThey are teachers.（彼らは先生です）\\n\\n★ 覚え方：「I は am」「he/she/it は is」「you と複数は are」。\\n\\n■ be動詞の2つの意味\\n①「〜です・〜だ」（主語＝あとの語）\\n　例）I am Tom.（私はトムです）→ I ＝ Tom\\n　例）This is a book.（これは本です）→ This ＝ a book\\n②「〜にいる・〜にある」（場所を表す）\\n　例）I am in the classroom.（私は教室にいます）\\n　例）Your bag is on the desk.（あなたのかばんは机の上にあります）\\n\\n■ 短縮形（話し言葉でよく使う）\\nI am → I'm ／ You are → You're ／ He is → He's\\nShe is → She's ／ It is → It's ／ We are → We're ／ They are → They're\\n例）I'm from Osaka.（私は大阪出身です）\\n\\n⚠ 注意：be動詞の文には一般動詞（play・like など）を入れない。\\n× I am play tennis.（×）\\n○ I play tennis.（一般動詞の文）\\n○ I am a tennis player.（be動詞の文）\"},{\"heading\":\"2. 一般動詞の使い方と三人称単数のs\",\"mangaId\":\"eigo_08_sanninshou_manga\",\"body\":\"一般動詞は「動作や状態」を表す動詞。be動詞（am/is/are）以外の動詞はすべて一般動詞だ。\\n\\n■ 一般動詞の例\\nplay（〜をする）／ like（〜が好き）／ have（持っている）／ go（行く）\\nstudy（勉強する）／ run（走る）／ eat（食べる）／ read（読む）／ live（住む）\\n\\n■ 一般動詞の肯定文（ふつうの文）\\n主語 ＋ 一般動詞 ＋ 〜\\n例）I play soccer.（私はサッカーをする）\\n例）You like music.（あなたは音楽が好きだ）\\n例）We study English.（私たちは英語を勉強する）\\n\\n■ 三人称単数のs（重要ルール）\\n主語が he / she / it や1人の人・1つのもの（三人称単数）のとき、一般動詞の最後に s または es をつける。\\n例）I play tennis. → He plays tennis.\\n例）They like dogs. → She likes dogs.\\n\\n■ 三人称単数とは\\n・一人称：I（私）／ we（私たち）\\n・二人称：you（あなた・あなたたち）\\n・三人称：それ以外すべて（he, she, it, Tom, my mother, the cat, this book など）\\n★ ポイント：「私」でも「あなた」でもない、1人・1つの何かが三人称単数。\\n\\n■ s / es のつけ方\\n・ふつうは s：play → plays ／ like → likes ／ run → runs\\n・s, o, x, ch, sh で終わる語は es：go → goes ／ watch → watches ／ wash → washes\\n・「子音＋y」で終わる語は y を i に変えて es：study → studies ／ cry → cries\\n・特別な形：have → has\\n\\n例）My father goes to work by train.（父は電車で仕事に行く）\\n例）She studies math every day.（彼女は毎日数学を勉強する）\\n例）Tom has a dog.（トムは犬を飼っている）\\n\\n⚠ 注意：主語が複数（they, we, my parents など）のときは s をつけない。\\n× They likes soccer.（×）\\n○ They like soccer.（○）\",\"figureId\":\"xf_eigo_08_be_ippan_doushi\"},{\"heading\":\"3. 否定文の作り方（〜でない・〜しない）\",\"mangaId\":\"eigo_08_hitei_manga\",\"body\":\"「〜ではない」「〜しない」という否定文の作り方は、be動詞と一般動詞でまったく違う。ここを区別するのが最重要。\\n\\n■ be動詞の否定文：be動詞のあとに not を置く\\n形：主語 ＋ am / is / are ＋ not ＋ 〜\\n例）I am not a teacher.（私は先生ではありません）\\n例）She is not busy.（彼女は忙しくありません）\\n例）They are not students.（彼らは生徒ではありません）\\n★ 短縮形：is not → isn't ／ are not → aren't（am not に短縮形はない）\\n例）He isn't at home. ／ We aren't ready.\\n\\n■ 一般動詞の否定文：動詞の前に do not / does not を置く\\n形：主語 ＋ do not（does not）＋ 動詞の原形 ＋ 〜\\n・主語が I / you / we / they → do not（don't）\\n・主語が he / she / it（三人称単数）→ does not（doesn't）\\n例）I do not like natto.（私は納豆が好きではない）\\n例）She does not play the piano.（彼女はピアノを弾かない）\\n\\n■ 最重要ポイント：does not のあとの動詞は原形に戻す\\n三人称単数でも、does not を使うときは動詞の s を取って原形にする。\\n× She does not likes tennis.（×）\\n○ She does not like tennis.（○ likes → like）\\n★ 理由：s の意味は does がすでに引き受けているので、動詞は原形でよい。\\n\\n■ 短縮形\\ndo not → don't ／ does not → doesn't\\n例）I don't have a smartphone.（私はスマホを持っていない）\\n例）My brother doesn't eat vegetables.（弟は野菜を食べない）\\n\\n⚠ まちがえやすいポイント\\n・be動詞の文なのに do を使う → ×\\n　× I don't be busy. → ○ I'm not busy.\\n・一般動詞の文なのに not だけ → ×\\n　× I not like it. → ○ I don't like it.\"},{\"heading\":\"4. 疑問文の作り方と答え方\",\"body\":\"「〜ですか？」「〜しますか？」とたずねる疑問文も、be動詞と一般動詞で作り方が違う。\\n\\n■ be動詞の疑問文：be動詞を文の先頭に出す\\n形：Am / Is / Are ＋ 主語 ＋ 〜 ?\\n例）You are a student. → Are you a student?（あなたは生徒ですか）\\n例）He is your brother. → Is he your brother?（彼はあなたの兄ですか）\\n\\n答え方（Yes / No で答える）\\n・Yes, 主語 ＋ be動詞. ／ No, 主語 ＋ be動詞 ＋ not.\\n例）Are you a student? → Yes, I am. ／ No, I am not.（No, I'm not.）\\n例）Is he busy? → Yes, he is. ／ No, he isn't.\\n★ ポイント：答えの主語は代名詞にする（Tom → he、your mother → she）。\\n\\n■ 一般動詞の疑問文：Do / Does を文の先頭に置く\\n形：Do（Does）＋ 主語 ＋ 動詞の原形 ＋ 〜 ?\\n・主語が I / you / we / they → Do\\n・主語が he / she / it（三人称単数）→ Does\\n例）You play tennis. → Do you play tennis?（テニスをしますか）\\n例）She likes music. → Does she like music?（音楽が好きですか）\\n\\n■ 最重要ポイント：Does の疑問文でも動詞は原形\\n× Does she likes music?（×）\\n○ Does she like music?（○ likes → like）\\n★ 否定文の does not と同じで、s は does が引き受ける。\\n\\n答え方\\n・Yes, 主語 ＋ do / does. ／ No, 主語 ＋ don't / doesn't.\\n例）Do you like dogs? → Yes, I do. ／ No, I don't.\\n例）Does he play soccer? → Yes, he does. ／ No, he doesn't.\\n\\n⚠ まちがえやすいポイント\\n・答えるときの動詞を間違える\\n　Are you 〜? → Yes, I am.（be動詞で答える）\\n　Do you 〜? → Yes, I do.（do で答える）\\n　この2つを混同しないこと！\"},{\"heading\":\"5. be動詞と一般動詞の使い分け・練習問題\",\"body\":\"be動詞と一般動詞を正しく区別できるかが、英文法の第一関門。問題で確認しよう。\\n\\n■ 使い分けのまとめ表\\n　項目／be動詞（am/is/are）／一般動詞（play/like等）\\n　意味 … be動詞（am/is/are）は〜です・いる/ある／一般動詞（play/like等）は動作・状態\\n　否定文 … be動詞（am/is/are）はbe動詞＋not／一般動詞（play/like等）はdo/does not＋原形\\n　疑問文 … be動詞（am/is/are）はbe動詞を前へ／一般動詞（play/like等）はDo/Doesを前へ＋原形\\n　答え … be動詞（am/is/are）はYes, I am.／一般動詞（play/like等）はYes, I do.\\n\\n【問題1】（　）に am / is / are のどれかを入れなさい。\\n① I (   ) a soccer fan.　② She (   ) very kind.　③ They (   ) my classmates.\\n\\n【解答】① am　② is　③ are\\n【解説】I → am、she（三人称単数）→ is、they（複数）→ are。\\n\\n【問題2】次の文を否定文にしなさい。\\n① He plays the guitar.　② I am hungry.\\n\\n【解答】① He does not play the guitar.（doesn't play）　② I am not hungry.（I'm not hungry.）\\n【解説】①一般動詞の文 → does not ＋ 原形（plays → play）。②be動詞の文 → be動詞のあとに not。\\n\\n【問題3】次の文を疑問文にして、Yes で答えなさい。\\n① You like English.　② Ms. Tanaka is a teacher.\\n\\n【解答】① Do you like English? — Yes, I do.　② Is Ms. Tanaka a teacher? — Yes, she is.\\n【解説】①一般動詞 → Do を前に。答えは do。②be動詞 → is を前に。答えは be動詞。Ms. Tanaka は she で受ける。\\n\\n【問題4】まちがいを直しなさい。\\nDoes your sister likes music?\\n\\n【解答】Does your sister like music?\\n【解説】Does の疑問文では動詞を原形にする（likes → like）。\\n\\n★ 入試・テスト対策ポイント\\n■ まず「be動詞の文か一般動詞の文か」を見分ける\\n■ 否定文・疑問文は種類ごとにルールが違う\\n■ does / doesn't のあとの動詞は必ず原形\\n■ 答えの動詞は質問に合わせる（Are→am、Do→do）\"},{\"heading\":\"★ MAXレベル：三単現のsと状態動詞・命令文への発展\",\"body\":\"■ 三人称単数のs（三単現）を落とさないための総整理\\n三単現の s は「主語が三人称・単数・現在形」の3つがそろったときだけつく。1つでも欠けたらつかない。\\n・過去形にはつかない：He played tennis.（s ではなく ed）\\n・does / doesn't のあとはつかない：He doesn't play.（原形）\\n・助動詞（can など）のあとはつかない：He can play.（原形）\\n★ ポイント：「三・単・現」の3拍子がそろったときだけ s、と唱えて確認する。\\n\\n■ 動作動詞と状態動詞（進行形にできない動詞）\\n一般動詞には「動作」を表すものと「状態・気持ち」を表すものがある。\\n・動作動詞：play, run, eat, study（進行形 -ing にできる）\\n・状態動詞：like, love, know, have（持つ）, want, need（原則、進行形にしない）\\n× I am liking this song.（×）\\n○ I like this song.（○）\\n⚠ 注意：have は「持っている」のときは状態動詞（進行形不可）だが、「食べる・過ごす」の意味なら動作動詞になり進行形にできる。\\n　例）I am having lunch.（昼食を食べているところだ）○\\n\\n■ There is / There are（〜がある・いる）の構文\\nbe動詞を使った特別な形。「（場所に）〜がある／いる」を表す。\\n・単数のもの → There is ＋ 単数名詞\\n　例）There is a book on the desk.（机の上に本がある）\\n・複数のもの → There are ＋ 複数名詞\\n　例）There are three cats in the garden.（庭に3匹の猫がいる）\\n・否定：There is not（isn't）／ 疑問：Is there 〜?\\n　例）Is there a station near here? — Yes, there is.\\n⚠ 注意：the my your など「特定のもの」は There is 構文で使わない。\\n　× There is my bag on the desk. → ○ My bag is on the desk.\\n\\n■ 命令文への発展（主語 you を省いた形）\\n一般動詞の文から主語 you を取り、動詞の原形で始めると命令文になる。\\n・You open the window. → Open the window.（窓を開けなさい）\\n・be動詞の命令文は Be で始める：Be quiet.（静かにしなさい）／ Be kind.（親切にしなさい）\\n★ ポイント：命令文は動詞の原形で始まる、という点で「Do/Does の疑問文」「否定文の原形」とルールがつながっている。原形の感覚をここで完成させよう。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_09_gimonshi\",\"studyPeriod\":\"小5後半\",\"subject\":\"eigo\",\"title\":\"疑問詞（what/who/where/when/how など）で質問する\",\"description\":\"5W1Hを使いこなす！具体的にたずねる疑問文の作り方\",\"keyPoints\":[\"疑問詞：what(何)／who(誰)／where(どこ)／when(いつ)／which(どちら)／whose(誰の)／why(なぜ)／how(どう)\",\"語順は「疑問詞＋do/does/did＋主語＋原形」または「疑問詞＋be動詞＋主語」\",\"how many＋可算名詞複数(数)、how much(量・値段)、how old(年齢)、how long(長さ・期間)\",\"why の答えは Because 〜。疑問詞で始まる疑問文には Yes/No で答えない\",\"whose＝誰の（所有）、which＝どちら（選択）\",\"how＝手段・方法・状態（How do you go? / How are you?）\"],\"order\":9,\"sections\":[{\"heading\":\"1. 疑問詞とは・what と who\",\"body\":\"「はい・いいえ」で答えられない、具体的な内容をたずねる質問には「疑問詞」を使う。日本語の「なに・だれ・どこ・いつ・どうやって」にあたる言葉だ。\\n\\n■ おもな疑問詞（5W1H）\\n・what（なに）／ who（だれ）／ where（どこ）\\n・when（いつ）／ why（なぜ）／ how（どうやって・どのくらい）\\n・which（どちら・どれ）／ whose（だれの）\\n\\n■ 疑問詞を使った疑問文の基本の形\\n疑問詞 ＋ ふつうの疑問文（do/does/is/are… ＋ 主語 ＋ 〜）?\\n★ ポイント：疑問詞は「文のいちばん最初」に置く。そのあとは Yes/No 疑問文と同じ語順。\\n\\n■ what（なに）の使い方\\n・単独で「何」：What is this?（これは何ですか）— It is a pen.\\n・一般動詞と：What do you want?（何がほしいですか）— I want a new bag.\\n・「何の〜」と名詞をつける：What sport do you like?（何のスポーツが好きですか）\\n　例）What time is it?（何時ですか）／ What color do you like?（何色が好きですか）\\n\\n■ who（だれ）の使い方\\n・who が主語のとき（だれが〜する）→ 疑問詞のあとにすぐ動詞。三単現の s をつける。\\n　例）Who plays the piano?（だれがピアノを弾きますか）— Tom does.\\n・who が主語でないとき → ふつうの疑問文の語順\\n　例）Who is that girl?（あの女の子はだれですか）— She is my sister.\\n　例）Who do you like?（だれが好きですか）\\n\\n⚠ 注意：疑問詞の疑問文には Yes / No で答えない。たずねられた「中身」を答える。\\n　× Where do you live? — Yes, I do.（×）\\n　○ Where do you live? — I live in Osaka.（○）\"},{\"heading\":\"2. where（どこ）と when（いつ）\",\"body\":\"場所をたずねる where、時をたずねる when は日常会話でも入試でも超頻出。\\n\\n■ where（どこ・どこで・どこに）\\n形：Where ＋ do/does/is/are ＋ 主語 ＋ 〜 ?\\n例）Where do you live?（どこに住んでいますか）— I live in Tokyo.\\n例）Where is my pen?（私のペンはどこですか）— It is on the desk.\\n例）Where does she study?（彼女はどこで勉強しますか）— She studies in her room.\\n★ 答え方：場所を表す語（in 〜, on 〜, at 〜, here, there）で答える。\\n\\n■ 場所を表す前置詞とセットで覚える\\n・in（〜の中に）：in the box ／ in Osaka\\n・on（〜の上に）：on the table\\n・under（〜の下に）：under the chair\\n・near（〜の近くに）：near the station\\n・by（〜のそばに）：by the window\\n\\n■ when（いつ）\\n形：When ＋ do/does/is/are ＋ 主語 ＋ 〜 ?\\n例）When do you play tennis?（いつテニスをしますか）— On Sundays.\\n例）When is your birthday?（誕生日はいつですか）— It is May 5th.\\n例）When does the movie start?（映画はいつ始まりますか）— At seven.\\n★ 答え方：時を表す語（on Monday, in summer, at seven, tomorrow など）で答える。\\n\\n■ 時を表す前置詞の使い分け（重要）\\n・at ＋ 時刻：at seven（7時に）／ at noon（正午に）\\n・on ＋ 曜日・日付：on Sunday ／ on May 5th\\n・in ＋ 月・季節・年：in April ／ in summer ／ in 2026\\n⚠ 注意：「時刻＝at」「曜日/日＝on」「月/季節/年＝in」の3段階で覚える。範囲が広いほど in、せまい一点ほど at。\"},{\"heading\":\"3. how の使い方（数・量・年齢・程度）\",\"body\":\"how は「どうやって（方法）」だけでなく、「how ＋ 形容詞／副詞」でいろいろな程度をたずねる、とても便利な疑問詞。\\n\\n■ how 単独（方法・状態・様子）\\n・方法「どうやって」：How do you go to school?（どうやって学校へ行きますか）— By bus.\\n・状態「どんな具合」：How are you?（元気ですか）— I'm fine, thank you.\\n・感想「どうですか」：How is the weather?（天気はどうですか）— It's sunny.\\n\\n■ how many（いくつ／何人）＋ 数えられる名詞の複数形\\n例）How many books do you have?（本を何冊持っていますか）— I have ten (books).\\n例）How many students are there in your class?（クラスに何人生徒がいますか）— Thirty.\\n★ ポイント：how many のあとの名詞は必ず複数形（books, students）。\\n\\n■ how much（いくら／どれくらい）\\n①値段をたずねる：How much is this bag?（このかばんはいくらですか）— It's 2,000 yen.\\n②数えられない量：How much water do you need?（水はどれくらい必要ですか）\\n★ ポイント：数えられる → how many、数えられない（水・お金など）→ how much。\\n\\n■ how old（何歳・築何年）\\n例）How old are you?（何歳ですか）— I'm twelve (years old).\\n例）How old is this temple?（この寺は築何年ですか）\\n\\n■ how long / how tall / how far など\\n・how long（どのくらい長い・長さ／期間）：How long is this river?\\n・how tall（どのくらい高い・身長）：How tall are you? — I'm 150 cm.\\n・how far（どのくらい遠い・距離）：How far is it from here to the station?\\n・how often（どのくらいの頻度で）：How often do you play tennis? — Twice a week.\\n★ 覚え方：「how ＋ 形容詞」で「どのくらい〜？」とたずねる、が共通ルール。\",\"figureId\":\"xf_eigo_09_gimonshi\"},{\"heading\":\"4. why・which・whose と答え方\",\"mangaId\":\"eigo_09_whywhichwhose_manga\",\"body\":\"残りの疑問詞 why（なぜ）・which（どちら）・whose（だれの）を覚えれば、疑問詞はすべてそろう。\\n\\n■ why（なぜ）と答え方\\n形：Why ＋ do/does/is/are ＋ 主語 ＋ 〜 ?\\n例）Why do you like English?（なぜ英語が好きですか）\\n答え方は2通り：\\n①Because ＋ 主語 ＋ 動詞（〜だから）\\n　例）Because it is fun.（楽しいからです）\\n②To ＋ 動詞の原形（〜するためです）\\n　例）Why do you study hard? — To be a doctor.（医者になるためです）\\n★ ポイント：why の答えは Because または To 〜 で始めるのが基本。\\n\\n■ which（どちら・どれ）\\n2つ以上の中から選ぶときに使う。\\n・Which is your bag, this one or that one?（あなたのかばんはどちら、これそれともあれ）\\n・Which ＋ 名詞：Which season do you like?（どの季節が好きですか）\\n★ ポイント：「A それとも B」と選択肢があるときは、what より which を使う。\\n\\n■ whose（だれの）\\n持ち主をたずねる。「whose ＋ 名詞」または whose 単独。\\n例）Whose pen is this?（これはだれのペンですか）— It's mine.（私のです）\\n例）Whose is this bike?（この自転車はだれのですか）— It's Tom's.\\n★ 答え方：mine（私の）／ yours（あなたの）／ Tom's（トムの）など所有を表す語。\\n\\n■ 疑問詞のまとめ表\\n（疑問詞／意味／答えの例）\\n・what … なに／It's a pen.\\n・who … だれ／She is my sister.\\n・where … どこ／In Osaka.\\n・when … いつ／On Sunday.\\n・why … なぜ／Because it's fun.\\n・how … どうやって/どのくらい／By bus. / I'm fine.\\n・which … どちら／This one.\\n・whose … だれの／It's mine.\\n\\n⚠ 注意：疑問詞疑問文には Yes/No で答えず、たずねられた内容を答える。これが最重要ルール。\"},{\"heading\":\"5. 練習問題（疑問詞）\",\"body\":\"疑問詞を正しく使えるか、問題で確認しよう。\\n\\n【問題1】答えの文に合うように、（　）に適切な疑問詞を入れなさい。\\n① (   ) do you live? — I live in Kyoto.\\n② (   ) is your birthday? — It's April 10th.\\n③ (   ) many pencils do you have? — I have five.\\n\\n【解答】① Where　② When　③ How\\n【解説】①場所を答えている → Where　②日付を答えている → When　③数を答えている → How many の How。\\n\\n【問題2】次の日本語を英語にしなさい。\\n「あなたはなぜ早く起きるのですか。」\\n\\n【解答例】Why do you get up early?\\n【解説】疑問詞 Why ＋ 一般動詞の疑問文（do you get up）＋ early。答えるときは Because 〜 か To 〜。\\n\\n【問題3】下線部をたずねる疑問文を作りなさい。\\nThis is Tom's bag.（下線部：Tom's）\\n\\n【解答】Whose bag is this?\\n【解説】「だれの」持ち物かをたずねる → Whose。whose bag のかたまりを文頭に置き、is this? を続ける。\\n\\n【問題4】（　）に which か what を入れなさい。\\n(   ) do you like better, tea or coffee?\\n\\n【解答】Which\\n【解説】「tea それとも coffee」と2つの選択肢から選ぶので which を使う。選択肢があるときは what ではなく which。\\n\\n★ 入試・テスト対策ポイント\\n■ 疑問詞は文の最初に置き、あとは Yes/No 疑問文と同じ語順\\n■ how ＋ 形容詞（many/much/old/long/tall/far/often）で程度をたずねる\\n■ why の答えは Because 〜／To 〜\\n■ 選択肢があるときは which\\n■ 疑問詞疑問文に Yes/No で答えない\"},{\"heading\":\"★ MAXレベル：間接疑問文・付加疑問・疑問詞＋to\",\"mangaId\":\"eigo_09_fukagimonbun_manga\",\"body\":\"■ 間接疑問文（疑問文が文の中に入る形）\\n疑問文が別の文の一部になると、語順が「疑問詞 ＋ 主語 ＋ 動詞」（ふつうの文の語順）に変わる。do/does/did は使わない。\\n・直接疑問：Where does she live?\\n・間接疑問：I don't know where she lives.（彼女がどこに住んでいるか知らない）\\n例）Do you know what time it is?（今何時か知っていますか）\\n例）Tell me why you were late.（なぜ遅れたのか教えて）\\n⚠ 注意：間接疑問文の中では\\n　①疑問文の語順（倒置）にしない\\n　②do/does/did を使わず、動詞に三単現の s や過去形をつける\\n　× I don't know where does she live. → ○ I don't know where she lives.\\n★ 入試で最も差がつく落とし穴。「文の中の疑問文はふつうの語順」と覚える。\\n\\n■ 付加疑問文（〜だよね？と念を押す）\\n文の最後に「短い疑問」をつけて確認する。前が肯定なら後ろは否定、前が否定なら後ろは肯定にする。\\n・You are a student, aren't you?（あなたは生徒だよね）\\n・He plays tennis, doesn't he?（彼はテニスをするよね）\\n・She doesn't like natto, does she?（彼女は納豆が好きじゃないよね）\\n★ ポイント：前の文の動詞（be動詞／do・does／助動詞）を使い、肯定と否定を逆にして主語を代名詞にする。\\n\\n■ 疑問詞 ＋ to 不定詞（〜すべきか）\\n疑問詞と to ＋ 動詞の原形を組み合わせると、便利な名詞のかたまりになる。\\n・what to do（何をすべきか）：I don't know what to do.（何をすべきかわからない）\\n・how to 〜（〜のしかた）：Please tell me how to use this.（使い方を教えて）\\n・where to go（どこへ行くべきか）：We decided where to go.（どこへ行くか決めた）\\n・when to start（いつ始めるべきか）\\n例）Do you know how to get to the station?（駅への行き方を知っていますか）\\n★ ポイント：「how to swim（泳ぎ方）」のように、疑問詞＋to＋原形で「〜する方法・〜すべきか」を表す。会話・作文で非常に役立つ。\\n\\n■ How come 〜?（なぜ〜なの？）\\nwhy のくだけた言い方。ただし語順がふつうの文（主語＋動詞）になる点に注意。\\n例）How come you are so happy?（どうしてそんなに嬉しいの）\\n⚠ why なら Why are you so happy? と倒置するが、How come のあとは倒置しない。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_10_can_meirei\",\"studyPeriod\":\"小5後半\",\"subject\":\"eigo\",\"title\":\"can・命令文・助動詞の基礎\",\"description\":\"「できる」「〜しなさい」「〜しよう」を表す表現をマスター\",\"keyPoints\":[\"can＋動詞の原形「〜できる」。否定 can't/cannot、疑問 Can you 〜?\",\"can は許可（Can/May I 〜?）・依頼（Can/Could you 〜?）の意味にもなる\",\"命令文は動詞の原形で始める。否定命令は Don't＋原形、ていねいには please を添える\",\"Let's＋動詞の原形「〜しよう」\",\"will「〜だろう・するつもり」、must「〜しなければならない」、should「〜すべき」、may「〜してよい・かもしれない」\",\"助動詞の後は必ず動詞の原形（× can plays）。must は have to で書きかえられる\"],\"order\":10,\"sections\":[{\"heading\":\"1. can の使い方（能力・可能）\",\"mangaId\":\"eigo_10_can_manga\",\"body\":\"can は「〜できる」という意味を表す言葉。動詞を助ける働きをするので「助動詞（じょどうし）」と呼ばれる。\\n\\n■ can の基本の形\\n主語 ＋ can ＋ 動詞の原形 ＋ 〜\\n例）I can swim.（私は泳げる）\\n例）She can speak English.（彼女は英語が話せる）\\n例）Birds can fly.（鳥は飛べる）\\n★ 最重要ポイント：can のあとの動詞は、主語が he/she でも必ず「原形」。三単現の s をつけない。\\n× She can speaks English.（×）\\n○ She can speak English.（○）\\n\\n■ なぜ原形になるのか\\ncan などの助動詞は「動詞を助ける」役目。時制や人称の情報は助動詞がもつので、あとの動詞は変化しない原形のまま。これは will・must・should など他の助動詞にも共通するルール。\\n\\n■ can の否定文（〜できない）\\ncan のあとに not をつける。can not は1語で cannot、短縮形は can't。\\n例）I cannot（can't）ride a bike.（私は自転車に乗れない）\\n例）He can't cook.（彼は料理ができない）\\n\\n■ can の疑問文（〜できますか）\\ncan を文の最初に出す。\\n形：Can ＋ 主語 ＋ 動詞の原形 〜 ?\\n例）Can you play the guitar?（ギターを弾けますか）\\n答え方：Yes, 主語 ＋ can. ／ No, 主語 ＋ can't.\\n例）Can you swim? — Yes, I can. ／ No, I can't.\\n\\n■ be able to（can とほぼ同じ意味）\\ncan は「be able to（〜することができる）」で言いかえられる。\\n例）I can swim. = I am able to swim.\\n★ ポイント：未来（will）や完了形など、can が使えない場面では be able to を使う。\\n例）I will be able to swim soon.（もうすぐ泳げるようになる）※will can とは言えない\",\"figureId\":\"xf_eigo_10_can_meirei\"},{\"heading\":\"2. can のいろいろな意味（許可・依頼）\",\"body\":\"can は「能力（〜できる）」以外にも、会話でよく使う意味がある。場面ごとに覚えよう。\\n\\n■ 許可「〜してもよい」（Can I 〜?）\\n自分がしてよいか相手にたずねる。\\n例）Can I open the window?（窓を開けてもいいですか）\\n例）Can I use your pen?（あなたのペンを使ってもいいですか）\\n答え方：Sure. / Of course. / OK.（いいですよ）／ Sorry, you can't.（だめです）\\n\\n■ 依頼「〜してくれますか」（Can you 〜?）\\n相手に何かをたのむ。\\n例）Can you help me?（手伝ってくれますか）\\n例）Can you pass me the salt?（塩を取ってくれますか）\\n答え方：Sure. / OK. / All right.（いいですよ）／ Sorry, I can't.（ごめん、できません）\\n\\n■ よりていねいな言い方（Could you / May I）\\n・Could you 〜?：Can you より丁寧な依頼「〜していただけますか」\\n　例）Could you tell me the way to the station?（駅への道を教えていただけますか）\\n・May I 〜?：Can I より丁寧な許可「〜してもよろしいですか」\\n　例）May I come in?（入ってもよろしいですか）\\n★ ポイント：Could / May は目上の人やお店などでの丁寧な表現。中身は can とほぼ同じ。\\n\\n■ 「〜できた」（過去の could）\\ncan の過去形は could。「〜できた」を表す。\\n例）I could swim when I was five.（5歳のとき泳げた）\\n否定：couldn't（〜できなかった）\\n例）I couldn't sleep last night.（昨夜は眠れなかった）\\n\\n⚠ 注意：Can I / Can you の答えでは can で答えない。\\n　Can you help me? — Sure.（○）／ Yes, I can.（能力を答える感じで少し不自然）\\n　依頼・許可には Sure. / Of course. / Sorry. などで応じるのが自然。\"},{\"heading\":\"3. 命令文（〜しなさい・〜してください）\",\"body\":\"「〜しなさい」「〜してください」と相手に指示・お願いする文を命令文という。作り方はとてもシンプル。\\n\\n■ 命令文の基本：主語 you を省き、動詞の原形で始める\\n・You open the door. → Open the door.（ドアを開けなさい）\\n・You are quiet. → Be quiet.（静かにしなさい）\\n★ ポイント：ふつうの文の主語 You を取るだけ。be動詞の命令文は Be で始める。\\n\\n■ ていねいにする please\\n文の最初か最後に please をつけると「〜してください」と丁寧になる。\\n例）Please sit down. ／ Sit down, please.（すわってください）\\n★ 文末につけるときは前にコンマ「,」を入れる。\\n\\n■ 否定の命令文「〜してはいけない」（Don't 〜）\\n動詞の原形の前に Don't（Do not）を置く。\\n例）Don't run here.（ここで走ってはいけません）\\n例）Don't be late.（遅れてはいけません）※be動詞でも Don't be\\n例）Don't worry.（心配しないで）\\n\\n■ Let's 〜（〜しよう）：さそいかけの文\\nLet's（Let us の短縮）＋ 動詞の原形 で「（いっしょに）〜しよう」と提案する。\\n例）Let's play soccer.（サッカーをしよう）\\n例）Let's go to the library.（図書館へ行こう）\\n答え方：Yes, let's.（そうしよう）／ Sounds good.（いいね）／ Sorry, I can't.（ごめん、無理）\\n\\n■ 命令文 ＋ and / or（重要構文）\\n・命令文, and 〜：「〜しなさい、そうすれば…」\\n　例）Get up early, and you can catch the train.（早く起きなさい、そうすれば電車に乗れる）\\n・命令文, or 〜：「〜しなさい、さもないと…」\\n　例）Hurry up, or you will be late.（急ぎなさい、さもないと遅れるよ）\\n★ ポイント：and は「そうすれば（良い結果）」、or は「さもないと（悪い結果）」。入試頻出。\\n\\n⚠ 注意：命令文には主語がない。動詞は必ず原形で始める。三単現の s も過去形もつけない。\"},{\"heading\":\"4. その他の助動詞（will / must / should / may）\",\"mangaId\":\"eigo_10_willmust_manga\",\"body\":\"can 以外にも、動詞に意味を加える助動詞がある。どれも「助動詞 ＋ 動詞の原形」の形は共通。\\n\\n■ will（〜するつもりだ・〜だろう）：未来を表す\\n例）I will study hard.（一生懸命勉強するつもりだ）\\n例）It will rain tomorrow.（明日は雨が降るだろう）\\n否定：will not（won't）\\n例）I won't give up.（あきらめない）\\n疑問：Will you 〜?（〜してくれますか／〜するつもりですか）\\n例）Will you help me? — Sure.\\n\\n■ must（〜しなければならない・〜にちがいない）\\n①義務「〜しなければならない」\\n　例）You must do your homework.（宿題をしなければならない）\\n②推量「〜にちがいない」\\n　例）He must be tired.（彼は疲れているにちがいない）\\n否定 must not（mustn't）は「〜してはいけない」（強い禁止）\\n　例）You must not run here.（ここで走ってはいけない）\\n\\n■ have to（〜しなければならない）：must とほぼ同じ意味\\n・主語が三人称単数のときは has to\\n　例）She has to go now.（彼女はもう行かなければならない）\\n・否定 don't have to は「〜しなくてよい」（不必要）※must not と意味が違う！\\n　例）You don't have to hurry.（急がなくてよい）\\n⚠ 注意：must not「〜してはいけない（禁止）」と don't have to「〜しなくてよい（不要）」は正反対。入試頻出の区別。\\n\\n■ should（〜すべきだ・〜したほうがよい）\\n例）You should see a doctor.（医者に行ったほうがよい）\\n例）We should protect nature.（自然を守るべきだ）\\n\\n■ may（〜してもよい・〜かもしれない）\\n①許可「〜してもよい」：You may go home.（帰ってもよい）\\n②推量「〜かもしれない」：It may rain.（雨が降るかもしれない）\\n\\n★ 助動詞の共通ルールまとめ\\n①助動詞のあとの動詞は必ず原形（三単現の s なし）\\n②助動詞は2つ並べられない（× will can → ○ will be able to）\\n③否定は助動詞 ＋ not、疑問は助動詞を前に出す\"},{\"heading\":\"5. 練習問題（can・命令文・助動詞）\",\"body\":\"助動詞と命令文の理解を問題で確認しよう。\\n\\n【問題1】（　）内から正しいものを選びなさい。\\nShe can ( plays / play / played ) the violin.\\n\\n【解答】play\\n【解説】助動詞 can のあとの動詞は必ず原形。主語が she でも plays にしない。\\n\\n【問題2】次の文を否定文にしなさい。\\n① You can enter this room.　② Run in the classroom.（命令文）\\n\\n【解答】① You cannot（can't）enter this room.　② Don't run in the classroom.\\n【解説】①can の否定は cannot／can't。②命令文の否定は Don't ＋ 原形。\\n\\n【問題3】次の日本語を英語にしなさい。\\n「急ぎなさい、さもないとバスに乗り遅れますよ。」\\n\\n【解答例】Hurry up, or you will miss the bus.\\n【解説】「命令文, or 〜」で「〜しなさい、さもないと…」。and（そうすれば）と or（さもないと）を混同しないこと。\\n\\n【問題4】意味の違いに注意して日本語にしなさい。\\n① You must not swim here.　② You don't have to swim here.\\n\\n【解答】① ここで泳いではいけない。（禁止）　② ここで泳ぐ必要はない。（不要）\\n【解説】must not は強い禁止、don't have to は「しなくてよい」。正反対の意味なので要注意。\\n\\n★ 入試・テスト対策ポイント\\n■ 助動詞（can/will/must/should/may）のあとは必ず動詞の原形\\n■ 命令文は原形で始める。否定は Don't、勧誘は Let's\\n■ 「命令文, and」＝そうすれば／「命令文, or」＝さもないと\\n■ must not（禁止）と don't have to（不要）は正反対\\n■ can = be able to、must = have to で言いかえられる\"},{\"heading\":\"★ MAXレベル：助動詞の書きかえと過去・未来での表現\",\"body\":\"■ 助動詞は時制で言いかえが必要（原則2語並べられない）\\n助動詞どうしは並べられないため、未来や完了では「be able to / have to」を使う。\\n・can → 未来：will be able to（〜できるようになる）\\n　例）I will be able to drive a car next year.\\n・must → 未来：will have to（〜しなければならないだろう）\\n　例）You will have to wait.（待たなければならないだろう）\\n・must → 過去：had to（〜しなければならなかった）\\n　例）I had to walk home yesterday.（昨日は歩いて帰らなければならなかった）\\n⚠ 注意：must には過去形がないので、過去は had to を使う。\\n\\n■ 助動詞を使ったていねいな依頼・申し出の使い分け\\n・Will you 〜? … 依頼（〜してくれる？）ややカジュアル\\n・Would you 〜? … Will you より丁寧\\n・Can you 〜? … 依頼（〜できる？）\\n・Could you 〜? … Can you より丁寧\\n・Shall I 〜? … 申し出（〜しましょうか）\\n　例）Shall I carry your bag?（かばんを持ちましょうか）— Yes, please.\\n・Shall we 〜? … 勧誘（いっしょに〜しましょうか）＝ Let's 〜\\n　例）Shall we dance?（踊りましょうか）\\n\\n■ had better（〜したほうがよい／しないと困る）\\nshould より強い忠告。「そうしないとまずい」というニュアンス。\\n例）You had better see a doctor.（医者に行ったほうがいい）\\n否定：had better not（〜しないほうがよい）\\n例）You had better not eat too much.（食べすぎないほうがいい）\\n⚠ 注意：had better のあとも動詞は原形。not の位置は had better の直後（had better not）。\\n\\n■ 助動詞 ＋ have ＋ 過去分詞（過去への推量・後悔）※発展\\n・must have 過去分詞：〜したにちがいない\\n　例）He must have missed the train.（電車に乗り遅れたにちがいない）\\n・should have 過去分詞：〜すべきだったのに（後悔）\\n　例）I should have studied harder.（もっと勉強すべきだった）\\n・may / might have 過去分詞：〜したかもしれない\\n　例）She may have forgotten it.（忘れたのかもしれない）\\n★ ポイント：これらは「今から見て過去のこと」を推量・後悔する上級表現。難関校・高校英語で頻出。\\n\\n■ Let's 〜 の付加疑問と応答\\n・Let's go, shall we?（行きましょうよ、ね？）… Let's の付加疑問は shall we?\\n・命令文の付加疑問は will you?：Open the door, will you?（ドアを開けてくれる？）\\nこれらは「疑問詞・付加疑問」と「命令・勧誘」の知識を組み合わせた総合問題として出やすい。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_11_aisatsu_kaiwa\",\"studyPeriod\":\"小4\",\"subject\":\"eigo\",\"title\":\"あいさつ・自己紹介・数・曜日・時間の会話表現\",\"description\":\"英語で話す第一歩！日常の決まり文句と数・時・曜日を身につける\",\"keyPoints\":[\"あいさつ：Good morning/afternoon/evening、How are you?→I'm fine, thank you.\",\"自己紹介：My name is 〜.／I'm from 〜.／Nice to meet you.\",\"基数（one, two…）と序数（first, second, third…）。日付には序数を使う\",\"曜日 Sunday〜Saturday、月 January〜December。曜日名・月名は必ず大文字で始める\",\"時刻は It's＋数字。What time is it?→It's seven (o'clock).\",\"数字：13〜19は-teen、20/30…は-ty、序数は 21st・22nd・23rd のように作る\"],\"order\":11,\"sections\":[{\"heading\":\"1. あいさつと別れの表現\",\"body\":\"英語のコミュニケーションはあいさつから始まる。場面や時間帯に合ったあいさつを覚えよう。\\n\\n■ 時間帯によるあいさつ\\n・Good morning.（おはよう）… 朝\\n・Good afternoon.（こんにちは）… 昼\\n・Good evening.（こんばんは）… 夜\\n・Hello. / Hi.（やあ・こんにちは）… いつでも使える\\n★ ポイント：Good night.（おやすみ）は「別れ・寝るとき」に使う。夜のあいさつ（会ったとき）は Good evening。\\n\\n■ 調子をたずねる・答える\\n・How are you?（元気ですか）\\n　答え：I'm fine, thank you. And you?（元気です、ありがとう。あなたは？）\\n　　　　Pretty good. / Not bad. / So-so.（まあまあ）\\n・How are you doing? / How's it going?（調子どう？）… くだけた言い方\\n\\n■ はじめて会ったときのあいさつ\\n・Nice to meet you.（はじめまして）\\n　答え：Nice to meet you, too.（こちらこそ）\\n★ ポイント：2回目以降は Nice to see you.（また会えてうれしい）を使う。meet は「初対面」、see は「再会」。\\n\\n■ 別れのあいさつ\\n・Goodbye. / Bye.（さようなら）\\n・See you. / See you later.（またね）／ See you tomorrow.（また明日）\\n・Take care.（気をつけてね）\\n・Have a nice day.（よい一日を）\\n　答え：You too.（あなたもね）\\n\\n■ お礼・あやまり・返事\\n・Thank you (very much). / Thanks.（ありがとう）→ You're welcome.（どういたしまして）\\n・I'm sorry. / Excuse me.（ごめんなさい／すみません）→ That's OK. / No problem.（大丈夫）\\n⚠ 注意：Excuse me. は「呼びかけ・軽い失礼」（すみません＝話しかけるとき）、I'm sorry. は「あやまる」（ごめんなさい）。場面で使い分ける。\"},{\"heading\":\"2. 自己紹介の表現\",\"body\":\"自己紹介は名前・出身・好きなもの・できることなどを英語で言えるようにしよう。スピーキングテストでも定番。\\n\\n■ 名前を言う\\n・My name is Tom. / I'm Tom.（私の名前はトムです）\\n・Please call me Ken.（ケンと呼んでください）\\n・たずねる：What's your name?（お名前は）— My name is 〜.\\n\\n■ 出身・住んでいる場所\\n・I'm from Osaka.（大阪出身です）\\n・I live in Tokyo.（東京に住んでいます）\\n・たずねる：Where are you from? — I'm from Japan.\\n\\n■ 年齢・学年\\n・I'm twelve (years old).（12歳です）\\n・I'm a sixth grader. / I'm in the sixth grade.（6年生です）\\n・たずねる：How old are you? — I'm twelve.\\n\\n■ 好きなもの・得意なこと\\n・I like soccer. / My favorite sport is soccer.（サッカーが好きです）\\n・I'm good at math.（数学が得意です）\\n・I can play the piano.（ピアノが弾けます）\\n・たずねる：What subject do you like? — I like English.\\n\\n■ 家族やペット\\n・I have a brother and a sister.（兄と妹がいます）\\n・I have a dog. Its name is Pochi.（犬を飼っています。名前はポチです）\\n\\n■ 自己紹介の例（つなげてみよう）\\nHello. My name is Yuki. I'm from Kyoto. I'm eleven years old. I like reading books, and I'm good at English. I have a cat. Nice to meet you.\\n★ ポイント：「あいさつ→名前→出身→年齢→好きなこと→ペット→しめのあいさつ」の順で並べると自然な自己紹介になる。\"},{\"heading\":\"3. 数の言い方（基数・序数）\",\"body\":\"数は日付・時間・値段・電話番号などあらゆる場面で使う。基数（ふつうの数）と序数（順番）をセットで覚えよう。\\n\\n■ 基数（ものの数を表す数）1〜20\\none, two, three, four, five, six, seven, eight, nine, ten,\\neleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty\\n⚠ 注意：13〜19は「-teen」、つづりに注意（thirteen, fifteen, eighteen は特別な形）。\\n\\n■ 何十・大きな数\\n・twenty(20), thirty(30), forty(40 ※uなし), fifty(50), sixty(60), seventy(70), eighty(80), ninety(90)\\n・21以上はハイフンでつなぐ：21 → twenty-one ／ 35 → thirty-five\\n・100 → one hundred ／ 1,000 → one thousand ／ 10,000 → ten thousand\\n例）235 → two hundred (and) thirty-five\\n★ ポイント：hundred・thousand は複数でも s をつけない（two hundred、× two hundreds）。\\n\\n■ 序数（順番・〜番目を表す数）\\nfirst(1st), second(2nd), third(3rd), fourth(4th), fifth(5th),\\nsixth(6th), seventh(7th), eighth(8th), ninth(9th ※eなし), tenth(10th),\\neleventh, twelfth(12th), … twentieth(20th), twenty-first(21st)\\n★ ポイント：1st, 2nd, 3rd は特別な形。それ以外は基本「-th」。5番目 fifth、9番目 ninth、12番目 twelfth はつづりに注意。\\n\\n■ 序数を使う場面\\n・日付：May 5th（5月5日）／ the third of April（4月3日）\\n・順番：the first floor（1階）／ the second question（2問目）\\n・「〜回目」：the first time（初めて）\\n\\n■ 電話番号・年号の読み方\\n・電話番号は数字を1つずつ読む：090-1234-5678 → zero nine zero, one two three four, …\\n・年号は2けたずつ：1999 → nineteen ninety-nine ／ 2026 → twenty twenty-six\\n⚠ 注意：0 は「オー」または「ゼロ」と読む。\",\"figureId\":\"xf_eigo_11_aisatsu_kaiwa\"},{\"heading\":\"4. 曜日・月・日付の言い方\",\"body\":\"曜日・月・日付は会話でも入試でも頻出。つづりと大文字ルールに注意して覚えよう。\\n\\n■ 曜日（Days of the week）※最初は大文字\\nSunday（日）, Monday（月）, Tuesday（火）, Wednesday（水）,\\nThursday（木）, Friday（金）, Saturday（土）\\n⚠ 注意：Wednesday（d を読まない）、Tuesday・Thursday のつづりに注意。\\n・「〜曜日に」は on を使う：on Monday（月曜日に）／ on Sundays（毎週日曜に）\\n・たずねる：What day is it today? — It's Friday.（今日は何曜日？— 金曜日）\\n\\n■ 月（Months）※最初は大文字\\nJanuary（1月）, February（2月）, March（3月）, April（4月）,\\nMay（5月）, June（6月）, July（7月）, August（8月）,\\nSeptember（9月）, October（10月）, November（11月）, December（12月）\\n・「〜月に」は in を使う：in April（4月に）／ in December\\n⚠ 注意：February のつづり（r が2つ）、August の発音（オーガスト）に注意。\\n\\n■ 日付の言い方\\n・月 ＋ 序数：May 5th（5月5日）／ July 20th\\n・読むときは序数（fifth, twentieth）で読む：May fifth\\n・「〜日に」は on：on May 5th\\n・たずねる：What's the date today? — It's June 10th.（今日は何日？— 6月10日）\\n\\n■ 日付を書く順番（アメリカ式とイギリス式）\\n・アメリカ式：月→日→年　例）April 3, 2026 ／ 4/3/2026\\n・イギリス式：日→月→年　例）3 April 2026 ／ 3/4/2026\\n★ ポイント：4/3 がアメリカでは4月3日、イギリスでは3月4日を指す。入試ではアメリカ式が基本。\\n\\n■ 季節（Seasons）\\nspring（春）, summer（夏）, fall / autumn（秋）, winter（冬）\\n・「〜（季節）に」は in：in summer（夏に）\\n例）I like winter because I can ski.（スキーができるので冬が好きだ）\"},{\"heading\":\"5. 時間の言い方と練習問題\",\"body\":\"時刻のたずね方・答え方を覚えれば、日常会話とリスニングでぐっと有利になる。\\n\\n■ 時刻のたずね方\\n・What time is it (now)?（今何時ですか）\\n・Do you have the time?（今何時ですか）※ていねいな言い方\\n・What time do you 〜?（何時に〜しますか）\\n　例）What time do you get up? — At six.（6時に起きます）\\n\\n■ 時刻の答え方\\n①「時＋分」をそのまま並べる（かんたん）\\n　7:15 → It's seven fifteen. ／ 8:30 → It's eight thirty.\\n②past（過ぎ）と to（前）を使う言い方\\n　・7:15 → It's fifteen past seven.（7時15分過ぎ）\\n　・7:45 → It's fifteen to eight.（8時15分前）\\n　・7:30 → It's half past seven.（7時半）\\n　・7:00ちょうど → It's seven o'clock.\\n★ ポイント：past は「〜分過ぎ」、to は「〜分前（次の時刻まで）」。half は30分、quarter は15分。\\n\\n■ 午前・午後\\n・a.m.（午前）／ p.m.（午後）\\n　例）It's 9 a.m.（午前9時）／ It's 3 p.m.（午後3時）\\n・in the morning（午前中に）／ in the afternoon（午後に）／ in the evening（夕方に）／ at night（夜に）\\n・at noon（正午に）／ at midnight（真夜中に）\\n\\n【問題1】次の時刻を英語で言いなさい（2通り）。\\n6:30\\n\\n【解答】It's six thirty. ／ It's half past six.\\n【解説】そのまま読む言い方と past を使う言い方の両方ができるとよい。30分は half。\\n\\n【問題2】（　）に at / on / in のどれかを入れなさい。\\n① I get up (   ) seven.　② My birthday is (   ) May.　③ We have no school (   ) Sunday.\\n\\n【解答】① at　② in　③ on\\n【解説】時刻は at、月は in、曜日は on。「点＝at、範囲が広い＝in、曜日/日付＝on」で覚える。\\n\\n【問題3】次の日本語を英語にしなさい。\\n「今日は何曜日ですか。」\\n\\n【解答】What day is it today?\\n【解説】曜日をたずねる決まった言い方。日付をたずねるなら What's the date today?。\\n\\n★ まとめ\\n■ あいさつは時間帯・初対面/再会で使い分ける\\n■ 自己紹介は「名前→出身→年齢→好き→ペット」の順\\n■ 序数の 1st/2nd/3rd/5th/9th/12th は特別な形\\n■ 時の前置詞：時刻 at ／ 曜日・日付 on ／ 月・季節・年 in\\n■ 時刻は「そのまま読む」と「past / to」の2通り\",\"mangaId\":\"eigo_11_aisatsu_kaiwa_xm\"},{\"heading\":\"★ MAXレベル：場面別の会話表現とていねいさ\",\"body\":\"■ 買い物での会話（店員と客）\\n・店員：May I help you?（いらっしゃいませ／お手伝いしましょうか）\\n・客：I'm just looking, thank you.（見ているだけです）／ I'm looking for a T-shirt.（Tシャツを探しています）\\n・値段：How much is it? — It's 1,500 yen.\\n・試着：Can I try it on?（試着してもいいですか）\\n・決める：I'll take it.（これをください）／ Here you are.（はいどうぞ）\\n★ ポイント：May I help you? は店・道案内など「手伝いの申し出」の決まり文句。\\n\\n■ 電話での会話\\n・Hello, this is Tom.（もしもし、トムです）※電話では I am ではなく this is を使う\\n・May I speak to Ken?（ケンをお願いできますか）\\n・Speaking.（私です）※本人が出たとき\\n・Hold on, please. / Just a moment, please.（少々お待ちください）\\n・Can I take a message?（伝言をうかがいましょうか）／ Can I leave a message?（伝言をお願いできますか）\\n⚠ 注意：電話で名乗るときは this is 〜 を使う。I am Tom とは言わない。\\n\\n■ レストラン・食事での会話\\n・注文をとる：Are you ready to order?（ご注文はお決まりですか）\\n・注文する：I'd like a hamburger, please.（ハンバーガーをお願いします）※I'd like = I would like（ていねいな I want）\\n・すすめる：Would you like some more?（もう少しいかがですか）— Yes, please. / No, thank you.\\n・会計：Check, please. / Can I have the bill?（お会計をお願いします）\\n★ ポイント：I'd like 〜／Would you like 〜? は want より丁寧。接客・おもてなしの定番表現。\\n\\n■ 道案内の会話\\n・たずねる：Excuse me. How can I get to the station?（駅へはどう行けばいいですか）\\n・答える：Go straight and turn right at the second corner. It's on your left.\\n・距離・時間：It's about five minutes' walk.（歩いて5分くらいです）\\n・お礼：Thank you. — You're welcome.\\n\\n■ ていねいさの段階（同じ内容でも表現で印象が変わる）\\n（カジュアル／ふつう／ていねい）\\n・Open the window. … Can you open the window?／Could you open the window?\\n・I want water. … I'd like water.／I'd like some water, please.\\n・What? … Pardon?／I beg your pardon?\\n★ 入試のリスニング・会話問題では、場面（店・電話・食事・道案内）と、ていねいさのレベルを聞き分ける力が問われる。決まり文句をかたまりで覚えておくと即得点につながる。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_12_zenchishi\",\"subject\":\"eigo\",\"title\":\"前置詞の使い分け完全マスター（in/on/at/for/during 等）\",\"description\":\"小さいけど得点源！場所・時間・関係を表す前置詞を体系整理\",\"keyPoints\":[\"場所：at（点・狭い場所）／in（広い空間の中）／on（面に接している）。in the box・on the desk・at the station\",\"時刻・時：at＋時刻（at seven）／on＋曜日・日付（on Monday）／in＋月・季節・年（in April）\",\"期間：for＋数字（for three years）／during＋特定の期間（during summer vacation）\",\"期限：by＋期限（〜までに、完了）／until＋期限（〜まで、継続）。この区別は入試最頻出\",\"移動：to（〜へ）／from（〜から）／into（〜の中へ）／out of（〜の外へ）／through（〜を通り抜けて）\",\"前置詞とセットで覚える熟語：be famous for／be afraid of／depend on／listen to／look for／arrive at(in)\",\"群前置詞：because of／in spite of／according to／thanks to（あとに名詞・動名詞を続ける）\"],\"order\":12,\"examType\":\"chugaku\",\"studyPeriod\":\"小5前半\",\"sections\":[{\"heading\":\"1. 場所を表す前置詞（in / on / at / under / near など）\",\"mangaId\":\"eigo_12_bashozenchishi_manga\",\"body\":\"前置詞は名詞の前に置いて「場所・時・関係」を表す小さな単語だが、入試では空所補充・並び替え・英作文のあらゆる場面で問われる最重要分野の一つ。\\n\\n■ in・on・at の基本イメージ\\n・in：広がりのある空間の「中」にある\\n例）in the box（箱の中に）／ in Tokyo（東京の中に）／ in the water（水の中に）\\n・on：面に「接している」\\n例）on the desk（机の上に、接している）／ on the wall（壁に、貼りついて）／ on the ceiling（天井に）\\n・at：地図上の「点」として特定の場所を指す\\n例）at the station（駅というポイントで）／ at the door（ドアのところで）／ at home（家で）\\n\\n★ ポイント：on は必ずしも「上」ではなく「接触」を表す。壁のポスターも on the wall、天井の電球も on the ceiling。\\n\\n■ 位置関係を表す前置詞\\nunder（〜の下に）／ over・above（〜の上に、離れて）／ below（〜より下に）\\nnext to・beside（〜の隣に）／ near・close to（〜の近くに）\\nin front of（〜の前に）／ behind（〜の後ろに）\\nbetween A and B（AとBの間に：2つのものの間）\\namong（〜の間に：3つ以上・大勢の中に）\\n\\n例）The cat is under the table.（猫はテーブルの下にいる）\\n例）My house is between the park and the school.（私の家は公園と学校の間にある）\\n例）She is popular among students.（彼女は生徒たちの間で人気がある）\\n\\n⚠ 注意：between（2者の間）と among（3者以上の間）の使い分けは並び替え・空所補充の定番。\\n\\n■ 建物・乗り物の中にいることを表す前置詞\\nin a car / in a taxi（狭い乗り物の中：入って座る）\\non a bus / on a train / on a plane（広く移動できる乗り物：乗って歩ける）\\n例）I read a book on the train.（電車の中で本を読む）\\n例）She got into the car.（彼女は車に乗り込んだ）\\n★ ポイント：狭い乗り物（car/taxi）は in、広い乗り物（bus/train/plane/ship）は on。\"},{\"heading\":\"2. 時を表す前置詞（at / on / in / for / during）\",\"mangaId\":\"eigo_12_zenchishi_manga\",\"body\":\"時を表す前置詞は「範囲の広さ」で使い分けるとわかりやすい。狭い範囲から広い範囲の順に整理しよう。\\n\\n■ at・on・in の使い分け（時刻・曜日・月）\\n・at ＋ 時刻・時の一点：at seven（7時に）／ at noon（正午に）／ at night（夜に）\\n・on ＋ 曜日・日付・特定の日：on Monday（月曜日に）／ on May 5th（5月5日に）／ on my birthday（誕生日に）\\n・in ＋ 月・季節・年・世紀などの広い期間：in April（4月に）／ in summer（夏に）／ in 2026（2026年に）\\n\\n★ 覚え方：「点＝at」「曜日・日付＝on」「月・季節・年＝in」の3段階。狭いものから広いものへ。\\n\\n■ for と during（期間を表す前置詞）\\n・for ＋ 数字を含む期間：「〜の間（数字ではっきり示せる期間）」\\n例）I have lived here for ten years.（10年間ここに住んでいる）\\n例）We waited for two hours.（2時間待った）\\n・during ＋ 特定の期間（名詞）：「〜の間（いつの期間かを名詞で示す）」\\n例）I went to Kyoto during the summer vacation.（夏休みの間に京都に行った）\\n例）She fell asleep during the movie.（映画の間に眠ってしまった）\\n⚠ 注意：during のあとは「数字」ではなく「特定の名詞（期間を表す言葉）」がくる。\\n× during two hours（×）→ ○ for two hours（○）\\n\\n■ by と until（期限を表す前置詞・最重要の区別）\\n・by ＋ 期限：「〜までに」（その時までに動作が完了する）\\n例）Please finish this work by Friday.（金曜日までにこの仕事を終えてください）\\n→ 金曜日までのどこかで「終わる」という一回きりの動作。\\n・until（till）＋ 期限：「〜まで（ずっと）」（その時まで動作・状態が継続する）\\n例）I will wait here until five.（5時までここで待つ）\\n→ 5時まで「待つ」という状態がずっと続く。\\n\\n⚠ 入試最頻出の見分け方：動詞が「完了する動作（finish/return/submit）」なら by、「継続する状態（wait/stay/sleep）」なら until。\\n例）Submit your homework by Monday.（月曜までに提出＝完了）\\n例）She stayed at her aunt's house until Monday.（月曜まで滞在＝継続）\\n\\n■ その他の時の前置詞\\n・before（〜の前に）／ after（〜の後に）\\n・since（〜以来、起点）：I have known him since 2020.\\n・within（〜以内に）：Please reply within a week.（1週間以内に返信してください）\",\"figureId\":\"xf_eigo_12_zenchishi\"},{\"heading\":\"3. 方向・移動を表す前置詞\",\"body\":\"動きのある動詞（go/come/run/walkなど）と一緒に使われる前置詞は、動きの方向をイメージすると覚えやすい。\\n\\n■ 基本の方向前置詞\\n・to（〜へ、到達点）：I go to school.（学校へ行く）\\n・from（〜から、出発点）：I am from Japan.（私は日本出身だ）\\n・into（〜の中へ）：She went into the room.（彼女は部屋に入った）\\n・out of（〜の外へ）：He came out of the house.（彼は家から出てきた）\\n例）A cat jumped out of the box.（猫は箱から飛び出した）\\n\\n■ 通過・経由を表す前置詞\\n・through（〜を通り抜けて）：We walked through the forest.（森を通り抜けて歩いた）\\n・along（〜に沿って）：They walked along the river.（川に沿って歩いた）\\n・across（〜を横切って）：She ran across the street.（彼女は通りを走って渡った）\\n・past（〜のそばを通り過ぎて）：He walked past the school.（彼は学校を通り過ぎて歩いた）\\n\\n■ 方向を表す前置詞\\n・toward(s)（〜の方向へ、到達を含意しない）：He walked toward the station.（駅の方へ歩いた）\\n・for（〜行きの、目的地）：This train is for Osaka.（この電車は大阪行きだ）\\n・up（〜を上へ）／ down（〜を下へ）：She went up the stairs.（階段を上った）\\n\\n■ 手段・道具を表す前置詞\\n・by ＋ 交通手段（無冠詞）：by bus / by train / by car / by bike\\n例）I go to school by bike.（自転車で学校に行く）\\n⚠ 注意：歩く場合は on foot（前置詞byは使わない）。\\n・with ＋ 道具：write with a pen（ペンで書く）\\n・by ＋ 動名詞：「〜することによって」\\n例）You can improve your English by reading a lot.（たくさん読むことで英語が上達する）\\n\\n■ 前置詞＋関係の意味（〜について・〜のために）\\n・about（〜について）：talk about the weather\\n・for（〜のために）：This is a present for you.\\n・with（〜と一緒に、〜を持って）：I went there with my mother.\\n・without（〜なしで）：He can't live without his phone.\"},{\"heading\":\"4. 前置詞とセットで覚える重要熟語\",\"body\":\"動詞・形容詞と特定の前置詞が結びついた「セット表現」は、丸ごと覚えることが最も効率的。入試で穴埋め問題として頻出する。\\n\\n■ be動詞＋形容詞＋前置詞\\n・be famous for 〜：〜で有名だ（Kyoto is famous for its temples.）\\n・be afraid of 〜：〜を恐れる（She is afraid of dogs.）\\n・be interested in 〜：〜に興味がある（I'm interested in science.）\\n・be good at 〜：〜が得意だ（He is good at soccer.）\\n・be different from 〜：〜と異なる（This is different from that.）\\n・be full of 〜：〜でいっぱいだ（The box is full of toys.）\\n・be proud of 〜：〜を誇りに思う（She is proud of her son.）\\n・be tired of 〜：〜に飽きる（I'm tired of waiting.）\\n・be surprised at 〜：〜に驚く（He was surprised at the news.）\\n・be similar to 〜：〜に似ている（This bag is similar to mine.）\\n\\n■ 動詞＋前置詞のセット\\n・depend on 〜：〜次第だ・〜に頼る（It depends on the weather.）\\n・listen to 〜：〜を聞く（Listen to me carefully.）\\n・look for 〜：〜を探す（I'm looking for my key.）\\n・wait for 〜：〜を待つ（We waited for the bus.）\\n・arrive at（狭い場所）／ arrive in（広い場所）：arrive at the station / arrive in Japan\\n・laugh at 〜：〜を笑う（Don't laugh at him.）\\n・agree with 〜（人の意見に）：I agree with you.\\n・belong to 〜：〜に所属する（This bike belongs to me.）\\n・take care of 〜：〜の世話をする（She takes care of the baby.）\\n・consist of 〜：〜から成る（The team consists of ten players.）\\n\\n■ 名詞＋前置詞のセット\\n・a member of 〜：〜の一員（a member of the club）\\n・the number of 〜：〜の数（the number of students）\\n・a cause of 〜：〜の原因\\n\\n⚠ 入試の罠：似た意味でも前置詞が違う組み合わせが頻出。\\n・talk to（一方的に話す）／ talk with（対話する）\\n・different from（〜と違う）※ ×different than（アメリカ英語ではthanも使われるが正式にはfrom）\\n・good at（得意）／ good for（〜に良い、体に良い）：Vegetables are good for you.\"},{\"heading\":\"5. 入試例題（前置詞）\",\"body\":\"以下の問題で前置詞の使い分けを確認しよう。\\n\\n【問題1】（　）に適切な前置詞を入れなさい。\\nPlease finish your report (   ) next Monday.\\n\\n【解答】by\\n【解説】「終える」という完了の動作なので、期限を表す by を使う。until を使うと「月曜日までずっと終える状態が続く」という不自然な意味になってしまう。\\n\\n【問題2】（　）内から適切な語を選びなさい。\\nMy birthday is (   ) May 5th.\\na) at  b) on  c) in  d) for\\n\\n【解答】b) on\\n【解説】特定の日付には on を使う。at は時刻、in は月・季節・年に使う。\\n\\n【問題3】次の文の（　）に適切な前置詞を入れなさい。\\nKyoto is famous (   ) its beautiful temples.\\n\\n【解答】for\\n【解説】be famous for 〜「〜で有名だ」はセットで覚える重要熟語。\\n\\n【問題4】（　）内から適切な語を選びなさい。\\nThe cat is popular (   ) students in our school. (between / among)\\n\\n【解答】among\\n【解説】studentsのように3人以上の集団の中でのことを言うときは among を使う。2者の間なら between。\\n\\n★ 入試対策ポイント：\\n■ 場所：狭い点は at、面は on、空間の中は in\\n■ 時：狭い時刻は at、曜日・日付は on、月・季節・年は in\\n■ 期限の by（〜までに完了）と継続の until（〜までずっと）を混同しない\\n■ be famous for / be afraid of / depend on など熟語は前置詞ごとセットで暗記する\"},{\"heading\":\"★ MAXレベル：紛らわしい前置詞の精密使い分けと群前置詞\",\"body\":\"■ beside と besides の違い（スペルが似ていて要注意）\\n・beside（前置詞）：〜のそばに（位置）\\n例）She sat beside me.（彼女は私のそばに座った）\\n・besides（前置詞・副詞）：〜に加えて（追加）\\n例）Besides English, she can speak French.（英語に加えてフランス語も話せる）\\n\\n■ during と for の応用比較、by と until の総復習\\n・during は「特定の期間の中のある時点・全体」、for は「継続時間の長さ」を強調する。\\n例）It rained during the night.（夜の間に雨が降った＝夜のどこかで）\\n例）It rained for five hours.（5時間雨が降った＝継続時間）\\n・by と until を同じ文で比べる\\n例）I will be here until six.（6時までここにいる＝ずっといる、継続）\\n例）I will finish it by six.（6時までに終える＝6時までのどこかで完了）\\n\\n■ 群前置詞（2語以上で1つの前置詞のはたらきをする表現）\\n・because of ＋ 名詞：〜が原因で\\n例）The game was cancelled because of the rain.（雨のため試合は中止になった）\\n・in spite of ＋ 名詞：〜にもかかわらず\\n例）In spite of the rain, they played soccer.（雨にもかかわらずサッカーをした）\\n・thanks to ＋ 名詞：〜のおかげで\\n例）Thanks to your help, I finished it easily.（あなたの助けのおかげで簡単に終えられた）\\n・according to ＋ 名詞：〜によれば\\n例）According to the weather report, it will snow tomorrow.（天気予報によると明日は雪だ）\\n・instead of ＋ 名詞／動名詞：〜の代わりに\\n例）She had salad instead of rice.（ご飯の代わりにサラダを食べた）\\n・in front of（〜の前に）／ on top of（〜の上に）／ next to（〜の隣に）\\n\\n⚠ 入試の罠：because（接続詞、あとに主語＋動詞）と because of（前置詞、あとに名詞）を混同しない。\\n例）Because it rained, the game was cancelled.（接続詞＋文）\\n例）Because of the rain, the game was cancelled.（前置詞＋名詞）\\n同様に、although（接続詞）と in spite of / despite（前置詞）も同じ関係。\\n\\n■ 前置詞＋関係代名詞（上級構文）\\n前置詞は関係代名詞の前に移動することがある（ややフォーマルな言い方）。\\n例）the house that I live in ＝ the house in which I live（私が住んでいる家）\\n★ 中学レベルでは「後置」の形（住んでいる家＝the house I live in）が基本だが、難関校では「前置」の形も出題される。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_13_hikaku\",\"subject\":\"eigo\",\"title\":\"比較級・最上級で程度を表す\",\"description\":\"「もっと〜」「いちばん〜」を正確に作る！比較表現の総まとめ\",\"keyPoints\":[\"比較級は形容詞・副詞に-erをつける（tall→taller）か、前にmoreを置く（beautiful→more beautiful）\",\"最上級は-estをつける（tall→tallest）かmostを置く（beautiful→most beautiful）。原則theをつける\",\"1音節の語は-er/-est、3音節以上はmore/most。2音節語は語によって異なる（-yで終わる語は-ier/-iest）\",\"不規則変化：good/well→better→best、bad→worse→worst、many/much→more→most、little→less→least\",\"A is 比較級 than B「AはBより〜」。A is the 最上級 of/in 〜「Aは〜の中でいちばん〜」\",\"原級の比較：as ＋ 原級 ＋ as「〜と同じくらい」、not as 〜 as「〜ほど〜ではない」\",\"比較級を強める語：much/far/a lot（ずっと）。最上級を強める語：by far（断然）\"],\"order\":13,\"examType\":\"chugaku\",\"studyPeriod\":\"小5前半\",\"sections\":[{\"heading\":\"1. 比較級・最上級の作り方\",\"mangaId\":\"eigo_13_hikaku_manga\",\"body\":\"「AはBより〜だ」「Aがいちばん〜だ」という比較の表現は、形容詞・副詞の形を変えて作る。まずは基本の作り方のルールを整理しよう。\\n\\n■ 語尾に-er / -estをつけるパターン（原則：1音節の短い語）\\n・そのまま-er / -est：tall → taller → tallest（背が高い）\\n　small → smaller → smallest／ long → longer → longest\\n・eで終わる語は-r / -stのみ：large → larger → largest／ nice → nicer → nicest\\n・「短母音＋子音字」で終わる語は子音字を重ねる：big → bigger → biggest／ hot → hotter → hottest\\n・「子音字＋y」で終わる語はyをiに変える：easy → easier → easiest／ happy → happier → happiest\\n\\n■ more / mostをつけるパターン（原則：2音節以上の長い語）\\nbeautiful → more beautiful → most beautiful（美しい）\\nfamous → more famous → most famous（有名な）\\ndifficult → more difficult → most difficult（難しい）\\nimportant → more important → most important（重要な）\\ncarefully → more carefully → most carefully（副詞：注意深く）\\n\\n■ 音節数で迷ったときの目安\\n・1音節（母音のかたまりが1つ）：tall, big, long, fast → -er/-est\\n・3音節以上：beautiful, important, interesting → more/most\\n・2音節：語によって異なる。-y/-er/-ow/-leで終わる語は-er/-estが多い（happy→happier、clever→cleverer）。それ以外はmore/mostが多い（modern→more modern）\\n★ 迷ったら辞書で確認する習慣をつけよう。中学レベルでは代表的な語の形を覚えてしまうのが確実。\\n\\n■ 不規則変化（丸暗記が必要な重要語）\\ngood / well（良い・上手に）→ better → best\\nbad（悪い）→ worse → worst\\nmany / much（多い）→ more → most\\nlittle（少ない）→ less → least\\nfar（遠い）→ farther/further → farthest/furthest\\n★ ポイント：good と well はどちらも比較級・最上級が better/best になる。\",\"figureId\":\"xf_eigo_13_hikaku\"},{\"heading\":\"2. 比較級の文（A is 比較級 than B）\",\"body\":\"2つのものを比べて「AはBより〜だ」と言うときの文の形を確認しよう。\\n\\n■ 比較級の基本文\\nA ＋ be動詞 ＋ 比較級 ＋ than ＋ B\\n例）Tom is taller than Ken.（トムはケンより背が高い）\\n例）This book is more interesting than that one.（この本はあの本より面白い）\\n例）I get up earlier than my brother.（私は弟より早く起きる）※副詞の比較\\n\\n■ 比較級を強調する語（「ずっと〜」）\\nmuch / far / a lot ＋ 比較級：とても・ずっと〜\\n例）This bag is much heavier than that one.（このかばんはあのかばんよりずっと重い）\\n例）She runs a lot faster than me.（彼女は私よりずっと速く走る）\\n⚠ 注意：veryは比較級を修飾しない。× very taller（×）→ ○ much taller（○）\\n\\n■ 「少し〜」を表す語\\na little ＋ 比較級：少し〜\\n例）This one is a little cheaper than that one.（これはあれより少し安い）\\n\\n■ どんどん〜になる（比較級 and 比較級）\\n「比較級 and 比較級」で「ますます〜」という意味を表す。\\n例）It's getting colder and colder.（ますます寒くなっている）\\n例）More and more people use smartphones.（ますます多くの人がスマートフォンを使う）\\n⚠ 注意：more/mostを使う語はmore and moreの形にする（× interestinger and interestinger）\\n\\n■ the ＋ 比較級, the ＋ 比較級（〜すればするほど…）\\n例）The more you practice, the better you play.（練習すればするほど上手になる）\\n例）The harder he studied, the higher his score became.（一生懸命勉強すればするほど点数が上がった）\\n\\n■ 疑問文でたずねる比較\\nWhich is 比較級, A or B?（AとBではどちらが〜ですか）\\n例）Which is bigger, Japan or the U.K.?（日本とイギリスではどちらが大きいですか）— Japan is bigger.\"},{\"heading\":\"3. 最上級の文（A is the 最上級 of/in 〜）\",\"body\":\"3つ以上のものを比べて「Aがいちばん〜だ」と言うときの表現。\\n\\n■ 最上級の基本文\\nA ＋ be動詞 ＋ the ＋ 最上級 ＋ of/in 〜\\n例）Tom is the tallest in his class.（トムはクラスでいちばん背が高い）\\n例）This is the most interesting book of all.（これは全部の中でいちばん面白い本だ）\\n★ ポイント：最上級には原則 the をつける（副詞の最上級ではtheを省略することもある）。\\n\\n■ of と in の使い分け\\n・of ＋ 複数を表す語（数・all）：of the three（3つの中で）、of all students（全生徒の中で）\\n　例）This is the biggest of the three cakes.（3つのケーキの中でいちばん大きい）\\n・in ＋ 場所・集団を表す単数の語（class/school/family/Japan）：in my class、in Japan\\n　例）She is the youngest in her family.（彼女は家族の中でいちばん年下だ）\\n⚠ 注意：of と in を混同しやすい。「複数のグループ（3人/all）」→ of、「1つの場所・組織」→ in と覚える。\\n\\n■ 最上級を強調する表現\\nby far ＋ the 最上級：断然いちばん〜\\n例）She is by far the best singer in our school.（彼女は学校で断然いちばん上手な歌手だ）\\none of the 最上級 ＋ 複数名詞：最も〜な〜のひとつ\\n例）Mt. Fuji is one of the most famous mountains in Japan.（富士山は日本で最も有名な山のひとつだ）\\n⚠ 注意：one of のあとの名詞は必ず複数形にする。× one of the most famous mountain（×）\\n\\n■ 副詞の最上級（the を省略することがある）\\n例）He runs fastest in his class.（彼はクラスでいちばん速く走る）※ the を省略してもよい\\n例）Who studies hardest in this class?（このクラスでだれがいちばん熱心に勉強しますか）\\n\\n■ 疑問詞 What/Who ＋ 最上級\\nWhat is the longest river in the world?（世界でいちばん長い川は何ですか）— It's the Nile.\\nWho is the most popular singer in Japan?（日本でいちばん人気の歌手はだれですか）\"},{\"heading\":\"4. 原級の比較（as 〜 as）\",\"body\":\"「同じくらい〜」「〜ほど〜ではない」という、比較級・最上級を使わない比較の形も重要。\\n\\n■ as ＋ 原級 ＋ as ...（…と同じくらい〜だ）\\n形容詞・副詞は元の形（原級）のまま使う。\\n例）Tom is as tall as Ken.（トムはケンと同じくらいの背の高さだ）\\n例）She can run as fast as her brother.（彼女は兄と同じくらい速く走れる）\\n⚠ 注意：as と as の間には比較級ではなく原級（元の形）を入れる。× as taller as（×）\\n\\n■ not as 〜 as ...（…ほど〜ではない）\\n例）This book is not as difficult as that one.（この本はあの本ほど難しくない）\\n= That one is more difficult than this book.（あの本のほうがこの本より難しい）\\n例）I don't run as fast as my sister.（私は姉ほど速く走れない）\\n★ ポイント：not as A as B ＝ B is 比較級 than A（言いかえが可能）。not so 〜 as という形もある（意味は同じ）。\\n\\n■ 倍数表現との組み合わせ（発展）\\n・twice as 〜 as：…の2倍〜だ\\n例）This bag is twice as heavy as that one.（このかばんはあのかばんの2倍重い）\\n・three times as 〜 as：…の3倍〜だ\\n例）This building is three times as tall as that one.（この建物はあの建物の3倍の高さだ）\\n\\n■ as 〜 as possible（できるだけ〜）／ as 〜 as 主語 can（〜できるだけ）\\n例）Please come as soon as possible.（できるだけ早く来てください）\\n= Please come as soon as you can.\\n★ このパターンは英作文でも頻出。丸ごと覚えておこう。\\n\\n■ 比較の言いかえ（同じ意味を複数の形で表す・入試頻出）\\n①Tom is taller than Ken.\\n②Ken is shorter than Tom.\\n③Tom is not as short as Ken. ／ Ken is not as tall as Tom.\\n★ 1つの事実を「比較級」と「not as 〜 as」の両方で表現できることを理解しておくと、書きかえ問題に強くなる。\"},{\"heading\":\"5. 入試例題（比較級・最上級）\",\"body\":\"以下の問題で比較表現の理解を確認しよう。\\n\\n【問題1】（　）内の語を適切な形に変えなさい。\\nThis question is (difficult) than that one.\\n\\n【解答】more difficult\\n【解説】difficultは3音節以上の語なのでmoreをつける。× difficulter とはしない。\\n\\n【問題2】次の文を最上級の文に書きかえなさい。\\nKen is taller than any other student in his class.\\n\\n【解答】Ken is the tallest student in his class.\\n【解説】「他のどの〜より背が高い」＝「いちばん背が高い」という書きかえパターン。any other のあとの名詞は単数形になる点にも注意。\\n\\n【問題3】（　）に適切な語を入れなさい。\\nThis movie is not as (   ) as that one.（この映画はあの映画ほど面白くない）\\n\\n【解答】interesting\\n【解説】as と as の間には形容詞の原級（元の形）を入れる。比較級（more interesting）にはしない。\\n\\n【問題4】（　）内から適切な語を選びなさい。\\nThis is one of the (biggest / bigger) cities (of / in) Japan.\\n\\n【解答】biggest / in\\n【解説】「one of the 最上級 ＋ 複数名詞」の形。cities は複数形。Japanのような1つの場所・国には in を使う。\\n\\n★ 入試対策ポイント：\\n■ 1音節→-er/-est、3音節以上→more/most、2音節は語によって異なる\\n■ of ＋ 複数（3つ以上・all）、in ＋ 単数の場所・集団\\n■ as 〜 as の間は原級（元の形）を使う\\n■ not as A as B ＝ B is 比較級 than A（書きかえ頻出）\"},{\"heading\":\"★ MAXレベル：比較の応用表現と紛らわしい語\",\"body\":\"■ 「他のどの〜よりも〜」構文（最上級の言いかえ・入試頻出）\\n比較級を使って最上級と同じ意味を表す構文は、書きかえ問題の定番。\\n①最上級：Tom is the tallest boy in his class.\\n②比較級＋any other：Tom is taller than any other boy in his class.（クラスの他のどの少年よりも背が高い）\\n③比較級＋all the other：Tom is taller than all the other boys in his class.（他のすべての少年たちよりも背が高い）\\n⚠ 注意：②の any other のあとの名詞は単数形（boy）、③の all the other のあとは複数形（boys）。\\n\\n■ elder / eldest と older / oldest\\n・elder / eldest：主に家族間の「年上・年長」を表すフォーマルな語（限定用法のみ、比較のasやthanは使わない）\\n例）my elder brother（私の兄）／ the eldest son（長男）\\n・older / oldest：一般的な「年上・古い」を表す（家族にも物にも使える）\\n例）He is older than me.（彼は私より年上だ）\\n★ 入試では基本的にolder/oldestを使えば問題ない。elder/eldestは限定的な使い方として知っておく程度でよい。\\n\\n■ farther と further の使い分け\\n・farther：物理的な距離が「もっと遠い」\\n例）My house is farther from the station than yours.（私の家は駅からあなたの家より遠い）\\n・further：程度・話の内容が「さらなる」（距離以外）\\n例）I need further information.（さらなる情報が必要だ）\\n⚠ 入試では距離ならfarther、それ以外（詳しさ・程度）ならfurtherと覚えておくと安全。\\n\\n■ later / latter、last / latest の紛らわしいペア\\n・later（あとで、時間的にあと）／ latter（後者の）\\n　例）I'll call you later.（あとで電話するね）／ the latter half（後半）\\n・last（最後の・この前の）／ latest（最新の）\\n　例）the last train（最終電車）／ the latest news（最新のニュース）\\n\\n■ 比較を使った婉曲表現（大人っぽい丁寧な言い方・上級）\\n・I'd rather ＋ 動詞の原形：どちらかと言えば〜したい\\n例）I'd rather stay home today.（今日はどちらかと言えば家にいたい）\\n・prefer A to B：BよりAのほうを好む\\n例）I prefer tea to coffee.（コーヒーより紅茶のほうが好きだ）\\n★ prefer A to B の to は前置詞なので、あとに動詞がくるときは動名詞（-ing）にする。\\n例）I prefer reading to watching TV.（テレビを見るより読書が好きだ）\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_14_there_is_are\",\"subject\":\"eigo\",\"title\":\"There is/are構文と存在・所在表現\",\"description\":\"「〜がある・いる」を正確に表現する頻出構文を完全マスター\",\"keyPoints\":[\"There is ＋ 単数名詞／There are ＋ 複数名詞「〜がある・いる」。主語は名詞、thereは意味を持たない\",\"否定文 There isn't/aren't 〜、疑問文 Is/Are there 〜? — Yes, there is/are. No, there isn't/aren't.\",\"過去形 There was/were 〜。未来 There will be 〜\",\"There is/are のあとの名詞は「初めて話題に出す不特定のもの」。特定のもの（the/my/his等）には使わない\",\"How many 〜 are there in ...?で数をたずねる。答えはThere is/are ＋ 数\",\"There is/are ＋ 名詞 ＋ 場所を表す語句（in/on/near等）が基本の並び\",\"似た意味のhave構文との違い：所有はhave、単なる存在はthere is/are\"],\"order\":14,\"examType\":\"chugaku\",\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. There is/are の基本の形\",\"mangaId\":\"eigo_14_thereisare_manga\",\"body\":\"「〜がある」「〜がいる」と、あるものの存在を伝えるときに使う特別な構文がThere is/are構文。日本語につられて主語をまちがえやすいので、形をしっかり覚えよう。\\n\\n■ There is/are の基本形\\nThere is ＋ 単数名詞 ＋ 場所（〜に…がある／いる）\\nThere are ＋ 複数名詞 ＋ 場所（〜に…がある／いる）\\n例）There is a cat on the sofa.（ソファの上に猫が1匹いる）\\n例）There are three books on the desk.（机の上に本が3冊ある）\\n★ 最重要ポイント：thereは「そこに」という意味を持たない、形だけの主語（形式主語）。本当の主語は is/are のあとの名詞。だからis/areはあとの名詞の単数・複数に合わせる。\\n\\n■ なぜThereなのに意味の「そこ」ではないのか\\nThere is/are構文の there は「導入のthere」と呼ばれ、日本語には訳さない。実際の場所は文の最後（in the box, on the desk など）に置かれる。\\n例）There is a park near my house.（私の家の近くに公園がある）\\n→ There自体は訳さず、near my house（私の家の近くに）が本当の場所情報。\\n\\n■ 単数・複数の判断（is か are か）\\n名詞が2つ以上並ぶときは、いちばん近い名詞に合わせるのが基本ルール。\\n例）There is a pen and two notebooks on the desk.（近いpenが単数なのでis）\\n例）There are two notebooks and a pen on the desk.（近いnotebooksが複数なのでare）\\n★ ただし文法的には最初の名詞に合わせるという考え方もあるため、入試では「is/are どちらでも自然な例文」を使うことが多い。\\n\\n■ There is/are のあとに来る名詞の種類\\n・不可算名詞にも使える（単数扱い）\\n例）There is some water in the bottle.（ボトルの中に水がある）\\n・someやa lot ofなど数量表現とも組み合わせられる\\n例）There are a lot of students in the gym.（体育館にたくさんの生徒がいる）\",\"figureId\":\"xf_eigo_14_there_is_are\"},{\"heading\":\"2. There is/are の否定文・疑問文\",\"body\":\"There is/are構文もbe動詞の文なので、否定文・疑問文の作り方はbe動詞と同じルールに従う。\\n\\n■ 否定文：is/areのあとにnotを置く\\nThere is not（isn't）＋ 単数名詞 〜\\nThere are not（aren't）＋ 複数名詞 〜\\n例）There isn't a bank near here.（この近くに銀行はない）\\n例）There aren't any students in the classroom.（教室にはひとりも生徒がいない）\\n★ ポイント：否定文の中では、someではなくanyを使う（There aren't any 〜）。\\n\\n■ 疑問文：is/areを文の最初に出す\\nIs there ＋ 単数名詞 〜?\\nAre there ＋ 複数名詞 〜?\\n例）Is there a hospital near your house?（あなたの家の近くに病院はありますか）\\n— Yes, there is. ／ No, there isn't.\\n例）Are there any parks in this town?（この町に公園はありますか）\\n— Yes, there are. ／ No, there aren't.\\n★ ポイント：答えるときも there を使う（Yes, it is. ではなく Yes, there is.）。\\n\\n■ 疑問文の中のsome→any\\n肯定文ではsomeを使う場面でも、疑問文・否定文ではanyに変わる。\\n例）There are some apples in the fridge.（肯定：冷蔵庫にリンゴがいくつかある）\\n→ Are there any apples in the fridge?（疑問：冷蔵庫にリンゴはありますか）\\n→ There aren't any apples in the fridge.（否定：冷蔵庫にリンゴはひとつもない）\\n\\n■ There is/areが使えない場合（特定のものには使わない）\\nThere is/are構文は「初めて話題に出す、不特定のもの」に使う。すでに話題に出た特定のもの（the〜、my〜など）には使わない。\\n× There is my bag on the chair.（×）\\n○ My bag is on the chair.（○ 特定のものは主語にして be動詞で表す）\\n⚠ 注意：この使い分けは英作文・並び替え問題で頻出。「a/an/someがつくもの→There is/are」「the/my/hisなど特定→ふつうのbe動詞文」と覚える。\"},{\"heading\":\"3. There was/were（過去形）と数をたずねる表現\",\"body\":\"There is/are構文は過去形・未来形にもすることができる。時制を変えるときはbe動詞の部分だけを変化させる。\\n\\n■ There was/wereの形（過去）\\nThere was ＋ 単数名詞 〜（〜があった／いた）\\nThere were ＋ 複数名詞 〜（〜があった／いた）\\n例）There was a big tree in front of my house.（私の家の前に大きな木があった）\\n例）There were many people at the festival.（お祭りにはたくさんの人がいた）\\n\\n■ There was/wereの否定文・疑問文\\nThere wasn't/weren't 〜（〜はなかった）\\nWas/Were there 〜?（〜はありましたか）— Yes, there was/were. ／ No, there wasn't/weren't.\\n例）Was there a library in your town before?（あなたの町に前は図書館がありましたか）\\n\\n■ There will be（未来）\\n形：There will be ＋ 名詞 〜（〜があるだろう）\\n例）There will be a big event next month.（来月大きなイベントがあるだろう）\\n疑問文：Will there be 〜? — Yes, there will. ／ No, there won't.\\n\\n■ How many 〜 are there in ...?（数をたずねる重要構文）\\n「〜はいくつありますか／何人いますか」とたずねるときの決まった形。\\n形：How many ＋ 複数名詞 ＋ are there ＋ 場所 ?\\n例）How many students are there in your class?（あなたのクラスに生徒は何人いますか）\\n— There are thirty (students) (in my class).\\n例）How many books are there on the shelf?（棚に本は何冊ありますか）\\n— There are twenty.\\n★ ポイント：How manyのあとの名詞は複数形。文末はareがthereの前に来る疑問文の語順（are there）。\\n\\n■ 過去の数をたずねる場合\\nHow many people were there at the party?（パーティーには何人いましたか）\\n— There were about fifty people.\\n★ 時制（is/are/was/were）を問いと答えでそろえることを忘れずに。\"},{\"heading\":\"4. There is/are構文とhave構文の使い分け\",\"body\":\"「〜がある」という日本語は、英語では「There is/are」と「have」の2通りで表現できる場合がある。意味の違いを正しく理解しよう。\\n\\n■ There is/are：単なる存在（〜が存在する）\\n場所を主語にしない、客観的な存在を伝える表現。\\n例）There is a park near my house.（私の家の近くに公園がある）\\n例）There are four seasons in Japan.（日本には四季がある）\\n\\n■ have：所有・所属（〜を持っている）\\n主語（人やもの）が「持っている」という関係を表す。\\n例）I have a bike.（私は自転車を持っている）\\n例）This house has three bedrooms.（この家には3つの寝室がある）\\n★ ポイント：have構文では「持ち主」が主語になる。There is/are構文では場所が文末に来て、存在するものが主語（is/areのあと）になる。\\n\\n■ 同じ内容を2通りで言いかえる練習（入試頻出）\\n①There are three rooms in this house.（この家には3つの部屋がある）\\n②This house has three rooms.（この家は3つの部屋を持っている）\\n→ ①は「部屋の存在」に焦点、②は「家という主語」に焦点を当てた言い方。どちらも同じ状況を表せる。\\n\\n■ There is/are ＋ 人（存在を表す場合）\\n人の存在を表すときにもThere is/areは使える。ただし特定の人（Tom等の固有名詞）には使わない。\\n例）There is a woman at the door.（ドアのところに女の人がいる）\\n× There is Tom in the room.（×固有名詞には使わない）\\n○ Tom is in the room.（○）\\n\\n■ There is/are ＋ something/nothing/anything（不定代名詞との組み合わせ）\\n例）There is something wrong with this computer.（このパソコンはどこかおかしい）\\n例）There is nothing in the box.（箱の中には何もない）\\n★ something/nothingを修飾する形容詞は後ろに置く（something wrong、nothing specialの語順）点に注意。\"},{\"heading\":\"5. 入試例題（There is/are構文）\",\"body\":\"以下の問題でThere is/are構文の理解を確認しよう。\\n\\n【問題1】（　）内から適切な語を選びなさい。\\nThere (   ) a lot of books on the shelf.\\na) is  b) are\\n\\n【解答】b) are\\n【解説】主語（books）が複数なのでareを使う。There is/areのあとの名詞の数に合わせるのが原則。\\n\\n【問題2】次の文を否定文にしなさい。\\nThere are some students in the library.\\n\\n【解答】There aren't any students in the library.\\n【解説】否定文ではsomeがanyに変わる。areにnotをつけてaren'tにする。\\n\\n【問題3】次の文を疑問文にして、Yesで答えなさい。\\nThere is a post office near the station.\\n\\n【解答】Is there a post office near the station? — Yes, there is.\\n【解説】isを文頭に出す。答えにも there is を使う。\\n\\n【問題4】次の日本語を英語にしなさい。\\n「あなたのクラスには何人の生徒がいますか。」\\n\\n【解答例】How many students are there in your class?\\n【解説】How many ＋ 複数名詞 ＋ are there ＋ 場所、の決まった語順。studentsを忘れずに複数形にする。\\n\\n【問題5】まちがいを直しなさい。\\nThere is my pen on the table.\\n\\n【解答】My pen is on the table.\\n【解説】「my（特定のもの）」にはThere is/are構文を使わない。特定のものは主語にしてふつうのbe動詞文にする。\\n\\n★ 入試対策ポイント：\\n■ There is/areのあとの名詞の数（単数/複数）でis/areを決める\\n■ 疑問文・否定文ではsome→anyに変わる\\n■ How many 〜 are there in...?で数をたずねる\\n■ 特定のもの（the/my/his等）にはThere is/areを使わない\"},{\"heading\":\"★ MAXレベル：There構文の応用表現\",\"body\":\"■ There seems/appears to be 〜（〜があるようだ）\\nThere is/are構文にseem/appearを組み合わせた発展形。「〜があるようだ・見えるようだ」という推量を表す。\\n例）There seems to be a mistake in this sentence.（この文には間違いがあるようだ）\\n例）There appeared to be no one in the house.（その家には誰もいないようだった）\\n★ ポイント：There is/are の is/are の部分が「seems/appears to be」に置きかわる形。\\n\\n■ There used to be 〜（以前は〜があった、今はない）\\n過去にあったが今はない、という対比を表す重要表現。\\n例）There used to be a big tree here.（ここには昔大きな木があった＝今はない）\\n例）There used to be a small shop on this corner.（この角には昔小さな店があった）\\n⚠ 注意：There was 〜（単に過去にあった）と There used to be 〜（今はないという対比の含み）のニュアンスの違いに注意。\\n\\n■ There is no 〜ing（〜することはできない）※慣用表現\\n「There is no ＋ 動名詞」で「〜することは不可能だ」という意味になる、やや発展的な表現。\\n例）There is no telling what will happen.（何が起こるかわからない）\\n例）There is no denying that he is smart.（彼が賢いことは否定できない）\\n\\n■ Here is/are 〜（ここに〜がある）との比較\\nThere is/are と似た形でHere is/areがある。「ここに〜がある」と相手に何かを差し出す・紹介するときに使う。\\n例）Here is your ticket.（はい、あなたのチケットです）\\n例）Here are the results of the test.（これがテストの結果です）\\n★ ポイント：Here is/are のあとの名詞は「特定のもの」でもよい（Thereとの違い）。相手に手渡す・示すニュアンスが強い。\\n\\n■ 存在文の倒置（副詞句が前に出る発展形）\\n場所を表す副詞句を文頭に出し、動詞と主語を倒置させる文もある（There is/are構文と似た効果）。\\n例）On the hill stands an old castle.（丘の上に古いお城が立っている）\\n= There is an old castle on the hill.\\n★ この倒置は説明文・物語文でよく使われる、やや文学的な表現。読解で出会うことがある。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_15_shinkoukei\",\"subject\":\"eigo\",\"title\":\"現在進行形・過去進行形の総合演習\",\"description\":\"「〜している最中」を表す進行形を、時制・作文・会話すべての角度から固める\",\"keyPoints\":[\"現在進行形：am/is/are ＋ -ing「今〜しているところだ」。過去進行形：was/were ＋ -ing「〜していたところだった」\",\"-ingの作り方：そのまま＋ing、eをとって＋ing（make→making）、短母音+子音字は重ねて＋ing（run→running）\",\"状態動詞（like/know/have=持つ/want/love等）は原則進行形にしない\",\"否定文はbe動詞＋not＋-ing、疑問文はbe動詞を主語の前に出す\",\"whenは「〜したとき（一点）」、whileは「〜している間（継続）」。過去進行形とセットでよく使われる\",\"現在進行形は近い未来の予定を表すこともある（I'm leaving tomorrow.）\",\"now/right nowは現在進行形、at that timeやwhen〜は過去進行形のサインワード\"],\"order\":15,\"examType\":\"chugaku\",\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 現在進行形の形と意味\",\"body\":\"現在進行形は「今まさに〜しているところだ」という、一時的に進行中の動作を表す形。ふつうの現在形（習慣）との違いをはっきり区別しよう。\\n\\n■ 現在進行形の基本形\\n主語 ＋ am/is/are ＋ 動詞の-ing形 ＋ 〜\\n例）I am studying English now.（私は今英語を勉強しているところだ）\\n例）She is cooking dinner.（彼女は夕食を作っているところだ）\\n例）They are playing soccer in the park.（彼らは公園でサッカーをしているところだ）\\n\\n■ 現在形（習慣）と現在進行形（一時的な動作）の違い\\n・現在形：いつもすること・習慣・事実\\n例）I play tennis every Sunday.（毎週日曜にテニスをする＝習慣）\\n・現在進行形：今ちょうどしていること\\n例）I am playing tennis now.（今ちょうどテニスをしている＝一時的）\\n⚠ 注意：現在形と現在進行形はよく一緒に出題され、「usually/every day→現在形」「now/right now→現在進行形」という目印を見分ける問題が多い。\\n\\n■ -ing形の作り方（つづりの変化ルール）\\n①ふつうはそのまま-ingをつける：play→playing／study→studying／read→reading\\n②eで終わる語はeをとって-ing：make→making／write→writing／come→coming\\n③「短母音＋子音字」で終わる語は子音字を重ねて-ing：run→running／swim→swimming／sit→sitting／stop→stopping\\n④ieで終わる語はieをyに変えて-ing：die→dying／lie→lying／tie→tying\\n★ ポイント：②と③を混同しやすい。make(eで終わる)→making、run(短い母音+子音字1つ)→running、と語の形をよく見て判断する。\\n\\n■ 現在進行形の疑問文・否定文\\n・疑問文：Am/Is/Are ＋ 主語 ＋ -ing 〜?\\n例）Is she watching TV?（彼女はテレビを見ているところですか）— Yes, she is. ／ No, she isn't.\\n・否定文：主語 ＋ am/is/are ＋ not ＋ -ing 〜\\n例）I am not sleeping.（私は寝ていない）\\n例）They are not studying now.（彼らは今勉強していない）\",\"figureId\":\"xf_eigo_15_shinkoukei\"},{\"heading\":\"2. 進行形にしない動詞（状態動詞）\",\"mangaId\":\"eigo_15_joutaidoushi_manga\",\"body\":\"一般動詞には「動作」を表すものと「状態・気持ち」を表すものがあり、後者（状態動詞）は原則として進行形にしない。入試で頻出のひっかけポイント。\\n\\n■ 状態動詞の代表例（進行形にしない）\\n・気持ちを表す動詞：like（好き）／ love（大好き）／ want（欲しい）／ hope（望む）／ hate（嫌い）\\n・知覚・認識を表す動詞：know（知っている）／ understand（理解している）／ believe（信じている）／ remember（覚えている）\\n・所有を表す動詞：have（持っている）／ own（所有している）／ belong to（〜に属する）\\n・見た目・感覚を表す動詞：look（〜に見える）／ sound（〜に聞こえる）／ seem（〜のようだ）\\n\\n× I am liking this song.（×）\\n○ I like this song.（○ 「好き」という状態は進行形にしない）\\n× She is knowing the answer.（×）\\n○ She knows the answer.（○）\\n\\n■ 動作動詞と状態動詞、両方の意味を持つ動詞（発展）\\n一部の動詞は「動作」の意味では進行形にできる。\\n・have：「持っている」（状態、進行形不可）／「食べる・過ごす」（動作、進行形可）\\n例）I have a car.（車を持っている＝状態）\\n例）I am having lunch now.（今昼食を食べているところだ＝動作）\\n・think：「〜と思う」（状態、進行形不可）／「考え中だ」（動作、進行形可）\\n例）I think it's true.（それは本当だと思う＝意見・状態）\\n例）I am thinking about my future.（将来について考えているところだ＝思考の動作）\\n・see：「見える」（状態、進行形不可）／「（人に）会う」（動作、進行形可）\\n例）I see a bird.（鳥が見える＝視覚）\\n例）I am seeing my dentist this afternoon.（今日の午後、歯医者に会う予定だ）\\n\\n■ なぜ状態動詞は進行形にしないのか\\n進行形は「途中で始まって途中で終わる、一時的な動作」を表す形。like/know/haveのような「継続的な心の状態・持続する関係」には「途中」という概念がなじまないため、進行形にしない。\\n\\n⚠ 入試の罠：知らない単語が動詞として出てきたとき、進行形の空所で「状態動詞かどうか」を判断させる問題がよく出る。like/want/know/haveは特に頻出。\"},{\"heading\":\"3. 過去進行形（was/were + -ing）\",\"body\":\"過去進行形は「（過去のある時点で）〜していたところだった」という意味を表す。単なる過去形（〜した）との違いを意識しよう。\\n\\n■ 過去進行形の基本形\\n主語 ＋ was/were ＋ -ing ＋ 〜\\n例）I was watching TV then.（そのとき私はテレビを見ていた）\\n例）They were playing soccer at that time.（そのとき彼らはサッカーをしていた）\\n★ am/is → was、are → were と、be動詞を過去形に変えるだけでよい。\\n\\n■ 過去形と過去進行形の違い\\n・過去形：完結した動作（〜した）\\n例）I watched TV yesterday.（昨日テレビを見た＝見終わった）\\n・過去進行形：ある時点で進行中だった動作（〜していた）\\n例）I was watching TV when he came.（彼が来たとき、私はテレビを見ていた＝まだ途中だった）\\n\\n■ whenとwhileを使った過去進行形の重要構文（入試最頻出）\\n「〜していたとき、…した」という「進行中の動作」と「その途中に起きた一瞬の出来事」を組み合わせる構文。\\n形：主語A＋was/were＋-ing＋when＋主語B＋過去形（一般動詞の過去形）\\n例）I was sleeping when the phone rang.（電話が鳴ったとき、私は眠っていた）\\n例）She was cooking when I came home.（私が帰宅したとき、彼女は料理をしていた）\\n★ ポイント：when以降（一瞬の出来事）は過去形、主節（進行中だった長い動作）は過去進行形にする。\\n\\n■ whileを使った過去進行形どうしの組み合わせ\\nwhileは「〜している間」という継続を表すので、両方の節が過去進行形になることが多い。\\n例）While I was studying, my brother was playing video games.（私が勉強している間、弟はテレビゲームをしていた）\\n\\n■ 過去進行形の疑問文・否定文\\n・疑問文：Was/Were ＋ 主語 ＋ -ing 〜?\\n例）Were you sleeping at ten last night?（昨夜10時、あなたは寝ていましたか）\\n・否定文：主語 ＋ was/were ＋ not ＋ -ing\\n例）I was not（wasn't）studying then.（そのとき私は勉強していなかった）\"},{\"heading\":\"4. 進行形の応用（近い未来・時を表す語句）\",\"body\":\"進行形は「今している最中」だけでなく、いくつかの応用的な使い方がある。ここを押さえると表現の幅が広がる。\\n\\n■ 現在進行形で近い未来の予定を表す（重要な応用）\\n「be going to」と同じように、すでに決まっている近い未来の予定を現在進行形で表すことがある。\\n例）I am leaving for Tokyo tomorrow.（私は明日東京に出発する予定だ）\\n例）She is coming to the party tonight.（彼女は今夜パーティーに来る予定だ）\\n★ ポイント：go/come/leave/arriveなど「移動」を表す動詞でよく使われる。tomorrow/tonight/next weekなど未来を表す語と一緒に使われることが多い。\\n\\n■ 現在進行形とセットで使われる時を表す語\\nnow（今）／ right now（ちょうど今）／ at the moment（今のところ）／ at present（現在）\\n例）What are you doing right now?（あなたは今ちょうど何をしていますか）\\n\\n■ 過去進行形とセットで使われる時を表す語\\nthen（そのとき）／ at that time（そのとき）／ at ＋ 時刻（〜時に）／ when 〜（〜したとき）\\n例）What were you doing at seven yesterday?（昨日の7時、あなたは何をしていましたか）\\n— I was having dinner.（夕食を食べていた）\\n\\n■ 常に〜しているという不満・非難を表す進行形（発展）\\nalwaysなど頻度を表す語と現在進行形を組み合わせると、「いつも〜してばかりいる」という不満・驚きのニュアンスを表せる。\\n例）He is always losing his umbrella.（彼はいつも傘をなくしてばかりいる）\\n★ ポイント：ふつうのalways＋現在形（習慣・客観的事実）とは違い、alwaysが進行形と組み合わさると「困った様子・呆れ」を表す。中学英語では発展知識として押さえておく。\\n\\n■ 進行形の疑問詞疑問文\\nWhat/Where/Who ＋ be動詞 ＋ 主語 ＋ -ing?\\n例）What are you doing?（何をしているの）— I'm doing my homework.\\n例）Where were you going?（どこに行くところだったの）— I was going to the library.\"},{\"heading\":\"5. 入試例題（進行形）\",\"body\":\"以下の問題で進行形の理解を確認しよう。\\n\\n【問題1】（　）内から適切な語を選びなさい。\\nI ( am liking / like ) this song very much.\\n\\n【解答】like\\n【解説】likeは状態動詞なので進行形にしない。「好き」という継続的な気持ちを表すときは現在形を使う。\\n\\n【問題2】次の動詞を-ing形にしなさい。\\n① run　② make　③ study\\n\\n【解答】① running　② making　③ studying\\n【解説】①短母音＋子音字なので子音字を重ねる ②eで終わる語はeをとる ③そのまま-ingをつける。\\n\\n【問題3】（　）内から適切な語を選びなさい。\\nI ( was watching / watched ) TV when my father came home.\\n\\n【解答】was watching\\n【解説】「父が帰宅したとき（一瞬の出来事＝過去形came）」の途中で進行していた動作なので、過去進行形を使う。\\n\\n【問題4】次の文を疑問文にしなさい。\\nShe was studying math at nine last night.\\n\\n【解答】Was she studying math at nine last night?\\n【解説】be動詞（was）を主語の前に出すだけでよい。\\n\\n【問題5】次の日本語を英語にしなさい。\\n「私が電話をかけたとき、彼は宿題をしていた。」\\n\\n【解答例】He was doing his homework when I called him.\\n【解説】「〜していた（継続）」→ 過去進行形、「電話をかけた（一瞬の動作）」→ 過去形。when以降を過去形にすることを忘れずに。\\n\\n★ 入試対策ポイント：\\n■ 状態動詞（like/know/have=持つ/want）は進行形にしない\\n■ -ing形のつづり変化（子音字を重ねる／eをとる）を正確に\\n■ when＋過去形（一瞬）と過去進行形（継続中）の組み合わせが最頻出パターン\\n■ 現在進行形は近い未来の予定を表すこともある\"},{\"heading\":\"★ MAXレベル：進行形の完了形との組み合わせと受動態\",\"body\":\"■ 現在完了進行形（have/has been -ing）※発展文法\\n「（ずっと）〜し続けている」という、継続用法の現在完了をさらに強調した形。動作動詞で使われることが多い。\\n例）I have been studying English for three hours.（私は3時間ずっと英語を勉強し続けている）\\n例）It has been raining since this morning.（今朝からずっと雨が降り続いている）\\n★ ポイント：現在完了（have studied）は「継続の結果、今の状態」に焦点、現在完了進行形（have been studying）は「ずっと動作が続いていること」そのものに焦点がある。\\n\\n■ 過去完了進行形（had been -ing）※発展文法\\n過去のある時点までずっと続いていた動作を表す。\\n例）She had been waiting for two hours when the bus finally came.（バスがついに来たとき、彼女は2時間ずっと待ち続けていた）\\n\\n■ 進行形の受動態（be being + 過去分詞）※発展文法\\n「〜されているところだ」という、進行中の受け身を表す形。\\n例）The bridge is being built now.（その橋は今建設されているところだ）\\n例）My car was being repaired when I called the garage.（整備工場に電話したとき、私の車はちょうど修理されているところだった）\\n★ ポイント：ふつうの受動態（is built＝建てられている、状態）と進行形の受動態（is being built＝今まさに建てられている最中）の違いを区別する。\\n\\n■ 未来進行形（will be -ing）※発展文法\\n「（未来の）その時には〜しているだろう」という、未来のある時点で進行中の動作を予測する表現。\\n例）This time tomorrow, I will be flying to Osaka.（明日の今頃、私は大阪に向かって飛行機に乗っているだろう）\\n\\n■ 進行形が使えない場面のまとめ（総整理）\\n①状態動詞（like/know/have=持つ/want/believe）\\n②不変の真理・確定した事実（The earth goes around the sun.）\\n③一瞬で終わる動作（find/lose/break など、点のような動作は「〜し続けている」という感覚と合わないため進行形にしにくい）\\n★ ただし文脈によっては、動作動詞的に使われる場合もあるため、丸暗記だけでなく文の意味から判断する練習も大切。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_16_eiken_hyogen\",\"subject\":\"eigo\",\"title\":\"英検5級〜3級レベルの重要表現とスピーキング\",\"description\":\"英検頻出の実用表現をまとめて攻略！中学入試の会話問題にも直結\",\"keyPoints\":[\"英検5級：あいさつ・時間割・買い物など日常表現、be動詞・一般動詞の基本文\",\"英検4級：過去形・未来形・比較・不定詞・動名詞の基礎、Eメール形式の読解\",\"英検3級：受動態・現在完了・関係代名詞・間接疑問文などやや高度な文法\",\"二次試験（面接）頻出表現：Please describe A.／What do you think of 〜?／How about you?\",\"Eメール・手紙特有の書き出し・結びの表現：Thank you for your e-mail.／I'm looking forward to hearing from you.\",\"英検のライティングは意見→理由2つ→結論の型に沿って書くと高得点\",\"イラスト問題（何をしているか説明）は現在進行形が中心：One boy is running.\"],\"order\":16,\"examType\":\"chugaku\",\"studyPeriod\":\"小5後半\",\"sections\":[{\"heading\":\"1. 英検5級レベルの重要表現\",\"body\":\"英検5級は英語学習の入り口で、日常生活の基本表現が中心。中学受験の英語入試でもこのレベルの表現は前提知識として問われる。\\n\\n■ 自己紹介・日常のやりとり\\n・What's your name? — My name is 〜.（お名前は？—私の名前は〜です）\\n・How old are you? — I'm 〜 years old.（何歳？—〜歳です）\\n・Where are you from? — I'm from 〜.（出身は？—〜出身です）\\n・What time is it? — It's 〜 o'clock.（何時？—〜時です）\\n\\n■ 学校生活の表現\\n・What subject do you like? — I like 〜.（何の教科が好き？—〜が好きです）\\n・I have four classes today.（今日は4時間授業がある）\\n・It's time for lunch.（お昼の時間です）\\n\\n■ 買い物・値段の表現\\n・How much is this? — It's 〜 yen.（これはいくら？—〜円です）\\n・I'll take this one.（これをください）\\n・Can I try this on?（試着してもいいですか）\\n\\n■ 時間割・曜日の表現\\n・What do you have on Mondays?（月曜日は何がありますか）\\n・We have P.E. on Tuesdays.（火曜日には体育がある）\\n★ P.E.（Physical Education：体育）のように教科の略称も英検5級で出題される。\\n\\n■ 天気・季節の会話\\n・How's the weather today? — It's sunny (rainy/cloudy/snowy).（今日の天気は？—晴れ(雨/くもり/雪)です）\\n・What season do you like? — I like spring because I can see cherry blossoms.（どの季節が好き？—桜が見られるから春が好き）\\n\\n★ ポイント：5級は「聞かれたことに素直に答える」練習が中心。定型のQ&Aを声に出して覚えると得点が安定する。\",\"figureId\":\"xf_eigo_16_eiken_hyogen\"},{\"heading\":\"2. 英検4級レベルの重要表現\",\"body\":\"英検4級では過去形・未来形・比較・不定詞など、中学1〜2年で習う文法を使った少し複雑な表現が加わる。\\n\\n■ 過去の出来事を話す表現\\n・What did you do last weekend? — I went to the zoo.（先週末何をした？—動物園に行った）\\n・I was busy yesterday.（昨日は忙しかった）\\n・Did you enjoy the trip? — Yes, I did. / No, I didn't.（旅行は楽しかった？—はい／いいえ）\\n\\n■ 未来の予定を話す表現\\n・What are you going to do this weekend?（今週末何をする予定？）\\n・I'm going to visit my grandmother.（祖母を訪ねる予定だ）\\n・I will call you later.（あとで電話するね）\\n\\n■ 比較を使った会話\\n・Which do you like better, dogs or cats?（犬と猫、どちらが好き？）\\n・This is the biggest cake in the shop.（これは店でいちばん大きいケーキだ）\\n\\n■ 依頼・提案の表現（4級頻出）\\n・Could you help me with my homework?（宿題を手伝ってもらえますか）\\n・Why don't we go to the park?（公園に行きませんか）\\n・Let's have lunch together.（一緒に昼食を食べましょう）\\n\\n■ Eメール形式の読解問題でよく使う表現\\n英検3級・4級では「Eメールを読んで答える」問題形式がある。頻出のフレーズを覚えておく。\\n・Thank you for your e-mail.（メールをありがとう）\\n・I'm writing to tell you about 〜.（〜についてお知らせするために書いています）\\n・I'm looking forward to seeing you.（会えるのを楽しみにしています）\\n・Please write back soon.（早めに返信してください）\\n・Best wishes, / Sincerely,（結びの言葉：敬具にあたる表現）\\n\\n★ ポイント：Eメール文は「用件→詳細→締めのあいさつ」という決まった構成をとることが多い。構成のパターンを知っていると内容が予測しやすくなる。\"},{\"heading\":\"3. 英検3級レベルの重要表現\",\"body\":\"英検3級では受動態・現在完了・関係代名詞・間接疑問文など、中学3年レベルの文法を使った複雑な表現が問われる。難関中学の英語入試でもこのレベルの読解・作文が出題される。\\n\\n■ 受動態を使った表現\\n・This temple was built about 500 years ago.（この寺は約500年前に建てられた）\\n・English is spoken in many countries.（英語は多くの国で話されている）\\n\\n■ 現在完了を使った表現\\n・I have never been to Okinawa.（私は一度も沖縄に行ったことがない）\\n・Have you finished your homework yet?（もう宿題は終わりましたか）\\n・I have lived in this town for ten years.（この町に10年間住んでいる）\\n\\n■ 関係代名詞を使った表現\\n・The book that I bought yesterday is very interesting.（昨日買った本はとても面白い）\\n・I have a friend who can speak three languages.（3か国語を話せる友達がいる）\\n\\n■ 間接疑問文を使った表現\\n・Do you know what time the train leaves?（電車が何時に出るか知っていますか）\\n・I'm not sure how to get to the museum.（博物館への行き方がよくわからない）\\n\\n■ 意見・提案を述べる表現（3級ライティング頻出）\\n・I think (that) 〜 because 〜.（〜だと思う、なぜなら〜だから）\\n・In my opinion, 〜.（私の意見では〜）\\n・It is important for us to 〜.（私たちが〜することは重要だ）\\n・I agree/disagree with this idea.（この意見に賛成/反対だ）\\n\\n■ 電話・道案内・買い物での応用会話\\n・May I speak to Mr. Smith, please?（スミスさんをお願いできますか）\\n・Could you tell me how to get to the station?（駅への行き方を教えていただけますか）\\n・Excuse me, but is this seat taken?（すみません、この席は空いていますか）\\n\\n★ ポイント：3級レベルは「複数の文法を組み合わせて長い文を作る」練習が中心。中学受験の記述式英作文にも直結する。\"},{\"heading\":\"4. 面接（スピーキング）とライティングの型\",\"body\":\"英検の二次試験（面接）やライティング問題には、決まった「型」がある。型を知っていれば初見の問題にも対応できる。\\n\\n■ 面接（スピーキング）でよく聞かれる質問パターン\\n・Please describe the picture.（絵の内容を説明してください）\\n　→ One boy is reading a book. A girl is playing the piano.（現在進行形で描写するのが基本）\\n・What do you usually do on weekends?（週末は普段何をしますか）\\n　→ I usually 〜.（現在形で習慣を答える）\\n・Do you like 〜? Why or why not?（〜は好きですか。その理由は？）\\n　→ Yes, I do. I like it because 〜.（理由をbecauseで続ける）\\n・What do you think of 〜?（〜についてどう思いますか）\\n　→ I think 〜.（意見を述べる）\\n\\n■ イラスト描写問題のコツ（現在進行形が中心）\\n面接のイラスト問題では、絵の中の人物が「今何をしているか」を説明する。\\n例）A man is walking his dog.（男性が犬を散歩させている）\\n例）Two girls are talking near the bench.（2人の女の子がベンチの近くで話している）\\n★ ポイント：現在の状態や1回きりの動作を描写するので、be動詞＋-ingの現在進行形を使うのが基本。\\n\\n■ ライティング（意見文）の型\\n英検のライティングは「意見→理由2つ→結論」の3段構成が基本の型。\\n①I think (that) 〜.（意見を述べる）\\n②First, 〜. Second, 〜.（理由を2つ挙げる）\\n③For example, 〜.（具体例があるとより説得力が増す）\\n④結論を繰り返す、またはIn conclusion, 〜.でまとめる（省略可の級もある）\\n\\n例）Question: Do you like studying English?\\nAnswer: I think studying English is important. First, I can talk with people from other countries. Second, I can enjoy watching English movies without subtitles. For these reasons, I like studying English.\\n\\n■ 単語数・時間配分の目安\\n・英検5級：筆記（語句補充・会話・語句整序）とリスニングが中心で、ライティング（英作文）は出ない\\n・英検4級：ライティング（英作文）は出ない（筆記とリスニングのみ）\\n・英検3級：2024年度から2問。Eメールへの返信（15〜25語）と、意見論述（25〜35語、理由は2つ挙げるのが基本）\\n\\n★ 型を覚えておけば、どんなお題が出ても「意見→理由→（具体例）→結論」の流れに当てはめて書ける。\",\"mangaId\":\"eigo_16_eiken_hyogen_xm\"},{\"heading\":\"5. 練習問題（英検スタイル）\",\"body\":\"英検スタイルの問題形式で理解を確認しよう。\\n\\n【問題1】次の会話の（　　）に入る最も適切な文を選びなさい。（5級レベル）\\nA: What time is it now?\\nB: (　　)\\n\\na) It's Monday.\\nb) It's sunny.\\nc) It's seven thirty.\\nd) It's my favorite.\\n\\n【解答】c)\\n【解説】「今何時ですか」という時刻をたずねる質問には、時刻で答える。\\n\\n【問題2】次のEメールの一部を読んで、その意味に最も近いものを選びなさい。（4級レベル）\\n\\\"I'm looking forward to seeing you next month.\\\"\\na) 私はあなたに会うのが心配だ\\nb) 私はあなたに会うのを楽しみにしている\\nc) 私はあなたにもう会った\\nd) 私はあなたに会えない\\n\\n【解答】b)\\n【解説】look forward to -ing「〜を楽しみにする」の重要熟語。\\n\\n【問題3】面接のイラスト描写問題として、次の状況を英語で説明しなさい。\\n「1人の男の子が公園でボールを蹴っている。」\\n\\n【解答例】A boy is kicking a ball in the park.\\n【解説】絵の中の「今行われている動作」なので現在進行形（is kicking）を使う。\\n\\n【問題4】次の意見文の（　）に入る適切なつなぎ言葉を答えなさい。（3級ライティング）\\nI like reading books. (   ), I can learn new things. (   ), I can relax while reading.\\n\\n【解答】First / Second\\n【解説】理由を2つ挙げるライティングの型。First〜Second〜の順番で理由を並べる。\\n\\n★ まとめ：\\n■ 5級は日常会話の即答練習、4級はEメール・過去未来・比較の応用\\n■ 3級は受動態・現在完了・関係代名詞を使った複雑な文\\n■ 面接のイラスト描写は現在進行形が基本\\n■ ライティングは「意見→理由2つ→結論」の型で書く\"},{\"heading\":\"★ MAXレベル：準2級レベルへの橋渡しと語彙戦略\",\"body\":\"■ 準2級レベルで求められる語彙・文法への橋渡し\\n難関中学の英語入試や、英検準2級（高校レベル）へのステップとして、以下のような表現も知っておくとよい。\\n・It is said that 〜.（〜と言われている）\\n例）It is said that this custom is very old.（この習慣はとても古いと言われている）\\n・Not only A but also B（AだけでなくBも）\\n例）She is not only kind but also smart.（彼女は親切なだけでなく賢い）\\n・as long as 〜（〜する限りは）\\n例）You can stay here as long as you like.（好きなだけここにいてよい）\\n\\n■ 単語を「カテゴリー」で覚える戦略（英検・入試共通で効率的）\\n英検の語彙問題は「テーマごとにまとまった単語」が出やすい。カテゴリー学習が効果的。\\n・環境：environment, pollution, recycle, resource\\n・健康：health, exercise, diet, medicine\\n・技術：technology, invention, device, application\\n・国際：culture, custom, tradition, overseas\\n\\n■ ライティング・面接で「理由が思いつかない」ときの型（実戦テクニック）\\n理由を思いつかないときは、以下の3パターンのどれかに当てはめると書きやすい。\\n①時間・お金の節約になる（It saves time/money.）\\n②健康・環境に良い（It is good for our health/the environment.）\\n③新しいことを学べる・視野が広がる（I can learn new things.）\\n★ このパターンを知っておくと、初見のお題でも「型に当てはめて理由を作る」ことができる。\\n\\n■ 英検と中学入試英語の関係\\n中学入試で英語を課す学校の多くは「英検3級〜準2級程度」を出題の目安としている。英検の過去問演習は、そのまま中学入試英語の対策になる。\\n★ ポイント：英検の級を取得すること自体が、面接で「英語力の証明」として評価される学校もある（英検資格による加点・優遇措置）。志望校の入試要項を早めに確認しておこう。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_17_gojun_ouyou\",\"subject\":\"eigo\",\"title\":\"英文の語順の応用（強調構文・倒置・省略）\",\"description\":\"並び替え問題で差がつく！ふつうの語順から外れる特殊構文を攻略\",\"keyPoints\":[\"否定語（never/little/hardly等）が文頭に出ると主語と（助）動詞が倒置する（Never have I seen 〜）\",\"場所・方向を表す副詞句が文頭に出ると倒置することがある（Here comes the bus.）\",\"It is 〜 that ...の強調構文：It とthatの間に強調したい語句を入れる\",\"so/neither＋（助）動詞＋主語「〜もそうだ／〜もそうではない」の倒置\",\"等位接続詞でつながれた文では、共通する主語・動詞・助動詞を省略できる\",\"andの前にコンマを打つ場合とbutで対比を作る場合の語順パターンを区別する\",\"疑問文の語順を使わない感嘆文（What/How〜!）は倒置とセットで整序問題に出やすい\"],\"order\":17,\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"sections\":[{\"heading\":\"1. 強調構文（It is 〜 that ...）\",\"body\":\"文の中の特定の語句を強く伝えたいとき、英語には「It is 〜 that ...」という特別な構文がある。並び替え問題・書きかえ問題で頻出。\\n\\n■ 強調構文の基本の形\\nIt is（was）＋ 強調したい語句 ＋ that ＋ 残りの部分\\n例）Tom broke the window yesterday.（トムが昨日窓を割った）\\n→ It was Tom that broke the window yesterday.（窓を割ったのはトムだった＝Tomを強調）\\n→ It was the window that Tom broke yesterday.（トムが割ったのは窓だった＝the windowを強調）\\n→ It was yesterday that Tom broke the window.（トムが窓を割ったのは昨日だった＝yesterdayを強調）\\n\\n■ 強調構文の作り方の手順\\n①強調したい語句を見つける\\n②It is（過去の文なら was）を文頭に置く\\n③強調したい語句を続ける\\n④that以降に残りの部分を置く（強調した語句だけ抜けた形になる）\\n\\n■ 強調構文で強調できる語句\\n主語・目的語・時や場所を表す語句など、名詞的・副詞的な要素は強調できる。\\n★ 注意：動詞そのものは強調構文で直接強調できない（そのかわりdo/does/didを使って動詞を強調する方法がある：I did finish my homework.のように）。\\n\\n■ It is 〜 who ...（人を強調するとき）\\n強調する語句が「人」の場合、thatの代わりにwhoを使うこともできる（thatも可）。\\n例）It was Ken who（that）called me last night.（昨夜私に電話したのはケンだった）\\n\\n■ 強調構文と形式主語のitとの見分け方\\n形式主語のIt（It is important to study.のような文）と強調構文のItを混同しないよう注意。\\n見分け方：強調構文はIt is/was と that を取りのぞいて「〜」をもとの位置にもどすと、意味の通る完全な文になる。\\n例）It was Tom that broke the window. → Tom broke the window.（意味が通る＝強調構文）\\n例）It is important to study English. → It is を取りのぞくと「important to study English」となり、文として成り立たない（形式主語構文）。\",\"figureId\":\"xf_eigo_17_gojun_ouyou\"},{\"heading\":\"2. 否定語による倒置（Never have I seen 〜）\",\"body\":\"否定的な意味を持つ語句（never/little/hardlyなど）を強調のために文頭に置くと、あとの主語と（助）動詞の順番が入れかわる（倒置）。難関校の並び替え問題で頻出。\\n\\n■ 倒置の基本ルール\\n否定語句を文頭に置くと、疑問文と同じ語順（助動詞＋主語）になる。\\n例）I have never seen such a beautiful sunset.（ふつうの語順）\\n→ Never have I seen such a beautiful sunset.（否定語Neverを強調で前に出し、倒置）\\n\\n■ 倒置を起こす代表的な否定語句\\n・never（決して〜ない）\\n例）Never have I been so happy.（これほど幸せだったことは一度もない）\\n・little（ほとんど〜ない）\\n例）Little did she know that he was lying.（彼が嘘をついているとは彼女はほとんど知らなかった）\\n・hardly / rarely / seldom（めったに〜ない）\\n例）Rarely does he make a mistake.（彼はめったに間違えない）\\n・not until 〜（〜して初めて）\\n例）Not until I met her did I understand true kindness.（彼女に出会って初めて本当の優しさを理解した）\\n\\n■ 倒置が起きるときの動詞の形の作り方（一般動詞の場合）\\n一般動詞の文を倒置するときは、疑問文と同じようにdo/does/didを使う。\\n例）She rarely goes out at night.（ふつうの語順）\\n→ Rarely does she go out at night.（rarelyを前に出し、doesを使って倒置）\\n★ ポイント：be動詞や助動詞（have/canなど）がある文はそれをそのまま前に出す。一般動詞のみの文はdo/does/didを補う。\\n\\n■ 倒置が中学英語で問われる場面\\n中学レベルでは「読解の中で出てきた倒置文を正しく理解できるか」が中心。並び替え・作文で自分から倒置文を作らせる問題は難関校のみでまれに出題される程度。まずは読んで意味がわかることを目標にしよう。\"},{\"heading\":\"3. so/neitherを使った同意の倒置とHere/There構文\",\"body\":\"会話でよく使う「〜もそうです」「〜もそうではありません」という同意の表現にも、特別な語順（倒置）がある。\\n\\n■ So ＋（助）動詞 ＋ 主語（〜もそうです：肯定文への同意）\\n相手の肯定文に対して「私もそうだ」と同意するときに使う。\\n例）A: I like soccer. B: So do I.（サッカーが好きです。—私もです。）\\n例）A: She can swim well. B: So can I.（彼女は上手に泳げます。—私もです。）\\n★ ポイント：前の文の動詞に応じてdo/does/did/am/is/are/can等を使い分け、主語を続ける。\\n\\n■ Neither ＋（助）動詞 ＋ 主語（〜もそうではありません：否定文への同意）\\n相手の否定文に対して「私もそうではない」と同意するときに使う。\\n例）A: I don't like natto. B: Neither do I.（納豆が好きではありません。—私もです（好きではない）。）\\n例）A: He isn't busy today. B: Neither is she.（彼は今日忙しくありません。—彼女もそうです（忙しくない）。）\\n⚠ 注意：Neitherを使う文自体が否定の意味を持つので、動詞は否定形にしない（× Neither don't I.は誤り）。\\n\\n■ Here/Thereで始まる文の倒置（相手の注意を引く表現）\\n「ほら、〜が来た」「あそこに〜がある」というとき、Here/Thereを文頭に置いて動詞と主語を倒置させることがある。\\n例）Here comes the bus!（ほら、バスが来た！）\\n例）There goes my train!（あ、電車が行ってしまう！）\\n★ ポイント：主語が名詞（the bus, my train）のときは倒置するが、主語が代名詞（it, he等）のときは倒置しない。\\n例）Here it comes!（それが来た！）※代名詞のときは倒置しない語順\\n\\n■ 練習：会話での同意表現の使い分け\\nA: I have already finished my homework.\\nB: So have I.（私も終えました）\\nA: I can't speak French.\\nB: Neither can I.（私も話せません）\\n★ 会話文読解・面接練習でも頻出の重要パターン。\",\"mangaId\":\"eigo_17_gojun_ouyou_xm\"},{\"heading\":\"4. 省略構文と接続詞による語順パターン\",\"body\":\"英語では、繰り返しを避けるために共通する部分（主語・動詞・助動詞）を省略することがよくある。この省略のルールを知っていると並び替え・読解がぐっと楽になる。\\n\\n■ 等位接続詞（and/but/or）による共通要素の省略\\n同じ主語・動詞が繰り返されるとき、2つ目以降を省略できる。\\n例）I like tennis, and I like soccer, too.\\n→ I like tennis and soccer.（重複する I like を省略）\\n例）She can sing well, and she can dance well, too.\\n→ She can sing and dance well.（重複する she can を省略）\\n\\n■ 比較文での省略（as 〜 as / than のあとの省略）\\n比較の文では、比較対象の重複部分がよく省略される。\\n例）Tom is taller than Ken is.（もとの完全な文）\\n→ Tom is taller than Ken.（重複する is を省略）\\n\\n■ 従属節での主語＋be動詞の省略（分詞構文的な省略）\\n接続詞（when/while/if/although等）の後ろで、主節と主語が同じ場合、「主語＋be動詞」が省略されることがある。\\n例）When I was young, I lived in Osaka.\\n→ When young, I lived in Osaka.（When I wasが省略され、youngだけが残る）\\n例）While I was walking to school, I met my teacher.\\n→ While walking to school, I met my teacher.（I was が省略され、walking が残る）\\n⚠ 注意：この省略は主節と従属節の主語が同じときだけ可能。\\n\\n■ 不定詞・動名詞の意味上の主語の省略\\n文の主語と同じ場合、to不定詞・動名詞の「〜する人」は省略される。\\n例）I want to go there.（私が行きたい＝Iとto goの主語が同じなので明示しない）\\n例）Playing soccer is fun for me.（私にとってサッカーをすることが楽しい）\\n\\n■ 会話での省略（口語表現）\\n・(Do you) Want some coffee?（コーヒーいる？）※カジュアルな会話でDo you等が省略されることがある\\n・(I) See you.（またね）\\n★ 読解・リスニングでは省略された部分を補って理解する練習が大切。\"},{\"heading\":\"5. 入試例題（強調構文・倒置・省略）\",\"body\":\"以下の問題で応用的な語順の理解を確認しよう。\\n\\n【問題1】次の文の下線部を強調する文に書きかえなさい。\\nKen found the key under the sofa.（下線部：Ken）\\n\\n【解答】It was Ken that（who）found the key under the sofa.\\n【解説】強調したい語句（Ken）をIt was 〜 thatではさむ。人を強調するのでwhoも使える。\\n\\n【問題2】次の会話の（　）に適切な語を入れなさい。\\nA: I have never been to Australia.\\nB: (   ) have I.\\n\\n【解答】Neither\\n【解説】相手の否定文（never been）に対して「私も〜ない」と同意するので、Neitherを使った倒置表現。\\n\\n【問題3】次の並び替え問題を完成させなさい。（すべての語を使う）\\n（seen / never / I / such / beautiful / a / view / have）\\n\\n【解答】Never have I seen such a beautiful view.\\n【解説】否定語Neverを文頭に出すと、あとは疑問文と同じ語順（助動詞have＋主語I）になる。\\n\\n【問題4】次の2つの文を1つにまとめなさい。\\nShe can sing well. She can dance well.\\n\\n【解答例】She can sing and dance well.\\n【解説】共通する主語（she）と助動詞（can）を省略し、動詞をandでつなぐ。\\n\\n★ 入試対策ポイント：\\n■ 強調構文：It is/was と that を取りのぞいても文が成立するかで見分ける\\n■ 否定語（never/little/hardly）が文頭→倒置（助動詞＋主語）\\n■ So/Neither＋（助）動詞＋主語で「〜もそうです／そうではない」\\n■ 等位接続詞・比較文・従属節では共通部分が省略されることが多い\"},{\"heading\":\"★ MAXレベル：仮定法の倒置と強調のdo\",\"body\":\"■ 仮定法のIfの省略と倒置（発展）\\n仮定法の文でIfを省略すると、あとの主語と（助）動詞が倒置する、というやや高度な書きかえパターン。難関校の読解で出会うことがある。\\n・If I were you, I would not do that.\\n→ Were I you, I would not do that.（Ifを省略し、wereを主語の前に倒置）\\n・If it should rain tomorrow, we will cancel the picnic.\\n→ Should it rain tomorrow, we will cancel the picnic.（Ifを省略し、shouldを前に倒置）\\n・If I had known the truth, I would have told you.\\n→ Had I known the truth, I would have told you.（Ifを省略し、hadを前に倒置）\\n★ ポイント：この倒置形はフォーマルな文章（説明文・契約書・古い物語文など）でよく使われる。中学英語では「読んで理解できる」ことが目標。\\n\\n■ 動詞を強調するdo/does/did（強調のdo）\\n「本当に〜する」と動詞そのものを強調したいときは、動詞の前にdo/does/didを置く（肯定文なのにdoを使う特殊な形）。\\n例）I do like this song.（私は本当にこの歌が好きだ）\\n例）She does study hard.（彼女は本当に一生懸命勉強する）\\n例）He did finish his homework.（彼は本当に宿題を終えたのだ）\\n★ ポイント：このdoのあとの動詞は必ず原形（三単現のsをつけない）。didのあとも原形。\\n\\n■ 感嘆文の倒置しない語順（改めて整理）\\n感嘆文（What/How〜!）は疑問文のような形をしているが、実際には倒置しない（ふつうの文の語順のまま）という点で、他の倒置構文と対照的。\\n例）What a beautiful flower this is!（これはなんて美しい花なんだろう）※ thisが動詞isの前\\n⚠ 注意：疑問文と混同して「What a beautiful flower is this!」としないよう気をつける。並び替え問題での頻出のひっかけ。\\n\\n■ 譲歩を表すas（形容詞・副詞を強調する倒置）※超発展\\n「〜ではあるが」という譲歩を表すとき、形容詞・副詞をasの前に出す倒置がある。\\n例）Tired as she was, she kept working.（疲れてはいたが、彼女は働き続けた）\\n= Though she was tired, she kept working.\\n★ 超難関校の読解にまれに登場する形。存在だけ知っておけば十分。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_18_e_nikki_sakubun\",\"subject\":\"eigo\",\"title\":\"絵日記・自由英作文の書き方（時系列描写）\",\"description\":\"絵を見て・体験を思い出して書く！入試頻出の描写型英作文を攻略\",\"keyPoints\":[\"絵日記は過去形が基本。1日の出来事を時系列（first→then→after that→finally）で並べる\",\"複数のイラストが並ぶ問題は「登場人物が何をしているか」を1コマずつ現在形/過去形で説明する\",\"時間の順序を示す語：first/at first、then/next、after that、finally/in the end\",\"感想は最後にI was happy/tired/surprisedなど気持ちの形容詞でしめくくる\",\"語数指定がある場合は「出来事の説明」を増減して調整し、主語・動詞は削らない\",\"複数コマ描写では主語がコマごとに変わることが多いので、指示語（he/she/they）を正しく使い分ける\",\"絵日記・体験文の定番テーマ：週末の出来事、遠足・運動会、家族との時間、季節の行事\"],\"order\":18,\"examType\":\"chugaku\",\"studyPeriod\":\"小5後半\",\"sections\":[{\"heading\":\"1. 絵日記（picture diary）の基本構成\",\"body\":\"絵日記は「1枚または数枚の絵を見て、その日の出来事を英語で説明する」形式の英作文で、中学入試の英語表現問題として頻出。自由英作文（意見文）とは異なり、事実・出来事を時系列で描写する力が問われる。\\n\\n■ 絵日記の基本の流れ\\n①いつ・どこでの出来事かを示す（時・場所の設定）\\n②起きた出来事を時間の順番で説明する\\n③最後に感想（気持ち）でしめくくる\\n\\n■ 絵日記でよく使う時制\\n出来事は基本的に「過去形」で書く（すでに起きたことを説明するため）。\\n例）Last Sunday, I went to the zoo with my family.（この前の日曜日、家族と動物園に行った）\\n例）We saw many animals there.（そこでたくさんの動物を見た）\\n例）I was very happy.（とても嬉しかった）\\n★ ポイント：「絵日記＝過去形」「今している最中の描写（面接のイラスト説明）＝現在進行形」という区別を意識する。\\n\\n■ 書き出しの決まり文句\\n・Last Sunday, / Yesterday, / This morning,（この前の日曜日は／昨日は／今朝は）\\n・I went to 〜 with 〜.（〜と一緒に〜へ行った）\\n・It was a sunny day.（晴れた日だった）※天気の説明から始めるのも自然\\n\\n■ 絵日記の例（1枚の絵から）\\n【絵の内容】家族でピクニックに行き、お弁当を食べている様子\\n【英作文例】\\nLast Saturday, I went to the park with my family. We had a picnic there. My mother made rice balls, and they were delicious. We ate lunch under a big tree. It was a fun day.\\n\\n★ ポイント：「誰が・どこで・何をしたか」を具体的に書くと絵日記らしい自然な文章になる。\"},{\"heading\":\"2. 複数のイラストを時系列でつなげる書き方\",\"mangaId\":\"eigo_18_e_nikki_sakubun_manga\",\"body\":\"入試の英作文では、3〜4コマのイラストが並んでいて、それぞれの場面を順番に説明させる形式がよく出題される。時間の順序を示す語（linking words）を使いこなすことがカギ。\\n\\n■ 時間の順序を示す語（重要・丸暗記）\\n・First, / At first,（まず・最初は）\\n・Then, / Next,（それから・次に）\\n・After that,（その後）\\n・Finally, / In the end,（最後に・ついに）\\n★ この4つの語をこの順番で使うと、自然な時系列の文章になる。\\n\\n■ 複数コマの絵日記の例\\n【4コマの内容】①朝起きる ②朝食を食べる ③学校へ行く ④友達と勉強する\\n【英作文例】\\nFirst, I woke up at seven. Then, I had breakfast with my family. After that, I went to school by bike. Finally, I studied math with my friends.\\n\\n★ ポイント：First/Then/After that/Finallyを使うことで、絵を見なくても順番がわかる文章になる。\\n\\n■ 場面ごとに主語が変わる場合の描写\\nイラストの中に複数の登場人物がいて、それぞれ違う動作をしている場合は、主語ごとに文を分ける。\\n【絵の内容】男の子はサッカーをしていて、女の子は本を読んでいる\\n例）One boy is playing soccer. A girl is reading a book near him.\\n★ ポイント：「1人目はA、もう1人はB」という描写にはone 〜, another（the other）〜の表現も使える（既習の代名詞の知識を応用）。\\n\\n■ せりふ（吹き出し）がある絵の描写\\nイラストに吹き出しでせりふが書かれている場合は、間接話法（〜と言った）または直接引用で描写する。\\n例）He said, \\\"I'm hungry.\\\"（彼は「お腹が空いた」と言った）\\n例）He said that he was hungry.（彼はお腹が空いたと言った）※時制の一致に注意\",\"figureId\":\"xf_eigo_18_e_nikki_sakubun\"},{\"heading\":\"3. 感想・気持ちを表す表現とまとめ方\",\"body\":\"絵日記・体験文の最後には、出来事に対する感想（気持ち）を書くと、より自然で完成度の高い文章になる。感情を表す形容詞をストックしておこう。\\n\\n■ 気持ちを表す形容詞（絵日記の結びに使える）\\nhappy（嬉しい）／ excited（わくわくした）／ surprised（驚いた）／ tired（疲れた）\\nnervous（緊張した）／ glad（嬉しい）／ sad（悲しい）／ proud（誇らしい）\\n\\n■ 感想文の作り方（I was 〜.のパターン）\\n例）I was very happy because I could see my favorite animal.（大好きな動物を見られてとても嬉しかった）\\n例）I was tired, but it was a great day.（疲れたけど、素晴らしい一日だった）\\n★ ポイント：「感情の形容詞＋because〜（理由）」の組み合わせが定番。\\n\\n■ 「〜したいと思った」という感想の発展表現\\n体験を通して感じたことを、未来への思いとして書く発展パターン。\\n例）I want to go there again.（また行きたいと思った）\\n例）I hope to see them again someday.（いつかまた会えたらいいなと思う）\\n\\n■ 絵日記全体の完成例（時系列＋感想）\\n【設定】遠足で水族館に行った一日\\nLast Friday, our class went to the aquarium. First, we watched a dolphin show. It was amazing. Then, we had lunch together in the park. After that, we looked at many kinds of fish. Finally, we came back to school by bus. I was very tired, but I had a wonderful time.\\n\\n★ この例のように「時系列の描写（First〜Finally）」＋「感想（I was tired, but I had a wonderful time.）」の組み合わせが絵日記・体験文の完成形。\\n\\n■ 語数調整のコツ\\n・語数が足りないとき：それぞれの場面に形容詞・理由を1つ足す（It was fun. → It was really fun because I love animals.）\\n・語数が多すぎるとき：修飾語（とても・本当に等）を削る、文をシンプルにする\\n⚠ 注意：主語・動詞・時制などの骨組みは削らない。削るのは修飾語や具体的すぎる説明から。\"},{\"heading\":\"4. 定番テーマ別の表現ストック\",\"body\":\"絵日記・体験作文でよく出るテーマごとに、使える表現をあらかじめストックしておくと本番で困らない。\\n\\n■ 遠足・社会科見学\\n・go on a school trip（遠足に行く）／ visit a museum（博物館を訪れる）\\n・take pictures（写真を撮る）／ learn about 〜（〜について学ぶ）\\n例）We went on a school trip to Kyoto. We visited an old temple and took a lot of pictures.\\n\\n■ 運動会・体育祭\\n・have a sports day（運動会がある）／ run a relay race（リレーで走る）\\n・practice hard（一生懸命練習する）／ win / lose the game（試合に勝つ／負ける）\\n例）We had a sports day last month. I ran in the relay race, and our team won.\\n\\n■ 家族との時間\\n・spend time with my family（家族と時間を過ごす）／ cook dinner together（一緒に夕食を作る）\\n・go shopping（買い物に行く）／ watch a movie at home（家で映画を見る）\\n例）Last weekend, I spent time with my family. We cooked curry together and watched a movie.\\n\\n■ 季節の行事（お正月・七夕・夏祭りなど）\\n・celebrate New Year's Day（お正月を祝う）／ make a wish on Tanabata（七夕に願い事をする）\\n・enjoy fireworks（花火を楽しむ）／ wear a yukata（浴衣を着る）\\n例）On Tanabata, I wrote my wish on a piece of paper and hung it on a bamboo tree.\\n\\n■ 誕生日・記念日\\n・have a birthday party（誕生日パーティーをする）／ blow out the candles（ろうそくを吹き消す）\\n・get a present from 〜（〜からプレゼントをもらう）\\n例）It was my birthday yesterday. My friends came to my house, and we had a party.\\n\\n★ ポイント：これらの「動詞＋名詞」のセット表現をテーマごとに5〜10個ストックしておくと、どんな絵日記のお題にもすぐ対応できる。\"},{\"heading\":\"5. 入試例題（絵日記・体験作文）\",\"body\":\"以下の問題で絵日記・体験作文の書き方を確認しよう。\\n\\n【問題1】次の4つの出来事を、時間の順序を表す語を使って1つの文章にまとめなさい。\\n①7時に起きた ②朝食を食べた ③学校に行った ④友達とサッカーをした\\n\\n【解答例】First, I got up at seven. Then, I had breakfast. After that, I went to school. Finally, I played soccer with my friends.\\n【解説】First/Then/After that/Finallyの順で出来事をつなぐ。すべて過去形にそろえる。\\n\\n【問題2】次の絵の内容を英語で説明しなさい。\\n【絵の内容】女の子が図書館で本を読んでいる（現在進行形で描写）\\n\\n【解答例】A girl is reading a book in the library.\\n【解説】面接のイラスト描写と同じく、今行われている動作は現在進行形で描写する。\\n\\n【問題3】次の日本語を参考に、感想を含めた1文を英語で書きなさい。\\n「動物園に行けてとても嬉しかった。」\\n\\n【解答例】I was very happy that I could go to the zoo.（またはbecause I could go to the zoo.）\\n【解説】happy＋that/because〜で理由を続ける感想文の型。\\n\\n【問題4】次の絵日記の下線部の誤りを直しなさい。\\nYesterday, I go to the park and play with my dog.\\n\\n【解答】Yesterday, I went to the park and played with my dog.\\n【解説】Yesterday（過去を表す語）があるので、動詞は過去形（went, played）にする。\\n\\n★ 入試対策ポイント：\\n■ 絵日記は過去形が基本、面接のイラスト描写は現在進行形が基本\\n■ First/Then/After that/Finallyで時系列を明確にする\\n■ 最後に感情の形容詞＋becauseで感想をしめくくる\\n■ テーマ別の定番表現をストックしておくと本番で困らない\"},{\"heading\":\"★ MAXレベル：物語文形式の描写と会話を含む作文\",\"body\":\"■ 物語文（ストーリー）形式の英作文\\nより高度な絵日記・作文問題では、単なる出来事の羅列ではなく「物語（ストーリー）」として起承転結を意識した構成が求められることがある。\\n①導入（Introduction）：いつ・どこで・誰が\\n②展開（Development）：何が起きたか（複数の出来事）\\n③山場（Climax）：いちばん印象的な出来事・困ったこと\\n④結び（Conclusion）：どうなったか・感想\\n\\n例）\\nOne day, I went hiking with my family. (導入)\\nWe walked up the mountain for two hours. (展開)\\nSuddenly, it started to rain heavily, and we got lost. (山場)\\nFinally, a kind man showed us the way, and we got home safely. I will never forget that day. (結び)\\n\\n★ ポイント：Suddenly（突然）、However（しかし）などの語を使うと、単調な出来事の羅列から「物語らしい展開」に変わる。\\n\\n■ 会話（せりふ）を含む作文のテクニック\\n物語調の作文にせりふを入れると生き生きとした文章になる。直接話法（引用符）と間接話法（伝達）の両方を使い分けられると表現の幅が広がる。\\n例）\\\"Let's go home,\\\" my mother said.（「帰りましょう」と母は言った）\\n例）My mother said that we should go home.（母は帰るべきだと言った）\\n\\n■ 五感を使った描写（発展的な表現技法）\\n単に「楽しかった」だけでなく、見た目・音・味などの感覚を描写に加えると、文章の完成度が上がる。\\n・視覚：I saw a beautiful sunset.（美しい夕日を見た）\\n・聴覚：I heard birds singing.（鳥のさえずりが聞こえた）\\n・味覚：The cake tasted delicious.（ケーキはおいしい味がした）\\n★ 難関校の記述式英作文では、単純な事実の羅列よりも「具体的な描写」がある答案のほうが高評価を得やすい。\\n\\n■ 締めくくりの発展表現（後日談・教訓を加える）\\n・That experience taught me the importance of 〜.（その経験は私に〜の大切さを教えてくれた）\\n・Since then, I have loved 〜.（それ以来、私は〜が大好きだ）\\nこれらの表現は難関校の自由英作文で高得点を狙う際の仕上げとして使える。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_19_kaiwabun_dokkai\",\"subject\":\"eigo\",\"title\":\"会話文読解（電話・買い物・道案内の長文対話）\",\"description\":\"複数ターンの会話文を正確に読み解く！中学入試頻出の対話読解を攻略\",\"keyPoints\":[\"会話文読解は「誰が話しているか（話者）」を常に整理しながら読む\",\"空所補充問題は、空所の前後の発言との「かみ合い」（質問と答えの対応）を確認する\",\"場面（電話・買い物・道案内・レストラン）ごとに登場する決まり文句を予測しながら読む\",\"会話中の指示語（it/that/one）が何を指すかは直前の発言から探す\",\"複数空所がある問題は、確実にわかる空所から埋めて選択肢を絞り込む（消去法）\",\"会話の最後の発言に、話の結論や次の行動が書かれていることが多い\",\"イラスト・図表付きの会話文では、会話の内容と絵・表の情報を照合する問題が出やすい\"],\"order\":19,\"examType\":\"chugaku\",\"studyPeriod\":\"小6前半\",\"sections\":[{\"heading\":\"1. 会話文読解の基本の読み方\",\"body\":\"会話文読解は、AさんとBさんなど複数の話者が交互に話す形式の長文を読み、内容一致や空所補充に答える問題形式。1人の書き手による説明文とは異なる読み方のコツがある。\\n\\n■ 話者を整理しながら読む\\n会話文では「誰が何を言ったか」を混同しないことが最重要。読みながら、話者ごとに簡単なメモ（A：〜と言った、B：〜と聞いた）を取る習慣をつけよう。\\n\\n例）\\nA: Have you finished your homework?\\nB: Not yet. I'm still working on it.\\nA: Do you need any help?\\nB: Yes, please. Can you check my math problems?\\n→ A（宿題を聞く人）、B（まだ終わっていない人）と役割を整理して読む。\\n\\n■ 質問と答えの「かみ合い」を確認する\\n会話は「質問→答え」「提案→反応」のペアで進む。前の発言の種類（疑問文か、依頼か、意見か）を確認し、次の発言がそれにふさわしい内容になっているかチェックする。\\n・疑問文のあとには、その疑問詞・内容に対応する答えが来る\\n・依頼（Can you 〜?）のあとには、承諾か断りの返事が来る\\n・意見（I think 〜）のあとには、賛成か反対の反応が来る\\n\\n■ 会話の展開パターン（典型的な流れ）\\n①あいさつ・切り出し\\n②本題（質問・依頼・提案）\\n③応答・やりとりの往復\\n④結論・次の行動の確認\\n⑤締めのあいさつ\\n★ ポイント：長い会話文でも、この基本パターンに当てはめて読むと展開が予測しやすくなる。\\n\\n■ 会話文特有の口語表現に慣れる\\n説明文にはあまり出てこない口語的な表現（相づち・つなぎ言葉）も会話文読解では重要。\\n・Well, .../ Actually, ... / You know, ...（ええと・実は・ほら）\\n・I see. / That's too bad. / Sounds good.（なるほど・それは残念・いいね）\\nこれらは意味内容というより「会話のリズム」を作る言葉なので、設問の答えには直接関係しないことが多い。\"},{\"heading\":\"2. 電話の会話文読解\",\"body\":\"電話での会話には特有の決まり文句があり、これを知っていると場面がすぐにイメージできる。\\n\\n■ 電話会話の典型的な流れと表現\\n①電話を受ける：Hello, this is 〜 speaking.（もしもし、〜です）\\n②取り次ぎを頼む：May I speak to Mr. Green, please?（グリーンさんをお願いできますか）\\n③本人が出る：Speaking.（私です）\\n④不在の応答：I'm sorry, he is out now.（すみません、今外出しています）\\n⑤伝言：Can I take a message? / Can I leave a message?（伝言を承りましょうか／お伝えいただけますか）\\n⑥かけ直し：Could you ask him to call me back?（折り返し電話するよう伝えていただけますか）\\n\\n■ 電話会話文の読解例\\nTom: Hello, this is Tom. May I speak to Emma?\\nMother: I'm sorry, Tom. She's not home now. She's at the library.\\nTom: I see. Could you tell her to call me when she gets home?\\nMother: Sure, I will.\\n\\n【設問例】Why isn't Emma at home?（なぜエマは家にいないのですか）\\n【解答】She is at the library.（図書館にいるから）\\n★ ポイント：「不在の理由」は必ず本文中に明示されている。会話の流れの中で自然に答えが出てくる。\\n\\n■ 電話会話で問われやすい設問パターン\\n・待ち合わせの時間・場所（What time will they meet? / Where will they meet?）\\n・伝言の内容（What does Tom want Emma to do?）\\n・電話の目的（Why did Tom call Emma?）\\n\\n⚠ 注意：電話の会話では「相手が今どこにいるか」「何を頼まれたか」という情報が設問の中心になることが多い。読みながらこれらの情報にマークをつける習慣をつけよう。\",\"figureId\":\"xf_eigo_19_kaiwabun_dokkai\"},{\"heading\":\"3. 買い物・道案内の会話文読解\",\"body\":\"買い物と道案内は入試の会話文読解で最も頻出する2大場面。決まった展開パターンを覚えておくと圧倒的に読みやすくなる。\\n\\n■ 買い物の会話の典型的な流れ\\n①声かけ：May I help you?（いらっしゃいませ）\\n②探し物：I'm looking for a birthday present for my brother.（弟への誕生日プレゼントを探しています）\\n③提案：How about this T-shirt? It's very popular.（このTシャツはいかがですか。とても人気です）\\n④値段の確認：How much is it? — It's 2,000 yen.\\n⑤試着・検討：Can I try it on? / Do you have a bigger size?\\n⑥決定：I'll take it. / I'll think about it.（これにします／考えておきます）\\n\\n■ 買い物会話文の読解例\\nClerk: May I help you?\\nCustomer: Yes, I'm looking for shoes for my son.\\nClerk: How about these? They're very popular among children.\\nCustomer: They look nice. How much are they?\\nClerk: They're 3,000 yen.\\nCustomer: OK, I'll take them.\\n\\n【設問例】What did the customer buy?（客は何を買いましたか）\\n【解答】Shoes for his/her son.（息子のための靴）\\n★ ポイント：買い物の会話では「何を」「誰のために」「いくらで」買ったかが設問の定番。\\n\\n■ 道案内の会話の典型的な流れ\\n①声かけ：Excuse me. Could you tell me the way to the museum?（すみません、博物館への道を教えてもらえますか）\\n②道順の説明：Go straight for two blocks, and turn right at the corner.（2区画まっすぐ進んで、角を右に曲がってください）\\n③目印：You'll see it on your left, next to the post office.（左手に、郵便局の隣に見えます）\\n④時間・距離：It's about a ten-minute walk from here.（ここから歩いて約10分です）\\n⑤お礼：Thank you very much. — You're welcome.\\n\\n■ 道案内会話文の設問パターン\\n・道順を図示させる問題（地図上に経路を書く）\\n・目印になる建物を選ぶ問題（次にどの角を曲がるか）\\n・所要時間・距離を答える問題\\n\\n★ ポイント：道案内はleft/right/straight/turn/blockなど方向を表す語を正確に聞き分ける（読み取る）ことが得点のカギ。地図が併記されている場合は、会話を読みながら実際に指でなぞって確認するとよい。\"},{\"heading\":\"4. 複数空所補充・整序問題の解き方\",\"body\":\"会話文読解では、複数の空所に適切な文を選んで入れる形式（対話文完成問題）がよく出題される。効率よく解くための手順を身につけよう。\\n\\n■ 複数空所問題の解き方の手順\\n①まず選択肢をすべて目を通し、それぞれの発言の「種類」（質問・承諾・断り・提案など）を把握する\\n②文脈から確実にわかる空所から埋める（すべて悩まず、簡単なものから）\\n③埋まった空所の前後から、残りの空所も絞り込んでいく（消去法）\\n④最後に会話全体を通して読み、自然な流れになっているか確認する\\n\\n■ 例題形式（3つの空所を4つの選択肢から選ぶ）\\nA: Excuse me. ( 1 )\\nB: Sure. What do you need?\\nA: ( 2 )\\nB: They're on the second floor, next to the bookstore.\\nA: ( 3 )\\nB: You're welcome. Have a nice day.\\n\\n選択肢：\\na) Thank you very much.\\nb) Could you help me?\\nc) Where can I find children's shoes?\\nd) I'll take these, please.\\n\\n【解法】\\n【何を聞かれているか】4つの選択肢を、3つの空所 (1)(2)(3) に入れる（d は使わない）。\\n【なぜこの考え方か】会話は「質問→答え」「お願い→承諾」「お礼→You're welcome.」のように、ペアでできている。だから空所の前後の発言とペアになるものを選べば、一つに決まるからである。\\n【ステップ1】(1) の次の発言は B: Sure. What do you need?（いいですよ。何が必要ですか）。Sure は「承諾」の返事なので、直前は「お願い」のはず。b) Could you help me?（手伝ってもらえますか）が、承諾 Sure につながる。\\n【ステップ2】(2) の次の発言は B: They're on the second floor, next to the bookstore.（2階の本屋のとなりです）。「場所」を答えているので、直前は「場所をたずねる質問」のはず。c) Where can I find children's shoes?（子ども靴はどこにありますか）が合う。They're は shoes を受ける言葉で、複数形とも合う。\\n【ステップ3】(3) の次の発言は B: You're welcome.（どういたしまして）。これは「お礼」への返事なので、直前は「お礼」のはず。a) Thank you very much. が合う。\\n【ステップ4】d) I'll take these, please.（これをください）は、買う決心をしたときの言葉。場所をたずねている段階では出てこないので、使わない。\\n【答え】(1) b (2) c (3) a\\n【確かめ】通して読む。「手伝ってもらえますか→いいですよ、何が必要ですか→子ども靴はどこ？→2階です→ありがとう→どういたしまして」。一本の流れになり、不自然なところがない。\\n【よくあるまちがい】(2) に d) I'll take these, please. を入れてしまう。買い物の場面にはそれらしくても、直前の「何が必要ですか」にも、直後の「2階です」にも合わない。\\n\\n★ ポイント：それぞれの空所を「独立した1文」として考えず、前後との「対応関係」で判断する。\\n\\n■ 選択肢に含まれる紛らわしい罠\\n・場面には合っているが、直前の発言とかみ合わない選択肢（内容はそれっぽいが、疑問文に疑問文で返す等、応答としてズレている）\\n・本文中の単語を使っているが、意味的に逆の内容になっている選択肢\\n⚠ 注意：「それらしい」選択肢に飛びつかず、直前の発言と論理的につながるかを必ず確認する。\\n\\n■ 会話文の並び替え問題（文の順番を並べ替える）\\nバラバラになった会話を正しい順番に並べる問題もある。あいさつ→本題→結論という基本の流れと、代名詞（it/that）が指すものが先に出てくる必要がある、という手がかりを使って解く。\",\"mangaId\":\"eigo_19_kaiwabun_dokkai_xm\"},{\"heading\":\"5. 入試例題（会話文読解総合）\",\"body\":\"以下の会話文を読んで、問いに答えなさい。\\n\\n【会話文】\\nWaiter: Are you ready to order?\\nKate: Yes. I'd like a hamburger and a small salad, please.\\nWaiter: Would you like anything to drink?\\nKate: Yes, I'll have orange juice.\\nWaiter: Would you like some ice cream for dessert?\\nKate: No, thank you. I'm on a diet.\\nWaiter: All right. That will be 1,200 yen.\\nKate: Here you are.\\n\\n【問題1】What did Kate order?（ケイトは何を注文しましたか。すべて答えなさい）\\n【解答】A hamburger, a small salad, and orange juice.\\n【解説】注文の場面で出てきた食べ物・飲み物をすべて拾う。デザート（ice cream）は断っているので含めない。\\n\\n【問題2】Why didn't Kate order ice cream?（なぜケイトはアイスクリームを注文しなかったのですか）\\n【解答】Because she is on a diet.（ダイエット中だから）\\n【解説】\\\"I'm on a diet.\\\"が理由に対応する。\\n\\n【問題3】How much did Kate pay?（ケイトはいくら払いましたか）\\n【解答】1,200 yen.\\n【解説】\\\"That will be 1,200 yen.\\\"が金額の答え。\\n\\n【問題4】次の会話の（　　）に入る最も適切な文を選びなさい。\\nWaiter: (　　)\\nKate: Yes, I'll have orange juice.\\n\\na) Would you like anything to drink?\\nb) How much is it?\\nc) What time is it?\\nd) Where is the station?\\n\\n【解答】a)\\n【解説】Kate が飲み物を答えているので、直前の Waiter の発言は飲み物をたずねる文になる。\\n\\n★ 入試対策ポイント：\\n■ 話者を整理し、質問と答えの対応を確認しながら読む\\n■ 電話・買い物・道案内はそれぞれ決まった展開パターンがある\\n■ 複数空所問題は確実な空所から埋め、消去法で絞り込む\\n■ 会話の最後には結論・次の行動が来ることが多い\"},{\"heading\":\"★ MAXレベル：長い対話文とEメール・SNS形式の読解\",\"body\":\"■ 3人以上が登場する会話文（応用パターン）\\n難関校では、3人以上の登場人物がいる会話文が出題されることがある。誰が誰に向かって話しているかを正確に把握することがより重要になる。\\n例）\\nTom: Emma, do you know where Ken is?\\nEmma: I think he's in the library. Why?\\nTom: I need to ask him about the homework.\\nEmma: You can text him. He always checks his phone.\\n★ ポイント：3人になると「TomがEmmaに聞く」「EmmaがKenについて答える」というように、話題の中心人物（Ken）と話者（Tom・Emma）が別人になる場合がある。混同しないよう、名前に印をつけながら読む。\\n\\n■ Eメール・チャット（SNS）形式の読解\\n近年の入試では、電話や対面会話だけでなく「Eメールのやりとり」「メッセージアプリの会話」形式の読解も増えている。\\n・件名（Subject）・宛先（To/From）・日付から、まず概要を把握する\\n・Eメールは手紙よりカジュアルな書き出し・結びが使われることが多い\\n　書き出し：Hi Tom, / Hello Emma,\\n　結び：See you soon. / Take care. / Best, （名前）\\n・チャット形式は、短い文の応答が連続する（電話に近い読み方が有効）\\n\\n■ 複数の文書を組み合わせた問題（ポスター＋会話文など）\\n「イベントのポスター」や「時刻表」といった別の資料と会話文を組み合わせ、両方の情報を照合させる問題も難関校では出題される。\\n解法のポイント：\\n①まず資料（ポスター・表）のタイトル・数字を確認する\\n②会話文中で資料に言及している箇所を探す（\\\"According to the poster...\\\" 等）\\n③会話の内容と資料の情報にズレがないか照合する\\n\\n■ 話者の感情・態度を読み取る問題（発展）\\n「Aの発言から、Aはどんな気持ちだと考えられるか」という、感情を推測させる設問も上級レベルで出題される。\\n・驚き：Really? / Are you serious? / I can't believe it!\\n・喜び：That's great! / Awesome!\\n・心配：Are you OK? / That sounds worrying.\\n・不満：That's not fair. / I'm not happy about that.\\n★ ポイント：感嘆符（!）や口語的な相づちの語から、話者の感情のトーンを読み取る練習をしておくと、上級の読解問題にも対応できる。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_20_tansuu_fukusuu\",\"subject\":\"eigo\",\"title\":\"単数・複数の応用とつづり変化・集合名詞\",\"description\":\"複数形のつづりルールと、間違えやすい数の一致を総整理\",\"keyPoints\":[\"複数形の基本：語尾-s。s/x/ch/shで終わる語は-es、子音字+yはyをiにして-es、fやfeで終わる語はvesに変える\",\"不規則複数形：child→children、man→men、foot→feet、単複同形：sheep/fish/deer\",\"集合名詞：family/team/classなど、全体として単数扱いにも個々の成員として複数扱いにもなる\",\"a number of＋複数名詞は「多くの〜」で複数扱い、the number of＋複数名詞は「〜の数」で単数扱い\",\"複合名詞の複数形は通常は末尾にsをつける（girlfriends）。意味の中心が前にある語は、その語にsをつける（passers-by）\",\"複数形に見える固有名詞（United States等）や学問名（math, news）は単数扱いの不可算名詞として扱う\",\"everyone/everybody/someone等は単数扱い、その代名詞での受け方（they）は近年広く許容される\"],\"order\":20,\"examType\":\"chugaku\",\"studyPeriod\":\"小5後半\",\"sections\":[{\"heading\":\"1. 複数形の作り方（つづりの変化ルール）\",\"mangaId\":\"eigo_20_fukusuu_manga\",\"body\":\"名詞を複数形にするときのつづりの変化には、いくつかのパターンがある。ルールを整理して確実に書けるようにしよう。\\n\\n■ 基本パターン：そのまま-sをつける\\nbook → books／ pen → pens／ dog → dogs／ apple → apples\\n\\n■ -s, -x, -ch, -sh, -oで終わる語：-esをつける\\nbus → buses／ box → boxes／ watch → watches／ dish → dishes\\ntomato → tomatoes／ potato → potatoes\\n⚠ 注意：ピアノ・写真など外来語系の-oで終わる語は例外的に-sのみ：piano→pianos／ photo→photos／ radio→radios\\n\\n■ 「子音字＋y」で終わる語：yをiに変えて-esをつける\\ncity → cities／ story → stories／ baby → babies／ country → countries\\n⚠ 注意：「母音字＋y」で終わる語はそのまま-sをつける（yは変えない）：boy → boys／ day → days／ toy → toys\\n\\n■ -f, -feで終わる語：fをvに変えて-esをつける（一部例外あり）\\nleaf → leaves／ knife → knives／ life → lives／ wife → wives／ shelf → shelves\\n⚠ 注意：例外もある（そのまま-sをつける語）：roof → roofs／ belief → beliefs\\n\\n■ 発音のルール（-s/-esの読み方・発展）\\n・無声音（p, t, k, f）のあとは「ス」：cats [s]／ books [s]\\n・有声音・母音のあとは「ズ」：dogs [z]／ pens [z]\\n・s/x/ch/sh/zで終わる語のあとは「イズ」：buses [iz]／ watches [iz]\\n★ 発音のルールはリスニング・発音問題で問われることがある。目で見て覚えるだけでなく、声に出して確認しよう。\",\"figureId\":\"xf_eigo_20_tansuu_fukusuu\"},{\"heading\":\"2. 不規則複数形と単複同形\",\"body\":\"複数形の中には、上記のルールに当てはまらない「不規則な変化」をする語がある。頻出のものをまとめて覚えよう。\\n\\n■ 不規則複数形（形がまったく変わる語）\\nchild（子ども）→ children\\nman（男性）→ men／ woman（女性）→ women\\nfoot（足）→ feet／ tooth（歯）→ teeth\\nmouse（ねずみ）→ mice\\nperson（人）→ people（peopleは元々「人々」という意味で使われることが多い）\\n⚠ 注意：women の発音は「ウィミン」で、単数形womanの発音（ウーマン）と大きく異なる点に注意。\\n\\n■ 単数形と複数形が同じ形の語（単複同形）\\nsheep（羊）→ sheep／ deer（鹿）→ deer／ fish（魚）→ fish（種類を強調するときはfishes）\\nJapanese（日本人）→ Japanese／ Chinese（中国人）→ Chinese\\nseries（シリーズ）→ series／ species（種）→ species\\n例）I have two sheep.（羊を2匹飼っている）※sheepsとしない\\n例）There are many Japanese in this city.（この街には多くの日本人がいる）\\n\\n■ 常に複数形で使う名詞（対になっているもの）\\nscissors（はさみ）／ glasses（眼鏡）／ pants／ trousers（ズボン）／ jeans（ジーンズ）\\nこれらは「1つ」を表すときも複数形のまま使い、数えるときはa pair of 〜を使う。\\n例）I need a pair of scissors.（はさみが1つ必要だ）\\n例）These jeans are too small.（このジーンズは小さすぎる）※このjeansは常に複数扱い\\n\\n■ お金・単位を表す語の複数形の注意点\\n・数字＋hundred/thousand/millionは複数でもsをつけない（数を表す形容詞として使うとき）\\n例）two hundred students（200人の生徒）※ × two hundreds students\\n・ただし「of」を使って漠然とした数を表すときはhundreds of/thousands ofとsをつける\\n例）hundreds of people（何百人もの人々）\"},{\"heading\":\"3. 集合名詞と数の一致（is/are・単数複数の判断）\",\"body\":\"集合名詞（家族・チーム・クラスなど、複数の人の集まりを表す名詞）は、状況によって単数扱いにも複数扱いにもなる。この判断は入試でよく問われる。\\n\\n■ 集合名詞とは\\nfamily（家族）／ team（チーム）／ class（クラス）／ group（グループ）／ audience（観客）／ staff（職員）\\n\\n■ 単数扱い（全体を1つのまとまりとして見るとき）\\n集合体を「1つの単位」として捉えるときは単数扱い（is/wasを使う）。\\n例）My family is large.（私の家族は大人数だ＝家族という1つの単位）\\n例）Our team is the strongest in the league.（私たちのチームはリーグでいちばん強い）\\n\\n■ 複数扱い（構成する個々のメンバーに注目するとき）\\n集合体の中の「個々の人々」に注目するときは複数扱い（are/wereを使う）。\\n例）My family are all early risers.（私の家族はみんな早起きだ＝家族の1人1人に注目）\\n例）The team are wearing different color uniforms.（チームのメンバーはそれぞれ違う色のユニフォームを着ている）\\n★ ポイント：日本の中学英語では単数扱い（is）を基本として教えることが多いが、文脈で複数扱いになることも知っておくと読解で困らない。\\n\\n■ a number of と the number of の区別（最重要の紛らわしいペア）\\n・a number of ＋ 複数名詞：「多くの〜」（数量表現、意味上many に近い）→ 複数扱い（are）\\n例）A number of students are absent today.（今日は多くの生徒が休んでいる）\\n・the number of ＋ 複数名詞：「〜の数」（数そのものを主語にしている）→ 単数扱い（is）\\n例）The number of students in this school is increasing.（この学校の生徒数は増加している）\\n⚠ 注意：a number of とthe number ofは見た目が似ているが、動詞の単数・複数がまったく逆になる。入試最頻出のひっかけ。\\n\\n■ everyone/everybody/someone/somebody/each（単数扱い）\\nこれらは単数動詞で受け、後で受ける代名詞はhe/she/theyのいずれも使われる。\\n例）Everyone in this class likes music.（このクラスのみんなが音楽を好きだ）※動詞はlikes（単数扱い）\\n例）Everybody has to bring his or her（their）own lunch.（全員が自分の昼食を持ってこなければならない）\"},{\"heading\":\"4. 複合名詞・不可算名詞・固有名詞の数の扱い\",\"body\":\"複数形にするときに迷いやすい、複合名詞・不可算名詞・固有名詞のパターンを整理しよう。\\n\\n■ 複合名詞の複数形（2つ以上の語が組み合わさった名詞）\\n基本的には最後の名詞部分にsをつける。\\n例）birthday party → birthday parties／ football player → football players\\nただし、意味の中心となる名詞が最後に来ない場合は、その語にsをつける（中学レベルでは頻度は低いが読解で出会うことがある）。\\n例）passer-by（通行人）→ passers-by（中心語はpasser）\\n\\n■ 学問名・病名・ゲーム名の不可算名詞扱い（-sで終わるが単数扱い）\\n一見複数形に見えるが、実際は単数扱いの不可算名詞がある。\\n例）math（mathematics）is my favorite subject.（数学は私の好きな教科だ）\\n例）news is not always true.（ニュースが常に真実とは限らない）\\n例）physics（物理学）／ economics（経済学）はすべて単数扱い\\n\\n■ 固有名詞の単数・複数扱い\\n・国名で複数形に見えるが単数扱いのもの：the United States is 〜（アメリカ合衆国は〜）\\n・複数のTom（同じ名前の人が複数）を表すとき：There are two Toms in my class.（クラスに2人のトムがいる）※固有名詞でも複数の人を指すときは複数形にできる\\n\\n■ 不可算名詞を「数える」ときの単位（重要熟語）\\n不可算名詞は直接複数形にできないが、単位を表す語をつけて数えることができる。\\n・a piece of paper／ a sheet of paper（紙1枚）\\n・a glass of water（コップ1杯の水）／ a cup of tea（カップ1杯のお茶）\\n・a piece of advice／ a piece of information（助言・情報1つ）\\n・a loaf of bread（パン1斤）\\n複数にするときは単位のほうを複数形にする：two glasses of water、three pieces of paper\\n\\n■ 練習：不可算名詞の数え方チェック\\n× two informations（×）→ ○ two pieces of information（○）\\n× a furniture（×）→ ○ a piece of furniture（○）※furniture（家具）も不可算名詞\"},{\"heading\":\"5. 入試例題（単数・複数の総合）\",\"body\":\"以下の問題で単数・複数の理解を確認しよう。\\n\\n【問題1】次の名詞を複数形にしなさい。\\n① city　② knife　③ sheep　④ child\\n\\n【解答】① cities　② knives　③ sheep　④ children\\n【解説】①子音字+yはyをiにして-es ②fをvに変えて-es ③単複同形（変化なし）④不規則変化。\\n\\n【問題2】（　）内から適切な語を選びなさい。\\nA number of students (   ) absent today.\\na) is  b) are\\n\\n【解答】b) are\\n【解説】a number of ＋複数名詞は「多くの〜」という意味で複数扱い。\\n\\n【問題3】（　）内から適切な語を選びなさい。\\nThe number of foreign visitors (   ) increasing every year.\\na) is  b) are\\n\\n【解答】a) is\\n【解説】the number of 〜は「〜の数」という単数の概念を表すので単数扱い。\\n\\n【問題4】まちがいを直しなさい。\\nCan you give me some informations?\\n\\n【解答】Can you give me some information?（またはa piece of information）\\n【解説】informationは不可算名詞なのでsをつけない。\\n\\n【問題5】次の日本語を英語にしなさい。\\n「私にコップ1杯の水をください。」\\n\\n【解答例】Please give me a glass of water.\\n【解説】不可算名詞waterを数えるときは単位（a glass of）を使う。\\n\\n★ 入試対策ポイント：\\n■ 複数形のつづり変化（-es/y→ies/f→ves）を正確に覚える\\n■ a number of（複数扱い）とthe number of（単数扱い）を混同しない\\n■ math/news/physicsなど-sで終わる不可算名詞は単数扱い\\n■ 不可算名詞は単位（piece/glass/cup）をつけて数える\"},{\"heading\":\"★ MAXレベル：数の一致の発展パターン\",\"body\":\"■ 「時間・距離・金額」のまとまりを1つの単位として扱う数の一致\\n複数形の名詞でも、1つのまとまり（金額・時間・距離）として捉えるときは単数扱いになる、という発展的なルールがある。\\n例）Ten thousand yen is not enough for this trip.（1万円ではこの旅行には足りない＝金額全体を1つの単位として）\\n例）Five years is a long time to wait.（5年は待つには長い時間だ＝期間全体を1つの単位として）\\n⚠ 注意：「10,000円」「5年」という数字は複数形の名詞（yen/years）だが、「ひとまとまりの量・期間」として捉えるときは動詞を単数形（is）にする。\\n\\n■ Both A and B（複数扱い）とEither A or B / Neither A nor B（近い方に一致）\\n・both A and B ＋ 複数扱い（and でつながるので常に複数の意味）\\n例）Both Tom and Ken are good at soccer.（トムとケンはどちらもサッカーが得意だ）\\n・either A or B / neither A nor B ＋ 動詞はBに一致させる（Bに近い方）\\n例）Either you or I am wrong.（あなたか私のどちらかが間違っている）※ Iに近いのでam\\n例）Neither he nor his friends were there.（彼も彼の友達もそこにいなかった）※friendsに近いのでwere\\n★ ポイント：「近接一致の原則」と呼ばれるルール。Bのほうの数（単数・複数）に動詞を合わせる。\\n\\n■ each of / one of ＋ 複数名詞（単数扱いになる）\\n「〜のうちの1つ・それぞれ」という意味のとき、全体の名詞が複数でも動詞は単数になる。\\n例）Each of the students has his own locker.（生徒それぞれが自分のロッカーを持っている）\\n例）One of my friends is from Canada.（私の友達の1人はカナダ出身だ）\\n⚠ 注意：of のあとの名詞（students, friends）につられて動詞を複数にしないよう注意。主語はEach/Oneであり、単数扱い。\\n\\n■ many a + 単数名詞（文語的・発展知識）\\nmanyのあとに a/an＋単数名詞を続け、動詞も単数にするという、やや古風で文学的な表現がある。\\n例）Many a student has made this mistake.（多くの生徒がこの間違いをしたことがある）\\n= Many students have made this mistake.（意味は同じ、こちらが一般的な言い方）\\n★ 中学レベルでは知識として知っておく程度でよいが、難関校の読解・長文で出会うことがある。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_21_setsuzokushi\",\"subject\":\"eigo\",\"title\":\"等位接続詞と相関接続詞（and/but/or/so, both A and B等）\",\"description\":\"文と文、語と語をつなぐ接続詞の正しい使い方を総整理\",\"keyPoints\":[\"等位接続詞 and（追加）／but（逆接）／or（選択）／so（結果）は対等な文・語句をつなぐ\",\"命令文, and 〜「そうすれば」、命令文, or 〜「さもないと」\",\"both A and B「AとBの両方」は複数扱い。either A or B「AかBのどちらか」は動詞をBに合わせる\",\"neither A nor B「AもBも〜ない」も動詞はBに合わせる。not only A but also B「AだけでなくBも」\",\"等位接続詞でつながれた語句は文法的に同じ形（品詞・時制）をそろえる（並列の原則）\",\"コンマの使い方：3つ以上を並べるときはA, B, and Cのようにコンマとandを併用\",\"so（結果、口語的）とtherefore（結果、フォーマル）、but（逆接、口語的）とhowever（逆接、フォーマル）の違い\"],\"order\":21,\"examType\":\"chugaku\",\"studyPeriod\":\"小5後半\",\"sections\":[{\"heading\":\"1. 等位接続詞 and / but / or / so の基本\",\"mangaId\":\"eigo_21_setsuzokushi_manga\",\"body\":\"接続詞には大きく「等位接続詞」と「従属接続詞」の2種類がある。ここでは文法的に対等な語句・文をつなぐ「等位接続詞」を整理する。\\n\\n■ and（そして・〜と）：追加・並列\\n語句どうし、文どうしを対等につなぐ。\\n例）I like dogs and cats.（犬と猫が好きだ）※語句をつなぐ\\n例）I did my homework, and I watched TV.（宿題をして、そしてテレビを見た）※文をつなぐ\\n★ ポイント：3つ以上並べるときは、最後の2つの前にandを置き、コンマで区切る：A, B, and C\\n例）I have a pen, a notebook, and an eraser.（ペンとノートと消しゴムを持っている）\\n\\n■ but（しかし）：逆接・対比\\n前の内容と反対・対照的な内容をつなぐ。\\n例）I like soccer, but I don't like baseball.（サッカーは好きだが、野球は好きではない）\\n例）She is small, but she is very strong.（彼女は小柄だが、とても力強い）\\n\\n■ or（または・〜か…）：選択\\n2つ以上の選択肢を示す。\\n例）Which do you like, tea or coffee?（紅茶とコーヒー、どちらが好きですか）\\n例）Hurry up, or you will miss the train.（急ぎなさい、さもないと電車に乗り遅れますよ）※命令文＋or\\n\\n■ so（だから・それで）：結果\\n前の内容の結果・結論を示す。\\n例）It was raining, so I took an umbrella.（雨が降っていたので、傘を持って行った）\\n例）I was very tired, so I went to bed early.（とても疲れていたので、早く寝た）\\n\\n■ 命令文と組み合わせる and / or（重要構文の再確認）\\n・命令文, and 〜：「〜しなさい、そうすれば…」（良い結果）\\n例）Study hard, and you will pass the exam.（一生懸命勉強しなさい、そうすれば試験に合格するだろう）\\n・命令文, or 〜：「〜しなさい、さもないと…」（悪い結果）\\n例）Get up now, or you will be late.（今起きなさい、さもないと遅刻するよ）\\n⚠ 注意：andとorを取り違えると意味がまったく逆になる。文脈から「良い結果か悪い結果か」を判断する。\"},{\"heading\":\"2. 相関接続詞 both A and B / either A or B / neither A nor B\",\"body\":\"2つの語句をペアで使う「相関接続詞（correlative conjunctions）」は、それぞれ意味と動詞の一致のルールが異なるため、正確に区別する必要がある。\\n\\n■ both A and B（AとBの両方）\\n2つとも含む、という意味。動詞は常に複数扱い。\\n例）Both Tom and Ken are good at math.（トムとケンはどちらも数学が得意だ）\\n例）I like both dogs and cats.（犬と猫の両方が好きだ）\\n\\n■ either A or B（AかBのどちらか）\\n2つのうちどちらか一方、という意味。動詞はBに一致させる（近接一致）。\\n例）Either you or I am wrong.（あなたか私のどちらかが間違っている）\\n例）Either Tom or his sisters are coming to the party.（トムか彼の姉妹たちのどちらかがパーティーに来る）\\n★ ポイント：eitherだけで「（2つのうち）どちらか」という意味の形容詞・代名詞としても使われる（Either plan is fine.）。\\n\\n■ neither A nor B（AもBも〜ない）\\n両方とも否定する、という意味。動詞はBに一致させる。\\n例）Neither Tom nor Ken likes vegetables.（トムもケンも野菜が好きではない）\\n例）Neither my brother nor I am good at cooking.（兄も私も料理が得意ではない）\\n⚠ 注意：neither A nor B自体がすでに否定の意味を持つので、動詞をさらに否定形（doesn't/isn't）にしない。\\n× Neither Tom nor Ken doesn't like vegetables.（×二重否定になってしまう）\\n\\n■ not only A but also B（AだけでなくBも）\\nBを特に強調する表現。動詞はBに一致させる。\\n例）Not only Tom but also his sisters are coming.（トムだけでなく彼の姉妹たちも来る）\\n例）She is not only kind but also smart.（彼女は親切なだけでなく賢い）\\n★ not only A but also B とほぼ同じ意味の表現：B as well as A（Bも、Aだけでなく）\\n例）His sisters as well as Tom are coming.（トムだけでなく彼の姉妹たちも来る）※こちらは動詞をB（先に来る語）に一致させる\\n\\n■ 相関接続詞の動詞の一致まとめ\\n（相関接続詞／意味／動詞の一致）\\n・both A and B … AとB両方／常に複数\\n・either A or B … AかBどちらか／Bに一致\\n・neither A nor B … AもBも〜ない／Bに一致\\n・not only A but also B … AだけでなくBも／Bに一致\",\"figureId\":\"xf_eigo_21_setsuzokushi\"},{\"heading\":\"3. 等位接続詞と並列の原則（品詞・時制をそろえる）\",\"body\":\"等位接続詞（and/but/or）でつながれる語句は、文法的に「同じ種類・同じ形」でなければならない、という重要なルールがある（並列の原則）。\\n\\n■ 品詞をそろえる\\n名詞と名詞、形容詞と形容詞、動詞と動詞のように、同じ種類の語句をつなぐ。\\n○ I like swimming and running.（動名詞どうし）\\n× I like swimming and to run.（動名詞と不定詞が混在→不自然）\\n○ She is kind and smart.（形容詞どうし）\\n\\n■ 動詞の時制をそろえる\\n過去の話をしているときは、andでつながれた動詞もすべて過去形にする。\\n例）I went to the park and played soccer.（公園に行ってサッカーをした）※went・playedどちらも過去形\\n× I went to the park and play soccer.（×時制がそろっていない）\\n\\n■ 不定詞の並列（重複するtoの省略）\\n不定詞を複数並べるときは、2つ目以降のtoを省略できる。\\n例）I want to read books and (to) study English.（本を読んで、英語を勉強したい）\\n★ ポイント：文法的には省略しても正しいが、意味を明確にしたいときはtoを繰り返してもよい。\\n\\n■ 比較・対句表現での並列\\n比較の文でも、比較する2つの要素は同じ形にそろえる。\\n○ Playing tennis is more fun than watching TV.（動名詞どうしの比較）\\n× Playing tennis is more fun than to watch TV.（×形がそろっていない）\\n\\n■ 3つ以上並べるときのコンマの使い方（オックスフォードコンマ）\\n3つ以上の語句を並べるときは、最後の2つの前にandを置き、その前にもコンマを打つのが標準的（特にアメリカ英語）。\\n例）I bought apples, oranges, and bananas.（リンゴとオレンジとバナナを買った）\\n★ 最後のコンマ（バナナの前）は「オックスフォードコンマ」と呼ばれ、省略される場合もあるが、入試では両方の形を正解として扱うことが多い。\"},{\"heading\":\"4. 会話的な接続詞とフォーマルな言いかえ\",\"body\":\"英語には「話し言葉でよく使う接続詞」と「書き言葉・フォーマルな場面で使う言いかえ表現」がある。両方を知っておくと読解の幅が広がる。\\n\\n■ so（口語） と therefore（フォーマル）：結果\\n・so：日常会話でよく使う「だから」\\n例）It was cold, so I wore a coat.（寒かったので、コートを着た）\\n・therefore：説明文やスピーチで使うフォーマルな「したがって」\\n例）The road was closed. Therefore, we had to take another route.（道路が閉鎖されていた。したがって、別の道を通らなければならなかった）\\n★ ポイント：thereforeは文頭に置かれ、コンマで区切ることが多い（接続副詞と呼ばれる）。\\n\\n■ but（口語） と however（フォーマル）：逆接\\n・but：文と文をandのように直接つなぐ（接続詞）\\n例）I like cats, but I don't like dogs.\\n・however：独立した文の最初に置いて前の文とのつながりを示す（接続副詞）\\n例）I like cats. However, I don't like dogs.\\n⚠ 注意：howeverはbutと違い、文法的には2つの文をコンマだけでつなぐことができない（howeverの前にピリオドかセミコロンが必要）。\\n× I like cats, however I don't like dogs.（口語ではよく見るが正式には誤りとされる）\\n○ I like cats. However, I don't like dogs.（○）\\n\\n■ その他の口語・フォーマルの言いかえペア\\n・and so（口語：それで）／ as a result（フォーマル：結果として）\\n・also（口語：また）／ in addition, moreover, furthermore（フォーマル：さらに）\\n・because（口語：〜だから、接続詞）／ due to, owing to（フォーマル：〜のため、前置詞＋名詞）\\n\\n■ 接続副詞（however/therefore/moreover等）の位置の自由さ\\n接続副詞は文中のいろいろな位置に置くことができる（接続詞ほど位置が固定されていない）。\\n例）However, she didn't give up.\\n例）She, however, didn't give up.\\n例）She didn't give up, however.\\n★ 読解では、howeverが文の途中に出てきても「逆接の合図」であることに気づけるようにしておこう。\"},{\"heading\":\"5. 入試例題（等位接続詞・相関接続詞）\",\"body\":\"以下の問題で接続詞の理解を確認しよう。\\n\\n【問題1】（　）内から適切な語を選びなさい。\\nBoth Tom and Ken (   ) good at soccer.\\na) is  b) are\\n\\n【解答】b) are\\n【解説】both A and Bは常に複数扱い。\\n\\n【問題2】（　）内から適切な語を選びなさい。\\nEither you or he (   ) responsible for this.\\na) am  b) is  c) are\\n\\n【解答】b) is\\n【解説】either A or Bは動詞をBに一致させる。heは三人称単数なのでis。\\n\\n【問題3】次の文の（　）に適切な接続詞を入れなさい。\\nHurry up, (   ) you will miss the bus.\\n\\n【解答】or\\n【解説】「急ぎなさい、さもないと」という悪い結果を表すのでor。andを使うと意味が逆になってしまう。\\n\\n【問題4】次の文を、not only 〜 but alsoを使って書きかえなさい。\\nShe is kind. She is smart, too.\\n\\n【解答】She is not only kind but also smart.\\n【解説】「AだけでなくBも」の構文にまとめる。\\n\\n【問題5】まちがいを直しなさい。\\nNeither Tom nor Ken doesn't like vegetables.\\n\\n【解答】Neither Tom nor Ken likes vegetables.\\n【解説】neither A nor Bですでに否定の意味を持つので、動詞をさらに否定形にしない（二重否定を避ける）。\\n\\n★ 入試対策ポイント：\\n■ both A and Bは複数扱い、either/neitherはBに動詞を一致させる\\n■ 命令文, and〜（そうすれば）／ 命令文, or〜（さもないと）を混同しない\\n■ andでつなぐ語句は品詞・時制をそろえる（並列の原則）\\n■ however/thereforeは接続副詞、文法的な使い方がbut/soとは異なる\"},{\"heading\":\"★ MAXレベル：接続詞の省略と発展的な相関表現\",\"body\":\"■ 命令文, and 〜 の発展用法（発展知識）\\nまれに、andが「そして」以上の意味（結果・条件）を持つことがある。\\n例）Study hard, and you will succeed.（一生懸命勉強しなさい、そうすれば成功する）\\n= If you study hard, you will succeed.（もし一生懸命勉強すれば）\\n★ 命令文, and〜の構文は、実質的に「If you 〜, ...」という条件文の言いかえになっていることを理解しておくと、複雑な読解にも対応できる。\\n\\n■ not A but B（AではなくB）\\nnot only 〜 but alsoと似ているが、こちらは「Aを完全に否定してBに置きかえる」という意味。\\n例）He is not a teacher but a doctor.（彼は先生ではなく医者だ）\\n例）It was not luck but hard work that made her succeed.（彼女を成功させたのは運ではなく努力だった）※強調構文との組み合わせ\\n\\n■ so that 〜（〜するために：目的）とso 〜 that ...（とても〜なので…：結果）の区別\\n似た形だが意味がまったく異なるので、入試で頻出の区別ポイント。\\n・so that ＋ S ＋ can/will/may 〜：「〜するために」（目的）\\n例）I studied hard so that I could pass the exam.（合格するために一生懸命勉強した）\\n・so ＋ 形容詞/副詞 ＋ that ...：「とても〜なので…」（結果）\\n例）I was so tired that I fell asleep.（とても疲れていたので眠ってしまった）\\n⚠ 注意：so thatの前に形容詞・副詞があるかどうかで判断する。\\n\\n■ whether A or B（AかBか）／ whether ... or not（〜かどうか）\\nor と組み合わさる従属接続詞的な表現で、名詞節を作る。\\n例）I don't know whether he will come or not.（彼が来るかどうかわからない）\\n例）Whether we win or lose, we will do our best.（勝つか負けるかにかかわらず、全力を尽くす）\\n★ ポイント：whether A or Bは「選択の不確かさ」を表す名詞節・副詞節を作る、やや発展的な構文。難関校の読解・英作文で使われることがある。\\n\\n■ 接続詞が省略される口語表現（that の省略）\\nthink/say/know などのあとのthat（〜ということ）は、口語ではよく省略される。\\n例）I think (that) he is right.（彼は正しいと思う）\\n★ すでに他単元でも触れたが、接続詞の単元としても「thatは省略可能な接続詞」として整理しておくとよい。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_22_kantanbun\",\"subject\":\"eigo\",\"title\":\"感嘆文・付加疑問文・否定疑問文の会話表現\",\"description\":\"気持ちを込めた特殊な文の形を総整理！会話文・リスニングの得点源\",\"keyPoints\":[\"感嘆文：What＋a/an＋形容詞＋名詞＋主語＋動詞！／ How＋形容詞（副詞）＋主語＋動詞！\",\"感嘆文は疑問文のように見えるが倒置しない（ふつうの文の語順のまま）\",\"付加疑問文：肯定文には否定の付加疑問、否定文には肯定の付加疑問を文末につける\",\"付加疑問文は前の文の動詞（be動詞/do・does/助動詞）を使い、主語は代名詞にする\",\"否定疑問文（Isn't it 〜? / Don't you 〜?）への答え方：内容が肯定ならYes、否定ならNo（日本語の「はい・いいえ」と逆になることがある）\",\"Yes/No疑問文と疑問詞疑問文、感嘆文の3つの文の型を語順で見分ける\",\"会話でよく使う感嘆の相づち：What a surprise! / How nice! / That's amazing!\"],\"order\":22,\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"sections\":[{\"heading\":\"1. 感嘆文（What と How）の作り方\",\"mangaId\":\"eigo_22_kantanbun_manga\",\"body\":\"「なんて〜なんだろう！」と驚き・感動を強く表す文を感嘆文という。WhatまたはHowを使って作るが、それぞれ文の形が異なるので正確に区別しよう。\\n\\n■ What を使う感嘆文（名詞を強調）\\n形：What ＋ a/an（＋形容詞）＋ 名詞 ＋ 主語 ＋ 動詞！\\n例）What a nice day it is!（なんていい天気なんだろう！）\\n例）What a beautiful flower this is!（これはなんて美しい花なんだろう！）\\n例）What an interesting book this is!（これはなんて面白い本なんだろう！）\\n★ ポイント：名詞が単数のときはa/anを忘れずにつける。名詞が複数形・不可算名詞のときはa/anをつけない。\\n例）What beautiful flowers these are!（これらはなんて美しい花なんだろう！）※複数形なのでaなし\\n例）What nice weather it is!（なんていい天気なんだろう！）※weatherは不可算名詞なのでaなし\\n\\n■ How を使う感嘆文（形容詞・副詞を強調）\\n形：How ＋ 形容詞（副詞）＋ 主語 ＋ 動詞！\\n例）How beautiful this flower is!（この花はなんて美しいんだろう！）\\n例）How fast he runs!（彼はなんて速く走るんだろう！）\\n例）How kind you are!（あなたはなんて親切なんだろう！）\\n★ ポイント：Howのあとには名詞を置かない（形容詞・副詞のみ）。名詞がある場合はWhatを使う、という使い分けが最大のポイント。\\n\\n■ WhatとHowの使い分けまとめ\\n・名詞を強調したい（〜という○○）→ What ＋（a/an）＋ 形容詞 ＋ 名詞\\n・形容詞・副詞だけを強調したい → How ＋ 形容詞/副詞\\n例）What a kind boy he is!（彼はなんて親切な少年なんだろう！）※ boyという名詞がある→What\\n例）How kind he is!（彼はなんて親切なんだろう！）※ 名詞がない→How\\n\\n■ 感嘆文の主語＋動詞の省略（会話でよく使われる形）\\n会話ではしばしば「主語＋動詞」を省略し、Whatや Howの部分だけで感嘆を表す。\\n例）What a surprise!（なんて驚きだ！）\\n例）How nice!（なんて素敵！）\\n例）How kind of you!（ご親切に！）※ how kind of 人で「〜してくれるとは親切だ」という決まった表現\"},{\"heading\":\"2. 感嘆文の語順の注意点（倒置しない）\",\"body\":\"感嘆文は疑問文と似た「What/How」で始まる形をしているが、疑問文とは違い、主語と動詞の語順を入れかえない（倒置しない）という点が最重要のポイント。\\n\\n■ 感嘆文と疑問文の語順の違い（比較）\\n・疑問文：What is this?（これは何ですか）→ be動詞（is）が主語（this）の前\\n・感嘆文：What a nice pen this is!（これはなんて素敵なペンなんだろう！）→ 主語（this）のあとに動詞（is）\\n⚠ 注意：感嘆文で疑問文のように倒置してしまうミスが非常に多い。\\n× What a nice pen is this!（×）\\n○ What a nice pen this is!（○）\\n\\n■ 「主語＋動詞」の並び方を確認する練習\\n感嘆文を作るときは、まず「ふつうの文（主語＋動詞）」を考えてから、強調したい語句をWhat/Howとともに前に出す、という手順で作ると間違えにくい。\\n①ふつうの文：This is a very nice pen.（これはとても素敵なペンだ）\\n②強調したい語句（a very nice pen）をWhatとともに前に出す：What a nice pen this is!\\n★ ふつうの文の主語・動詞の順番（this is）はそのまま保たれることを意識する。\\n\\n■ How を使う感嘆文の同様の注意点\\n①ふつうの文：He runs very fast.（彼はとても速く走る）\\n②強調したい語句（fast）をHowとともに前に出す：How fast he runs!\\n⚠ 注意：ここでも疑問文のような倒置（How fast does he run!）にしないよう気をつける。\\n\\n■ 感嘆文の書きかえ問題（入試頻出パターン）\\nveryを使ったふつうの文を感嘆文に書きかえる問題がよく出る。\\n例）This is a very interesting story.\\n→ What an interesting story this is!（Whatを使う書きかえ）\\n例）She sings very well.\\n→ How well she sings!（Howを使う書きかえ）\\n★ 手順：①veryを取り除く ②残りの形容詞・副詞の種類でWhat（名詞あり）かHow（名詞なし）かを判断する ③文頭に出して感嘆符（!）で終える\"},{\"heading\":\"3. 付加疑問文（〜だよね？と確認する）\",\"body\":\"文の最後に短い疑問をつけて、相手に確認したり同意を求めたりする表現を付加疑問文という。会話でよく使われ、リスニング・会話文読解でも頻出。\\n\\n■ 付加疑問文の基本ルール\\n①前の文が肯定文なら、付加疑問は否定形にする\\n②前の文が否定文なら、付加疑問は肯定形にする\\n③前の文の動詞（be動詞・do/does/did・助動詞）を使う\\n④主語は必ず代名詞にする\\n\\n■ be動詞の文の付加疑問\\n例）You are a student, aren't you?（あなたは生徒ですよね？）\\n例）She isn't busy, is she?（彼女は忙しくないですよね？）\\n例）It was cold yesterday, wasn't it?（昨日は寒かったですよね？）\\n\\n■ 一般動詞の文の付加疑問\\n例）He plays soccer, doesn't he?（彼はサッカーをしますよね？）\\n例）They don't like natto, do they?（彼らは納豆が好きではないですよね？）\\n例）You went to the party, didn't you?（あなたはパーティーに行きましたよね？）\\n\\n■ 助動詞の文の付加疑問\\n例）She can swim, can't she?（彼女は泳げますよね？）\\n例）You will come, won't you?（あなたは来ますよね？）\\n例）We should hurry, shouldn't we?（急いだほうがいいですよね？）\\n\\n■ 特殊な付加疑問文（形が変わるもの）\\n・I am 〜, aren't I?（私は〜ですよね？）※ am notではなくaren'tを使う特別な形\\n例）I'm right, aren't I?（私は正しいですよね？）\\n・Let's 〜, shall we?（〜しましょう、いいですよね？）\\n例）Let's go, shall we?（行きましょう、いいですよね？）\\n・命令文, will you?（〜してくれる？）\\n例）Open the door, will you?（ドアを開けてくれる？）\\n\\n■ 付加疑問文への答え方\\n付加疑問文は「たずねている内容」に対してYes/Noで答える（前の文が否定でも、答えは事実に合わせる）。\\n例）You don't like coffee, do you? — No, I don't.（コーヒーが好きじゃないですよね？—はい、好きじゃないです）\\n例）You don't like coffee, do you? — Yes, I do.（コーヒーが好きじゃないですよね？—いいえ、好きです）\\n★ ポイント：日本語の「はい・いいえ」につられず、答えの内容（好き＝Yes、嫌い＝No）で機械的に判断する。\",\"figureId\":\"xf_eigo_22_kantanbun\"},{\"heading\":\"4. 否定疑問文（〜ではないのですか？）と答え方\",\"body\":\"Isn't it 〜? / Don't you 〜? のように、not を含む疑問文を否定疑問文という。答え方が日本語の感覚と逆になることがあるため、特に注意が必要な分野。\\n\\n■ 否定疑問文の作り方\\nbe動詞・助動詞・do/does/didの短縮形（isn't/don't/doesn't/didn't等）を主語の前に置く。\\n例）Isn't this your bag?（これはあなたのかばんではないのですか）\\n例）Don't you like vegetables?（あなたは野菜が好きではないのですか）\\n例）Didn't she come to the party?（彼女はパーティーに来なかったのですか）\\n\\n■ 否定疑問文への答え方（最重要ルール）\\n英語では、答えの「内容」が肯定ならYes、否定ならNoで答える。日本語の「はい・いいえ」の感覚とズレることが多いので注意。\\n\\n例）Don't you like coffee?（コーヒーは好きではないのですか）\\n— Yes, I do.（いいえ、好きです）※内容が「好き」なのでYes\\n— No, I don't.（はい、好きではありません）※内容が「好きではない」のでNo\\n\\n★ 日本語では「はい、好きではありません」「いいえ、好きです」のように、否定の質問に対して逆の言い方をするが、英語ではあくまで「答えの内容」に忠実にYes/Noを選ぶ。\\n\\n■ 否定疑問文が使われる場面（ニュアンス）\\n・確認・驚き：Isn't it cold today?（今日は寒くないですか＝寒いと思っている）\\n・勧誘・提案：Won't you have some tea?（お茶を飲みませんか＝勧誘のニュアンス）\\n・軽い非難・意外感：Didn't you know that?（それを知らなかったのですか＝知っていると思っていた）\\n\\n■ 否定疑問文と付加疑問文の違い\\n・否定疑問文：文全体がnotを含む疑問文（Isn't this...?）\\n・付加疑問文：肯定・否定の文のあとに短い疑問をつける（This is..., isn't it?）\\n★ 意味は似ているが、形が異なる。否定疑問文は「文全体の形」、付加疑問文は「文末に追加する形」という違いを区別しておく。\"},{\"heading\":\"5. 入試例題（感嘆文・付加疑問文・否定疑問文）\",\"body\":\"以下の問題で特殊な文の形の理解を確認しよう。\\n\\n【問題1】次の文を感嘆文に書きかえなさい。\\nThis is a very difficult question.\\n\\n【解答】What a difficult question this is!\\n【解説】名詞がある（question）のでWhatを使う。veryを取り、「a difficult question」をWhatとともに前に出し、あとはthis isの語順のまま。\\n\\n【問題2】次の文を感嘆文に書きかえなさい。\\nShe sings very beautifully.\\n\\n【解答】How beautifully she sings!\\n【解説】名詞がなく副詞（beautifully）だけを強調するのでHowを使う。\\n\\n【問題3】（　）に適切な付加疑問を入れなさい。\\nYou have finished your homework, (   )?\\n\\n【解答】haven't you\\n【解説】現在完了の文（have finished）の付加疑問はhaven't youになる。肯定文なので否定形の付加疑問。\\n\\n【問題4】次の否定疑問文に、事実（好き）に合わせて答えなさい。\\nDon't you like math? （数学は好き）\\n\\n【解答】Yes, I do.\\n【解説】内容が「好き」なのでYesで答える。日本語の「いいえ、好きです」につられて Noと答えないよう注意。\\n\\n【問題5】まちがいを直しなさい。\\nWhat a nice pen is this!\\n\\n【解答】What a nice pen this is!\\n【解説】感嘆文は疑問文のように倒置しない。主語（this）のあとに動詞（is）を置く。\\n\\n★ 入試対策ポイント：\\n■ 名詞があればWhat、なければHowを使う感嘆文\\n■ 感嘆文は倒置しない（主語＋動詞のふつうの語順）\\n■ 付加疑問文は前の文と逆（肯定→否定、否定→肯定）、主語は代名詞\\n■ 否定疑問文の答えは「日本語のはい・いいえ」ではなく「内容」で機械的にYes/Noを選ぶ\"},{\"heading\":\"★ MAXレベル：会話でよく使う感嘆表現と発展的な確認表現\",\"body\":\"■ 会話でとっさに使える感嘆の相づち表現（暗記推奨）\\n文法的な感嘆文以外にも、会話でよく使われる決まった感嘆の相づちがある。\\n・What a surprise!（なんて驚きだ！）\\n・How nice! / How wonderful! / How amazing!（なんて素敵/素晴らしい/すごい！）\\n・That's amazing! / That's incredible!（それはすごい！信じられない！）\\n・No way!（うそでしょう！/まさか！）※驚きを表すくだけた表現\\n・I can't believe it!（信じられない！）\\n★ これらは面接・スピーキングテストで感情豊かに応答する際にも役立つ。\\n\\n■ 付加疑問文のイントネーションによる意味の違い（発展的な音声知識）\\n付加疑問文は、文末を上げ調子で読むか下げ調子で読むかで意味・ニュアンスが変わる。\\n・下げ調子（確認・同意を求める、答えがほぼわかっている）：You are a student, aren't you？（↘）\\n・上げ調子（本当に知りたい・確信がない）：You are a student, aren't you？（↗）\\n★ 中学レベルでは知識として知っておく程度でよいが、リスニング問題で「話者がどれくらい確信しているか」を判断する手がかりになる。\\n\\n■ 否定疑問文のさらなる応用：Why don't you 〜?（〜したらどうですか＝提案）\\nWhy don't you 〜?は形は否定疑問文だが、意味は「〜してはどうですか」という提案・勧誘になる特殊な用法。\\n例）Why don't you take a break?（休憩をとったらどうですか）\\n例）Why don't we eat out tonight?（今夜は外食しませんか）※Why don't we 〜はLet's 〜とほぼ同じ意味\\n⚠ 注意：Why don't you 〜?を文字通り「なぜあなたは〜しないのですか」と誤訳しないよう注意。提案の決まり文句として覚える。\\n\\n■ so/neitherの倒置と付加疑問文の混同に注意（総復習）\\n別単元で学んだ「So do I. / Neither do I.」の同意表現と、この単元の付加疑問文は形が似ているが役割が異なる。\\n・付加疑問文：自分の発言の最後に確認をつける（You like tea, don't you?）\\n・So/Neitherの倒置：相手の発言に「私も」と応じる（A: I like tea. B: So do I.）\\n★ どちらも「主語＋動詞」の倒置的な語順を含むため混同しやすいが、「自分の文の末尾に付けるか」「相手への応答か」で区別するとよい。\",\"maxOnly\":true}]}",
"{\"id\":\"eigo_s001\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"アルファベット①：大文字と小文字\",\"description\":\"26文字の大文字・小文字の対応と、大文字を使う場所のきまりを身につける\",\"intro\":\"「ローマ字なら書けるよ」という人でも、いざ英文を書くと japan や i のように小文字で書き始めてしまいます。日本語には大文字・小文字の区別がないので、知らなければ必ずやるまちがいです。どこで大文字を使うのか、ここで決着をつけます。\",\"order\":501,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"アルファベットは全部で26文字。1文字につき大文字と小文字が1つずつある。\",\"大文字を使うのは「文の最初」「人名・地名・国名」「曜日・月の名前」「I（私は）」。\",\"小文字には「大文字を小さくしただけの字」と「形がまったく変わる字」の2種類がある。\",\"b と d、p と q は形が左右逆。丸がどちら側につくかで区別する。\",\"英語は単語と単語のあいだを1文字分あけて書く（日本語のように続けて書かない）。\"],\"sections\":[{\"heading\":\"26文字と大文字・小文字\",\"body\":\"英語はアルファベット26文字だけで書かれる。日本語のひらがな・カタカナ・漢字にくらべると覚える文字数はとても少ないが、1文字につき大文字（capital letter）と小文字（small letter）の2つの形があるので、対応をしっかり覚える必要がある。\\n\\n■ 大文字と小文字の関係は2種類\\n①大きさがちがうだけで形は同じ字\\n　C-c　O-o　S-s　U-u　V-v　W-w　X-x　Z-z　P-p　K-k　J-j\\n②形そのものが変わる字\\n　A-a　B-b　D-d　E-e　F-f　G-g　H-h　I-i　L-l　M-m　N-n　Q-q　R-r　T-t　Y-y\\n\\n②のグループがまちがえやすい。とくに R-r、Q-q、G-g は、大文字だけ書けて小文字が書けない子が多い。\\n\\n■ 形がまぎらわしい組み合わせ\\nb と d ／ p と q ／ n と h ／ u と v ／ i と j\\nb は「棒が左、丸が右」、d は「丸が左、棒が右」。声に出しながら書いて手で覚えるとよい。\\n\\n★ ポイント：中学入試の英語では、答案の文字が読み取れないだけで不正解にされる。うまい字より「はっきり区別できる字」を書くことが得点につながる。\",\"figureId\":\"lf_eigoext01_001\"},{\"heading\":\"大文字を使う場所のきまり\",\"body\":\"日本語には大文字・小文字の区別がないので、日本人がいちばんまちがえるのがここである。次の5つは必ず大文字で書き始める。\\n\\n①文の最初の1文字\\n　例）This is my school.（学校の s は文の途中なので小文字）\\n②人の名前・地名・国名・言語名\\n　例）Ken／Tokyo／Japan／English\\n③曜日の名前\\n　例）Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday\\n④月の名前\\n　例）January, February, March, April, May, June, July, August, September, October, November, December\\n⑤「私は」を表す I\\n　例）I am ten years old.（文の途中でも必ず大文字の I）\\n\\n■ 逆に大文字にしないもの\\n教科名の一部（math, science）、季節（spring, summer, fall, winter）、方角（east, west）は小文字で書く。ただし English（英語）は「イギリスの」という国名から来た語なので、教科名でも大文字である。\\n\\n⚠ 注意：日本語では「日曜日」も「私」もふつうの字なので、つい sunday、i と書いてしまう。書いたあとに「文の頭・名前・曜日・月・I」の5つを見直す習慣をつける。\",\"mangaId\":\"eigo_s001_xm\"}],\"trapExamples\":[{\"question\":\"「わたしは日曜日にピアノをひきます。」を英語で書きなさい。（I play the piano on ~ を使う）\",\"wrongAnswer\":\"i play the piano on sunday.\",\"trapExplanation\":\"日本語には大文字・小文字の区別がないため、文の最初も、曜日も、「私」も、すべて同じ調子で小文字のまま書いてしまう。とくに I は1文字なので小さく書きたくなる。\",\"correctAnswer\":\"I play the piano on Sunday.\",\"correctExplanation\":\"文の最初の文字は大文字、「私は」を表す I はどこにあっても大文字、曜日名 Sunday も大文字で書き始める。書き終えたら「文頭・I・曜日・月・名前」の5点を必ず見直す。\"},{\"question\":\"「ベッド」を表す英単語 bed を4本線に書きなさい。\",\"wrongAnswer\":\"ded\",\"trapExplanation\":\"b と d はどちらも「まっすぐな棒＋丸」でできているため、丸が左右どちらにつくのかがあやふやになる。頭の中で音は正しく「ベッド」と言えていても、手が逆の形を書いてしまう。\",\"correctAnswer\":\"bed\",\"correctExplanation\":\"b は棒を先に下ろしてから右下に丸をつける字、d は丸を先に書いてから右側に棒を下ろす字である。両手でこぶしを作って親指を立てると、左手が b、右手が d の形になる。この方法で毎回確かめるとまちがえない。\"}]}",
"{\"id\":\"eigo_s002\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"アルファベット②：4本線への正しい書き方\",\"description\":\"小文字の高さの3グループと、4本線のどこに書くかのきまりを覚える\",\"intro\":\"ノートの4本線は、なんとなく引いてある飾りではありません。g や p を線の下までのばさずに書くと、q や 9 と見分けがつかなくなります。小文字の高さは3つのグループに分かれていて、そのきまりを知るだけで字が急に読みやすくなります。\",\"order\":502,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"4本線は上から第1線・第2線・第3線・第4線。第3線が「基準の線（ベースライン）」で、ほとんどの字はこの線の上に立つ。\",\"小文字の高さは3グループ。上に出る字7つ（b d f h k l t）、下に出る字5つ（g j p q y）、まん中だけの字14。\",\"大文字はすべて第1線から第3線までいっぱいに書く（下にははみ出さない）。\",\"t は上に出るが、l や b よりやや低く書く。\",\"i と j の点、t の横棒は、字の本体を書き終えてから最後に付ける。\"],\"sections\":[{\"heading\":\"4本線の使い方\",\"body\":\"英語のノートは4本線になっている。この4本の線には役割があり、どの高さに書くかで文字の形が決まる。\\n\\n■ 線の呼び方\\n上から第1線・第2線・第3線・第4線と呼ぶ。いちばん大事なのは第3線で、これを「基準の線」という。ほとんどの文字はこの第3線の上に立ち、第2線と第3線のあいだの空間（まん中の部屋）を本体とする。\\n\\n■ 大文字の書き方\\n大文字は26字すべて、第1線から第3線までを使って書く。下の第4線までははみ出さない。\\n例）A B C D E F G … すべて同じ高さになる。\\n\\n■ 小文字の書き方\\n小文字は本体が「第2線から第3線のあいだ」に収まる。ここから上にはみ出す字と、下にはみ出す字がある。\\n例）a c e m n o r s u v w x z → まん中の部屋だけ\\n例）b d f h k l → 上の第1線まで届く\\n例）g j p q y → 下の第4線まで下りる\\n\\n★ ポイント：単語を書くときは、まず第3線（基準の線）に文字をそろえて並べる意識を持つ。文字の下端がそろっていれば、多少形がくずれても読みやすい答案になる。\"},{\"heading\":\"高さの3グループを数で覚える\",\"body\":\"小文字26字を高さで分けると、次のようにきれいに3つに分かれる。\\n\\n■ 上に出る字（7字）：b d f h k l t\\n　→ 第1線まで届く「背の高い字」。ただし t だけは少し低く、第1線と第2線のちょうど中間くらいまでにする。\\n■ 下に出る字（5字）：g j p q y\\n　→ 第3線を突き抜けて第4線まで下りる「しっぽのある字」。j は上の点も忘れない。\\n■ まん中だけの字（14字）：a c e i m n o r s u v w x z\\n　→ 第2線と第3線のあいだだけを使う。i の点は第2線より上に出る。\\n\\n■ 書き順で気をつけること\\ni・j の点、t の横棒は、たての線を書き終えてから最後に付ける。先に点や横棒を書くと位置がずれる。\\nf は上に出るが、下にも少し出す書き方（筆記体風）とまん中で止める書き方がある。ブロック体では第1線から第3線までで止めるのがふつうである。\\n\\n⚠ 注意：apple の p を「まん中の部屋」だけに書くと、a と同じ高さになってしまい、まったく別の字に見える。高さの情報も文字の形の一部だと考える。\",\"figureId\":\"lf_eigoext01_002\"},{\"heading\":\"なぜ高さで文字が決まるのか\",\"mangaId\":\"eigo_s002_manga\",\"body\":\"英語の小文字は、**形だけでなく高さも文字の情報**です。n と h は、たての棒が第1線まで届くかどうかだけのちがいで、a と d も同じです。p と n は丸の位置は似ていますが、棒が第4線まで下りるかどうかで区別します。だから高さをそろえて書かないと、読む人にはちがう文字に見え、正しく書いたつもりでも不正解になります。4本線は飾りではなく、この高さの情報を書き分けるための線です。\\n\\n小文字を3つのグループに分けるのは、26字を1字ずつ覚えるより、**「上に出る7字・下に出る5字・残りはまん中」**と数で覚えるほうが確実だからです。上に出る7字のうち t だけ少し低いのは、l と同じ高さまでのばすと横棒が無いときに l と見分けがつかないからです。\\n\\n■ 確かめのしかた\\n①書いた単語の**文字の下端が第3線にそろっているか**を見る。ここがそろえば多少形がくずれても読める。\\n②上に出る字（b d f h k l t）が第1線まで届いているか、t は少し低いか。\\n③下に出る字（g j p q y）が第4線まで下りているか。apple の p がまん中だけになっていたら a と同じ高さ→×。\\n④i・j の点、t の横棒は、たての線を書いてから最後に付けたか。\\n\\n★ ここがポイント：小文字は**高さも文字の情報**（n と h、p と n は高さでしか区別できない）。**上に出る7字・下に出る5字・残りはまん中**と数で覚え、下端を第3線にそろえる。\"}],\"trapExamples\":[{\"question\":\"「apple」を4本線に書くとき、p はどこに書くか。\",\"wrongAnswer\":\"第2線と第3線のあいだ（まん中の部屋）だけに書く\",\"trapExplanation\":\"「小文字はまん中の部屋に書く」とだけ覚えていると、しっぽのある字も同じ高さに縮めてしまう。丸の部分だけを見て a や o と同じ大きさに書いてしまうのが原因。\",\"correctAnswer\":\"丸の部分を第2線と第3線のあいだに書き、たての棒を第4線まで下ろす\",\"correctExplanation\":\"p は「下に出る字」5つ（g j p q y）のひとつ。丸の部分だけをまん中の部屋に収め、棒は基準の線（第3線）を突き抜けて第4線まで下ろす。下に出さないと n や o と見分けがつかなくなる。\"},{\"question\":\"小文字の t は、l や b と同じ高さまで上に出すか。\",\"wrongAnswer\":\"同じ高さまで出す（第1線まで届かせる）\",\"trapExplanation\":\"「上に出る字は b d f h k l t の7つ」とまとめて覚えるため、7字すべてが同じ高さだと思いこんでしまう。\",\"correctAnswer\":\"上には出すが、l や b よりやや低く（第1線と第2線の中間くらいまで）書く\",\"correctExplanation\":\"t だけは他の6字より背が低い。l と同じ高さまで伸ばすと、横棒がなければ l と見分けがつかなくなる。「t は少し低くて横棒つき」と覚える。\"}]}",
"{\"id\":\"eigo_s003\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"アルファベット③：並び順と名前の読み方\",\"description\":\"A〜Zの順序を確実にし、まぎらわしい文字の名前（アルファベット読み）を区別する\",\"intro\":\"辞書も名簿も目次も、すべて A から Z の順に並んでいます。順番があやふやだと、辞書を引くだけで時間を取られます。しかも英語の Z は「ゼット」とは読みません。文字の名前と、文字が単語の中で出す音のちがいもここで整理します。\",\"order\":503,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"A〜Z の26字の順番は、何も見ずに書けるまで練習する。辞書・名簿・目次はすべてこの順に並ぶ。\",\"「アルファベット読み（文字の名前）」と「フォニックスの音（文字が単語の中で出す音）」は別もの。\",\"まぎらわしい名前：G（ジー）と J（ジェイ）、M（エム）と N（エヌ）、E（イー）と I（アイ）、V（ヴィー）と W（ダブリュー）。\",\"Z は日本では「ゼット」と言うが、英語（アメリカ）では [ziː]（ズィー）と読む。\",\"「◯の2つ前／3つ後ろの文字」を答える問題では、指を使って前後を数え、方向をまちがえない。\"],\"sections\":[{\"heading\":\"26字の順序と歌の区切り\",\"body\":\"アルファベットの並び順は、英語学習の土台になる。辞書を引く、名簿を探す、索引を見る──どれも A〜Z の順を知らないとできない。\\n\\n■ 覚え方\\nアルファベットの歌（ABC ソング）は、次の4つのまとまりで区切られている。この区切りごとに書き出す練習をすると、途中から言えるようになる。\\n①A B C D E F G（7字）\\n②H I J K L M N O P（9字）\\n③Q R S T U V（6字）\\n④W X Y Z（4字）\\n\\n■ 途中から言える／書けるようにする\\n入試や英検では「Rの次の文字は？」「Pの2つ前は？」のように、順番そのものを問う問題が出る。歌のように最初から歌わないと出てこない状態では時間がかかる。M（13番目）を真ん中の目印にして、前半・後半に分けて練習するとよい。\\n\\n★ ポイント：26字を10秒以内に書けるようになるまで、毎日1回書く。ここが速くなると辞書引きの速さがまるで変わる。\",\"figureId\":\"lf_eigoext01_003\"},{\"heading\":\"まぎらわしい文字の名前\",\"body\":\"文字には「名前」がある。A は [eɪ]（エイ）、B は [biː]（ビー）というように読む。これをアルファベット読みという。聞き取りの問題では、この名前を正しく聞き分けられるかが問われる。\\n\\n■ 聞きまちがえやすい組み合わせ\\nG（ジー）と J（ジェイ）… J のほうが「エイ」の音が入る\\nM（エム）と N（エヌ）… M は「ム」で口を閉じる、N は「ヌ」で舌が上につく\\nE（イー）と I（アイ）… E は日本語の「イー」に近い、I は「アイ」\\nV（ヴィー）と B（ビー）… V は上の歯で下くちびるをかむ\\nA（エイ）と R（アール）／ K（ケイ）と Q（キュー）\\n\\n■ 日本語なまりに注意\\n・Z は日本では「ゼット」と言うが、これはドイツ語・フランス語風の読み方。英語（アメリカ）では [ziː]（ズィー）である。\\n・L は「エル」、R は「アール」。日本語ではどちらも「ル」の音になりがちだが、英語では別の音である。\\n・H を「ヘチ」と言わない。英語では [eɪtʃ]（エイチ）。\\n\\n⚠ 注意：文字の名前（エイ、ビー、シー）と、単語の中でその文字が出す音（ア、ブ、ク）はまったく別のもの。次の課からは「音」のほうを学ぶ。\"},{\"heading\":\"なぜ順番を速く言えることが大事で、なぜ名前と音を分けるのか\",\"mangaId\":\"eigo_s003_manga\",\"body\":\"辞書も名簿も索引も、A から Z の順に並んでいます。順番があやふやだと、辞書で1語を引くたびに最初から歌わなければならず、時間を取られます。「R の2つ前は何か」のような問題も、順番そのものを問うています。ABC の歌の4つの区切り（7・9・6・4字）で覚え、M（13番目）を真ん中の目印にすると、途中からでも数えられるようになります。\\n\\n文字の**名前**（A＝エイ、B＝ビー）と、単語の中でその文字が出す**音**（a＝ア、b＝ブ）を分けるのは、両方を混ぜると cat を「ケイト」と読んでしまうからです。名前は聞き取り問題やつづりを言うときに使い、音は単語を読むときに使います。日本語の「ゼット」「エル・アール」の区別も、英語の名前とはちがうので、英語の音で覚え直します。\\n\\n■ 確かめのしかた\\n①26字を**何も見ずに10秒以内**で書けるか。書けないなら区切り（ABCDEFG／HIJKLMNOP／QRSTUV／WXYZ）ごとに練習する。\\n②「〇の2つ前」は、指でアルファベット表を**左にたどる**。R の2つ前→Q→P。「前」と「後ろ」の方向をまちがえていないか。\\n③まぎらわしい名前を対で言えるか：G（ジー）／J（ジェイ）、M（ム）／N（ヌ）、E（イー）／I（アイ）、V／B、Z（ズィー）。\\n④名前と音を混ぜていないか。cat の a は「エイ」ではなく短母音の音。\\n\\n★ ここがポイント：A〜Z の順番は**辞書引きの速さ**そのものなので、区切りと M の目印で途中からも数えられるようにする。**文字の名前と音は別もの**で、名前は聞き取りとつづり、音は読むときに使う。\"}],\"trapExamples\":[{\"question\":\"アルファベットで、R の2つ前の文字を書きなさい。\",\"wrongAnswer\":\"T\",\"trapExplanation\":\"「2つ前」と言われたのに、頭の中でアルファベットを前から順に唱えるくせがあるため、R から先に進んで数えてしまう。日本語の「前」が時間の意味にも位置の意味にも使えることも混乱のもとになる。\",\"correctAnswer\":\"P\",\"correctExplanation\":\"A→Z の並びで R より手前に2つもどる。R の1つ前が Q、2つ前が P である。数えるときは指でアルファベット表を左にたどる、と動作を決めておくと方向をまちがえない。\"},{\"question\":\"文字 G の名前（アルファベット読み）をカタカナで書きなさい。\",\"wrongAnswer\":\"ジェイ\",\"trapExplanation\":\"G と J はどちらも「ジ」で始まる音に聞こえるため、名前が入れかわる。とくに日本語ではローマ字の「じ」を ji と書くので、J のほうを「ジー」だと思いこみやすい。\",\"correctAnswer\":\"ジー（[dʒiː]）\",\"correctExplanation\":\"G が「ジー」、J が「ジェイ」である。J には「エイ」の音がつく、と組にして覚える。同じく K（ケイ）、A（エイ）、H（エイチ）も「エイ」を含む仲間としてまとめて確認しておく。\"}]}",
"{\"id\":\"eigo_s004\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"アルファベット④：ブロック体・筆記体とまぎらわしい字\",\"description\":\"入試で通用する活字体（ブロック体）の書き方と、読みまちがえられない字の書き分け\",\"intro\":\"答案に書いた u が v に見えたら、内容が合っていても不正解になります。日本語ではめったに起きませんが、英語ではこれが本当に起こります。入試で通用する字の形と、まぎらわしい字の書き分けを確かめましょう。\",\"order\":504,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"入試の答案はブロック体（活字体）で書く。筆記体は「読めればよい」程度でよい。\",\"書き分けが必要なのは u と v、n と h、a と o、q と g、r と v、i と l。\",\"大文字の I は上下に短い横棒を付ける。棒1本だけだと小文字の l と区別がつかない。\",\"単語のあいだは1文字分あける。文字と文字はくっつけすぎない。\",\"答案では、あいまいな字は書き直す。読めない字は内容が合っていても不正解になる。\"],\"sections\":[{\"heading\":\"入試で使う字はブロック体\",\"body\":\"英語の文字の書き方には、活字体（ブロック体）と筆記体の2種類がある。\\n\\n■ ブロック体\\n教科書やこの教材で使われている、1文字ずつ独立した形。中学入試・英検・学校のテストで書くのはすべてこちらである。まずこれを正確に書けるようにする。\\n\\n■ 筆記体\\n文字をつなげて続けて書く書き方。かつては中学校で必ず習ったが、現在の学習指導要領では必修ではない。中学入試で筆記体を書かせる問題はまず出ない。ただし、英語圏の手紙や絵本の題字で使われることがあるので、読めると得をする程度に思っておけばよい。\\n\\n■ 答案で気をつけること\\n①単語のあいだは1文字分あける。あけないと2語が1語に見える。\\n　例）I am a student.（4語がはっきり分かれて見えるように書く）\\n②文字と文字はつなげない。ブロック体をつなげて書くと筆記体のようになり、判読できなくなる。\\n③文の終わりにはピリオド（.）、疑問文にはクエスチョンマーク（?）を必ず付ける。これも採点の対象になる。\\n\\n★ ポイント：うまい字を書く必要はまったくない。「他人がひと目で読める字」が正解になる字である。\"},{\"heading\":\"読みまちがえられやすい字\",\"body\":\"採点者は、書いた本人ではない。自分では書けているつもりでも、別の字に読めてしまえば不正解になる。とくに次の組み合わせに注意する。\\n\\n■ u と v\\nu は下が丸い、v は下がとがる。v の下を丸めると u になり、five が fiue になってしまう。\\n■ n と h\\nh は上に高く伸ばす、n は伸ばさない。中途半端な高さだとどちらか分からない。\\n■ a と o\\na は右側にたての棒がつく。丸だけで棒を書かないと o になる。cat が cot に見える例がある。\\n■ q と g\\nq は下の棒をまっすぐ下ろす、g は下を左に曲げる。\\n■ r と v\\nr は右上に短くはらうだけ。大きくはらうと v に見える。\\n■ 大文字 I と小文字 l と数字の 1\\n大文字の I は上下に短い横棒を付ける。これを忘れて縦棒1本で書くと、小文字の l と区別がつかない。\\n\\n⚠ 注意：答案を書き終えたら、自分の書いた単語を「知らない人が読んだらどう見えるか」という目で読み返す。あやしい字は消して書き直したほうが安全である。\",\"figureId\":\"xf_eigo_s004\",\"mangaId\":\"eigo_s004_xm\"}],\"trapExamples\":[{\"question\":\"数の「5」を表す英単語を書きなさい。\",\"wrongAnswer\":\"fiue\",\"trapExplanation\":\"v の下をまるく書くくせがあると、u と同じ形になってしまう。書いた本人は five のつもりでも、採点する人には fiue（存在しない語）に見えるため不正解になる。\",\"correctAnswer\":\"five\",\"correctExplanation\":\"v は下をとがらせ、u は下をまるく書く。この2字は形のちがいが1か所しかないので、意識して書き分ける。似た例に seven（v）、have（v）があり、いずれも v の書き方であやしくなりやすい。\"},{\"question\":\"「I have a dog.」をブロック体で書き写しなさい。\",\"wrongAnswer\":\"l have a dog.（大文字の I をたて棒1本で書いた）\",\"trapExplanation\":\"大文字の I はたて棒1本で書けると思いこみやすい。しかしそれでは小文字の l とまったく同じ形になり、文頭の語が読めなくなる。\",\"correctAnswer\":\"I have a dog.（I の上下に短い横棒を付ける）\",\"correctExplanation\":\"ブロック体の大文字 I は、たて棒の上下に短い横棒を付けて書く。こうすれば小文字の l や数字の 1 と区別できる。1文字だけの語 I と a は、まわりを広くあけて書くと読みやすい。\"}]}",
"{\"id\":\"eigo_s005\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"母音字と子音字：26字の役割分担\",\"description\":\"母音字5字・子音字21字の区別と、y の二面性、a／an の使い分けを理解する\",\"intro\":\"by や my には母音字が一つも見当たりません。それなのに読めるのはなぜでしょうか。実は y が母音の役をしているからです。26文字を母音字と子音字に分けて考えると、a と an の使い分けまで見通せるようになります。\",\"order\":505,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"母音字は a・e・i・o・u の5字。残りの21字が子音字。\",\"y は子音の働き（yes, you）と母音の働き（my, happy, gym）の両方を持つ特別な字。\",\"どの単語にも必ず母音の音が入る。母音字が見えない by・my・why は y が母音の働きをしている。\",\"母音＝口の中で息がさえぎられずに出る音。子音＝くちびる・舌・歯のどこかで息をせき止めて出す音。\",\"a と an の使い分けは「つづり」ではなく「次に来る音」で決まる（an hour／a university）。\"],\"sections\":[{\"heading\":\"母音字と子音字\",\"mangaId\":\"eigo_s005_manga\",\"body\":\"アルファベット26字は、母音字と子音字に分かれる。\\n\\n■ 母音字（5字）\\na・e・i・o・u\\n口を開けて、息が舌や歯にじゃまされずにそのまま出てくる音を表す。日本語の「ア・イ・ウ・エ・オ」に近い役割だが、英語では1つの文字が何通りもの音を表すので注意が必要である。\\n\\n■ 子音字（21字）\\nb・c・d・f・g・h・j・k・l・m・n・p・q・r・s・t・v・w・x・y・z\\nくちびるを閉じる（p, b, m）、舌を上あごにつける（t, d, n）、息をすきまから出す（s, f）など、どこかで息をせき止めたりこすったりして出す音を表す。\\n\\n■ どの語にも母音がある\\n英語の単語には必ず母音の音が入っている。母音がなければ声にならないからである。\\n例）cat（a）／dog（o）／school（oo）／strong（o）\\nstrong は子音字が5つも並ぶが、母音の音は o の1つだけ。この「母音は少なく子音が多い」という形が、日本語（原則として子音＋母音がセット）とは大きく異なる英語の特徴である。\\n\\n★ ポイント：単語を見たらまず母音字に丸をつける。母音の数＝おおよその音のまとまり（音節）の数になる。\",\"figureId\":\"lf_eigoext01_005\"},{\"heading\":\"y の二面性と a／an の使い分け\",\"body\":\"■ y は子音にも母音にもなる\\n①子音として働く場合（語の最初に来るとき）\\n　例）yes／you／year／yellow → 「ヤ・ユ・ヨ」に近い音\\n②母音として働く場合（語の中・語の終わりに来るとき）\\n　例）my／by／why → 「アイ」の音\\n　例）happy／city／baby → 「イ」の音\\n　例）gym／system → 「イ」の短い音\\nだから my や by は、母音字が1つもないのに単語として成り立つ。y が母音のはたらきをしているからである。\\n\\n■ a と an の使い分け\\n数えられる名詞が1つのとき、前に a か an を付ける。ここで多くの人がまちがえる。\\n◎きまり：次に来る語が「母音の音」で始まれば an、「子音の音」で始まれば a。\\n　→ 判断するのはつづりではなく音である。\\n例）a book／a cat／an apple／an orange／an egg\\n例外に見えるもの：\\n　an hour（h を読まないので「アウア」＝母音の音で始まる）\\n　an honest boy（h を読まない）\\n　a university（「ユー」＝ y の子音の音で始まる）\\n　a uniform（同じく「ユー」）\\n\\n⚠ 注意：「a・i・u・e・o で始まる語には an」と覚えると、university や hour でまちがえる。必ず声に出して、最初の音で判断する。\"}],\"trapExamples\":[{\"question\":\"「my」には母音字 a・e・i・o・u が1つも入っていない。それでも単語として成り立つのはなぜか。\",\"wrongAnswer\":\"英語には母音の音を持たない単語もあるから\",\"trapExplanation\":\"「母音字＝a e i o u の5つ」とだけ覚えていると、この5字がなければ母音がないと考えてしまう。y を子音字の仲間としてしか見ていないことが原因。\",\"correctAnswer\":\"y が母音の働きをして「アイ」の音を出しているから\",\"correctExplanation\":\"y は語の最初では子音（yes, you）、語の中や終わりでは母音（my, by, happy, gym）として働く特別な文字である。英語の単語には必ず母音の音が入るので、母音字が見あたらない語は y をさがす。\"},{\"question\":\"（　）に a か an を入れなさい。　I studied for （　） hour.\",\"wrongAnswer\":\"a\",\"trapExplanation\":\"hour は h という子音字で始まるので、つづりだけを見て a を選んでしまう。a／an をつづりで判断するくせがあると必ず引っかかる。\",\"correctAnswer\":\"an（I studied for an hour.）\",\"correctExplanation\":\"hour の h は読まないので、実際の音は母音「アウア」で始まる。a／an は「つづり」ではなく「次に来る音」で決める。逆に university はつづりが u で始まるが音は「ユー」なので a university となる。\"}]}",
"{\"id\":\"eigo_s006\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"短母音①：a・e・i・o・u の5つの音\",\"description\":\"フォニックスの出発点である短母音を、口の形とともに区別できるようにする\",\"intro\":\"知らない語に出会ったとき、日本語なら漢字から意味の見当がつきます。英語ではつづりから音の見当をつけます。その手がかりになるきまりがフォニックスです。まずは cat・bed・sit の a・e・i、5つの短い母音から始めます。\",\"order\":506,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"フォニックスとは「つづり字と音の対応のきまり」のこと。読めない単語も音の見当がつくようになる。\",\"短母音は5つ。a（cat）／e（bed）／i（sit）／o（box）／u（cup）。\",\"「子音＋母音字1つ＋子音」で終わる語は、たいてい母音字が短母音になる。\",\"a の短母音は日本語の「ア」ではなく、口を横に開いた「エとアの中間（ェア）」。\",\"u の短母音は口をあまり開けない「ア」。日本語の「ウ」ではない（cup は「カップ」に近い）。\"],\"sections\":[{\"heading\":\"フォニックスと短母音\",\"body\":\"フォニックス（phonics）とは、つづり字と音の関係を学ぶ方法である。英語は「つづりを見れば読み方の見当がつく」ようにできている部分が多く、そのきまりを知っていれば、初めて見る単語でも読めるようになる。逆にこれを知らないと、単語を1つずつ丸暗記することになり、覚える量が何倍にもふくれあがる。\\n\\n■ まず覚えるのは5つの短母音\\na … cat, hat, map, bag, sad\\ne … bed, pen, ten, red, egg\\ni … sit, big, pig, six, hit\\no … box, dog, hot, top, stop\\nu … cup, bus, run, sun, cut\\n\\n■ どんなときに短母音になるか\\n「子音＋母音字1つ＋子音」の形（CVC 型）で語が終わるとき、その母音字はほぼ短母音になる。\\n例）c-a-t（cat）／b-e-d（bed）／h-o-t（hot）\\n母音字が2つ並んだり、語末に e が付いたりすると読み方が変わる（次の課以降で学ぶ）。\\n\\n★ ポイント：短母音は「短く、鋭く」発音する。日本語のようにのばさない。cat を「キャーット」とのばすと、まったくちがう語に聞こえる。\"},{\"heading\":\"口の形で覚える5つの母音\",\"body\":\"5つの短母音は、口の開き方と舌の位置がそれぞれちがう。カタカナに置きかえずに、口の形で覚えるのが近道である。\\n\\n■ a（cat）\\n口を横に大きく開き、「エ」と「ア」の中間のような音を出す。日本語の「ア」で cat と言うと cut（切る）に近く聞こえてしまう。\\n■ e（bed）\\n口を軽く横に開いて「エ」。日本語の「エ」に近く、5つの中ではいちばんやさしい。\\n■ i（sit）\\n口を少しだけ横に開いて、短く弱い「イ」。日本語の「イ」よりも力を抜く。sit を強く「シート」と言うと seat（座席）になってしまう。\\n■ o（box）\\n口を丸くたてに開いて「ア」に近い音（アメリカ英語）。イギリス英語では「オ」に近い。\\n■ u（cup）\\n口をあまり開けず、のどの奥で短く「ア」。日本語の「ウ」ではない。cup は「クップ」ではなく「カップ」に近い。\\n\\n⚠ 注意：短母音のうち、日本人がとくに苦手なのは a と u の区別である。cat と cut、bag と bug、hat と hut は、母音の1音だけで意味が変わる。\",\"figureId\":\"lf_eigoext01_006\"},{\"heading\":\"なぜフォニックスから始めるのか、なぜ CVC 型は短母音なのか\",\"mangaId\":\"eigo_s006_manga\",\"body\":\"英語のつづりと音には、かなりの部分できまりがあります。このきまり（フォニックス）を知っていれば、初めて見る単語でも音の見当がつき、聞いた音からつづりを組み立てられます。知らなければ、単語を1つずつ丸暗記することになり、覚える量が何倍にもなります。だから最初に、いちばん基本の5つの短母音から始めます。\\n\\n「子音＋母音字1つ＋子音」（CVC 型）で終わる語の母音が短母音になるのは、母音字が**1つだけで、あとに子音でふさがれている**からです。cat・bed・sit・box・cup はどれもこの形です。母音字が2つ並んだり（rain）、語末に e が付いたり（cake）すると、母音は長くのびて文字の名前の音（エイ）になります。つまり「母音字が1つで、うしろが子音」なら短く、それ以外なら別のきまり、と区別できます。\\n\\n■ 確かめのしかた\\n①単語を c-a-t のように**音に分けて**、母音字が1つで子音にはさまれているか見る。そうなら短母音。\\n②5つの短母音を**口の形**で言えるか：a（横に大きく開く・エとアの中間）、e（軽く横に開く）、i（少し開いて弱く）、o（丸くたてに開く）、u（あまり開けず、のどの奥で短くア）。\\n③日本語の母音で代用していないか。cat を「ア」で言うと cut、sit を強く「シート」と言うと seat になる。\\n④聞き取りで bad と bed のように迷ったら、**意味の通る文**を作って確かめる（That is a bad idea. ／ I sleep in my bed.）。\\n\\n★ ここがポイント：フォニックスは**つづりと音のきまり**で、知っていれば初めての単語も読める。**母音字が1つで子音にはさまれた語（CVC）は短母音**。5つの音は口の形で覚え、a と u の区別をとくに練習する。\"}],\"trapExamples\":[{\"question\":\"「cat」の a はどのように読むか。\",\"wrongAnswer\":\"エイ（アルファベット読みのまま「ケイト」と読む）\",\"trapExplanation\":\"文字の名前（A＝エイ）を先に覚えるため、単語の中でもその名前の音で読んでしまう。とくにアルファベットの歌を覚えたばかりの段階で起こりやすい。\",\"correctAnswer\":\"短母音の a（口を横に開いた、エとアの中間の短い音）\",\"correctExplanation\":\"「子音＋母音字1つ＋子音」で終わる語では、母音字は短母音になる。cat は c-a-t の3つの音でできており、a は短く鋭い音になる。「エイ」と読むのは cake のように語末に e が付いたときである（マジックE）。\"},{\"question\":\"「悪い」という意味の英単語を書きなさい。\",\"wrongAnswer\":\"bed\",\"trapExplanation\":\"短母音の a を日本語の「ア」ではなく「エ」に近い音として習うため、bad の音を聞いて e を思いうかべてしまう。bad と bed は母音1字しかちがわないので、耳だけに頼ると必ずまざる。\",\"correctAnswer\":\"bad\",\"correctExplanation\":\"bad（悪い）の母音字は a、bed（ベッド）の母音字は e である。a のほうが口を大きく横に開き、e より長めに聞こえる。聞き取りで迷ったら、意味の通る文をつくって確かめる（That is a bad idea. ／ I sleep in my bed.）。\"}]}",
"{\"id\":\"eigo_s007\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"短母音②：a と e、e と i の書き分け\",\"description\":\"bad／bed、bed／bid のように1字で意味が変わる語を、意味とセットで区別する\",\"intro\":\"bad と bed はまん中の1文字だけがちがいます。ところがカタカナに直すとどちらも「ベッド」に近くなり、区別が消えてしまいます。pen と pin も同じです。音のちがいを、意味とセットで覚えていきましょう。\",\"order\":507,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"母音字1字のちがいで意味が変わる語（ミニマルペア）を、意味とセットで覚える。\",\"a と e：bad／bed、man／men、sad／said（said は例外の読み）、pan／pen。\",\"e と i：pen／pin、ten／tin、desk／disk、bed／bid、set／sit。\",\"a は口を横に大きく、e は軽く横に、i は力を抜いた短い「イ」。\",\"聞き取りで迷ったら、その語が入って意味の通る文を作って判断する。\"],\"sections\":[{\"heading\":\"a と e を区別する\",\"mangaId\":\"eigo_s007_manga\",\"body\":\"英語には、母音字を1字入れかえるだけで別の語になるペアがたくさんある。これをミニマルペアという。書き取り問題では、このペアのどちらを書くかで得点が決まる。\\n\\n■ a と e のペア\\nbad（悪い）／bed（ベッド）\\nman（男性・単数）／men（男性・複数）\\npan（フライパン）／pen（ペン）\\nsad（悲しい）／said（言った、say の過去形）\\nband（バンド）／bend（曲げる）\\n\\n■ 音のちがい\\na は口を横に大きく開き、あごを下げて「ェア」に近い音を出す。e は口の開きが小さく、日本語の「エ」に近い。日本人にとって a のほうがむずかしいので、a を「大きく開く音」と決めて練習する。\\n\\n■ man と men はとくに重要\\n単数と複数のちがいがこの1字だけで表される。同じように woman（1人）／women（複数）もあるが、women は読み方が「ウィミン」となり、つづりの o と音がずれる特別な語である。ここは丸暗記する。\\n\\n★ ポイント：ペアは必ず2語セットで、意味・つづり・例文の3点をまとめてノートに書く。片方だけ覚えると、テストで必ずもう片方と混同する。\",\"figureId\":\"xf_eigo_s007\"},{\"heading\":\"e と i を区別する\",\"body\":\"■ e と i のペア\\npen（ペン）／pin（ピン）\\nten（10）／tin（すず・かん）\\ndesk（つくえ）／disk（円ばん）\\nbed（ベッド）／bid（値をつける）\\nset（置く）／sit（すわる）\\nhead は e、hid は i と、つづりが似ていても形がちがう語もある。\\n\\n■ 音のちがい\\ne は口を横に開いて「エ」。i は口の力を抜いて短く「イ」。日本語の「イ」より弱く、あいまいに響く。日本人は i を強くはっきり「イー」と言いがちで、そうすると sit が seat（座席）に、hit が heat（熱）に聞こえてしまう。\\n\\n■ 書き取りでの見分け方\\n迷ったら意味の通る文にあてはめる。\\n例）I have a （pen／pin）. → 学校の場面なら pen\\n例）There are （ten／tin） students. → 数を表すなら ten\\n例）Please （set／sit） down. → 「すわる」なら sit\\n\\n⚠ 注意：日本語のカタカナ語がじゃまをすることがある。「デスク」「テン」はそのまま desk・ten でよいが、「ピン」は pin、「ペン」は pen と、カタカナでは同じ「エ／イ」に聞こえても英語では別音である。\"}],\"trapExamples\":[{\"question\":\"「10人の男性」を英語で書きなさい。\",\"wrongAnswer\":\"ten man\",\"trapExplanation\":\"「男性」＝man と1つの形だけで覚えていると、数が複数になっても形を変えない。また man の複数形を mans と考えて s を付けてしまう人もいる。\",\"correctAnswer\":\"ten men\",\"correctExplanation\":\"man の複数形は s を付けず、母音字を a から e に変えて men とする。同じ形の変化に woman／women、child／children（これは形がちがう）、foot／feet、tooth／teeth がある。数を表す語が前にあるときは複数形かどうかを必ず確かめる。\"},{\"question\":\"「Please （　） down.（すわってください）」の（　）に入る語を書きなさい。\",\"wrongAnswer\":\"set\",\"trapExplanation\":\"e と i の音の区別があいまいなうえ、set も sit も日本語では「セット」「シット」と似た調子で覚えているため、意味を確かめずに書いてしまう。\",\"correctAnswer\":\"sit\",\"correctExplanation\":\"sit は「すわる」、set は「（物を）置く」。人が動作の主なら sit、物を置くなら set である。sit down（すわる）、set the table（食卓の用意をする）と、決まった言い方ごと覚えるとまちがえない。\"}]}",
"{\"id\":\"eigo_s008\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"短母音③：o と u、a と u の聞き分け\",\"description\":\"日本人がいちばん苦手な a・o・u の区別を、口の形と語のペアで身につける\",\"intro\":\"cat（ねこ）と cut（切る）、hat（ぼうし）と hut（小屋）。カタカナで書くとどれも「ア」ですが、英語では別の音です。日本語の「ア」は一つしかないので、ここは口の形から覚え直す必要があります。\",\"order\":508,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"a と u のペア：cat／cut、bag／bug、hat／hut、cap／cup、bad／bud。\",\"o と u のペア：hot／hut、box／bus、not／nut、cop／cup。\",\"a は口を横に大きく、o は口を丸くたてに、u は口をあまり開けずのどの奥で短く。\",\"カタカナで書くと a も o も u も「ア」になってしまう。カタカナに置きかえない。\",\"つづりを見れば区別できるので、書き取り以外の問題では必ずつづりを手がかりにする。\"],\"sections\":[{\"heading\":\"「ア」に聞こえる3つの音\",\"body\":\"日本語の母音は「ア・イ・ウ・エ・オ」の5つだけだが、英語の母音はその4倍近くある。とくに短母音の a・o・u は、日本語のカタカナに直すとどれも「ア」になってしまうため、区別ができなくなる。\\n\\n■ 3つの音のちがい\\na（cat）… 口を横に大きく開き、あごを下げる。「ェア」に近い。\\no（box）… 口を丸くたてに開ける。アメリカ英語では「ア」に近く、イギリス英語では「オ」に近い。\\nu（cup）… 口をほとんど開けず、のどの奥で短く弱く出す。\\n\\n■ 代表的なペア\\ncat（ねこ）／cut（切る）\\nbag（かばん）／bug（虫）\\nhat（ぼうし）／hut（小屋）\\ncap（帽子）／cup（コップ）\\nhot（暑い）／hut（小屋）\\nnot（〜ない）／nut（木の実）\\nbox（箱）／bus（バス）\\n\\n★ ポイント：口の形を先に決めてから声を出す。a は「横に大きく」、o は「たてに丸く」、u は「開けない」。この3つの動作を体で覚えると、聞き取りも自然にできるようになる。\",\"figureId\":\"xf_eigo_s008\",\"mangaId\":\"eigo_s008_xm\"},{\"heading\":\"つづりを手がかりにする\",\"body\":\"聞き取りの力がつくまでは、つづりを手がかりにして意味を判断するのが現実的である。中学入試の英語では、音声問題より読み書きの問題のほうが配点が大きいことが多い。\\n\\n■ 意味から母音を決める練習\\n「ぼうしをかぶる」→ ぼうし＝cap または hat。前だけにつばのある帽子は cap、ぐるりとふちのある帽子は hat。どちらも u ではない。\\n「コップ1ぱいの水」→ a cup of water。cap ではない。\\n「バスに乗る」→ take a bus。box ではない。\\n「暑い日」→ a hot day。hut（小屋）ではない。\\n\\n■ よく出るまとまりで覚える\\na cup of tea（1ぱいの紅茶）\\na bus stop（バス停）\\nIt is hot today.（今日は暑い）\\nCut the paper.（紙を切る）\\n\\n■ 文全体で確かめる\\nI have a cat.（ねこを飼っている）と I cut my finger.（指を切った）では、文の形も意味もまったくちがう。1語だけを見ずに、まわりの語といっしょに考える。\\n\\n⚠ 注意：カタカナ語にひっぱられる例に注意する。「カップ」は cup だが「キャップ」は cap、「バッグ」は bag だが「バグ」は bug である。日本語になっている語こそ、つづりを確かめる。\"}],\"trapExamples\":[{\"question\":\"「一ぱいのお茶」を英語で書きなさい。\",\"wrongAnswer\":\"a cap of tea\",\"trapExplanation\":\"cup と cap は母音字1字しかちがわず、日本語ではどちらも「カップ／キャップ」と似た調子で発音される。書くときにどちらの母音字だったかが思い出せなくなる。\",\"correctAnswer\":\"a cup of tea\",\"correctExplanation\":\"cup（コップ・カップ）は u、cap（つばのある帽子）は a である。a cup of ~ は「カップ1ぱいの〜」を表す決まった言い方で、a cup of tea／coffee のかたちでそのまま覚える。帽子は wear a cap と使う。\"},{\"question\":\"次の英文の意味を答えなさい。　I cut the cake.\",\"wrongAnswer\":\"私はケーキをねこにあげた（cat と読みちがえた）\",\"trapExplanation\":\"cut と cat はつづりも音も似ているうえ、cut は原形と過去形が同じ形なので、動詞だと気づかずに名詞（ねこ）として読んでしまう。\",\"correctAnswer\":\"私はケーキを切った（切ります）。\",\"correctExplanation\":\"cut は「切る」という動詞で、cut－cut－cut と原形・過去形・過去分詞が同じ形になる。文の中で I のすぐ後ろにあるので動詞の位置である。cat は名詞なので、この位置には a や the なしでは入れない。語の位置からも品詞を判断する。\"}]}",
"{\"id\":\"eigo_s009\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"子音の基本音：対になる音を知る\",\"description\":\"b／p、d／t、g／k のように口の形が同じで声のあるなしだけが違う音を整理する\",\"intro\":\"b と p、d と t は、口の形がまったく同じです。ちがうのは、のどをふるわせるかどうかだけ。この区別は、あとで学ぶ books と dogs の -s の読み分けを決めるときに必ず使います。今のうちに整理しておきましょう。\",\"order\":509,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"子音には「声を出す音（有声音）」と「息だけの音（無声音）」の対がある。\",\"対になる音：b／p、d／t、g／k、v／f、z／s、j（ジ）／ch（チ）。\",\"この対は、あとで学ぶ -s や -ed の発音のきまりで必ず使うので、今のうちに整理しておく。\",\"l と r は日本語にない区別。l は舌先を上の歯ぐきにつける、r は舌をどこにもつけない。\",\"v と b、s と th、f と h はカタカナでは同じになりやすいので、口の形で覚える。\"],\"sections\":[{\"heading\":\"有声音と無声音\",\"body\":\"のどに手をあてて「ズー」と言うとふるえるが、「スー」と言うとふるえない。このふるえ（声帯の振動）があるかないかで、子音は2つに分かれる。\\n\\n■ 有声音（声がある）\\nb・d・g・v・z・m・n・l・r・w・j など\\n■ 無声音（息だけ）\\np・t・k・f・s・h・ch・sh など\\n\\n■ 対になっている6組\\nb（ブ）／p（プ）… くちびるを閉じて開く\\nd（ドゥ）／t（トゥ）… 舌先を上の歯ぐきにつける\\ng（グ）／k（ク）… 舌の奥を上あごにつける\\nv（ヴ）／f（フ）… 上の歯で下くちびるにふれる\\nz（ズ）／s（ス）… 舌先を上の歯ぐきに近づけてすきまから息を出す\\nj（ヂ）／ch（チ）… 舌を上あごにつけてから離す\\n\\nこの6組は、口の形も舌の位置もまったく同じで、声を出すか出さないかだけがちがう。だから b と p、d と t を聞きまちがえやすい。\\n\\n★ ポイント：この「対」は、-s の発音（/s/ か /z/ か）や -ed の発音（/t/ か /d/ か）を決めるときに必ず使う。フォニックスの土台なので、6組を今のうちに言えるようにしておく。\",\"figureId\":\"xf_eigo_s009\",\"mangaId\":\"eigo_s009_xm\"},{\"heading\":\"日本語にない音\",\"body\":\"日本語にない音は、カタカナに置きかえたとたんに区別が消える。次の音はとくに注意する。\\n\\n■ l と r\\nl … 舌先を上の歯の裏（歯ぐき）にしっかりつけて「ル」。light, look, play, class\\nr … 舌をどこにもつけず、舌先を少し内側に丸めて「ゥル」。right, read, red, train\\n日本語の「ラ行」はどちらとも少しちがう。ペアで練習する。\\n例）light（光）／right（右）　lead（導く）／read（読む）　glass（コップ）／grass（草）\\n\\n■ v と b\\nv … 上の歯で下くちびるに軽くふれ、声を出す。very, van, love, five\\nb … くちびるを閉じて開く。berry, bat, boy\\n例）vest（チョッキ）／best（最もよい）\\n\\n■ f と h\\nf … 上の歯で下くちびるにふれ、息だけ。food, fish, four\\nh … 口の形は変えず、のどから息を出す。hood, house, hot\\n\\n■ th\\n上下の歯のあいだに舌先を軽くはさんで息を出す。無声（think, three, month）と有声（this, that, mother）の2種類がある。\\n\\n⚠ 注意：これらは「日本語のどの音に近いか」ではなく「口のどこをどう使うか」で覚える。カタカナに直した瞬間に区別が消えることを忘れない。\"}],\"trapExamples\":[{\"question\":\"「right」と「light」の発音上のちがいを説明しなさい。\",\"wrongAnswer\":\"どちらも日本語の「ライト」と同じで、ちがいはない\",\"trapExplanation\":\"日本語では l と r の区別がなく、どちらもカタカナで「ライト」と書かれる。カタカナで理解しているかぎり、ちがいがないように感じてしまう。\",\"correctAnswer\":\"l（light）は舌先を上の歯ぐきにつけて出し、r（right）は舌をどこにもつけずに出す\",\"correctExplanation\":\"l は舌先を上の歯の裏にしっかりつけ、その両わきから声を出す。r は舌先をどこにもつけず、少し丸めるようにして出す。意味は light（光・軽い）と right（右・正しい）でまったく異なるので、聞き取り問題では前後の語から意味を判断することも大切である。\"},{\"question\":\"「g」と「k」の音のちがいは何か。\",\"wrongAnswer\":\"口の形も舌の位置もまったくちがう音である\",\"trapExplanation\":\"カタカナでは「グ」と「ク」でまったく別の音に見えるため、口の使い方も別だと考えてしまう。実際には同じ場所を使っている。\",\"correctAnswer\":\"口の形も舌の位置も同じで、声を出すか（g）出さないか（k）だけがちがう\",\"correctExplanation\":\"g も k も、舌の奥を上あごの奥につけてから離して出す音である。ちがいは声帯をふるわせるか（有声の g）、息だけを出すか（無声の k）だけ。この関係は b／p、d／t、v／f、z／s でも同じで、あとで -s や -ed の発音を決めるときに役立つ。\"}]}",
"{\"id\":\"eigo_s010\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"CVC の語を読む・書く\",\"description\":\"「子音＋母音＋子音」の3音の語を、音を1つずつつないで読み書きできるようにする\",\"intro\":\"c・a・t の3つの音をつなげると cat になります。逆に cat という音を聞いたら、c／a／t と3つに切り分けて書けます。この行き来ができるようになると、習っていない語でも読めて書けるようになります。\",\"order\":510,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"CVC＝子音（Consonant）＋母音（Vowel）＋子音（Consonant）の形。英語のいちばん基本の語の形。\",\"CVC の語では、まん中の母音字はほぼ必ず短母音になる。\",\"読むときは1音ずつ出してからつなげる（c－a－t → cat）。これをブレンディングという。\",\"書くときは音を1つずつ区切って文字にする（cat → c／a／t）。これをセグメンティングという。\",\"最初の音・まん中の音・最後の音を入れかえる練習（cat→cut→cup）で、音の感覚が育つ。\"],\"sections\":[{\"heading\":\"3つの音をつないで読む\",\"body\":\"英語の単語のいちばん基本の形が CVC 型である。子音・母音・子音の3つの音でできていて、フォニックスの練習はここから始まる。\\n\\n■ 代表的な CVC 語\\na：cat, hat, map, bag, sad, man, bad, can\\ne：bed, pen, ten, red, leg, net, get, hen\\ni：sit, big, pig, six, hit, win, lip, fin\\no：box, dog, hot, top, pot, hop, log, mop\\nu：cup, bus, run, sun, cut, bug, mud, nut\\n\\n■ 読み方の手順（ブレンディング）\\n①1文字ずつ音を出す　c（ク）－ a（ア）－ t（トゥ）\\n②となり合う音をつなげる　「クァ」－「トゥ」\\n③一気に言う　cat\\n最初はゆっくりでよい。慣れると①②を頭の中で行えるようになり、初めて見る語も読めるようになる。\\n\\n■ 書き方の手順（セグメンティング）\\n読むときと逆の手順をとる。\\n①語を聞いて、いくつの音でできているか指を折って数える（cat は3つ）\\n②音を1つずつ文字に直す（ク→c、ア→a、トゥ→t）\\n③つなげて書く\\n\\n★ ポイント：CVC がすらすら読めれば、英検5級・4級の単語の半分近くは自力で読める。ここを飛ばさずに練習する。\",\"figureId\":\"lf_eigoext01_010\",\"mangaId\":\"eigo_s010_xm\"},{\"heading\":\"1音だけ入れかえる練習\",\"body\":\"CVC の力を伸ばすには、3つの音のうち1つだけを入れかえる練習が効く。音の位置と役割がはっきり意識できるようになる。\\n\\n■ 最初の音を変える\\ncat → bat → hat → mat → rat → sat\\npen → hen → ten → men\\n■ まん中の音（母音）を変える\\ncat → cut → cot\\nbag → beg → big → bug\\npen → pin → pan\\nhot → hat → hut → hit\\n■ 最後の音を変える\\ncat → cap → can → cab\\nbig → bit → bid → bin\\n\\n■ 意味もいっしょに確認する\\n音を変えると意味は完全に変わる。\\nbat（コウモリ・バット）／mat（マット）／rat（ネズミ）\\nbeg（たのむ）／big（大きい）／bug（虫）\\ncan（〜できる・かん）／cab（タクシー）\\n\\n⚠ 注意：CVC のきまりが当てはまらない語もある。put（プット）の u は「ア」ではなく「ウ」に近い音、was（ワズ）の a も例外である。ただし、こうした例外は数が限られているので、まず原則を身につけてから覚えればよい。\"}],\"trapExamples\":[{\"question\":\"「pig」という語はいくつの音（音素）からできているか。\",\"wrongAnswer\":\"2つ（ピ・グ）\",\"trapExplanation\":\"日本語はカナ1文字が「子音＋母音」のセットなので、「ピ」を1つの音と数えてしまう。日本語の感覚のままだと、英語の音の数をつねに少なく数えることになる。\",\"correctAnswer\":\"3つ（p／i／g）\",\"correctExplanation\":\"英語では子音と母音を別々の音として数える。pig は p（プ）－ i（イ）－ g（グ）の3音である。この数え方ができるようになると、書き取りのとき「音の数だけ文字がある」という手がかりが使えるようになる。\"},{\"question\":\"次の音を聞いて書きなさい。　「バス（乗り物）」\",\"wrongAnswer\":\"bas\",\"trapExplanation\":\"カタカナの「バス」を音のとおりに文字にすると b－a－s になってしまう。日本語のカタカナ表記が、英語の母音のちがいを消してしまうことが原因。\",\"correctAnswer\":\"bus\",\"correctExplanation\":\"bus の母音は u（口をあまり開けない短い「ア」）である。カタカナの「バ」は英語の a の音に引きずられやすいが、実際の音は cup や run と同じ仲間である。カタカナ語になっている語は、必ずつづりを確かめてから書く。\"}]}",
"{\"id\":\"eigo_s011\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"長母音①：アルファベット読みになる母音\",\"description\":\"長母音は「文字の名前をそのまま言う音」だと理解し、複数のつづり方があることを知る\",\"intro\":\"cap は「キャップ」、cape は「ケイプ」。最後に e が付いただけで、まん中の a が文字の名前そのままの「エイ」に変わりました。この「文字の名前を言う音」が長母音です。長母音になる合図は3つあります。\",\"order\":511,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"長母音＝その母音字の「名前」をそのまま言う音（a→エイ、e→イー、i→アイ、o→オウ、u→ユー）。\",\"短母音より長くのばして発音する。cap（短）とcape（長）、hop（短）とhope（長）。\",\"同じ長母音の音でも、つづり方は何通りもある（「イー」＝ee, ea, e_e, ie, y）。\",\"つづりが違っても音が同じ語は、同音異義語になりやすい（meet／meat、see／sea）。\",\"長母音になる合図は3つ。①語末の e（マジックE）②母音字が2つ並ぶ③語末が母音字1つ（he, go）。\"],\"sections\":[{\"heading\":\"長母音とは何か\",\"body\":\"短母音は「文字の名前とはちがう短い音」だったが、長母音は「文字の名前をそのまま言う音」である。だから長母音のほうが覚えやすい。\\n\\n■ 5つの長母音\\na … エイ　cake, name, rain, day, baby\\ne … イー　he, see, tree, eat, meet\\ni … アイ　bike, nine, night, my, kind\\no … オウ　go, home, boat, snow, old\\nu … ユー　use, cute, music, new, blue\\n\\n■ 短母音との比べ方\\ncap（キャップ）／cape（岬・マント）\\nhop（ぴょんと跳ぶ）／hope（希望）\\nkit（道具一式）／kite（たこ）\\nnot（〜でない）／note（メモ）\\ncut（切る）／cute（かわいい）\\n右側はどれも語末に e が付いており、まん中の母音が長母音になっている。\\n\\n■ 長母音になる3つの合図\\n①語の終わりに e が付く（マジックE）… name, bike, home\\n②母音字が2つ並ぶ… rain, see, boat, meat\\n③1音節の語が母音字で終わる… he, she, we, go, no, hi, my\\n\\n★ ポイント：まず「短母音か長母音か」を決めてから読む。合図の3つを見つけられれば、初めて見る語でもかなり正確に読める。\"},{\"heading\":\"1つの音にいくつものつづり\",\"body\":\"英語のむずかしさは、同じ音を表すつづりが何通りもあることにある。読むときは困らないが、書くときにどのつづりかを選ぶ必要が出てくる。\\n\\n■ 「イー」の音\\nee … see, tree, green, week, sleep\\nea … eat, sea, read, teach, please\\ne_e … these, Chinese\\nie … field, piece\\ny（語末）… happy, city, easy\\n■ 「エイ」の音\\na_e … cake, name, game　／　ai … rain, train, wait　／　ay（語末）… day, play, say\\n■ 「アイ」の音\\ni_e … bike, nine　／　igh … night, light, high　／　y（語末）… my, sky, fly　／　ie … pie, tie\\n■ 「オウ」の音\\no_e … home, nose　／　oa … boat, coat, road　／　ow（語末）… snow, know, window\\n■ 「ユー」の音\\nu_e … use, cute　／　ue … blue, Tuesday　／　ew … new, few\\n\\n■ 位置に注目すると選びやすい\\n「エイ」は語のとちゅうなら ai、語の終わりなら ay。\\n「オウ」は語のとちゅうなら oa、語の終わりなら ow。\\nこのきまりを知っているだけで、rain／ray、boat／bow の書き分けができる。\\n\\n⚠ 注意：音が同じでつづりがちがう語（同音異義語）は入試で頻出。meet（会う）／meat（肉）、see（見る）／sea（海）、right（右）／write（書く）、know（知る）／no（いいえ）。意味とセットで覚える。\",\"figureId\":\"lf_eigoext01_011\",\"mangaId\":\"eigo_s011_xm\"}],\"trapExamples\":[{\"question\":\"「私は毎日肉を食べます。」の英文中の「肉」にあたる語を書きなさい。（I eat （　） every day.）\",\"wrongAnswer\":\"meet\",\"trapExplanation\":\"meat と meet は発音がまったく同じ（同音異義語）なので、音だけを頼りにすると、より先に習う meet（会う）のつづりが出てきてしまう。\",\"correctAnswer\":\"meat（I eat meat every day.）\",\"correctExplanation\":\"「肉」は meat、「会う」は meet である。ea と ee はどちらも「イー」と読むので、意味とつづりを結びつけて覚えるしかない。eat（食べる）と meat（肉）は同じ ea の仲間、と関連づけると思い出しやすい。\"},{\"question\":\"「雨」を表す語のつづりとして正しいのはどちらか。　ray／rain\",\"wrongAnswer\":\"ray\",\"trapExplanation\":\"「エイ」の音のつづりが ai と ay の2通りあることを知らないと、より短い ay をあてはめてしまう。ray（光線）は実在する語なので、まちがいに気づきにくい。\",\"correctAnswer\":\"rain\",\"correctExplanation\":\"「エイ」の音は、語のとちゅうでは ai（rain, train, wait, paint）、語の終わりでは ay（day, play, say, way）と書く。rain は最後に n という子音があるので、とちゅうの位置になり ai を使う。同じきまりで「オウ」も、とちゅうは oa（boat）、終わりは ow（snow）となる。\"}]}",
"{\"id\":\"eigo_s012\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"長母音②：マジックE（サイレントE）\",\"description\":\"語末の読まない e が、前の母音を長母音に変えるしくみを理解する\",\"intro\":\"hop は「ぴょんと跳ぶ」、hope は「望む」。読まない e が1つ付くだけで、音も意味も変わってしまいます。この e は自分では音を出さないのに前の母音を変えるので、マジックE と呼ばれます。しくみを知れば読み分けられます。\",\"order\":512,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「子音＋母音＋子音＋e」の形では、語末の e を読まず、前の母音がアルファベット読み（長母音）になる。\",\"このしくみをマジックE（サイレントE）という。cap→cape、hop→hope、kit→kite、cut→cute。\",\"e 自身は音を出さないが、他の母音の読み方を変える働きをする。\",\"例外：have, give, live, love, come, some の e は前の母音を長くしない。\",\"語尾に ing や ed を付けるときは、この e を取ってから付ける（make→making、hope→hoped）。\"],\"sections\":[{\"heading\":\"マジックE のしくみ\",\"body\":\"英語には「読まないのに大事な文字」がある。その代表がマジックE（サイレントE、または「魔法の e」）である。\\n\\n■ しくみ\\n「子音＋母音字＋子音＋e」の形になると、語末の e は発音されず、そのかわり前の母音字がアルファベット読み（長母音）になる。\\n例）cap（キャップ）→ cape（ケイプ）\\n　　hop（ホップ）→ hope（ホウプ）\\n　　kit（キット）→ kite（カイト）\\n　　cut（カット）→ cute（キュート）\\n　　not（ノット）→ note（ノウト）\\n　　tap（タップ）→ tape（テイプ）\\n　　pin（ピン）→ pine（パイン）\\n　　hat（ハット）→ hate（ヘイト）\\n\\n■ 覚え方\\n語末の e が、1つ手前の子音をとびこえて母音に「きみは名前で読みなさい」と魔法をかける、とイメージする。e 自身は音を出さないので声は聞こえないが、はたらきはしている。\\n\\n■ よく出る語\\nname, game, make, take, late, date, face, place\\ntime, nine, five, ride, white, write, life, wide\\nhome, nose, close, those, stone, hole\\nuse, cute, June, rule\\n\\n★ ポイント：語末に e があったら、まず前の母音を長母音で読んでみる。それで知っている語になれば正解であることが多い。\",\"figureId\":\"lf_eigoext01_012\"},{\"heading\":\"例外と、語尾を付けるときの変化\",\"mangaId\":\"eigo_s012_manga\",\"body\":\"■ マジックE がきかない語（例外）\\n語末に e があるのに、前の母音が短いままの語がある。数は限られているので覚えてしまう。\\nhave（ハヴ）… ×ヘイヴ\\ngive（ギヴ）／live（リヴ）… ×ライヴ（「生きている」の意味の形容詞 live はライヴと読む）\\nlove（ラヴ）／come（カム）／some（サム）／done（ダン）／none（ナン）\\nこのうち have・give・live・love は、英語では語末に v を1字だけで置かないというきまりのために、意味のない e が付いた語である。come・some・done・none の e は別の歴史的な事情によるもので、これも例外として覚える。\\n\\n■ なぜ e を付けるのか\\n英語では v で終わる語を作らない。だから have, give, live, love には音を出さない e が必要になる。\\n\\n■ ing や ed を付けるときは e を取る\\n語末の e はそのままにせず、取ってから付ける。\\nmake → making　／　take → taking　／　write → writing\\nhope → hoped → hoping　／　use → used → using\\nlive → lived → living　／　come → coming\\nただし、see → seeing のように母音が2つ並んでいる語は e を取らない。\\n\\n⚠ 注意：makeing、writeing のように e を残したまま ing を付けるのは、書き取りでいちばん多いまちがい。「e を取って ing」と口で唱えてから書く。\"}],\"trapExamples\":[{\"question\":\"「hope（望む）」に ing を付けて「望んでいる」の形にしなさい。\",\"wrongAnswer\":\"hopeing\",\"trapExplanation\":\"「動詞に ing を付ける」というきまりだけを覚えていると、語の形をそのまま残して ing をつなげてしまう。e が読まない文字なので、あってもなくても同じだと感じてしまうことも原因。\",\"correctAnswer\":\"hoping\",\"correctExplanation\":\"語末に読まない e がある語は、e を取ってから ing を付ける。make→making、take→taking、write→writing、use→using も同じ。なお hop（ぴょんと跳ぶ）に ing を付けると hopping と p を重ねる形になり、hoping（望んでいる）とは別の語になる。\"},{\"question\":\"「have」の a は長母音か、短母音か。\",\"wrongAnswer\":\"長母音（語末に e があるので「ヘイヴ」と読む）\",\"trapExplanation\":\"マジックE のきまりを覚えたばかりの段階では、語末に e があるすべての語にあてはめてしまう。have は最もよく使う語なので、この誤読は目立つ。\",\"correctAnswer\":\"短母音（「ハヴ」と読む）\",\"correctExplanation\":\"have, give, live, love, come, some, done はマジックE の例外で、前の母音は短いままである。このうち have, give, live, love の e は、英語では語末に v を1字で置かないというきまりのために付いた、音を出さない e である（come, some, done の e は別の歴史的な事情による）。数が少ないので例外としてまとめて覚える。\"}]}",
"{\"id\":\"eigo_s013\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"長母音③：母音字が2つ並ぶとき\",\"description\":\"ai・ea・oa・ee のように母音字が並ぶと、前の字が名前を言うきまりと例外を学ぶ\",\"intro\":\"rain の ai は「アイ」ではなく「エイ」と読みます。ローマ字の感覚で読むとまず通じません。母音字が2つ並ぶと、前の字が名前を言い、後ろの字は黙る。これが基本です。ただし ea には例外が多く、そこが勝負どころです。\",\"order\":513,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"母音字が2つ並ぶと、前の字がアルファベット読み、後ろの字は読まないことが多い（ai, ea, oa, ee, ie）。\",\"例）rain（レイン）、sea（スィー）、boat（ボウト）、tree（トゥリー）。\",\"ea には例外が多い。「イー」（eat, sea）／「エ」（bread, head）／「エイ」（great, break）。\",\"oo は「ウー」（school, food）と「ウ」（book, look, good）の2種類がある。\",\"このきまりはすべての語に当てはまるわけではない。当てはまらない語は語ごとに覚える。\"],\"sections\":[{\"heading\":\"前の母音字が名前を言う\",\"body\":\"母音字が2つ並んだとき、前の字をアルファベット読みし、後ろの字は読まない──これが基本のきまりである。英語圏の学校では「2つの母音が歩くと、前のほうが話をする」と教えられる。\\n\\n■ ai（エイ）\\nrain, train, wait, paint, tail, mail, afraid\\n■ ay（エイ・語末）\\nday, play, say, way, may, stay, today\\n■ ea（イー）\\neat, sea, tea, read, teach, please, easy, clean\\n■ ee（イー）\\nsee, tree, green, week, sleep, three, feet\\n■ oa（オウ）\\nboat, coat, road, soap, goat, toast\\n■ ie（イー／アイ）\\nfield, piece（イー）／pie, tie, lie（アイ・語末）\\n■ ui・ue（ウー・ユー）\\nfruit, juice／blue, true, Tuesday\\n\\n■ 語の中と語の終わりで使い分ける\\n「エイ」…とちゅうは ai、終わりは ay\\n「オウ」…とちゅうは oa、終わりは ow\\n「イー」…とちゅうは ea か ee、終わりは ee（see, three）か y（happy）\\n\\n★ ポイント：知らない語に出会ったら、まず母音字の並びをさがす。並んでいれば長母音で読んでみる、というのが読解の第一手である。\",\"figureId\":\"xf_eigo_s013\"},{\"heading\":\"きまりが当てはまらない語\",\"body\":\"このきまりが当てはまらない語もたくさんあり、それらは例外である。よく出る例外は覚えてしまうしかない。\\n\\n■ ea の3つの読み方\\n①イー（原則どおり）… eat, sea, tea, read（現在形）, teach, please\\n②エ（短い音）… bread, head, ready, heavy, weather, breakfast, sweater\\n③エイ… great, break, steak\\nとくに②は身近な語が多いので要注意。read は現在形が「リード」、過去形が「レッド」と、同じつづりで読み方が変わる。\\n\\n■ oo の2つの読み方\\n①ウー（長い）… school, food, moon, room, soon, too, zoo\\n②ウ（短い）… book, look, good, cook, foot, wood, stood\\nk で終わる語は短い「ウ」になることが多い、と覚えると便利である。\\n\\n■ ou の読み方もいろいろ\\nout, house, about（アウ）／you, soup, group（ウー）／country, young, touch（ア）／could, would, should（ウ）\\n\\n⚠ 注意：例外語は「読み」と「意味」をセットにして声に出して覚える。bread（パン）を「ブリード」と読んでしまうと、聞き取りでも書き取りでも通じない。\",\"mangaId\":\"eigo_s013_xm\"}],\"trapExamples\":[{\"question\":\"「bread（パン）」の ea はどのように読むか。\",\"wrongAnswer\":\"イー（「ブリード」と読む）\",\"trapExplanation\":\"「母音字が2つ並んだら前の字を名前で読む」というきまりを覚えたばかりだと、eat や sea と同じように ea を「イー」と読んでしまう。bread は身近な語なのに例外なので、まちがえたまま覚えやすい。\",\"correctAnswer\":\"エ（短い音。「ブレッド」と読む）\",\"correctExplanation\":\"ea を短く「エ」と読む語は数が限られている。bread, head, ready, heavy, weather, breakfast, sweater が代表例で、いずれも日常でよく使う語である。まとめて声に出して覚えてしまうのがいちばん早い。\"},{\"question\":\"次の2語の oo は同じ読み方か。　book ／ school\",\"wrongAnswer\":\"同じ（どちらも「ウー」とのばす）\",\"trapExplanation\":\"つづりが同じ oo なので、読み方も同じだと考えてしまう。日本語のカタカナ表記でも「ブック」「スクール」と、どちらも「ウ」に見えるため気づきにくい。\",\"correctAnswer\":\"ちがう（book は短い「ウ」、school はのばす「ウー」）\",\"correctExplanation\":\"oo には短い「ウ」（book, look, good, cook, foot）と長い「ウー」（school, food, moon, room, too, zoo）の2つの読み方がある。k で終わる語は短くなることが多い。読みのちがいは書き取りには影響しないが、聞き取りと音読では区別が必要である。\"}]}",
"{\"id\":\"eigo_s014\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重母音①：oi／oy と ou／ow\",\"description\":\"発音のとちゅうで口の形が動く母音を、動きの向きとして理解する\",\"intro\":\"boy を「ボイ」、house を「ハウス」と読めば通じそうに思えますが、英語では口の形が動きながら1つの音になります。しかも同じ音でも、語のとちゅうと語末ではつづりが変わります。その使い分けを整理します。\",\"order\":514,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"二重母音＝1つの母音から別の母音へ、口の形が動きながら出す音。\",\"oi／oy（オイ）… とちゅうは oi（coin, point）、語末は oy（boy, toy, enjoy）。\",\"ou／ow（アウ）… とちゅうは ou（house, out, about）、語末や語中の一部は ow（now, how, town, brown）。\",\"ow には「オウ」と読む場合もある（snow, know, show, window）。意味で見分ける。\",\"二重母音は日本語の「アイ・オイ・アウ」より、なめらかに1つの音としてつなげる。\"],\"sections\":[{\"heading\":\"口の形が動く母音\",\"body\":\"二重母音とは、1つの母音から別の母音へ口の形を動かしながら出す音のことである。始まりの音と終わりの音がちがうので、日本語の短い母音とは感じがちがう。\\n\\n■ oi／oy（オイ）\\n口を丸くして「オ」で始まり、口を横に開いて「イ」で終わる。\\nとちゅう… coin, point, join, oil, voice, boil, noise\\n語末… boy, toy, joy, enjoy, soy\\n■ ou／ow（アウ）\\n口を大きく開けて「ア」で始まり、口をすぼめて「ウ」で終わる。\\nとちゅう… house, out, about, mouth, cloud, sound, count, mountain\\n語末・語中… now, how, cow, town, down, brown, flower\\n\\n■ 位置で使い分ける\\noi と oy、ou と ow の関係は、ai と ay、oa と ow の関係と同じである。語のとちゅうでは i や u を使い、語の終わりでは y や w を使う。英語では語の最後に i や u を置きたがらない、というくせがあるためである。\\n\\n★ ポイント：二重母音は2つの音を続けて言うのではなく、口を動かしながら1つの音として出す。boy を「ボ・イ」と切らずに「ボイ」となめらかに出す。\",\"figureId\":\"lf_eigoext01_014\"},{\"heading\":\"ow の2つの読み方\",\"body\":\"ow には2通りの読み方があり、これがまちがえやすい。\\n\\n■ アウと読む ow\\nnow（今）, how（どのように）, cow（牛）, town（町）, down（下へ）, brown（茶色）, flower（花）, crowd（群衆）\\n■ オウと読む ow\\nsnow（雪）, know（知っている）, show（見せる）, low（低い）, slow（おそい）, window（窓）, yellow（黄色）, grow（育つ）, throw（投げる）\\n\\n■ 見分けるヒント\\n・語末が -ow で2音節の語（window, yellow, follow, tomorrow）は「オウ」が多い。\\n・1音節で -own, -owd の形（town, down, brown, crowd）は「アウ」が多い。ただし known, shown, own は「オウ」なので例外。\\n・結局のところ、語ごとに覚えるのがいちばん確実である。\\n\\n■ 意味で確かめる\\nHow are you?（アウ）／I know it.（オウ）\\nSit down.（アウ）／It is snowing.（オウ）\\n\\n⚠ 注意：know（知っている）と now（今）は、つづりが1字ちがうだけで読み方も意味もまったくちがう。know は k を読まないので「ノウ」、now は「ナウ」である。書き取りでよく混同する。\",\"mangaId\":\"eigo_s014_xm\"}],\"trapExamples\":[{\"question\":\"「I know his name.」の know の読み方を答えなさい。\",\"wrongAnswer\":\"ナウ（now と同じ読み方をした）\",\"trapExplanation\":\"know と now はつづりが1字しかちがわず、どちらもよく出る語なので混同する。さらに know の頭の k を読まないことを知らないと、「クノウ」と読んでしまう場合もある。\",\"correctAnswer\":\"ノウ（[noʊ]）\",\"correctExplanation\":\"know の k は読まない文字（サイレントレター）で、ow は「オウ」と読む。だから know は no（いいえ）とまったく同じ発音になる。now（今）は「ナウ」で別の語である。knife, knee, knock も同じく k を読まない仲間。\"},{\"question\":\"「コイン」を表す英単語のつづりとして正しいのはどちらか。　coyn ／ coin\",\"wrongAnswer\":\"coyn\",\"trapExplanation\":\"boy や toy で oy を先に習うため、「オイ」の音はすべて oy と書くと思いこんでしまう。位置によって使い分けるというきまりを知らないと必ず引っかかる。\",\"correctAnswer\":\"coin\",\"correctExplanation\":\"「オイ」の音は、語のとちゅうでは oi（coin, point, join, oil, voice）、語の終わりでは oy（boy, toy, joy, enjoy）と書く。英語は語末に i を置きたがらないため、y に変える。同じきまりが ai／ay、ou／ow にもあてはまる。\"}]}",
"{\"id\":\"eigo_s015\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重母音②：au／aw と oo\",\"description\":\"au・aw の「オー」と、oo の長短2種類の読み分けを整理する\",\"intro\":\"book と school はどちらも oo なのに、「ブック」と「スクール」で長さがちがいます。walk の l に至っては読みません。ここでは oo の2つの読み方と、「オー」と読むつづりをまとめて片づけます。\",\"order\":515,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"au／aw は「オー」と読む。とちゅうは au（autumn, because）、語末は aw（saw, draw, law）。\",\"all・alk・alt の a も「オー」になる（ball, call, small, walk, talk, salt）。\",\"oo は長い「ウー」（school, food, moon）と短い「ウ」（book, look, good）の2種類。\",\"-ook で終わる語（book, look, cook, took）はほぼ短い「ウ」。\",\"walk・talk の l は読まない。この2語は「ウォーク」「トーク」と読む。\"],\"sections\":[{\"heading\":\"au／aw と al の「オー」\",\"body\":\"日本語の「オー」に近い音を表すつづりは何通りもある。まとめて整理しておく。\\n\\n■ au（語のとちゅう）\\nautumn（秋）, because（なぜなら）, August（8月）, sauce（ソース）, daughter（むすめ）, caught（catch の過去形）\\n■ aw（語の終わり・語中）\\nsaw（see の過去形）, draw（かく）, law（法律）, straw（ストロー）, lawn（しばふ）, dawn（夜明け）\\n■ all の a\\nball, call, small, tall, wall, fall, all\\n■ alk・alt の a\\nwalk, talk, chalk（l は読まない）／salt, halt\\n\\n■ 位置のきまりは同じ\\nau と aw の使い分けも、ai／ay、oi／oy と同じ考え方である。語のとちゅうは u、語の終わりは w。\\n\\n■ 注意すべき語\\nbecause は日本人が読みまちがえやすい語で、「ビコーズ」と読む。「ビカウス」ではない。\\ndaughter は gh を読まないので「ドーター」。\\ncaught（catch の過去形）、bought（buy の過去形）、thought（think の過去形）も gh を読まず「コート」「ボート」「ソート」に近い音になる。\\n\\n★ ポイント：walk と talk の l は読まない。「ウォーク」「トーク」と読む。work（仕事）とは別の語なので注意する。\"},{\"heading\":\"oo の長短を見分ける\",\"body\":\"oo は英語の中でもとくに読み分けが必要なつづりである。\\n\\n■ 長い「ウー」\\nschool, food, moon, room, soon, too, zoo, pool, cool, tool, roof, noon, afternoon, choose\\n■ 短い「ウ」\\nbook, look, good, cook, took, foot, wood, stood, hook, shook\\n\\n■ 見分けの目安\\n①-ook で終わる語はほぼ短い「ウ」… book, look, cook, took, shook, hook\\n②-ood は分かれる… good, stood, wood は短い／food, mood は長い\\n③-oon, -ool, -oom は長い… moon, soon, school, pool, room\\n\\n■ 音のちがい\\n長い「ウー」は口を強くすぼめてのばす。短い「ウ」は口の力を抜いて短く出す。日本語の「ウ」は短い「ウ」に近い。\\n\\n■ よく出る組み合わせ\\ngo to school（学校へ行く）／read a book（本を読む）\\nfoot（足）の複数形は feet。food（食べ物）とは別の語。\\n\\n⚠ 注意：foot（足・単数）と feet（足・複数）と food（食べ物）を混同しないこと。つづりも意味もちがう3語である。\",\"figureId\":\"xf_eigo_s015\",\"mangaId\":\"eigo_s015_xm\"}],\"trapExamples\":[{\"question\":\"「私は毎日歩いて学校へ行きます。」の「歩く」にあたる語 walk の読み方を答えなさい。\",\"wrongAnswer\":\"ウォルク（l をはっきり発音した）\",\"trapExplanation\":\"つづりに l があるので、そのまま音にしてしまう。日本語のカタカナ語「ウォーキング」でも「ウォ」と「キ」のあいだに音がないため、l を入れるとかえって不自然になることに気づきにくい。\",\"correctAnswer\":\"ウォーク（[wɔːk]。l は読まない）\",\"correctExplanation\":\"walk, talk, chalk の l は読まない文字である。walk は「ウォーク」、talk は「トーク」と読む。似た形の work（仕事・働く）は「ワーク」で、母音の音がちがう別の語なので混同しないこと。\"},{\"question\":\"「食べ物」を表す語のつづりを書きなさい。\",\"wrongAnswer\":\"fut\",\"trapExplanation\":\"「フード」という音を短くとらえて、u の1字で書いてしまう。また foot（足）と food（食べ物）が音でもつづりでも似ているため、混同することもある。\",\"correctAnswer\":\"food\",\"correctExplanation\":\"food は oo を長い「ウー」と読む語で、school, moon, room と同じ仲間である。foot（足・単数）は同じ oo でも短い「ウ」で、意味も別。食べ物 food、足 foot、複数の足 feet の3語をまとめて確かめておく。\"}]}",
"{\"id\":\"eigo_s016\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"r のついた母音：ar／or／er／ir／ur\",\"description\":\"母音字のあとに r が来ると音が変わるきまりを、5つのつづりで整理する\",\"intro\":\"car の ar、bird の ir、turn の ur。母音字のあとに r が来ると、短母音でも長母音でもない別の音に変わります。しかも er・ir・ur は音では区別できません。つづりで覚えるしかない、という割り切りが要る単元です。\",\"order\":516,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"母音字のあとに r が来ると、短母音でも長母音でもない特別な音になる。\",\"ar は「アー」（car, park, star, hard, garden）。\",\"or は「オー」（for, short, morning, north, sport）。\",\"er・ir・ur はすべて同じ「アー」に近い音（her, bird, turn）。この3つは音では区別できない。\",\"w のあとの ar は「オー」（warm, war）、w のあとの or は「アー」（work, world, word）になる。\"],\"sections\":[{\"heading\":\"5つのつづりと音\",\"body\":\"母音字のあとに r が来ると、その母音は短母音でも長母音でもない特別な音になる。これを r 音性母音という。英語らしい音の代表なので、しっかり練習する。\\n\\n■ ar（アー）\\ncar, park, star, hard, farm, garden, market, party, start, dark\\n■ or（オー）\\nfor, short, morning, north, sport, story, corner, born, or\\n■ er（アー）\\nher, teacher, water, sister, brother, winter, summer, dinner, letter, computer\\n■ ir（アー）\\nbird, girl, first, third, shirt, dirty, birthday, circle\\n■ ur（アー）\\nturn, hurt, church, nurse, purple, Thursday, burn, return\\n\\n■ er・ir・ur は同じ音\\nつづりは3通りあるが、音はほとんど同じである。だから「音を聞いてつづりを決める」ことができない。書き取りでは語ごとに覚える必要がある。\\n例）her（彼女の）／bird（鳥）／turn（曲がる）は、母音の音が同じ。\\n\\n★ ポイント：er は語の終わりに多い（teacher, water, sister）。「〜する人」を表す -er、比較級の -er も同じ音である。\",\"figureId\":\"xf_eigo_s016\"},{\"heading\":\"例外と、まちがえやすい語\",\"body\":\"■ w のあとでは音が入れかわる\\nw のあとの ar は「オー」になる。\\n　warm（あたたかい）, war（戦争）, toward, warn\\nw のあとの or は「アー」になる。\\n　work（働く）, world（世界）, word（語）, worm（虫）, worse\\nつまり warm は「ウォーム」、work は「ワーク」である。この2語は入れかわりやすいので、セットで覚える。\\n\\n■ walk／work／wark\\nwalk（歩く）＝ウォーク（l は読まない）\\nwork（働く）＝ワーク\\nこの2語は日本語のカタカナでは近いが、英語では母音がまったくちがう。\\n\\n■ 語の終わりの -er, -or, -ar\\n「〜する人・〜するもの」を表す語尾は3通りある。\\n-er … teacher, singer, player, writer, driver, worker\\n-or … doctor, actor, visitor, sailor\\n-ar … 数は少ない（liar など）\\nどれも同じ「アー」の音なので、つづりは語ごとに覚える。doctor を doctar、teacher を teachor と書くまちがいが多い。\\n\\n⚠ 注意：first（1番目）, third（3番目）, thirteen（13）, thirty（30）はすべて ir を使う。これらは数の語として入試頻出なので、まとめて確認する。\",\"mangaId\":\"eigo_s016_xm\"}],\"trapExamples\":[{\"question\":\"「医者」を表す英単語を書きなさい。\",\"wrongAnswer\":\"docter\",\"trapExplanation\":\"「〜する人」を表す語尾を -er と覚えているため、doctor にもあてはめてしまう。er と or は発音がまったく同じなので、音を頼りにすると区別できない。\",\"correctAnswer\":\"doctor\",\"correctExplanation\":\"「〜する人」の語尾には -er（teacher, singer, player）と -or（doctor, actor, visitor）の2通りがあり、音は同じ「アー」である。音では決められないので、語ごとにつづりを覚えるしかない。doctor, actor, visitor, sailor をまとめて覚えておく。\"},{\"question\":\"次の2語の母音の音は同じか。　warm ／ work\",\"wrongAnswer\":\"同じ（どちらも w のあとなので同じ音になる）\",\"trapExplanation\":\"w のあとに r 付きの母音が来る語だという点が共通しているため、同じ音になると考えてしまう。ar と or の通常の読みをそのままあてはめても、逆の答えになる。\",\"correctAnswer\":\"ちがう（warm は「ウォーム」、work は「ワーク」）\",\"correctExplanation\":\"w のあとでは音が入れかわる。ふつう ar は「アー」だが w のあとでは「オー」になり（warm, war）、ふつう or は「オー」だが w のあとでは「アー」になる（work, world, word）。この入れかわりは覚えるしかないが、warm と work の2語を代表として押さえておけば思い出せる。\"}]}",
"{\"id\":\"eigo_s017\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"子音連結①：語頭の bl・cl・br・cr など\",\"description\":\"子音が2つ続く語頭の音を、母音を入れずにつなげて読めるようにする\",\"intro\":\"blue を「ブルー」、play を「プレイ」と言ってしまうのは、日本語が「子音＋母音」でできているからです。英語は子音を続けて出せます。b と l のあいだに「ウ」を入れないこと。ここが日本人の最大の壁です。\",\"order\":517,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"英語は子音を続けて発音できる。日本語は「子音＋母音」が原則なので、ここが最大の壁になる。\",\"l 型：bl（blue）、cl（class）、fl（flower）、gl（glass）、pl（play）、sl（sleep）。\",\"r 型：br（brother）、cr（cry）、dr（drink）、fr（friend）、gr（green）、pr（present）、tr（train）。\",\"つづりは2字でも、音は2つ。あいだに「ウ」や「オ」を入れない（×ブルー・ライト）。\",\"語頭に子音は最大3つまで並ぶ（str-, spr-, scr-, spl-）。\"],\"sections\":[{\"heading\":\"日本語との決定的なちがい\",\"body\":\"日本語は「か・き・く・け・こ」のように、子音のあとに必ず母音が付く。だから子音だけを続けて出す習慣がない。一方、英語は子音を2つでも3つでも続けて出せる。ここが日本人にとって最大の壁である。\\n\\n■ 語頭に子音が2つ並ぶ形\\nl を含むもの：bl, cl, fl, gl, pl, sl\\n　blue, black, blackboard／class, clean, clock, close／flower, fly, floor／glass, glad／play, please, plane／sleep, slow\\nr を含むもの：br, cr, dr, fr, gr, pr, tr\\n　brother, bread, bring／cry, cross／drink, dream, drive／friend, from, fruit／green, great, grow／present, pretty／train, tree, try\\n\\n■ まちがえやすい発音\\nblue を「ブルー」と読むと、b と l のあいだに「ウ」が入ってしまい、英語では別の語のように聞こえる。正しくは b と l をすきまなく続けて出す。\\ntrain を「トレイン」と読むと t のあとに「オ」が入る。t と r を続けて出す。\\n\\n■ 練習の方法\\n①まず子音2つだけを続けて言う（bl, bl, bl）\\n②そのあとに母音をつける（blu-）\\n③語全体を言う（blue）\\n\\n★ ポイント：カタカナ語になっている語ほどまちがえやすい。「ブラック」「クラス」「グラス」「プレゼント」は、すべて日本語では母音が入っている。\",\"figureId\":\"lf_eigoext01_017\",\"mangaId\":\"eigo_s017_xm\"},{\"heading\":\"書き取りで落とさないために\",\"body\":\"子音連結は、発音だけでなく書き取りでも落としやすい。日本語の耳では、2つ目の子音が聞こえないことがあるためである。\\n\\n■ 落としやすい文字\\nclass を cass、friend を fiend、green を geen と書いてしまう例が多い。声に出して「ク・ラ」と2つの音があることを確かめてから書く。\\n\\n■ l と r の書き分け\\n子音連結では l と r のどちらが入るかで意味が変わる。\\nglass（コップ・ガラス）／grass（草）\\nfly（飛ぶ）／fry（あげる）\\nplay（遊ぶ）／pray（いのる）\\nclown（道化師）／crown（王冠）\\nblue（青）／brew（作る）\\nどれも入試や英検で問われる組み合わせである。\\n\\n■ 意味から判断する\\nI drink a glass of milk.（コップ1ぱいの牛乳）→ glass\\nThe dog is running on the grass.（しばふの上）→ grass\\nBirds can fly.（飛ぶ）→ fly\\n\\n⚠ 注意：日本語のカタカナ語は l と r を区別しないので、「グラス」「フライ」といったカタカナ語からつづりを決めてはいけない。必ず意味から決める。\"}],\"trapExamples\":[{\"question\":\"「牛乳をコップ1ぱい飲む」の「コップ」にあたる語を書きなさい。（I drink a （　） of milk.）\",\"wrongAnswer\":\"grass\",\"trapExplanation\":\"日本語では l と r をどちらも「ラ行」で表すため、「グラス」という音からつづりを決めようとすると、glass と grass のどちらも同じに思える。grass のほうが先に頭にうかぶ人も多い。\",\"correctAnswer\":\"glass（I drink a glass of milk.）\",\"correctExplanation\":\"glass はコップ・ガラス、grass は草・しばふである。a glass of milk（コップ1ぱいの牛乳）という決まった言い方で覚える。同じ組み合わせに fly（飛ぶ）／fry（あげる）、play（遊ぶ）／pray（いのる）、clown（道化師）／crown（王冠）がある。\"},{\"question\":\"「友だち」を表す英単語を書きなさい。\",\"wrongAnswer\":\"fiend\",\"trapExplanation\":\"friend は「フレンド」と読むが、日本語の耳では r の音が母音にまぎれて聞こえにくい。さらに ie の部分を「エ」と読むという例外もあり、音からつづりを組み立てようとすると必ずくずれる。\",\"correctAnswer\":\"friend\",\"correctExplanation\":\"friend は f－r の子音連結で始まり、ie を「エ」と読む例外語である。fr の連結を落とさないよう「フ・レ」ではなく「フル」と続けて音を確かめてから書く。fiend は実在する別の語（悪魔）なので、まちがえても気づきにくい。\"}]}",
"{\"id\":\"eigo_s018\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"子音連結②：s で始まる連結と3つ続く音\",\"description\":\"sk・sp・st などの s 連結と、str・spr のように3つ続く形を練習する\",\"intro\":\"street には s・t・r と子音が3つ続きます。カタカナの「ストリート」は母音が3つも入っていて、音の数がまるでちがいます。s で始まる連結を、あいだに母音をはさまずに出せるようにしていきましょう。\",\"order\":518,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"s＋子音の形：sc/sk（school）、sm（small）、sn（snow）、sp（sport）、st（stop）、sw（swim）、sl（sleep）。\",\"s＋子音＋子音の形：str（street）、spr（spring）、scr（scream）、spl（splash）、squ（square）。\",\"s のあとの p・t・k は、息を強く出さずに濁ったように聞こえる（sports は「スポーツ」ではなく「スボーツ」に近い）。\",\"語末の子音連結も多い：-st（best）、-nd（and）、-nt（want）、-mp（jump）、-nk（think）、-sk（ask）。\",\"日本語のカタカナ語は必ず母音を入れてしまうので、カタカナで確認しない。\"],\"sections\":[{\"heading\":\"s で始まる子音連結\",\"body\":\"s は、ほかの子音と組んで語の最初に立つことがとても多い文字である。\\n\\n■ s＋子音（2つ）\\nsc/sk … school, sky, skate, skirt\\nsm … small, smile, smoke\\nsn … snow, snake\\nsp … sport, speak, spring, spoon\\nst … stop, study, star, student, stand\\nsw … swim, sweet, sweater\\nsl … sleep, slow\\n\\n■ s＋子音＋子音（3つ）\\nstr … street, strong, string, strange\\nspr … spring, spread\\nscr … scream, screen\\nspl … split\\nsqu … square\\n\\n英語の語頭に立てる子音は最大3つで、しかも1つ目は必ず s である。これは英語の音のきまりで、例外はない。\\n\\n■ 発音の注意\\ns のあとの p・t・k は息を強く出さない。だから speak の p は、日本語の「ペ」より「ベ」に近く聞こえる。student の t も「デュ」に近く聞こえることがある。\\n\\n★ ポイント：street は s－t－r の3つの子音が続く。「ストリート」とカタカナで言うと母音が3つも入ってしまう。3子音をひとかたまりで練習する。\",\"figureId\":\"xf_eigo_s018\",\"mangaId\":\"eigo_s018_xm\"},{\"heading\":\"語末の子音連結\",\"body\":\"語の終わりにも子音が続く。英語は語末に最大4つまで子音を並べることができる（texts など）。\\n\\n■ よく出る語末の連結\\n-st … best, first, last, must, fast, just, west\\n-nd … and, hand, find, friend, second, kind\\n-nt … want, front, point, student, present\\n-mp … jump, camp, lamp\\n-nk … think, thank, drink, pink, bank\\n-sk … ask, desk, task\\n-lk … milk, walk（l は読まない）\\n-nch … lunch, bench\\n-ct … act, fact, correct\\n\\n■ 落としやすい音\\nand を「アン」、hand を「ハン」と発音・表記してしまうと d が消える。英語では最後の d までしっかり形にする（強く発音はしないが、口の形は作る）。\\n\\n■ 複数形や過去形が付くとさらに増える\\ndesk → desks（-sks の3子音）\\nask → asked（-skt の3子音）\\ntext → texts（-ksts の4子音）\\n最後まで言い切ろうとせず、口の形だけ作れば十分である。\\n\\n⚠ 注意：書き取りでは、聞こえにくい語末の子音こそ落としやすい。「意味の通る形になっているか」を最後に確認する（friend の d、second の d を落とすと別の語になる）。\"}],\"trapExamples\":[{\"question\":\"「通り・street」の音はいくつの子音で始まっているか。\",\"wrongAnswer\":\"2つ（st の2文字なので2つ）\",\"trapExplanation\":\"つづりの「st」だけを見て数えてしまい、そのあとの r を母音の一部だと考えてしまう。カタカナの「ストリート」では「ス・ト・リ」と母音が入るため、なおさら数えにくい。\",\"correctAnswer\":\"3つ（s／t／r）\",\"correctExplanation\":\"street は s－t－r の3つの子音が母音なしで続いている。英語で語頭に置ける子音は最大3つで、そのときの1つ目は必ず s である（str-, spr-, scr-, spl-）。日本語には子音を3つ続ける形がないので、意識して練習する必要がある。\"},{\"question\":\"「私は2番目に着きました。」の「2番目」にあたる語を書きなさい。\",\"wrongAnswer\":\"secon\",\"trapExplanation\":\"語末の -nd は、d の音がほとんど聞こえないため、聞いたとおりに書くと d が落ちる。and を「アン」、hand を「ハン」と覚えている人ほどこの落とし方をする。\",\"correctAnswer\":\"second\",\"correctExplanation\":\"語末の -nd は、d をはっきり響かせなくても文字としては必ず書く。and, hand, find, friend, second, kind が同じ形である。書き取りでは、語末の子音を落としていないかを最後に必ず点検する。\"}]}",
"{\"id\":\"eigo_s019\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重子音字①：sh と ch\",\"description\":\"2文字で1つの音を表すつづり sh・ch・tch のきまりを覚える\",\"intro\":\"she の sh は、s と h を別々に読むわけではありません。2文字で1つの音です。では watch はなぜ tch と3文字も使うのでしょうか。実はここにも、直前の母音がからんだきまりがあります。まとめて片づけましょう。\",\"order\":519,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"2文字で1つの音を表すつづりを二重子音字という（sh, ch, th, ph, wh, ck, ng）。\",\"sh は「シュ」（she, fish, shop, wash, English）。\",\"ch は「チ」（chair, lunch, teach, children, watch）。\",\"短母音のすぐあとで「チ」の音が語末に来るときは tch と書く（watch, catch, kitchen）。\",\"ch を「ク」と読む語もある（school, Christmas, stomach）。ギリシャ語から来た語に多い。\"],\"sections\":[{\"heading\":\"sh と ch の音\",\"mangaId\":\"eigo_s019_manga\",\"body\":\"2つの文字が組んで1つの音を表すつづりを二重子音字（digraph）という。sh・ch・th・ph・wh・ck・ng がその代表で、どれも「2文字で1音」である。文字の数と音の数がずれるので、書き取りのときに意識が必要になる。\\n\\n■ sh（シュ）\\n語頭… she, shop, ship, short, shoe, shine\\n語中・語末… fish, wash, dish, English, finish, brush, push\\nくちびるを前に出して、息を細く出す。日本語の「シ」より息の音が強い。\\n\\n■ ch（チ）\\n語頭… chair, cheese, children, chocolate, church, cherry\\n語中・語末… lunch, teach, beach, much, rich, March\\n舌を上あごにつけてから、はじくように離す。\\n\\n■ 音の数を数える\\nfish は f－i－sh の3音（文字は4つ）。\\nlunch は l－u－n－ch の4音（文字は5つ）。\\n文字数と音の数がちがうことをつねに意識する。\\n\\n★ ポイント：sh は「静かに」の合図（Shh!）と同じ音、ch は電車の音（チャッチャッ）と同じ音、というふうに身近な音と結びつけて覚えると忘れにくい。\"},{\"heading\":\"tch のきまりと、ch の例外\",\"body\":\"■ いつ tch と書くか\\n語末で「チ」の音になるとき、直前が短母音1字なら tch と書く。\\n　watch, catch, match, kitchen, witch\\n直前が長母音や子音なら ch のままでよい。\\n　teach（ea の長母音）, beach, each／lunch（n という子音のあと）, March, bench\\nただし much, such, rich, which は短母音のあとでも ch のままの例外である。\\n\\n■ 同じきまりが ck にもある\\n語末で「ク」の音になるとき、直前が短母音1字なら ck と書く。\\n　back, black, clock, duck, kick, sick, rock\\n長母音や子音のあとは k のままである。\\n　book（oo）, week, milk（l のあと）, think\\n\\n■ ch を「ク」と読む語\\nギリシャ語からきた語では ch を「ク」と読む。\\n　school, Christmas, stomach（胃）, chorus, character, headache（頭痛）\\nschool は「スクール」であって「シュクール」ではない。数は多くないので、出てきたら覚える。\\n\\n■ ch を「シュ」と読む語\\nフランス語からきた語では「シュ」になる。\\n　machine（機械）, chef, Chicago\\nmachine は「マシーン」と読む。\\n\\n⚠ 注意：watch を wach、catch を cach と書くまちがいが非常に多い。「短い母音のあとの語末のチは tch」と唱えて覚える。\",\"figureId\":\"xf_eigo_s019\"}],\"trapExamples\":[{\"question\":\"「時計・腕時計」を表す英単語を書きなさい。\",\"wrongAnswer\":\"wach\",\"trapExplanation\":\"「チ」の音を ch と書くと習うため、そのまま当てはめてしまう。音だけを聞いても t は聞こえないので、t が必要だとは気づけない。\",\"correctAnswer\":\"watch\",\"correctExplanation\":\"語末の「チ」の音は、直前が短母音1字のときは tch と書く。watch, catch, match, kitchen が同じ形。teach や lunch のように直前が長母音や子音の場合は ch のままでよい。同じきまりが「ク」の音の ck（back, clock）にもあてはまる。\"},{\"question\":\"「school」の ch はどのように読むか。\",\"wrongAnswer\":\"チ（「シュクール」「チュクール」のように読む）\",\"trapExplanation\":\"ch＝「チ」と1対1で覚えてしまうと、例外の語に出会ったときに対応できない。school はよく使う語なので、実際にはカタカナの「スクール」で覚えていて、つづりと音の対応を考えたことがない場合も多い。\",\"correctAnswer\":\"ク（[k]。「スクール」と読む）\",\"correctExplanation\":\"ギリシャ語からきた語では ch を「ク」と読む。school, Christmas, stomach, chorus, headache が代表例である。また、フランス語からきた machine では「シュ」と読む。ch には「チ・ク・シュ」の3通りがあると整理しておく。\"}]}",
"{\"id\":\"eigo_s020\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重子音字②：ph・ck・ng\",\"description\":\"ph が f の音になる理由と、ck・ng の使い方を整理する\",\"intro\":\"phone には f が1文字もないのに「フォン」と読みます。ph が f の音になるからです。sing の ng も「ング」と2つに切ってはいけません。-ing の形はこれから何百回も出てくるので、今のうちに音を固めます。\",\"order\":520,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"ph は f と同じ音（phone, photo, elephant, alphabet, dolphin）。ギリシャ語からきた語に多い。\",\"ck は k と同じ音。短母音1字のすぐあとの語末で使う（back, clock, duck）。\",\"ng は「ング」ではなく、鼻に抜ける1つの音（sing, long, king, spring）。\",\"-ing の形（現在進行形・動名詞）もこの ng の音。「イング」と2つに切らない。\",\"nk（think, thank, pink）も同じ鼻の音＋k の組み合わせ。\"],\"sections\":[{\"heading\":\"ph と ck\",\"body\":\"■ ph は f の音\\nph は2文字で f と同じ音を表す。ギリシャ語からきた語に多い。\\n　phone（電話）, telephone, photo（写真）, photograph, elephant（ゾウ）, alphabet, dolphin（イルカ）, graph, nephew（おい）\\nなぜ f と書かないのかというと、もともとギリシャ語の文字を写した名残だからである。理由は覚えなくてよいが、「ph＝f」と「ギリシャ語系の語に多い」ことは覚えておく。\\n\\n■ ck は k の音\\nck も2文字で1つの「ク」の音を表す。使う場所が決まっている。\\n◎短母音1字のすぐあと、語末で使う\\n　back, black, clock, duck, kick, sick, rock, pocket, chicken\\n◎長母音・二重母音・子音のあとは k だけ\\n　book, week, look, milk, think, bank, dark, park, make, bike\\n\\n■ 見分け方の練習\\n「マク」の音で終わる語… 直前が短い a なら ck（black）\\n「メイク」の音で終わる語… 長母音なので k（make）\\n「ミルク」… 直前が l という子音なので k（milk）\\n\\n★ ポイント：ck と tch は、まったく同じきまりで使い分ける。「短母音1字のすぐあと、語末」のときだけ2文字になる。\",\"mangaId\":\"eigo_s020_xm\"},{\"heading\":\"ng の音\",\"body\":\"■ ng は1つの音\\nng は「ン」と「グ」の2つではなく、鼻に息を抜きながら出す1つの音である。日本語の「りんご」の「ん」の音に近い。\\n　sing, song, long, king, ring, spring, strong, young, thing, morning, English\\n\\n■ -ing の形\\n動詞に付ける -ing も同じ音である。\\n　playing, running, swimming, studying, going, coming\\n日本語では「プレイング」とカタカナで書くが、最後の「グ」を強く出す必要はない。むしろ強く出すと不自然になる。\\n\\n■ nk の音\\nthink, thank, drink, pink, bank, sink も、n の部分が同じ鼻の音になる。ng の仲間として覚える。\\n\\n■ 語の中の ng\\nfinger（指）, England, hungry, angry は、ng のあとに g の音がもう1つ聞こえる。\\n一方 singer（歌手）, ringing は g の音が加わらない。\\nこの区別は入試では問われないが、音読のときに知っていると自然に読める。\\n\\n⚠ 注意：ing を「イ・ン・グ」と3つに切って発音・表記すると、日本語なまりが強くなる。「ング」をひとかたまりの鼻の音として練習する。\",\"figureId\":\"xf_eigo_s020\"}],\"trapExamples\":[{\"question\":\"「写真」を表す英単語 photo の ph はどのように読むか。\",\"wrongAnswer\":\"プ（p と h をそのまま読んで「プホト」とする）\",\"trapExplanation\":\"ローマ字の感覚では p と h をそれぞれ読むのが自然に思える。ph が2文字で1つの音を表すことを知らないと、必ずこう読んでしまう。\",\"correctAnswer\":\"f と同じ音（「フォウトウ」と読む）\",\"correctExplanation\":\"ph は2文字で f の音を表す。photo, phone, elephant, alphabet, dolphin, graph が代表例で、ギリシャ語からきた語に多い。書き取りでは「フ」の音を f と書くか ph と書くかで迷うが、これらの語はつづりごと覚える。\"},{\"question\":\"「黒い」を表す英単語を書きなさい。\",\"wrongAnswer\":\"blak\",\"trapExplanation\":\"音を聞いて b－l－a－k と1音1文字であてはめると、ck が k 1字になってしまう。ck という2文字のつづりが必要な場所のきまりを知らないと防げない。\",\"correctAnswer\":\"black\",\"correctExplanation\":\"語末の「ク」の音は、直前が短母音1字のときは ck と書く。black, back, clock, duck, kick, rock が同じ形。長母音のあと（book, week）や子音のあと（milk, think）は k 1字でよい。tch のきまりとまったく同じ考え方である。\"}]}",
"{\"id\":\"eigo_s021\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重子音字③：th の2つの音\",\"description\":\"日本語にない th の音を、有声と無声の2種類に分けて練習する\",\"intro\":\"think を「シンク」と言うと sink（流し）に聞こえます。they を「デイ」と言えば day です。th は日本語にない音なので、似た音で代用すると別の語になってしまいます。舌の位置ひとつで通じ方が変わります。\",\"order\":521,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"th は上下の歯のあいだに舌先を軽くはさんで出す音。日本語には存在しない。\",\"無声の th（息だけ）… think, three, thank, month, bath, mouth, north, birthday。\",\"有声の th（声を出す）… this, that, these, those, the, they, mother, father, brother, weather。\",\"the・this・that など、よく使う短い語はほとんど有声。\",\"th を s や z、あるいは t や d に置きかえると別の語になってしまう（think／sink、they／day）。\"],\"sections\":[{\"heading\":\"th の出し方\",\"mangaId\":\"eigo_s021_manga\",\"body\":\"th は日本語にまったくない音である。だからこそ、意識して練習しなければ一生出せるようにならない。\\n\\n■ 口の形\\n上下の歯を軽く合わせ、そのあいだに舌先を少しだけはさむ。舌を強く出す必要はなく、軽く触れる程度でよい。その状態で息を出す。\\n\\n■ 2種類ある\\n①無声の th（息だけ。のどはふるえない）\\n　think, thank, three, thirty, Thursday, month, bath, mouth, tooth, north, birthday, healthy, something\\n②有声の th（声を出す。のどがふるえる）\\n　this, that, these, those, the, they, them, there, then, mother, father, brother, other, weather, together, with\\n\\n■ 見分けの目安\\n・the, this, that, they のように、文をつなぐはたらきをする短い語は有声。\\n・数を表す語（three, thirty, third）は無声。\\n・語末の -th はほとんど無声（month, bath, mouth, north, tooth）。\\n・-ther で終わる語はほとんど有声（mother, father, brother, other, weather）。\\n\\n★ ポイント：どちらの th も口の形は同じで、声を出すか出さないかだけがちがう。b／p、d／t の関係と同じである。\",\"figureId\":\"lf_eigoext01_021\"},{\"heading\":\"置きかえると別の語になる\",\"body\":\"th を出せないと、日本人はつい s・z・t・d のどれかに置きかえてしまう。しかしそれらは英語では別の音であり、別の語になってしまう。\\n\\n■ 無声の th を s にすると\\nthink（考える）→ sink（しずむ）\\nthick（厚い）→ sick（病気の）\\nmouth（口）→ mouse（ねずみ）※つづりもちがう\\n■ 有声の th を d にすると\\nthey（彼らは）→ day（日）\\nthen（そのとき）→ den（ほらあな）\\n■ 有声の th を z にすると\\nbreathe（呼吸する）→ breeze（そよ風）\\n\\n■ 練習の順序\\n①舌先を歯のあいだにはさんだまま、息だけを出す（thhhh）\\n②そこに母音をつける（thi-）\\n③語にする（think）\\n④文にする（I think so.）\\n\\n■ 数を表す語で練習する\\nthree, third, thirteen, thirty, thousand は、すべて無声の th で始まる。数の練習と th の練習を同時にできる。\\n\\n⚠ 注意：th のあとに r が続く three, throw, through は、th と r という日本語にない音が2つ続く。とくにゆっくり練習する。\"}],\"trapExamples\":[{\"question\":\"次の2語は同じ音で始まるか。　three ／ the\",\"wrongAnswer\":\"同じ（どちらも th なので同じ音）\",\"trapExplanation\":\"つづりが同じ th なので、音も1種類しかないと思ってしまう。日本語では「ス」「ズ」と別々に置きかえて覚えていることが多く、それが同じつづりだと気づいていない場合もある。\",\"correctAnswer\":\"ちがう（three は息だけの無声、the は声を出す有声）\",\"correctExplanation\":\"th には無声（think, three, month, bath）と有声（the, this, that, mother）の2種類がある。口の形はまったく同じで、のどをふるわせるかどうかだけがちがう。b／p、d／t、v／f と同じ関係である。\"},{\"question\":\"「私はそう思います。」を英語で書きなさい。\",\"wrongAnswer\":\"I sink so.\",\"trapExplanation\":\"th の音を出せないと s に置きかえて覚えてしまい、つづりまで s で書いてしまう。sink（しずむ）は実在する語なので、文としては成り立ってしまい、まちがいに気づきにくい。\",\"correctAnswer\":\"I think so.\",\"correctExplanation\":\"think（考える・思う）は無声の th で始まる。s に置きかえると sink（しずむ）という別の語になり、「私はそのようにしずみます」という意味不明の文になってしまう。thick（厚い）／sick（病気の）も同じ組み合わせなので、あわせて確認する。\"}]}",
"{\"id\":\"eigo_s022\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二重子音字④：wh と qu\",\"description\":\"疑問詞に多い wh と、必ずセットで使う qu のきまりを覚える\",\"intro\":\"what・when・where は wh を w と読むのに、who だけは h の音になり w を読みません。同じ疑問詞なのに不ぞろいです。また q は必ず u とセットで使います。例外はまとめて覚えてしまいましょう。\",\"order\":522,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"wh はふつう w と同じ音（what, when, where, which, white, why）。\",\"ただし who・whose・whom・whole は h の音になり、w は読まない。\",\"疑問詞は5W1H。what, when, where, who, why, how。how だけつづりが wh ではない。\",\"q は必ず u とセットで qu と書く。音は「クゥ」（question, quiet, quick, queen）。\",\"wh・qu のあとは母音が続くのがふつう。\"],\"sections\":[{\"heading\":\"wh の読み方\",\"body\":\"■ 基本は w の音\\nwh は h を読まず、w だけの音になるのがふつうである。\\n　what（何）, when（いつ）, where（どこ）, which（どちら）, why（なぜ）\\n　white（白い）, whale（クジラ）, wheel（車輪）, while（〜のあいだ）\\n\\n■ 例外：h の音になる語\\n次の語では逆に w を読まず、h の音になる。\\n　who（だれ）, whose（だれの）, whom（だれを）, whole（全体の）\\nwho は「フー」、whose は「フーズ」、whole は「ホウル」と読む。\\nwhole（全体の）と hole（あな）は同じ発音の別語である。\\n\\n■ 疑問詞をまとめて確認する\\nwhat（何）／when（いつ）／where（どこ）／who（だれ）／why（なぜ）／which（どちら）／whose（だれの）／how（どのように）\\n「5W1H」と呼ばれるが、how だけは wh で始まらない。\\n\\n■ 疑問詞は文の最初に置く\\n例）What is this?（これは何ですか）\\n例）Where do you live?（どこに住んでいますか）\\n例）Who is that boy?（あの男の子はだれですか）\\n\\n★ ポイント：疑問詞は入試で必ず出る。つづり・意味・使い方の3点をセットで覚える。where（どこ）と wear（着る）、which（どちら）と witch（魔女）は同じ発音の別語である。\",\"figureId\":\"xf_eigo_s022\",\"mangaId\":\"eigo_s022_xm\"},{\"heading\":\"qu のきまり\",\"body\":\"■ q は必ず u とセット\\n英語では、q のあとには必ず u が続く。q だけで終わる語も、q のあとに別の文字が来る語も、ふつうの英単語には存在しない。\\n　question（質問）, quiet（静かな）, quick（速い）, queen（女王）, quiz（クイズ）, quarter（4分の1）, square（正方形）, equal（等しい）\\n\\n■ 音は「クゥ」\\nqu は k と w を続けたような音になる。question は「クエスチョン」、quick は「クイック」に近い。\\n\\n■ まちがえやすい語\\nquestion は、途中の -tion を「チュン」に近い音で読む。「クエスチョン」の「チョ」の部分である。\\nquiet（静かな）と quite（かなり・まったく）は、つづりがよく似ていて意味がちがう。\\n　例）Be quiet.（静かにしなさい）／It is quite cold.（かなり寒い）\\n\\n■ 数の語にも出てくる\\nquarter は「4分の1」「15分」の意味で、時刻の言い方に出る。\\n　例）It is a quarter past three.（3時15分です）\\n\\n⚠ 注意：quiet と quite は、i と t の順番が入れかわっているだけ。書くときも読むときも、この2語は必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"「あの男の子はだれですか。」を英語で書くとき、下線部にあたる疑問詞 who の読み方を答えなさい。\",\"wrongAnswer\":\"ウォー（what や when と同じように w の音で読む）\",\"trapExplanation\":\"wh＝w の音と覚えると、who にもそのまま当てはめてしまう。what, when, where, why を先に習うため、who だけが例外だとは思いにくい。\",\"correctAnswer\":\"フー（[huː]。w を読まず h の音になる）\",\"correctExplanation\":\"wh のうち who, whose, whom, whole の4語だけは、w を読まずに h の音になる。それ以外（what, when, where, which, why, white）は w の音である。4語だけなので例外としてまとめて覚える。\"},{\"question\":\"「静かにしてください。」を英語で書きなさい。（Please be （　）.）\",\"wrongAnswer\":\"Please be quite.\",\"trapExplanation\":\"quiet と quite は、つづりが i と t の順番だけしかちがわない。書いているうちに順番が入れかわり、しかも quite も実在する語なので、見た目ではまちがいに気づきにくい。\",\"correctAnswer\":\"Please be quiet.\",\"correctExplanation\":\"quiet は「静かな」（クワイエット、2つの音のかたまり）、quite は「かなり・まったく」（クワイト、1つの音のかたまり）である。音の長さもちがう。Be quiet. と It is quite cold. の2文をセットで覚えて、書くときに口に出して確かめるとまちがえない。\"}]}",
"{\"id\":\"eigo_s023\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"読まない文字①：kn・wr・語末の -mb\",\"description\":\"書くのに読まないサイレントレターを、パターンごとにまとめて覚える\",\"intro\":\"know の k、write の w、climb の b。どれも書くのに読みません。聞いたとおりに書くと必ず落としてしまう文字です。一つずつ覚えるより、同じ形のなかまでまとめて覚えるほうがずっと速く済みます。\",\"order\":523,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"語頭の kn は k を読まない（know, knife, knee, knock, knot）。\",\"語頭の wr は w を読まない（write, wrong, wrist）。\",\"語末の -mb は b を読まない（climb, lamb, thumb, comb）。\",\"語頭の gn・ps も最初の文字を読まない（gnome, psychology）が、小学生には出番が少ない。\",\"読まない文字は「昔は読んでいた名残」。理由より、パターンでまとめて覚えるほうが速い。\"],\"sections\":[{\"heading\":\"読まないのに書く文字\",\"mangaId\":\"eigo_s023_manga\",\"body\":\"英語には、書くけれども読まない文字がたくさんある。これをサイレントレター（黙字）という。書き取り問題では、この読まない文字を落とすまちがいが最も多い。\\n\\n■ 語頭の kn（k を読まない）\\nknow（知っている）, knife（ナイフ）, knee（ひざ）, knock（ノックする）, knot（結び目）\\nknow は「ノウ」、knife は「ナイフ」と読む。\\n\\n■ 語頭の wr（w を読まない）\\nwrite（書く）, wrong（まちがった）, wrist（手首）, wrap（包む）\\nwrite は「ライト」で、right（右・正しい）とまったく同じ発音になる。\\n\\n■ 語末の -mb（b を読まない）\\nclimb（登る）, lamb（子羊）, thumb（親指）, comb（くし）, bomb（爆弾）\\nclimb は「クライム」と読む。\\n\\n■ なぜ書くのか\\nこれらは昔の英語では実際に発音されていた。発音だけが時代とともに変わり、つづりは昔のまま残った。だから理由を考えても今の音とはつながらない。パターンごとにまとめて覚えるのが最も効率がよい。\\n\\n★ ポイント：書き取りでいちばん多いまちがいが「読まない文字を書き忘れる」ことである。know を no、write を rite と書いてしまわないよう、語頭の k と w を意識する。\",\"figureId\":\"xf_eigo_s023\"},{\"heading\":\"同じ発音の別の語に注意\",\"body\":\"サイレントレターがあるために、まったく別の語と発音が同じになることがある。中学入試・英検で頻出の組み合わせを整理する。\\n\\n■ know（知っている）／no（いいえ・1つもない）\\n　例）I know him.（彼を知っている）／I have no money.（お金がない）\\n■ write（書く）／right（右・正しい）\\n　例）Write your name.（名前を書きなさい）／Turn right.（右に曲がりなさい）\\n■ knight（騎士）／night（夜）\\n　例）at night（夜に）\\n■ hour（時間）／our（私たちの）\\n　例）an hour（1時間）／our school（私たちの学校）\\n■ whole（全体の）／hole（あな）\\n■ knew（know の過去形）／new（新しい）\\n\\n■ 見分け方\\n音は同じなので、必ず意味と文の形で決める。\\n・「〜を知っている」なら know（あとに目的語がくる）\\n・「いいえ」「1つもない」なら no（あとに名詞がくるか、単独で使う）\\n・「書く」なら write（動詞）\\n・「右」「正しい」なら right\\n\\n⚠ 注意：聞き取り問題では、音が同じ語が答えの候補になることがある。前後の意味からどちらかを判断する練習をしておく。\"}],\"trapExamples\":[{\"question\":\"「あなたの名前を書きなさい。」を英語で書きなさい。（（　） your name.）\",\"wrongAnswer\":\"Right your name.\",\"trapExplanation\":\"write と right は発音がまったく同じである。しかも right のほうが先に習うことが多く、つづりも短いので、音だけを頼りにすると right が出てきてしまう。\",\"correctAnswer\":\"Write your name.\",\"correctExplanation\":\"write（書く）は w を読まないサイレントレターの語である。right は「右・正しい」という意味で、動詞ではないのでこの文には入らない。文の先頭で動詞から始まる命令文なので、動詞である write を選ぶ。\"},{\"question\":\"「私はその山に登りました。」の「登った」にあたる語 climbed のつづりを書きなさい。\",\"wrongAnswer\":\"climed\",\"trapExplanation\":\"climb の b は読まないので、音のとおりに書くと b が抜ける。読まない文字は聞き取りの手がかりがまったくないため、つづりを知らなければ必ず落とす。\",\"correctAnswer\":\"climbed\",\"correctExplanation\":\"語末の -mb では b を読まないが、書くときは必ず b を入れる。climb, lamb, thumb, comb が同じ仲間。ed を付けても b は残るので climbed となる。読まない文字を含む語は、書く練習を多めにしておく。\"}]}",
"{\"id\":\"eigo_s024\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"読まない文字②：gh・l・t など\",\"description\":\"night・walk・listen のように語の中で消える文字を整理する\",\"intro\":\"night の gh、walk の l、listen の t。書いてあるのに消える文字は、耳ではなく「知っているかどうか」で差がつきます。laugh のように gh を f と読む語まであります。ここで一気に整理します。\",\"order\":524,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"igh の gh は読まない（night, light, right, high, bright）。読み方は「アイ」。\",\"ought・aught の gh も読まない（bought, thought, caught, daughter）。読み方は「オー」。\",\"alk・alf・alm の l は読まない（walk, talk, half, calm）。\",\"listen・often の t、island の s、Wednesday の d も読まない。\",\"gh を f と読む語もある（laugh, enough, cough）。\"],\"sections\":[{\"heading\":\"gh のいろいろ\",\"body\":\"gh は、英語の中でも最も読み方が不安定なつづりである。3つのパターンに整理する。\\n\\n■ ①読まない（igh の形）\\nnight（夜）, light（光・軽い）, right（右・正しい）, high（高い）, bright（明るい）, might, sight, fight, tight\\nigh 全体で「アイ」と読む。i の長母音である。\\n\\n■ ②読まない（ough・augh の形）\\nbought（buy の過去形）, thought（think の過去形）, brought（bring の過去形）, caught（catch の過去形）, taught（teach の過去形）, daughter（むすめ）\\nこれらは「オー」と読む。動詞の過去形に多いのが特ちょうである。\\n\\n■ ③f の音になる\\nlaugh（笑う）, enough（十分な）, cough（せき）, tough（かたい）\\nlaugh は「ラフ」、enough は「イナフ」と読む。\\n\\n■ 読み方が特別な語\\nthough（〜だけれども）は「ゾウ」、through（〜を通って）は「スルー」。この2語はつづりが似ていて読みがまったくちがうので、入試で問われやすい。\\n\\n★ ポイント：不規則動詞の過去形には gh を含むものが多い（buy→bought、think→thought、bring→brought、catch→caught、teach→taught）。まとめて覚えると効率がよい。\",\"figureId\":\"xf_eigo_s024\",\"mangaId\":\"eigo_s024_xm\"},{\"heading\":\"l・t・s・d が消える語\",\"body\":\"■ l を読まない語\\nwalk（歩く）, talk（話す）, chalk（チョーク）\\nhalf（半分）, calf（子牛）\\ncalm（静かな）, palm（手のひら）\\nshould, would, could（助動詞。l を読まない）\\nwould は「ウッド」、could は「クッド」、should は「シュッド」である。\\n\\n■ t を読まない語\\nlisten（聞く）→「リスン」\\noften（しばしば）→「オフン」（「オフトゥン」と読む人もいる）\\ncastle（城）→「キャスル」\\nChristmas（クリスマス）→ t を読まない\\n\\n■ s を読まない語\\nisland（島）→「アイランド」\\nisle（小島）\\n\\n■ d を読まない語\\nWednesday（水曜日）→「ウェンズデイ」\\nhandkerchief（ハンカチ）\\n\\n■ h を読まない語\\nhour（1時間）, honest（正直な）, honor（名誉）\\n\\n⚠ 注意：Wednesday は曜日の中でいちばんつづりをまちがえやすい。「ウェド・ネス・デイ」と、書くとき専用の読み方をして覚えるとよい。\"}],\"trapExamples\":[{\"question\":\"「聞く」という意味の英単語 listen の読み方を答えなさい。\",\"wrongAnswer\":\"リストゥン（t をはっきり発音する）\",\"trapExplanation\":\"つづりに t があるので、そのまま音にしてしまう。日本語のカタカナ語「リスニング」でも「リス・ニング」と t の音が入らないのに、文字を見ると読みたくなる。\",\"correctAnswer\":\"リスン（[ˈlɪsn]。t は読まない）\",\"correctExplanation\":\"listen の t は読まない文字である。同じ仲間に often, castle, Christmas がある。listening（リスニング）も同じく t を読まない。読まない文字は、書くときには必ず必要なので、書き取りでは t を落とさないよう注意する。\"},{\"question\":\"「水曜日」を表す英単語を書きなさい。\",\"wrongAnswer\":\"Wensday\",\"trapExplanation\":\"Wednesday は「ウェンズデイ」と読み、d と e の音が聞こえない。音のとおりに書くと、読まない d と e が抜け落ちてしまう。曜日の中でいちばんまちがえやすい語である。\",\"correctAnswer\":\"Wednesday\",\"correctExplanation\":\"W－e－d－n－e－s－d－a－y と9文字ある。書くときは「ウェド・ネス・デイ」と区切って唱えると覚えやすい。同じくつづりと音がずれやすい語に Tuesday（チューズデイ）、February（フェブラリー、最初の r を読まないことがある）がある。曜日は大文字で書き始めることも忘れない。\"}]}",
"{\"id\":\"eigo_s025\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つづりの例外①：c と g の2つの読み方\",\"description\":\"あとに続く母音字で c と g の読み方が変わるきまりを覚える\",\"intro\":\"cat の c は「ク」、city の c は「ス」。同じ1文字なのに読み方が変わります。でたらめではなく、次に来る母音字が e・i・y かどうかで決まります。きまりを知れば、初めて見る語も読めます。\",\"order\":525,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"c のあとに e・i・y が来ると「ス」の音（city, cent, cycle, ice, nice, pencil）。\",\"c のあとに a・o・u や子音が来ると「ク」の音（cat, come, cup, class, cry）。\",\"g のあとに e・i・y が来ると「ジ」の音になることが多い（gym, giant, orange, age, large）。\",\"g のあとに a・o・u が来ると「グ」の音（game, go, guitar, glass）。\",\"g には例外が多い（get, give, girl は「グ」）。c のきまりのほうが確実。\"],\"sections\":[{\"heading\":\"c の2つの読み方\",\"body\":\"c は英語の中で読み方が2通りある文字である。しかも、あとに続く文字を見れば読み方が決まるという、はっきりしたきまりがある。\\n\\n■ 「ク」と読む c（ハードC）\\nあとに a・o・u または子音が続くとき。\\n　cat, can, car, cake, camera\\n　come, cold, color, cook\\n　cup, cut, cute\\n　class, clean, cry, cross（子音が続く）\\n\\n■ 「ス」と読む c（ソフトC）\\nあとに e・i・y が続くとき。\\n　cent（セント）, center, city, circle, cycle\\n　ice, nice, race, place, face, pencil, dance, since\\n\\n■ 語の中でも同じ\\n1つの語の中に両方が出てくることもある。\\n　circle … 最初の c は i の前なので「ス」、2つ目の c は l（子音）の前なので「ク」。「サークル」と読む。\\n\\n■ ck は必ず「ク」\\nback, clock, duck の ck は、いつでも「ク」の音である。\\n\\n★ ポイント：このきまりを知っていれば、city を「キティ」と読むまちがいがなくなる。「e・i・y の前ならス」と唱えて覚える。\",\"figureId\":\"xf_eigo_s025\"},{\"heading\":\"g の2つの読み方と例外\",\"mangaId\":\"eigo_s025_manga\",\"body\":\"g にも同じようなきまりがあるが、こちらは例外が多い。\\n\\n■ 「グ」と読む g（ハードG）\\nあとに a・o・u または子音が続くとき。\\n　game, garden, go, good, guitar, gun, glass, green, grow\\n\\n■ 「ジ」と読む g（ソフトG）\\nあとに e・i・y が続くとき。\\n　gym（体育館）, giant（巨人）, gentle, giraffe（キリン）\\n　orange, age, large, change, page, village, bridge, message\\n\\n■ 例外（e・i の前なのに「グ」）\\nget, give, girl, gift, begin, forget, together, tiger\\nこれらは日常でよく使う語ばかりなので、例外のほうが目立ってしまう。\\n\\n■ dge は「ジ」\\nbridge（橋）, edge（へり）, judge（裁判官）。短母音のあとの「ジ」の音は dge と書く。ck や tch と同じ考え方である。\\n\\n■ 語末の -ge\\n語末で「ジ」の音になるときは必ず e を付ける（age, page, large, change, village）。g だけで語を終えない。\\n\\n⚠ 注意：g のきまりは例外が多いので、「あとが e・i・y ならジのことが多い」くらいに考え、get・give・girl は例外として先に覚えておく。\"}],\"trapExamples\":[{\"question\":\"「city（都市）」の最初の c はどのように読むか。\",\"wrongAnswer\":\"ク（「キティ」と読む）\",\"trapExplanation\":\"c＝「ク」と1通りに覚えていると、cat や cup と同じように読んでしまう。フォニックスで最初に習う c の音が「ク」なので、こちらが強く残る。\",\"correctAnswer\":\"ス（「スィティ」と読む）\",\"correctExplanation\":\"c のあとに e・i・y が続くときは「ス」の音になる。city, cent, circle, cycle, ice, nice, pencil, dance が同じ仲間である。a・o・u や子音が続くときは「ク」（cat, come, cup, class）。あとに続く文字を見てから読む習慣をつける。\"},{\"question\":\"次の2語の g は同じ音か。　girl ／ giant\",\"wrongAnswer\":\"同じ（どちらも i の前なので「ジ」の音）\",\"trapExplanation\":\"「g のあとに e・i・y が来ると『ジ』」というきまりを覚えたばかりだと、例外の存在に気づかず機械的にあてはめてしまう。girl は身近な語なので、まちがえるとそのまま定着しやすい。\",\"correctAnswer\":\"ちがう（girl は「グ」、giant は「ジ」）\",\"correctExplanation\":\"g のきまりには例外が多い。get, give, girl, gift, begin, forget, together, tiger は e・i の前でも「グ」と読む。この例外語を先に覚え、それ以外で e・i・y が続く場合は「ジ」と読む、という順で考えるとまちがえにくい。\"}]}",
"{\"id\":\"eigo_s026\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つづりの例外②：つづりと音がずれる理由ときまり\",\"description\":\"なぜ英語はつづりどおりに読めないのかを知り、つづりの基本ルールを覚える\",\"intro\":\"英語は26文字しかないのに、音は40以上あります。文字が足りないので、1つの文字がいくつもの音を担当することになりました。つづりどおりに読めないのはそのためです。理由が分かると、覚え方そのものが変わってきます。\",\"order\":526,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"英語は26文字で約44の音を表すので、1つの文字がいくつもの音を担当することになる。\",\"母音字は5字しかないのに、母音の音は20前後ある。ここがつづりのむずかしさの原因。\",\"i は e の前（believe, field）。ただし c のあとは ei（receive）。\",\"語末が「子音＋y」の語は、s や ed を付けるとき y を i に変える（study→studies→studied）。\",\"短母音＋子音1つで終わる語は、ing や ed を付けるとき最後の子音を重ねる（stop→stopping）。\"],\"sections\":[{\"heading\":\"なぜつづりどおりに読めないのか\",\"mangaId\":\"eigo_s026_manga\",\"body\":\"英語の文字は26字しかないのに、英語の音はおよそ44ある。文字より音のほうが多いので、1つの文字がいくつもの音を担当せざるをえない。とくに母音は、5つの文字で20前後の音を表している。ここが英語のつづりのむずかしさの正体である。\\n\\n■ 日本語との比較\\n日本語のかなは、1字が1つの音に対応している。「あ」はいつでも「ア」、「か」はいつでも「カ」である。だから読み方に迷うことはない。\\n英語では、a という1文字が cat（ェア）、cake（エイ）、car（アー）、all（オー）、about（あいまいな音）と、5通り以上の音を表す。\\n\\n■ もう1つの理由：外国語からの借用\\n英語は歴史の中で、フランス語・ラテン語・ギリシャ語などから大量の語を取りこんできた。取りこむときに、もとの言語のつづりをそのまま残したため、読み方のきまりが何種類も混ざってしまった。\\n　ph（ギリシャ語）… photo, phone\\n　ch を「シュ」と読む（フランス語）… machine\\n　ch を「ク」と読む（ギリシャ語）… school\\n\\n■ だからどうするか\\n①フォニックスの基本のきまりを覚える（7割はこれで読める）\\n②残りは例外としてパターンごとに覚える\\nこの2段構えが、いちばん効率のよい進め方である。\\n\\n★ ポイント：「英語はつづりと音がずれるものだ」と最初から知っておくと、例外に出会ってもあわてない。\",\"figureId\":\"lf_eigoext01_026\"},{\"heading\":\"覚えておくと得をするつづりのきまり\",\"body\":\"つづりの世界にも、知っていると得をするきまりがいくつかある。\\n\\n■ ①i は e の前、ただし c のあとは逆\\nbelieve, field, friend, piece, chief（ie の順）\\nreceive, ceiling（c のあとなので ei の順）\\n英語圏では詩のように唱えて覚える有名なきまりである。\\n\\n■ ②語末が「子音＋y」なら y を i に変える\\nstudy → studies（三単現）／studied（過去形）\\ncity → cities（複数形）／country → countries\\ncarry → carried／try → tried／cry → cried\\nただし「母音＋y」なら変えない。\\nplay → plays／played　boy → boys　day → days\\n\\n■ ③短母音＋子音1つで終わる語は、子音を重ねる\\nstop → stopping／stopped\\nrun → running　swim → swimming　sit → sitting\\nbig → bigger／biggest　hot → hotter／hottest\\n「1音節・母音1つ・子音1つ」の3条件がそろったときだけ重ねる。\\n\\n■ ④語末の e は取ってから ing・ed を付ける\\nmake → making　write → writing　use → used／using　live → lived／living\\n\\n⚠ 注意：③と④を混同して makeing、runing と書くまちがいが非常に多い。「e があれば取る、短母音＋子音1つなら重ねる」と2つを並べて覚える。\"}],\"trapExamples\":[{\"question\":\"「run（走る）」に ing を付けて「走っている」の形にしなさい。\",\"wrongAnswer\":\"runing\",\"trapExplanation\":\"「動詞に ing を付ける」というきまりだけで機械的に処理してしまう。母音が短いときに子音を重ねるという条件を知らないと、まちがいに気づけない。\",\"correctAnswer\":\"running\",\"correctExplanation\":\"1音節で、母音字1つ＋子音字1つで終わる語は、ing や ed を付けるとき最後の子音を重ねる。run→running、swim→swimming、sit→sitting、stop→stopping、get→getting が同じ形。なお、母音字が2つある語（read→reading）や子音字が2つある語（help→helping）は重ねない。\"},{\"question\":\"「study（勉強する）」を三人称単数現在の形にしなさい。\",\"wrongAnswer\":\"studys\",\"trapExplanation\":\"三単現は s を付けると覚えているため、語の形をそのままにして s をつなげてしまう。語末が「子音＋y」のときの変化を知らないと防げない。\",\"correctAnswer\":\"studies\",\"correctExplanation\":\"語末が「子音＋y」のときは、y を i に変えて es を付ける。study→studies、city→cities、country→countries、carry→carries が同じ形である。ただし「母音＋y」のときは変えずに s を付けるだけでよい（play→plays、boy→boys、day→days）。y の1つ前の文字を必ず確かめる。\"}]}",
"{\"id\":\"eigo_s027\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音節（シラブル）の数え方\",\"description\":\"語をいくつのかたまりに分けて読むかを、母音の音の数で判断できるようにする\",\"intro\":\"strike は日本語では「ス・ト・ラ・イ・ク」と5拍ですが、英語では1かたまりです。この数え方のずれが、英語が速く聞こえる正体の一つです。あごに手をあてて数えると、英語のリズムの単位が見えてきます。\",\"order\":527,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"音節＝母音の音を中心とした、語の中の音のかたまり。\",\"音節の数＝母音の音の数。母音字の数ではないことに注意（cake は母音字2つでも1音節）。\",\"あごの下に手をあてて発音し、あごが下がった回数が音節の数になる。\",\"日本語はかな1字が1拍だが、英語は音節が1拍。strike は日本語で5拍、英語では1音節。\",\"辞書では音節の区切りが中点（・）で示される（beau・ti・ful）。\"],\"sections\":[{\"heading\":\"音節とは何か\",\"mangaId\":\"eigo_s027_manga\",\"body\":\"音節（シラブル）とは、母音の音を中心にした音のかたまりのことである。英語のリズムは、この音節を単位にして作られている。\\n\\n■ 数え方\\n音節の数は、母音の「音」の数と同じである。母音「字」の数ではない。\\n　cat … 母音の音は a だけ → 1音節\\n　cake … 母音字は a と e の2つだが、e は読まない → 1音節\\n　rain … 母音字は a と i の2つだが、音は「エイ」1つ → 1音節\\n　apple … a と e → 2音節（ap・ple）\\n　banana … 3音節（ba・na・na）\\n　beautiful … 3音節（beau・ti・ful）\\n　computer … 3音節（com・pu・ter）\\n\\n■ 体で確かめる方法\\nあごの下に手のこうをあてて、ゆっくり発音する。母音を出すときにあごが下がるので、あごが下がった回数を数えれば音節の数になる。\\n　strike … あごが下がるのは1回 → 1音節\\n\\n■ 日本語との大きなちがい\\n日本語はかな1字が1拍である。「ストライク」は5拍。しかし英語の strike は1音節、つまり1拍でしかない。この差が、日本語なまりの最大の原因になる。\\n\\n★ ポイント：カタカナ語を思い出したら、まず「英語では何音節か」を数え直す。ここが直ると発音が一気に英語らしくなる。\",\"figureId\":\"xf_eigo_s027\"},{\"heading\":\"音節で区切る練習\",\"body\":\"語を音節で区切れるようになると、長い語も読めるようになり、アクセントの位置も考えやすくなる。\\n\\n■ 2音節の語\\nteach・er（先生）／stu・dent（生徒）／pen・cil（えんぴつ）／win・dow（窓）／mo・ther（母）／sum・mer（夏）／of・fice（会社）／mu・sic（音楽）\\n\\n■ 3音節の語\\nbeau・ti・ful（美しい）／com・pu・ter（コンピュータ）／to・mor・row（明日）／fa・vo・rite（お気に入りの）／im・por・tant（大切な）／ex・cit・ing（わくわくする）\\n\\n■ 4音節以上の語\\nin・ter・est・ing（おもしろい・4音節）\\nin・for・ma・tion（情報・4音節）\\ncom・mu・ni・ca・tion（伝達・5音節）\\n\\n■ 区切りのおおよそのきまり\\n①子音が2つ続くときは、そのあいだで切る（win・dow, sum・mer, pen・cil）\\n②子音が1つのときは、その前で切ることが多い（mu・sic, o・pen）\\n③接頭語・接尾語は切れ目になる（un・hap・py, teach・er, care・ful）\\n\\n⚠ 注意：語末の -ed が音節を1つ増やすのは、t・d で終わる語のときだけである（want・ed は2音節、played は1音節）。次の課で学ぶ -ed の発音と関係している。\"}],\"trapExamples\":[{\"question\":\"「cake」は何音節か。\",\"wrongAnswer\":\"2音節（母音字が a と e の2つあるから）\",\"trapExplanation\":\"音節の数を「母音字の数」で数えてしまう。cake の e は読まないマジックE なので音を持たないが、文字として見えているぶん数に入れたくなる。\",\"correctAnswer\":\"1音節\",\"correctExplanation\":\"音節の数は母音の「音」の数で決まる。cake の母音の音は「エイ」1つだけなので1音節である。同じように rain（エイ）、boat（オウ）、night（アイ）もすべて1音節。母音字が2つ並んでも、音が1つなら1音節と数える。\"},{\"question\":\"「strike」を英語のリズムで発音すると、いくつの拍になるか。\",\"wrongAnswer\":\"5拍（「ス・ト・ラ・イ・ク」）\",\"trapExplanation\":\"カタカナの「ストライク」が5拍なので、英語も同じだと思ってしまう。日本語はかな1字が1拍なのに対し、英語は音節が1拍であるという根本のちがいに気づいていない。\",\"correctAnswer\":\"1拍（1音節）\",\"correctExplanation\":\"strike は s－t－r という3つの子音が続き、母音の音は「アイ」1つ、最後に k が来る形で、全体が1音節である。日本語のカタカナは子音のあとに必ず母音を入れるため拍が増える。カタカナ語は必ず「英語では何音節か」を数え直す。\"}]}",
"{\"id\":\"eigo_s028\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"アクセント（強勢）の位置\",\"description\":\"語のどこを強く読むかのきまりと、名詞・動詞で位置が変わる語を学ぶ\",\"intro\":\"日本語では、語のどこを強く読むかをあまり意識しません。英語は強く読む場所がずれるだけで通じなくなります。しかも名詞と動詞でアクセントの位置が動く語まであります。どこを強く読むのか、そのきまりを見ていきましょう。\",\"order\":528,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"2音節以上の語には、必ず強く読む音節（アクセント）が1つある。\",\"2音節の名詞は第1音節を強く読むことが多い（TEA-cher、STU-dent、WIN-dow）。\",\"2音節の動詞は第2音節を強く読むことが多い（be-GIN、for-GET、a-GREE）。\",\"-tion、-sion で終わる語は、その直前の音節を強く読む（in-for-MA-tion）。\",\"アクセントの位置がちがうと、通じないだけでなく別の語に聞こえることがある。\"],\"sections\":[{\"heading\":\"アクセントのきまり\",\"mangaId\":\"eigo_s028_manga\",\"body\":\"英語の語には、強く長くはっきり読む音節が必ず1つある。これをアクセント（強勢）という。日本語のアクセントが音の高さで決まるのに対し、英語のアクセントは強さ・長さ・はっきりさで決まる。\\n\\n■ 2音節の語\\n名詞… 第1音節が強いことが多い\\n　TEA-cher, STU-dent, WIN-dow, MU-sic, SUM-mer, PEN-cil, MOR-ning\\n動詞… 第2音節が強いことが多い\\n　be-GIN, for-GET, a-GREE, ex-PLAIN, en-JOY, re-MEM-ber（3音節）\\n\\n■ 語尾で決まるきまり\\n①-tion, -sion で終わる語 … 直前の音節を強く読む\\n　in-for-MA-tion, com-mu-ni-CA-tion, QUES-tion, STA-tion\\n②-ity, -ical, -ic で終わる語 … 直前の音節\\n　e-LEC-tric, fan-TAS-tic\\n③-ese, -eer, -ee で終わる語 … その語尾自体を強く読む\\n　Jap-a-NESE, Chi-NESE, en-gi-NEER\\n\\n■ 弱く読む部分はあいまいになる\\n強く読まない音節の母音は、はっきりした音を失って「ア」に近いあいまいな音になる。\\n　about（アバウト）の a、teacher（ティーチャー）の er、banana（バナナ）の最初と最後の a。\\nだから、弱い部分は聞き取りにくい。\\n\\n★ ポイント：新しい語を覚えるときは、意味・つづりだけでなく「どこを強く読むか」もいっしょに覚える。\",\"figureId\":\"lf_eigoext01_028\"},{\"heading\":\"位置がちがうと別の語になる\",\"body\":\"英語には、つづりが同じでもアクセントの位置で品詞と意味が変わる語がある。\\n\\n■ 前を強く読むと名詞、後ろを強く読むと動詞\\nrecord … RE-cord（記録・レコード／名詞）／re-CORD（記録する／動詞）\\npresent … PRE-sent（贈り物／名詞）／pre-SENT（贈る／動詞）\\nincrease … IN-crease（増加／名詞）／in-CREASE（増える／動詞）\\n「名前は前、動きは後ろ」と覚えるとよい。\\n\\n■ カタカナ語のアクセントに注意\\n日本語になった外来語は、英語とアクセントの位置がちがうことが多い。\\n　volunteer … 日本語は「ボランティア」だが、英語は vol-un-TEER と最後が強い。\\n　calendar … 英語は CAL-en-dar と最初が強い。\\n　hotel … 英語は ho-TEL と後ろが強い。\\n　orange … 英語は OR-ange と前が強い。\\n\\n■ 入試での出題形式\\n「最も強く読む音節の位置を記号で答えなさい」という形で出る。音節に区切る→アクセントのきまりをあてはめる、という手順で解く。\\n\\n⚠ 注意：アクセントの位置がずれると、正しい音を出していても通じないことがある。日本語で「はし」の高さを変えると意味が変わるのと同じくらい、英語では強さの位置が重要である。\"}],\"trapExamples\":[{\"question\":\"「volunteer（ボランティア）」で最も強く読む音節はどこか。\",\"wrongAnswer\":\"第1音節（vol- を強く読む。日本語の「ボランティア」と同じ）\",\"trapExplanation\":\"日本語のカタカナ語「ボランティア」では最初のほうを強く言うため、そのまま英語にあてはめてしまう。日本語になっている語ほど、英語のアクセントを確かめずに使ってしまう。\",\"correctAnswer\":\"第3音節（vol-un-TEER。最後の -teer を強く読む）\",\"correctExplanation\":\"-eer, -ese, -ee で終わる語は、その語尾自体を強く読む。volunteer, engineer, Japanese, Chinese が同じ形である。日本語になった外来語はアクセントの位置が変わっていることが多いので、hotel（ho-TEL）、calendar（CAL-en-dar）などもあわせて確かめておく。\"},{\"question\":\"「I got a present from my mother.」の present は、どこを強く読むか。\",\"wrongAnswer\":\"第2音節（pre-SENT）\",\"trapExplanation\":\"「贈る」という動詞のイメージが先に立つと、動詞のアクセント（後ろが強い）をあてはめてしまう。文の中でどんな働きをしているかを確かめずに読むと起こるまちがいである。\",\"correctAnswer\":\"第1音節（PRE-sent。「贈り物」という名詞なので前を強く読む）\",\"correctExplanation\":\"この文では a present（1つの贈り物）と a が付いているので名詞である。present は名詞なら PRE-sent（贈り物）、動詞なら pre-SENT（贈る）と、アクセントの位置で品詞が変わる。record（RE-cord／re-CORD）、increase（IN-crease／in-CREASE）も同じ。「名前は前、動きは後ろ」と覚える。\"}]}",
"{\"id\":\"eigo_s029\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語末の -s の3つの発音\",\"description\":\"複数形・三単現の -s が /s/・/z/・/ɪz/ のどれになるかを決めるきまりを学ぶ\",\"intro\":\"books は「ブックス」、dogs は「ドッグズ」、buses は「バスィズ」。同じ -s なのに読み方が3通りあります。しかも自分で選んでいるのではなく、直前の音が自動的に決めています。そのしくみを解きます。\",\"order\":529,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"-s の発音は3種類。「ス」／「ズ」／「イズ」。\",\"無声音（p・t・k・f）のあと → 「ス」（books, cats, maps, cups）。\",\"有声音（母音や b・d・g・l・m・n・r・v）のあと → 「ズ」（dogs, boys, pens, cars）。\",\"s・z・sh・ch・x・ge のあと → 「イズ」（buses, boxes, watches, dishes, oranges）。\",\"つづりも変わる。s・x・z・sh・ch で終わる語には es を付ける。\"],\"sections\":[{\"heading\":\"3つの発音の決まり方\",\"mangaId\":\"eigo_s029_manga\",\"body\":\"名詞の複数形や、動詞の三人称単数現在形に付ける -s は、いつも同じ音ではない。直前の音によって3通りに変わる。これは「言いやすいように自然に変わる」ためのきまりである。\\n\\n■ ①「ス」と読む（無声音のあと）\\n直前が p・t・k・f・θ のような、声を出さない音のとき。\\n　books, cats, maps, cups, lakes, months, stops, helps, likes, takes\\n■ ②「ズ」と読む（有声音のあと）\\n直前が母音、または b・d・g・l・m・n・r・v のような、声を出す音のとき。\\n　dogs, boys, pens, cars, girls, games, birds, rooms, plays, goes, comes, lives\\n■ ③「イズ」と読む（音がぶつかるとき）\\n直前が s・z・sh・ch・x・ge のように、-s と似た音のとき。そのままだと続けて言えないので、あいだに母音を入れる。\\n　buses, boxes, watches, dishes, classes, oranges, teaches, washes\\n\\n■ 音節が1つ増えるのは③だけ\\nbus（1音節）→ buses（2音節）\\nwatch（1音節）→ watches（2音節）\\n①②では音節は増えない。\\n\\n★ ポイント：無声音のあとは無声の「ス」、有声音のあとは有声の「ズ」。前の音と種類をそろえているだけである。b／p、d／t の対を思い出す。\",\"figureId\":\"lf_eigoext01_029\"},{\"heading\":\"つづりの変化もあわせて覚える\",\"body\":\"発音だけでなく、つづりも変わることがある。\\n\\n■ ①ふつうは s を付けるだけ\\nbook → books　dog → dogs　pen → pens\\n■ ②s・x・z・sh・ch で終わる語は es を付ける\\nbus → buses　box → boxes　watch → watches　dish → dishes　class → classes\\n■ ③「子音＋y」で終わる語は y を i に変えて es\\ncity → cities　country → countries　study → studies　carry → carries\\n（「母音＋y」なら s だけ： boy → boys、day → days、play → plays）\\n■ ④f・fe で終わる語は ves に変える語がある\\nleaf → leaves　knife → knives　life → lives　wife → wives\\n（例外： roof → roofs）\\n■ ⑤o で終わる語の一部は es\\ntomato → tomatoes　potato → potatoes\\n（photo → photos、piano → pianos は s だけ）\\n\\n■ 形が変わる複数形（不規則）\\nman → men　woman → women　child → children　foot → feet　tooth → teeth　mouse → mice\\nsheep → sheep　fish → fish（形が変わらない）\\n\\n⚠ 注意：三単現の -s も同じきまりで動く（go → goes、watch → watches、study → studies）。複数形とセットで覚えれば、覚える量が半分になる。\"}],\"trapExamples\":[{\"question\":\"「buses」の語末の -es はどのように読むか。\",\"wrongAnswer\":\"ス（「バスス」のように読む）\",\"trapExplanation\":\"-s は「ス」と読むと覚えていると、そのまま当てはめてしまう。しかし s の音のあとに s を続けることは実際には発音できないため、この読み方は成り立たない。\",\"correctAnswer\":\"イズ（「バスィズ」と読み、音節が1つ増える）\",\"correctExplanation\":\"s・z・sh・ch・x・ge で終わる語に -es が付くと「イズ」と読み、音節が1つ増える。buses, boxes, watches, dishes, classes, oranges が同じ形である。前の音とぶつかって言えないため、あいだに母音を入れて調整している。\"},{\"question\":\"「books」と「dogs」の語末の -s は同じ音か。\",\"wrongAnswer\":\"同じ（どちらも s なので「ス」と読む）\",\"trapExplanation\":\"つづりが同じ s なので、音も同じだと考えてしまう。日本語では「ブックス」「ドッグス」と、どちらもカタカナの「ス」で書かれることも原因である。\",\"correctAnswer\":\"ちがう（books は「ス」、dogs は「ズ」）\",\"correctExplanation\":\"直前の音が無声音（k）なら無声の「ス」、有声音（g）なら有声の「ズ」になる。前の音に種類をそろえているだけなので、覚えるというより口の動きに従えば自然にそうなる。cats（ス）／pens（ズ）、maps（ス）／cars（ズ）で確かめるとよい。\"}]}",
"{\"id\":\"eigo_s030\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語末の -ed の3つの発音\",\"description\":\"過去形の -ed が /t/・/d/・/ɪd/ のどれになるかを決めるきまりを学ぶ\",\"intro\":\"played は「プレイド」、looked は「ルックト」、wanted は「ウォンティド」。同じ -ed でも3通りに読み分けます。wanted だけは音のかたまりが1つ増えるので、聞き取りでも書き取りでも差がつきます。\",\"order\":530,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"-ed の発音は3種類。「ト」／「ド」／「イド」。\",\"無声音（p・k・f・s・sh・ch・x）のあと → 「ト」（helped, looked, washed, watched）。\",\"有声音（母音や b・g・l・m・n・r・v・z）のあと → 「ド」（played, opened, called, lived）。\",\"t・d のあと → 「イド」（wanted, needed, visited, started）。音節が1つ増える。\",\"つづりは「e を取って ed」「子音を重ねて ed」「y を i に変えて ed」の3パターン。\"],\"sections\":[{\"heading\":\"3つの発音の決まり方\",\"mangaId\":\"eigo_s030_manga\",\"body\":\"規則動詞の過去形・過去分詞に付ける -ed も、-s と同じように直前の音で3通りに変わる。\\n\\n■ ①「ト」と読む（無声音のあと）\\n直前が p・k・f・s・sh・ch・x のように、声を出さない音のとき。\\n　helped, looked, washed, watched, stopped, walked, liked, cooked, laughed, passed, finished\\n■ ②「ド」と読む（有声音のあと）\\n直前が母音、または b・g・l・m・n・r・v・z のような、声を出す音のとき。\\n　played, opened, called, lived, listened, cleaned, enjoyed, studied, arrived, remembered\\n■ ③「イド」と読む（t・d のあと）\\n直前が t か d のとき。そのままでは続けて言えないので、あいだに母音を入れる。\\n　wanted, needed, visited, started, waited, ended, decided, painted\\n\\n■ 音節が増えるのは③だけ\\nwant（1音節）→ wanted（2音節）\\nneed（1音節）→ needed（2音節）\\n一方、played は1音節のまま、looked も1音節のままである。\\n\\n■ 覚え方\\n「t・d のあとだけイド、それ以外は前の音にそろえる」と1行で覚える。-s のきまりとまったく同じ考え方である。\\n\\n★ ポイント：liked を「ライクド」、looked を「ルックド」と読んでしまうまちがいが多い。無声音のあとは「ト」である。\",\"figureId\":\"lf_eigoext01_030\"},{\"heading\":\"つづりの変化\",\"body\":\"-ed を付けるときのつづりの変化は3パターンある。\\n\\n■ ①そのまま ed を付ける\\nplay → played　want → wanted　open → opened　visit → visited　watch → watched\\n■ ②語末が e なら d だけ付ける\\nlike → liked　live → lived　use → used　arrive → arrived　close → closed\\n（e を取ってから ed を付ける、と考えても同じ結果になる）\\n■ ③1音節で「短母音＋子音1つ」なら子音を重ねる\\nstop → stopped　plan → planned　drop → dropped\\n（stoped と書くと×。stopped と p を2つにする）\\n■ ④「子音＋y」なら y を i に変えて ed\\nstudy → studied　carry → carried　try → tried　cry → cried\\n（「母音＋y」なら変えない： play → played、enjoy → enjoyed、stay → stayed）\\n\\n■ 不規則動詞は -ed が付かない\\ngo → went　come → came　see → saw　eat → ate　have → had\\nbuy → bought　think → thought　teach → taught　catch → caught\\nこれらは形ごと覚える。中学入試でもよく出る。\\n\\n⚠ 注意：study は「子音＋y」なので studied、play は「母音＋y」なので played。y の1つ前の文字を必ず見る。この見分けは複数形・三単現でも同じである。\"}],\"trapExamples\":[{\"question\":\"「I looked at the picture.」の looked の -ed はどのように読むか。\",\"wrongAnswer\":\"イド（「ルックイド」と2音節で読む）\",\"trapExplanation\":\"-ed を見ると「エド」「イド」と読みたくなる。とくに wanted や needed を先に習っていると、すべての -ed に母音が入ると思いこんでしまう。\",\"correctAnswer\":\"ト（「ルックト」。1音節のまま）\",\"correctExplanation\":\"直前が k という無声音なので、-ed は無声の「ト」になる。helped, washed, watched, stopped, liked も同じ。「イド」と読むのは直前が t か d のとき（wanted, needed, visited, started）だけである。\"},{\"question\":\"「stop（止まる）」を過去形にしなさい。\",\"wrongAnswer\":\"stoped\",\"trapExplanation\":\"「過去形は ed を付ける」というきまりだけで処理してしまい、子音を重ねる条件を確かめない。stoped と書いても見た目に大きな違和感がないため、まちがいに気づきにくい。\",\"correctAnswer\":\"stopped\",\"correctExplanation\":\"1音節で「短母音＋子音1つ」で終わる語は、-ed を付けるとき最後の子音を重ねる。stop→stopped、plan→planned、drop→dropped が同じ形である。ing を付けるときも同じきまりで stopping となる。母音字が2つある語（look→looked）や子音字が2つ続く語（help→helped）では重ねない。\"}]}",
"{\"id\":\"eigo_s031\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"英語のリズムと弱く読む語\",\"description\":\"強く読む語と弱く読む語を区別し、英語らしいリズムで読めるようにする\",\"intro\":\"英語が速く感じられるのは、話す人が急いでいるからではありません。a・the・of のような語を思い切り弱く読むからです。an apple が「アナポー」に聞こえるのもそのため。強弱のしくみが分かると急に聞き取れます。\",\"order\":531,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"英語は強く読む語と弱く読む語がはっきり分かれる。強く読む語の間隔はほぼ一定になる。\",\"強く読む語＝名詞・動詞・形容詞・副詞・疑問詞（意味の中心になる語）。\",\"弱く読む語＝ a, the, of, to, and, is, can, for などの短い語（文をつなぐ語）。\",\"弱く読む語の母音はあいまいな「ア」に近い音になる（can は「カン」ではなく「クン」に近い）。\",\"語と語はつながって聞こえる（an apple → アナポー、pick it up → ピキラップ）。\"],\"sections\":[{\"heading\":\"強く読む語と弱く読む語\",\"body\":\"英語の文は、すべての語を同じ強さで読むわけではない。意味の中心になる語だけを強く読み、それ以外は弱く短く読む。\\n\\n■ 強く読む語（内容語）\\n名詞… book, school, mother\\n動詞… go, eat, study（ただし be動詞・助動詞は弱い）\\n形容詞… big, beautiful\\n副詞… slowly, always\\n疑問詞… what, where, who\\n数… three, ten\\n\\n■ 弱く読む語（機能語）\\n冠詞… a, an, the\\n前置詞… of, to, in, at, for, from\\n接続詞… and, but, or\\n代名詞… I, you, he, it, them\\nbe動詞・助動詞… is, are, was, can, will, do\\n\\n■ 例文で確かめる\\nI WANT to BUY a BOOK.（大文字が強く読む部分）\\n強く読むのは want, buy, book の3語。to と a はほとんど聞こえないくらい弱くなる。\\n\\n■ 弱く読むと母音が変わる\\ncan … 強いとき「キャン」、弱いとき「クン」に近い\\nto … 強いとき「トゥー」、弱いとき「タ」に近い\\nand … 弱いとき「ン」に近い（fish and chips → フィッシュンチップス）\\n\\n★ ポイント：聞き取りで単語が消えたように感じるのは、弱く読まれているからである。消えているのは、たいてい a・the・to・of・and などの短い語である。\",\"mangaId\":\"eigo_s031_xm\"},{\"heading\":\"強い語の間隔は一定になる\",\"body\":\"英語は、強く読む語と語のあいだの時間がほぼ一定になるようにできている。これを強勢拍リズムという。だから、あいだに弱い語がいくつ入っても、文全体にかかる時間はあまり変わらない。\\n\\n■ 実験してみる\\n①DOGS EAT BONES.（3語・強勢3つ）\\n②The DOGS EAT the BONES.（5語・強勢3つ）\\n③The DOGS will EAT the BONES.（6語・強勢3つ）\\n語数は増えているのに、声に出すとかかる時間はほぼ同じになる。弱い語はすきまに押しこまれて、速く短く読まれるからである。\\n\\n■ 日本語との比較\\n日本語はかな1字が1拍で、拍の数だけ時間がかかる。「いぬ」（2拍）より「いぬがほねをたべる」（9拍）のほうが確実に長い。英語ではこうならない。この差が、日本人が英語を聞き取れない大きな理由である。\\n\\n■ 音がつながる\\n弱い語は前後の語とつながって聞こえる。\\nan apple → アナポー\\npick it up → ピキラップ\\ntake it easy → テイキリーズィー\\n子音で終わる語のあとに母音で始まる語が来ると、くっついて1つの語のように聞こえる。\\n\\n⚠ 注意：聞き取り問題では「単語が速すぎて聞こえない」と感じることが多いが、実際には弱く読まれてつながっているだけである。強く読まれる語だけを拾えば意味はつかめる。\",\"figureId\":\"lf_eigoext01_031\"}],\"trapExamples\":[{\"question\":\"「I can swim.」の can は、どのように読まれることが多いか。\",\"wrongAnswer\":\"キャン（いつでもはっきり「キャン」と読む）\",\"trapExplanation\":\"つづりが can なので、いつでも同じ音で読むと考えてしまう。日本語では語の読み方が場面で変わることが少ないため、弱く読む形があるという発想が出てこない。\",\"correctAnswer\":\"弱く「クン」に近い音になる（強く読むのは swim のほう）\",\"correctExplanation\":\"can のような助動詞は弱く読む語である。文の中心は動詞の swim なので、そこを強く読む。逆に Yes, I can. のように文末で使われるときは強く「キャン」と読む。同じ語でも位置によって強さが変わる点が英語の特ちょうである。\"},{\"question\":\"「The dogs will eat the bones.」は、「Dogs eat bones.」よりどれくらい長い時間がかかるか。\",\"wrongAnswer\":\"語数が2倍なので、およそ2倍の時間がかかる\",\"trapExplanation\":\"日本語は拍の数だけ時間がかかるため、語数が増えれば比例して長くなると考えてしまう。英語のリズムのしくみを知らないと、必ずこの答えになる。\",\"correctAnswer\":\"ほとんど変わらない（どちらも強く読む語が3つなので、かかる時間はほぼ同じ）\",\"correctExplanation\":\"英語は強く読む語と語のあいだの時間がほぼ一定になるリズムを持つ。強勢の数が同じなら、あいだの弱い語がいくつ増えても全体の長さはあまり変わらない。弱い語は速く短くつぶされて発音される。これが英語が速く聞こえる理由である。\"}]}",
"{\"id\":\"eigo_s032\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ローマ字①：ヘボン式と訓令式のちがい\",\"description\":\"2つのローマ字の書き方のちがいと、どちらを使うべき場面かを整理する\",\"intro\":\"「ふじ」は Huzi でしょうか、Fuji でしょうか。実はどちらも正しいローマ字です。学校で最初に習う訓令式と、パスポートや駅名で使うヘボン式の2種類があるからです。ちがいが出るのは、し・ち・つ・ふ・じの行だけです。\",\"order\":532,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"ローマ字には訓令式（学校で最初に習う）とヘボン式（パスポート・駅名で使う）がある。\",\"ちがいが出るのは し・ち・つ・ふ・じ・ぢ・づ と、しゃ行・ちゃ行・じゃ行だけ。\",\"訓令式… si, ti, tu, hu, zi, sya, tya, zya。\",\"ヘボン式… shi, chi, tsu, fu, ji, sha, cha, ja。\",\"人名・地名を英語の文の中で書くときは、ヘボン式を使うのがふつう。\"],\"sections\":[{\"heading\":\"2つの書き方\",\"body\":\"日本語をアルファベットで書き表す方法をローマ字という。ローマ字には主に2つの方式がある。\\n\\n■ 訓令式\\n日本語の五十音表のならびをそのまま整理した、規則的な書き方。小学校の国語で最初に習う。\\n　さ行… sa, si, su, se, so\\n　た行… ta, ti, tu, te, to\\n　は行… ha, hi, hu, he, ho\\n　ざ行… za, zi, zu, ze, zo\\n　しゃ・しゅ・しょ… sya, syu, syo\\n\\n■ ヘボン式\\n英語を話す人が読んだときに、日本語の音に近くなるように工夫した書き方。パスポート、駅名の表示、道路標識で使われる。\\n　さ行… sa, shi, su, se, so\\n　た行… ta, chi, tsu, te, to\\n　は行… ha, hi, fu, he, ho\\n　ざ行… za, ji, zu, ze, zo\\n　しゃ・しゅ・しょ… sha, shu, sho\\n\\n■ ちがうのはごく一部\\n2つの方式で書き方がちがうのは、し・ち・つ・ふ・じ・ぢ・づ と、しゃ行・ちゃ行・じゃ行だけである。あ行、か行、な行、ま行、ら行などはまったく同じである。\\n\\n★ ポイント：どちらもまちがいではない。ただし、英語の文の中で日本の人名・地名を書くときはヘボン式を使う。英語話者が読んだときに近い音になるからである。\",\"figureId\":\"lf_eigoext01_032\"},{\"heading\":\"使い分けと、まちがえやすい書き方\",\"mangaId\":\"eigo_s032_manga\",\"body\":\"■ どちらを使うか\\n・小学校の国語のテスト … 訓令式が基本（ただしヘボン式も認められることが多い）\\n・パスポート、クレジットカードの名義 … ヘボン式のみ\\n・駅名、道路標識、地図 … ヘボン式\\n・英語の授業・入試の英作文 … ヘボン式\\n\\n■ ヘボン式でよく出る語\\n富士山 … Fuji（Huzi ではない）\\n東京 … Tokyo\\n大阪 … Osaka\\n渋谷 … Shibuya（Sibuya ではない）\\n茶 … cha\\n寿司 … sushi（susi ではない）\\n一 … ichi（iti ではない）\\n\\n■ 名前の例\\nたかし … Takashi（Takasi ではない）\\nちひろ … Chihiro（Tihiro ではない）\\nつよし … Tsuyoshi（Tuyosi ではない）\\nじゅん … Jun（Zyun ではない）\\n\\n■ 特別なきまり\\nヘボン式では、ん のあとに b・m・p が続くとき、n を m と書くことがある（難波＝Namba、群馬＝Gunma／Gumma）。パスポートでは m を使う。\\n\\n⚠ 注意：訓令式で書いた「Huzisan」は英語話者にはまったく通じない。h－u と読むと「ヒュージサン」のようになってしまう。英語の中では必ず Fuji と書く。\"}],\"trapExamples\":[{\"question\":\"英語の文の中で「富士山」を書くとき、正しいのはどちらか。　Huzisan ／ Mt. Fuji\",\"wrongAnswer\":\"Huzisan\",\"trapExplanation\":\"学校の国語で訓令式を先に習うため、ふ＝hu、じ＝zi のつづりが身についている。英語の中でもそのまま使えると思ってしまう。\",\"correctAnswer\":\"Mt. Fuji\",\"correctExplanation\":\"英語の文の中で日本の地名を書くときはヘボン式を使う。ふ＝fu、じ＝ji である。また「〜山」は Mt.（Mount の略）を付けて Mt. Fuji と書くのがふつうである。Huzisan と書くと、英語話者には日本語の音として読み取れない。\"},{\"question\":\"「つよし」という名前をパスポートに書くときのつづりを答えなさい。\",\"wrongAnswer\":\"Tuyosi\",\"trapExplanation\":\"訓令式では つ＝tu、し＝si なので、そのまま書いてしまう。訓令式のほうが規則的で覚えやすいため、こちらが先に出てくる。\",\"correctAnswer\":\"Tsuyoshi\",\"correctExplanation\":\"パスポートはヘボン式で書くきまりになっている。つ＝tsu、し＝shi なので Tsuyoshi となる。同じように ちひろ＝Chihiro、じゅん＝Jun、しんじ＝Shinji と書く。訓令式と異なるのは し・ち・つ・ふ・じ と、しゃ行・ちゃ行・じゃ行だけである。\"}]}",
"{\"id\":\"eigo_s033\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ローマ字②：長音・促音・はねる音の書き方\",\"description\":\"のばす音・つまる音・はねる音をローマ字でどう書くかのきまりを覚える\",\"intro\":\"「きっぷ」の小さい「っ」、「しんいち」の「ん」、「さとう」ののばす音。かなでは書けても、ローマ字ではどう書くか迷います。パスポートでは「さとう」は Sato と書きます。書き方のきまりを確かめましょう。\",\"order\":533,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"促音（小さい っ）は、次の子音を重ねて書く（きっぷ＝kippu、がっこう＝gakko）。\",\"ただし ち で始まる音の前は t を重ねる（まっちゃ＝matcha）。\",\"撥音（ん）は n。母音や y の前ではアポストロフィで区切る（しんいち＝Shin'ichi）。\",\"長音（のばす音）は、パスポートでは書かないのがふつう（おおの＝Ono、さとう＝Sato）。\",\"拗音（小さい ゃ ゅ ょ）はヘボン式で ya, yu, yo をつなげて書く（きょう＝kyo、しゃしん＝shashin）。\"],\"sections\":[{\"heading\":\"つまる音・はねる音\",\"body\":\"ローマ字でとくにまちがえやすいのが、小さい「っ」と「ん」の書き方である。\\n\\n■ 促音（小さい っ）＝次の子音を重ねる\\nきって（切手）… kitte\\nがっこう（学校）… gakko\\nにっぽん（日本）… Nippon\\nさっぽろ（札幌）… Sapporo\\nざっし（雑誌）… zasshi（sh を重ねるので s が増える）\\n\\n■ ち・ちゃ行の前だけは t を重ねる\\nまっちゃ（抹茶）… matcha（ccha ではない）\\nこっち … kotchi\\nヘボン式では ち＝chi なので、そのまま重ねると cchi となって読みにくい。そこで t を使う。\\n\\n■ 撥音（ん）＝ n\\nにほん … Nihon\\nかんじ … kanji\\nしんぶん … shinbun\\n\\n■ ん のあとに母音・y が来るときはアポストロフィ\\nしんいち … Shin'ichi（Shinichi だと「し・に・ち」と読まれてしまう）\\nほんや … hon'ya\\nまんいん … man'in\\n\\n■ ん のあとに b・m・p が来るとき\\nヘボン式では n を m と書くことがある。\\nなんば（難波）… Namba\\nぐんま（群馬）… Gunma（Gumma とも書く）\\n\\n★ ポイント：促音は「次の子音を重ねる」、撥音は「n」、この2つを先に固める。\",\"figureId\":\"xf_eigo_s033\",\"mangaId\":\"eigo_s033_xm\"},{\"heading\":\"のばす音と小さい ゃ ゅ ょ\",\"body\":\"■ 長音（のばす音）\\n日本語の「おおの」「さとう」「こうこう」のようにのばす音は、ローマ字では書き方が何通りもある。\\n①のばす記号を付ける … Ōno, Satō（学術的な表記）\\n②母音を重ねる … Oono, Satou（入力するときの書き方）\\n③何も書かない … Ono, Sato（パスポート・一般的な表記）\\nパスポートや英語の文の中では③が基本である。だから「大野さん」も「小野さん」も、どちらも Ono になる。\\n\\n■ 名前でよく出る例\\nたろう … Taro\\nゆうき … Yuki\\nこうた … Kota\\nしょうこ … Shoko\\nどれものばす音を書かない。\\n\\n■ 拗音（小さい ゃ ゅ ょ）\\nヘボン式では、i の段の音に ya・yu・yo をつなげる。\\nきゃ・きゅ・きょ … kya, kyu, kyo\\nしゃ・しゅ・しょ … sha, shu, sho（sya ではない）\\nちゃ・ちゅ・ちょ … cha, chu, cho（tya ではない）\\nにゃ・にゅ・にょ … nya, nyu, nyo\\nひゃ・ひゅ・ひょ … hya, hyu, hyo\\nじゃ・じゅ・じょ … ja, ju, jo（zya ではない）\\n\\n例）きょうと（京都）… Kyoto　しゃしん（写真）… shashin　じゅうどう（柔道）… judo\\n\\n⚠ 注意：東京は Tokyo と書く。To-u-kyo-u ののばす音を書かないので、Tokyo という5文字になる。Toukyou と書くのは入力用の書き方で、英語の文の中では使わない。\"}],\"trapExamples\":[{\"question\":\"「がっこう（学校）」をローマ字（ヘボン式）で書きなさい。\",\"wrongAnswer\":\"gatsukou\",\"trapExplanation\":\"小さい「っ」を、大きい「つ」と同じ tsu で書いてしまう。さらにのばす音「う」もそのまま u と書くため、まったく別の読み方になる。\",\"correctAnswer\":\"gakko\",\"correctExplanation\":\"促音（小さい っ）は次の子音を重ねて表す。「がっこう」は次が k なので kk となり gakko である。のばす音は、パスポートや英語の文の中では書かないのがふつう。同じ形に きって＝kitte、さっぽろ＝Sapporo がある。\"},{\"question\":\"「しんいち」という名前をローマ字で書きなさい。\",\"wrongAnswer\":\"Shinichi\",\"trapExplanation\":\"ん＝n、いち＝ichi と、部分ごとに正しく書いているつもりでも、つなげると shi－ni－chi と読めてしまう。区切りを示す必要があることに気づきにくい。\",\"correctAnswer\":\"Shin'ichi\",\"correctExplanation\":\"「ん」のあとに母音や y が続くときは、アポストロフィ（'）で区切る。区切らないと「しにち」と読まれてしまう。同じ形に ほんや＝hon'ya、まんいん＝man'in がある。「ん」のあとに何が来るかを必ず確かめる。\"}]}",
"{\"id\":\"eigo_s034\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ローマ字③：ローマ字読みで英語を読まない\",\"description\":\"ローマ字と英語のつづりのきまりのちがいを知り、読みまちがいを防ぐ\",\"intro\":\"ローマ字を先に覚えてから英語を習うと、like を「リケ」、name を「ナメ」と読んでしまいます。ローマ字は日本語を書くための道具で、英語のつづりのきまりとは別ものです。ここで頭を切りかえましょう。\",\"order\":534,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"ローマ字は日本語を書くための道具であり、英語のつづりのきまりとは別のもの。\",\"ローマ字では a＝ア、i＝イ、u＝ウ、e＝エ、o＝オ と1対1。英語ではそうならない。\",\"ローマ字読みのくせが出ると、like を「リケ」、name を「ナメ」と読んでしまう。\",\"同じつづりでも読み方がちがう：ローマ字の e は「エ」、英語の語末の e は読まない。\",\"ローマ字が役に立つのは、日本語の音を書き表すときと、日本語の語を英語の文に入れるときだけ。\"],\"sections\":[{\"heading\":\"2つの体系のちがい\",\"body\":\"ローマ字と英語は、同じアルファベットを使うが、まったく別のきまりで動いている。ここを区別しないと、英語の読み書きがいつまでも安定しない。\\n\\n■ ローマ字のきまり\\n・母音字は5つで、それぞれ1つの音だけを表す（a＝ア、i＝イ、u＝ウ、e＝エ、o＝オ）。\\n・子音字＋母音字で1つの音のかたまりを作る（ka, si, tu）。\\n・つづりを見れば読み方が必ず決まる。例外がない。\\n\\n■ 英語のきまり\\n・母音字5つで20前後の音を表す。同じ a でも cat, cake, car, all で音がちがう。\\n・子音が続くことがある（street, texts）。\\n・語末の e は読まない（name, like, cake）。\\n・読まない文字がある（know, write, night）。\\n\\n■ ローマ字読みをしてしまう例\\nlike → 「リケ」（正しくは「ライク」）\\nname → 「ナメ」（正しくは「ネイム」）\\nmake → 「マケ」（正しくは「メイク」）\\ntime → 「ティメ」（正しくは「タイム」）\\nhouse → 「ホウセ」（正しくは「ハウス」）\\n\\n★ ポイント：英語の語を見たら、まずフォニックスのきまり（短母音・長母音・マジックE）を思い出す。ローマ字のきまりは頭から切りはなす。\",\"figureId\":\"xf_eigo_s034\"},{\"heading\":\"まぎらわしい組み合わせ\",\"mangaId\":\"eigo_s034_manga\",\"body\":\"ローマ字と英語で、同じつづりなのに読み方がちがう例を確かめておく。\\n\\n■ 語末の e\\nローマ字… ike（いけ）、ie（いえ）→ e を「エ」と読む\\n英語… like（ライク）、bike（バイク）→ e は読まない\\n■ i\\nローマ字… i は「イ」\\n英語… i は短母音で「イ」（sit）、長母音で「アイ」（bike, night, my）\\n■ u\\nローマ字… u は「ウ」\\n英語… u は短母音で「ア」に近い（cup）、長母音で「ユー」（use, music）\\n■ ei\\nローマ字… ei は「エイ」（sensei）\\n英語… ei は「イー」（receive）や「エイ」（eight）\\n■ ai\\nローマ字… ai は「アイ」（ai＝愛）\\n英語… ai は「エイ」（rain, train）\\n\\n■ 日本語が英語に入った語\\nsushi, tempura, karaoke, judo, origami, tsunami, manga などは、英語の中でもローマ字に近いつづりのまま使われている。ただし発音は英語風になる（karaoke は「キャリオウキ」に近い）。\\n\\n⚠ 注意：ローマ字は日本語を書くための道具であって、英語の読み方を教えてくれるものではない。「ローマ字ができるから英語も読める」と考えると、かえって読みまちがいが増える。\"}],\"trapExamples\":[{\"question\":\"「name」の読み方を答えなさい。\",\"wrongAnswer\":\"ナメ（ローマ字のとおりに n－a－m－e と読む）\",\"trapExplanation\":\"国語でローマ字を習った直後は、アルファベットを見るとローマ字のきまりで読んでしまう。ローマ字では e を「エ」と読むので、語末の e も声に出してしまう。\",\"correctAnswer\":\"ネイム（[neɪm]。語末の e は読まず、a が長母音になる）\",\"correctExplanation\":\"name は「子音＋母音＋子音＋e」の形なので、マジックE のきまりが働く。語末の e は読まず、そのかわり a がアルファベット読み（エイ）になる。同じ形に like（ライク）、make（メイク）、time（タイム）、home（ホウム）がある。\"},{\"question\":\"英語の rain と、ローマ字の「あい（ai）」では、ai の読み方は同じか。\",\"wrongAnswer\":\"同じ（どちらも「アイ」と読む）\",\"trapExplanation\":\"つづりが同じ ai なので、読み方も同じだと考えてしまう。ローマ字のきまりを英語にそのまま持ちこむと、rain を「ライン」と読むまちがいにつながる。\",\"correctAnswer\":\"ちがう（ローマ字の ai は「アイ」、英語の ai は「エイ」）\",\"correctExplanation\":\"英語の ai は「エイ」と読む（rain, train, wait, paint）。ローマ字の ai は a と i をそれぞれ読むので「アイ」である。英語で「アイ」の音を表すのは i_e（bike）、igh（night）、y（my）などである。ローマ字と英語は別のきまりで動いていることを、つねに意識する。\"}]}",
"{\"id\":\"eigo_s035\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ローマ字④：名前・地名の書き方\",\"description\":\"英語の文の中で自分の名前や日本の地名をどう書くかを決められるようにする\",\"intro\":\"自己紹介で自分の名前を英語で書くとき、姓が先か名が先か迷いませんか。今の公用文では姓を先にするのが原則で、姓をすべて大文字にする書き方もあります。地名や「〜山」「〜駅」の書き方もここで決めておきます。\",\"order\":535,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"名前は姓も名も最初の1文字を大文字にする（Masaya Nanjo／Nanjo Masaya）。\",\"英語の文では「名－姓」の順が長く使われてきたが、公用文では「姓－名」の順が原則になった。\",\"姓をはっきり示したいときは、姓をすべて大文字で書く（NANJO Masaya）。\",\"地名も最初の1文字を大文字にする（Tokyo, Osaka, Kyoto, Hokkaido）。\",\"「〜山」は Mt.、「〜駅」は Station、「〜川」は River を付ける（Mt. Fuji, Tokyo Station）。\"],\"sections\":[{\"heading\":\"名前の書き方\",\"body\":\"英語の文の中で自分の名前を書く機会は多い。自己紹介の英作文、英検の解答用紙、入試の答案などである。\\n\\n■ 基本のきまり\\n・姓も名も、最初の1文字を大文字にする。\\n・姓と名のあいだは1文字分あける。\\n　例）Masaya Nanjo ／ Nanjo Masaya\\n\\n■ 順番について\\nかつては英語の文では「名－姓」の順に書くのがふつうだった（Masaya Nanjo）。しかし、日本語の姓名の順を尊重する考え方から、国の方針として公用文では「姓－名」の順に書くことが原則となった（Nanjo Masaya）。\\nどちらでも通じるが、姓と名を取りちがえられないように、姓をすべて大文字で書く方法がある。\\n　例）NANJO Masaya\\n\\n■ 入試ではどうするか\\n学校の指示があればそれに従う。指示がなければ、どちらの順でもよい。ただし、答案の中で順番を統一する。\\n\\n■ 名前のつづり\\nヘボン式で書く。のばす音は書かない。\\n　こうた … Kota　ゆうき … Yuki　しょう … Sho　じゅんこ … Junko\\n\\n★ ポイント：自分の名前のつづりは、書けて当たり前として出題される。今のうちに1つに決めて、書き慣れておく。\",\"figureId\":\"xf_eigo_s035\"},{\"heading\":\"地名・固有名詞の書き方\",\"body\":\"■ 地名\\n最初の1文字を大文字にする。ヘボン式でつづり、のばす音は書かない。\\n　東京 … Tokyo　大阪 … Osaka　京都 … Kyoto　北海道 … Hokkaido\\n　九州 … Kyushu　名古屋 … Nagoya　神戸 … Kobe　広島 … Hiroshima\\n\\n■ 地形・建物には英語の語を付ける\\n山 … Mt.（Mount の略）… Mt. Fuji（富士山）, Mt. Aso\\n川 … River … the Shinano River（信濃川）\\n海 … Sea … the Sea of Japan（日本海）\\n駅 … Station … Tokyo Station, Osaka Station\\n公園 … Park … Ueno Park\\n神社・寺 … Shrine / Temple … Meiji Shrine, Kinkakuji Temple\\n\\n■ 国名・言語名\\n日本 … Japan　日本語 … Japanese　日本人 … Japanese\\n中国 … China　中国語・中国人 … Chinese\\nアメリカ … America / the United States　英語 … English\\n\\n■ よくあるまちがい\\n・Tokyo を Toukyou と書く（入力用の書き方なので、英語の文では使わない）\\n・fuji のように小文字で書き始める\\n・Mt.Fuji のようにピリオドのあとをあけずに書く（Mt. Fuji と1文字分あける）\\n\\n⚠ 注意：日本の地名は、英語の中では日本語の語をそのまま使う。「東京」は Eastern Capital などと訳さない。固有名詞は訳さずに音を写す、というのが原則である。\",\"mangaId\":\"eigo_s035_xm\"}],\"trapExamples\":[{\"question\":\"英語の自己紹介文で「私は東京に住んでいます。」と書きたい。正しい英文はどれか。\",\"wrongAnswer\":\"I live in toukyou.\",\"trapExplanation\":\"ローマ字入力のつづり（toukyou）をそのまま書き、さらに地名を小文字で書き始めてしまう。パソコンやスマートフォンで打ち慣れたつづりが手に残っていることが原因である。\",\"correctAnswer\":\"I live in Tokyo.\",\"correctExplanation\":\"地名は最初の1文字を大文字にする。またヘボン式では、のばす音を書かないので Toukyou ではなく Tokyo となる。同じく Osaka（Oosaka ではない）、Kyoto（Kyouto ではない）、Sato（Satou ではない）も同じ考え方である。\"},{\"question\":\"英語で「富士山」と書きなさい。\",\"wrongAnswer\":\"Fujisan Mountain\",\"trapExplanation\":\"日本語の「〜山」をそのままローマ字にしたうえで、英語の Mountain も付けてしまう。「山」の意味が二重になっていることに気づきにくい。\",\"correctAnswer\":\"Mt. Fuji\",\"correctExplanation\":\"「〜山」は Mt.（Mount の略）を前に付けて表す。Mt. Fuji で「富士山」の意味になるので、さらに Mountain を付ける必要はない。Mt. のあとは1文字分あける。同じ形に Mt. Aso（阿蘇山）、the Shinano River（信濃川）、Tokyo Station（東京駅）がある。\"}]}",
"{\"id\":\"eigo_s036\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まちがえやすいつづり①：曜日と月の名前\",\"description\":\"入試で必ず出る曜日・月のつづりを、まちがえやすい点とともに固める\",\"intro\":\"Wednesday の d、February の最初の r。どちらも発音ではほとんど聞こえないのに、書かなければ不正解です。曜日と月の名前は入試で必ず出るうえ、文のとちゅうでも大文字で書き始めます。ここで固めます。\",\"order\":536,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"曜日・月の名前は、文のとちゅうでも必ず大文字で書き始める。\",\"Wednesday は d を落としやすい。「ウェド・ネス・デイ」と区切って覚える。\",\"Tuesday は ue の順。Thursday は th で始まる。Saturday は u（Saterday ではない）。\",\"February は最初の r を落としやすい。August は最後が t（Augast ではない）。\",\"曜日の前には on、月の前には in を使う（on Monday／in April）。\"],\"sections\":[{\"heading\":\"曜日のつづり\",\"body\":\"曜日と月の名前は、中学入試・英検で必ず出る。しかもつづりがまぎらわしい語が多い。\\n\\n■ 7つの曜日\\nSunday（日曜日）\\nMonday（月曜日）\\nTuesday（火曜日）… u と e の順に注意。Teusday ではない。\\nWednesday（水曜日）… d を書き落としやすい。読みは「ウェンズデイ」。\\nThursday（木曜日）… th で始まる。Thursday の r も落としやすい。\\nFriday（金曜日）\\nSaturday（土曜日）… u を書く。Saterday ではない。\\n\\n■ 覚え方\\nWednesday … 「ウェド・ネス・デイ」と、書く用の読み方をして覚える。\\nTuesday … Tues＋day。Tue で区切ると u→e の順が定着する。\\nThursday … Thurs＋day。木曜日は th の音で始まる。\\nSaturday … Sat＋ur＋day。「サタデー」の「タ」のあとが u。\\n\\n■ 使い方\\n曜日の前には on を使う。\\n　例）I play tennis on Sunday.（日曜日にテニスをします）\\n　例）We have English classes on Monday and Friday.\\n\\n★ ポイント：曜日は文のとちゅうでも大文字で書き始める。on sunday と書くと不正解になる。\"},{\"heading\":\"月のつづり\",\"body\":\"■ 12か月\\nJanuary（1月）… Jan は「ジャン」ではなく「ジャニュ」\\nFebruary（2月）… 最初の r を落として Febuary と書くまちがいが非常に多い\\nMarch（3月）\\nApril（4月）\\nMay（5月）\\nJune（6月）\\nJuly（7月）\\nAugust（8月）… 最後は t。Augast ではない\\nSeptember（9月）\\nOctober（10月）… Octorber と r を入れすぎるまちがいに注意\\nNovember（11月）\\nDecember（12月）\\n\\n■ 使い方\\n月の前には in を使う。\\n　例）My birthday is in June.（誕生日は6月です）\\n日付まで言うときは on を使う。\\n　例）My birthday is on June 10.（6月10日です）\\n\\n■ 日付の書き方\\nアメリカ式… June 10, 2026（月－日－年）\\nイギリス式… 10 June 2026（日－月－年）\\n入試ではアメリカ式が多い。\\n\\n■ 序数とセットで\\n日付は序数（1番目、2番目…）で読む。June 10 は「ジューン・テンス」と読む。\\nfirst, second, third, fourth, fifth, … twentieth, twenty-first\\n\\n⚠ 注意：September から December は語尾が -ber でそろっている。September, October, November, December の4つをまとめて書く練習をすると定着が速い。\"},{\"heading\":\"なぜ読まない文字があり、なぜ大文字で始めるのか\",\"mangaId\":\"eigo_s036_manga\",\"body\":\"Wednesday の d や February の最初の r は、発音ではほとんど聞こえません。これは、英語のつづりが**昔の発音のまま残っている**からです。Wednesday はもともと「ウォーデンの日」という意味で、発音が変わっても文字は変わりませんでした。だから音のとおりに書くと文字が落ちます。防ぐには、「ウェド・ネス・デイ」「フェブ・ル・アリー」のように**書く用の読み方**で覚えるのが確実です。\\n\\n曜日・月の名前を文のとちゅうでも大文字で始めるのは、英語では**固有名詞（人名・地名・曜日・月）は大文字で始める**というきまりがあるからです。曜日や月は、神や皇帝の名前から来た固有名詞なので、on sunday と小文字で書くと不正解になります。曜日の前に on、月の前に in を使うのも、決まった組み合わせとして覚えます。\\n\\n■ 確かめのしかた\\n①曜日・月を書いたら、**大文字で始まっているか**を見る。\\n②落としやすい文字を確かめる：Wednesday の d、Thursday の r、Saturday の u、February の最初の r、August の最後の t、October に余分な r を入れていないか。\\n③つづりを区切って読めるか：Tues＋day、Thurs＋day、Sat＋ur＋day、Feb＋ru＋ary。\\n④前置詞は on＋曜日（on Sunday）、in＋月（in June）、on＋日付（on June 10）。日付は序数で読む（June tenth）。\\n\\n★ ここがポイント：つづりは**昔の発音のまま残っている**ので、聞こえない文字がある。**書く用の読み方**（ウェド・ネス・デイ）で覚え、曜日・月は**固有名詞なので大文字**で始める。on＋曜日、in＋月。\",\"figureId\":\"xf_eigo_s036\"}],\"trapExamples\":[{\"question\":\"「私は水曜日にピアノを習っています。」の「水曜日に」にあたる部分を英語で書きなさい。\",\"wrongAnswer\":\"on wensday\",\"trapExplanation\":\"Wednesday は「ウェンズデイ」と読むので、聞こえたとおりに書くと読まない d と e が抜ける。さらに曜日を大文字で書き始めるきまりも忘れやすい。\",\"correctAnswer\":\"on Wednesday\",\"correctExplanation\":\"Wednesday は W－e－d－n－e－s－d－a－y の9文字。読まない d と e を落とさないよう「ウェド・ネス・デイ」と区切って覚える。曜日名は文のとちゅうでも大文字で書き始め、曜日の前には on を使う。\"},{\"question\":\"「私の誕生日は2月です。」を英語で書きなさい。\",\"wrongAnswer\":\"My birthday is in Febuary.\",\"trapExplanation\":\"February は「フェブラリー」と読み、最初の r をはっきり発音しないことが多い。そのため音のとおりに書くと Febuary となり、r が1つ抜ける。\",\"correctAnswer\":\"My birthday is in February.\",\"correctExplanation\":\"February は F－e－b－r－u－a－r－y で、r が2つある。「フェブ・ル・アリー」と区切って書く練習をする。月の前には in を使い（in February）、日付まで言うときは on を使う（on February 3）。月名も大文字で書き始める。\"}]}",
"{\"id\":\"eigo_s037\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まちがえやすいつづり②：弱く読む部分がある語\",\"description\":\"発音では消えてしまう母音を含む語を、書くとき専用の読み方で覚える\",\"intro\":\"favorite を聞こえたとおりに書くと favrite になります。chocolate も、まん中の母音が消えて聞こえます。英語には「読むときは消えるのに、書くときは要る母音」があるのです。書く用の読み方で覚えます。\",\"order\":537,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"アクセントのない音節の母音は弱くあいまいになり、書くときに落としやすい。\",\"favorite（フェイヴァリット）、chocolate（チョコレット）、vegetable（ヴェジタブル）は、まん中の母音が消えやすい。\",\"different、interesting、every、family も、読むときは音が1つ減る。\",\"書くとき専用の読み方（つづり読み）をして覚える。favorite なら「ファ・ヴォ・リ・テ」。\",\"英語の答案では、1文字足りないだけで不正解になる。書いたあとに音節ごとに指で確かめる。\"],\"sections\":[{\"heading\":\"音が消える語\",\"body\":\"英語では、アクセントのない音節の母音は弱くあいまいになり、ときにはほとんど聞こえなくなる。そのため、聞こえたとおりに書くと文字が足りなくなる。\\n\\n■ 母音が消えやすい語\\nfavorite（お気に入りの）… fa・vo・rite の3音節だが、実際は「フェイヴリット」と2音節に近く聞こえる。まん中の o を落として favrite と書くまちがいが多い。\\nchocolate（チョコレート）… cho・co・late の3音節だが「チョクレット」に近い。2つ目の o を落としやすい。\\nvegetable（野菜）… ve・ge・ta・ble の4音節だが「ヴェジタブル」と3音節に聞こえる。e を落として vegtable と書きやすい。\\ndifferent（ちがう）… dif・fe・rent だが「ディフレント」に近い。まん中の e を落としやすい。\\ninteresting（おもしろい）… in・te・res・ting だが「イントレスティング」に近い。\\nevery（すべての）… ev・e・ry だが「エヴリ」に近い。\\nfamily（家族）… fa・mi・ly だが「ファムリ」に近い。\\ncamera（カメラ）… ca・me・ra だが「キャムラ」に近い。\\n\\n■ 対策：書くとき専用の読み方をする\\n発音とは別に、書くための読み方を決めてしまう。\\n　favorite … 「ファ・ヴォ・リ・テ」\\n　chocolate … 「チョ・コ・ラ・テ」\\n　vegetable … 「ヴェ・ゲ・タ・ブレ」\\nこのように1字ずつ声に出しながら書くと、消える母音を落とさなくなる。\\n\\n★ ポイント：漢字の書き取りで「口へんに未」と唱えるのと同じ。書く用の唱え方を作るのがいちばん確実である。\",\"figureId\":\"xf_eigo_s037\",\"mangaId\":\"eigo_s037_xm\"},{\"heading\":\"よく出る語のつづり点検\",\"body\":\"中学入試・英検4級〜3級で頻出の、つづりをまちがえやすい語をまとめる。\\n\\n■ 長めの語\\nbeautiful（美しい）… beau の部分が独特。「ベ・アウ・ティ・フル」と唱える。\\nbecause（なぜなら）… be＋cause。「ビ・カウ・セ」と唱える。becouse と書くまちがいが多い。\\nrestaurant（レストラン）… au と最後の t。「レス・タウ・ラント」と唱える。\\ndelicious（おいしい）… ci の部分が「シ」の音。deliscious と s を入れすぎない。\\nimportant（大切な）… im＋port＋ant。\\ndifficult（むずかしい）… dif＋fi＋cult。f が2つ。\\nbreakfast（朝食）… break＋fast。ea を「エ」と読む語。\\numbrella（かさ）… l が2つ。\\nhospital（病院）… hos＋pi＋tal。\\nlibrary（図書館）… lib＋ra＋ry。r が2つ。\\nJanuary（1月）… Jan＋u＋a＋ry。\\n\\n■ 音とつづりがずれる語\\nenough（十分な）… gh を「フ」と読む\\nlisten（聞く）… t を読まない\\nanswer（答え）… w を読まない\\noften（しばしば）… t を読まないことが多い\\nscience（科学）… c を「ス」と読む\\nworld（世界）… or を「アー」と読む\\n\\n⚠ 注意：つづりを覚えるときは、必ず声に出しながら手で書く。目で見るだけでは定着しない。同じ語を3回書いて、4回目は見ないで書く、という順序が効率がよい。\"}],\"trapExamples\":[{\"question\":\"「私の好きな教科は理科です。」の「好きな（お気に入りの）」にあたる語を書きなさい。\",\"wrongAnswer\":\"favrite\",\"trapExplanation\":\"favorite は「フェイヴリット」と2音節に近く発音され、まん中の o がほとんど聞こえない。音のとおりに書くと o が1つ抜ける。\",\"correctAnswer\":\"favorite（My favorite subject is science.）\",\"correctExplanation\":\"favorite は fa・vo・rite の3音節で、まん中に o がある。書くときは「ファ・ヴォ・リ・テ」と1字ずつ唱えて書く。同じように母音が消えやすい語に chocolate、vegetable、different、every、camera がある。\"},{\"question\":\"「野菜」を表す英単語を書きなさい。\",\"wrongAnswer\":\"vegtable\",\"trapExplanation\":\"vegetable は「ヴェジタブル」と3音節に聞こえるが、実際には4音節でつづられている。2つ目の e が発音で消えるため、書くときに落としてしまう。\",\"correctAnswer\":\"vegetable\",\"correctExplanation\":\"vegetable は ve・ge・ta・ble の4音節。書くときは「ヴェ・ゲ・タ・ブレ」と区切って唱える。g のあとの e は、g を「ジ」と読ませる役目も持っている（e・i・y の前の g はジ）。この e を落とすと読み方まで変わってしまう。\"}]}",
"{\"id\":\"eigo_s038\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まちがえやすいつづり③：文字を重ねる語\",\"description\":\"同じ文字が2つ続く語を、重ねる位置とともに正確に書けるようにする\",\"intro\":\"tomorrow の r、dinner の n。音を聞いても1つにしか聞こえないので、書くときに落としがちです。どこで文字を重ねるのかは丸暗記に見えますが、run から running のように理由のあるものもあります。\",\"order\":538,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"同じ文字が2つ続く語は、音を聞いても1つにしか聞こえないため落としやすい。\",\"r を重ねる語：tomorrow、sorry、carry、hurry。\",\"n を重ねる語：dinner、beginning、tennis、running。\",\"その他：summer（m）、happy（p）、letter（t）、soccer（c）、hobby（b）、address（d と s）。\",\"短母音＋子音1つで終わる語に ing・ed を付けるときは子音を重ねる（run→running）。\"],\"sections\":[{\"heading\":\"重ねる文字を落とさない\",\"body\":\"英語には、同じ文字が2つ続く語がたくさんある。しかし発音では1つの音にしか聞こえないため、書くときに落としやすい。\\n\\n■ r を重ねる語\\ntomorrow（明日）… to＋mor＋row。r が2つ、o が3つ。\\nsorry（ごめんなさい）\\ncarry（運ぶ）／hurry（急ぐ）／marry（結婚する）\\n■ n を重ねる語\\ndinner（夕食）／tennis（テニス）／beginning（始まり）／running（走っている）\\n■ m を重ねる語\\nsummer（夏）／swimming（泳いでいる）\\n■ p を重ねる語\\nhappy（幸せな）／apple（りんご）／supper（夕食）／shopping（買い物）\\n■ t を重ねる語\\nletter（手紙）／better（よりよい）／little（小さい）／bottle（びん）／getting\\n■ その他\\nsoccer（サッカー・c が2つ）／hobby（趣味・b が2つ）／address（住所・d と s が2つずつ）／difficult（f が2つ）／office（会社・f が2つ）／class（授業・s が2つ）／grass（草・s が2つ）\\n\\n■ 数え方の練習\\ntomorrow … t－o－m－o－r－r－o－w（8文字、o が3つ、r が2つ）\\nbeginning … b－e－g－i－n－n－i－n－g（9文字、n が3つ）\\n\\n★ ポイント：重ねる文字がある語は、書いたあとに「文字数」を数えて確かめる。tomorrow は8文字、と数で覚えておくと点検が速い。\"},{\"heading\":\"重ねるかどうかのきまり\",\"body\":\"語尾に ing や ed、er や est を付けるとき、最後の子音を重ねるかどうかにはきまりがある。\\n\\n■ 重ねる条件（3つすべてを満たすとき）\\n①1音節の語（または最後の音節を強く読む語）\\n②母音字が1つだけ\\n③子音字1つで終わる\\n　run → running　swim → swimming　sit → sitting　stop → stopping\\n　big → bigger／biggest　hot → hotter／hottest\\n　begin → beginning（最後の音節 -gin を強く読むので重ねる）\\n\\n■ 重ねない場合\\n・母音字が2つある … read → reading　look → looking　rain → raining\\n・子音字が2つ続く … help → helping　jump → jumping　want → wanted\\n・語末が e … make → making　use → used\\n・最後の音節を強く読まない … visit → visiting（VIS-it と前を強く読む）\\n\\n■ 比べて確かめる\\nhop（ぴょんと跳ぶ）→ hopping　／　hope（望む）→ hoping\\nplan（計画する）→ planning　／　play（遊ぶ）→ playing\\nsit（すわる）→ sitting　／　eat（食べる）→ eating\\n\\n⚠ 注意：hopping と hoping は1文字ちがいでまったく別の語になる。母音が短いか長いかを、重ねるかどうかで書き分けている。文字を重ねることには、音を短く保つという役目がある。\",\"figureId\":\"xf_eigo_s038\",\"mangaId\":\"eigo_s038_xm\"}],\"trapExamples\":[{\"question\":\"「明日会いましょう。」の「明日」にあたる語を書きなさい。（See you （　）.）\",\"wrongAnswer\":\"tomorow\",\"trapExplanation\":\"tomorrow は「トゥモロウ」と読み、r の音が1つにしか聞こえない。音のとおりに書くと r が1つ足りなくなる。o が3つあることも見落としやすい。\",\"correctAnswer\":\"tomorrow（See you tomorrow.）\",\"correctExplanation\":\"tomorrow は t－o－m－o－r－r－o－w の8文字で、o が3つ、r が2つある。「トゥ・モ・ロウ」と3つに区切って、まん中に r を2つ書くと覚える。同じく r を重ねる語に sorry, carry, hurry がある。\"},{\"question\":\"「泳ぐ（swim）」を「泳いでいる」の形にしなさい。\",\"wrongAnswer\":\"swiming\",\"trapExplanation\":\"「ing を付ける」というきまりだけで処理してしまい、子音を重ねる条件を確かめない。swiming と書いても見た目に違和感が少なく、まちがいに気づきにくい。\",\"correctAnswer\":\"swimming\",\"correctExplanation\":\"1音節で、母音字1つ＋子音字1つで終わる語は最後の子音を重ねる。swim→swimming、run→running、sit→sitting、stop→stopping、begin→beginning が同じ形。母音字が2つある read→reading や、子音字が2つ続く help→helping では重ねない。\"}]}",
"{\"id\":\"eigo_s039\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まちがえやすいつづり④：数と序数\",\"description\":\"基数と序数のつづりの変化を、まちがえやすい語を中心に固める\",\"intro\":\"four には u があるのに、forty には u がありません。nine には e があるのに、ninth では消えます。数のことばは毎日使うのに、つづりの変化がふぞろいです。まちがえやすい語から先につぶしておきましょう。\",\"order\":539,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"four は u があるが、forty には u がない（fourty は誤り）。\",\"five → fifteen／fifty、twelve → twelfth のように、ve が f に変わる。\",\"nine → ninth は e が消える（nineth は誤り）。nineteen・ninety は e が残る。\",\"eight → eighth は t が1つ（eightth ではない）。\",\"序数は th を付けるのが基本。first・second・third だけ形がちがう。\"],\"sections\":[{\"heading\":\"基数のつづり\",\"body\":\"数を表す語は、日付・年令・時刻・値段など、あらゆる場面で出てくる。つづりの変化にきまりがあるので整理する。\\n\\n■ 1〜12（形がそれぞれちがう）\\none, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve\\n\\n■ 13〜19（-teen が付く）\\nthirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen\\n・three → thirteen（three の形が変わる）\\n・five → fifteen（ve が f になる）\\n・eight → eighteen（t は1つのまま）\\n\\n■ 20〜90（-ty が付く）\\ntwenty, thirty, forty, fifty, sixty, seventy, eighty, ninety\\n・four → forty（u が消える。fourty は誤り。ここが最頻出のまちがい）\\n・five → fifty（ve が f になる）\\n・eight → eighty（t は1つ）\\n・nine → ninety（e は残る。e が消えるのは ninth）\\n\\n■ 大きな数\\nhundred（100）, thousand（1000）\\n21以上はハイフンでつなぐ… twenty-one, thirty-five, ninety-nine\\n100以上は and を入れることがある… one hundred and twenty\\n\\n★ ポイント：forty に u がないことと、fifteen・fifty が f になることは、必ず問われる。声に出して「フォーティーに u なし」と覚える。\",\"figureId\":\"xf_eigo_s039\"},{\"heading\":\"序数のつづり\",\"mangaId\":\"eigo_s039_manga\",\"body\":\"序数は「1番目・2番目…」を表す語で、日付・階数・順位で使う。\\n\\n■ 特別な形（3つだけ）\\nfirst（1番目）, second（2番目）, third（3番目）\\n\\n■ th を付けるのが基本\\nfourth, sixth, seventh, tenth, eleventh, thirteenth, fourteenth, sixteenth, seventeenth, eighteenth, nineteenth\\n\\n■ 形が変わるもの\\nfive → fifth（ve が f に）\\neight → eighth（t は1つのまま。eightth ではない）\\nnine → ninth（e が消える。nineth は誤り）\\ntwelve → twelfth（ve が f に）\\ntwenty → twentieth（y を ie に変えて th）\\nthirty → thirtieth／forty → fortieth／ninety → ninetieth\\n\\n■ 使い方\\n日付… May 5（May fifth と読む）／June 20（June twentieth）\\n階… the third floor（3階）\\n順位… He came in second.（2位だった）\\n21以上… twenty-first, twenty-second, thirty-first（後ろの数だけ序数にする）\\n\\n■ 短く書く方法\\n1st, 2nd, 3rd, 4th, 5th … 数字＋語尾の2文字で表す。\\n\\n⚠ 注意：nine → ninth と nineteen の e のあつかいがちがう。ninth では e が消え、nineteen では残る。まとめて書いて確かめる。\"}],\"trapExamples\":[{\"question\":\"「40」を表す英単語を書きなさい。\",\"wrongAnswer\":\"fourty\",\"trapExplanation\":\"4は four、14は fourteen と、どちらも u があるため、40も同じように u を入れてしまう。発音でも u の有無は聞き分けられないので、知識がないと必ずまちがえる。\",\"correctAnswer\":\"forty\",\"correctExplanation\":\"40 は forty で、u を書かない。four（4）と fourteen（14）には u があるのに、forty（40）だけ u がないという例外である。同じ仲間の変化に five→fifteen／fifty、nine→ninth（e が消える。ninety は e が残る）がある。数の語の中で最もまちがえやすい語なので、単独で覚える。\"},{\"question\":\"「9番目」を表す序数を書きなさい。\",\"wrongAnswer\":\"nineth\",\"trapExplanation\":\"序数は「基数に th を付ける」と覚えているため、nine にそのまま th をつなげてしまう。fourth や tenth が原則どおりなので、nine も同じだと考えてしまう。\",\"correctAnswer\":\"ninth\",\"correctExplanation\":\"nine の e を取ってから th を付けて ninth となる。同じように形が変わる序数に five→fifth、twelve→twelfth、eight→eighth（t は1つ）、twenty→twentieth がある。特別な形の first・second・third とあわせて、変化する序数だけをまとめて覚える。\"}]}",
"{\"id\":\"eigo_s040\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"総仕上げ：書き取り（ディクテーション）の手順\",\"description\":\"聞いた英文を正しく書き取るための手順と、書いたあとの点検項目を身につける\",\"intro\":\"書き取りでいちばん多いミスは、聞こえなかった a や the の落としと、文末のピリオド忘れです。つまり耳よりも手順で差がつきます。3回に分けて書き進めるやり方と、書き終えたあとの6つの点検項目を身につけます。\",\"order\":540,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"書き取りは3回に分けて行う。①意味をつかむ ②語を書く ③点検する。\",\"聞こえない語（a, the, to, of, and）は、意味から補って書く。\",\"点検項目は6つ。文頭の大文字／固有名詞の大文字／ピリオド・クエスチョンマーク／三単現の s／複数形の s／過去形。\",\"知らない語はフォニックスのきまりで音から組み立て、空白のままにしない。\",\"書いたあとは必ず声に出して読み返す。意味の通らない文はどこかがまちがっている。\"],\"sections\":[{\"heading\":\"3回に分けて書き取る\",\"body\":\"聞いた英文を書き取る練習をディクテーションという。フォニックスで学んだことをすべて使う総合練習である。手順を決めておくと、聞きもらしても立て直せる。\\n\\n■ 1回目：意味をつかむ\\n書かずに聞くことに集中する。何についての文かをつかむ。強く読まれる語（名詞・動詞・形容詞）だけを拾えば、意味の骨組みは分かる。\\n\\n■ 2回目：語を書く\\n語を1つずつ書いていく。聞き取れなかった部分は空白にして、下線を引いておく。全部を書こうとして止まらないことが大切である。\\n\\n■ 3回目：点検する\\n空白を埋め、次の6点を確かめる。\\n①文の最初は大文字か\\n②人名・地名・曜日・月・I は大文字か\\n③文の終わりにピリオド（.）か クエスチョンマーク（?）があるか\\n④主語が三人称単数で現在の文なら、動詞に s が付いているか\\n⑤複数を表す名詞に s が付いているか\\n⑥過去の文なら、動詞が過去形になっているか\\n\\n★ ポイント：点数を落とすのは、聞き取れなかった語よりも、この6点の見落としであることが多い。点検は必ず行う。\"},{\"heading\":\"聞こえない語を補う\",\"body\":\"弱く読まれる語は、実際にほとんど聞こえない。しかし文法の知識で補うことができる。\\n\\n■ 補いやすい語\\na / an … 数えられる名詞が1つのとき。次の音で a か an かを決める。\\nthe … すでに話に出た名詞や、1つしかないもの（the sun, the door）。\\nto … 動詞のあとに「〜へ」「〜すること」が続くとき（go to school, want to play）。\\nof … 「〜の」を表すとき（a cup of tea, a lot of books）。\\nand … 語や文をつなぐとき。\\n\\n■ 音のつながりに注意\\nan apple → 「アナポー」と聞こえる。an と apple の切れ目は聞こえない。\\na lot of → 「アロラヴ」に近い。\\nwant to → 「ワナ」に近く聞こえることがある。\\n聞こえたかたまりを、知っている語に分ける作業が必要になる。\\n\\n■ 知らない語が出たとき\\n空白のままにせず、フォニックスのきまりで音から組み立てて書く。\\n「キャット」と聞こえたら、短母音の a を使って cat と書く。\\n「ネイム」と聞こえたら、マジックE を使って name と書く。\\n部分点がもらえることもあるし、あとで確かめれば覚えられる。\\n\\n■ 最後に声に出して読み返す\\n書いた英文を小さな声で読み返す。意味が通らなければ、どこかがまちがっている。とくに主語と動詞の形が合っているかを確かめる。\\n\\n⚠ 注意：完ぺきに書き取れなくてもよい。強く読まれる語（意味の中心）が正しく取れていれば、内容は理解できている。まずそこを確実にする。\"},{\"heading\":\"なぜ耳より手順で差がつくのか\",\"mangaId\":\"eigo_s040_manga\",\"body\":\"書き取りで落とすのは、聞こえなかった難しい語ではなく、a・the・to・of・-s のような**弱く短く読まれる部分**です。これらはどんなに耳がよくてもほとんど聞こえません。しかし文法で決まっているので、**知識で補える**部分でもあります。He play soccer. と聞こえても、主語が He で現在の文なら plays に決まります。two cat と聞こえても、two があれば cats に決まります。だから、3回に分けて聞き、最後に6つの点検をする手順のほうが、耳を鍛えるより確実に点が上がります。\\n\\n1回目に書かずに意味をつかむのは、強く読まれる語（名詞・動詞・形容詞）が意味の骨組みで、それが分かれば弱い語を補う手がかりになるからです。聞こえない語を空白にして先へ進むのは、止まるとそのあとを全部聞きのがすからです。\\n\\n■ 確かめのしかた\\n①1回目は書かずに聞き、**何についての文か**を言えるか。\\n②2回目は語を書き、聞こえない所は下線を引いて空白にする。\\n③3回目に**6つの点検**：文頭の大文字／固有名詞・I の大文字／ピリオドか ? ／三単現の s／複数形の s／過去形。\\n④知らない語はフォニックスで組み立てる（「キャット」→cat、「ネイム」→name）。最後に**声に出して読み返し**、意味が通るか。every day は2語。\\n\\n★ ここがポイント：落とすのは**弱く読まれる語**で、それは**文法の知識で補える**。3回に分けて聞き、**6つの点検**を必ず行う。手順が耳を助ける。\",\"figureId\":\"xf_eigo_s040\"}],\"trapExamples\":[{\"question\":\"「彼は毎日サッカーをします。」を聞いて書き取りなさい。\",\"wrongAnswer\":\"He play soccer every day.\",\"trapExplanation\":\"主語が He（三人称単数）で現在の文なので動詞に s が必要だが、-s は弱く短く読まれるため聞き取れない。聞こえたとおりに書くと s が落ちる。\",\"correctAnswer\":\"He plays soccer every day.\",\"correctExplanation\":\"主語が三人称単数（he, she, it, 人名）で現在の文なら、動詞に s を付ける。聞き取れなくても文法の知識で補う。書き取りのあとの点検で「主語は何か」「現在の文か」を必ず確かめる。なお every day は2語に分けて書く（everyday は「毎日の」という形容詞で別の語）。\"},{\"question\":\"「I have two cat.」という書き取りの答えを見直しなさい。どこがまちがっているか。\",\"wrongAnswer\":\"まちがいはない（cat は聞こえたとおりに書いてある）\",\"trapExplanation\":\"語末の -s は弱く短いため聞こえないことが多く、聞こえたとおりに書くと落ちる。しかも文としては形が整って見えるので、見直しても気づきにくい。\",\"correctAnswer\":\"cat を cats にする（I have two cats.）\",\"correctExplanation\":\"two（2つ）という数を表す語があるので、名詞は複数形にしなければならない。cats の -s は、直前が無声音の t なので「ス」と読む。書き取りの点検では「数を表す語があるか」「その名詞は複数形になっているか」を必ず確かめる。\"}]}",
"{\"id\":\"eigo_s041\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞①：主語と「＝」で結ぶことば\",\"description\":\"am・is・are の三つがどんなはたらきをするのかを、日本語の「です」と区別してつかむ\",\"intro\":\"「私は学生。」は、日本語では動詞がなくても通じます。ところが英語で I a student. とは言えません。必ず am が要ります。be動詞は「です」ではなく「＝」だと考えると、なぜ省けないのかが見えてきます。\",\"order\":541,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞は am / is / are の三つ。「〜です」「〜である」と訳し、主語とあとの語を「＝」で結ぶ。\",\"語順は〈主語＋be動詞＋名詞または形容詞〉。I am a student. / She is kind.\",\"be動詞は日本語の「は」ではなく「＝」にあたる。「は」は主語のしるしにすぎない。\",\"あとに来るのが数えられる名詞の単数なら a / an を必ず付ける（I am a student.）。\",\"英語の文には必ず動詞が要る。「私は学生。」のような文でも am を省略できない。\"],\"sections\":[{\"heading\":\"be動詞は「＝」の記号\",\"mangaId\":\"eigo_s041_manga\",\"body\":\"英語の文は〈だれが〉〈どうする／どんなだ〉の順にならぶ。このうち「どんなだ」を表すときに使うのが be動詞である。be動詞には am・is・are の三つの形がある。\\n\\n■ 基本の形\\n主語＋be動詞＋名詞・形容詞\\n\\n例）I am a student.（私は学生です）\\n例）She is kind.（彼女は親切です）\\n例）They are my friends.（彼らは私の友達です）\\n\\n■ be動詞＝イコール\\nbe動詞のいちばん大事なはたらきは、主語とあとの語を「＝」でつなぐことである。\\n\\nI ＝ a student\\nShe ＝ kind\\nThey ＝ my friends\\n\\n日本語の「私は学生です」を見ると、「は」が be動詞にあたるように感じてしまう。しかし「は」は主語のしるし（主語を示す助詞）であって、be動詞ではない。be動詞にあたるのは文の終わりの「です」の部分である。\\n\\n★ ポイント：主語のあとに「＝」の記号を置く、と考えるとよい。I（私）＝ a student（学生）。この「＝」が am という形になって現れている。\",\"figureId\":\"xf_eigo_s041\"},{\"heading\":\"英語の文には必ず動詞が要る\",\"body\":\"日本語では「私は学生。」と言い切っても文になる。しかし英語では動詞のない文は作れない。\\n\\n✗ I a student.\\n○ I am a student.\\n\\nこれは英語の文の絶対のきまりである。「です」にあたる語が日本語で目立たないときほど、be動詞を落としやすいので注意する。\\n\\n■ 落としやすい形\\n形容詞が来るときは特に忘れやすい。\\n\\n✗ She kind.　　○ She is kind.（彼女は親切です）\\n✗ We happy.　　○ We are happy.（私たちは幸せです）\\n✗ I hungry.　　○ I am hungry.（私はおなかがすいています）\\n\\n「hungry（空腹の）」は形容詞なので、それだけでは文にならない。かならず am / is / are をはさむ。\\n\\n■ 名詞が来るときは a / an を忘れない\\n数えられる名詞が一つのときは、前に a（母音の音で始まる語には an）を付ける。\\n\\n例）I am a doctor.（私は医者です）\\n例）He is an English teacher.（彼は英語の先生です）\\n\\n⚠ 注意：人の名前や国名のように「一つしかないもの」には a を付けない。\\n例）I am Ken.（○）／ I am a Ken.（✗）\\n例）She is Japanese.（○）※ Japanese はここでは形容詞\"}],\"trapExamples\":[{\"question\":\"「私は野球の選手です。」を英語にしなさい。\",\"wrongAnswer\":\"I am baseball player.\",\"trapExplanation\":\"日本語には「一人の」にあたる語が出てこないので、a を入れる必要を感じない。am まで書けたところで安心してしまい、冠詞の確認をとばしてしまう。\",\"correctAnswer\":\"I am a baseball player.\",\"correctExplanation\":\"player は数えられる名詞で、ここでは一人のことなので a が必要である。be動詞のあとに数えられる名詞の単数が来たら、a / an が付いているかを必ず確かめる。母音の音で始まる語のときは an（I am an artist.）になる。\"},{\"question\":\"「彼女は親切です。」を英語にしなさい。\",\"wrongAnswer\":\"She kind.\",\"trapExplanation\":\"日本語の「親切です」は「親切」＋「です」で、「です」がおまけのように見える。そのため kind だけで「親切です」を表せていると思ってしまう。\",\"correctAnswer\":\"She is kind.\",\"correctExplanation\":\"kind は「親切な」という形容詞にすぎず、それだけでは文にならない。英語の文には必ず動詞が要るので、She と kind を「＝」で結ぶ is を入れる。形容詞が来る文ほど be動詞を落としやすいので、書き終わったら動詞があるかを見直す。\"}]}",
"{\"id\":\"eigo_s042\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞②：am・is・are の使い分け\",\"description\":\"主語の人称と単数・複数によって be動詞の形が決まるしくみを整理する\",\"intro\":\"You is my friend. と書いてしまう人は少なくありません。you は1人でも are だからです。be動詞は、主語が何人称で単数か複数かだけで自動的に決まります。3つの使い分けをここで整理しましょう。\",\"order\":542,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"am は主語が I のときだけ。世界中で I am しかない。\",\"is は主語が he / she / it、および「一人・一つ」の名詞のとき。\",\"are は主語が you / we / they、および「二つ以上」の名詞のとき。\",\"you は「あなた」一人でも are（× you is）。\",\"and で二つ以上つないだ主語は複数なので are。Ken and I are 〜／Tom and Mika are 〜。\"],\"sections\":[{\"heading\":\"三つの形の決まり方\",\"body\":\"be動詞の形は、主語がだれで、いくつあるかで決まる。決め方は次の三段階で考える。\\n\\n■ ①主語が I なら am\\n例）I am from Osaka.（私は大阪出身です）\\nam を使うのは主語が I のときだけである。ほかの主語で am を使うことはない。\\n\\n■ ②主語が you なら are\\n例）You are a good singer.（あなたは歌が上手です）\\nyou は「あなた」一人でも「あなたたち」でも are を使う。× You is とは絶対に言わない。\\n\\n■ ③そのほかは「一つなら is、二つ以上なら are」\\n一人・一つ → is\\n例）He is my brother. / She is a nurse. / This is my desk.\\n例）My father is a teacher.（father は一人 → is）\\n\\n二つ以上 → are\\n例）They are students. / We are in the same class.\\n例）My parents are teachers.（parents は二人 → are）\\n\\n★ ポイント：「I なら am、you なら are、あとは数で決める」。この順に確かめれば迷わない。\",\"figureId\":\"lf_eigoext02_042\"},{\"heading\":\"主語が長いときの見分け方\",\"mangaId\":\"eigo_s042_manga\",\"body\":\"入試でまちがえるのは、主語が一語ではなく長いかたまりになっているときである。be動詞は「主語のかたまりの中心の語」に合わせる。\\n\\n■ and でつないだ主語は複数\\n例）Ken and Yuki are in the library.（ケンとユキは図書室にいます）\\n例）My brother and I are good friends.（兄と私は仲よしです）\\n二人いるのだから are である。直前の I につられて am にしてはいけない。\\n\\n■ うしろに説明が付いた主語\\n主語のかたまりの中心（数を決めている語）を見つける。\\n\\n例）The boy with two dogs is my cousin.\\n　　（二匹の犬を連れた少年は私のいとこです）\\n中心は The boy（一人）なので is。直前の two dogs につられて are としない。\\n\\n例）The books on the desk are mine.\\n　　（机の上の本は私のものです）\\n中心は The books（複数）なので are。\\n\\n⚠ 注意：be動詞のすぐ前の語を見て決めるのではなく、「文の主語は何か」をつかんでから決める。前置詞（with / on / in など）から始まるかたまりは主語ではない。\"}],\"trapExamples\":[{\"question\":\"（　）に am / is / are のどれかを入れなさい。　Tom and I（　）in the same class.\",\"wrongAnswer\":\"am\",\"trapExplanation\":\"be動詞のすぐ前の語が I なので、「I なら am」の決まりをそのままあてはめてしまう。主語がどこからどこまでかを確かめていないために起こるまちがい。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"主語は Tom and I で、トムと私の二人である。二人以上なら are を使う。「I なら am」が使えるのは主語が I ひとつだけのときに限られる。and が見えたら、まず主語全体を丸で囲んで人数を数えるとよい。\"},{\"question\":\"（　）に am / is / are のどれかを入れなさい。　My brother's friends（　）very kind.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"文の先頭の My brother（兄・一人）だけを見て「一人だから is」と決めてしまう。所有を表す 's が付いた語は主語の中心ではないのに、目立つので主語だと思いこむ。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"主語は My brother's friends（兄の友達）で、中心の語は friends という複数形である。したがって are を使う。's が付いた語は「だれの」を説明しているだけなので、そのうしろの名詞が単数か複数かで be動詞を決める。\"}]}",
"{\"id\":\"eigo_s043\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞③：主語になる代名詞（I・you・he・she・it・we・they）\",\"description\":\"名詞を代名詞に置きかえるときの選び方と、それに合う be動詞を身につける\",\"intro\":\"「ケンと私は」を Ken and I is と続けたくなりますが、2人なので we、つまり are です。名詞を代名詞に置きかえられれば、be動詞も自動的に決まります。まずは7つの代名詞を押さえます。\",\"order\":543,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語になる代名詞は I / you / he / she / it / we / they の七つ。\",\"he＝男性一人、she＝女性一人、it＝人以外の一つ（動物・もの）。\",\"「〇〇と私」は we に置きかえる（Ken and I → we）。「〇〇とあなた」も you。\",\"人以外が二つ以上なら they。they は人にもものにも使える。\",\"代名詞が決まれば be動詞も決まる：I→am、he/she/it→is、you/we/they→are。\"],\"sections\":[{\"heading\":\"代名詞の選び方\",\"body\":\"同じ名詞をくり返さないために、二度目からは代名詞に置きかえる。どの代名詞を使うかは「だれ・何を指すか」と「一つか二つ以上か」で決まる。\\n\\n■ 一人・一つを指すもの\\nI（私は）… 自分\\nyou（あなたは）… 相手\\nhe（彼は）… 男性一人（my father, Ken, the boy など）\\nshe（彼女は）… 女性一人（my mother, Mika, the girl など）\\nit（それは）… 人以外の一つ（this book, the cat, my bag など）\\n\\n■ 二つ以上を指すもの\\nwe（私たちは）… 自分をふくむ二人以上\\nyou（あなたたちは）… 相手をふくむ二人以上\\nthey（彼らは／それらは）… 自分も相手もふくまない二つ以上\\n\\n例）Ken is my friend. He is from Kobe.（ケン → he）\\n例）This is my bag. It is new.（bag → it）\\n例）Mika and Yuki are sisters. They are twins.（二人 → they）\\n\\n★ ポイント：they は人だけでなくものにも使える。These are my books. They are old. のように、複数のものはすべて they になる。\",\"figureId\":\"xf_eigo_s043\"},{\"heading\":\"まとめて置きかえるとき\",\"body\":\"二つ以上の語がまとまって主語になっているときは、「自分が入っているか」「相手が入っているか」で決める。\\n\\n■ 自分（I）が入っていれば we\\nKen and I → we\\nMy family and I → we\\n例）Ken and I are in the tennis club. → We are in the tennis club.\\n\\n■ 自分は入らず、相手（you）が入っていれば you\\nYou and Tom → you\\n例）You and Tom are late. → You are late.\\n\\n■ 自分も相手も入っていなければ they\\nKen and Mika → they\\nMy father and mother → they\\n例）My father and mother are doctors. → They are doctors.\\n\\n⚠ 注意：「〇〇と私」を they にするまちがいが非常に多い。自分が入っているのだから「彼ら」ではなく「私たち」である。\\n\\n■ 代名詞が決まれば be動詞も決まる\\nI → am\\nhe / she / it → is\\nyou / we / they → are\\n主語を代名詞に置きかえてから be動詞を選ぶと、まちがいがへる。\",\"mangaId\":\"eigo_s043_xm\"}],\"trapExamples\":[{\"question\":\"下線部を代名詞にかえなさい。　Mika and I are in the music room.\",\"wrongAnswer\":\"They are in the music room.\",\"trapExplanation\":\"Mika という他人の名前が先に出てくるので、「ミカたち」＝彼ら、と考えて they を選んでしまう。自分（I）が主語の中にふくまれていることを見落としている。\",\"correctAnswer\":\"We are in the music room.\",\"correctExplanation\":\"主語に I（私）が入っているので、置きかえる代名詞は we（私たち）になる。they は自分も相手もふくまないときに使う語である。「and I」が見えたら自動的に we、と覚えておくとよい。be動詞は we でも are のままで変わらない。\"},{\"question\":\"下線部を代名詞にかえなさい。　That dog is very big.\",\"wrongAnswer\":\"He is very big.\",\"trapExplanation\":\"犬を飼っている人は犬を「彼」と呼ぶことがあるため、生きているものは he だと考えてしまう。日本語で「その子」と言う感覚に引きずられるのも原因である。\",\"correctAnswer\":\"It is very big.\",\"correctExplanation\":\"英語では、人以外の一つのものや動物は it で受けるのが基本である。he / she は人（男性・女性）に使う。飼っている動物を性別まで意識して he / she と呼ぶことはあるが、入試で「代名詞にかえよ」と問われたら it が正解になる。be動詞は it なので is。\"}]}",
"{\"id\":\"eigo_s044\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞④：短縮形（I'm・you're・isn't・aren't）\",\"description\":\"会話でよく使う短縮形の作り方と、アポストロフィの位置を正確に覚える\",\"intro\":\"会話では I am を I'm、is not を isn't のように縮めます。まちがえやすいのが its と it's です。it's は it is の短縮形、its は「その」を表す別の語。アポストロフィの位置にも理由があります。\",\"order\":544,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"〈主語＋be動詞〉の短縮：I'm / you're / he's / she's / it's / we're / they're。\",\"〈be動詞＋not〉の短縮：isn't / aren't。省いた文字の位置にアポストロフィを置く。\",\"am not には短縮形がない。I am not → I'm not（× I amn't）。\",\"it's ＝ it is の短縮形。「その」を表す its とはまったく別の語。\",\"文の終わりでは短縮形を使わない。Yes, I am.（× Yes, I'm.）\"],\"sections\":[{\"heading\":\"二種類の短縮形\",\"body\":\"会話や手紙では、二語をつづめて一語のように書くことが多い。これを短縮形という。be動詞の短縮形は二種類ある。\\n\\n■ ①〈主語＋be動詞〉をつづめる\\nI am → I'm\\nyou are → you're\\nhe is → he's\\nshe is → she's\\nit is → it's\\nwe are → we're\\nthey are → they're\\nthat is → that's\\n\\n例）I'm from Kyoto.（私は京都出身です）\\n例）They're in the gym.（彼らは体育館にいます）\\n\\n■ ②〈be動詞＋not〉をつづめる\\nis not → isn't\\nare not → aren't\\n\\n例）He isn't busy today.（彼は今日いそがしくありません）\\n例）We aren't hungry.（私たちはおなかがすいていません）\\n\\n★ ポイント：アポストロフィ（'）は「文字を省いたしるし」である。is not の o を省いたから isn't、are not の o を省いたから aren't。省いた文字のあった場所に置く、と考えれば位置をまちがえない。\"},{\"heading\":\"まちがえやすい三つの点\",\"mangaId\":\"eigo_s044_manga\",\"body\":\"■ ① am not に短縮形はない\\nbe動詞の中で am だけは not と結びついた短縮形を持たない。\\n\\n✗ I amn't busy.\\n○ I am not busy.\\n○ I'm not busy.（主語と be動詞のほうをつづめる）\\n\\n「〜ではありません」を短く言いたいときは I'm not の形にする。これは決まりなので理由なしに覚える。\\n\\n■ ② it's と its はまったく別の語\\nit's ＝ it is（それは〜です）\\nits ＝ その（持ち主を表す語）\\n\\n例）It's a cat.（それはねこです）\\n例）Its name is Tama.（その名前はタマです）\\nアポストロフィがあるかないかで意味が変わる。書き分けをまちがえると減点になる。\\n\\n■ ③ 文の終わりでは短縮しない\\n答えの文のように、be動詞が文の最後に来るときは短縮形を使わない。\\n\\n✗ Yes, I'm.　　○ Yes, I am.\\n✗ Yes, he's.　　○ Yes, he is.\\n\\n⚠ 注意：Yes, I'm not. のような形も存在しない。否定で答えるときは No, I'm not. または No, I am not. とする。\",\"figureId\":\"xf_eigo_s044\"}],\"trapExamples\":[{\"question\":\"「私はつかれていません。」を、短縮形を使って三語で書きなさい。\",\"wrongAnswer\":\"I amn't tired.\",\"trapExplanation\":\"is not → isn't、are not → aren't という規則を見て、am not も同じように amn't にできると考えてしまう。規則がきれいにそろっているように見えるだけに引っかかりやすい。\",\"correctAnswer\":\"I'm not tired.\",\"correctExplanation\":\"am not だけは短縮形を作らない。短くしたいときは主語と be動詞のほうをつづめて I'm not とする。三語という指定は I'm / not / tired の三語を指している。be動詞の短縮でつまずいたら「amn't は存在しない」と思い出すこと。\"},{\"question\":\"次の文の誤りを直しなさい。　Look at that cat. It's tail is very long.\",\"wrongAnswer\":\"It's tail is very long.（そのままで正しい）\",\"trapExplanation\":\"「その」を表す語だと分かっていても、it に何かを付けるときはアポストロフィが要ると思いこんでいる。名前を表す 's（Ken's bag）と混同するために起こる。\",\"correctAnswer\":\"Its tail is very long.\",\"correctExplanation\":\"it's は it is をつづめた形なので、そのまま入れると「それは しっぽ は とても長い」という意味の通らない文になる。「その〜」を表すのはアポストロフィのない its である。my / your / his / her と同じ仲間だと考えるとよい。\"}]}",
"{\"id\":\"eigo_s045\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞⑤：「〜にいる・〜にある」を表す使い方\",\"description\":\"be動詞のもう一つの意味（存在）と、There is / There are の文をつかむ\",\"intro\":\"「机の上に本があります」を英語にするとき、have を使いたくなります。でも持ち主の話ではないので My book is on the desk. と be動詞を使います。be動詞には「＝」のほかに「ある・いる」の意味があるのです。\",\"order\":545,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞には「〜です（＝）」のほかに「〜にいる・〜にある（存在）」の意味がある。\",\"〈主語＋be動詞＋場所を表す語句〉で「〜にいる／ある」。My book is on the desk.\",\"「〜がある」を have で表さない。持ち主を言うときだけ have を使う。\",\"There is ＋ 単数、There are ＋ 複数。「〜がある」と新しく話題に出すときの言い方。\",\"There is / are のあとに the や my の付いた語は置かない（× There is my book on the desk.）。\"],\"sections\":[{\"heading\":\"be動詞の二つ目の意味\",\"body\":\"be動詞には大きく二つの意味がある。\\n\\n■ ①「〜です」＝主語と結びつける\\n例）He is a doctor.（彼は医者です）\\n例）This flower is beautiful.（この花は美しいです）\\n\\n■ ②「〜にいる・〜にある」＝どこにあるかを言う\\nbe動詞のうしろに場所を表す語句が来ると、「存在」の意味になる。\\n\\n例）My father is in the kitchen.（父は台所にいます）\\n例）Your bag is on the chair.（あなたのかばんはいすの上にあります）\\n例）The station is near my house.（駅は私の家の近くにあります）\\n例）We are at school now.（私たちは今、学校にいます）\\n\\n場所を表すのは in（〜の中に）・on（〜の上に）・under（〜の下に）・near（〜の近くに）・by（〜のそばに）・at（〜に）などの語である。\\n\\n★ ポイント：be動詞のうしろを見て、名詞・形容詞なら「〜です」、場所なら「〜にいる／ある」と読み分ける。どちらの意味でも am / is / are の使い分けは変わらない。\"},{\"heading\":\"There is / There are の文\",\"body\":\"「（ある場所に）〜がある・〜がいる」と、聞き手がまだ知らないものを新しく話題に出すときは、There is / There are で文を始める。\\n\\n■ 形\\nThere is ＋ 単数のもの ＋ 場所\\nThere are ＋ 複数のもの ＋ 場所\\n\\n例）There is a cat under the table.（テーブルの下にねこが一匹います）\\n例）There are two libraries in this city.（この市には図書館が二つあります）\\n\\nbe動詞は There のうしろに来る名詞に合わせる。there 自体には「そこに」という意味はほとんどなく、文を始めるための語である。\\n\\n■ 使えない場合\\nThere is / are のあとには、the・my・this のような「すでに決まったもの」を表す語の付いた名詞は置かない。\\n\\n✗ There is my book on the desk.\\n○ My book is on the desk.（私の本は机の上にあります）\\n\\n自分の本は、聞き手ももう知っているものなので、ふつうの〈主語＋be動詞＋場所〉の文で表す。\\n\\n⚠ 注意：日本語の「〜がある」につられて have を使うまちがいが多い。have は「持っている」であって、場所を言う文には使えない。\",\"figureId\":\"xf_eigo_s045\",\"mangaId\":\"eigo_s045_xm\"}],\"trapExamples\":[{\"question\":\"「私のかさは玄関にあります。」を英語にしなさい。（umbrella／at the door を使う）\",\"wrongAnswer\":\"My umbrella has at the door.\",\"trapExplanation\":\"日本語の「ある」をそのまま「持っている（have）」に結びつけてしまう。「ある＝存在」と「持っている＝所有」が日本語では同じ言い方になることがあるため起こるまちがい。\",\"correctAnswer\":\"My umbrella is at the door.\",\"correctExplanation\":\"「〜にある」と場所を言う文では be動詞を使う。have は「（人が）〜を持っている」という意味で、I have an umbrella.（私はかさを持っています）のように主語が持ち主のときに使う。主語がもの、うしろが場所なら be動詞、と覚える。\"},{\"question\":\"（　）に is / are のどちらかを入れなさい。　There（　）three parks in my town.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"There is 〜 という形を一つのかたまりとして覚えてしまい、うしろの名詞が複数でも is のまま書いてしまう。There が単数のように見えるのも原因である。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"There is / are の be動詞は、うしろに来る名詞の数に合わせる。ここでは three parks と複数なので are になる。There は文を始めるための語で、数を決める語ではない。「There のうしろの名詞を数える」と手順にしておくとよい。\"}]}",
"{\"id\":\"eigo_s046\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞の否定文：not はどこに入れるか\",\"description\":\"be動詞の文を「〜ではありません」にかえるときの not の位置を確実にする\",\"intro\":\"I don't am a student. と書いてしまうのは、否定文には don't が要ると思いこんでいるからです。be動詞の文は not を後ろに置くだけで否定になります。do の出番はありません。位置を体で覚えましょう。\",\"order\":546,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞の否定文は〈主語＋be動詞＋not＋〜〉。not は be動詞のすぐうしろ。\",\"don't / doesn't は使わない（× I don't am 〜）。be動詞の文は not だけで否定できる。\",\"短縮形は isn't / aren't。am not に短縮形はなく、I'm not とする。\",\"not のうしろの a や the はそのまま残す。He is not a teacher.\",\"「〜にいない・〜にない」も同じ形。The cat is not under the table.\"],\"sections\":[{\"heading\":\"not は be動詞のすぐあと\",\"mangaId\":\"eigo_s046_manga\",\"body\":\"be動詞の文を否定文（「〜ではありません」）にするのはとても簡単で、be動詞のすぐうしろに not を入れるだけでよい。語順は変えない。\\n\\n■ 作り方\\nI am a student.（私は学生です）\\n→ I am not a student.（私は学生ではありません）\\n\\nShe is my sister.\\n→ She is not my sister.（彼女は私の姉ではありません）\\n\\nThey are in the classroom.\\n→ They are not in the classroom.（彼らは教室にいません）\\n\\n■ 短縮形を使うと\\nis not → isn't　　are not → aren't\\n例）She isn't my sister.\\n例）They aren't in the classroom.\\nam not だけは短縮形がないので、I'm not busy. のように主語のほうをつづめる。\\n\\n★ ポイント：be動詞の文には do や does は登場しない。× I don't am tired. のような文は英語には存在しない。be動詞そのものが「〜です」という動詞なので、not を付けるだけで否定になる。\",\"figureId\":\"lf_eigoext02_046\"},{\"heading\":\"否定文で気をつけること\",\"body\":\"■ ① a / the は消さない\\n否定文にしても、名詞に付く a や the はそのまま残る。\\n\\n例）He is a doctor. → He is not a doctor.（○）\\n✗ He is not doctor.\\n\\n■ ② not のうしろの形は変わらない\\n形容詞でも名詞でも場所でも、同じように not を入れるだけである。\\n\\n例）This question is not easy.（この問題はやさしくありません）\\n例）My father is not at home now.（父は今、家にいません）\\n例）Those aren't my shoes.（あれらは私のくつではありません）\\n\\n■ ③ 「〜も〜ない」の言い方\\ntoo（〜も）は肯定文で使い、否定文では either にかわる。\\n\\n例）I am a student, too.（私も学生です）\\n例）I am not a student, either.（私も学生ではありません）\\n中学受験でもときどき問われるので、否定文では either になることを覚えておく。\\n\\n⚠ 注意：not をどこに入れるか迷ったら、「be動詞をさがして、そのすぐ右に置く」と手順化する。主語の前や文の最後に置くことはない。\"}],\"trapExamples\":[{\"question\":\"「私は先生ではありません。」を英語にしなさい。\",\"wrongAnswer\":\"I don't am a teacher.\",\"trapExplanation\":\"「〜しません」を英語にするときは don't を使う、と一般動詞の否定文の作り方を覚えていて、それを be動詞の文にもあてはめてしまう。否定文＝don't という思いこみが原因である。\",\"correctAnswer\":\"I am not a teacher.（短縮形なら I'm not a teacher.）\",\"correctExplanation\":\"be動詞の文では、be動詞のすぐうしろに not を置くだけで否定文になる。do や does の助けは要らない。文の中に am / is / are があるかどうかをまず見て、あれば not だけを入れる、と手順を分けて覚えるとよい。\"},{\"question\":\"「彼らは同じクラスではありません。」を英語にしなさい。（in the same class を使う）\",\"wrongAnswer\":\"They not are in the same class.\",\"trapExplanation\":\"日本語では「同じクラスでは ない です」のように打ち消しがうしろに来るため、語順の感覚が定まらない。「not は主語のあと」とだけ覚えていると、be動詞の前に置いてしまう。\",\"correctAnswer\":\"They are not in the same class.（短縮形なら They aren't 〜）\",\"correctExplanation\":\"not は必ず be動詞のうしろに入る。主語→be動詞→not の順である。短縮形 aren't を使えば are と not の順番をまちがえようがないので、迷ったときは isn't / aren't の形で書くのも有効である。\"}]}",
"{\"id\":\"eigo_s047\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞の疑問文：主語と入れかえる\",\"description\":\"be動詞を文の先頭に出して疑問文を作る手順を、語順の図で確実にする\",\"intro\":\"Do you are a student? は動詞が2つになるので通じません。be動詞の文では、be動詞を主語の前に出すだけで疑問文になります。入れかえるだけ、というこの語順の操作を図で確かめましょう。\",\"order\":547,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞の疑問文は〈be動詞＋主語＋〜?〉。be動詞を主語の前に出す。\",\"文の終わりにクエスチョンマーク（?）を付ける。文頭は大文字にする。\",\"Do / Does は使わない（× Do you are 〜?）。\",\"疑問文では短縮形〈主語＋be動詞〉は使えない（× 're you 〜?）。\",\"主語が長いときは、そのかたまり全体をbe動詞のうしろに置く。Is the boy with a cap your brother?\"],\"sections\":[{\"heading\":\"入れかえるだけで疑問文になる\",\"body\":\"be動詞の文を疑問文（「〜ですか」）にするには、be動詞を主語の前に移すだけでよい。\\n\\n■ 作り方\\nYou are a student.（あなたは学生です）\\n→ Are you a student?（あなたは学生ですか）\\n\\nHe is your brother.\\n→ Is he your brother?（彼はあなたのお兄さんですか）\\n\\nThey are in the gym.\\n→ Are they in the gym?（彼らは体育館にいますか）\\n\\n移動させたあと、文のはじめの語は大文字で書き始め、終わりに ? を付ける。もとの文にあった大文字・小文字はそれに合わせて直す。\\n\\n■ 一般動詞の疑問文とはちがう\\n一般動詞の文では Do you 〜? のように do を借りてくるが、be動詞の文では do を使わない。\\n\\n✗ Do you are a student?\\n○ Are you a student?\\n\\n★ ポイント：be動詞は自分で前に出られる。do の助けが要るのは、前に出られない一般動詞のときだけである。\",\"figureId\":\"lf_eigoext02_047\"},{\"heading\":\"主語が長い疑問文\",\"body\":\"主語が二語以上のかたまりのときも、やることは同じである。be動詞をかたまりの前に出す。\\n\\n例）Your mother is a nurse.\\n→ Is your mother a nurse?（あなたのお母さんは看護師ですか）\\n\\n例）The boy with a cap is your brother.\\n→ Is the boy with a cap your brother?\\n主語は The boy with a cap の全体で、中心は boy（一人）なので be動詞は is である。your につられて Are にしないよう気をつける。\\n\\n例）Ken and Yuki are your friends.\\n→ Are Ken and Yuki your friends?\\n\\n■ 短縮形は使えない\\n疑問文では〈主語＋be動詞〉の短縮形を使えない。\\n\\n✗ 're you free today?\\n○ Are you free today?（今日はひまですか）\\n短縮形は主語のうしろに be動詞があるときにだけ作れるものだからである。\\n\\n⚠ 注意：疑問文にすると主語が be動詞のあとに来るので、be動詞をどれにするかを主語で決めるという順序は変わらない。先に主語を見つけてから、is か are かを決める。\",\"mangaId\":\"eigo_s047_xm\"}],\"trapExamples\":[{\"question\":\"「あなたはサッカーファンですか。」を英語にしなさい。（a soccer fan を使う）\",\"wrongAnswer\":\"Do you are a soccer fan?\",\"trapExplanation\":\"「〜ですか」とたずねる文は Do から始まる、と覚えているために、be動詞の文にも do を付け足してしまう。be動詞と一般動詞の疑問文の作り方を区別できていない。\",\"correctAnswer\":\"Are you a soccer fan?\",\"correctExplanation\":\"be動詞の文では、be動詞そのものを主語の前に出せば疑問文になる。do を借りる必要はない。文の中に am / is / are があるかを最初に確かめ、あればそれを前に出す、と手順を分ければ混同しない。\"},{\"question\":\"「あなたのお姉さんは高校生ですか。」を英語にしなさい。（a high school student を使う）\",\"wrongAnswer\":\"Are your sister a high school student?\",\"trapExplanation\":\"「あなたの」という語につられて、you に合う are を選んでしまう。your は主語の中心ではなく「だれの」を説明する語にすぎないのに、目立つので主語だと感じてしまう。\",\"correctAnswer\":\"Is your sister a high school student?\",\"correctExplanation\":\"主語は your sister（あなたのお姉さん）で、一人なので be動詞は is になる。疑問文にする前に、もとの文 Your sister is a high school student. を思いうかべて be動詞を決めると確実である。your / my / his などは数を決める語ではない。\"}]}",
"{\"id\":\"eigo_s048\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"be動詞の疑問文への答え方\",\"description\":\"Yes / No で答えるときの代名詞の選び方と、短縮形のきまりを整理する\",\"intro\":\"Are you hungry? に Yes, I'm. と答えると、英語では尻切れに聞こえます。Yes, I am. と最後まで言うのがきまりです。しかもたずねられた you は、答えるときには I か we に変わります。\",\"order\":548,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"答え方は Yes, 主語＋be動詞. / No, 主語＋be動詞＋not.\",\"主語は必ず代名詞にする（Is Ken 〜? → Yes, he is.）。\",\"you とたずねられたら I か we で答える。you のまま返さない。\",\"Yes の答えでは短縮形を使わない（× Yes, I'm. ○ Yes, I am.）。\",\"No の答えでは短縮形を使ってよい（No, I'm not. / No, he isn't.）。\"],\"sections\":[{\"heading\":\"答えの形と代名詞\",\"body\":\"be動詞の疑問文には、Yes か No のあとに〈主語＋be動詞〉を続けて答える。\\n\\n■ 基本の形\\nYes, 主語＋be動詞.\\nNo, 主語＋be動詞＋not.\\n\\n例）Are you tired? － Yes, I am. / No, I am not.\\n例）Is he a teacher? － Yes, he is. / No, he isn't.\\n例）Are they your friends? － Yes, they are. / No, they aren't.\\n\\n■ 主語は代名詞に置きかえる\\nたずねられた文の主語をそのままくり返さず、代名詞にする。\\n\\nIs Ken your brother? － Yes, he is.（× Yes, Ken is.）\\nIs this your bag? － Yes, it is.（this → it）\\nAre those your books? － Yes, they are.（those → they）\\n\\n■ you で聞かれたときの返し方\\nAre you 〜? と聞かれているのは自分のことなので、I で答える。\\nAre you and Tom 〜? のように二人以上を聞かれたら we で答える。\\n\\n例）Are you a student? － Yes, I am.\\n例）Are you and Tom in the same class? － Yes, we are.\\n\\n★ ポイント：問いの主語をそのまま返すと、意味がひっくり返ってしまう。「聞かれた相手の立場に立ちかえる」と考える。\",\"figureId\":\"xf_eigo_s048\"},{\"heading\":\"短縮形が使えるところ・使えないところ\",\"body\":\"答えの文では短縮形の使い方に決まりがある。\\n\\n■ Yes の答え → 短縮しない\\n✗ Yes, I'm.　　○ Yes, I am.\\n✗ Yes, he's.　　○ Yes, he is.\\n✗ Yes, they're.　○ Yes, they are.\\n\\nbe動詞が文の最後に来るときは短縮形にできない、というのが理由である。\\n\\n■ No の答え → 短縮してよい\\n○ No, I am not. ／ No, I'm not.\\n○ No, he is not. ／ No, he isn't. ／ No, he's not.\\nNo の答えでは not が最後に来るので、be動詞をつづめることができる。\\n\\n■ this / that / these / those の受け方\\nIs this your pen? － Yes, it is.\\nIs that your house? － Yes, it is.\\nAre these your shoes? － Yes, they are.\\nthis も that も、答えでは it になる。these / those は they になる。\\n\\n⚠ 注意：Yes, this is. のように this をそのまま使うのはまちがい。答えではすでに何を指すか分かっているので、代名詞の it / they を使う。\",\"mangaId\":\"eigo_s048_xm\"}],\"trapExamples\":[{\"question\":\"Are you a member of the tennis club? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, you are.\",\"trapExplanation\":\"問いの文にある you をそのまま写して答えてしまう。日本語では「はい、そうです」と主語を言わずに答えるので、だれのことを答えているのかを意識しないまま書き写しがちである。\",\"correctAnswer\":\"Yes, I am.\",\"correctExplanation\":\"Are you 〜? は「あなたは〜ですか」と自分がたずねられている文なので、答えるときは I（私）にかえる。Yes, you are. では「はい、あなたはそうです」となって答えにならない。you で聞かれたら I（二人以上なら we）で返す、と決めておく。\"},{\"question\":\"Is your father a doctor? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, he's.\",\"trapExplanation\":\"会話では he's をよく使うので、答えの文でも短くできると考えてしまう。短縮形は書けば書くほど自然に見えるため、使ってよい場所の制限に気づきにくい。\",\"correctAnswer\":\"Yes, he is.\",\"correctExplanation\":\"be動詞が文の最後に来るときは短縮形を使えない。Yes, he is. と書くのが正しい。ただし No で答えるときは not が最後に来るので、No, he isn't. のように短縮できる。「Yesの答えは短縮しない」と一つの規則で覚えておく。\"}]}",
"{\"id\":\"eigo_s049\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞＋be動詞：What・Who・Where でたずねる\",\"description\":\"「何・だれ・どこ」をたずねる文の語順と、Yes / No で答えないきまりをつかむ\",\"intro\":\"「トイレはどこですか」を Where is toilet? と言ってしまう人は多いのですが、the が抜けています。それ以前に語順の問題もあります。疑問詞は必ず文の先頭、そのあとに be動詞と主語。そして Yes・No では答えません。\",\"order\":549,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"語順は〈疑問詞＋be動詞＋主語＋〜?〉。疑問詞は必ず文のいちばん前。\",\"疑問詞の疑問文には Yes / No で答えない。たずねられた中身を答える。\",\"What is 〜? → What's 〜? のように短縮できる。\",\"be動詞は主語に合わせる。Where are my keys?（keys は複数 → are）\",\"Who is that boy? のように、Who のあとも〈be動詞＋主語〉の順になる。\"],\"sections\":[{\"heading\":\"疑問詞は文の先頭に置く\",\"body\":\"「何ですか」「だれですか」「どこにありますか」のように、Yes / No では答えられないことをたずねるときは疑問詞を使う。\\n\\n■ よく使う疑問詞\\nwhat（何）／who（だれ）／where（どこ）／when（いつ）／whose（だれの）／how（どのように・どれくらい）\\n\\n■ 語順\\n疑問詞＋be動詞＋主語＋〜?\\n\\n例）What is your name?（あなたの名前は何ですか）\\n例）Who is that girl?（あの女の子はだれですか）\\n例）Where is my pencil case?（私の筆箱はどこにありますか）\\n例）When is your birthday?（あなたの誕生日はいつですか）\\n例）Whose bag is this?（これはだれのかばんですか）\\n\\n作り方は二段階で考える。\\n①ふつうの疑問文を作る（Is your name 〜?）\\n②たずねたい部分を疑問詞にかえて、文の先頭に出す（What is your name?）\\n\\n★ ポイント：疑問詞は必ず先頭。× Your name is what? のように、日本語の語順のまま置いてはいけない。\",\"figureId\":\"lf_eigoext02_049\"},{\"heading\":\"答え方と be動詞の選び方\",\"body\":\"■ Yes / No では答えない\\n疑問詞でたずねられたら、その中身を答える。\\n\\nWhat is this? － It is a dictionary.（これは何ですか － 辞書です）\\nWho is he? － He is my uncle.（彼はだれですか － 私のおじです）\\nWhere is your school? － It is near the station.（駅の近くです）\\n\\n✗ What is this? － Yes, it is.\\nこれは意味が通らない。疑問詞が見えたら Yes / No は使わない、と決めておく。\\n\\n■ be動詞は主語に合わせる\\n疑問詞のうしろに来る be動詞も、主語の数で決まる。\\n\\n例）Where is my key?（key は一つ → is）\\n例）Where are my keys?（keys は二つ以上 → are）\\n例）Who are those boys?（those boys は複数 → are）\\n\\n■ 短縮形\\nWhat is → What's　　Where is → Where's　　Who is → Who's\\n例）What's your favorite color?（好きな色は何ですか）\\n\\n⚠ 注意：Whose（だれの）と Who's（＝Who is）は音が同じで、意味がまったくちがう。Whose bag is this?（これはだれのかばんですか）と Who's that man?（あの男の人はだれですか）を書き分ける。\"},{\"heading\":\"なぜ疑問詞は先頭で、なぜ Yes / No で答えないのか\",\"mangaId\":\"eigo_s049_manga\",\"body\":\"疑問詞は「何・だれ・どこ」という**知りたいことそのもの**を表す語です。英語では、いちばん知りたいことを文の先頭に置いて相手に伝えます。だから What is your name? のように疑問詞が先頭に来て、そのあとはふつうの疑問文の語順（be動詞＋主語）が続きます。日本語の「あなたの名前は何ですか」の順のまま Your name is what? と置くと、英語では知りたいことが最後に来てしまい、疑問文になりません。\\n\\nYes / No で答えないのは、疑問詞の質問が「はい・いいえ」で答えられる質問ではなく、**中身（名前・人・場所）を聞いている**からです。What is this? に Yes, it is. と答えても、何なのかは伝わりません。答えは It is a dictionary. のように中身を言います。be動詞は主語の数で決まるので、Where are my keys? のように keys が複数なら are です。\\n\\n■ 確かめのしかた\\n①作り方は二段階：**①ふつうの疑問文を作る（Is your bag 〜?）→②たずねたい部分を疑問詞にして先頭に出す（Where is your bag?）**。\\n②疑問詞のうしろが**be動詞＋主語**の順になっているか。Where your bag is? は×。\\n③答えを書く前に**文の先頭に疑問詞があるか**を見る。あれば Yes / No は使わず、中身を答える。\\n④be動詞は主語の数に合わせる（key→is、keys→are）。Whose（だれの）と Who's（＝Who is）を書き分ける。\\n\\n★ ここがポイント：疑問詞は**知りたいことそのもの**なので先頭に置き、あとは**be動詞＋主語**の疑問文の語順。**中身を聞いている**ので Yes / No では答えない。作り方は「ふつうの疑問文→疑問詞を先頭に」の二段階。\"}],\"trapExamples\":[{\"question\":\"「あなたのかばんはどこにありますか。」を英語にしなさい。\",\"wrongAnswer\":\"Where your bag is?\",\"trapExplanation\":\"日本語の「あなたのかばんは どこに ありますか」の語順のまま英語に置きかえてしまう。疑問詞さえ前に出せばよいと考え、そのあとの入れかえを忘れている。\",\"correctAnswer\":\"Where is your bag?\",\"correctExplanation\":\"疑問詞のうしろも疑問文の語順のままなので、〈be動詞＋主語〉と続けなければならない。手順は、①Is your bag 〜? を作る、②たずねたい部分を where にして先頭に出す、の二段階。Where's your bag? と短縮してもよい。\"},{\"question\":\"What is that building? に答えなさい。\",\"wrongAnswer\":\"Yes, it is.\",\"trapExplanation\":\"be動詞で始まる疑問文には Yes / No で答える、という練習をくり返しているため、文の先頭に疑問詞があっても同じ答え方をしてしまう。is という語だけが目に入っている。\",\"correctAnswer\":\"It is a hospital.（など、その建物が何かを答える）\",\"correctExplanation\":\"疑問詞（what / who / where など）でたずねられた文は「何なのか」を答える文なので、Yes / No では答えられない。文の先頭を見て、疑問詞があるかどうかをまず確かめる。答えの主語は that building を受けて it にする。\"}]}",
"{\"id\":\"eigo_s050\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞①：be動詞ではない動詞\",\"description\":\"「〜する」を表す一般動詞と be動詞のちがいを、はっきり区別する\",\"intro\":\"「私はテニスをします」を I am play tennis. と書く人はとても多いのです。「します」につられて am を足してしまうからです。英語の文の動詞は1つだけ。be動詞と一般動詞は同時には使えません。\",\"order\":550,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"一般動詞＝am / is / are 以外の動詞。play・like・have・go・study など。\",\"動作だけでなく、like・want・know・have のような気持ち・状態を表す動詞も一般動詞。\",\"一文に動詞は一つ。be動詞と一般動詞を並べない（× I am play tennis.）。\",\"語順は〈主語＋動詞＋（目的語）〉。日本語の「〜を〜する」とは逆の順になる。\",\"「私は〜が好きです」は like を使う（× I am like 〜）。「です」に引かれない。\"],\"sections\":[{\"heading\":\"一般動詞とは何か\",\"mangaId\":\"eigo_s050_manga\",\"body\":\"英語の動詞は、be動詞（am / is / are）と、それ以外の一般動詞の二つに分かれる。一般動詞は「〜する」という動作や「〜している状態だ」という気持ち・状態を表す。\\n\\n■ 動作を表すもの\\nplay（する・演奏する）／run（走る）／go（行く）／come（来る）／study（勉強する）／read（読む）／write（書く）／eat（食べる）／speak（話す）\\n\\n■ 気持ちや状態を表すもの\\nlike（好む）／want（ほしがる）／know（知っている）／have（持っている）／live（住んでいる）／need（必要とする）\\n\\n例）I play the piano.（私はピアノをひきます）\\n例）I like dogs.（私は犬が好きです）\\n例）He lives in Osaka.（彼は大阪に住んでいます）\\n\\n■ 大切な区別\\n「〜です」と訳せる文でも、like・have・know などが使われていれば一般動詞の文である。日本語の訳し方ではなく、使われている語で判断する。\\n\\n★ ポイント：I like English.（私は英語が好きです）は、日本語では「です」で終わるが英語では一般動詞 like の文。be動詞は入らない。\",\"figureId\":\"xf_eigo_s050\"},{\"heading\":\"一文に動詞は一つ\",\"body\":\"英語の文には動詞が必ず一つ要るが、二つ並べることはできない。be動詞と一般動詞を続けて置く文は誤りである。\\n\\n✗ I am play tennis.\\n○ I play tennis.（私はテニスをします）\\n\\n✗ He is likes music.\\n○ He likes music.（彼は音楽が好きです）\\n\\n✗ We are study English.\\n○ We study English.（私たちは英語を勉強します）\\n\\nbe動詞は「＝」を表す動詞なので、それ自体がすでに動詞である。そこに play や like をもう一つ足すことはできない。\\n\\n■ 語順は「だれが → どうする → 何を」\\n日本語　私は　テニスを　します\\n英語　　I　　play　　　tennis\\n\\n日本語では「何を」が動詞より前に来るが、英語では動詞のうしろに来る。日本語の順のまま並べると ✗ I tennis play. となってしまう。\\n\\n⚠ 注意：英語を書くときは、まず主語、次に動詞、最後に「何を」の順に組み立てる。日本語を一語ずつ置きかえるのではなく、順番を組みかえる意識をもつ。\"}],\"trapExamples\":[{\"question\":\"「私は毎日サッカーをします。」を英語にしなさい。（every day を使う）\",\"wrongAnswer\":\"I am play soccer every day.\",\"trapExplanation\":\"「私は〜です」の文で I am をくり返し練習しているため、主語のあとには am を置くものだと体が覚えてしまっている。play という動詞を足しても、am のほうを消すことに気づかない。\",\"correctAnswer\":\"I play soccer every day.\",\"correctExplanation\":\"一文に動詞は一つだけである。play という一般動詞を使うのだから、am は要らない。「主語のうしろに来る動詞は一つ」と確かめる習慣をつける。be動詞を使うのは、He is a soccer player.（彼はサッカー選手です）のように「＝」で結ぶときである。\"},{\"question\":\"「私はテニスが好きです。」を英語にしなさい。\",\"wrongAnswer\":\"I tennis like.\",\"trapExplanation\":\"日本語の「私は テニスが 好きです」の語順のまま単語を置きかえてしまう。日本語では動詞が最後に来るので、その感覚のまま英語を書くと目的語と動詞が逆になる。\",\"correctAnswer\":\"I like tennis.\",\"correctExplanation\":\"英語は〈主語＋動詞＋目的語〉の順で、「何を」は動詞のうしろに来る。日本語とは逆になるので、書くときは「だれが→どうする→何を」と口に出しながら組み立てる。like は一般動詞なので be動詞は入らない。\"}]}",
"{\"id\":\"eigo_s051\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞②：語順〈主語＋動詞＋目的語〉\",\"description\":\"英語の基本の語順と、修飾語をどこに置くかを図で確認する\",\"intro\":\"日本語は「私は 毎週日曜に 公園で テニスを します」と、動詞が最後に来ます。英語は I play tennis と、動詞と「何を」が先。「いつ・どこで」は後回しです。この順番の逆転が英作文の第一関門です。\",\"order\":551,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"英語の基本語順は〈主語（S）＋動詞（V）＋目的語（O）〉。\",\"目的語は動詞のすぐうしろ。動詞と目的語の間に他の語をはさまない。\",\"「いつ・どこで」を表す語句は文の終わりに置くのがふつう。\",\"順番は〈場所→時〉。I play tennis in the park every Sunday.\",\"目的語が代名詞のときは目的格にする（× I like she. ○ I like her.）。\"],\"sections\":[{\"heading\":\"基本の三つの箱\",\"body\":\"英語の文は、前から順に「だれが」「どうする」「何を」の三つの箱にことばを入れていくと考えると分かりやすい。\\n\\n■ 三つの箱\\n①主語（S）＝だれが\\n②動詞（V）＝どうする\\n③目的語（O）＝何を\\n\\n例）I　　study　　English.\\n　　私は　勉強する　英語を\\n\\n例）She　plays　the piano.\\n例）We　　like　　this song.\\n例）Tom　has　　two dogs.\\n\\n日本語では「私は英語を勉強する」のように「何を」が動詞より前に来るが、英語では必ず動詞のうしろである。\\n\\n■ 動詞と目的語の間に語をはさまない\\n✗ I study every day English.\\n○ I study English every day.\\n\\n「毎日」のような語は、目的語のうしろに置く。動詞と目的語はぴったりくっつけるのが基本である。\\n\\n★ ポイント：文を書いたら「S・V・O」の三つが正しい順に並んでいるかを指で追って確かめる。\",\"figureId\":\"lf_eigoext02_051\",\"mangaId\":\"eigo_s051_xm\"},{\"heading\":\"「いつ・どこで」を置く場所\",\"body\":\"時や場所を表す語句（修飾語）は、ふつう文の終わりに置く。二つ以上あるときは〈場所→時〉の順にする。\\n\\n■ 場所→時の順\\n例）I play tennis in the park every Sunday.\\n　　（私は毎週日曜日に公園でテニスをします）\\n　　in the park（場所）→ every Sunday（時）\\n\\n例）We study English at school every day.\\n　　（私たちは毎日学校で英語を勉強します）\\n\\n日本語では「毎週日曜日に公園で」と時が先に来ることが多いので、英語にするときは順番を入れかえる必要がある。\\n\\n■ 目的語が代名詞のとき\\n目的語の位置に代名詞を置くときは、形が変わる（目的格という）。\\n\\nI → me　　you → you　　he → him　　she → her\\nit → it　　we → us　　they → them\\n\\n例）I know him.（私は彼を知っています）※ × I know he.\\n例）She likes them.（彼女はそれらが好きです）\\n\\n⚠ 注意：主語の位置で使う形（he / she / they）と目的語の位置で使う形（him / her / them）を混同しない。動詞のうしろに来たら形がかわる、と覚える。\"}],\"trapExamples\":[{\"question\":\"「私は毎週土曜日に公園で野球をします。」を英語にしなさい。（in the park／every Saturday を使う）\",\"wrongAnswer\":\"I play in the park baseball every Saturday.\",\"trapExplanation\":\"日本語の「公園で野球を」の順につられて、場所を表す語句を目的語より前に入れてしまう。動詞のうしろにすぐ来るのが目的語だという原則が抜けている。\",\"correctAnswer\":\"I play baseball in the park every Saturday.\",\"correctExplanation\":\"動詞と目的語はくっつけて〈play baseball〉とし、そのあとに修飾語を〈場所→時〉の順で並べる。日本語では時が先に来ることが多いので、英語では逆になると意識して入れかえる。\"},{\"question\":\"（　）内の語を正しい形にしなさい。　My sister likes（he）very much.\",\"wrongAnswer\":\"My sister likes he very much.\",\"trapExplanation\":\"「彼」という日本語には形の変化がないので、he のまま置いてしまう。he＝彼、と一対一で覚えていて、置かれる場所によって形が変わることを意識していない。\",\"correctAnswer\":\"My sister likes him very much.\",\"correctExplanation\":\"動詞のうしろ（目的語の位置）に来る代名詞は目的格になる。he → him、she → her、they → them、I → me、we → us と変わる。「動詞のうしろに来たら形がかわる」と手順にして、書いたあとに確かめるとよい。\"}]}",
"{\"id\":\"eigo_s052\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"三人称単数現在の -s ①：付ける・付けないの見分け\",\"description\":\"主語が「自分でも相手でもない一人・一つ」のときに動詞へ -s を付ける規則を身につける\",\"intro\":\"He play soccer. は、日本語の感覚では何もおかしくありません。でも英語では、主語が「自分でも相手でもない1人」のときだけ動詞に -s が付きます。なぜ主語で動詞が変わるのか、ここで整理します。\",\"order\":552,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が三人称単数（he / she / it、一人・一つの名詞）で現在の文のとき、動詞に -s を付ける。\",\"一人称＝I、二人称＝you、三人称＝それ以外。I と you には -s を付けない。\",\"主語が複数なら -s は付けない（My friends like 〜）。\",\"-s が付くのは動詞であって名詞ではない。名詞の複数の s とは別物。\",\"過去の文や、be動詞の文には三単現の -s は関係しない。\"],\"sections\":[{\"heading\":\"「三人称単数現在」とは\",\"mangaId\":\"eigo_s052_manga\",\"body\":\"英語では、現在のことを言う文で主語が「三人称の単数」のとき、動詞の終わりに -s を付ける。これを三人称単数現在（三単現）の -s という。\\n\\n■ 人称の分け方\\n一人称＝I、we（自分がふくまれる）\\n二人称＝you（相手）\\n三人称＝それ以外すべて（he, she, it, Ken, my mother, the dog, this book …）\\n\\n■ 単数か複数か\\n単数＝一人・一つ\\n複数＝二つ以上\\n\\n■ -s が付く条件\\n①主語が三人称\\n②主語が単数\\n③現在のことを言う文\\nこの三つがすべてそろったときだけ -s を付ける。\\n\\n例）He plays tennis.（彼はテニスをします）\\n例）She likes music.（彼女は音楽が好きです）\\n例）My father works at a bank.（父は銀行で働いています）\\n例）This bus goes to the station.（このバスは駅に行きます）\\n\\n★ ポイント：I と you は、単数でも -s が付かない。I play / You play。ここは条件①（三人称であること）を満たさないからである。\",\"figureId\":\"xf_eigo_s052\"},{\"heading\":\"付けてはいけない場合\",\"body\":\"-s を付けすぎるまちがいも多い。次の場合は付けない。\\n\\n■ 主語が複数のとき\\n例）My friends like soccer.（○）　× My friends likes soccer.\\n例）Ken and Mika study together.（○）\\n例）They live in Tokyo.（○）\\n\\n■ 主語が I / you のとき\\n例）I play the guitar.（○）　× I plays the guitar.\\n例）You know him well.（○）\\n\\n■ 名詞の複数の s と混同しない\\n名詞に付く s（books, dogs）は「二つ以上」を表す。動詞に付く s は「主語が三人称単数」を表す。役割がまったくちがう。\\n\\n例）He reads books.\\nreads の s ＝主語 He が三人称単数だから\\nbooks の s ＝本が二冊以上あるから\\n\\n⚠ 注意：主語が dogs のように複数形なら、動詞に -s は要らない。ただし目的語の s を見て決めてはいけない。動詞の -s を決めるのは、いつでも主語である。\\n例）He has three dogs.（主語 He が単数なので has）\"}],\"trapExamples\":[{\"question\":\"（　）内の語を正しい形にしなさい。　My mother and father（work）at the same hospital.\",\"wrongAnswer\":\"My mother and father works at the same hospital.\",\"trapExplanation\":\"直前の father が一人なので、三人称単数だと判断して -s を付けてしまう。and でつながれた主語全体を見ずに、動詞のすぐ前の語だけで決めてしまうのが原因。\",\"correctAnswer\":\"My mother and father work at the same hospital.\",\"correctExplanation\":\"主語は My mother and father の全体で、二人いるので複数である。複数の主語には三単現の -s を付けない。and が見えたら主語のかたまり全体を確かめる、という手順を必ず入れる。\"},{\"question\":\"（　）内の語を正しい形にしなさい。　I（have）a new bike.\",\"wrongAnswer\":\"I has a new bike.\",\"trapExplanation\":\"have の三人称単数形が has であることを覚えた直後は、have を見ると反射的に has にしたくなる。主語が I であることの確認をとばしてしまう。\",\"correctAnswer\":\"I have a new bike.\",\"correctExplanation\":\"三単現の -s が付くのは主語が三人称単数のときだけである。I は一人称なので、単数であっても have のままでよい。has を使うのは He has / She has / My brother has のように主語が三人称単数のときに限られる。\"}]}",
"{\"id\":\"eigo_s053\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"三人称単数現在の -s ②：-es を付ける動詞\",\"description\":\"s・x・ch・sh・o で終わる動詞の変化を、例とともに正確に覚える\",\"intro\":\"go に -s を付けると gos ではなく goes です。watch も watchs ではなく watches。-es になるのは s・x・ch・sh・o で終わる5種類だけ。数が少ないので、まとめて覚えてしまえば迷いません。\",\"order\":553,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"ほとんどの動詞はそのまま -s を付ける（play → plays、like → likes）。\",\"s・x・ch・sh・o で終わる動詞には -es を付ける。\",\"代表例：goes / does / watches / teaches / washes / passes / mixes。\",\"go → goes、do → does は特に出題が多い。\",\"-es を付ける動詞は数が少ないので、語尾の五種類をまとめて覚えてしまう。\"],\"sections\":[{\"heading\":\"大部分はそのまま -s\",\"body\":\"三単現の -s の付け方は、まず「ほとんどの動詞はそのまま -s を付けるだけ」と押さえる。\\n\\n例）play → plays　　like → likes　　run → runs\\n例）read → reads　　know → knows　　speak → speaks\\n例）live → lives　　come → comes　　write → writes\\n例）eat → eats　　want → wants　　need → needs\\n\\nこれが基本形で、大部分の動詞がここに入る。まず「そのまま -s」を土台にして、例外だけを覚えるとよい。\\n\\n■ 例外① s・x・ch・sh・o で終わる動詞は -es\\n語尾がこの五種類のとき、そのまま s を付けると発音しにくくなるので -es を付ける。\\n\\ns で終わる　　pass → passes（通り過ぎる）\\nx で終わる　　mix → mixes（混ぜる）／ fix → fixes（直す）\\nch で終わる　watch → watches（見る）／ teach → teaches（教える）／ catch → catches（つかまえる）\\nsh で終わる　wash → washes（洗う）／ finish → finishes（終える）\\no で終わる　　go → goes（行く）／ do → does（する）\\n\\n★ ポイント：s・x・ch・sh・o の五つを「エス・エックス・チ・シュ・オー」と口で唱えて覚える。入試で出るのは goes・does・watches・teaches・washes がほとんどである。\",\"figureId\":\"lf_eigoext02_053\",\"mangaId\":\"eigo_s053_xm\"},{\"heading\":\"発音と書き方の注意\",\"body\":\"■ -es の発音\\nwatches / teaches / washes / passes / mixes の -es は「イズ」と読む。goes と does だけは「ズ」に近い音になる。\\n\\ngoes は「ゴーズ」、does は「ダズ」と読む。does のつづりは do＋es だが、読み方は do の音のままではないので注意する。\\n\\n■ 書きまちがえやすい形\\n✗ gos　　○ goes\\n✗ dos　　○ does\\n✗ watchs　○ watches\\n✗ washs　　○ washes\\n✗ teachs　○ teaches\\n\\nいずれも「そのまま -s」の規則をあてはめてしまった形である。語尾を見て、五種類のどれかに当たらないかを必ず確かめる。\\n\\n■ o で終わってもすべてが -es ではない\\no で終わる動詞は数が少なく、中学受験で出るのは go と do のほぼ二つである。この二つだけを確実に覚えれば足りる。\\n\\n⚠ 注意：play は y で終わるが、直前が a（母音）なので plays でよい。y で終わる動詞をすべて -ies にするのは誤りである。くわしくは次のまとまりで扱う。\"}],\"trapExamples\":[{\"question\":\"（　）内の語を正しい形にしなさい。　My brother（go）to school by bus.\",\"wrongAnswer\":\"My brother gos to school by bus.\",\"trapExplanation\":\"「そのまま -s を付ける」という基本の規則を先に覚えているため、go にもそのまま s を付けてしまう。go は短い語なので例外だと気づきにくい。\",\"correctAnswer\":\"My brother goes to school by bus.\",\"correctExplanation\":\"go は o で終わる動詞なので -es を付けて goes になる。同じ仲間の do → does もあわせて覚える。語尾が s・x・ch・sh・o のどれかなら -es、と確かめる手順を入れると防げる。\"},{\"question\":\"（　）内の語を正しい形にしなさい。　Yuki（play）the violin every evening.\",\"wrongAnswer\":\"Yuki plaies the violin every evening.\",\"trapExplanation\":\"y で終わる動詞は y を i にかえて -es を付ける、という規則を覚えた直後に、直前の文字を見ずにすべての y にあてはめてしまう。study → studies の印象が強すぎるのが原因。\",\"correctAnswer\":\"Yuki plays the violin every evening.\",\"correctExplanation\":\"y を i にかえるのは、y の直前が子音のときだけである。play は y の直前が a（母音）なので、そのまま -s を付けて plays になる。同じく stay → stays、enjoy → enjoys、buy → buys。y の直前の一文字を必ず見る。\"}]}",
"{\"id\":\"eigo_s054\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"三人称単数現在の -s ③：y で終わる動詞と have\",\"description\":\"子音＋y の動詞を -ies にかえる規則と、have → has の特別な変化を確実にする\",\"intro\":\"study は studies なのに、play は plays。同じ y で終わるのに変化がちがいます。分かれ目は、y の直前が母音字かどうかです。そして have だけは has という特別な形になります。\",\"order\":554,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"〈子音＋y〉で終わる動詞は、y を i にかえて -es（study → studies）。\",\"〈母音＋y〉で終わる動詞は、そのまま -s（play → plays、enjoy → enjoys）。\",\"母音は a・i・u・e・o の五つ。y の直前の一文字を見て判断する。\",\"have だけは特別で has になる（× haves）。\",\"名詞の複数形（city → cities）も同じ規則なので、まとめて覚えられる。\"],\"sections\":[{\"heading\":\"y の直前を見る\",\"mangaId\":\"eigo_s054_manga\",\"body\":\"y で終わる動詞は、y の直前の文字が母音か子音かで変化のしかたが分かれる。\\n\\n■ 子音＋y → y を i にかえて -es\\nstudy → studies（勉強する）\\ncarry → carries（運ぶ）\\ntry → tries（ためす）\\ncry → cries（泣く）\\nfly → flies（飛ぶ）\\nworry → worries（心配する）\\n\\nstudy の y の直前は d（子音）なので studies になる。\\n\\n■ 母音＋y → そのまま -s\\nplay → plays（する）\\nstay → stays（とどまる）\\nenjoy → enjoys（楽しむ）\\nbuy → buys（買う）\\nsay → says（言う）\\n\\nplay の y の直前は a（母音）なので plays でよい。\\n\\n■ 母音とは\\na・i・u・e・o の五文字。これ以外はすべて子音である。\\n\\n★ ポイント：手順は「語尾が y か → 直前の一文字は母音か子音か → 子音なら ies、母音なら s」。二段階で確かめれば必ず正解できる。\\n\\n⚠ 注意：says のつづりは規則どおりだが、読み方は「セズ」に近い音になる。読み方だけは例外である。\",\"figureId\":\"xf_eigo_s054\"},{\"heading\":\"have → has という特別な形\",\"body\":\"have は三単現の形が特別で、has になる。\\n\\n✗ haves　　✗ hases　　○ has\\n\\n例）I have a dog. → He has a dog.（彼は犬を飼っています）\\n例）We have two classes today. → She has two classes today.\\n\\nhave は「持っている・飼っている・（兄弟が）いる・（食事を）とる」など使い道が広く、入試でもよく出る。has の形はくり返し書いて覚える。\\n\\n例）My sister has long hair.（姉は髪が長いです）\\n例）Ken has a lot of friends.（ケンには友達がたくさんいます）\\n例）He has breakfast at seven.（彼は七時に朝食を食べます）\\n\\n■ そのほかの注意する動詞\\ndo → does（する）※ o で終わるので -es\\ngo → goes（行く）※ o で終わるので -es\\nhave → has（持っている）※ 完全な例外\\n\\nこの三つが、三単現でとくに出題される動詞である。\\n\\n■ 名詞の複数形も同じ規則\\ncity → cities／country → countries／baby → babies（子音＋y）\\nboy → boys／day → days／key → keys（母音＋y）\\n動詞と名詞で同じ規則が働くので、あわせて覚えると効率がよい。\"}],\"trapExamples\":[{\"question\":\"（　）内の語を正しい形にしなさい。　My sister（study）English every night.\",\"wrongAnswer\":\"My sister studys English every night.\",\"trapExplanation\":\"「そのまま -s」という基本形が頭にあるので、y で終わる語にもそのまま s を付けてしまう。studys と書いても見た目に大きな違和感がないため、見直しでも気づきにくい。\",\"correctAnswer\":\"My sister studies English every night.\",\"correctExplanation\":\"study は y の直前が d という子音なので、y を i にかえて -es を付け studies になる。同じ形に carry → carries、try → tries、cry → cries がある。y で終わる語を見たら、直前の一文字を必ず確かめる。\"},{\"question\":\"（　）内の語を正しい形にしなさい。　Tom（have）three brothers.\",\"wrongAnswer\":\"Tom haves three brothers.\",\"trapExplanation\":\"三単現は -s を付けるという規則にしたがって、have にもそのまま s を付けてしまう。have は形が変わる特別な動詞だという例外を覚えていないと必ず引っかかる。\",\"correctAnswer\":\"Tom has three brothers.\",\"correctExplanation\":\"have の三人称単数現在形は has という特別な形である。haves という語は存在しない。「三単現でとくに注意するのは has・goes・does の三つ」とまとめて覚えておくと、テストのときに思い出しやすい。\"}]}",
"{\"id\":\"eigo_s055\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"三人称単数現在の -s ④：主語を正しく見つける\",\"description\":\"主語が長いときや修飾語が入るときに、動詞の形をまちがえないための手順を練習する\",\"intro\":\"The boy with two dogs run fast. は、どこがまちがいでしょうか。走るのは boy 1人なので runs です。dogs につられて複数だと思ってしまうのです。動詞の形を決めるのは、いつでも主語の中心の語です。\",\"order\":555,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"動詞の形を決めるのは、いつでも主語の中心になる名詞。\",\"in / on / with / from などで始まるかたまりは主語ではない（修飾語）。\",\"The boy with two dogs runs fast.（中心は boy → runs）\",\"Everyone・Every 〜 は単数あつかいなので -s を付ける。\",\"書いたあとに「主語はどれか」「単数か複数か」を必ず確かめる。\"],\"sections\":[{\"heading\":\"主語の中心をさがす\",\"body\":\"三単現の -s でまちがえるのは、主語が長いときである。主語のかたまりの中で、数を決めている中心の名詞を見つけることが大切になる。\\n\\n■ 前置詞から始まるかたまりは主語ではない\\nin（〜の中の）・on（〜の上の）・with（〜を持った）・from（〜出身の）・of（〜の）などで始まるかたまりは、直前の名詞を説明しているだけである。\\n\\n例）The girl with two dogs lives near my house.\\n主語の中心＝The girl（一人）→ lives\\nうしろの two dogs は「二匹の犬を連れた」と girl を説明しているだけ。\\n\\n例）The students in my class study very hard.\\n主語の中心＝The students（複数）→ study\\nmy class（単数）にひかれて studies としない。\\n\\n例）A boy from Canada speaks Japanese well.\\n主語の中心＝A boy → speaks\\n\\n★ ポイント：動詞のすぐ前の名詞ではなく、「文が何について語っているか」を決める名詞を見る。前置詞から始まるかたまりに線を引いて消してしまうと、主語の中心が浮かび上がる。\",\"figureId\":\"xf_eigo_s055\",\"mangaId\":\"eigo_s055_xm\"},{\"heading\":\"単数あつかいの主語\",\"body\":\"見た目は複数っぽいのに単数としてあつかう主語がある。これらには -s を付ける。\\n\\n■ everyone / everybody（みんな）\\n例）Everyone likes this song.（みんなこの歌が好きです）\\n「みんな」でも単数あつかいなので likes。\\n\\n■ every ＋ 単数名詞\\n例）Every student has a computer.（すべての生徒がコンピュータを持っています）\\nevery のうしろは必ず単数名詞で、動詞にも -s が付く。\\n\\n■ 数えられない名詞\\n例）Water freezes at zero degrees.（水はセ氏0度でこおります）\\n\\n■ 逆に複数あつかい\\n例）My family and I go to the beach every summer.（and で結ぶ → 複数）\\n例）These books are interesting.\\n\\n■ 三単現が関係しない文\\n過去の文（I played / He played）では、主語が何であっても形は同じである。また be動詞の文（He is 〜）にも三単現の -s は関係しない。三単現の -s は「現在の文の一般動詞」だけの話である。\\n\\n⚠ 注意：解き終わったら、①主語はどれか、②単数か複数か、③現在の文か、の三つを口の中で確かめる。この確認だけで失点が大きくへる。\"}],\"trapExamples\":[{\"question\":\"（　）内の語を正しい形にしなさい。　The students in my class（study）very hard.\",\"wrongAnswer\":\"The students in my class studies very hard.\",\"trapExplanation\":\"動詞のすぐ前にある my class（一つ）を主語だと思いこみ、三単現の -s を付けてしまう。前置詞 in から始まるかたまりが修飾語であることを見落としている。\",\"correctAnswer\":\"The students in my class study very hard.\",\"correctExplanation\":\"主語は The students（複数）で、in my class は「私のクラスの」と students を説明する修飾語にすぎない。前置詞から始まるかたまりに線を引いて消すと、主語の中心が The students であることがはっきりする。複数なので -s は付けない。\"},{\"question\":\"（　）内の語を正しい形にしなさい。　Everyone in my family（like）natto.\",\"wrongAnswer\":\"Everyone in my family like natto.\",\"trapExplanation\":\"everyone を「みんな」と訳すので、複数だと考えて -s を付けない。日本語の感覚では明らかに二人以上を指しているため、単数あつかいだと気づきにくい。\",\"correctAnswer\":\"Everyone in my family likes natto.\",\"correctExplanation\":\"everyone / everybody / every ＋ 単数名詞 は、意味は「みんな」でも文法上は単数としてあつかう。したがって動詞には -s が付いて likes になる。in my family は修飾語なので、動詞の形とは関係しない。\"}]}",
"{\"id\":\"eigo_s056\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞の否定文①：do not（don't）\",\"description\":\"一般動詞の文を否定するときに do を借りてくるしくみをつかむ\",\"intro\":\"I not like natto. と書きたくなりますが、英語では通じません。一般動詞の文を否定するには、do という語をわざわざ借りてきて don't を作ります。なぜそんな手間をかけるのか、形から見ていきましょう。\",\"order\":556,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"一般動詞の否定文は〈主語＋do not（don't）＋動詞の原形〉。\",\"do not は動詞の前に置く。not だけを付けることはできない。\",\"be動詞は使わない（× I am not like 〜）。\",\"短縮形は don't。会話でも作文でもよく使う。\",\"主語が I / you / we / they や複数のときは don't（三人称単数は次のまとまり）。\"],\"sections\":[{\"heading\":\"do を借りて否定する\",\"body\":\"be動詞の文は not を付けるだけで否定文になったが、一般動詞にはその力がない。そこで do という語を借りてきて、do not（短縮形 don't）を動詞の前に置く。\\n\\n■ 形\\n主語＋do not（don't）＋動詞\\n\\n例）I play tennis. → I don't play tennis.（私はテニスをしません）\\n例）They like natto. → They don't like natto.（彼らは納豆が好きではありません）\\n例）We have a car. → We don't have a car.（私たちは車を持っていません）\\n例）You know him. → You don't know him.（あなたは彼を知りません）\\n\\n■ not だけでは否定できない\\n✗ I not play tennis.\\n✗ I play not tennis.\\nどちらも誤りである。英語では一般動詞を否定するとき、必ず do の助けが要る。\\n\\n■ be動詞を混ぜない\\n✗ I am not play tennis.\\nbe動詞と一般動詞を並べることはできないので、これも誤り。\\n\\n★ ポイント：「一般動詞の否定＝don't を動詞の前に置く」と一つの動作で覚える。do not の not だけを取り出して使うことはない。\",\"figureId\":\"lf_eigoext02_056\",\"mangaId\":\"eigo_s056_xm\"},{\"heading\":\"意味と使い方の広がり\",\"body\":\"■ 「〜しません」だけでなく「〜ではありません」も\\nlike や know のような状態を表す動詞でも、否定文の作り方は同じである。\\n\\n例）I don't like carrots.（私はにんじんが好きではありません）\\n例）I don't know his name.（私は彼の名前を知りません）\\n例）We don't need it.（私たちはそれを必要としていません）\\n\\n日本語では「好きではありません」と「です・ます」で終わるので be動詞を使いたくなるが、like は一般動詞なので don't を使う。\\n\\n■ 「あまり〜ない」「まったく〜ない」\\ndon't と組み合わせてよく使う語がある。\\n\\n例）I don't play the piano very well.（あまり上手にひけません）\\n例）I don't like it at all.（まったく好きではありません）\\n\\n■ 命令文の否定\\n「〜してはいけません」は Don't で文を始める。\\n\\n例）Don't run in the hallway.（廊下を走ってはいけません）\\n例）Don't open the window.（窓を開けてはいけません）\\n主語がなく、Don't から始まる点がふつうの否定文とちがう。\\n\\n⚠ 注意：Don't で始まる命令文と、I don't 〜 の否定文を混同しない。主語があるかないかで見分ける。\"}],\"trapExamples\":[{\"question\":\"「私は納豆が好きではありません。」を英語にしなさい。\",\"wrongAnswer\":\"I am not like natto.\",\"trapExplanation\":\"日本語が「〜ではありません」と「です・ます」で終わるので、be動詞の否定文と同じ形にしてしまう。like を動詞ではなく「好き」という形容詞のように感じているのも原因である。\",\"correctAnswer\":\"I don't like natto.（I do not like natto.）\",\"correctExplanation\":\"like は一般動詞なので、否定には do not（don't）を動詞の前に置く。be動詞と一般動詞は並べられない。日本語の訳ではなく「使われている語が be動詞か一般動詞か」で判断する習慣をつける。\"},{\"question\":\"「私は英語を話しません。」を英語にしなさい。\",\"wrongAnswer\":\"I speak not English.\",\"trapExplanation\":\"be動詞の否定文で「動詞のうしろに not」と覚えたため、一般動詞でも同じ位置に not を置いてしまう。日本語の「話し ません」の語順とも合ってしまうので、まちがいに気づきにくい。\",\"correctAnswer\":\"I don't speak English.（I do not speak English.）\",\"correctExplanation\":\"一般動詞の否定文では、動詞の前に do not（don't）を置く。not を単独で動詞のうしろに置く形は英語にはない。「be動詞なら not をうしろに、一般動詞なら don't を前に」と対で覚えると混同しない。\"}]}",
"{\"id\":\"eigo_s057\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞の否定文②：does not（doesn't）と原形\",\"description\":\"主語が三人称単数のときの否定文で、動詞を原形に戻すきまりを身につける\",\"intro\":\"He doesn't plays soccer. は最頻出のまちがいです。doesn't がすでに三単現を引き受けているので、動詞は原形の play にもどします。-s は文の中に1つだけ、と考えると迷いません。\",\"order\":557,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が三人称単数のときは does not（doesn't）を使う。\",\"doesn't のうしろの動詞は必ず原形（-s を取る）。\",\"× He doesn't plays 〜 は最頻出のまちがい。\",\"has も原形の have に戻る（He doesn't have a car.）。\",\"主語が I / you / we / they・複数なら don't、he / she / it・単数なら doesn't。\"],\"sections\":[{\"heading\":\"does を使う場合\",\"body\":\"一般動詞の否定文で、主語が三人称単数のときは don't ではなく doesn't を使う。\\n\\n■ 使い分け\\nI / you / we / they、複数の名詞　→ don't\\nhe / she / it、単数の名詞　　　　→ doesn't\\n\\n例）He doesn't play the piano.（彼はピアノをひきません）\\n例）She doesn't like coffee.（彼女はコーヒーが好きではありません）\\n例）My father doesn't watch TV.（父はテレビを見ません）\\n例）This bus doesn't go to the station.（このバスは駅へ行きません）\\n\\n■ 動詞は原形に戻す\\nいちばん大切なのはここである。doesn't を使ったら、そのうしろの動詞から -s / -es を取って原形に戻す。\\n\\n✗ He doesn't plays the piano.\\n○ He doesn't play the piano.\\n\\n✗ She doesn't likes coffee.\\n○ She doesn't like coffee.\\n\\n✗ He doesn't goes to school by bus.\\n○ He doesn't go to school by bus.\\n\\n★ ポイント：「三人称単数」という情報は does がすでに持っている。だから動詞まで -s を付けると二重になってしまう。-s は文の中で一か所だけ、と覚える。\",\"figureId\":\"xf_eigo_s057\",\"mangaId\":\"eigo_s057_xm\"},{\"heading\":\"have → have に戻す\",\"body\":\"肯定文で has になっていた動詞も、否定文では原形の have に戻る。\\n\\n例）He has a bike. → He doesn't have a bike.（彼は自転車を持っていません）\\n例）She has two dogs. → She doesn't have two dogs.\\n例）My mother has a car. → My mother doesn't have a car.\\n\\n× He doesn't has a bike. は誤り。has は have の三人称単数現在形なので、原形に戻せば have である。\\n\\n■ 同じように戻る動詞\\ngoes → go　　does → do　　studies → study\\nwatches → watch　　teaches → teach\\n\\n例）He doesn't study French.（彼はフランス語を勉強しません）\\n例）She doesn't watch TV after dinner.（彼女は夕食後にテレビを見ません）\\n\\n■ 書いたあとの確認手順\\n①主語は三人称単数か → doesn't\\n②そのうしろの動詞は原形になっているか\\nこの二つを毎回確かめる。とくに②は、書いているうちに肯定文の形（plays, has）が指に残ってしまうため、意識して見直す必要がある。\\n\\n⚠ 注意：does not を短縮すると doesn't。does'nt や dose'nt と書くまちがいが多いので、つづりも正確に覚える。\"}],\"trapExamples\":[{\"question\":\"次の文を否定文にしなさい。　Ken plays the guitar.\",\"wrongAnswer\":\"Ken doesn't plays the guitar.\",\"trapExplanation\":\"もとの文の plays をそのまま残してしまう。主語が三人称単数だから -s が要る、という意識が強すぎて、does がすでにその役目を果たしていることに気づかない。\",\"correctAnswer\":\"Ken doesn't play the guitar.\",\"correctExplanation\":\"doesn't を使ったら、うしろの動詞は必ず原形に戻す。三人称単数であることは does が示しているので、動詞にも -s を付けると二重になってしまう。「does があれば動詞は原形」と一組で覚える。\"},{\"question\":\"「私の姉はねこが好きではありません。」を英語にしなさい。\",\"wrongAnswer\":\"My sister don't like cats.\",\"trapExplanation\":\"don't のほうを先に習うので使い慣れており、主語が三人称単数であることを確かめずに書いてしまう。日本語からは主語の人称が意識されにくいことも原因である。\",\"correctAnswer\":\"My sister doesn't like cats.\",\"correctExplanation\":\"主語 My sister は三人称単数なので doesn't を使う。don't を使うのは主語が I / you / we / they や複数の名詞のときである。否定文を書くときは、まず主語を見て don't か doesn't かを決め、次に動詞を原形にする、という順で進める。\"}]}",
"{\"id\":\"eigo_s058\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞の疑問文①：Do 〜? と答え方\",\"description\":\"Do を文の先頭に置いてたずねる形と、do を使った答え方を身につける\",\"intro\":\"Do you like dogs? に Yes, I like. と答えると不自然です。答えは Yes, I do. と do でそろえます。たずねるときも答えるときも、借りてきた do がそのまま使われるのです。\",\"order\":558,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"一般動詞の疑問文は〈Do＋主語＋動詞の原形〜?〉。\",\"答えは Yes, 主語＋do. / No, 主語＋don't.\",\"答えの文で be動詞を使わない（× Yes, I am.）。\",\"答えでは動詞をくり返さない（× Yes, I have.）。\",\"Do you 〜? と聞かれたら I（二人以上なら we）で答える。\"],\"sections\":[{\"heading\":\"Do を先頭に置く\",\"body\":\"一般動詞の文を疑問文にするときは、文の先頭に Do を置く。be動詞のように動詞そのものを前に出すことはできない。\\n\\n■ 形\\nDo＋主語＋動詞の原形〜?\\n\\n例）You play tennis. → Do you play tennis?（あなたはテニスをしますか）\\n例）They live in Tokyo. → Do they live in Tokyo?（彼らは東京に住んでいますか）\\n例）You have any brothers? → Do you have any brothers?（兄弟はいますか）\\n\\n主語のうしろの動詞はそのままの形（原形）でよい。語順は〈Do → 主語 → 動詞 → そのほか〉である。\\n\\n■ be動詞を混ぜない\\n✗ Are you play tennis?\\n✗ Do you are a student?\\nどちらも動詞が二つある形なので誤り。一般動詞の文なら Do、be動詞の文なら be動詞を前に出す、と使い分ける。\\n\\n★ ポイント：Do は「これから質問しますよ」という合図の語である。それ自体に意味はほとんどなく、日本語には訳さない。\",\"figureId\":\"lf_eigoext02_058\"},{\"heading\":\"答え方は do でそろえる\",\"body\":\"Do 〜? でたずねられたら、答えにも do を使う。\\n\\n■ 形\\nYes, 主語＋do.\\nNo, 主語＋don't.（do not.）\\n\\n例）Do you like music? － Yes, I do. / No, I don't.\\n例）Do they play soccer? － Yes, they do. / No, they don't.\\n例）Do you and Ken walk to school? － Yes, we do. / No, we don't.\\n\\n■ よくある誤り\\n✗ Do you have a pen? － Yes, I have.\\n動詞をくり返して答えることはできない。○ Yes, I do.\\n\\n✗ Do you like dogs? － Yes, I am.\\nbe動詞は使えない。○ Yes, I do.\\n\\n■ 主語は代名詞に置きかえる\\nDo your parents work in Osaka? － Yes, they do.\\nDoes 〜 の形は次のまとまりで扱うが、答えの仕組みは同じである。\\n\\n⚠ 注意：たずねる文が Do で始まっていたら答えも do、Are で始まっていたら答えも be動詞。「問いの最初の語と、答えに使う語をそろえる」と覚えると混乱しない。\",\"mangaId\":\"eigo_s058_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは音楽が好きですか。」を英語にしなさい。\",\"wrongAnswer\":\"Are you like music?\",\"trapExplanation\":\"「〜ですか」と日本語が「です」で終わるので、be動詞の疑問文の形をあてはめてしまう。Are you 〜? という形を先に覚えて口になじんでいることも原因である。\",\"correctAnswer\":\"Do you like music?\",\"correctExplanation\":\"like は一般動詞なので、疑問文は Do を先頭に置いて作る。Are you like 〜? では are と like の二つの動詞が並んでしまう。文で使う動詞が be動詞か一般動詞かを先に決めてから、疑問文の形を選ぶ。\"},{\"question\":\"Do you have a dog? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, I have.\",\"trapExplanation\":\"問いに使われている have をそのままくり返せばよいと考えてしまう。日本語で「はい、飼っています」と動詞をくり返して答えるので、その感覚が英語にも持ちこまれる。\",\"correctAnswer\":\"Yes, I do.\",\"correctExplanation\":\"Do 〜? でたずねられたら、答えにも do を使って Yes, I do. / No, I don't. とする。動詞をくり返す答え方は英語にはない。「問いの最初の語と答えの語をそろえる」と覚えると、Are 〜? には am / is / are で答えることも同時に整理できる。\"}]}",
"{\"id\":\"eigo_s059\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞の疑問文②：Does 〜? と答え方\",\"description\":\"主語が三人称単数のときの疑問文で、動詞を原形にするきまりを確実にする\",\"intro\":\"Does he plays tennis? と書いてしまう人が絶えません。Does がすでに三単現を表しているので、動詞は原形にもどします。has も have にもどります。答え方も does でそろえます。\",\"order\":559,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が三人称単数のときは〈Does＋主語＋動詞の原形〜?〉。\",\"Does のうしろの動詞は必ず原形（× Does he plays 〜?）。\",\"答えは Yes, 主語＋does. / No, 主語＋doesn't.\",\"has も原形の have に戻る（Does she have a bike?）。\",\"答えの主語は代名詞にする（Does Ken 〜? → Yes, he does.）。\"],\"sections\":[{\"heading\":\"Does を使う疑問文\",\"body\":\"主語が he / she / it や一人・一つの名詞のときは、Do ではなく Does で文を始める。\\n\\n■ 形\\nDoes＋主語＋動詞の原形〜?\\n\\n例）He plays soccer. → Does he play soccer?（彼はサッカーをしますか）\\n例）She likes English. → Does she like English?（彼女は英語が好きですか）\\n例）Your father works here. → Does your father work here?\\n例）This train stops at Kyoto. → Does this train stop at Kyoto?\\n\\n■ 動詞は原形に戻す\\n肯定文で -s の付いていた動詞は、疑問文では原形に戻る。\\n\\n✗ Does he plays soccer?\\n○ Does he play soccer?\\n✗ Does she studies math?\\n○ Does she study math?\\n✗ Does he has a car?\\n○ Does he have a car?\\n\\n理由は否定文のときと同じで、「三人称単数」という情報を Does がすでに持っているからである。\\n\\n★ ポイント：Do / Does / Did のうしろの動詞は、いつでも原形。この一つの規則で、否定文も疑問文もまとめて処理できる。\",\"figureId\":\"xf_eigo_s059\",\"mangaId\":\"eigo_s059_xm\"},{\"heading\":\"答え方\",\"body\":\"Does 〜? には does を使って答える。\\n\\n■ 形\\nYes, 主語＋does.\\nNo, 主語＋doesn't.\\n\\n例）Does he play the piano? － Yes, he does. / No, he doesn't.\\n例）Does your sister like cats? － Yes, she does. / No, she doesn't.\\n例）Does this bus go to the museum? － Yes, it does. / No, it doesn't.\\n\\n■ 主語は代名詞にする\\nDoes Ken live near here? － Yes, he does.（× Yes, Ken does.）\\nDoes that dog have a name? － Yes, it does.\\n\\n■ be動詞と混ぜない\\n✗ Does she like cats? － Yes, she is.\\n○ Yes, she does.\\n\\n■ 使い分けのまとめ\\n主語が I / you / we / they・複数 → Do 〜? → Yes, 〜 do.\\n主語が he / she / it・単数 → Does 〜? → Yes, 〜 does.\\n\\n⚠ 注意：Does を使った疑問文を作ったあと、必ずうしろの動詞を見て -s が残っていないかを確かめる。ここは入試でもっとも多い失点の一つである。\"}],\"trapExamples\":[{\"question\":\"次の文を疑問文にしなさい。　Yuki studies Chinese.\",\"wrongAnswer\":\"Does Yuki studies Chinese?\",\"trapExplanation\":\"もとの文の studies をそのまま写してしまう。主語が三人称単数だから -s が要る、という考えが強く、Does がその役目をすでに果たしていることに気づかない。\",\"correctAnswer\":\"Does Yuki study Chinese?\",\"correctExplanation\":\"Does を使ったら、うしろの動詞は必ず原形に戻す。studies → study である。「Do / Does のうしろは原形」という規則は、否定文（doesn't play）でも疑問文（Does he play?）でも同じように働く。\"},{\"question\":\"Does your brother like baseball? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, he is.\",\"trapExplanation\":\"Yes のあとに来るのは be動詞だという思いこみがある。Yes, I am. の形を先に覚えているため、主語を代名詞にかえるところまでは正しくできても、続く語をまちがえる。\",\"correctAnswer\":\"Yes, he does.\",\"correctExplanation\":\"Does 〜? でたずねられたら does で答える。your brother は男性一人なので he に置きかえて Yes, he does. とする。「問いの最初の語（Do / Does / Is / Are）と、答えに使う語をそろえる」と覚えれば、この種のまちがいは起こらない。\"}]}",
"{\"id\":\"eigo_s060\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞＋do / does：What do you 〜?\",\"description\":\"疑問詞と do / does を組み合わせた文の語順と、疑問詞が主語になる場合を学ぶ\",\"intro\":\"What do you like? の語順は、日本語の「あなたは何が好きですか」とはまるで逆です。疑問詞が先、次に do、そして主語。ところが Who plays the piano? のように、疑問詞が主語になると do が消えます。\",\"order\":560,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"語順は〈疑問詞＋do / does＋主語＋動詞の原形〜?〉。\",\"疑問詞は必ず文のいちばん前。do / does はそのすぐうしろ。\",\"答えは Yes / No ではなく、たずねられた中身を答える。\",\"What time / What sport のように、疑問詞が二語になることもある。\",\"疑問詞が主語のときは do / does を使わず、〈疑問詞＋動詞（三単現）〉。Who plays the piano?\"],\"sections\":[{\"heading\":\"四つの箱の順にならべる\",\"body\":\"「何を〜しますか」「どこに〜しますか」のようにたずねるときは、疑問詞と do / does を組み合わせる。\\n\\n■ 語順\\n疑問詞＋do / does＋主語＋動詞の原形〜?\\n\\n例）What do you want?（あなたは何がほしいですか）\\n例）What does he study?（彼は何を勉強していますか）\\n例）Where do you live?（あなたはどこに住んでいますか）\\n例）When does the game start?（試合はいつ始まりますか）\\n例）How do you go to school?（あなたはどうやって学校へ行きますか）\\n\\n作り方は二段階で考える。\\n①ふつうの疑問文を作る（Do you want 〜?）\\n②たずねたい部分を疑問詞にして先頭に出す（What do you want?）\\n\\n■ 疑問詞が二語になる形\\nWhat time do you get up?（何時に起きますか）\\nWhat sport do you like?（どのスポーツが好きですか）\\nHow many books do you have?（本を何冊持っていますか）\\nこれらは〈What time〉〈What sport〉〈How many books〉でひとかたまりとして先頭に置く。\\n\\n★ ポイント：does を使ったら、うしろの動詞は原形。What does he study? であって What does he studies? ではない。\",\"figureId\":\"lf_eigoext02_060\"},{\"heading\":\"疑問詞が主語になるとき\",\"body\":\"「だれが〜しますか」「何が〜しますか」のように、疑問詞そのものが主語になる場合がある。このときは do / does を使わない。\\n\\n■ 形\\n疑問詞（主語）＋動詞〜?\\n\\n例）Who plays the piano in your family?（家族でだれがピアノをひきますか）\\n例）Who lives in that house?（あの家にはだれが住んでいますか）\\n例）What makes you happy?（何があなたを幸せにしますか）\\n\\nwho や what が主語のときは、そのまま動詞を続ける。しかも who / what は三人称単数あつかいなので、動詞には -s が付く。\\n\\n✗ Who does play the piano?\\n○ Who plays the piano?\\n\\n■ 見分け方\\n疑問詞のうしろに「別の主語」があるかどうかを見る。\\n\\nWhat do you want?　→ you という主語がある → do が要る\\nWho wants this?　　→ 主語にあたる語がない → who 自身が主語 → do は不要\\n\\n■ 答え方\\nWho plays the piano? － My sister does.（姉です）\\nこの does は plays the piano のかわりをしている。\\n\\n⚠ 注意：疑問詞が主語の文は上位校でよく問われる。「疑問詞のうしろに主語があるか」で判断する手順を身につけておく。\",\"mangaId\":\"eigo_s060_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは日曜日に何をしますか。」を英語にしなさい。（on Sundays を使う）\",\"wrongAnswer\":\"What you do on Sundays?\",\"trapExplanation\":\"疑問詞を前に出すところまではできるが、そのあとを肯定文の語順のままにしてしまう。日本語の「あなたは何を するか」の順とも合ってしまうので、まちがいに気づきにくい。\",\"correctAnswer\":\"What do you do on Sundays?\",\"correctExplanation\":\"疑問詞のうしろも疑問文の語順を保つので、〈do＋主語＋動詞〉と続ける。この文では最初の do が疑問文を作る語、二つ目の do が「する」という意味の動詞である。二つ並ぶのが正しい形。\"},{\"question\":\"「あなたの家族でだれがギターをひきますか。」を英語にしなさい。（in your family を使う）\",\"wrongAnswer\":\"Who does play the guitar in your family?\",\"trapExplanation\":\"疑問文には do / does が要ると覚えているので、疑問詞のうしろに機械的に does を入れてしまう。who が主語そのものになっている文の形を知らないと必ず引っかかる。\",\"correctAnswer\":\"Who plays the guitar in your family?\",\"correctExplanation\":\"who がこの文の主語なので、あらためて主語を置く必要がなく、do / does も不要である。who は三人称単数あつかいなので動詞は plays になる。「疑問詞のうしろに別の主語があるか」を見て、なければ do / does を使わない、と判断する。\"}]}",
"{\"id\":\"eigo_s061\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"混同を防ぐ①：一文に動詞は一つ\",\"description\":\"be動詞と一般動詞を並べてしまう誤りの原因を知り、動詞を一つに決める練習をする\",\"intro\":\"I am play tennis. も He is like music. も、まちがいの正体は同じです。動詞を2つ並べていること。日本語の「です・ます」につられると、つい be動詞を足してしまいます。指さして確かめる習慣をつけましょう。\",\"order\":561,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"一つの文に動詞は一つ。be動詞と一般動詞を並べることはできない。\",\"文を書いたら「動詞はどれか」を指さして一つだけか確かめる。\",\"日本語の「です・ます」に引かれて be動詞を足さない。\",\"live・belong・come・go などは一般動詞なので be動詞は不要。\",\"「〜しています」でも、習慣を表すなら現在形（I play tennis every day.）。\"],\"sections\":[{\"heading\":\"なぜ動詞を二つ書いてしまうのか\",\"mangaId\":\"eigo_s061_manga\",\"body\":\"英語を書くときにもっとも多い誤りが、be動詞と一般動詞を並べてしまうことである。\\n\\n✗ I am like dogs.\\n✗ He is play baseball.\\n✗ We are study English.\\n\\n原因は主に三つある。\\n\\n■ ①日本語の「です・ます」に引かれる\\n「私は犬が好きです」の「です」を be動詞だと感じてしまう。しかし英語では like がすでに動詞なので、be動詞は要らない。\\n\\n■ ②主語のあとには am / is / are、という手が覚えている\\nI am 〜 の練習をたくさんするので、主語を書いた瞬間に be動詞を書く手ぐせがついてしまう。\\n\\n■ ③「〜しています」を進行形と思ってしまう\\n「私は毎日サッカーをしています」は、習慣を表すので現在形 I play soccer every day. でよい。今この瞬間の動作なら I am playing soccer now. と ing 形にするが、この場合も動詞の原形を並べてはいけない。\\n\\n★ ポイント：文を書き終わったら、動詞に丸を付けてみる。丸が二つ付いたら、どちらかが余分である。\",\"figureId\":\"xf_eigo_s061\"},{\"heading\":\"まぎらわしい動詞\",\"body\":\"日本語では「〜です」「〜にいます」と訳すのに、英語では一般動詞を使う語がある。これらは be動詞を足したくなるので注意する。\\n\\n■ live（住んでいる）\\n○ I live in Osaka.（私は大阪に住んでいます）\\n✗ I am live in Osaka.\\n\\n■ belong to（〜に所属している）\\n○ I belong to the tennis club.（私はテニス部に入っています）\\n✗ I am belong to the tennis club.\\n※「私はテニス部員です」なら I am a member of the tennis club. と be動詞を使う。\\n\\n■ have（持っている・いる）\\n○ I have two sisters.（私には姉妹が二人います）\\n✗ I am have two sisters.\\n\\n■ know（知っている）\\n○ I know him.　✗ I am know him.\\n\\n■ 逆に be動詞を使うもの\\n形容詞や名詞が続くときは be動詞である。\\n○ I am happy.（私は幸せです）\\n○ He is a doctor.（彼は医者です）\\n○ She is at home.（彼女は家にいます）\\n\\n⚠ 注意：うしろに来るのが「動作を表す語」なら一般動詞だけ、「名前・様子を表す語」なら be動詞、と切り分けて考える。\"}],\"trapExamples\":[{\"question\":\"「彼は毎週日曜日に野球をします。」を英語にしなさい。\",\"wrongAnswer\":\"He is play baseball every Sunday.\",\"trapExplanation\":\"主語を書いたあとに be動詞を置く手ぐせが働き、そのあとに動詞 play を続けてしまう。「彼は〜です」という日本語の形にも合ってしまうため、読み返しても違和感を持ちにくい。\",\"correctAnswer\":\"He plays baseball every Sunday.\",\"correctExplanation\":\"一文に動詞は一つなので、play を使うなら is は要らない。さらに主語 He は三人称単数なので plays と -s を付ける。書いたあとに動詞をさがして、二つあれば余分なほうを消す、という見直しを習慣にする。\"},{\"question\":\"「私はバスケットボール部に入っています。」を英語にしなさい。（belong to を使う）\",\"wrongAnswer\":\"I am belong to the basketball team.\",\"trapExplanation\":\"「入っています」という状態を表す日本語なので、be動詞を使う文だと感じてしまう。belong が動詞であることを意識していないと、am を足したくなる。\",\"correctAnswer\":\"I belong to the basketball team.\",\"correctExplanation\":\"belong は一般動詞なので be動詞は要らない。もし be動詞を使って言うなら I am a member of the basketball team.（私はバスケットボール部の一員です）のように、うしろに名詞を置く形にする。使う動詞を一つに決めてから文を組み立てる。\"}]}",
"{\"id\":\"eigo_s062\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"混同を防ぐ②：否定文は isn't か doesn't か\",\"description\":\"否定文を作るとき、not だけでよいのか do / does が要るのかを判断できるようにする\",\"intro\":\"He isn't speak Japanese. と He doesn't a teacher. は、どちらも同じ迷いから生まれます。not だけでよいのか、do を借りるのか。決め手は、もとの文の動詞が be動詞かどうか、その一点です。\",\"order\":562,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"be動詞の文 → be動詞のうしろに not（isn't / aren't / am not）。\",\"一般動詞の文 → 動詞の前に don't / doesn't。\",\"判断の手順：もとの文の動詞が am / is / are かどうかを見る。\",\"doesn't のうしろの動詞は原形。\",\"× He doesn't a teacher.／× He isn't speak Japanese. の二方向の誤りに注意。\"],\"sections\":[{\"heading\":\"判断は「もとの文の動詞」で\",\"body\":\"否定文を作るときにやることは、たった一つの判断で決まる。「もとの文の動詞が be動詞か一般動詞か」である。\\n\\n■ be動詞の文 → not をうしろに置くだけ\\nHe is a teacher. → He is not（isn't）a teacher.\\nThey are busy. → They aren't busy.\\nI am tired. → I'm not tired.\\n\\n■ 一般動詞の文 → don't / doesn't を前に置く\\nHe speaks Japanese. → He doesn't speak Japanese.\\nThey play tennis. → They don't play tennis.\\nI know him. → I don't know him.\\n\\n■ 二方向のまちがい\\n①be動詞の文なのに doesn't を使う\\n✗ He doesn't a teacher.（動詞がなくなってしまう）\\n②一般動詞の文なのに isn't を使う\\n✗ He isn't speak Japanese.（動詞が二つになってしまう）\\n\\nどちらも「動詞が何個あるか」を数えれば気づける。①は動詞がゼロ、②は動詞が二つになっている。\\n\\n★ ポイント：正しい文には必ず動詞が一つある。否定文を作ったら、もう一度動詞を数える。\"},{\"heading\":\"練習と確認手順\",\"body\":\"否定文にするときの手順を三段階で決めておく。\\n\\n①もとの文の動詞をさがす\\n②それが am / is / are なら、うしろに not を入れて終わり\\n③それ以外（一般動詞）なら、主語を見て don't か doesn't を選び、動詞を原形にする\\n\\n■ 例で確かめる\\nThe book is interesting.\\n→ 動詞は is（be動詞）→ The book isn't interesting.\\n\\nMy father cooks dinner on Sundays.\\n→ 動詞は cooks（一般動詞）→ 主語は三人称単数 → My father doesn't cook dinner on Sundays.\\n\\nWe are in the same class.\\n→ 動詞は are → We aren't in the same class.\\n\\nKen and Mika go to the same school.\\n→ 動詞は go → 主語は複数 → Ken and Mika don't go to the same school.\\n\\n■ 特に注意する動詞\\nhave は一般動詞である。\\nI have a dog. → I don't have a dog.（○）\\n✗ I am not have a dog.\\n\\n⚠ 注意：「〜がいます／あります」を be動詞で表している文（There is a cat 〜）の否定は There isn't a cat 〜 で、be動詞の規則にしたがう。\"},{\"heading\":\"なぜ be動詞は not だけで、一般動詞は do を借りるのか\",\"mangaId\":\"eigo_s062_manga\",\"body\":\"be動詞（am / is / are）は、そのものが「〜である」という意味を持ち、否定するには**うしろに not を置くだけ**で足ります（is not）。ところが一般動詞（speak・play・know）は、そのままでは not を付けられません。そこで英語は「do」という**手伝いの語**を借りて、do not（don't）speak と否定します。does は主語が三人称単数のときの do の形で、そのぶん動詞は原形に戻します。つまり否定文の作り方は、もとの文の動詞が be動詞かどうか、その一点で決まります。\\n\\n「動詞を数える」と確かめられるのは、正しい文には**動詞が必ず一つ**あるからです。He doesn't a teacher. は動詞がゼロ（is が消えた）、He isn't speak Japanese. は動詞が二つ（is と speak）。どちらも数えれば気づけます。\\n\\n■ 確かめのしかた\\n①もとの文の**動詞を探す**。am / is / are なら be動詞、それ以外なら一般動詞。\\n②be動詞なら、うしろに not（isn't / aren't / I'm not）。一般動詞なら、前に don't / doesn't を置き、動詞を**原形**に戻す。\\n③作った否定文の**動詞を数える**。ゼロや二つになっていたら×。\\n④have は一般動詞（I don't have a dog.）。There is 〜 の否定は There isn't 〜（be動詞の規則）。\\n\\n★ ここがポイント：be動詞は**not だけで否定できる**が、一般動詞は**do を借りる**。決め手は**もとの文の動詞が be動詞か**の一点。作ったら**動詞が一つ**あるか数える。\",\"figureId\":\"xf_eigo_s062\"}],\"trapExamples\":[{\"question\":\"次の文を否定文にしなさい。　My uncle is a police officer.\",\"wrongAnswer\":\"My uncle doesn't a police officer.\",\"trapExplanation\":\"否定文といえば doesn't、という手順を先に思い出してしまい、もとの文の動詞を確かめない。日本語に直すと「警察官ではありません」となり、doesn't でも意味が通じるように感じてしまう。\",\"correctAnswer\":\"My uncle is not a police officer.（My uncle isn't a police officer.）\",\"correctExplanation\":\"もとの文の動詞は is という be動詞なので、うしろに not を入れるだけでよい。doesn't を使うと文から動詞が消えてしまう。否定文を作ったら、動詞が一つ残っているかを必ず数える。\"},{\"question\":\"次の文を否定文にしなさい。　Tom speaks Japanese.\",\"wrongAnswer\":\"Tom isn't speak Japanese.\",\"trapExplanation\":\"「〜しません」を be動詞の否定文と同じ形で作ろうとしてしまう。isn't は使い慣れているので、動詞の種類を確かめずに手が動いてしまう。\",\"correctAnswer\":\"Tom doesn't speak Japanese.\",\"correctExplanation\":\"speaks は一般動詞なので、否定には doesn't を動詞の前に置き、動詞を原形 speak に戻す。isn't speak では is と speak の二つの動詞が並んでしまう。もとの文の動詞を見てから、not か doesn't かを決める。\"}]}",
"{\"id\":\"eigo_s063\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"混同を防ぐ③：疑問文は Are you か Do you か\",\"description\":\"疑問文を作るとき、be動詞を前に出すのか Do を借りるのかを見分ける\",\"intro\":\"Are you have a pen? と言ってしまうのは、have が「あります」に近く感じられるからでしょうか。have は一般動詞なので Do you have a pen? が正しい形です。見分け方をはっきりさせましょう。\",\"order\":563,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"be動詞の文 → be動詞を主語の前に出す（Are you 〜? / Is he 〜?）。\",\"一般動詞の文 → Do / Does を先頭に置く（Do you 〜? / Does he 〜?）。\",\"答えも同じ語でそろえる（Are 〜? → Yes, I am. ／ Do 〜? → Yes, I do.）。\",\"× Do you are 〜?／× Are you have 〜? は動詞が二つになるので誤り。\",\"have は一般動詞なので Do you have 〜? が正しい。\"],\"sections\":[{\"heading\":\"二つの作り方を並べて見る\",\"body\":\"疑問文の作り方は、be動詞の文と一般動詞の文でまったくちがう。並べて確かめる。\\n\\n■ be動詞の文\\nYou are a student. → Are you a student?\\nHe is kind. → Is he kind?\\nThey are at home. → Are they at home?\\nやること：be動詞を主語の前に出す。\\n\\n■ 一般動詞の文\\nYou play tennis. → Do you play tennis?\\nHe plays tennis. → Does he play tennis?\\nThey live here. → Do they live here?\\nやること：Do / Does を先頭に置き、動詞は原形にする。\\n\\n■ 動詞が二つになる誤り\\n✗ Do you are a student?（do と are）\\n✗ Are you play tennis?（are と play）\\n✗ Are you have a pen?（are と have）\\n\\nどれも動詞が二つ並んでいる。疑問文を作ったら、Do / Does をのぞいて動詞が一つかを確かめる。\\n\\n★ ポイント：Do / Does は動詞の数に数えない「合図の語」である。合図の語＋動詞一つ、が正しい形。\"},{\"heading\":\"答え方までそろえる\",\"body\":\"問いの最初の語と、答えに使う語をそろえるのが鉄則である。\\n\\n■ Are / Is で始まる問い → be動詞で答える\\nAre you hungry? － Yes, I am. / No, I'm not.\\nIs he your brother? － Yes, he is. / No, he isn't.\\n\\n■ Do / Does で始まる問い → do / does で答える\\nDo you like music? － Yes, I do. / No, I don't.\\nDoes she play the piano? － Yes, she does. / No, she doesn't.\\n\\n■ 混ぜてはいけない\\n✗ Do you like music? － Yes, I am.\\n✗ Are you a student? － Yes, I do.\\n\\n■ have に注意\\n「持っていますか」は一般動詞の疑問文である。\\n○ Do you have a pen?（ペンを持っていますか）\\n✗ Are you have a pen?\\n答えも Yes, I do. になる。\\n\\n■ 「〜にいますか」は be動詞\\n○ Are you at home now?（今、家にいますか）\\n答えは Yes, I am.\\n\\n⚠ 注意：日本語の訳は手がかりにならないことが多い。使う英語の動詞が be動詞か一般動詞かで機械的に決める。\"},{\"heading\":\"なぜ Do は動詞の数に数えないのか、なぜ答えの語をそろえるのか\",\"mangaId\":\"eigo_s063_manga\",\"body\":\"be動詞の疑問文は、be動詞を主語の前に出すだけで作れます（Are you 〜?）。一般動詞は前に出せないので、否定文と同じように **Do / Does という合図の語**を借りて先頭に置きます。Do は「これから疑問文です」という合図であって動作の意味は持たないので、動詞の数には数えません。だから正しい疑問文は「合図の語＋動詞一つ」か「be動詞＋主語」のどちらかで、Do you are 〜? や Are you have 〜? は動詞が二つ並んでいて×です。\\n\\n答えの語をそろえるのは、答えが**問いの動詞をくり返す**形だからです。Are you hungry? には Yes, I am（hungry）。Do you like music? には Yes, I do（like music）。問いが Do なら do、Are なら am で受けないと、何をくり返しているのか分からなくなります。\\n\\n■ 確かめのしかた\\n①もとの文の動詞が be動詞なら**主語の前に出す**、一般動詞なら**Do / Does を先頭**に置いて動詞を原形にする。\\n②作った疑問文で、Do / Does をのぞいて**動詞が一つ**か数える。\\n③**問いの最初の語**を見てから答える。Are 〜?→Yes, I am. / No, I'm not.、Do 〜?→Yes, I do. / No, I don't.\\n④have は一般動詞（Do you have a pen?→Yes, I do.）。「〜にいますか」は be動詞（Are you at home?→Yes, I am.）。\\n\\n★ ここがポイント：Do / Does は**疑問文の合図の語**で動詞に数えないので、「合図＋動詞一つ」か「be動詞＋主語」が正しい形。答えは**問いの最初の語をくり返す**（Do→do、Are→am）。\",\"figureId\":\"xf_eigo_s063\"}],\"trapExamples\":[{\"question\":\"「あなたは自転車を持っていますか。」を英語にしなさい。（a bike を使う）\",\"wrongAnswer\":\"Are you have a bike?\",\"trapExplanation\":\"Are you 〜? という形が口になじんでいるため、たずねる文はまず Are you で始めてしまう。have が一般動詞であることを確かめないまま、そのうしろに置いてしまう。\",\"correctAnswer\":\"Do you have a bike?\",\"correctExplanation\":\"have は一般動詞なので、疑問文は Do を先頭に置いて作る。Are you have 〜? では are と have の二つの動詞が並んでしまう。答えも Yes, I do. / No, I don't. とそろえる。\"},{\"question\":\"Do you like sports? に No で答えなさい。\",\"wrongAnswer\":\"No, I'm not.\",\"trapExplanation\":\"No で答える形として I'm not をいちばんよく練習しているため、問いの最初の語を見ずに書いてしまう。会話としては通じそうに感じるのも見落としの原因である。\",\"correctAnswer\":\"No, I don't.\",\"correctExplanation\":\"Do 〜? でたずねられているので、答えにも do を使って No, I don't. とする。I'm not で答えるのは Are you 〜? と聞かれたときである。問いの最初の語を必ず見てから答えを書く、という手順を守る。\"}]}",
"{\"id\":\"eigo_s064\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"混同を防ぐ④：四つの型のまとめ\",\"description\":\"be動詞と一般動詞、否定文と疑問文の四つの組み合わせを一枚に整理する\",\"intro\":\"be動詞か一般動詞か、否定文か疑問文か。組み合わせはたった4つしかありません。それなのに混乱するのは、一つずつばらばらに覚えているからです。1枚の表にまとめると、自分がどこで迷っているのかが見えてきます。\",\"order\":564,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"四つの型：be動詞の否定／be動詞の疑問／一般動詞の否定／一般動詞の疑問。\",\"be動詞の否定＝isn't・aren't、疑問＝Is 〜? Are 〜?。\",\"一般動詞の否定＝don't・doesn't、疑問＝Do 〜? Does 〜?。\",\"形容詞（sleepy・hungry）は be動詞、動作を表す語は一般動詞。\",\"「〜がいます・持っています」は have（一般動詞）、「〜です・〜にいます」は be動詞。\"],\"sections\":[{\"heading\":\"四つの型を一枚に\",\"body\":\"ここまで学んだ形を、二つの軸（be動詞か一般動詞か／否定か疑問か）で整理する。\\n\\n■ be動詞の文\\n肯定　He is a student.\\n否定　He is not（isn't）a student.\\n疑問　Is he a student? － Yes, he is. / No, he isn't.\\n\\n■ 一般動詞の文\\n肯定　He plays tennis.\\n否定　He does not（doesn't）play tennis.\\n疑問　Does he play tennis? － Yes, he does. / No, he doesn't.\\n\\n■ 決め方の順序\\n①この文で使う動詞は何か\\n②それが am / is / are なら be動詞の規則、それ以外なら一般動詞の規則\\n③一般動詞なら、主語を見て do か does かを決め、動詞を原形にする\\n\\nこの順に考えれば、どんな文でも迷わない。日本語の訳から入ると、「です・ます」に引かれて必ずまちがえる。\\n\\n★ ポイント：まず英語の動詞を決める。動詞が決まれば、否定文も疑問文も自動的に決まる。\",\"figureId\":\"lf_eigoext02_064\"},{\"heading\":\"まぎらわしい日本語\",\"body\":\"日本語からは判断できない例を集めて確かめる。\\n\\n■ 「私はねむいです」\\nsleepy は形容詞 → be動詞\\n○ I am sleepy.　✗ I sleep.（これは「私は眠る」）\\n\\n■ 「私は兄が二人います」\\n「います」でも所有を表す → have\\n○ I have two brothers.　✗ I am two brothers.\\n\\n■ 「彼は大阪に住んでいます」\\nlive は一般動詞\\n○ He lives in Osaka.　✗ He is live in Osaka.\\n\\n■ 「彼は大阪にいます」\\n場所を表す → be動詞\\n○ He is in Osaka.\\n\\n■ 「私はサッカーが好きです」\\nlike は一般動詞\\n○ I like soccer.　✗ I am like soccer.\\n\\n■ 「私はサッカー選手です」\\n名詞が続く → be動詞\\n○ I am a soccer player.\\n\\n⚠ 注意：同じ「〜います」でも、〈場所〉が続けば be動詞、〈持っているもの〉が続けば have になる。うしろに何が来るかを見て決める。\"},{\"heading\":\"なぜ日本語の訳から入るとまちがえるのか\",\"mangaId\":\"eigo_s064_manga\",\"body\":\"日本語の「です・ます」は、be動詞にも一般動詞にも付きます。「ねむいです」「サッカー選手です」はどちらも「です」ですが、英語では sleepy（形容詞）も a soccer player（名詞）も be動詞で結びます。「兄がいます」「大阪にいます」はどちらも「います」ですが、家族は have、場所は be動詞です。つまり**日本語の語尾は英語の動詞を決める手がかりにならない**ので、訳から入ると必ずどこかでまちがえます。\\n\\nだから決め方は「まず英語の動詞を決める」です。①この文で使う動詞は何か、②am / is / are なら be動詞の規則、それ以外なら一般動詞の規則、③一般動詞なら主語を見て do / does。動詞が決まれば、否定文も疑問文も四つの型のどれかに自動的に決まります。四つの型を一枚の表にするのは、自分がどの型で迷っているかを見えるようにするためです。\\n\\n■ 確かめのしかた\\n①日本語ではなく**うしろに来る語**で決める。形容詞（sleepy・hungry）→be動詞。名詞（a player）→be動詞。動作（play・live・like）→一般動詞。\\n②「〜います」は、うしろが**持っているもの・家族**なら have、**場所**なら be動詞。I have two sisters. ／ He is in Osaka.\\n③動詞を決めたら、四つの型のどれかを言う：be動詞の否定（isn't）／疑問（Is 〜?）、一般動詞の否定（doesn't）／疑問（Does 〜?）。\\n④I am like soccer. や He is live in Osaka. のように、be動詞と一般動詞を重ねていないか（動詞を数える）。\\n\\n★ ここがポイント：日本語の「です・います」は**英語の動詞を決める手がかりにならない**。**うしろに来る語**（形容詞・名詞→be動詞、動作→一般動詞、持ち物→have）で動詞を決めれば、否定・疑問は四つの型に自動的に決まる。\"}],\"trapExamples\":[{\"question\":\"「私は今日、とてもねむいです。」を英語にしなさい。（sleepy／very／today を使う）\",\"wrongAnswer\":\"I sleep very today.\",\"trapExplanation\":\"sleep（眠る）と sleepy（ねむい）が形も意味も近いので、動詞のほうを選んでしまう。動詞を使えば be動詞は要らないと考え、文としてはそろっているように見えてしまう。\",\"correctAnswer\":\"I am very sleepy today.\",\"correctExplanation\":\"sleepy は「ねむい」という状態を表す形容詞なので、be動詞で主語と結ぶ。I sleep は「私は眠る」という動作の意味になり、日本語とずれてしまう。うしろに来る語が形容詞なら be動詞、と決めて選ぶ。\"},{\"question\":\"「私には妹が二人います。」を英語にしなさい。\",\"wrongAnswer\":\"I am two sisters.\",\"trapExplanation\":\"「います」という日本語を「存在」ととらえ、be動詞を使う文だと考えてしまう。しかし I am two sisters. は「私は二人の妹です」という意味になり、まったく通じない。\",\"correctAnswer\":\"I have two sisters.\",\"correctExplanation\":\"家族が何人いるかを言うときは have（持っている・いる）を使う。be動詞は主語と「＝」で結ぶ語なので、I ＝ two sisters となってしまい意味が通らない。「〜がいます」は have、「〜です」は be動詞、と分けて覚える。\"}]}",
"{\"id\":\"eigo_s065\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"文の要素と五つの文型\",\"description\":\"S・V・O・C という文の部品と、修飾語（M）との区別をつかむ\",\"intro\":\"同じ「〜になる」でも、He became a doctor. と He got angry. では後ろに来る語の種類がちがいます。英語の文は S・V・O・C という部品でできていて、その組み合わせは5つだけ。部品の見分け方から始めます。\",\"order\":565,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"文の要素は S（主語）・V（動詞）・O（目的語）・C（補語）の四つ。\",\"修飾語（M）は文型に数えない。前置詞から始まるかたまり・時を表す語句など。\",\"五つの文型：SV／SVC／SVO／SVOO／SVOC。\",\"C は主語や目的語とイコールになる語。O はイコールにならない。\",\"文型を答える問題では、まず修飾語を（　）でくくって消す。\"],\"sections\":[{\"heading\":\"文の四つの部品\",\"body\":\"英語の文は、次の四つの部品（要素）を組み合わせてできている。\\n\\n■ S（主語）＝「〜は・〜が」にあたる語\\n例）Ken runs fast. の Ken\\n\\n■ V（動詞）＝「〜する・〜である」にあたる語\\n例）Ken runs fast. の runs\\n\\n■ O（目的語）＝「〜を・〜に」にあたる語\\n例）I like music. の music\\n\\n■ C（補語）＝主語や目的語がどんなものかを説明し、イコールで結ばれる語\\n例）He is a doctor. の a doctor（He ＝ a doctor）\\n\\n■ M（修飾語）＝上の四つ以外のかざりの語句\\n例）in the park（公園で）／every day（毎日）／very（とても）／fast（速く）\\n修飾語は文型を決めるときには数えない。取りのぞいても文が成り立つのが特徴である。\\n\\n★ ポイント：文型を答えるときは、まず前置詞（in・on・at・with・to・for など）から始まるかたまりと、時を表す語句を（　）でくくって消す。残った骨組みが文型である。\",\"figureId\":\"lf_eigoext02_065\"},{\"heading\":\"五つの文型\",\"body\":\"残った骨組みの組み合わせ方は、五種類しかない。\\n\\n■ 第1文型　SV\\n例）Birds fly.（鳥が飛ぶ）\\n例）I go to school.（to school は M）\\n\\n■ 第2文型　SVC（S＝C）\\n例）He is a teacher.（He ＝ a teacher）\\n例）She looks happy.（She ＝ happy）\\n\\n■ 第3文型　SVO（S≠O）\\n例）I like dogs.（I ≠ dogs）\\n例）He plays the piano.\\n\\n■ 第4文型　SVOO（人に・ものを）\\n例）He gave me a book.（me ＝ 人、a book ＝ もの）\\n\\n■ 第5文型　SVOC（O＝C）\\n例）We call him Ken.（him ＝ Ken）\\n例）The news made me happy.（me ＝ happy）\\n\\n■ 見分けの鍵は「イコールかどうか」\\nC が出てくる文型（SVC・SVOC）では、必ずイコールの関係がある。O が二つ並ぶ SVOO では、二つの O はイコールにならない。\\n\\n⚠ 注意：文型を答える問題で修飾語を数えてしまうと、SVO を SVOO と答えるようなまちがいが起こる。まず修飾語を消す、という作業を必ず先に行う。\"},{\"heading\":\"なぜ修飾語を消してから文型を決めるのか、なぜ「イコール」で見分けるのか\",\"mangaId\":\"eigo_s065_manga\",\"body\":\"文型は、文の**骨組み**（S・V・O・C）の組み合わせです。in the park や every morning のような修飾語は、取りのぞいても文が成り立つ飾りなので、骨組みには入りません。修飾語を残したまま数えると、I play tennis in the park. を「tennis と in the park で目的語が二つ」と見て SVOO と答えてしまいます。だから先に前置詞から始まるかたまりと時を表す語句を（　）でくくって消し、残った骨組みで決めます。\\n\\nC（補語）を「イコール」で見分けるのは、補語が**主語や目的語がどんなものかを説明する語**だからです。He is a doctor. は He＝a doctor、We call him Ken. は him＝Ken。いっぽう O（目的語）は動作の相手なので、I like dogs. の I≠dogs、He gave me a book. の me≠a book です。イコールが成り立つかどうかで、SVC・SVOC と SVO・SVOO を分けられます。\\n\\n■ 確かめのしかた\\n①**前置詞（in・on・at・with・to・for）から始まるかたまりと時の語句**を（　）でくくる。\\n②残った語に S・V・O・C を当てる。主語は「動詞の動作をする人・もの」で、先頭にあるかどうかでは決めない（Every morning my mother makes breakfast. の S は my mother）。\\n③動詞のうしろの語が**主語とイコール**なら C（SVC）、イコールでなければ O（SVO）。\\n④O のうしろにもう一語あれば、**O とイコール**なら C（SVOC：him＝Ken）、イコールでなければ二つ目の O（SVOO：me≠a book）。\\n\\n★ ここがポイント：文型は**骨組み**なので、**修飾語を先に（　）で消す**。C は**イコールになる語**（He＝a doctor、him＝Ken）、O はならない語。この二つの作業で五つの文型は必ず決まる。\"}],\"trapExamples\":[{\"question\":\"次の文の文型を答えなさい。　I play tennis in the park.\",\"wrongAnswer\":\"第4文型（SVOO）\",\"trapExplanation\":\"play のうしろに tennis と in the park の二つのまとまりが見えるので、目的語が二つある第4文型だと考えてしまう。修飾語を先に消す作業をしていないために起こる。\",\"correctAnswer\":\"第3文型（SVO）\",\"correctExplanation\":\"in the park は前置詞 in から始まる修飾語（M）なので、文型には数えない。これを消すと I（S）play（V）tennis（O）が残り、第3文型になる。文型の問題では、前置詞から始まるかたまりを最初に（　）でくくる。\"},{\"question\":\"次の文の主語（S）を答えなさい。　Every morning my mother makes breakfast.\",\"wrongAnswer\":\"Every morning\",\"trapExplanation\":\"主語は文のいちばん前に来るものだと覚えているので、先頭にある Every morning をそのまま主語だと考えてしまう。時を表す語句が前に置かれることがあると知らないと引っかかる。\",\"correctAnswer\":\"my mother\",\"correctExplanation\":\"Every morning は「毎朝」という時を表す修飾語で、文の前に置かれているだけである。「だれが作るのか」を考えれば主語は my mother だと分かる。主語は「動詞の動作をする人・もの」であって、位置だけで決めてはいけない。\"}]}",
"{\"id\":\"eigo_s066\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"第1文型 SV：動詞だけで意味が完成する文\",\"description\":\"目的語も補語も要らない文の形と、うしろに続く修飾語の見分け方を学ぶ\",\"intro\":\"I go to school. の「学校に」は、日本語では目的語のように見えます。でも英語では to school は飾りにすぎず、文の骨組みは I go の2つだけ。この見分けができると、文型の問題が怖くなくなります。\",\"order\":566,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"第1文型は〈S＋V〉。目的語も補語もない。\",\"うしろに語句が続いても、修飾語であれば第1文型のまま。\",\"go / come / run / walk / live / swim / sit / stand などが代表的。\",\"I go to school. は to school が修飾語なので SV。\",\"「〜を」と訳せても、前置詞が入っていれば目的語ではない。\"],\"sections\":[{\"heading\":\"動詞だけで意味が通る\",\"body\":\"第1文型は、主語と動詞だけで意味が完成する文である。\\n\\n■ 形\\nS＋V\\n\\n例）Birds fly.（鳥が飛ぶ）\\n例）The baby cried.（赤ちゃんが泣いた）\\n例）He runs.（彼は走る）\\n\\nこれだけでも文として成り立つ。「何を」も「どんなだ」も要らない。\\n\\n■ うしろに修飾語が付いても第1文型\\n実際の文では、うしろに場所や時を表す語句が付くことがほとんどである。しかしそれは修飾語なので、文型は SV のままである。\\n\\n例）I go to school.（S＝I、V＝go、to school は M）\\n例）He lives in Kyoto.（in Kyoto は M）\\n例）We walked in the park yesterday.（in the park と yesterday が M）\\n例）She swims very fast.（very fast は M）\\n\\n■ 代表的な動詞\\ngo（行く）／come（来る）／run（走る）／walk（歩く）／swim（泳ぐ）／live（住む）／sit（すわる）／stand（立つ）／sleep（眠る）／arrive（着く）／happen（起こる）\\n\\n★ ポイント：第1文型かどうかは「動詞のうしろに、前置詞なしの名詞や形容詞があるか」で見分ける。なければ第1文型である。\",\"figureId\":\"xf_eigo_s066\"},{\"heading\":\"「〜を」に引かれない\",\"body\":\"日本語に訳すと「〜を」となるのに、英語では前置詞が要る場合がある。このとき前置詞から始まるかたまりは修飾語なので、目的語ではない。\\n\\n例）He runs in the park.（彼は公園を走る）\\n「公園を」と訳すが、英語では in the park という修飾語である。\\n✗ He runs the park.\\n\\n例）We walked along the river.（私たちは川ぞいを歩いた）\\n例）The bird flew over the house.（鳥は家の上を飛んだ）\\n\\n日本語の「を」だけで目的語を判断してはいけない。英語の形（前置詞があるかないか）で判断する。\\n\\n■ 逆に前置詞が要らない動詞もある\\n例）I entered the room.（私は部屋に入った）\\n「部屋に」と訳すが、enter は前置詞なしで目的語をとる。これは第3文型である。\\n\\n例）We reached the station.（駅に着いた）\\n※ arrive は arrive at the station と前置詞が要る（第1文型）。\\n\\n⚠ 注意：訳ではなく、英語の形を覚える。go to／arrive at／listen to は前置詞が要り、enter／reach／discuss は前置詞なしで目的語をとる。\",\"mangaId\":\"eigo_s066_xm\"}],\"trapExamples\":[{\"question\":\"次の文の文型を答えなさい。　My father goes to work by train.\",\"wrongAnswer\":\"第3文型（SVO）\",\"trapExplanation\":\"goes のうしろに to work という語句が続くので、それを目的語だと考えてしまう。「仕事へ行く」と訳せるので、work が「何を」にあたるように感じてしまう。\",\"correctAnswer\":\"第1文型（SV）\",\"correctExplanation\":\"to work も by train も前置詞から始まる修飾語なので、文型には数えない。残るのは My father（S）goes（V）だけなので第1文型である。前置詞が付いている語句は目的語になれない、と覚えておく。\"},{\"question\":\"「彼は毎朝、公園を走ります。」を英語にしなさい。（the park／every morning を使う）\",\"wrongAnswer\":\"He runs the park every morning.\",\"trapExplanation\":\"日本語の「公園を」の「を」を目的語のしるしだと考え、前置詞なしで the park を置いてしまう。日本語の助詞と英語の目的語を一対一で対応させているのが原因。\",\"correctAnswer\":\"He runs in the park every morning.\",\"correctExplanation\":\"run は「走る」という動作だけで意味が完成する動詞で、走る場所は in / along などの前置詞を使って表す。日本語の「を」に引かれず、英語ではどの前置詞を使うかで覚える。この文は第1文型である。\"}]}",
"{\"id\":\"eigo_s067\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"第2文型 SVC：主語とイコールになる語\",\"description\":\"補語（C）の見分け方と、S＝C という関係の確かめ方を身につける\",\"intro\":\"He is a doctor. の he と a doctor は同じ人です。I like dogs. の I と dogs は別ものです。後ろに来る語が主語とイコールになるかどうか。この一点で文型が決まります。実際に「＝」を書いて確かめましょう。\",\"order\":567,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"第2文型は〈S＋V＋C〉。S＝C の関係が成り立つ。\",\"C になるのは名詞と形容詞。副詞は C になれない。\",\"be動詞の文はほとんどが第2文型（He is a doctor. / She is kind.）。\",\"become・look・get・feel・sound・taste・smell も SVC を作る。\",\"S＝C かどうかを、実際に「＝」を書いて確かめる。\"],\"sections\":[{\"heading\":\"S＝C の関係\",\"body\":\"第2文型は、動詞のうしろに主語を説明する語（補語 C）が来る文である。S と C はイコールの関係になる。\\n\\n■ 形\\nS＋V＋C（S＝C）\\n\\n例）He is a doctor.（He ＝ a doctor）\\n例）She is kind.（She ＝ kind）\\n例）My father is a teacher.（My father ＝ a teacher）\\n例）This book is interesting.（This book ＝ interesting）\\n\\n■ C になれるのは名詞と形容詞\\n名詞　a doctor / a teacher / my friend\\n形容詞　kind / happy / interesting / young\\n\\n✗ 副詞は C になれない\\nHe is well. の well は「体調がよい」という意味の形容詞で、副詞の「上手に」の意味にはならない。第2文型の C には形容詞を置く。\\n\\n■ 確かめ方\\n文を書いたら、S と C の間に「＝」を書いてみる。意味が通れば第2文型である。\\n\\nHe is a doctor. → He ＝ a doctor（○）\\nI like dogs. → I ＝ dogs（✗ 意味が通らない → 第3文型）\\n\\n★ ポイント：この「＝を書いてみる」作業が、第2文型と第3文型を見分けるいちばん確実な方法である。\",\"figureId\":\"lf_eigoext02_067\",\"mangaId\":\"eigo_s067_xm\"},{\"heading\":\"be動詞以外の SVC\",\"body\":\"be動詞以外にも、S＝C の関係を作る動詞がある。\\n\\n■ become（〜になる）\\n例）He became a doctor.（彼は医者になった）\\n例）She will become famous.\\n\\n■ look（〜に見える）\\n例）You look tired.（あなたはつかれて見える）\\n例）He looks happy.\\n\\n■ get（〜になる）\\n例）It is getting dark.（暗くなってきた）\\n例）He got angry.（彼は怒った）\\n\\n■ feel（〜と感じる）／sound（〜に聞こえる）／taste（〜の味がする）／smell（〜のにおいがする）\\n例）I feel sick.（気分が悪い）\\n例）That sounds good.（それはよさそうだ）\\n例）This soup tastes salty.（このスープは塩からい）\\n\\nこれらの動詞のうしろには形容詞を置く。副詞ではないので注意する。\\n\\n■ look と look like\\nうしろに名詞を置くときは like が要る。\\n例）He looks young.（形容詞）\\n例）He looks like a student.（名詞 → like が必要）\\n\\n⚠ 注意：You look happily. は誤り。happily は「幸せそうに」という副詞である。正しくは You look happy.（あなたは幸せそうに見える）。\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　My sister looks happily today.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"日本語で「幸せそうに見える」と「〜に」を付けて訳すので、副詞の happily がふさわしいと感じてしまう。look＝見える、という訳し方が副詞を呼びこんでしまう。\",\"correctAnswer\":\"My sister looks happy today.\",\"correctExplanation\":\"look はうしろに補語（C）をとる動詞で、C になるのは名詞か形容詞である。happily は副詞なので C にはなれない。My sister ＝ happy というイコールの関係を作るのだから、形容詞の happy を置く。\"},{\"question\":\"次の文の文型を答えなさい。　She became a famous singer.\",\"wrongAnswer\":\"第3文型（SVO）\",\"trapExplanation\":\"became のうしろに a famous singer という名詞のかたまりがあるので、目的語だと考えてしまう。名詞が来たら O、という覚え方をしていると必ず引っかかる。\",\"correctAnswer\":\"第2文型（SVC）\",\"correctExplanation\":\"She ＝ a famous singer というイコールの関係が成り立つので、a famous singer は補語（C）である。名詞であっても、主語とイコールになるなら C になる。「＝を書いて意味が通るか」で判断する。\"}]}",
"{\"id\":\"eigo_s068\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVC をつくる動詞：become・look・sound など\",\"description\":\"感覚を表す動詞のうしろに形容詞を置くきまりと、like の有無を整理する\",\"intro\":\"「このスープはおいしそうなにおいがする」を This soup smells deliciously. と書くと誤りです。smell のあとには形容詞が来るので good を使います。感覚を表す動詞のうしろは、副詞ではないのです。\",\"order\":568,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"感覚を表す動詞：look（見える）・sound（聞こえる）・taste（味がする）・smell（においがする）・feel（感じる）。\",\"これらのうしろには形容詞を置く（× smells deliciously）。\",\"うしろに名詞を置くときは like を入れる（look like a doctor）。\",\"become / get / turn は「〜になる」という変化を表す。\",\"This soup smells good. の good を well にしない。\"],\"sections\":[{\"heading\":\"感覚を表す動詞＋形容詞\",\"body\":\"五感（見る・聞く・味わう・においをかぐ・感じる）に関する動詞は、うしろに形容詞を置いて第2文型を作る。\\n\\n■ look（〜に見える）\\n例）You look tired.（つかれて見える）\\n例）The cake looks delicious.（そのケーキはおいしそうに見える）\\n\\n■ sound（〜に聞こえる）\\n例）That sounds interesting.（それはおもしろそうだ）\\n例）Your idea sounds good.\\n\\n■ taste（〜の味がする）\\n例）This soup tastes salty.（このスープは塩からい）\\n\\n■ smell（〜のにおいがする）\\n例）These flowers smell sweet.（この花はあまいにおいがする）\\n\\n■ feel（〜と感じる）\\n例）I feel sleepy.（ねむい）\\n例）This cloth feels soft.（この布はやわらかい手ざわりだ）\\n\\n★ ポイント：日本語では「おいしそうに」「あまく」と副詞のように訳すが、英語では形容詞を置く。× tastes deliciously ではなく ○ tastes delicious。\",\"figureId\":\"xf_eigo_s068\",\"mangaId\":\"eigo_s068_xm\"},{\"heading\":\"like が要るとき・要らないとき\",\"body\":\"これらの動詞のうしろに名詞を置きたいときは、like（〜のように）を入れる。\\n\\n■ 形容詞のとき → like は不要\\n例）He looks young.（彼は若く見える）\\n例）It sounds strange.（それは変に聞こえる）\\n\\n■ 名詞のとき → like が必要\\n例）He looks like a doctor.（彼は医者のように見える）\\n例）It sounds like a good idea.（それはよい考えのように聞こえる）\\n例）This tastes like chicken.（これはとり肉のような味がする）\\n\\n✗ He looks like tired.（tired は形容詞なので like は不要）\\n✗ He looks a doctor.（名詞なので like が必要）\\n\\n■ 「〜になる」を表す動詞\\nbecome（〜になる）：例）He became a pilot. / She became famous.\\nget（〜になる）：例）It got cold.（寒くなった）／ He got angry.\\nturn（色などが〜になる）：例）The leaves turn red in fall.（葉が秋に赤くなる）\\n\\nbecome は名詞も形容詞もうしろに置けるが、get は形容詞を置くのがふつうである。\\n\\n⚠ 注意：good（形容詞）と well（副詞）を混同しない。This soup smells good.（○）／ This soup smells well.（✗）。ただし He plays tennis well.（上手にテニスをする）は一般動詞を修飾するので well が正しい。\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　This soup smells deliciously.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「おいしそうなにおいがする」と日本語で「〜そうに」と訳すため、副詞の形がふさわしいと感じてしまう。動詞を説明する語は副詞、という規則を機械的にあてはめている。\",\"correctAnswer\":\"This soup smells delicious.（または smells good.）\",\"correctExplanation\":\"smell は第2文型をつくる動詞で、うしろには主語を説明する形容詞が来る。This soup ＝ delicious という関係である。副詞は動詞の様子（どのように）を説明する語なので、ここには置けない。\"},{\"question\":\"次の文の誤りを直しなさい。　My brother looks like tired today.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"look like ＝「〜のように見える」という熟語として丸ごと覚えているため、うしろが形容詞でも like を入れてしまう。日本語の訳がどちらも「〜のように見える」になるのも原因である。\",\"correctAnswer\":\"My brother looks tired today.\",\"correctExplanation\":\"like が必要なのは、うしろに名詞を置くときだけである。tired は形容詞なので like は要らない。名詞なら He looks like a teacher.、形容詞なら He looks tired.、と使い分ける。\"}]}",
"{\"id\":\"eigo_s069\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"第3文型 SVO：「〜を」にあたる目的語\",\"description\":\"目的語のはたらきと、S≠O という関係を第2文型と対比して確かめる\",\"intro\":\"I like dogs. の I と dogs はイコールになりません。ここが He is a doctor. との決定的なちがいです。動詞のすぐうしろに前置詞なしで名詞が来ていれば、それが目的語。英語でいちばん多い形です。\",\"order\":569,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"第3文型は〈S＋V＋O〉。O は動詞の動作を受けるもの。\",\"S＝O にはならない（I like dogs. で I ≠ dogs）。\",\"O になるのは名詞・代名詞（目的格）・不定詞・動名詞など。\",\"動詞のすぐうしろに前置詞なしで名詞が来ていれば O。\",\"英語で書くいちばん多い形なので、語順を体にしみこませる。\"],\"sections\":[{\"heading\":\"目的語とは何か\",\"body\":\"第3文型は、動詞の動作が及ぶ相手（目的語 O）が置かれる文である。英語の文でもっともよく使われる形である。\\n\\n■ 形\\nS＋V＋O（S≠O）\\n\\n例）I like dogs.（私は犬が好きです）\\n例）He plays the piano.（彼はピアノをひきます）\\n例）We study English.（私たちは英語を勉強します）\\n例）She has a nice bag.（彼女はすてきなかばんを持っています）\\n例）Tom knows my sister.（トムは私の姉を知っています）\\n\\n■ 第2文型とのちがい\\n第2文型　He is a doctor.（He ＝ a doctor）\\n第3文型　He knows a doctor.（He ≠ a doctor）\\n\\nどちらも動詞のうしろに名詞が来ているが、イコールになるかどうかがちがう。「＝を書いてみて意味が通るか」で見分ける。\\n\\n■ 前置詞があれば O ではない\\n例）I look at the picture.（at があるので the picture は O ではない）\\n例）I see the picture.（前置詞なし → the picture は O）\\n\\n★ ポイント：動詞のすぐうしろに前置詞なしで名詞が来ていて、しかも主語とイコールにならなければ、それが目的語である。\",\"figureId\":\"lf_eigoext02_069\",\"mangaId\":\"eigo_s069_xm\"},{\"heading\":\"目的語になるもの\",\"body\":\"目的語の位置には、名詞のほかにもいろいろな形が来る。\\n\\n■ 名詞\\n例）I want a new bike.\\n\\n■ 代名詞（目的格）\\n例）I know him.（× I know he.）\\n例）She helps us every day.\\n\\n■ 〈to＋動詞の原形〉＝「〜すること」\\n例）I want to play tennis.（私はテニスをしたい）\\n例）She likes to read books.（彼女は本を読むのが好きだ）\\n\\n■ 〈動詞の ing 形〉＝「〜すること」\\n例）He enjoys playing soccer.（彼はサッカーをするのを楽しむ）\\n例）I finished doing my homework.\\n\\n「〜すること」を表すかたまりも、まとめて一つの目的語と考える。文型としては SVO である。\\n\\n⚠ 注意：want のうしろは to＋原形、enjoy のうしろは ing 形と決まっている。× I want playing tennis. や × He enjoys to play soccer. は誤り。中学受験でも上位校ではここまで問われる。\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　My brother knows she very well.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「彼女」という日本語には形の変化がないので、she のまま置いてしまう。主語の位置で使う she を「彼女」の唯一の形だと思いこんでいることが原因である。\",\"correctAnswer\":\"My brother knows her very well.\",\"correctExplanation\":\"動詞のうしろ（目的語の位置）に来る代名詞は目的格になる。she → her、he → him、they → them、I → me、we → us。「動詞のうしろに来たら形がかわる」と確かめる手順を必ず入れる。\"},{\"question\":\"「私は音楽室に入ります。」を英語にしなさい。（the music room を使う）\",\"wrongAnswer\":\"I enter into the music room.\",\"trapExplanation\":\"日本語の「〜に入る」の「に」につられて、前置詞 into を入れてしまう。日本語の助詞と英語の前置詞を一対一で対応させようとするのが原因である。\",\"correctAnswer\":\"I enter the music room.\",\"correctExplanation\":\"enter は前置詞なしで目的語をとる動詞なので、into は要らない。同じ仲間に reach（〜に着く）、visit（〜を訪れる）がある。逆に arrive は arrive at 〜、listen は listen to 〜 と前置詞が要る。動詞ごとに形で覚える。\"}]}",
"{\"id\":\"eigo_s070\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"目的語になる代名詞：目的格の形\",\"description\":\"代名詞が主語のときと目的語のときで形が変わることを整理する\",\"intro\":\"I like she. と書いてしまうのは、日本語の「彼女が好き」に引かれるからかもしれません。英語では、動詞のうしろに来た瞬間に her に変わります。同じ人でも位置で形が変わる、という感覚をつかみましょう。\",\"order\":570,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"主格→目的格：I→me、you→you、he→him、she→her、it→it、we→us、they→them。\",\"動詞のうしろ、前置詞のうしろでは目的格を使う。\",\"with me / for us / to him のように、前置詞のあとも目的格。\",\"you と it は主格と目的格が同じ形。\",\"「私の」を表す my / our などとは別の形なので混同しない。\"],\"sections\":[{\"heading\":\"形が変わる場所\",\"mangaId\":\"eigo_s070_manga\",\"body\":\"代名詞は、文の中でどの位置に置かれるかによって形が変わる。\\n\\n■ 主格（主語になる形）\\nI / you / he / she / it / we / they\\n\\n■ 目的格（目的語になる形）\\nme / you / him / her / it / us / them\\n\\n■ 目的格を使う場所は二つ\\n①動詞のうしろ（目的語）\\n例）I like him.（私は彼が好きです）\\n例）She helps us.（彼女は私たちを助けてくれます）\\n例）Do you know them?（彼らを知っていますか）\\n\\n②前置詞のうしろ\\n例）Come with me.（私といっしょに来て）\\n例）This present is for her.（このプレゼントは彼女のためのものです）\\n例）Look at it.（それを見て）\\n例）Between you and me（あなたと私の間で）\\n\\n■ 同じ形のもの\\nyou と it は、主格でも目的格でも形が変わらない。\\n\\n例）You know me. / I know you.\\n例）It is easy. / I like it.\\n\\n★ ポイント：主語なら主格、動詞や前置詞のうしろなら目的格。「置かれた場所」で決まる。\",\"figureId\":\"xf_eigo_s070\"},{\"heading\":\"「〜の」を表す形と区別する\",\"body\":\"代名詞にはもう一つ「〜の」を表す形（所有格）があり、三つを混同しないことが大切である。\\n\\n■ 三つの形\\n私　　I（私は）／my（私の）／me（私を・私に）\\nあなた　you／your／you\\n彼　　he／his／him\\n彼女　she／her／her\\nそれ　it／its／it\\n私たち　we／our／us\\n彼ら　they／their／them\\n\\n■ 使い分けの例\\n例）I like her.（私は彼女が好きです）＝目的格\\n例）This is her bag.（これは彼女のかばんです）＝所有格\\nher は目的格と所有格が同じ形なので、うしろに名詞があるかどうかで見分ける。\\n\\n例）He is my friend.（所有格 my ＋ 名詞 friend）\\n例）He knows me.（目的格 me、うしろに名詞はない）\\n\\n■ よくある誤り\\n✗ Please help I.　　○ Please help me.\\n✗ This is a picture of we.　○ This is a picture of us.\\n✗ Give it to she.　　○ Give it to her.\\n\\n⚠ 注意：前置詞（of / to / for / with / at）のうしろは必ず目的格。ここは書き取り問題で頻出である。\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　Please come to the party with I.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「私と」という日本語をそのまま with I にしてしまう。I ＝ 私、という覚え方しかしていないと、前置詞のうしろで形が変わることに気づけない。\",\"correctAnswer\":\"Please come to the party with me.\",\"correctExplanation\":\"前置詞（with / to / for / of / at など）のうしろに来る代名詞は目的格になるので、I ではなく me を使う。同じく for us、to him、of them となる。「前置詞のうしろは目的格」と一つの規則で覚える。\"},{\"question\":\"次の文の誤りを直しなさい。　I like tennis. My brother likes it, too. He plays it with he friends.\",\"wrongAnswer\":\"He plays it with he friends.\",\"trapExplanation\":\"前置詞のうしろだから目的格、と覚えた直後に、うしろに名詞 friends があることを見落として him や he を置いてしまう。ここで必要なのは「彼の」を表す所有格である。\",\"correctAnswer\":\"He plays it with his friends.\",\"correctExplanation\":\"friends という名詞が続いているので、必要なのは「彼の」を表す所有格 his である。前置詞のうしろがすぐ代名詞なら目的格（with him）、うしろに名詞が続くなら所有格（with his friends）と、うしろを見て判断する。\"}]}",
"{\"id\":\"eigo_s071\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自動詞と他動詞：前置詞が要るか要らないか\",\"description\":\"目的語を直接とる動詞と、前置詞を必要とする動詞を区別して覚える\",\"intro\":\"「〜を訪ねる」は visit Kyoto と前置詞なしなのに、「〜を聞く」は listen to music と to が要ります。日本語ではどちらも「を」なので、助詞から判断すると必ず外れます。動詞ごとに覚えるしかありません。\",\"order\":571,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"他動詞＝目的語を直接とる動詞（前置詞なし）。自動詞＝目的語をとらない動詞。\",\"前置詞が要るもの：listen to／look at／arrive at／wait for／go to。\",\"前置詞が要らないもの：enter／reach／visit／discuss／marry。\",\"日本語の助詞（を・に）から判断してはいけない。\",\"同じ動詞が自動詞にも他動詞にもなることがある（run など）。\"],\"sections\":[{\"heading\":\"二つの種類\",\"body\":\"動詞は、目的語を直接とれるかどうかで二つに分かれる。\\n\\n■ 他動詞＝目的語を直接とる（前置詞なし）\\n例）I like music.／He knows my name.／We study English.\\n\\n■ 自動詞＝目的語をとらない（あとに続けるなら前置詞が要る）\\n例）I go to school.／He arrived at the station.／We walked in the park.\\n\\n■ 前置詞が必要な代表例\\nlisten to 〜（〜を聞く）\\n例）I listen to music every day.（× I listen music）\\n\\nlook at 〜（〜を見る）\\n例）Look at that bird.（× Look that bird）\\n\\narrive at / in 〜（〜に着く）\\n例）We arrived at the airport.\\n\\nwait for 〜（〜を待つ）\\n例）I waited for him for an hour.\\n\\ngo to 〜（〜へ行く）\\n例）She goes to school by bike.\\n\\n★ ポイント：日本語では「音楽を聞く」「鳥を見る」と「を」が付くのに、英語では前置詞が要る。日本語の助詞は手がかりにならない。\"},{\"heading\":\"前置詞が要らない動詞\",\"body\":\"逆に、日本語では「〜に」と訳すのに、英語では前置詞なしで目的語をとる動詞がある。\\n\\n■ enter（〜に入る）\\n例）He entered the room.（× entered into the room）\\n\\n■ reach（〜に着く）\\n例）We reached the top of the mountain.（× reached to）\\n\\n■ visit（〜を訪れる）\\n例）I visited my grandmother.（× visited to）\\n\\n■ discuss（〜について話し合う）\\n例）We discussed the problem.（× discussed about）\\n\\n■ marry（〜と結婚する）\\n例）He married her.（× married with）\\n\\nこれらは中学受験の上位校でも問われることがある。「前置詞を入れたくなるが入れない動詞」としてまとめて覚える。\\n\\n■ 同じ動詞が両方になることも\\nrun（走る＝自動詞）：He runs fast.\\nrun（経営する＝他動詞）：He runs a restaurant.（彼はレストランを経営している）\\n\\n■ よく似た組み合わせ\\nlisten to（意識して聞く）／hear（自然に聞こえる、前置詞なし）\\n例）I listened to the radio. / I heard a strange sound.\\nlook at（意識して見る）／see（自然に見える、前置詞なし）\\n例）Look at the board. / I can see the sea from my room.\\n\\n⚠ 注意：listen・look は前置詞が要り、hear・see は要らない。二組をセットで覚えると混同しない。\"},{\"heading\":\"なぜ日本語の「を」は手がかりにならないのか\",\"mangaId\":\"eigo_s071_manga\",\"body\":\"英語の動詞には、目的語を**直接**うしろに置ける動詞（他動詞）と、置けない動詞（自動詞）があります。listen や look は自動詞で、「何を」を続けるには to や at という前置詞の橋が要ります。visit や enter は他動詞で、橋なしで直接続けます。この区別は**英語の動詞ごとに決まっていて、日本語の訳とは関係がありません**。「音楽を聞く」も「京都を訪ねる」も日本語では同じ「を」ですが、英語では listen to music と visit Kyoto です。だから助詞で判断すると必ず外れ、動詞ごとに覚えるしかありません。\\n\\n同じ「聞く・見る」でも、listen to／look at は意識して聞く・見る、hear／see は自然に聞こえる・見える、という意味のちがいがあり、前置詞の有無も対になっています。二組をセットで覚えると混同しません。\\n\\n■ 確かめのしかた\\n①**前置詞が要る動詞**を言えるか：listen to／look at／arrive at（in）／wait for／go to。\\n②**前置詞を入れたくなるが入れない動詞**を言えるか：enter／reach／visit／discuss／marry。× enter into、× reach to、× discuss about。\\n③文を書いたら、動詞のうしろを見る。I listen music→listen は自動詞→to が要る。We arrived the station→arrive は自動詞→at が要る。\\n④対で確かめる：listen to／hear、look at／see。run は自動詞（走る）にも他動詞（経営する）にもなる。\\n\\n★ ここがポイント：目的語を直接置けるかは**英語の動詞ごとに決まっていて、日本語の「を・に」とは無関係**。前置詞が要る動詞（listen to・look at・arrive at・wait for）と要らない動詞（enter・reach・visit・discuss・marry）を、対（listen to／hear）で覚える。\",\"figureId\":\"xf_eigo_s071\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　I listen music every morning.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「音楽を聞く」と日本語では「を」が付くので、目的語をそのまま置けば足りると考えてしまう。同じ「聞く」でも hear は前置詞が要らないため、いっそう混乱しやすい。\",\"correctAnswer\":\"I listen to music every morning.\",\"correctExplanation\":\"listen は自動詞なので、うしろに「何を」を続けるには前置詞 to が要る。同じ仲間に look at、wait for、arrive at がある。一方 hear と see は他動詞なので前置詞は不要（I hear a sound.）。二組を対にして覚える。\"},{\"question\":\"次の文の誤りを直しなさい。　We arrived the station at seven.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"reach（〜に着く）が前置詞なしで使えることを覚えていると、同じ意味の arrive も同じように使えると考えてしまう。日本語の訳が同じなので区別しにくい。\",\"correctAnswer\":\"We arrived at the station at seven.\",\"correctExplanation\":\"arrive は自動詞なので、場所を続けるときは at（せまい場所）や in（広い場所）が要る。同じ意味でも reach は他動詞で We reached the station. と前置詞なしになる。訳ではなく動詞ごとの形で覚える。\"}]}",
"{\"id\":\"eigo_s072\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVC と SVO の見分け方\",\"description\":\"同じ動詞が二つの文型をつくる場合を、イコールの関係で判断する\",\"intro\":\"He got angry.（怒った）と He got a letter.（手紙を受け取った）。同じ got なのに文型がちがいます。訳し方で悩むと迷路に入ります。判断はただ一つ、主語とうしろの語がイコールになるかどうかです。\",\"order\":572,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"見分けの鍵はただ一つ、S＝あとの語 が成り立つかどうか。\",\"成り立てば SVC、成り立たなければ SVO。\",\"get・feel・look・turn は、どちらの文型もつくる。\",\"He got angry.（SVC）／He got a letter.（SVO）\",\"訳し方ではなく、イコールの関係で判断する。\"],\"sections\":[{\"heading\":\"「＝」を書いて確かめる\",\"body\":\"第2文型（SVC）と第3文型（SVO）は、どちらも〈主語＋動詞＋語句〉という同じ並びに見える。ちがいはただ一つ、主語とうしろの語がイコールになるかどうかである。\\n\\n■ 手順\\n①動詞のうしろの語を見つける\\n②主語との間に「＝」を書いてみる\\n③意味が通れば SVC、通らなければ SVO\\n\\n例）He is a doctor.\\nHe ＝ a doctor（○）→ SVC\\n\\n例）He knows a doctor.\\nHe ＝ a doctor（✗ 彼は医者そのものではない）→ SVO\\n\\n例）She became a nurse.\\nShe ＝ a nurse（○）→ SVC\\n\\n例）She met a nurse.\\nShe ＝ a nurse（✗）→ SVO\\n\\n★ ポイント：うしろに来るのが名詞か形容詞かでは決まらない。名詞でもイコールなら C になる。必ず「＝」を書いて確かめる。\",\"figureId\":\"xf_eigo_s072\",\"mangaId\":\"eigo_s072_xm\"},{\"heading\":\"両方の文型をつくる動詞\",\"body\":\"同じ動詞が、使い方によって SVC にも SVO にもなる。\\n\\n■ get\\nHe got angry.（彼は怒った）→ He ＝ angry → SVC\\nHe got a letter.（彼は手紙を受け取った）→ He ≠ a letter → SVO\\n\\n■ feel\\nI feel sick.（気分が悪い）→ I ＝ sick → SVC\\nI feel a cold wind.（冷たい風を感じる）→ I ≠ a cold wind → SVO\\n\\n■ look\\nHe looks young.（若く見える）→ SVC\\nHe looked at the picture.（絵を見た）→ at があるので O ではなく、文型としては SV\\n\\n■ turn\\nThe leaves turn red.（葉が赤くなる）→ SVC\\nHe turned the key.（かぎを回した）→ SVO\\n\\n■ run\\nHe runs fast.（速く走る）→ SV\\nHe runs a shop.（店を経営する）→ SVO\\n\\n⚠ 注意：動詞の意味を一つだけ覚えていると、文型の判断をまちがえる。文全体を読んで、主語とうしろの語がイコールかどうかを毎回確かめる習慣をつける。\"}],\"trapExamples\":[{\"question\":\"次の文の文型を答えなさい。　My father got angry yesterday.\",\"wrongAnswer\":\"第3文型（SVO）\",\"trapExplanation\":\"get は「〜を得る」という他動詞として覚えているので、うしろの語を自動的に目的語だと考えてしまう。「怒った」という訳からは、イコールの関係が意識されにくい。\",\"correctAnswer\":\"第2文型（SVC）\",\"correctExplanation\":\"My father ＝ angry というイコールの関係が成り立つので、angry は補語（C）である。get は「〜になる」の意味では SVC をつくる。He got a letter. のように主語とイコールにならない語が続けば SVO になる。\"},{\"question\":\"次の文の文型を答えなさい。　I felt a cold wind on my face.\",\"wrongAnswer\":\"第2文型（SVC）\",\"trapExplanation\":\"feel は I feel sick. のように第2文型で使う動詞だと覚えているので、うしろの語をつねに補語だと考えてしまう。感覚を表す動詞＝SVC という思いこみが原因である。\",\"correctAnswer\":\"第3文型（SVO）\",\"correctExplanation\":\"I ＝ a cold wind とはならないので、a cold wind は目的語（O）である。on my face は修飾語なので数えない。同じ動詞でも、うしろの語と主語がイコールになるかどうかで文型が変わる。必ず「＝」を書いて確かめる。\"}]}",
"{\"id\":\"eigo_s073\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"第4文型 SVOO：「人に」「ものを」の順\",\"description\":\"目的語を二つとる文の語順と、二つの O の関係を確かめる\",\"intro\":\"He gave a book me. と書くと通じません。英語では「人に」が先、「ものを」が後ろです。日本語なら「私に本を」も「本を私に」も自然ですが、英語は順番が決まっています。なぜその順なのかを見ていきます。\",\"order\":573,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"第4文型は〈S＋V＋O1（人）＋O2（もの）〉。「人に」「ものを」の順。\",\"二つの O はイコールにならない（me ≠ a book）。\",\"代表的な動詞：give・tell・show・teach・send・buy・make・cook・ask。\",\"順番を入れかえると意味が通らなくなる（× He gave a book me.）。\",\"人が代名詞のときも、その位置は変わらない（give me a book）。\"],\"sections\":[{\"heading\":\"目的語が二つある文\",\"body\":\"動詞のうしろに「だれに」「何を」の二つを続ける文を第4文型という。\\n\\n■ 形\\nS＋V＋O1（人）＋O2（もの）\\n\\n例）He gave me a book.（彼は私に本をくれた）\\n例）She teaches us English.（彼女は私たちに英語を教える）\\n例）My father bought me a bike.（父は私に自転車を買ってくれた）\\n例）Please show me your notebook.（ノートを見せてください）\\n例）I sent her a birthday card.（私は彼女に誕生日カードを送った）\\n\\n■ 順番は「人 → もの」\\n英語では、先に「だれに」、あとに「何を」を置く。\\n\\n✗ He gave a book me.\\n○ He gave me a book.\\n\\n日本語では「私に本を」も「本を私に」も言えるが、英語ではこの語順が決まっている。\\n\\n■ 二つの O はイコールにならない\\nme ≠ a book である。ここが第5文型（O＝C）との大きなちがいになる。\\n\\n★ ポイント：第4文型は「〜に…を」と二つの助詞が出てくる文だ、と日本語から見当をつけ、英語では〈人→もの〉の順に置く。\",\"figureId\":\"lf_eigoext02_073\"},{\"heading\":\"SVOO をつくる動詞\",\"body\":\"第4文型が作れる動詞は限られている。よく出るものをまとめて覚える。\\n\\n■ 「与える」仲間\\ngive（与える）／send（送る）／show（見せる）／teach（教える）／tell（話す）／lend（貸す）／pass（手わたす）／write（書き送る）\\n\\n例）I'll show you my album.（アルバムを見せましょう）\\n例）Please pass me the salt.（塩を取ってください）\\n例）Tell me the truth.（本当のことを話して）\\n\\n■ 「作る・手に入れる」仲間\\nbuy（買う）／make（作る）／cook（料理する）／get（取ってくる）／find（見つけてやる）\\n\\n例）My mother made me a cake.（母は私にケーキを作ってくれた）\\n例）He cooked us dinner.（彼は私たちに夕食を作ってくれた）\\n\\n■ ask（たずねる）\\n例）May I ask you a question?（質問してもよいですか）\\n\\n■ 使えない動詞に注意\\nsay は SVOO を作れない。\\n✗ He said me the truth.\\n○ He told me the truth.（tell を使う）\\n○ He said to me, \\\"Come here.\\\"（say は to が要る）\\n\\n⚠ 注意：say と tell の使い分けは頻出である。「人に」を直接続けられるのは tell、say は say to 〜 の形になる。\"},{\"heading\":\"なぜ「人」が先で「もの」があとなのか\",\"mangaId\":\"eigo_s073_manga\",\"body\":\"He gave me a book. のように動詞のうしろに二つの目的語を並べるとき、英語では**受け取る人を先、わたすものをあと**に置きます。give・tell・show・teach は「相手に向かって何かをわたす」動作なので、まず相手（だれに）を言い、次に中身（何を）を言う順が自然だからです。「もの」を先に言いたいときは、He gave a book to me. のように前置詞 to で「相手」を示す必要があります。前置詞なしで並べるなら、必ず人が先です。日本語は「私に本を」も「本を私に」も言えるので、この順番を知らないと入れかえてしまいます。\\n\\n第4文型を作れる動詞が限られているのは、「人に・ものを」という**わたす動作**の動詞だけがこの形をとるからです。say は「言葉を発する」動作で相手を直接とれないので、He said me 〜 とは言えず、相手を直接とれる tell を使います（He told me the truth.）。say を使うなら say to me の形です。\\n\\n■ 確かめのしかた\\n①動詞のうしろに二つの語を並べたら、**人→もの**の順か。He gave a book me. は×。\\n②二つの目的語が**イコールでない**ことを確かめる（me≠a book）。イコールなら第5文型（SVOC）。\\n③第4文型を作れる動詞か：give・send・show・teach・tell・lend・pass・buy・make・cook・get・ask。**say は不可**→tell に直す。\\n④「もの」を先にしたいときは前置詞を付ける：He gave a nice present to me.\\n\\n★ ここがポイント：第4文型は**わたす動作**の動詞で、**受け取る人が先、ものがあと**。ものを先にするなら to が要る。二つの O はイコールにならず、**say は使えない（tell を使う）**。\"}],\"trapExamples\":[{\"question\":\"「彼は私にすてきなプレゼントをくれました。」を英語にしなさい。（a nice present を使う）\",\"wrongAnswer\":\"He gave a nice present me.\",\"trapExplanation\":\"日本語の「すてきなプレゼントを 私に」という順でも自然に言えるため、英語でも入れかえられると考えてしまう。「何を」を先に思いうかべてしまうのも原因である。\",\"correctAnswer\":\"He gave me a nice present.\",\"correctExplanation\":\"第4文型は〈動詞＋人＋もの〉の順が決まっている。もし「もの」を先に置きたいときは前置詞が必要で、He gave a nice present to me. としなければならない。前置詞なしで並べるときは必ず人が先である。\"},{\"question\":\"次の文の誤りを直しなさい。　My grandmother said me an interesting story.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"say も tell も「言う・話す」と訳すので、どちらでも同じように使えると考えてしまう。日本語の訳が同じであることが、そのまま誤りの原因になっている。\",\"correctAnswer\":\"My grandmother told me an interesting story.\",\"correctExplanation\":\"say は〈人＋もの〉の形をとれない動詞なので、「人に…を話す」と言うときは tell を使う。say を使うなら She said to me, \\\"...\\\" のように to が要る。tell me / tell us と、人を直接続けられるのは tell だと覚える。\"}]}",
"{\"id\":\"eigo_s074\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVOO の書きかえ①：to を使う動詞\",\"description\":\"give型の動詞を〈もの＋to＋人〉の形に書きかえる手順を身につける\",\"intro\":\"He gave me a book. は He gave a book to me. とも言えます。同じ意味なのに形が2つあるのはなぜでしょう。しかも to を使える動詞と使えない動詞があります。まずは「相手にわたす」型からです。\",\"order\":574,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"〈V＋人＋もの〉→〈V＋もの＋to＋人〉に書きかえられる。\",\"to を使う動詞：give・tell・show・teach・send・lend・pass・write。\",\"書きかえると第4文型（SVOO）から第3文型（SVO）になる。\",\"「相手にわたす・届ける」意味の動詞は to をとる、と考えるとよい。\",\"「もの」が it などの代名詞のときは、to を使う形にする（give it to me）。\"],\"sections\":[{\"heading\":\"二つの言い方\",\"mangaId\":\"eigo_s074_manga\",\"body\":\"第4文型の文は、前置詞を使って言いかえることができる。give の仲間は to を使う。\\n\\n■ 書きかえの形\\nS＋V＋人＋もの\\n→ S＋V＋もの＋to＋人\\n\\n例）He gave me a book.\\n→ He gave a book to me.（彼は私に本をくれた）\\n\\n例）She showed us her album.\\n→ She showed her album to us.\\n\\n例）I sent him an e-mail.\\n→ I sent an e-mail to him.\\n\\n例）Mr. Sato teaches us English.\\n→ Mr. Sato teaches English to us.\\n\\n例）Please pass me the salt.\\n→ Please pass the salt to me.\\n\\n■ to を使う動詞\\ngive（与える）／tell（話す）／show（見せる）／teach（教える）／send（送る）／lend（貸す）／pass（手わたす）／write（書き送る）／sell（売る）\\n\\nいずれも「相手にわたす・届ける」という意味を持つ。届く先を示すのが to である。\\n\\n★ ポイント：書きかえると目的語は一つになるので、文型は第4文型（SVOO）から第3文型（SVO）に変わる。to me の部分は修飾語になる。\",\"figureId\":\"lf_eigoext02_074\"},{\"heading\":\"書きかえの手順と注意\",\"body\":\"■ 手順\\n①〈人〉と〈もの〉を見つける\\n②〈もの〉を動詞のすぐうしろに移す\\n③〈人〉の前に to を付けて、いちばんうしろに置く\\n\\nHe gave me a book.\\n　　　　　人  もの\\n→ He gave a book to me.\\n\\n■ 人が代名詞でも同じ\\n例）I told her the news. → I told the news to her.\\nher はそのままの形（目的格）で使う。\\n\\n■ 「もの」が代名詞のとき\\n「もの」が it / them のような代名詞のときは、前置詞を使う形にするのがふつうである。\\n\\n例）He gave it to me.（彼はそれを私にくれた）\\n△ He gave me it.（ふつうこの言い方はしない）\\n\\nこれは、代名詞は聞き手がすでに知っているものを指すので、文の中で目立たない位置に置きたいからである。\\n\\n■ 意味は同じでも、伝わり方は少しちがう\\nHe gave me a book.（何をあげたかに重点）\\nHe gave a book to me.（だれにあげたかに重点）\\n入試ではどちらも正解になるが、書きかえよと指定されたら指示どおりの形にする。\\n\\n⚠ 注意：to を for にしてはいけない。give / tell / show / teach / send はすべて to である。\"}],\"trapExamples\":[{\"question\":\"次の文を、ほぼ同じ意味になるように書きかえなさい。　My aunt sent me a nice present.\",\"wrongAnswer\":\"My aunt sent a nice present for me.\",\"trapExplanation\":\"「私のために送ってくれた」と考えると for がふさわしく感じられる。for が「〜のために」という親切さを表すことを知っているために、かえって選んでしまう。\",\"correctAnswer\":\"My aunt sent a nice present to me.\",\"correctExplanation\":\"send は「相手に届ける」意味の動詞なので、書きかえには to を使う。to をとるのは give・tell・show・teach・send・lend・pass などである。for をとるのは buy・make・cook のような「作ってあげる」仲間で、別のまとまりで扱う。\"},{\"question\":\"「彼はそれを私にくれました。」を英語にしなさい。（it を使う）\",\"wrongAnswer\":\"He gave me it.\",\"trapExplanation\":\"〈give＋人＋もの〉の形を覚えているので、ものが代名詞でもそのまま当てはめてしまう。文法の形だけを見れば正しそうに見えるので、まちがいだと気づきにくい。\",\"correctAnswer\":\"He gave it to me.\",\"correctExplanation\":\"「もの」が it や them のような代名詞のときは、〈V＋もの＋to＋人〉の形にするのがふつうである。He gave me it. は英語として不自然になる。代名詞が出てきたら to を使う形、と覚えておく。\"}]}",
"{\"id\":\"eigo_s075\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVOO の書きかえ②：for を使う動詞\",\"description\":\"buy型の動詞が for をとることを、to型との対比で確実にする\",\"intro\":\"My mother made me a cake. を書きかえると、to ではなく for を使います。相手にわたすのではなく、相手のために作るからです。to 型と for 型は動詞ごとに決まっていて、訳し方では決まりません。\",\"order\":575,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"for を使う動詞：buy・make・cook・get・find・choose・sing。\",\"「相手のために作る・手に入れる」意味の動詞は for をとる。\",\"「相手にわたす・届ける」意味の動詞は to をとる（give型）。\",\"書きかえの形は〈V＋もの＋for＋人〉。\",\"to型か for型かは動詞ごとに覚える。訳し方では決まらない。\"],\"sections\":[{\"heading\":\"for をとる動詞\",\"body\":\"第4文型の書きかえで for を使う動詞がある。「相手のために作る・手に入れる」意味の仲間である。\\n\\n■ 書きかえの形\\nS＋V＋人＋もの\\n→ S＋V＋もの＋for＋人\\n\\n例）My mother made me a cake.\\n→ My mother made a cake for me.（母は私にケーキを作ってくれた）\\n\\n例）He bought his sister a doll.\\n→ He bought a doll for his sister.\\n\\n例）She cooked us dinner.\\n→ She cooked dinner for us.\\n\\n例）Will you get me a glass of water?\\n→ Will you get a glass of water for me?\\n\\n■ for を使う動詞\\nbuy（買う）／make（作る）／cook（料理する）／get（取ってくる）／find（見つけてやる）／choose（選ぶ）／sing（歌ってやる）／play（演奏してやる）\\n\\n■ to と for のちがい\\nto　… 相手にわたす・届く先を示す（give / send / tell / show / teach）\\nfor … 相手のために何かをする（buy / make / cook / get）\\n\\ngive の場合、相手がその場にいなければわたせない。一方 buy や make は、相手がいなくてもできる。この差が to と for の使い分けにつながっている。\\n\\n★ ポイント：「わたす系は to、作る系は for」と分けて覚え、動詞ごとにどちらかを暗記する。\",\"figureId\":\"lf_eigoext02_075\",\"mangaId\":\"eigo_s075_xm\"},{\"heading\":\"覚え方とまぎらわしい例\",\"body\":\"■ 動詞の分類表\\nto をとる　give / send / show / teach / tell / lend / pass / write / sell\\nfor をとる　buy / make / cook / get / find / choose / sing\\n\\n数の少ない for 型（buy・make・cook・get・find）を丸ごと覚え、残りは to、と決めてしまうのが効率がよい。\\n\\n■ まぎらわしいもの\\n①make\\n「作ってあげる」は for。\\n例）She made me a doll. → She made a doll for me.\\n※ make には第5文型の使い方（make me happy）もあるので混同しない。\\n\\n②get\\n「取ってきてあげる」は for。\\n例）Get me some water. → Get some water for me.\\n\\n③ask は of を使う\\n例）He asked me a question. → He asked a question of me.\\nask だけは to でも for でもないので、注意が必要である。入試では「ask は特別」とだけ覚えておけばよい。\\n\\n⚠ 注意：書きかえの問題では、動詞を見た瞬間に to か for かを決められるようにしておく。訳から考えると「〜のために」がどちらにも当てはまってしまい、判断できない。\"}],\"trapExamples\":[{\"question\":\"次の文を、ほぼ同じ意味になるように書きかえなさい。　My father bought me a new bike.\",\"wrongAnswer\":\"My father bought a new bike to me.\",\"trapExplanation\":\"give の書きかえで to を使う練習を先に多くするので、書きかえといえば to だと手が覚えてしまう。「私に買ってくれた」という訳からも、届け先を表す to がふさわしく感じられる。\",\"correctAnswer\":\"My father bought a new bike for me.\",\"correctExplanation\":\"buy は「相手のために買う」意味なので for をとる。for 型は buy・make・cook・get・find が中心で、数が少ないのでまとめて覚えるとよい。それ以外の give・send・show・teach・tell はすべて to である。\"},{\"question\":\"次の文を、ほぼ同じ意味になるように書きかえなさい。　Ms. Green teaches us English.\",\"wrongAnswer\":\"Ms. Green teaches English for us.\",\"trapExplanation\":\"「私たちのために教えてくれる」と考えると for が自然に思える。for 型を覚えた直後は、今度はすべてを for にしてしまうという逆の誤りが起こりやすい。\",\"correctAnswer\":\"Ms. Green teaches English to us.\",\"correctExplanation\":\"teach は「相手に知識をわたす」意味の動詞なので to をとる。give・send・show・tell と同じ仲間である。書きかえの前に、その動詞が to 型か for 型かを思い出す、という手順を必ずはさむ。\"}]}",
"{\"id\":\"eigo_s076\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVOO の否定文・疑問文と、たずね方\",\"description\":\"第4文型の文を否定・疑問にする形と、What / Who でたずねる形を練習する\",\"intro\":\"Does he gives you a present? と書いてしまうのは、目的語が2つあって文が長くなり、動詞を原形にもどすのを忘れるからです。「だれに」をたずねると、文末に to がぽつんと残る形も出てきます。\",\"order\":576,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"否定文・疑問文の作り方は、ふつうの一般動詞の文と同じ。\",\"Does he give you 〜? のように、does のうしろの動詞は原形。\",\"「何を」をたずねるときは What does he give you? の語順。\",\"「だれに」をたずねるときは Who does he give it to? のように to が文末に残る。\",\"give / show / tell は、人が代名詞でもその位置は変わらない。\"],\"sections\":[{\"heading\":\"否定文と疑問文\",\"body\":\"第4文型でも、否定文・疑問文の作り方は変わらない。一般動詞の文と同じ規則にしたがう。\\n\\n■ 否定文\\n例）He gives me a present. → He doesn't give me a present.\\n例）They tell us the truth. → They don't tell us the truth.\\n\\ndoesn't / don't のうしろは原形なので、gives → give に戻る。\\n\\n■ 疑問文\\n例）He gives you a present. → Does he give you a present?\\n　　－ Yes, he does. / No, he doesn't.\\n例）They teach you math. → Do they teach you math?\\n\\n■ 人の位置は変わらない\\n疑問文にしても〈動詞＋人＋もの〉の順は変わらない。\\n\\n○ Does your mother make you lunch?\\n✗ Does your mother make lunch you?\\n\\n■ 命令文\\n例）Please show me your ticket.（切符を見せてください）\\n例）Don't tell him my secret.（彼に私の秘密を言わないで）\\n\\n★ ポイント：文型が変わっても、否定文・疑問文の作り方の規則は変わらない。動詞が一般動詞なら do / does を使う、という土台は同じである。\",\"figureId\":\"xf_eigo_s076\",\"mangaId\":\"eigo_s076_xm\"},{\"heading\":\"疑問詞でたずねる\",\"body\":\"第4文型の一部をたずねる文も作れる。\\n\\n■ 「何を」をたずねる（もの＝O2 をたずねる）\\nHe gives you a present. の a present をたずねる。\\n→ What does he give you?（彼はあなたに何をくれますか）\\n答え）He gives me a present.\\n\\n■ 「だれに」をたずねる（人＝O1 をたずねる）\\n書きかえた形をもとにして、前置詞を文の終わりに残す言い方が使われる。\\n→ Who does he give it to?（彼はそれをだれにあげますか）\\n答え）He gives it to me.\\n\\n■ 「だれが」をたずねる\\nWho gives you a present?（だれがあなたにプレゼントをくれますか）\\nwho が主語なので do / does は使わず、動詞に -s を付ける。\\n\\n■ よく出る形\\nWhat do you call this in English?（これを英語で何と言いますか）\\n※ これは第5文型（call＋O＋C）の疑問文で、次のまとまりで扱う。\\n\\n⚠ 注意：What does he give you? の does のうしろは原形 give である。gives と書いてしまう誤りが非常に多いので、書いたあとに必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"次の文を疑問文にしなさい。　Your mother makes you lunch every day.\",\"wrongAnswer\":\"Does your mother makes you lunch every day?\",\"trapExplanation\":\"もとの文の makes をそのまま写してしまう。目的語が二つあって文が長いため、動詞を原形に戻すという基本の確認がぬけ落ちやすい。\",\"correctAnswer\":\"Does your mother make you lunch every day?\",\"correctExplanation\":\"Does を使ったら、うしろの動詞は必ず原形に戻す（makes → make）。目的語が二つある文でも、否定文・疑問文の作り方は一般動詞の文とまったく同じである。文が長いときほど、動詞の形を最後に確かめる。\"},{\"question\":\"「彼はあなたに何をくれますか。」を英語にしなさい。\",\"wrongAnswer\":\"What does he gives you?\",\"trapExplanation\":\"主語 he が三人称単数であることが目に入るため、動詞に -s を付けてしまう。疑問詞が文の先頭にあると、does の存在が意識から外れやすいのも原因である。\",\"correctAnswer\":\"What does he give you?\",\"correctExplanation\":\"疑問詞が付いても〈does＋主語＋動詞の原形〉という並びは変わらないので、give のままでよい。三人称単数であることは does がすでに示している。「do / does のうしろは原形」という規則をここでも使う。\"}]}",
"{\"id\":\"eigo_s077\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"第5文型 SVOC：目的語とイコールになる語\",\"description\":\"目的語のあとに、その目的語を説明する補語が来る文の形をつかむ\",\"intro\":\"We call him Ken. の him と Ken は同じ人です。これが He gave me a book.（me と a book は別もの）とのちがいです。目的語のあとに、その目的語を説明する語が来る形をここで学びます。\",\"order\":577,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"第5文型は〈S＋V＋O＋C〉。O＝C の関係が成り立つ。\",\"C になるのは名詞と形容詞。副詞は C になれない。\",\"代表的な動詞：call・name・make・keep・find・leave。\",\"語順は〈O → C〉。入れかえると意味が変わる。\",\"第4文型（O1≠O2）とのちがいは、イコールになるかどうか。\"],\"sections\":[{\"heading\":\"O＝C の関係\",\"body\":\"第5文型は、目的語のうしろに「その目的語がどうであるか」を説明する語（補語 C）が来る文である。\\n\\n■ 形\\nS＋V＋O＋C（O＝C）\\n\\n例）We call him Ken.（私たちは彼をケンと呼ぶ）\\n　　him ＝ Ken\\n\\n例）The news made me happy.（その知らせは私を幸せにした）\\n　　me ＝ happy\\n\\n例）Please keep the door open.（ドアを開けたままにしておいて）\\n　　the door ＝ open\\n\\n例）I found the book interesting.（その本はおもしろいと分かった）\\n　　the book ＝ interesting\\n\\n■ 第2文型との関係\\n第2文型は S＝C、第5文型は O＝C である。イコールになる相手がちがうだけで、C のはたらきは同じである。\\n\\n第2文型　He is happy.（He ＝ happy）\\n第5文型　The news made him happy.（him ＝ happy）\\n\\n■ C になれるもの\\n名詞（Ken / our leader / a doctor）\\n形容詞（happy / clean / open / interesting）\\n副詞は C になれない。\\n\\n★ ポイント：「O＝C」を書いてみて意味が通れば第5文型である。第4文型では二つの O がイコールにならないので、ここで区別できる。\",\"figureId\":\"lf_eigoext02_077\",\"mangaId\":\"eigo_s077_xm\"},{\"heading\":\"語順は入れかえられない\",\"body\":\"第5文型では、O と C の順番が決まっている。入れかえると意味が変わってしまう。\\n\\n例）We call him Ken.（彼をケンと呼ぶ）\\n　　We call Ken him.（ケンを「彼」と呼ぶ → 意味が通らない）\\n\\n例）They named the baby Mika.（赤ちゃんをミカと名づけた）\\n　　They named Mika the baby.（✗）\\n\\n■ O に代名詞が来るとき\\nO の位置なので目的格を使う。\\n\\n例）We call her Emi.（× We call she Emi.）\\n例）The song makes them happy.（× The song makes they happy.）\\n\\n■ C の位置には形容詞\\n✗ The news made me happily.\\n○ The news made me happy.\\nhappily は副詞なので C になれない。\\n\\n■ よく使う表現\\nKeep the room clean.（部屋をきれいにしておきなさい）\\nDon't leave the window open.（窓を開けたままにしないで）\\nHis words made me sad.（彼のことばは私を悲しませた）\\n\\n⚠ 注意：第5文型を作れる動詞は限られている。call・name・make・keep・find・leave・elect などを覚えておけば、中学受験では十分である。\"}],\"trapExamples\":[{\"question\":\"「私たちは彼をトムと呼びます。」を英語にしなさい。\",\"wrongAnswer\":\"We call Tom him.\",\"trapExplanation\":\"日本語の「彼を トムと」という順が意識にあっても、名前のほうが具体的なので先に置きたくなってしまう。O と C の順番が決まっていることを知らないと入れかえてしまう。\",\"correctAnswer\":\"We call him Tom.\",\"correctExplanation\":\"第5文型は〈V＋O＋C〉の順で、「だれを」が先、「何と」があとになる。We call Tom him. では「トムを彼と呼ぶ」という意味不明の文になる。O ＝ C の関係で、左が呼ばれる相手、右がその呼び名である。\"},{\"question\":\"次の文の誤りを直しなさい。　The good news made us happily.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「私たちを幸せにした」と日本語で「〜に」と訳すので、副詞の形がふさわしく感じられる。動詞のうしろだから副詞、という思いこみが働いている。\",\"correctAnswer\":\"The good news made us happy.\",\"correctExplanation\":\"C の位置に来るのは名詞か形容詞で、副詞は入れない。us ＝ happy というイコールの関係を作るので、形容詞の happy が正しい。happily は「幸せそうに」と動作の様子を表す語なので、ここには置けない。\"}]}",
"{\"id\":\"eigo_s078\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVOC①：call・name 型（〜を…と呼ぶ）\",\"description\":\"呼び名や名前を表す第5文型と、それをたずねる疑問文を身につける\",\"intro\":\"「これは英語で何と言いますか」を How do you call this? と言いたくなりますが、正しくは What do you call this in English? です。日本語の「どう」に引かれて How を使うのが、よくあるまちがいです。\",\"order\":578,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"call＋O＋C＝「O を C と呼ぶ」。name＋O＋C＝「O を C と名づける」。\",\"C には名前や呼び名（名詞）が入る。\",\"「英語で何と言いますか」は What do you call 〜 in English?\",\"How ではなく What を使う（× How do you call this?）。\",\"受け身で He is called Ken. という形もよく出る。\"],\"sections\":[{\"heading\":\"call と name\",\"body\":\"第5文型の中でも、呼び名や名前を表す形はとくによく出る。\\n\\n■ call＋O＋C（O を C と呼ぶ）\\n例）We call him Ken.（私たちは彼をケンと呼びます）\\n例）My friends call me Yu.（友達は私をユウと呼びます）\\n例）People call this flower a sunflower.（人々はこの花をひまわりと呼びます）\\n\\n■ name＋O＋C（O を C と名づける）\\n例）They named the baby Sakura.（彼らは赤ちゃんをさくらと名づけました）\\n例）We named our dog Shiro.（私たちは犬をシロと名づけました）\\n\\n■ C には名前が入る\\ncall や name の C は名詞である。人名や呼び名なので大文字で書き始めることが多い。\\n\\n■ 受け身の形\\n「〜と呼ばれている」と言うときは be動詞＋called の形になる。\\n\\n例）He is called Ken.（彼はケンと呼ばれています）\\n例）This tower is called Tsutenkaku.（この塔は通天閣と呼ばれています）\\n\\n★ ポイント：〈call＋人＋呼び名〉の順を、We call him Ken. の一文で丸ごと覚えてしまうとよい。\",\"figureId\":\"xf_eigo_s078\"},{\"heading\":\"「英語で何と言いますか」\",\"body\":\"第5文型をたずねる形で、入試に非常によく出るのが次の文である。\\n\\n■ 形\\nWhat do you call 〜 in English?（〜は英語で何と言いますか）\\n\\n例）What do you call this flower in English?\\n　－ We call it a sunflower.（ひまわりと言います）\\n\\n例）What do you call this in Japanese?\\n　－ We call it obi.\\n\\n■ How を使わない\\n✗ How do you call this in English?\\n○ What do you call this in English?\\n\\n日本語の「どう言いますか」につられて How を使ってしまうが、たずねているのは「呼び名（名前そのもの）」なので What を使う。How は「どのように・どんな方法で」をたずねる語である。\\n\\n■ 答え方\\nWe call it 〜. / It is called 〜. のどちらでもよい。\\n例）－ It is called a sunflower.\\n\\n■ 似た形\\nWhat is this called in English?（これは英語で何と呼ばれますか）\\n受け身を使った言い方で、意味は同じである。\\n\\n⚠ 注意：日本語では「なんて呼ぶの」「どう呼ぶの」のどちらでも言えるが、英語では What しか使えない。ここは書きかえ・選択問題の定番である。\",\"mangaId\":\"eigo_s078_xm\"}],\"trapExamples\":[{\"question\":\"「この鳥は英語で何と言いますか。」を英語にしなさい。（this bird／in English を使う）\",\"wrongAnswer\":\"How do you call this bird in English?\",\"trapExplanation\":\"日本語の「どう言いますか」「どう呼びますか」という言い方につられて、「どのように」を表す How を選んでしまう。日本語としてはどちらも自然に言えるのが原因である。\",\"correctAnswer\":\"What do you call this bird in English?\",\"correctExplanation\":\"たずねているのは「呼び名そのもの」なので、名前をたずねる What を使う。How は方法や様子をたずねる語で、呼び名をたずねる文には使えない。〈What do you call ＋ もの ＋ in English?〉の形で丸ごと覚える。\"},{\"question\":\"「彼らは彼女をエミと呼んでいます。」を英語にしなさい。\",\"wrongAnswer\":\"They call she Emi.\",\"trapExplanation\":\"「彼女」という日本語から she を選んでしまう。第5文型の O の位置であることを意識していないと、主格のまま置いてしまう。\",\"correctAnswer\":\"They call her Emi.\",\"correctExplanation\":\"call のうしろは目的語（O）の位置なので、代名詞は目的格の her になる。O＝C の関係で her ＝ Emi である。動詞のうしろに来る代名詞は形が変わる、という規則は文型が変わっても同じように働く。\"}]}",
"{\"id\":\"eigo_s079\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"SVOC②：make・keep・find 型\",\"description\":\"「O を C にする・C のままにしておく」を表す文と、make の二つの用法を区別する\",\"intro\":\"The news made me happy. は、直訳すると「その知らせが私を幸せにした」。日本語なら「知らせを聞いてうれしかった」と言うところです。ものを主語にして人の気持ちを動かす、英語らしい言い方に慣れましょう。\",\"order\":579,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"make＋O＋C＝「O を C にする」。The news made me happy.\",\"keep＋O＋C＝「O を C のままにしておく」。Keep the room clean.\",\"find＋O＋C＝「O が C だと分かる」。I found the book easy.\",\"C には形容詞が入ることが多い。副詞は入れない。\",\"make には SVOO（作ってあげる）と SVOC（〜にする）の二つがある。\"],\"sections\":[{\"heading\":\"三つの動詞の使い方\",\"body\":\"■ make＋O＋C（O を C にする）\\n例）The news made me happy.（その知らせは私を幸せにした）\\n例）Music makes me sleepy.（音楽は私をねむくさせる）\\n例）His words made her sad.（彼のことばは彼女を悲しませた）\\n例）They made him the captain.（彼らは彼をキャプテンにした）\\n\\nC には形容詞（happy / sad / sleepy）も名詞（the captain）も入る。\\n\\n■ keep＋O＋C（O を C のままにしておく）\\n例）Keep the door closed.（ドアを閉めておきなさい）\\n例）She keeps her room clean.（彼女は部屋をきれいにしている）\\n例）Keep the milk cold.（牛乳を冷たいままにしておいて）\\n\\n■ find＋O＋C（O が C だと分かる）\\n例）I found the book interesting.（その本はおもしろいと分かった）\\n例）We found the question easy.（その問題はやさしいと分かった）\\n\\n■ leave＋O＋C（O を C のままにしておく）\\n例）Don't leave the window open.（窓を開けたままにしないで）\\n\\n★ ポイント：どの動詞でも、O と C の間に「＝」が入る。me ＝ happy、her room ＝ clean、the book ＝ interesting。\",\"figureId\":\"xf_eigo_s079\"},{\"heading\":\"make の二つの用法\",\"body\":\"make は第4文型と第5文型の両方を作るので、区別が必要である。\\n\\n■ 第4文型（SVOO）＝「人に ものを 作ってあげる」\\n例）My mother made me a cake.\\n　　me（人）≠ a cake（もの）\\n　　書きかえ）My mother made a cake for me.\\n\\n■ 第5文型（SVOC）＝「O を C にする」\\n例）The song made me happy.\\n　　me ＝ happy\\n　　書きかえはできない。\\n\\n■ 見分け方\\nうしろの二つの語がイコールになるかどうかを見る。\\n\\nmade me a cake　→ me ＝ a cake?（✗）→ 第4文型\\nmade me happy　→ me ＝ happy?（○）→ 第5文型\\nmade him the captain → him ＝ the captain?（○）→ 第5文型\\n\\nC が名詞のときは第4文型と見分けにくいので、必ず「＝」を書いて確かめる。\\n\\n■ C の位置に副詞を置かない\\n✗ She keeps her room cleanly.\\n○ She keeps her room clean.\\ncleanly は「きれいに（動作の様子）」を表す副詞なので、C にはなれない。\\n\\n⚠ 注意：make・keep・find のうしろに二つの語が並んだら、まずイコールかどうかを確かめる。これだけで第4文型と第5文型を正しく分けられる。\",\"mangaId\":\"eigo_s079_xm\"}],\"trapExamples\":[{\"question\":\"次の文の誤りを直しなさい。　My sister always keeps her desk cleanly.\",\"wrongAnswer\":\"そのままで正しい\",\"trapExplanation\":\"「きれいにしておく」と日本語で「〜に」と訳すので、副詞の cleanly がふさわしく感じられる。動詞のうしろに置く語は副詞、という覚え方をしていると必ず引っかかる。\",\"correctAnswer\":\"My sister always keeps her desk clean.\",\"correctExplanation\":\"keep＋O＋C の C には形容詞が入る。her desk ＝ clean というイコールの関係を作るので、形容詞の clean が正しい。cleanly は「きれいに（掃除する）」のように動作の様子を表す副詞で、C にはなれない。\"},{\"question\":\"次の文の文型を答えなさい。　My mother made me happy.\",\"wrongAnswer\":\"第4文型（SVOO）\",\"trapExplanation\":\"make＋人＋〜 の形を見て、My mother made me a cake.（作ってくれた）と同じ第4文型だと考えてしまう。make ＝「作る」という訳だけを覚えているのが原因である。\",\"correctAnswer\":\"第5文型（SVOC）\",\"correctExplanation\":\"me ＝ happy というイコールの関係が成り立つので第5文型である。第4文型なら me ≠ a cake のようにイコールにならない。make のうしろに二つの語が並んだら、必ず「＝」を書いて確かめる。\"}]}",
"{\"id\":\"eigo_s080\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"文型の総まとめ：SVOO と SVOC の見分け\",\"description\":\"五つの文型を一つの手順で判別できるようにして、この単元を仕上げる\",\"intro\":\"SVOO と SVOC は、どちらも動詞のうしろに語が2つ並びます。見た目はそっくりなのに、片方はイコールになり、もう片方はなりません。修飾語を消して数え、最後にイコールで判定する。この手順を固めます。\",\"order\":580,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"手順①：修飾語（前置詞から始まるかたまり・時の語句）を消す。\",\"手順②：残った要素の数を数える（二つ＝SV、三つ＝SVC か SVO、四つ＝SVOO か SVOC）。\",\"手順③：イコールになるかどうかで最終判断する。\",\"S＝C なら SVC、O＝C なら SVOC。イコールにならなければ SVO・SVOO。\",\"give・buy・send は SVOO、call・make・keep は SVOC を作りやすい。\"],\"sections\":[{\"heading\":\"三段階の判別手順\",\"body\":\"文型を答える問題は、次の三段階で必ず解ける。\\n\\n■ 手順①　修飾語を消す\\n前置詞（in / on / at / to / for / with / of）から始まるかたまり、時を表す語句（every day / yesterday）、様子を表す副詞（very / fast / always）を（　）でくくって消す。\\n\\n例）My father gave me a watch on my birthday.\\n→（on my birthday）を消す\\n→ My father gave me a watch.\\n\\n■ 手順②　残った要素を数える\\n主語＋動詞のあとに、いくつ語のかたまりが残っているかを数える。\\n0個 → 第1文型（SV）\\n1個 → 第2文型か第3文型\\n2個 → 第4文型か第5文型\\n\\n■ 手順③　イコールで判断する\\n1個のとき　S＝それ なら SVC、ちがえば SVO\\n2個のとき　前＝後ろ なら SVOC、ちがえば SVOO\\n\\nMy father gave me a watch. → me ＝ a watch?（✗）→ SVOO\\nWe call him Ken. → him ＝ Ken?（○）→ SVOC\\n\\n★ ポイント：この三段階を機械的に実行すれば、どんな文でも文型を決められる。訳して考えると必ずまちがえる。\",\"figureId\":\"xf_eigo_s080\",\"mangaId\":\"eigo_s080_xm\"},{\"heading\":\"五つの文型の総整理\",\"body\":\"■ 第1文型　SV\\n例）Birds fly.／I go to school.（to school は M）\\n動詞のうしろに前置詞なしの名詞がない。\\n\\n■ 第2文型　SVC（S＝C）\\n例）He is a doctor.／She looks happy.／He became a teacher.\\nbe動詞、become、look、feel、sound、taste、smell、get、turn。\\n\\n■ 第3文型　SVO（S≠O）\\n例）I like dogs.／He plays the piano.／She entered the room.\\nいちばん多い形。\\n\\n■ 第4文型　SVOO（O1≠O2）\\n例）He gave me a book.／She made me a cake.\\n書きかえ）to（give / send / show / teach / tell）／for（buy / make / cook / get）\\n\\n■ 第5文型　SVOC（O＝C）\\n例）We call him Ken.／The news made me happy.／Keep the room clean.\\ncall、name、make、keep、find、leave。\\n\\n■ 動詞から見当をつける\\ngive・send・show・teach・buy・make・cook が出たら SVOO の可能性が高い。\\ncall・name・keep・find・leave が出たら SVOC の可能性が高い。\\nmake はどちらにもなるので、必ずイコールを確かめる。\\n\\n⚠ 注意：文型を答える問題では、まず修飾語を消す作業を省かないこと。ここを飛ばすと、SVO を SVOO と答えるようなまちがいが起こる。\"}],\"trapExamples\":[{\"question\":\"次の文の文型を答えなさい。　The students made him their leader.\",\"wrongAnswer\":\"第4文型（SVOO）\",\"trapExplanation\":\"make のうしろに him と their leader という二つの名詞のかたまりが並んでいるので、「彼に指導者を作ってあげた」と読んで第4文型だと考えてしまう。C が名詞のときはとくに見分けにくい。\",\"correctAnswer\":\"第5文型（SVOC）\",\"correctExplanation\":\"him ＝ their leader というイコールの関係が成り立つので第5文型である。「彼らは彼を自分たちのリーダーにした」という意味になる。第4文型なら made him a cake のように二つの語がイコールにならない。必ず「＝」を書いて確かめる。\"},{\"question\":\"次の文の文型を答えなさい。　My aunt sent me a beautiful card last week.\",\"wrongAnswer\":\"第5文型（SVOC）\",\"trapExplanation\":\"動詞のうしろに二つの語が並んでいることだけを見て、第5文型だと決めてしまう。四つの要素があれば SVOC、という覚え方をしていると、イコールの確認をとばしてしまう。\",\"correctAnswer\":\"第4文型（SVOO）\",\"correctExplanation\":\"last week は時を表す修飾語なので消す。残った me と a beautiful card は、me ＝ a beautiful card とはならないので第4文型である。書きかえると My aunt sent a beautiful card to me. となり、send が to 型であることも確かめられる。\"}]}",
"{\"id\":\"eigo_s081\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"名詞の基本①：数えられる名詞と数えられない名詞\",\"description\":\"英語の名詞が可算・不可算の二種類に分かれることと、それぞれの書き方の約束を身につける\",\"intro\":\"「かばんを持っています」を I have bag. と言うと、英語ではひどく不自然に聞こえます。a を付けるか複数形にするかを、必ず決めなければならないからです。日本語は数を言わずに済む言語、英語は数を言わずにいられない言語なのです。\",\"order\":581,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"名詞＝人・物・ことがらの名前を表す語。英語では「数えられる名詞（可算名詞）」と「数えられない名詞（不可算名詞）」に分かれる。\",\"可算名詞の単数は、裸で置かない。a / an / the / my などを必ず前に付ける（× I have bag.）。\",\"可算名詞が2つ以上のときは複数形にする（two books）。\",\"不可算名詞は a / an を付けず、複数形にもしない（× a water／× waters）。\",\"不可算名詞は単数あつかい。Water is important. のように動詞は is・was になる。\",\"「決まった形があって1つ2つと切り分けられるか」が、数えられるかどうかの判断の目安。\"],\"sections\":[{\"heading\":\"英語の名詞には二種類ある\",\"mangaId\":\"eigo_s081_manga\",\"body\":\"日本語で「本」「水」「宿題」と言うとき、私たちは形をあまり気にしない。「本が3つ」も「水が3つ」も、言い方としては同じ形で作れてしまう。ところが英語では、名詞をまず二つのグループに分けてから使う。\\n\\n■ 数えられる名詞（可算名詞）\\n1つ・2つと数えられるもの。はっきりした形や輪かくがあり、半分に切ったらもうそれとは呼べなくなるものが多い。\\n例）book（本）／apple（りんご）／dog（犬）／pen（ペン）／cup（コップ）／friend（友達）\\n\\n■ 数えられない名詞（不可算名詞）\\n1つ・2つと数えられないもの。決まった形がなく、いくら分けても同じ名前で呼べるもの、また目に見えないことがらが多い。\\n例）water（水）／milk（牛乳）／bread（パン）／money（お金）／music（音楽）／love（愛）\\n\\n■ 見分けるときの目安\\n①決まった形があるか。りんごは形が決まっている（可算）。水はコップに入れれば丸く、皿に入れれば平たくなる（不可算）。\\n②半分にしても同じ名前で呼べるか。本を半分にしたら本ではないが、水を半分にしてもやはり水である。半分にしても同じ名前なら不可算。\\n③目に見えるか。music・time・peace・information のような目に見えないことがらは、ふつう不可算。\\n\\n★ ポイント：英語では名詞を書くたびに「これは数えられる方か、数えられない方か」を必ず考える。この一手間をおろそかにすると、a を付け忘れたり、付けてはいけない a を付けたりする誤りが一生なおらない。\"},{\"heading\":\"可算名詞の三つの約束\",\"body\":\"数えられる名詞には、守らなければならない約束が三つある。\\n\\n■ 約束①　単数は裸で置かない\\n1つのときは、前に a / an を付ける（初めて話に出すとき）。すでに話に出ていて「あの〜」と特定できるときは the を付ける。my / your / this などが付く場合はそれで十分。\\n例）I have a bag.（かばんを1つ持っている）\\n例）This is my bag.（これは私のかばんです）\\n⚠ 注意：× I have bag. は英語として成り立たない。日本語には冠詞がないので、日本人がいちばん多くまちがえるところである。\\n\\n■ 約束②　2つ以上なら複数形にする\\n例）I have two bags.／I have many books.／There are three apples on the table.\\n数字・many・some・these などが前に来たら、後ろの名詞は複数形になっているかを必ず見直す。\\n\\n■ 約束③　単数か複数かで動詞の形が変わる\\n例）This book is new.／These books are new.\\n例）A dog runs fast.（犬というものは速く走る）／Dogs run fast.\\n\\n★ ポイント：可算名詞は「a か、複数形か」のどちらかになる、と覚えるとよい。裸の単数が残っていたら、ほぼ書きまちがいである。\"},{\"heading\":\"不可算名詞の三つの約束\",\"body\":\"数えられない名詞にも、逆向きの約束が三つある。\\n\\n■ 約束①　a / an を付けない\\n例）I like music.（× I like a music.）\\n例）We need water.（× We need a water.）\\n\\n■ 約束②　複数形にしない\\n例）I have homework today.（× two homeworks）\\n「たくさんある」と言いたいときは much や a lot of を使う。\\n例）I have a lot of homework.／There is much snow in Hokkaido.\\n\\n■ 約束③　いつも単数あつかい\\n例）Water is important for our life.（× Water are ...）\\n例）This information is very useful.\\n\\n■ どうしても数を言いたいときは\\n「入れ物」や「かたまり」を表すことばを借りて数える。\\n例）a glass of water（コップ1ぱいの水）／a cup of coffee（カップ1ぱいのコーヒー）／a piece of paper（紙1枚）\\nこのやり方はあとのセッションでくわしく学ぶ。\\n\\n⚠ 注意：不可算名詞は the が付くことはある。the water in this bottle（このびんの中の水）のように「どの水か」が決まる場合である。付けられないのは a / an だけだと整理しておく。\",\"figureId\":\"lf_eigoext03_081\"}],\"trapExamples\":[{\"question\":\"「私はかばんを持っています。」を英語にしなさい。\",\"wrongAnswer\":\"I have bag.\",\"trapExplanation\":\"日本語の「かばん」には a にあたる語がないので、そのまま単語を並べて bag と書いてしまう。日本語に冠詞がないことから来る、日本人にいちばん多い誤り。\",\"correctAnswer\":\"I have a bag.\",\"correctExplanation\":\"bag は数えられる名詞なので、1つのときは a を付ける。数えられる名詞の単数を裸で置くことはできない。「a か、複数形か」のどちらかになるという原則で必ず見直す。two bags なら複数形にする。\"},{\"question\":\"（　）に is か are を入れなさい。　Water （　） important for our life.\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"「水」はたくさんあるイメージなので、複数だと考えて are を選んでしまう。日本語では水を単数・複数で区別しないため、量が多い＝複数と思いこみやすい。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"water は数えられない名詞なので、量がどれだけ多くても単数あつかいになり、動詞は is を使う。同じように Money is important. / This information is useful. も単数あつかい。数えられない名詞は複数形にならないので、are が来ることはない。\"}]}",
"{\"id\":\"eigo_s082\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数えられない名詞の四つのグループ\",\"description\":\"物質・抽象・固有・まとめて呼ぶ名詞という四つの型で、不可算名詞を整理して覚える\",\"intro\":\"water を「1つ、2つ」と数える人はいません。では music はどうでしょうか。目に見えないものも数えられないのです。数えられない名詞は4つの型に分けられます。型で覚えると、a を付けるかどうかで迷わなくなります。\",\"order\":582,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"不可算名詞は大きく「物質名詞」「抽象名詞」「固有名詞」「まとめて呼ぶ名詞」の四つに分けられる。\",\"物質名詞＝water, milk, bread, rice, paper, money, air, snow など、切っても同じ名前で呼べるもの。\",\"抽象名詞＝music, love, peace, time, work, health, luck など、目に見えないことがら。\",\"固有名詞＝Japan, Tokyo, Ken など、世界に一つしかない名前。a も複数形も付けない。\",\"まとめて呼ぶ名詞＝furniture（家具類）, baggage（荷物類）, food（食べ物）のように、いろいろな物をひとまとめにした言い方。\",\"「a を付けたくなったら、その語がこの四つのどれかでないか」を確かめる習慣をつける。\"],\"sections\":[{\"heading\":\"四つの型に分けて覚える\",\"body\":\"不可算名詞は一つひとつ覚えるときりがない。次の四つの型に分けると、初めて見る単語でも見当がつくようになる。\\n\\n■ ①物質名詞（材料・液体・こな・かたまり）\\n決まった形がなく、分けても同じ名前で呼べるもの。\\n例）water（水）／milk（牛乳）／juice（ジュース）／bread（パン）／rice（米・ごはん）／meat（肉）／cheese（チーズ）／sugar（砂糖）／salt（塩）／paper（紙）／glass（ガラス）／wood（木材）／iron（鉄）／money（お金）／air（空気）／snow（雪）／rain（雨）\\n\\n■ ②抽象名詞（目に見えないことがら）\\n気持ち・考え・状態など、手でさわれないもの。\\n例）music（音楽）／art（芸術）／love（愛）／peace（平和）／time（時間）／work（仕事）／health（健康）／luck（運）／fun（楽しみ）／help（助け）／advice（助言）／information（情報）／news（知らせ）\\n\\n■ ③固有名詞（世界に一つの名前）\\n例）Japan／Tokyo／Ken／Monday／April／Mt. Fuji\\n必ず大文字で書き始め、ふつう a も複数形も付けない。\\n\\n■ ④まとめて呼ぶ名詞\\nいろいろな種類の物を、ひとまとめにして呼ぶ言い方。\\n例）furniture（つくえ・いす・たななどをまとめた「家具類」）／baggage・luggage（かばん類）／food（食べ物）／clothing（衣類）／equipment（用具類）\\n\\n★ ポイント：④は「1つ2つ数えられそうなのに数えられない」ので、入試でとくにねらわれる。furniture を furnitures とは書かない。\",\"figureId\":\"xf_eigo_s082\",\"mangaId\":\"eigo_s082_xm\"},{\"heading\":\"不可算名詞をふくむ文の作り方\",\"body\":\"不可算名詞は a も複数形も使えないので、量を表したいときは次のことばを借りる。\\n\\n■ 量を表すことば\\nmuch（たくさんの）／a lot of・lots of（たくさんの）／some（いくらかの）／a little（少しの）／little（ほとんどない）／no（まったくない）\\n例）I have a lot of homework today.（今日は宿題がたくさんある）\\n例）There is a little milk in the glass.（コップに牛乳が少し入っている）\\n例）We had no rain last month.（先月は雨がまったく降らなかった）\\n\\n■ 「どのくらい？」とたずねるとき\\n数をたずねる How many〜? ではなく、量をたずねる How much〜? を使う。\\n例）How much water do you drink every day?（毎日どのくらい水を飲みますか）\\n例）How much time do we have?（時間はどのくらいありますか）\\n\\n■ 動詞は必ず単数あつかい\\n例）Music is my favorite subject.（音楽は私の好きな教科です）\\n例）Some water was left in the bottle.（びんに水が少し残っていた）\\n\\n⚠ 注意：some は肯定文で可算・不可算のどちらにも使える便利な語である。よくわからないときにとりあえず some を置くと、まちがいを大きく減らせる。I want some bread.（パンがほしい）は、a bread と書くより安全で自然。\"}],\"trapExamples\":[{\"question\":\"「私はパンを食べたい。」を英語にしなさい。\",\"wrongAnswer\":\"I want to eat a bread.\",\"trapExplanation\":\"日本語で「パンを1つ」と数えられる気がするので、つい a を付けてしまう。実際に目にするパンは形があるため、数えられる物だと感じてしまうのが原因。\",\"correctAnswer\":\"I want to eat some bread.（1切れなら a piece of bread / a slice of bread）\",\"correctExplanation\":\"bread は「パンという材料・食べ物」を表す物質名詞なので、a も複数形も付けられない。量を言いたいときは some を使い、1切れなら a slice of bread、ひとかたまりなら a loaf of bread のように単位のことばを借りる。同じ理由で cheese, meat, rice も不可算。\"},{\"question\":\"「私は音楽が好きです。」を英語にしなさい。\",\"wrongAnswer\":\"I like a music.\",\"trapExplanation\":\"「〜が好きです」の形をおぼえるときに I like a dog. のような例文で練習するため、名詞の前にはいつも a を置くものだと思いこんでしまう。\",\"correctAnswer\":\"I like music.\",\"correctExplanation\":\"music は目に見えないことがらを表す抽象名詞なので、a を付けず、複数形にもしない。同じく I like art. / I want peace. / We need help. も冠詞なしで使う。なお I like dogs. のように数えられる名詞で「〜というものが好き」と言うときは、a dog ではなく複数形にするのがふつう。\"}]}",
"{\"id\":\"eigo_s083\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"日本語の感覚とずれる不可算名詞\",\"description\":\"homework・information・advice など、日本語では数えられるのに英語では数えられない語をまとめて覚える\",\"intro\":\"「宿題がたくさんある」を I have many homeworks. と書きたくなりますが、homework は数えられません。日本語では1つ2つと数えられるのに、英語では数えない。ここは知識の差がそのまま点差になるところです。\",\"order\":583,\"studyPeriod\":\"小4\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"「1つ2つ数えられそうなのに数えられない」語が、入試ではいちばんねらわれる。\",\"代表格：homework（宿題）／information（情報）／advice（助言）／furniture（家具）／baggage・luggage（荷物）／news（知らせ）／work（仕事）／money（お金）／weather（天気）／traffic（交通）／fun（楽しみ）。\",\"news は -s で終わるが複数形ではない。単数あつかい（The news is true.）。\",\"数えたいときは a piece of を借りる（a piece of advice＝助言1つ／two pieces of information）。\",\"これらの語には many ではなく much / a lot of を使い、How many ではなく How much でたずねる。\"],\"sections\":[{\"heading\":\"まちがえやすい不可算名詞リスト\",\"mangaId\":\"eigo_s083_manga\",\"body\":\"日本語では「宿題が3つ」「情報を2つ」と平気で数えるのに、英語では数えられない語がある。理屈で考えるより、次のリストを丸暗記してしまうのが早い。\\n\\n■ 必ず覚える11語\\nhomework（宿題）／information（情報）／advice（助言・アドバイス）／furniture（家具）／baggage・luggage（荷物）／news（知らせ・ニュース）／work（仕事）／money（お金）／weather（天気）／traffic（交通・交通量）／fun（楽しみ）\\n\\n例）I have a lot of homework today.（今日は宿題がたくさんある）\\n例）He gave me some good advice.（彼はよい助言をいくつかくれた）\\n例）There is too much traffic in this city.（この町は交通量が多すぎる）\\n\\n■ なぜ数えられないのか\\n英語では、これらを「一つひとつの品物」ではなく「そういう種類のもの全体」としてとらえている。furniture はつくえ・いす・たなをまとめた呼び名なので、それ自体は1つ2つと数えない。数えたいときは a desk, two chairs のように具体的な語に言いかえるか、a piece of furniture（家具1点）と単位を借りる。\\n\\n★ ポイント：日本語で「〜類」「〜というもの」と言いかえられる語は、英語では不可算になりやすい。「家具類」「荷物類」「情報というもの」と頭の中で言いかえてみるとよい。\",\"figureId\":\"xf_eigo_s083\"},{\"heading\":\"money・news・work の注意点\",\"body\":\"とくにまちがえやすい三語を、個別に確認しておく。\\n\\n■ money（お金）\\n不可算。× many moneys とは言えない。\\n例）I don't have much money.（あまりお金がない）\\n例）He has a lot of money.（彼はお金をたくさん持っている）\\n※ 数えられるのは coin（硬貨）や bill（紙幣）のほう。two coins は正しい。\\n\\n■ news（知らせ）\\n-s で終わっているが複数形ではない。単数あつかいになる。\\n例）The news was very sad.（その知らせはとても悲しかった）\\n例）I have good news for you.（よい知らせがあります）\\n※ 同じように、-s で終わるのに単数あつかいの語に mathematics（数学）がある。\\n\\n■ work（仕事）\\n「仕事・労働」の意味では不可算。\\n例）I have a lot of work to do.（するべき仕事がたくさんある）\\n※ ただし「作品」の意味では数えられる。the works of Natsume Soseki（夏目漱石の作品）。\\n※ 「職・勤め口」と言いたいときは、数えられる語 job を使う。I found a good job.（よい仕事を見つけた）\\n\\n⚠ 注意：these・many・数字が前にあるのに不可算名詞が来ていたら、そこがまちがい。× many homeworks／× two informations／× three advices。すべて much / a lot of / a piece of に直す。\"}],\"trapExamples\":[{\"question\":\"「私は今日、宿題がたくさんある。」を英語にしなさい。\",\"wrongAnswer\":\"I have many homeworks today.\",\"trapExplanation\":\"日本語では「宿題が3つ」と数えるので、複数形にして many を付けたくなる。プリントやページなど、目に見える形があることも思いこみを強めてしまう。\",\"correctAnswer\":\"I have a lot of homework today.（much homework も可）\",\"correctExplanation\":\"homework は不可算名詞なので複数形にできず、many も使えない。量を表す a lot of / much を使い、名詞は homework のままにする。数えたいときは two pieces of homework のように単位を借りる。information, advice, furniture も同じ形で使う。\"},{\"question\":\"（　）に is か are を入れなさい。　The news （　） true.\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"語尾が -s なので複数形だと考えて are を選んでしまう。「複数形は -s」という規則を覚えたばかりの人ほど引っかかりやすい。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"news はもともと -s のついた形で一語になっている不可算名詞で、複数形ではない。したがって単数あつかいで is を使う。The news was very sad. のように過去形でも was になる。同じ型の語に mathematics（数学）がある。\"}]}",
"{\"id\":\"eigo_s084\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"可算にも不可算にもなる名詞\",\"description\":\"glass・paper・chicken・room・time など、意味によって数え方が変わる語を区別する\",\"intro\":\"a glass は「コップ」、glass は「ガラス」。a paper は「新聞」、paper は「紙」。同じ語でも a が付くかどうかで意味が変わります。つまり冠詞は飾りではなく、意味そのものを運んでいるのです。\",\"order\":584,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"同じつづりでも、意味が変われば数え方も変わる語がある。\",\"glass：ガラス（材料・不可算）／コップ（可算）。paper：紙（不可算）／新聞・答案（可算）。\",\"chicken：鶏肉（不可算）／にわとり（可算）。fish：魚肉（不可算）／魚（可算、複数形も fish）。\",\"room：余地・空間（不可算）／部屋（可算）。time：時間（不可算）／回数（可算）。\",\"light：光（不可算）／電灯（可算）。work：仕事（不可算）／作品（可算）。\",\"「材料・ぼんやりした全体」なら不可算、「形のある1つの品物」なら可算、と整理する。\"],\"sections\":[{\"heading\":\"意味で数え方が変わる代表語\",\"body\":\"英語には、同じつづりでありながら、意味によって可算にも不可算にもなる名詞がある。a が付いているかいないかで意味が変わってしまうので、読解でも作文でも重要になる。\\n\\n■ glass\\n不可算＝ガラス（材料）。The window is made of glass.（窓はガラスでできている）\\n可算＝コップ。I drank a glass of milk.（コップ1ぱいの牛乳を飲んだ）\\n※ 複数形 glasses は「めがね」。My glasses are new.（私のめがねは新しい）\\n\\n■ paper\\n不可算＝紙。I need some paper.（紙が少しいる）\\n可算＝新聞・答案・論文。I read a paper every morning.（毎朝新聞を読む）\\n\\n■ chicken\\n不可算＝鶏肉。I ate chicken for dinner.（夕食に鶏肉を食べた）\\n可算＝にわとり。There are three chickens in the yard.（庭ににわとりが3羽いる）\\n\\n■ room\\n不可算＝余地・空間。There is no room for my bag.（かばんを置く場所がない）\\n可算＝部屋。There are six rooms in this house.（この家には部屋が6つある）\\n\\n■ time\\n不可算＝時間。I don't have time.（時間がない）\\n可算＝回数。I have been to Kyoto three times.（京都へ3回行ったことがある）\\n\\n★ ポイント：材料やぼんやりした全体をさすときは不可算、切り取られた形のある1品をさすときは可算になる。\",\"figureId\":\"xf_eigo_s084\",\"mangaId\":\"eigo_s084_xm\"},{\"heading\":\"意味のちがいが出る例文で確かめる\",\"body\":\"a が付くかどうかで意味が変わる例を、対にして確かめておく。\\n\\n■ light\\nLight travels very fast.（光はとても速く進む）＝不可算\\nPlease turn on the light.（電灯をつけてください）＝可算\\n\\n■ work\\nI have a lot of work today.（今日は仕事がたくさんある）＝不可算\\nThis is a work of art.（これは一つの芸術作品だ）＝可算\\n\\n■ fish\\nWe had fish for lunch.（昼食に魚〈の身〉を食べた）＝不可算\\nI caught three fish in the river.（川で魚を3びきつかまえた）＝可算。ただし複数形も fish のまま。\\n\\n■ hair\\nMy hair is long.（髪が長い）＝不可算。頭全体の髪をまとめてさす。\\nThere is a hair in my soup.（スープに髪の毛が1本入っている）＝可算。1本を取り出せば数えられる。\\n\\n■ iron\\nThis gate is made of iron.（この門は鉄でできている）＝不可算\\nMy mother bought a new iron.（母は新しいアイロンを買った）＝可算\\n\\n⚠ 注意：I ate a chicken. と書くと「にわとりを1羽まるごと食べた」という意味になってしまう。鶏肉なら I ate chicken. または I ate some chicken. とする。a の有無で意味が変わることを、笑い話ではなく文法として理解しておく。\"}],\"trapExamples\":[{\"question\":\"「私は夕食に鶏肉を食べました。」を英語にしなさい。\",\"wrongAnswer\":\"I ate a chicken for dinner.\",\"trapExplanation\":\"数えられる名詞の単数には a を付ける、という規則をおぼえた直後の人ほど、chicken にも機械的に a を付けてしまう。「1羽」と「肉」の区別が日本語では意識されないことも原因。\",\"correctAnswer\":\"I ate chicken for dinner.（I ate some chicken. も可）\",\"correctExplanation\":\"「鶏肉」の意味の chicken は材料を表す不可算名詞なので、a を付けず複数形にもしない。a chicken と書くと「にわとり1羽」となり、生きた鳥をまるごと食べた意味になってしまう。fish も同じで、料理としての魚は We had fish. とする。\"},{\"question\":\"「私は時間がありません。」を英語にしなさい。\",\"wrongAnswer\":\"I have no times.\",\"trapExplanation\":\"three times（3回）という言い方を先に習っているため、time はいつも数えられる語だと思いこんで複数形にしてしまう。\",\"correctAnswer\":\"I have no time.\",\"correctExplanation\":\"「時間」の意味の time は不可算名詞なので複数形にしない。数えられるのは「回数」の意味のときだけで、three times（3回）、many times（何度も）はこちらである。同じように room も「部屋」なら可算、「余地」なら不可算になる。\"}]}",
"{\"id\":\"eigo_s085\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数と量を表す語：many・much・few・little\",\"description\":\"可算名詞と不可算名詞で使い分ける数量の語を、意味のちがいまで含めて整理する\",\"intro\":\"「水がたくさん」を many water とは言えません。数えられる名詞には many、数えられない名詞には much を使うからです。さらに a few と few は、a があるかないかで意味がほぼ反対になります。\",\"order\":585,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"many＋可算名詞の複数形（many books）／much＋不可算名詞（much water）。\",\"a lot of・lots of は可算・不可算のどちらにも使え、肯定文でよく使う。\",\"a few＋可算名詞の複数形＝「少しはある」／few＝「ほとんどない」。a の有無で意味が逆になる。\",\"a little＋不可算名詞＝「少しはある」／little＝「ほとんどない」。\",\"数をたずねるのは How many＋複数形、量をたずねるのは How much＋不可算名詞。\",\"much は否定文・疑問文で使うことが多く、肯定文ではふつう a lot of を使う。\"],\"sections\":[{\"heading\":\"「多い」を表す語の使い分け\",\"body\":\"「たくさんの」を表す語は、後ろに来る名詞が数えられるかどうかで変わる。\\n\\n■ many＋数えられる名詞の複数形\\n例）I have many friends.（友達がたくさんいる）\\n例）There are many students in the gym.（体育館に生徒がたくさんいる）\\n\\n■ much＋数えられない名詞\\n例）I don't have much money.（あまりお金がない）\\n例）Is there much snow in your town?（あなたの町は雪が多いですか）\\n⚠ 注意：much は否定文・疑問文で使うのがふつうで、肯定文で使うとかたい言い方になる。「たくさんある」と肯定文で言うときは a lot of を使う。\\n\\n■ a lot of・lots of＋どちらでもよい\\n例）I have a lot of books.（本をたくさん持っている）\\n例）I have a lot of homework.（宿題がたくさんある）\\n迷ったら a lot of を使えば、可算・不可算のどちらでもまちがいにならない。\\n\\n■ たずねるとき\\n数をたずねる：How many books do you have?（本を何冊持っていますか）\\n量をたずねる：How much water do you drink?（水をどのくらい飲みますか）\\n※ How much is this?（これはいくらですか）は値段をたずねる決まり文句。\",\"figureId\":\"lf_eigoext03_085\"},{\"heading\":\"a few と few、a little と little\",\"body\":\"「少し」を表す語は、a が付くかどうかで意味がほぼ逆になる。入試で最もねらわれる区別の一つである。\\n\\n■ 数えられる名詞につくもの\\na few＋複数形＝「少しはある（数が少しある）」…プラスの気持ち\\nfew＋複数形＝「ほとんどない」…マイナスの気持ち\\n例）I have a few friends in Tokyo.（東京に友達が数人いる）\\n例）I have few friends in Tokyo.（東京にはほとんど友達がいない）\\n\\n■ 数えられない名詞につくもの\\na little＋不可算名詞＝「少しはある」\\nlittle＋不可算名詞＝「ほとんどない」\\n例）There is a little water in the bottle.（びんに水が少し入っている）\\n例）There is little water in the bottle.（びんにはほとんど水がない）\\n\\n■ 覚え方\\na が付くと「a＝1つでもある」と考えて〈ある〉方に、a がないと〈ない〉方に傾く、と結びつけると忘れにくい。\\n\\n■ そのほかの数量表現\\nsome（いくらかの）…肯定文で使う。可算・不可算どちらにも付く。\\nany（いくらかの・少しも）…疑問文・否定文で使う。\\nno（一つもない・少しもない）…名詞の前に置くだけで否定になる。I have no money.\\n例）Would you like some tea?（お茶はいかがですか）※すすめる疑問文では some を使う。\\n\\n★ ポイント：a little は「少しはある」、little は「ほとんどない」。日本語訳では「少し」と「ほとんどない」で大きく違うので、和訳問題ではここで差がつく。\",\"mangaId\":\"eigo_s085_xm\"}],\"trapExamples\":[{\"question\":\"「あなたはお金をいくら持っていますか。」を英語にしなさい。\",\"wrongAnswer\":\"How many money do you have?\",\"trapExplanation\":\"日本語の「いくら」を「いくつ」と同じ感覚でとらえてしまい、数をたずねる How many を選んでしまう。money に -s が付いていないことにも気づきにくい。\",\"correctAnswer\":\"How much money do you have?\",\"correctExplanation\":\"money は数えられない名詞なので、量をたずねる How much を使う。How many の後ろには必ず数えられる名詞の複数形（How many books / How many students）が来る。後ろの名詞に -s が付けられるかどうかで、many と much を決めるとよい。\"},{\"question\":\"He has few friends in this city. の意味として正しいものを選びなさい。\",\"wrongAnswer\":\"彼はこの町に友達が少しいる。\",\"trapExplanation\":\"few を「少し」と訳す語としておぼえていると、a few との区別がつかず、そのまま「少しいる」と訳してしまう。a があるかないかを見落とすのが原因。\",\"correctAnswer\":\"彼はこの町にはほとんど友達がいない。\",\"correctExplanation\":\"a のない few は「ほとんどない」というマイナスの意味を表す。「少しはいる」と言いたいときは a few friends とする。数えられない名詞でも同じで、a little water は「水が少しある」、little water は「水がほとんどない」。a の有無で意味が逆になることを必ず確認する。\"}]}",
"{\"id\":\"eigo_s086\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"複数形①：基本は -s を付けるだけ\",\"description\":\"複数形の作り方の原則と、複数形にしなければならない場面を確実にする\",\"intro\":\"「本を3冊持っています」を I have three book. と書くと、英語では数の合図がぶつかっています。three と言った時点で、book も複数形にしなければなりません。日本語にはない、この二重の合図に慣れましょう。\",\"order\":586,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"数えられる名詞が2つ以上のときは複数形にする。作り方の基本は語尾に -s を付けるだけ。\",\"数字（two, ten…）／many／some／a lot of／these／those の後ろの名詞は複数形になる。\",\"one の後ろは単数のまま（one book / two books）。\",\"主語が複数形なら、動詞に三人称単数の -s は付けない（Many students like soccer.）。\",\"主語が複数形なら be動詞は are・were になる（These books are new.）。\"],\"sections\":[{\"heading\":\"複数形の作り方の原則\",\"mangaId\":\"eigo_s086_manga\",\"body\":\"数えられる名詞が2つ以上あるときは、名詞の形を変える。これを複数形という。日本語には「本」と「本たち」の区別がないので、書き忘れがいちばん多い項目である。\\n\\n■ 原則：語尾に -s を付ける\\nbook → books（本）／pen → pens（ペン）／dog → dogs（犬）／apple → apples（りんご）／friend → friends（友達）／student → students（生徒）／house → houses（家）／table → tables（テーブル）\\n\\n■ 複数形にしなければならない合図\\n①数字が前にある：two books／five apples／ten students\\n②many がある：many books\\n③some / a lot of がある：some pens／a lot of dogs\\n④these / those がある：these books／those cars\\n⑤複数を表す語がある：a lot of, several, both, all\\n例）There are a lot of books in this room.（この部屋には本がたくさんある）\\n\\n■ 単数のままにするもの\\none の後ろ：one book（× one books）\\na / an の後ろ：a book（× a books）\\neach / every の後ろ：every student（× every students）。every は「一人ひとり」を見ているので単数。\\n\\n★ ポイント：作文をしたら、名詞の前に数字や many がないかを確かめ、あれば -s が付いているかを見直す。この見直しだけで得点が変わる。\",\"figureId\":\"xf_eigo_s086\"},{\"heading\":\"複数形にすると文全体が変わる\",\"body\":\"名詞を複数形にしたら、それにつられて文のほかの部分も変わる。名詞だけ直して満足してはいけない。\\n\\n■ be動詞が変わる\\nThis book is new.（この本は新しい）\\n→ These books are new.（これらの本は新しい）\\nThat was a good movie.\\n→ Those were good movies.\\n\\n■ 一般動詞の三人称単数の -s が消える\\nMy friend likes soccer.（私の友達はサッカーが好きだ）\\n→ My friends like soccer.（私の友達はサッカーが好きだ）\\n⚠ 注意：主語が複数のときに likes と書くのは典型的な誤り。「主語に -s が付いたら動詞の -s は取れる」と覚えるとよい。\\n\\n■ this / that も変わる\\nthis → these／that → those\\n例）Is this your pen? → Are these your pens?\\n\\n■ There is / There are も変わる\\nThere is a book on the desk.\\n→ There are two books on the desk.\\n\\n■ a / an が消える\\nHe is a student. → They are students.（× They are a students.）\\n\\n★ ポイント：単数の文を複数の文に書きかえる問題は入試の定番。①主語の名詞　②be動詞または一般動詞　③this/that　④a/an の四か所を順に点検すると、取りこぼしがなくなる。\"}],\"trapExamples\":[{\"question\":\"「私には兄弟が3人と姉妹が1人います。」を英語にしなさい。\",\"wrongAnswer\":\"I have three brother and one sisters.\",\"trapExplanation\":\"日本語では「兄弟」も「姉妹」も形が変わらないため、-s を付ける位置を取りちがえる。数字を見ずに、なんとなく後ろの語にだけ -s を付けてしまうことが多い。\",\"correctAnswer\":\"I have three brothers and one sister.\",\"correctExplanation\":\"2以上の数字の後ろは複数形（three brothers）、one の後ろは単数（one sister）になる。名詞の前にある数字を必ず見てから -s を付けるかどうかを決める。and でつながれた二つの名詞は、それぞれ別々に判断する。\"},{\"question\":\"「多くの生徒がサッカーが好きです。」を英語にしなさい。\",\"wrongAnswer\":\"Many students likes soccer.\",\"trapExplanation\":\"「三人称単数の主語には動詞に -s」という規則を強く覚えていると、主語が複数になっても動詞の -s を残してしまう。名詞の -s と動詞の -s を混同するのが原因。\",\"correctAnswer\":\"Many students like soccer.\",\"correctExplanation\":\"動詞に -s が付くのは、主語が三人称で単数のときだけである。many students は複数なので、動詞は原形のまま like を使う。「名詞に -s が付いたら動詞の -s は消える」とセットで覚える。My friend likes soccer. と My friends like soccer. を並べて確かめるとよい。\"}]}",
"{\"id\":\"eigo_s087\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"複数形②：-es を付ける語\",\"description\":\"s・x・ch・sh・o で終わる語の複数形を、例外までふくめて覚える\",\"intro\":\"box は boxs ではなく boxes、potato は potatoes。ところが piano は pianoes ではなく pianos です。同じ o で終わるのに分かれるのはなぜでしょう。理由と、覚えるべき例外をここで整理します。\",\"order\":587,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"s, x, ch, sh で終わる語には -es を付ける（bus→buses, box→boxes, watch→watches, dish→dishes）。\",\"-es を付ける理由は、-s だけでは発音がつながらないから。読むと音が一つふえる。\",\"o で終わる語のうち、potato・tomato・hero は -es を付ける。\",\"o で終わっても piano・photo・radio・kilo は -s だけ（外来語や短縮した語に多い）。\",\"class→classes のように、もともと s で終わる語も -es になる。\"],\"sections\":[{\"heading\":\"s・x・ch・sh で終わる語\",\"body\":\"語尾が s・x・ch・sh の語に -s だけを付けると、音がつながらず発音できない。そこで e をはさんで -es とする。\\n\\n■ s で終わる語\\nbus → buses（バス）／class → classes（授業・組）／glass → glasses（コップ・めがね）／dress → dresses（ドレス）\\n\\n■ x で終わる語\\nbox → boxes（箱）／fox → foxes（きつね）／six → sixes\\n\\n■ ch で終わる語\\nwatch → watches（うで時計）／church → churches（教会）／bench → benches（ベンチ）／sandwich → sandwiches（サンドイッチ）／peach → peaches（もも）\\n\\n■ sh で終わる語\\ndish → dishes（皿）／brush → brushes（ブラシ）／bush → bushes（低木）\\n\\n■ 発音のポイント\\n-es を付けた語は、読むときに音のかたまりが一つふえる。bus は「バス」、buses は「バスィズ」となる。watch「ウォッチ」→ watches「ウォッチィズ」も同じ。\\n★ ポイント：「-es が付いたら、読むときにも音が一つふえる」と結びつけて覚えると、書き落としが減る。\",\"figureId\":\"xf_eigo_s087\"},{\"heading\":\"o で終わる語（-es 派と -s 派）\",\"body\":\"o で終わる語は二つに分かれる。数は多くないので、代表例を丸暗記してしまう。\\n\\n■ -es を付ける語（食べ物・古くからある語に多い）\\npotato → potatoes（じゃがいも）\\ntomato → tomatoes（トマト）\\nhero → heroes（英雄）\\necho → echoes（こだま）\\n\\n■ -s だけを付ける語（外来語・短くした語）\\npiano → pianos（ピアノ）\\nphoto → photos（写真。photograph を短くした語）\\nradio → radios（ラジオ）\\nkilo → kilos（キロ）\\nzoo → zoos（動物園。母音＋o なので -s）\\n\\n■ 覚え方\\n「じゃがいもとトマトは英雄だ（potatoes, tomatoes, heroes）」と一文にして覚えると三語まとめて片づく。それ以外の o は -s と考えておけば、中学入試ではほぼ困らない。\\n\\n⚠ 注意：pianoes・photoes は誤り。逆に potatos・tomatos も誤り。同じ o 終わりなのに逆向きの誤りが起きるので、必ず口に出して確かめる。\\n\\n■ f・fe で終わる語は次のセッションで\\nleaf → leaves のように、f・fe で終わる語には別の規則がある。混同しないよう、いまは s・x・ch・sh・o の五つに集中する。\",\"mangaId\":\"eigo_s087_xm\"}],\"trapExamples\":[{\"question\":\"box の複数形を書きなさい。\",\"wrongAnswer\":\"boxs\",\"trapExplanation\":\"「複数形は -s を付ける」という原則だけを覚えていると、語尾の音を確かめずに機械的に s を足してしまう。boxs は英語として発音することもできない。\",\"correctAnswer\":\"boxes\",\"correctExplanation\":\"語尾が s・x・ch・sh の語には -es を付ける。box は x で終わるので boxes となり、読み方も「ボクスィズ」と音が一つふえる。同じ規則で bus→buses、watch→watches、dish→dishes となる。声に出して読めるかどうかで確かめられる。\"},{\"question\":\"piano の複数形を書きなさい。\",\"wrongAnswer\":\"pianoes\",\"trapExplanation\":\"potatoes・tomatoes を先に覚えていると、「o で終わる語は -es」という誤った規則を作ってしまい、すべての o 終わりに -es を付けてしまう。\",\"correctAnswer\":\"pianos\",\"correctExplanation\":\"o で終わる語のうち -es を付けるのは potato, tomato, hero, echo など少数で、piano・photo・radio・kilo・zoo は -s だけを付ける。楽器や外来語、短くした語は -s になると覚えておく。「じゃがいも・トマト・英雄だけが -es」と限定して覚えるのが安全。\"}]}",
"{\"id\":\"eigo_s088\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"複数形③：y で終わる語・f/fe で終わる語\",\"description\":\"city→cities、leaf→leaves のようなつづりの変化を、条件つきで正確に覚える\",\"intro\":\"city は cities なのに day は days。knife は knives なのに roof は roofs。似た形なのに変わり方がちがうので、丸暗記ではすぐ混ざってしまいます。分かれ目になる条件をはっきりさせましょう。\",\"order\":588,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"「子音字＋y」で終わる語は、y を i に変えて -es（city→cities、country→countries、baby→babies）。\",\"「母音字＋y」で終わる語は、そのまま -s（boy→boys、day→days、key→keys、monkey→monkeys）。\",\"y の直前が a・i・u・e・o なら、y はそのまま残ると覚える。\",\"f・fe で終わる語は、f・fe を v に変えて -es（leaf→leaves、knife→knives、life→lives、wife→wives）。\",\"例外：roof→roofs、chief→chiefs、safe→safes、belief→beliefs は -s のみ。\"],\"sections\":[{\"heading\":\"y で終わる語：直前の文字を見る\",\"mangaId\":\"eigo_s088_manga\",\"body\":\"y で終わる語は二種類に分かれる。決め手は「y の直前が母音字か子音字か」の一点だけである。母音字とは a・i・u・e・o の五文字をいう。\\n\\n■ 子音字＋y → y を i に変えて -es\\ncity → cities（都市）／country → countries（国）／baby → babies（赤ちゃん）／story → stories（物語）／family → families（家族）／lady → ladies（婦人）／dictionary → dictionaries（辞書）／library → libraries（図書館）／party → parties（パーティー）／hobby → hobbies（趣味）\\nこれらはすべて y の直前が t・r・b・l など子音字である。\\n\\n■ 母音字＋y → そのまま -s\\nboy → boys（少年）／day → days（日）／key → keys（かぎ）／toy → toys（おもちゃ）／monkey → monkeys（さる）／way → ways（道・方法）／holiday → holidays（休日）\\nこれらは y の直前が o・a・e など母音字である。\\n\\n■ 確かめ方の手順\\n①語尾が y か確かめる。\\n②y のすぐ左の一文字を見る。\\n③a・i・u・e・o のどれかなら -s、それ以外なら y を i に変えて -es。\\n\\n★ ポイント：boy を boies としてしまう誤りは、②の手順をとばして「y はぜんぶ i に変える」と思いこむことから起きる。必ず直前の一文字を見る。\",\"figureId\":\"xf_eigo_s088\"},{\"heading\":\"f・fe で終わる語：v に変える\",\"body\":\"f・fe で終わる語の多くは、f・fe を v に変えて -es を付ける。読み方も「フ」から「ヴズ」に変わる。\\n\\n■ v に変える語\\nleaf → leaves（葉）／knife → knives（ナイフ）／life → lives（命・生活）／wife → wives（妻）／wolf → wolves（おおかみ）／shelf → shelves（たな）／thief → thieves（どろぼう）／half → halves（半分）／yourself → yourselves（あなたがた自身）\\n\\n例）The leaves turn red in fall.（秋には葉が赤くなる）\\n例）Put the knives on the table.（ナイフをテーブルに置いて）\\n\\n■ そのまま -s を付ける語（例外）\\nroof → roofs（屋根）／chief → chiefs（長）／safe → safes（金庫）／belief → beliefs（信念）／cliff → cliffs（がけ）／handkerchief → handkerchiefs（ハンカチ）\\n\\n■ 覚え方\\n中学入試で問われるのはほぼ leaf・knife・life・wife の四語である。この四語を「葉っぱ・ナイフ・命・妻はヴになる」と唱えて覚え、roof は例外として別に押さえておけばよい。\\n\\n⚠ 注意：life（命）の複数形 lives は「ライヴズ」と読む。live（住む）という動詞の三人称単数 lives（リヴズ）とつづりが同じなので、文中でどちらかを判断する必要がある。\\n例）Many lives were saved.（多くの命が救われた）＝名詞\\n例）He lives in Osaka.（彼は大阪に住んでいる）＝動詞\"}],\"trapExamples\":[{\"question\":\"boy の複数形を書きなさい。\",\"wrongAnswer\":\"boies\",\"trapExplanation\":\"city→cities、baby→babies を先に覚えているため、「y は i に変える」という規則をすべての y に当てはめてしまう。y の直前の文字を確かめる手順をとばすのが原因。\",\"correctAnswer\":\"boys\",\"correctExplanation\":\"y を i に変えるのは「子音字＋y」で終わる語だけである。boy は y の直前が母音字の o なので、そのまま -s を付けて boys とする。day→days、key→keys、monkey→monkeys も同じ。必ず y の左の一文字を見てから決める。\"},{\"question\":\"roof の複数形を書きなさい。\",\"wrongAnswer\":\"rooves\",\"trapExplanation\":\"leaf→leaves、knife→knives という変化を覚えた直後は、f で終わる語をすべて v に変えたくなる。規則を広げすぎることで起きる誤り。\",\"correctAnswer\":\"roofs\",\"correctExplanation\":\"f・fe を v に変えるのは leaf, knife, life, wife, wolf, shelf などで、roof, chief, safe, belief は -s を付けるだけである。roof は例外として個別に覚える。規則を当てはめる前に、例外リストに入っていないかを確認する習慣をつける。\"}]}",
"{\"id\":\"eigo_s089\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"複数形④：形が変わる語・変わらない語\",\"description\":\"man→men、child→children などの不規則複数形と、単複同形の語をまとめて覚える\",\"intro\":\"child の複数は childs ではなく children、foot は feet。しかも sheep は1匹でも100匹でも sheep のままです。数が形にあらわれない日本語とちがい、英語には形が変わる語と変わらない語があります。\",\"order\":589,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"母音が変わる型：man→men、woman→women、foot→feet、tooth→teeth、goose→geese、mouse→mice。\",\"-ren を付ける型：child→children、ox→oxen。\",\"単数も複数も同じ形：sheep、fish、deer、Japanese、Chinese。\",\"person の複数は people を使うのがふつう。people は常に複数あつかい。\",\"woman は単数「ウマン」、複数 women は「ウィミン」と読み方が変わる。\",\"children はすでに複数形なので childrens とは書かない。\"],\"sections\":[{\"heading\":\"不規則に変わる語\",\"mangaId\":\"eigo_s089_manga\",\"body\":\"-s も -es も付けず、語の形そのものが変わる名詞がある。数は十数語しかないので、まとめて丸暗記する。\\n\\n■ 母音が変わる型\\nman → men（男の人）\\nwoman → women（女の人）\\nfoot → feet（足）\\ntooth → teeth（歯）\\ngoose → geese（ガチョウ）\\nmouse → mice（ねずみ）\\n※ women は「ウィミン」と読む。単数 woman「ウマン」との発音のちがいが聞き取り問題で問われる。\\n\\n■ -ren / -en を付ける型\\nchild → children（子ども）\\nox → oxen（雄牛）\\n\\n■ 人を表す語\\nperson（人）の複数形は persons とも言えるが、ふつうは people を使う。\\n例）There are twenty people in the room.（部屋には20人いる）\\n⚠ 注意：people はそれ自体が複数あつかいなので、動詞は are / were になる。× There is many people. は誤り。\\n\\n■ 覚えるときのこつ\\nman / woman を含む語は同じように変化する。\\nEnglishman → Englishmen／policeman → policemen／businessman → businessmen\",\"figureId\":\"lf_eigoext03_089\"},{\"heading\":\"単数と複数が同じ形の語\",\"body\":\"複数になっても形が変わらない名詞がある。数を表すのは、前に付く数字や動詞の形である。\\n\\n■ 単複同形の語\\nsheep → sheep（羊）\\nfish → fish（魚）※種類を区別するときは fishes とすることもある\\ndeer → deer（しか）\\nJapanese → Japanese（日本人）\\nChinese → Chinese（中国人）\\n\\n例）I saw ten sheep in the field.（野原で羊を10ぴき見た）\\n例）There are many fish in this river.（この川には魚がたくさんいる）\\n例）Many Japanese visit Kyoto every year.（多くの日本人が毎年京都を訪れる）\\n\\n■ 見分け方\\n形が同じでも、数字・many・are などの手がかりで単複を判断できる。\\nThere is a sheep.（1ぴき）／There are five sheep.（5ひき）\\n\\n■ 国民を表す語の注意\\n-ese で終わる語（Japanese, Chinese, Vietnamese）は単複同形。\\n-an で終わる語（American, Italian, Korean）は -s を付ける。two Americans。\\n-man で終わる語（Englishman, Frenchman）は men に変わる。two Englishmen。\\n\\n★ ポイント：「羊・魚・しか・日本人は形が変わらない」と四つ並べて覚える。動物では sheep・fish・deer の三つ、人では -ese の語、と分けておけば整理しやすい。\"}],\"trapExamples\":[{\"question\":\"「私には子どもが3人います。」を英語にしなさい。\",\"wrongAnswer\":\"I have three childrens.\",\"trapExplanation\":\"「複数のときは -s」という規則が体にしみこんでいるため、すでに複数形になっている children にさらに -s を付けてしまう。children が child の複数形であることを忘れている。\",\"correctAnswer\":\"I have three children.\",\"correctExplanation\":\"child の複数形は children で、これ自体がすでに複数を表している。さらに -s を付けることはできない。同じく men, women, feet, teeth, people も、そのままで複数形なので -s を重ねない。× mens × peoples（peoples は「諸民族」という別の意味になる）。\"},{\"question\":\"（　）に is か are を入れなさい。　There （　） a lot of people in the park.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"people には -s が付いていないので単数だと考えて is を選んでしまう。「複数形には -s が付く」という思いこみが逆に働くひっかけである。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"people は -s が付いていなくても複数あつかいの語なので、動詞は are になる。person の複数として使われるためで、Many people were there. のように過去形でも were を使う。同じく単複同形の sheep も、five sheep are... と複数あつかいになる。\"}]}",
"{\"id\":\"eigo_s090\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"複数形⑤：-s の発音三種類\",\"description\":\"複数形の -s が [s]・[z]・[iz] のどれで読まれるかを区別できるようにする\",\"intro\":\"同じ -s なのに、cats は「ツ」に近く、dogs は「ズ」、buses では音のかたまりが1つ増えます。書けば同じ文字なのに、聞くと別ものに聞こえるのです。この読み分けは、動詞の -s にもそのまま当てはまります。\",\"order\":590,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"複数形の -s の読み方は三種類ある：[s]・[z]・[iz]。\",\"無声音（のどがふるえない音 p, k, t, f）のあとは [s]：books, cats, cups。\",\"有声音（のどがふるえる音や母音）のあとは [z]：dogs, pens, boys, cars。\",\"s, z, sh, ch, x, ge のあとは [iz] と読み、音のかたまりが一つふえる：buses, boxes, watches, oranges。\",\"同じ規則が、動詞の三人称単数の -s（likes, goes）にもそのまま当てはまる。\"],\"sections\":[{\"heading\":\"三つの読み方と、その決まり方\",\"mangaId\":\"eigo_s090_manga\",\"body\":\"複数形は書くときは -s / -es だが、読むときは三通りある。どれになるかは、-s の直前の音で自動的に決まる。\\n\\n■ ①[s] と読む（「ス」）\\n直前が、のどがふるえない音（無声音）のとき。p・k・t・f・th の音が代表。\\n例）books（ブックス）／cats（キャッツ）／cups（カップス）／maps（マップス）／months（マンス）／desks（デスクス）\\n\\n■ ②[z] と読む（「ズ」）\\n直前が、のどがふるえる音（有声音）や母音のとき。b・d・g・l・m・n・r・v の音や、母音で終わる語。\\n例）dogs（ドッグズ）／pens（ペンズ）／beds（ベッズ）／boys（ボーイズ）／cars（カーズ）／girls（ガールズ）／apples（アップルズ）\\n\\n■ ③[iz] と読む（「イズ」）\\n直前が s・z・sh・ch・x・ge の音のとき。この場合だけ、読むときの音のかたまりが一つふえる。\\n例）buses（バスィズ）／boxes（ボクスィズ）／watches（ウォッチィズ）／dishes（ディッシィズ）／oranges（オレンジィズ）／classes（クラスィズ）\\n\\n■ 確かめ方\\nのどに手を当てて、-s の直前の音を出してみる。ふるえれば [z]、ふるえなければ [s]。s や sh の音で終わっていれば [iz]。\\n\\n★ ポイント：③は「-es と書く語はだいたい [iz]」と結びつけて覚えるとよい（orange のように e で終わる語も含む）。\",\"figureId\":\"lf_eigoext03_090\"},{\"heading\":\"入試での問われ方と、動詞への応用\",\"body\":\"発音の問題は、英語入試を実施する中学校でよく出る。「下線部の発音が他と異なるものを選べ」という形式が定番である。\\n\\n■ 出題例\\n次のうち、下線部の -s の発音が他と異なるものを選びなさい。\\n　ア books　イ cats　ウ dogs　エ maps\\n答え：ウ dogs（[z]。ほかは [s]）\\n\\n次のうち、-s の発音が他と異なるものを選びなさい。\\n　ア boxes　イ dishes　ウ watches　エ apples\\n答え：エ apples（[z]。ほかは [iz]）\\n\\n■ 動詞にも同じ規則が当てはまる\\n三人称単数の -s も、まったく同じ三分類になる。\\n[s]：likes（ライクス）／works（ワークス）／stops（ストップス）\\n[z]：plays（プレイズ）／runs（ランズ）／goes（ゴーズ）／reads（リーズ）\\n[iz]：watches（ウォッチィズ）／washes（ウォッシィズ）／teaches（ティーチィズ）／uses（ユーズィズ）\\n\\n■ 過去形 -ed も同じ考え方\\n[t]：worked／stopped　　[d]：played／opened　　[id]：wanted／needed\\n「直前の音がふるえるかどうか」で決まる点は共通である。\\n\\n⚠ 注意：つづりだけを見て判断しないこと。決めているのは文字ではなく音である。months は th の音（無声音）のあとなので [s]、oranges は ge の音のあとなので [iz] になる。\"}],\"trapExamples\":[{\"question\":\"buses は、bus と比べて音のかたまり（音節）がふえますか。\",\"wrongAnswer\":\"ふえない（bus と同じ長さで「バス」と読む）\",\"trapExplanation\":\"日本語では「バス」も「バスたち」も音の数がほとんど変わらないので、-es が付いても読み方は変わらないと考えてしまう。書くときだけ e を足すものだと思いこむのが原因。\",\"correctAnswer\":\"ふえる（「バスィズ」と、音のかたまりが一つふえる）\",\"correctExplanation\":\"s・z・sh・ch・x で終わる語に -es を付けると、[iz] と読まれて音のかたまりが一つふえる。bus は1音節、buses は2音節になる。boxes, watches, dishes, classes も同じで、読むときに必ず「イズ」の音が加わる。この音がふえることが -es と書く理由でもある。\"},{\"question\":\"dogs の下線部 s の発音は、cats の s の発音と同じですか。\",\"wrongAnswer\":\"同じ（どちらも「ス」と読む）\",\"trapExplanation\":\"つづりがどちらも -s なので、読み方も同じだと考えてしまう。カタカナで「ドッグス」「キャッツ」と覚えていると、ちがいに気づけない。\",\"correctAnswer\":\"ちがう（dogs は [z]「ズ」、cats は [s]「ス」）\",\"correctExplanation\":\"-s の読み方は直前の音で決まる。dog の g はのどがふるえる有声音なので [z]、cat の t はふるえない無声音なので [s] になる。pens・boys・cars は [z]、books・maps・cups は [s]。のどに手を当てて直前の音を確かめると、確実に判断できる。\"}]}",
"{\"id\":\"eigo_s091\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"入れ物で数える：a glass of / a cup of\",\"description\":\"飲み物など、入れ物のことばを借りて数えられない名詞を数える言い方を身につける\",\"intro\":\"「水を2杯ください」を Two waters, please. と言いたくなりますが、教科書では two glasses of water と習います。water は数えられないので、入れ物のことばを借りて数えるのです。複数形にするのは glass のほうです。\",\"order\":591,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"数えられない名詞は「単位のことば＋of＋名詞」で数える。\",\"冷たい飲み物は a glass of（水・牛乳・ジュース）、温かい飲み物は a cup of（コーヒー・紅茶・お茶）。\",\"びん入りは a bottle of、かん入りは a can of、わん・どんぶりは a bowl of。\",\"単位のことばは数えられる名詞なので、これを複数形にする（two glasses of water）。\",\"of の後ろの名詞は不可算のまま。× two glasses of waters。\"],\"sections\":[{\"heading\":\"入れ物のことばを借りる\",\"body\":\"water は数えられない。しかし現実には「水を2はい飲んだ」と言いたい場面がある。そこで英語は、水そのものではなく、水を入れた入れ物のほうを数える。\\n\\n■ 基本の形\\n　単位のことば ＋ of ＋ 数えられない名詞\\n例）a glass of water（コップ1ぱいの水）\\n例）a cup of coffee（カップ1ぱいのコーヒー）\\n例）a bottle of milk（びん1本の牛乳）\\n\\n■ glass と cup の使い分け\\nglass＝ガラスのコップ。冷たい飲み物に使う。\\n　a glass of water（水）／a glass of milk（牛乳）／a glass of juice（ジュース）／a glass of orange juice\\ncup＝取っ手のついた温かい飲み物用のカップ。\\n　a cup of coffee（コーヒー）／a cup of tea（紅茶・お茶）／a cup of hot chocolate（ココア）\\n★ ポイント：「冷たい＝glass、温かい＝cup」で覚える。a cup of water とは、ふつう言わない。\\n\\n■ そのほかの入れ物\\na bottle of water（ペットボトル・びん1本の水）\\na can of coffee（かん1本のコーヒー）\\na bowl of rice（茶わん1ぱいのごはん）／a bowl of soup（スープ1ぱい）\\na spoonful of sugar（スプーン1ぱいの砂糖）\\na glass of wine ではなく、子ども向けの入試では飲み物は水・牛乳・ジュース・コーヒー・紅茶で十分である。\",\"figureId\":\"xf_eigo_s091\"},{\"heading\":\"数をふやすとき・たずねるとき\",\"body\":\"この形で数をふやすときに、どちらの語を複数形にするのかが最大の急所になる。\\n\\n■ 複数にするのは「単位のことば」のほう\\na glass of water → two glasses of water（コップ2はいの水）\\na cup of tea → three cups of tea（カップ3ばいの紅茶）\\na bottle of milk → five bottles of milk（びん5本の牛乳）\\n⚠ 注意：water・tea・milk は数えられない名詞のままなので、-s は付けない。× two glasses of waters は誤り。\\n\\n■ たずね方\\n数をたずねる：How many glasses of water do you drink every day?（1日にコップ何ばいの水を飲みますか）\\n量をたずねる：How much water do you drink every day?（1日にどのくらい水を飲みますか）\\nどちらも正しい文だが、How many の後ろには数えられる語 glasses が来る点がちがう。\\n\\n■ 注文するときの言い方\\n店では、a coffee のように短く言うこともあるが、これは「a cup of coffee」を省略した会話表現である。テストの答案では a cup of coffee と正しく書く。\\n\\n■ 会話でよく使う形\\nWould you like a cup of tea?（紅茶を1ぱいいかがですか）\\nCan I have a glass of water, please?（お水を1ぱいいただけますか）\\nI drink two glasses of milk every morning.（毎朝、牛乳をコップ2はい飲みます）\",\"mangaId\":\"eigo_s091_xm\"}],\"trapExamples\":[{\"question\":\"「私は毎朝、水をコップ2はい飲みます。」を英語にしなさい。\",\"wrongAnswer\":\"I drink two glass of waters every morning.\",\"trapExplanation\":\"「水を2はい」の「2」が water にかかっていると考えて、water のほうに -s を付けてしまう。英語では数えているのがコップのほうだという発想の切りかえができていない。\",\"correctAnswer\":\"I drink two glasses of water every morning.\",\"correctExplanation\":\"数えられるのは入れ物である glass のほうなので、複数形にするのは glasses。water は数えられない名詞のままなので -s を付けない。two cups of coffee、three bottles of milk も同じ形になる。「複数形になるのは of の前」と覚える。\"},{\"question\":\"「コーヒーを1ぱいいかがですか。」を英語にしなさい。\",\"wrongAnswer\":\"Would you like a glass of coffee?\",\"trapExplanation\":\"a glass of water を先に覚えると、飲み物はすべて glass で数えると思いこんでしまう。日本語の「1ぱい」が入れ物を区別しないことも原因である。\",\"correctAnswer\":\"Would you like a cup of coffee?\",\"correctExplanation\":\"glass は冷たい飲み物用のガラスのコップ、cup は温かい飲み物用の取っ手つきのカップを表す。コーヒー・紅茶・お茶は a cup of、水・牛乳・ジュースは a glass of を使う。入れ物の形を思いうかべて選ぶ。\"}]}",
"{\"id\":\"eigo_s092\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形で数える：a piece of / a sheet of / a slice of\",\"description\":\"紙・パン・助言など、切り分けたひとまとまりを表す単位のことばを使い分ける\",\"intro\":\"「アドバイスを1つ」を an advice とは言えません。advice は数えられないからです。代わりに a piece of advice と言います。紙・パン・情報など、ひとまとまりを表すことばの使い分けを学びます。\",\"order\":592,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"a piece of は最も広く使える万能の単位（紙・ケーキ・助言・情報・家具・チョーク）。\",\"a sheet of＝紙などの薄い1枚。a slice of＝パン・チーズ・ピザなど薄く切った1枚。\",\"a loaf of bread＝パン1斤（切る前のかたまり）。a bar of chocolate＝板チョコ1枚。\",\"advice・information・news・furniture は a piece of で数える（× an advice）。\",\"a paper は「新聞・答案」の意味になるので、「紙1枚」は a sheet of paper とする。\"],\"sections\":[{\"heading\":\"万能の a piece of\",\"body\":\"入れ物のない物を数えるときは、「1つ分のかたまり」を表す piece を借りる。piece は「かけら・1片」という意味の数えられる名詞である。\\n\\n■ a piece of ＋ 数えられない名詞\\na piece of paper（紙1枚）\\na piece of cake（ケーキ1切れ）\\na piece of chalk（チョーク1本）\\na piece of furniture（家具1点）\\na piece of advice（助言1つ）\\na piece of information（情報1つ）\\na piece of news（ニュース1つ）\\na piece of music（楽曲1曲）\\n\\n例）He gave me a piece of good advice.（彼はよい助言を一つくれた）\\n例）I need two pieces of paper.（紙が2枚いる）\\n\\n■ なぜ a piece of が必要か\\nadvice や information は「助言というもの全体」を表すので、そのままでは数えられない。そこから「一つ分」を取り出す働きをするのが a piece of である。\\n⚠ 注意：× an advice／× two informations は誤り。必ず a piece of advice／two pieces of information とする。\\n\\n★ ポイント：単位のことばが思いつかないときは a piece of を使えば、たいていの不可算名詞に対応できる。まずこの形を確実にする。\",\"figureId\":\"xf_eigo_s092\",\"mangaId\":\"eigo_s092_xm\"},{\"heading\":\"物ごとに決まった単位のことば\",\"body\":\"より正確に言うために、物ごとに決まった単位を使うことがある。よく出るものだけ覚える。\\n\\n■ 紙\\na sheet of paper（紙1枚）…薄い1枚をさす、いちばんふつうの言い方\\na piece of paper（紙1枚・紙きれ）\\n⚠ 注意：a paper は「新聞」「答案・論文」の意味になる。I read a paper.（新聞を読む）。「紙が1枚ほしい」を I want a paper. と書くと意味が変わってしまう。\\n\\n■ パン・食べ物\\na slice of bread（うすく切ったパン1枚）\\na loaf of bread（切る前のパン1斤）\\na slice of cheese（チーズ1枚）／a slice of pizza（ピザ1切れ）\\na piece of cake（ケーキ1切れ）\\na bar of chocolate（板チョコ1枚）／a bar of soap（せっけん1個）\\n\\n■ 粉・つぶ\\na spoonful of sugar（スプーン1ぱいの砂糖）\\na grain of rice（米1つぶ）\\n\\n■ 服・くつ\\na pair of shoes（くつ1足）※次のセッションでくわしく学ぶ\\n\\n■ 例文で確かめる\\nPlease give me a sheet of paper.（紙を1枚ください）\\nI ate two slices of bread for breakfast.（朝食にパンを2枚食べた）\\nShe bought a loaf of bread at the bakery.（彼女はパン屋でパンを1斤買った）\"}],\"trapExamples\":[{\"question\":\"「彼は私によい助言を一つくれた。」を英語にしなさい。\",\"wrongAnswer\":\"He gave me a good advice.\",\"trapExplanation\":\"日本語で「助言を一つ」と数えられるので、そのまま a を付けてしまう。advice が数えられない名詞であることを見落とすのが原因で、an advice と書く誤りも多い。\",\"correctAnswer\":\"He gave me a piece of good advice.（He gave me some good advice. も可）\",\"correctExplanation\":\"advice は不可算名詞なので a も複数形も付けられない。「一つ」と数えたいときは a piece of advice とする。information, news, furniture も同じで、two pieces of information、a piece of furniture となる。数えないなら some advice でよい。\"},{\"question\":\"「紙を1枚ください。」を英語にしなさい。\",\"wrongAnswer\":\"Please give me a paper.\",\"trapExplanation\":\"paper を「紙」とだけ覚えていると、数えられる名詞のつもりで a を付けてしまう。しかも a paper という形自体は英語として存在するので、誤りに気づきにくい。\",\"correctAnswer\":\"Please give me a sheet of paper.（a piece of paper も可）\",\"correctExplanation\":\"「紙」の意味の paper は不可算名詞なので、1枚と数えるときは a sheet of paper か a piece of paper とする。a paper と言うと「新聞」または「答案・論文」という別の意味になってしまう。数えられる意味と数えられない意味を持つ語の代表例である。\"}]}",
"{\"id\":\"eigo_s093\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"二つで一組：a pair of\",\"description\":\"shoes・glasses・scissors など、いつも複数形で使う語と、その数え方を覚える\",\"intro\":\"くつは2つで1組なので、英語ではいつも shoes と複数形です。めがねもはさみもズボンも同じです。1足だけ言いたいときは a pair of shoes と言います。日本語の「1足」「1本」に近い発想ですね。\",\"order\":593,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"左右そろって一組になる物は、いつも複数形で使う（shoes, socks, gloves, glasses, scissors, pants, jeans）。\",\"数えるときは a pair of＋複数形（a pair of shoes＝くつ1足）。\",\"2組以上なら pair のほうを複数形にする（two pairs of shoes）。\",\"これらの語が主語になると、動詞は are・were になる（My glasses are new.）。\",\"a pair of ～ が主語のときは pair が単数なので is を使う（A pair of shoes is on the floor.）。\"],\"sections\":[{\"heading\":\"いつも複数形で使う語\",\"mangaId\":\"eigo_s093_manga\",\"body\":\"英語では、左右または二つの部分がそろって初めて役に立つ物を、いつも複数形で表す。\\n\\n■ 代表的な語\\nshoes（くつ）／socks（くつ下）／gloves（手ぶくろ）／glasses（めがね）／scissors（はさみ）／pants・trousers（ズボン）／jeans（ジーンズ）／shorts（半ズボン）／chopsticks（はし）\\n\\n■ なぜ複数形なのか\\nくつは左右2つで1足、めがねはレンズが2枚、はさみは刃が2枚、ズボンは足を通す部分が2本ある。英語は「2つの部分でできている」という見方をそのまま形に表す。日本語の「はさみ」「めがね」に複数の意味がないので、日本人には感覚がつかみにくい。\\n\\n■ 数えたいときは a pair of\\na pair of shoes（くつ1足）\\na pair of socks（くつ下1足）\\na pair of glasses（めがね1つ）\\na pair of scissors（はさみ1ちょう）\\ntwo pairs of shoes（くつ2足）\\n⚠ 注意：複数形になるのは pair のほう。shoes は最初から複数形なので、そのままにしておく。× two pair of shoes／× two pairs of shoe はどちらも誤り。\\n\\n★ ポイント：a scissors・a shoe とは言えない。「1つ」と言いたいときは必ず a pair of を使う。ただし a shoe（かた方のくつ）という言い方自体は、かた方だけをさすときには使える。\",\"figureId\":\"xf_eigo_s093\"},{\"heading\":\"主語になったときの動詞\",\"body\":\"これらの語が主語になると、動詞の形をまちがえやすい。何が主語の中心かを見きわめる。\\n\\n■ そのまま主語になる場合 → 複数あつかい\\nMy glasses are new.（私のめがねは新しい）\\nThese scissors are very sharp.（このはさみはとてもよく切れる）\\nWhere are my socks?（私のくつ下はどこですか）\\nYour shoes were under the table.（あなたのくつはテーブルの下にあった）\\n\\n■ a pair of ～ が主語の場合 → pair の数に合わせる\\nA pair of shoes is on the floor.（くつが1足、ゆかに置いてある）\\nTwo pairs of gloves are in the box.（手ぶくろが2組、箱に入っている）\\n※ 主語の中心は pair なので、a pair なら単数あつかいになる。\\n\\n■ this / that との組み合わせ\\n× this scissors → these scissors／this pair of scissors\\n× that glasses → those glasses／that pair of glasses\\n\\n■ よく出る文\\nI bought a pair of new shoes yesterday.（きのう新しいくつを1足買った）\\nHe wears glasses.（彼はめがねをかけている）※ wear glasses は無冠詞・複数形で使う決まった言い方\\nPlease pass me the scissors.（はさみを取ってください）\"}],\"trapExamples\":[{\"question\":\"「私ははさみを1ちょう持っています。」を英語にしなさい。\",\"wrongAnswer\":\"I have a scissors.\",\"trapExplanation\":\"日本語では「はさみ1ちょう」と単数で数えるので、そのまま a を付けてしまう。scissors の -s を複数形の -s だと気づかず、単語の一部だと思いこむことも多い。\",\"correctAnswer\":\"I have a pair of scissors.\",\"correctExplanation\":\"scissors は2枚の刃でできているため、いつも複数形で使う語である。a を直接付けることはできず、1つと数えるときは a pair of scissors とする。glasses（めがね）、pants（ズボン）も同じで、a pair of glasses、a pair of pants となる。\"},{\"question\":\"（　）に is か are を入れなさい。　My glasses （　） new.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"めがねは1つの品物なので単数だと考えて is を選んでしまう。日本語の感覚では「めがねが1つ」なので、複数あつかいだと気づきにくい。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"glasses は形の上でも意味の上でも複数なので、主語になれば動詞は are になる。These scissors are sharp. も同じ。ただし A pair of glasses is on the desk. のように a pair of が主語のときは、中心の語が pair（単数）なので is を使う。何が主語の中心かで判断する。\"}]}",
"{\"id\":\"eigo_s094\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数え方の総整理：複数にするのはどちらか\",\"description\":\"単位＋of＋不可算名詞の形で、複数形にする語と数のたずね方を完全に固める\",\"intro\":\"two glasses of water の -s は、glass に付いて water には付きません。どちらを複数形にするか迷ったら、数えているのはどちらかを考えます。たずね方も How many と How much で変わります。\",\"order\":594,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"「単位のことば＋of＋不可算名詞」では、複数形にするのは単位のことばだけ。\",\"two glasses of milk／three cups of tea／five pieces of paper／two pairs of shoes。\",\"of の後ろの不可算名詞は、いくつになっても形を変えない。\",\"数をたずねるときは How many＋単位の複数形（How many cups of coffee ...?）。\",\"量をたずねるときは How much＋不可算名詞（How much coffee ...?）。\",\"主語になったときは単位のことばの数に合わせて動詞を決める。\"],\"sections\":[{\"heading\":\"複数形にする位置をまちがえない\",\"body\":\"ここまで学んだ数え方を、一つの表にまとめて確認する。まちがいはほとんど「どちらを複数形にするか」で起きる。\\n\\n■ 正しい形\\na glass of water　→　two glasses of water\\na cup of coffee　→　three cups of coffee\\na bottle of milk　→　four bottles of milk\\na piece of paper　→　five pieces of paper\\na slice of bread　→　six slices of bread\\na pair of shoes　→　two pairs of shoes\\n\\n■ よくある誤り\\n× two glass of water（単位が複数形になっていない）\\n× two glasses of waters（不可算名詞に -s を付けている）\\n× two glass of waters（両方まちがえている）\\n\\n■ なぜそうなるのか\\n数えているのは、あくまで入れ物やかたまりのほうである。水そのものは相変わらず数えられない。だから -s が付くのは of の前だけになる。\\n★ ポイント：「-s は of の前に付く」と一言で覚えてしまう。作文の見直しでは of を探し、その左の語に -s があるかを確認する。\",\"figureId\":\"lf_eigoext03_094\",\"mangaId\":\"eigo_s094_xm\"},{\"heading\":\"たずね方と動詞の一致\",\"body\":\"数え方の形は、疑問文や主語になったときにも影響する。\\n\\n■ 数をたずねる（How many）\\nHow many cups of coffee do you drink a day?（1日に何ばいコーヒーを飲みますか）\\n　→ 答え：I drink two cups of coffee a day.\\nHow many pieces of paper do you need?（紙は何枚必要ですか）\\n※ How many の直後には、数えられる語の複数形（cups, pieces, glasses）が来る。\\n\\n■ 量をたずねる（How much）\\nHow much coffee do you drink a day?（1日にどのくらいコーヒーを飲みますか）\\n　→ 答え：I drink a lot of coffee.\\n※ How much の直後には、不可算名詞（coffee, water, money, time）が来る。\\n⚠ 注意：× How many coffee ...? は誤り。coffee をそのまま数えることはできない。\\n\\n■ 主語になったとき\\nA glass of water is on the table.（コップ1ぱいの水がテーブルにある）…中心は a glass（単数）→ is\\nTwo glasses of water are on the table.（コップ2はいの水が…）…中心は glasses（複数）→ are\\nThree pieces of cake were left.（ケーキが3切れ残っていた）\\n\\n■ 総まとめの例文\\nI bought a loaf of bread, two bottles of milk, and three pairs of socks.\\n（パンを1斤、牛乳を2本、くつ下を3足買った）\\nこの一文の中に、単位を複数にする規則がすべて入っている。声に出して覚えるとよい。\"}],\"trapExamples\":[{\"question\":\"「私は毎朝、紅茶をカップ3ばい飲みます。」を英語にしなさい。\",\"wrongAnswer\":\"I drink three cup of teas every morning.\",\"trapExplanation\":\"日本語の「3ばいの紅茶」につられて、紅茶のほうを複数形にし、単位の cup をそのままにしてしまう。-s を付ける位置が日本語と英語で逆になる点でつまずく。\",\"correctAnswer\":\"I drink three cups of tea every morning.\",\"correctExplanation\":\"複数形にするのは単位のことば cup のほうで、tea は不可算名詞なので形を変えない。「-s は of の前」と覚えると確実である。two glasses of water、five pieces of paper もすべて同じ形になる。\"},{\"question\":\"「あなたは1日にどのくらいコーヒーを飲みますか。」を英語にしなさい。\",\"wrongAnswer\":\"How many coffee do you drink a day?\",\"trapExplanation\":\"日本語の「どのくらい」を「いくつ」と同じに考えて How many を選んでしまう。coffee に -s が付いていないのに How many を使っている点にも気づきにくい。\",\"correctAnswer\":\"How much coffee do you drink a day?（How many cups of coffee do you drink a day? も可）\",\"correctExplanation\":\"coffee は不可算名詞なので、量をたずねる How much を使う。数をたずねたいなら、数えられる単位を入れて How many cups of coffee ...? とする。How many の直後には必ず複数形の数えられる語が来る、という形で見分ける。\"}]}",
"{\"id\":\"eigo_s095\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a / an の基本：初めて話に出す「一つの」\",\"description\":\"数えられる名詞の単数に付ける a・an の意味と、使う場面を理解する\",\"intro\":\"I am student. では英語になりません。数えられる名詞が1つのときは、裸のまま置けないからです。a には「まだ相手の知らない1つ」という意味があります。日本語に冠詞はないので、意識して付ける練習が要ります。\",\"order\":595,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"a / an は「一つの」「ある〜」を表し、数えられる名詞の単数にだけ付く。\",\"もともと one から生まれた語なので、複数形や不可算名詞には付けられない。\",\"話に初めて出す物、相手がどれのことかまだ知らない物に使う。\",\"職業や身分を言うときは a を付ける（She is a teacher.／He is a doctor.）。\",\"「〜というものが好き」と全体を言うときは、a ではなく複数形を使う（I like dogs.）。\"],\"sections\":[{\"heading\":\"a / an の意味と使い方\",\"mangaId\":\"eigo_s095_manga\",\"body\":\"a / an を冠詞という。日本語にはない品詞なので、意味を正しくつかんでおく必要がある。\\n\\n■ 意味①「一つの」\\na はもともと one（1）から生まれた語である。だから数えられる名詞の単数にしか付かない。\\n例）I have a dog.（犬を1ぴき飼っている）\\n例）There is a book on the desk.（つくえの上に本が1冊ある）\\n\\n■ 意味②「ある〜」（どれかは特定しない）\\n話し手も聞き手も、まだどれのことか決めていないときに使う。\\n例）A boy is running in the park.（1人の男の子が公園を走っている）\\n※ どの男の子かは、聞き手にはまだわからない。\\n\\n■ 付けられない相手\\n複数形には付けられない：× a books\\n数えられない名詞には付けられない：× a water／× a music\\nすでに my・this・the が付いているものには付けられない：× a my bag\\n\\n■ 職業・身分を言うとき\\n英語では、職業を言うときに a を付ける。日本語には対応する語がないので忘れやすい。\\n例）She is a teacher.（彼女は先生です）\\n例）My father is a doctor.（父は医者です）\\n例）I want to be a soccer player.（サッカー選手になりたい）\\n\\n★ ポイント：a は「数えられる／単数／まだ特定されていない」の三条件がそろったときに使う、と整理しておく。\",\"figureId\":\"xf_eigo_s095\"},{\"heading\":\"「〜というもの」を表す言い方\",\"body\":\"「犬が好きです」のように、特定の1ぴきではなく種類全体を表したいときは、言い方に注意がいる。\\n\\n■ ふつうは複数形を使う\\n例）I like dogs.（犬が好きです）\\n例）Dogs are friendly animals.（犬は人なつこい動物だ）\\n例）I don't like tomatoes.（トマトは好きではない）\\n「犬というもの全体」を表すには、複数形にするのがいちばん自然である。\\n\\n■ a を使うと「1ぴきの犬」になる\\nI like a dog. と書くと、「ある特定の1ぴきの犬が好き」という不自然な意味になってしまう。\\n⚠ 注意：好ききらいを言う文では、数えられる名詞は複数形にすると覚えておくと安全である。\\n例）Do you like cats?（ねこは好きですか）\\n例）She likes apples.（彼女はりんごが好きだ）\\n\\n■ 数えられない名詞ならそのまま\\nI like music.／I like water.（× a music／× a water）\\n\\n■ a に「〜というものは」の意味がある場合\\nA dog is a friendly animal.（犬というものは人なつこい動物だ）\\nこのように、1ぴきを代表として全体を表す使い方もある。中学入試ではまれだが、読解で出てきたら「犬というものは」と訳す。\\n\\n■ まとめの例文\\nI have a dog. It is very cute.（犬を1ぴき飼っている。とてもかわいい）\\nI like dogs very much.（犬が大好きだ）\\nMy uncle is a vet. He takes care of dogs and cats.（おじは獣医だ。犬やねこの世話をしている）\"}],\"trapExamples\":[{\"question\":\"「彼女は先生です。」を英語にしなさい。\",\"wrongAnswer\":\"She is teacher.\",\"trapExplanation\":\"日本語の「先生です」には a にあたる語がないので、そのまま単語を並べてしまう。職業名は名前のようなものだと感じて、冠詞がいらないと思いこむことも多い。\",\"correctAnswer\":\"She is a teacher.\",\"correctExplanation\":\"職業や身分を表す語は数えられる名詞なので、単数のときは a / an を付ける。He is a doctor. / I am a student. / My brother is an engineer. も同じ。ただし複数のときは付けない（They are teachers.）。\"},{\"question\":\"「私は犬が好きです。」を英語にしなさい。\",\"wrongAnswer\":\"I like a dog.\",\"trapExplanation\":\"「数えられる名詞の単数には a」という規則だけを機械的に当てはめてしまう。日本語の「犬が好き」が単数か複数かを区別しないため、a dog で正しいと感じてしまう。\",\"correctAnswer\":\"I like dogs.\",\"correctExplanation\":\"好ききらいを言うときは、その種類全体をさすので複数形を使う。I like a dog. は「ある特定の1ぴきの犬が好き」という意味になり不自然。Do you like cats? / She likes apples. も同じ形になる。数えられない名詞なら I like music. のようにそのまま使う。\"}]}",
"{\"id\":\"eigo_s096\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a と an は「音」で決まる\",\"description\":\"つづりではなく発音で a・an を選ぶ原則と、まぎらわしい語を確実にする\",\"intro\":\"an hour はつづりが h で始まるのに an を使い、a university は u で始まるのに a を使います。決めているのはつづりではなく最初の音です。hour の h は読まず、university は「ユ」で始まるからです。\",\"order\":596,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"母音の音（ア・イ・ウ・エ・オ）で始まる語の前は an、それ以外は a。\",\"決めるのはつづりではなく発音である。\",\"つづりが子音字でも an：an hour（h を読まない）／an honest boy。\",\"つづりが母音字でも a：a university（ユ）／a uniform（ユ）／a useful book（ユ）／a European country（ユ）。\",\"a / an は、名詞ではなく「すぐ後ろに来る語」の音で決まる（an old book → a nice old book）。\"],\"sections\":[{\"heading\":\"原則は音で決まる\",\"mangaId\":\"eigo_s096_manga\",\"body\":\"a と an のどちらを使うかは、次に来る語の最初の「音」で決まる。母音の音で始まるなら an、そうでないなら a である。\\n\\n■ an を使う（母音の音で始まる語）\\nan apple（りんご）／an egg（たまご）／an orange（オレンジ）／an umbrella（かさ）／an island（島）／an animal（動物）／an old man（おじいさん）／an easy question（やさしい問題）\\n\\n■ a を使う（子音の音で始まる語）\\na book／a cat／a desk／a pen／a young boy／a good idea\\n\\n■ なぜ an が必要なのか\\na apple と続けて言うと「ア・アップル」となって発音しにくい。そこで n をはさんで「アナップル」と言いやすくしている。読みやすくするための工夫だと理解すれば、規則が自然に感じられる。\\n\\n■ 気をつける語①：つづりは子音字なのに an\\nhour（時間）／honest（正直な）／honor（名誉）\\nこれらは h を発音しない。an hour は「アナワー」と読む。\\n例）I waited for an hour.（1時間待った）\\n例）He is an honest boy.（彼は正直な少年だ）\\n\\n■ 気をつける語②：つづりは母音字なのに a\\nuniversity（大学）／uniform（制服）／useful（役に立つ）／union（組合）／European（ヨーロッパの）\\nこれらは「ユ」という子音の音で始まる。\\n例）My sister goes to a university.（姉は大学に通っている）\\n例）This is a very useful book.（これはとても役に立つ本だ）\",\"figureId\":\"lf_eigoext03_096\"},{\"heading\":\"直後の語で決まる\",\"body\":\"a / an を決めるのは、名詞そのものではなく、a / an のすぐ後ろに来る語である。名詞の前に形容詞が入ると、判断の相手が変わる。\\n\\n■ 形容詞が入ると変わる例\\nan apple（りんご）→ a red apple（赤いりんご）\\n　※ red は子音の音で始まるので a になる。\\na book（本）→ an interesting book（おもしろい本）\\n　※ interesting は母音の音で始まるので an になる。\\nan old book（古い本）→ a nice old book（すてきな古い本）\\n　※ 判断するのは old ではなく nice。\\n\\n■ 例文で確かめる\\nHe has an egg.（たまごを1つ持っている）\\nHe has a fresh egg.（新しいたまごを1つ持っている）\\nShe is an English teacher.（彼女は英語の先生だ）\\nShe is a good English teacher.（彼女はよい英語の先生だ）\\n\\n■ 数字やアルファベットの前\\nan hour（1時間）／an eight-year-old boy（8歳の少年）／an A（Aという文字）／an F\\n※ 文字は名前を読んだときの音で決める。A は「エイ」、F は「エフ」なので an。B は「ビー」なので a B。\\n\\n★ ポイント：作文の見直しでは、a / an の右どなりの語を声に出して読んでみる。「ア・イ・ウ・エ・オ」の音で始まっていれば an、そうでなければ a。この一手間で確実に正解できる。\\n\\n⚠ 注意：an を使うのは母音の「音」であって、母音字ではない。university を an university と書くのは、つづりだけを見た典型的な誤りである。\"}],\"trapExamples\":[{\"question\":\"（　）に a か an を入れなさい。　I waited for （　） hour.\",\"wrongAnswer\":\"a hour\",\"trapExplanation\":\"hour は h という子音字で始まっているので、つづりだけを見て a を選んでしまう。「母音字なら an」という覚え方をしていると必ず引っかかる。\",\"correctAnswer\":\"an hour\",\"correctExplanation\":\"hour の h は発音しないため、「アワー」と母音の音で始まる。したがって an を使う。決めるのはつづりではなく音である。an honest boy（正直な少年）も同じ理由で an になる。声に出して読んで確かめる習慣をつける。\"},{\"question\":\"an old book に nice を加えて「すてきな古い本」とするとき、正しい形を書きなさい。\",\"wrongAnswer\":\"an nice old book\",\"trapExplanation\":\"もとの形が an old book なので、an は old ではなく book に付いていると思いこみ、そのまま an を残してしまう。a / an が「すぐ後ろの語」で決まることを意識していないのが原因。\",\"correctAnswer\":\"a nice old book\",\"correctExplanation\":\"a / an を決めるのは、直後に来る語の音である。nice は子音の音で始まるので a になる。逆に a book に interesting を加えると an interesting book になる。形容詞を入れたら、必ず a / an を選び直す。\"}]}",
"{\"id\":\"eigo_s097\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a / an を付けてはいけない場面\",\"description\":\"所有格・指示語・不可算名詞・スポーツや教科の名前など、冠詞を付けない場合を整理する\",\"intro\":\"「私の友達」を a my friend と言ってしまう人は多いのですが、これは誤りです。my がすでにどれかを決めているので、a を重ねられません。正しくは a friend of mine。付けない場面をまとめて確かめます。\",\"order\":597,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"my・your・his・this・that・John’s などが付く名詞に、a / an は重ねない（× a my bag）。\",\"「私の友達の一人」は a friend of mine と言う（× a my friend）。\",\"不可算名詞・複数形には a / an を付けない。\",\"スポーツ名・教科名・食事名は冠詞なし（play tennis／study math／have lunch）。\",\"固有名詞にも冠詞を付けない（× a Tokyo）。\"],\"sections\":[{\"heading\":\"所有格・指示語とは重ねられない\",\"mangaId\":\"eigo_s097_manga\",\"body\":\"名詞の前に置ける「限定することば」は、原則として一つだけである。a / an と my / this などは、同じ位置を取り合うため並べられない。\\n\\n■ 並べられない組み合わせ\\n× a my bag　→　my bag（私のかばん）\\n× a this book　→　this book（この本）\\n× the my house　→　my house（私の家）\\n× a Ken’s pen　→　Ken’s pen（ケンのペン）\\n\\n■ 「私のかばんの一つ」と言いたいとき\\n「一つの」と「私の」を両方言いたい場合は、of の形を使う。\\n例）a friend of mine（私の友達の一人）\\n例）a book of mine（私の本の一冊）\\n⚠ 注意：of の後ろは所有代名詞（mine, yours, his, hers, ours, theirs）にする。× a friend of my は誤り。\\n\\n■ 例文\\nHe is a friend of mine.（彼は私の友達の一人です）\\nShe is one of my friends.（同じ意味の別の言い方）\\nThis is my favorite book.（これは私のいちばん好きな本です）\\n\\n★ ポイント：名詞の前に my・your・this・that・所有格の 's があったら、a / an / the は不要である。作文の見直しでは、名詞の前に限定することばが二つ並んでいないか確かめる。\",\"figureId\":\"xf_eigo_s097\"},{\"heading\":\"冠詞を付けない決まった言い方\",\"body\":\"決まった言い方として、名詞に冠詞を付けないものがある。まとめて覚えてしまう。\\n\\n■ スポーツ名\\nplay soccer／play tennis／play baseball／play basketball\\n例）I play tennis every Sunday.（毎週日曜日にテニスをする）\\n⚠ 注意：楽器のときは the が必要（play the piano）。次のセッションで学ぶ。\\n\\n■ 教科名・言語名\\nstudy math／study science／study English／speak Japanese\\n例）I study English every day.（毎日英語を勉強する）\\n\\n■ 食事の名前\\nhave breakfast／have lunch／have dinner／eat breakfast\\n例）I have breakfast at seven.（7時に朝食を食べる）\\n※ ただし形容詞が付くと a が必要になる。I had a big breakfast.（たっぷりの朝食を食べた）\\n\\n■ 季節・月・曜日\\nin spring／in April／on Monday\\n例）It is cold in winter.（冬は寒い）\\n\\n■ 固有名詞\\nJapan／Tokyo／Ken／Mt. Fuji\\n例）I live in Osaka.（× in an Osaka）\\n\\n■ 不可算名詞・複数形\\nI like music.／I have homework.／There are books on the desk.\\n\\n■ 交通手段・場所の決まり文句\\nby bus／by train／by car／at home／go to school／go to bed\\n例）I go to school by bus.（バスで学校へ行く）\\n\\n★ ポイント：「a を付けるかどうか迷ったら、まず数えられる名詞かどうか」→「次に、前に my や this がないか」→「最後に、決まった言い方でないか」の順に確かめる。\"}],\"trapExamples\":[{\"question\":\"「彼は私の友達の一人です。」を英語にしなさい。\",\"wrongAnswer\":\"He is a my friend.\",\"trapExplanation\":\"「一人の」を a、「私の」を my と、日本語の語をそのまま置きかえて並べてしまう。英語では a と my が同じ位置を取り合うため並べられない、という約束を知らないと必ず起きる誤り。\",\"correctAnswer\":\"He is a friend of mine.（He is one of my friends. も可）\",\"correctExplanation\":\"a / an と my・your・this などは重ねて使えない。「一つの」と「私の」を両方言いたいときは a friend of mine の形にする。of の後ろは所有代名詞 mine を使い、× a friend of my とはしない。\"},{\"question\":\"「私は先週の日曜日にテニスをしました。」を英語にしなさい。\",\"wrongAnswer\":\"I played a tennis last Sunday.\",\"trapExplanation\":\"「数えられる名詞の単数には a」という規則を、スポーツ名にも当てはめてしまう。play the piano という形を覚えていると、スポーツにも冠詞がいるように感じることもある。\",\"correctAnswer\":\"I played tennis last Sunday.\",\"correctExplanation\":\"スポーツ名は冠詞を付けずに使う決まった言い方である。play soccer, play baseball も同じ。一方で楽器には the が必要（play the piano）。教科名（study math）、食事名（have lunch）も冠詞なしで使う。セットで覚えておく。\"}]}",
"{\"id\":\"eigo_s098\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a を使った決まった言い方\",\"description\":\"once a week のような「〜につき」の a と、a を含む重要熟語をまとめて覚える\",\"intro\":\"「週に1回」は once a week。この a は「1つの」ではなく「〜につき」の意味です。同じ a なのに役目がちがいます。take a walk や have a good time など、a を含む決まった言い方もここでまとめます。\",\"order\":598,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"「〜につき」を表す a：once a week（週に1回）／three times a day（1日に3回）／sixty kilometers an hour（時速60キロ）。\",\"回数は once（1回）→ twice（2回）→ three times（3回）と数える。\",\"have a cold（風邪をひいている）／have a good time（楽しく過ごす）／take a bath（風呂に入る）／take a walk（散歩する）。\",\"in a hurry（急いで）／for a while（しばらくの間）／as a result（その結果）。\",\"a little（少しの）／a few（少しの）も a を含むひとまとまりの表現。\"],\"sections\":[{\"heading\":\"「〜につき」を表す a\",\"body\":\"a には「一つの」のほかに、「〜につき」という意味がある。回数や速さを言うときに使う。\\n\\n■ 回数の言い方\\nonce a week（週に1回）\\ntwice a week（週に2回）\\nthree times a week（週に3回）\\nfour times a month（月に4回）\\nonce a year（年に1回）\\n例）I play the piano twice a week.（週に2回ピアノをひく）\\n例）He goes to the library once a month.（彼は月に1回図書館へ行く）\\n\\n■ 回数の数え方に注意\\n1回＝once　　2回＝twice　　3回以上＝three times, four times ...\\n⚠ 注意：one time／two times と言うこともあるが、1回・2回は once, twice を使うのがふつうである。\\n\\n■ 速さ・単位あたりの量\\nsixty kilometers an hour（時速60キロ）\\nfive hundred yen a kilogram（1キロ500円）\\n例）This car runs at eighty kilometers an hour.（この車は時速80キロで走る）\\n\\n■ たずね方\\nHow often do you play tennis?（どのくらいの回数テニスをしますか）\\n　→ Three times a week.（週に3回です）\\n★ ポイント：How often（どのくらいの頻度で）とセットで覚えると、会話文の問題にそのまま使える。\",\"figureId\":\"lf_eigoext03_098\",\"mangaId\":\"eigo_s098_xm\"},{\"heading\":\"a を含む重要熟語\",\"body\":\"a が入って初めて意味が完成する、決まった言い方がある。a を落とすと誤りになるので、ひとまとまりで覚える。\\n\\n■ have を使うもの\\nhave a cold（風邪をひいている）\\nhave a good time（楽しく過ごす）\\nhave a headache（頭が痛い）\\nhave a fever（熱がある）\\n例）I have a cold today.（今日は風邪をひいている）\\n例）We had a good time at the party.（パーティーで楽しく過ごした）\\n\\n■ take を使うもの\\ntake a bath（風呂に入る）\\ntake a shower（シャワーを浴びる）\\ntake a walk（散歩する）\\ntake a rest（休む）\\ntake a look（見てみる）\\n例）I take a walk with my dog every morning.（毎朝、犬と散歩する）\\n\\n■ その他\\nin a hurry（急いで）\\nfor a while（しばらくの間）\\nas a result（その結果）\\na lot of（たくさんの）\\na little（少しの）／a few（少しの）\\nall of a sudden（突然）\\n例）He left in a hurry.（彼は急いで出て行った）\\n例）Please wait for a while.（しばらく待ってください）\\n\\n⚠ 注意：cold は「寒さ」の意味なら不可算だが、「風邪」の意味では数えられる名詞になり、a が必要になる。I have cold. は誤りで、I have a cold. が正しい。同じように、time は「時間」なら不可算だが have a good time では a が入る。熟語は形ごと覚えるのが安全である。\"}],\"trapExamples\":[{\"question\":\"「私は1日に2回、犬を散歩に連れて行きます。」を英語にしなさい。\",\"wrongAnswer\":\"I take my dog for a walk two times a day.\",\"trapExplanation\":\"「2回」を数字の two をそのまま使って two times と書いてしまう。three times, four times という形を先に覚えていると、2回も同じ形で作れると思いこむ。\",\"correctAnswer\":\"I take my dog for a walk twice a day.\",\"correctExplanation\":\"回数は1回が once、2回が twice、3回以上が three times, four times となる。once a week（週に1回）、twice a month（月に2回）のように、a は「〜につき」の意味を表す。two times は誤りではないが、入試では once / twice を書けることが求められる。\"},{\"question\":\"「私は今日、風邪をひいています。」を英語にしなさい。\",\"wrongAnswer\":\"I have cold today.\",\"trapExplanation\":\"cold を「寒い・寒さ」という語として覚えていると、数えられない名詞のつもりで a を付けずに書いてしまう。日本語の「風邪をひく」に数の感覚がないことも原因である。\",\"correctAnswer\":\"I have a cold today.\",\"correctExplanation\":\"「風邪」の意味の cold は数えられる名詞なので a が必要になる。have a cold, have a headache, have a fever はどれも a を含むひとまとまりの表現である。「寒さ」の意味では I can’t stand the cold. のように不可算で使われ、意味によって数え方が変わる語の一つである。\"}]}",
"{\"id\":\"eigo_s099\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"the の基本①：相手にもどれかわかるとき\",\"description\":\"一度話に出たものや、場面で一つに決まるものに the を付ける原則をつかむ\",\"intro\":\"I saw a dog. The dog was big. 1文目は a、2文目は the。同じ犬なのに変わるのは、2度目には相手にもどの犬か分かるからです。the は「お互いに分かっている」という合図なのです。\",\"order\":599,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"the は「どれのことか、相手にもわかる」ときに使う。\",\"一度 a で出したものを二度目に指すときは the に変える（I saw a dog. The dog was big.）。\",\"その場に一つしかない物には、初めから the を使う（Open the door.）。\",\"後ろから説明が付いて一つに決まるときも the（the water in this bottle／the boy over there）。\",\"the は数えられる名詞・数えられない名詞・単数・複数のすべてに付けられる。\"],\"sections\":[{\"heading\":\"a と the のいちばん大きなちがい\",\"body\":\"a と the のちがいは、「聞き手がどれのことかわかっているかどうか」の一点である。\\n\\n■ 初めて話に出すとき → a\\n例）I have a dog.（犬を飼っている）\\n　聞き手にとっては、どんな犬かまだわからない。\\n\\n■ 二度目からは → the\\n例）I have a dog. The dog is very big.（犬を飼っている。その犬はとても大きい）\\n　一度出したので、聞き手も「さっきの犬」だとわかる。\\n\\n■ 物語文でよく出る流れ\\nOnce upon a time, there was an old man.（昔々、一人のおじいさんがいました）\\nThe old man lived in a small village.（そのおじいさんは小さな村に住んでいました）\\nThe village was near a river.（その村は川の近くにありました）\\n※ 新しく出す名詞には a、すでに出た名詞には the が付いていることを確かめる。物語文の読解では、この流れを追うだけで話の筋がつかめる。\\n\\n★ ポイント：a は「知らせる」ため、the は「思い出させる」ためのことば、と考えるとわかりやすい。\",\"figureId\":\"lf_eigoext03_099\",\"mangaId\":\"eigo_s099_xm\"},{\"heading\":\"初めから the を使う場合\",\"body\":\"一度も話に出ていなくても、聞き手が「どれのことか」わかる場合には、初めから the を使う。\\n\\n■ その場に一つしかない物\\n例）Open the door, please.（ドアを開けてください）…その部屋のドアは一つに決まっている\\n例）Look at the blackboard.（黒板を見なさい）\\n例）Where is the bathroom?（トイレはどこですか）\\n\\n■ おたがいに了解している物\\n例）Let’s go to the park.（公園へ行こう）…いつも行く近所の公園\\n例）I saw your brother at the station.（駅であなたのお兄さんを見かけた）\\n\\n■ 後ろから説明が付いて一つに決まるとき\\n例）the water in this bottle（このびんの中の水）\\n例）the boy standing over there（あそこに立っている少年）\\n例）the book on the desk（つくえの上の本）\\n例）the first day of school（学校の初日）\\n⚠ 注意：不可算名詞にも the は付けられる。water には a を付けられないが、「どの水か」が決まれば the water となる。a が付けられないことと、the が付けられないことは別の話である。\\n\\n■ 複数形にも the は付く\\n例）the students in this class（このクラスの生徒たち）\\n例）Where are the books I bought yesterday?（きのう買った本はどこですか）\\n\\n■ まとめの練習\\nI bought a book yesterday. The book was very interesting.\\n（きのう本を買った。その本はとてもおもしろかった）\\nこの二文の a と the が入れかわっていないかを、必ず確認する。\"}],\"trapExamples\":[{\"question\":\"次の英文の二文目を正しく直しなさい。　I saw a cat in the garden. A cat was white.\",\"wrongAnswer\":\"A cat was white.（そのまま）\",\"trapExplanation\":\"一文目で a cat と書いたので、同じ語には同じ冠詞を付ければよいと考えてしまう。日本語では「その猫は」と言わずに「猫は白かった」でも通じるため、区別の必要を感じにくい。\",\"correctAnswer\":\"The cat was white.\",\"correctExplanation\":\"一度 a で話に出した名詞を、二度目に指すときは the に変える。二文目の cat は「さっき見たあの猫」であり、聞き手にもどれのことかわかるからである。物語文では、この a から the への流れが必ず現れる。\"},{\"question\":\"「このびんの中の水を飲んではいけません。」を英語にしなさい。\",\"wrongAnswer\":\"Don’t drink water in this bottle.\",\"trapExplanation\":\"water は数えられない名詞なので冠詞を付けてはいけない、と覚えすぎて、the まで落としてしまう。a が付けられないことと the が付けられないことを混同するのが原因。\",\"correctAnswer\":\"Don’t drink the water in this bottle.\",\"correctExplanation\":\"数えられない名詞に付けられないのは a / an だけで、the は付けられる。in this bottle という説明が付いて「どの水か」が一つに決まるので the を使う。the milk in the glass、the money on the table も同じ形である。\"}]}",
"{\"id\":\"eigo_s100\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"the の基本②：世界に一つのもの・楽器・序数・最上級\",\"description\":\"決まって the が付く場面を、代表例ごとに覚える\",\"intro\":\"月も太陽も世界に一つなので the moon、the sun と言います。ところがピアノをひくときも play the piano。楽器に the が付くのは不思議ですが、これは決まりごとです。the が固定される場面をまとめます。\",\"order\":600,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"世界に一つしかないものには the（the sun／the moon／the earth／the sky／the world）。\",\"方角には the（in the east／in the north）。\",\"楽器を演奏するときは the（play the piano／play the guitar）。スポーツは無冠詞。\",\"序数（the first／the second）と最上級（the best／the tallest）には the を付ける。\",\"the same（同じ）／on the Internet（インターネットで）も the を使う決まった形。\"],\"sections\":[{\"heading\":\"一つしかないもの・方角\",\"body\":\"世の中に一つしかないものは、言った時点で「どれのことか」決まるので the を付ける。\\n\\n■ 天体・自然\\nthe sun（太陽）／the moon（月）／the earth（地球）／the sky（空）／the sea（海）／the world（世界）\\n例）The sun rises in the east.（太陽は東からのぼる）\\n例）The earth goes around the sun.（地球は太陽のまわりを回る）\\n例）There are many stars in the sky.（空には星がたくさんある）\\n\\n■ 方角\\nin the east（東に）／in the west（西に）／in the north（北に）／in the south（南に）\\n例）Japan is in the east of Asia.（日本はアジアの東にある）\\n\\n■ 一つに決まる役職・場所\\nthe station（駅）／the post office（郵便局）／the hospital（病院）／the library（図書館）\\n例）I went to the post office this morning.（今朝、郵便局へ行った）\\n※ その町に一つしかない、または話し手と聞き手が同じ場所を思いうかべているため the が付く。\\n\\n★ ポイント：日本語で「あの」を付けなくても意味が通じるのに英語では the が要る、というのがこの型である。The sun is bright. を A sun is bright. と書くと、太陽がいくつもあることになってしまう。\",\"figureId\":\"xf_eigo_s100\"},{\"heading\":\"楽器・序数・最上級\",\"mangaId\":\"eigo_s100_manga\",\"body\":\"決まって the が付く言い方を三つ覚える。ここは入試で直接問われやすい。\\n\\n■ ①楽器を演奏する\\nplay the piano（ピアノをひく）／play the guitar（ギターをひく）／play the violin（バイオリンをひく）／play the drums（ドラムをたたく）\\n例）She plays the piano very well.（彼女はピアノがとてもじょうずだ）\\n⚠ 注意：スポーツには冠詞を付けない。play soccer／play tennis。\\n「楽器には the、スポーツには何も付けない」と対にして覚える。\\n\\n■ ②序数（〜番目）\\nthe first（1番目の）／the second（2番目の）／the third（3番目の）／the fifth（5番目の）\\n例）January is the first month of the year.（1月は1年の最初の月だ）\\n例）He was the first person to come.（彼は最初に来た人だった）\\n\\n■ ③最上級（いちばん〜）\\nthe best／the tallest／the most beautiful\\n例）He is the tallest boy in our class.（彼はクラスでいちばん背が高い）\\n例）This is the most beautiful lake in Japan.（これは日本でいちばん美しい湖だ）\\n※ 「いちばん」は一つに決まるので the が付く、と理解すれば覚えやすい。\\n\\n■ そのほかの決まった形\\nthe same（同じ）：We are in the same class.（私たちは同じクラスだ）\\non the Internet（インターネットで）：I found it on the Internet.\\nin the morning／in the afternoon／in the evening\\nplay the piano と in the morning は、どちらも the を落とさないよう注意する。\"}],\"trapExamples\":[{\"question\":\"「彼女はピアノをひくのがじょうずです。」を英語にしなさい。\",\"wrongAnswer\":\"She plays a piano very well.\",\"trapExplanation\":\"「数えられる名詞の単数には a」という規則をそのまま当てはめてしまう。play soccer のようにスポーツを冠詞なしで習っていると、楽器にも冠詞の区別があると気づきにくい。\",\"correctAnswer\":\"She plays the piano very well.\",\"correctExplanation\":\"楽器を演奏するというときは the を付ける決まりになっている。play the piano, play the guitar, play the violin。一方でスポーツには冠詞を付けず、play soccer, play tennis とする。「楽器は the、スポーツは無冠詞」と対で覚える。\"},{\"question\":\"「太陽は東からのぼる。」を英語にしなさい。\",\"wrongAnswer\":\"Sun rises in east.\",\"trapExplanation\":\"日本語の「太陽」「東」に冠詞がないため、そのまま単語を並べてしまう。名前のようなものだから固有名詞と同じで冠詞は不要だ、と考えてしまうことも多い。\",\"correctAnswer\":\"The sun rises in the east.\",\"correctExplanation\":\"世界に一つしかないもの（the sun, the moon, the earth）と方角（in the east, in the north）には the を付ける。The earth goes around the sun. も同じ形。なお rises と三人称単数の -s を付ける点も忘れないこと。\"}]}",
"{\"id\":\"eigo_s101\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"固有名詞と the：付く名前・付かない名前\",\"description\":\"川・海・山脈・複数形の国名には the、湖・単独の山・国・都市には the を付けない区別を覚える\",\"intro\":\"富士山は Mt. Fuji で the が付きませんが、信濃川は the Shinano River と付きます。琵琶湖は Lake Biwa、太平洋は the Pacific Ocean。同じ地名なのに分かれるので、種類ごとに整理して覚えます。\",\"order\":601,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"the が付く：川（the Shinano River）／海・大洋（the Pacific Ocean）／山脈（the Alps）。\",\"the が付く：複数形の国名（the United States／the Philippines／the Netherlands）。\",\"the が付く：新聞・船・公共の建物（the Asahi Shimbun／the Titanic／the White House）。\",\"the が付かない：湖（Lake Biwa）／単独の山（Mt. Fuji）／国名（Japan）／都市（Osaka）。\",\"the が付かない：駅・空港・公園・通り・人名（Tokyo Station／Narita Airport）。\"],\"sections\":[{\"heading\":\"the を付ける固有名詞\",\"body\":\"固有名詞には冠詞を付けないのが原則だが、例外的に the が付くグループがある。まとめて覚えてしまう。\\n\\n■ 川\\nthe Shinano River（信濃川）／the Nile（ナイル川）／the Thames（テムズ川）／the Mississippi River（ミシシッピ川）\\n例）The Shinano River is the longest river in Japan.（信濃川は日本でいちばん長い川だ）\\n\\n■ 海・大洋・海峡\\nthe Pacific Ocean（太平洋）／the Atlantic Ocean（大西洋）／the Sea of Japan（日本海）\\n\\n■ 山脈（連なった山）\\nthe Alps（アルプス山脈）／the Rocky Mountains（ロッキー山脈）／the Japanese Alps（日本アルプス）\\n※ 山脈は山がいくつも連なっているので複数の感じがあり、the が付くと考えるとよい。\\n\\n■ 複数形になっている国名\\nthe United States（アメリカ合衆国）／the Philippines（フィリピン）／the Netherlands（オランダ）\\n※ States, Philippines と -s が付いていることに注目する。\\n\\n■ 新聞・船・公共の建物\\nthe Asahi Shimbun（朝日新聞）／the Titanic（タイタニック号）／the White House（ホワイトハウス）／the British Museum（大英博物館）\\n\\n★ ポイント：「川・海・山脈・複数形の国名」の四つを唱えて覚える。この四つ以外はほぼ the なしと考えてよい。\",\"figureId\":\"xf_eigo_s101\",\"mangaId\":\"eigo_s101_xm\"},{\"heading\":\"the を付けない固有名詞\",\"body\":\"次のグループには the を付けない。日本人がまちがえやすいのは、川と対になる「湖」「単独の山」である。\\n\\n■ 湖\\nLake Biwa（琵琶湖）／Lake Michigan（ミシガン湖）\\n⚠ 注意：川は the Shinano River なのに、湖は the が付かない。この対比がそのまま入試問題になる。\\n\\n■ 単独の山\\nMt. Fuji（富士山）／Mt. Everest（エベレスト）\\n⚠ 注意：山脈は the Alps、単独の山は Mt. Fuji。\\n\\n■ 国名・都市名・大陸名\\nJapan／China／France／Osaka／London／Asia／Africa\\n例）I live in Japan.（× in the Japan）\\n\\n■ 駅・空港・公園・通り\\nTokyo Station（東京駅）／Narita Airport（成田空港）／Central Park（セントラルパーク）／Broadway（ブロードウェイ）\\n\\n■ 人名・曜日・月・祝日\\nKen／Ms. Tanaka／Monday／April／Christmas\\n例）I will see him on Monday.（月曜日に彼に会う）\\n\\n■ 対比してまとめる\\nthe Shinano River ⇔ Lake Biwa\\nthe Alps ⇔ Mt. Fuji\\nthe United States ⇔ Japan\\nthe Pacific Ocean ⇔ Tokyo Bay（東京湾は the を付けないことが多い）\\n左右の列を対にして覚えると、どちらか一方を思い出せばもう一方も出てくる。\"}],\"trapExamples\":[{\"question\":\"「私は去年、富士山に登りました。」を英語にしなさい。\",\"wrongAnswer\":\"I climbed the Mt. Fuji last year.\",\"trapExplanation\":\"the Alps や the Shinano River のように、地名には the が付くと思いこんでしまう。「山」というだけで the が要ると考えるのが原因。\",\"correctAnswer\":\"I climbed Mt. Fuji last year.\",\"correctExplanation\":\"単独の山には the を付けない（Mt. Fuji, Mt. Everest）。the が付くのは連なった山脈のほう（the Alps, the Rocky Mountains）である。同じく湖も Lake Biwa と the を付けないが、川は the Shinano River と the が付く。対にして覚えるとよい。\"},{\"question\":\"「私はアメリカ合衆国に行きたい。」を英語にしなさい。\",\"wrongAnswer\":\"I want to go to United States.\",\"trapExplanation\":\"Japan や China に the を付けないので、国名にはすべて冠詞が不要だと考えてしまう。United States が複数形になっていることに気づいていない。\",\"correctAnswer\":\"I want to go to the United States.\",\"correctExplanation\":\"複数形になっている国名には the を付ける（the United States, the Philippines, the Netherlands）。ふつうの国名 Japan, China, France には the を付けない。語尾に -s が付いた国名かどうかで見分ける。\"}]}",
"{\"id\":\"eigo_s102\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"冠詞を付けない決まった言い方\",\"description\":\"go to school・by bus・at home など、本来の目的で使うときに冠詞を落とす形を覚える\",\"intro\":\"go to school は「勉強しに学校へ行く」、go to the school は「学校という建物へ行く」。the があるかないかで意味が変わります。「バスで」も by bus と冠詞なし。本来の目的で使うときは冠詞が消えるのです。\",\"order\":602,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"建物や場所を「本来の目的」で使うときは冠詞を付けない：go to school（勉強しに）／go to bed（ねるために）。\",\"建物そのものをさすときは the が付く：go to the school（学校という建物へ行く）。\",\"交通手段は by＋冠詞なし：by bus／by train／by car／by bike。ただし on foot（徒歩で）。\",\"食事名（have lunch）／スポーツ名（play tennis）／教科名（study math）は冠詞なし。\",\"at home（家で）／at school（学校で）／in bed（ねている）も冠詞を付けない。\"],\"sections\":[{\"heading\":\"本来の目的で使うときは冠詞なし\",\"body\":\"英語には、建物や場所を「その本来の目的のために利用する」ときに冠詞を落とす言い方がある。\\n\\n■ 代表的な形\\ngo to school（学校へ行く＝勉強しに行く）\\ngo to bed（ねる）\\ngo to church（礼拝に行く）\\ngo to work（仕事に行く）\\nbe in bed（ねている）\\nbe at school（学校にいる＝授業を受けている）\\nbe in the hospital／be in hospital（入院している）\\n例）I go to school at eight every morning.（毎朝8時に学校へ行く）\\n例）My brother went to bed early last night.（弟は昨夜早くねた）\\n\\n■ 建物そのものをさすときは the\\nMy mother came to the school to meet my teacher.\\n（母は先生に会うために学校〈という建物〉へ来た）\\n※ 母は勉強しに行くのではないので the school となる。\\nThere is a big bed in the room. I sat on the bed.\\n（部屋に大きなベッドがある。私はそのベッドにすわった）\\n※ ねるためではなく、家具としてのベッドをさすので the bed。\\n\\n★ ポイント：go to school は「生徒として通う」、go to the school は「その建物に行く」。日本語では区別がないが、英語では冠詞一つで意味が変わる。\",\"figureId\":\"xf_eigo_s102\",\"mangaId\":\"eigo_s102_xm\"},{\"heading\":\"交通手段・場所・その他の無冠詞表現\",\"body\":\"そのほか、冠詞を付けない決まった言い方をまとめる。\\n\\n■ 交通手段（by＋乗り物）\\nby bus（バスで）／by train（電車で）／by car（車で）／by bike（自転車で）／by plane（飛行機で）／by ship（船で）\\n例）I go to school by bus.（バスで学校へ行く）\\n⚠ 注意：× by a bus／× by the bus とは言わない。ただし「徒歩で」は on foot と別の形になる。\\n例）I go to school on foot.（歩いて学校へ行く）＝I walk to school.\\n\\n■ 場所を表す決まった形\\nat home（家で）／at school（学校で）／at work（仕事中で）／in class（授業中で）／at night（夜に）\\n例）I stayed at home yesterday.（きのうは家にいた）\\n例）Don’t talk in class.（授業中にしゃべってはいけません）\\n\\n■ 食事・スポーツ・教科\\nhave breakfast／have lunch／have dinner\\nplay tennis／play baseball\\nstudy English／study science\\n\\n■ 対にして覚える\\ngo to school（通学する） ⇔ go to the school（建物へ行く）\\nplay tennis（スポーツ） ⇔ play the piano（楽器）\\nby bus（交通手段） ⇔ take the bus（そのバスに乗る）\\n左右のちがいを説明できるようにしておくと、冠詞の問題で迷わなくなる。\"}],\"trapExamples\":[{\"question\":\"「私は毎晩10時にねます。」を英語にしなさい。\",\"wrongAnswer\":\"I go to the bed at ten every night.\",\"trapExplanation\":\"bed を家具として思いうかべるため、「そのベッド」という気持ちで the を付けてしまう。日本語の「ねる」に場所の意識がないことも、判断を難しくしている。\",\"correctAnswer\":\"I go to bed at ten every night.\",\"correctExplanation\":\"go to bed は「ねる」という意味の決まった言い方で、冠詞を付けない。ベッドという家具そのものをさすときだけ the bed となる（I sat on the bed.）。go to school, go to work も同じ考え方で、本来の目的で使うときは冠詞を落とす。\"},{\"question\":\"「私は毎週土曜日にテニスをします。」を英語にしなさい。\",\"wrongAnswer\":\"I play the tennis every Saturday.\",\"trapExplanation\":\"play the piano を覚えていると、play の後ろにはいつも the が要ると思いこんでしまう。楽器とスポーツで扱いが逆になることを知らないと必ず引っかかる。\",\"correctAnswer\":\"I play tennis every Saturday.\",\"correctExplanation\":\"スポーツ名には冠詞を付けず、楽器名には the を付ける。play tennis / play soccer ⇔ play the piano / play the guitar。play の後ろに来る語がスポーツか楽器かを見て決める。教科名（study math）も冠詞なしである。\"}]}",
"{\"id\":\"eigo_s103\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"冠詞の総まとめ：a・the・無冠詞の選び分け\",\"description\":\"三つの手順で冠詞を決める方法を身につけ、まぎらわしい文で確実に選べるようにする\",\"intro\":\"a か the か、それとも何も付けないか。迷うたびに勘で決めていては、いつまでも正答率が上がりません。数えられるか、単数か複数か、相手にどれか分かるか。この3つを順に問えば、答えは1つに決まります。\",\"order\":603,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"手順①：その名詞は数えられるか。②単数か複数か。③相手にどれのことかわかるか。\",\"相手にわかる（特定できる）なら、単数・複数・不可算のすべてで the。\",\"相手にわからない場合、単数なら a / an、複数や不可算なら冠詞を付けない。\",\"決まった言い方（play the piano／go to school／by bus）は手順より優先して覚える。\",\"名詞の前に my・this・数字などがあるときは、a / the を重ねない。\"],\"sections\":[{\"heading\":\"三つの手順で決める\",\"body\":\"冠詞は感覚ではなく、手順で決められる。次の三段階を順にたどる。\\n\\n■ 手順①　数えられる名詞か\\n数えられない（water, music, homework）→ a / an は使えない。手順③へ進む。\\n数えられる（book, dog, apple）→ 手順②へ。\\n\\n■ 手順②　単数か複数か\\n単数 → a / an か the のどちらか。\\n複数 → the か、冠詞なしのどちらか。\\n\\n■ 手順③　相手にどれのことかわかるか\\nわかる（すでに話に出た／その場に一つ／後ろに説明が付く／世界に一つ）→ the\\nわからない（初めて出す／どれでもよい）→ 単数なら a / an、複数や不可算なら冠詞なし\\n\\n■ 表にすると\\n　　　　　　　　特定できる　　特定できない\\n単数（可算）　　the dog　　　　a dog\\n複数（可算）　　the dogs　　　 dogs（冠詞なし）\\n不可算　　　　　the water　　　water（冠詞なし）\\n\\n★ ポイント：右下の二つ（複数・不可算で特定されない場合）だけが「冠詞なし」になる。ここを覚えておけば、迷ったときの判断が速くなる。\",\"figureId\":\"lf_eigoext03_103\"},{\"heading\":\"まぎらわしい文で練習する\",\"body\":\"手順に当てはめながら、実際の文で確かめてみる。\\n\\n■ 練習1　I bought （　） book yesterday. （　） book was interesting.\\n一文目：数えられる・単数・初めて出す → a book\\n二文目：すでに出た → The book\\n答え：a／The\\n\\n■ 練習2　（　） sun is bright today.\\n世界に一つしかない → the\\n答え：The\\n\\n■ 練習3　I like （　） music.\\n数えられない・特定されない → 冠詞なし\\n答え：（何も入れない）\\n\\n■ 練習4　She plays （　） violin and （　） soccer.\\n楽器には the、スポーツには冠詞なし\\n答え：the／（何も入れない）\\n\\n■ 練習5　There is （　） water in （　） glass on the table.\\n一つ目：数えられない・特定されない → 冠詞なし\\n二つ目：on the table という説明が付いて一つに決まる → the\\n答え：（何も入れない）／the\\n\\n■ 決まった言い方は手順より優先\\ngo to school／go to bed／by bus／at home／have lunch／play tennis／play the piano／in the morning／once a week\\nこれらは形ごと暗記しておき、手順で考え直さない。\\n\\n⚠ 注意：名詞の前に my・your・this・that・数字・some・any があるときは、a も the も付けない。× the my book／× a two books。冠詞を入れる前に、名詞の前に何があるかを必ず見る。\"},{\"heading\":\"なぜ三つの手順で冠詞が決まるのか\",\"mangaId\":\"eigo_s103_manga\",\"body\":\"冠詞は、名詞について**「数えられるか」「一つか」「相手にどれか分かるか」**という三つの情報を相手に伝える語です。a は「数えられるものが一つで、どれでもよい」、the は「相手にどれのことか分かる」、冠詞なしは「数えられない、または複数で、特定していない」。だから、この三つの情報を順に確かめれば、a・the・無冠詞のどれかが一つに決まります。勘で選ぶと、太陽（世界に一つ→相手に分かる→the）を a sun と書いたり、coffee（数えられない）を a coffee と書いたりします。\\n\\n決まった言い方（play the piano・go to school・by bus）を手順より優先するのは、これらが**理屈ではなく習慣で固まった形**だからです。手順で考え直すとかえって迷うので、形ごと覚えます。名詞の前に my・this・数字があるときに a / the を付けないのは、それらがすでに「どれか」を示しているからです。\\n\\n■ 確かめのしかた\\n①**数えられるか**：water・music・homework・coffee→数えられない→a は使えない。\\n②**単数か複数か**：単数→a か the、複数→the か冠詞なし。\\n③**相手にどれか分かるか**：すでに出た／その場に一つ／後ろに説明が付く／世界に一つ→the。初めて出す・どれでもよい→単数なら a、複数・不可算なら冠詞なし。\\n④名詞の前に my・your・this・数字・some があれば冠詞は付けない。決まった言い方（play the piano／play tennis／go to bed／in the morning）は形ごと覚える。\\n\\n★ ここがポイント：冠詞は**数えられるか・一つか・相手に分かるか**の三つの情報を伝える語なので、**三つの手順を最後まで進める**と一つに決まる（the sun は「世界に一つ」で the）。決まった言い方は手順より優先。\"}],\"trapExamples\":[{\"question\":\"「今日は太陽が明るい。」を英語にしなさい。\",\"wrongAnswer\":\"A sun is bright today.\",\"trapExplanation\":\"数えられる名詞の単数だから a を付ける、と手順の途中で止まってしまう。「相手にどれのことかわかるか」という三つ目の手順を確かめていないのが原因。\",\"correctAnswer\":\"The sun is bright today.\",\"correctExplanation\":\"太陽は世界に一つしかないので、初めて話に出しても相手はどれのことかわかる。したがって the を使う。a sun と書くと太陽がいくつもあることになってしまう。the moon, the earth, the sky も同じ。手順は必ず三つ目まで進める。\"},{\"question\":\"「彼は毎朝コーヒーを飲みます。」を英語にしなさい。\",\"wrongAnswer\":\"He drinks a coffee every morning.\",\"trapExplanation\":\"店で「コーヒー1つ」と注文する言い方を知っていると、a coffee でよいと感じてしまう。coffee が数えられない名詞であるという手順①を飛ばしている。\",\"correctAnswer\":\"He drinks coffee every morning.\",\"correctExplanation\":\"coffee は数えられない名詞なので a を付けない。特定もされていないので冠詞なしになる。「カップ1ぱいの」と数を言いたいときは a cup of coffee とする。手順①で数えられるかどうかを確かめれば、この誤りは防げる。\"}]}",
"{\"id\":\"eigo_s104\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"人称代名詞①：主格（〜は・〜が）\",\"description\":\"名詞のかわりに使う代名詞の役割と、主語になる形をおさえる\",\"intro\":\"日本語では「昨日、公園に行った。楽しかった。」と主語を言わなくても通じます。英語では It was fun. のように必ず主語を置かなければなりません。省けないからこそ、代名詞という短い語が発達したのです。\",\"order\":604,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"代名詞＝名詞のくり返しをさけるために使う語。I, you, he, she, it, we, they が主格。\",\"英語では主語を省略できない。日本語で「〜は」が消えていても、英語では必ず置く。\",\"男性は he、女性は she、物や動物は it、複数は they を使う。\",\"it は天気・時間・曜日・距離・明暗を表す主語としても使う（It is rainy today.）。\",\"「太郎と私」は Taro and I の順にし、自分は最後に置く。\"],\"sections\":[{\"heading\":\"代名詞の役割と主格\",\"body\":\"同じ名詞を何度もくり返すと、文がくどくなる。そこで二度目からは代名詞に置きかえる。\\n\\n■ 例\\nKen is my friend. Ken is very kind.\\n→ Ken is my friend. He is very kind.（ケンは私の友達です。彼はとても親切です）\\n\\n■ 主格の一覧（主語になる形）\\nI（私は）／you（あなたは・あなたたちは）／he（彼は）／she（彼女は）／it（それは）／we（私たちは）／they（彼らは・それらは）\\n\\n■ どれを使うか\\n男性1人 → he　　女性1人 → she　　物・動物1つ → it　　2人以上・2つ以上 → they\\n例）This is my brother. He is ten years old.\\n例）That is my sister. She is a student.\\n例）I have a dog. It is very cute.\\n例）Ken and Tom are my friends. They like soccer.\\n\\n■ 英語は主語を省略できない\\n日本語では「学校へ行きます」と主語なしで言えるが、英語では必ず主語を置く。\\n例）（私は）学校へ行きます。→ I go to school.（× Go to school. は「学校へ行きなさい」という命令文になってしまう）\\n\\n★ ポイント：主語が抜けている英文はほぼ誤りである。作文したら、まず主語があるかを確かめる。\",\"figureId\":\"xf_eigo_s104\"},{\"heading\":\"it の特別な使い方と、並べる順序\",\"mangaId\":\"eigo_s104_manga\",\"body\":\"it には「それは」と訳さない使い方がある。天気や時間を表す文で使う it である。\\n\\n■ 天気・時間・曜日・日付・距離・明暗の it\\nIt is rainy today.（今日は雨だ）\\nIt is seven o’clock.（7時です）\\nIt is Monday today.（今日は月曜日です）\\nIt is June 10 today.（今日は6月10日です）\\nIt is about two kilometers from here to the station.（ここから駅まで約2キロある）\\nIt is dark outside.（外は暗い）\\n※ この it は「それは」と訳さない。日本語には対応する語がないので、そのまま形で覚える。\\n\\n■ たずね方\\nWhat time is it now?（今何時ですか）→ It is nine thirty.\\nHow is the weather today?（今日の天気はどうですか）→ It is sunny.\\nWhat day is it today?（今日は何曜日ですか）→ It is Friday.\\n\\n■ 二つ以上を並べるときの順序\\n自分（I）は最後に置くのが礼儀とされる。\\n例）Taro and I are good friends.（太郎と私は仲のよい友達です）\\n⚠ 注意：× Me and Taro are good friends. は誤り。主語の位置なので I を使い、しかも自分を後ろに置く。\\n例）You and I are in the same class.（あなたと私は同じクラスです）\\n\\n■ 主語が複数になると動詞も変わる\\nHe is my friend. → He and I are good friends.\\nShe likes soccer. → She and her sister like soccer.\"}],\"trapExamples\":[{\"question\":\"「今日は雨が降っています。」を英語にしなさい。\",\"wrongAnswer\":\"Rain is falling today.\",\"trapExplanation\":\"日本語の「雨が降る」をそのまま単語に置きかえてしまう。英語には天気を表すときに it を主語にする決まった形があることを知らないと起きる誤り。\",\"correctAnswer\":\"It is rainy today.（It is raining today. も可）\",\"correctExplanation\":\"天気・時間・曜日・距離・明暗を表す文では、意味を持たない it を主語に置く。この it は「それは」と訳さない。It is sunny. / It is seven o’clock. / It is Monday today. も同じ形である。日本語に対応する語がないので、形ごと覚える。\"},{\"question\":\"「太郎と私は仲のよい友達です。」を英語にしなさい。\",\"wrongAnswer\":\"Me and Taro are good friends.\",\"trapExplanation\":\"会話で耳にする形をまねてしまい、主語の位置に目的格の me を置いてしまう。また、日本語では「私と太郎」と自分を先に言うこともあるため、順序も逆にしがちである。\",\"correctAnswer\":\"Taro and I are good friends.\",\"correctExplanation\":\"主語の位置には主格 I を使う。また、自分をさす語は最後に置くのが英語の習わしなので Taro and I の順になる。主語が2人になったので be動詞は are。You and I are in the same class. も同じ形である。\"}]}",
"{\"id\":\"eigo_s105\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"人称代名詞②：目的格（〜を・〜に）\",\"description\":\"動詞や前置詞の後ろに置く形を、語順との関係で理解する\",\"intro\":\"I know he. とは言えません。動詞のうしろに来た瞬間に him に変わるからです。日本語では「彼を知っている」も「彼が来る」も「彼」のままですが、英語は文の中の位置によって形そのものが変わるのです。\",\"order\":605,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"目的格＝me, you, him, her, it, us, them。「〜を」「〜に」にあたる形。\",\"動詞の後ろ（目的語の位置）では必ず目的格を使う（I know him.）。\",\"前置詞（with, for, to, at, about）の後ろも目的格（with me／for us／look at him）。\",\"you と it は主格と目的格が同じ形。\",\"and で並んだときも目的格のまま（between you and me）。\"],\"sections\":[{\"heading\":\"位置で形が変わる\",\"mangaId\":\"eigo_s105_manga\",\"body\":\"英語は語順で役割が決まる言語である。同じ「彼」でも、文のどこに置くかで形が変わる。\\n\\n■ 主格と目的格の対応\\nI → me（私を・私に）\\nyou → you（あなたを）\\nhe → him（彼を）\\nshe → her（彼女を）\\nit → it（それを）\\nwe → us（私たちを）\\nthey → them（彼らを・それらを）\\n※ you と it は形が変わらない。\\n\\n■ 動詞の後ろ（目的語）\\nI know him.（私は彼を知っている）\\nShe likes me.（彼女は私が好きだ）\\nWe helped them.（私たちは彼らを助けた）\\nPlease call us tonight.（今夜私たちに電話してください）\\n\\n■ 日本語との対応\\n「彼は」＝he、「彼を・彼に」＝him。日本語では「は」「を」という助詞で区別するが、英語では語そのものの形で区別する。だから語順と形の両方を守る必要がある。\\n\\n★ ポイント：動詞のすぐ後ろに人が来たら、その形は目的格になっているかを確かめる。× I know he. はもっとも多い誤りの一つである。\",\"figureId\":\"lf_eigoext03_105\"},{\"heading\":\"前置詞の後ろも目的格\",\"body\":\"with, for, to, at, about, from などの前置詞の後ろに来る代名詞も、必ず目的格になる。\\n\\n■ 前置詞＋目的格\\nwith me（私といっしょに）／for you（あなたのために）／to him（彼に）／at her（彼女を）／about them（彼らについて）／from us（私たちから）\\n例）Come with me.（私といっしょに来て）\\n例）This present is for you.（このプレゼントはあなたのためのものです）\\n例）Look at him.（彼を見て）\\n例）I am talking about them.（私は彼らのことを話している）\\n\\n■ and でつながれたときが要注意\\n前置詞の後ろで人が二人並ぶと、うっかり主格を使ってしまう。\\n◯ between you and me（あなたと私の間で）\\n× between you and I\\n◯ This is a present for Ken and me.（これはケンと私へのプレゼントです）\\n× for Ken and I\\n⚠ 注意：and をはずして一人だけにしてみると、正しい形が見える。for ... me は自然だが、for ... I は明らかにおかしい、と確かめられる。\\n\\n■ 動詞が二つの目的語を取るとき\\nHe gave me a book.（彼は私に本をくれた）\\n　me（〜に）＋a book（〜を）の順。\\nHe gave it to me.（彼はそれを私にくれた）\\n　「〜を」が代名詞になるときは、to を使ってこの語順にする。\\n\\n■ 主格と目的格が両方出る文\\nHe likes her, and she likes him, too.（彼は彼女が好きで、彼女も彼が好きだ）\\nこの一文で、動詞の前が主格・後ろが目的格になっていることを確かめる。\"}],\"trapExamples\":[{\"question\":\"「私は彼を知っています。」を英語にしなさい。\",\"wrongAnswer\":\"I know he.\",\"trapExplanation\":\"「彼」＝he と一対一で覚えてしまうと、文のどこに置いても he を使ってしまう。日本語では「彼は」も「彼を」も同じ「彼」なので、形を変える必要に気づきにくい。\",\"correctAnswer\":\"I know him.\",\"correctExplanation\":\"動詞の後ろ（目的語の位置）では目的格を使うので him になる。he は主語の位置に置く形である。She likes me. / We helped them. も同じ。動詞のすぐ後ろに人が来たら、目的格になっているかを必ず確かめる。\"},{\"question\":\"（　）に正しい語を入れなさい。　This is a secret between you and （　）.\",\"wrongAnswer\":\"I\",\"trapExplanation\":\"Taro and I のように「and でつないだら I を使う」と覚えてしまい、前置詞の後ろでも I を選んでしまう。ていねいな言い方に聞こえることも、誤りを助長する。\",\"correctAnswer\":\"me\",\"correctExplanation\":\"between は前置詞なので、後ろの代名詞は目的格 me になる。and をはずして between ... me と考えれば、I が入らないことがすぐわかる。for Ken and me、with you and me も同じ。主格 I を使うのは、あくまで主語の位置だけである。\"}]}",
"{\"id\":\"eigo_s106\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"人称代名詞③：所有格（〜の）\",\"description\":\"my・your・his などの所有格と、名詞に付ける ’s の使い方を身につける\",\"intro\":\"「私の本」は my book、「ケンの本」は Ken's book。ではこの2つを重ねて a my book と言えるでしょうか。言えません。所有格が付いた名詞には、a も the も重ねないからです。\",\"order\":606,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"所有格＝my, your, his, her, its, our, their。必ず後ろに名詞が来る。\",\"所有格が付いた名詞に a / the は重ねない（× a my book）。\",\"人や動物の「〜の」は名詞＋’s で表す（Ken’s book／my father’s car）。\",\"複数形の -s で終わる語は、アポストロフィだけを付ける（the students’ room）。\",\"物の「〜の」は of を使うことが多い（the color of the car）。\",\"its（それの）と it’s（it is の短縮）はまったく別物。書き分けに注意。\"],\"sections\":[{\"heading\":\"所有格の形と使い方\",\"body\":\"「〜の」を表す形を所有格という。所有格は必ず後ろに名詞をともなう。\\n\\n■ 所有格の一覧\\nI → my（私の）\\nyou → your（あなたの・あなたたちの）\\nhe → his（彼の）\\nshe → her（彼女の）\\nit → its（それの）\\nwe → our（私たちの）\\nthey → their（彼らの・それらの）\\n\\n■ 使い方\\n例）This is my bag.（これは私のかばんです）\\n例）Her father is a teacher.（彼女の父は先生です）\\n例）I like their songs.（私は彼らの歌が好きだ）\\n例）The dog wagged its tail.（その犬はしっぽをふった）\\n\\n■ 冠詞と重ねない\\n所有格が付いたら a / the は付けない。\\n× a my book／× the his car\\n◯ my book／his car\\n「一つの」と「私の」を両方言いたいときは a book of mine とする。\\n\\n⚠ 注意：its と it’s のちがい。\\nits＝それの（所有格）：The cat is licking its paw.（そのねこは自分の足をなめている）\\nit’s＝it is または it has の短縮形：It’s cold today.（今日は寒い）\\nアポストロフィが入るのは短縮形のほうである。所有格の its にはアポストロフィを付けない。\"},{\"heading\":\"名詞に付ける ’s と of\",\"body\":\"代名詞ではなくふつうの名詞に「〜の」を付けたいときは、’s か of を使う。\\n\\n■ 人・動物には ’s（アポストロフィ・エス）\\nKen’s book（ケンの本）\\nmy father’s car（父の車）\\nthe dog’s name（その犬の名前）\\ntoday’s newspaper（今日の新聞）\\n例）This is my sister’s bike.（これは姉の自転車です）\\n\\n■ 複数形の -s で終わる語には ’ だけ\\nthe students’ room（生徒たちの部屋）\\nmy parents’ house（両親の家）\\n※ students’s とは書かない。読み方は students と変わらない。\\n※ 複数でも -s で終わらない語は ’s を付ける。children’s books（子どもたちの本）／women’s clothes（女性の服）\\n\\n■ 物には of を使うことが多い\\nthe color of the car（その車の色）\\nthe name of this flower（この花の名前）\\nthe top of the mountain（山の頂上）\\nthe end of the story（物語の終わり）\\n※ × the car’s color とは、ふつう言わない。生き物でないものは of を使うと覚えておく。\\n\\n■ お店・家を表す ’s\\nI went to the dentist’s.（歯医者へ行った）\\nI stayed at my uncle’s.（おじの家に泊まった）\\n※ 後ろの office や house が省略された形である。\\n\\n★ ポイント：「生き物なら ’s、物なら of」が原則。ただし時を表す語（today’s, this year’s）は例外的に ’s を使う。\"},{\"heading\":\"なぜ所有格に冠詞を重ねず、なぜ物には of を使うのか\",\"mangaId\":\"eigo_s106_manga\",\"body\":\"my・your・his のような所有格は、「だれのものか」を示すことで、**その名詞がどれのことかをすでに決めています**。a は「どれでもよい一つ」、the は「相手に分かるあれ」を示す語なので、所有格と重ねると「どれでもよくて、私のもの」のように矛盾します。だから a my book とは言えず、両方言いたければ a book of mine と形を変えます。\\n\\n生き物には 's、物には of が多いのは、**'s が「持ち主」を表す形**だからです。人や動物は持ち主になれますが、車や山は何かを「持つ」わけではないので、the color of the car のように of で「〜の一部・〜に属する」と言います。today's のように時を表す語が 's を使うのは例外として覚えます。its と it's の区別は、**アポストロフィは短縮の印**で、所有格には付かない、と考えれば迷いません。\\n\\n■ 確かめのしかた\\n①所有格（my・his・their）を付けたら、その前に a・the が残っていないか。× a my book。\\n②「〜の」が二つある日本語（私の父の車）は、英語でも二つ必要か。my father's car（my→father、father's→car）。\\n③人・動物→'s（Ken's book、the dog's name）。複数の -s で終わる語→' だけ（the students' room）。-s で終わらない複数→'s（children's books）。物→of（the top of the mountain）。\\n④its（それの）と it's（it is）を文に入れて確かめる。The dog wagged its tail.（それの）／It's cold.（it is）。\\n\\n★ ここがポイント：所有格は**どれのことかをすでに決めている**ので冠詞を重ねない。**'s は持ち主の形**なので生き物に使い、物は of。アポストロフィは短縮の印なので所有格の its には付かない。\",\"figureId\":\"xf_eigo_s106\"}],\"trapExamples\":[{\"question\":\"（　）に正しい語を入れなさい。　The dog wagged （　） tail.（その犬はしっぽをふった）\",\"wrongAnswer\":\"it’s\",\"trapExplanation\":\"「それの」だから it に ’s を付ければよい、と考えてしまう。Ken’s book のように名詞には ’s を付けて所有を表すため、it にも同じ形が使えると思いこむのが原因。\",\"correctAnswer\":\"its\",\"correctExplanation\":\"所有格の「それの」はアポストロフィのない its である。it’s は it is または it has の短縮形で、まったく別の語。It’s cold today.（今日は寒い）と The cat licked its paw.（ねこは自分の足をなめた）を並べて確認する。代名詞の所有格（my, your, his, her, its, our, their）にはアポストロフィを付けない。\"},{\"question\":\"「これは私の父の車です。」を英語にしなさい。\",\"wrongAnswer\":\"This is my father car.\",\"trapExplanation\":\"my を付けたことで「〜の」を言い終えた気になり、father と car の間の所有を表す形を落としてしまう。日本語の「私の父の車」に「の」が二つあることを見落としている。\",\"correctAnswer\":\"This is my father’s car.\",\"correctExplanation\":\"「父の車」の部分にも所有の形が必要なので father’s とする。my は father にかかり、father’s が car にかかる二重の構造になっている。my sister’s bike、Ken’s book も同じ。人を表す名詞には ’s を付けると覚える。\"}]}",
"{\"id\":\"eigo_s107\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"人称代名詞④：所有代名詞（〜のもの）\",\"description\":\"mine・yours などの一語で「〜のもの」を表す形を使えるようにする\",\"intro\":\"This is mine book. と書きたくなりますが、mine のうしろに名詞は置きません。mine は「私のもの」で、my book をまるごと1語にした形だからです。Whose is this? への答えとしてよく使います。\",\"order\":607,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"所有代名詞＝mine, yours, his, hers, ours, theirs。「〜のもの」を一語で表す。\",\"所有代名詞の後ろには名詞を置かない（× This is mine book.）。\",\"his は所有格も所有代名詞も同じ形。it には所有代名詞がない。\",\"hers, yours, theirs にアポストロフィは付けない（× her’s）。\",\"Whose is this?（これはだれのものですか）に対する答えとして使う。\",\"a friend of mine（私の友達の一人）の形でも使う。\"],\"sections\":[{\"heading\":\"所有代名詞の形と使い方\",\"body\":\"「私のもの」「あなたのもの」のように、〈所有格＋名詞〉をまとめて一語で言いかえた形を所有代名詞という。\\n\\n■ 一覧\\nmy book → mine（私のもの）\\nyour book → yours（あなたのもの）\\nhis book → his（彼のもの）\\nher book → hers（彼女のもの）\\nour book → ours（私たちのもの）\\ntheir book → theirs（彼らのもの）\\n※ it には所有代名詞がなく、its を「それのもの」の意味では使わない。\\n\\n■ 使い方\\n例）This bag is mine.（このかばんは私のものです）\\n例）That car is theirs.（あの車は彼らのものです）\\n例）Is this pen yours?（このペンはあなたのものですか）\\n例）My bike is old, but hers is new.（私の自転車は古いが、彼女のは新しい）\\n\\n■ 後ろに名詞を置かない\\n所有代名詞にはすでに名詞の意味がふくまれている。\\n× This is mine book. → ◯ This is my book. または This is mine.\\n⚠ 注意：my（所有格）は名詞とセットで、mine（所有代名詞）は単独で使う。\\n\\n■ アポストロフィを付けない\\n◯ hers／yours／ours／theirs\\n× her’s／your’s／our’s／their’s\\n名詞に付ける Ken’s とちがい、代名詞にはアポストロフィを使わない。ここは書き取り問題でねらわれる。\",\"figureId\":\"xf_eigo_s107\",\"mangaId\":\"eigo_s107_xm\"},{\"heading\":\"Whose とのやりとり・a friend of mine\",\"body\":\"所有代名詞は、「だれのもの？」とたずねる文への答えとしてよく使われる。\\n\\n■ Whose を使ったやりとり\\nWhose bag is this?（これはだれのかばんですか）→ It’s mine.（私のものです）\\nWhose is this bag?（このかばんはだれのものですか）→ It’s Ken’s.（ケンのものです）\\n※ 名詞の場合は Ken’s のように ’s の形が、そのまま「ケンのもの」を表す。\\nWhose pens are these?（これらはだれのペンですか）→ They are hers.（彼女のものです）\\n\\n■ a friend of mine の形\\n「私の友達の一人」のように、a と my を両方使いたいときは of を使う。\\na friend of mine（私の友達の一人）\\na book of his（彼の本の一冊）\\nsome friends of ours（私たちの友達の何人か）\\n⚠ 注意：of の後ろは所有代名詞にする。× a friend of my は誤り。\\n\\n■ 比べる文でよく使う\\nMy hair is longer than hers.（私の髪は彼女のより長い）\\nYour idea is better than mine.（あなたの考えは私のよりよい）\\n※ than の後ろで、同じ名詞のくり返しをさけるために所有代名詞を使う。\\n\\n■ 練習\\nThis is my desk, and that is （　）.（あれは彼女のものです）→ hers\\nIs this umbrella （　）?（これはあなたのですか）→ yours\\nThese books are （　）.（これらは私たちのものです）→ ours\"}],\"trapExamples\":[{\"question\":\"「このかばんは私のものです。」を英語にしなさい。\",\"wrongAnswer\":\"This bag is my.\",\"trapExplanation\":\"「私の」＝my と覚えているため、名詞がなくても my を置いてしまう。日本語では「私のです」と言えるので、英語でも同じように言えると感じてしまう。\",\"correctAnswer\":\"This bag is mine.\",\"correctExplanation\":\"my は後ろに名詞をともなう所有格なので、単独では使えない。名詞なしで「私のもの」と言うときは所有代名詞 mine を使う。This is my bag. と This bag is mine. は同じ内容を別の形で表している。yours, hers, ours, theirs も同じ使い方をする。\"},{\"question\":\"「あの自転車は彼女のものです。」を英語にしなさい。\",\"wrongAnswer\":\"That bike is her’s.\",\"trapExplanation\":\"Ken’s bike のように名詞には ’s を付けて所有を表すので、代名詞にも同じ形が使えると考えてしまう。音が同じであることも誤りを見えにくくする。\",\"correctAnswer\":\"That bike is hers.\",\"correctExplanation\":\"所有代名詞 hers, yours, ours, theirs にはアポストロフィを付けない。アポストロフィを使うのは、Ken’s のようにふつうの名詞に付けるときだけである。its も同じで、アポストロフィが入る it’s は it is の短縮形になってしまう。\"}]}",
"{\"id\":\"eigo_s108\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"人称代名詞の格変化 総まとめ\",\"description\":\"主格・所有格・目的格・所有代名詞の四つを、表として完全に覚える\",\"intro\":\"I・my・me・mine。同じ「私」なのに、英語には4つの形があります。日本語では文のどこに置いても「私」のままなので、ここは覚え直しが必要です。文の中の位置さえ見れば、どの形を使うかは必ず決まります。\",\"order\":608,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"I – my – me – mine／you – your – you – yours／he – his – him – his。\",\"she – her – her – hers／it – its – it –（なし）。\",\"we – our – us – ours／they – their – them – theirs。\",\"he の行は所有格も所有代名詞も his。she の行は主格以外がすべて her で始まる形。\",\"文の中の位置（主語か、名詞の前か、動詞や前置詞の後ろか）を見て、どの列かを決める。\"],\"sections\":[{\"heading\":\"四つの列を声に出して覚える\",\"body\":\"人称代名詞は、四つの形をひとまとまりにして唱えて覚えるのがいちばん速い。\\n\\n■ 唱え方（主格－所有格－目的格－所有代名詞）\\nI – my – me – mine\\nyou – your – you – yours\\nhe – his – him – his\\nshe – her – her – hers\\nit – its – it –（所有代名詞はなし）\\nwe – our – us – ours\\nthey – their – them – theirs\\n\\n■ 列の意味\\n第1列（主格）：〜は、〜が　→　主語の位置\\n第2列（所有格）：〜の　→　名詞の前\\n第3列（目的格）：〜を、〜に　→　動詞・前置詞の後ろ\\n第4列（所有代名詞）：〜のもの　→　単独で使う\\n\\n■ 形が重なるところに注意\\nyou：主格と目的格が同じ（you）\\nit：主格と目的格が同じ（it）\\nhe：所有格と所有代名詞が同じ（his）\\nshe：所有格と目的格が同じ（her）\\nこの四か所が入試でねらわれる。とくに she の行は her が二回出てくるので、どちらの意味かを文の位置で判断する必要がある。\\n例）I know her.（彼女を知っている＝目的格）\\n例）I know her sister.（彼女の姉を知っている＝所有格）\",\"figureId\":\"lf_eigoext03_108\",\"mangaId\":\"eigo_s108_xm\"},{\"heading\":\"位置から形を決める練習\",\"body\":\"どの形を使うかは、文の中の位置だけで決まる。次の手順で判断する。\\n\\n■ 手順\\n①主語の位置か → 主格\\n②すぐ後ろに名詞があるか → 所有格\\n③動詞や前置詞の後ろか → 目的格\\n④後ろに名詞がなく、単独で「〜のもの」か → 所有代名詞\\n\\n■ 練習1　（　） am a student.　→ 主語の位置 → I\\n■ 練習2　This is （　） pen.（私の）→ 後ろに名詞 pen → my\\n■ 練習3　Please help （　）.（私を）→ 動詞の後ろ → me\\n■ 練習4　This pen is （　）.（私のもの）→ 単独 → mine\\n■ 練習5　I like （　） very much.（彼女を）→ 動詞の後ろ → her\\n■ 練習6　（　） mother is a nurse.（彼女の）→ 後ろに名詞 mother → Her\\n■ 練習7　This is not my bike. It is （　）.（彼らのもの）→ 単独 → theirs\\n■ 練習8　We went there with （　）.（彼と）→ 前置詞の後ろ → him\\n\\n■ 一文で全部確かめる\\nHe gave his book to me, and I gave mine to him.\\n（彼は自分の本を私にくれ、私は私のものを彼にあげた）\\nhe（主格）／his（所有格）／me（目的格）／mine（所有代名詞）／him（目的格）が一文に入っている。声に出して読み、それぞれがなぜその形なのかを説明できるようにする。\"}],\"trapExamples\":[{\"question\":\"「彼女は私の友達です。」を英語にしなさい。\",\"wrongAnswer\":\"Her is my friend.\",\"trapExplanation\":\"she の行は her が二回出てくるので、目的格・所有格の her を主語の位置にも使ってしまう。会話で her をよく耳にすることも影響する。\",\"correctAnswer\":\"She is my friend.\",\"correctExplanation\":\"主語の位置には主格 she を使う。her は「彼女を」（目的格）または「彼女の」（所有格）の形である。I know her.（彼女を知っている）／I know her sister.（彼女の姉を知っている）と並べて、位置ごとの形を確かめる。\"},{\"question\":\"「この本は彼女のものです。」を英語にしなさい。\",\"wrongAnswer\":\"This book is her.\",\"trapExplanation\":\"「彼女の」＝her と覚えているため、「彼女のもの」も her でよいと考えてしまう。she の行に形が三つ（her が二回、hers が一回）あることが混乱のもとになる。\",\"correctAnswer\":\"This book is hers.\",\"correctExplanation\":\"後ろに名詞がなく、単独で「〜のもの」を表すときは所有代名詞 hers を使う。her は後ろに名詞をともなう所有格（her book）か、動詞・前置詞の後ろに来る目的格（I know her.）である。she – her – her – hers と唱えて、四つの位置を区別する。\"}]}",
"{\"id\":\"eigo_s109\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"再帰代名詞：myself・yourself・themselves\",\"description\":\"「自分自身」を表す形の作り方と、決まった言い方をおさえる\",\"intro\":\"「自分で作った」を I made it by me. とは言えません。by myself が正しい形です。主語と同じ人がもう一度出てくるときは、目的格ではなく myself のような形にします。作り方には規則があります。\",\"order\":609,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"単数は -self、複数は -selves を付ける（myself／ourselves）。\",\"myself, yourself, himself, herself, itself／ourselves, yourselves, themselves。\",\"一・二人称は所有格に付け（my+self, your+self）、三人称は目的格に付ける（him+self, them+selves）。\",\"× hisself／× theirselves は誤り。himself／themselves が正しい。\",\"主語と同じ人を動詞の後ろに置くときは、目的格ではなく再帰代名詞にする（He saw himself.）。\",\"by oneself（一人で）／enjoy oneself（楽しむ）／help oneself to（自由に取って食べる）。\"],\"sections\":[{\"heading\":\"形の作り方\",\"body\":\"「自分自身」を表す代名詞を再帰代名詞という。作り方には規則がある。\\n\\n■ 一覧\\nI → myself（私自身）\\nyou → yourself（あなた自身）\\nhe → himself（彼自身）\\nshe → herself（彼女自身）\\nit → itself（それ自体）\\nwe → ourselves（私たち自身）\\nyou → yourselves（あなたがた自身）\\nthey → themselves（彼ら自身）\\n\\n■ 作り方の規則\\n①複数は -selves になる（self の複数形が selves だから。leaf → leaves と同じ変化）。\\n②一人称・二人称は所有格に付ける：my + self／your + self／our + selves\\n③三人称は目的格に付ける：him + self／them + selves／her + self（her は所有格と目的格が同じ形）\\n⚠ 注意：③の規則を知らないと、hisself（× 所有格 his に付けた形）や theirselves（× 所有格 their に付けた形）と書いてしまう。正しくは himself, themselves である。\\n\\n■ you の単数と複数\\n一人に言うなら yourself、二人以上に言うなら yourselves。\\n例）Did you hurt yourself?（けがをしましたか）…相手が一人\\n例）Help yourselves to the cake.（ケーキを自由に取ってください）…相手が複数\\n\\n★ ポイント：三人称だけ目的格から作る、と覚えておけば hisself・theirselves の誤りは防げる。\",\"figureId\":\"xf_eigo_s109\",\"mangaId\":\"eigo_s109_xm\"},{\"heading\":\"使い方と決まった言い方\",\"body\":\"再帰代名詞は、主語と同じ人・物をもう一度さすときに使う。\\n\\n■ 動詞の後ろで使う\\nHe looked at himself in the mirror.（彼は鏡で自分を見た）\\nShe hurt herself.（彼女はけがをした＝自分を傷つけた）\\nI introduced myself to the class.（私はクラスで自己紹介をした）\\n⚠ 注意：He looked at him. と書くと、「彼は（別の）彼を見た」という意味になり、別人をさしてしまう。主語と同じ人なら必ず再帰代名詞を使う。\\n\\n■ 意味を強めるために使う\\nI made this cake myself.（このケーキは私が自分で作った）\\nThe teacher himself said so.（先生自身がそう言った）\\n※ この使い方では、取りのぞいても文が成り立つ。\\n\\n■ 覚えるべき熟語\\nby oneself（一人で・独力で）：He went there by himself.（彼は一人でそこへ行った）\\nfor oneself（自分のために・自分で）：Think for yourself.（自分の頭で考えなさい）\\nenjoy oneself（楽しく過ごす）：We enjoyed ourselves at the party.（パーティーで楽しく過ごした）\\nhelp oneself to（〜を自由に取って食べる）：Help yourself to the cookies.（クッキーを自由に食べてね）\\nsay to oneself（心の中で思う）：He said to himself, “I can do it.”\\ntake care of oneself（体に気をつける）：Take care of yourself.（お大事に）\\n\\n★ ポイント：熟語では oneself の部分を、主語に合わせて変える。主語が he なら himself、we なら ourselves になる。\"}],\"trapExamples\":[{\"question\":\"「彼は一人でそこへ行きました。」を英語にしなさい。\",\"wrongAnswer\":\"He went there by hisself.\",\"trapExplanation\":\"myself が my + self、yourself が your + self なので、he の所有格 his に self を付ければよいと考えてしまう。規則を最後まで確かめていないのが原因。\",\"correctAnswer\":\"He went there by himself.\",\"correctExplanation\":\"三人称の再帰代名詞は、所有格ではなく目的格に付けて作る。him + self で himself、them + selves で themselves となる。hisself, theirselves という形は存在しない。「一・二人称は所有格から、三人称は目的格から」と規則で覚える。\"},{\"question\":\"「彼は鏡で自分の姿を見た。」を英語にしなさい。\",\"wrongAnswer\":\"He looked at him in the mirror.\",\"trapExplanation\":\"「彼を見た」だから目的格 him でよい、と考えてしまう。日本語の「自分」を英語でどう表すかを意識していないと起きる誤りである。\",\"correctAnswer\":\"He looked at himself in the mirror.\",\"correctExplanation\":\"主語と同じ人をもう一度さすときは、目的格ではなく再帰代名詞を使う。He looked at him. と書くと、主語とは別の男性を見たという意味になってしまう。She hurt herself.（彼女はけがをした）も同じ形で、目的格を使うと別人を傷つけたことになる。\"}]}",
"{\"id\":\"eigo_s110\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"指示代名詞：this・that・these・those\",\"description\":\"距離と数で使い分ける指示語と、電話や紹介での決まった言い方を覚える\",\"intro\":\"電話で「もしもし、ケンです」と名乗るとき、英語では I am Ken. ではなく This is Ken. と言います。自分を this で指すのは不思議ですが、これが決まった言い方です。this と that の使い分けを見ていきます。\",\"order\":610,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"近い＋単数＝this／遠い＋単数＝that／近い＋複数＝these／遠い＋複数＝those。\",\"複数の these・those の後ろの名詞は複数形になる（these books）。\",\"主語が these・those なら動詞は are・were。\",\"人を紹介するときは This is 〜.（こちらは〜さんです）を使う。\",\"電話で名乗るときは This is Ken (speaking).、相手を確かめるときは Is that Ken?。\"],\"sections\":[{\"heading\":\"距離と数で決まる四つの語\",\"body\":\"this・that・these・those は、話し手からの距離と、さすものの数で使い分ける。\\n\\n■ 四つの使い分け\\nthis（これ・この）…近くにある一つ\\nthat（あれ・あの）…遠くにある一つ\\nthese（これら・これらの）…近くにある二つ以上\\nthose（あれら・あれらの）…遠くにある二つ以上\\n\\n■ 例文\\nThis is my pen.（これは私のペンです）\\nThat is your bag.（あれはあなたのかばんです）\\nThese are my books.（これらは私の本です）\\nThose are their bikes.（あれらは彼らの自転車です）\\n\\n■ 名詞の前に置く使い方\\nthis book（この本）／that car（あの車）／these books（これらの本）／those cars（あれらの車）\\n⚠ 注意：these・those の後ろの名詞は必ず複数形にする。× these book は誤り。\\n\\n■ 動詞の形\\nThis is my pen.（単数 → is）\\nThese are my pens.（複数 → are）\\nThat was a good movie.（単数・過去 → was）\\nThose were good movies.（複数・過去 → were）\\n\\n■ 単数の文を複数の文に書きかえる\\nIs this your pen? → Are these your pens?\\nThat is a beautiful flower. → Those are beautiful flowers.\\n※ ①this/that ②be動詞 ③a の消去 ④名詞の複数形、の四か所すべてを直す。\",\"figureId\":\"lf_eigoext03_110\"},{\"heading\":\"決まった言い方\",\"body\":\"this・that には、日本語と形が合わない決まった使い方がある。会話文の問題で必ず出る。\\n\\n■ 人を紹介するとき\\nThis is my friend, Ken.（こちらは私の友達のケンです）\\n※ 人に対して「これは」とは訳さず、「こちらは」と訳す。He is my friend, Ken. でも通じるが、紹介の場面では This is 〜. を使う。\\n\\n■ 電話での言い方\\nThis is Ken speaking.（もしもし、ケンです）…自分が名乗る\\nIs that Ken?／Who is this?（ケンですか／どちらさまですか）…相手を確かめる\\n⚠ 注意：電話で名乗るときに I am Ken. とは言わない。決まった言い方として覚える。\\n\\n■ 前に言ったことをさす that\\nHe said nothing. That made me angry.（彼は何も言わなかった。そのことが私を怒らせた）\\n※ that は、前の文の内容全体をさすことができる。\\n\\n■ 「あちらの人々」を表す those\\nThose people are from Canada.（あちらの人々はカナダ出身だ）\\nThose who work hard will succeed.（努力する人々は成功するだろう）※ やや難しい言い方\\n\\n■ 会話でよく使う形\\nWhat is this?（これは何ですか）→ It is a camera.（カメラです）\\n※ 答えるときは this ではなく it を使う。\\nIs this yours?（これはあなたのものですか）→ Yes, it is.\\n「これは何？」に対して「それは〜です」と答える、という日本語と同じ流れになる。\",\"mangaId\":\"eigo_s110_xm\"}],\"trapExamples\":[{\"question\":\"「これらは私の本です。」を英語にしなさい。\",\"wrongAnswer\":\"This are my books.\",\"trapExplanation\":\"名詞 books を複数形にしたところで満足してしまい、指示語と be動詞の組み合わせを見直さない。「これら」にあたる語が this とは別にあることを忘れている。\",\"correctAnswer\":\"These are my books.\",\"correctExplanation\":\"this の複数形は these である。主語が複数になったので be動詞も are になる。単数の文を複数の文に書きかえるときは、①this→these ②is→are ③a を消す ④名詞を複数形にする、の四か所をすべて直す。\"},{\"question\":\"電話で「もしもし、ケンです。」と名乗るとき、正しい言い方はどれですか。\",\"wrongAnswer\":\"I am Ken.\",\"trapExplanation\":\"「私はケンです」という日本語をそのまま英語にしてしまう。文法としては正しい文なので、誤りだと気づきにくい。\",\"correctAnswer\":\"This is Ken (speaking).\",\"correctExplanation\":\"電話で名乗るときは This is 〜. を使うのが英語の決まった言い方である。相手を確かめるときは Is that Ken? または Who is this? と言う。人を紹介するときの This is my friend, Ken. と合わせて、this が人をさす場面として覚えておく。\"}]}",
"{\"id\":\"eigo_s111\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"it と one の使い分け\",\"description\":\"同じ物をさす it と、同じ種類の別の物をさす one を区別する\",\"intro\":\"「ペンをなくしたので、新しいのを買った」の「新しいの」は it でしょうか。ちがいます。なくしたペンとは別のものなので a new one です。同じものか、同じ種類の別のものか。日本語の「の」では区別できません。\",\"order\":611,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"it＝前に出たものと「まったく同じ物」。one＝同じ種類の「別の物」。\",\"複数のときは them（同じ物）／ones（別の物）を使う。\",\"one に形容詞が付くと a が必要（a red one／a new one）。\",\"the one は「その〜」と特定するときに使う（the one on the desk）。\",\"不可算名詞には one を使えない。some を使う（I need some.）。\"],\"sections\":[{\"heading\":\"it と one のちがい\",\"mangaId\":\"eigo_s111_manga\",\"body\":\"どちらも前に出た名詞のくり返しをさけるための語だが、さす中身がちがう。\\n\\n■ it＝まったく同じ物\\n例）I lost my pen. I looked for it, but I couldn’t find it.\\n（ペンをなくした。それをさがしたが、見つけられなかった）\\n※ さがしたのは、なくしたその同じペンである。\\n\\n■ one＝同じ種類の別の物\\n例）I lost my pen, so I bought a new one.\\n（ペンをなくしたので、新しいのを買った）\\n※ 買ったのは別の新しいペンである。it を使うと「なくしたそのペンを買った」という変な意味になってしまう。\\n\\n■ 複数のとき\\nthem＝同じ物たち：I have two dogs. I take them for a walk every day.\\nones＝別の物たち：These apples are small. I want bigger ones.\\n\\n■ 見分け方\\n「そのもの自体」なら it、「同じようなもの」なら one。日本語では「それ」「の」で言い分けるので、和訳から判断してもよい。\\n例）Do you have a pen? — Yes, I have one.（ペンを持っていますか。—はい、1本持っています）\\n※ 相手の言ったペンそのものではなく、自分の持っているペンなので one。\",\"figureId\":\"lf_eigoext03_111\"},{\"heading\":\"one の使い方の細かい約束\",\"body\":\"one には、形容詞や the と組み合わせるときの約束がある。\\n\\n■ 形容詞が付くと a が必要\\n◯ a red one（赤いの）／a new one（新しいの）／a big one（大きいの）\\n× red one\\n例）This bag is too small. I want a bigger one.（このかばんは小さすぎる。もっと大きいのがほしい）\\n※ 何も付かない場合は a を付けない。I need one.（1つ必要だ）\\n\\n■ the one＝その〜\\n特定できるときは the one を使う。\\n例）Which is your umbrella? — The one by the door.（どれがあなたのかさですか。—ドアのそばのです）\\n例）This bike is the one I bought last year.（この自転車は、私が去年買ったものです）\\n\\n■ 複数形は ones\\n例）I like these shoes better than those ones.（あれらよりこれらのくつのほうが好きだ）\\n例）Which cakes do you want? — The chocolate ones, please.\\n\\n■ 不可算名詞には使えない\\none は数えられる名詞のかわりにしか使えない。\\n× Do you have any water? — Yes, I have one.\\n◯ Do you have any water? — Yes, I have some.\\n⚠ 注意：数えられない名詞のくり返しをさけるときは some / any / it を使う。\\n\\n■ まとめの練習\\nI don’t like this cap. Show me another （　）.→ one\\nWhere is my key? I put （　） on the table.→ it\\nThese pencils are old. I need new （　）.→ ones\"}],\"trapExamples\":[{\"question\":\"「私はペンをなくしたので、新しいのを買いました。」を英語にしなさい。\",\"wrongAnswer\":\"I lost my pen, so I bought it.\",\"trapExplanation\":\"日本語の「新しいの」の「の」を、前に出たペンをさす it だと考えてしまう。it と one のちがいを「同じ物か別の物か」でとらえていないのが原因。\",\"correctAnswer\":\"I lost my pen, so I bought a new one.\",\"correctExplanation\":\"買ったのは、なくしたペンとは別の新しいペンなので one を使う。it を使うと「なくしたそのペンを買った」という意味になり、話が通らない。まったく同じ物をさすときだけ it を使い、同じ種類の別の物には one を使う。\"},{\"question\":\"「このかばんは小さすぎます。もっと大きいのがほしい。」の後半を英語にしなさい。\",\"wrongAnswer\":\"I want bigger one.\",\"trapExplanation\":\"one は代名詞だから冠詞はいらないと考えてしまう。I want one. という形が正しいことも、a を落とす原因になる。\",\"correctAnswer\":\"I want a bigger one.\",\"correctExplanation\":\"one に形容詞が付くと、ふつうの名詞と同じように a / an が必要になる。a new one, a red one, a bigger one。形容詞が付かない場合は I need one. のように a を付けない。複数なら ones を使い、a は付けない（I want bigger ones.）。\"}]}",
"{\"id\":\"eigo_s112\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"some・any・another・the other\",\"description\":\"数や残りの数によって使い分ける不定代名詞を整理する\",\"intro\":\"「もう1杯いかがですか」は Would you like another cup? と言います。another は an と other が合わさった語なので、a は付きません。some と any の使い分けとあわせて、残りの数で決まるしくみを見ます。\",\"order\":612,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"some は肯定文、any は疑問文・否定文で使うのが原則。\",\"人にすすめる疑問文では some を使う（Would you like some tea?）。\",\"another＝an + other。「もう一つ（残りがまだある）」を表し、a は付けない。\",\"2つのうち残りの1つは the other。3つ以上で残り全部は the others。\",\"「ほかのいくつか（特定しない）」は others、「ほかの〜」は other＋複数名詞。\"],\"sections\":[{\"heading\":\"some と any\",\"body\":\"some と any は、どちらも「いくつかの・いくらかの」を表すが、使う文の種類がちがう。\\n\\n■ 原則\\nsome → 肯定文　　any → 疑問文・否定文\\n例）I have some questions.（質問がいくつかあります）\\n例）Do you have any questions?（質問はありますか）\\n例）I don’t have any questions.（質問はありません）\\n\\n■ 数えられる名詞・数えられない名詞のどちらにも使える\\nsome books（何冊かの本）／some water（いくらかの水）\\nany pens（何本かのペン）／any money（いくらかのお金）\\n\\n■ 例外①：すすめる・たのむ疑問文では some\\nWould you like some coffee?（コーヒーはいかがですか）\\nCan I have some water?（水をいただけますか）\\n※ 「あるはずだ」「もらえるはずだ」と思って言う疑問文では some を使う。\\n\\n■ 例外②：肯定文の any は「どんな〜でも」\\nAny student can join the club.（どの生徒でもクラブに入れる）\\nYou can take any book you like.（好きな本をどれでも取っていいですよ）\\n\\n■ 代名詞としての使い方\\n名詞を付けずに単独でも使える。\\n例）I need some pens. Do you have any?（ペンが何本かいる。持っていますか）\\n例）Some of my friends live in Tokyo.（友達の何人かは東京に住んでいる）\"},{\"heading\":\"another と the other\",\"body\":\"「もう一つ」「残りの一つ」は、残っている数によって形が変わる。ここは入試の頻出項目である。\\n\\n■ another＝an + other\\nまだ残りがいくつもあるときの「もう一つ・別の一つ」。\\n例）This cake is delicious. Can I have another?（このケーキはおいしい。もう一つもらえますか）\\n例）I don’t like this color. Show me another one.（この色は好きではない。別のを見せてください）\\n⚠ 注意：another にはすでに an が入っているので、a を付けない（× an another）。また後ろに複数形も置かない（× another books）。\\n\\n■ the other＝残りの一つ（もう決まっている）\\n2つのうち1つを取ったら、残りは1つに決まるので the other。\\n例）I have two dogs. One is white, and the other is black.\\n（犬を2ひき飼っている。1ぴきは白で、もう1ぴきは黒だ）\\n\\n■ the others＝残り全部（3つ以上）\\n例）There are five students. One is Japanese, and the others are Americans.\\n（生徒が5人いる。1人は日本人で、残りはみなアメリカ人だ）\\n\\n■ others＝ほかの人・物（特定しない）\\n例）Some like baseball, and others like soccer.\\n（野球が好きな人もいれば、サッカーが好きな人もいる）\\n\\n■ 整理\\n　　残りがまだ複数ある → another（1つ）／others（複数）\\n　　残りが決まっている → the other（1つ）／the others（複数）\\nthe が付くかどうかは、「残りが全部決まっているか」で判断する。\",\"figureId\":\"lf_eigoext03_112\",\"mangaId\":\"eigo_s112_xm\"}],\"trapExamples\":[{\"question\":\"「ペンを何本か持っていますか。」を英語にしなさい。\",\"wrongAnswer\":\"Do you have some pens?\",\"trapExplanation\":\"「何本か」＝some と一対一で覚えているため、疑問文でもそのまま some を使ってしまう。some を使う疑問文（すすめる文）が実際にあることも、判断を難しくする。\",\"correctAnswer\":\"Do you have any pens?\",\"correctExplanation\":\"ふつうの疑問文・否定文では any を使う。some を使うのは Would you like some tea? のように、相手にすすめたり、もらえると思ってたのんだりする疑問文の場合である。「たずねる」なら any、「すすめる」なら some と区別する。\"},{\"question\":\"「私は犬を2ひき飼っています。1ぴきは白で、もう1ぴきは黒です。」の後半を英語にしなさい。\",\"wrongAnswer\":\"One is white, and another is black.\",\"trapExplanation\":\"「もう1ぴき」を「もう一つ」と考えて another を選んでしまう。残りが1ぴきに決まっているかどうかを確かめていないのが原因である。\",\"correctAnswer\":\"One is white, and the other is black.\",\"correctExplanation\":\"2ひきのうち1ぴきを取れば、残りは1ぴきに決まる。決まっているものには the を付けるので the other となる。another は「残りがまだいくつもあるうちの、もう一つ」を表す。3つ以上で残り全部をさすときは the others を使う。\"}]}",
"{\"id\":\"eigo_s113\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"集合名詞：family・people・police\",\"description\":\"まとまりを表す名詞の単数・複数の扱いを整理する\",\"intro\":\"「私の家族は5人です」を My family is five. と言っても通じません。family はひとまとまりで単数あつかい、people はいつも複数あつかいです。数え方の感覚が日本語とずれる語をここで整理します。\",\"order\":613,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"family, team, class, group, club は、一つのまとまりとして単数あつかいにするのが基本。\",\"people は形が単数に見えても、いつも複数あつかい（people are）。\",\"police も複数あつかい（The police are coming.）。\",\"peoples は「諸民族」という別の意味になるので、「人々」の意味では -s を付けない。\",\"「家族は5人です」は There are five people in my family. などの形で表す。\"],\"sections\":[{\"heading\":\"まとまりを表す名詞\",\"body\":\"family（家族）や team（チーム）のように、複数の人が集まって一つのまとまりを作る名詞を集合名詞という。\\n\\n■ 一つのまとまりとして見る → 単数あつかい\\nMy family is large.（うちは大家族だ）\\nOur team is very strong.（私たちのチームはとても強い）\\nOur class has thirty students.（うちのクラスには30人の生徒がいる）\\n※ family, team, class, group, club はふつう単数あつかいで、is / has / was を使う。\\n\\n■ 複数形にもできる\\nまとまりが二つ以上あるときは、ふつうに複数形にする。\\n例）There are ten families in this building.（この建物には10世帯が住んでいる）\\n例）Two teams played in the final.（決勝には2チームが出た）\\n\\n■ 「家族は何人ですか」の言い方\\n日本語の「私の家族は5人です」を直訳すると誤りになる。\\n× My family is five.／× My family are five people.\\n◯ There are five people in my family.（私の家族は5人です）\\n◯ I have a family of five.\\n◯ My family has five members.\\n※ 入試の英作文では、There are 〜 in my family. の形を覚えておくと安全である。\\n\\n★ ポイント：集合名詞はまず単数あつかいと覚え、複数の建物・チームなど数がふえたときだけ複数形にする。\"},{\"heading\":\"people と police\",\"body\":\"形からは判断できないのに複数あつかいになる語がある。とくに people と police は必ず問われる。\\n\\n■ people（人々）\\nいつも複数あつかい。-s は付けない。\\n例）Many people were at the station.（駅にはたくさんの人がいた）\\n例）There are twenty people in this room.（この部屋には20人いる）\\n例）Japanese people are kind.（日本人は親切だ）\\n⚠ 注意：× There is many people.／× many peoples はどちらも誤り。\\n※ peoples と -s を付けると「諸民族」という別の意味になる。the peoples of Asia（アジアの諸民族）。\\n\\n■ police（警察）\\nいつも複数あつかい。the を付けて使うのがふつう。\\n例）The police are looking for the man.（警察はその男をさがしている）\\n例）Call the police!（警察を呼んで）\\n※ 警察官1人は a police officer と言う。× a police は誤り。\\n\\n■ その他の複数あつかいの語\\ncattle（牛の群れ）：The cattle are in the field.\\n※ 中学入試では people と police の二語をおさえれば十分である。\\n\\n■ 数え方のまとめ\\nperson（1人） → two people（2人）\\npolice officer（警察官1人） → three police officers（警察官3人）\\nfamily（1家族） → two families（2家族）\\nそれぞれ、数えるときにどの語を使うかを確かめておく。\"},{\"heading\":\"なぜ family は単数で、people は複数なのか\",\"mangaId\":\"eigo_s113_manga\",\"body\":\"family・team・class は、何人かの人を**ひとまとまりとして見た名前**です。まとまりが一つなら単数なので My family is large. と is を使い、まとまりが二つ以上（ten families）ならふつうに複数形にします。「私の家族は5人です」を My family is five. と言えないのは、family は「まとまり」であって「人数」ではないからで、人数を言うなら There are five people in my family. と人（people）を数えます。\\n\\npeople は形に -s がありませんが、**person の複数にあたる語**で、それ自体が「人々」という複数の意味を持っています。だから動詞は are / were で、-s を付けると「諸民族」という別の語になります。police も「警察官たち」を表す語で複数あつかいです。警察官一人は a police officer と言います。形に -s があるかどうかではなく、その語が何を表しているかで単複が決まります。\\n\\n■ 確かめのしかた\\n①family・team・class・group・club は**まとまり一つ→is / has**。まとまりが二つ以上→families・teams。\\n②人数を言うときは people を数える：There are five people in my family. ／ I have a family of five.\\n③people・police は**-s が無くても複数あつかい**：Many people were there. ／ The police are coming.\\n④× many peoples（諸民族の意味になる）、× a police（→a police officer）。person（1人）→two people（2人）と数える。\\n\\n★ ここがポイント：family は**まとまりの名前**なので一つなら単数、people は**person の複数にあたる語**なので -s が無くても複数。形の -s ではなく**その語が何を表すか**で動詞を決める。\",\"figureId\":\"xf_eigo_s113\"}],\"trapExamples\":[{\"question\":\"（　）に is か are を入れなさい。　The police （　） looking for the man.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"police に -s が付いていないので単数だと考え、また「警察」という組織を一つのまとまりとしてとらえて is を選んでしまう。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"police は、警察官たちを表す複数あつかいの語なので動詞は are になる。1人をさすときは a police officer と言う。同じく people も -s が付いていないが複数あつかいで、Many people were there. のように are / were を使う。\"},{\"question\":\"「公園にはたくさんの人がいました。」を英語にしなさい。\",\"wrongAnswer\":\"There were many peoples in the park.\",\"trapExplanation\":\"「たくさんの人」だから複数形にしなければ、と考えて people にさらに -s を付けてしまう。people 自体がすでに複数を表していることを見落としている。\",\"correctAnswer\":\"There were many people in the park.\",\"correctExplanation\":\"people は person の複数にあたる語で、それ自体が複数を表すため -s を付けない。peoples と書くと「諸民族」という別の意味になってしまう。children や men に -s を重ねないのと同じ考え方である。\"}]}",
"{\"id\":\"eigo_s114\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"固有名詞の書き方と使い方\",\"description\":\"大文字で書き始める語の範囲と、固有名詞に冠詞を付けない原則を確認する\",\"intro\":\"月曜日は Monday、英語は English。文のとちゅうでも大文字で書き始めます。ところが春は spring、算数は math と小文字のままです。同じ「名前」に見えるのに分かれるのはなぜか、線引きをはっきりさせます。\",\"order\":614,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"人名・地名・国名・言語名・曜日・月・祝日は、文の途中でも大文字で書き始める。\",\"季節（spring, summer）と教科の多く（math, science）は小文字のまま。ただし English は言語名なので大文字。\",\"固有名詞には a も the も付けないのが原則（Japan／Tokyo／Ken）。\",\"言語名に the は付けない（× the English）。\",\"敬称・略号も大文字：Mr., Ms., Dr., Mt., Lake, St.。\"],\"sections\":[{\"heading\":\"大文字で書き始める語\",\"body\":\"英語では、世界に一つしかない名前を大文字で書き始める。文の途中にあっても大文字にする。\\n\\n■ 大文字にするもの\\n①人名：Ken, Ms. Tanaka, Bob Smith\\n②地名・国名：Japan, Osaka, London, Asia\\n③言語名・国民名：English, Japanese, French, American\\n④曜日：Monday, Sunday\\n⑤月：January, April, December\\n⑥祝日・行事：Christmas, New Year’s Day\\n⑦建物・組織名：Tokyo Station, Osaka Castle\\n⑧書名・題名の主な語：The Old Man and the Sea\\n⑨I（私は）はいつも大文字\\n\\n■ 小文字のままのもの\\n①季節：spring, summer, fall（autumn）, winter\\n②教科の多く：math, science, music, history（ただし English, Japanese は言語名なので大文字）\\n③方角：east, west, north, south\\n④動物・物の名前：dog, apple, desk\\n\\n■ 例文で確かめる\\nI study English on Monday.（月曜日に英語を勉強する）\\nWe go to Kyoto in spring.（春に京都へ行く）\\nMy birthday is in December.（誕生日は12月です）\\n⚠ 注意：english, monday のように小文字で書くのは、日本人にとても多い誤りである。書き取りでは必ず頭の文字を確かめる。\",\"figureId\":\"xf_eigo_s114\",\"mangaId\":\"eigo_s114_xm\"},{\"heading\":\"固有名詞と冠詞\",\"body\":\"固有名詞は、それ自体で「どれのことか」が決まっているので、原則として a も the も付けない。\\n\\n■ 冠詞を付けない\\nJapan（× the Japan）／Tokyo（× a Tokyo）／Ken（× the Ken）／Mt. Fuji（× the Mt. Fuji）\\n例）I live in Japan.／This is Ken.／We climbed Mt. Fuji.\\n\\n■ 言語名にも the を付けない\\n◯ I speak English.（私は英語を話す）\\n× I speak the English.\\n◯ She can speak Japanese well.（彼女は日本語をじょうずに話せる）\\n※ ただし「英語の授業」は an English class、「英語の先生」は an English teacher のように、後ろに名詞が来れば冠詞が必要になる。\\n\\n■ 例外的に the が付く固有名詞（復習）\\n川・海・山脈・複数形の国名・新聞・船：the Shinano River／the Pacific Ocean／the Alps／the United States／the Asahi Shimbun\\n\\n■ 敬称・略号\\nMr. Smith（スミスさん・男性）／Ms. Tanaka（田中さん・女性）／Dr. Brown（ブラウン先生・医師や博士）／Mt. Fuji（富士山）／Lake Biwa（琵琶湖）／St. Mary（聖マリア）\\n※ Mr., Ms., Dr., Mt. の後ろにはピリオドを打ち、次の語との間を一つあける。\\n⚠ 注意：Mr. の後ろに下の名前だけを置くことはしない。Mr. Bob ではなく Mr. Smith（名字）とする。\\n\\n■ 家族を表す語の大文字\\n呼びかけや名前のかわりに使うときは大文字にする。\\n例）Thank you, Mom.（ありがとう、お母さん）\\n例）My mother is a nurse.（母は看護師です）…ふつうの名詞なので小文字\"}],\"trapExamples\":[{\"question\":\"次の英文の誤りを直しなさい。　i study english on monday.\",\"wrongAnswer\":\"i study english on monday.（そのまま）\",\"trapExplanation\":\"日本語には大文字・小文字の区別がないため、単語のつづりさえ合っていればよいと考えてしまう。とくに文の途中にある english, monday は見落としやすい。\",\"correctAnswer\":\"I study English on Monday.\",\"correctExplanation\":\"「私は」の I はいつも大文字、言語名 English と曜日 Monday も文の途中でも大文字で書き始める。一方、教科の math や science、季節の spring は小文字のままである。書いたあとに頭の文字を一つずつ確かめる習慣をつける。\"},{\"question\":\"「私は英語を話します。」を英語にしなさい。\",\"wrongAnswer\":\"I speak the English.\",\"trapExplanation\":\"play the piano のように the が入る形を覚えていると、English にも the を付けたくなる。また「その英語」と特定している気持ちになることも原因である。\",\"correctAnswer\":\"I speak English.\",\"correctExplanation\":\"言語名は固有名詞なので冠詞を付けない。She can speak Japanese. も同じ。ただし an English class（英語の授業）、an English teacher（英語の先生）のように、後ろに名詞が続く場合は冠詞が必要になる。名詞が続くかどうかで判断する。\"}]}",
"{\"id\":\"eigo_s115\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"名詞・冠詞・代名詞の総合演習\",\"description\":\"このユニットで学んだ規則を、誤り訂正と英作文の形で総点検する\",\"intro\":\"I have many homeworks. のどこが誤りか、すぐ指摘できるでしょうか。名詞・冠詞・代名詞のミスは、文全体が読めていても最後の1文字で失点します。見直しの手順を決めて、自分で点検できるようにします。\",\"order\":615,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"見直しの手順：①数えられるか ②単数か複数か ③冠詞は適切か ④代名詞の形は位置に合っているか。\",\"不可算名詞に a・-s・many を付けていないか（homework, information, advice, money, water）。\",\"数字・many・these の後ろの名詞が複数形になっているか。\",\"「単位＋of＋不可算名詞」で、-s が of の前に付いているか。\",\"代名詞は、主語なら主格、名詞の前なら所有格、動詞・前置詞の後ろなら目的格。\",\"決まった言い方（play the piano／go to school／by bus／once a week）は形ごと暗記する。\"],\"sections\":[{\"heading\":\"答案を見直す四つの手順\",\"body\":\"英作文を書き終えたら、次の四点を順に点検する。この手順を通すだけで、失点は大きく減る。\\n\\n■ 手順①　名詞は数えられるか\\nhomework, information, advice, furniture, money, water, bread は不可算。a も -s も many も付けられない。\\n× many homeworks → ◯ a lot of homework\\n× two advices → ◯ two pieces of advice\\n\\n■ 手順②　単数か複数か\\n数字・many・these の後ろは複数形（some は不可算名詞にも付くので別あつかい）。one・each・every の後ろは単数。\\n× three book → ◯ three books\\n× many student likes → ◯ many students like\\n\\n■ 手順③　冠詞は正しいか\\n数えられる単数を裸で置いていないか（× I have bag.）。\\n不可算・複数に a を付けていないか（× a water／× a books）。\\n所有格や this と冠詞を重ねていないか（× a my book）。\\n世界に一つのもの・楽器・最上級に the があるか（the sun／play the piano／the tallest）。\\n\\n■ 手順④　代名詞の形は位置に合っているか\\n主語 → 主格（I, he, she, they）\\n名詞の前 → 所有格（my, his, her, their）\\n動詞・前置詞の後ろ → 目的格（me, him, her, them）\\n単独で「〜のもの」→ 所有代名詞（mine, his, hers, theirs）\\n\\n★ ポイント：手順①〜④はこの順で行う。名詞を決めてからでないと、冠詞も代名詞も決まらないからである。\",\"figureId\":\"xf_eigo_s115\",\"mangaId\":\"eigo_s115_xm\"},{\"heading\":\"総合練習と、まちがえやすい形の総点検\",\"body\":\"実際の入試で出る形式で確かめる。\\n\\n■ 誤りを一か所直す問題\\n①I have a lot of homeworks today.　→ homework\\n②There is many people in the park.　→ There are\\n③My mother bought two breads.　→ two loaves of bread\\n④She plays a piano very well.　→ the piano\\n⑤This is a my friend.　→ a friend of mine\\n⑥I know he very well.　→ him\\n⑦That bike is her.　→ hers\\n⑧I go to the bed at ten.　→ go to bed\\n⑨The sun rises in east.　→ in the east\\n⑩He went there by hisself.　→ by himself\\n\\n■ 英作文\\n①「私は毎朝、水をコップ1ぱい飲みます。」\\n　→ I drink a glass of water every morning.\\n②「先週、新しいくつを1足買いました。」\\n　→ I bought a pair of new shoes last week.\\n③「彼は週に2回ギターをひきます。」\\n　→ He plays the guitar twice a week.\\n④「これらは私の本ではありません。彼らのものです。」\\n　→ These are not my books. They are theirs.\\n⑤「情報はインターネットでたくさん手に入る。」\\n　→ We can get a lot of information on the Internet.\\n\\n■ 最後に覚え直す形\\n不可算：homework／information／advice／furniture／money／water／bread／news\\n単位：a glass of／a cup of／a piece of／a sheet of／a slice of／a pair of\\n不規則複数：man–men／woman–women／child–children／foot–feet／tooth–teeth／mouse–mice／sheep–sheep／fish–fish\\n代名詞：I–my–me–mine／he–his–him–his／she–her–her–hers／they–their–them–theirs\\nこれらを口に出して言えるようになれば、このユニットは完成である。\"}],\"trapExamples\":[{\"question\":\"次の英文の誤りを直しなさい。　There are a lot of informations on internet.\",\"wrongAnswer\":\"There are a lot of informations on internet.（そのまま）\",\"trapExplanation\":\"「情報がたくさん」なので複数形にするべきだと考え、さらに internet を固有名詞のように感じて冠詞を落としてしまう。二か所同時にまちがえる典型的な文である。\",\"correctAnswer\":\"There is a lot of information on the Internet.\",\"correctExplanation\":\"information は不可算名詞なので -s を付けず、動詞も単数あつかいで is になる。また「インターネットで」は on the Internet と the を付ける決まった言い方である。不可算名詞と決まった表現の両方を同時に点検する必要がある。\"},{\"question\":\"「母はパンを2斤と牛乳を3本買いました。」を英語にしなさい。\",\"wrongAnswer\":\"My mother bought two breads and three milks.\",\"trapExplanation\":\"日本語の「2斤」「3本」につられて、bread と milk のほうに -s を付けてしまう。不可算名詞は単位のことばを借りて数える、という形が身についていないと必ず起きる。\",\"correctAnswer\":\"My mother bought two loaves of bread and three bottles of milk.\",\"correctExplanation\":\"bread も milk も不可算名詞なので複数形にできない。数えるときは単位のことばを借り、複数形にするのはその単位のほうにする（loaf → loaves、bottle → bottles）。「-s は of の前に付く」という原則をここでも使う。\"}]}",
"{\"id\":\"eigo_s116\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在形①：くり返す習慣を表す\",\"description\":\"現在形は「今この瞬間」ではなく「いつもくり返していること」を表す、という基本をつかむ\",\"intro\":\"「私は英語を勉強しています」を英語にすると、I study English. と I am studying English. の2つが考えられます。前者は「ふだん勉強している」、後者は「今まさに勉強中」。英語の現在形は、実は今この瞬間を表しません。\",\"order\":616,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"現在形の中心の意味は「今この瞬間の動作」ではなく「くり返している習慣」。\",\"every day / every Sunday / usually / always / often / sometimes がある文はまず現在形。\",\"主語が三人称単数（he・she・it・my father など）のときだけ動詞に -s／-es が付く。\",\"「今まさに〜している」は現在進行形（be＋~ing）で表し、現在形とは指す時間がちがう。\",\"否定文・疑問文では do／does を使い、そのとき動詞は必ず原形にもどす。\"],\"sections\":[{\"heading\":\"現在形が指している「時間」\",\"body\":\"英語の「現在形」という名前は、じつはまぎらわしい。現在形が表すのは「今この瞬間にしていること」ではなく、「ふだんくり返していること」だからである。\\n\\n例）I play soccer every Sunday.（私は毎週日曜日にサッカーをします）\\nこの文は、今この瞬間にサッカーをしているとは言っていない。先週の日曜もして、今週の日曜もして、来週の日曜もするだろう、という「くり返し」を表している。\\n\\n例）My father gets up at six every morning.（父は毎朝6時に起きます）\\nこれも同じで、毎朝くり返される習慣を述べている。\\n\\n■ 現在形といっしょに使われやすい語\\nevery day（毎日）・every week（毎週）・every Sunday（毎週日曜日）・on Sundays（日曜日にはいつも）\\nalways（いつも）・usually（たいてい）・often（よく）・sometimes（ときどき）・never（けっして〜ない）\\n\\nこれらの語が文の中にあれば、その文はふつう現在形である。（ただし always は「いつも〜ばかりしている」と不満を表すときに進行形と使うことがある。入試ではまず現在形と考えてよい。）\\n\\n★ ポイント：現在形＝「点がくり返し並んでいる」イメージ。今この瞬間だけを指す一本の帯（現在進行形）とは、指している時間そのものがちがう。\",\"figureId\":\"lf_eigoext04_116\"},{\"heading\":\"主語によって動詞の形が変わる\",\"mangaId\":\"eigo_s116_manga\",\"body\":\"現在形でいちばん失点しやすいのが、主語が三人称単数のときに動詞へ -s を付け忘れることである。\\n\\n■ 三人称単数とは\\n自分（I）でも相手（you）でもない、一人（一つ）のもの。\\nhe / she / it / Ken / my mother / that dog / this book / everyone など。\\n\\n例）I play tennis.　You play tennis.　We play tennis.　They play tennis.（-s なし）\\n　　He plays tennis.　She plays tennis.　Ken plays tennis.（-s あり）\\n\\n■ 否定文・疑問文では -s が do のほうへ移る\\n否定文：He does not（doesn't）play tennis.　← plays ではなく play にもどる\\n疑問文：Does he play tennis?　― Yes, he does. / No, he doesn't.\\n「-s は文の中に一つだけ」と覚えるとよい。does に -s があるので、動詞は原形にもどるのである。\\n\\n⚠ 注意：主語が長いと数を見あやまりやすい。My father and my brother play tennis.（父と兄＝二人なので -s なし）／ The boy with two dogs runs fast.（主語は The boy 一人なので -s あり）。「〜と〜」でつながれていれば複数、前置詞のかたまりが後ろに付いているだけなら、その前の名詞が主語である。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は毎朝6時に起きます。」\",\"wrongAnswer\":\"He get up at six every morning.\",\"trapExplanation\":\"日本語には「主語が一人だと動詞の形が変わる」という決まりがないので、he と get をそのままつなげてしまう。日本語で考えてから英語に置きかえる子ほど落としやすい。\",\"correctAnswer\":\"He gets up at six every morning.\",\"correctExplanation\":\"主語 He は三人称・単数、そして時制は現在なので、動詞に -s を付けて gets にする。英作文では書き終えたあとに「主語は he・she・it のどれかに置きかえられるか」を必ず確認する習慣をつける。\"},{\"question\":\"次の日本語を英語にしなさい。「私は今、宿題をしています。」\",\"wrongAnswer\":\"I do my homework now.\",\"trapExplanation\":\"「現在のこと＝現在形」と覚えているため、now があっても現在形で書いてしまう。しかし現在形は「毎日する」という習慣の意味になり、「今まさにしている」という意味にはならない。\",\"correctAnswer\":\"I am doing my homework now.\",\"correctExplanation\":\"今この瞬間に進行中の動作は、現在進行形 be動詞＋~ing で表す。now・right now・at this moment などがあれば進行形を疑う。I do my homework every day.（毎日する＝習慣）との差をセットで覚える。\"}]}",
"{\"id\":\"eigo_s117\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在形②：三人称単数現在の -s のつづり\",\"description\":\"-s／-es の付け方の四つのパターンと、主語の数の見きわめ方を身につける\",\"intro\":\"study は studies なのに、play は plays。同じ y で終わるのに変わり方がちがいます。しかも -s が付くのは「三人称・単数・現在」の3つがそろったときだけ。1つでも欠ければ付きません。条件から確認します。\",\"order\":617,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"-s が付くのは「三人称・単数・現在」の三つがそろったときだけ。\",\"s, x, ch, sh, o で終わる動詞は -es（passes, mixes, watches, washes, goes, does）。\",\"「子音字＋y」は y を i に変えて -es（study→studies, carry→carries, fly→flies）。\",\"「母音字＋y」はそのまま -s（play→plays, enjoy→enjoys, stay→stays）。\",\"have だけは特別な形 has になる。\"],\"sections\":[{\"heading\":\"-s／-es の付け方 四つのパターン\",\"body\":\"① そのまま -s を付ける（いちばん多い）\\nplay→plays　like→likes　run→runs　read→reads　want→wants　live→lives\\n\\n② s, x, ch, sh, o で終わる語は -es\\npass→passes　mix→mixes　teach→teaches　watch→watches　wash→washes　finish→finishes　go→goes　do→does\\n（発音しにくいので、間に e を入れて「イズ」と読めるようにしていると考えるとよい）\\n\\n③ 「子音字＋y」は y を i に変えて -es\\nstudy→studies　carry→carries　fly→flies　cry→cries　try→tries\\ny の直前が a, i, u, e, o 以外（子音字）のときだけこの変え方をする。\\n\\n④ 「母音字＋y」はそのまま -s\\nplay→plays　enjoy→enjoys　stay→stays　buy→buys\\ny の直前が a や o（母音字）なら、何も変えずに -s を付けるだけ。\\n\\n■ 特別な形\\nhave→has（haves とはならない）\\nbe動詞は am / is / are と、はじめから形が決まっている。\\n\\n★ ポイント：③と④の見分けは「y の一つ前の文字」だけを見る。study の t は子音字→ studies、play の a は母音字→ plays。この一手間で確実に得点できる。\",\"figureId\":\"xf_eigo_s117\",\"mangaId\":\"eigo_s117_xm\"},{\"heading\":\"主語の数を見あやまらない\",\"body\":\"-s のルールを覚えても、そもそも主語の数を取りちがえると意味がない。入試で狙われるのは次のような形である。\\n\\n■ 主語が「〜と〜」でつながれているとき → 複数\\nKen and Yumi go to the same school.（ケンとユミ＝二人なので -s なし）\\nMy brother and I like baseball.（兄と私＝二人なので -s なし）\\n\\n■ 主語の後ろに前置詞のかたまりが付いているとき → 前の名詞が主語\\nThe boy with two dogs runs in the park.（主語は The boy＝一人なので runs）\\nThe books on the desk are mine.（主語は The books＝複数）\\nwith two dogs や on the desk は、主語の説明をしているだけで主語ではない。\\n\\n■ 「みんな」「だれも」を表す語は単数あつかい\\nEveryone knows his name.（everyone は単数）\\nEvery student has a computer.（every＋単数名詞は単数）\\n\\n⚠ 注意：日本語で「私の兄と私は」と言うと最後が「私」なので、つい I だけに合わせて動詞を選んでしまう。しかし主語全体は二人＝複数なので、-s は付けない。英文を書いたら、主語を he / she / it / they のどれかに置きかえてみて確かめる。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼女は毎日、音楽を勉強します。」\",\"wrongAnswer\":\"She studys music every day.\",\"trapExplanation\":\"「三人称単数なら -s を付ける」とだけ覚えているので、study にそのまま -s を付けてしまう。y で終わる動詞には別の決まりがあることが頭から抜けている。\",\"correctAnswer\":\"She studies music every day.\",\"correctExplanation\":\"study は y の直前が t（子音字）なので、y を i に変えて -es を付け studies となる。同じ仲間に carry→carries、fly→flies、try→tries がある。一方 play は y の直前が a（母音字）なので plays でよい。\"},{\"question\":\"次の英文の（　）に入る正しい形を選びなさい。My sister and I （go / goes）to school together.\",\"wrongAnswer\":\"goes\",\"trapExplanation\":\"（　）のすぐ前にある I や、主語の中の My sister（一人）だけが目に入り、「単数だから goes」と決めてしまう。主語全体を一つのかたまりとして見ていないために起こる誤りである。\",\"correctAnswer\":\"go\",\"correctExplanation\":\"主語は My sister and I（姉と私＝二人）で複数なので、-s は付けずに go とする。主語全体を代名詞に置きかえると we になり、We go to school together. と確かめられる。and でつながれた主語は複数、と覚えておく。\"}]}",
"{\"id\":\"eigo_s118\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在形③：いつでも変わらない事実を表す\",\"description\":\"自然の法則や決まりきったことがらは、いつの話でも現在形で表すことを理解する\",\"intro\":\"「太陽は東からのぼる」は、昨日の話でも100年前の話でも The sun rises in the east. と現在形で書きます。いつでも変わらないことは、いつの話でも現在形。時制は時間だけで決まるのではないのです。\",\"order\":618,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「いつでもそうだ」という事実・法則は、過去の話の中でも現在形で書く。\",\"例）The sun rises in the east.／Water boils at 100 degrees Celsius.\",\"日本語の「〜している」に引かれて進行形にしない（The earth goes around the sun.）。\",\"時刻表・規則・ことわざのように「決まっていること」も現在形。\",\"国や人の性質を一般的に述べるときも現在形（Pandas eat bamboo.）。\"],\"sections\":[{\"heading\":\"いつでも成り立つことは現在形\",\"body\":\"現在形の二つ目の用法は「不変の事実」である。昨日も今日も明日も変わらず成り立つことは、いつの話をしていても現在形で表す。\\n\\n例）The sun rises in the east and sets in the west.（太陽は東からのぼり、西にしずむ）\\n例）Water boils at 100 degrees Celsius.（水はセ氏100度でふっとうする）\\n例）Water freezes at zero degrees Celsius.（水はセ氏0度でこおる）\\n例）The earth goes around the sun.（地球は太陽のまわりを回っている）\\n例）Ice is lighter than water.（氷は水より軽い）\\n\\nこれらは「今そうなっている」だけでなく「いつでもそうだ」という内容なので、現在形以外は使えない。\\n\\n■ 決まっていることも現在形\\nThe bank opens at nine.（銀行は9時に開く）\\nOur school starts in April.（私たちの学校は4月に始まる）\\nThe train leaves at 6:30.（その電車は6時30分に出発する）\\n時刻表や規則のように「決まりとして動かないこと」も、未来のことであっても現在形で表す。\\n\\n★ ポイント：現在形は「今」を指す形ではなく、「時間に左右されない形」だと考えるとすっきりする。習慣も、法則も、時刻表も、すべて「いつでもそう」だから現在形なのである。\",\"figureId\":\"xf_eigo_s118\"},{\"heading\":\"日本語につられて起こる二つの誤り\",\"body\":\"■ 誤り1：過去の話の中だから、と過去形にしてしまう\\n理科の実験を思い出して書くとき、「あのとき水は100度でふっとうした」と考えて Water boiled at 100 degrees. と書いてしまうことがある。しかし「水は100度でふっとうする」という性質は今も変わらないので、Water boils at 100 degrees Celsius. と現在形にする。実験をした「そのとき」の出来事を語る場合だけ過去形になる。\\n例）Yesterday we heated the water, and it boiled.（昨日水を熱したら、ふっとうした）← この文の boiled は、昨日起きた一回の出来事なので過去形でよい。\\n\\n■ 誤り2：「〜している」だから、と進行形にしてしまう\\n「地球は太陽のまわりを回っている」を The earth is going around the sun. と書くのは誤り。日本語の「〜ている」は、進行中の動作にも、変わらない事実にも使えるあいまいな言い方だからである。英語では「いつでもそうだ」なら現在形、「今この瞬間だけ」なら進行形とはっきり分かれる。\\n正）The earth goes around the sun.\\n正）The moon goes around the earth.\\n\\n⚠ 注意：一般的な性質を述べるときは、主語を複数形にすることが多い。Pandas eat bamboo.（パンダは竹を食べる）／ Dogs like to run.（犬は走るのが好きだ）。A panda eats bamboo. も可能だが、複数形のほうが「〜というものは」という感じがよく出る。\",\"mangaId\":\"eigo_s118_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「水はセ氏100度でふっとうします。」\",\"wrongAnswer\":\"Water boiled at 100 degrees Celsius.\",\"trapExplanation\":\"理科の授業でやった実験の場面を思いうかべ、「あのときふっとうした」という体験の記憶にひきずられて過去形にしてしまう。実験は過去でも、性質そのものは今も変わらない。\",\"correctAnswer\":\"Water boils at 100 degrees Celsius.\",\"correctExplanation\":\"「水は100度でふっとうする」はいつでも成り立つ事実なので、主語 Water（三人称単数）に合わせて現在形 boils を使う。過去形になるのは「昨日、実験で水がふっとうした」のように一回の出来事を語るときだけである。\"},{\"question\":\"次の日本語を英語にしなさい。「地球は太陽のまわりを回っています。」\",\"wrongAnswer\":\"The earth is going around the sun.\",\"trapExplanation\":\"日本語の「回っています」の「〜ています」を、そのまま現在進行形に置きかえてしまう。日本語の「〜ている」は進行中の動作にも変わらない事実にも使えるので、そのまま訳すと形をまちがえる。\",\"correctAnswer\":\"The earth goes around the sun.\",\"correctExplanation\":\"「地球が太陽のまわりを回る」は今だけでなくいつでも成り立つ事実なので現在形を使う。「〜ている」という日本語を見たら、①今この瞬間だけか、②いつでもそうか、を必ず自分に問いかけてから形を決める。\"}]}",
"{\"id\":\"eigo_s119\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在形④：今の状態を表す be動詞と一般動詞\",\"description\":\"be動詞の使い分けと、状態を表す一般動詞（like・have・live など）の使い方を整理する\",\"intro\":\"「私は犬を飼っています」を I am having a dog. と言うと変です。have は「持っている」という状態なので、進行形にしません。「〜ています」に引かれて進行形にしてしまう、日本語話者らしいまちがいです。\",\"order\":619,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞は主語で決まる。I→am／you・複数→are／三人称単数→is。\",\"be動詞と一般動詞を一つの文に二つ並べない（× I am like baseball.）。\",\"like・know・have・want・live などは「状態」を表し、現在形で今のことが言える。\",\"There is ＋単数名詞／There are ＋複数名詞。be動詞は後ろの名詞に合わせる。\",\"「〜がいます・あります」は There is/are と have を場面で使い分ける。\"],\"sections\":[{\"heading\":\"be動詞は「＝」を表す\",\"body\":\"現在形の三つ目の用法は「今の状態」である。まず be動詞から確認する。\\n\\n■ be動詞の使い分け\\nI am a student.（私は生徒です）\\nYou are kind.（あなたは親切です）\\nHe is my brother.（彼は私の兄です）\\nThey are in the park.（彼らは公園にいます）\\n\\nbe動詞は「主語＝後ろの語」または「主語がどこにいるか」を表す。主語によって am / are / is を使い分けるだけで、意味は変わらない。\\n\\n■ 短縮形\\nI am → I'm　You are → You're　He is → He's　They are → They're\\nis not → isn't　are not → aren't（am not に短縮形はない）\\n\\n■ be動詞と一般動詞は一つの文に二つ入れない\\n× I am like baseball.\\n○ I like baseball.（私は野球が好きです）\\n× He is play tennis.\\n○ He plays tennis.（彼はテニスをします）\\n「〜です」という日本語につられて be動詞を先に置き、そのあとに一般動詞を続けてしまうのがいちばん多い誤りである。文の中心となる動詞は一つだけ、と覚えておく。\\n\\n★ ポイント：be動詞は「＝」、一般動詞は「動作や状態」。両方を同時に文の中心にはできない。ただし be動詞＋~ing（進行形）だけは例外で、これは二つで一つの動詞のはたらきをしている。\",\"figureId\":\"xf_eigo_s119\",\"mangaId\":\"eigo_s119_xm\"},{\"heading\":\"状態を表す一般動詞と There is / There are\",\"body\":\"一般動詞の中には、動作ではなく「状態」を表すものがある。これらは現在形のままで「今のこと」を表せる。\\n\\n例）I like music.（私は音楽が好きです）\\n例）I know his name.（私は彼の名前を知っています）\\n例）He has two dogs.（彼はイヌを2匹飼っています）\\n例）She lives in Osaka.（彼女は大阪に住んでいます）\\n例）I want a new bike.（私は新しい自転車がほしい）\\n日本語では「知っています」「飼っています」「住んでいます」と「〜ています」が付くが、英語では進行形にしないことに注意する。\\n\\n■ There is / There are（〜があります・います）\\nThere is a book on the desk.（机の上に本が1冊あります）\\nThere are three books on the desk.（机の上に本が3冊あります）\\nbe動詞は There ではなく、後ろに来る名詞の数に合わせる。単数なら is、複数なら are。\\n疑問文は Is there a book on the desk?（― Yes, there is. / No, there isn't.）となる。\\n\\n■ There is/are と have の使い分け\\nThere is a park near my house.（家の近くに公園があります）＝ 場所に何かが存在する\\nI have a bike.（私は自転車を持っています）＝ だれかが所有している\\nどちらも日本語では「あります」となるので、「だれのものか」を言いたいときは have、「そこに存在する」だけなら There is/are と覚える。\\n\\n⚠ 注意：There is/are のあとに the my your this などが付いた名詞は置かない。× There is my bike in the garage. → ○ My bike is in the garage.\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は野球が好きです。」\",\"wrongAnswer\":\"I am like baseball.\",\"trapExplanation\":\"日本語の文末が「〜です」で終わっているので、「です＝am」と反射的に置いてしまい、そのあとに like を続けてしまう。be動詞を「です」の訳語だと思いこんでいるために起こる誤りである。\",\"correctAnswer\":\"I like baseball.\",\"correctExplanation\":\"like はそれ自体が「〜が好きだ」という意味の一般動詞なので、be動詞は不要。一つの文の中心となる動詞は一つだけである。「〜です」で終わる日本語でも、like・know・want・have のような動詞を使うときは be動詞を付けない。\"},{\"question\":\"次の日本語を英語にしなさい。「机の上に本が3冊あります。」\",\"wrongAnswer\":\"There is three books on the desk.\",\"trapExplanation\":\"There is 〜 を一つのかたまりとして丸暗記しているため、後ろが複数名詞になっても is のまま書いてしまう。There が主語だと思っていると、いつまでも直らない。\",\"correctAnswer\":\"There are three books on the desk.\",\"correctExplanation\":\"There is/are の be動詞は、後ろに来る名詞の数に合わせる。three books は複数なので are を使う。逆に There are a book. も誤り。まず名詞が単数か複数かを見てから is / are を決める、という順番で書く。\"}]}",
"{\"id\":\"eigo_s120\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去形①：過去の一点で完結する\",\"description\":\"過去形が指している時間と、be動詞 was/were・一般動詞 -ed の基本形をつかむ\",\"intro\":\"「昨日、京都に行きました」は I went to Kyoto yesterday.。日本語の「した」は今とのつながりをぼかせますが、英語の過去形は「そこで終わったこと」とはっきり言い切ります。be動詞は was と were の2つだけです。\",\"order\":620,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"過去形は「過去のある一点で起きて、そこで終わったこと」を表し、今とはつながらない。\",\"be動詞の過去形は was（I・三人称単数）と were（you・複数）の二つだけ。\",\"一般動詞の規則変化は原形に -ed を付ける。主語が何であっても形は変わらない。\",\"yesterday／last night／last week／three days ago／in 2020 は過去形の合図。\",\"過去形には三人称単数の -s は存在しない（× He playeds）。\"],\"sections\":[{\"heading\":\"過去形が指している時間\",\"body\":\"過去形は「過去のある一点で始まり、その場で終わったこと」を表す。今この瞬間とは線がつながっていない、というのが最大の特徴である。\\n\\n例）I visited my grandmother yesterday.（私は昨日、祖母を訪ねました）\\n昨日という一点での出来事を述べているだけで、今も祖母の家にいるかどうかには何も触れていない。\\n\\n例）He was busy last week.（彼は先週いそがしかった）\\n先週いそがしかったと言っているだけで、今いそがしいかどうかは分からない。\\n\\n■ 過去形といっしょに使われる語\\nyesterday（昨日）・last night（昨夜）・last week / month / year（先週・先月・昨年）\\nthree days ago（3日前）・a long time ago（ずっと昔）・in 2020（2020年に）・then / at that time（そのとき）\\nこれらは「過去の一点」を指す語なので、過去形とだけ結びつく。あとで学ぶ現在完了とはいっしょに使えない。\\n\\n★ ポイント：過去形は「点」。今とつながっていないからこそ、yesterday のような「いつ」を表す語を自由にそえられる。これは現在完了との決定的なちがいになる。\",\"figureId\":\"lf_eigoext04_120\",\"mangaId\":\"eigo_s120_xm\"},{\"heading\":\"be動詞の過去形と一般動詞の過去形\",\"body\":\"■ be動詞の過去形は二つだけ\\nam → was　　is → was　　are → were\\nI was tired.（私はつかれていました）\\nHe was at home.（彼は家にいました）\\nYou were kind to me.（あなたは私に親切でした）\\nThey were in the library.（彼らは図書館にいました）\\n現在形は am / is / are と三つあるが、過去形は was と were の二つに減る。you は一人でも were を使う点に注意する。\\n\\n■ 一般動詞の規則変化\\n原形に -ed を付けるだけで、主語が何であっても形は同じ。\\nplay → played　　watch → watched　　want → wanted　　help → helped　　open → opened\\nI played tennis.　He played tennis.　They played tennis.（すべて played）\\n現在形では He plays と -s が必要だったが、過去形では主語による形の変化がまったくない。ここは英語の中で最も楽な部分である。\\n\\n⚠ 注意：現在形のくせが残って He playeds のように -s まで付けてしまう誤りが出る。過去形に三人称単数の -s は存在しない。\\n\\n■ 「〜でした」と「〜しました」の見分け\\n日本語が「〜でした」「〜だった」で終わっていれば be動詞の過去形、「〜しました」「〜した」で終わっていれば一般動詞の過去形になることが多い。ただし「〜にいました」も be動詞（was / were）なので気をつける。\\n例）私は昨日いそがしかった。→ I was busy yesterday.\\n例）私は昨日、公園にいました。→ I was in the park yesterday.\\n例）私は昨日、公園へ行きました。→ I went to the park yesterday.\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は昨日、公園へ行きませんでした。」\",\"wrongAnswer\":\"I didn't went to the park yesterday.\",\"trapExplanation\":\"「過去の文だから動詞も過去形」と考えて、didn't のあとまで過去形にしてしまう。過去を表す仕事はすでに did が引き受けている、という仕組みが見えていない。\",\"correctAnswer\":\"I didn't go to the park yesterday.\",\"correctExplanation\":\"否定文では did（do の過去形）が過去を表すので、そのあとの動詞は原形にもどす。現在形の He doesn't play. で play にもどるのと同じ仕組みで、「過去を表す印は文に一つだけ」と覚えるとよい。\"},{\"question\":\"次の英文の（　）に入る正しい語を選びなさい。They （was / were）busy yesterday.\",\"wrongAnswer\":\"was\",\"trapExplanation\":\"過去形の be動詞といえば was、と一つだけを強く覚えていると、主語が複数でも was を選んでしまう。現在形で are を使う主語には were、という対応が結びついていない。\",\"correctAnswer\":\"were\",\"correctExplanation\":\"主語 They は複数なので were を使う。現在形の am・is が was に、are が were に変わる、と対応させて覚える。とくに You were 〜. は you が一人であっても were なので、まちがえやすい形として押さえておく。\"}]}",
"{\"id\":\"eigo_s121\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去形②：-ed のつけ方 五つのパターン\",\"description\":\"規則動詞の過去形のつづりを、五つの型に整理して確実に書けるようにする\",\"intro\":\"stop の過去形は stoped ではなく stopped、study は studyed ではなく studied。同じ -ed を付けるだけなのに、つづりが5通りに分かれます。分かれ目は語尾の形。パターンで覚えれば書きまちがえません。\",\"order\":621,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"原則はそのまま -ed（play→played, watch→watched, want→wanted）。\",\"e で終わる語は -d だけ（like→liked, live→lived, use→used）。\",\"「子音字＋y」は y を i に変えて -ed（study→studied, carry→carried, cry→cried）。\",\"「母音字＋y」はそのまま -ed（play→played, enjoy→enjoyed, stay→stayed）。\",\"「短い母音＋子音字1つ」で終わる語は最後の子音字を重ねて -ed（stop→stopped, plan→planned）。\"],\"sections\":[{\"heading\":\"五つのパターン\",\"body\":\"規則動詞の過去形は、次の五つの型に分けて覚える（①〜④のあとに⑤を説明する）。\\n\\n① そのまま -ed を付ける（いちばん多い）\\nplay→played　watch→watched　want→wanted　help→helped　open→opened　visit→visited　call→called　listen→listened\\n\\n② e で終わる語は -d だけ\\nlike→liked　live→lived　use→used　close→closed　move→moved　arrive→arrived　practice→practiced\\nすでに e があるので、d を一つ足すだけでよい。likeed とは書かない。\\n\\n③ 「子音字＋y」は y を i に変えて -ed\\nstudy→studied　carry→carried　cry→cried　try→tried　worry→worried\\n三人称単数の -es のときと同じ考え方である。\\n\\n④ 「母音字＋y」はそのまま -ed\\nplay→played　enjoy→enjoyed　stay→stayed\\ny の直前が a や o なら、何も変えずに -ed を付ける。plaied は誤り。\\n\\n■ 五つ目の型：子音字を重ねる\\nstop→stopped　plan→planned　drop→dropped　shop→shopped\\n「短い母音1つ＋子音字1つ」で終わる語は、最後の子音字を重ねてから -ed を付ける。母音が短いままであることを示す書き方である。\\n\\n★ ポイント：まず語の最後の文字を見る。e なら②、y なら③か④（一つ前が母音字かどうか）、それ以外なら①か⑤。この順で判断すれば迷わない。\",\"figureId\":\"xf_eigo_s121\"},{\"heading\":\"子音字を重ねる型を広げすぎない\",\"mangaId\":\"eigo_s121_manga\",\"body\":\"五つ目の「子音字を重ねる」型は便利だが、当てはめすぎる誤りが非常に多い。重ねるのは次の条件をすべて満たすときだけである。\\n\\n■ 重ねる条件\\n（ア）最後が「母音字1つ＋子音字1つ」で終わっている\\n（イ）その母音が短く読まれる（1音節、または最後の部分を強く読む語）\\n\\nstop →「o（短い母音）＋p（子音字1つ）」で1音節 → stopped ○\\nplan →「a（短い母音）＋n（子音字1つ）」で1音節 → planned ○\\ndrop → dropped ○　　shop → shopped ○\\n\\n■ 重ねない例\\nvisit → visited（visit は前のほうを強く読む2音節の語なので重ねない。× visitted）\\nopen → opened（同じく前を強く読む。× openned）\\nwait → waited（母音字が ai と二つ並んでいるので条件（ア）に当てはまらない。× waitted）\\nrain → rained（同じく ai なので重ねない）\\nhelp → helped（最後が lp と子音字2つなので重ねない）\\nlook → looked（oo と母音字が二つなので重ねない）\\n\\n⚠ 注意：まぎらわしい組み合わせを並べて覚えると強い。\\nstop→stopped ／ visit→visited\\nplan→planned ／ open→opened\\ndrop→dropped ／ wait→waited\\n左は重ねる、右は重ねない。声に出して「ストップト」「ヴィジティッド」と読み比べると、リズムのちがいでも区別できる。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼はそのバスを止めました。」\",\"wrongAnswer\":\"He stoped the bus.\",\"trapExplanation\":\"「過去形は -ed を付けるだけ」と覚えているので、stop にそのまま -ed を付けてしまう。子音字を重ねるという決まりが頭から抜けているために起こる、最も多い書きあやまりの一つ。\",\"correctAnswer\":\"He stopped the bus.\",\"correctExplanation\":\"stop は「短い母音 o ＋子音字 p」で終わる1音節の語なので、p を重ねて stopped とする。同じ型に plan→planned、drop→dropped、shop→shopped がある。stoped と書くと「ストゥープト」のように長く読む語に見えてしまう。\"},{\"question\":\"次の日本語を英語にしなさい。「私は昨年、京都を訪れました。」\",\"wrongAnswer\":\"I visitted Kyoto last year.\",\"trapExplanation\":\"stopped や planned を覚えたあとに起こる「覚えすぎ」の誤り。最後が「母音字＋子音字」に見えるので、条件を確かめずに t を重ねてしまう。ルールを広げすぎるのも失点の原因になる。\",\"correctAnswer\":\"I visited Kyoto last year.\",\"correctExplanation\":\"visit は vi-sit と2音節で、前の部分を強く読む語なので子音字を重ねない。そのまま -ed を付けて visited とする。open→opened も同じ仲間。子音字を重ねるのは stop・plan・drop のように短くて1音節の語だ、とセットで覚えておく。\"}]}",
"{\"id\":\"eigo_s122\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去形③：-ed の発音と、まぎらわしいつづり\",\"description\":\"-ed の三つの発音を区別し、リスニングと読み上げでつまずかないようにする\",\"intro\":\"wanted は「ウォンティド」と、音のかたまりが1つ増えます。ところが looked は「ルックト」で増えません。同じ -ed でも読み方は3通り。聞いた文が過去形かどうかを判断する手がかりになります。\",\"order\":622,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"-ed の発音は三種類。[t]／[d]／[id] のどれになるかは直前の音で決まる。\",\"直前が [t] [d] の音のときだけ [id]（wanted, needed, visited, started）と読み、音節が一つ増える。\",\"直前が息だけの音（k, p, s, ʃ, tʃ, f）なら [t]（looked, stopped, washed, watched）。\",\"それ以外（声を出す音・母音）なら [d]（played, opened, listened, cleaned）。\",\"つづりの例外に注意。die→died、lie→lied、agree→agreed（e を重ねない）。\"],\"sections\":[{\"heading\":\"-ed の三つの発音\",\"body\":\"-ed はいつも「エド」と読むわけではない。直前の音によって、次の三通りに変わる。\\n\\n■ [id]（イド）と読む場合 ― 直前が t か d の音\\nwanted（ウォンティド）・needed（ニーディド）・visited（ヴィジティド）・started（スターティド）・decided（ディサイディド）\\nt や d のあとに t や d を続けると発音しにくいので、間に母音を入れる。この場合だけ音節が一つ増える（want は1音節、wanted は2音節）。\\n\\n■ [t]（ト）と読む場合 ― 直前が息だけで出す音（k, p, s, sh, ch, f）\\nlooked（ルックト）・stopped（ストップト）・washed（ウォッシュト）・watched（ウォッチト）・helped（ヘルプト）・laughed（ラフト）\\nつづりに ed とあっても、母音は入らず「ト」とだけ読む。\\n\\n■ [d]（ド）と読む場合 ― それ以外（声を出す音・母音のあと）\\nplayed（プレイド）・opened（オープンド）・listened（リスンド）・cleaned（クリーンド）・lived（リヴド）・enjoyed（エンジョイド）\\n\\n★ ポイント：見分け方は「直前の音が t / d か、そうでないか」をまず確かめること。t / d なら [id]。ちがえば、その音を出すときにのどがふるえるかどうかで [d] と [t] に分かれる。\",\"figureId\":\"xf_eigo_s122\"},{\"heading\":\"つづりでまちがえやすい語\",\"mangaId\":\"eigo_s122_manga\",\"body\":\"発音とあわせて、つづりの例外も確認しておく。\\n\\n■ e で終わる語に -ed を付けるとき\\ndie → died（死んだ）　lie → lied（うそをついた）　tie → tied（結んだ）\\nこれらは e で終わっているので d を足すだけである。dieed とは書かない。また、y に変える必要もないので dyed（染めた）としてしまうのも誤り（dye は「染める」という別の動詞）。\\n\\n■ ee で終わる語\\nagree → agreed（同意した）　free → freed\\nすでに e が二つあるので、そのまま d を足す。\\n\\n■ 意味のちがいに注意する組\\nlive（リヴ）→ lived（住んでいた）／ leave（リーヴ）→ left（去った・置いてきた／不規則動詞）\\nplan（計画する）→ planned ／ plant（植える）→ planted\\nつづりが似ていても、変化のしかたも意味もちがう。\\n\\n⚠ 注意：入試のリスニングでは「現在形か過去形か」を -ed の音だけで聞き分けさせる問題が出る。とくに [t] と読む型（looked, stopped, watched）は、うっかりすると現在形に聞こえるので、直前の名詞や yesterday などの語もあわせて判断する。\\n\\n■ 練習：次の -ed の読み方を分けてみる\\nwalked ［t］／ needed ［id］／ played ［d］／ washed ［t］／ visited ［id］／ opened ［d］\"}],\"trapExamples\":[{\"question\":\"stopped の -ed の発音として正しいものを選びなさい。ア「ト」［t］　イ「ド」［d］　ウ「イド」［id］\",\"wrongAnswer\":\"ウ「イド」［id］（ストッピドのように2音節で読む）\",\"trapExplanation\":\"つづりで p が二つ重なっているうえに ed という文字が見えるので、「ストッ・ピド」と余分な母音を入れて読んでしまう。文字の見た目につられ、音の決まりで考えていない。\",\"correctAnswer\":\"ア「ト」［t］（ストップト、1音節）\",\"correctExplanation\":\"［id］と読むのは直前が t か d の音のときだけ。stop の最後は p なので［t］と読み、stopped は「ストップト」と1音節で発音する。つづりが長くなっても音節は増えない。wanted［id］、played［d］と並べて音で覚える。\"},{\"question\":\"次の日本語を英語にしなさい。「そのイヌは3年前に死にました。」\",\"wrongAnswer\":\"The dog dyed three years ago.\",\"trapExplanation\":\"study→studied を覚えているために「y があれば i に変える」と考えたり、dieed とは書けないと気づいて音の似た dye を持ち出したりしてしまう。dye は「（布を）染める」という別の動詞である。\",\"correctAnswer\":\"The dog died three years ago.\",\"correctExplanation\":\"die は e で終わっているので、d を一つ足して died とするだけでよい。lie→lied、tie→tied も同じ型。y を i に変える決まりは study・carry のように「子音字＋y」で終わる語だけに使い、e で終わる語には使わない。\"}]}",
"{\"id\":\"eigo_s123\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去形④：否定文・疑問文（did の使い方）\",\"description\":\"did を使う過去の否定文・疑問文と、be動詞の過去の文とを区別できるようにする\",\"intro\":\"Did you played tennis? と書いてしまうのはよくあることです。did がすでに「過去」を表しているので、動詞は原形にもどします。しかも be動詞の過去の文には did を使いません。使い分けを固めましょう。\",\"order\":623,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"一般動詞の過去の否定文は did not（didn't）＋動詞の原形。\",\"疑問文は Did ＋主語＋動詞の原形 …? で、答えも did / didn't を使う。\",\"did を使ったら動詞は必ず原形にもどす（× Did you played）。\",\"be動詞の過去の文には did を使わない。was / were をそのまま前に出す。\",\"疑問詞の文は What did you do? のように「疑問詞＋did＋主語＋原形」の順。\"],\"sections\":[{\"heading\":\"did を使う否定文と疑問文\",\"body\":\"一般動詞の過去の文を否定文・疑問文にするときは、do の過去形 did を使う。\\n\\n■ 否定文\\nI played tennis. → I did not（didn't）play tennis.（私はテニスをしませんでした）\\nHe watched TV. → He didn't watch TV.（彼はテレビを見ませんでした）\\n主語が何であっても didn't の形は変わらない。現在形では don't と doesn't を使い分けたが、過去形では didn't だけである。\\n\\n■ 疑問文\\nYou played tennis. → Did you play tennis?（あなたはテニスをしましたか）\\n― Yes, I did. / No, I didn't.\\nShe went to school. → Did she go to school?\\n― Yes, she did. / No, she didn't.\\n\\n■ did のあとは必ず原形\\n× Did you played tennis?　○ Did you play tennis?\\n× He didn't went home.　○ He didn't go home.\\n過去を表す仕事は did が引き受けているので、動詞まで過去形にすると「過去の印」が二重になってしまう。\\n\\n■ 疑問詞のある疑問文\\nWhat did you do yesterday?（あなたは昨日、何をしましたか）― I studied math.\\nWhere did he go?（彼はどこへ行きましたか）― He went to the library.\\nWhen did you get up?（あなたはいつ起きましたか）― I got up at six.\\n「疑問詞＋did＋主語＋動詞の原形」の順にそろえる。答えの文では過去形にもどることに注意する。\\n\\n★ ポイント：did が出てきたら、そのうしろの動詞は原形。これだけで多くの失点が防げる。\",\"figureId\":\"xf_eigo_s123\",\"mangaId\":\"eigo_s123_xm\"},{\"heading\":\"be動詞の過去の文には did を使わない\",\"body\":\"be動詞の文は、現在形のときと同じように「be動詞そのもの」を動かす。did は使わない。\\n\\n■ 否定文\\nI was busy. → I was not（wasn't）busy.（私はいそがしくなかった）\\nThey were at home. → They weren't at home.（彼らは家にいなかった）\\n\\n■ 疑問文\\nHe was at home. → Was he at home?（彼は家にいましたか）\\n― Yes, he was. / No, he wasn't.\\nYou were tired. → Were you tired?\\n― Yes, I was. / No, I wasn't.\\n\\n■ まちがえやすい形\\n× Did he be at home yesterday?\\n○ Was he at home yesterday?\\n× He didn't be busy.\\n○ He wasn't busy.\\n\\n■ 見分け方\\n日本語が「〜でした」「〜だった」「〜にいました」で終わっていれば be動詞、「〜しました」「〜した」なら一般動詞、と大まかに判断できる。迷ったら、まず肯定文を作ってみるとよい。肯定文に was / were があれば be動詞の文、なければ一般動詞の文である。\\n\\n⚠ 注意：進行形の過去（過去進行形）も be動詞の文なので、did は使わない。\\n× Did you doing your homework?　○ Were you doing your homework?（あなたは宿題をしていましたか）\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「あなたは昨日、テニスをしましたか。」\",\"wrongAnswer\":\"Did you played tennis yesterday?\",\"trapExplanation\":\"「昨日のことだから動詞も過去形にしなければ」と考えて、Did のあとまで過去形にしてしまう。日本語では「しましたか」と一か所で過去を表すので、英語でも二重になることに気づきにくい。\",\"correctAnswer\":\"Did you play tennis yesterday?\",\"correctExplanation\":\"Did がすでに過去を表しているので、そのあとの動詞は原形 play にもどす。答えるときは Yes, I did. / No, I didn't. とし、内容を続けるなら I played tennis with Ken. のように過去形にもどる。\"},{\"question\":\"次の日本語を英語にしなさい。「彼は昨日、家にいましたか。」\",\"wrongAnswer\":\"Did he be at home yesterday?\",\"trapExplanation\":\"「過去の疑問文は Did で始める」とだけ覚えているため、be動詞の文にも Did を付けてしまう。日本語の「いましたか」が動作のように感じられることも原因になる。\",\"correctAnswer\":\"Was he at home yesterday?\",\"correctExplanation\":\"「家にいた」は be動詞（was）の文なので、was を主語の前に出すだけでよい。答えは Yes, he was. / No, he wasn't.。did を使うのは一般動詞の文だけ、be動詞の文は be動詞そのものを動かす、と使い分ける。\"}]}",
"{\"id\":\"eigo_s124\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則動詞①：規則動詞と不規則動詞\",\"description\":\"不規則動詞を「原形-過去形-過去分詞」の3変化でとらえ、過去分詞の役割を知る\",\"intro\":\"go の過去形が goed でないことは知っていても、なぜ went なのかは説明できません。よく使う動詞ほど形が不規則なのです。数は200語ほど。原形・過去形・過去分詞を3つセットで覚える理由から始めます。\",\"order\":624,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"不規則動詞は200語ほどしかないが、毎日使う動詞ほど不規則なので出会う回数は非常に多い。\",\"覚えるときは「原形－過去形－過去分詞」の3つをセットで、声に出して覚える。\",\"過去分詞は現在完了（have＋過去分詞）と受け身（be＋過去分詞）で使う形。\",\"過去形と過去分詞は形がちがうことがある（go-went-gone, see-saw-seen）。\",\"不規則動詞に -ed を付けてはいけない（× buyed, × goed, × teached）。\"],\"sections\":[{\"heading\":\"数は少ないが、出会う回数は多い\",\"mangaId\":\"eigo_s124_manga\",\"body\":\"英語の動詞の大部分は -ed を付けるだけで過去形になる「規則動詞」である。しかし一部の動詞は、まったくちがう形に変わる。これを「不規則動詞」という。\\n\\n例）go → went（行った）　　see → saw（見た）　　buy → bought（買った）\\n例）take → took（取った）　　come → came（来た）　　have → had（持っていた）\\n\\n不規則動詞は全部で200語ほどしかなく、動詞全体から見ればごくわずかである。ところが、be・have・do・go・come・get・take・make・see・say のように毎日使う基本の動詞ほど不規則なので、英文を読むと必ず出てくる。数は少ないのに出会う回数が多い、というのが不規則動詞の特徴である。\\n\\nだから「まず不規則動詞を全部覚えてしまう」ことが、時制を得点源にする最短の道になる。\\n\\n★ ポイント：規則動詞は考えれば書ける。不規則動詞は覚えていなければ絶対に書けない。だから覚える価値がいちばん高い。\",\"figureId\":\"lf_eigoext04_124\"},{\"heading\":\"3変化で覚える理由\",\"body\":\"不規則動詞は「原形－過去形－過去分詞」の3つを必ずセットで覚える。過去形だけ覚えても、あとで現在完了を学ぶときに必ず困るからである。\\n\\n■ 三つの形とその使い道\\n原形　　… 現在形の文、did のあと、will のあと、to のあと（to go）\\n過去形　… 過去の文（I went to Kyoto.）\\n過去分詞… 現在完了（I have gone. / I have seen.）、受け身（It is made in Japan.）\\n\\n例）go － went － gone\\n　I go to school.（現在）\\n　I went to school.（過去）\\n　He has gone to America.（現在完了）\\n\\n例）see － saw － seen\\n　I see a bird.／I saw a bird.／I have seen the movie.\\n\\n例）eat － ate － eaten\\n　I eat lunch.／I ate lunch.／I have eaten lunch.\\n\\n■ 覚え方のコツ\\n声に出して「ゴー・ウェント・ゴーン」「シー・ソー・シーン」「イート・エイト・イートン」とリズムで唱える。目で見るだけより、音のかたまりで覚えたほうが定着する。1日10語ずつ、3回に分けて口に出すのが効果的である。\\n\\n⚠ 注意：不規則動詞に -ed を付けるのは、入試でいちばん多い減点である。buyed・goed・teached・comed・seed はすべて誤り。「この動詞は不規則だったか」と一度立ち止まる習慣をつける。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は昨日、新しい自転車を買いました。」\",\"wrongAnswer\":\"He buyed a new bike yesterday.\",\"trapExplanation\":\"「過去形は -ed を付ける」という規則をすべての動詞に当てはめてしまう。buy は日常でよく使う語なのに不規則動詞である、という意識が薄いと必ず起こる。\",\"correctAnswer\":\"He bought a new bike yesterday.\",\"correctExplanation\":\"buy は buy － bought － bought と変化する不規則動詞。同じ型に bring－brought－brought、think－thought－thought、teach－taught－taught がある。まとめて「オート組」として覚えるとよい。\"},{\"question\":\"次の日本語を英語にしなさい。「彼女はもう昼食を食べてしまいました。」\",\"wrongAnswer\":\"She has ate lunch already.\",\"trapExplanation\":\"eat の過去形 ate は覚えているが、過去分詞 eaten まで区別できていない。「過去のことだから ate」と考えてしまい、have のあとに過去形を置いてしまう。\",\"correctAnswer\":\"She has already eaten lunch.\",\"correctExplanation\":\"have／has のあとに置くのは過去分詞なので eaten が正しい。eat － ate － eaten と3つセットで覚える。過去形と過去分詞が同じ動詞（buy－bought－bought）もあるので、形がちがう動詞ほど意識して覚える必要がある。\"}]}",
"{\"id\":\"eigo_s125\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則動詞②：A-B-B型（過去形と過去分詞が同じ）\",\"description\":\"不規則動詞の半分を占める A-B-B 型を、音のグループごとにまとめて覚える\",\"intro\":\"buy-bought、bring-brought、think-thought。ばらばらに覚えると多く感じますが、音の似たものを組にすると一気に減ります。過去形と過去分詞が同じ A-B-B 型は、不規則動詞のおよそ半分を占めています。\",\"order\":625,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"A-B-B型＝過去形と過去分詞が同じ形。不規則動詞のおよそ半分を占める。\",\"「オート／アート組」：buy-bought, bring-brought, think-thought, teach-taught, catch-caught。\",\"「エプト組」：keep-kept, sleep-slept, feel-felt, leave-left, lose-lost, build-built。\",\"「オールド組」：tell-told, sell-sold, hold-held。\",\"say-said, hear-heard, find-found, meet-met, send-sent, make-made, have-had も同型。\"],\"sections\":[{\"heading\":\"A-B-B型とは\",\"body\":\"不規則動詞の中でいちばん多いのが、過去形と過去分詞が同じ形になる型である。原形をA、変化後をBと書いて A-B-B 型という。二つ覚えれば済むので、いちばん楽な型でもある。\\n\\n■ オート・アート組（-ought / -aught）\\nbuy － bought － bought（買う）\\nbring － brought － brought（持ってくる）\\nthink － thought － thought（思う）\\nfight － fought － fought（戦う）\\nteach － taught － taught（教える）\\ncatch － caught － caught（つかまえる）\\n\\n■ エプト・エルト組（-ept / -elt / -ft）\\nkeep － kept － kept（保つ）\\nsleep － slept － slept（ねむる）\\nfeel － felt － felt（感じる）\\nleave － left － left（去る・置いていく）\\nlose － lost － lost（失う・負ける）\\nbuild － built － built（建てる）\\nspend － spent － spent（費やす）\\nsend － sent － sent（送る）\\n\\n■ オールド組（-old / -eld）\\ntell － told － told（伝える）\\nsell － sold － sold（売る）\\nhold － held － held（持つ・開催する）\\n\\n★ ポイント：バラバラに覚えるのではなく、音のグループでまとめる。「ボート・ブロート・ソート・トート・コート」と続けて唱えると、記憶に残りやすい。\",\"figureId\":\"xf_eigo_s125\"},{\"heading\":\"そのほかの A-B-B 型と使い方\",\"body\":\"■ 覚えておきたい残りの A-B-B 型\\nsay － said － said（言う。発音は「セッド」）\\nhear － heard － heard（聞こえる。発音は「ハード」）\\nfind － found － found（見つける）\\nmeet － met － met（会う）\\nsit － sat － sat（すわる）\\nstand － stood － stood（立つ）\\nunderstand － understood － understood（理解する）\\nmake － made － made（作る）\\nhave － had － had（持っている）\\npay － paid － paid（支払う）\\nread － read － read（読む。つづりは同じで発音だけ「リード→レッド」に変わる）\\n\\n■ 文の中での使い方\\nI bought this book last week.（過去形）\\nI have bought a new computer.（現在完了）\\nThis book was bought in Kyoto.（受け身）\\n過去形と過去分詞が同じなので、どこに置いても形は変わらない。have があれば現在完了、be動詞があれば受け身、どちらもなければ過去形、と見分ける。\\n\\n⚠ 注意：意味の取りちがえに気をつける動詞がある。\\n・leave は「去る」だけでなく「（物を）置き忘れる」の意味でもよく出る。I left my bag on the train.（電車にかばんを置き忘れた）\\n・say は「（内容を）言う」、tell は「（人に）伝える」。say のあとに人は直接置けない。× say me → ○ tell me\\n・hold は「持つ」のほか「（会などを）開く」。The festival was held last week.（祭りが先週開かれた）\",\"mangaId\":\"eigo_s125_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は私に本当のことを言いました。」\",\"wrongAnswer\":\"He said me the truth.\",\"trapExplanation\":\"「言う＝say」と一対一で覚えているので、日本語の「私に言った」をそのまま said me としてしまう。say と tell の使い分けは、動詞の形ではなく語法の問題なので、変化だけ覚えていても防げない。\",\"correctAnswer\":\"He told me the truth.\",\"correctExplanation\":\"say のあとに「人」を直接置くことはできず、「〜に言う」と相手を示すときは tell を使う（tell － told － told）。say を使うなら He said to me, \\\"...\\\" のように to が必要。「tell＋人＋内容」「say＋内容」と形で覚える。\"},{\"question\":\"次の日本語を英語にしなさい。「彼女は10年間、英語を教えています。」\",\"wrongAnswer\":\"She has teached English for ten years.\",\"trapExplanation\":\"現在完了の形（have/has＋過去分詞）は理解できていても、teach が不規則動詞であることを忘れて -ed を付けてしまう。ch で終わるので -ed が自然に見えてしまうのも一因である。\",\"correctAnswer\":\"She has taught English for ten years.\",\"correctExplanation\":\"teach は teach － taught － taught と変化する A-B-B 型。過去形も過去分詞も taught なので、has のあとにそのまま置ける。catch － caught － caught と発音が似ているので、二つ並べて覚えるとよい。\"}]}",
"{\"id\":\"eigo_s126\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則動詞③：A-B-C型（三つとも形がちがう）\",\"description\":\"最も重要な A-B-C 型を、母音の変化のパターンでまとめて覚える\",\"intro\":\"I seen it. や They swum. のように、過去分詞を過去形の場所に置くまちがいがよく起こります。see-saw-seen、swim-swam-swum のように3つとも形がちがう型は、数は少ないのに出題は最も多いのです。\",\"order\":626,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"A-B-C型＝原形・過去形・過去分詞の三つとも形がちがう。数は少ないが最頻出。\",\"「-en で終わる組」：take-took-taken, give-gave-given, write-wrote-written, speak-spoke-spoken。\",\"「i-a-u 組」：sing-sang-sung, drink-drank-drunk, swim-swam-swum, begin-began-begun, ring-rang-rung。\",\"go-went-gone, see-saw-seen, eat-ate-eaten, do-did-done, be-was/were-been は最重要。\",\"過去分詞を過去形の位置に置く誤り（× I seen, × They swum）がいちばん多い。\"],\"sections\":[{\"heading\":\"-en で終わる組と i-a-u 組\",\"body\":\"三つとも形がちがう A-B-C 型は、数こそ少ないものの、どれも毎日使う動詞ばかりである。母音の変わり方でグループにすると覚えやすい。\\n\\n■ 過去分詞が -en / -n で終わる組\\ntake － took － taken（取る）\\ngive － gave － given（与える）\\nwrite － wrote － written（書く）\\nspeak － spoke － spoken（話す）\\nbreak － broke － broken（こわす）\\nchoose － chose － chosen（選ぶ）\\ndrive － drove － driven（運転する）\\nride － rode － ridden（乗る）\\nknow － knew － known（知っている）\\ngrow － grew － grown（育つ）\\nthrow － threw － thrown（投げる）\\nfly － flew － flown（飛ぶ）\\ndraw － drew － drawn（線でかく）\\nsee － saw － seen（見える）\\neat － ate － eaten（食べる）\\nfall － fell － fallen（落ちる）\\nforget － forgot － forgotten（忘れる）\\nwear － wore － worn（身につけている）\\n\\n■ i － a － u と母音が変わる組\\nsing － sang － sung（歌う）\\ndrink － drank － drunk（飲む）\\nswim － swam － swum（泳ぐ）\\nbegin － began － begun（始める）\\nring － rang － rung（鳴る）\\n「イ・ア・ウ」と口の形が順に変わるので、声に出すと一気に覚えられる。\\n\\n★ ポイント：A-B-C 型は「過去分詞に -en が付くか」「母音が i-a-u と動くか」の二つでほとんど整理できる。\",\"figureId\":\"xf_eigo_s126\"},{\"heading\":\"最重要の五語と、位置による使い分け\",\"body\":\"次の五語は英語のあらゆる文に出てくるので、何よりも先に覚える。\\n\\ngo － went － gone（行く）\\ndo － did － done（する）\\nsee － saw － seen（見える）\\neat － ate － eaten（食べる）\\nbe － was / were － been（〜である・いる）\\n\\nbe動詞だけは過去形が二つ（was と were）ある点に注意する。\\n\\n■ 位置で形が決まる\\nI went to Kyoto last year.（過去形：文の中心の動詞）\\nI have been to Kyoto twice.（過去分詞：have のあと）\\nThis letter was written by Ken.（過去分詞：be動詞のあと＝受け身）\\nI want to go to Kyoto.（原形：to のあと）\\nDid you go to Kyoto?（原形：did のあと）\\nI will go to Kyoto.（原形：will のあと）\\n\\nつまり、動詞の形は「意味」ではなく「置かれる場所」で決まる。have があれば過去分詞、did や will のあとなら原形、と機械的に判断できる。\\n\\n⚠ 注意：口語では I seen it. / They swum. のような言い方を耳にすることがあるが、これは誤った形として入試では×になる。過去分詞は単独で文の動詞にはなれない。必ず have か be動詞といっしょに使う、と覚えておく。\",\"mangaId\":\"eigo_s126_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私はその映画を見たことがあります。」\",\"wrongAnswer\":\"I have saw that movie.\",\"trapExplanation\":\"see の過去形 saw はよく知っているが、過去分詞 seen が別にあることを意識していない。「過去のことだから saw」と考え、have のあとにそのまま置いてしまう。\",\"correctAnswer\":\"I have seen that movie.\",\"correctExplanation\":\"have／has のあとは必ず過去分詞なので seen を使う。see － saw － seen と3つ唱えて覚える。同じ型に eat － ate － eaten、take － took － taken、write － wrote － written がある。過去分詞が -en で終わる組としてまとめて覚えるとよい。\"},{\"question\":\"次の日本語を英語にしなさい。「その鳥は空高く飛びました。」\",\"wrongAnswer\":\"The bird flied high in the sky.\",\"trapExplanation\":\"fly が y で終わっているので、study → studied の決まりを当てはめて flied としてしまう。つづりの規則を思い出したことが、かえって不規則動詞であることを見えなくしている。\",\"correctAnswer\":\"The bird flew high in the sky.\",\"correctExplanation\":\"fly は fly － flew － flown と変化する不規則動詞。y を i に変える決まりは規則動詞にしか使えない。同じ型に grow － grew － grown、throw － threw － thrown、know － knew － known、draw － drew － drawn がある。\"}]}",
"{\"id\":\"eigo_s127\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則動詞④：A-A-A型・A-B-A型\",\"description\":\"形が変わらない型と、原形と過去分詞が同じ型を区別して覚える\",\"intro\":\"cut や put は、原形も過去形も同じ形です。では I cut it. は「切る」でしょうか、「切った」でしょうか。形では決まらないので周りの語から判断します。read に至っては、形は同じで発音だけ変わります。\",\"order\":627,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"A-A-A型＝三つとも同じ形。cut, put, set, hit, let, shut, cost, hurt。\",\"read は A-A-A 型だが、発音だけ「リード→レッド」に変わる。\",\"A-B-A型＝原形と過去分詞が同じ。come-came-come, run-ran-run, become-became-become。\",\"A-A-A型は形が同じなので、時制は主語や周りの語から判断する。\",\"A-B-A型では過去形だけがちがうので、過去形の書き落としに注意する。\"],\"sections\":[{\"heading\":\"A-A-A型：形が変わらない動詞\",\"body\":\"三つとも同じ形のままの動詞がある。楽に見えるが、逆に「時制が見た目で分からない」というむずかしさがある。\\n\\n■ 代表的な A-A-A 型\\ncut － cut － cut（切る）\\nput － put － put（置く）\\nset － set － set（置く・整える）\\nhit － hit － hit（打つ）\\nlet － let － let（させる）\\nshut － shut － shut（閉める）\\ncost － cost － cost（費用がかかる）\\nhurt － hurt － hurt（傷つける・痛む）\\n\\n■ read はつづりだけ同じ\\nread － read － read\\nつづりは三つとも read だが、発音は「リード → レッド → レッド」と変わる。音読の問題や読解でよく問われる。\\n例）I read a book every night.（リード＝現在形）\\n例）I read a book last night.（レッド＝過去形）\\nこの二文はつづりだけ見ると区別がつかない。every night か last night かで判断する。\\n\\n■ 時制の見分け方\\nHe cut the paper.（過去形か現在形か？）\\n主語が He なのに -s が付いていないので、これは過去形である。現在形なら He cuts the paper. となる。\\nこのように、A-A-A 型の文では「三単現の -s があるかどうか」「yesterday などの語があるかどうか」で時制を判断する。\\n\\n★ ポイント：A-A-A 型の動詞が出てきたら、必ず文全体を見て時制を決める。動詞の形だけ見ても答えは出ない。\",\"figureId\":\"xf_eigo_s127\"},{\"heading\":\"A-B-A型：原形と過去分詞が同じ\",\"body\":\"過去形だけがちがい、原形と過去分詞が同じ形にもどる型もある。\\n\\ncome － came － come（来る）\\nrun － ran － run（走る）\\nbecome － became － become（〜になる）\\n\\n■ 文の中での使い分け\\nHe comes here every day.（現在形）\\nHe came here yesterday.（過去形）\\nHe has come here many times.（現在完了：過去分詞は come にもどる）\\n\\nI run every morning.（現在形）\\nI ran in the park yesterday.（過去形）\\nI have run ten kilometers.（現在完了）\\n\\n■ まちがえやすい点\\ncome－came－come のように原形と過去分詞が同じだと、「じゃあ過去形も come でいいのでは」と考えて He come here yesterday. と書いてしまう誤りが多い。真ん中だけがちがう型だと、はっきり意識しておく。\\n\\n⚠ 注意：become は「〜になる」という意味で、あとに名詞や形容詞が続く。He became a doctor.（彼は医者になった）／ It became cold.（寒くなった）。過去分詞も become なので、He has become a good player.（彼はよい選手になった）となる。\\n\\n■ 型のまとめ\\nA-B-B（teach－taught－taught）… いちばん多い\\nA-B-C（go－went－gone）… 数は少ないが最頻出\\nA-A-A（cut－cut－cut）… 形は同じ、時制は周りで判断\\nA-B-A（come－came－come）… 真ん中だけちがう\",\"mangaId\":\"eigo_s127_xm\"}],\"trapExamples\":[{\"question\":\"次の英文の下線部 read の読み方を答えなさい。I read an interesting book last night.\",\"wrongAnswer\":\"「リード」と読む\",\"trapExplanation\":\"つづりが現在形とまったく同じなので、そのまま「リード」と読んでしまう。read が不規則動詞で、つづりを変えずに発音だけ変わることを知らないと必ず落とす。\",\"correctAnswer\":\"「レッド」と読む（過去形）\",\"correctExplanation\":\"last night があるのでこの read は過去形であり、発音は「レッド」になる。read － read － read はつづりが同じで発音だけ変わる特別な動詞。文中の時を表す語や三単現の -s の有無を手がかりに、どの時制かを先に決めてから読む。\"},{\"question\":\"次の日本語を英語にしなさい。「彼は昨日、ここへ来ました。」\",\"wrongAnswer\":\"He come here yesterday.\",\"trapExplanation\":\"come－came－come の三つのうち二つが come なので、「come のままでよい」と思いこんでしまう。A-B-A 型は真ん中だけがちがう、という点が抜け落ちている。\",\"correctAnswer\":\"He came here yesterday.\",\"correctExplanation\":\"過去形は came である。原形と過去分詞が同じ come だからこそ、過去形 came を強く意識して覚える必要がある。run － ran － run、become － became － become も同じ型で、真ん中だけが変わる。\"}]}",
"{\"id\":\"eigo_s128\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則動詞⑤：まぎらわしい動詞の総整理\",\"description\":\"形が似ていて取りちがえやすい不規則動詞を、意味とセットで区別する\",\"intro\":\"fall（落ちる）と feel（感じる）は、過去形が fell と felt でよく似ています。leave は「去る」とも「置き忘れる」とも訳せます。形も意味もまぎらわしい動詞は、例文ごと覚えるのが結局いちばん速い方法です。\",\"order\":628,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"fall（落ちる）－fell－fallen と feel（感じる）－felt－felt を混同しない。\",\"find（見つける）－found－found と、規則動詞 found（設立する）－founded は別語。\",\"leave（去る・置き忘れる）－left－left と forget（忘れる）の使い分け。\",\"A-B-B型が半分を占めるので、まずそこから覚えると効率がよい。\",\"意味が二つある動詞（leave, hold, run, spend）は、例文ごと覚える。\"],\"sections\":[{\"heading\":\"型ごとの分量を知って、覚える順番を決める\",\"body\":\"不規則動詞を「やみくもに全部」覚えようとすると続かない。型ごとの分量を知り、多い型から手をつけると効率がよい。\\n\\n■ おおよその内訳\\nA-B-B型（teach－taught－taught）… 約半分\\nA-B-C型（go－went－gone）… 3割ほど\\nA-A-A型（cut－cut－cut）… 1割強\\nA-B-A型（come－came－come）… わずか3語（come, run, become）\\n\\nつまり、A-B-B 型をまとめて覚えるだけで半分が終わる。次に A-B-C 型を覚えれば8割に届く。残りの A-A-A 型・A-B-A 型は語数が少ないので、最後に一気に暗記できる。\\n\\n■ 覚える順番の目安\\n第1週：A-B-B型のオート組・エプト組（buy, bring, think, teach, catch, keep, sleep, feel, leave, lose）\\n第2週：A-B-B型の残り（say, hear, find, meet, sit, stand, make, have, tell, sell）\\n第3週：A-B-C型の -en 組（take, give, write, speak, break, know, see, eat）\\n第4週：A-B-C型の i-a-u 組と A-A-A型・A-B-A型\\n\\n★ ポイント：毎日ちがう語を少しずつではなく、同じ型を1週間くり返す。型のリズムごと体に入れるほうが忘れにくい。\",\"figureId\":\"lf_eigoext04_128\"},{\"heading\":\"まぎらわしい組をペアで区別する\",\"body\":\"入試で差がつくのは、形や意味が似ている動詞の区別である。ペアにして覚える。\\n\\n■ fall と feel\\nfall － fell － fallen（落ちる・倒れる）\\nfeel － felt － felt（感じる）\\nHe fell from the tree.（彼は木から落ちた）\\nHe felt sad.（彼は悲しく感じた）\\nfell と felt は l が一つちがうだけなので、意味とセットで覚える。\\n\\n■ find と found\\nfind － found － found（見つける）\\nfound － founded － founded（設立する。これは規則動詞）\\nI found my key.（かぎを見つけた）\\nThe school was founded in 1950.（その学校は1950年に設立された）\\n\\n■ leave と forget\\nleave － left － left（去る／物を置き忘れる）\\nforget － forgot － forgotten（忘れる＝頭から抜ける）\\nI left my bag on the train.（かばんを電車に置き忘れた ← 場所を言うときは leave）\\nI forgot his name.（彼の名前を忘れた ← 場所を言わないときは forget）\\n\\n■ そのほかの注意組\\nlose － lost － lost（失う・負ける）／ loose（ゆるい：形容詞で別語）\\nsit（すわる：sit－sat－sat）／ set（置く：set－set－set）\\nrise（のぼる：rise－rose－risen）／ raise（上げる：規則動詞 raised）\\n\\n⚠ 注意：意味が二つある動詞は、両方の例文を覚えておく。\\nhold：持つ／開催する　The meeting was held last Friday.\\nrun：走る／経営する　My uncle runs a small shop.\\nspend：（お金を）使う／（時間を）過ごす　I spent two hours on my homework.\",\"mangaId\":\"eigo_s128_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は昨日、木から落ちました。」\",\"wrongAnswer\":\"He felt from the tree yesterday.\",\"trapExplanation\":\"fall と feel はつづりも音も似ているうえ、過去形 fell と felt は一文字ちがいなので取りちがえやすい。単語カードで形だけ覚えていると、意味の確認がおろそかになる。\",\"correctAnswer\":\"He fell from the tree yesterday.\",\"correctExplanation\":\"「落ちる」は fall － fell － fallen なので過去形は fell。「感じる」は feel － felt － felt で過去形は felt。fall には fall（秋）という名詞の意味もあるので、「秋は葉が落ちる」と結びつけて覚えると区別しやすい。\"},{\"question\":\"次の日本語を英語にしなさい。「私はかばんを電車に置き忘れました。」\",\"wrongAnswer\":\"I forgot my bag on the train.\",\"trapExplanation\":\"「忘れた＝forget」と一対一で覚えているため、場所を表す語が付いていても forgot を使ってしまう。動詞の変化ではなく語法の問題なので、暗記だけでは防げない。\",\"correctAnswer\":\"I left my bag on the train.\",\"correctExplanation\":\"「（場所に）置き忘れる」は leave － left － left を使う。forget は「記憶から抜ける」ことを表し、あとに場所を表す語句を続けることはできない。「場所が出てきたら leave」と形で覚えておくとよい。\"}]}",
"{\"id\":\"eigo_s129\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在進行形①：be動詞＋~ing のかたち\",\"description\":\"「今まさにしている最中」を表す現在進行形の形と意味をつかむ\",\"intro\":\"「私は英語を勉強しています」を I am study English. と書いてしまう人はとても多いのです。am のうしろは studying でなければなりません。be動詞と ~ing はセット。どちらが欠けても文になりません。\",\"order\":629,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"現在進行形は「be動詞（am/is/are）＋動詞の ~ing 形」。be動詞を落とさない。\",\"意味は「今まさに〜している最中だ」。今を含む短い時間の幅を表す。\",\"be動詞は主語に合わせて am / is / are を使い分ける。\",\"now, right now, at this moment, Look!, Listen! が合図になる。\",\"~ing 形だけでは動詞のはたらきをしない（× He playing soccer.）。\"],\"sections\":[{\"heading\":\"現在進行形が指す時間\",\"mangaId\":\"eigo_s129_manga\",\"body\":\"現在進行形は「今まさにしている最中だ」ということを表す。少し前に始まり、今も続いていて、もうすぐ終わる、という短い時間の幅を指している。\\n\\n例）I am reading a book now.（私は今、本を読んでいるところです）\\n例）She is cooking dinner.（彼女は夕食を作っているところです）\\n例）They are playing soccer in the park.（彼らは公園でサッカーをしているところです）\\n\\n■ 形は「be動詞＋~ing」\\n主語　　　be動詞　　~ing形\\nI　　　　　am　　　reading\\nHe / She / It　is　　reading\\nYou / We / They　are　reading\\n\\n■ 合図になる語\\nnow（今）・right now（ちょうど今）・at this moment（この瞬間）\\nLook!（見て！）・Listen!（聞いて！）\\nLook! The bus is coming.（見て！　バスが来るよ）\\nListen! Someone is singing.（聞いて！　だれかが歌っているよ）\\n命令の形で相手の注意を今この瞬間に向けているので、あとには必ず進行形が続く。\\n\\n★ ポイント：現在形が「点がくり返し並ぶ」形なのに対し、現在進行形は「今を包む一本の帯」。同じ「今」でも、指しているものがまったくちがう。\",\"figureId\":\"lf_eigoext04_129\"},{\"heading\":\"be動詞を落とさない\",\"body\":\"現在進行形でいちばん多い失点は、be動詞を書き落とすことである。\\n\\n× They playing soccer.\\n○ They are playing soccer.\\n× He studying English.\\n○ He is studying English.\\n\\n日本語の「〜している」は動詞ひとつで表せるので、英語でも一語で足りると感じてしまうのが原因である。しかし英語の ~ing 形は、それだけでは文の動詞になれない。必ず be動詞とセットで使う。\\n\\n■ ~ing 形だけを使う場面（参考）\\nPlaying soccer is fun.（サッカーをすることは楽しい）← 主語になっている\\nこれは「動名詞」と呼ばれる別の使い方で、進行形ではない。進行形として使うなら必ず be動詞が前に必要である。\\n\\n■ ~ing を落とす誤りもある\\n× My mother is cook in the kitchen.\\n○ My mother is cooking in the kitchen.\\nbe動詞と原形をそのまま並べても進行形にはならない。be動詞＋~ing の二つがそろって、はじめて「〜している最中」の意味になる。\\n\\n⚠ 注意：主語が長いときは、be動詞の形を選びまちがえやすい。\\nThe boys in the park are playing baseball.（主語は The boys＝複数なので are）\\nThe girl with two dogs is walking along the river.（主語は The girl＝単数なので is）\\nin the park や with two dogs は主語の説明にすぎない。前置詞のかたまりを取りのぞいてから be動詞を決める。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼らは公園でサッカーをしています。」\",\"wrongAnswer\":\"They playing soccer in the park.\",\"trapExplanation\":\"日本語の「しています」が動詞ひとつで表せるので、英語でも playing だけで足りると感じてしまう。~ing 形が単独では文の動詞になれない、という仕組みが身についていない。\",\"correctAnswer\":\"They are playing soccer in the park.\",\"correctExplanation\":\"現在進行形は必ず「be動詞＋~ing」の二語一組で使う。主語 They は複数なので are を置く。英作文では ~ing を書いたら、その前に am / is / are があるかを必ず指さして確認する習慣をつける。\"},{\"question\":\"次の日本語を英語にしなさい。「見て！　あの鳥は歌っているよ。」\",\"wrongAnswer\":\"Look! That bird sings.\",\"trapExplanation\":\"「鳥は歌う」という内容だけを見て現在形を選んでしまう。Look! が「今この瞬間を見て」という合図であることに気づいていない。\",\"correctAnswer\":\"Look! That bird is singing.\",\"correctExplanation\":\"Look! や Listen! は相手の注意を今この瞬間に向ける語なので、あとには現在進行形が続く。That bird sings. だと「あの鳥は（いつも）歌う」という習慣の意味になり、目の前の場面を表せない。\"}]}",
"{\"id\":\"eigo_s130\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在進行形②：現在形（習慣）との使い分け\",\"description\":\"同じ「〜しています」でも、習慣なら現在形・進行中なら進行形と選び分ける\",\"intro\":\"「私はテニスをしています」は、部活の話なら I play tennis.、今コートにいるなら I am playing tennis.。日本語の「〜ています」は両方に使えるあいまいな言い方なので、英語にするとき必ず立ち止まります。\",\"order\":630,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"日本語の「〜ています」は、習慣にも進行中にも使えるあいまいな言い方。\",\"every day / usually / always があれば現在形、now / Look! があれば進行形。\",\"「今この瞬間そうしているか」を自分に問いかけてから形を決める。\",\"職業・状態を述べる「〜しています」は現在形（She teaches English.）。\",\"「〜を飼っています」「〜を持っています」は have を使い、進行形にしない。\"],\"sections\":[{\"heading\":\"日本語の「〜ています」は二つの意味を持つ\",\"body\":\"日本語の「〜ています」は、次の二つをどちらも表せる、とてもあいまいな言い方である。\\n\\n① 今まさにしている最中　→　英語では現在進行形\\n　「私は今、英語を勉強しています」　I am studying English now.\\n② いつもくり返している習慣　→　英語では現在形\\n　「私は毎日、英語を勉強しています」　I study English every day.\\n\\n日本語では同じ「勉強しています」なのに、英語ではまったくちがう形になる。だから日本語をそのまま置きかえるのではなく、「今この瞬間そうしているのか」を必ず自分に問いかける必要がある。\\n\\n■ 見分けの合図\\n現在形になる語：every day / every morning / on Sundays / usually / always / often / sometimes / never\\n現在進行形になる語：now / right now / at this moment / Look! / Listen! / these days（最近）\\n\\n例）My father usually gets up at six.（父はたいてい6時に起きます＝習慣）\\n例）My father is getting up now.（父は今、起きているところです＝今の動作）\\n\\n★ ポイント：迷ったら「今、目の前でその動作をしているか」を考える。していれば進行形、していなくても言えるなら現在形。\",\"figureId\":\"lf_eigoext04_130\"},{\"heading\":\"進行形にしてはいけない「〜ています」\",\"mangaId\":\"eigo_s130_manga\",\"body\":\"日本語で「〜ています」となっていても、英語では進行形にできない場合がある。とくに次の三つに注意する。\\n\\n■ ① 職業や役割を述べるとき\\nShe teaches English at a high school.（彼女は高校で英語を教えています）\\nMy father works for a bank.（父は銀行に勤めています）\\n「今この瞬間に教えている」のではなく「そういう仕事をしている」という意味なので現在形になる。\\n\\n■ ② 所有・状態を表すとき\\nI have two dogs.（私はイヌを2匹飼っています）\\nHe knows my name.（彼は私の名前を知っています）\\nShe lives in Osaka.（彼女は大阪に住んでいます）\\nI like music.（私は音楽が好きです）\\nこれらは動作ではなく状態なので、進行形にしない。× I am having two dogs. は誤り。\\n\\n■ ③ 変わらない事実を述べるとき\\nThe earth goes around the sun.（地球は太陽のまわりを回っています）\\nThis river flows into the sea.（この川は海に流れこんでいます）\\n\\n⚠ 注意：逆に、現在形で書いてしまう誤りも多い。\\n× My father reads a newspaper now.\\n○ My father is reading a newspaper now.\\nnow があるのに現在形にすると「父は今（いつも）新聞を読む」という意味不明な文になる。now / Look! / Listen! を見たら反射的に進行形、と覚えておく。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は毎日ピアノを弾いています。」\",\"wrongAnswer\":\"I am playing the piano every day.\",\"trapExplanation\":\"「弾いています」の「〜ています」だけを見て進行形を選んでしまう。every day という「くり返し」を示す語があるのに、日本語の語尾のほうに気を取られている。\",\"correctAnswer\":\"I play the piano every day.\",\"correctExplanation\":\"every day があるので、これは今この瞬間の動作ではなく習慣である。習慣は現在形で表すので I play the piano every day. とする。「〜ています」を見たら、まず every day や now などの合図の語をさがしてから形を決める。\"},{\"question\":\"次の日本語を英語にしなさい。「私はイヌを2匹飼っています。」\",\"wrongAnswer\":\"I am having two dogs.\",\"trapExplanation\":\"「飼っています」の「〜ています」から進行形を選び、さらに「飼う＝have」と考えて am having としてしまう。have が状態を表す動詞で進行形にできないことを知らないと起こる。\",\"correctAnswer\":\"I have two dogs.\",\"correctExplanation\":\"「飼っている・持っている」という所有は状態なので、have を現在形のまま使う。状態を表す動詞（have・know・like・want・live）は、日本語が「〜ています」でも進行形にしない。これは次のまとまりで学ぶ「状態動詞」の代表例である。\"}]}",
"{\"id\":\"eigo_s131\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在進行形③：~ing のつづり\",\"description\":\"~ing 形の作り方を三つの型で整理し、書きあやまりをなくす\",\"intro\":\"run は runing ではなく running、make は makeing ではなく making、die は dieing ではなく dying。~ing を付けるだけなのに、語尾によって型が分かれます。書き取りで差がつくところです。\",\"order\":631,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"原則はそのまま -ing（play→playing, study→studying, watch→watching）。\",\"e で終わる語は e を取って -ing（make→making, write→writing, come→coming）。\",\"「短い母音＋子音字1つ」は子音字を重ねて -ing（run→running, swim→swimming, sit→sitting）。\",\"ie で終わる語は ie を y に変えて -ing（die→dying, lie→lying）。\",\"see→seeing、be→being は e を取らない。\"],\"sections\":[{\"heading\":\"三つの型\",\"body\":\"~ing 形の作り方は、次の三つの型で整理できる。\\n\\n① そのまま -ing を付ける（いちばん多い）\\nplay→playing　study→studying　watch→watching　read→reading　listen→listening　enjoy→enjoying\\nstudy は y を i に変えない。studying が正しい（過去形の studied とは扱いがちがう）。\\n\\n② e で終わる語は e を取ってから -ing\\nmake→making　write→writing　come→coming　take→taking　use→using　have→having　live→living　dance→dancing\\n「発音しない e」なので、取ってしまう。makeing とは書かない。\\nただし see→seeing、agree→agreeing、be→being は e を残す（ee や特別な形のため）。\\n\\n③ 「短い母音1つ＋子音字1つ」は子音字を重ねる\\nrun→running　swim→swimming　sit→sitting　get→getting　put→putting　cut→cutting　stop→stopping　begin→beginning　shop→shopping\\n過去形で stopped としたのと同じ考え方である。\\n\\n■ 例外：ie → y\\ndie→dying（死ぬ）　lie→lying（横になる・うそをつく）　tie→tying（結ぶ）\\ni が二つ続くのをさけるため、ie を y に変える。\\n\\n★ ポイント：語の最後を見て、e なら②、「母音1つ＋子音字1つ」なら③、それ以外は①。この順に判断すれば迷わない。\",\"figureId\":\"xf_eigo_s131\"},{\"heading\":\"重ねる・重ねないの見分け\",\"body\":\"③の「子音字を重ねる」型を広げすぎる誤りが多い。重ねるのは次の条件を満たすときだけである。\\n\\n■ 重ねる条件\\n（ア）最後が「母音字1つ＋子音字1つ」\\n（イ）その母音を短く読む（1音節、または最後を強く読む語）\\n\\nrun → running（u が短い、1音節）○\\nswim → swimming ○　sit → sitting ○　get → getting ○\\nbegin → beginning（be-GIN と最後を強く読むので重ねる）○\\n\\n■ 重ねない例\\nwait → waiting（母音字が ai と二つ並ぶ。× waitting）\\nread → reading（ea と二つ。× readding）\\nlook → looking（oo と二つ。× lookking）\\nhelp → helping（最後が lp と子音字二つ。× helpping）\\nopen → opening（O-pen と前を強く読む2音節。× openning）\\nvisit → visiting（前を強く読む。× visitting）\\n\\n■ まぎらわしい組を並べて覚える\\nrun→running ／ rain→raining\\nsit→sitting ／ wait→waiting\\nstop→stopping ／ open→opening\\nswim→swimming ／ seem→seeming\\n\\n⚠ 注意：進行形と過去形で判断の基準は同じである。stop は stopped と stopping、visit は visited と visiting。過去形で重ねる語は進行形でも重ね、重ねない語はどちらでも重ねない。一度覚えれば両方に使える。\",\"mangaId\":\"eigo_s131_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は今、公園を走っています。」\",\"wrongAnswer\":\"He is runing in the park now.\",\"trapExplanation\":\"「~ing を付けるだけ」と覚えているので、run にそのまま ing を付けてしまう。子音字を重ねる決まりが抜けている、最も多い書きあやまりの一つである。\",\"correctAnswer\":\"He is running in the park now.\",\"correctExplanation\":\"run は「短い母音 u ＋子音字 n」で終わる1音節の語なので、n を重ねて running とする。同じ型に swim→swimming、sit→sitting、get→getting、begin→beginning がある。runing と書くと「ルーニング」のように長く読む語に見えてしまう。\"},{\"question\":\"次の日本語を英語にしなさい。「私は今、電車を待っています。」\",\"wrongAnswer\":\"I am waitting for the train now.\",\"trapExplanation\":\"running や sitting を覚えたあとに起こる「覚えすぎ」の誤り。最後が t で終わっているので条件を確かめずに重ねてしまう。ルールは適用しすぎても失点になる。\",\"correctAnswer\":\"I am waiting for the train now.\",\"correctExplanation\":\"wait は母音字が ai と二つ並んでいるので、「母音字1つ＋子音字1つ」という条件に当てはまらない。そのまま -ing を付けて waiting とする。rain→raining、read→reading、look→looking も同じで重ねない。\"}]}",
"{\"id\":\"eigo_s132\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在進行形④：否定文・疑問文と答え方\",\"description\":\"進行形の否定文・疑問文はすべて be動詞を動かす、という原則を徹底する\",\"intro\":\"Do you playing soccer? と書いてしまうのは、疑問文には do が要ると思いこんでいるからです。進行形の文にはすでに be動詞があるので、それを前に出すだけ。動かすのは be動詞、と決めてしまいましょう。\",\"order\":632,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"否定文は be動詞のすぐあとに not を置く（He is not playing.）。\",\"疑問文は be動詞を主語の前に出す（Are you studying?）。\",\"答えも be動詞でそろえる（Yes, I am. / No, I am not.）。do は使わない。\",\"疑問詞の文は「疑問詞＋be動詞＋主語＋~ing …?」の順（What are you doing?）。\",\"What are you doing? には I am ~ing … で答える。\"],\"sections\":[{\"heading\":\"否定文・疑問文はすべて be動詞を動かす\",\"body\":\"進行形は be動詞を使う文なので、否定文も疑問文も be動詞の文とまったく同じ作り方になる。do や does は使わない。\\n\\n■ 否定文：be動詞のすぐあとに not\\nHe is playing soccer. → He is not（isn't）playing soccer.\\nThey are watching TV. → They aren't watching TV.\\nI am reading. → I am not reading.（am not に短縮形はない）\\n\\n■ 疑問文：be動詞を主語の前に出す\\nYou are studying. → Are you studying?\\n― Yes, I am. / No, I'm not.\\nShe is cooking. → Is she cooking?\\n― Yes, she is. / No, she isn't.\\n\\n■ 答え方をそろえる\\n質問が Are 〜? なら答えも am / are / is を使う。\\n× Are you watching TV? ― Yes, I do.\\n○ Are you watching TV? ― Yes, I am.\\n「聞かれた動詞で答える」が英語の原則である。Do you 〜? には do、Are you 〜? には be動詞、Did you 〜? には did、で答える。\\n\\n★ ポイント：進行形の文を見たら「これは be動詞の文だ」と最初に決めてしまう。そうすれば否定も疑問も自動的に決まる。\",\"figureId\":\"xf_eigo_s132\",\"mangaId\":\"eigo_s132_xm\"},{\"heading\":\"疑問詞を使う進行形の疑問文\",\"body\":\"疑問詞（what, where, who, how など）を使うときは、疑問詞を文の先頭に置き、そのあとを疑問文の形にする。\\n\\n■ 語順\\n疑問詞 ＋ be動詞 ＋ 主語 ＋ ~ing … ?\\n\\nWhat are you doing?（あなたは何をしているのですか）\\n― I'm doing my homework.（宿題をしています）\\nWhere is he going?（彼はどこへ行くところですか）\\n― He is going to the library.\\nWho is playing the piano?（だれがピアノを弾いているのですか）\\n― Ken is.（ケンです）\\n※ 疑問詞 who が主語のときは、そのまま「Who is ~ing …?」の語順になる。\\n\\n■ よく問われる答え方\\nWhat are you doing? に対しては、動作を答えるので I am ~ing … と進行形で返す。\\n× What are you doing? ― I do my homework.\\n○ What are you doing? ― I'm doing my homework.\\n\\nHow are you feeling today?（今日は気分はどうですか）― I'm feeling better, thank you.\\n\\n⚠ 注意：What do you do? と What are you doing? はまったく意味がちがう。\\nWhat do you do?（あなたは何をしていますか＝ご職業は何ですか）\\nWhat are you doing?（あなたは今、何をしているのですか）\\n現在形は習慣や職業、進行形は今この瞬間の動作を尋ねる。会話文の問題でよく出るちがいである。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「あなたは今、何をしているのですか。」\",\"wrongAnswer\":\"What do you doing now?\",\"trapExplanation\":\"「疑問文は do で始める」と強く覚えているため、進行形の文にも do を持ちこんでしまう。be動詞の文には do を使わない、という区別ができていない。\",\"correctAnswer\":\"What are you doing now?\",\"correctExplanation\":\"進行形は be動詞の文なので、疑問文では be動詞を主語の前に出す。「疑問詞＋be動詞＋主語＋~ing」の順で What are you doing now? とする。答えも I am doing my homework. のように進行形でそろえる。\"},{\"question\":\"次の問いに対する正しい答えを選びなさい。Are you watching TV? ― （Yes, I do. / Yes, I am.）\",\"wrongAnswer\":\"Yes, I do.\",\"trapExplanation\":\"Yes, I do. という答え方を先に覚えているため、質問の形を確かめずに口をついて出てしまう。聞かれた動詞と答えの動詞をそろえる、という原則が身についていない。\",\"correctAnswer\":\"Yes, I am.\",\"correctExplanation\":\"質問が Are 〜? なので、答えも be動詞を使って Yes, I am. / No, I'm not. とする。Do you 〜? なら Yes, I do.、Did you 〜? なら Yes, I did.、Have you 〜? なら Yes, I have.、と質問の先頭の語で答えが決まる。\"}]}",
"{\"id\":\"eigo_s133\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去進行形①：was / were ＋ ~ing\",\"description\":\"過去のある時点で進行中だった動作を表す形をつかむ\",\"intro\":\"「7時には夕食を食べていました」は、I had dinner at seven. ではなく I was having dinner at seven.。過去形は1回で終わった動作、過去進行形はそのとき続いていた動作を表します。\",\"order\":633,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"過去進行形は「was / were ＋ ~ing」で、「そのとき〜している最中だった」を表す。\",\"be動詞は主語に合わせる。I・三人称単数→was、you・複数→were。\",\"then / at that time / at seven last night のように「過去の一点」を示す語と使う。\",\"否定文・疑問文は be動詞を動かす（wasn't / Were you 〜?）。did は使わない。\",\"過去形は「一回で終わった動作」、過去進行形は「続いていた動作」。\"],\"sections\":[{\"heading\":\"過去進行形の形と意味\",\"body\":\"過去進行形は「過去のある時点で、その動作が進行中だった」ことを表す。現在進行形の be動詞を過去形にするだけでよい。\\n\\n例）I was watching TV at eight last night.（私は昨夜8時にテレビを見ていました）\\n例）They were playing soccer then.（彼らはそのときサッカーをしていました）\\n例）She was studying in her room.（彼女は自分の部屋で勉強していました）\\n\\n■ 形\\nI / He / She / It ＋ was ＋ ~ing\\nYou / We / They ＋ were ＋ ~ing\\n\\n■ いっしょに使われる語\\nthen（そのとき）・at that time（そのとき）・at eight last night（昨夜8時に）\\nthis morning（今朝）・when I came home（私が家に帰ったとき）\\n「過去のどの時点で進行中だったのか」をはっきりさせる語句が必要になる。ただ was playing とだけ言っても、いつのことか分からないからである。\\n\\n■ 過去形とのちがい\\nI watched TV last night.（昨夜テレビを見た＝見たという事実だけ）\\nI was watching TV at eight last night.（昨夜8時には見ている最中だった＝その時点で進行中）\\n前者は「見た」という出来事を一点として述べ、後者は「その時刻に続いていた」という幅を述べている。\\n\\n★ ポイント：過去進行形は「過去に置いた帯」。その帯のどこかを指し示す語句（then、at eight、when 〜）がセットになる。\",\"figureId\":\"lf_eigoext04_133\"},{\"heading\":\"否定文・疑問文と、二つの動作の関係\",\"body\":\"■ 否定文・疑問文は be動詞を動かす\\nHe was sleeping. → He was not（wasn't）sleeping.\\nThey were studying. → They weren't studying.\\nYou were reading. → Were you reading?　― Yes, I was. / No, I wasn't.\\nWhat were you doing at that time?（そのとき何をしていましたか）― I was cooking dinner.\\n現在進行形と同じく、did は使わない。× Did you doing 〜? は誤りである。\\n\\n■ 二つの動作が同時に起こる文\\n過去進行形は、別の動作といっしょに使われることが多い。\\nWhen I came home, my mother was cooking dinner.\\n（私が家に帰ったとき、母は夕食を作っていました）\\nこの文では、母が料理をしている長い時間の帯の中に、「私が帰った」という一回きりの動作が割りこんでいる。\\n\\n■ どちらを進行形にするか\\n・長く続いていたほう　→　過去進行形（was cooking）\\n・その途中で起きた短い動作　→　過去形（came）\\n両方を過去形にすると「帰ってから料理を始めた」という別の意味になってしまうので、区別が重要である。\\n\\n⚠ 注意：主語が長いときの was / were の選びまちがえに注意する。\\nMy brother and I were listening to music then.（兄と私＝二人なので were）\\nThe boys in the park were playing baseball.（主語は The boys＝複数なので were）\\nすぐ前の語ではなく、主語全体の数で決める。\",\"mangaId\":\"eigo_s133_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私が家に帰ったとき、母は夕食を作っていました。」\",\"wrongAnswer\":\"When I came home, my mother cooked dinner.\",\"trapExplanation\":\"「過去の話なのだから、二つとも過去形でよい」と考えてしまう。日本語の「作っていました」の「〜ていました」が進行を表していることに気づいていない。\",\"correctAnswer\":\"When I came home, my mother was cooking dinner.\",\"correctExplanation\":\"母が料理をしている途中に「私が帰る」という動作が起きたので、続いていたほうを過去進行形 was cooking にする。両方を過去形にすると「帰ってから料理を始めた」という別の意味の文になってしまう。\"},{\"question\":\"次の英文の（　）に入る正しい語を選びなさい。My brother and I （was / were）listening to music then.\",\"wrongAnswer\":\"was\",\"trapExplanation\":\"（　）のすぐ前にある I につられて was を選んでしまう。I was 〜 という形をよく使うため、主語全体を見ずに反射的に答えてしまうことが原因である。\",\"correctAnswer\":\"were\",\"correctExplanation\":\"主語は My brother and I（兄と私＝二人）で複数なので were を使う。主語を代名詞に置きかえると We were listening to music then. となり、すぐ確かめられる。and でつながれた主語は複数、と覚えておく。\"}]}",
"{\"id\":\"eigo_s134\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去進行形②：when と while の使い分け\",\"description\":\"二つの動作の関係を when / while で正しく結べるようにする\",\"intro\":\"「勉強しているときに電話が鳴った」を英語にすると、どちらを進行形にするか迷います。長く続いていたほうを進行形、とちゅうで起きた短い動作を過去形にします。while のうしろを過去形にしないのがきまりです。\",\"order\":634,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"when＝「〜したとき」。あとには短い一回の動作（過去形）が来ることが多い。\",\"while＝「〜している間に」。あとには続いていた動作（過去進行形）が来る。\",\"長く続いていたほうを進行形、途中で起きた短い動作を過去形にする。\",\"when / while のかたまりは文の前半にも後半にも置ける。前に置くときはコンマで区切る。\",\"while の直後を過去形にしない（× While I studied 〜）。\"],\"sections\":[{\"heading\":\"when と while の役割のちがい\",\"body\":\"過去進行形は、when や while を使って別の動作と結びつけることが多い。\\n\\n■ when 〜（〜したとき）\\nあとに続くのは、たいてい「一回きりの短い動作」である。\\nWhen the phone rang, I was taking a bath.\\n（電話が鳴ったとき、私はふろに入っていました）\\n「電話が鳴る」は一瞬の出来事なので過去形、「ふろに入っている」は続いていたので過去進行形になる。\\n\\n■ while 〜（〜している間に）\\nあとに続くのは「続いていた動作」なので、過去進行形になる。\\nWhile I was studying English, my brother came into my room.\\n（私が英語を勉強している間に、弟が部屋に入ってきました）\\n\\n■ 二つの言い方は入れかえられる\\nWhen the phone rang, I was taking a bath.\\n＝ While I was taking a bath, the phone rang.\\n同じ場面を、どちらの動作を先に述べるかで言いかえているだけである。when のあとは短い動作、while のあとは続いていた動作、という役割は変わらない。\\n\\n★ ポイント：「割りこんだほうが when、割りこまれたほうが while」と覚えると迷わない。\",\"figureId\":\"xf_eigo_s134\",\"mangaId\":\"eigo_s134_xm\"},{\"heading\":\"語順と、まちがえやすい形\",\"body\":\"■ 語順は二通り\\nWhen I came home, my mother was cooking dinner.\\nMy mother was cooking dinner when I came home.\\nwhen や while のかたまりは、文の前に置いても後ろに置いてもよい。前に置くときはコンマ（,）で区切る。後ろに置くときはコンマは不要である。\\n\\n■ while の直後を過去形にしない\\n× While I studied English, my brother came into my room.\\n○ While I was studying English, my brother came into my room.\\nwhile は「〜している間に」という意味なので、そのあとは進行形になるのが原則である。\\n\\n■ 両方が続いていた場合は両方進行形\\nWhile I was cooking, my sister was cleaning the room.\\n（私が料理をしている間、姉は部屋をそうじしていました）\\n二つの動作が並行して続いていたときは、どちらも過去進行形にする。\\n\\n■ 短い動作どうしなら両方過去形\\nWhen I opened the door, the cat ran out.\\n（私がドアを開けると、ネコが走り出た）\\nどちらも一瞬の出来事なので、進行形にはしない。\\n\\n⚠ 注意：when は「〜したとき」だけでなく「〜するとき」の意味でも使う。When I get up, I always drink water.（起きたとき、いつも水を飲む）。この場合は習慣なので現在形になる。時制は文全体の内容で決める。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私が英語を勉強している間に、弟が部屋に入ってきました。」\",\"wrongAnswer\":\"While I studied English, my brother came into my room.\",\"trapExplanation\":\"「過去の文だから過去形」と機械的に考え、while のあとも過去形にしてしまう。while が「〜している間に」という進行の意味を持つことが意識されていない。\",\"correctAnswer\":\"While I was studying English, my brother came into my room.\",\"correctExplanation\":\"while のあとには「続いていた動作」が来るので過去進行形 was studying にする。そこへ割りこんできた「弟が入ってきた」は一回きりの動作なので過去形 came。while ＝進行形、と形で結びつけて覚える。\"},{\"question\":\"次の日本語を英語にしなさい。「電話が鳴ったとき、私はふろに入っていました。」\",\"wrongAnswer\":\"When the phone was ringing, I took a bath.\",\"trapExplanation\":\"どちらを進行形にするかを取りちがえている。日本語の語順のまま「電話が鳴った」を先に見て、そこに進行形を当ててしまうために起こる。\",\"correctAnswer\":\"When the phone rang, I was taking a bath.\",\"correctExplanation\":\"長く続いていたのは「ふろに入っている」ほうなので、そちらを過去進行形 was taking にする。「電話が鳴る」は一瞬の出来事なので過去形 rang。「割りこんだ短い動作が when のあと」と覚えると判断が速くなる。\"}]}",
"{\"id\":\"eigo_s135\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"進行形にしない動詞①：状態動詞\",\"description\":\"know・like・have など、進行形にできない動詞のグループを覚える\",\"intro\":\"「彼を知っています」を I am knowing him. とは言えません。know は状態を表すので、進行形にしないからです。日本語の「〜ています」がそのまま進行形にならない動詞のグループを、まとめて覚えます。\",\"order\":635,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"状態を表す動詞は、日本語が「〜ている」でも進行形にしない。\",\"気持ち：like, love, want, need, hate。\",\"頭のはたらき：know, understand, remember, believe, think（思う）。\",\"所有・関係：have（持っている）, belong to, resemble。\",\"感覚：see（見える）, hear（聞こえる）。can をそえて I can see 〜. と言うことが多い。\"],\"sections\":[{\"heading\":\"状態動詞とは\",\"mangaId\":\"eigo_s135_manga\",\"body\":\"動詞には「動作」を表すものと「状態」を表すものがある。状態を表す動詞は進行形にしない。\\n\\n■ 状態動詞の代表\\n気持ちを表す：like（好きだ）・love（愛している）・want（ほしい）・need（必要だ）・hate（きらいだ）\\n頭のはたらきを表す：know（知っている）・understand（理解している）・remember（覚えている）・believe（信じている）・think（〜だと思う）\\n所有・関係を表す：have（持っている）・belong to（〜に属している）・resemble（似ている）\\n感覚を表す：see（見える）・hear（聞こえる）・smell（においがする）・taste（味がする）\\n\\n例）I know his name.（彼の名前を知っています）\\n例）She wants a new bag.（彼女は新しいかばんをほしがっています）\\n例）He has a nice car.（彼はすてきな車を持っています）\\n例）I understand your question.（あなたの質問が分かります）\\n\\nこれらはすべて日本語で「〜ている」となるが、× I am knowing、× She is wanting とは言えない。\\n\\n■ なぜ進行形にしないのか\\n進行形は「今始まって、今続いていて、もうすぐ終わる」という短い幅を作る形である。ところが状態動詞は、はじめから長く続いている状態そのものを表しているので、わざわざ幅を作る必要がない。「知っている」という状態に「今まさに知っている最中」という言い方は成り立たないのである。\\n\\n★ ポイント：動作は「やめられる」、状態は「やめられない」。走るのはやめられるが、知っているのは自分でやめられない。やめられないものは進行形にしない。\",\"figureId\":\"lf_eigoext04_135\"},{\"heading\":\"感覚を表す動詞と can\",\"body\":\"see・hear のような感覚の動詞は、進行形にするかわりに can をそえることが多い。\\n\\n例）I can see Mt. Fuji from here.（ここから富士山が見えます）\\n例）I can hear a bird singing.（鳥が鳴いているのが聞こえます）\\n「今この瞬間に見えている・聞こえている」ことを表したいときに、英語では can see / can hear と言う。日本語の「見えている」「聞こえている」につられて am seeing / am hearing としないよう注意する。\\n\\n■ look / watch / listen とのちがい\\nsee（見える）… 自然に目に入る　　→ I can see the sea.\\nlook at（目を向ける）… 意識して見る → I am looking at the picture.（進行形にできる）\\nwatch（動くものをじっと見る）… → I am watching TV.（進行形にできる）\\nhear（聞こえる）… 自然に耳に入る　→ I can hear music.\\nlisten to（耳をかたむける）… → I am listening to music.（進行形にできる）\\n\\n同じ「見る」「聞く」でも、自分の意志でする動作（look at, watch, listen to）は進行形にできる。自然に感じ取るだけの see, hear は進行形にしない。この対応は入試で非常によく問われる。\\n\\n⚠ 注意：think は意味によって扱いがちがう。\\nI think he is right.（彼は正しいと思う）… 「思う」＝状態なので進行形にしない\\nI am thinking about my future.（将来について考えているところだ）… 「頭を働かせる」＝動作なので進行形にできる\\nこのように、一つの動詞が二つの顔を持つことがある。次のまとまりでくわしく学ぶ。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私はこの歌を知っています。」\",\"wrongAnswer\":\"I am knowing this song.\",\"trapExplanation\":\"「知っています」の「〜ています」を進行形と結びつけてしまう。日本語では状態も「〜ている」で表すので、そのまま置きかえると誤りになる。\",\"correctAnswer\":\"I know this song.\",\"correctExplanation\":\"know は状態を表す動詞なので進行形にしない。現在形のままで「今知っている」という意味になる。like・want・have・understand・remember も同じ仲間で、日本語が「〜ている」でも現在形のまま使う。\"},{\"question\":\"次の日本語を英語にしなさい。「ここから海が見えます。」\",\"wrongAnswer\":\"I am seeing the sea from here.\",\"trapExplanation\":\"「見えています」という今の状態を表したいので進行形を選んでしまう。see が「自然に目に入る」という状態の動詞であることを知らないと起こる。\",\"correctAnswer\":\"I can see the sea from here.\",\"correctExplanation\":\"see・hear は進行形にせず、can をそえて「見える・聞こえる」を表す。意識して見る look at や watch、耳をかたむける listen to は進行形にできる（I am watching TV.）。この対応をペアで覚えておく。\"}]}",
"{\"id\":\"eigo_s136\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"進行形にしない動詞②：have や think の二つの顔\",\"description\":\"同じ動詞でも意味によって進行形にできる場合とできない場合があることを知る\",\"intro\":\"have は進行形にできないと習ったのに、We are having lunch. は正しい英語です。「持っている」なら状態、「食べる」なら動作だからです。同じ動詞が2つの顔を持つ、その見分け方を身につけます。\",\"order\":636,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"have は「持っている」なら状態で進行形にしない。「食べる・過ごす」なら動作で進行形にできる。\",\"We are having lunch.（昼食を食べているところだ）／We are having a good time.（楽しんでいる）は正しい。\",\"think は「〜と思う」なら状態、「考える」なら動作（I am thinking about it.）。\",\"see は「見える」なら状態、「（人に）会う」なら動作。\",\"「動作かどうか」は、その行為を自分の意志で始めたり止めたりできるかで判断する。\"],\"sections\":[{\"heading\":\"have の二つの顔\",\"mangaId\":\"eigo_s136_manga\",\"body\":\"have は英語で最もよく使う動詞の一つで、意味によって進行形にできるかどうかが変わる。\\n\\n■ 状態の have（進行形にしない）\\nI have two brothers.（兄弟が二人います）\\nHe has a new bike.（新しい自転車を持っています）\\nShe has long hair.（髪が長い）\\nI have a cold.（風邪をひいている）\\n「持っている・そなえている」という所有や性質を表す have は状態なので、進行形にできない。\\n\\n■ 動作の have（進行形にできる）\\nWe are having lunch now.（私たちは今、昼食を食べているところです）\\nThey are having a party.（彼らはパーティーを開いているところです）\\nI am having a good time.（私は楽しい時を過ごしています）\\nhave が「食べる・飲む・（会などを）開く・（時を）過ごす」の意味になると、これは動作なので進行形にできる。\\n\\n■ 見分け方\\nその動作を「今始めた」「もうすぐ終わる」と言えるなら動作、ずっとそうであり続けるだけなら状態である。昼食は始まって終わるので動作、兄弟がいることはやめられないので状態である。\\n\\n★ ポイント：have を見たら「持っている」か「食べる・過ごす」かを確かめる。前者なら現在形、後者なら進行形も使える。\",\"figureId\":\"xf_eigo_s136\"},{\"heading\":\"think・see なども二つの顔を持つ\",\"body\":\"■ think\\nI think he is a good teacher.（彼はよい先生だと思います）… 「思う」＝状態、進行形にしない\\nI am thinking about my future.（将来について考えているところです）… 「頭を働かせる」＝動作、進行形にできる\\n「〜と思う」という意見は状態、「あれこれ考える」という頭のはたらきは動作である。\\n\\n■ see\\nI can see a bird in the tree.（木に鳥が見えます）… 「見える」＝状態\\nI am seeing my grandmother this weekend.（今週末、祖母に会う予定です）… 「会う」＝動作\\n※「会う予定」の意味では未来を表す使い方にもなる。\\n\\n■ そのほかの例\\ntaste：This soup tastes good.（このスープはおいしい味がする＝状態）／ She is tasting the soup.（彼女はスープの味見をしている＝動作）\\nsmell：The flower smells sweet.（甘いにおいがする＝状態）／ He is smelling the flower.（花のにおいをかいでいる＝動作）\\nlook：You look tired.（つかれて見える＝状態）／ I am looking at the map.（地図を見ている＝動作）\\n\\n■ 覚え方\\n「自然にそうなっている」なら状態、「自分でしている」なら動作。味がするのは自然だが、味見をするのは自分の意志でする動作である。\\n\\n⚠ 注意：「have は進行形にできない」とだけ覚えると、今度は We have lunch now. と書いてしまう。ルールは覚えすぎても失点になる。意味を確かめてから形を決める、という順番を守る。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私たちは今、昼食を食べているところです。」\",\"wrongAnswer\":\"We have lunch now.\",\"trapExplanation\":\"「have は状態動詞だから進行形にできない」と一度覚えたことを、意味を確かめずにすべての have に当てはめてしまう。ルールの覚えすぎから生まれる誤りである。\",\"correctAnswer\":\"We are having lunch now.\",\"correctExplanation\":\"この have は「食べる」という動作の意味なので、進行形にできる。進行形にしないのは「持っている・そなえている」という所有の have だけ。have a party、have a good time も動作なので are having と言える。\"},{\"question\":\"次の日本語を英語にしなさい。「私は新しい自転車を持っています。」\",\"wrongAnswer\":\"I am having a new bike.\",\"trapExplanation\":\"We are having lunch. のような形を覚えたあとに、今度はすべての have を進行形にしてしまう。「持っています」の「〜ています」も進行形と結びつきやすい。\",\"correctAnswer\":\"I have a new bike.\",\"correctExplanation\":\"「持っている」という所有は状態なので進行形にしない。have は「所有＝状態、食べる・過ごす＝動作」と二つの顔を持つので、そのつど意味を確かめる。所有の have は現在形のままで「今持っている」ことを表せる。\"}]}",
"{\"id\":\"eigo_s137\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来①：will の基本\",\"description\":\"will の形と、「その場で決めた意志」「今の予測」という二つの意味をつかむ\",\"intro\":\"「じゃあ、ぼくが持つよ」のように、その場で決めたことは will で表します。ところが will のうしろは必ず原形なので、He will is busy. とは書けません。will be です。意味と形をあわせて確認します。\",\"order\":637,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"will のあとは必ず動詞の原形。主語が三人称単数でも -s は付けない。\",\"be動詞の原形は be（× will is、○ will be）。\",\"will の意味①：話しているその場で決めた意志（I'll help you.）。\",\"will の意味②：今の時点での予測（It will be sunny tomorrow.）。\",\"tomorrow / next week / someday / in the future が合図になる。\"],\"sections\":[{\"heading\":\"will の形\",\"body\":\"英語には「未来形」という動詞の形はない。未来のことは will や be going to などの言い方で表す。\\n\\n■ 形は「will ＋ 動詞の原形」\\nI will go to Tokyo next week.（私は来週、東京へ行きます）\\nHe will come here tomorrow.（彼は明日ここへ来ます）\\nThey will be busy next month.（彼らは来月いそがしいでしょう）\\n\\n■ 主語による形の変化がない\\nwill は主語が何であっても will のまま。そして will のあとの動詞は必ず原形になる。\\n× He will comes here.　○ He will come here.\\n× She will goes to school.　○ She will go to school.\\n現在形では He comes と -s が必要だったが、will のあとでは原形にもどる。\\n\\n■ be動詞の原形は be\\n× It will is sunny.　○ It will be sunny tomorrow.（明日は晴れるでしょう）\\n× You will are busy.　○ You will be busy tomorrow.\\nam / is / are の原形が be であることを忘れると、この形でつまずく。\\n\\n■ 短縮形\\nI will → I'll　　you will → you'll　　he will → he'll　　it will → it'll\\nwe will → we'll　　they will → they'll\\n会話文では短縮形がよく使われる。\\n\\n★ ポイント：will のあとは原形。三単現の -s も、be動詞の is も、そこには入らない。\",\"figureId\":\"lf_eigoext04_137\",\"mangaId\":\"eigo_s137_xm\"},{\"heading\":\"will の二つの意味\",\"body\":\"■ ① その場で決めた意志（〜します）\\n話している、まさにその瞬間に決めたことを表す。\\nA: The phone is ringing.（電話が鳴っているよ）\\nB: I'll answer it.（私が出ます）\\nA: This bag is heavy.（このかばん、重いなあ）\\nB: I'll carry it for you.（私が運びましょう）\\n前もって決めていたわけではなく、その場で申し出ているので will を使う。\\n\\n■ ② 今の時点での予測（〜でしょう）\\nIt will be sunny tomorrow.（明日は晴れるでしょう）\\nHe will be twelve next year.（彼は来年12歳になります）\\nI think it will rain this afternoon.（午後は雨が降ると思います）\\n「たぶんこうなるだろう」という話し手の見通しを表す。I think 〜 や probably（たぶん）といっしょに使われることが多い。\\n\\n■ 合図になる語\\ntomorrow（明日）・next week / month / year（来週・来月・来年）\\nsomeday（いつか）・in the future（将来）・soon（まもなく）・this afternoon（今日の午後）\\n\\n⚠ 注意：日本語の「〜します」がすべて will になるわけではない。前から決めていた予定は be going to を使うほうが自然である（次のまとまりで学ぶ）。will はあくまで「今決めた」「今予測した」という、決断や判断の瞬間が「今」にある言い方である。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は明日、ここへ来るでしょう。」\",\"wrongAnswer\":\"He will comes here tomorrow.\",\"trapExplanation\":\"「主語が三人称単数なら動詞に -s」という決まりが強く身についているため、will があっても -s を付けてしまう。will のあとが原形だという原則が抜けている。\",\"correctAnswer\":\"He will come here tomorrow.\",\"correctExplanation\":\"will のあとは必ず動詞の原形なので come とする。三単現の -s が付くのは「現在形」のときだけ。will・can・must などの助動詞のあと、did のあと、to のあとは、いずれも原形になる。\"},{\"question\":\"次の日本語を英語にしなさい。「あなたは明日、いそがしいでしょう。」\",\"wrongAnswer\":\"You will are busy tomorrow.\",\"trapExplanation\":\"「あなたは〜です」を英語にするとき You are 〜 と覚えているので、will を足すときも are をそのまま残してしまう。be動詞の原形が be であることを意識していない。\",\"correctAnswer\":\"You will be busy tomorrow.\",\"correctExplanation\":\"am / is / are の原形は be なので、will のあとは be になる。It will be sunny. / He will be twelve next year. も同じ形。「will のあとは原形」という原則は、be動詞にもそのまま当てはまる。\"}]}",
"{\"id\":\"eigo_s138\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来②：will の否定文・疑問文と Shall\",\"description\":\"won't の形、Will you 〜? の依頼、Shall I / Shall we の使い分けを覚える\",\"intro\":\"will not の短縮形は willn't ではなく won't です。形が予想外なので、これは覚えるしかありません。また Will you 〜? は「〜するつもりですか」だけでなく、「〜してくれませんか」という頼み方にもなります。\",\"order\":638,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"否定は will not。短縮形は won't（× willn't）。\",\"疑問文は Will ＋主語＋原形 …?　答えは Yes, 主語 will. / No, 主語 won't.\",\"Will you 〜? は「〜してくれませんか」という依頼にもなる。答えは Sure. / All right. / Sorry, I can't.\",\"Shall I 〜?＝「（私が）〜しましょうか」。答えは Yes, please. / No, thank you.\",\"Shall we 〜?＝「（いっしょに）〜しましょうか」。答えは Yes, let's. / No, let's not.\"],\"sections\":[{\"heading\":\"否定文と疑問文\",\"body\":\"■ 否定文：will not（won't）＋原形\\nI will not（won't）go to school tomorrow.（明日は学校へ行きません）\\nIt won't rain this afternoon.（今日の午後は雨は降らないでしょう）\\n短縮形は won't である。don't・doesn't・didn't の形につられて willn't と書くのは誤り。つづりも「wo」で始まる点に注意する。\\n\\n■ 疑問文：Will ＋主語＋動詞の原形 …?\\nWill he come to the party?（彼はパーティーに来るでしょうか）\\n― Yes, he will. / No, he won't.\\nWill it be sunny tomorrow?（明日は晴れるでしょうか）\\n― Yes, it will. / No, it won't.\\n\\n■ 疑問詞のある疑問文\\nWhat will you do this weekend?（今週末は何をしますか）― I'll visit my uncle.\\nWhere will you go next summer?（来年の夏はどこへ行きますか）\\nWhen will he come back?（彼はいつもどってきますか）\\n語順は「疑問詞＋will＋主語＋原形 …?」となる。\\n\\n★ ポイント：will の文はすべて「will を動かす」だけで否定・疑問が作れる。do や does は使わない。\",\"figureId\":\"xf_eigo_s138\"},{\"heading\":\"Will you 〜? と Shall I / Shall we 〜?\",\"body\":\"■ Will you 〜?（〜してくれませんか）\\nWill you open the window?（窓を開けてくれませんか）\\n― Sure. / All right. / OK. / Sorry, I can't.\\n本来は「あなたは〜するつもりですか」だが、実際には相手にお願いする言い方としてよく使われる。答えるときは Yes, I will. でも通じるが、会話では Sure. や All right. が自然である。\\nより丁寧に言うときは Would you 〜? や Could you 〜? を使う。\\n\\n■ Shall I 〜?（（私が）〜しましょうか）\\nShall I open the window?（窓を開けましょうか）\\n― Yes, please.（はい、お願いします）／ No, thank you.（いいえ、けっこうです）\\n自分が相手のために何かをしようと申し出る言い方である。\\n\\n■ Shall we 〜?（（いっしょに）〜しましょうか）\\nShall we play tennis?（いっしょにテニスをしませんか）\\n― Yes, let's.（そうしましょう）／ No, let's not.（やめておきましょう）\\nLet's play tennis. とほぼ同じ意味になる。\\n\\n■ 答え方をまちがえない\\nShall I 〜? → Yes, please. / No, thank you.\\nShall we 〜? → Yes, let's. / No, let's not.\\nI（私が一人でする）か we（いっしょにする）かで答え方が変わる。ここは入試で必ず問われる。\\n\\n⚠ 注意：Will you 〜? は場面によって「依頼」にも「予定をたずねる文」にもなる。Will you come to the party?（パーティーに来ますか＝予定をたずねる）／ Will you help me?（手伝ってくれませんか＝依頼）。前後の会話から判断する。\",\"mangaId\":\"eigo_s138_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は明日、学校へ行きません。」\",\"wrongAnswer\":\"I willn't go to school tomorrow.\",\"trapExplanation\":\"don't・doesn't・didn't・isn't のように「not を n't にして後ろにくっつける」という形に慣れているため、will にも同じ作り方を当てはめてしまう。\",\"correctAnswer\":\"I won't go to school tomorrow.\",\"correctExplanation\":\"will not の短縮形は won't という特別な形になる。willn't という語は存在しない。つづりも will とは変わって「wo」で始まるので、書いて覚える必要がある。短縮しない I will not go 〜 でももちろん正しい。\"},{\"question\":\"次の問いへの正しい答えを選びなさい。Shall I carry your bag? ― （Yes, let's. / Yes, please.）\",\"wrongAnswer\":\"Yes, let's.\",\"trapExplanation\":\"Shall という語だけを見て、Shall we 〜? の答え方 Yes, let's. を反射的に選んでしまう。I と we のちがいを読み取れていない。\",\"correctAnswer\":\"Yes, please.\",\"correctExplanation\":\"Shall I 〜? は「（私が）〜しましょうか」という申し出なので、答えは Yes, please. / No, thank you. になる。Yes, let's. と答えるのは Shall we 〜?（いっしょに〜しましょうか）のとき。I か we かをまず確かめる。\"}]}",
"{\"id\":\"eigo_s139\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来③：be going to（前から決めていた予定）\",\"description\":\"be going to の形と、「前から決めていた予定」「きざしからの予測」の意味をつかむ\",\"intro\":\"「来週、京都に行くつもりです」のように前から決めていた予定は、be going to で表します。going という語が入っていますが、「行く」という意味とはかぎりません。to のうしろは必ず原形です。\",\"order\":639,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"形は「be動詞（am/is/are）＋going to＋動詞の原形」。be動詞は主語に合わせる。\",\"意味①：前から決めていた予定・つもり（I am going to visit Kyoto next week.）。\",\"意味②：今のきざしから見た予測（It is going to rain. 空が暗い）。\",\"否定文・疑問文は be動詞を動かす（isn't going to / Are you going to 〜?）。\",\"to のあとは必ず原形（× is going to buys）。\"],\"sections\":[{\"heading\":\"be going to の形と意味\",\"body\":\"■ 形\\nI am going to play tennis tomorrow.（明日テニスをするつもりです）\\nHe is going to visit his uncle next Sunday.（彼は次の日曜におじさんを訪ねる予定です）\\nThey are going to have a party.（彼らはパーティーを開く予定です）\\nbe動詞は主語に合わせて am / is / are を使い分け、going to のあとは必ず動詞の原形を置く。\\n\\n■ 意味① 前から決めていた予定\\nI'm going to study abroad next year.（私は来年、留学するつもりです）\\nすでに心の中で決めていて、場合によっては準備も始めていることを表す。「今決めた」ではなく「前から決めていた」という点が will とのちがいである。\\n\\n■ 意味② 今のきざしから見た予測\\nLook at those dark clouds. It's going to rain.（あの黒い雲を見て。雨が降りそうだ）\\nHe is going to fall!（彼は落ちそうだ！）\\n目の前に「そうなりそうな証拠」があるときの予測に使う。単なる見通しを述べる will とはちがい、根拠が目の前にある。\\n\\n★ ポイント：be going to は「もうその方向に進んでいる」感じ。決めた時点や、そうなるきざしが、すでに今より前にある。\",\"figureId\":\"lf_eigoext04_139\",\"mangaId\":\"eigo_s139_xm\"},{\"heading\":\"否定文・疑問文と注意点\",\"body\":\"be going to は be動詞を使う文なので、否定文も疑問文も be動詞を動かす。\\n\\n■ 否定文\\nI am not going to watch TV tonight.（今夜はテレビを見るつもりはありません）\\nHe isn't going to come.（彼は来るつもりはありません）\\nThey aren't going to play soccer.\\n\\n■ 疑問文\\nAre you going to visit Kyoto?（京都を訪れるつもりですか）\\n― Yes, I am. / No, I'm not.\\nIs he going to join us?（彼は参加する予定ですか）\\n― Yes, he is. / No, he isn't.\\nWhat are you going to do this weekend?（今週末は何をするつもりですか）\\n― I'm going to see a movie.\\n\\n■ to のあとは原形\\n× She is going to buys a new bike.\\n○ She is going to buy a new bike.\\ngoing to のあとには必ず原形が来る。三単現の -s を付けるのは、現在形の動詞だけである。\\n\\n■ be going to go の重なり\\nI am going to go to Osaka next week.（来週、大阪へ行く予定です）\\ngo が二回続くので変に見えるが、これは正しい文である。会話では I'm going to Osaka next week. と、現在進行形で予定を表す言い方も使われる。\\n\\n⚠ 注意：be動詞を落とす誤りが多い。× They going to play tennis. → ○ They are going to play tennis. going to は be動詞とセットで一つの形である。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼女は来月、新しい自転車を買うつもりです。」\",\"wrongAnswer\":\"She is going to buys a new bike next month.\",\"trapExplanation\":\"主語 She が三人称単数であることが目に入り、動詞に -s を付けてしまう。すでに is が主語に合わせてあるので、そのあとは原形でよい、という仕組みが見えていない。\",\"correctAnswer\":\"She is going to buy a new bike next month.\",\"correctExplanation\":\"going to のあとは必ず動詞の原形なので buy とする。主語に合わせるのは be動詞（is）のほうで、-s の役目はそこですでに果たされている。will come、to buy、did go と同じく「原形が来る場所」として覚える。\"},{\"question\":\"次の場面にふさわしい英文を選びなさい。空を見上げると黒い雲が広がっている。「雨が降りそうだ。」\",\"wrongAnswer\":\"It will rain.\",\"trapExplanation\":\"「未来のこと＝will」と一つだけ覚えているため、目の前に根拠があってもすべて will で表してしまう。will と be going to の使い分けが「時」ではなく「根拠の有無」で決まることを知らない。\",\"correctAnswer\":\"It's going to rain.\",\"correctExplanation\":\"黒い雲という「そうなりそうなきざし」が目の前にあるときの予測は be going to を使う。will は根拠のない見通しや、今その場で思った予測に使う。Look at those clouds. It's going to rain. がひとまとまりの表現として出題される。\"}]}",
"{\"id\":\"eigo_s140\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来④：will と be going to の使い分け\",\"description\":\"「いつ決めたか」「根拠があるか」で二つの未来表現を選び分ける\",\"intro\":\"will も be going to も「〜するつもり」と訳せるのに、英語では選び分けます。決め手は「いつ決めたか」。今この場で決めたなら will、前から決めていたなら be going to。切符をもう買ってあるなら後者です。\",\"order\":640,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"決めたのが「今この瞬間」なら will、「前から」なら be going to。\",\"その場の申し出・約束は will（I'll get it. / I'll help you.）。\",\"準備ずみの予定は be going to（I'm going to visit Kyoto. 切符はもう買った）。\",\"目の前のきざしから予測するときは be going to、根拠のない見通しは will。\",\"どちらでもよい場合も多いが、会話問題では場面から判断させる出題が多い。\"],\"sections\":[{\"heading\":\"「いつ決めたか」で選ぶ\",\"mangaId\":\"eigo_s140_manga\",\"body\":\"will と be going to は、どちらも未来のことを表す。ちがいは「決めた時点がどこにあるか」である。\\n\\n■ その場で決めた → will\\nA: The phone is ringing.（電話が鳴っているよ）\\nB: I'll answer it.（私が出ます）\\n電話が鳴るのを聞いて、その瞬間に決めたことなので will を使う。ここで I'm going to answer it. と言うと「前からそのつもりだった」という不自然な意味になる。\\n\\nA: I can't open this jar.（このびんが開かない）\\nB: I'll help you.（手伝ってあげるよ）\\n\\n■ 前から決めていた → be going to\\nA: Why are you buying so much food?（どうしてそんなに食べ物を買っているの）\\nB: I'm going to have a party tonight.（今夜パーティーを開く予定なんだ）\\n買い物をしている時点ですでに決まっていたことなので be going to を使う。\\n\\n■ 判断の手順\\n①その予定は、話す前から決まっていたか　→　はい：be going to\\n②話しているその瞬間に決めたか　→　はい：will\\n\\n★ ポイント：会話文の問題では、直前のセリフを見る。相手の言葉を聞いて決めたのなら必ず will である。\",\"figureId\":\"xf_eigo_s140\"},{\"heading\":\"予測のときの使い分けと、共通する点\",\"body\":\"■ 予測の場合\\n根拠が目の前にある　→　be going to\\n　Look at the sky. It's going to snow.（空を見て。雪が降りそうだ）\\n　The baby is going to cry.（赤ちゃんが泣きそうだ ← 顔がゆがんでいる）\\n根拠がなく、話し手の見通しを述べる　→　will\\n　I think he will win the game.（彼は試合に勝つと思う）\\n　Our team will be strong next year.（来年、私たちのチームは強くなるでしょう）\\n\\n■ どちらでもよい場合\\nHe will be twelve next year. ／ He is going to be twelve next year.\\n決まりきった未来のことは、どちらを使っても大きな差はない。実際の会話では区別があいまいなことも多い。\\n\\n■ 入試での問われ方\\n①会話文で、直前のセリフを受けて答える場面 → will（その場の決断）\\n②「もう切符を買った」「準備をしている」などの記述がある → be going to\\n③「あの雲を見て」「顔色が悪い」など目の前の証拠がある → be going to\\n④ I think 〜 / probably といっしょ → will\\n\\n■ 意志を表す will の否定\\nI won't do it again.（二度としません）\\nwon't には「どうしても〜しない」という強い拒否の意味が出ることがある。\\nThis door won't open.（このドアはどうしても開かない）\\n\\n⚠ 注意：日本語の「〜するつもりです」はどちらにもなる。「つもり」という語だけで be going to と決めつけず、いつ決めたのかを場面から読み取る。\"}],\"trapExamples\":[{\"question\":\"次の会話の（　）に入る英文を選びなさい。A: The phone is ringing.　B: （　）\",\"wrongAnswer\":\"I'm going to answer it.\",\"trapExplanation\":\"「これから電話に出る＝未来のこと」とだけ考え、be going to を選んでしまう。be going to が「前から決めていた」という意味を持つことに気づいていない。\",\"correctAnswer\":\"I'll answer it.\",\"correctExplanation\":\"電話が鳴るのを聞いて、その瞬間に「私が出よう」と決めたのだから will を使う。I'm going to answer it. だと「前から電話に出るつもりだった」という不自然な意味になる。会話文では直前のセリフを受けた決断かどうかを見る。\"},{\"question\":\"次の日本語を英語にしなさい。「私は今年の夏、北海道を訪れるつもりです。切符はもう買いました。」（前半のみ英語にする）\",\"wrongAnswer\":\"I will visit Hokkaido this summer.\",\"trapExplanation\":\"「〜するつもりです」という日本語を見て、未来だから will と決めてしまう。「切符はもう買った」という、前から決めていた証拠を読み落としている。\",\"correctAnswer\":\"I'm going to visit Hokkaido this summer.\",\"correctExplanation\":\"切符を買っているということは、話す前からその予定が決まっていたということなので be going to を使う。will はその場で決めたことに使う言い方。日本語の「つもり」だけで判断せず、いつ決めたかを場面から読み取る。\"}]}",
"{\"id\":\"eigo_s141\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来⑤：現在進行形・現在形で表す未来\",\"description\":\"進行形や現在形が未来を表す場合と、時・条件を表す文の中の時制を整理する\",\"intro\":\"「明日雨が降ったら」を If it will rain tomorrow, と書くと誤りです。if や when のあとでは、未来のことでも現在形を使います。理由は説明しにくいのですが、入試では最頻出のひっかけです。\",\"order\":641,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"現在進行形は「約束ずみの近い予定」を表せる（I'm meeting Ken at three tomorrow.）。\",\"時刻表・行事のように決まっている予定は現在形（The train leaves at 6:30.）。\",\"if・when・before・after・until・as soon as のあとでは、未来のことも現在形で表す。\",\"× If it will rain tomorrow → ○ If it rains tomorrow が最頻出のひっかけ。\",\"文の中心の動詞のほうは will のままでよい（If it rains, I will stay home.）。\"],\"sections\":[{\"heading\":\"未来を表す四つの言い方\",\"body\":\"未来のことは will と be going to のほかに、現在進行形や現在形でも表せる。どれくらい前から決まっているか、どれくらい確定しているかで使い分ける。\\n\\n■ 現在形（時刻表・行事など、決まりきった予定）\\nThe train leaves at 6:30 tomorrow morning.（その電車は明朝6時30分に出ます）\\nSchool starts on April 8.（学校は4月8日に始まります）\\nThe concert begins at seven.（コンサートは7時に始まります）\\n個人の意志では動かせない、決まった予定に使う。\\n\\n■ 現在進行形（すでに約束・予約がすんでいる近い予定）\\nI'm meeting Ken at three tomorrow.（明日3時にケンに会うことになっています）\\nWe're having a party this Saturday.（今週の土曜日にパーティーをします）\\nすでに相手と約束したり、場所を予約したりして、動かしにくくなっている予定を表す。\\n\\n■ be going to（前から決めている予定）\\nI'm going to buy a new bike next month.\\n\\n■ will（今決めたこと・今の予測）\\nI'll help you.　It will be sunny tomorrow.\\n\\n★ ポイント：左（現在形）へ行くほど「動かせない」、右（will）へ行くほど「その場の判断」になる。\",\"figureId\":\"lf_eigoext04_141\"},{\"heading\":\"時・条件を表す文の中では現在形\",\"body\":\"英語には、未来のことでも will を使わない大切な決まりがある。\\n\\n■ 決まり\\nif（もし〜なら）・when（〜するとき）・before（〜する前に）・after（〜したあとで）・until（〜するまで）・as soon as（〜するとすぐに）などが導くまとまりの中では、未来のことでも現在形を使う。\\n\\n例）If it rains tomorrow, I will stay home.\\n　（もし明日雨が降ったら、家にいます）\\n　× If it will rain tomorrow, ...\\n例）When he comes back, I will tell him.\\n　（彼がもどってきたら、彼に伝えます）\\n　× When he will come back, ...\\n例）I will call you as soon as I arrive at the station.\\n　（駅に着いたらすぐに電話します）\\n　× as soon as I will arrive ...\\n例）Let's wait here until the rain stops.\\n　（雨がやむまでここで待ちましょう）\\n\\n■ 文の中心のほうは will でよい\\nIf it rains tomorrow, I will stay home.\\n前半（if のまとまり）は現在形、後半（文の中心）は will。両方を現在形にする必要はない。\\n\\n■ 覚え方\\n「if・when のあとは will を使わない」と一言で覚えてしまう。これは中学入試でも高校入試でも必ず出る決まりである。\\n\\n⚠ 注意：when には「いつ〜か」という疑問の意味もあり、その場合は will を使える。I don't know when he will come.（彼がいつ来るか分からない）。ただし中学受験ではまず「時・条件のまとまりでは現在形」を確実にしておけばよい。\"},{\"heading\":\"なぜ if・when のあとは will を使わないのか、なぜ進行形が予定を表すのか\",\"mangaId\":\"eigo_s141_manga\",\"body\":\"If it rains tomorrow, I will stay home. で if のあとに will を使わないのは、if のまとまりが「雨が降る」という**条件をただ置いているだけ**で、未来を予測しているわけではないからです。予測や意志を表す will は文の中心（I will stay home）に一度あれば足り、条件の側にまで付けると意味が重なります。when・before・after・until・as soon as も同じで、時や条件のまとまりの中では現在形にします。理屈は複雑なので、「if・when のあとは will を使わない」と一言で覚えて、必ず出るひっかけとして対処します。\\n\\n現在進行形が予定を表せるのは、約束や予約がすんで**すでに動き出している**予定だからです。I'm meeting Ken at three tomorrow. は、今もその約束が進行中というとらえ方です。時刻表や行事のように個人では動かせない予定は現在形（The train leaves at 6:30.）で、動かせない順に 現在形→進行形→be going to→will と並びます。\\n\\n■ 確かめのしかた\\n①if・when・before・after・until・as soon as を見つけたら、**そのまとまりの動詞が現在形か**。If it will rain→×→If it rains（三単現の s も忘れない）。\\n②文の中心のほうは will のままでよい。両方を現在形にしない。\\n③tomorrow・this Saturday・next week があるのに進行形なら、「〜している最中」ではなく**「〜する予定」**と読む。\\n④予定の確かさで形を選ぶ：時刻表・行事→現在形、約束ずみ→進行形、前から決めていた→be going to、今決めた・予測→will。\\n\\n★ ここがポイント：if・when のまとまりは**条件を置いているだけ**なので will を使わず現在形。進行形は**約束がすんで動き出している予定**を表す。未来を示す語と進行形が一緒なら「予定」と読む。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「もし明日雨が降ったら、私は家にいます。」\",\"wrongAnswer\":\"If it will rain tomorrow, I will stay home.\",\"trapExplanation\":\"「明日のこと＝未来だから will」と考えて、if のまとまりの中まで will を入れてしまう。日本語では「降ったら」と過去のような形になるため、時制のずれにも気づきにくい。\",\"correctAnswer\":\"If it rains tomorrow, I will stay home.\",\"correctExplanation\":\"if・when・before・after・until・as soon as が導くまとまりの中では、未来のことでも現在形を使う。主語 it は三人称単数なので rains となる。文の中心のほうは I will stay home. と will のままでよい。\"},{\"question\":\"次の英文の意味として正しいものを選びなさい。I'm having lunch with my aunt tomorrow.\",\"wrongAnswer\":\"私は明日、おばと昼食を食べている最中だ。\",\"trapExplanation\":\"「現在進行形＝今〜している最中」と一つだけ覚えているため、tomorrow があっても「〜している最中」と訳してしまう。進行形が近い予定を表す使い方を知らない。\",\"correctAnswer\":\"私は明日、おばと昼食を食べる予定だ。\",\"correctExplanation\":\"現在進行形は、すでに約束がすんでいる近い未来の予定を表すことがある。tomorrow・this Saturday・next week など未来を示す語がいっしょにあれば「〜する予定だ」と読む。I'm meeting Ken at three tomorrow. も同じ使い方である。\"}]}",
"{\"id\":\"eigo_s142\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了①：have / has ＋過去分詞のかたち\",\"description\":\"現在完了の形をつかみ、「過去から今までがひとつながり」というイメージを持つ\",\"intro\":\"「彼はもう出かけました」と「彼は出かけました」。日本語ではどちらも過去のようですが、英語では今どうなっているかで形が変わります。have と過去分詞を組み合わせた現在完了は、過去と今をつなぐ形なのです。\",\"order\":642,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"形は「have / has ＋過去分詞」。主語が三人称単数のときだけ has。\",\"現在完了は「過去のある時点から今まで」がつながっていることを表す。\",\"用法は三つ。継続（ずっと〜している）・完了／結果（〜してしまった）・経験（〜したことがある）。\",\"否定は have not（haven't）／has not（hasn't）＋過去分詞。\",\"疑問文は Have / Has を主語の前に出し、答えも have / has でそろえる。\"],\"sections\":[{\"heading\":\"現在完了の形\",\"body\":\"現在完了は「have（has）＋過去分詞」という形で、過去のある時点から今までがひとつながりになっていることを表す。\\n\\n■ 形\\nI have lived in Osaka for five years.（私は5年間、大阪に住んでいます）\\nHe has lived in Osaka for five years.（主語が三人称単数なので has）\\nThey have already finished their homework.（彼らはもう宿題を終えました）\\n\\n主語　　　　　　　助動詞　　過去分詞\\nI / You / We / They　have　　lived\\nHe / She / It　　　　has　　　lived\\n\\n■ 短縮形\\nI have → I've　　you have → you've　　we have → we've　　they have → they've\\nhe has → he's　　she has → she's　　it has → it's\\n※ he's は he is の短縮形でもあるので、あとに過去分詞が来ていれば he has だと判断する。\\n\\n■ 否定文\\nI have not（haven't）seen him.（私は彼に会っていません）\\nShe has not（hasn't）finished her work.\\n\\n■ 疑問文\\nHave you finished your homework?（宿題は終わりましたか）\\n― Yes, I have. / No, I haven't.\\nHas he arrived yet?（彼はもう着きましたか）\\n― Yes, he has. / No, he hasn't.\\n答えるときは have / has を使う。do や did は使わない。\\n\\n★ ポイント：have は「持っている」ではなく、ここでは過去分詞とセットで時制を作る役目をしている。意味を訳そうとせず、形として覚える。\",\"figureId\":\"lf_eigoext04_142\"},{\"heading\":\"三つの用法と、共通するイメージ\",\"body\":\"現在完了には三つの用法があるが、根っこにあるイメージは一つだけである。「過去のある時点から今まで、線がつながっている」ということである。\\n\\n■ ① 継続（ずっと〜している）\\nI have known him for ten years.（私は彼を10年間知っています）\\n過去のある時点で知り合い、その状態が今も続いている。\\n合図の語：for（〜の間）・since（〜以来）・How long（どのくらいの間）\\n\\n■ ② 完了・結果（〜してしまった・〜したところだ）\\nI have just finished my homework.（ちょうど宿題を終えたところです）\\n動作は終わったが、その結果が今に残っている。\\n合図の語：just（ちょうど）・already（もう）・yet（まだ・もう）\\n\\n■ ③ 経験（〜したことがある）\\nI have visited Kyoto three times.（私は京都を3回訪れたことがあります）\\n生まれてから今までの間に、その経験がある。\\n合図の語：ever（今までに）・never（一度も〜ない）・before（以前に）・once / twice / 〜 times（回数）\\n\\n■ 用法の見分け方\\n文中の合図の語を見れば、たいていどの用法か決まる。for / since があれば継続、just / already / yet があれば完了・結果、ever / never / 回数があれば経験である。\\n\\n⚠ 注意：be動詞の過去分詞は been である。I have been busy since yesterday.（昨日からずっといそがしい）。× I have be busy は誤り。be － was/were － been をしっかり覚えておく。\",\"mangaId\":\"eigo_s142_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「彼は3年間、大阪に住んでいます。」\",\"wrongAnswer\":\"He have lived in Osaka for three years.\",\"trapExplanation\":\"現在完了の形を「have＋過去分詞」と一つだけ覚えているため、主語が三人称単数でも have のままにしてしまう。have が動詞と同じように主語で形を変えることを意識していない。\",\"correctAnswer\":\"He has lived in Osaka for three years.\",\"correctExplanation\":\"主語 He は三人称単数なので has を使う。現在完了の have / has は、現在形の have / has と同じ使い分けをする。I have、You have、He has、She has、They have と、主語を見てから決める習慣をつける。\"},{\"question\":\"次の日本語を英語にしなさい。「私は昨日からずっといそがしい。」\",\"wrongAnswer\":\"I have be busy since yesterday.\",\"trapExplanation\":\"「have のあとは原形」と、will のあとの決まりと混同してしまう。また be動詞の過去分詞が been であることを覚えていないと、原形の be を置くしかなくなる。\",\"correctAnswer\":\"I have been busy since yesterday.\",\"correctExplanation\":\"have のあとに来るのは原形ではなく過去分詞なので、be の過去分詞 been を使う。be － was / were － been と3変化で覚えておく。原形が来るのは will・can・did のあとで、have のあとは必ず過去分詞である。\"}]}",
"{\"id\":\"eigo_s143\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了②：継続用法（ずっと〜している）\",\"description\":\"過去に始まった状態が今も続いていることを表す使い方を身につける\",\"intro\":\"「私は大阪に3年住んでいます」を I live in Osaka for three years. と書きたくなります。でも3年前から今までという幅があるので、英語では I have lived in Osaka for three years. とします。\",\"order\":643,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"継続＝「過去のある時点に始まって、今も続いている」。日本語は「ずっと〜している」。\",\"合図は for（〜の間）・since（〜以来）・How long（どのくらいの間）。\",\"日本語が現在の形（「知っています」「住んでいます」）でも、期間があれば現在完了。\",\"live・know・be・want・study のような状態を表す語と相性がよい。\",\"動作の継続は「have been ＋~ing」（現在完了進行形）にする。\"],\"sections\":[{\"heading\":\"継続用法の考え方\",\"body\":\"継続用法は「過去のある時点に始まって、今もその状態が続いている」ことを表す。\\n\\n例）I have known him for ten years.（私は彼を10年間知っています）\\n10年前に知り合って、今も知っている。\\n\\n例）She has lived in Tokyo since 2020.（彼女は2020年からずっと東京に住んでいます）\\n2020年に住み始めて、今も住んでいる。\\n\\n例）We have been friends for a long time.（私たちは長い間ずっと友だちです）\\n例）It has been cold since last week.（先週からずっと寒い）\\n\\n■ 日本語にまどわされない\\n日本語では「知っています」「住んでいます」と現在の形になるので、つい I know him for ten years. と現在形で書いてしまう。しかし現在形は「今のこと」しか表さないので、「10年間」という期間をそえることができない。期間が出てきたら現在完了、と覚える。\\n\\n■ 過去形ともちがう\\nHe lived in Tokyo for ten years.（彼は10年間、東京に住んでいた）← 今はもう住んでいない\\nHe has lived in Tokyo for ten years.（彼は10年間、東京に住んでいる）← 今も住んでいる\\n同じ「10年間」でも、今とつながっているかどうかで形が変わる。\\n\\n★ ポイント：「今も続いているか」を確かめる。続いていれば現在完了、終わっていれば過去形。\",\"figureId\":\"xf_eigo_s143\"},{\"heading\":\"状態の継続と動作の継続\",\"body\":\"■ 状態の継続 ― ふつうの現在完了\\nlive（住んでいる）・know（知っている）・be（〜である）・want（ほしい）・have（持っている）のような状態を表す語は、have＋過去分詞のままで継続を表せる。\\nI have wanted this book for a long time.（この本をずっとほしいと思っていました）\\nHe has been sick since Monday.（彼は月曜日からずっと病気です）\\n\\n■ 動作の継続 ― 現在完了進行形（have been ＋~ing）\\nrun（走る）・study（勉強する）・rain（雨が降る）・wait（待つ）のような動作を表す語は、「have been ＋~ing」の形にすると「ずっと〜し続けている」がはっきり表せる。\\nIt has been raining since this morning.（今朝からずっと雨が降っています）\\nHe has been running for two hours.（彼は2時間ずっと走っています）\\nI have been waiting for you for an hour.（1時間ずっとあなたを待っています）\\n\\n■ 使い分けの目安\\n状態を表す語　→　have＋過去分詞（I have known him for ten years.）\\n動作を表す語　→　have been ＋~ing（I have been studying for three hours.）\\nただし study・work・live などは、どちらの形でも継続を表せることが多い。\\n\\n⚠ 注意：know・like・be などの状態動詞は、進行形にできないという決まりがあるので、× I have been knowing him とは言えない。進行形にできない動詞は、現在完了進行形にもできない。ここは s135 で学んだ状態動詞の決まりがそのまま生きる。\",\"mangaId\":\"eigo_s143_xm\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は5年間、彼を知っています。」\",\"wrongAnswer\":\"I know him for five years.\",\"trapExplanation\":\"日本語が「知っています」と現在の形で終わっているので、そのまま現在形にしてしまう。「5年間」という期間が、今とはつながらない現在形とは合わないことに気づいていない。\",\"correctAnswer\":\"I have known him for five years.\",\"correctExplanation\":\"「5年前から今まで知っている」という継続なので現在完了にする。know の過去分詞は known。for 〜（〜の間）や since 〜（〜以来）といった期間を表す語が出てきたら、現在形ではなく現在完了を使う。\"},{\"question\":\"次の日本語を英語にしなさい。「彼は2時間ずっと走っています。」\",\"wrongAnswer\":\"He has run for two hours.\",\"trapExplanation\":\"「継続は have＋過去分詞」とだけ覚えているため、動作を表す動詞にもそのまま当てはめてしまう。He has run 〜 は「走ったことがある」という経験の意味に読まれやすい。\",\"correctAnswer\":\"He has been running for two hours.\",\"correctExplanation\":\"run のような動作を表す動詞で「ずっと〜し続けている」と言うときは、have been ＋~ing（現在完了進行形）にする。It has been raining since this morning. も同じ形。状態を表す know・live などは have＋過去分詞のままでよい。\"}]}",
"{\"id\":\"eigo_s144\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了③：for と since の使い分け\",\"description\":\"「幅」を表す for と「起点」を表す since を確実に区別する\",\"intro\":\"「3年間」は for three years、「2020年から」は since 2020。for のうしろには長さ、since のうしろには始まった時点が来ます。「3年前から」を since three years と書くのは、よくある誤りです。\",\"order\":644,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"for＋期間の長さ（for three years, for a week, for a long time）。\",\"since＋起点（since 2020, since last week, since I was a child）。\",\"since のあとには文（主語＋動詞の過去形）を置くこともできる。\",\"「3年前から」は for three years または since three years ago（× since three years）。\",\"for のあとに「いつ」を表す語、since のあとに「長さ」を表す語は置かない。\"],\"sections\":[{\"heading\":\"for は長さ、since は起点\",\"mangaId\":\"eigo_s144_manga\",\"body\":\"継続用法でいちばん問われるのが for と since の使い分けである。指しているものがまったくちがう。\\n\\n■ for ＋「どれくらいの長さか」\\nfor three years（3年間）・for a week（1週間）・for two hours（2時間）\\nfor a long time（長い間）・for many years（何年も）\\nI have studied English for five years.（私は5年間、英語を勉強しています）\\n\\n■ since ＋「いつからか」\\nsince 2021（2021年から）・since last week（先週から）・since this morning（今朝から）\\nsince April（4月から）・since I was a child（子どものころから）\\nI have studied English since 2021.（私は2021年から英語を勉強しています）\\n\\n■ 同じ内容を二通りで言える\\nI have lived here for five years.\\n＝ I have lived here since 2021.（今が2026年だとして）\\n同じ帯を、「長さ」で言うか「始まり」で言うかのちがいである。\\n\\n★ ポイント：for のあとには数えられる長さ、since のあとには時計やカレンダーで指せる一点が来る。「◯年間」なら for、「◯年から」なら since。\",\"figureId\":\"lf_eigoext04_144\"},{\"heading\":\"since のあとに文が来る形と、「〜前から」\",\"body\":\"■ since のあとに文を置く\\nsince は前置詞としてだけでなく、あとに「主語＋動詞」を続けることもできる。そのときの動詞は過去形にする。\\nI have known her since I was a child.（子どものころから彼女を知っています）\\nHe has been busy since he came to Japan.（日本に来てからずっといそがしい）\\nIt has been raining since I got up.（起きてからずっと雨が降っています）\\n「〜して以来」という起点を、文で表しているのである。\\n\\n■ 「〜前から」の言い方\\n日本語の「3年前から」を since three years と書くのは誤り。three years は「長さ」であって「いつ」ではないからである。次の二通りで表す。\\n○ for three years（3年間）\\n○ since three years ago（3年前から）\\nago を付ければ「3年前」という一点になるので since が使える。\\n\\n■ How long で尋ねる\\nHow long have you lived here?（どのくらいここに住んでいますか）\\n― For ten years.（10年間です）／ Since 2015.（2015年からです）\\n答えは for でも since でもよい。\\n\\n⚠ 注意：for が不要な場合もある。all day（一日中）・all my life（生まれてからずっと）・these days のような語には for を付けない。\\n○ I have been busy all day.（一日中いそがしい）\\n× I have been busy for all day.\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は3年前からこの町に住んでいます。」\",\"wrongAnswer\":\"I have lived in this town since three years.\",\"trapExplanation\":\"日本語の「3年前から」の「から」を見て since を選び、「3年」をそのまま置いてしまう。since のあとには「長さ」ではなく「いつ」が来る、という区別ができていない。\",\"correctAnswer\":\"I have lived in this town for three years.（または since three years ago）\",\"correctExplanation\":\"three years は長さなので for を使う。どうしても「〜前から」と言いたければ ago を付けて since three years ago とする。「◯年間」なら for、「◯年から・◯月から」なら since、と日本語の形で見分ける。\"},{\"question\":\"次の日本語を英語にしなさい。「私は子どものころから彼を知っています。」\",\"wrongAnswer\":\"I have known him for I was a child.\",\"trapExplanation\":\"for と since のどちらを使うか迷ったすえ、よく見る for を選んでしまう。since のあとには「主語＋動詞」の文を置けることを知らないと、この形は作れない。\",\"correctAnswer\":\"I have known him since I was a child.\",\"correctExplanation\":\"「子どものころ」は起点にあたるので since を使い、そのあとに I was a child という文を続ける。since のあとの動詞は過去形にする。for のあとに文を置くことはできないので、この形を見たら since と決まる。\"}]}",
"{\"id\":\"eigo_s145\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了④：継続の疑問文と答え方\",\"description\":\"How long 〜? をはじめとする継続の疑問文を、正しい語順と答え方で使う\",\"intro\":\"「どのくらい日本にいますか」は How long have you been in Japan? とたずねます。答えは Yes・No ではなく For 〜. や Since 〜.。ところが When でたずねると、なぜか過去形の文になります。\",\"order\":645,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"期間を尋ねるのは How long have / has ＋主語＋過去分詞 …?\",\"答えは For 〜. または Since 〜. で、Yes / No では答えない。\",\"Have you 〜 for / since …? のように Yes / No で答える疑問文もある。\",\"否定文は haven't / hasn't ＋過去分詞（I haven't seen him for a week.）。\",\"How long ではなく When で尋ねると過去形の文になる（When did you come to Japan?）。\"],\"sections\":[{\"heading\":\"How long で期間を尋ねる\",\"body\":\"継続用法で「どのくらいの間」を尋ねるときは How long を使う。\\n\\n■ 語順\\nHow long ＋ have / has ＋ 主語 ＋ 過去分詞 … ?\\n\\nHow long have you lived in this town?（どのくらいこの町に住んでいますか）\\n― For five years.（5年間です）／ Since 2020.（2020年からです）\\nHow long has she been sick?（彼女はどのくらい病気なのですか）\\n― Since last Monday.（先週の月曜からです）\\nHow long have you been studying English?（どのくらい英語を勉強していますか）\\n― For three years.\\n\\n■ 答え方\\nFor 〜.（期間の長さ）または Since 〜.（起点）で答える。\\n文にして答えるなら I have lived here for five years. のようにくり返してもよい。\\n× How long have you lived here? ― Yes, I have.\\nHow long は「どのくらい」を尋ねているので、Yes / No では答えられない。\\n\\n■ Yes / No で答える疑問文\\nHave you lived here for a long time?（長い間ここに住んでいるのですか）\\n― Yes, I have. / No, I haven't.\\nHas he been in the hospital since last week?\\n― Yes, he has.\\n疑問詞がなければ Yes / No で答える。ここは形で判断する。\\n\\n★ ポイント：疑問詞のある文は Yes / No で答えない。これは現在完了にかぎらず、英語全体の原則である。\",\"figureId\":\"xf_eigo_s145\",\"mangaId\":\"eigo_s145_xm\"},{\"heading\":\"否定文と、When との使い分け\",\"body\":\"■ 継続の否定文\\nI haven't seen him for a week.（1週間、彼に会っていません）\\nShe hasn't written to me since last year.（彼女は昨年から手紙をくれていません）\\nIt hasn't rained for a month.（1か月、雨が降っていません）\\n「ずっと〜していない」という意味になり、これも継続用法である。\\n\\n■ 言いかえの形\\nI haven't seen him for a week.\\n＝ It has been a week since I last saw him.（彼に最後に会ってから1週間になります）\\n少し難しいが、上位校ではこの言いかえも問われる。\\n\\n■ When で尋ねると過去形になる\\nHow long have you lived in Japan?（どのくらい日本に住んでいますか）← 現在完了\\nWhen did you come to Japan?（いつ日本に来たのですか）← 過去形\\nWhen は「いつ」という過去の一点を尋ねる語なので、現在完了とはいっしょに使えない。\\n× When have you come to Japan?\\nこれは入試で非常によく問われるので、How long は現在完了、When は過去形、とセットで覚える。\\n\\n⚠ 注意：答え方の対応も確認しておく。\\nHow long 〜? → For 〜. / Since 〜.\\nWhen 〜? → Three years ago. / In 2020. / Last week.\\nどちらも「時」に関する質問だが、答えの形がちがう。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「あなたはどのくらいの間、英語を勉強していますか。」\",\"wrongAnswer\":\"How long do you study English?\",\"trapExplanation\":\"「勉強していますか」という日本語が現在の形なので、現在形の疑問文にしてしまう。「どのくらいの間」という期間が、今だけを指す現在形とは合わないことに気づいていない。\",\"correctAnswer\":\"How long have you studied English?（または How long have you been studying English?）\",\"correctExplanation\":\"過去から今まで続いている期間を尋ねるので現在完了にする。How long＋have／has＋主語＋過去分詞、の語順を固めて覚える。答えは For three years. / Since 2021. のように for か since で返す。\"},{\"question\":\"次の問いへの正しい答えを選びなさい。How long have you known her? ― （Yes, I have. / For ten years.）\",\"wrongAnswer\":\"Yes, I have.\",\"trapExplanation\":\"文が have で始まっているように見えるため、Yes / No で答える疑問文だと思ってしまう。文頭の How long という疑問詞を読み飛ばしていることが原因である。\",\"correctAnswer\":\"For ten years.\",\"correctExplanation\":\"How long は「どのくらいの間」を尋ねる疑問詞なので、For 〜. または Since 〜. で答える。疑問詞がある疑問文は Yes / No では答えない。Have you known her for a long time? なら Yes, I have. でよい。\"}]}",
"{\"id\":\"eigo_s146\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑤：完了・結果（もう〜してしまった）\",\"description\":\"動作は終わったが、その結果が今に残っていることを表す使い方をつかむ\",\"intro\":\"「宿題はもう終わった」は、単なる過去の報告ではありません。だから今は遊べる、という今の状態まで含んでいます。英語ではこれを have finished と表します。just・already・yet が合図になります。\",\"order\":646,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"完了・結果＝「動作は終わったが、その結果が今に残っている」。\",\"合図は just（ちょうど）・already（もう）・yet（まだ・もう）。\",\"already はふつう肯定文、yet は否定文・疑問文で使う。\",\"日本語では「〜したところだ」「もう〜してしまった」となる。\",\"現在完了は「〜したことがある」だけではない。用法を合図の語で見分ける。\"],\"sections\":[{\"heading\":\"完了・結果とは\",\"body\":\"完了・結果の用法は、「その動作は少し前に終わったが、終わった結果が今に残っている」ことを表す。\\n\\n例）I have just finished my homework.（ちょうど宿題を終えたところです）\\n　宿題を終えたのは少し前。その結果、今は宿題が残っていない。\\n例）The train has already left.（電車はもう出てしまいました）\\n　出発したのは少し前。その結果、今ホームに電車はいない。\\n例）She has washed the dishes.（彼女は皿を洗ってしまいました）\\n　その結果、今は皿がきれいになっている。\\n\\n■ 過去形とのちがい\\nI finished my homework.（宿題を終えた）… 終えたという事実だけ\\nI have just finished my homework.（ちょうど終えたところだ）… 今その結果がある\\n過去形は過去の一点を述べるだけで、今どうなっているかには触れない。現在完了は今の状態まで含めて述べる。\\n\\n■ 合図の語\\njust（ちょうど・たった今）：I have just arrived.（たった今着いたところです）\\nalready（もう・すでに）：He has already read the book.（彼はもうその本を読んでしまいました）\\nyet（否定文で「まだ」、疑問文で「もう」）：I haven't finished it yet. / Have you finished it yet?\\n\\n★ ポイント：完了・結果は「帯がとても短く、右はしが今にぴったりくっついている」イメージ。だから今の状態を語れる。\",\"figureId\":\"lf_eigoext04_146\"},{\"heading\":\"用法の見分けと、三つの用法の関係\",\"body\":\"現在完了は形が同じなので、どの用法かは合図の語と文の内容で見分ける。\\n\\n■ 合図の語による見分け\\nfor / since / How long　→　継続（ずっと〜している）\\njust / already / yet　　→　完了・結果（〜したところだ）\\never / never / before / 回数　→　経験（〜したことがある）\\n\\n■ 合図の語がない場合は内容で判断する\\nI have washed my hands.（手を洗いました＝今きれいだ）… 完了・結果\\nI have washed this car three times.（この車を3回洗ったことがある）… 経験（回数がある）\\nI have lived here since 2020.（2020年から住んでいる）… 継続（since がある）\\n\\n■ 三つの用法に共通するもの\\nどの用法でも「今とつながっている」ことは共通している。\\n継続 → 今も続いている\\n完了・結果 → 今その結果が残っている\\n経験 → 今その経験を持っている\\nつまり現在完了は、いつでも「今どうであるか」を語る形なのである。\\n\\n⚠ 注意：「現在完了＝〜したことがある」と一つだけ覚えていると、I have washed the car. を「洗ったことがある」と読んでしまう。合図の語がない文では、前後の文脈からどの用法かを決める。会話文なら直前のセリフが大きな手がかりになる。\",\"mangaId\":\"eigo_s146_xm\"}],\"trapExamples\":[{\"question\":\"次の英文の意味として、この場面に合うものを選びなさい。（父に「車がきれいだね」と言われて）I have washed the car.\",\"wrongAnswer\":\"私はその車を洗ったことがあります。\",\"trapExplanation\":\"「現在完了＝〜したことがある」と一つの訳だけを覚えているため、経験の意味で読んでしまう。合図の語がないときは文脈で判断する、という手順が身についていない。\",\"correctAnswer\":\"私はその車を洗ってしまいました（だから今きれいなのです）。\",\"correctExplanation\":\"「車がきれいだ」という今の状態が話題なので、これは完了・結果の用法である。洗い終えた結果が今に残っていることを表す。経験なら I have washed this car three times. のように回数や before などがそえられることが多い。\"},{\"question\":\"次の日本語を英語にしなさい。「彼女はもうその手紙を書いてしまいましたか。」\",\"wrongAnswer\":\"Has she written the letter already?\",\"trapExplanation\":\"日本語の「もう」をそのまま already に置きかえてしまう。already は主に肯定文で使い、疑問文では yet を使う、という使い分けを知らないために起こる。\",\"correctAnswer\":\"Has she written the letter yet?\",\"correctExplanation\":\"疑問文で「もう〜しましたか」と尋ねるときは文末に yet を置く。already を疑問文で使うと「もう（そんなに早く）〜したの？」という驚きの意味になる。肯定文なら She has already written the letter. でよい。\"}]}",
"{\"id\":\"eigo_s147\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑥：just と already の位置\",\"description\":\"just・already を置く位置と、just now との使い分けを覚える\",\"intro\":\"I have just arrived. の just は、have と過去分詞のあいだに入ります。ところがよく似た just now は現在完了では使えず、過去形とセットです。1語ちがうだけで形が変わるので、位置ごと覚えます。\",\"order\":647,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"just・already は have / has と過去分詞の間に置く。\",\"例）I have just arrived. / He has already finished it.\",\"just now（たった今）は過去形といっしょに使う（He left just now.）。\",\"already は肯定文で「もう」、疑問文では驚きを表す。\",\"文末に置く yet とは位置がちがうので、まとめて整理して覚える。\"],\"sections\":[{\"heading\":\"置く位置は have と過去分詞の間\",\"body\":\"just（ちょうど）と already（もう）は、have / has と過去分詞の間に置く。\\n\\n○ I have just arrived at the station.（たった今、駅に着きました）\\n○ He has already finished his homework.（彼はもう宿題を終えました）\\n○ The bus has just left.（バスはちょうど出たところです）\\n○ She has already gone home.（彼女はもう帰ってしまいました）\\n\\n× I have arrived just at the station.\\n× He has finished already his homework.\\n位置がずれると不自然になったり、意味が変わったりする。「have ＋ just / already ＋ 過去分詞」というかたまりで覚えてしまうのがよい。\\n\\n■ yet は文末\\nI haven't finished my homework yet.（まだ宿題を終えていません）\\nHave you finished your homework yet?（もう宿題を終えましたか）\\nyet だけは文の最後に置く。位置がちがうので、just / already と分けて覚える。\\n\\n■ 位置のまとめ\\nhave ＋ just ＋ 過去分詞　… 「ちょうど〜したところだ」\\nhave ＋ already ＋ 過去分詞　… 「もう〜してしまった」\\nhave not ＋ 過去分詞 ＋ yet　… 「まだ〜していない」\\nHave ＋ 主語 ＋ 過去分詞 ＋ yet ?　… 「もう〜しましたか」\\n\\n★ ポイント：just と already は「中」、yet は「後ろ」。この三つの位置だけは図で覚えてしまう。\",\"figureId\":\"xf_eigo_s147\"},{\"heading\":\"just と just now のちがい\",\"mangaId\":\"eigo_s147_manga\",\"body\":\"just と just now は形が似ているが、いっしょに使う時制がちがう。\\n\\n■ just ＋ 現在完了\\nHe has just left the office.（彼はちょうど会社を出たところです）\\njust は「ちょうど今しがた」という意味で、現在完了とともに使う。\\n\\n■ just now ＋ 過去形\\nHe left the office just now.（彼はたった今、会社を出ました）\\njust now は「たった今」という過去の一点を指す語なので、過去形といっしょに使う。\\n× He has left the office just now.\\n\\n■ なぜちがうのか\\njust now は yesterday や three days ago と同じ「いつ」を表す語である。現在完了は「いつ」を表す語といっしょに使えないので、just now とは結びつかない。一方 just は「いつ」ではなく「たった今しがた」という近さを表しているだけなので、現在完了と使える。\\n\\n■ そのほかの語の位置\\nnever も have と過去分詞の間に置く。I have never been to Hokkaido.\\never も同じ位置。Have you ever seen a panda?\\nこれらは「頻度や経験の程度」を表す語なので、まとめて「have と過去分詞の間」と覚えてよい。\\n\\n⚠ 注意：already を疑問文で使うと意味が変わる。\\nHave you finished your homework yet?（もう宿題は終わりましたか）… ふつうの質問\\nHave you already finished your homework?（もう終わったの？）… 「そんなに早く？」という驚き\\n入試では、ふつうの質問なら yet、と覚えておけばよい。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私はちょうど駅に着いたところです。」\",\"wrongAnswer\":\"I have arrived just at the station.\",\"trapExplanation\":\"日本語の「ちょうど駅に」という語順につられて、just を場所を表す語句の前に置いてしまう。just が動詞にかかる語であることを意識していない。\",\"correctAnswer\":\"I have just arrived at the station.\",\"correctExplanation\":\"just は have と過去分詞の間に置く。「have ＋ just ＋ 過去分詞」をひとかたまりで覚える。already・never・ever も同じ位置に入る。文末に置くのは yet だけである。\"},{\"question\":\"次の日本語を英語にしなさい。「彼はたった今、出発しました。」\",\"wrongAnswer\":\"He has left just now.\",\"trapExplanation\":\"just と just now を同じ意味の語だと思っているため、現在完了にそのまま just now を付けてしまう。just now が「いつ」を表す過去の語であることに気づいていない。\",\"correctAnswer\":\"He left just now.\",\"correctExplanation\":\"just now は「たった今」という過去の一点を指す語なので、過去形といっしょに使う。現在完了で言いたいなら He has just left. と just だけにする。yesterday や three days ago と同じ仲間だと考えると分かりやすい。\"}]}",
"{\"id\":\"eigo_s148\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑦：yet の二つの意味\",\"description\":\"否定文の「まだ」と疑問文の「もう」を、文の形から読み分ける\",\"intro\":\"同じ yet でも、否定文では「まだ」、疑問文では「もう」と訳が反対になります。Have you washed the dishes yet? は「もう皿を洗いましたか」。訳から考えると混乱するので、文の形を先に見るのがこつです。\",\"order\":648,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"yet は文末に置く。否定文では「まだ（〜していない）」、疑問文では「もう（〜しましたか）」。\",\"否定文：I haven't washed the dishes yet.（まだ皿を洗っていません）\",\"疑問文：Have you washed the dishes yet?（もう皿を洗いましたか）\",\"同じ yet でも訳が反対になるので、文の形を先に見る。\",\"still（まだ〜している）とは意味も位置もちがう。\"],\"sections\":[{\"heading\":\"否定文の yet と疑問文の yet\",\"mangaId\":\"eigo_s148_manga\",\"body\":\"yet は文末に置く語で、否定文と疑問文で意味が変わる。\\n\\n■ 否定文の yet ＝「まだ〜していない」\\nI haven't finished my homework yet.（私はまだ宿題を終えていません）\\nShe hasn't come home yet.（彼女はまだ帰ってきていません）\\nThe store hasn't opened yet.（その店はまだ開いていません）\\n\\n■ 疑問文の yet ＝「もう〜しましたか」\\nHave you finished your homework yet?（もう宿題を終えましたか）\\n― Yes, I have.（はい、終えました）／ No, not yet.（いいえ、まだです）\\nHas the bus come yet?（バスはもう来ましたか）\\n\\n■ 答え方\\nNo, not yet. は「いいえ、まだです」という決まった言い方で、会話文の空所補充でよく出る。\\nYes, I have already finished it. のように already で答えることもできる。\\n\\n■ 訳が反対になる理由\\nyet はもともと「今の時点で」という意味を持つ語である。それが否定文では「今の時点でまだ〜ない」、疑問文では「今の時点でもう〜したか」となる。日本語の訳が反対に見えるだけで、はたらきは同じである。\\n\\n★ ポイント：yet を見たら、まず「否定文か疑問文か」を確かめる。それだけで訳が決まる。\",\"figureId\":\"xf_eigo_s148\"},{\"heading\":\"still・already との区別\",\"body\":\"■ still（まだ〜している）\\nHe is still sleeping.（彼はまだねむっています）\\nI still remember her name.（私はまだ彼女の名前を覚えています）\\nstill は「以前からの状態が今も続いている」ことを表し、be動詞や一般動詞の前に置く。文末には置かない。\\n\\n■ 否定文の still（まだ〜していない）\\nHe still hasn't finished his work.（彼はまだ仕事を終えていない）\\nこれは「終わっていないことに対するいらだち」を表す少し強い言い方である。ふつうは He hasn't finished his work yet. を使う。\\n\\n■ 三つの語のまとめ\\nalready：もう（すでに）… 肯定文、have と過去分詞の間\\nyet：まだ／もう … 否定文・疑問文、文末\\nstill：まだ（〜し続けている）… 動詞の前\\n\\n例）He has already arrived.（彼はもう着きました）\\n例）He hasn't arrived yet.（彼はまだ着いていません）\\n例）He is still waiting.（彼はまだ待っています）\\n\\n⚠ 注意：yet には「けれども」という別の意味もある（It is small, yet powerful.）。中学受験では現在完了といっしょに使う用法だけを押さえておけば十分である。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私はまだ昼食を食べていません。」\",\"wrongAnswer\":\"I don't eat lunch yet.\",\"trapExplanation\":\"「食べていません」という日本語を現在形の否定文にしてしまう。「まだ〜していない」が、過去から今までの間に一度もしていないという現在完了の意味であることに気づいていない。\",\"correctAnswer\":\"I haven't eaten lunch yet.\",\"correctExplanation\":\"「まだ〜していない」は現在完了の否定文＋yet で表す。eat の過去分詞は eaten。I don't eat lunch. だと「私は（ふだん）昼食を食べない」という習慣の意味になってしまい、場面に合わない。\"},{\"question\":\"次の英文の意味として正しいものを選びなさい。Have you finished your homework yet?\",\"wrongAnswer\":\"あなたはまだ宿題を終えていないのですか。\",\"trapExplanation\":\"yet＝「まだ」と一対一で覚えているため、疑問文でも「まだ」と訳してしまう。文の形によって訳が変わることを知らないと、読解でも意味を取りちがえる。\",\"correctAnswer\":\"あなたはもう宿題を終えましたか。\",\"correctExplanation\":\"疑問文の yet は「もう」という意味になる。「まだ」と訳すのは否定文のとき（I haven't finished it yet.）。yet を見たら、まず否定文か疑問文かを確かめてから訳を決める。答えは Yes, I have. / No, not yet. となる。\"}]}",
"{\"id\":\"eigo_s149\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑧：結果が今に残るということ\",\"description\":\"have lost・have gone など、今の状態まで語る言い方を理解する\",\"intro\":\"I lost my key. は「なくした」だけですが、I have lost my key. は「なくして、今も見つかっていない」まで表します。過去形では今の状況が伝わりません。だから現在完了を選ぶのです。\",\"order\":649,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"I have lost my key.＝なくして、今も見つかっていない。\",\"He has gone to America.＝行ってしまって、今ここにいない。\",\"I have caught a cold.＝風邪をひいて、今も風邪をひいている。\",\"過去形にすると「今どうなっているか」は表せない。\",\"「その結果、今どうなのか」を言いたいときに現在完了を選ぶ。\"],\"sections\":[{\"heading\":\"結果を表す代表的な言い方\",\"body\":\"完了・結果の用法の中でも、「今の状態」がはっきり出る言い方を覚えておく。\\n\\n■ have lost（なくして、今もない）\\nI have lost my watch.（時計をなくしてしまいました＝今も見つかっていない）\\n過去形の I lost my watch yesterday. は「昨日なくした」という事実だけを述べ、今見つかったかどうかには触れない。\\n\\n■ have gone to（行ってしまって、今ここにいない）\\nHe has gone to America.（彼はアメリカへ行ってしまいました＝今ここにいない）\\n「行ったことがある」ではないことに注意する。\\n\\n■ have caught a cold（風邪をひいて、今もひいている）\\nI have caught a cold.（風邪をひいてしまいました＝今も具合が悪い）\\n\\n■ have broken（こわして、今もこわれている）\\nHe has broken the window.（彼が窓をこわしてしまいました＝今も割れたまま）\\n\\n■ have become（〜になって、今もそうである）\\nIt has become warm.（暖かくなりました＝今は暖かい）\\n\\n★ ポイント：どれも「〜してしまった。だから今こうだ」という二段構えの意味を持つ。日本語の「〜してしまった」に近い。\",\"figureId\":\"xf_eigo_s149\"},{\"heading\":\"過去形との差をはっきりさせる\",\"body\":\"同じ内容でも、過去形と現在完了では伝わることがちがう。\\n\\n■ 例1\\nI lost my key yesterday.（昨日かぎをなくした）\\nI have lost my key.（かぎをなくしてしまった）\\n【解法】\\n【何を聞かれているか】同じ「かぎをなくした」でも、過去形と現在完了で伝わることがどうちがうか。\\n【なぜこの考え方か】過去形は「昔あったできごと」を言うだけの形で、今のことには何も触れない。現在完了は have（今持っている）＋過去分詞（なくした結果）の形なので、「その結果を今も持っている」＝今もその状態だ、という意味になる。\\n【ステップ1】過去形 I lost my key yesterday. は、昨日の話だけを言っている。\\n【ステップ2】今どうなっているかは書いていないので、もう見つかっているかもしれない。\\n【ステップ3】現在完了 I have lost my key. は、have が今のことを表すので、なくした結果が今も続いている。\\n【ステップ4】だから「今も見つかっていない。だから今こまっている」と伝わる。\\n【答え】過去形は今の状態が分からない。現在完了は今も見つかっていない。\\n【確かめ】日本語に直して「今も見つかっていないか」を自分に聞く。「見つかっていない」と言えるなら現在完了、言えないなら過去形を選ぶ。\\n【よくあるまちがい】どちらも「なくした」と訳して同じ意味だと思ってしまう。今の状態が伝わるかどうかがちがう。\\n\\n■ 例2\\nHe went to America.（彼はアメリカへ行った）\\nHe has gone to America.（彼はアメリカへ行ってしまった）\\n【解法】\\n【何を聞かれているか】went と has gone で、彼が今どこにいるかの伝わり方はどうちがうか。\\n【なぜこの考え方か】例1と同じで、過去形は昔のできごとだけを言い、現在完了は「行った結果、今どうなのか」まで言うからである。\\n【ステップ1】He went to America. は、行ったという昔の事実だけを言っている。\\n【ステップ2】行ったあとに帰ってきたかどうかは書いていないので、今もどっているかどうかは分からない。\\n【ステップ3】He has gone to America. は、行った結果を今も持っている形なので、行ったきりで今も向こうにいる。\\n【ステップ4】だから「今ここにいない」と伝わる。\\n【答え】went は今のことが分からない。has gone は今ここにいない。\\n【確かめ】has gone のあとに「でも今ここにいるよ」とつなげると、意味が合わなくなる。合わなくなるのは、今いないという意味をもっているからである。\\n【よくあるまちがい】has gone を「行ったことがある」と読んでしまう。「行ったことがある」なら今ここにいることもあり、has been to を使う。\\n\\n■ 例3\\nShe lost her wallet, but she found it later.（財布をなくしたが、あとで見つけた）\\n【解法】\\n【何を聞かれているか】この文を現在完了にしてよいか、過去形にすべきか。\\n【なぜこの考え方か】現在完了は「結果が今も続いている」ときの形だから、結果が今は消えているなら使えない。\\n【ステップ1】文の後半に「あとで見つけた」とあるので、今は財布がある。\\n【ステップ2】現在完了 has lost にすると「今も財布がない」という意味になり、後半の「見つけた」と食いちがう。\\n【ステップ3】結果がもう続いていないので、過去形 lost を使う。\\n【答え】過去形（She lost her wallet, but she found it later.）。\\n【確かめ】現在完了にした文を日本語に直し、「今もない」と読めるか見る。後半とけんかするなら過去形が正しい。\\n【よくあるまちがい】「なくした」という動詞を見ただけで、すぐ現在完了にしてしまう。あとの文で結果が消えていないかまで読む。\\n\\n■ 会話でのはたらき\\n現在完了は「だから今こまっている」「だから今いない」という、今の事情を相手に伝える形である。だから会話文で理由を説明する場面によく出てくる。\\nA: Why are you looking for something?（何をさがしているの）\\nB: I've lost my glasses.（めがねをなくしてしまって）\\n\\n⚠ 注意：yesterday や last week のような「いつ」を表す語といっしょには使えない。× I have lost my key yesterday. → ○ I lost my key yesterday.（過去形にする）。この決まりは s154 でくわしく学ぶ。\",\"mangaId\":\"eigo_s149_xm\"}],\"trapExamples\":[{\"question\":\"次の英文の意味として正しいものを選びなさい。He has gone to Canada.\",\"wrongAnswer\":\"彼はカナダへ行ったことがあります。\",\"trapExplanation\":\"「現在完了＝〜したことがある」と覚えているため、経験の意味で読んでしまう。go の過去分詞 gone が「行ってしまって今いない」を表すことを知らないと必ず取りちがえる。\",\"correctAnswer\":\"彼はカナダへ行ってしまいました（今ここにいません）。\",\"correctExplanation\":\"have gone to 〜 は「行ってしまって今ここにいない」という結果を表す。「行ったことがある」という経験は have been to 〜 を使い、He has been to Canada. となる。この二つの区別は入試の定番である。\"},{\"question\":\"次の日本語を英語にしなさい。「私はかぎをなくしてしまいました（今も見つかっていません）。」\",\"wrongAnswer\":\"I lost my key.\",\"trapExplanation\":\"「なくした」という過去の出来事に目が行き、過去形で済ませてしまう。かっこ書きの「今も見つかっていない」という条件が、時制の選び方に関わることに気づいていない。\",\"correctAnswer\":\"I have lost my key.\",\"correctExplanation\":\"「今も見つかっていない」という結果まで表したいので現在完了を使う。I lost my key. は「なくした」という過去の事実を述べるだけで、今の状態には触れない。「その結果、今どうなのか」を言いたいときは現在完了を選ぶ。\"}]}",
"{\"id\":\"eigo_s150\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑨：経験用法（〜したことがある）\",\"description\":\"生まれてから今までの間の経験を表す使い方をつかむ\",\"intro\":\"「富士山に登ったことがありますか」は Have you ever climbed Mt. Fuji? とたずねます。「登りましたか」との差は、生まれてから今までのどこかで、という幅があること。回数を数えられるのが特徴です。\",\"order\":650,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"経験＝「今までに〜したことがある」。回数を数えられるのが特徴。\",\"合図は ever（今までに）・never（一度もない）・before（以前に）・once / twice / 〜 times。\",\"never は have と過去分詞の間に置き、not とは重ねない。\",\"疑問文は Have you ever ＋過去分詞 …? で、答えは Yes, I have. / No, I never have. / No, I haven't.\",\"「いつ」を表す語（three years ago など）とはいっしょに使えない。\"],\"sections\":[{\"heading\":\"経験用法の考え方\",\"body\":\"経験用法は「生まれてから今までの間に、その経験があるか」を表す。\\n\\n例）I have visited Kyoto three times.（私は京都を3回訪れたことがあります）\\n例）She has read this book before.（彼女は以前この本を読んだことがあります）\\n例）I have never seen a real panda.（私は本物のパンダを一度も見たことがありません）\\n例）Have you ever climbed Mt. Fuji?（あなたは富士山に登ったことがありますか）\\n\\n■ 「いつ」は問題にしない\\n経験用法では、その経験がいつのことかは問題にしない。だから three years ago や last year のような「いつ」を表す語とはいっしょに使えない。回数（three times）は言えるが、日付は言えないのである。\\n× I have visited Kyoto three years ago.\\n○ I visited Kyoto three years ago.（過去形にする）\\n○ I have visited Kyoto three times.（回数なら現在完了でよい）\\n\\n■ 合図の語\\never（今までに）… 疑問文で使う\\nnever（一度も〜ない）… 否定の意味を持つ\\nbefore（以前に）… 文末に置く\\nonce（1回）・twice（2回）・three times（3回）・many times（何度も）\\n\\n★ ポイント：経験は「生まれてから今まで」という長い帯の中に、点がいくつあるかを数える形。だから回数は言えても、日付は言えない。\",\"figureId\":\"lf_eigoext04_150\",\"mangaId\":\"eigo_s150_xm\"},{\"heading\":\"否定文・疑問文の作り方\",\"body\":\"■ 否定文には never を使う\\nI have never been to Hokkaido.（私は北海道へ行ったことが一度もありません）\\nHe has never eaten natto.（彼は納豆を食べたことが一度もありません）\\nnever は have と過去分詞の間に置く。never 自体が否定の意味を持っているので、not と重ねてはいけない。\\n× I haven't never seen it.\\n○ I have never seen it.\\n\\n■ not を使う否定文もある\\nI have not seen that movie.（その映画を見たことがありません）\\nnever を使うほうが「一度も」という気持ちが強く出る。\\n\\n■ 疑問文には ever を使う\\nHave you ever been to Kyoto?（京都へ行ったことがありますか）\\n― Yes, I have.（はい、あります）\\n― No, I haven't.（いいえ、ありません）\\n― No, I have never been there.（いいえ、一度もありません）\\never は「今までに」という意味で、have と過去分詞の間に置く。\\n\\n■ 回数を尋ねる\\nHow many times have you been to Kyoto?（何回、京都へ行ったことがありますか）\\n― Three times.（3回です）／ Only once.（1回だけです）\\n\\n⚠ 注意：ever は疑問文で使うのが基本で、肯定文では使わない。× I have ever been to Kyoto. は誤り。肯定文なら I have been to Kyoto before. や I have been to Kyoto twice. とする。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私はその映画を一度も見たことがありません。」\",\"wrongAnswer\":\"I haven't never seen that movie.\",\"trapExplanation\":\"「〜ない」という日本語に引かれて否定の形を作り、そこへさらに never を足してしまう。never がそれ自体で否定の意味を持つことを意識していない。\",\"correctAnswer\":\"I have never seen that movie.\",\"correctExplanation\":\"never は「一度も〜ない」という否定の意味をすでに含んでいるので、not と重ねて使わない。have と過去分詞の間に置いて I have never seen 〜 とする。not を使うなら I have not seen that movie. とする。\"},{\"question\":\"次の日本語を英語にしなさい。「あなたは今までにその歌を聞いたことがありますか。」\",\"wrongAnswer\":\"Do you ever hear that song?\",\"trapExplanation\":\"「聞いたことがありますか」を「聞きますか」に近い形でとらえ、現在形の疑問文にしてしまう。「今までに」という経験を表すには現在完了が必要だと気づいていない。\",\"correctAnswer\":\"Have you ever heard that song?\",\"correctExplanation\":\"経験を尋ねるときは Have you ever ＋過去分詞 …? の形にする。hear の過去分詞は heard。答えは Yes, I have. / No, I haven't.。Do you ever hear 〜? だと「ふだん聞くことがありますか」という別の意味になる。\"}]}",
"{\"id\":\"eigo_s151\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑩：ever・never・before と回数の言い方\",\"description\":\"経験用法でよく使う語の位置と、回数の表し方を確実にする\",\"intro\":\"never は have と過去分詞のあいだ、before は文末。置く場所が語ごとに決まっています。また「以前に」は before で、ago は使えません。ago は過去形とセットの語だからです。位置ごと覚えましょう。\",\"order\":651,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"ever・never は have と過去分詞の間、before は文末に置く。\",\"回数は once（1回）・twice（2回）・three times（3回）・many times（何度も）。\",\"「以前に」は before。ago は過去形とセットなので現在完了では使えない。\",\"回数を尋ねるのは How many times have you ＋過去分詞 …?\",\"Have you ever 〜? への答えは Yes, I have. / No, I haven't. / No, never.\"],\"sections\":[{\"heading\":\"語の位置を固める\",\"body\":\"経験用法でよく使う語は、置く場所が決まっている。\\n\\n■ have と過去分詞の間に置く語\\never（今までに）：Have you ever visited Kyoto?\\nnever（一度も〜ない）：I have never visited Kyoto.\\njust（ちょうど）：I have just visited Kyoto.（完了・結果）\\nalready（もう）：I have already visited Kyoto.（完了・結果）\\n\\n■ 文末に置く語\\nbefore（以前に）：I have seen him before.（以前に彼に会ったことがあります）\\nyet（まだ・もう）：I haven't seen him yet.\\n回数を表す語：I have seen him twice.（2回会ったことがあります）\\n\\n■ よくある位置の誤り\\n× I never have read the book.\\n○ I have never read the book.\\nnever を have の前に置くのは誤りである。「have ＋ never ＋ 過去分詞」というかたまりで覚える。\\n\\n★ ポイント：ever・never は「中」、before・yet・回数は「後ろ」。この二つに分けて覚えれば十分である。\"},{\"heading\":\"回数の表し方と、before / ago の区別\",\"body\":\"■ 回数の言い方\\nonce（1回）　twice（2回）　three times（3回）　four times（4回）　many times（何度も）\\n※ 1回・2回だけは once・twice という特別な語を使う。one time・two times とも言えるが、once・twice のほうがふつうである。3回以降は「数＋times」の形になる。\\n\\nI have been to Hokkaido once.（北海道へ1回行ったことがあります）\\nHe has read this book twice.（彼はこの本を2回読んだことがあります）\\nShe has visited America many times.（彼女は何度もアメリカを訪れたことがあります）\\n\\n■ 回数を尋ねる\\nHow many times have you been to Kyoto?（何回、京都へ行ったことがありますか）\\n― Three times. / Only once. / Never.\\nHow often 〜? も使えるが、中学受験では How many times 〜? を覚えておけばよい。\\n\\n■ before と ago の区別\\nbefore（以前に）… 現在完了と使える。今から見ていつのことかは言わない。\\n　I have met him before.（以前に彼に会ったことがあります）\\nago（〜前に）… 過去形と使う。「今から◯だけさかのぼった一点」を指す。\\n　I met him three days ago.（3日前に彼に会いました）\\n　× I have met him three days ago.\\n\\n■ 覚え方\\nago は必ず前に数量が付く（three days ago, a year ago）。before は単独で「以前に」と使える。数量が付いていたら過去形、と考えるとよい。\\n\\n⚠ 注意：before にも「〜する前に」という別の使い方がある（before I go to bed）。現在完了といっしょに文末に置かれていれば「以前に」の意味である。\"},{\"heading\":\"なぜ never は中で before は文末なのか、なぜ ago は使えないのか\",\"mangaId\":\"eigo_s151_manga\",\"body\":\"ever・never・just・already は、**動作の「あり方」を説明する語**で、have と過去分詞のあいだに入って動詞を修飾します。before・yet・回数（twice・three times）は、**文全体に「いつ・何回」という情報を足す語**なので、文の終わりに置きます。「have＋never＋過去分詞」をかたまりで覚えるのは、日本語の「一度も」を先に言いたい気持ちで never を have の前に出す誤りを防ぐためです。\\n\\nago が現在完了と使えないのは、ago が「今から3日さかのぼった**過去の一点**」を指す語だからです。現在完了は「過去から今までの幅」を表すので、一点を指す語（ago・yesterday・last year）とは合いません。before は「以前に」とだけ言って時点を指さないので、現在完了と使えます。ago には必ず数量が付く（three days ago）ので、数量が付いていたら過去形、と判断できます。\\n\\n■ 確かめのしかた\\n①**中に置く語**（ever・never・just・already）と**文末に置く語**（before・yet・once・twice・three times）に分けて言えるか。\\n②I never have read→× → I have never read。「have＋never＋過去分詞」の順か。\\n③「以前に」→before（現在完了）。「〇日前に」→ago（過去形）。× I have met him three days ago。\\n④回数：once（1回）・twice（2回）・three times（3回〜）。たずねるときは How many times have you 〜?、答えは Three times. / Only once. / Never.\\n\\n★ ここがポイント：ever・never は**動作のあり方**なので中に、before・yet・回数は**文全体への情報**なので文末に置く。ago は**過去の一点**を指すので過去形とだけ使い、現在完了には before。\",\"figureId\":\"xf_eigo_s151\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は以前、彼に会ったことがあります。」\",\"wrongAnswer\":\"I have met him ago.\",\"trapExplanation\":\"「以前」という日本語から ago を思いうかべてしまう。ago は「◯日前」のように数量とセットで使い、現在完了とはいっしょに使えないことを知らない。\",\"correctAnswer\":\"I have met him before.\",\"correctExplanation\":\"現在完了で「以前に」と言うときは before を文末に置く。ago は three days ago のように数量が必要で、しかも過去形とセットで使う語である（I met him three days ago.）。ago が出てきたら過去形、と結びつけて覚える。\"},{\"question\":\"次の日本語を英語にしなさい。「私はその本を一度も読んだことがありません。」\",\"wrongAnswer\":\"I never have read the book.\",\"trapExplanation\":\"日本語の「一度も」を先に言いたい気持ちから、never を have の前に出してしまう。「have ＋ never ＋ 過去分詞」という位置が固まっていない。\",\"correctAnswer\":\"I have never read the book.\",\"correctExplanation\":\"never は have と過去分詞の間に置く。ever・just・already も同じ位置に入る。文末に置くのは before・yet・回数を表す語である。位置を二つのグループに分けて覚えると迷わない。\"}]}",
"{\"id\":\"eigo_s152\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了⑪：have been to と have gone to\",\"description\":\"経験の been to、結果の gone to、継続の been in を区別する\",\"intro\":\"He has been to America. は「行ったことがある」、He has gone to America. は「行ってしまって、今ここにいない」。to のあとが同じでも意味は大きくちがいます。しくみが分かれば取りちがえません。\",\"order\":652,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"have been to 〜＝「〜へ行ったことがある」（経験）／「〜へ行ってきたところだ」（完了）。\",\"have gone to 〜＝「〜へ行ってしまった（今ここにいない）」（結果）。\",\"have been in 〜＝「〜にずっといる」（継続）。前置詞が to か in かで意味が変わる。\",\"I have gone to 〜 とは言わない（自分が今ここにいないことになる）。\",\"have been to には「行った経験」、have gone to には「今いない」という結果がある。\"],\"sections\":[{\"heading\":\"三つの形を並べて区別する\",\"mangaId\":\"eigo_s152_manga\",\"body\":\"be動詞の過去分詞 been を使った形は、前置詞と組み合わせで意味が変わる。三つを並べて覚える。\\n\\n■ have been to 〜（経験：〜へ行ったことがある）\\nI have been to Kyoto three times.（京都へ3回行ったことがあります）\\nHave you ever been to America?（アメリカへ行ったことがありますか）\\nその場所を訪れた経験があり、今はもどってきている。\\n\\n■ have been to 〜（完了：〜へ行ってきたところだ）\\nI have just been to the post office.（郵便局へ行ってきたところです）\\njust がそえられると「行ってきた」という完了の意味になる。\\n\\n■ have gone to 〜（結果：〜へ行ってしまった）\\nHe has gone to America.（彼はアメリカへ行ってしまいました＝今ここにいない）\\n行ったきり、今この場にいないことを表す。\\n\\n■ have been in 〜（継続：〜にずっといる）\\nShe has been in Osaka for three years.（彼女は3年間ずっと大阪にいます）\\nin は「その中にいる」という状態を表すので、継続の意味になる。\\n\\n★ ポイント：been to は「行って帰ってきた」、gone to は「行ったきり」、been in は「ずっとそこにいる」。\",\"figureId\":\"xf_eigo_s152\"},{\"heading\":\"まちがえやすい点\",\"body\":\"■ 主語が I や we のときは gone を使わない\\n× I have gone to Kyoto.\\n自分が「行ってしまって今ここにいない」ことになるので、話している本人には使えない。\\n○ I have been to Kyoto.（行ったことがある）\\n\\n■ 三人称でも文脈で決まる\\nHe has been to Kyoto.（彼は京都へ行ったことがある＝今ここにいる）\\nHe has gone to Kyoto.（彼は京都へ行ってしまった＝今ここにいない）\\n同じ「行った」でも、今その人がどこにいるかがちがう。会話文では「だから彼は今いないんだ」といった説明とセットで出る。\\n\\n■ 前置詞を落とさない\\n× I have been Kyoto.\\n○ I have been to Kyoto.\\n「〜へ」という方向を表す to が必要である。\\n\\n■ そのほかの been の使い方\\nI have been busy since yesterday.（昨日からずっといそがしい）… be動詞の継続\\nIt has been three years since he left Japan.（彼が日本を発ってから3年になります）… 時の経過\\n\\n⚠ 注意：have been to 〜 は「行ったことがある」と訳すため経験用法だと思いがちだが、just や already がそえられると「行ってきたところだ」という完了の意味になる。合図の語を見てから訳を決める。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は一度アメリカへ行ったことがあります。」\",\"wrongAnswer\":\"I have gone to America once.\",\"trapExplanation\":\"「行った」という日本語から go を選び、その過去分詞 gone を使ってしまう。gone to が「行ってしまって今ここにいない」を表すことを知らないと、必ずこの形になる。\",\"correctAnswer\":\"I have been to America once.\",\"correctExplanation\":\"「行ったことがある」という経験は have been to 〜 で表す。I have gone to America. と言うと、話している自分が今ここにいないという矛盾した文になる。主語が I や we のときは gone を使わない、と覚えておく。\"},{\"question\":\"次の日本語を英語にしなさい。「彼女は3日間ずっと病院にいます。」\",\"wrongAnswer\":\"She has been to the hospital for three days.\",\"trapExplanation\":\"been という語を見て「been to」の形をそのまま当てはめてしまう。to と in で意味が変わることを意識していないと、「行ったことがある」の形で書いてしまう。\",\"correctAnswer\":\"She has been in the hospital for three days.\",\"correctExplanation\":\"「ずっと〜にいる」という継続は have been in 〜 で表す。been to は「行ったことがある・行ってきた」で、for three days という期間とは合わない。to は方向、in は「その中にいる」状態、と前置詞の意味から考える。\"}]}",
"{\"id\":\"eigo_s153\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了と過去形①：今とつながるか、切れているか\",\"description\":\"同じ出来事でも、今とのつながりの有無で形が変わることを理解する\",\"intro\":\"「京都に行きました」を英語にするとき、I went to Kyoto. と I have been to Kyoto. のどちらを選ぶでしょうか。日本語は同じでも、今とのつながりがあるかどうかで形が変わります。判断のしかたを決めます。\",\"order\":653,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"過去形＝過去の一点で完結し、今とは切れている。\",\"現在完了＝過去から今までつながっていて、今の状態まで語る。\",\"同じ日本語でも、今どうなっているかで形が変わる。\",\"「今も続いている」「今も結果が残っている」「今までの経験」なら現在完了。\",\"英作文では「今どうなのか」を自分に問いかけてから形を決める。\"],\"sections\":[{\"heading\":\"二つの形が指す範囲のちがい\",\"mangaId\":\"eigo_s153_manga\",\"body\":\"過去形と現在完了は、どちらも「過去に起きたこと」を語る。ちがいは、その出来事を今と結びつけるかどうかである。\\n\\n■ 過去形：点で終わる\\nI lost my umbrella yesterday.（昨日、かさをなくしました）\\n昨日という一点での出来事を述べているだけで、今かさがあるかどうかには触れていない。もう見つかっているかもしれない。\\n\\n■ 現在完了：今まで届く\\nI have lost my umbrella.（かさをなくしてしまいました）\\nなくした結果が今まで届いているので、「今も見つかっていない」ことまで表す。\\n\\n■ ほかの例\\nHe went to America.（アメリカへ行った）… 今もどっているかは不明\\nHe has gone to America.（アメリカへ行ってしまった）… 今ここにいない\\n\\nShe lived in Osaka for ten years.（10年間、大阪に住んでいた）… 今は住んでいない\\nShe has lived in Osaka for ten years.（10年間、大阪に住んでいる）… 今も住んでいる\\n\\nI was busy last week.（先週いそがしかった）… 今はどうか分からない\\nI have been busy since last week.（先週からずっといそがしい）… 今もいそがしい\\n\\n★ ポイント：「今どうなのか」まで言いたいときだけ現在完了を使う。言う必要がなければ過去形でよい。\",\"figureId\":\"lf_eigoext04_153\"},{\"heading\":\"日本語からの判断のしかた\",\"body\":\"日本語だけを見ると、どちらの形にすべきか分かりにくい。次の手順で判断する。\\n\\n■ 手順\\n① その出来事は今も続いているか　→　はい：現在完了（継続）\\n② その結果が今も残っているか　→　はい：現在完了（完了・結果）\\n③ 今までの経験として言っているか　→　はい：現在完了（経験）\\n④ 「いつ」を表す語（昨日・先週・3年前）があるか　→　はい：過去形\\n\\n■ 日本語の手がかり\\n現在完了になりやすい表現\\n　「ずっと〜している」「〜してしまった」「〜したことがある」「もう〜した」「まだ〜していない」\\n過去形になりやすい表現\\n　「昨日〜した」「先週〜した」「〜年前に〜した」「そのとき〜した」\\n\\n■ まぎらわしい例\\n「私は3年間、大阪に住んでいました」\\n　→ 今は住んでいないなら過去形：I lived in Osaka for three years.\\n「私は3年間、大阪に住んでいます」\\n　→ 今も住んでいるので現在完了：I have lived in Osaka for three years.\\n日本語の語尾のわずかなちがいが、英語では時制のちがいになる。\\n\\n⚠ 注意：現在完了は「今」に関わる形なので、過去の一点を指す語とはいっしょに使えない。この決まりについては次のまとまりでくわしく確認する。\"}],\"trapExamples\":[{\"question\":\"次の二文のうち、「今もかさが見つかっていない」ことまで表すのはどちらか。ア I lost my umbrella.　イ I have lost my umbrella.\",\"wrongAnswer\":\"ア I lost my umbrella.\",\"trapExplanation\":\"どちらも日本語では「かさをなくした」と訳せるので、同じ意味だと思ってしまう。過去形が今の状態には触れない形であることが理解できていない。\",\"correctAnswer\":\"イ I have lost my umbrella.\",\"correctExplanation\":\"過去形は過去の一点を述べるだけで、今かさがあるかどうかには触れない。現在完了は今まで線がつながっているので、「今も見つかっていない」という結果まで表す。「今どうなのか」を語るのが現在完了である。\"},{\"question\":\"次の日本語を英語にしなさい。「私は3年間ずっとここにいます。」\",\"wrongAnswer\":\"I am here for three years.\",\"trapExplanation\":\"「います」という現在の言い方から、be動詞の現在形を選んでしまう。「3年間」という期間は、今だけを指す現在形とはいっしょに使えないことに気づいていない。\",\"correctAnswer\":\"I have been here for three years.\",\"correctExplanation\":\"過去のある時点から今まで続いているので現在完了にする。be の過去分詞は been。期間を表す for 〜 や since 〜 が出てきたら、現在形ではなく現在完了を使う、と結びつけて覚える。\"}]}",
"{\"id\":\"eigo_s154\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"現在完了と過去形②：いっしょに使えない語\",\"description\":\"yesterday・ago・When 〜? など、現在完了と共存できない語を押さえる\",\"intro\":\"I have finished it yesterday. は誤りです。現在完了は今とつながる形なので、yesterday のように過去の一点を指す語とは同居できません。When でたずねるときも過去形になります。線引きを覚えます。\",\"order\":654,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"現在完了は「過去の一点」を指す語といっしょに使えない。\",\"使えない語：yesterday, last night / week / year, 〜 ago, just now, then, in 2020。\",\"When 〜? で尋ねるときは過去形（× When have you come?　○ When did you come?）。\",\"使える語：for, since, just, already, yet, ever, never, before, 回数, today, this week。\",\"「いつ」を言いたいなら過去形、「今どうか」を言いたいなら現在完了。\"],\"sections\":[{\"heading\":\"いっしょに使えない語\",\"mangaId\":\"eigo_s154_manga\",\"body\":\"現在完了は「過去から今まで」を一本の線でとらえる形である。だから、線の途中の一点だけを指す語とは矛盾してしまい、いっしょに使えない。\\n\\n■ 使えない語\\nyesterday（昨日）・last night / last week / last year（昨夜・先週・昨年）\\nthree days ago（3日前）・a long time ago（ずっと昔）\\njust now（たった今）・then / at that time（そのとき）・in 2020（2020年に）\\nWhen 〜?（いつ〜か）\\n\\n× I have finished the book three days ago.\\n○ I finished the book three days ago.（過去形にする）\\n× He has come to Japan last year.\\n○ He came to Japan last year.\\n\\n■ 使える語\\nfor 〜（〜の間）・since 〜（〜以来）\\njust（ちょうど）・already（もう）・yet（まだ・もう）\\never（今までに）・never（一度も〜ない）・before（以前に）・once / twice / 〜 times\\ntoday（今日）・this week / this month（今週・今月）・recently（最近）\\nこれらは「今を含む範囲」を表すので、現在完了と両立する。\\n\\n★ ポイント：「いつ」を指す語は過去形、「どのくらい・何回・もう／まだ」を表す語は現在完了。語を見た瞬間に時制が決まる。\",\"figureId\":\"xf_eigo_s154\"},{\"heading\":\"When と How long の対応\",\"body\":\"■ 疑問文での使い分け\\nWhen did you come to Japan?（いつ日本に来たのですか）― Three years ago.\\nHow long have you been in Japan?（どのくらい日本にいますか）― For three years.\\n\\nWhen は「過去のいつか」を尋ねる語なので、必ず過去形とセットになる。\\n× When have you come to Japan? は誤りである。「来て今もいる」という気持ちから現在完了にしてしまいがちだが、When がある時点で過去形と決まる。\\n\\n■ 二つの文で書き分ける\\n「私は3年前に日本に来て、今もここにいます」を英語にするときは、二文に分ける。\\nI came to Japan three years ago. And I have been here since then.\\n一文の中に「3年前」と現在完了を同居させることはできない。\\n\\n■ 書きかえの問題\\nHe died three years ago.（彼は3年前に亡くなった）\\n＝ He has been dead for three years.（彼が亡くなって3年になります）\\n＝ Three years have passed since he died.\\n＝ It has been three years since he died.\\n上位校ではこうした書きかえも出る。「3年前に死んだ」＝「死んだ状態が3年続いている」と考えると、現在完了に置きかえられる。\\n\\n⚠ 注意：today や this week は「今を含む期間」なので現在完了と使える。I have seen him twice today.（今日、彼に2回会いました）。ただし今日がもう終わった話をするなら過去形になる。今を含むかどうかで判断する。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「あなたはいつ日本へ来たのですか。」\",\"wrongAnswer\":\"When have you come to Japan?\",\"trapExplanation\":\"「来て今も日本にいる」という状況から、今とつながる現在完了を選んでしまう。When が「過去のいつか」を尋ねる語であり、現在完了とは共存できないことを知らない。\",\"correctAnswer\":\"When did you come to Japan?\",\"correctExplanation\":\"When は過去の一点を尋ねる語なので、必ず過去形といっしょに使う。今もいることを言いたいなら How long have you been in Japan?（どのくらい日本にいますか）と別の尋ね方をする。When＝過去形、How long＝現在完了、とセットで覚える。\"},{\"question\":\"次の日本語を英語にしなさい。「私は3日前にその本を読み終えました。」\",\"wrongAnswer\":\"I have finished the book three days ago.\",\"trapExplanation\":\"「読み終えた」という完了の意味から現在完了を選び、そこに「3日前」をそのまま足してしまう。「〜してしまった」という日本語が現在完了と強く結びついているために起こる。\",\"correctAnswer\":\"I finished the book three days ago.\",\"correctExplanation\":\"three days ago は過去の一点を指す語なので、現在完了とはいっしょに使えない。過去形 finished にする。現在完了で言うなら I have just finished the book.（ちょうど読み終えたところです）のように、「いつ」を表す語を外す。\"}]}",
"{\"id\":\"eigo_s155\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時制の総整理：一本の時間軸で並べる\",\"description\":\"ここまで学んだすべての時制を、一本の時間軸の上で整理して選べるようにする\",\"intro\":\"現在形・過去形・進行形・未来・現在完了。ここまでに出てきた形をばらばらに覚えていると、英作文のたびに迷います。1本の時間軸の上に並べ、「点か幅か」「今とつながるか」の2つで選べるようにして仕上げます。\",\"order\":655,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"判断は二段階。①今とつながっているか　②点か幅か。\",\"過去形＝過去の点／過去進行形＝過去の幅／現在完了＝過去から今までの幅。\",\"現在形＝くり返す点／現在進行形＝今の幅／will・be going to＝これから。\",\"時・条件を表すまとまり（if, when など）の中では、未来のことも現在形。\",\"and で結ばれた動詞は同じ時制にそろえる。\"],\"sections\":[{\"heading\":\"一本の時間軸にすべてを並べる\",\"body\":\"ここまで学んだ時制を、一本の時間軸の上に並べて整理する。\\n\\n■ 過去のこと\\n過去形：I played tennis yesterday.（過去の一点での出来事）\\n過去進行形：I was playing tennis at three yesterday.（過去のある時点で進行中）\\n\\n■ 過去から今まで\\n現在完了（継続）：I have played tennis for five years.（今も続いている）\\n現在完了（完了・結果）：I have just played tennis.（終わって、その結果が今にある）\\n現在完了（経験）：I have played tennis many times.（今までに何回も）\\n\\n■ 今のこと\\n現在形：I play tennis every Sunday.（くり返す習慣）\\n現在進行形：I am playing tennis now.（今この瞬間の幅）\\n\\n■ これからのこと\\nwill：I'll play tennis with you.（今決めた）\\nbe going to：I'm going to play tennis tomorrow.（前から決めていた）\\n現在進行形：I'm playing tennis at three tomorrow.（約束ずみ）\\n現在形：The game starts at three.（決まっている予定）\\n\\n★ ポイント：形が七つ以上あっても、判断するのは二つだけ。①今とつながっているか　②点か幅か。この二つを順に確かめれば、どの形を使うかは自動的に決まる。\",\"figureId\":\"lf_eigoext04_155\"},{\"heading\":\"入試で問われる最後の確認事項\",\"body\":\"時制の問題で最後まで残りやすい注意点をまとめておく。\\n\\n■ ① 時・条件のまとまりでは未来も現在形\\nIf it rains tomorrow, I will stay home.\\nWhen he comes back, I will tell him.\\nif・when・before・after・until・as soon as のあとは will を使わない。\\n\\n■ ② and で結ばれた動詞は時制をそろえる\\n× I went to the park and play soccer.\\n○ I went to the park and played soccer.\\n一つ目の動詞が過去形なら、and のあとも過去形にする。\\n\\n■ ③ 状態動詞は進行形にしない\\n× I am knowing him.　○ I know him.\\nただし have は「食べる・過ごす」の意味なら進行形にできる。\\n\\n■ ④ 現在完了に「いつ」を表す語は付けない\\n× I have seen him yesterday.　○ I saw him yesterday.\\n\\n■ ⑤ 助動詞や did のあとは原形\\n× He will comes.　○ He will come.\\n× Did you played?　○ Did you play?\\n\\n■ ⑥ have のあとは過去分詞\\n× I have saw it.　○ I have seen it.\\n\\n■ 見直しの手順\\n英作文を書き終えたら、次の順で見直す。\\n（ア）主語と動詞の数は合っているか\\n（イ）時を表す語と時制は矛盾していないか\\n（ウ）助動詞・did・to のあとは原形か\\n（エ）have のあとは過去分詞か\\nこの四つを確認するだけで、時制の失点は大きく減らせる。\"},{\"heading\":\"なぜ「今とつながるか」「点か幅か」の二つで決まるのか\",\"mangaId\":\"eigo_s155_manga\",\"body\":\"英語の時制は、**出来事が時間軸のどこにあるか**と**どんな長さか**の二つを表す形です。過去形は過去の一点、過去進行形は過去の幅、現在完了は過去から今までの幅、現在形はくり返す点、現在進行形は今の幅。だから「今とつながっているか」で過去形と現在完了を分け、「点か幅か」で単純形と進行形を分ければ、七つ以上ある形も二つの問いで一つに決まります。ばらばらに覚えると英作文のたびに迷いますが、一本の時間軸に並べれば、迷う場所が二か所に減ります。\\n\\n最後の確認事項（and で時制をそろえる・状態動詞は進行形にしない・現在完了に yesterday を付けない・助動詞と did のあとは原形・have のあとは過去分詞）は、**時制を決めたあとに形が崩れる**失敗を防ぐものです。日本語では文末にしか「〜しました」が付かないので、and のあとの動詞の時制を意識しにくく、ここでよく落とします。\\n\\n■ 確かめのしかた\\n①**今とつながっているか**：since・for・「ずっと」があれば現在完了（I haven't seen her since yesterday.）。yesterday・ago があれば過去形。\\n②**点か幅か**：「〜している最中」なら進行形、習慣・事実なら現在形。\\n③書き終えたら四つを見直す：（ア）主語と動詞の数、（イ）時を表す語と時制の矛盾、（ウ）助動詞・did・to のあとは原形、（エ）have のあとは過去分詞。\\n④and・but の前後で時制がそろっているか。I went 〜 and play→×→played。\\n\\n★ ここがポイント：時制は**時間軸の位置と長さ**を表す形なので、**今とつながるか／点か幅か**の二つで決まる。決めたあとは**and の前後・原形・過去分詞**の四つの見直しで形の崩れを防ぐ。\"}],\"trapExamples\":[{\"question\":\"次の日本語を英語にしなさい。「私は昨日から母に会っていません。」\",\"wrongAnswer\":\"I don't see my mother since yesterday.\",\"trapExplanation\":\"「会っていません」という日本語が現在の否定に見えるため、現在形の否定文にしてしまう。since yesterday という「昨日から今まで」の幅が、現在形とは合わないことに気づいていない。\",\"correctAnswer\":\"I haven't seen my mother since yesterday.\",\"correctExplanation\":\"昨日から今まで続いている状態なので現在完了の否定文にする。see の過去分詞は seen。since 〜 や for 〜 が出てきたら現在完了、と機械的に結びつけてよい。「ずっと〜していない」も継続用法である。\"},{\"question\":\"次の日本語を英語にしなさい。「私は昨日、公園へ行ってサッカーをしました。」\",\"wrongAnswer\":\"I went to the park yesterday and play soccer.\",\"trapExplanation\":\"一つ目の動詞を過去形にしたことで安心してしまい、and のあとの動詞を原形のままにしてしまう。日本語では最後にだけ「〜しました」と付くので、二つ目の動詞の時制を意識しにくい。\",\"correctAnswer\":\"I went to the park yesterday and played soccer.\",\"correctExplanation\":\"and で結ばれた二つの動詞は、同じ時制にそろえる。went が過去形なので played も過去形にする。長い英作文では、and や but の前後で時制がずれていないかを最後に必ず確認する。\"}]}",
"{\"id\":\"eigo_s156\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"助動詞の基本と can①：「〜できる」の文の形\",\"description\":\"助動詞に共通する三つの決まりを覚え、can を使った肯定文・否定文を正しく作れるようにする\",\"intro\":\"「彼女はピアノをひけます」を英語にすると She can play the piano. です。ここで多くの人が She can plays. と書いてしまいます。日本語では「ひける」と動詞そのものが変わるのに、英語では can を足すかわりに動詞は原形に戻る。この「戻る」感覚が助動詞のすべての出発点です。\",\"order\":656,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"助動詞は動詞の前に置いて、「できる」「かもしれない」などの気持ちを付け加える語。\",\"助動詞のあとの動詞は必ず原形。主語が三人称単数でも s を付けない（× She can plays）。\",\"助動詞自身も形を変えない。主語が he / she でも can は can のまま（× cans）。\",\"助動詞を二つ並べることはできない（× will can → will be able to）。\",\"否定文は助動詞のうしろに not を置くだけ。don't / doesn't は使わない。\",\"can not は一語でつなげて cannot と書き、短縮形は can't。\"],\"sections\":[{\"heading\":\"助動詞に共通する三つの決まり\",\"mangaId\":\"eigo_s156_manga\",\"body\":\"英語の動詞は、そのままでは「する・した」という事実しか伝えられない。そこに「できる」「〜しなければならない」「〜かもしれない」といった話し手の気持ちを付け加えるのが助動詞である。can・may・must・will・should などがその仲間で、いつも動詞の前に置く。\\n\\n助動詞にはどれにも共通する三つの決まりがある。この三つを最初に丸ごと覚えてしまえば、can でも must でも will でも同じように文が作れる。\\n\\n■ 決まり① 助動詞のあとは動詞の原形\\n例）She can play the piano.（彼女はピアノをひける）\\n主語が she でも play に s は付かない。× She can plays the piano.\\n\\n■ 決まり② 助動詞自身は形を変えない\\n例）He can swim fast.（彼は速く泳げる）\\n× He cans swim. のように助動詞に s を付けてはいけない。\\n\\n■ 決まり③ 助動詞は二つ並べられない\\n× He will can come. とは言えない。「〜できるだろう」は will be able to を使って He will be able to come. と表す。\\n\\n★ ポイント：「助動詞のうしろは原形」「助動詞に s は付かない」の二つは、これから習うすべての助動詞に効く。ここでつまずくと must でも should でも同じまちがいをくり返すことになる。\",\"figureId\":\"lf_eigoext05_156\"},{\"heading\":\"can の意味と否定文の作り方\",\"body\":\"can の中心の意味は「〜することができる」である。人の能力にも、ものごとの可能性にも使う。\\n\\n例）I can play the guitar.（私はギターがひける）＝能力\\n例）You can see Mt. Fuji from here.（ここから富士山が見えます）＝可能\\n例）You can use my bike.（私の自転車を使っていいよ）＝許可\\n\\n■ 否定文\\n助動詞の否定文は、助動詞のすぐうしろに not を置くだけでできる。一般動詞の否定文で使う don't / doesn't は使わない。\\n例）I cannot swim. ＝ I can't swim.（私は泳げない）\\n× I don't can swim. ／ × He doesn't can swim. は典型的なまちがい。\\n\\n■ can not の書き方\\ncan の場合だけ、not をくっつけて cannot と一語で書くのがふつうである。短縮形は can't。書くときは cannot・can't のどちらでもよいが、can not と離して書くのは避ける。\\n\\n■ 主語が何であっても形は同じ\\nI can / You can / He can / She can / We can / They can とすべて同じ。三単現の s におびえて cans と書いてしまう受験生が毎年いるので、ここは声に出して確認しておく。\\n\\n⚠ 注意：can のうしろに to を入れて × I can to swim. とするまちがいも多い。want to play・be able to play のように to を使う形を先に習っているとつられやすいが、助動詞のうしろは to なしの原形である。\"}],\"trapExamples\":[{\"question\":\"「彼女はピアノをひくことができます。」を英語にしなさい。\",\"wrongAnswer\":\"She can plays the piano.\",\"trapExplanation\":\"主語が三人称単数のときは動詞に s を付ける、という三単現のルールが体にしみついているため、can のうしろの play にもつい s を付けてしまう。\",\"correctAnswer\":\"She can play the piano.\",\"correctExplanation\":\"助動詞のあとの動詞は必ず原形なので、三単現の s は付けない。三単現の s は「助動詞のない現在の文」だけのルールである。She plays the piano.（s あり）と She can play the piano.（s なし）を並べて覚えるとよい。\"},{\"question\":\"「私の兄は英語を話せません。」を英語にしなさい。\",\"wrongAnswer\":\"My brother doesn't can speak English.\",\"trapExplanation\":\"一般動詞の否定文は doesn't を使うと習っているため、can のある文にもそのまま doesn't を付けてしまう。\",\"correctAnswer\":\"My brother cannot speak English.（＝ My brother can't speak English.）\",\"correctExplanation\":\"助動詞のある文の否定は、助動詞のうしろに not を置くだけでよい。do / does の助けはいらない。can not は cannot と一語で書き、短縮形は can't。疑問文も同じで、Does he can 〜? ではなく Can he 〜? となる。\"}]}",
"{\"id\":\"eigo_s157\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"can②：疑問文の作り方と答え方\",\"description\":\"can の疑問文は can を主語の前に出すだけであることを理解し、答え方まで正確に書けるようにする\",\"intro\":\"Can you swim? に対して「はい、泳げます」を Yes, I can swim. と長く答えると、まちがいではないのに会話ではくどく響きます。英語は Yes, I can. で切り上げるのがふつうです。しかも答えの主語は you ではなく I に入れかえます。たずねる形と答える形をセットで身につけましょう。\",\"order\":657,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"can の疑問文は can を主語の前に出す。Do / Does は使わない。\",\"答えは Yes, 主語 can. / No, 主語 can't. と、必ず can で受ける。\",\"答えの主語は代名詞にする（Can Ken 〜? → Yes, he can.）。\",\"疑問詞のある文は「疑問詞＋can＋主語＋原形 〜?」の語順（What can you see?）。\",\"How many などのかたまりは、ばらさずに丸ごと文の先頭に置く。\"],\"sections\":[{\"heading\":\"疑問文は can を前に出すだけ\",\"body\":\"助動詞のある文を疑問文にするときは、助動詞を主語の前に出すだけでよい。一般動詞の疑問文で使う Do / Does は必要ない。\\n\\n例）You can play the guitar.（あなたはギターがひける）\\n　→ Can you play the guitar?（あなたはギターがひけますか）\\n\\n例）Ken can run fast.\\n　→ Can Ken run fast?\\n\\n■ 答え方\\n答えるときも can を使って受ける。\\nYes, I can. / No, I can't.\\nYes, he can. / No, he can't.\\n× Yes, I do. や × No, I don't. と答えるのは誤りである。「聞かれた助動詞でそのまま返す」と覚える。\\n\\n■ 答えの主語は代名詞にする\\nCan your sister swim? — Yes, she can.\\nCan Tom and Ken play soccer? — Yes, they can.\\n問題文の主語をそのまま書き写して Yes, your sister can. とすると不自然。答えでは代名詞に置きかえるのが原則である。\\n\\n★ ポイント：肯定文・否定文・疑問文の三つを、同じ文で並べて練習すると定着が早い。\\nHe can ride a bike. ／ He can't ride a bike. ／ Can he ride a bike?\",\"figureId\":\"lf_eigoext05_157\",\"mangaId\":\"eigo_s157_xm\"},{\"heading\":\"疑問詞といっしょに使う\",\"body\":\"「何が見えますか」「どこで買えますか」のように、疑問詞と can を組み合わせる文は入試でよく出る。語順は決まっていて、疑問詞をいちばん前に置き、そのうしろに can の疑問文の形をそのまま続ける。\\n\\n■ 語順：疑問詞 ＋ can ＋ 主語 ＋ 動詞の原形 〜?\\n例）What can you see from your room?（あなたの部屋から何が見えますか）\\n例）Where can I buy this book?（どこでこの本を買えますか）\\n例）When can we meet?（いつ会えますか）\\n例）How can I get to the station?（どうやって駅へ行けますか）\\n\\n■ かたまりで動く疑問詞\\nHow many books can you carry?（何冊の本を運べますか）\\nHow fast can he swim?（彼はどれくらい速く泳げますか）\\nHow many books・How fast はひとかたまりなので、ばらさずに丸ごと先頭に置く。× How can you many books carry? のようにはならない。\\n\\n■ 疑問詞が主語になるとき\\nWho can answer this question?（だれがこの問題に答えられますか）\\nこの文の who は主語なので、うしろは can answer とふつうの語順のまま続く。答えは I can. や Ken can. のように短く言う。\\n\\n⚠ 注意：What can you see? のように疑問詞を前に出したあとは、必ず「can ＋ 主語」の順になる。× What you can see? と主語が先に来る語順は、日本語の語順につられた典型的なまちがいである。\"}],\"trapExamples\":[{\"question\":\"「あなたは中国語を話せますか。」を英語にしなさい。\",\"wrongAnswer\":\"Do you can speak Chinese?\",\"trapExplanation\":\"疑問文は Do で始める、と一般動詞のルールを先に覚えているため、can のある文にも Do を付け足してしまう。\",\"correctAnswer\":\"Can you speak Chinese?\",\"correctExplanation\":\"助動詞のある文の疑問文は、助動詞を主語の前に出すだけでよい。Do / Does は一般動詞の文にしか使わない。同じように Must you go? / Will you come? も do は不要である。\"},{\"question\":\"Can your brother play the violin? に「はい、ひけます」と答えなさい。\",\"wrongAnswer\":\"Yes, he does.\",\"trapExplanation\":\"Yes, he does. という答え方の形になじみがあるため、can で聞かれたことを忘れて does で受けてしまう。主語を your brother のまま書いてしまうミスも多い。\",\"correctAnswer\":\"Yes, he can.\",\"correctExplanation\":\"聞かれた助動詞をそのまま使って答えるのが原則。Can 〜? には can / can't で返す。また主語は代名詞にかえるので、your brother は he になる。否定で答えるときは No, he can't. とする。\"}]}",
"{\"id\":\"eigo_s158\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"can③：could と be able to（過去・未来の「できる」）\",\"description\":\"can には過去形 could があるが未来形はないことを理解し、be able to で時制を補えるようにする\",\"intro\":\"「来年には泳げるようになります」を英語にしようとして I will can swim next year. と書いてしまう人がいます。しかし英語では助動詞を二つ続けて置くことができません。そこで登場するのが be able to です。can に足りない過去と未来を、どう補うのかを見ていきましょう。\",\"order\":658,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"can の過去形は could。「〜できた」の意味になる。\",\"can に未来形はない。「〜できるだろう」は will be able to を使う（× will can）。\",\"be able to の be は主語に合わせて am / is / are、過去は was / were になる。\",\"過去に一回だけ「実際にやりとげた」ことは was / were able to を使うのがふつう。\",\"could の否定は couldn't（＝could not）。「〜できなかった」。\"],\"sections\":[{\"heading\":\"could と will be able to\",\"body\":\"can は「〜できる」という現在の文にしか使えない。過去や未来を表したいときは、次のように形を変える。\\n\\n■ 過去「〜できた」→ could\\n例）I could swim when I was five.（私は五歳のとき泳げた）\\n例）He couldn't come to the party.（彼はパーティーに来られなかった）\\n\\n■ 未来「〜できるだろう」→ will be able to\\n助動詞は二つ並べられないので、× will can とは書けない。can と同じ意味を持つ be able to を借りてきて、will be able to とする。\\n例）You will be able to speak English well.（あなたは英語を上手に話せるようになるでしょう）\\n\\n■ be able to の形\\nbe able to は「be動詞＋able to＋動詞の原形」で、be動詞の部分が主語と時制に合わせて変化する。\\n現在：I am able to 〜 ／ He is able to 〜 ／ They are able to 〜\\n過去：I was able to 〜 ／ They were able to 〜\\n未来：I will be able to 〜（この be は原形のまま）\\n\\n★ ポイント：can が使える場面ではふつう can を使う。be able to はもっぱら「助動詞が二つ並んでしまうとき」の助っ人として登場する、と考えておくとよい。\",\"figureId\":\"lf_eigoext05_158\"},{\"heading\":\"could と was able to の使い分け\",\"mangaId\":\"eigo_s158_manga\",\"body\":\"どちらも「〜できた」と訳せるが、英検三級や上位校の入試では区別が問われることがある。\\n\\n■ could ＝ もともとその力があった（能力・状態）\\n例）My grandfather could speak three languages.（祖父は三か国語を話せた）\\n例）I could read English books when I was ten.\\n「いつでもできる力を持っていた」という、幅のある過去を表す。\\n\\n■ was / were able to ＝ その一回、実際にやりとげた\\n例）I was able to finish my homework before dinner.（私は夕食前に宿題を終えることができた）\\n例）He was able to catch the last train.（彼は最終電車に間に合った）\\n「がんばった結果、そのときうまくいった」という一回きりの出来事には was / were able to を使う。\\n\\n■ 否定なら could でもよい\\n「できなかった」という否定では、一回きりの出来事でも couldn't が自然に使える。\\n例）I couldn't catch the last train.（最終電車に間に合わなかった）\\n\\n⚠ 注意：「昨日は雨がやんだので、公園でサッカーができた」のような一回の出来事に could を使うと不自然になる。過去の文を英作するときは、「もともとの力の話か、その日一度だけの話か」を確かめるくせをつけたい。\"}],\"trapExamples\":[{\"question\":\"「あなたは来年、上手に泳げるようになるでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"You will can swim well next year.\",\"trapExplanation\":\"「〜だろう」は will、「〜できる」は can と、日本語の意味を一つずつ英語に置きかえていくと、助動詞が二つ並んでしまうことに気づかない。\",\"correctAnswer\":\"You will be able to swim well next year.\",\"correctExplanation\":\"助動詞は一つの文に二つ並べられない。will を残して can のほうを be able to に置きかえる。will のうしろは原形なので be able to の be はそのままの形。同じ理由で「〜しなければならないだろう」も × will must ではなく will have to となる。\"},{\"question\":\"「私は昨日、その川を泳いでわたることができた。」を英語にしなさい。\",\"wrongAnswer\":\"I could swim across the river yesterday.\",\"trapExplanation\":\"「できた」＝ can の過去形 could、と機械的に置きかえてしまう。could が「もともとその力があった」という意味に寄ることを知らないために起こる。\",\"correctAnswer\":\"I was able to swim across the river yesterday.\",\"correctExplanation\":\"過去の一回きりの出来事を「実際にやりとげた」と言うときは was / were able to を使う。could は「五歳のときから泳げた」のように、力を持っていた状態を表すのに向いている。ただし否定文（couldn't）はどちらの場合にも使える。\"}]}",
"{\"id\":\"eigo_s159\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"can④：許可と依頼の can、can't の「はずがない」\",\"description\":\"Can I 〜? と Can you 〜? を区別し、会話で使う can の意味を正しくつかむ\",\"intro\":\"Can I open the window? と Can you open the window? — ちがうのは一語だけですが、前者は「開けてもいいですか」、後者は「開けてくれますか」です。だれがその動作をするのかで意味が入れかわります。会話で使う can の意味を、場面ごとに整理していきましょう。\",\"order\":659,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Can I 〜? ＝「（私が）〜してもいいですか」＝許可を求める言い方。\",\"Can you 〜? ＝「（あなたが）〜してくれますか」＝相手への依頼。\",\"主語が I か you かで意味がまったく変わるので、英作文では必ず確認する。\",\"承諾は Sure. / Of course. / All right. 、断るときは I'm sorry, I can't.。\",\"can't には「〜のはずがない」という強い否定の推量の意味もある。\"],\"sections\":[{\"heading\":\"Can I 〜? と Can you 〜?\",\"body\":\"can は「能力」だけでなく、会話では「許可」と「依頼」にも使われる。見分けるかぎは主語である。\\n\\n■ Can I 〜?（私が〜してもいいですか）＝許可を求める\\n例）Can I use your dictionary?（辞書を使ってもいいですか）\\n例）Can I have some water?（お水をいただけますか）\\n自分が何かをしたいときの言い方。\\n\\n■ Can you 〜?（〜してくれませんか）＝相手への依頼\\n例）Can you open the window?（窓を開けてくれませんか）\\n例）Can you help me with my homework?（宿題を手伝ってくれませんか）\\n相手に何かをしてもらいたいときの言い方。\\n\\n■ 答え方\\nどちらにも次のように答える。\\n承諾：Sure. ／ Of course. ／ All right. ／ No problem.\\n断り：I'm sorry, I can't. ／ Sorry, but I'm busy now.\\nYes, you can. とも言えるが、上から許可を出すひびきになることがあるので、会話では Sure. のほうがよく使われる。\\n\\n★ ポイント：日本語の「〜していい？」と「〜してくれる？」はどちらも短いので混同しやすい。英語では「するのはだれか」を主語がはっきり示す、と意識する。\",\"figureId\":\"xf_eigo_s159\"},{\"heading\":\"can't ＝「〜のはずがない」\",\"mangaId\":\"eigo_s159_manga\",\"body\":\"can't は「〜できない」のほかに、「〜のはずがない」という強い打ち消しの推量を表すことがある。上位校や英検三級で問われる用法である。\\n\\n例）It can't be true.（それが本当のはずがない）\\n例）He can't be at home. His bike isn't here.（彼が家にいるはずがない。自転車がないもの）\\n例）That can't be Ken. He is in Osaka today.\\n\\n■ 「〜にちがいない」の反対語として覚える\\nmust be 〜（〜にちがいない） ⇔ can't be 〜（〜のはずがない）\\nこの二つは対になっている。「〜でないにちがいない」と言いたくて must not be としてしまうまちがいが非常に多い。must not は「してはいけない」という禁止の意味になってしまう。\\n\\n■ 見分け方\\nうしろが be や動詞の原形でも、文の内容が「能力」ではなく「そんなことはありえない」という判断であれば推量の can't である。\\n例）She can't be twenty.（彼女が二十歳のはずがない）＝ 能力の話ではない\\n\\n⚠ 注意：Can it be true?（本当だろうか）のように、疑問文で「いったい〜だろうか」という驚きを表すこともある。訳すときは前後の文の内容から判断する。\"}],\"trapExamples\":[{\"question\":\"「窓を開けてくれませんか。」を英語にしなさい。\",\"wrongAnswer\":\"Can I open the window?\",\"trapExplanation\":\"日本語の「開けてくれませんか」には主語がないため、どちらが動作をするのかを意識せずに、覚えやすい Can I 〜? の形を選んでしまう。\",\"correctAnswer\":\"Can you open the window?\",\"correctExplanation\":\"窓を開けるのは相手なので主語は you。Can I open the window? では「私が開けてもいいですか」となり、意味が正反対になる。「相手にしてもらう＝ you」「自分がする＝ I」と、動作をする人を先に決めてから英文を書く。\"},{\"question\":\"次の英文を日本語にしなさい。「That story can't be true.」\",\"wrongAnswer\":\"その話は本当にすることができない。\",\"trapExplanation\":\"can't を「〜できない」と機械的に訳すため、be true（本当である）と結びついて意味の通らない日本語になってしまう。\",\"correctAnswer\":\"その話が本当のはずがない。\",\"correctExplanation\":\"can't be 〜 は「〜のはずがない」という強い打ち消しの推量。反対に must be 〜 は「〜にちがいない」。訳して意味が通らないときは、能力の can ではなく推量の can't を疑う。\"}]}",
"{\"id\":\"eigo_s160\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"may①：許可の may（May I 〜? と答え方）\",\"description\":\"ていねいに許可を求める May I 〜? の形と受け答えを、会話の場面ごとに身につける\",\"intro\":\"お店に入ると、店員さんが May I help you? と声をかけてきます。直訳すれば「私はあなたを手伝ってもよいですか」。日本語の「いらっしゃいませ」にあたる決まり文句です。may は相手にへりくだって許しを求める語で、Can I 〜? よりていねいに響きます。\",\"order\":660,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"May I 〜? ＝「〜してもよろしいですか」。Can I 〜? よりていねい。\",\"may のうしろも動詞の原形（× May I to use 〜?）。\",\"承諾は Sure. / Of course. / Certainly.、断りは I'm sorry, but 〜。\",\"May you 〜? という依頼の言い方はしない。相手に頼むときは Can / Will / Could you 〜?。\",\"May I help you? は店員の「いらっしゃいませ・何かお探しですか」の決まり文句。\"],\"sections\":[{\"heading\":\"ていねいに許可を求める May I 〜?\",\"body\":\"may の第一の意味は「〜してもよい」という許可である。とくに疑問文の May I 〜? は、初対面の人や目上の人に何かを頼むときのていねいな言い方として、会話問題で頻出する。\\n\\n例）May I come in?（入ってもよろしいですか）\\n例）May I use your phone?（電話をお借りしてもよろしいですか）\\n例）May I ask you a question?（質問してもよろしいですか）\\n例）May I take a picture here?（ここで写真をとってもよろしいですか）\\n\\n■ 平叙文の may\\n例）You may go home now.（もう帰ってよろしい）\\nこれは先生が生徒に言うような、上の立場から許可を与えるひびきになる。友達どうしでは使わない。\\n\\n■ 答え方\\n承諾：Sure. ／ Of course. ／ Certainly. ／ Yes, please do.\\n断り：I'm sorry, but you can't. ／ I'm afraid not.\\nNo, you may not. は「だめです」と強くはねつけるひびきになるので、ふつうは I'm sorry を付けてやわらげる。\\n\\n★ ポイント：ていねいさの順は Can I 〜? ＜ May I 〜? ≒ Could I 〜? のイメージ。相手が友達なら Can I、店員さんや先生になら May I、と場面で選ぶ。\",\"figureId\":\"xf_eigo_s160\"},{\"heading\":\"会話で覚える決まり文句\",\"body\":\"May I 〜? は会話文の並べかえ・応答選択でくり返し出題される。次の型は場面ごと丸ごと覚えてしまうのが速い。\\n\\n■ 店で\\n店員：May I help you?（いらっしゃいませ。何かお探しですか）\\n客：Yes, please. I'm looking for a T-shirt.（はい。Tシャツを探しています）\\n客：No, thank you. I'm just looking.（いいえ、けっこうです。見ているだけです）\\n\\n■ 電話で\\nMay I speak to Ken, please?（ケンさんをお願いします）\\n— Speaking.（私です）\\n— Just a moment, please.（少々お待ちください）\\n— I'm sorry, he is out now.（すみません、いま出かけています）\\n\\n■ 名前をたずねる\\nMay I have your name, please?（お名前をうかがってもよろしいですか）\\n\\n⚠ 注意：May I help you? を「私を手伝ってくれますか」と取りちがえる受験生が多い。動作をするのは I（店員）なので、「（私が）お手伝いしましょうか」という申し出である。「手伝ってくれますか」と頼むときは Can you help me? となる。\",\"mangaId\":\"eigo_s160_xm\"}],\"trapExamples\":[{\"question\":\"店員に「私のかばんを運んでいただけますか」と頼む言い方として正しいものを書きなさい。\",\"wrongAnswer\":\"May you carry my bag?\",\"trapExplanation\":\"may は「ていねいな言い方」と覚えているため、相手に頼むときにも May you 〜? と主語だけ入れかえて使ってしまう。\",\"correctAnswer\":\"Could you carry my bag?（Can you 〜? / Will you 〜? も可）\",\"correctExplanation\":\"May I 〜? は「私がしてもよいか」と許可を求める形で、May you 〜? という依頼の言い方は英語にはない。相手に何かをしてもらうときは Can you / Will you / Could you / Would you を使う。「許可の may は主語が I のときだけ」と覚えておく。\"},{\"question\":\"店で店員に May I help you? と言われた。「いいえ、けっこうです。見ているだけです」と答えなさい。\",\"wrongAnswer\":\"No, I don't. I see only.\",\"trapExplanation\":\"May I help you? を「あなたは私を手伝いますか」と読みちがえ、一般動詞の疑問文のつもりで No, I don't. と答えてしまう。\",\"correctAnswer\":\"No, thank you. I'm just looking.\",\"correctExplanation\":\"May I help you? は店員の決まり文句で「いらっしゃいませ、何かお探しですか」の意味。断るときは No, thank you.、用があるときは Yes, please. で受ける。「見ているだけです」は I'm just looking. が決まった言い方である。\"}]}",
"{\"id\":\"eigo_s161\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"may②：推量の may / might（〜かもしれない）\",\"description\":\"may と might が表す「かもしれない」の意味と、確信の強さの違いをつかむ\",\"intro\":\"It may rain tomorrow. を「明日は雨が降ってもよい」と訳すと、意味が通りません。正しくは「明日は雨が降るかもしれない」です。同じ may に、許可とまったくちがう「推量」の意味があるからです。might とのひびきの差もふくめて確かめていきます。\",\"order\":661,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"may ＝「〜かもしれない」。五分五分くらいの弱い推量。\",\"might は may よりさらに自信のない「ひょっとすると〜かもしれない」。\",\"might は形は may の過去形だが、意味は現在の弱い推量であることが多い。\",\"推量の may not ＝「〜しないかもしれない」。禁止の意味ではない。\",\"確信の強さは must ＞ will ＞ may ＞ might の順。\"],\"sections\":[{\"heading\":\"「〜かもしれない」の may と might\",\"body\":\"may には許可のほかに、もう一つ大切な意味がある。「〜かもしれない」という推量である。天気や人の予定など、はっきり分からないことを言うときに使う。\\n\\n例）It may rain this afternoon.（午後は雨が降るかもしれない）\\n例）He may be sick.（彼は病気かもしれない）\\n例）She may know the answer.（彼女は答えを知っているかもしれない）\\n\\n■ might はもっと自信がない\\n例）It might snow tonight.（今夜はひょっとすると雪が降るかもしれない）\\n例）He might be at home.（彼は家にいるかもしれない）\\nmight は形の上では may の過去形だが、現在のことについて「may よりさらに自信がない」と言うのに使うことが多い。might を見て機械的に過去に訳さないよう気をつける。\\n\\n■ 許可か推量かの見分け方\\n・May I 〜? のように主語が I の疑問文 → ほぼ許可\\n・It may rain. / He may be 〜. のように三人称が主語の平叙文 → ほぼ推量\\n文全体の意味を日本語にしてみて、「〜してもよい」と「〜かもしれない」のどちらが通じるかで決める。\\n\\n★ ポイント：推量の may・might のうしろも当然、動詞の原形。be動詞なら is や are ではなく be になる（He may be busy.）。\",\"figureId\":\"lf_eigoext05_161\",\"mangaId\":\"eigo_s161_xm\"},{\"heading\":\"推量の may not と否定の意味\",\"body\":\"推量の may を否定にすると「〜しないかもしれない」となる。禁止の「〜してはいけない」ではないので注意する。\\n\\n例）He may not come to school today.（彼は今日、学校に来ないかもしれない）\\n例）It may not be true.（それは本当ではないかもしれない）\\n\\n■ 許可の may not は「してはいけない」\\n例）You may not use your phone here.（ここでは電話を使ってはいけません）\\n同じ may not でも、許可の意味で使えば禁止になる。主語と場面で判断する。\\n\\n■ 確信の強さくらべ\\nHe must be tired.（疲れているにちがいない）…ほぼ確実\\nHe will be tired.（疲れているだろう）…かなり確か\\nHe may be tired.（疲れているかもしれない）…五分五分\\nHe might be tired.（ひょっとすると疲れているかもしれない）…自信なし\\nHe can't be tired.（疲れているはずがない）…強く打ち消す\\n\\n■ 書きかえの定番\\nIt may rain tomorrow. ＝ Maybe it will rain tomorrow. ＝ Perhaps it will rain tomorrow.\\n副詞の maybe（たぶん）を使った文への書きかえは頻出。maybe は一語、may be（〜かもしれない）は二語なので、書き分けに注意する。\\n\\n⚠ 注意：It maybe rain tomorrow. は誤り。maybe は副詞なので文の先頭に置き、うしろは will rain のようにふつうの文が続く。\"}],\"trapExamples\":[{\"question\":\"次の英文を日本語にしなさい。「Tom may not come to the party.」\",\"wrongAnswer\":\"トムはパーティーに来てはいけない。\",\"trapExplanation\":\"may を「〜してもよい」の意味だけで覚えていると、その否定 may not をすべて「〜してはいけない」という禁止だと思いこんでしまう。\",\"correctAnswer\":\"トムはパーティーに来ないかもしれない。\",\"correctExplanation\":\"主語が三人称で、内容が「話し手にも分からないこと」なら推量の may。推量の否定 may not は「〜しないかもしれない」となる。禁止を表したいときは must not（〜してはいけない）を使うのがふつうである。\"},{\"question\":\"次の英文を日本語にしなさい。「It might rain tomorrow.」\",\"wrongAnswer\":\"昨日は雨が降ったかもしれない。\",\"trapExplanation\":\"might は may の過去形だと習うため、文全体を過去のことだと思いこんでしまう。tomorrow を見落とすと気づけない。\",\"correctAnswer\":\"明日はひょっとすると雨が降るかもしれない。\",\"correctExplanation\":\"might は形こそ may の過去形だが、現在や未来のことを「may よりも自信なく」述べるのに使うことが多い。tomorrow があるのだから過去の訳になるはずがない。時を表す語（yesterday / tomorrow / tonight）を先に確認するくせをつける。\"}]}",
"{\"id\":\"eigo_s162\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"may③：許可と推量の見分け方（may のまとめ）\",\"description\":\"may・might の二つの意味を場面から判断し、書きかえ問題にも対応できるようにする\",\"intro\":\"may には「〜してもよい」と「〜かもしれない」という二つの意味がありました。では You may go home. はどちらでしょうか。「帰ってよろしい」とも「帰るかもしれない」とも読めてしまいます。文のどこを見れば決められるのか、その手順を作っていきます。\",\"order\":662,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"may の意味は「許可（〜してよい）」と「推量（〜かもしれない）」の二つだけ。\",\"主語が I の疑問文なら許可、三人称の平叙文なら推量と考えるのが基本。\",\"許可の may は can で、推量の may は maybe を使った文で言いかえられる。\",\"May I 〜? への答えは Sure. / Of course. / I'm sorry, but 〜。\",\"マイナスの内容（病気・遅刻・雨）が続くときは推量であることが多い。\"],\"sections\":[{\"heading\":\"二つの意味を場面で見分ける\",\"body\":\"may には「許可」と「推量」の二つの意味がある。テストでは、どちらの意味かを答えさせたり、正しく訳させたりする問題が出る。次の手順で判断すれば迷わない。\\n\\n■ 手順① 主語と文の形を見る\\n・May I 〜? / May we 〜? → 許可（〜してもよいですか）\\n・You may 〜. → 許可（〜してよろしい）\\n・He / She / It / They may 〜. → ほとんど推量（〜かもしれない）\\n\\n■ 手順② 日本語にして通るほうを選ぶ\\nIt may be cold tomorrow. を「明日は寒くてもよい」と訳しても意味が通らない。「明日は寒いかもしれない」なら通る。だから推量。\\n\\n■ 手順③ 内容がマイナスなら推量を疑う\\nHe may be sick.（病気かもしれない）／The train may be late.（電車は遅れるかもしれない）\\n「病気になってよい」「遅れてよい」と許可することはふつうないので、推量と判断できる。\\n\\n★ ポイント：might には許可の意味がほとんどなく、ほぼ推量専用と考えてよい。might が出てきたら「ひょっとすると〜かもしれない」と訳せば当たる。\",\"figureId\":\"xf_eigo_s162\",\"mangaId\":\"eigo_s162_xm\"},{\"heading\":\"書きかえと会話でのていねいさ\",\"body\":\"may の二つの意味は、それぞれ別の表現で言いかえられる。書きかえ問題では、どちらの意味かを見分けてから直す必要がある。\\n\\n■ 許可の may ⇔ can\\nMay I use this computer? ＝ Can I use this computer?\\nYou may go home. ＝ You can go home.\\n※ていねいさは may のほうが上。\\n\\n■ 推量の may ⇔ maybe / perhaps ＋ will\\nShe may come tomorrow. ＝ Maybe she will come tomorrow.\\nIt may be sunny. ＝ Perhaps it will be sunny.\\n※maybe は一語の副詞で「たぶん」。may be（助動詞＋be）と混同しないこと。\\n\\n■ ていねいさの階段（許可を求める言い方）\\nCan I 〜?（友達に）＜ May I 〜?・Could I 〜?（目上の人に、ていねい）\\nどれも答え方は同じで、Sure. / Of course. / I'm sorry, but 〜。\\n\\n■ 会話でよく出るやりとり\\nA: May I sit here?（ここにすわってもよろしいですか）\\nB: Sure. Go ahead.（どうぞ）\\nA: May I take this seat?\\nB: I'm sorry, but my friend is coming.（すみません、友達が来るので）\\n\\n⚠ 注意：Maybe を文の途中に入れて × It will maybe rain. とするのは不自然。Maybe it will rain. と文頭に置く形で覚える。\"}],\"trapExamples\":[{\"question\":\"次の文とほぼ同じ意味になるように（　）に入る語を書きなさい。「She may be late.」＝「（　）she will be late.」\",\"wrongAnswer\":\"May\",\"trapExplanation\":\"may をそのまま前に移せばよいと考えてしまう。maybe（副詞・一語）と may be（助動詞＋動詞・二語）の区別がついていない。\",\"correctAnswer\":\"Maybe（Perhaps でもよい）\",\"correctExplanation\":\"推量の may は「maybe ＋ ふつうの文」で言いかえられる。maybe は「たぶん」という意味の副詞で一語。空所のあとに she will be late と完全な文が続いているので、助動詞ではなく副詞が入ると判断できる。\"},{\"question\":\"次の may と同じ意味・用法の may を含む文を、ア〜ウから選びなさい。「You may use my bike.」　ア It may be cold. イ May I come in? ウ He may not know it.\",\"wrongAnswer\":\"ウ\",\"trapExplanation\":\"not の有無や主語の形だけを見て「似ている文」を選んでしまい、意味が許可か推量かという肝心の点を確かめていない。\",\"correctAnswer\":\"イ\",\"correctExplanation\":\"問題文の You may use my bike. は「私の自転車を使ってよい」という許可。同じ許可の用法はイの May I come in?（入ってもよろしいですか）。アとウはどちらも「〜かもしれない」という推量である。まず日本語に直して意味で分類する。\"}]}",
"{\"id\":\"eigo_s163\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"must①：「〜しなければならない」の文\",\"description\":\"must の肯定文・否定文・疑問文の形をおさえ、強い義務を表す使い方を理解する\",\"intro\":\"「もう帰らなければなりません」を英語で言うとき、日本語につられて長い文を作りたくなります。でも英語なら I must go home now. の五語で足ります。「しなければならない」という気持ちは must 一語が引き受け、動詞は原形のまま。英語の身軽さがよく分かる単元です。\",\"order\":663,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"must ＝「〜しなければならない」。話し手の強い気持ちがこもった義務。\",\"must のうしろも動詞の原形。三単現の s も to も付けない。\",\"疑問文は Must ＋ 主語 ＋ 原形 〜?。Do は使わない。\",\"must には過去形・未来形がないので、had to / will have to で補う。\",\"must not は「〜してはいけない」という禁止。\"],\"sections\":[{\"heading\":\"must の形と意味\",\"body\":\"must は「〜しなければならない」という強い義務を表す助動詞である。規則で決まっていることや、話し手が「絶対にそうすべきだ」と思っていることに使う。\\n\\n■ 肯定文\\n例）You must wash your hands before dinner.（夕食の前に手を洗いなさい）\\n例）We must be quiet in the library.（図書館では静かにしなければならない）\\n例）She must study hard for the test.\\n主語が she でも must に s は付かず、うしろの動詞も原形のままである。\\n\\n■ 否定文（禁止）\\n例）You must not run here.（ここで走ってはいけません）\\n短縮形は mustn't。「〜しなくてよい」ではなく「〜してはいけない」という強い禁止になる点が最大のポイントで、次のセッションで詳しく学ぶ。\\n\\n■ 疑問文\\n例）Must I go now?（もう行かなければなりませんか）\\n— Yes, you must. ／ No, you don't have to.（いいえ、その必要はありません）\\n答えの No のほうが独特で、No, you mustn't. とすると「行ってはいけない」という別の意味になってしまう。\\n\\n★ ポイント：must は形が一つしかない。s も付かず、過去形も未来形もない。「変わらない代わりに、意味が強い」と覚える。\",\"figureId\":\"xf_eigo_s163\"},{\"heading\":\"must が使えない場面\",\"body\":\"must は便利だが弱点がある。過去形と未来形を持たないことである。\\n\\n■ 過去「〜しなければならなかった」→ had to\\n例）I had to walk home yesterday.（昨日は歩いて帰らなければならなかった）\\n× I must walk home yesterday. とは書けない。\\n\\n■ 未来「〜しなければならないだろう」→ will have to\\n例）You will have to get up early tomorrow.\\n助動詞は二つ並べられないので × will must は誤り。\\n\\n■ ていねいさ・かたさ\\nmust は命令に近い強さがあるので、目上の人や初対面の人に向かって You must 〜. と言うときつく響く。日常会話では have to や should を使うほうが自然な場面が多い。\\n\\n■ must と have to の意味の差\\n・You must finish it today.（話し手が「今日中にやれ」と強く思っている）\\n・You have to finish it today.（規則や事情でそうなっている）\\n中学受験のレベルではほぼ同じ意味として書きかえに使われるが、この差を知っておくと英文の調子が読みとりやすくなる。\\n\\n⚠ 注意：must のうしろに to を入れて × You must to go. とするまちがいが非常に多い。have to の to につられるためである。「to が付くのは have to のほうだけ」と唱えて覚える。\",\"mangaId\":\"eigo_s163_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは今日、宿題を終えなければなりません。」を英語にしなさい。\",\"wrongAnswer\":\"You must to finish your homework today.\",\"trapExplanation\":\"同じ意味の have to に to が入っているため、must のうしろにも to が必要だと思いこんでしまう。\",\"correctAnswer\":\"You must finish your homework today.\",\"correctExplanation\":\"must は助動詞なので、うしろは to のない動詞の原形。to が付くのは have to / be able to のように「動詞のかたまり」で助動詞の代わりをする表現のほうである。must ＋ 原形、have to ＋ 原形（to は have にくっついている）と整理する。\"},{\"question\":\"「私は昨日、早く起きなければなりませんでした。」を英語にしなさい。\",\"wrongAnswer\":\"I must got up early yesterday.\",\"trapExplanation\":\"must には過去形がないことを知らないため、うしろの動詞を過去形にして過去を表そうとしてしまう。助動詞のあとは原形という基本もくずれている。\",\"correctAnswer\":\"I had to get up early yesterday.\",\"correctExplanation\":\"must は現在の文にしか使えない。過去は have to の過去形 had to を使って表す。うしろは当然 get のままの原形。未来なら will have to、否定の過去なら didn't have to（〜する必要がなかった）となる。\"}]}",
"{\"id\":\"eigo_s164\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"have to①：形と疑問文・否定文（do を使う）\",\"description\":\"have to は一般動詞の仲間なので、疑問文・否定文に do / does が必要なことを理解する\",\"intro\":\"must と同じ意味だと習う have to。ところが疑問文にすると、Must you go? に対して Do you have to go? となり、do が現れます。have to は見た目こそ助動詞のようですが、中身は一般動詞 have の仲間だからです。この一点をおさえれば形はすべて決まります。\",\"order\":664,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"have to ＋ 動詞の原形 ＝「〜しなければならない」。\",\"主語が三人称単数のときは has to になる。\",\"疑問文は Do / Does ＋ 主語 ＋ have to 〜?。must とは作り方がちがう。\",\"否定文は don't / doesn't have to ＝「〜しなくてよい」。\",\"答えは Yes, 主語 do(does). / No, 主語 don't(doesn't). となる。\"],\"sections\":[{\"heading\":\"have to は一般動詞の仲間\",\"body\":\"have to は must とほぼ同じ意味だが、文の作り方はまったくちがう。have to の have は一般動詞なので、疑問文・否定文には do / does の助けが必要になる。\\n\\n■ 肯定文\\n例）I have to clean my room.（部屋をそうじしなければならない）\\n例）He has to help his mother.（彼はお母さんを手伝わなければならない）\\n主語が he / she / it のときは has to になる。ここが助動詞 must との大きなちがいで、must は主語が何でも must のままだった。\\n\\n■ 疑問文\\n例）Do you have to go now?（もう行かなければなりませんか）\\n例）Does she have to wear a uniform?（彼女は制服を着なければなりませんか）\\n— Yes, she does. ／ No, she doesn't.\\nDoes のうしろは has ではなく have to に戻る点にも注意する。\\n\\n■ 否定文\\n例）I don't have to get up early on Sunday.（日曜日は早く起きなくてよい）\\n例）He doesn't have to come today.\\n\\n★ ポイント：must は「助動詞グループ」、have to は「一般動詞グループ」。同じ意味なのに文の作り方が別々なので、意味だけでつないで覚えると必ず事故が起きる。\",\"figureId\":\"lf_eigoext05_164\",\"mangaId\":\"eigo_s164_xm\"},{\"heading\":\"must と have to の書きかえ\",\"body\":\"入試では「ほぼ同じ意味の文にしなさい」という書きかえ問題で、must と have to がよく出る。肯定文どうしなら次のように置きかえられる。\\n\\n■ 肯定文の書きかえ\\nI must go now. ＝ I have to go now.\\nShe must study English. ＝ She has to study English.（三単現の has を忘れない）\\nWe must be careful. ＝ We have to be careful.\\n\\n■ 時制がある文\\nI had to study yesterday.（過去）\\nI will have to study tomorrow.（未来）\\nmust には過去形も未来形もないので、これらは have to しか使えない。\\n\\n■ 否定文は書きかえできない\\nYou must not swim here.（泳いではいけない）\\nYou don't have to swim here.（泳がなくてよい）\\nこの二つは意味が正反対である。書きかえ問題で否定文が出たら、機械的に置きかえてはいけない。次のセッションで集中的に確認する。\\n\\n■ 主語がかわるときの注意\\nTom must practice every day. ＝ Tom has to practice every day.\\nmust の文には三単現の s がなかったので、have to に直したときに has にし忘れる受験生が非常に多い。書きかえたら必ず主語を見直す。\\n\\n⚠ 注意：Does he have to 〜? の答えを Yes, he must. とするのは不自然。聞かれた形（does）で受けて Yes, he does. と答える。\"}],\"trapExamples\":[{\"question\":\"「彼は毎日、犬を散歩させなければなりません。」を英語にしなさい。\",\"wrongAnswer\":\"He have to walk his dog every day.\",\"trapExplanation\":\"have to をひとかたまりの決まり文句として覚えているため、主語が三人称単数でも have のままにしてしまう。must には s が付かないという知識が悪い方向に働くこともある。\",\"correctAnswer\":\"He has to walk his dog every day.\",\"correctExplanation\":\"have to の have は一般動詞なので、三人称単数現在では has to になる。助動詞 must なら He must walk 〜. と s は付かない。「must は変わらない／have to は変わる」と対にして覚える。\"},{\"question\":\"「あなたは今日、学校へ行かなければなりませんか。」を英語にしなさい。\",\"wrongAnswer\":\"Have you to go to school today?\",\"trapExplanation\":\"be動詞や助動詞の疑問文と同じように、have を主語の前に出せばよいと考えてしまう。have to の have が一般動詞であることを見落としている。\",\"correctAnswer\":\"Do you have to go to school today?\",\"correctExplanation\":\"have to の疑問文は Do / Does を文の先頭に置き、have to はそのままの位置に残す。三人称単数なら Does he have to 〜? となり、has ではなく have に戻ることにも注意する。答えは Yes, I do. / No, I don't.。\"}]}",
"{\"id\":\"eigo_s165\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"have to②：had to と will have to（時制の補い方）\",\"description\":\"must が持たない過去・未来を have to でどう表すかを、時を表す語とともに練習する\",\"intro\":\"must には過去形も未来形もありません。では「昨日は早く起きなければならなかった」はどう言うのでしょう。ここで have to が活躍します。have を had にすれば過去、will have to にすれば未来。時制を自由に動かせるのが have to の強みです。\",\"order\":665,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"過去「〜しなければならなかった」＝ had to ＋ 原形。\",\"過去の否定「〜する必要がなかった」＝ didn't have to ＋ 原形。\",\"未来「〜しなければならないだろう」＝ will have to ＋ 原形（× will must）。\",\"過去の疑問文は Did ＋ 主語 ＋ have to 〜?（had to にしない）。\",\"yesterday / last night / tomorrow など、時を表す語が時制を決める手がかりになる。\"],\"sections\":[{\"heading\":\"過去の「〜しなければならなかった」\",\"body\":\"must には過去形がない。過去のことを言うときは have to の過去形 had to を使う。\\n\\n■ 肯定文\\n例）I had to stay home last Sunday.（この前の日曜は家にいなければならなかった）\\n例）She had to take care of her brother.（彼女は弟の世話をしなければならなかった）\\nhad to は主語が何であっても had to のまま。三単現も関係ない。\\n\\n■ 否定文\\n例）I didn't have to go to school yesterday.（昨日は学校へ行かなくてよかった）\\n「行かなければならなかった」の否定ではなく、「行く必要がなかった」という意味になる。\\n\\n■ 疑問文\\n例）Did you have to walk home?（歩いて帰らなければならなかったの）\\n— Yes, I did. ／ No, I didn't.\\nDid を使ったので、うしろは had to ではなく have to に戻る。× Did you had to 〜? は誤り。\\n\\n★ ポイント：時を表す語（yesterday・last week・then）があれば過去、tomorrow・next week があれば未来と判断できる。英作文でも和訳でも、まず時を表す語をさがす。\",\"figureId\":\"xf_eigo_s165\",\"mangaId\":\"eigo_s165_xm\"},{\"heading\":\"未来の「〜しなければならないだろう」\",\"body\":\"未来のことは will have to で表す。× will must とは言えない。助動詞を二つ並べられないという決まりを、ここでも思い出す。\\n\\n■ 肯定文\\n例）You will have to wait for an hour.（一時間待たなければならないでしょう）\\n例）We will have to leave early tomorrow.\\nwill のうしろは原形なので、have to の have はそのまま。has to にはならない。× He will has to go. は誤りで、He will have to go. が正しい。\\n\\n■ 否定文\\n例）You won't have to pay for it.（それにお金をはらう必要はないでしょう）\\n\\n■ 疑問文\\n例）Will I have to change trains?（電車を乗りかえなければなりませんか）\\n— Yes, you will. ／ No, you won't.\\n\\n■ まとめ表（頭の中で作る）\\n現在：must ／ have to（has to）\\n過去：had to （must には過去形なし）\\n未来：will have to （must には未来形なし）\\n否定：must not（禁止）／ don't have to（不要）\\n\\n⚠ 注意：「〜しなければならないでしょう」を書くとき、まず will を書いてから have to を続ける。will の直後に must や has to を書きたくなったら、助動詞のルール③を思い出すこと。\"}],\"trapExamples\":[{\"question\":\"「私たちは明日、6時に起きなければならないでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"We will must get up at six tomorrow.\",\"trapExplanation\":\"「〜だろう」＝ will、「〜しなければならない」＝ must と一語ずつ置きかえてしまい、助動詞が二つ並んでいることに気づかない。\",\"correctAnswer\":\"We will have to get up at six tomorrow.\",\"correctExplanation\":\"助動詞は一つの文に二つ並べられない。will を残し、must を have to に置きかえる。will のうしろは原形なので has to にはならない。同じ理由で「〜できるだろう」も will be able to となる。\"},{\"question\":\"「あなたは昨日、部屋をそうじしなければならなかったのですか。」を英語にしなさい。\",\"wrongAnswer\":\"Did you had to clean your room yesterday?\",\"trapExplanation\":\"過去の文だから had にする、という意識が強すぎて、Did をすでに使っていることを忘れてしまう。過去形が二か所に出てしまう典型的なミス。\",\"correctAnswer\":\"Did you have to clean your room yesterday?\",\"correctExplanation\":\"Did が文の先頭に出た時点で、うしろの動詞は原形に戻る。したがって had to ではなく have to。一般動詞の過去の疑問文（Did you go 〜?）とまったく同じ仕組みである。答えは Yes, I did. / No, I didn't.。\"}]}",
"{\"id\":\"eigo_s166\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"must not と don't have to のちがい\",\"description\":\"「してはいけない」と「しなくてよい」を混同しない。入試最頻出の対比を図で整理する\",\"intro\":\"英語で一番こわい取りちがえの一つです。You must not go. は「行ってはいけない」、You don't have to go. は「行かなくてよい」。日本語ではどちらも「〜ない」で終わるのに、意味は正反対です。相手を止めるのか、自由にするのかが変わってしまいます。\",\"order\":666,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"must not（mustn't）＝「〜してはいけない」＝強い禁止。\",\"don't have to ＝「〜しなくてよい・する必要がない」＝不要。\",\"二つは反対の意味なので、書きかえ問題で入れかえてはいけない。\",\"Must I 〜? への No の答えは No, you don't have to.（No, you mustn't. は別の意味）。\",\"禁止は Don't 〜. や You can't 〜. でも表せる。\"],\"sections\":[{\"heading\":\"正反対になる二つの否定\",\"body\":\"must と have to は肯定文ではほぼ同じ意味なのに、否定文になると意味が正反対になる。中学受験でも英検でも、ここがいちばんねらわれる。\\n\\n■ must not ＝ してはいけない（禁止）\\n例）You must not swim in this river.（この川で泳いではいけません）\\n例）You mustn't tell anyone.（だれにも言ってはいけないよ）\\n「絶対にするな」という強い禁止で、標識や校則にも使われる。\\n\\n■ don't have to ＝ しなくてよい（不要）\\n例）You don't have to come tomorrow.（明日は来なくてよいですよ）\\n例）He doesn't have to wear a tie.（彼はネクタイをしめる必要がない）\\n「してもよいが、その必要はない」という意味。するかしないかは相手の自由である。\\n\\n■ ならべて確認\\nYou must not eat here.（ここで食べてはいけない）\\nYou don't have to eat here.（ここで食べなくてもよい）\\nたった数語のちがいで、店の看板なら意味が正反対になってしまう。\\n\\n★ ポイント：must not の not は「動作そのもの」を打ち消し、don't have to の not は「しなければならないという義務」を打ち消している。何を打ち消しているのかを考えると混乱しない。\",\"figureId\":\"lf_eigoext05_166\"},{\"heading\":\"答え方と言いかえ\",\"body\":\"Must I 〜? と聞かれたときの答えは、この単元でいちばんまちがえやすい。\\n\\n■ Must I 〜? への答え\\nMust I go now?（もう行かなければなりませんか）\\n— Yes, you must.（はい、行かなければなりません）\\n— No, you don't have to.（いいえ、その必要はありません）\\nNo, you mustn't. と答えると「いいえ、行ってはいけません」という別の意味になってしまう。「Must の No は don't have to」と型で覚える。\\n\\n■ 禁止のいろいろな言い方\\nYou must not run here.\\n＝ Don't run here.（命令文）\\n＝ You can't run here.（ここでは走れません＝走ってはいけません）\\n掲示では No running. のような書き方も使われる。\\n\\n■ 不要のいろいろな言い方\\nYou don't have to hurry.\\n＝ You need not hurry.（急ぐ必要はない）\\n＝ There is no need to hurry.\\nneed not は少しかたい言い方だが、英検三級の書きかえで見かける。\\n\\n■ 過去の「しなくてよかった」\\nI didn't have to work last Sunday.（先週の日曜は働かなくてよかった）\\n\\n⚠ 注意：和訳問題で don't have to を「してはいけない」と書くと、正解にはならない。逆に must not を「しなくてよい」と書いても同じ。訳を書き終えたら、「禁止か、不要か」を必ず読み返して確認する。\"},{\"heading\":\"なぜ must と have to は否定になると意味が正反対になるのか\",\"mangaId\":\"eigo_s166_manga\",\"body\":\"肯定文の must と have to はどちらも「しなければならない」ですが、**not が打ち消す相手がちがいます**。must not の not は、うしろの動作（go・eat）を打ち消して「行くな・食べるな」という禁止になります。don't have to の not は、have to（しなければならないという義務）を打ち消して「その義務はない」＝「しなくてよい」になります。同じ「〜ない」で終わる日本語に見えても、英語では打ち消す相手がちがうので、意味が正反対になります。\\n\\nMust I go? の No が No, you don't have to. になるのも同じ理由です。「行かなければなりませんか」に「いいえ」と答えるのは「その義務はない」という意味なので、義務を打ち消す don't have to を使います。No, you mustn't. は「行ってはいけない」という別の答えになります。\\n\\n■ 確かめのしかた\\n①訳を書いたら、**禁止か、不要か**を読み返す。must not→してはいけない（禁止）、don't have to→しなくてよい（不要）。\\n②「〜なくてよい」を英語にするとき、must not を選んでいないか。You don't have to come tomorrow.\\n③Must I 〜? への答え：Yes, you must. ／ No, you don't have to.（× No, you mustn't.）\\n④言いかえで確かめる：禁止＝Don't 〜.／You can't 〜.、不要＝You need not 〜.／There is no need to 〜.。過去の不要は didn't have to。\\n\\n★ ここがポイント：**must not は動作を、don't have to は義務を打ち消す**ので意味が正反対（禁止／不要）。Must I? の No は「義務がない」ので **don't have to**。訳を書いたら禁止か不要かを必ず読み返す。\"}],\"trapExamples\":[{\"question\":\"「あなたは明日、ここへ来なくてもよいです。」を英語にしなさい。\",\"wrongAnswer\":\"You must not come here tomorrow.\",\"trapExplanation\":\"「〜しなくてよい」を「〜しない」＋「must（〜しなければならない）の否定」と考えてしまい、must not を選んでしまう。日本語の「〜なくてよい」と「〜てはいけない」の差が英語では大きい。\",\"correctAnswer\":\"You don't have to come here tomorrow.\",\"correctExplanation\":\"must not は「してはいけない」という禁止で、意味が正反対になってしまう。「しなくてよい・する必要がない」は don't have to。主語が三人称単数なら doesn't have to、過去なら didn't have to を使う。\"},{\"question\":\"次の英文を日本語にしなさい。「You don't have to answer this question.」\",\"wrongAnswer\":\"あなたはこの質問に答えてはいけません。\",\"trapExplanation\":\"have to ＝「しなければならない」と覚えているので、その否定は「してはいけない」だと思ってしまう。否定が義務のほうにかかっていることに気づいていない。\",\"correctAnswer\":\"あなたはこの質問に答えなくてもよい（答える必要はない）。\",\"correctExplanation\":\"don't have to は「その義務がない」＝「しなくてよい」。答えるかどうかは自由である。「答えてはいけない」と禁止するなら You must not answer this question. となる。not が何を打ち消しているかを考えるのがこつ。\"}]}",
"{\"id\":\"eigo_s167\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"must②：推量の must（〜にちがいない）と助動詞マップ\",\"description\":\"「〜にちがいない」の must を理解し、助動詞を推量の強さと義務の強さで整理する\",\"intro\":\"何度電話しても友だちが出ないとき、He must be busy. と言えます。「彼はいそがしいにちがいない」という意味で、義務とは関係ありません。must にも may と同じように推量の意味があるのです。must・may・might を「どれくらい確信しているか」の目盛りで並べてみましょう。\",\"order\":667,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"must には「〜にちがいない」という強い推量の意味もある。\",\"must be 〜（〜にちがいない） ⇔ can't be 〜（〜のはずがない）が対になる。\",\"推量の must の否定に must not は使わない。\",\"義務か推量かは、うしろが動作か状態かと、文の内容で見分ける。\",\"助動詞は「推量の強さ」と「義務の強さ」の二つの顔を持つ。\"],\"sections\":[{\"heading\":\"「〜にちがいない」の must\",\"body\":\"must は「〜しなければならない」だけでなく、「〜にちがいない」という強い推量も表す。話し手が状況から見て「そうとしか考えられない」と判断しているときに使う。\\n\\n例）You must be tired.（あなたは疲れているにちがいない）\\n例）He must be sick. He didn't come today.（彼は病気にちがいない。今日来なかったから）\\n例）That must be Ken's bike.（あれはケンの自転車にちがいない）\\n\\n■ 義務か推量かの見分け方\\n・うしろが be動詞や know / like など「状態を表す語」→ 推量が多い\\n　You must be hungry.（おなかがすいているにちがいない）\\n・うしろが go / study / clean など「動作を表す語」→ 義務が多い\\n　You must study hard.（一生懸命勉強しなければならない）\\nただし決め手は文の内容である。「疲れなければならない」と訳して意味が通らなければ推量である。\\n\\n■ 反対の意味は can't\\nmust be 〜（〜にちがいない） ⇔ can't be 〜（〜のはずがない）\\n例）He must be at home. ⇔ He can't be at home.\\n推量を打ち消すのに must not は使わない。must not は「してはいけない」という禁止だからである。\\n\\n★ ポイント：must be と can't be はセットで覚える。「ちがいない」「はずがない」という日本語も、対にして口に出しておくとよい。\",\"mangaId\":\"eigo_s167_xm\"},{\"heading\":\"助動詞を二つの軸で整理する\",\"body\":\"ここまでに出てきた助動詞は、どれも「推量（どのくらい確かか）」と「義務・許可（どのくらい強くうながすか）」という二つの顔を持っている。二つの軸で位置づけると、全体像がつかめる。\\n\\n■ 推量の軸（〜だろう）\\nmust（にちがいない）＞ will（だろう）＞ may（かもしれない）＞ might（ひょっとすると）\\n打ち消し側：can't（はずがない）\\n\\n■ 義務・許可の軸（〜すべきだ）\\nmust（しなければならない）＞ have to（しなければならない）＞ should（したほうがよい）＞ may / can（してもよい）\\n打ち消し側：must not（してはいけない）\\n\\n■ 同じ語が両方にあらわれる\\nmust：右上（強い推量・強い義務）\\nshould：まん中（たぶん〜だろう・したほうがよい）\\nmay：弱い推量・軽い許可\\nmight：いちばん弱い推量。義務の意味はほぼない\\n\\n■ 実際の文で確かめる\\nYou must be careful.（気をつけなければならない）＝義務\\nYou must be Tom's sister.（トムのお姉さんにちがいない）＝推量\\n同じ must be でも、うしろが careful（気をつける）なら義務、Tom's sister（人の正体）なら推量になる。\\n\\n⚠ 注意：選択問題では「意味の強さ」で正解が決まることがある。「たぶん〜だろう」と書いてあれば may、「ぜったい〜にちがいない」なら must、と日本語の強さに合わせて選ぶ。\",\"figureId\":\"lf_eigoext05_167\"}],\"trapExamples\":[{\"question\":\"次の英文を日本語にしなさい。「You must be very tired.」\",\"wrongAnswer\":\"あなたはとても疲れなければなりません。\",\"trapExplanation\":\"must ＝「〜しなければならない」と一つの意味しか覚えていないため、be tired と結びつけて意味の通らない訳を作ってしまう。\",\"correctAnswer\":\"あなたはとても疲れているにちがいありません。\",\"correctExplanation\":\"must には「〜にちがいない」という推量の意味がある。うしろが be tired のような状態を表す語で、しかも「疲れる義務」など存在しないのだから、推量と判断できる。訳して意味が通らないときは、もう一つの意味を思い出す。\"},{\"question\":\"「彼がうそをついているはずがない。」を英語にしなさい。\",\"wrongAnswer\":\"He must not be telling a lie.\",\"trapExplanation\":\"「〜にちがいない」が must be なので、その反対は must not be だと考えてしまう。must not が禁止の意味になることを忘れている。\",\"correctAnswer\":\"He can't be telling a lie.（He can't be a liar. なども可）\",\"correctExplanation\":\"推量の must be を打ち消すのは can't be（〜のはずがない）である。must not be としてしまうと「うそをついてはいけない」という禁止の意味になってしまう。must be ⇔ can't be の対を、はじめから一組にして覚えておく。\"}]}",
"{\"id\":\"eigo_s168\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"should①：「〜すべきだ・したほうがよい」\",\"description\":\"should の肯定・否定・疑問の形を身につけ、助言する文を書けるようにする\",\"intro\":\"かぜをひいた友だちに「病院に行ったほうがいいよ」と言いたいとき、must を使うと「行かなければだめだ」と命令のように響きます。ここで使うのが should です。You should see a doctor. なら、おしつけずに助言する言い方になります。強さのちがいが分かる単元です。\",\"order\":668,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"should ＝「〜すべきだ・〜したほうがよい」。must より弱い、やわらかい助言。\",\"should のうしろも動詞の原形。to は付けない。\",\"否定は should not（shouldn't）＝「〜しないほうがよい」。\",\"疑問文は Should I 〜?（〜したほうがよいですか）。\",\"疑問詞といっしょのときは「疑問詞＋should＋主語＋原形」の語順。\"],\"sections\":[{\"heading\":\"should の形と使い方\",\"body\":\"should は相手に「〜したほうがいいよ」とすすめたり、「〜すべきだ」と軽く義務を示したりする助動詞である。must ほど強くないので、友達にも先生にも使いやすい。\\n\\n■ 肯定文\\n例）You should see a doctor.（お医者さんに行ったほうがいいよ）\\n例）You should take an umbrella. It may rain.（かさを持っていったほうがいい。雨が降るかもしれない）\\n例）We should help each other.（私たちはたがいに助け合うべきだ）\\n\\n■ 否定文\\n例）You shouldn't eat too much.（食べすぎないほうがいい）\\n例）You should not go out today.\\n「〜しないほうがよい」という、やわらかい打ち消しになる。must not（絶対にするな）ほど強くない。\\n\\n■ 疑問文\\n例）Should I bring my lunch?（お弁当を持っていったほうがいいですか）\\n— Yes, you should. ／ No, you don't have to.（その必要はありません）\\n— No, you shouldn't.（やめたほうがいい）\\n\\n★ ポイント：should も助動詞なので、三単現の s も付かず、to も付かない。He should goes. も He should to go. も誤りで、He should go. が正しい。\",\"figureId\":\"xf_eigo_s168\"},{\"heading\":\"疑問詞といっしょに使う should\",\"body\":\"会話では「何をしたらいいですか」「どこへ行けばいいですか」と相談する場面が多い。このとき should がよく使われる。\\n\\n■ 語順：疑問詞 ＋ should ＋ 主語 ＋ 動詞の原形 〜?\\n例）What should I do?（私はどうしたらよいですか）\\n例）Where should we meet?（どこで待ち合わせましょうか）\\n例）When should I call you?（いつ電話したらよいですか）\\n例）Which bus should I take?（どのバスに乗ればよいですか）\\n\\n日本語では「私は何をすべきですか」と主語が先に来るので、× What I should do? と書いてしまう受験生が多い。疑問詞のすぐうしろに助動詞、その次に主語、と順番を固定して覚える。\\n\\n■ 助言を表す他の言い方\\nYou should go to bed early.\\n＝ You had better go to bed early.（もっと強い。次のセッションで学ぶ）\\n＝ Why don't you go to bed early?（早く寝たらどう？）\\n＝ How about going to bed early?（早く寝るのはどう？）\\n\\n■ 会話でよく出るやりとり\\nA: I have a headache.（頭が痛いんだ）\\nB: You should go home and rest.（家に帰って休んだほうがいいよ）\\nA: Thank you. I will.（ありがとう。そうするよ）\\n\\n⚠ 注意：Should I 〜? の答えで No, you shouldn't.（やめたほうがいい）と No, you don't have to.（その必要はない）は意味がちがう。相手の質問の内容に合うほうを選ぶ。\",\"mangaId\":\"eigo_s168_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは医者に診てもらったほうがいいですよ。」を英語にしなさい。\",\"wrongAnswer\":\"You should to see a doctor.\",\"trapExplanation\":\"「〜したほうがよい」という日本語からは「〜すること」という感じを受けるため、to 不定詞を続けたくなる。have to や want to の形にもつられる。\",\"correctAnswer\":\"You should see a doctor.\",\"correctExplanation\":\"should は助動詞なので、うしろは to のない動詞の原形。can・may・must・will・should はすべて同じ決まりである。to が付くのは have to / be able to / want to のように、動詞や形容詞のあとに to が来る形だけ。\"},{\"question\":\"「私は何をしたらよいですか。」を英語にしなさい。\",\"wrongAnswer\":\"What I should do?\",\"trapExplanation\":\"日本語が「私は—何を—したらよいか」の順なので、そのまま主語を先に置いてしまう。疑問詞を前に出したあとの語順が身についていない。\",\"correctAnswer\":\"What should I do?\",\"correctExplanation\":\"疑問詞のある助動詞の疑問文は「疑問詞＋助動詞＋主語＋動詞の原形」の順。What should I do? / Where should we go? / When can you come? はすべて同じ形である。日本語の語順につられないよう、型ごと声に出して覚える。\"}]}",
"{\"id\":\"eigo_s169\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"had better：強い助言と警告\",\"description\":\"had better の形と、should より強いというひびきの差を理解して使い分ける\",\"intro\":\"had better は「〜したほうがよい」と訳されるので、should よりやわらかい言い方だと思われがちです。実は逆で、「そうしないとまずいことになる」という警告のひびきがあります。目上の人に You had better 〜. と言うと失礼になることも。強さを知って使い分けます。\",\"order\":669,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"had better ＋ 動詞の原形 ＝「〜したほうがよい」。should より強い。\",\"否定は had better not ＋ 原形。not の位置に注意（× had not better）。\",\"had と書くが過去の意味ではない。短縮形は You'd better 〜。\",\"「そうしないと困ったことになる」という警告のひびきがある。\",\"目上の人に向かって使うと失礼になるので、そのときは should を使う。\"],\"sections\":[{\"heading\":\"had better の形\",\"body\":\"had better は二語で一つの助動詞のようにはたらき、「〜したほうがよい」という強めの助言を表す。\\n\\n■ 肯定文\\n例）You had better take an umbrella.（かさを持っていったほうがいい）\\n例）You'd better hurry.（急いだほうがいい）\\n短縮形は You'd better / He'd better のように、主語のあとに 'd を付ける。\\n\\n■ うしろは原形\\nhad と書いてあっても過去の意味ではなく、うしろの動詞は必ず原形である。\\n× You had better to go. ／ × You had better went. はどちらも誤り。\\n\\n■ 否定文\\n例）You had better not go out today.（今日は出かけないほうがいい）\\n例）You'd better not tell him.（彼には言わないほうがいい）\\nnot は better のうしろに置く。× You had not better go. は誤りで、ここが試験でよくねらわれる。\\n\\n■ 主語がかわっても形は同じ\\nI had better / You had better / He had better / They had better\\nhad が has や have に変わることはない。\\n\\n★ ポイント：「had better ＋ 原形」「had better not ＋ 原形」の二つの型を、そのまま音で覚えてしまうのが確実である。\"},{\"heading\":\"should との強さのちがい\",\"body\":\"had better と should はどちらも「〜したほうがよい」と訳せるが、ひびきの強さがちがう。\\n\\n■ should ＝ やわらかい助言\\nYou should go to bed early.（早く寝たほうがいいよ）\\n相手のためを思ったアドバイス。だれに向かって使ってもよい。\\n\\n■ had better ＝ 強い助言・警告\\nYou had better go to bed early.（早く寝たほうがいい。でないと明日つらいよ）\\n「そうしないとまずいことになる」という警告がふくまれる。親が子どもに、あるいは友達どうしで使う言い方で、先生や目上の人に向かって使うと「そうしないとどうなっても知らないぞ」と聞こえてしまい失礼になる。\\n\\n■ 強さの順\\nDon't be late.（命令）＞ You must not be late.（禁止）＞ You had better not be late.（強い助言）＞ You shouldn't be late.（助言）＞ You may not want to be late.（かなり遠回し）\\n\\n■ 目上の人に助言するとき\\n先生に「早く帰られたほうがいいですよ」と言いたいときは、had better ではなく\\nI think you should go home early. や Why don't you go home early? を使う。\\n\\n⚠ 注意：had better を「〜したほうがよい」という和訳だけで覚えていると、丁寧語のつもりで目上の人に使ってしまう。英作文の場面設定（相手はだれか）を必ず確認する。\",\"figureId\":\"lf_eigoext05_169\",\"mangaId\":\"eigo_s169_xm\"}],\"trapExamples\":[{\"question\":\"「今日は出かけないほうがいいよ。」を英語にしなさい。\",\"wrongAnswer\":\"You had not better go out today.\",\"trapExplanation\":\"助動詞の否定は助動詞のすぐうしろに not を置く、という規則にひきずられ、had のうしろに not を入れてしまう。\",\"correctAnswer\":\"You had better not go out today.\",\"correctExplanation\":\"had better は二語でひとかたまりなので、not はそのかたまりのうしろ、つまり better の直後に置く。「had better not ＋ 動詞の原形」と型で覚える。短縮形なら You'd better not go out today.。\"},{\"question\":\"先生に「もう遅いので、早くお帰りになったほうがいいですよ」と伝えたい。適切な英文はどちらか。ア You had better go home early. イ I think you should go home early.\",\"wrongAnswer\":\"ア\",\"trapExplanation\":\"had better を「〜したほうがよい」というていねいな助言だと思いこんでいるため、目上の人にこそ使うべき表現だと勘ちがいしてしまう。\",\"correctAnswer\":\"イ\",\"correctExplanation\":\"had better には「そうしないと困ったことになるぞ」という警告のひびきがあり、目上の人に向けて使うと失礼になる。先生に助言するときは I think you should 〜. や Why don't you 〜? のようにやわらかい言い方を選ぶ。\"}]}",
"{\"id\":\"eigo_s170\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"should②：助言・提案の表現を使い分ける\",\"description\":\"Why don't you 〜? / How about 〜ing? など、助言と提案の言い方をまとめて整理する\",\"intro\":\"「勉強したら?」とすすめるとき、英語では Why don't you study? と言います。直訳すれば「なぜ勉強しないの?」。責めているように見えて、実はやさしいすすめの言い方です。日本語からは想像しにくいこうした表現を、まとめて身につけます。\",\"order\":670,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Why don't you 〜? ＝「〜したらどうですか」という提案。理由をたずねる文ではない。\",\"How about 〜? のうしろは名詞か動詞の -ing 形（× How about to go）。\",\"Why don't we 〜? ＝ Shall we 〜? ＝ Let's 〜.（いっしょにしよう）。\",\"I think you should 〜. はやわらかく助言する言い方。\",\"提案への返事は That's a good idea. / Sounds good. / Sorry, I can't.。\"],\"sections\":[{\"heading\":\"助言・提案の代表的な言い方\",\"body\":\"相手に何かをすすめる言い方は、会話問題でくり返し出題される。意味の近い表現をまとめて覚えておくと、書きかえにも応答選択にも強くなる。\\n\\n■ You should 〜.（〜したほうがいい）\\n例）You should try this cake.（このケーキを食べてみるといいよ）\\n\\n■ Why don't you 〜?（〜したらどうですか）\\n例）Why don't you ask your teacher?（先生に聞いてみたらどう）\\n形は否定疑問文だが、「なぜ〜しないのですか」と理由をたずねているのではなく、提案の決まり文句である。\\n\\n■ How about 〜?（〜はどうですか）\\n例）How about this one?（こちらはいかがですか）＝うしろは名詞\\n例）How about going to the movies?（映画に行くのはどう）＝うしろは動名詞\\nabout は前置詞なので、動詞を続けるときは必ず -ing 形にする。× How about to go は誤り。\\n\\n■ Why don't we 〜? / Shall we 〜? / Let's 〜.（いっしょに〜しよう）\\n例）Why don't we play tennis? ＝ Shall we play tennis? ＝ Let's play tennis.\\nyou なら「あなたが」、we なら「いっしょに」と、主語で相手の受け取り方が変わる。\\n\\n★ ポイント：Why don't you 〜? は「あなたへの提案」、Why don't we 〜? は「いっしょにやろう」という誘い。you と we を読み分ける。\",\"figureId\":\"xf_eigo_s170\",\"mangaId\":\"eigo_s170_xm\"},{\"heading\":\"提案への答え方\",\"body\":\"提案されたときの返事も、決まった言い方を覚えておけばそのまま得点になる。\\n\\n■ 賛成するとき\\nThat's a good idea.（いい考えですね）\\nSounds good. ／ That sounds nice.（よさそうですね）\\nYes, let's.（そうしましょう）※Let's 〜. や Shall we 〜? に対して\\nSure. ／ Of course. ／ All right.（いいですよ）\\n\\n■ 断るとき\\nI'm sorry, I can't.（すみません、できません）\\nSorry, but I have to help my mother.（ごめんなさい、母を手伝わないといけないので）\\nMaybe next time.（また今度ね）\\n断るときは、理由を一言そえるのが自然である。\\n\\n■ 会話の流れの例\\nA: I have a bad cold.（ひどいかぜをひいてしまって）\\nB: Why don't you go home and rest?（家に帰って休んだらどう）\\nA: That's a good idea. Thank you.（それはいい考えだね。ありがとう）\\n\\nA: How about going to the park after school?（放課後、公園に行くのはどう）\\nB: Sounds good. Let's meet at the gate.（いいね。門のところで待ち合わせよう）\\n\\n⚠ 注意：Why don't you 〜? に対して「Because 〜」と理由を答えるのは誤り。提案なので、Sure. や That's a good idea. のように賛成・不賛成で答える。\"}],\"trapExamples\":[{\"question\":\"「放課後、買い物に行くのはどうですか。」を英語にしなさい。\",\"wrongAnswer\":\"How about to go shopping after school?\",\"trapExplanation\":\"「〜すること」を to 不定詞で表す形になじんでいるため、How about のうしろにも to go を置いてしまう。about が前置詞であることを意識していない。\",\"correctAnswer\":\"How about going shopping after school?\",\"correctExplanation\":\"about は前置詞なので、うしろに動詞を続けるときは -ing 形（動名詞）にする。How about ＋ 名詞／動名詞、と型で覚える。同じ意味で Why don't we go shopping after school? や Let's go shopping after school. とも言える。\"},{\"question\":\"次の英文を日本語にしなさい。「Why don't you come with us?」\",\"wrongAnswer\":\"あなたはなぜ私たちといっしょに来ないのですか。\",\"trapExplanation\":\"Why と don't が並んでいるため、理由をたずねる否定疑問文だと読んでしまう。会話の決まり文句であることを知らないと必ず引っかかる。\",\"correctAnswer\":\"私たちといっしょに来ませんか（来たらどうですか）。\",\"correctExplanation\":\"Why don't you 〜? は「〜したらどうですか」という提案・勧誘の決まり文句。答えるときも理由ではなく Sure. / That's a good idea. / Sorry, I can't. のように応じる。Why don't we 〜? なら「いっしょに〜しませんか」となる。\"}]}",
"{\"id\":\"eigo_s171\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"will①：未来と意志（will と be going to）\",\"description\":\"will の形と意味をおさえ、be going to との使い分けまで理解する\",\"intro\":\"「明日は雨が降るでしょう」も「私が持ちますよ」も、英語ではどちらも will を使えます。予想と意志という別のことを、一語でまかなっているのです。一方 be going to は、前から決めていた予定に使います。同じ未来でも、選び方で伝わり方が変わります。\",\"order\":671,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"will ＋ 動詞の原形 ＝「〜するだろう・〜するつもりだ」。\",\"主語が三人称単数でも will のまま。うしろの動詞にも s を付けない。\",\"否定は will not ＝ won't。疑問文は Will ＋ 主語 ＋ 原形 〜?。\",\"be going to は前から決めていた予定、will はその場で決めた意志に使う。\",\"未来を表す語（tomorrow / next week / soon）といっしょに使うことが多い。\"],\"sections\":[{\"heading\":\"will の形\",\"body\":\"will は未来のことを表す助動詞で、「〜するだろう」という予想と、「〜するつもりだ」という意志の二つの意味を持つ。\\n\\n■ 肯定文\\n例）It will be sunny tomorrow.（明日は晴れるでしょう）＝予想\\n例）I will call you tonight.（今夜、電話するね）＝意志\\n例）He will be fifteen next month.（彼は来月十五歳になります）\\n主語が he でも will は変わらず、うしろの動詞も原形。× He wills come. も × He will comes. も誤り。\\n\\n■ 否定文\\n例）I won't tell anyone.（だれにも言わないよ）\\n例）It won't rain this afternoon.\\nwill not の短縮形は won't。will not をつなげて willn't とは書かない。\\n\\n■ 疑問文\\n例）Will you be free tomorrow?（明日はひまですか）\\n— Yes, I will. ／ No, I won't.\\n\\n■ 未来を表す語といっしょに\\ntomorrow（明日）・next week（来週）・next year（来年）・soon（まもなく）・someday（いつか）\\nこれらの語があれば未来の文と判断してよい。\\n\\n★ ポイント：短縮形 I'll / You'll / He'll / We'll / They'll は会話文で必ず出る。読めるだけでなく書けるようにしておく。\",\"figureId\":\"xf_eigo_s171\"},{\"heading\":\"will と be going to\",\"body\":\"未来を表す言い方には be going to もある。中学受験でも書きかえや選択で問われるので、使い分けの目安を持っておきたい。\\n\\n■ be going to ＝ 前から決めていた予定\\n例）I am going to visit my grandmother next Sunday.（次の日曜に祖母を訪ねる予定です）\\nすでに計画してあることを言う。be動詞は主語に合わせて am / is / are と変わる。\\n\\n■ will ＝ その場で決めた意志・単なる予想\\n例）A: The phone is ringing.（電話が鳴っているよ）\\n　　B: I'll get it.（ぼくが出るよ）＝今その場で決めた\\n例）I think it will rain tomorrow.（明日は雨だと思う）＝ただの予想\\n\\n■ 形のちがい\\nbe going to のうしろも動詞の原形である。\\n例）She is going to buy a new bag.\\n× She is going to buys 〜 は誤り。\\n\\n■ 否定文・疑問文\\n例）I'm not going to go out today.\\n例）Are you going to play soccer? — Yes, I am. / No, I'm not.\\nbe going to の疑問文は be動詞を前に出す。will の疑問文とは作り方がちがう。\\n\\n⚠ 注意：時や条件を表す if / when のあとでは、未来のことでも現在形を使う。\\n例）If it is fine tomorrow, we will go on a picnic.（× If it will be fine 〜）\\nこれは上位校でねらわれる決まりである。\",\"mangaId\":\"eigo_s171_xm\"}],\"trapExamples\":[{\"question\":\"「私の姉は来年、大阪に住むでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"My sister will lives in Osaka next year.\",\"trapExplanation\":\"主語が三人称単数なので動詞に s を付けるという習慣が働き、will のうしろの live にも s を付けてしまう。\",\"correctAnswer\":\"My sister will live in Osaka next year.\",\"correctExplanation\":\"助動詞のうしろは必ず原形なので、三単現の s は付かない。will 自身も wills にはならない。三単現の s は「助動詞のない現在の文」だけのルールだと、can の課で学んだことをそのまま当てはめる。\"},{\"question\":\"「私は今日の午後、買い物に行く予定です（前から決めていた）。」を英語にしなさい。\",\"wrongAnswer\":\"I will go shopping this afternoon.\",\"trapExplanation\":\"「〜する予定です」という日本語をすべて will で表せると思ってしまう。前から決めていたのか、その場で決めたのかという区別を意識していない。\",\"correctAnswer\":\"I am going to go shopping this afternoon.\",\"correctExplanation\":\"前もって決めてある予定は be going to で表すのが自然。will はその場で決めた意志や、単なる予想に使う。問題文に「前から決めていた」「〜する予定だ」とあれば be going to を選ぶ。\"}]}",
"{\"id\":\"eigo_s172\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"would①：would like to（ていねいな「〜したい」）\",\"description\":\"want の代わりに使う would like / would like to の形と会話での使い方を覚える\",\"intro\":\"お店で I want a hamburger. と言っても通じますが、子どもっぽく聞こえます。大人は I'd like a hamburger. と言うのがふつうです。would like は want のていねいな言いかえで、would like to 〜 なら「〜したいのですが」になります。注文の場面で必ず出てくる形です。\",\"order\":672,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"would like ＋ 名詞 ＝「〜がほしいのですが」。want のていねいな言い方。\",\"would like to ＋ 動詞の原形 ＝「〜したいのですが」。\",\"短縮形は I'd like 〜。主語が何でも would の形は変わらない。\",\"Would you like 〜? ＝「〜はいかがですか」とすすめる言い方。\",\"すすめられたときの返事は Yes, please. / No, thank you.。\"],\"sections\":[{\"heading\":\"would like と would like to\",\"body\":\"want（〜がほしい・〜したい）は、そのまま使うと少し直接的でぶっきらぼうに聞こえることがある。店や初対面の人との会話では、would like を使うとていねいになる。\\n\\n■ would like ＋ 名詞（〜がほしいのですが）\\n例）I would like a cup of tea.（紅茶を一杯いただきたいのですが）\\n例）I'd like this one, please.（これをください）\\n短縮形は I'd like。会話文ではほとんどこの形で出る。\\n\\n■ would like to ＋ 動詞の原形（〜したいのですが）\\n例）I would like to go with you.（あなたといっしょに行きたいのですが）\\n例）I'd like to ask you a question.（質問したいのですが）\\nto のうしろは必ず原形。× I'd like to going は誤り。\\n\\n■ 主語がかわっても形は同じ\\nHe would like to see you.（彼はあなたに会いたがっています）\\nwould は助動詞なので、三人称単数でも would のまま。\\n\\n■ want との比較\\nI want some water.（水がほしい）…友達や家族に\\nI'd like some water.（お水をいただけますか）…店員や目上の人に\\n意味はほぼ同じで、ていねいさがちがう。\\n\\n★ ポイント：would like ＝ want、would like to ＝ want to。この対応を覚えておけば、書きかえ問題は一瞬で解ける。\",\"figureId\":\"xf_eigo_s172\"},{\"heading\":\"Would you like 〜? とその答え方\",\"body\":\"相手に何かをすすめるときは Would you like 〜? を使う。レストランや家庭でのもてなしの場面として頻出する。\\n\\n■ Would you like ＋ 名詞?（〜はいかがですか）\\n例）Would you like some tea?（お茶はいかがですか）\\n例）Would you like another piece of cake?（ケーキをもう一つどうぞ）\\n\\n■ Would you like to ＋ 原形?（〜しませんか）\\n例）Would you like to come to my house?（うちに来ませんか）\\n例）Would you like to join us?（私たちに加わりませんか）\\n\\n■ 答え方\\nYes, please.（はい、お願いします）\\nNo, thank you.（いいえ、けっこうです）\\nYes, I'd love to.（ぜひ）※to のあとに動詞を続けない形で使う\\nすすめられたときに Yes, I do. や Yes, I want. と答えるのは誤りである。\\n\\n■ ていねいな疑問文で使う some\\nふつう疑問文では any を使うが、すすめる文では some を使う。\\n例）Would you like some coffee?（× any coffee）\\nこれは「相手が yes と答えることを期待している」ときの決まりで、Would you like 〜? のほか How about some 〜? でも同じである。\\n\\n⚠ 注意：Would you like to 〜?（〜しませんか）と Would you 〜?（〜してくれませんか）はまったく別の意味。like to があるかないかで、相手にすすめているのか、頼んでいるのかが変わる。\",\"mangaId\":\"eigo_s172_xm\"}],\"trapExamples\":[{\"question\":\"Would you like some tea? に「はい、お願いします」と答えなさい。\",\"wrongAnswer\":\"Yes, I want.\",\"trapExplanation\":\"would like ＝ want と覚えているため、答えにも want を使ってしまう。またすすめられたときの決まり文句を知らない。\",\"correctAnswer\":\"Yes, please.\",\"correctExplanation\":\"何かをすすめられたときは Yes, please.（はい、お願いします）／ No, thank you.（いいえ、けっこうです）で答えるのが決まり。Yes, I want. は英語として不自然で、want を使うなら Yes, I want some tea. と目的語まで必要になる。\"},{\"question\":\"店員に「この赤いシャツがほしいのですが」とていねいに伝える文を書きなさい。\",\"wrongAnswer\":\"I want this red shirt.\",\"trapExplanation\":\"「ほしい」＝ want と直訳してしまう。文法としては誤りではないが、店員に対しては直接的でぶっきらぼうな言い方になる。\",\"correctAnswer\":\"I'd like this red shirt.（I would like this red shirt.）\",\"correctExplanation\":\"店や初対面の人との会話では、want の代わりに would like を使うとていねいになる。動詞を続けたいときは would like to ＋ 原形（I'd like to try it on. 試着したいのですが）。会話文の問題では、場面に合うていねいさが問われる。\"}]}",
"{\"id\":\"eigo_s173\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"would②：Will you 〜? と Would you 〜?（依頼）\",\"description\":\"相手にものを頼む言い方を、ていねいさの度合いとともに整理する\",\"intro\":\"Will you open the door? と Would you open the door? — どちらも「開けてくれますか」ですが、後者のほうがていねいです。英語では、遠回しな言い方ほどていねいに響くという性質があります。頼み方の強さを、目盛りの上にならべて整理していきましょう。\",\"order\":673,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Will you 〜? ＝「〜してくれますか」。Would you 〜? はそのていねい版。\",\"ていねいさは Will / Can ＜ Would / Could の順で強くなる。\",\"承諾は Sure. / All right. / Of course.、断りは I'm sorry, I can't.。\",\"Would you 〜?（依頼）と Would you like to 〜?（勧誘）は別物。\",\"「私が〜しましょうか」は Shall I 〜? で、Will you 〜? ではない。\"],\"sections\":[{\"heading\":\"依頼の Will you 〜? / Would you 〜?\",\"body\":\"相手に何かをしてもらいたいときは、will や would を使って頼むことができる。\\n\\n■ Will you 〜?（〜してくれませんか）\\n例）Will you open the window?（窓を開けてくれませんか）\\n例）Will you help me with my homework?（宿題を手伝ってくれませんか）\\n友達や家族に対して使うくだけた言い方。\\n\\n■ Would you 〜?（〜していただけませんか）\\n例）Would you close the door?（ドアを閉めていただけませんか）\\n例）Would you say that again?（もう一度言っていただけませんか）\\nwould は will のていねいな形で、目上の人や初対面の人に使う。\\n\\n■ ていねいさの順\\nWill you 〜? ／ Can you 〜?（友達に）\\nWould you 〜? ／ Could you 〜?（目上の人に）\\nさらにていねいにしたいときは、文の終わりに please を付ける。\\n例）Would you help me, please?\\n\\n■ 答え方\\n承諾：Sure. ／ All right. ／ OK. ／ Of course. ／ Certainly.\\n断り：I'm sorry, I can't. ／ Sorry, I'm busy now.\\nYes, I will. と答えることもできるが、会話では Sure. のほうが自然に響く。\\n\\n★ ポイント：頼まれごとを引き受ける返事は Sure. の一語で足りる。会話文の空所補充で最もよく問われる語である。\",\"figureId\":\"lf_eigoext05_173\"},{\"heading\":\"まぎらわしい形の区別\",\"body\":\"would を使う文は形が似ているため、意味を取りちがえやすい。次の三つをはっきり区別する。\\n\\n■ Would you 〜?（依頼）\\nWould you open the window?（窓を開けていただけませんか）\\n→ 動作をするのは相手（you）。\\n\\n■ Would you like 〜? / Would you like to 〜?（勧誘・すすめ）\\nWould you like some coffee?（コーヒーはいかがですか）\\nWould you like to open the window?（窓を開けたいですか＝開けてもよいですよ）\\n→ 相手の希望をたずねている。頼んでいるのではない。\\n\\n■ Shall I 〜?（申し出）\\nShall I open the window?（（私が）窓を開けましょうか）\\n→ 動作をするのは自分（I）。\\n\\n三つとも窓を開ける話だが、開けるのがだれか、そして頼んでいるのか申し出ているのかがまったくちがう。英作文では「動作をするのはだれか」を先に決めるとまちがえない。\\n\\n■ 会話の流れの例\\nA: It's hot in here. Would you open the window?（暑いですね。窓を開けていただけますか）\\nB: Sure. No problem.（もちろんです）\\n\\nA: It's hot in here.（暑いですね）\\nB: Shall I open the window?（窓を開けましょうか）\\nA: Yes, please.（はい、お願いします）\\n\\n⚠ 注意：Would you like to 〜? を「〜してくれませんか」と訳す誤りが非常に多い。like to があれば「〜したいですか・〜しませんか」と、相手の気持ちをたずねる文である。\",\"mangaId\":\"eigo_s173_xm\"}],\"trapExamples\":[{\"question\":\"「（あなたの）かばんを持ちましょうか。」と申し出る文を英語にしなさい。\",\"wrongAnswer\":\"Will you carry my bag?\",\"trapExplanation\":\"日本語の「〜しましょうか」に主語がないため、覚えている依頼の型をそのまま使ってしまう。Will you 〜? では「私のかばんを運んでくれませんか」と、相手に頼む文になってしまう。\",\"correctAnswer\":\"Shall I carry your bag?\",\"correctExplanation\":\"運ぶのは自分なので主語は I。「（私が）〜しましょうか」という申し出は Shall I 〜? を使う。答えは Yes, please. / No, thank you.。相手に頼むなら Will you carry my bag? となり、意味が正反対になる。\"},{\"question\":\"「このいすを運んでいただけませんか。」を英語にしなさい。\",\"wrongAnswer\":\"Would you like to carry this chair?\",\"trapExplanation\":\"Would you like 〜? をていねいな依頼の形として覚えているため、like to を付けたままにしてしまう。実際には「このいすを運びたいですか」と相手の希望をたずねる文になる。\",\"correctAnswer\":\"Would you carry this chair?（Could you carry this chair? も可）\",\"correctExplanation\":\"依頼は Would you ＋ 動詞の原形 〜?。like to が入ると勧誘・希望をたずねる文に変わってしまう。Would you 〜?（していただけますか）と Would you like to 〜?（〜しませんか）を、形と意味の両方で区別する。\"}]}",
"{\"id\":\"eigo_s174\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Shall I 〜?：「（私が）〜しましょうか」の申し出\",\"description\":\"自分が何かをしてあげると申し出る Shall I 〜? の形と答え方を身につける\",\"intro\":\"Shall I carry your bag? は「私がかばんを持ちましょうか」という申し出です。ところがこれを、いっしょに持とうという意味だと勘ちがいして Shall we 〜? と混同する人が多くいます。だれがその動作をするのかが、I と we で分かれます。まずは Shall I から確かめます。\",\"order\":674,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Shall I ＋ 動詞の原形 〜? ＝「（私が）〜しましょうか」という申し出。\",\"答えは Yes, please.（お願いします）／ No, thank you.（けっこうです）。\",\"Shall I 〜? に Yes, let's. と答えるのは誤り。\",\"同じ意味で Do you want me to 〜? や Can I help you? も使う。\",\"Shall you 〜? という言い方はない。相手に頼むのは Will / Could you 〜?。\"],\"sections\":[{\"heading\":\"Shall I 〜? の形と場面\",\"mangaId\":\"eigo_s174_shall_manga\",\"body\":\"Shall I 〜? は「（私が）〜しましょうか」と、自分から手助けを申し出る言い方である。困っている人を見かけたときの決まり文句として、会話問題で頻出する。\\n\\n例）Shall I open the window?（窓を開けましょうか）\\n例）Shall I carry your bag?（かばんをお持ちしましょうか）\\n例）Shall I help you?（お手伝いしましょうか）\\n例）Shall I call a taxi for you?（タクシーを呼びましょうか）\\n\\n■ うしろは動詞の原形\\nshall も助動詞なので、うしろは原形。× Shall I to help you? は誤り。\\n\\n■ 答え方\\nYes, please.（はい、お願いします）\\nNo, thank you. I'm all right.（いいえ、けっこうです。だいじょうぶです）\\nThank you. That's very kind of you.（ありがとうございます。ご親切に）\\nShall I 〜? は自分がすることを申し出ているので、Yes, let's.（そうしましょう）とは答えない。let's は「いっしょにしよう」という意味だからである。\\n\\n★ ポイント：Shall I 〜? は主語が I。「私が動く」と決まっているので、答えは「お願いします／けっこうです」になる。ここを取りちがえると会話問題を一問落とす。\",\"figureId\":\"xf_eigo_s174\"},{\"heading\":\"似た意味の言い方\",\"body\":\"申し出の言い方はいくつかある。場面に応じて選べるようにしておく。\\n\\n■ Shall I 〜?（〜しましょうか）\\n少しかたい、ていねいな申し出。\\n\\n■ Can I help you? / May I help you?\\n店員がお客に「いらっしゃいませ、何かお探しですか」と声をかける定番。困っている人に「お手伝いしましょうか」と言うときにも使う。\\n\\n■ Do you want me to 〜?（〜してほしいですか）\\n友達どうしのくだけた言い方。\\n例）Do you want me to help you?\\n\\n■ Let me 〜.（〜させてください）\\n例）Let me help you.（お手伝いさせてください）\\n\\n■ 会話の流れの例\\nA: This box is very heavy.（この箱、とても重いんです）\\nB: Shall I help you?（お手伝いしましょうか）\\nA: Yes, please. Thank you very much.（はい、お願いします。ありがとうございます）\\n\\nA: Shall I turn on the light?（電気をつけましょうか）\\nB: No, thank you. It's still bright.（いいえ、けっこうです。まだ明るいので）\\n\\n⚠ 注意：相手にしてもらいたいときに Shall you 〜? とは言わない。英語に Shall you 〜? という依頼の形は存在しないので、Will you 〜? / Can you 〜? / Could you 〜? を使う。\"}],\"trapExamples\":[{\"question\":\"Shall I open the window? に「はい、お願いします」と答えなさい。\",\"wrongAnswer\":\"Yes, let's.\",\"trapExplanation\":\"Shall で始まる疑問文の答えは Yes, let's. だと丸暗記しているため、Shall I と Shall we の区別をせずに答えてしまう。\",\"correctAnswer\":\"Yes, please.\",\"correctExplanation\":\"Shall I 〜? は「（私が）〜しましょうか」という申し出なので、答えは Yes, please.（お願いします）／ No, thank you.（けっこうです）。Yes, let's. と答えるのは Shall we 〜?（いっしょに〜しましょうか）に対してである。\"},{\"question\":\"「（あなたが）私を手伝ってくれませんか。」を英語にしなさい。\",\"wrongAnswer\":\"Shall you help me?\",\"trapExplanation\":\"Shall I 〜? を「手伝いましょうか」と覚えているため、主語だけ you に変えれば「手伝ってくれますか」になると考えてしまう。\",\"correctAnswer\":\"Will you help me?（Can you 〜? / Could you 〜? も可）\",\"correctExplanation\":\"英語に Shall you 〜? という依頼の形はない。相手に何かを頼むときは Will you / Can you / Would you / Could you を使う。shall が使えるのは Shall I 〜?（申し出）と Shall we 〜?（誘い）の二つの形だと覚えておく。\"}]}",
"{\"id\":\"eigo_s175\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Shall we 〜? と Let's 〜.：いっしょにしようと誘う\",\"description\":\"相手を誘う二つの言い方の形をおさえ、否定の Let's not まで正しく書けるようにする\",\"intro\":\"Shall we dance? は「いっしょにおどりませんか」。Shall I dance? なら「私がおどりましょうか」で、意味がまるでちがいます。一語のちがいで、さそいにも申し出にも変わるのです。Let's 〜. への言いかえや、否定の Let's not 〜. までまとめて扱います。\",\"order\":675,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Shall we ＋ 原形 〜? ＝「いっしょに〜しましょうか」。\",\"Let's ＋ 原形 ＝「〜しましょう」。Let's は Let us の短縮形。\",\"Let's のうしろも動詞の原形（× Let's to go／× Let's going）。\",\"否定は Let's not ＋ 原形 ＝「〜するのはやめましょう」。\",\"Shall we 〜? ＝ Let's 〜. ＝ Why don't we 〜? はほぼ同じ意味。\"],\"sections\":[{\"heading\":\"Shall we 〜? と Let's 〜. の形\",\"body\":\"相手をさそって「いっしょに〜しよう」と言う言い方は二つある。どちらも会話問題と書きかえ問題の定番である。\\n\\n■ Shall we ＋ 動詞の原形 〜?\\n例）Shall we play tennis after school?（放課後にテニスをしませんか）\\n例）Shall we go to the museum?（博物館に行きましょうか）\\n少していねいで、相手の気持ちをうかがうひびきがある。\\n\\n■ Let's ＋ 動詞の原形.\\n例）Let's play tennis after school.（放課後にテニスをしよう）\\n例）Let's go to the museum.\\nLet's は Let us の短縮形。うしろは必ず動詞の原形で、疑問文ではないのでピリオドで終わる。\\n× Let's to play ／ × Let's playing はどちらも誤り。\\n\\n■ 否定「〜するのはやめよう」\\n例）Let's not talk about it.（その話はやめよう）\\n例）Let's not go out today. It's raining.\\nnot は Let's のうしろに置く。× Let's don't go. は誤りである。\\n\\n■ 書きかえ\\nShall we go shopping? ＝ Let's go shopping. ＝ Why don't we go shopping?\\nどれもほぼ同じ意味で、書きかえ問題でそのまま出題される。\\n\\n★ ポイント：Shall we 〜? は疑問文なので ? で終わり、Let's 〜. は誘いかける文なので . で終わる。書き終えたら文末の記号を確認する。\",\"figureId\":\"xf_eigo_s175\",\"mangaId\":\"eigo_s175_xm\"},{\"heading\":\"答え方と会話での使い方\",\"body\":\"さそわれたときの返事も決まっている。丸ごと覚えてしまえば得点源になる。\\n\\n■ Shall we 〜? / Let's 〜. への返事\\n賛成：Yes, let's.（そうしましょう）\\n　　　That's a good idea. ／ Sounds good. ／ Sure.\\n断り：No, let's not.（やめておきましょう）\\n　　　I'm sorry, I can't. I have to study today.\\n\\nYes, let's. は Shall we 〜? と Let's 〜. のどちらに対しても使える返事である。一方、Shall I 〜?（私がしましょうか）に対しては使えない。\\n\\n■ 会話の流れの例\\nA: Shall we have lunch together?（いっしょにお昼を食べませんか）\\nB: Yes, let's. Where shall we go?（そうしましょう。どこへ行きましょうか）\\nA: How about the new cafe near the station?（駅の近くの新しいカフェはどう）\\nB: Sounds good.（いいですね）\\n\\n■ Let's 〜, shall we? という形\\n例）Let's go, shall we?（行きましょうよ、ね）\\nLet's の文につける付加疑問は shall we? である。これは付加疑問の課でもう一度確認する。\\n\\n⚠ 注意：「〜しましょう」と「〜しましょうか（私が）」は日本語では一字ちがいだが、英語では Let's / Shall we（いっしょに）と Shall I（私が）に分かれる。だれが動くのかを必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"「放課後にサッカーをしましょう。」を英語にしなさい。\",\"wrongAnswer\":\"Let's to play soccer after school.\",\"trapExplanation\":\"Let's を「〜すること」を導く語のように感じてしまい、to を続けてしまう。want to play などの形にもつられる。\",\"correctAnswer\":\"Let's play soccer after school.\",\"correctExplanation\":\"Let's は Let us の短縮形で、うしろは動詞の原形が続く。× Let's to play も × Let's playing も誤り。同じ意味の Shall we play soccer after school? も、shall のうしろが原形である点は同じ。\"},{\"question\":\"「今日は出かけるのはやめましょう。」を英語にしなさい。\",\"wrongAnswer\":\"Let's don't go out today.\",\"trapExplanation\":\"否定文は don't を使うという一般動詞のルールをそのまま当てはめてしまう。Let's の否定形を習っていないと必ずこの形になる。\",\"correctAnswer\":\"Let's not go out today.\",\"correctExplanation\":\"Let's の否定は「Let's not ＋ 動詞の原形」。don't は使わない。Let's not talk about it.（その話はやめよう）のように、not の位置は Let's のすぐうしろで固定である。\"}]}",
"{\"id\":\"eigo_s176\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"提案・申し出への答え方のまとめ\",\"description\":\"Shall I / Shall we / Let's / Would you like への返事を、場面ごとに正しく選べるようにする\",\"intro\":\"「手伝いましょうか」と言われて「はい、お願いします」と返すとき、英語では Yes, please. です。ところが Shall we 〜? に対しては Yes, let's. と答えます。同じ「はい」でも、たずね方によって決まった返しが変わるのです。場面ごとに対で覚えていきましょう。\",\"order\":676,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Shall I 〜?（私がしましょうか）→ Yes, please. / No, thank you.\",\"Shall we 〜? / Let's 〜.（いっしょにしよう）→ Yes, let's. / No, let's not.\",\"Would you like 〜?（いかがですか）→ Yes, please. / No, thank you.\",\"Can you 〜? / Could you 〜?（してくれますか）→ Sure. / I'm sorry, I can't.\",\"断るときは理由を一言そえると自然になる。\"],\"sections\":[{\"heading\":\"「だれがするか」で返事が決まる\",\"body\":\"会話問題では、さそわれた・すすめられた・頼まれた場面での返事を選ばせる問題が必ず出る。返事の形は「動作をするのはだれか」で決まる。\\n\\n■ 自分がする（相手の申し出を受ける）\\nShall I 〜? ／ Would you like 〜? ／ May I help you?\\n→ Yes, please.（はい、お願いします）\\n→ No, thank you.（いいえ、けっこうです）\\n\\n■ いっしょにする（さそいに応じる）\\nShall we 〜? ／ Let's 〜. ／ Why don't we 〜?\\n→ Yes, let's.（そうしましょう）\\n→ No, let's not.（やめておきましょう）\\n→ That's a good idea. ／ Sounds good.\\n\\n■ 相手がする（頼まれごとを引き受ける）\\nCan you 〜? ／ Will you 〜? ／ Could you 〜? ／ Would you 〜?\\n→ Sure. ／ Of course. ／ All right. ／ Certainly.\\n→ I'm sorry, I can't.\\n\\n★ ポイント：Yes, please. は「してもらう」とき、Yes, let's. は「いっしょにする」とき、Sure. は「してあげる」とき。三つを場面とセットで覚える。\",\"figureId\":\"xf_eigo_s176\",\"mangaId\":\"eigo_s176_xm\"},{\"heading\":\"自然な断り方\",\"body\":\"英語では、断るときにただ No. とだけ言うのはぶっきらぼうに聞こえる。「ごめんなさい」と「理由」をそえるのが基本の形である。\\n\\n■ 断りの基本の型\\nI'm sorry, but ＋ 理由.\\n例）I'm sorry, but I have to help my mother.（すみません、母を手伝わなければならなくて）\\n例）Sorry, I can't. I have a piano lesson today.（ごめん、無理なんだ。今日はピアノのレッスンがあって）\\n例）Thank you, but I'm busy this afternoon. Maybe next time.（ありがとう、でも今日の午後はいそがしくて。また今度ね）\\n\\n■ お礼をそえる断り方\\nNo, thank you. I'm all right.（いいえ、けっこうです。だいじょうぶです）\\nThat's very kind of you, but I can do it myself.（ご親切にありがとうございます。でも自分でできます）\\n\\n■ 会話の流れの例\\nA: Shall we go to the movies this Sunday?（今度の日曜、映画に行きませんか）\\nB: I'm sorry, I can't. I'm going to visit my grandmother.（ごめんなさい、行けません。祖母の家に行く予定なんです）\\nA: That's too bad. How about next Sunday?（残念。来週の日曜はどうですか）\\nB: Sounds good.（いいですね）\\n\\n⚠ 注意：That's too bad.（それは残念ですね）は相手の残念な知らせに対する決まり文句である。「それはとても悪い」と直訳しないよう気をつける。\"}],\"trapExamples\":[{\"question\":\"Shall I help you with your homework? に「はい、お願いします」と答えなさい。\",\"wrongAnswer\":\"Yes, let's.\",\"trapExplanation\":\"shall という語だけを見て、いっしょに何かをする誘いだと思ってしまう。Shall I は「私が手伝いましょうか」という申し出である。\",\"correctAnswer\":\"Yes, please.\",\"correctExplanation\":\"手伝うのは相手なので、こちらは「お願いします」と受ける。Yes, please. / No, thank you. が正しい返事。Yes, let's. は「いっしょにやりましょう」という意味なので、Shall we 〜? や Let's 〜. への返事になる。\"},{\"question\":\"Let's play catch in the park. に「そうしましょう」と答えなさい。\",\"wrongAnswer\":\"Yes, please.\",\"trapExplanation\":\"賛成の返事はすべて Yes, please. だと思いこんでいる。Let's は「いっしょにやろう」という誘いなので、please（お願いします）では意味が合わない。\",\"correctAnswer\":\"Yes, let's.\",\"correctExplanation\":\"Let's 〜. や Shall we 〜? のように「いっしょにしよう」と誘われたときは Yes, let's.（そうしましょう）／ No, let's not.（やめておきましょう）で答える。Yes, please. は相手が自分のために何かをしてくれるときの返事である。\"}]}",
"{\"id\":\"eigo_s177\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Could you 〜?：ていねいに人にものを頼む\",\"description\":\"Could you 〜? の意味と語順をおさえ、道をたずねる場面の会話に強くなる\",\"intro\":\"道でこまったとき、Where is the station? だけでは、ぶっきらぼうに聞こえます。Could you tell me the way to the station? と言えば、ぐっとていねいになります。この could は「できた」という過去の意味ではなく、遠慮のひびきを出すために使われているのです。\",\"order\":677,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Could you ＋ 原形 〜? ＝「〜していただけませんか」。過去の意味ではない。\",\"Can you 〜? よりていねい。初対面の人や目上の人に使う。\",\"Could you tell me the way to 〜? は道をたずねる決まり文句。\",\"tell me のあとに疑問文が続くときは「主語＋動詞」の語順になる。\",\"承諾は Sure. / Certainly.、断りは I'm sorry, I can't.。\"],\"sections\":[{\"heading\":\"Could you 〜? の意味と使い方\",\"body\":\"could は can の過去形だが、Could you 〜? という疑問文では過去の意味にならない。「〜していただけませんか」という、ていねいな依頼になる。\\n\\n例）Could you help me?（手伝っていただけませんか）\\n例）Could you say that again?（もう一度言っていただけませんか）\\n例）Could you speak more slowly?（もっとゆっくり話していただけませんか）\\n例）Could you show me your ticket?（切符を見せていただけますか）\\n\\n■ ていねいさの階段\\nCan you 〜?（〜してくれる？）…友達に\\nWill you 〜?（〜してくれますか）…友達・家族に\\nCould you 〜?（〜していただけませんか）…目上の人・初対面の人に\\nWould you 〜?（〜していただけませんか）…同じくていねい\\nさらに please を付けると、よりていねいになる。\\n例）Could you open the door, please?\\n\\n■ 答え方\\n承諾：Sure. ／ Certainly. ／ Of course. ／ All right.\\n断り：I'm sorry, I can't. ／ I'm afraid I can't.\\nYes, I could. とは答えない。could をそのまま返すと不自然になるので、Sure. などを使う。\\n\\n★ ポイント：Could you 〜? を「〜できましたか」と訳すと意味が通らなくなる。疑問文の Could you / Would you はていねいさを表す形だと覚える。\"},{\"heading\":\"道をたずねる会話\",\"body\":\"Could you 〜? は、道をたずねる場面の会話としてよく出題される。型ごと覚えてしまうのが早い。\\n\\n■ たずねる言い方\\nExcuse me. Could you tell me the way to the station?（すみません、駅へ行く道を教えていただけませんか）\\nCould you tell me how to get to the museum?（博物館への行き方を教えていただけますか）\\nWhere is the post office?（郵便局はどこですか）\\n\\n■ 答え方\\nGo straight along this street.（この通りをまっすぐ行ってください）\\nTurn right at the second corner.（二つ目の角を右に曲がってください）\\nYou'll see it on your left.（左手に見えますよ）\\nIt's about five minutes' walk.（歩いて五分ほどです）\\nI'm sorry, I'm a stranger here.（すみません、このあたりは不案内なんです）\\n\\n■ 語順の注意\\nCould you tell me のあとに「どこ・いつ・何」をたずねる文を続けるときは、疑問文の語順にしない。\\n○ Could you tell me where the station is?\\n× Could you tell me where is the station?\\ntell me のうしろは「疑問詞＋主語＋動詞」の順になる。これを間接疑問といい、上位校で問われる。\\n\\n⚠ 注意：道案内の答えは命令文（Go / Turn）で表す。これは次の命令文の課とつながる。「行ってください」とていねいに言うときは、文末に please を付ける。\",\"figureId\":\"xf_eigo_s177\",\"mangaId\":\"eigo_s177_xm\"}],\"trapExamples\":[{\"question\":\"次の英文を日本語にしなさい。「Could you carry this box for me?」\",\"wrongAnswer\":\"あなたは私のためにこの箱を運ぶことができましたか。\",\"trapExplanation\":\"could ＝ can の過去形と覚えているため、疑問文でも過去の意味に訳してしまう。ていねいな依頼の形であることを知らないと必ず引っかかる。\",\"correctAnswer\":\"この箱を運んでいただけませんか。\",\"correctExplanation\":\"Could you 〜? / Would you 〜? は過去ではなく、ていねいな依頼を表す。Can you 〜? のていねい版と考える。答えるときも Sure. / Certainly. / I'm sorry, I can't. を使い、Yes, I could. とは言わない。\"},{\"question\":\"「駅がどこにあるか教えていただけませんか。」を英語にしなさい。\",\"wrongAnswer\":\"Could you tell me where is the station?\",\"trapExplanation\":\"Where is the station? という疑問文の形をそのまま文の中に入れてしまう。文の中に入る疑問文は語順が変わることを知らない。\",\"correctAnswer\":\"Could you tell me where the station is?\",\"correctExplanation\":\"tell me / know / ask のあとに疑問詞の文が続くときは、「疑問詞＋主語＋動詞」というふつうの語順に戻す（間接疑問）。Do you know what this is?（× what is this）も同じ仕組みである。\"}]}",
"{\"id\":\"eigo_s178\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"May I 〜? / Could I 〜?：ていねいに許可を求める\",\"description\":\"自分が何かをする許しを求める言い方を、場面と語法の両面から身につける\",\"intro\":\"写真をとってよいか聞くとき、Can I take a picture? でも通じますが、初めて会う人には May I take a picture? のほうが安心です。どちらも自分が動作をする許可を求める形。ていねいさの度合いと、場面に合った選び方を身につけます。\",\"order\":678,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"May I 〜? / Could I 〜? ＝「〜してもよろしいですか」。主語は I。\",\"ていねいさは Can I ＜ May I ≒ Could I の順。\",\"use（その場で使う）と borrow（借りて持っていく）を使い分ける。\",\"電話の May I speak to 〜? への返事は Speaking. / Just a moment, please.\",\"断るときは I'm sorry, but 〜 とやわらげる。\"],\"sections\":[{\"heading\":\"許可を求める三つの言い方\",\"body\":\"自分が何かをしたいとき、相手に許しを求める言い方は三つある。どれも主語は I である。\\n\\n■ Can I 〜?（〜してもいい？）\\n例）Can I use your eraser?（消しゴムを使ってもいい？）友達に。\\n\\n■ May I 〜?（〜してもよろしいですか）\\n例）May I come in?（入ってもよろしいですか）先生や目上の人に。\\n\\n■ Could I 〜?（〜させていただけますか）\\n例）Could I use your phone?（電話をお借りできますか）May I と同じくらいていねい。\\n\\n■ 答え方\\n承諾：Sure. ／ Of course. ／ Certainly. ／ Go ahead.（どうぞ）\\n断り：I'm sorry, but you can't. ／ I'm afraid not.\\nNo, you may not. は強くはねつける言い方なので、ふつうは I'm sorry を付けてやわらげる。\\n\\n■ use と borrow のちがい\\nuse ＝ その場で使う（電話・トイレ・辞書など動かさないもの）\\nborrow ＝ 借りて自分のところへ持っていく（本・かさ・自転車など）\\n例）May I use the bathroom?（トイレをお借りしてもよいですか）\\n例）May I borrow your umbrella?（かさを借りてもよいですか）\\n日本語ではどちらも「借りる」と言うので、取りちがえやすい。\\n\\n★ ポイント：May I 〜? は自分がする、Could you 〜? は相手がする。I と you のどちらで始まるかが意味を決める。\",\"figureId\":\"xf_eigo_s178\",\"mangaId\":\"eigo_s178_xm\"},{\"heading\":\"電話と訪問の会話\",\"body\":\"May I 〜? は電話の会話でも決まり文句になっている。並べかえや応答選択で頻出する。\\n\\n■ 電話をかける側\\nHello. This is Ken.（もしもし、ケンです）※ I am Ken. とは言わない\\nMay I speak to Mr. Brown, please?（ブラウンさんをお願いします）\\nCould I leave a message?（伝言をお願いできますか）\\n\\n■ 電話を受ける側\\nSpeaking.（私です）\\nJust a moment, please. ／ Hold on, please.（少々お待ちください）\\nI'm sorry, he is out now.（すみません、いま外出しています）\\nShall I take a message?（ご伝言をうかがいましょうか）\\nCan I call you back later?（あとでかけ直してもよいですか）\\n\\n■ 家をたずねる場面\\nMay I come in?（入ってもよろしいですか）\\n— Sure. Please come in.（どうぞお入りください）\\nPlease make yourself at home.（どうぞ楽になさってください）\\n\\n⚠ 注意：電話で自分の名前を言うときは This is Ken (speaking). と言う。I am Ken. は目の前の相手に自己紹介するときの言い方で、電話では使わない。また相手をたずねるときは Who are you? ではなく May I ask who is calling? や Who's calling, please? を使う。\"}],\"trapExamples\":[{\"question\":\"ホームステイ先で「トイレをお借りしてもよろしいですか」とたずねる文を書きなさい。\",\"wrongAnswer\":\"May I borrow the bathroom?\",\"trapExplanation\":\"日本語の「借りる」をそのまま borrow に置きかえてしまう。borrow は「持っていって使う」ことなので、トイレには使えない。\",\"correctAnswer\":\"May I use the bathroom?\",\"correctExplanation\":\"その場から動かせないもの（トイレ・電話・辞書をその場で見るなど）は use、持っていって使えるもの（本・かさ・自転車）は borrow を使う。「借りる」という日本語にまどわされず、動かすかどうかで判断する。\"},{\"question\":\"電話で May I speak to Tom, please? と言われた。自分がトムのとき、どう答えるか。\",\"wrongAnswer\":\"Yes, you may.\",\"trapExplanation\":\"May I 〜? に対する答えは Yes, you may. だと機械的に覚えているため、電話特有の受け答えがあることに気づかない。\",\"correctAnswer\":\"Speaking.（This is Tom speaking. も可）\",\"correctExplanation\":\"電話で「私です」と伝えるときは Speaking. または This is he / This is Tom speaking. と言う。相手が不在なら I'm sorry, he is out now.、取りつぐなら Just a moment, please. が定番。電話の会話は場面ごと丸ごと覚える。\"}]}",
"{\"id\":\"eigo_s179\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"依頼と許可の整理（だれがするか × ていねいさ）\",\"description\":\"I で始まる許可と you で始まる依頼を二つの軸で整理し、正しく選べるようにする\",\"intro\":\"Can I 〜? と Can you 〜?、May I 〜? と Would you 〜?。似た形がならぶと、どれを使えばよいか分からなくなります。実は「だれがするか」と「どれくらいていねいか」の二つの軸でならべると、きれいに整理できます。表にして一気に見わたしましょう。\",\"order\":679,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"主語が I なら許可（自分がする）、you なら依頼（相手がする）。\",\"ていねいさは can → may / will → could / would の順に上がる。\",\"Would you mind 〜ing? は「〜していただけませんか」でうしろは -ing 形。\",\"Would you mind 〜? への承諾は No, not at all.（否定で「いいですよ」）。\",\"英作文では「動作をするのはだれか」を先に決めてから助動詞を選ぶ。\"],\"sections\":[{\"heading\":\"二つの軸で表現を整理する\",\"body\":\"依頼と許可の表現はよく似た形をしているので、二つの軸で位置づけると混乱しなくなる。\\n\\n■ 軸① だれが動作をするか\\n自分がする（許可を求める）：Can I 〜? ／ May I 〜? ／ Could I 〜?\\n相手がする（依頼する）：Can you 〜? ／ Will you 〜? ／ Could you 〜? ／ Would you 〜?\\n\\n■ 軸② どのくらいていねいか\\nくだけた ← Can ／ Will → May ／ Would ／ Could → ていねい\\n\\n■ 組み合わせて覚える\\nCan I use your pen?（ペン借りていい？）友達に、自分がする\\nCould I use your pen?（ペンをお借りできますか）目上の人に、自分がする\\nCan you pass me the salt?（塩取って）友達に、相手がする\\nCould you pass me the salt?（塩を取っていただけますか）目上の人に、相手がする\\n\\n四つとも「ペン」「塩」の話だが、だれが動くのか、どのくらいていねいかがちがう。英作文では、まず日本語を読んで「動くのはだれか」を決め、次に「相手はだれか」でていねいさを決める、という二段階で考える。\\n\\n★ ポイント：日本語の「〜してもいい？」は自分が動く、「〜してくれる？」は相手が動く。助詞の少ない短い日本語ほど、動作主を落ち着いて確かめる。\",\"figureId\":\"lf_eigoext05_179\"},{\"heading\":\"Would you mind 〜? の答え方\",\"body\":\"上位校や英検準二級で出る、少し変わった依頼の言い方が Would you mind 〜? である。\\n\\n■ 形\\nWould you mind ＋ 動詞の -ing 形?\\n例）Would you mind opening the window?（窓を開けていただけませんか）\\n例）Would you mind waiting here?（ここで待っていただけますか）\\nmind は「いやだと思う」という意味の動詞で、直訳すると「〜するのをいやだと思いますか」となる。\\n\\n■ 答え方が逆になる\\n承諾（いいですよ）：No, not at all. ／ Of course not. ／ Certainly not.\\n断り（申し訳ないが）：I'm sorry, but 〜\\n「いやだと思いますか」→「いいえ、まったく」＝「いいですよ」という理くつである。Yes. と答えると「いやです」という意味になってしまうので注意する。\\n\\n■ Do you mind if I 〜? もある\\n例）Do you mind if I open the window?（窓を開けてもよろしいですか）\\nこれは自分が動く許可の言い方。答えはやはり No, not at all.（どうぞ）となる。\\n\\n■ ほかの依頼表現との比較\\nCould you open the window?（開けていただけますか）— Sure.\\nWould you mind opening the window?（開けていただけませんか）— No, not at all.\\n答え方がちがうことを、必ず形とセットで覚える。\\n\\n⚠ 注意：mind のうしろは動名詞（-ing）で、to 不定詞は使わない。× Would you mind to open 〜? は誤り。\",\"mangaId\":\"eigo_s179_xm\"}],\"trapExamples\":[{\"question\":\"「あなたのペンを使ってもよろしいですか。」を英語にしなさい。\",\"wrongAnswer\":\"Could you use your pen?\",\"trapExplanation\":\"ていねいな言い方＝ Could you 〜? と覚えているため、動作をするのが自分であることを忘れて you を主語にしてしまう。\",\"correctAnswer\":\"Could I use your pen?（May I use your pen? も可）\",\"correctExplanation\":\"ペンを使うのは自分なので主語は I。Could you use your pen? では「あなたのペンを使っていただけますか」という意味不明の文になる。「自分がする＝ I」「相手がする＝ you」をまず決めてから、ていねいさで助動詞を選ぶ。\"},{\"question\":\"Would you mind opening the window? に「いいですよ（どうぞ）」と答えなさい。\",\"wrongAnswer\":\"Yes, of course.\",\"trapExplanation\":\"承諾するのだから Yes だと考えてしまう。mind が「いやだと思う」という意味なので、Yes は「いやです」という断りになってしまう。\",\"correctAnswer\":\"No, not at all.（Of course not. / Certainly not. も可）\",\"correctExplanation\":\"Would you mind 〜? は「〜するのをいやだと思いますか」とたずねる形なので、承諾するときは No（いいえ、まったくいやではありません）で答える。Could you 〜? への Sure. とは答え方が逆になる点が問われやすい。\"}]}",
"{\"id\":\"eigo_s180\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話でよく出る受け答えと決まり文句\",\"description\":\"助動詞を使った会話でくり返し出る応答表現を、場面ごとに整理して覚える\",\"intro\":\"英語の会話では、Sure. / Of course. / I'm afraid not. のように、決まった返しがくり返し登場します。これは冷たいのではなく、その場でいちいち考えなくてよいようにできた便利な形です。入試の会話文でも同じ表現が何度も出ます。まとめて覚えてしまいましょう。\",\"order\":680,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Sure. / Of course. / Certainly. ＝「いいですよ」（依頼への承諾）。\",\"Here you are. ＝「はい、どうぞ」（ものを手わたすとき）。\",\"I'm afraid not. ＝「残念ながらちがいます・できません」。\",\"That's too bad. ＝「それは残念ですね」。\",\"店では May I help you? — Yes, please. / No, thank you. I'm just looking.\"],\"sections\":[{\"heading\":\"場面別の決まり文句\",\"body\":\"助動詞の単元の会話問題は、応答の決まり文句を知っているかどうかで差がつく。場面ごとにまとめて覚える。\\n\\n■ 頼まれたとき\\nSure. ／ Of course. ／ Certainly. ／ All right. ／ No problem.（いいですよ）\\nI'm sorry, I can't.（すみません、できません）\\nI'm afraid I can't.（残念ながらできません）\\n\\n■ ものをわたすとき\\nHere you are. ／ Here it is.（はい、どうぞ）\\n— Thank you. ／ Thanks a lot.\\n— You're welcome. ／ Not at all.（どういたしまして）\\n\\n■ 申し出をうけるとき・ことわるとき\\nYes, please.（お願いします）\\nNo, thank you. I'm all right.（けっこうです。だいじょうぶです）\\nThat's very kind of you.（ご親切にありがとうございます）\\n\\n■ 残念な知らせを聞いたとき\\nThat's too bad.（それは残念ですね）\\nI'm sorry to hear that.（それはお気の毒に）\\n\\n■ 店で\\n店員：May I help you?／店員：Here you are.\\n客：Yes, please. I'm looking for a cap.／客：No, thank you. I'm just looking.\\n客：How much is it?／客：I'll take it.（これをいただきます）\\n\\n★ ポイント：I'm afraid 〜 は「残念ながら〜」という前置き。I'm afraid not.（残念ながらちがいます）、I'm afraid so.（残念ながらそのとおりです）の二つは丸暗記しておく。\",\"figureId\":\"xf_eigo_s180\"},{\"heading\":\"会話文の流れを読む\",\"body\":\"会話問題では、空所の前後から「これは依頼か、申し出か、さそいか」を見きわめることが第一歩になる。次の三つの流れを頭に入れておく。\\n\\n■ 依頼の流れ\\nA: Could you help me with my homework?（宿題を手伝ってくださいませんか）\\nB: Sure. What's the problem?（いいですよ。どこが分からないの）\\nA: I can't answer this question.（この問題が解けなくて）\\n\\n■ 申し出の流れ\\nA: You look tired. Shall I carry your bag?（疲れているみたいだね。かばんを持とうか）\\nB: Thank you. That's very kind of you.（ありがとう。ご親切に）\\nA: No problem.（どういたしまして）\\n\\n■ さそいの流れ\\nA: Shall we go to the zoo this Saturday?（今度の土曜、動物園に行きませんか）\\nB: I'd like to, but I have to help my father.（行きたいのですが、父を手伝わなければならなくて）\\nA: That's too bad. How about next week?（残念だな。来週はどう）\\nB: Sounds good.（いいですね）\\n\\n■ ことわるときの決まり文句\\nI'd like to, but 〜（行きたいのですが〜）は、断り方としてとてもよく出る。I'd like to のあとに動詞を続けないまま but でつなぐ形をそのまま覚える。\\n\\n⚠ 注意：You're welcome.（どういたしまして）は Thank you. への返事。Excuse me.（すみません）は人に話しかけるときや軽くあやまるとき、I'm sorry. は本当に悪かったときと、使い分けがある。\",\"mangaId\":\"eigo_s180_xm\"}],\"trapExamples\":[{\"question\":\"店で May I help you? と声をかけられた。「いいえ、けっこうです。見ているだけです」と答えなさい。\",\"wrongAnswer\":\"No, I don't. I'm seeing only.\",\"trapExplanation\":\"一般動詞の疑問文だと勘ちがいして No, I don't. と答えてしまう。また「見ているだけ」を see で表そうとしている。\",\"correctAnswer\":\"No, thank you. I'm just looking.\",\"correctExplanation\":\"店員の May I help you? は申し出なので、Yes, please. / No, thank you. で答える。「見ているだけです」は I'm just looking. が決まった言い方。look は「目を向ける」、see は「目に入る」で、店で品物を見て回るのは look である。\"},{\"question\":\"次の英文を日本語にしなさい。「Here you are.」\",\"wrongAnswer\":\"ここにあなたがいます。\",\"trapExplanation\":\"Here / you / are をそのまま単語ごとに直訳してしまう。ものを手わたすときの決まり文句であることを知らないと意味が取れない。\",\"correctAnswer\":\"はい、どうぞ。\",\"correctExplanation\":\"Here you are. ／ Here it is. は、相手にものを手わたすときの決まり文句で「はい、どうぞ」の意味。返事は Thank you.、それに対しては You're welcome. と続く。会話の決まり文句は直訳せず、場面ごと覚える。\"}]}",
"{\"id\":\"eigo_s181\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"命令文①：動詞の原形で始める文\",\"description\":\"主語を書かずに動詞の原形で始める命令文の作り方を、be動詞の文までふくめて習得する\",\"intro\":\"英語で「静かにしなさい」は Be quiet. です。主語がありません。英語の文はふつう主語で始まるはずなのに、命令するときだけ主語を省き、動詞の原形で始めるという特別なきまりがあります。日本語では気づきにくい、英語らしい約束事です。\",\"order\":681,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"命令文は主語 You を書かず、動詞の原形で始める。\",\"三単現の s も過去形も使わない。いつでも原形。\",\"be動詞の文の命令文は Be 〜. で始める（You are kind. → Be kind.）。\",\"命令文は「〜しなさい」だけでなく、道案内や説明にも使う。\",\"文の終わりはピリオド。強く言うときは感嘆符（!）を使うこともある。\"],\"sections\":[{\"heading\":\"命令文の作り方\",\"mangaId\":\"eigo_s181_manga\",\"body\":\"相手に「〜しなさい」「〜してください」と言う文を命令文という。作り方はとても簡単で、ふつうの文から主語 You を取り、動詞を原形にするだけである。\\n\\n■ 一般動詞の文から\\nYou open the window.（あなたは窓を開ける）\\n→ Open the window.（窓を開けなさい）\\n\\nYou study English every day.\\n→ Study English every day.（毎日英語を勉強しなさい）\\n\\nYou wash your hands.\\n→ Wash your hands.（手を洗いなさい）\\n\\n主語がないので、三単現の s を付ける必要もない。相手に言う文なのだから、そもそも主語は you に決まっていて、書かなくても分かるという理くつである。\\n\\n■ 動詞は必ず原形\\n過去のことを命令することはできないので、過去形は使わない。\\n× Opened the window. ／ × Opens the window. はどちらも誤り。\\n\\n■ 使われる場面\\n命令だけでなく、指示・道案内・説明書・レシピなど、幅広く使われる。\\n例）Turn right at the next corner.（次の角を右に曲がってください）\\n例）Put the eggs into the bowl.（卵をボウルに入れます）\\n\\n★ ポイント：「命令文＝動詞の原形で始まる文」と覚える。文の最初の語が動詞の原形なら、それは命令文である。\",\"figureId\":\"lf_eigoext05_181\"},{\"heading\":\"be動詞の命令文\",\"body\":\"be動詞（am / is / are）を使った文を命令文にするときは、be動詞の原形である Be を文の先頭に置く。ここが受験生のつまずきどころである。\\n\\n■ 作り方\\nYou are quiet.（あなたは静かだ）\\n→ Be quiet.（静かにしなさい）\\n\\nYou are kind to others.\\n→ Be kind to others.（人には親切にしなさい）\\n\\nYou are careful.\\n→ Be careful.（気をつけなさい）\\n\\nam / is / are の原形は be である。are をそのまま残して × Are quiet. とすると疑問文のような形になってしまい、意味が通らない。\\n\\n■ よく使う be の命令文\\nBe quiet.（静かに）\\nBe careful.（気をつけて）\\nBe kind.（親切にしなさい）\\nBe a good boy.（いい子にしていなさい）\\nBe on time.（時間を守りなさい）\\n\\n■ 主語を書いてしまうまちがい\\n「あなたは窓を開けなさい」という日本語につられて You open the window. と書くと、「あなたは窓を開けます」というふつうの文になってしまい、命令の意味にならない。日本語に「あなたは」があっても、英語では書かない。\\n\\n⚠ 注意：命令文の文末はピリオドが基本。強い調子を表したいときだけ感嘆符を使う（Look out!／Stop!）。会話文の並べかえ問題では、文末の記号まで採点されることがある。\"}],\"trapExamples\":[{\"question\":\"「静かにしなさい。」を英語にしなさい。\",\"wrongAnswer\":\"Are quiet.\",\"trapExplanation\":\"You are quiet. の主語を取るだけだと考えて、are をそのまま残してしまう。be動詞にも原形があることを意識していない。\",\"correctAnswer\":\"Be quiet.\",\"correctExplanation\":\"命令文では動詞を原形にする。am / is / are の原形は be なので、Be quiet. となる。Be careful.（気をつけて）、Be kind.（親切にしなさい）も同じ形。「be動詞の命令文は Be で始まる」と型で覚える。\"},{\"question\":\"「（あなたは）このドアを開けなさい。」を英語にしなさい。\",\"wrongAnswer\":\"You open this door.\",\"trapExplanation\":\"日本語に「あなたは」があるため、主語を書いてしまう。書いてしまうと「あなたはこのドアを開けます」というふつうの文になり、命令の意味が消える。\",\"correctAnswer\":\"Open this door.\",\"correctExplanation\":\"命令文は主語 You を書かず、動詞の原形から始める。相手に向かって言う文なので、主語が you であることは言わなくても分かるからである。ていねいに言いたいときは Please open this door. や Open this door, please. とする。\"}]}",
"{\"id\":\"eigo_s182\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"命令文②：否定の命令文（Don't 〜.）\",\"description\":\"「〜してはいけません」を表す Don't の命令文を、be動詞の文もふくめて正確に作る\",\"intro\":\"「走ってはいけません」を英語にするとき、No run. と書いてしまう人がいます。看板の No running. につられるからです。文として言うときは Don't run. が正しい形。be動詞の文でも Don't be late. のように Don't を使います。\",\"order\":682,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"否定の命令文は Don't ＋ 動詞の原形 ＝「〜してはいけない・〜しないで」。\",\"be動詞の文でも Don't be 〜. とする（× Be not 〜.）。\",\"主語がないので doesn't は使わない。いつでも Don't。\",\"Never ＋ 原形 ＝「決して〜するな」。Don't よりさらに強い。\",\"ていねいにするときは Please don't 〜. と、please を先頭に置く。\"],\"sections\":[{\"heading\":\"Don't で始める否定の命令文\",\"body\":\"「〜してはいけません」と止めるときは、命令文の前に Don't を置く。\\n\\n■ 一般動詞の場合\\nOpen the window.（窓を開けなさい）\\n→ Don't open the window.（窓を開けてはいけません）\\n\\n例）Don't run in the hallway.（ろうかを走ってはいけません）\\n例）Don't touch this button.（このボタンにさわらないで）\\n例）Don't worry.（心配しないで）\\n例）Don't forget your homework.（宿題を忘れないで）\\n\\n■ be動詞の場合も Don't\\nBe late. → Don't be late.（遅れてはいけません）\\n例）Don't be afraid.（こわがらないで）\\n例）Don't be shy.（はずかしがらないで）\\n× Be not late. とは言わない。be動詞の否定命令文も Don't be 〜. の形になる。\\n\\n■ 主語がないので doesn't は使わない\\n命令文には主語がないので、相手が何人でも、どんな人でも Don't のままである。× Doesn't run. のような形は存在しない。\\n\\n★ ポイント：「命令文の否定は、文の頭に Don't を足すだけ」。一般動詞でも be動詞でも同じで、例外がない。\",\"figureId\":\"xf_eigo_s182\",\"mangaId\":\"eigo_s182_xm\"},{\"heading\":\"Never と please\",\"body\":\"否定の命令文には、意味を強めたりやわらげたりする言い方がある。\\n\\n■ Never ＋ 動詞の原形（決して〜するな）\\n例）Never give up.（決してあきらめるな）\\n例）Never tell a lie.（決してうそをついてはいけない）\\nDon't よりも強い調子になる。標語やことわざのような文でよく使われる。Never のうしろも動詞の原形で、Don't は付けない（× Never don't give up.）。\\n\\n■ Please をそえてやわらげる\\n例）Please don't open the door.（どうかドアを開けないでください）\\n例）Don't open the door, please.\\nplease は文頭か文末に置く。文末に置くときは、直前にコンマを入れる。\\n× Don't please open the door. のように、文の途中に入れるのは誤りである。\\n\\n■ 禁止を表す他の言い方\\nDon't swim here.（ここで泳いではいけない）\\n＝ You must not swim here.\\n＝ You can't swim here.\\n掲示では No swimming.（遊泳禁止）のように「No ＋ -ing」の形も使われる。\\n\\n■ 相手を気づかう決まり文句\\nDon't worry.（心配しないで）\\nDon't mention it.（どういたしまして）\\nDon't be sad.（悲しまないで）\\n\\n⚠ 注意：Don't be late for school.（学校に遅れてはいけません）のように、be動詞のあとに形容詞や熟語が続く形は頻出。be を落として × Don't late for school. と書くまちがいに気をつける。\"}],\"trapExamples\":[{\"question\":\"「遅れてはいけませんよ。」を英語にしなさい。\",\"wrongAnswer\":\"Don't late.\",\"trapExplanation\":\"「遅れる」を late という一語で表せると思ってしまう。late は形容詞なので、動詞 be が必要であることを見落としている。\",\"correctAnswer\":\"Don't be late.\",\"correctExplanation\":\"late は「遅い」という形容詞なので、be動詞と組にして be late（遅れる）となる。否定の命令文にすると Don't be late. である。同じように Don't be afraid. / Don't be shy. も be を落とさない。\"},{\"question\":\"「どうか泣かないでください。」を英語にしなさい。\",\"wrongAnswer\":\"Don't please cry.\",\"trapExplanation\":\"日本語の「どうか泣かないで」の語順につられ、Don't のうしろに please を入れてしまう。please の置き場所が決まっていることを知らない。\",\"correctAnswer\":\"Please don't cry.（Don't cry, please. も可）\",\"correctExplanation\":\"please は文の先頭か文の終わりに置く。文末に置くときは Don't cry, please. とコンマを入れる。文の途中に割りこませることはできない。肯定の命令文でも Please sit down. / Sit down, please. と同じ規則である。\"}]}",
"{\"id\":\"eigo_s183\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"命令文③：please の位置と呼びかけのコンマ\",\"description\":\"ていねいな命令文の作り方と、名前で呼びかけるときのコンマの使い方を正確に身につける\",\"intro\":\"Please sit down. と Sit down, please. — どちらも正しく、please は前にも後ろにも置けます。ただし後ろに置くときはコンマが必要です。また Ken, come here. のように名前で呼びかけるときもコンマが要ります。この小さな記号が、書き取り問題では点になります。\",\"order\":683,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"please は文頭か文末に置く。文末のときは直前にコンマを入れる。\",\"呼びかけの名前も、文頭・文末どちらでもコンマで区切る。\",\"Please 〜. でもていねいさは十分だが、Could you 〜? のほうがよりていねい。\",\"Let's 〜. は命令文ではないが、同じく原形で始まる仲間として覚える。\",\"コンマの有無で減点されることがあるので、書いたら必ず確認する。\"],\"sections\":[{\"heading\":\"please の置き場所\",\"body\":\"命令文に please を付けると「〜してください」とていねいになる。置く場所は文頭か文末の二か所だけである。\\n\\n■ 文頭に置く\\n例）Please open the window.（窓を開けてください）\\n例）Please come in.（どうぞお入りください）\\nコンマは不要である。\\n\\n■ 文末に置く\\n例）Open the window, please.\\n例）Come in, please.\\n文末に置くときは、please の直前にコンマを入れる。このコンマを落とすと減点されることがある。\\n\\n■ 途中には置けない\\n× Open please the window. は誤り。please は文全体にかかる語なので、文の中に割りこませない。\\n\\n■ 否定の命令文でも同じ\\nPlease don't touch it.（さわらないでください）\\nDon't touch it, please.\\n\\n■ もっとていねいに言いたいとき\\nPlease open the window. よりも\\nCould you open the window? ／ Would you open the window?\\nのほうがていねいである。目上の人やお店の人には、こちらを使うとよい。\\n\\n★ ポイント：please があっても命令文は命令文なので、動詞は原形のまま。Please opens 〜 のように s を付けてはいけない。\",\"figureId\":\"lf_eigoext05_183\"},{\"heading\":\"呼びかけのコンマ\",\"body\":\"相手の名前を呼びながら命令文を言うとき、名前と文の間には必ずコンマを入れる。これを呼びかけのコンマという。\\n\\n■ 名前が前\\n例）Ken, come here.（ケン、こっちへおいで）\\n例）Tom, be quiet.（トム、静かに）\\n\\n■ 名前があと\\n例）Come here, Ken.\\n例）Close the door, Tom.\\n\\n■ please と両方使うとき\\n例）Ken, please open the window.\\n例）Open the window, please, Ken.（少しくどいので、ふつうは Ken, please open the window. とする）\\n\\n■ コンマがないと意味が変わってしまう例\\nLet's eat, Grandma.（おばあちゃん、食べよう）\\nLet's eat Grandma.（おばあちゃんを食べよう）\\nコンマ一つで意味がまるで変わってしまう。英語ではコンマが意味を決める大切な記号である。\\n\\n■ Let's 〜. も原形で始まる\\nLet's go home.（家に帰ろう）は命令文ではないが、Let's のうしろが動詞の原形という点は命令文と同じ。「原形で始まるなかま」として並べて覚えておくと、語順を忘れにくい。\\n\\n⚠ 注意：呼びかけの語は、名前だけでなく Mr. Brown / everyone / boys and girls などでも同じようにコンマで区切る。\\n例）Everyone, look at this picture.\",\"mangaId\":\"eigo_s183_xm\"}],\"trapExamples\":[{\"question\":\"「ドアを閉めてください、ケン。」を英語にしなさい。\",\"wrongAnswer\":\"Close the door please Ken.\",\"trapExplanation\":\"語順は合っているのに、コンマをまったく打たない。日本語では読点を打たなくても意味が通じるため、英語でも不要だと感じてしまう。\",\"correctAnswer\":\"Close the door, please, Ken.（Ken, please close the door. も可）\",\"correctExplanation\":\"文末の please の前にはコンマを入れ、呼びかけの名前の前にもコンマを入れる。すっきり書くなら Ken, please close the door. とするとよい。コンマの有無は採点対象になるので、書き終えたら必ず見直す。\"},{\"question\":\"「どうぞこの本を読んでください。」を英語にしなさい。\",\"wrongAnswer\":\"Read please this book.\",\"trapExplanation\":\"「どうぞ読んでください」という日本語の順に引きずられ、動詞のすぐあとに please を入れてしまう。\",\"correctAnswer\":\"Please read this book.（Read this book, please. も可）\",\"correctExplanation\":\"please は文頭か文末のどちらかに置く。文末に置くときは直前にコンマが必要。文の途中に入れることはできない。否定の命令文でも Please don't 〜. / Don't 〜, please. と同じ規則である。\"}]}",
"{\"id\":\"eigo_s184\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"命令文④：命令文, and 〜 と 命令文, or 〜\",\"description\":\"「そうすれば」と「さもないと」を表す二つの型を、if を使った文への書きかえまで理解する\",\"intro\":\"Hurry up, and you'll catch the bus.（急ぎなさい、そうすればバスに間に合う）。Hurry up, or you'll miss the bus.（急ぎなさい、さもないと乗りおくれる）。and と or の一語で、はげましと警告が入れかわります。if を使った文への書きかえまでできるようにします。\",\"order\":684,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"命令文, and 〜 ＝「〜しなさい、そうすれば…」。\",\"命令文, or 〜 ＝「〜しなさい、さもないと…」。\",\"and のあとは良い結果、or のあとは困った結果が続くことが多い。\",\"命令文, and 〜 ＝ If you 〜, … に書きかえられる。\",\"命令文, or 〜 ＝ If you don't 〜, … と、否定にして書きかえる。\"],\"sections\":[{\"heading\":\"二つの型を覚える\",\"body\":\"命令文のうしろにコンマを打ち、and または or を続けると、「そうすれば」「さもないと」という意味の文になる。入試の定番である。\\n\\n■ 命令文, and 〜（〜しなさい、そうすれば…）\\n例）Hurry up, and you will catch the bus.（急ぎなさい、そうすればバスに間に合います）\\n例）Study hard, and you will pass the exam.（一生懸命勉強しなさい、そうすれば試験に受かります）\\n例）Turn right, and you will see the post office.（右に曲がれば、郵便局が見えます）\\nand のあとには、命令にしたがった場合の良い結果が続く。\\n\\n■ 命令文, or 〜（〜しなさい、さもないと…）\\n例）Hurry up, or you will miss the bus.（急ぎなさい、さもないとバスに乗り遅れます）\\n例）Get up early, or you will be late for school.（早く起きなさい、でないと学校に遅れます）\\n例）Take an umbrella, or you will get wet.（かさを持っていきなさい、さもないとぬれますよ）\\nor のあとには、命令にしたがわなかった場合の困った結果が続く。\\n\\n■ 見分け方\\nうしろの文が「うまくいく話」なら and、「困った話」なら or。\\ncatch the bus（間に合う）→ and ／ miss the bus（乗り遅れる）→ or\\npass（受かる）→ and ／ fail（落ちる）→ or\\n\\n★ ポイント：and は「そうすれば」、or は「さもないと」。日本語の訳とセットで、コンマの位置まで覚える。\",\"figureId\":\"xf_eigo_s184\"},{\"heading\":\"if を使った文への書きかえ\",\"body\":\"この二つの型は、if（もし〜ならば）を使った文に書きかえられる。書きかえ問題では、and と or で否定の有無が変わることがねらわれる。\\n\\n■ 命令文, and 〜 ＝ If you 〜, …\\nHurry up, and you will catch the bus.\\n＝ If you hurry up, you will catch the bus.（もし急げば、バスに間に合うでしょう）\\nそのまま if の文にすればよい。\\n\\n■ 命令文, or 〜 ＝ If you don't 〜, …\\nHurry up, or you will miss the bus.\\n＝ If you don't hurry up, you will miss the bus.（もし急がなければ、バスに乗り遅れるでしょう）\\nor は「さもないと」＝「もし〜しなければ」なので、if の文では否定にする。ここを落とすと不正解になる。\\n\\n■ 書きかえの手順\\n①命令文の部分を主語 you で始まる文に直す\\n②and ならそのまま、or なら don't を入れる\\n③文全体を If 〜, … の形に整える\\n\\n■ 未来のことでも if のあとは現在形\\nIf you hurry up, you will catch the bus.\\n× If you will hurry up 〜 とは書かない。時や条件を表す if / when のあとは、未来のことでも現在形を使うという決まりがある。\\n\\n⚠ 注意：or には「または」という意味もあるので、コンマの前が命令文になっているかを必ず確かめる。Tea or coffee?（紅茶かコーヒーか）の or とは別のはたらきである。\",\"mangaId\":\"eigo_s184_xm\"}],\"trapExamples\":[{\"question\":\"「早く起きなさい、さもないと学校に遅れますよ。」を英語にしなさい。\",\"wrongAnswer\":\"Get up early, and you will be late for school.\",\"trapExplanation\":\"命令文のあとをつなぐのは and だと覚えているため、うしろが「遅れる」という困った結果であることに気づかず and を使ってしまう。\",\"correctAnswer\":\"Get up early, or you will be late for school.\",\"correctExplanation\":\"and は「そうすれば」で良い結果、or は「さもないと」で困った結果を導く。be late for school（学校に遅れる）は困った結果なので or を使う。うしろの内容が良いか悪いかで選ぶ、と手順を決めておく。\"},{\"question\":\"次の文とほぼ同じ意味になるように書きかえなさい。「Run fast, or you will miss the train.」→「If you （　） fast, you will miss the train.」\",\"wrongAnswer\":\"run\",\"trapExplanation\":\"命令文の部分をそのまま if の文に移せばよいと考えてしまう。or が「〜しなければ」という否定の意味をふくんでいることを見落としている。\",\"correctAnswer\":\"don't run\",\"correctExplanation\":\"命令文, or 〜 は「もし〜しなければ…」という意味なので、if の文にするときは否定にする。If you don't run fast, you will miss the train. となる。and の場合は否定にせず、そのまま If you run fast, … とする。\"}]}",
"{\"id\":\"eigo_s185\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"感嘆文①：What で始まる感嘆文\",\"description\":\"「なんて〜な…でしょう」を表す What の感嘆文の語順と、a / an の有無を正確に身につける\",\"intro\":\"「なんて美しい花なんだろう」は What a beautiful flower it is! です。ここで a を落として What beautiful flower 〜 と書くと形がくずれます。感嘆文でも、数えられる名詞が一つなら a や an が要るからです。語順と冠詞、二つを同時にそろえます。\",\"order\":685,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"What ＋ (a / an) ＋ 形容詞 ＋ 名詞 ＋ 主語 ＋ 動詞 ! の語順。\",\"名詞があるときは What を使う。\",\"数えられる名詞が単数のときは a / an を忘れない。\",\"複数形や数えられない名詞には a / an を付けない。\",\"文末の主語＋動詞は省略できる（What a beautiful flower!）。\"],\"sections\":[{\"heading\":\"What の感嘆文の語順\",\"body\":\"おどろきや感動を表して「なんて〜な…でしょう」と言う文を感嘆文という。名詞がふくまれるときは What で始める。\\n\\n■ 基本の語順\\nWhat ＋ (a / an) ＋ 形容詞 ＋ 名詞 ＋ 主語 ＋ 動詞 !\\n\\n例）What a beautiful flower this is!（これはなんて美しい花でしょう）\\n例）What a tall building that is!（あれはなんて高い建物でしょう）\\n例）What an interesting book this is!（これはなんておもしろい本でしょう）\\n例）What a good singer she is!（彼女はなんて歌が上手なのでしょう）\\n\\n■ ふつうの文からの作り方\\nThis is a very beautiful flower.（これはとても美しい花です）\\n①very を取って、a beautiful flower をひとかたまりにする\\n②その前に What を置いて文の先頭へ\\n③残った this is をうしろに置き、文末を ! にする\\n→ What a beautiful flower this is!\\n\\n■ 文末は必ず感嘆符\\n感嘆文の終わりはピリオドではなく ! を付ける。書き忘れると減点される。\\n\\n★ ポイント：もとの文の very を what に置きかえて、そのかたまりを前に出す、と考えると作りやすい。\",\"figureId\":\"lf_eigoext05_185\"},{\"heading\":\"a / an を付けるか付けないか\",\"body\":\"What の感嘆文でいちばんまちがえやすいのが a / an の有無である。判断は、うしろの名詞の形で決まる。\\n\\n■ 数えられる名詞の単数 → a / an が必要\\nWhat a big dog it is!（なんて大きな犬でしょう）\\nWhat an old temple this is!（なんて古いお寺でしょう）\\n形容詞が母音の音で始まるときは an（an old / an interesting / an easy）。\\n\\n■ 複数形 → a / an は付けない\\nWhat beautiful flowers they are!（なんて美しい花々でしょう）\\nWhat kind people they are!（なんて親切な人たちでしょう）\\n\\n■ 数えられない名詞 → a / an は付けない\\nWhat good news it is!（なんてよい知らせでしょう）\\nWhat cold water this is!（なんて冷たい水でしょう）\\nnews・water・money・information などは数えられない名詞である。\\n\\n■ 見分けの手順\\n①名詞をさがす\\n②その名詞が数えられて、しかも一つなら a / an\\n③複数形か、数えられない名詞なら付けない\\n\\n■ 主語と動詞の省略\\nWhat a beautiful flower this is! → What a beautiful flower!\\n会話では省略した形がよく使われる。What a nice day!（なんていい天気でしょう）／What a surprise!（なんておどろき）などが定番である。\\n\\n⚠ 注意：a / an の位置は What のすぐあと。× What beautiful a flower の順にはならない。「What ＋ a ＋ 形容詞 ＋ 名詞」の順を口に出して覚える。\",\"mangaId\":\"eigo_s185_xm\"}],\"trapExamples\":[{\"question\":\"「これはなんて美しい花なのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"What beautiful flower this is!\",\"trapExplanation\":\"感嘆文の語順は覚えているが、flower が数えられる名詞の単数であることを意識していないため、a を落としてしまう。\",\"correctAnswer\":\"What a beautiful flower this is!\",\"correctExplanation\":\"数えられる名詞が単数のときは a / an が必要。位置は What のすぐあとで、What a beautiful flower となる。形容詞が母音の音で始まるときは an（What an interesting book this is!）。複数形なら a は付けない。\"},{\"question\":\"「彼らはなんて親切な少年たちなのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"What a kind boys they are!\",\"trapExplanation\":\"What のあとには必ず a が入ると型で覚えてしまっているため、名詞が複数形でも a を付けてしまう。\",\"correctAnswer\":\"What kind boys they are!\",\"correctExplanation\":\"a / an は「数えられる名詞の単数」に付く冠詞なので、複数形の boys には付けられない。What kind boys they are! が正しい。数えられない名詞も同じで、What good news it is! のように a を付けない。\"}]}",
"{\"id\":\"eigo_s186\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"感嘆文②：How で始まる感嘆文\",\"description\":\"名詞をふくまない感嘆文 How 〜! の語順を、疑問文との区別まで含めて習得する\",\"intro\":\"How beautiful! と How beautiful is it? — 前者は「なんて美しいんだ」という感動、後者は「どれくらい美しいの」という質問です。同じ How で始まるのに中身がちがいます。見分けるかぎは、あとに続く語順と、文の終わりが ! か ? かにあります。\",\"order\":686,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How ＋ 形容詞（副詞）＋ 主語 ＋ 動詞 ! の語順。\",\"How のあとに名詞は入らない。a / an も付かない。\",\"主語と動詞は疑問文の語順にしない（× How fast is he!）。\",\"文末の主語＋動詞は省略できる（How beautiful!）。\",\"副詞を使えば How fast he runs! のように動作の様子も表せる。\"],\"sections\":[{\"heading\":\"How の感嘆文の語順\",\"body\":\"名詞をふくまず、「なんて〜だろう」と性質や様子だけを言うときは How で始める。\\n\\n■ 基本の語順\\nHow ＋ 形容詞または副詞 ＋ 主語 ＋ 動詞 !\\n\\n例）How beautiful this flower is!（この花はなんて美しいのでしょう）\\n例）How kind she is!（彼女はなんて親切なのでしょう）\\n例）How tall he is!（彼はなんて背が高いのでしょう）\\n例）How fast he runs!（彼はなんて速く走るのでしょう）\\n例）How well she plays the piano!（彼女はなんて上手にピアノをひくのでしょう）\\n\\n■ 形容詞と副詞のどちらも使える\\nbe動詞の文なら形容詞（How kind she is!）、一般動詞の文なら副詞（How fast he runs!）が入る。\\n\\n■ ふつうの文からの作り方\\nThis flower is very beautiful.\\n①very beautiful の very を how に置きかえる\\n②How beautiful を文の先頭へ\\n③残った this flower is をうしろに置き、文末を ! にする\\n→ How beautiful this flower is!\\n\\n★ ポイント：How のうしろに来るのは一語（形容詞か副詞）だけ。名詞をつづけたくなったら、それは What の感嘆文である。\",\"figureId\":\"lf_eigoext05_186\"},{\"heading\":\"疑問文の語順にしない\",\"body\":\"How で始まる文には疑問文もあるので、語順の区別がとても大切である。\\n\\n■ 感嘆文（主語 → 動詞の順）\\nHow fast he runs!（彼はなんて速く走るのでしょう）\\nHow old this temple is!（このお寺はなんて古いのでしょう）\\n主語と動詞はふつうの文の順のまま。\\n\\n■ 疑問文（動詞・助動詞 → 主語の順）\\nHow fast does he run?（彼はどれくらい速く走りますか）\\nHow old is this temple?（このお寺はどれくらい古いのですか）\\nbe動詞や助動詞が主語の前に出る。\\n\\n■ まちがえやすい形\\n× How fast is he!（疑問文の語順になっている）\\n○ How fast he runs!（一般動詞の文）\\n○ How fast he is!（「彼はなんて足が速いのだろう」＝形容詞 fast）\\n\\n■ 省略した形\\nHow beautiful!（なんて美しいのでしょう）\\nHow kind of you!（ご親切に）\\nHow nice!（すてきですね）\\n会話では主語と動詞を省略した形がよく使われる。\\n\\n■ How + many / much の例外\\nHow many books he has!（彼はなんてたくさんの本を持っているのだろう）\\n数や量をたずねる many / much は、名詞が続いても How を使う。これは次のセッションで確認する。\\n\\n⚠ 注意：文末の記号でも見分けられる。? なら疑問文、! なら感嘆文。読解でも、記号を先に見ると意味を取りちがえない。\",\"mangaId\":\"eigo_s186_xm\"}],\"trapExamples\":[{\"question\":\"「彼はなんて速いランナーなのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"How a fast runner he is!\",\"trapExplanation\":\"How ＝「なんて」という訳だけで覚えているため、名詞（runner）が入っていても How で始めてしまう。\",\"correctAnswer\":\"What a fast runner he is!\",\"correctExplanation\":\"名詞（runner）がふくまれるので What の感嘆文を使う。How のあとに来るのは形容詞か副詞ひとつだけで、名詞や a / an は入らない。同じ内容を How で言うなら How fast he runs!（彼はなんて速く走るのでしょう）となる。\"},{\"question\":\"「このお寺はなんて古いのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"How old is this temple!\",\"trapExplanation\":\"How old is 〜? という疑問文の形になじんでいるため、感嘆文でも be動詞を主語の前に出してしまう。\",\"correctAnswer\":\"How old this temple is!\",\"correctExplanation\":\"感嘆文では主語と動詞をふつうの語順（主語→動詞）のまま置く。How old is this temple? としてしまうと「このお寺はどれくらい古いのですか」という疑問文になる。文末が ! か ? かも、あわせて確認する。\"}]}",
"{\"id\":\"eigo_s187\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"感嘆文③：What と How の使い分け\",\"description\":\"名詞があるかどうかで What と How を選び分け、省略形や例外にも対応できるようにする\",\"intro\":\"What a fast runner he is! と How fast he runs! は、どちらも「彼はなんて速く走るのだろう」という意味です。同じことを二通りに言えるのは、名詞を使うか使わないかがちがうから。どちらで書くかは、あとに続く語を見れば決まります。\",\"order\":687,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"名詞があれば What、なければ How。これが最大の見分け方。\",\"What ＋ (a/an) ＋ 形容詞 ＋ 名詞 ＋ 主語 ＋ 動詞 !\",\"How ＋ 形容詞・副詞 ＋ 主語 ＋ 動詞 !\",\"How many / How much は名詞が続いても How を使う。\",\"同じ内容を What と How の両方で言い表せることがある。\"],\"sections\":[{\"heading\":\"名詞があるかどうかで決める\",\"mangaId\":\"eigo_s187_manga\",\"body\":\"感嘆文で What と How のどちらを使うかは、文の中に名詞があるかどうかで決まる。手順にしてしまえば迷わない。\\n\\n■ 手順① 「なんて〜」の部分に名詞があるか\\nある → What ／ ない → How\\n\\n■ 手順② 語順を当てはめる\\nWhat ＋ (a / an) ＋ 形容詞 ＋ 名詞 ＋ 主語 ＋ 動詞 !\\nHow ＋ 形容詞・副詞 ＋ 主語 ＋ 動詞 !\\n\\n■ 同じ内容を両方で言う\\n彼はなんてよい野球選手なのだろう。\\n→ What a good baseball player he is!（名詞 player がある）\\n→ How well he plays baseball!（名詞がなく、副詞 well を使う）\\n\\nこれはなんて簡単な問題なのだろう。\\n→ What an easy question this is!\\n→ How easy this question is!\\n\\n意味はほぼ同じでも、名詞を使うか使わないかで What と How が入れかわる。書きかえ問題で頻出する。\\n\\n■ もとの文にもどして考える\\nHe is a very good player.（very ＋ 形容詞 ＋ 名詞）→ What\\nHe plays very well.（very ＋ 副詞）→ How\\n「very が付いている語が名詞のかたまりの中にあるか」で判断するのがこつである。\\n\\n★ ポイント：very を what / how に置きかえて前に出す、という作り方を覚えれば、どちらを使うかも自然に決まる。\",\"figureId\":\"xf_eigo_s187\"},{\"heading\":\"例外と省略\",\"body\":\"いくつか気をつけたい形がある。\\n\\n■ How many / How much は名詞が続いても How\\n例）How many books he has!（彼はなんてたくさんの本を持っているのだろう）\\n例）How much money she has!（彼女はなんてたくさんのお金を持っているのだろう）\\nmany・much は数や量を表す語で、how と結びついてひとかたまりになるため、名詞が続いても How のままである。× What many books は誤り。\\n\\n■ 主語＋動詞の省略\\nWhat a nice day!（なんていい天気だろう）\\nWhat a surprise!（なんておどろき）\\nHow nice!（すてきですね）\\nHow beautiful!（なんて美しいのだろう）\\n会話ではむしろ省略形のほうがよく使われる。省略しても文末の ! は必要である。\\n\\n■ How ＋ of you の形\\nHow kind of you!（ご親切にありがとうございます）\\nThat's very kind of you. と同じ意味で、お礼の決まり文句になっている。\\n\\n■ 感嘆文と疑問文の見分け\\nWhat a beautiful garden this is!（感嘆文・! で終わる）\\nWhat is this?（疑問文・? で終わる）\\nHow old this temple is!（感嘆文・主語→動詞）\\nHow old is this temple?（疑問文・動詞→主語）\\n\\n⚠ 注意：What と How のどちらでも書ける内容でも、問題に語数の指定や語群がある場合は、指定に合うほうを選ぶ。並べかえ問題では、a があれば What、なければ How と当たりを付けられる。\"}],\"trapExamples\":[{\"question\":\"「彼女はなんて上手に歌うのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"What well she sings!\",\"trapExplanation\":\"感嘆文といえば What と覚えているため、名詞がない文にも What を使ってしまう。well が副詞であることに注目できていない。\",\"correctAnswer\":\"How well she sings!\",\"correctExplanation\":\"名詞がなく、副詞 well で「上手に」と言っているので How を使う。How ＋ 副詞 ＋ 主語 ＋ 動詞 ! の語順である。名詞を使って言いかえるなら What a good singer she is! となり、このときは What になる。\"},{\"question\":\"「彼はなんてたくさんの本を持っているのでしょう。」を英語にしなさい。\",\"wrongAnswer\":\"What many books he has!\",\"trapExplanation\":\"名詞（books）があるから What、という覚え方だけで判断してしまう。many が how と結びつく語であることを知らない。\",\"correctAnswer\":\"How many books he has!\",\"correctExplanation\":\"many・much は how と組になって「どれくらい多くの」を表すので、名詞が続いても How で始める。How many books / How much money はひとかたまりで動く。名詞があれば What という原則の、数少ない例外として覚えておく。\"}]}",
"{\"id\":\"eigo_s188\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"付加疑問文①：「〜ですね」の作り方\",\"description\":\"肯定文には否定、否定文には肯定を付ける付加疑問の作り方を正確に身につける\",\"intro\":\"「今日は暑いですね」の「ですね」にあたるのが付加疑問です。It's hot today, isn't it? のように、文の最後に短い疑問をくっつけます。日本語は「ね」の一字ですが、英語は前の文が肯定か否定か、どんな動詞かによって形が変わります。作り方には決まった手順があります。\",\"order\":688,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"付加疑問は「本文, 反対の形＋代名詞?」の形で「〜ですね」を表す。\",\"本文が肯定なら否定の短縮形、否定なら肯定の形にする。\",\"使う語は本文と同じ種類（be動詞→be動詞、助動詞→助動詞、一般動詞→do / does / did）。\",\"主語は必ず代名詞にかえる（Tom → he、this book → it）。\",\"短縮形を使うのが原則（is not → isn't）。\"],\"sections\":[{\"heading\":\"付加疑問文の作り方\",\"body\":\"文の終わりに短い疑問の形をつけて「〜ですね」「〜でしょう？」と念をおす言い方を付加疑問文という。作り方は三つの手順で決まる。\\n\\n■ 手順① 本文が肯定か否定かを見る\\n肯定文 → 否定の付加疑問を付ける\\n否定文 → 肯定の付加疑問を付ける\\n\\n■ 手順② 本文で使われている語の種類をそろえる\\nbe動詞の文 → be動詞を使う\\n　You are tired, aren't you?（疲れているんですね）\\n　Tom isn't busy, is he?（トムはいそがしくないんですね）\\n助動詞の文 → 同じ助動詞を使う\\n　You can swim, can't you?\\n　He won't come, will he?\\n一般動詞の文 → do / does / did を使う\\n　You like music, don't you?\\n　She plays tennis, doesn't she?\\n　They went home, didn't they?\\n\\n■ 手順③ 主語を代名詞にかえる\\nTom can swim, can't he?（Tom → he）\\nThis book is interesting, isn't it?（This book → it）\\nKen and Tom are friends, aren't they?\\n\\n★ ポイント：「本文の反対」「同じ種類の語」「代名詞」の三つを順に確かめれば、どんな文にも付けられる。\",\"figureId\":\"lf_eigoext05_188\",\"mangaId\":\"eigo_s188_xm\"},{\"heading\":\"書き方の細かい決まり\",\"body\":\"付加疑問には形の上の決まりがいくつかある。細かいところで減点されやすいので、ここで確認しておく。\\n\\n■ コンマと疑問符\\n本文と付加疑問の間にはコンマを入れ、文末は ? で終わる。\\n例）You are a student, aren't you?\\nコンマを落とす、ピリオドで終える、といったミスに注意する。\\n\\n■ 短縮形を使う\\n否定の付加疑問は必ず短縮形にする。\\n○ isn't it? ／ don't you? ／ can't he?\\n△ is it not? は古い言い方で、ふつう使わない。\\n\\n■ am の場合だけ特別\\nI am late, aren't I?（私は遅れていますね）\\namn't という形はないので、aren't I? を使うと決まっている。\\n\\n■ 否定文に付けるとき\\nShe can't drive, can she?（彼女は運転できないんですね）\\nThey didn't come, did they?\\n本文が否定なら、付加疑問は肯定の形になる。not を二つ重ねてはいけない。\\n\\n■ There is 〜. の文\\nThere is a park near here, isn't there?\\n主語のように見える there をそのまま使う。\\n\\n⚠ 注意：付加疑問は「相手に確かめる」ための言い方なので、話しことばでよく使われる。読解では、話し手が相手の同意を求めている場面だと分かる手がかりになる。\"}],\"trapExamples\":[{\"question\":\"「あなたは中学生ですよね。」を英語にしなさい。（You are a junior high school student, ＿＿＿ ＿＿＿?）\",\"wrongAnswer\":\"You are a junior high school student, don't you?\",\"trapExplanation\":\"付加疑問といえば don't you? という形をいちばんよく見かけるため、本文が be動詞の文であることを確かめずに付けてしまう。\",\"correctAnswer\":\"You are a junior high school student, aren't you?\",\"correctExplanation\":\"付加疑問には、本文と同じ種類の語を使う。本文が be動詞（are）の文なので、付加疑問も be動詞を使って aren't you? とする。do / does / did を使うのは、本文が一般動詞の文のときだけである。\"},{\"question\":\"「この自転車はあなたのものですね。」を英語にしなさい。（This bike is yours, ＿＿＿ ＿＿＿?）\",\"wrongAnswer\":\"This bike is yours, isn't this bike?\",\"trapExplanation\":\"主語をそのまま書き写してしまう。付加疑問の主語は代名詞にする、という決まりを知らないと起こるミス。this を残して isn't this? としてしまう例も多い。\",\"correctAnswer\":\"This bike is yours, isn't it?\",\"correctExplanation\":\"付加疑問の主語は必ず代名詞にかえる。This bike は「もの」なので it になる。Tom → he、Ken and Tom → they、your sister → she のように置きかえる。動詞の種類（is）はそのまま使い、否定の短縮形にする。\"}]}",
"{\"id\":\"eigo_s189\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"付加疑問文②：答え方と特別な形\",\"description\":\"付加疑問への答え方の原則と、命令文・Let's に付く特別な形を身につける\",\"intro\":\"You aren't busy, are you? と聞かれて「はい、いそがしくありません」と答えたいとき、英語では No, I'm not. です。日本語の「はい」につられて Yes と答えると、まるで逆の意味になります。命令文や Let's に付く特別な形もあわせて確かめます。\",\"order\":689,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"答えは付加疑問ではなく「事実」に合わせる。中身が肯定なら Yes、否定なら No。\",\"日本語の「はい・いいえ」とずれることがあるので、事実で判断する。\",\"命令文には will you? を付ける（Open the window, will you?）。\",\"Let's 〜. には shall we? を付ける（Let's go, shall we?）。\",\"Don't 〜. にも will you? を付ける。\"],\"sections\":[{\"heading\":\"答え方は「事実」で決める\",\"mangaId\":\"eigo_s189_manga\",\"body\":\"付加疑問への答え方は、付いている疑問の形ではなく、実際にどうなのかという事実で決まる。\\n\\n■ 原則\\nそうである → Yes, ＋ 肯定\\nそうでない → No, ＋ 否定\\n\\n例）You can swim, can't you?（泳げますよね）\\n　泳げる → Yes, I can.\\n　泳げない → No, I can't.\\n\\n例）Tom can't swim, can he?（トムは泳げないんですよね）\\n　泳げない → No, he can't.\\n　泳げる → Yes, he can.\\n\\n■ 日本語とずれる場合\\n「トムは泳げないんですよね」に対して、日本語では「はい、泳げません」と答える。しかし英語では、泳げないという事実に合わせて No, he can't. となる。日本語の「はい」につられて Yes, he can't. と書くのは、二重に誤りである（Yes のあとに否定は来ない）。\\n\\n■ 覚え方\\nYes のあとは必ず肯定、No のあとは必ず否定。この組み合わせがくずれることはない。\\n○ Yes, he can. ／ ○ No, he can't.\\n× Yes, he can't. ／ × No, he can.\\n\\n★ ポイント：付加疑問の答えは、日本語に訳さず「事実はどちらか」だけを考える。これで確実に正解できる。\",\"figureId\":\"xf_eigo_s189\"},{\"heading\":\"命令文と Let's の付加疑問\",\"body\":\"命令文や Let's 〜. にも付加疑問を付けられる。ただし、付ける形が特別に決まっている。\\n\\n■ 命令文 → will you?\\n例）Open the window, will you?（窓を開けてくれませんか）\\n例）Wait here, will you?（ここで待っていてくれますか）\\n命令の調子をやわらげ、「〜してくれませんか」という依頼に近い言い方になる。won't you? を使うと、よりていねいなさそいになる。\\n\\n■ 否定の命令文 → will you?\\n例）Don't tell anyone, will you?（だれにも言わないでね）\\n否定の命令文でも、付けるのは will you? である。\\n\\n■ Let's 〜. → shall we?\\n例）Let's go to the park, shall we?（公園に行きましょうよ、ね）\\n例）Let's take a break, shall we?（ひと休みしましょうか）\\nLet's は「いっしょに〜しよう」という誘いなので、shall we? が対応する。\\n\\n■ 三つをまとめて覚える\\nふつうの文 → 本文と同じ種類の語で作る\\n命令文（Don't もふくむ）→ will you?\\nLet's 〜. → shall we?\\n\\n■ I am の文\\nI'm right, aren't I?（私は正しいですよね）\\namn't という形がないため、aren't I? を使う。\\n\\n⚠ 注意：命令文に do you? や can you? を付けるのは誤り。「命令文には will you?、Let's には shall we?」と、二つセットで暗記する。\"}],\"trapExamples\":[{\"question\":\"「Tom can't play the guitar, can he?」に、「はい、ひけません」という内容で答えなさい。\",\"wrongAnswer\":\"Yes, he can't.\",\"trapExplanation\":\"日本語の「はい、ひけません」の「はい」につられて Yes を選んでしまう。英語では Yes のあとに否定文は来ない。\",\"correctAnswer\":\"No, he can't.\",\"correctExplanation\":\"英語では、事実が「できない」なら No、「できる」なら Yes と答える。日本語の「はい・いいえ」は相手の言ったことへの同意を表すが、英語は事実そのものに合わせる。Yes ＋ 肯定、No ＋ 否定の組み合わせはくずれない。\"},{\"question\":\"「いっしょに公園へ行きましょうよ、ね。」を英語にしなさい。（Let's go to the park, ＿＿＿ ＿＿＿?）\",\"wrongAnswer\":\"Let's go to the park, will you?\",\"trapExplanation\":\"命令文に will you? を付けると覚えたため、原形で始まるという点が似ている Let's の文にも同じものを付けてしまう。\",\"correctAnswer\":\"Let's go to the park, shall we?\",\"correctExplanation\":\"Let's 〜. に付ける付加疑問は shall we? と決まっている。will you? を付けるのは命令文（Open the door, will you? / Don't be late, will you?）である。Let's ＝ shall we、命令文 ＝ will you と対にして覚える。\"}]}",
"{\"id\":\"eigo_s190\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"否定疑問文：Don't you 〜? の形と答え方\",\"description\":\"「〜ではないのですか」とたずねる文の作り方と、日本語とずれる答え方を確実にする\",\"intro\":\"Don't you like natto? と聞かれて、きらいなら答えは No, I don't. です。日本語なら「はい、きらいです」と言うので、つい Yes と答えたくなります。英語は質問の形に関係なく、好きなら Yes、好きでないなら No。ここがずれると、会話が正反対に伝わります。\",\"order\":690,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"否定疑問文は Don't / Aren't / Can't など、短縮形で文を始める。\",\"意味は「〜ではないのですか・〜しないのですか」。おどろきや念おしを表す。\",\"答えは事実で決める。そうなら Yes、そうでないなら No。\",\"日本語の「はい・いいえ」と逆になることが多いので、訳に引きずられない。\",\"Yes ＋ 肯定／No ＋ 否定の組み合わせは絶対にくずれない。\"],\"sections\":[{\"heading\":\"否定疑問文の作り方\",\"body\":\"「〜ではないのですか」「〜しないのですか」とたずねる文を否定疑問文という。ふつうの疑問文の先頭を否定の短縮形にするだけで作れる。\\n\\n■ 一般動詞の文\\nDo you like natto? → Don't you like natto?（納豆が好きではないのですか）\\nDoes he play soccer? → Doesn't he play soccer?\\nDid you go there? → Didn't you go there?\\n\\n■ be動詞の文\\nAre you tired? → Aren't you tired?（疲れていないのですか）\\nIs this your bag? → Isn't this your bag?\\n\\n■ 助動詞の文\\nCan you swim? → Can't you swim?（泳げないのですか）\\nWill you come? → Won't you come?（来ないのですか）\\n\\n■ 短縮形で書く\\n否定疑問文では、短縮形を使うのが決まりである。\\n○ Don't you 〜? ／ × Do not you 〜?\\n主語の前に not だけを置く形は使わない。\\n\\n■ 使われる場面\\n・おどろき：Don't you know Ken?（ケンを知らないの？）\\n・念おし：Isn't it cold today?（今日は寒くない？）\\n・さそい：Won't you come with us?（いっしょに来ませんか）\\nWon't you 〜? はさそいの決まり文句としても使われる。\\n\\n★ ポイント：形は「短縮形＋主語＋…?」。ふつうの疑問文の頭を否定にするだけと考えればよい。\"},{\"heading\":\"答え方は日本語と逆になる\",\"body\":\"否定疑問文でいちばん大切なのは答え方である。英語では、聞かれ方に関係なく「事実」に合わせて Yes / No を決める。\\n\\n■ 原則\\nそうである（する）→ Yes, ＋ 肯定\\nそうでない（しない）→ No, ＋ 否定\\n\\n例）Don't you like tomatoes?（トマトは好きではないのですか）\\n　好きだ → Yes, I do.（日本語では「いいえ、好きです」）\\n　好きではない → No, I don't.（日本語では「はい、好きではありません」）\\n\\n例）Aren't you hungry?（おなかはすいていないのですか）\\n　すいている → Yes, I am.（いいえ、すいています）\\n　すいていない → No, I'm not.（はい、すいていません）\\n\\n■ 日本語との差\\n日本語の「はい・いいえ」は、相手の言ったことに同意するかどうかを表す。英語の Yes / No は、事実がどうであるかだけを表す。だから否定疑問文では、両者がしばしば逆になる。\\n\\n■ まちがえないための手順\\n①質問の否定は無視して、「事実はどうか」だけを考える\\n②事実が肯定なら Yes、否定なら No\\n③Yes のあとは肯定、No のあとは否定でそろえる\\n\\n■ 付加疑問文でも同じ\\nYou aren't busy, are you? — Yes, I am.（いいえ、いそがしいです）\\n考え方はまったく同じである。\\n\\n⚠ 注意：Yes, I don't. や No, I do. のような組み合わせは、どんな場合でも誤り。答えを書いたら、Yes と肯定、No と否定がそろっているかを必ず確認する。\",\"figureId\":\"xf_eigo_s190\",\"mangaId\":\"eigo_s190_xm\"}],\"trapExamples\":[{\"question\":\"「Don't you like natto?」に、「いいえ、好きです」という内容で答えなさい。\",\"wrongAnswer\":\"No, I do.\",\"trapExplanation\":\"日本語の「いいえ」につられて No を選んでしまう。さらに No のあとに肯定の I do を続けており、組み合わせもくずれている。\",\"correctAnswer\":\"Yes, I do.\",\"correctExplanation\":\"英語では事実に合わせて答える。好きだという事実があるので Yes、そのあとは肯定の I do。日本語の「いいえ、好きです」とはちょうど逆になる。質問の Don't は無視して、「好きか、好きでないか」だけを考えるとまちがえない。\"},{\"question\":\"「あなたは中国語を話さないのですか。」を英語にしなさい。\",\"wrongAnswer\":\"Do not you speak Chinese?\",\"trapExplanation\":\"否定文は not を使うと覚えているため、Do のうしろに not をそのまま置いてしまう。否定疑問文では短縮形を使うという決まりを知らない。\",\"correctAnswer\":\"Don't you speak Chinese?\",\"correctExplanation\":\"否定疑問文は Don't / Doesn't / Didn't / Aren't / Can't のように短縮形で文を始める。Do not you 〜? という形は使わない。be動詞なら Aren't you 〜?、助動詞なら Can't you 〜? と、すべて同じ作り方である。\"}]}",
"{\"id\":\"eigo_s191\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Yes/No疑問文①：be動詞の文をたずねる形にする\",\"description\":\"be動詞を主語の前に出すだけで疑問文になることを、語順の箱で理解する\",\"intro\":\"「あなたは日本の出身ですか」を英語にすると Are you from Japan? です。日本語は文の最後に「か」を付けるだけですが、英語は語順そのものを入れかえます。You are 〜 の are を前に出すだけ。この「箱を入れかえる」動きが、英語の疑問文すべての土台になります。\",\"order\":691,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞（am / is / are）の文は、be動詞を主語の前に出すだけで疑問文になる。\",\"語順は「be動詞＋主語＋残りの語＋?」。文の終わりの ? を書き忘れない。\",\"be動詞の疑問文に do・does は絶対に使わない（Does he is 〜? は誤り）。\",\"be動詞は主語に合わせる。Am I 〜? / Is he 〜? / Are they 〜? と形が変わる。\",\"答えは Yes, 主語＋be動詞. / No, 主語＋be動詞＋not. の形にする。\"],\"sections\":[{\"heading\":\"be動詞の文を疑問文にする手順\",\"mangaId\":\"eigo_s191_manga\",\"body\":\"英語の疑問文は「日本語のように文の終わりに『か』を付ける」のではなく、語の順番を入れかえて作る。be動詞の文はいちばんかんたんで、be動詞を主語の前に持ち上げるだけでよい。\\n\\n■ 手順は二つだけ\\n①be動詞（am / is / are）を主語の前に出す\\n②文の終わりのピリオド（.）をクエスチョンマーク（?）に変える\\n\\n例）This is your book.（これはあなたの本です）\\n　→ Is this your book?（これはあなたの本ですか）\\n\\n例）You are a student.\\n　→ Are you a student?\\n\\n例）They are in the park.\\n　→ Are they in the park?\\n\\n■ 主語に合わせて be動詞の形が変わる\\nI → am／he, she, it, 単数の名詞 → is／you, we, they, 複数の名詞 → are\\n例）Is your sister a nurse?（sister は単数なので is）\\n例）Are those boys your friends?（those boys は複数なので are）\\n\\n⚠ 注意：疑問文にしても be動詞の形は変わらない。もとの文が is なら Is 〜?、are なら Are 〜? のままである。「疑問文だから are にする」といった思いこみでの書きかえは誤り。\\n\\n★ ポイント：be動詞の文には do や does を使う場所がない。Does he is a teacher? のように二つ重ねてしまう誤りが非常に多いので、「be動詞の文はbe動詞だけを動かす」と唱えて覚える。\",\"figureId\":\"lf_eigoext06_191\"},{\"heading\":\"短く答える形（Yes / No の答え方）\",\"body\":\"Yes/No疑問文には Yes か No で答える。そのあとに「主語＋be動詞」を付けるのが英語の決まりで、これを短答（たんとう）という。\\n\\n■ 答えの形\\nYes, 主語＋be動詞.\\nNo, 主語＋be動詞＋not.\\n\\n例）Are you a student? — Yes, I am. / No, I am not.（No, I'm not.）\\n例）Is this your bag? — Yes, it is. / No, it is not.（No, it isn't.）\\n例）Are they teachers? — Yes, they are. / No, they aren't.\\n\\n■ 答えの主語は代名詞に置きかえる\\nたずねられた名詞をそのままくり返さず、代名詞にする。\\nThis / That → it　　These / Those → they\\nyour father → he　　your mother → she　　you and Ken → we\\n\\n例）Is that your house? — Yes, it is.（Yes, that is. とはしない）\\n例）Are you and your brother busy? — Yes, we are.（Yes, I am. ではない）\\n\\n■ Yes の答えでは短縮形を使わない\\nNo, I'm not. は言えるが、Yes, I'm. とは言えない。文の最後に来る be動詞は短縮できないからである。Yes, I am. / Yes, it is. / Yes, they are. と、必ずのばした形で書く。\\n\\n★ ポイント：短答は「Yes/No」＋「主語」＋「be動詞」の三点セット。三つそろっているかを毎回指さし確認するとミスが消える。\"}],\"trapExamples\":[{\"question\":\"He is a teacher. を疑問文に書きかえなさい。\",\"wrongAnswer\":\"Does he is a teacher?\",\"trapExplanation\":\"「疑問文には do や does を付ける」とだけ覚えているため、be動詞の文にも does を足してしまう。動詞が二つ（does と is）並んでしまっている点に気づけない。\",\"correctAnswer\":\"Is he a teacher?\",\"correctExplanation\":\"be動詞の文は be動詞そのものを主語の前に出すだけでよい。He is 〜 → Is he 〜? と入れかえ、最後を ? にする。do・does は一般動詞（play, like, go など）の文だけに使う道具で、be動詞の文には出番がない。\"},{\"question\":\"Are you a soccer fan? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, I'm.\",\"trapExplanation\":\"I am を I'm と縮めるくせがついているため、答えの文でもそのまま短縮してしまう。ふだん使う I'm a student. の形につられるのが原因。\",\"correctAnswer\":\"Yes, I am.\",\"correctExplanation\":\"短縮形は「うしろに語が続くとき」だけ使える。Yes, I am. の am は文の最後に来ているので縮められない。ただし No, I'm not. は not がうしろに続くので短縮してよい。「Yes はのばす、No は縮めてよい」と覚える。\"}]}",
"{\"id\":\"eigo_s192\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Yes/No疑問文②：一般動詞の文と Do / Does\",\"description\":\"Do・Does を先頭に置き、動詞を原形に戻す手順を身につける\",\"intro\":\"He plays tennis. を疑問文にするとき、Does he plays tennis? と書きたくなります。でも正しくは Does he play tennis? です。三人称の s は Does がすでに引き受けているので、動詞は原形に戻ります。s を二度使わない、というのがこの単元のかんじんな点です。\",\"order\":692,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"一般動詞（play, like, go, have など）の文は Do / Does を文の先頭に置いて疑問文にする。\",\"主語が三人称単数（he, she, it, Ken, my sister など）のときだけ Does を使う。\",\"Does を使ったら動詞の s を取って原形に戻す（Does he play 〜?）。\",\"答えは Yes, 主語＋do(does). / No, 主語＋don’t(doesn’t). の形。\",\"be動詞と一般動詞を一つの文に二つ並べない（Are you play 〜? は誤り）。\"],\"sections\":[{\"heading\":\"Do と Does の使い分け\",\"mangaId\":\"eigo_s192_manga\",\"body\":\"一般動詞の文には、be動詞のように前に出せる語がない。そこで Do / Does という助っ人（助動詞）を文の先頭に置いて疑問文を作る。\\n\\n■ 手順\\n①主語を見て Do か Does かを決める\\n②それを文の先頭に置く\\n③動詞を原形（s の付かない形）に戻す\\n④最後を ? にする\\n\\n例）You play tennis. → Do you play tennis?\\n例）They live in Osaka. → Do they live in Osaka?\\n例）He plays tennis. → Does he play tennis?（plays の s が消える）\\n例）Your sister likes music. → Does your sister like music?（likes → like）\\n\\n■ Does を使う主語\\nhe / she / it、および Ken・my father・that girl・The dog のように「一人（一つ）で、私でもあなたでもないもの」。これを三人称単数という。\\nそれ以外（I, you, we, they, 複数の名詞）はすべて Do。\\n\\n■ なぜ動詞が原形に戻るのか\\n三単現の s は「今のことで、主語が三人称単数」という印である。その印を Does がまとめて引き受けるため、動詞にまで s を付けると印が二重になってしまう。だから動詞は s のない形に戻る。\\n\\n⚠ 注意：Does he plays 〜? は入試で最も多い誤りの一つ。Does を書いた瞬間に「動詞から s を消す」と手を動かす習慣をつける。\",\"figureId\":\"lf_eigoext06_192\"},{\"heading\":\"答え方と、be動詞の文との区別\",\"body\":\"■ 短く答える形\\nYes, 主語＋do / does.\\nNo, 主語＋don't / doesn't.\\n\\n例）Do you like natto? — Yes, I do. / No, I don't.\\n例）Does Ken play the piano? — Yes, he does. / No, he doesn't.\\n例）Do your parents speak English? — Yes, they do. / No, they don't.\\n\\n答えの中に動詞をくり返す必要はない。Yes, I like it. と答えてもよいが、短答では do / does で受けるのが基本形である。\\n\\n■ be動詞の文か、一般動詞の文かを先に見分ける\\n疑問文を作るとき、いちばん最初にすることは「この文の動詞はどちらか」を決めることである。\\n・動詞が am / is / are → be動詞の文 → be動詞を前に出す\\n・動詞が play / like / go / have / study など → 一般動詞の文 → Do / Does を前に置く\\n\\n例）You are a student.（be動詞）→ Are you a student?\\n例）You study English.（一般動詞）→ Do you study English?\\n\\n⚠ 注意：Are you play soccer? のように be動詞と一般動詞を並べた文は存在しない。一つの文に「動くもの（動詞）」は原則一つだけだと覚えておく。\\n\\n★ ポイント：have は「持っている」という一般動詞。Have you a pen? ではなく Do you have a pen? が中学受験で求められる形である。\"}],\"trapExamples\":[{\"question\":\"He plays tennis every Sunday. を疑問文に書きかえなさい。\",\"wrongAnswer\":\"Does he plays tennis every Sunday?\",\"trapExplanation\":\"もとの文の plays をそのまま書き写してしまう。Does を付けたことで三単現の印がすでに使われていることに気づかず、s を二重に付けている。\",\"correctAnswer\":\"Does he play tennis every Sunday?\",\"correctExplanation\":\"Does が「今のこと・主語は三人称単数」という情報をすべて引き受けるので、動詞は原形の play に戻す。書きかえのときは「Does を書く → 動詞の s を消す」を必ずセットで行う。過去の Did でも同じで、Did he play 〜? と原形になる。\"},{\"question\":\"「あなたはサッカーをしますか」を英語にしなさい。\",\"wrongAnswer\":\"Are you play soccer?\",\"trapExplanation\":\"「疑問文は文の先頭に語を置く」とだけ覚えていて、置く語が Are なのか Do なのかを区別していない。be動詞をとりあえず先頭に出すくせが原因。\",\"correctAnswer\":\"Do you play soccer?\",\"correctExplanation\":\"この文の動詞は play という一般動詞なので、先頭に置くのは Do である。be動詞の Are を使ってよいのは Are you a soccer player?（あなたはサッカー選手ですか）のように、うしろが名詞や形容詞で動詞がないときだけ。動詞の種類を見てから先頭の語を決める。\"}]}",
"{\"id\":\"eigo_s193\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Yes/No疑問文③：過去の文をたずねる（Was / Were / Did）\",\"description\":\"過去の疑問文で be動詞と Did を使い分け、動詞を原形に戻す\",\"intro\":\"He went to Kyoto. を疑問文にすると、Did he went to Kyoto? としてしまいがちです。正しくは Did he go to Kyoto?。過去を表す仕事は Did が引き受けるので、動詞は原形の go に戻ります。せっかく覚えた不規則動詞を、ここでは使ってはいけないのです。\",\"order\":693,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"過去のbe動詞の文は was / were を主語の前に出す（Was he 〜? / Were you 〜?）。\",\"was を使う主語は I, he, she, it, 単数名詞。were を使う主語は you, we, they, 複数名詞。\",\"過去の一般動詞の文は Did を先頭に置き、動詞は必ず原形に戻す（Did you go 〜?）。\",\"答えは Yes, 主語＋was(were / did). / No, 主語＋wasn’t(weren’t / didn’t).\",\"yesterday, last night, 〜 ago, then などの語があれば過去の文だと見抜く。\"],\"sections\":[{\"heading\":\"過去のbe動詞の疑問文（Was / Were）\",\"body\":\"過去の文でも作り方は現在と同じで、be動詞を主語の前に出すだけである。ちがうのは be動詞が was / were になっている点だけ。\\n\\n■ was と were の使い分け\\nI was / He was / She was / It was / My father was（単数）\\nYou were / We were / They were / My friends were（複数）\\n\\n例）You were busy yesterday. → Were you busy yesterday?\\n例）He was at home last night. → Was he at home last night?\\n例）The books were on the desk. → Were the books on the desk?\\n\\n■ 答え方\\nYes, 主語＋was / were.　No, 主語＋wasn't / weren't.\\n例）Were you tired? — Yes, I was. / No, I wasn't.\\n\\n⚠ 注意：you の be動詞は、一人でも二人以上でも were である。Was you happy? という誤りが非常に多い。「you はいつも are / were」と丸ごと覚えてしまうとよい。\\n\\n■ 過去だと見抜く手がかり\\nyesterday（きのう）、last Sunday（この前の日曜）、two days ago（二日前）、then（そのとき）、at that time（当時）、in 2020 のような語が文にあれば過去の文である。これらの語が問題文にあるのに現在形で答えると、内容が正しくても不正解になる。\"},{\"heading\":\"過去の一般動詞の疑問文（Did）\",\"body\":\"過去の一般動詞の文は、主語が何であっても Did を先頭に置く。現在のように Do と Does を使い分ける必要はなく、全員 Did でよい。\\n\\n■ 手順\\n①Did を文の先頭に置く\\n②動詞を原形に戻す（過去形をやめる）\\n③最後を ? にする\\n\\n例）You went to the park. → Did you go to the park?（went → go）\\n例）He studied English. → Did he study English?（studied → study）\\n例）They had lunch at noon. → Did they have lunch at noon?（had → have）\\n\\n■ 答え方\\nYes, 主語＋did. / No, 主語＋didn't.\\n例）Did you see the movie? — Yes, I did. / No, I didn't.\\n\\n★ ポイント：Did が「過去である」という印をすべて引き受けるので、動詞はまっさらな原形に戻る。went, studied, had のような過去形をそのまま残すのは、印を二重に付けているのと同じで誤り。\\n\\n⚠ 注意：不規則動詞（go — went、see — saw、have — had、eat — ate、take — took）は、原形に戻すときに形が大きく変わる。原形が思い出せないと必ずまちがえるので、原形・過去形をセットで覚えておくこと。\",\"figureId\":\"xf_eigo_s193\",\"mangaId\":\"eigo_s193_xm\"}],\"trapExamples\":[{\"question\":\"You went to the zoo last Sunday. を疑問文に書きかえなさい。\",\"wrongAnswer\":\"Did you went to the zoo last Sunday?\",\"trapExplanation\":\"went をそのまま残してしまう。「過去のことだから過去形のままにしておかないと過去にならない」と考えてしまうのが原因。\",\"correctAnswer\":\"Did you go to the zoo last Sunday?\",\"correctExplanation\":\"Did がすでに「過去のこと」を表しているので、動詞は原形の go に戻す。過去を表す印は文の中に一つだけでよい。同じ理由で Did he studied? も誤りで、Did he study? が正しい。\"},{\"question\":\"You were free yesterday. を疑問文に書きかえなさい。\",\"wrongAnswer\":\"Did you were free yesterday?\",\"trapExplanation\":\"「過去の疑問文には Did」とだけ覚えているため、be動詞の文にも Did を付けてしまう。were と Did が二重になっていることに気づけない。\",\"correctAnswer\":\"Were you free yesterday?\",\"correctExplanation\":\"were は be動詞なので、そのまま主語の前に出せばよい。Did を使うのは play, go, study のような一般動詞の文だけである。現在の文で「be動詞なら前に出す・一般動詞なら Do/Does」と学んだ規則が、過去でもそのまま当てはまる。\"}]}",
"{\"id\":\"eigo_s194\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Yes/No疑問文④：助動詞（Can / Will / May / Must）\",\"description\":\"助動詞を先頭に出す疑問文と、依頼・許可のていねいな言い方を学ぶ\",\"intro\":\"助動詞の疑問文は、助動詞を主語の前に出すだけで作れます。be動詞と同じ動きです。ただし Will you open the window? のように、ただの質問ではなく「開けてくれますか」という依頼になることがあります。形は同じでも意味が変わる、そこがおもしろい部分です。\",\"order\":694,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"助動詞（can, will, may, must, should）の文は、助動詞を主語の前に出すだけで疑問文になる。\",\"助動詞のうしろの動詞は、主語が何であっても必ず原形（Can he swim?）。\",\"答えは Yes, 主語＋助動詞. / No, 主語＋助動詞＋not. で、たずねられた助動詞をそのまま返す。\",\"Can you 〜?（〜してくれますか）は依頼、Can I 〜?（〜してもよいですか）は許可。\",\"Must I 〜? への No の答えは No, you don't have to.（〜しなくてよい）。\"],\"sections\":[{\"heading\":\"助動詞の疑問文の作り方\",\"body\":\"can（〜できる）、will（〜するつもりだ）、may（〜してもよい）、must（〜しなければならない）、should（〜すべきだ）を助動詞という。助動詞のある文は、be動詞と同じように助動詞を主語の前に出すだけで疑問文になる。\\n\\n■ 作り方\\n例）He can swim fast. → Can he swim fast?\\n例）You will go to the party. → Will you go to the party?\\n例）I may use this pen. → May I use this pen?\\n例）She should see a doctor. → Should she see a doctor?\\n\\n■ 助動詞のうしろは必ず原形\\n主語が三人称単数でも、動詞に s は付けない。\\n○ Can he swim?　× Can he swims?\\n○ Will she come?　× Will she comes?\\nまた、助動詞を二つ重ねることもできない（× He will can 〜）。\\n\\n■ 答え方\\nたずねられた助動詞をそのまま使って答える。\\n例）Can you play the guitar? — Yes, I can. / No, I can't.\\n例）Will it rain tomorrow? — Yes, it will. / No, it won't.\\n例）May I come in? — Yes, you may. / Sure. / Of course.\\n\\n★ ポイント：疑問文を作るときに前へ出す語は「be動詞・助動詞・do/does/did」の三種類しかない。文を見たらまずこの三つのどれがあるかを探す、という順序で考えるとまちがえない。\",\"mangaId\":\"eigo_s194_xm\"},{\"heading\":\"依頼・許可の言い方と、ていねいさ\",\"body\":\"助動詞の疑問文は、単に「できるかどうか」をたずねるだけでなく、人にお願いしたり許可を求めたりするときにも使う。主語が you か I かで意味が変わるので注意する。\\n\\n■ Can you 〜? / Will you 〜?（〜してくれますか）＝依頼\\n例）Can you help me?（手伝ってくれますか）\\n例）Will you open the window?（窓を開けてくれますか）\\n\\n■ Can I 〜? / May I 〜?（〜してもよいですか）＝許可を求める\\n例）Can I use your eraser?（消しゴムを借りてもいい？）\\n例）May I speak to Ken, please?（電話で「ケンさんをお願いします」）\\n\\n■ ていねいにするには過去形を使う\\nCould you 〜? / Would you 〜? は、can・will の過去形を使った遠回しな言い方で、よりていねいになる。意味は過去ではない。\\n例）Could you say that again, please?（もう一度言っていただけますか）\\n\\n■ 答え方の決まり文句\\n引き受けるとき：Sure. / All right. / OK. / Of course. / Certainly.\\n断るとき：I'm sorry, I can't. / Sorry, but I'm busy now.\\n\\n⚠ 注意：Will you 〜? に Yes, I will. と答えるのはやや事務的で、会話では Sure. や All right. を使うことが多い。会話文の穴うめではこれらの決まり文句が問われる。\",\"figureId\":\"lf_eigoext06_194\"}],\"trapExamples\":[{\"question\":\"「彼は速く泳げますか」を英語にしなさい。\",\"wrongAnswer\":\"Can he swims fast?\",\"trapExplanation\":\"主語が he なので「三単現の s を付けなければ」という規則が反射的に働いてしまう。助動詞のうしろは原形という決まりが、三単現の規則に負けている。\",\"correctAnswer\":\"Can he swim fast?\",\"correctExplanation\":\"助動詞 can のうしろの動詞は、主語が何であっても必ず原形になる。三単現の s が付くのは、助動詞のない現在の文だけである。He can swim.（肯定文）の段階ですでに s が付いていないことを確かめると気づきやすい。\"},{\"question\":\"Must I clean this room? に「その必要はありません」と答えなさい。\",\"wrongAnswer\":\"No, you mustn't.\",\"trapExplanation\":\"たずねられた助動詞をそのまま返す、という短答の形にしたがって mustn't にしてしまう。しかし mustn't は「してはいけない」という強い禁止の意味になり、たずねた人に「掃除するな」と命じることになる。\",\"correctAnswer\":\"No, you don't have to.\",\"correctExplanation\":\"must には「must not ＝〜してはいけない（禁止）」と「don't have to ＝〜しなくてよい（不要）」という別の否定が二つある。「しなくてよい」と言いたいときは don't have to を使う。Must 〜? の No の答えだけは例外だと覚えておく。なお Yes の答えは Yes, you must. でよい。\"}]}",
"{\"id\":\"eigo_s195\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Yes/No疑問文⑤：短く答える形を完成させる\",\"description\":\"答えの主語を代名詞にそろえ、たずねられた語で受ける練習をする\",\"intro\":\"Is your mother a teacher? と聞かれて、Yes, my mother is. と答えるのはくどい言い方です。英語では Yes, she is. と代名詞に置きかえます。しかも、たずねられたのが Is なら is で、Do なら do で受けます。答え方には決まった型があるのです。\",\"order\":695,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"短答は「Yes / No ＋ 主語 ＋ be動詞・助動詞・do系」の三点セットで作る。\",\"答えの主語は代名詞にする。this / that → it、these / those → they。\",\"you and 〜 でたずねられたら we で答える。your father は he、your mother は she。\",\"たずねられた語の種類で受ける。Is → is、Do → do、Did → did、Can → can。\",\"Yes の答えでは短縮形を使わない（Yes, it is. ○ / Yes, it’s. ×）。\"],\"sections\":[{\"heading\":\"主語を代名詞に置きかえる\",\"body\":\"短答では、たずねられた文の主語をそのままくり返さず、代名詞に置きかえる。ここを機械的にできるようにすると、短答の問題はほぼ落とさなくなる。\\n\\n■ 置きかえの一覧\\nthis / that / your bag / the dog（一つ・一匹のもの）→ it\\nthese / those / your books / the dogs（複数のもの）→ they\\nyour father / Ken / that boy → he\\nyour mother / Ms. Green / that girl → she\\nyou（あなた）→ I\\nyou and Ken / you and your sister（あなたを含む複数）→ we\\nKen and Tom / your parents（自分たちを含まない複数）→ they\\n\\n例）Is that your bike? — Yes, it is.\\n例）Are these your pencils? — No, they aren't.\\n例）Does your mother like coffee? — Yes, she does.\\n例）Are you and Ken in the same class? — Yes, we are.\\n\\n⚠ 注意：Are you 〜? には I で答えるのが基本だが、Are you and 〜 〜? のようにあなた以外の人もふくまれていたら we で答える。問題文の主語をよく見ること。\\n\\n★ ポイント：人でないものは、犬でも本でも it（複数なら they）。ペットを he / she と呼ぶこともあるが、テストでは it でよい。\",\"figureId\":\"xf_eigo_s195\",\"mangaId\":\"eigo_s195_xm\"},{\"heading\":\"たずねられた語で受ける\",\"body\":\"短答の三つ目の部分（be動詞・助動詞・do系）は、たずねられた文の先頭の語をそのまま返すのが原則である。\\n\\n■ 対応表\\nIs / Are / Was / Were →　is / are / was / were\\nDo / Does / Did →　do / does / did\\nCan / Will / May / Must / Should →　can / will / may / must / should\\n\\n例）Was your brother at home? — Yes, he was.\\n例）Did you finish your homework? — No, I didn't.\\n例）Can Ken ride a unicycle? — Yes, he can.\\n例）Will they come to the party? — No, they won't.\\n\\n■ 短縮形が使えるかどうか\\nNo の答えでは短縮形が使える。No, it isn't. / No, I don't. / No, he can't. / No, they won't.\\nYes の答えでは短縮できない。Yes, it is.（× Yes, it's.）／Yes, I am.（× Yes, I'm.）\\n\\nこれは、短縮形が「うしろに語が続くときだけ使える弱い形」だからである。文の最後に来る語は強く発音されるので、縮めることができない。\\n\\n■ Yes/No 以外の答え方\\n会話では Of course.（もちろん）、Sure.（いいよ）、I think so.（そう思う）、I hope so.（そうだといいね）なども使う。会話文の問題ではこれらが答えの選択肢になることが多い。\"}],\"trapExamples\":[{\"question\":\"Are you and your sister good at English? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, I am.\",\"trapExplanation\":\"Are you 〜? の形を見た瞬間に「you と聞かれたら I で答える」という覚え方が働き、主語が you and your sister という二人であることを読み飛ばしてしまう。\",\"correctAnswer\":\"Yes, we are.\",\"correctExplanation\":\"主語は「あなたとあなたのお姉さん」の二人なので、答えるときは自分たちをまとめて we になる。be動詞も we に合わせて are。「you と聞かれたら I」ではなく「主語が何人かを数えてから代名詞を決める」と手順を直す。\"},{\"question\":\"Is this your umbrella? に Yes で答えなさい。\",\"wrongAnswer\":\"Yes, this is.\",\"trapExplanation\":\"たずねられた文の主語 this をそのまま写してしまう。日本語では「はい、これです」と言えるので、そのまま英語にしてしまうのが原因。\",\"correctAnswer\":\"Yes, it is.\",\"correctExplanation\":\"短答では主語を代名詞に置きかえる決まりがあり、this / that は it、these / those は they になる。Yes, this is. という英語は使わない。同じく Is that your dog? — Yes, it is.、Are those your shoes? — Yes, they are. となる。\"}]}",
"{\"id\":\"eigo_s196\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"what①：「何」をたずねる疑問文の骨組み\",\"description\":\"疑問詞を先頭に置き、そのあとを Yes/No疑問文と同じ語順にする\",\"intro\":\"What do you have in your bag? — 疑問詞 What を先頭に置いたあとは、do you have というふつうの疑問文の語順がそのまま続きます。つまり「疑問詞＋Yes/No疑問文」という二階建ての形です。この組み立て方を知れば、どの疑問詞でも同じように作れます。\",\"order\":696,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"疑問詞（what, who, when など）は必ず文の先頭に置く。\",\"疑問詞のうしろは Yes/No疑問文とまったく同じ語順（do/does/be動詞＋主語＋動詞）。\",\"疑問詞つきの疑問文には Yes / No で答えない。中身をそのまま答える。\",\"What is 〜? は What’s 〜? と短縮できる。\",\"文の終わりの ? を忘れない。読むときは下がり調子で読む。\"],\"sections\":[{\"heading\":\"疑問詞つき疑問文の作り方\",\"mangaId\":\"eigo_s196_manga\",\"body\":\"「これは何ですか」「あなたは何がほしいですか」のように、Yes / No では答えられない内容をたずねるときは疑問詞を使う。作り方は二段階で覚えるとかんたんである。\\n\\n■ 二段階の手順\\n①まず、ふつうの Yes/No疑問文を作る\\n②その先頭に疑問詞をくっつけ、たずねたい部分の語を消す\\n\\n例）You want a new bike.（あなたは新しい自転車がほしい）\\n　→ ①Do you want a new bike?\\n　→ ②What do you want?（a new bike を消して What を先頭へ）\\n\\n例）This is a camera.\\n　→ ①Is this a camera?\\n　→ ②What is this?（What's this?）\\n\\n■ 代表的な形\\nWhat is this / that?（これ／あれは何ですか）\\nWhat is your name?（お名前は）\\nWhat do you have in your hand?（手に何を持っていますか）\\nWhat does he do after school?（彼は放課後に何をしますか）\\nWhat did you eat for lunch?（昼食に何を食べましたか）\\n\\n⚠ 注意：What you want? のように do を落とす誤りが非常に多い。疑問詞のうしろは「疑問文の語順のまま」であって、平叙文の語順に戻るわけではない。\",\"figureId\":\"lf_eigoext06_196\"},{\"heading\":\"答え方（Yes / No では答えない）\",\"body\":\"疑問詞のついた疑問文は、たずねている中身が決まっているので Yes / No で答えることはできない。聞かれた内容をそのまま答える。\\n\\n■ 答え方の例\\nWhat is this? — It is a camera.（It's a camera.）\\nWhat do you want? — I want a new bike.／A new bike.\\nWhat does your father do? — He is a doctor.（職業をたずねる決まった言い方）\\nWhat did you do yesterday? — I played soccer with my friends.\\n\\n会話では A new bike. のように必要な部分だけを短く答えることも多い。文で答えるときは、たずねられた文の主語・動詞をそろえるとまちがえない。\\n\\n■ 主語と動詞をそろえる\\nWhat do you have? — I have a pen.（you → I、have はそのまま）\\nWhat does she like? — She likes music.（does を消したので likes と s が復活する）\\nWhat did he buy? — He bought a book.（did を消したので過去形 bought に戻す）\\n\\n★ ポイント：do / does / did は疑問文のあいだだけ動詞の印を預かっている。答えの文では do / does / did が消えるので、預けていた印（三単現の s、過去形）を動詞に返してやる、と考えるとよい。\\n\\n■ What's の使い方\\nWhat is は What's と縮められる。What's this? / What's your name? / What's the matter?（どうしたの）。ただし What's は「What is」だけでなく「What has」の短縮でもあるので、読解では注意する。\"}],\"trapExamples\":[{\"question\":\"「あなたはかばんの中に何を持っていますか」を英語にしなさい。\",\"wrongAnswer\":\"What you have in your bag?\",\"trapExplanation\":\"「What＝何」と「you have＝あなたは持っている」を日本語の順に置いただけになっている。疑問詞を先頭に出したことで疑問文が完成したと思いこみ、do を入れ忘れる。\",\"correctAnswer\":\"What do you have in your bag?\",\"correctExplanation\":\"疑問詞のうしろは Yes/No疑問文とまったく同じ語順になる。まず Do you have 〜? という疑問文を作り、その前に What を置く、という順で組み立てる。ただし What が主語のとき（What happened?）だけは do が不要で、これは別に学ぶ。\"},{\"question\":\"What do you have for breakfast? に答えなさい。\",\"wrongAnswer\":\"Yes, I have bread.\",\"trapExplanation\":\"疑問文だから Yes から答える、という形だけの反応をしてしまう。文の先頭が What であることを見落としている。\",\"correctAnswer\":\"I have bread and milk.\",\"correctExplanation\":\"疑問詞のある疑問文は「何を」「だれが」など中身をたずねているので、Yes / No では答えられない。答えは聞かれた部分（この場合は食べるもの）を示す。文の先頭が疑問詞かどうかを見てから答え方を決める習慣をつける。\"}]}",
"{\"id\":\"eigo_s197\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"what②：What ＋ 名詞（time / color / day / subject）\",\"description\":\"What のうしろに名詞をつけて「何の〜」とたずねる形をそろえる\",\"intro\":\"「何時ですか」は What time is it? です。What のうしろに time という名詞をくっつけて「何の時間」とたずねています。同じように What color、What day、What subject と作れます。日本語では「何色」「何曜日」と一語に見えますが、英語では二語に分かれているのです。\",\"order\":697,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"What のうしろに名詞を置くと「何の〜・どんな〜」という意味になる（What time / What color）。\",\"What ＋ 名詞 はひとかたまりで文の先頭に置く。とちゅうで切らない。\",\"What time is it? は時刻、What time do you 〜? は「何時に〜するか」。答え方がちがう。\",\"What day is it today? は曜日、What’s the date today? は日付をたずねる。\",\"答えるときの前置詞に注意（at seven / on Monday / in April）。\"],\"sections\":[{\"heading\":\"What ＋ 名詞 の形\",\"body\":\"What だけでは「何」とばくぜんとしているが、うしろに名詞を置くと「何の〜」と範囲をしぼることができる。この二語はひとかたまりとして扱い、そろえて文の先頭に置く。\\n\\n■ よく出る組み合わせ\\nWhat time（何時）／What day（何曜日）／What color（何色）／What sport（何のスポーツ）／What subject（何の教科）／What kind of 〜（どんな種類の〜）／What language（何語）\\n\\n例）What color do you like?（何色が好きですか）\\n　— I like blue.\\n例）What sport does he play?（彼は何のスポーツをしますか）\\n　— He plays baseball.\\n例）What subject do you like best?（何の教科がいちばん好きですか）\\n　— I like science best.\\n例）What kind of music do you listen to?（どんな種類の音楽を聞きますか）\\n　— I listen to J-pop.\\n\\n⚠ 注意：What color do you like? を What do you like color? のように分けてはいけない。What と color は切りはなせない一つのまとまりである。\\n\\n★ ポイント：What kind of のうしろの名詞には ふつう a / an を付けない（What kind of book do you read?）。\"},{\"heading\":\"時刻・曜日・日付のたずね方\",\"body\":\"時に関する言い方は形が似ていて混同しやすいので、たずね方と答え方をセットで覚える。\\n\\n■ 今の時刻\\nWhat time is it (now)? — It's seven thirty.（七時半です）\\nこの it は「時刻の it」で、「それ」という意味はない。答えの文でも It's 〜 で始める。\\n\\n■ 「何時に〜しますか」\\nWhat time do you get up? — I get up at six.\\nこの場合は「あなたが起きる時刻」をたずねているので、答えは I get up at six. のように主語と動詞をそろえて言う。時刻の前に at を付けるのを忘れない。\\n例）What time does the movie start? — It starts at two.\\n\\n■ 曜日\\nWhat day is it today? — It's Monday.（今日は月曜日です）\\nWhat day of the week is it? も同じ意味。\\n\\n■ 日付\\nWhat's the date today? — It's May 5.（五月五日です）\\n日付をたずねるときは day ではなく date を使う。\\n\\n⚠ 注意：What day is it today? に It's May 5. と日付で答えるのは誤り。day は曜日、date は日付、と対応させて覚えること。\\n\\n■ 月・年\\nWhat month is it? — It's July.\\nWhen is your birthday? — It's in April.（月の前は in）\",\"figureId\":\"xf_eigo_s197\",\"mangaId\":\"eigo_s197_xm\"}],\"trapExamples\":[{\"question\":\"What time do you go to bed? に答えなさい。\",\"wrongAnswer\":\"It's ten.\",\"trapExplanation\":\"What time で始まる文を見ると、反射的に「時刻をたずねる What time is it?」の答えである It's 〜 を書いてしまう。文のうしろの do you go to bed（あなたは寝る）を読んでいない。\",\"correctAnswer\":\"I go to bed at ten.\",\"correctExplanation\":\"この文は「あなたは何時に寝ますか」と、あなたの行動の時刻をたずねている。答えの主語は I で、動詞は go to bed、そして時刻の前に at を付ける。It’s 〜 で答えてよいのは What time is it? のように「今の時刻そのもの」をたずねられたときだけである。\"},{\"question\":\"What day is it today? に答えなさい（今日は5月5日の月曜日）。\",\"wrongAnswer\":\"It's May 5.\",\"trapExplanation\":\"日本語で「今日は何日？」「今日は何曜日？」のどちらも「今日は何？」と言えるため、day を「日」と訳して日付を答えてしまう。\",\"correctAnswer\":\"It's Monday.\",\"correctExplanation\":\"What day 〜? は曜日をたずねる言い方で、答えは Sunday 〜 Saturday のいずれかになる。日付をたずねるときは What’s the date today? と date を使い、It’s May 5. と答える。day＝曜日、date＝日付、と結びつけて覚える。\"}]}",
"{\"id\":\"eigo_s198\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"which①：「どちら・どれ」と選ばせる疑問文\",\"description\":\"Which と or を組み合わせて選択をたずねる形と、その答え方を学ぶ\",\"intro\":\"「コーヒーと紅茶、どちらがいいですか」は Which do you like, coffee or tea? です。えらぶものを or でならべ、コンマのあとに付け足すのが英語のやり方。答えるときは Yes や No ではなく、えらんだほうを言います。ここが Yes/No疑問文とのちがいです。\",\"order\":698,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Which は「示された範囲の中でどれ・どちら」とたずねる疑問詞。\",\"Which ＋ 名詞（Which book / Which bus）の形も What と同じように作れる。\",\"選択肢を並べるときは A or B とし、and は使わない。\",\"A or B の疑問文には Yes / No で答えず、選んだほうを答える。\",\"Which one 〜? の one は前に出た名詞のかわり。答えでは This one. などと言える。\"],\"sections\":[{\"heading\":\"Which の使い方\",\"body\":\"Which は「どれ・どちら」という意味で、選ぶ相手がある程度決まっているときに使う。目の前に二つ以上のものが示されている場面を思いうかべるとよい。\\n\\n■ Which だけで使う\\nWhich is your bag?（どれがあなたのかばんですか）\\nWhich do you like better, cats or dogs?（ねこと犬ではどちらが好きですか）\\n\\n■ Which ＋ 名詞\\nWhich bus goes to the station?（どのバスが駅に行きますか）\\nWhich season do you like the best?（どの季節がいちばん好きですか）\\nWhich color do you want, red or blue?\\n\\n■ 選択肢の並べ方\\n二つ（以上）の候補を示すときは、文の最後にコンマを打って A or B を続ける。\\n例）Which do you want, tea or coffee?\\n例）Which is bigger, the sun or the moon?\\n※ and を使うと「両方」の意味になってしまい、選ばせる文にならない。必ず or を使う。\\n\\n■ 読み方\\nA or B の疑問文は、A を上がり調子、B を下がり調子で読む。Yes/No疑問文のように最後まで上げると、意味が変わってしまう。\\n\\n★ ポイント：Which one do you want? の one は、前に出た名詞のくり返しをさけるための語。答えも This one, please. のように one を使える。\",\"figureId\":\"xf_eigo_s198\",\"mangaId\":\"eigo_s198_xm\"},{\"heading\":\"答え方と、比べる言い方\",\"body\":\"■ Yes / No では答えない\\nWhich do you like, summer or winter? に Yes, I like summer. と答えるのは誤り。選んだほうをそのまま答える。\\n　— I like summer.／Summer.／Summer is better for me.\\n\\n■ better / the best をそえる形\\n二つのうちどちらかを選ぶときは better、三つ以上から選ぶときは the best を使うことが多い。\\n例）Which do you like better, math or English? — I like math better.\\n例）Which season do you like the best? — I like spring the best.\\n\\n答えの文にも better / the best をそのまま入れると自然になる。\\n\\n■ Which と be動詞・一般動詞\\nWhich is your desk?（be動詞の文）— That one is.／This is.\\nWhich do you use?（一般動詞の文）— I use this one.\\n形は what と同じで、疑問詞のうしろは疑問文の語順になる。\\n\\n⚠ 注意：Which is taller, Ken or Tom? のように「二つを比べてどちらか」をたずねる文では、比較級（taller）を使う。答えは Ken is.（＝Ken is taller.）のように短く言える。\\n\\n■ 選択肢が示されないときは what\\nWhich do you want? は「ここにあるうちのどれ」、What do you want? は「何でもよいから何がほしいか」。次の課でくわしく区別する。\"}],\"trapExamples\":[{\"question\":\"Which do you like better, dogs or cats? に「犬のほうが好きです」と答えなさい。\",\"wrongAnswer\":\"Yes, I like dogs.\",\"trapExplanation\":\"文の形が Do you like 〜? に似ているので Yes/No疑問文だと思ってしまう。文頭の Which と、文末の A or B という選択の形を見落としている。\",\"correctAnswer\":\"I like dogs better.\",\"correctExplanation\":\"Which で始まる文も、A or B で選ばせる文も、Yes / No では答えられない。選んだほうを答える。better をそえると「（二つのうちで）そちらのほうが好き」という意味がはっきりする。会話では Dogs. と一語で答えてもよい。\"},{\"question\":\"「紅茶とコーヒーではどちらがほしいですか」を英語にしなさい。\",\"wrongAnswer\":\"Which do you want, tea and coffee?\",\"trapExplanation\":\"日本語の「紅茶とコーヒー」の「と」をそのまま and に置きかえてしまう。and にすると「紅茶とコーヒーの両方」という意味になり、選ばせる文にならない。\",\"correctAnswer\":\"Which do you want, tea or coffee?\",\"correctExplanation\":\"選択肢を並べて「どちらか」を選ばせるときは or を使う。日本語の「と」に引きずられないよう、「Which の文とセットになるのは or」と形で覚えてしまうとよい。三つ以上並べるときは A, B or C のように最後だけ or にする。\"}]}",
"{\"id\":\"eigo_s199\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"what と which の使い分け\",\"description\":\"選ぶ範囲が示されているかどうかで What と Which を選び分ける\",\"intro\":\"「何のスポーツが好きですか」は What sport do you like? です。ところが目の前に野球とサッカーのボールだけがあるなら、Which sport do you like? になります。えらぶ範囲が示されているかどうかで、使う語が変わるのです。この一点だけで見分けられます。\",\"order\":699,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"選ぶ範囲が示されている（目の前にある・A or B がある）ときは Which。\",\"範囲がしぼられておらず、自由に答えられるときは What。\",\"Which ＋ 名詞 / What ＋ 名詞 のどちらの形もあるので、名詞の有無では区別できない。\",\"A or B が文の中にあれば、まず Which を疑う。\",\"Which of 〜（〜のうちのどれ）の形では、うしろは the や these の付いた名詞になる。\"],\"sections\":[{\"heading\":\"「範囲があるか」で決める\",\"body\":\"What と Which はどちらも「何・どれ」と訳せるので、日本語からは決められない。判断のかぎは「選ぶ範囲が示されているかどうか」の一点である。\\n\\n■ 範囲が示されている → Which\\n・目の前に品物が並んでいる\\n・A or B と候補が文の中に出ている\\n・of these / of them のように、集まりが示されている\\n\\n例）Which do you want, this one or that one?\\n例）Which of these books is yours?\\n例）Which bus should I take?（バスは何番か何番か、と数が決まっている）\\n\\n■ 範囲が示されていない → What\\n・何と答えてもよい\\n・候補が示されていない\\n\\n例）What do you want for your birthday?（何でもよい）\\n例）What is your favorite sport?（世界中のスポーツから自由に）\\n例）What time is it?（時刻は無数にある）\\n\\n⚠ 注意：「Which は二つのとき、What は三つ以上のとき」という覚え方はまちがい。三つ以上でも範囲が決まっていれば Which を使う（Which of the five do you want?）。数ではなく範囲で決める。\",\"figureId\":\"lf_eigoext06_199\",\"mangaId\":\"eigo_s199_xm\"},{\"heading\":\"まぎらわしい場面を見分ける\",\"body\":\"■ 同じ内容でも場面でちがう\\n（レストランのメニューを見せながら）Which would you like?\\n（何も見せずに）What would you like to eat?\\n\\n同じ「何にしますか」でも、選ぶものが示されていれば Which、示されていなければ What になる。入試の会話文では、直前の文に候補が並んでいるかどうかが手がかりになる。\\n\\n■ 名詞が付いても同じ規準\\nWhat sport do you play?（スポーツ全般から自由に）\\nWhich sport do you like, soccer or tennis?（二つの中から）\\n名詞が付くかどうかは関係なく、範囲があるかどうかで決まる。\\n\\n■ Which of 〜 の形\\nWhich of these caps is yours?（これらの帽子のうちどれがあなたのですか）\\nWhich of you can swim?（あなたたちのうちだれが泳げますか）\\nof のうしろは these / the / you のように、まとまりが決まっている語になる。What of 〜 という言い方はしない。\\n\\n★ ポイント：問題文に or が見えたら、まず Which を候補に考える。ただし Do you want tea or coffee?（Yes/No疑問文＋or）のように、Which を使わない形もあるので、文頭に空所があるかどうかも確かめる。\\n\\n■ 決まり文句\\nWhat about 〜? / How about 〜?（〜はどうですか）はどちらもよく使う言い方で、Which about 〜? という形はない。\"}],\"trapExamples\":[{\"question\":\"（メニューを見せながら）「＿＿ do you want, tea or coffee?」の空所に入る語を答えなさい。\",\"wrongAnswer\":\"What\",\"trapExplanation\":\"「何がほしいですか」という日本語訳から What を選んでしまう。文末に tea or coffee という候補が示されていることに注目していない。\",\"correctAnswer\":\"Which\",\"correctExplanation\":\"tea or coffee という二つの候補が文の中に示されているので、選ぶ範囲が決まっている。範囲が決まっているときは Which を使う。文中に「A or B」があるかどうかが、この判断でいちばん確実な手がかりになる。\"},{\"question\":\"「あなたの好きな教科は何ですか」を英語にしなさい（候補は示されていない）。\",\"wrongAnswer\":\"Which is your favorite subject?\",\"trapExplanation\":\"「教科」という限られた集まりから選ぶのだから Which だ、と考えてしまう。しかし「学校の教科」という分類は文の中に示された候補ではない。\",\"correctAnswer\":\"What is your favorite subject?\",\"correctExplanation\":\"この場面では候補が文中に並べられていないので、自由に答えられる What を使う。Which を使うのは Which is your favorite, math or science? のように候補を示したときや、目の前に時間割を見せながらたずねるときである。\"}]}",
"{\"id\":\"eigo_s200\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"who①：「だれ」をたずねる\",\"description\":\"Who is 〜? と Who do you 〜? の形をそろえ、be動詞の数の一致に注意する\",\"intro\":\"「あの女の子はだれですか」は Who is that girl?、「あの子たちはだれですか」は Who are those girls? です。Who の形は変わらないのに、be動詞はうしろの語に合わせて変わります。さらに Who do you like? のように do を使う形もある。二つの型を見わけていきます。\",\"order\":700,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Who は人についてたずねる疑問詞。答えでは名前や関係（my brother など）を言う。\",\"Who is that man? のような文では、be動詞をうしろの主語に合わせる（Who are those girls?）。\",\"Who do you like? は「あなたはだれが好きか」と、好かれる相手をたずねる形。\",\"Who is 〜? の答えは He is 〜. / She is 〜. / They are 〜. と代名詞で受ける。\",\"Who が主語になる形（Who broke it?）は語順が変わらない。あとの課で学ぶ。\"],\"sections\":[{\"heading\":\"Who is 〜? の形と数の一致\",\"body\":\"Who は「だれ」と人をたずねる疑問詞である。いちばんよく使うのは、人を指して「あの人はだれですか」とたずねる形である。\\n\\n■ 基本の形\\nWho is that man? — He is my uncle.\\nWho is she? — She is Ms. Green, our new teacher.\\nWho are those boys? — They are my classmates.\\n\\n■ be動詞は「うしろの語」に合わせる\\nWho 自体は単数にも複数にも使えるので、be動詞はうしろに来る語で決める。\\n・Who is that girl?（that girl は単数 → is）\\n・Who are those girls?（those girls は複数 → are）\\n・Who were they?（they は複数 → were）\\n\\n⚠ 注意：Who is those boys? は誤り。日本語の「あの子たちはだれですか」につられて is にしてしまいやすい。うしろの名詞が複数形（-s）かどうかを必ず確かめる。\\n\\n■ 電話や紹介の決まり文句\\nWho is calling, please?（どちら様ですか）\\nWho is speaking?（電話で「どなたですか」）\\nThis is Ken speaking.（こちらはケンです）\\n電話では I am Ken. ではなく This is Ken. と言う。会話文の問題で頻出。\\n\\n★ ポイント：Who's は Who is の短縮形。Whose（だれの）と発音が同じなので、書くときに取りちがえないよう気をつける。\",\"figureId\":\"xf_eigo_s200\"},{\"heading\":\"「だれを」をたずねる形\",\"body\":\"Who は「だれが」だけでなく「だれを」の意味でもたずねられる。その場合は一般動詞の疑問文と同じく do / does / did が必要になる。\\n\\n■ 目的語をたずねる形\\nYou like Ken.（あなたはケンが好きだ）\\n　→ Who do you like?（あなたはだれが好きですか）\\n　— I like Ken.\\n\\nHe met Ms. Sato yesterday.\\n　→ Who did he meet yesterday?\\n　— He met Ms. Sato.\\n\\n■ 前置詞が残る形\\nたずねたい人が前置詞のうしろにあった場合、その前置詞は文の最後に残る。\\nYou are waiting for Tom.\\n　→ Who are you waiting for?（だれを待っているのですか）\\nYou went there with Ken.\\n　→ Who did you go there with?\\n\\n⚠ 注意：Who are you waiting? のように for を落とすと、意味が通じない文になる。もとの文にあった前置詞は消さずに最後まで書くこと。この点は次の課でくわしく練習する。\\n\\n■ 答え方\\nWho do you like? — I like my grandmother.\\nWho did you see? — I saw Ken and Tom.\\nYes / No では答えない。人の名前や、my brother のような言い方で答える。\",\"mangaId\":\"eigo_s200_xm\"}],\"trapExamples\":[{\"question\":\"「あの少年たちはだれですか」を英語にしなさい。\",\"wrongAnswer\":\"Who is those boys?\",\"trapExplanation\":\"Who を単数だと思いこみ、be動詞をいつも is にしてしまう。日本語では「だれですか」と単数・複数の区別がないため、うしろの those boys が複数であることを意識しにくい。\",\"correctAnswer\":\"Who are those boys?\",\"correctExplanation\":\"Who 自体には単数・複数の形がないので、be動詞はうしろの語に合わせる。those boys は複数なので are になる。答えも They are my friends. と複数で受ける。一人なら Who is that boy? — He is my friend. となる。\"},{\"question\":\"「あなたはだれを待っているのですか」を英語にしなさい。\",\"wrongAnswer\":\"Who are you waiting?\",\"trapExplanation\":\"日本語の「だれを待つ」には前置詞がないため、英語でも for が要らないと感じてしまう。wait for でひとかたまりの意味になることを知らないと必ず落とす。\",\"correctAnswer\":\"Who are you waiting for?\",\"correctExplanation\":\"もとの文は You are waiting for Tom. で、たずねたい Tom は for のうしろにあった。Who を先頭に出しても for は行き場がなく、文の最後に取り残される。look for（さがす）、listen to（聞く）なども同じで、最後の前置詞を書き落とさないこと。\"}]}",
"{\"id\":\"eigo_s201\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"whose：「だれの」をたずねる\",\"description\":\"Whose ＋ 名詞 の語順と、所有代名詞（mine / Ken’s）での答え方を身につける\",\"intro\":\"「これはだれのかさですか」は Whose umbrella is this? です。日本語では「だれの」でいったん切れますが、英語では whose と umbrella をくっつけて、まとめて先頭に置きます。答えるときは It's mine. のように、名詞をくり返さない言い方を使います。\",\"order\":701,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Whose は「だれの」。Whose ＋ 名詞 をひとかたまりにして文の先頭に置く。\",\"Whose is this bag? のように名詞をはさまない形も正しい。\",\"答えは「所有格＋名詞」（It is my bag.）か「所有代名詞」（It is mine.）。\",\"人名の所有は名前＋アポストロフィ s（Ken’s＝ケンの／ケンのもの）。\",\"Whose と Who’s（＝Who is）は発音が同じ。意味で書き分ける。\"],\"sections\":[{\"heading\":\"Whose ＋ 名詞 の語順\",\"body\":\"Whose は「だれの」という意味の疑問詞である。「だれの＋何」という日本語のとおり、うしろに名詞をくっつけてひとかたまりで使うのが基本形である。\\n\\n■ 基本の形\\nWhose bag is this? — It is my bag.／It is mine.\\nWhose pencils are these? — They are Ken's.\\nWhose car is that? — It is my father's.\\n\\n作り方は、This is my bag. の my をたずねる、と考えるとよい。\\n　This is my bag. → Whose bag is this?（my bag の my をたずね、Whose bag をまとめて先頭へ）\\n\\n■ 名詞をはさまない形\\nWhose is this bag? という言い方もでき、意味は同じである。この場合 Whose は「だれのもの」という意味で単独で使われている。\\nWhose are these? — They are mine.\\n\\n⚠ 注意：Whose is bag this? のように、名詞を切りはなしてばらばらに置くことはできない。Whose bag（だれのかばん）は二語で一つのまとまりだと意識する。\\n\\n★ ポイント：Whose のうしろの名詞には a / an / the を付けない。× Whose a bag is this? ／○ Whose bag is this?\",\"figureId\":\"lf_eigoext06_201\"},{\"heading\":\"答え方（所有格と所有代名詞）\",\"body\":\"Whose 〜? への答え方は二通りある。どちらも正しいが、形をきちんと区別しておく必要がある。\\n\\n■ ①所有格＋名詞\\nmy bag / your pen / his book / her cap / our school / their house\\n例）Whose bag is this? — It is my bag.\\n\\n■ ②所有代名詞（一語で「〜のもの」）\\nmine（私のもの）／yours（あなたのもの）／his（彼のもの）／hers（彼女のもの）／ours（私たちのもの）／theirs（彼らのもの）\\n例）Whose bag is this? — It is mine.\\n\\n所有代名詞のうしろに名詞を置くことはできない。× It is mine bag. ／○ It is my bag. または It is mine.\\n\\n■ 人名の場合\\n名前にアポストロフィと s を付ける。Ken's（ケンの／ケンのもの）、my father's（父の／父のもの）、Ms. Green's。\\n例）Whose racket is this? — It's Ken's.（ケンのものです）\\n※ 名前だけで It's Ken. と答えると「これはケンです」となってしまい、意味がおかしくなる。\\n\\n■ 複数形の所有\\n語尾が s の複数形にはアポストロフィだけを付ける。the students' room（生徒たちの部屋）。\\n語尾が s でない複数形（children, men）は children's のように 's を付ける。\\n\\n⚠ 注意：his は「彼の」と「彼のもの」の両方に使える特別な語。His book is here.／This book is his. のどちらも正しい。\",\"mangaId\":\"eigo_s201_xm\"}],\"trapExamples\":[{\"question\":\"Whose notebook is this? に「私のです」と答えなさい。\",\"wrongAnswer\":\"It's me.\",\"trapExplanation\":\"日本語の「私のです」を「私＝me」と単純に置きかえてしまう。me は「私を・私に」という形で、「私のもの」という意味は表せない。\",\"correctAnswer\":\"It's mine.\",\"correctExplanation\":\"「〜のもの」を一語で表す所有代名詞を使う。私のもの＝mine、あなたのもの＝yours、彼のもの＝his、彼女のもの＝hers。It’s my notebook. と答えてもよい。I / my / me / mine の四つの形を表にして覚えておくと迷わない。\"},{\"question\":\"Whose racket is this? に「ケンのです」と答えなさい。\",\"wrongAnswer\":\"It's Ken.\",\"trapExplanation\":\"名前をそのまま置けば「ケンの」になると思ってしまう。しかし It’s Ken. は「これはケンです」という意味になり、ラケットが人になってしまう。\",\"correctAnswer\":\"It's Ken's.\",\"correctExplanation\":\"人名で「〜の・〜のもの」を表すときは、名前にアポストロフィと s を付けて Ken’s とする。Whose racket is this? — It’s Ken’s racket. と名詞を付けてもよいが、くり返しをさけて It’s Ken’s. と言うのがふつうである。\"}]}",
"{\"id\":\"eigo_s202\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"whom と前置詞の位置\",\"description\":\"前置詞が文の最後に残る疑問文を作り、who と whom の使い分けを知る\",\"intro\":\"「だれといっしょに住んでいるのですか」は Who do you live with? となり、with が文の最後に取り残されます。日本語なら「だれと」で一続きになるので、この形はとても不思議に見えます。前置詞が最後に残るという英語の語順を、ここでしっかり身につけます。\",\"order\":702,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"たずねたい語が前置詞のうしろにあったときは、その前置詞は文の最後に残る。\",\"with / for / to / about / at などの落としに注意（Who did you go with?）。\",\"whom は「だれを・だれに」の固い形。ふだんの会話や中学受験では who でよい。\",\"主語をたずねるときは whom ではなく who を使う（Who is coming?）。\",\"With whom did you go? のように前置詞を先頭に置く形は非常に固い書き言葉。\"],\"sections\":[{\"heading\":\"前置詞が文の最後に取り残される\",\"body\":\"疑問文を作るとき、たずねたい語を疑問詞に変えて先頭に出す。その語がもともと前置詞のうしろにあった場合、前置詞だけが元の場所に取り残される。\\n\\n■ 作り方をたどる\\nI go to school with Ken.（私はケンと学校へ行く）\\n　→ Ken をたずねたい\\n　→ Ken を Who に変えて先頭へ\\n　→ Who do you go to school with?（だれと学校へ行きますか）\\n\\nwith は Ken を連れていってくれないので、そのまま最後に残る。これが英語の疑問文の大きな特徴である。\\n\\n■ よく出る形\\nWho are you waiting for?（だれを待っていますか）← wait for\\nWho did you talk about?（だれについて話したのですか）← talk about\\nWho are you looking for?（だれをさがしていますか）← look for\\nWhat are you looking at?（何を見ているのですか）← look at\\nWhat are you thinking about?（何を考えているのですか）← think about\\nWhere are you from?（どこの出身ですか）← be from\\n\\n⚠ 注意：日本語には「〜と」「〜を」にあたる助詞があるが、英語の前置詞は文の最後に置かれるため、日本語から英作文すると必ず落としやすい。書き終えたら「もとの文にあった前置詞を全部書いたか」を確かめる。\",\"figureId\":\"lf_eigoext06_202\"},{\"heading\":\"who と whom\",\"mangaId\":\"eigo_s202_manga\",\"body\":\"英語には「だれが」を表す who と、「だれを・だれに」を表す whom という二つの形がある。日本語の「が」と「を」の区別に近い。\\n\\n■ whom の使いどころ\\n・動詞の目的語：Whom did you meet?（だれに会いましたか）\\n・前置詞のうしろ：With whom did you go?（だれと行きましたか）\\n\\nしかし、今の英語では話し言葉でも書き言葉でも who を使うのがふつうで、whom はかなり固い言い方に限られる。中学受験でも Who did you meet? で正しい。\\n・ふつう：Who did you meet?\\n・固い形：Whom did you meet?\\n\\n■ whom を使ってはいけない場合\\n主語をたずねるときは必ず who である。\\n○ Who is coming to the party?\\n× Whom is coming to the party?\\nwhom はあくまで「だれを・だれに」であって、「だれが」の意味では使えない。\\n\\n■ 前置詞を先頭に置く形\\n前置詞ごと先頭に出す言い方もあるが、そのときは必ず whom になる。\\n・With whom did you go?（固い）\\n・Who did you go with?（ふつう）\\n・× With who did you go?（この形は誤り）\\n\\n★ ポイント：中学受験では「前置詞は文の最後に残す・疑問詞は who でよい」の二点をおさえれば十分である。whom は読解で出てきたときに意味がわかればよい。\"}],\"trapExamples\":[{\"question\":\"「あなたはだれと学校へ行きますか」を英語にしなさい。\",\"wrongAnswer\":\"Who do you go to school?\",\"trapExplanation\":\"日本語の「だれと」の「と」を Who がふくんでいると感じてしまい、with を書かない。文としては形が整って見えるので、見直しでも気づきにくい。\",\"correctAnswer\":\"Who do you go to school with?\",\"correctExplanation\":\"もとの文 I go to school with Ken. の Ken をたずねる形なので、with が文の最後に残る。英作文では「もとの平叙文を頭の中で作る → たずねたい語を疑問詞にして先頭へ → 前置詞は動かさない」という順に組み立てると落とさない。\"},{\"question\":\"「だれがパーティーに来るのですか」を英語にしなさい。\",\"wrongAnswer\":\"Whom is coming to the party?\",\"trapExplanation\":\"「whom のほうが正式でていねいな形だ」と覚えてしまい、どんな場面でも whom を使えばよいと考えてしまう。主語と目的語の区別を意識していない。\",\"correctAnswer\":\"Who is coming to the party?\",\"correctExplanation\":\"この文の疑問詞は「だれが」という主語にあたるので who を使う。whom が使えるのは「だれを・だれに」と、動詞や前置詞のうしろにあった語をたずねるときだけである。主語をたずねる文では do / does も不要で、語順も変わらない。\"}]}",
"{\"id\":\"eigo_s203\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"who / whose / who’s の総整理\",\"description\":\"音が同じ Whose と Who’s を書き分け、答え方の形をそろえる\",\"intro\":\"Whose と Who's は、声に出すとまったく同じ音です。それなのに Whose book is this?（だれの本）と Who's that boy?（だれですか）で意味はまるでちがいます。聞き取りでは前後の語しか手がかりがありません。書き分けと聞き分けを、ここで一度に整理します。\",\"order\":703,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Who＝だれ（人そのもの）、Whose＝だれの（持ち主）、Who’s＝Who is の短縮形。\",\"Whose と Who’s は発音が同じ。うしろに名詞が続けば Whose、動詞が続けば Who’s。\",\"Who is 〜? の答えは He is 〜. など、Whose 〜? の答えは It is mine. など。\",\"所有をたずねられたら mine / yours / his / hers / ours / theirs か 〜’s で答える。\",\"Who’s のうしろが -ing なら Who is 〜ing（進行形）だと見抜く。\"],\"sections\":[{\"heading\":\"三つの語の見分け方\",\"body\":\"who / whose / who's は音がまぎらわしく、聞き取りでも書き取りでもよくまちがえる。うしろに続く語の種類で機械的に見分けられる。\\n\\n■ Who（だれ）\\nうしろに be動詞や do / does / did が来て、人そのものをたずねる。\\n例）Who is that woman? / Who do you like?\\n\\n■ Whose（だれの）\\nうしろに名詞が来るか、または単独で「だれのもの」を表す。\\n例）Whose bike is this? / Whose is this bike?\\n\\n■ Who's（＝Who is / Who has）\\nうしろに名詞がなく、形容詞・-ing 形・場所を表す語などが来る。\\n例）Who's absent today?（きょうはだれが休みですか）\\n例）Who's singing over there?（あそこで歌っているのはだれですか）\\n\\n■ 見分けの手順\\n①うしろに名詞（bag, book, pen など）があるか → あれば Whose\\n②「だれは〜です」と be動詞でつなげられるか → つなげられれば Who's\\n例）＿＿ coming to the party? → coming は動詞の -ing 形なので Who's（＝Who is coming）\\n例）＿＿ umbrella is this? → umbrella は名詞なので Whose\\n\\n⚠ 注意：アポストロフィの有無は音では区別できないので、意味と語順で判断するしかない。リスニングでも同じで、うしろの語を最後まで聞いてから決める。\",\"figureId\":\"xf_eigo_s203\",\"mangaId\":\"eigo_s203_xm\"},{\"heading\":\"答え方をそろえる\",\"body\":\"たずねられた形によって答え方が決まっている。ここをそろえると、記述の失点が大きく減る。\\n\\n■ Who is 〜?（人はだれか）\\nWho is that man? — He is my teacher.／He is Mr. Sato.\\nWho are they? — They are my cousins.\\n答えの主語は he / she / they になる。It is my teacher. とは言わない。\\n\\n■ Whose 〜?（持ち主はだれか）\\nWhose cap is this? — It is mine.／It is Ken's.／It is my brother's.\\n答えの主語は it / they（もの）になる。He is mine. とは言わない。\\n\\n■ Who's 〜?（＝Who is 〜?）\\nWho's playing the piano? — Ken is.／Ken is playing the piano.\\n答えでは主語＋be動詞の形で短く受けられる。\\n\\n★ ポイント：「人をたずねられたら人（he / she）で答える、ものの持ち主をたずねられたら もの（it / they）で答える」と対応させる。日本語の「ケンのです」につられて主語を落とさないこと。\\n\\n■ 所有代名詞の一覧（答えでよく使う）\\nI → mine／you → yours／he → his／she → hers／we → ours／they → theirs\\n※ its（それのもの）は所有代名詞としてはほとんど使わない。\\n※ it's は it is の短縮形で、its（それの）とは別の語である。\"}],\"trapExamples\":[{\"question\":\"「＿＿ coming to the party?（だれがパーティーに来るの）」の空所に Whose か Who’s のどちらかを入れなさい。\",\"wrongAnswer\":\"Whose\",\"trapExplanation\":\"発音が同じなので、耳で覚えているとどちらでもよい気がしてしまう。「だれが」という日本語だけを手がかりにすると、Whose にも「だれ」が入っているため選んでしまう。\",\"correctAnswer\":\"Who's\",\"correctExplanation\":\"空所のうしろは coming という動詞の -ing 形で、名詞ではない。したがって「Who is coming（だれが来るのか）」の短縮形 Who’s が入る。Whose を使えるのは Whose bag（だれのかばん）のように、うしろに名詞が続くときだけである。\"},{\"question\":\"Whose are these pencils? に「私のです」と答えなさい。\",\"wrongAnswer\":\"They are my.\",\"trapExplanation\":\"「私の＝my」と一対一で覚えているため、名詞がなくても my で文を終えられると思ってしまう。my は必ずうしろに名詞が必要な形である。\",\"correctAnswer\":\"They are mine.\",\"correctExplanation\":\"my のうしろには名詞が要る（They are my pencils.）。名詞を言わずに終える場合は所有代名詞の mine を使う。主語は these pencils を受けて they になり、be動詞も are。my と mine の使い分けは、うしろに名詞があるかどうかで決まる。\"}]}",
"{\"id\":\"eigo_s204\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"when：「いつ」をたずねる\",\"description\":\"When の疑問文を作り、時を表す前置詞をそえて答える\",\"intro\":\"「いつ日本に来たのですか」は When did you come to Japan? です。答えは In 2020. や On Sunday. のように、前置詞を付けて言います。日本語なら「に」の一字ですむところですが、英語ではどの前置詞を選ぶかが決まっています。たずね方と答え方を対にして覚えます。\",\"order\":704,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"When は「いつ」と時をたずねる疑問詞。文の先頭に置き、うしろは疑問文の語順。\",\"答えは時を表す語句で言う。前置詞（at / on / in）を忘れない。\",\"When is your birthday? — It’s in April. のように月には in を使う。\",\"過去のことをたずねられたら、答えの動詞も過去形にする。\",\"What time はこまかい時刻、When はもっと広い「時」をたずねる。\"],\"sections\":[{\"heading\":\"When の疑問文\",\"body\":\"When は「いつ」と時をたずねる疑問詞である。作り方は What と同じで、疑問詞を先頭に置き、そのあとを疑問文の語順にする。\\n\\n■ be動詞の文\\nWhen is the school festival? — It's on November 3.\\nWhen is your birthday? — It's in May.\\nWhen was the party? — It was last Saturday.\\n\\n■ 一般動詞の文\\nWhen do you study at home? — I study after dinner.\\nWhen does the concert start? — It starts at six.\\nWhen did you come to Japan? — I came here two years ago.\\n\\n■ 答え方\\n答えは「時を表す語句」で言う。文で答えるときは、たずねられた文の主語・動詞をそろえる。\\n例）When did you finish it? — I finished it last night.（did が消えたので過去形に戻す）\\n例）When does he practice? — He practices every morning.（does が消えたので s が復活する）\\n\\n■ 時を表す語句の例\\ntoday / tomorrow / yesterday / this morning / next Sunday / last week / two days ago / after school / before dinner / in the morning / at night / every day\\n\\n⚠ 注意：When の疑問文に Yes / No で答えることはできない。When do you go? — Yes, I do. は誤り。\\n\\n★ ポイント：When と What time はどちらも時をたずねるが、What time は「何時何分」というこまかい時刻をたずねるときに使う。When はもっと広く、曜日・日付・季節・年でも答えられる。\"},{\"heading\":\"答えにそえる前置詞\",\"body\":\"When にどう答えるかで差がつくのは、時を表す前置詞である。ここは決まりを丸ごと覚えてしまう。\\n\\n■ at ＋ 時刻・一点の時\\nat seven（七時に）／at noon（正午に）／at night（夜に）／at that time（そのとき）\\n\\n■ on ＋ 曜日・日付・特定の日\\non Monday（月曜日に）／on May 5（五月五日に）／on Sunday morning（日曜の朝に）／on New Year's Day\\n\\n■ in ＋ 月・季節・年・午前午後\\nin April（四月に）／in summer（夏に）／in 2026（2026年に）／in the morning（午前中に）／in the afternoon\\n\\n■ 前置詞を付けない語\\nthis / next / last / every が付いた語句には前置詞を付けない。\\n○ next Sunday　× on next Sunday\\n○ last night　× in last night\\n○ every day　× on every day\\nまた today / tomorrow / yesterday にも前置詞は付けない。\\n\\n⚠ 注意：on Sunday morning のように「特定の日の朝」は on になる。in the morning（一般的な午前中）とのちがいに注意する。\\n\\n■ 期間を表す語\\nfor（〜のあいだ）：for three days\\nduring（〜のあいだじゅう）：during the summer vacation\\nbefore / after（〜の前に・あとに）：after school\",\"figureId\":\"xf_eigo_s204\",\"mangaId\":\"eigo_s204_xm\"}],\"trapExamples\":[{\"question\":\"When is your birthday? に「四月です」と答えなさい。\",\"wrongAnswer\":\"It's on April.\",\"trapExplanation\":\"「〜に」という日本語をすべて on に置きかえてしまう。日付に on を使う（on April 10）ことを知っていると、月だけのときにも on を付けてしまう。\",\"correctAnswer\":\"It's in April.\",\"correctExplanation\":\"月・季節・年のように広がりのある時には in を使う。日付まで言うときは on April 10 のように on になる。「点なら at、一日なら on、広い期間なら in」と、はばの大きさで覚えるとまちがえない。\"},{\"question\":\"When did you come to this town? に「二年前です」と文で答えなさい。\",\"wrongAnswer\":\"I come here two years ago.\",\"trapExplanation\":\"did で聞かれた疑問文では動詞が原形になっているので、答えでもそのまま come と書いてしまう。two years ago という過去を表す語があるのに時制を合わせていない。\",\"correctAnswer\":\"I came here two years ago.\",\"correctExplanation\":\"疑問文では did が過去の印を預かっていたが、答えの文には did がないので、動詞自身が過去形 came に戻る。〜 ago は必ず過去形といっしょに使う語なので、これも手がかりになる。\"}]}",
"{\"id\":\"eigo_s205\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"where：「どこ」をたずねる\",\"description\":\"Where の疑問文を作り、場所を表す前置詞をつけて答える\",\"intro\":\"「どこに住んでいるのですか」は Where do you live? ですが、答えは I live in Osaka. と in が要ります。ところが たずねる文のほうに in はありません。問いでは消え、答えでよみがえる。この前置詞の出入りが、書きかえ問題でよく問われます。\",\"order\":705,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Where は「どこ」と場所をたずねる疑問詞。うしろは疑問文の語順。\",\"Where is / are は主語の数に合わせる（Where are my shoes?）。\",\"答えでは場所の前に前置詞（in / on / at / under / near）が要ることが多い。\",\"Where are you from? は出身をたずねる決まった言い方。\",\"here / there には前置詞を付けない（× to here）。\"],\"sections\":[{\"heading\":\"Where の疑問文\",\"body\":\"Where は「どこ」と場所をたずねる。be動詞の文でも一般動詞の文でも、疑問詞を先頭に置いてうしろを疑問文の語順にする点は同じである。\\n\\n■ be動詞の文（「どこにありますか」）\\nWhere is my cap? — It's on the desk.\\nWhere are my shoes? — They are under the bed.\\nWhere is Ken? — He is in the library.\\n\\n主語が複数なら are、単数なら is。Where is my shoes? という誤りが多いので、うしろの名詞に -s が付いているかを確かめる。\\n\\n■ 一般動詞の文\\nWhere do you live? — I live in Osaka.\\nWhere does he play soccer? — He plays soccer in the park.\\nWhere did you buy it? — I bought it at that shop.\\n\\n■ 決まった言い方\\nWhere are you from? — I'm from Japan.（出身をたずねる）\\nWhere are you going? — I'm going to the station.\\nWhere shall we meet? — Let's meet in front of the station.\\n\\n⚠ 注意：Where は「どこ」という場所を表す語をすでにふくんでいるので、Where do you live in? のように前置詞を重ねる必要はない（in Osaka の in は答えの文で使う）。\\n\\n★ ポイント：たずねる文には前置詞が要らないのに、答えの文には前置詞が要る、という組み合わせが多い。ここが受験生のよく落とすところである。\",\"mangaId\":\"eigo_s205_xm\"},{\"heading\":\"答えに使う場所の前置詞\",\"body\":\"場所を答えるときは、位置関係に合った前置詞を選ぶ。図をかいて確かめられるようにしておく。\\n\\n■ 基本の三つ\\nin（〜の中に・広い場所に）：in the box／in Osaka／in Japan\\non（〜の上に・くっついて）：on the desk／on the wall（かべに）／on the second floor\\nat（〜の地点に）：at the station／at school／at home／at the bus stop\\n\\non は「上」だけでなく「面にくっついている」という意味なので、かべの絵は on the wall、天井のライトは on the ceiling となる。\\n\\n■ そのほかよく出るもの\\nunder（〜の下に）／by（〜のそばに）／near（〜の近くに）／between A and B（AとBのあいだに）／in front of（〜の前に）／behind（〜のうしろに）／over（〜の真上に）／along（〜にそって）／across from（〜の向かいに）\\n\\n例）The cat is under the table.\\n例）The bank is between the post office and the school.\\n例）There is a park in front of my house.\\n\\n■ 前置詞を付けない語\\nhere（ここに）／there（そこに）／home（家に）\\n○ Come here.　× Come to here.\\n○ I go home.　× I go to home.\\nただし at home（家に・在宅で）は名詞としての用法で、これは正しい。\\n\\n⚠ 注意：I live Osaka. のように前置詞を落とすと、文が成り立たない。live のあとに場所を言うときは必ず in / at が要る。\",\"figureId\":\"xf_eigo_s205\"}],\"trapExamples\":[{\"question\":\"Where do you live? に「大阪に住んでいます」と答えなさい。\",\"wrongAnswer\":\"I live Osaka.\",\"trapExplanation\":\"質問文 Where do you live? に前置詞がないので、答えにも要らないと考えてしまう。日本語の「大阪に住む」の「に」が英語のどこに現れるかを意識していない。\",\"correctAnswer\":\"I live in Osaka.\",\"correctExplanation\":\"「〜に住む」は live in 〜 の形で、場所の前に in が必要である。たずねる文の Where がすでに「どこに」の意味をふくんでいるので疑問文には前置詞が出てこないが、答えでは具体的な地名を言うので in が復活する。市や国には in、番地まで言うときは at を使う。\"},{\"question\":\"「私のくつはどこですか」を英語にしなさい。\",\"wrongAnswer\":\"Where is my shoes?\",\"trapExplanation\":\"Where is 〜? という形をひとかたまりで覚えているため、主語が複数でも is のままにしてしまう。shoes が複数形であることを見落としている。\",\"correctAnswer\":\"Where are my shoes?\",\"correctExplanation\":\"be動詞は主語に合わせる。shoes は複数形なので are になり、答えも They are under the bed. と they で受ける。くつ・めがね（glasses）・ズボン（pants）などは二つで一組なのでいつも複数形になる、という点も合わせて覚える。\"}]}",
"{\"id\":\"eigo_s206\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"when・where と前置詞（at / on / in）の整理\",\"description\":\"時と場所の前置詞を「はばの大きさ」でまとめて覚える\",\"intro\":\"「7時に」は at seven、「日曜日に」は on Sunday、「4月に」は in April。日本語ではどれも「に」の一語ですみます。だから日本語から考えると必ずまようのです。英語は時間や場所の「はば」の大きさで前置詞を選んでいます。その物差しを手に入れましょう。\",\"order\":706,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"時：at＝時刻（点）、on＝曜日・日付（一日）、in＝月・季節・年（広い）。\",\"場所：at＝地点、on＝面にくっつく、in＝囲まれた内部・広い地域。\",\"this / next / last / every が付いた語句には前置詞を付けない。\",\"here / there / home には to を付けない（go home）。「家で」は at home と前置詞が要る。\",\"in the morning だが on Sunday morning。特定の日が付くと on になる。\"],\"sections\":[{\"heading\":\"「はばの大きさ」でそろえる\",\"body\":\"at / on / in は、時でも場所でも「はばの大きさ」という同じ考え方で並んでいる。ばらばらに暗記するより、一本の線でつないだほうが忘れにくい。\\n\\n■ 時のはば\\nat（点）：at six／at noon／at midnight／at that time\\non（一日分）：on Monday／on May 5／on my birthday\\nin（広い）：in April／in spring／in 2026／in the morning\\n\\n■ 場所のはば\\nat（一点）：at the door／at the station／at school\\non（面）：on the desk／on the wall／on the second floor\\nin（内部・広い地域）：in the box／in the room／in Tokyo／in Japan\\n\\n同じ場所でも、見方によって前置詞が変わる。\\n・at the station（待ち合わせ地点としての駅）\\n・in the station（建物の内部としての駅）\\n・I live in Tokyo.（住む場所としての広い東京）\\n・Change trains at Tokyo.（乗りかえ地点としての東京）\\n\\n★ ポイント：「点なら at、面なら on、中なら in」と唱えて、時にも場所にもあてはめる。日本語の助詞（に・で）からは決められないので、必ずこの三段階で考える。\",\"figureId\":\"lf_eigoext06_206\"},{\"heading\":\"前置詞を付けない語句\",\"body\":\"英語には「前置詞を付けてはいけない語句」がある。ここを知らないと、ていねいに書いたつもりで減点される。\\n\\n■ this / next / last / every が付いた時の語句\\n○ this morning　× in this morning\\n○ next Sunday　× on next Sunday\\n○ last year　× in last year\\n○ every day　× on every day\\nこれらの語自体が「いつのことか」を示しているので、前置詞は不要である。\\n\\n■ today / tomorrow / yesterday / tonight\\n○ I will go there tomorrow.　× on tomorrow\\n\\n■ here / there / home\\n○ Come here.　× Come to here.\\n○ I went home at five.　× I went to home.\\n※ 「家で」は at home。go home（家へ帰る）と at home（家で）を混同しないこと。\\n\\n■ 例外的に on になる形\\nin the morning（一般的な午前中）\\n→ on Sunday morning（日曜の朝）／on the morning of May 5\\n特定の日を表す語がくっつくと、in ではなく on になる。\\n\\n⚠ 注意：I go to school. の to は必要（school は場所を表す名詞）。しかし I go home. には to を付けない（home は「家へ」という副詞のはたらきをする）。この二つはセットで問われることが多い。\",\"mangaId\":\"eigo_s206_xm\"}],\"trapExamples\":[{\"question\":\"「私は次の日曜日に彼を訪ねます」を英語にしなさい。\",\"wrongAnswer\":\"I will visit him on next Sunday.\",\"trapExplanation\":\"「曜日には on を付ける」という規則だけを覚えているため、next が付いていても機械的に on を足してしまう。ふだん on Sunday と書き慣れているほどまちがえやすい。\",\"correctAnswer\":\"I will visit him next Sunday.\",\"correctExplanation\":\"this / next / last / every が付いた時の語句には前置詞を付けない。next Sunday がそれだけで「次の日曜日に」という意味を持っているからである。on Sunday（日曜日に）は next が付いていないので on が必要、という対比で覚える。\"},{\"question\":\"「私は五時に家に帰りました」を英語にしなさい。\",\"wrongAnswer\":\"I went to home at five.\",\"trapExplanation\":\"go to school / go to the park のように「go to ＋場所」の形を覚えているため、home にも to を付けてしまう。home が名詞ではなく副詞として使われていることに気づけない。\",\"correctAnswer\":\"I went home at five.\",\"correctExplanation\":\"この home は「家へ」という意味をそれ自体で持つ語なので、to を付けない。here / there も同じで、come here / go there となる。一方、「家で」と場所を表すときは at home と前置詞が要る（I studied at home.）。\"}]}",
"{\"id\":\"eigo_s207\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"why：「なぜ」とその答え方（Because / To 〜）\",\"description\":\"Why の疑問文と、Because 〜／To 〜 の二通りの答え方を身につける\",\"intro\":\"Why were you late? と聞かれたら、Because I missed the bus. と答えます。日本語では「バスに乗りおくれたから」と、理由が先で「から」が後ろに来ます。英語は Because が先頭です。順番がひっくり返るのです。To 〜 で答える形もあわせて確かめます。\",\"order\":707,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Why は「なぜ」と理由をたずねる疑問詞。うしろは疑問文の語順。\",\"答え方は Because ＋ 主語＋動詞（理由）と、To ＋ 動詞の原形（目的）の二通り。\",\"because のうしろは文（主語＋動詞）、because of のうしろは名詞。\",\"so（だから）は結果を導く語で、because（なぜなら）と向きが逆。\",\"答えの時制はたずねられた文に合わせる（Why were you late? — Because the bus was late.）。\"],\"sections\":[{\"heading\":\"Why の疑問文と Because の答え\",\"body\":\"Why は理由をたずねる疑問詞である。作り方はほかの疑問詞と同じで、Why を先頭に置き、うしろは疑問文の語順にする。\\n\\n■ 疑問文の形\\nWhy do you study English? — Because I want to go abroad.\\nWhy is he so happy? — Because he passed the exam.\\nWhy were you absent yesterday? — Because I had a cold.\\nWhy did you come here? — Because I wanted to see you.\\n\\n■ Because のうしろは「主語＋動詞」\\nbecause は文と文をつなぐ語なので、うしろには必ず主語と動詞のそろった文が来る。\\n○ Because I was busy.\\n× Because busy.\\n× Because of I was busy.\\n\\n■ because of のうしろは名詞\\n理由を名詞で言うときは because of を使う。\\n○ Because of the rain.（雨のせいで）\\n○ We stayed home because of the heavy rain.\\n× Because of the rain was heavy.\\n\\n■ 時制をそろえる\\nたずねられた文が過去なら、答えも過去形にする。\\nWhy were you late? — Because the train was late.（was）\\nWhy did you buy it? — Because it was cheap.（was）\\n\\n⚠ 注意：会話では Because 〜 だけで答えてよいが、一つの文の中に because を使うときは「主節＋because＋理由」の形にする（I was late because I missed the bus.）。\",\"mangaId\":\"eigo_s207_xm\"},{\"heading\":\"To 〜 で目的を答える\",\"body\":\"Why 〜? には「何のために」という目的を答えることもできる。そのときは to ＋動詞の原形（不定詞）を使う。\\n\\n■ 目的を答える形\\nWhy did you go to the library? — To borrow some books.（本を借りるために）\\nWhy do you get up early? — To catch the first train.\\nWhy are you studying so hard? — To pass the entrance exam.\\n\\n■ Because との使い分け\\n・Because 〜：そうなった原因・わけ\\n・To 〜：これからしようとしている目的\\nどちらでも答えられる場面も多い。\\nWhy did you go to the park? — Because I wanted to play soccer.／To play soccer.\\n意味はほぼ同じで、To 〜 のほうが短く言える。\\n\\n■ In order to / So that（発展）\\n上位校では In order to 〜（〜するために）や so that 〜 can 〜 の形も出るが、中学受験では To 〜 で十分である。\\n\\n■ 文の中で目的を言う\\nI went to the store to buy some eggs.（卵を買うために店へ行った）\\nこのように、一つの文の中に to ＋原形 を入れると「〜するために」という目的が表せる。\\n\\n★ ポイント：Why 〜? に対する答えの型は二つだけ。「Because ＋ 文」か「To ＋ 動詞の原形」。まずどちらの型で答えるかを決めてから英語を組み立てると、形がくずれない。\",\"figureId\":\"xf_eigo_s207\"}],\"trapExamples\":[{\"question\":\"Why do you study English? に「アメリカに行きたいからです」と答えなさい。\",\"wrongAnswer\":\"Because I want go to America.\",\"trapExplanation\":\"want のうしろに動詞をそのまま続けてしまう。日本語の「行きたい」がひとかたまりに感じられるため、to が抜けていることに気づきにくい。\",\"correctAnswer\":\"Because I want to go to America.\",\"correctExplanation\":\"「〜したい」は want to ＋動詞の原形。to を落とすと動詞が二つ並んだ形になり文が成り立たない。同じ形の would like to、try to、need to、hope to も to を落とさないよう注意する。\"},{\"question\":\"Why were you late? に「バスが遅れたからです」と答えなさい。\",\"wrongAnswer\":\"Because of the bus was late.\",\"trapExplanation\":\"because と because of を同じものだと思っている。of を付けても意味が変わらない気がして、なんとなく付けてしまう。\",\"correctAnswer\":\"Because the bus was late.\",\"correctExplanation\":\"because のうしろには「主語＋動詞」のそろった文が来るので、the bus was late をそのまま続ければよい。because of のうしろに置けるのは名詞だけで、この形を使うなら Because of the bus.（バスのせいで）のように名詞で止める。うしろに動詞があるかどうかで of の要不要が決まる。\"}]}",
"{\"id\":\"eigo_s208\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"Why don’t you 〜? — さそう・すすめる言い方\",\"description\":\"形は疑問文でも意味は提案になる表現と、その答え方を覚える\",\"intro\":\"Why don't you come with us? を「なぜいっしょに来ないの?」と受け取ると、責められているようで気まずくなります。実際は「いっしょに来ない?」というさそいの言葉です。形は疑問文でも中身は提案。答えるときも Sure. や That sounds good. と返します。\",\"order\":708,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"Why don’t you 〜? は「〜したらどうですか」と相手にすすめる言い方。\",\"Why don’t we 〜? / Shall we 〜? / Let’s 〜 は「いっしょに〜しませんか」。\",\"どの形でも、うしろの動詞は必ず原形。\",\"答えは Yes, let’s. / That’s a good idea. / Sounds good. / Sorry, I can’t. など。\",\"形は否定疑問文でも「なぜ〜しないの」と責める意味ではない。\"],\"sections\":[{\"heading\":\"形と意味のずれ\",\"body\":\"Why don't you 〜? は形の上では「なぜあなたは〜しないのですか」という否定の疑問文だが、実際には「〜したらどうですか」と相手にすすめる決まり文句である。会話文の問題で必ず問われる。\\n\\n■ すすめる（相手に）\\nWhy don't you come with us?（いっしょに来ませんか）\\nWhy don't you ask your teacher?（先生に聞いてみたら？）\\nWhy don't you take a rest?（少し休んだらどう？）\\n\\n■ さそう（自分もいっしょに）\\nWhy don't we go shopping?（買い物に行きませんか）\\n＝ Shall we go shopping? ＝ Let's go shopping.\\nwe を使うと「私たちで〜しよう」というさそいになる。\\n\\n■ うしろは必ず動詞の原形\\ndon't のあとなので原形が来る。\\n○ Why don't you go?　× Why don't you to go?　× Why don't you going?\\n\\n■ ほかの言いかえ\\nHow about going shopping?（〜するのはどうですか）※ How about のうしろは -ing 形\\nWhat about having lunch here?\\nShall I open the window?（私が〜しましょうか）\\nShall we 〜?（いっしょに〜しましょうか）\\n\\n⚠ 注意：How about のうしろは動詞の -ing 形、Why don't you のうしろは原形。同じ「〜しませんか」でも形がちがうので、書きかえ問題では要注意である。\",\"figureId\":\"xf_eigo_s208\",\"mangaId\":\"eigo_s208_xm\"},{\"heading\":\"答え方の決まり文句\",\"body\":\"さそいやすすめに対する答えは、Yes / No よりも決まった言い方を使うことのほうが多い。会話文の穴うめではここが問われる。\\n\\n■ 引き受けるとき\\nYes, let's.（そうしましょう）※ Let's 〜 や Shall we 〜? への答え\\nThat's a good idea.（いい考えですね）\\nSounds good. / That sounds nice.（よさそうですね）\\nSure. / OK. / All right. / Of course.\\nYes, please.（Shall I 〜? への答え）\\n\\n■ 断るとき\\nI'm sorry, I can't.（すみませんができません）\\nSorry, but I'm busy today.\\nNo, thank you.（Shall I 〜? を断るとき）\\nMaybe next time.（また今度）\\n\\n断るときは、いきなり No. とだけ言わず I'm sorry を付けるのがふつうである。\\n\\n■ 組み合わせの整理\\nShall we 〜? — Yes, let's. / No, let's not.\\nShall I 〜? — Yes, please. / No, thank you.\\nWhy don't you 〜? — That's a good idea. / Sounds good.\\nLet's 〜. — Yes, let's. / OK.\\n\\n★ ポイント：Shall I 〜?（私がしましょうか）への答えが Yes, please. / No, thank you. である点がとくに問われる。Shall we 〜? との答え方のちがいをセットで覚えること。\"}],\"trapExamples\":[{\"question\":\"Why don’t you come to my house? の意味として正しいものを答えなさい。\",\"wrongAnswer\":\"なぜあなたは私の家に来ないのですか。\",\"trapExplanation\":\"Why（なぜ）と don’t（〜しない）をそれぞれ訳してつなげてしまう。形の上では否定疑問文なので、直訳するとこの意味になってしまうのが原因。\",\"correctAnswer\":\"私の家に来ませんか（来たらどうですか）。\",\"correctExplanation\":\"Why don’t you 〜? は、理由をたずねているのではなく相手をさそう・すすめる決まり文句である。答えも理由（Because 〜）ではなく That’s a good idea. や Sorry, I can’t. のようになる。同じく Why don’t we 〜? は「いっしょに〜しませんか」。\"},{\"question\":\"「いっしょに買い物に行きませんか」を Why で始めて英語にしなさい。\",\"wrongAnswer\":\"Why don't we to go shopping?\",\"trapExplanation\":\"「〜しに行く」という日本語や、want to go の形につられて to を入れてしまう。don’t のうしろが原形であるという決まりが働いていない。\",\"correctAnswer\":\"Why don't we go shopping?\",\"correctExplanation\":\"don’t / doesn’t / didn’t のうしろは必ず動詞の原形なので、to は不要である。同じ意味の Shall we go shopping? や Let’s go shopping. も、すべて原形が続く。to が要るのは want to go のように、to 不定詞を使う語のうしろだけである。\"}]}",
"{\"id\":\"eigo_s209\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"How come 〜? — 語順の変わらない「なぜ」\",\"description\":\"How come のうしろが平叙文の語順になることを、Why と比べて理解する\",\"intro\":\"Why did he go home? と同じ意味で、How come he went home? とも言えます。ところが語順に注目してください。How come のあとは he went と、ふつうの文のならびのままです。Why なら did が入るのに。同じ「なぜ」でも形がちがう、この一点が問われます。\",\"order\":709,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How come 〜? は Why 〜? とほぼ同じ意味の、くだけた言い方。\",\"How come のうしろは「主語＋動詞」の平叙文の語順になる。do / does / did を入れない。\",\"Why のうしろは疑問文の語順（Why do you 〜?）。ここが最大のちがい。\",\"答え方は Why と同じで Because 〜 が基本。\",\"おどろきや意外な気持ちをふくむことが多い言い方である。\"],\"sections\":[{\"heading\":\"Why との語順のちがい\",\"body\":\"How come 〜? は「どうして〜なの」という意味で、Why 〜? とほぼ同じである。ただし語順が大きくちがうので、そこだけは正確に覚える必要がある。\\n\\n■ Why は疑問文の語順\\nWhy do you know that?（どうしてそれを知っているの）\\nWhy is he angry?\\nWhy did you come home early?\\n\\n■ How come は平叙文の語順\\nHow come you know that?\\nHow come he is angry?\\nHow come you came home early?\\n\\nうしろが「主語＋動詞」のまま、つまり ふつうの文の語順のままである点に注目する。do / does / did は入れないし、be動詞も前に出さない。\\n\\n■ もとの形から考える\\nHow come は「How does it come about that 〜?（どうしてそういうことになるのか）」が短くなった言い方だと説明される。そのため「that 〜」の部分がふつうの文のまま残っている、と考えると語順が納得できる。\\n\\n⚠ 注意：How come do you know that? は誤り。How come を Why の言いかえだと思って、そのままうしろに疑問文をつなげてしまうのがよくある失敗である。\\n\\n★ ポイント：「Why は語順が変わる、How come は語順が変わらない」と一組で覚える。この対比そのものが出題される。\",\"figureId\":\"xf_eigo_s209\",\"mangaId\":\"eigo_s209_xm\"},{\"heading\":\"使い方と答え方\",\"body\":\"■ 気持ちのちがい\\nHow come 〜? は、Why 〜? よりくだけた話し言葉で、「えっ、どうして？」というおどろきや意外な気持ちをふくむことが多い。\\n例）How come you are here?（どうしてここにいるの？＝いるはずがないのに）\\n作文やあらたまった場面では Why を使うほうが安全である。\\n\\n■ 答え方\\nWhy と同じで Because 〜 で答える。\\nHow come you were late? — Because I missed the bus.\\nHow come she is so happy? — Because she won the game.\\n\\nYes / No では答えられない点も Why と同じである。\\n\\n■ そのほかの「なぜ」の言い方\\nWhat 〜 for?（何のために）\\n例）What did you buy it for?（何のためにそれを買ったの）＝ Why did you buy it?\\nこの形は Why と同じく疑問文の語順で、for が文の最後に残る。\\n\\n■ まとめ\\n・Why ＋ 疑問文の語順（Why do you 〜?）\\n・How come ＋ 平叙文の語順（How come you 〜?）\\n・What 〜 for? ＋ 疑問文の語順、for は最後\\nどれも答えは Because 〜。形だけが異なる。\"}],\"trapExamples\":[{\"question\":\"「どうしてそれを知っているのですか」を How come で始めて英語にしなさい。\",\"wrongAnswer\":\"How come do you know that?\",\"trapExplanation\":\"How come を Why の言いかえだと覚えているため、Why do you know that? の Why をそのまま How come に置きかえてしまう。語順まで変わることを知らない。\",\"correctAnswer\":\"How come you know that?\",\"correctExplanation\":\"How come のうしろは「主語＋動詞」の平叙文の語順になり、do / does / did は入れない。Why do you know that? と How come you know that? を並べて書き、do の有無を見比べて覚えるとよい。\"},{\"question\":\"How come you were absent yesterday? に答えなさい。\",\"wrongAnswer\":\"Yes, I was.\",\"trapExplanation\":\"How come のうしろが平叙文の語順で、Yes/No疑問文のように見えないため、かえって were you 〜? の形に読みかえて Yes で答えてしまう。\",\"correctAnswer\":\"Because I had a cold.\",\"correctExplanation\":\"How come 〜? は Why 〜? と同じく理由をたずねる言い方なので、Yes / No では答えられない。答えは Because ＋ 主語＋動詞 の形にする。過去のことをたずねられているので、答えの動詞も過去形（had）にそろえる。\"}]}",
"{\"id\":\"eigo_s210\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how①：手段・様子をたずねる基本の How\",\"description\":\"How の二つの意味（どのように／どんな具合か）を場面で使い分ける\",\"intro\":\"How do you go to school? は「どうやって学校へ行きますか」、How are you? は「調子はどうですか」。同じ How でも、手段をたずねる場合と様子をたずねる場合があります。日本語の「どう」も同じように広い語ですが、答え方はまったくちがいます。\",\"order\":710,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"How には「どのようにして（手段・方法）」と「どんな具合か（様子）」の二つの意味がある。\",\"手段は by ＋ 乗り物（by bus / by train）で答える。a や the は付けない。\",\"「歩いて」は on foot、または I walk to 〜. と動詞で表す。\",\"How are you? は体調、How is the weather? は天気をたずねる。\",\"How about 〜? は「〜はどうですか」。うしろは名詞か動詞の -ing 形。\"],\"sections\":[{\"heading\":\"手段・方法をたずねる How\",\"body\":\"How のいちばん基本の意味は「どのようにして」である。移動の手段や、やり方をたずねるときに使う。\\n\\n■ 手段をたずねる\\nHow do you go to school? — I go to school by bus.\\nHow does your father go to work? — He goes by train.\\nHow did you come here? — I came here by bike.\\n\\n■ by ＋ 乗り物 には a / the を付けない\\n○ by bus／by train／by car／by bike／by plane／by ship／by taxi\\n× by a bus／× by the train\\nby 〜 は「〜という手段で」という意味のかたまりなので、乗り物を数えているのではない。\\n\\n■ 「歩いて」の言い方\\non foot（徒歩で）※ feet ではなく foot\\n例）I go to school on foot.\\n同じ内容は I walk to school. とも言える。× by walk は誤り。\\n\\n■ やり方をたずねる\\nHow do you make it?（どうやって作るのですか）\\nHow do you say this in English?（これは英語で何と言いますか）\\nHow do you spell your name?（名前はどうつづりますか）\\nこれらは会話文でよく出る決まった言い方である。\\n\\n⚠ 注意：How can I get to the station?（駅へはどう行けばよいですか）は道をたずねる決まり文句。答えは Go straight and turn right at the second corner. のようになる。\",\"figureId\":\"xf_eigo_s210\",\"mangaId\":\"eigo_s210_xm\"},{\"heading\":\"様子・状態をたずねる How\",\"body\":\"How にはもう一つ「どんな具合か」と様子や状態をたずねる使い方がある。\\n\\n■ 人の調子\\nHow are you? — I'm fine, thank you. / Pretty good. / Not so good.\\nHow is your mother? — She is fine.\\nHow are you doing? / How's it going?（調子はどう？）\\n\\n■ ものごとの様子\\nHow is the weather in Tokyo? — It's sunny.（天気）\\nHow was your trip? — It was a lot of fun.（旅行の感想）\\nHow was the test? — It was very difficult.\\n過去のことをたずねるときは How was 〜? になる。\\n\\n■ How about 〜?（〜はどうですか）\\n提案したり、相手にたずね返したりするときに使う。\\nHow about you?（あなたはどうですか）\\nHow about a cup of tea?（お茶はいかがですか）※ うしろは名詞\\nHow about going to the movies?（映画に行きませんか）※ うしろは動詞の -ing 形\\nWhat about 〜? も同じ意味で使える。\\n\\n⚠ 注意：How about のうしろに動詞の原形を置くことはできない。× How about go to the park? ／○ How about going to the park?\\n\\n★ ポイント：How was 〜? に対しては、感想を表す形容詞（great, fun, boring, difficult, delicious）で答える。「よかった／悪かった」を言える形容詞をいくつか用意しておくと会話文で強い。\"}],\"trapExamples\":[{\"question\":\"How do you go to school? に「バスで行きます」と答えなさい。\",\"wrongAnswer\":\"I go to school by a bus.\",\"trapExplanation\":\"数えられる名詞には a を付ける、という規則を機械的にあてはめてしまう。by bus が「バスという手段で」というひとかたまりの言い方であることを知らない。\",\"correctAnswer\":\"I go to school by bus.\",\"correctExplanation\":\"「by ＋ 乗り物」で手段を表すときは、a / an / the を付けず、複数形にもしない。by bus / by train / by car / by bike のようにそのまま並べる。ただし I go to school in my father’s car. のように具体的な車を指すときは by ではなく in を使う。\"},{\"question\":\"「私は歩いて学校へ行きます」を英語にしなさい。\",\"wrongAnswer\":\"I go to school by walk.\",\"trapExplanation\":\"by bus / by train の形をそのまま応用して、「歩き」も by で表せると考えてしまう。walk が乗り物ではないことに気づけていない。\",\"correctAnswer\":\"I go to school on foot.\",\"correctExplanation\":\"「徒歩で」は on foot という決まった言い方で、by は使わない。foot は単数形のままで、on feet とはしない。同じ内容を I walk to school. と動詞で表すこともでき、こちらのほうが自然でよく使われる。\"}]}",
"{\"id\":\"eigo_s211\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how②：How many と How much\",\"description\":\"数えられる名詞と数えられない名詞で、たずね方を使い分ける\",\"intro\":\"「本を何冊持っていますか」は How many books 〜?、「水はどれくらい要りますか」は How much water 〜? です。本は数えられ、水は数えられないからです。日本語では「何冊」「どれくらい」と自然に使い分けていますが、英語ではこの区別が形にはっきり出ます。\",\"order\":711,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"How many ＋ 数えられる名詞の複数形（How many books do you have?）。\",\"How much ＋ 数えられない名詞（How much water 〜?）。\",\"How much is / are 〜? は値段をたずねる言い方。\",\"water / milk / money / time / bread / paper などは数えられない名詞。\",\"数えられない名詞は a glass of / a cup of / a piece of で数える。\"],\"sections\":[{\"heading\":\"数えられる名詞と数えられない名詞\",\"body\":\"英語の名詞は「一つ二つと数えられるもの」と「数えられないもの」に分かれる。どちらかによって、数量をたずねる語が変わる。\\n\\n■ 数えられる名詞（How many）\\nbook / apple / student / dog / pen / egg など、形がはっきりしていて一つ二つと数えられるもの。\\n・a book / two books のように a が付き、複数形になる。\\n\\n■ 数えられない名詞（How much）\\nwater / milk / juice / money / time / bread / paper / rice / sugar / snow / music / homework など、形が決まっていないものや、まとまりとして考えるもの。\\n・a を付けず、複数形にもしない。× two waters／× many homeworks\\n\\n■ たずね方\\nHow many books do you have? — I have twenty (books).\\nHow many students are there in your class? — There are thirty-five.\\nHow much water do you drink every day? — About two liters.\\nHow much time do we have? — We have ten minutes.\\n\\n⚠ 注意：How many のうしろの名詞は必ず複数形にする。× How many book do you have? ／○ How many books 〜?\\n\\n★ ポイント：日本語では「水を三つ」と言えてしまうが、英語では three waters とは言わない。数えられるかどうかは日本語の感覚ではなく、英語の単語ごとに覚える。\",\"figureId\":\"lf_eigoext06_211\",\"mangaId\":\"eigo_s211_xm\"},{\"heading\":\"値段のたずね方と、数えられない名詞の数え方\",\"body\":\"■ 値段をたずねる How much\\nHow much is this book? — It's 800 yen.\\nHow much are these apples? — They are 300 yen.\\n主語が単数なら is、複数なら are。値段は「量」なので、数えられるりんごでも値段をたずねるときは How much になる。\\n\\nHow much does it cost? / How much is the fare?（運賃は）といった言い方もある。\\n\\n■ 数えられない名詞を数える言い方\\n入れ物や形を表す語をそえて数える。\\na glass of water（コップ一杯の水）／two glasses of water\\na cup of coffee（カップ一杯のコーヒー）／three cups of tea\\na piece of paper（紙一枚）／two pieces of cake\\na slice of bread（パン一切れ）\\na bottle of milk（びん一本の牛乳）\\n\\n例）How many cups of coffee do you drink a day?（一日に何杯コーヒーを飲みますか）\\nこのように、入れ物の語（cups）が数えられる名詞なので How many を使える。\\n\\n■ 多い・少ないの言い方\\n数えられる名詞：many（多くの）／a few（少しの）／few（ほとんどない）\\n数えられない名詞：much（多くの）／a little（少しの）／little（ほとんどない）\\nどちらにも使える：a lot of / lots of / some / any\\n\\n⚠ 注意：肯定文で much を単独で使うことは少なく、a lot of を使うのがふつう（I have a lot of homework.）。\"}],\"trapExamples\":[{\"question\":\"「あなたは一日にどれくらいの水を飲みますか」を英語にしなさい。\",\"wrongAnswer\":\"How many water do you drink a day?\",\"trapExplanation\":\"日本語の「どれくらい」を「どれだけの数」と受け取り、How many を選んでしまう。water が数えられない名詞であることを意識していない。\",\"correctAnswer\":\"How much water do you drink a day?\",\"correctExplanation\":\"water は形が決まっていない数えられない名詞なので、量をたずねる How much を使う。water を複数形にすることもできない。数えられる名詞（books, students）なら How many ＋ 複数形、数えられない名詞（water, money, time）なら How much、と対応させる。\"},{\"question\":\"「あなたは本を何冊持っていますか」を英語にしなさい。\",\"wrongAnswer\":\"How many book do you have?\",\"trapExplanation\":\"「何冊」という日本語には複数を表す形がないため、book を単数のままにしてしまう。How many のうしろが必ず複数形になるという決まりを忘れている。\",\"correctAnswer\":\"How many books do you have?\",\"correctExplanation\":\"How many は「いくつあるか」をたずねるので、うしろの名詞は必ず複数形になる。答えが一冊であっても、たずねる時点では複数形で書く。同じく How many students / How many pens / How many times のように、-s を付ける習慣をつける。\"}]}",
"{\"id\":\"eigo_s212\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how③：How long と How far\",\"description\":\"時間・長さと距離をたずね分け、It takes 〜 の答え方を身につける\",\"intro\":\"「駅までどれくらいですか」——この日本語は、時間のことも距離のこともさせます。英語では How long does it take? と How far is it? に分かれます。答えも It takes ten minutes. と It's two kilometers. でちがう。あいまいさが許されない場面です。\",\"order\":712,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How long は「どのくらい長く（期間・長さ）」をたずねる。\",\"How far は「どのくらい遠く（距離）」をたずねる。\",\"時間の答えは It takes ＋ 時間（It takes ten minutes.）。\",\"距離の答えは It’s about ＋ 距離（It’s about two kilometers.）。\",\"How long のうしろに time を付けない（× How long time）。\"],\"sections\":[{\"heading\":\"How long（期間・長さ）\",\"body\":\"How long は「どのくらい長いか」をたずねる。時間の長さにも、ものの長さにも使える。\\n\\n■ かかる時間をたずねる\\nHow long does it take from here to the station? — It takes about ten minutes.\\nHow long does it take to get to your school? — It takes twenty minutes by bike.\\nこの it は「時間の it」で、「それ」という意味はない。答えの文も It takes 〜 で始める。\\n\\n■ 期間をたずねる\\nHow long did you stay in Kyoto? — I stayed there for three days.\\nHow long have you lived here?（現在完了。上位校向け）\\n期間を答えるときは for 〜（〜のあいだ）を使う。\\n\\n■ ものの長さをたずねる\\nHow long is this bridge? — It's about 500 meters long.\\nHow long is this movie? — It's two hours long.\\n\\n■ 答え方の型\\n・時間がかかる：It takes ＋ 時間.\\n・期間：for ＋ 期間.\\n・長さ：It's ＋ 数字 ＋ 単位 (long).\\n\\n⚠ 注意：How long time does it take? は誤り。long にすでに「長さ」の意味があるので time は不要である。\\n\\n★ ポイント：How long does it take 〜? は入試の会話文で最頻出。「It takes ＋ 時間」という答えの型を丸ごと覚えておく。\",\"figureId\":\"lf_eigoext06_212\",\"mangaId\":\"eigo_s212_xm\"},{\"heading\":\"How far（距離）\",\"body\":\"How far は「どのくらい遠いか」と距離をたずねる。時間ではなく、キロメートルやメートルで答える。\\n\\n■ 基本の形\\nHow far is it from here to the park? — It's about two kilometers.\\nHow far is your school from your house? — It's about one kilometer.\\nこの it も「距離の it」で、意味はない。\\n\\n■ How long との区別\\n同じ「駅までどのくらい？」でも、\\n・時間を知りたい → How long does it take to the station? — It takes ten minutes.\\n・距離を知りたい → How far is it to the station? — It's about one kilometer.\\nたずね方と答え方がずれると不正解になる。\\n\\n■ そのほかの言い方\\nHow high is that tower?（高さ）— It's 634 meters high.\\nHow deep is this lake?（深さ）— It's about 40 meters deep.\\nHow wide is this river?（幅）— It's about 100 meters wide.\\nこれらはすべて「How ＋ 形容詞」で、答えは「数字 ＋ 単位 ＋ 形容詞」の形になる。\\n\\n⚠ 注意：答えの文で単位のあとに long / high / deep をそえるのが正式な形（It's 500 meters long.）。単位だけで答えても通じるが、書くときはそえたほうが確実である。\"}],\"trapExamples\":[{\"question\":\"How long does it take from your house to school? に答えなさい。\",\"wrongAnswer\":\"It takes about two kilometers.\",\"trapExplanation\":\"「家から学校まで」という言い方から距離を答えたくなり、単位をキロメートルにしてしまう。How long と How far の役割のちがいを意識していない。\",\"correctAnswer\":\"It takes about fifteen minutes.\",\"correctExplanation\":\"How long does it take 〜? は「どのくらい時間がかかるか」をたずねる形なので、答えは時間の単位（minutes / hours）になる。距離をたずねるなら How far is it from your house to school? と聞き、It’s about two kilometers. と答える。\"},{\"question\":\"How long did you stay in Kyoto? に「三日間です」と答えなさい。\",\"wrongAnswer\":\"I stayed for three days ago.\",\"trapExplanation\":\"過去のことなので ago を付けたくなる。for（〜のあいだ）と ago（〜前に）はどちらも時間に関する語なので、区別せずに両方書いてしまう。\",\"correctAnswer\":\"I stayed there for three days.\",\"correctExplanation\":\"for は「どれだけの期間続いたか」、ago は「今からどれだけ前か」を表す語で、いっしょには使えない。How long（期間）に答えるので for three days が正しい。three days ago を使うのは When did you go there? に「三日前です」と答えるときである。\"}]}",
"{\"id\":\"eigo_s213\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how④：How often と頻度の言い方\",\"description\":\"回数の表し方（once / twice / 〜 times）と頻度の副詞の位置を覚える\",\"intro\":\"「どれくらいテニスをしますか」とたずねたいとき、How often do you play tennis? と言います。答えは Twice a week.（週に2回）のように回数で返します。この a week の a は「〜につき」の意味。小さいけれど落としやすい語です。\",\"order\":713,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How often 〜? は「どのくらいの頻度で」をたずねる。\",\"一回は once、二回は twice、三回以上は three times のように times を使う。\",\"「週に一回」は once a week。この a は「〜につき」の意味。\",\"頻度の副詞（always / usually / often / sometimes / never）は一般動詞の前、be動詞のうしろ。\",\"never はそれだけで否定の意味なので、not といっしょに使わない。\"],\"sections\":[{\"heading\":\"回数の表し方\",\"body\":\"How often 〜? は「どのくらいの頻度で〜しますか」とたずねる言い方である。答えでは回数と期間を組み合わせる。\\n\\n■ たずね方\\nHow often do you play tennis? — Twice a week.\\nHow often does your father go abroad? — About three times a year.\\nHow often do you go to the library? — Once a month.\\n\\n■ 回数の言い方\\n一回：once　二回：twice　三回：three times　四回：four times\\n※ once と twice だけは特別な形で、one time / two times とは言わないのがふつう。\\n\\n■ 「〜につき」の a\\nonce a week（週に一回）／twice a month（月に二回）／three times a year（年に三回）／five times a day（一日に五回）\\nこの a は「一つの」ではなく「〜につき」という意味で、per の代わりに使われている。\\n\\n■ そのほかの答え方\\nevery day（毎日）／every Sunday（毎週日曜）／once in a while（ときどき）／almost every day（ほぼ毎日）／not very often（あまり〜しない）\\n\\n⚠ 注意：答えるときに前置詞をそえない。× on twice a week ／○ twice a week\\n\\n★ ポイント：How often と How long は混同しやすい。often＝どのくらいの回数、long＝どのくらいの長さ、と対応させる。\",\"figureId\":\"lf_eigoext06_213\",\"mangaId\":\"eigo_s213_xm\"},{\"heading\":\"頻度の副詞と、その位置\",\"body\":\"回数のかわりに、頻度を表す副詞で答えることもできる。これらの副詞は文の中で置く場所が決まっている。\\n\\n■ 度合いの順\\nalways（いつも・100％）＞ usually（たいてい・80％）＞ often（よく・60％）＞ sometimes（ときどき・40％）＞ seldom / rarely（めったに〜ない・10％）＞ never（一度も〜ない・0％）\\n\\n■ 置く場所\\n①一般動詞の前\\nI always get up at six.\\nHe usually walks to school.\\nShe never eats natto.\\n\\n②be動詞のうしろ\\nHe is always kind to us.\\nI am sometimes late for school.\\n\\n③助動詞のうしろ\\nI will always remember you.\\nYou can usually see Mt. Fuji from here.\\n\\n■ sometimes の例外\\nsometimes は文の先頭や最後にも置ける。\\nSometimes I go to the park. / I go to the park sometimes.\\n\\n⚠ 注意：never はそれだけで「一度も〜ない」という否定の意味を持つので、don't といっしょには使わない。× I don't never eat natto. ／○ I never eat natto.\\n\\n★ ポイント：「一般動詞の前・be動詞のうしろ」は、not の位置とちょうど同じである（I don't 〜 / I am not 〜）。not の位置を思い出せば、頻度の副詞の位置も思い出せる。\"}],\"trapExamples\":[{\"question\":\"How often do you go to the swimming school? に「週に二回です」と答えなさい。\",\"wrongAnswer\":\"Two times a week.\",\"trapExplanation\":\"three times / four times の形をそのまま二回にもあてはめてしまう。twice という特別な語があることを知らないか、思い出せない。\",\"correctAnswer\":\"Twice a week.\",\"correctExplanation\":\"一回は once、二回は twice という特別な形を使い、三回以上から three times のように times を使う。「週に」は a week。once a week / twice a week / three times a week と続けて口に出して覚えると定着する。\"},{\"question\":\"「私はたいてい十時に寝ます」を英語にしなさい。\",\"wrongAnswer\":\"I am usually go to bed at ten.\",\"trapExplanation\":\"「頻度の副詞は be動詞のうしろ」という規則だけを覚えていて、文に be動詞がないのに am を足してしまう。動詞が二つ並んでいることに気づけない。\",\"correctAnswer\":\"I usually go to bed at ten.\",\"correctExplanation\":\"この文の動詞は go という一般動詞なので、頻度の副詞は動詞の前に置く。be動詞のうしろに置くのは He is always busy. のように、もともと文に be動詞があるときだけである。副詞を入れるために be動詞を足してはいけない。\"}]}",
"{\"id\":\"eigo_s214\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how⑤：How old / How tall / How high / How heavy\",\"description\":\"年齢・高さ・重さのたずね方と、答えるときの単位のそえ方を学ぶ\",\"intro\":\"How old are you? は「何才ですか」ですが、直訳すれば「どれくらい古いですか」です。ものにも使えて、How old is this temple? なら「この寺は建ってどれくらいですか」になります。How のあとに形容詞を置くと、そのものさしではかった量をたずねる形になるのです。\",\"order\":714,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How old は年齢だけでなく「どのくらい古いか」もたずねる。\",\"How tall は人・木・建物の「背の高さ」、How high は山や地面からの高さ。\",\"答えは「数 ＋ 単位 ＋ 形容詞」（It’s 634 meters tall.）。\",\"年齢の答えは 〜 years old。one year old は単数形。\",\"重さは How heavy 〜? か How much does it weigh?。\"],\"sections\":[{\"heading\":\"How old と How tall / How high\",\"body\":\"How のうしろに形容詞を置くと「どのくらい〜か」という意味になる。どの形容詞を選ぶかで、たずねる中身が決まる。\\n\\n■ How old（年齢・古さ）\\nHow old are you? — I'm twelve years old.\\nHow old is your brother? — He is fifteen.\\nHow old is this temple? — It's about 400 years old.（建ってから約400年）\\n\\n人だけでなく、建物・木・町にも使える。人以外に使うときは「何歳ですか」ではなく「どのくらい古いですか」という意味になる。\\n\\n■ 年齢の答え方\\ntwelve years old（12歳）／one year old（1歳・単数形）\\nyears old を省いて I'm twelve. と言うこともできる。\\n\\n■ How tall（背の高さ）\\nHow tall are you? — I'm 150 centimeters tall.\\nHow tall is that tree? — It's about ten meters tall.\\n人・木・建物のように「細長く立っているもの」の高さに使う。\\n\\n■ How high（地面からの高さ・山）\\nHow high is Mt. Fuji? — It's 3,776 meters high.\\nHow high can you jump?（どのくらい高く跳べますか）\\n山や、飛んでいるものの高さには high を使う。\\n\\n⚠ 注意：Mt. Fuji には tall ではなく high を使う。「山は tall と言わない」と覚えておくとよい（人・木・建物は tall）。\\n\\n★ ポイント：答えの形は「数 ＋ 単位 ＋ 形容詞」。It’s 3,776 meters high. のように、最後に形容詞をそえるところまで書けるようにする。\",\"figureId\":\"xf_eigo_s214\",\"mangaId\":\"eigo_s214_xm\"},{\"heading\":\"重さ・大きさ・値段のたずね方\",\"body\":\"■ 重さ\\nHow heavy is this bag? — It's about three kilograms.\\nHow much does it weigh? — It weighs three kilograms.\\nweigh は「重さが〜ある」という動詞である。\\n\\n■ 大きさ\\nHow big is your school? / How large is this park?\\nbig は身近な言い方、large はやや形式ばった言い方。\\n\\n■ 値段\\nHow much is this? — It's 500 yen.\\n（値段は数ではなく量とみなすので、How many ではなく How much を使う）\\n\\n■ 速さ・年齢以外の「どのくらい」\\nHow fast can you run?（どのくらい速く走れますか）\\nHow far can you swim?（どのくらいの距離を泳げますか）\\nHow well does she play the piano?（どのくらいじょうずに弾きますか）\\nHow ＋ 副詞 の形もあり、こちらは動作のしかたをたずねる。\\n\\n■ 単位の書き方\\n・数字が二以上なら単位は複数形：three kilograms / ten meters\\n・ただし年齢は 〜 years old（1歳だけ one year old）\\n・身長は centimeters、体重は kilograms がふつう\\n\\n⚠ 注意：How many years old are you? とは言わない。年齢は How old are you? の一つの形で決まっている。\"}],\"trapExamples\":[{\"question\":\"How old is this temple? の意味として正しいものを答えなさい。\",\"wrongAnswer\":\"このお寺は何歳ですか。\",\"trapExplanation\":\"How old ＝「何歳」と一対一で覚えているため、人以外に使われたときも「歳」で訳してしまう。日本語として不自然であることに気づけない。\",\"correctAnswer\":\"このお寺はどのくらい古いのですか（建ってからどのくらいたっていますか）。\",\"correctExplanation\":\"How old は「どのくらい年を経ているか」をたずねる言い方で、人に使えば年齢、ものに使えば古さを表す。答えも It’s about 400 years old.（約400年前のものです）となる。木・町・国などにも同じように使える。\"},{\"question\":\"「富士山はどのくらいの高さですか」を英語にしなさい。\",\"wrongAnswer\":\"How tall is Mt. Fuji?\",\"trapExplanation\":\"「高さ」という日本語から、身長をたずねる How tall を選んでしまう。tall と high の使い分けが、対象によって決まることを知らない。\",\"correctAnswer\":\"How high is Mt. Fuji?\",\"correctExplanation\":\"tall は人・木・建物のように細長く立っているものに使い、山には high を使う。答えは It’s 3,776 meters high. となる。なお建物は How tall is that tower? と How high is that tower? のどちらも使えるが、山は high と覚えておけば安全である。\"}]}",
"{\"id\":\"eigo_s215\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"how⑥：How ＋ 形容詞・副詞の総整理\",\"description\":\"How のあとに置く語で何をたずねているかを一覧で整理する\",\"intro\":\"How many、How long、How often、How tall — ここまでにいくつもの How が出てきました。ばらばらに覚えると、いざというとき出てきません。実はすべて「How ＋ ものさしになる語」という同じ形です。一覧にして、全体を見わたしておきましょう。\",\"order\":715,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"How ＋ 形容詞・副詞 で「どのくらい〜か」をたずねる。何をたずねるかはうしろの語で決まる。\",\"many＝数、much＝量・値段、long＝期間・長さ、far＝距離、often＝頻度、old＝年齢。\",\"たずね方と答えの単位をセットで覚える（long→minutes、far→kilometers）。\",\"How のうしろに余計な語を足さない（× How long time、× How many years old）。\",\"疑問詞のうしろは疑問文の語順。How many books do you have? の do を落とさない。\"],\"sections\":[{\"heading\":\"一覧で確かめる\",\"body\":\"How ＋ 形容詞・副詞 の形をまとめて並べると、何がちがうのかがはっきりする。たずね方と答え方をセットで覚えるのがこつである。\\n\\n■ 数と量\\nHow many ＋ 複数形（数）— Ten books.\\nHow much ＋ 数えられない名詞（量）— About two liters.\\nHow much is it?（値段）— It's 500 yen.\\n\\n■ 時間と距離\\nHow long（期間・長さ）— It takes ten minutes. / For three days.\\nHow far（距離）— It's about two kilometers.\\nHow often（頻度）— Twice a week.\\n\\n■ 大きさ・年齢\\nHow old（年齢・古さ）— I'm twelve years old.\\nHow tall（背の高さ）— I'm 150 centimeters tall.\\nHow high（山などの高さ）— It's 3,776 meters high.\\nHow heavy（重さ）— It's three kilograms.\\nHow big / How large（大きさ）\\n\\n■ 動作のしかた\\nHow fast（速さ）— I can run 100 meters in 15 seconds.\\nHow well（じょうずさ）— She plays the piano very well.\\nHow soon（あとどれくらいで）— In ten minutes.\\n\\n★ ポイント：How soon 〜? は「あとどれくらいで」で、答えは in ＋ 時間（in ten minutes＝十分後に）。How long との区別が上位校で問われる。\",\"figureId\":\"lf_eigoext06_215\"},{\"heading\":\"まちがえやすい組み合わせ\",\"body\":\"■ 余計な語を足さない\\n× How long time does it take? → ○ How long does it take?\\n× How many years old are you? → ○ How old are you?\\n× How much price is it? → ○ How much is it?\\nHow ＋ 形容詞 の二語で意味が完成しているので、同じ意味の名詞を重ねる必要はない。\\n\\n■ 語順を守る\\nHow many ＋ 名詞 のうしろは、ふつうの疑問文の語順になる。\\n○ How many books do you have?\\n× How many books you have?\\nただし「How many ＋ 名詞」が主語のときは do が要らない（How many students are there in your class? / How many people came to the party?）。\\n\\n■ たずねる語と答えの単位をそろえる\\nHow long → minutes / hours / days（時間）\\nHow far → meters / kilometers（距離）\\nHow often → once / twice / 〜 times（回数）\\nHow much → yen / dollars（値段）、liters（量）\\nHow old → years old（年齢）\\nたずねられた語と答えの単位がずれていないかを、答えを書いたあとに必ず確かめる。\\n\\n⚠ 注意：How much are you? は「あなたはいくらですか」となり、人を売り物にした意味になってしまう。年齢は How old are you?、身長は How tall are you? である。\",\"mangaId\":\"eigo_s215_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは何歳ですか」を英語にしなさい。\",\"wrongAnswer\":\"How much are you?\",\"trapExplanation\":\"How much を「どのくらい」という万能の言い方だと思ってしまう。much が量や値段を表すことを意識していないため、人に対して使ってしまう。\",\"correctAnswer\":\"How old are you?\",\"correctExplanation\":\"年齢は How old 〜? と決まっている。How much are you? は「あなたはいくらですか」という意味になってしまう。How のうしろの形容詞が何をたずねるかを決めるので、old＝年齢、much＝量・値段、tall＝背の高さ、と一つずつ対応させて覚える。\"},{\"question\":\"「駅までどのくらい時間がかかりますか」を英語にしなさい。\",\"wrongAnswer\":\"How long time does it take to the station?\",\"trapExplanation\":\"「どのくらい時間が」という日本語の「時間」を英語にも残そうとして time を入れてしまう。long にすでに時間の長さの意味があることに気づけない。\",\"correctAnswer\":\"How long does it take to the station?\",\"correctExplanation\":\"How long の二語で「どのくらいの長さ（時間）」という意味が完成しているので、time は不要である。同じく How many years old（年齢）や How much price（値段）も、意味の重なる名詞を足した誤りである。How ＋ 形容詞 は二語で一組と覚える。\"}]}",
"{\"id\":\"eigo_s216\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞が主語①：語順が変わらない疑問文\",\"description\":\"Who broke it? のように do を使わず、平叙文の語順のまま作る形を学ぶ\",\"intro\":\"Who broke this window? には do も does もありません。ふつうの疑問文には必要なのに、なぜないのでしょう。Who がそのまま主語だからです。「だれが」とたずねる文では、語順を入れかえる必要がありません。ここを知らないと、必ず do を入れてしまいます。\",\"order\":716,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"疑問詞そのものが主語のときは、do / does / did を使わない。\",\"語順は平叙文と同じ「疑問詞（主語）＋動詞〜?」。\",\"主語の疑問詞は三人称単数あつかい。現在形なら動詞に s が付く（Who wants 〜?）。\",\"過去なら動詞をそのまま過去形にする（Who broke the window?）。\",\"見分け方：疑問詞のすぐあとに動詞が来ていれば、その疑問詞は主語。\"],\"sections\":[{\"heading\":\"主語をたずねる疑問文\",\"body\":\"これまでの疑問文は「疑問詞＋do/does/did＋主語＋動詞」の形だった。しかし、たずねたいものが主語そのものである場合、入れかえる必要がなくなるため語順が変わらない。\\n\\n■ 平叙文と見比べる\\nKen broke this window.（ケンがこの窓を割った）\\n　→ Ken をたずねたい\\n　→ Ken の場所に Who を置くだけ\\n　→ Who broke this window?（だれがこの窓を割ったのですか）\\n\\ndo / does / did を入れる場所がないことに注目する。主語がすでに文の先頭にあるので、動かす必要がないのである。\\n\\n■ ほかの例\\nWho lives in this house?（だれがこの家に住んでいますか）\\nWho wants to go with me?（だれが私といっしょに行きたいですか）\\nWhat happened yesterday?（きのう何があったのですか）\\nWhich bus goes to the station?（どのバスが駅に行きますか）\\n\\n■ 目的語をたずねる文とのちがい\\n・Who do you like?（あなたはだれが好きですか）→ 好かれる相手をたずねる＝目的語 → do が要る\\n・Who likes you?（だれがあなたを好きですか）→ 好く人をたずねる＝主語 → do が要らない\\n\\n⚠ 注意：Who did break this window? は誤り（強く言いたいときの特別な形をのぞく）。中学受験では Who broke 〜? と書く。\",\"figureId\":\"lf_eigoext06_216\",\"mangaId\":\"eigo_s216_xm\"},{\"heading\":\"主語の疑問詞は三人称単数あつかい\",\"body\":\"Who / What が主語になるとき、それは「一人（一つ）」とみなして扱う。そのため現在の文では動詞に三単現の s が付く。\\n\\n■ 現在形\\nWho wants some tea?（だれかお茶がほしい人は？）※ want ではなく wants\\nWho has a pen?（だれかペンを持っていますか）※ have ではなく has\\nWho knows the answer?\\nWhat makes you so happy?\\n\\n答えが複数人になりそうな場面でも、たずねる時点では s を付ける。\\n\\n■ 過去形\\n過去の文では、動詞をそのまま過去形にする。\\nWho broke this cup?\\nWho came to the party?\\nWho said that?\\nWho took my eraser?\\n\\n■ be動詞の場合\\nWho is absent today?（きょうはだれが休みですか）\\nWhat is in this box?（この箱の中に何が入っていますか）\\nbe動詞は is を使う。\\n\\n■ Which ＋ 名詞 が主語のとき\\nWhich bus goes to the station?（bus は単数なので goes）\\nWhich trains stop at this station?（trains は複数なので stop）\\nうしろの名詞の数に合わせる。\\n\\n★ ポイント：「主語の Who は三単現」と覚える。Who want to go? という誤りが非常に多い。\"}],\"trapExamples\":[{\"question\":\"「だれがこの窓を割ったのですか」を英語にしなさい。\",\"wrongAnswer\":\"Who did break this window?\",\"trapExplanation\":\"「疑問文には do / does / did が必要」という規則を全部の疑問文にあてはめてしまう。Who がこの文の主語であり、入れかえる語がないことに気づいていない。\",\"correctAnswer\":\"Who broke this window?\",\"correctExplanation\":\"疑問詞そのものが主語のときは、Ken broke this window. の Ken を Who に置きかえるだけでよく、語順は変わらない。did を入れる場所がないので使わない。見分け方は「疑問詞のすぐあとに動詞が来ているか」。来ていればその疑問詞は主語である。\"},{\"question\":\"「だれが私といっしょに行きたいですか」を英語にしなさい。\",\"wrongAnswer\":\"Who want to go with me?\",\"trapExplanation\":\"「だれが」と聞くと何人来るかわからないので、複数を思いうかべて動詞に s を付けないでしまう。主語の疑問詞が三人称単数あつかいであることを知らない。\",\"correctAnswer\":\"Who wants to go with me?\",\"correctExplanation\":\"主語になった Who / What は三人称単数として扱うので、現在の文では動詞に s が付く。Who wants 〜? / Who has 〜? / Who knows 〜? の形で覚えておく。過去の文なら Who wanted to go? と過去形にすればよい。\"}]}",
"{\"id\":\"eigo_s217\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞が主語②：What happened? / Which 〜 が主語のとき\",\"description\":\"What や Which ＋ 名詞 が主語になる文を、動詞の形に注意して作る\",\"intro\":\"「何があったの?」は What happened? の二語で言えます。What did happen? としなくてよいのです。What や Which が主語のときは、動詞をそのまま続けます。しかも単数あつかいになるので、現在の文なら s が付く。細かいけれど差がつく点です。\",\"order\":717,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"What happened? は「何が起きたのですか」。did を使わない。\",\"What is in the box? のように、What が主語で be動詞が続く形もある。\",\"What makes you 〜? は「何があなたを〜にするのか」＝「なぜ〜なのか」。\",\"Which ＋ 名詞 が主語のときは、その名詞の数に動詞を合わせる。\",\"How many ＋ 名詞 が主語のときも do を使わない（How many students came?）。\"],\"sections\":[{\"heading\":\"What が主語になる文\",\"mangaId\":\"eigo_s217_manga\",\"body\":\"What も主語になれる。そのときは Who と同じく do / does / did を使わず、語順も変わらない。\\n\\n■ What happened?（何が起きたのですか）\\nSomething happened. の something をたずねる形。\\n例）What happened to you?（どうしたのですか）\\n例）What happened yesterday?\\n× What did happen? とは書かない。\\n\\n■ What is 〜?（何が〜にありますか）\\nWhat is in this box? — There is a cake in it.\\nWhat is on the desk? — There are some books.\\nbe動詞のうしろに場所を表す語句が来る形である。\\n\\n■ What makes 〜?（何が〜させるのか）\\nWhat makes you so happy? — I passed the exam.\\n直訳は「何があなたをそんなに幸せにするのですか」だが、意味は「どうしてそんなにうれしいのですか」に近い。Why are you so happy? と言いかえられる。\\n例）What made you cry?（どうして泣いたのですか）\\n\\n■ そのほか\\nWhat comes after Wednesday? — Thursday does.\\nWhat is the matter (with you)?（どうしたのですか）※ 決まり文句\\n\\n⚠ 注意：What did you happen? という文は成り立たない。happen（起こる）は「〜を起こす」という使い方ができない動詞で、主語には出来事が来る。\",\"figureId\":\"xf_eigo_s217\"},{\"heading\":\"Which ＋ 名詞 / How many ＋ 名詞 が主語のとき\",\"body\":\"疑問詞に名詞がくっついたかたまりが主語になることもある。この場合も do / does / did は使わない。\\n\\n■ Which ＋ 名詞 が主語\\nWhich bus goes to the station? — The No. 5 bus does.\\nWhich train stops at this station?\\nWhich student won the contest?\\nうしろの名詞が単数なら動詞に s、複数なら s なし。\\n例）Which trains stop at this station?（trains は複数 → stop）\\n\\n■ How many ＋ 名詞 が主語\\nHow many students came to school today? — Twenty did.\\nHow many people live in this town?\\nHow many books are on the desk?\\n「何人が来たか」のように「〜が」にあたる部分をたずねているので do は不要である。\\n\\n■ 目的語をたずねる形との比較\\n・How many books do you have?（あなたが持っている本の数＝目的語）→ do が要る\\n・How many books are on the desk?（机の上にある本の数＝主語）→ do が要らない\\nどちらも How many books で始まるので、うしろを見て判断する。\\n\\n★ ポイント：判断のしかたはいつも同じ。「疑問詞（＋名詞）のすぐあとに動詞が来ているか」を見る。来ていれば主語、そうでなければ do / does / did が必要な形である。\"}],\"trapExamples\":[{\"question\":\"「昨夜ここで何が起きたのですか」を英語にしなさい。\",\"wrongAnswer\":\"What did happen here last night?\",\"trapExplanation\":\"疑問文だから did を入れる、という手順が自動的に働いてしまう。What が主語であり、語順を入れかえる必要がないことに気づけない。\",\"correctAnswer\":\"What happened here last night?\",\"correctExplanation\":\"この What は「何が」という主語なので、Something happened here. の something を What に置きかえるだけでよい。did を入れる場所はない。同じ形で What happened to him?（彼に何があったのですか）もよく使われる。\"},{\"question\":\"「どの電車が大阪へ行きますか」を英語にしなさい。\",\"wrongAnswer\":\"Which train go to Osaka?\",\"trapExplanation\":\"do / does を使わない形だと気づいたところで安心してしまい、動詞を原形のままにしてしまう。Which train が三人称単数の主語であることを見落としている。\",\"correctAnswer\":\"Which train goes to Osaka?\",\"correctExplanation\":\"Which train は「一本の電車」で三人称単数なので、現在の文では動詞に s が付いて goes になる。do / does を使わないぶん、動詞そのものに三単現の s を付ける必要がある。複数形なら Which trains go to Osaka? と s なしになる。\"}]}",
"{\"id\":\"eigo_s218\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞が主語③：答え方と、目的語をたずねる文との区別\",\"description\":\"Ken did. のような答え方を身につけ、主語か目的語かを見分ける\",\"intro\":\"Who made this cake? への答えは、I did. や My mother did. です。I made this cake. と全部言わなくてよく、did が made の代わりをしています。また Who do you like? との見分けも大切です。主語をたずねているのか、目的語をたずねているのかを判断します。\",\"order\":718,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"主語をたずねられたら「主語 ＋ do / does / did.」で短く答える（Ken did.）。\",\"be動詞の文なら「主語 ＋ is / was.」で答える（Ken is.）。\",\"動詞をくり返す場合は目的語まで言う（Ken broke it. ／× Ken broke.）。\",\"疑問詞のすぐあとが動詞（be動詞・助動詞もふくむ。Who is absent? / Who can swim?）なら主語。do / does / did が来て、そのうしろに別の主語があれば目的語などをたずねている。\",\"日本語の「だれが／だれを」を取りちがえると英文がまるごと変わる。\"],\"sections\":[{\"heading\":\"短く答える形\",\"body\":\"主語をたずねる疑問文には、「主語＋do / does / did.」という独特の答え方がある。\\n\\n■ 一般動詞の文\\nWho broke this window? — Ken did.（ケンです）\\nWho wants some tea? — I do.\\nWho came to the party? — Tom and Mary did.\\nWho has a pen? — I do.（have なので do で受ける）\\n\\ndid / do / does は、くり返しをさけて動詞の代わりをしている。「ケンがやりました」という感じである。\\n\\n■ be動詞の文\\nWho is absent today? — Ken is.\\nWho was there? — I was.\\nbe動詞の文では be動詞をそのまま返す。\\n\\n■ 助動詞の文\\nWho can swim fast? — Ken can.\\nWho will go with me? — I will.\\n\\n■ 動詞をくり返して答える場合\\nWho broke this window? — Ken broke it.\\nこのとき目的語の it を落とさない。× Ken broke. では文が完成しない（break は「〜を割る」という意味なので、割られたものが必要）。\\n\\n⚠ 注意：Who came here? — Ken came. は目的語が要らない動詞（come）なのでこれで正しい。動詞によって目的語が要るかどうかがちがう。\\n\\n★ ポイント：迷ったら「主語 ＋ did.」の形にしておけば、目的語の抜けを心配しなくてすむ。\"},{\"heading\":\"主語か目的語かの見分け方\",\"body\":\"同じ Who で始まる文でも、主語をたずねているか目的語をたずねているかで意味も形もまったくちがう。ここは記述問題で差がつくところである。\\n\\n■ 二つの文を比べる\\n①Who likes Ken?（だれがケンを好きなのですか）\\n　→ 好きな気持ちを持つ人をたずねる＝主語をたずねる\\n　→ do が要らない、動詞に s が付く\\n　→ 答え：Mary does.\\n\\n②Who does Ken like?（ケンはだれが好きなのですか）\\n　→ 好かれる相手をたずねる＝目的語をたずねる\\n　→ does が要る、動詞は原形\\n　→ 答え：He likes Mary.\\n\\n日本語では「だれが好き」と「だれを好き」の差だけなので、読み取りをまちがえやすい。\\n\\n■ 見分けの手順\\n①疑問詞のすぐあとを見る\\n②動詞（broke, likes, happened）なら → 疑問詞が主語\\n③do / does / did が来て、そのうしろに別の主語があれば → 疑問詞は目的語などで、主語はそのうしろにある\\n（Who is absent? / Who can swim? のように、be動詞や助動詞が来ても、そのうしろに別の主語が無ければ疑問詞が主語）\\n\\n例）Who saw you?（Who が主語。だれがあなたを見た？）\\n例）Who did you see?（you が主語。あなたはだれを見た？）\\n\\n★ ポイント：日本語訳を作るときは「〜が」と「〜を」を必ず書き分ける。英作文では、まず平叙文（Ken likes Mary.）を作り、どちらをたずねたいのかを決めてから疑問詞に置きかえるとまちがえない。\",\"figureId\":\"xf_eigo_s218\",\"mangaId\":\"eigo_s218_xm\"}],\"trapExamples\":[{\"question\":\"「だれがあなたを手伝ってくれたのですか」を英語にしなさい。\",\"wrongAnswer\":\"Who did you help?\",\"trapExplanation\":\"「だれが」「あなたを」という日本語の順に英語を並べてしまい、Who did you 〜? という見慣れた形に落としこんでしまう。この形では「あなたがだれを手伝ったのか」という逆の意味になる。\",\"correctAnswer\":\"Who helped you?\",\"correctExplanation\":\"手伝った人をたずねているので Who が主語であり、did は使わず語順も変えない。Ken helped you. の Ken を Who に置きかえて Who helped you? となる。Who did you help? は「あなたはだれを手伝いましたか」で、助けた側と助けられた側が入れかわってしまう。\"},{\"question\":\"Who broke the cup? に「ケンです」と、動詞を使って答えなさい。\",\"wrongAnswer\":\"Ken broke.\",\"trapExplanation\":\"たずねられた文の動詞をそのまま写して答えを作ってしまう。もとの疑問文では the cup が文の中にあったので、答えでも要らない気がしてしまう。\",\"correctAnswer\":\"Ken did.（または Ken broke it.）\",\"correctExplanation\":\"break は「〜を割る」という、目的語が必要な動詞である。動詞をくり返して答えるなら Ken broke it. と it を付ける。もっと簡単に Ken did. と did で受ける形が、主語をたずねる疑問文への標準的な答え方である。\"}]}",
"{\"id\":\"eigo_s219\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"間接疑問①：文の中に入った疑問文は語順が戻る\",\"description\":\"I know where he lives. のように、疑問詞のあとが主語＋動詞になる形を学ぶ\",\"intro\":\"Where does he live? が、I know のうしろに入ると I know where he lives. になります。does が消え、語順が主語＋動詞に戻るのです。文の中に入ったとたん、疑問文らしさをなくす。この「戻る」動きが間接疑問のかなめです。\",\"order\":719,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"疑問文が別の文の一部に入ると「疑問詞 ＋ 主語 ＋ 動詞」の平叙文の語順に戻る。\",\"do / does / did は消え、その印は動詞に返る（does he live → he lives）。\",\"I know / I don’t know / Tell me / I want to know などのうしろに置く。\",\"文全体が平叙文なら、文末はピリオド。\",\"疑問詞のあとに be動詞を先に出さない（× where is he → ○ where he is）。\"],\"sections\":[{\"heading\":\"語順が戻るしくみ\",\"body\":\"Where does he live? のような疑問文を、別の文の中に組みこむことがある。このとき語順が「ふつうの文（主語＋動詞）」に戻る。この形を間接疑問という。\\n\\n■ 変化のしかた\\nWhere does he live?（彼はどこに住んでいますか）\\n　↓ I know のうしろに入れる\\nI know where he lives.（私は彼がどこに住んでいるか知っています）\\n\\n・does が消える\\n・主語 he と動詞 live の順が「he lives」に戻る\\n・does が預かっていた三単現の s が live に返って lives になる\\n・文全体は平叙文なので最後はピリオド\\n\\n■ ほかの例\\nWhat is this? → I don't know what this is.\\nWho broke the window? → I know who broke the window.（Who が主語の文はもともと平叙文の語順なので変化しない）\\nWhen did she come? → Tell me when she came.（did が消えて came に戻る）\\nWhere are you from? → Please tell me where you are from.\\n\\n■ 前に置ける表現\\nI know 〜／I don't know 〜／Tell me 〜／Please tell me 〜／I want to know 〜／I'm not sure 〜／I remember 〜／Do you know 〜?\\n\\n⚠ 注意：I know where does he live. は誤り。does を残したままにするのが最も多いまちがいである。\",\"figureId\":\"lf_eigoext06_219\",\"mangaId\":\"eigo_s219_xm\"},{\"heading\":\"手順にして覚える\",\"body\":\"間接疑問を作るときは、次の三段階を順に行うと確実である。\\n\\n■ 三つの手順\\n①もとの疑問文を書く：What is this?\\n②do / does / did を消す（あれば動詞に印を返す）\\n③主語→動詞の順に並べかえる：what this is\\n\\n例）What does he want?\\n　①What does he want?\\n　②does を消して want に s を返す → want → wants\\n　③he wants → I know what he wants.\\n\\n例）Where did you buy it?\\n　①Where did you buy it?\\n　②did を消して buy を過去形に → bought\\n　③you bought it → Tell me where you bought it.\\n\\n■ be動詞のときも同じ\\nWho is that man? → I don't know who that man is.\\nbe動詞は主語のうしろに戻る。× who is that man とはしない。\\n\\n■ 疑問詞が主語の場合は変化しない\\nWho broke it? / What happened? のように疑問詞が主語の文は、もともと「主語＋動詞」の語順なので、そのまま入れればよい。\\n例）I don't know who broke it.\\n例）Tell me what happened.\\n\\n★ ポイント：「間接疑問では、疑問文の顔をやめてふつうの文に戻る」と覚える。疑問詞だけが残り、あとはふつうの文になる。\"}],\"trapExamples\":[{\"question\":\"「私は彼がどこに住んでいるか知っています」を英語にしなさい。\",\"wrongAnswer\":\"I know where does he live.\",\"trapExplanation\":\"Where does he live? という疑問文をそのまま I know のうしろにくっつけてしまう。疑問詞が入っているので疑問文の形のままでよい、と思いこむのが原因。\",\"correctAnswer\":\"I know where he lives.\",\"correctExplanation\":\"疑問文が文の一部になると、語順は「疑問詞＋主語＋動詞」に戻る。does は消え、預かっていた三単現の s が動詞に返って lives になる。文全体は「私は知っています」という平叙文なので、最後はピリオドである。\"},{\"question\":\"「これが何なのか教えてください」を英語にしなさい。\",\"wrongAnswer\":\"Please tell me what is this.\",\"trapExplanation\":\"What is this? という覚えている形をそのまま使ってしまう。be動詞の文では do / does が出てこないため、語順が変わることに気づきにくい。\",\"correctAnswer\":\"Please tell me what this is.\",\"correctExplanation\":\"be動詞の文でも、間接疑問では「疑問詞＋主語＋動詞」の語順に戻る。this（主語）→ is（動詞）の順になり、what this is となる。同じく I don’t know who he is. / Do you know where the station is? のように、be動詞は必ず主語のうしろへ回る。\"}]}",
"{\"id\":\"eigo_s220\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"間接疑問②：Do you know 〜? の中に入れる\",\"description\":\"全体が疑問文になる場合の形と、答え方をそろえる\",\"intro\":\"Do you know where he lives? — 全体は疑問文なのに、where のあとは he lives とふつうの語順のままです。前半だけが疑問文の形をとっています。答えるときも Yes, I do. と、前半に合わせて答えます。二重に見える形を、順序立ててほどいていきます。\",\"order\":720,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"Do you know 〜? のうしろに入れても、中の語順は「疑問詞＋主語＋動詞」のまま。\",\"文全体が疑問文なので、文末はクエスチョンマーク。\",\"Do you know 〜? への答えは Yes / No で始めてよい。\",\"Do you think 〜? のときだけ、疑問詞が文の先頭に出る（What do you think this is?）。\",\"道をたずねるときの Do you know where 〜 is? は会話文の頻出表現。\"],\"sections\":[{\"heading\":\"全体が疑問文になる形\",\"body\":\"間接疑問を Do you know 〜? のような疑問文の中に入れることもできる。このとき、中の語順は平叙文のままで、文全体だけが疑問文になる。\\n\\n■ 基本の形\\nDo you know where he lives?（彼がどこに住んでいるか知っていますか）\\nDo you know what this is?\\nDo you know when the concert starts?\\nDo you know who that girl is?\\n\\n中の部分（where he lives）は主語＋動詞の順のままである。外側の Do you know だけが疑問文の形になっている。文末は ? になる。\\n\\n■ ていねいなたずね方\\nCould you tell me where the station is?（駅がどこか教えていただけますか）\\nDo you know how I can get to the museum?\\n道をたずねるときの決まった言い方で、会話文の問題で頻出である。Where is the station? と直接聞くより、ずっとていねいに聞こえる。\\n\\n■ 答え方\\nDo you know 〜? は Yes / No でたずねているので、Yes / No で答えてよい。\\nDo you know where he lives? — Yes, I do. He lives near the station.\\n　　　　　　　　　　　　　 — No, I don't. Sorry.\\n「知っているかどうか」を答えてから、知っていれば内容を続ける。\\n\\n⚠ 注意：Do you know where does he live? は誤り。外側が疑問文になっても、中の語順は変わらない。\"},{\"heading\":\"Do you think 〜? だけは例外\",\"mangaId\":\"eigo_s220_manga\",\"body\":\"Do you know 〜? は Yes / No で答えられるが、Do you think 〜?（〜だと思いますか）は「あなたの考え」をたずねるので Yes / No では答えられない。そのため、疑問詞が文の先頭に出るという特別な形になる。\\n\\n■ know の場合（疑問詞は中に残る）\\nDo you know what this is? — Yes, I do. It's a camera.\\n\\n■ think の場合（疑問詞が先頭に出る）\\nWhat do you think this is? — I think it's a camera.\\n× Do you think what this is? とは言わない。\\n\\n■ think と同じ仲間の動詞\\nthink / believe / say / guess / suppose など「〜と思う・言う」を表す動詞では、疑問詞が先頭に出る。\\nWho do you think will win the game?（だれが勝つと思いますか）\\nWhere do you think he went?（彼はどこへ行ったと思いますか）\\nWhen do you think she will come?\\n\\n答えはいつも I think 〜. の形になる。\\nWho do you think will win? — I think Ken will.\\n\\n★ ポイント：「know なら中に、think なら先頭に」と対で覚える。上位校の入試で問われる差のつく項目である。\\n\\n■ 中の語順は変わらない\\n疑問詞が先頭に出ても、そのうしろは平叙文の語順のまま。\\n○ Where do you think he went?（he went の順）\\n× Where do you think did he go?\",\"figureId\":\"xf_eigo_s220\"}],\"trapExamples\":[{\"question\":\"「駅がどこにあるか知っていますか」を英語にしなさい。\",\"wrongAnswer\":\"Do you know where is the station?\",\"trapExplanation\":\"Where is the station? という覚えている疑問文をそのまま Do you know のうしろにつなげてしまう。外側が疑問文なので、中も疑問文の形でよいと感じてしまう。\",\"correctAnswer\":\"Do you know where the station is?\",\"correctExplanation\":\"中に入った疑問文は「疑問詞＋主語＋動詞」の語順に戻るので、the station（主語）→ is（動詞）の順になる。疑問文の形をとるのは外側の Do you know だけである。ていねいに言うなら Could you tell me where the station is? となる。\"},{\"question\":\"「あなたはこれが何だと思いますか」を英語にしなさい。\",\"wrongAnswer\":\"Do you think what this is?\",\"trapExplanation\":\"Do you know what this is? の形を覚えているため、know を think に置きかえただけで作ってしまう。think の文が Yes / No で答えられないことに気づいていない。\",\"correctAnswer\":\"What do you think this is?\",\"correctExplanation\":\"think は「〜だと思う」なので、答えは Yes / No ではなく I think it’s a camera. のように中身になる。そのため疑問詞を文の先頭に出す。うしろは this is と平叙文の語順のまま。know は Yes / No で答えられるので疑問詞は中に残る、という対比で覚える。\"}]}",
"{\"id\":\"eigo_s221\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"間接疑問③：if / whether（〜かどうか）\",\"description\":\"疑問詞のない疑問文を文の中に入れる形と、条件の if との区別を学ぶ\",\"intro\":\"「彼が来るかどうか知りません」は I don't know if he will come. です。ここの if は「もし」ではなく「〜かどうか」。同じ if が二つの意味を持つので、読みまちがえると内容が変わってしまいます。whether との使い分けもあわせて確かめます。\",\"order\":721,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"疑問詞のない疑問文を文に入れるときは if / whether（〜かどうか）を使う。\",\"if / whether のうしろも「主語＋動詞」の平叙文の語順。\",\"whether 〜 or not の形もある（whether he will come or not）。\",\"条件の if（もし〜なら）とは意味がちがう。文の意味で見分ける。\",\"条件の if の中では、未来のことでも現在形で表す（If it rains tomorrow, 〜）。\"],\"sections\":[{\"heading\":\"「〜かどうか」の言い方\",\"body\":\"Is he a teacher? / Does he come? のように疑問詞のない疑問文を文の中に入れるときは、疑問詞のかわりに if または whether を使う。意味は「〜かどうか」である。\\n\\n■ 作り方\\nIs he a student?（彼は学生ですか）\\n　→ I don't know if he is a student.（彼が学生かどうか知りません）\\n\\nWill he come to the party?\\n　→ I'm not sure if he will come to the party.\\n\\nDid she like it?\\n　→ I want to know if she liked it.（did が消えて過去形に戻る）\\n\\n■ 語順は平叙文のまま\\nif / whether のうしろも「主語＋動詞」の語順になる。\\n○ I don't know if he will come.\\n× I don't know if will he come.\\n\\n■ whether の使い方\\nwhether は if よりあらたまった語で、意味は同じ。\\nI don't know whether he is right.\\nwhether 〜 or not（〜かどうか）の形もよく使う。\\nI don't know whether he will come or not.\\n※ if 〜 or not も使えるが、whether のほうが自然である。\\n\\n■ 前に置ける表現\\nI don't know if 〜／I'm not sure if 〜／Do you know if 〜?／I wonder if 〜（〜かしら）／Please tell me if 〜\\n\\n★ ポイント：疑問詞があれば疑問詞をそのまま使い、なければ if / whether を使う。この一点で使い分けられる。\"},{\"heading\":\"条件の if との区別\",\"body\":\"if には「もし〜なら」という条件の意味もある。同じ語なので、意味で見分ける必要がある。\\n\\n■ 二つの if\\n①〜かどうか（間接疑問）\\nI don't know if he will come.（彼が来るかどうかわからない）\\n→ if 以下が「知らない」の中身になっている\\n\\n②もし〜なら（条件）\\nIf he comes, I will be happy.（もし彼が来たら、私はうれしい）\\n→ if 以下が条件を表し、主となる文が別にある\\n\\n■ 見分け方\\n・know / be sure / wonder / ask のうしろにあれば「〜かどうか」\\n・文の前半か後半で、条件を表していれば「もし〜なら」\\n・「〜かどうか」の if は whether に置きかえられるが、条件の if は置きかえられない。これがいちばん確実な見分け方である。\\n\\n■ 時制の大きなちがい\\n条件の if の中では、未来のことでも will を使わず現在形で表す。\\n○ If it rains tomorrow, I will stay home.（もし明日雨なら）\\n× If it will rain tomorrow, 〜\\n\\n一方、「〜かどうか」の if の中では will をそのまま使う。\\n○ I don't know if it will rain tomorrow.（明日雨が降るかどうか）\\n\\n同じ if でも中の時制がちがうので、意味を取りちがえると必ずまちがえる。\\n\\n⚠ 注意：when（〜するとき）も条件と同じ仲間で、中では未来のことを現在形で表す（I will call you when he comes.）。ただし「いつ〜か」という間接疑問の when では will を使う（I don't know when he will come.）。\",\"figureId\":\"xf_eigo_s221\",\"mangaId\":\"eigo_s221_xm\"}],\"trapExamples\":[{\"question\":\"「彼が来るかどうかわかりません」を英語にしなさい。\",\"wrongAnswer\":\"I don't know if will he come.\",\"trapExplanation\":\"if のうしろに疑問文の形をそのまま入れてしまう。「〜かどうか」というたずねる意味があるため、疑問文の語順にしたくなるのが原因。\",\"correctAnswer\":\"I don't know if he will come.\",\"correctExplanation\":\"if / whether のうしろも、疑問詞のある間接疑問と同じで「主語＋動詞」の平叙文の語順になる。he（主語）→ will come（動詞）の順に並べる。疑問文の顔をやめる、という点は疑問詞の間接疑問とまったく同じである。\"},{\"question\":\"「もし明日雨なら、私は家にいます」を英語にしなさい。\",\"wrongAnswer\":\"If it will rain tomorrow, I will stay home.\",\"trapExplanation\":\"tomorrow があるので未来だと考え、両方の文に will を入れてしまう。条件を表す if の中では未来のことを現在形で表す、という決まりを知らない。\",\"correctAnswer\":\"If it rains tomorrow, I will stay home.\",\"correctExplanation\":\"「もし〜なら」という条件の if の中では、未来のことでも現在形で表す（it rains）。主となる文のほうには will を使う。一方、「〜かどうか」の if では I don’t know if it will rain tomorrow. のように will を使ってよい。二つの if を意味で区別すること。\"}]}",
"{\"id\":\"eigo_s222\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"間接疑問④：時制のそろえ方と総まとめ\",\"description\":\"主となる文が過去のとき、中の動詞も過去にそろえる決まりを身につける\",\"intro\":\"I know where he lives. を過去にすると I knew where he lived. になります。うしろの lives まで lived に変わるのです。日本語では「住んでいると知っていた」と、後半をそのままにできます。英語は文全体で時をそろえる。この差が書きかえ問題で問われます。\",\"order\":722,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"主となる文が過去なら、中に入った文の動詞も過去にそろえる（時制の一致）。\",\"will → would、can → could、is → was、live → lived と一段階過去にする。\",\"語順はどんな場合でも「疑問詞（if / whether）＋主語＋動詞」。\",\"疑問詞が主語の文（who broke it）はもともとこの語順なので変わらない。\",\"書き終えたら「do/does/did が残っていないか」「語順が主語→動詞か」を確かめる。\"],\"sections\":[{\"heading\":\"時制をそろえる\",\"body\":\"主となる文が過去形のとき、中に入った文の動詞も過去にそろえる決まりがある。これを時制の一致という。\\n\\n■ 例で確かめる\\n現在：I know where he lives.\\n過去：I knew where he lived.（lives → lived）\\n\\n現在：I don't know what he wants.\\n過去：I didn't know what he wanted.\\n\\n現在：She asks me if I can swim.\\n過去：She asked me if I could swim.（can → could）\\n\\n現在：I think he will come.\\n過去：I thought he would come.（will → would）\\n\\n■ 一段階うしろへずらす\\nis / are → was / were\\nlive / lives → lived\\ncan → could　　will → would　　may → might\\nこのように、中の動詞や助動詞を一段階過去へずらす。\\n\\n■ 例外（変えなくてよい場合）\\n・いつでも変わらない事実：The teacher said that the earth goes around the sun.\\n・ことわざや現在も続く習慣\\n中学受験では、まず「主となる文が過去なら中も過去」の原則を身につければよい。\\n\\n⚠ 注意：日本語では「彼がどこに住んでいるか知らなかった」と現在のように言うので、英語でも lives のままにしてしまいやすい。英語では knew に合わせて lived にする。\",\"figureId\":\"xf_eigo_s222\",\"mangaId\":\"eigo_s222_xm\"},{\"heading\":\"間接疑問の総チェック\",\"body\":\"ここまでの内容を、答案を見直すときのチェックリストにまとめる。\\n\\n■ ①do / does / did が残っていないか\\n× I know where does he live.\\n○ I know where he lives.\\n中に入った文には do / does / did を残さない。消したぶん、動詞に三単現の s や過去形を返す。\\n\\n■ ②語順が「主語→動詞」になっているか\\n× Tell me what is this.\\n○ Tell me what this is.\\nbe動詞や助動詞を主語より前に出さない。\\n\\n■ ③疑問詞がないときは if / whether を使ったか\\n× I don't know he will come.（接続詞が抜けている）\\n○ I don't know if he will come.\\n\\n■ ④文末の記号は正しいか\\nI know where he lives.（全体は平叙文 → ピリオド）\\nDo you know where he lives?（全体は疑問文 → クエスチョンマーク）\\n\\n■ ⑤時制はそろっているか\\nI didn't know what he wanted.（knew / didn't know に合わせて過去）\\n\\n■ ⑥疑問詞が主語の文はそのまま\\nI don't know who broke the window.（who broke はもとから主語＋動詞）\\n\\n★ ポイント：この六つを順に確かめる習慣をつけると、間接疑問の問題はほぼ落とさなくなる。とくに①と②は配点の高い英作文で必ず見られる。\"}],\"trapExamples\":[{\"question\":\"「私は彼女がそれをどこで買ったのかをたずねました」を英語にしなさい。\",\"wrongAnswer\":\"I asked her where did she buy it.\",\"trapExplanation\":\"Where did she buy it? という疑問文を、そのまま asked のうしろに置いてしまう。間接疑問では語順が戻ることを、疑問詞のある文では忘れやすい。\",\"correctAnswer\":\"I asked her where she bought it.\",\"correctExplanation\":\"did を消し、預かっていた過去の印を動詞に返して bought にする。語順は she bought it と主語→動詞になる。ask のうしろは「たずねた相手（her）＋たずねた内容（where she bought it）」の順に並べる。\"},{\"question\":\"「私は彼が何をほしがっているのか知りませんでした」を英語にしなさい。\",\"wrongAnswer\":\"I didn't know what he wants.\",\"trapExplanation\":\"日本語では「ほしがっている」と現在のように言うため、中の動詞を現在形のままにしてしまう。主となる文が過去であることに引きずられていない。\",\"correctAnswer\":\"I didn't know what he wanted.\",\"correctExplanation\":\"主となる文が didn’t know と過去なので、中の動詞も過去形の wanted にそろえる（時制の一致）。同じように I thought he would come.（will → would）、She said she was busy.（is → was）と一段階過去へずらす。\"}]}",
"{\"id\":\"eigo_s223\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"否定文①：not を置く場所\",\"description\":\"be動詞・一般動詞・助動詞の三系統で、否定文の作り方をそろえる\",\"intro\":\"「私はテニスをしません」は I don't play tennis.、「私は先生ではありません」は I'm not a teacher. です。同じ「〜ない」なのに、片方は don't、もう片方は not だけ。not をどこに置くかは、その文にどんな動詞があるかで決まります。三つの型に分けて整理します。\",\"order\":723,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"be動詞の文は be動詞のうしろに not を置く（I am not / He is not）。\",\"一般動詞の文は do not / does not / did not を主語のうしろに置き、動詞は原形に戻す。\",\"助動詞の文は助動詞のうしろに not を置く（cannot / will not / must not）。\",\"短縮形：isn’t / aren’t / don’t / doesn’t / didn’t / can’t / won’t / mustn’t。\",\"am not に短縮形はない。I’m not の形を使う。\"],\"sections\":[{\"heading\":\"三つの系統で覚える\",\"body\":\"否定文の作り方は、疑問文とちょうど対になっている。疑問文が「前に出す」なら、否定文は「うしろに not を置く」である。\\n\\n■ ①be動詞の文\\nbe動詞のすぐうしろに not を置く。\\nI am a student. → I am not a student.\\nHe is busy. → He is not busy.（He isn't busy.）\\nThey were at home. → They were not at home.（weren't）\\n\\n■ ②一般動詞の文\\n主語のうしろに do not / does not / did not を置き、動詞は原形に戻す。\\nI play tennis. → I do not play tennis.（don't）\\nHe plays tennis. → He does not play tennis.（doesn't play：s が消える）\\nShe went there. → She did not go there.（didn't go：原形に戻る）\\n\\n■ ③助動詞の文\\n助動詞のうしろに not を置く。\\nHe can swim. → He cannot swim.（can't）\\nIt will rain. → It will not rain.（won't）\\nYou must go. → You must not go.（mustn't）\\n※ can not は一語で cannot と書くのがふつう。will not の短縮形は won't という特別な形。\\n\\n★ ポイント：not の位置は、頻度の副詞（always など）の位置とまったく同じ「be動詞のうしろ・一般動詞の前」である。片方を思い出せばもう片方も思い出せる。\",\"figureId\":\"lf_eigoext06_223\"},{\"heading\":\"短縮形と、まちがえやすい形\",\"mangaId\":\"eigo_s223_manga\",\"body\":\"■ 短縮形の一覧\\nis not → isn't　　are not → aren't　　was not → wasn't　　were not → weren't\\ndo not → don't　　does not → doesn't　　did not → didn't\\ncannot → can't　　will not → won't　　must not → mustn't　　should not → shouldn't\\nhave not → haven't　　has not → hasn't\\n\\n■ am not には短縮形がない\\n× amn't という形は使わない。\\n○ I am not / I'm not\\n「私は〜ではありません」は I'm not 〜. と、am ではなく I を縮める。\\n\\n■ 動詞の形に注意\\ndoesn't / didn't のうしろは必ず原形。\\n× He doesn't likes natto. → ○ He doesn't like natto.\\n× She didn't went there. → ○ She didn't go there.\\n疑問文の Does he play 〜? と同じ理屈で、not のかたまりが三単現や過去の印を引き受けている。\\n\\n■ be動詞と一般動詞を混ぜない\\n× I am not have a pen. → ○ I don't have a pen.\\n「持っていません」は一般動詞 have の否定なので do not を使う。be動詞を足してはいけない。\\n\\n■ some と any\\n否定文では some を any に変えるのがふつう。\\nI have some money. → I don't have any money.\\n疑問文でも any を使う（Do you have any questions?）。ただし人にすすめるときは Would you like some tea? のように some のままにする。\"}],\"trapExamples\":[{\"question\":\"He likes natto. を否定文に書きかえなさい。\",\"wrongAnswer\":\"He doesn't likes natto.\",\"trapExplanation\":\"もとの文の likes をそのまま残してしまう。「主語が he だから s が要る」という規則が強く働き、doesn’t がすでに三単現の印を持っていることに気づけない。\",\"correctAnswer\":\"He doesn't like natto.\",\"correctExplanation\":\"doesn’t（does not）が「現在で主語は三人称単数」という情報を引き受けるので、動詞は原形の like に戻る。疑問文の Does he like natto? とまったく同じ理屈である。didn’t のうしろも同じく原形になる。\"},{\"question\":\"「私はペンを持っていません」を英語にしなさい。\",\"wrongAnswer\":\"I am not have a pen.\",\"trapExplanation\":\"「〜ではありません」という日本語の否定を be動詞で表そうとしてしまう。この文の動詞が一般動詞 have であることを意識していない。\",\"correctAnswer\":\"I don't have a pen.\",\"correctExplanation\":\"have は「持っている」という一般動詞なので、否定文は do not（don’t）を使う。be動詞の not を使えるのは I am not a student. のように、うしろが名詞や形容詞で一般動詞がないときだけである。動詞の種類を先に見てから否定の形を決める。\"}]}",
"{\"id\":\"eigo_s224\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"否定文②：not を使わない否定（never / no / few / little）\",\"description\":\"一語で否定を表す語を覚え、二重否定にならないように使う\",\"intro\":\"I don't have no money. と書くと、英語では「お金がないわけではない」という意味に受け取られます。否定は一つの文に一つが原則だからです。not を使わず一語で「〜ない」を表す never・no・few・little を覚えれば、こうした事故は起きません。\",\"order\":724,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"never（一度も〜ない）、no ＋ 名詞（一つも〜ない）はそれだけで否定。\",\"nothing / nobody / no one もそれ自体が否定なので not と重ねない。\",\"not 〜 any ＝ no 〜 で言いかえられる。\",\"few（数）／little（量）は「ほとんど〜ない」。a few / a little は「少しある」。\",\"hardly / seldom も「ほとんど〜ない」という否定の意味を持つ。\"],\"sections\":[{\"heading\":\"一語で否定を表す語\",\"body\":\"否定は not だけで表すとはかぎらない。一語で否定の意味を持つ語がいくつもあり、そのときは not を使わない。\\n\\n■ never（一度も〜ない）\\nI never eat natto.（私は納豆をぜったいに食べない）\\nHe has never been to Kyoto.（現在完了）\\n位置は not と同じで、一般動詞の前・be動詞のうしろ。\\n\\n■ no ＋ 名詞（一つも〜ない）\\nI have no money.（お金をまったく持っていない）\\nThere are no students in the room.\\n＝ I don't have any money. / There aren't any students in the room.\\nno を使う言い方のほうが、否定の気持ちが強い。\\n\\n■ nothing / nobody / no one\\nI have nothing to do.（することが何もない）\\nNobody came to the party.（だれもパーティーに来なかった）\\nNothing is impossible.\\nこれらが主語のときは三人称単数として扱う（Nobody knows the answer.）。\\n\\n■ 二重否定にしない\\nこれらの語はそれ自体が否定なので、don't などと重ねてはいけない。\\n× I don't have no money. → ○ I don't have any money. / I have no money.\\n× I don't know nothing. → ○ I don't know anything. / I know nothing.\\n\\n⚠ 注意：日本語の「何も知らない」には否定が二つあるように見えるので、英語でも重ねてしまいやすい。英語では否定は一つだけ。\",\"figureId\":\"xf_eigo_s224\"},{\"heading\":\"few / little と、そのほかの否定語\",\"body\":\"few と little は、a が付くかどうかで意味が正反対になる。入試で必ず問われるところである。\\n\\n■ few（数えられる名詞に）\\nfew friends（友達がほとんどいない）＝否定的\\na few friends（友達が少しいる）＝肯定的\\n例）He has few friends.（彼にはほとんど友達がいない）\\n例）He has a few friends.（彼には友達が少しいる）\\n\\n■ little（数えられない名詞に）\\nlittle money（お金がほとんどない）＝否定的\\na little money（お金が少しある）＝肯定的\\n例）I have little time.（時間がほとんどない）\\n例）I have a little time.（少し時間がある）\\n\\n■ そのほかの否定を表す語\\nhardly / scarcely（ほとんど〜ない）：I can hardly hear you.（ほとんど聞こえません）\\nseldom / rarely（めったに〜ない）：He seldom watches TV.\\ntoo 〜 to …（〜すぎて…できない）：This box is too heavy to carry.\\n\\n■ 意味の強さの順\\nnever（0％）＜ hardly / seldom（ほとんど・めったに）＜ sometimes（ときどき）\\n\\n★ ポイント：a が付けば「ある」、付かなければ「ない」。a few / a little の a は「少しはある」という気持ちを表していると考えると覚えやすい。\\n\\n⚠ 注意：Only a few students came. のように only が付くと、a few でも「たった数人しか」という否定的な感じになる。\",\"mangaId\":\"eigo_s224_xm\"}],\"trapExamples\":[{\"question\":\"「私はお金をまったく持っていません」を英語にしなさい。\",\"wrongAnswer\":\"I don't have no money.\",\"trapExplanation\":\"「まったく〜ない」という強い否定を表そうとして、don’t と no を両方使ってしまう。日本語の「持っていない」と「まったくない」を、どちらも英語の否定語に置きかえた結果である。\",\"correctAnswer\":\"I don't have any money.（または I have no money.）\",\"correctExplanation\":\"英語では一つの文に否定を二つ入れない。don’t を使うなら名詞の前は any、no を使うなら don’t は使わない、のどちらかにする。意味はほぼ同じだが、I have no money. のほうが否定の気持ちが強く伝わる。\"},{\"question\":\"He has few friends. の意味として正しいものを答えなさい。\",\"wrongAnswer\":\"彼には少し友達がいます。\",\"trapExplanation\":\"few を「少し」と覚えているため、a の有無を見ずに肯定の意味で訳してしまう。a few（少しいる）と few（ほとんどいない）の差は a 一文字だけなので見落としやすい。\",\"correctAnswer\":\"彼にはほとんど友達がいません。\",\"correctExplanation\":\"a の付かない few / little は「ほとんど〜ない」という否定の意味になる。a few / a little なら「少しはある」という肯定の意味である。数えられる名詞には few / a few、数えられない名詞には little / a little を使う点も合わせて覚える。\"}]}",
"{\"id\":\"eigo_s225\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"否定文③：部分否定と全体否定\",\"description\":\"not all / not always と、no / none / neither の意味のちがいを読み分ける\",\"intro\":\"I don't know all of them. は「全員は知らない」で、何人かは知っています。I know none of them. なら「一人も知らない」。日本語の「みんな知らない」はどちらにも読めてしまう、あいまいな言い方です。英語は形ではっきり区別します。\",\"order\":725,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"not ＋ all / every / always / both は部分否定「すべてが〜とはかぎらない」。\",\"no / none / never / neither は全体否定「まったく〜ない」。\",\"Not all birds can fly. は「飛べない鳥もいる」という意味。\",\"「二人とも知らない」は not both ではなく neither / not either を使う。\",\"日本語訳では「〜とはかぎらない」「〜わけではない」と書くと部分否定が伝わる。\"],\"sections\":[{\"heading\":\"部分否定（一部だけを否定する）\",\"mangaId\":\"eigo_s225_manga\",\"body\":\"all（すべて）・every（どの〜も）・always（いつも）・both（両方）のように「全部」を表す語が not といっしょに使われると、「全部が〜というわけではない」という一部だけの否定になる。これを部分否定という。\\n\\n■ 代表的な形\\nNot all the students came to school.（生徒全員が学校に来たわけではない＝来た生徒もいる）\\nI don't know all of them.（彼ら全員を知っているわけではない）\\nHe is not always kind.（彼はいつも親切とはかぎらない）\\nNot every student likes math.（すべての生徒が数学を好きなわけではない）\\nI don't like both of them.（両方とも好きというわけではない）\\n\\n■ 訳し方のこつ\\n「すべてが〜というわけではない」「いつも〜とはかぎらない」と、「〜わけではない」「〜とはかぎらない」を必ず入れる。これを入れないと全体否定と区別がつかない。\\n\\n■ 図で考える\\nNot all the students came. は、来た生徒と来なかった生徒が両方いる状態を表す。全員が来なかったのではない。\\n\\n⚠ 注意：日本語の「全部来なかった」はふつう全体否定の意味に取られる。部分否定を訳すときは「全員が来たわけではない」と書くこと。\",\"figureId\":\"lf_eigoext06_225\"},{\"heading\":\"全体否定（まるごと否定する）\",\"body\":\"いっぽう、まるごと否定する言い方は別の語を使う。\\n\\n■ 全体否定の形\\nNone of the students came to school.（生徒はだれも来なかった＝0人）\\nNo student came to school.\\nNobody came.\\nI know neither of them.（二人とも知らない）\\nHe is never kind.（彼はけっして親切ではない）\\nI don't know any of them.（彼らのだれも知らない）\\n\\n■ 部分否定と全体否定の対\\n・not all ↔ none / no\\n・not always ↔ never\\n・not both ↔ neither\\n左が部分否定、右が全体否定である。\\n\\n■ both と either / neither\\nboth（両方とも）は not といっしょに使うと部分否定になるので、「二つとも〜ない」と言いたいときは either / neither を使う。\\n○ I don't like either of them.（どちらも好きではない）\\n○ I like neither of them.（同じ意味）\\n△ I don't like both of them.（両方好きというわけではない＝部分否定）\\n\\n■ 読解でのポイント\\n入試の長文では、not all / not always の部分否定が内容一致問題のかぎになることが多い。「すべてが〜ではない」を「まったく〜ない」と読みちがえると、選択肢の正誤が逆になる。\\n\\n★ ポイント：not のうしろに all / every / always / both があったら、必ず部分否定を疑う。\"}],\"trapExamples\":[{\"question\":\"Not all the students came to school today. の意味として正しいものを答えなさい。\",\"wrongAnswer\":\"きょうは生徒がだれも学校に来なかった。\",\"trapExplanation\":\"not（〜ない）と all（すべて）をそのままつなげて「すべて〜ない」と読み、全員が来なかったと解釈してしまう。日本語の「全部来なかった」という言い方に引きずられるのが原因。\",\"correctAnswer\":\"きょうは生徒全員が学校に来たわけではない（来なかった生徒もいる）。\",\"correctExplanation\":\"not ＋ all は部分否定で、「全部が〜というわけではない」という意味になる。来た生徒もいれば来なかった生徒もいる状態である。全員が来なかったと言いたいときは None of the students came. や No student came. と表す。\"},{\"question\":\"「私は彼ら二人とも知りません」を英語にしなさい。\",\"wrongAnswer\":\"I don't know both of them.\",\"trapExplanation\":\"「二人とも」を both と置きかえ、「知りません」を don’t know と置きかえて、そのままつなげてしまう。not と both が組み合わさると部分否定になることを知らない。\",\"correctAnswer\":\"I don't know either of them.（または I know neither of them.）\",\"correctExplanation\":\"not ＋ both は「両方とも〜というわけではない」という部分否定になり、片方は知っている意味になってしまう。二つとも否定するときは not 〜 either か neither を使う。not all ↔ none、not always ↔ never と同じ対の関係である。\"}]}",
"{\"id\":\"eigo_s226\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞のはたらき①：名詞を前から説明する（限定用法）\",\"description\":\"形容詞が名詞の直前に置かれて「どんな〜」を説明する使い方と、冠詞との語順を身につける\",\"intro\":\"「赤い車」は a red car です。ここで red a car とは言えません。日本語では「その赤い車」も「赤いその車」も通じますが、英語では a や the が必ず形容詞より前に来ます。名詞の前にならぶ語には、動かせない順番があるのです。\",\"order\":726,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"形容詞は「どんな」を表す語。名詞の直前に置いて名詞を説明する（限定用法）。\",\"語順は〈冠詞・所有格＋形容詞＋名詞〉。a big dog であって big a dog ではない。\",\"a と an は、次に来る語の「音」で決める。形容詞が入れば形容詞の音で決まる（an old dog）。\",\"useful・university は「ユ」の音で始まるので a useful book / a university。\",\"複数形の名詞についても形容詞の形は変わらない（beautiful flowers。beautifuls とはしない）。\"],\"sections\":[{\"heading\":\"形容詞は名詞の前に置く\",\"body\":\"形容詞とは「大きい」「新しい」「親切な」のように、人やものが「どんなものか」を表す語である。英語の形容詞には二つの使い方があり、そのうちの一つが名詞のすぐ前に置いて名詞を説明する使い方で、これを限定用法という。\\n\\n例）a big dog（大きな犬）／an old book（古い本）／beautiful flowers（美しい花）／my new bike（私の新しい自転車）\\n\\n日本語でも「大きな犬」と、説明する語が名詞の前に来る。ここは日本語と英語の語順が一致するので覚えやすい。\\n\\n■ 冠詞・所有格は形容詞よりさらに前\\nまちがえやすいのが a・an・the・my・your などとの順番である。これらは必ず形容詞よりも前に置く。\\n\\n正）a big dog／an interesting story／the tall boy／my new bike\\n誤）big a dog／interesting an story／tall the boy／new my bike\\n\\n日本語では「大きな一匹の犬」と言えてしまうため、a を形容詞のあとに置く誤りが非常に多い。〈a → 形容詞 → 名詞〉という並びを声に出して覚えてしまうとよい。\\n\\n■ 名詞が複数形でも形容詞は変化しない\\n名詞が複数になっても形容詞に s は付かない。\\n\\n正）three big apples／beautiful flowers／two new pencils\\n誤）three bigs apples／beautifuls flowers\\n\\n★ ポイント：英語の形容詞は「数」でも「男女」でも形が変わらない。変わるのは名詞のほうだけである。\",\"figureId\":\"xf_eigo_s226\"},{\"heading\":\"a と an は「音」で決める\",\"body\":\"a と an の使い分けは「つづり」ではなく「次に来る語の発音」で決まる。母音の音（ア・イ・ウ・エ・オ）で始まる語の前では an を使う。\\n\\n例）an apple／an egg／an ice cream／an orange／an umbrella\\n\\n■ 形容詞が入ると、判断するのは形容詞の音\\n名詞の前に形容詞が入った場合、a か an かを決めるのは名詞ではなく、すぐ後ろに来る形容詞の音である。\\n\\n例）an old dog（dog は子音で始まるが、直後の old が母音の音なので an）\\n例）a big apple（apple は母音で始まるが、直後の big が子音の音なので a）\\n\\n■ つづりにだまされない語\\nつづりが母音字で始まっていても、発音が「ユ」や「ワ」で始まる語には a を使う。\\n\\n例）a useful book（ユースフル）／a university（ユニバーシティ）／a uniform（ユニフォーム）／a European country（ユーロピアン）\\n\\n逆に、つづりが子音字でも発音が母音で始まる語には an を使う。\\n\\n例）an hour（アウア。h を発音しない）／an honest boy（オネスト）\\n\\n⚠ 注意：「an useful book」は入試で頻出のひっかけ。useful は母音字 u で始まるが、発音は「ユ」なので a が正しい。\",\"mangaId\":\"eigo_s226_xm\"}],\"trapExamples\":[{\"question\":\"「大きな犬」を英語にしなさい。\",\"wrongAnswer\":\"big a dog\",\"trapExplanation\":\"日本語の「大きな一匹の犬」という語順や、「big（大きな）」をまず言いたい気持ちに引っぱられて、a を形容詞のあとに置いてしまう。\",\"correctAnswer\":\"a big dog\",\"correctExplanation\":\"英語の語順は〈冠詞・所有格＋形容詞＋名詞〉と決まっている。a・an・the・my・your などは、形容詞よりも必ず前に置く。同じように「私の新しい自転車」は my new bike であって new my bike ではない。\"},{\"question\":\"（　）に a か an を入れなさい。（　）useful book\",\"wrongAnswer\":\"an useful book\",\"trapExplanation\":\"useful がつづり上は母音字 u で始まるので、機械的に an を選んでしまう。「母音字なら an」と、つづりだけで覚えていると引っかかる。\",\"correctAnswer\":\"a useful book\",\"correctExplanation\":\"a と an はつづりではなく発音で決まる。useful の発音は「ユースフル」で、子音の「ユ」の音から始まるので a を使う。同じ仲間に a university、a uniform、a European country がある。逆に an hour（アウア）は h を発音しないため an になる。\"}]}",
"{\"id\":\"eigo_s227\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞の語順：形容詞を二つ以上ならべるとき\",\"description\":\"数量詞・評価・大小・新旧・色といった形容詞の並び順を、決まった順番として覚える\",\"intro\":\"「大きな古い茶色のいす」を英語にすると a big old brown chair となります。順番を変えて a brown old big chair とすると、とたんに英語らしくなくなります。英語には形容詞をならべる決まった順番があり、話し手は考えずにその順で口にしているのです。\",\"order\":727,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"形容詞をならべる順番は〈数量・冠詞〉→〈評価〉→〈大小〉→〈新旧〉→〈色〉→〈材料・出身〉→名詞。\",\"a・the・my・two などの数量を表す語は、どんなときでも列の先頭に置く。\",\"色を表す形容詞は名詞のいちばん近くに置く（big red apples）。\",\"中学入試では形容詞を三つ以上ならべることはまれ。二つの順番を確実にする。\",\"同じ種類の形容詞を並べるときは and でつなぐ（a big and heavy bag）。\"],\"sections\":[{\"heading\":\"形容詞をならべる順番\",\"body\":\"形容詞は一つの名詞に二つ以上つけることができる。そのとき英語では並べる順番がほぼ決まっており、順番を入れかえると不自然になる。\\n\\n■ 基本の順番\\n〈冠詞・所有格・数〉→〈評価（よい・すてきな）〉→〈大きさ〉→〈新しさ・年齢〉→〈色〉→〈材料・出身〉→〈名詞〉\\n\\n例）two big red apples（大きな赤いりんご2個）\\n例）a beautiful old temple（美しい古いお寺）\\n例）my new blue bike（私の新しい青い自転車）\\n例）a nice small Japanese car（すてきな小さい日本車）\\n\\n日本語では「赤くて大きなりんご」でも「大きくて赤いりんご」でも自然だが、英語では big red apples の順が普通で、red big apples とは言わない。色は名詞のいちばん近くに置くと覚える。\\n\\n■ 数量・冠詞は必ず先頭\\na・an・the・my・your・his・two・three・some などは、形容詞より前の先頭に置く。\\n\\n正）my new bike／three big apples／some old books\\n誤）new my bike／big three apples／old some books\\n\\n★ ポイント：中学入試で問われるのは形容詞二つまでがほとんど。「数や a は先頭」「色は名詞のとなり」の二点をおさえれば、ほぼ正解できる。\",\"figureId\":\"lf_eigoext07_227\"},{\"heading\":\"同じ種類の形容詞は and でつなぐ\",\"body\":\"並べる形容詞が同じ種類（どちらも大きさ、どちらも性格など）である場合は、間に and を入れる。\\n\\n例）a big and heavy bag（大きくて重いかばん）\\n例）She is kind and gentle.（彼女は親切でおだやかだ）\\n例）a long and boring movie（長くて退屈な映画）\\n\\n種類がちがう場合は and を入れずにそのまま並べる。\\n\\n例）a big red ball（大きな赤いボール。大きさと色でちがう種類）\\n\\n■ 三つ以上ならべるとき\\n文の途中で三つ以上ならべる場合は、コンマでつなぎ、最後だけ and にする。\\n\\n例）She is kind, cheerful, and honest.（彼女は親切で明るく正直だ）\\n\\n■ 数を表す語との組み合わせ\\n数を表す語（two, three, some, many）は、他の形容詞より前に来る。\\n\\n例）many beautiful flowers（たくさんの美しい花）\\n例）three small white dogs（3匹の小さな白い犬）\\n\\n⚠ 注意：「たくさんの美しい花」を beautiful many flowers としないこと。many のような数量の語は必ず前に出す。\"},{\"heading\":\"なぜ形容詞の順番が決まっているのか\",\"mangaId\":\"eigo_s227_manga\",\"body\":\"英語では、**名詞に近い形容詞ほど、その名詞と切りはなせない性質**を表します。色や材料（red・Japanese）はそのものの変わらない性質なので名詞のすぐ前、大きさや新しさは見た印象、評価（nice・beautiful）は話し手の気持ちなので名詞から遠くに置きます。数や a・my はそもそも「どれ・いくつ」を決める語なので列の先頭です。話し手は考えずにこの順で口にしているので、順番を変えると英語らしくなくなります。\\n\\n同じ種類の形容詞（どちらも大きさ、どちらも性格）を and でつなぐのは、**同じ種類は順番がつけられない**からです。big と heavy はどちらも見た印象なので a big and heavy bag、big と red は種類がちがうので a big red ball と並べます。\\n\\n■ 確かめのしかた\\n①**数・冠詞・所有格は先頭**か。× new my bike→my new bike。× beautiful many flowers→many beautiful flowers。\\n②**色は名詞のいちばん近く**か。× three red big apples→three big red apples。\\n③二つの形容詞が同じ種類なら and、ちがう種類ならそのまま並べる。a big and heavy bag／a big white dog。\\n④三つ以上並べるときはコンマでつなぎ、最後だけ and（kind, cheerful, and honest）。\\n\\n★ ここがポイント：**名詞に近いほど、その名詞と切りはなせない性質**（色・材料）を表すので順番が決まる。**数・a・my は先頭、色は名詞のとなり**の二点で入試はほぼ解ける。同じ種類は and でつなぐ。\"}],\"trapExamples\":[{\"question\":\"「私の新しい自転車」を英語にしなさい。\",\"wrongAnswer\":\"new my bike\",\"trapExplanation\":\"日本語の「新しい／私の／自転車」という語感のまま、説明したい語（new）を先に出してしまう。形容詞は名詞の前という規則だけを覚えていると、my も形容詞と同じ位置に置いてしまう。\",\"correctAnswer\":\"my new bike\",\"correctExplanation\":\"my・your・his などの所有格は、a・the と同じ仲間で、形容詞よりさらに前の先頭に置く。〈所有格→形容詞→名詞〉の順である。同じように「あなたの古いかばん」は your old bag となる。\"},{\"question\":\"「3個の大きな赤いりんご」を英語にしなさい。\",\"wrongAnswer\":\"three red big apples\",\"trapExplanation\":\"日本語では「赤くて大きい」も「大きくて赤い」も自然なので、そのまま英語に置きかえて red を先に出してしまう。\",\"correctAnswer\":\"three big red apples\",\"correctExplanation\":\"英語では〈大きさ→色→名詞〉の順が決まっている。色を表す形容詞は名詞のいちばん近くに置く。数を表す three はもっとも前である。「大きな白い犬」なら a big white dog となる。\"}]}",
"{\"id\":\"eigo_s228\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞のはたらき②：be動詞のあとで説明する（叙述用法）\",\"description\":\"be動詞や look・sound などのあとに置かれ、主語の様子を説明する形容詞の使い方を理解する\",\"intro\":\"This soup is hot. と This is hot soup. — どちらも熱いスープの話ですが、前者は be動詞のあと、後者は名詞の前に hot があります。形容詞には二つの居場所があるのです。さらに look や sound のあとにも入ります。どこに置けるのかを整理します。\",\"order\":728,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"〈主語＋be動詞＋形容詞〉で「主語は〜だ」を表す（叙述用法）。\",\"look・sound・feel・taste・smell・become・get のあとにも形容詞が来る。\",\"これらの動詞のあとを副詞にしてはいけない（You look happy. であって happily ではない）。\",\"日本語の「〜だ」に引かれて be動詞を落とさない（This book is interesting.）。\",\"同じ形容詞が限定用法にも叙述用法にも使えるのが普通（a kind boy / He is kind.）。\"],\"sections\":[{\"heading\":\"be動詞のあとに置く形容詞\",\"body\":\"形容詞のもう一つの使い方が、be動詞のあとに置いて主語の様子を説明する使い方で、これを叙述用法という。\\n\\n例）This flower is beautiful.（この花は美しい）\\n例）He is kind.（彼は親切だ）\\n例）They are busy.（彼らは忙しい）\\n例）The test was easy.（そのテストは簡単だった）\\n\\n限定用法との関係を見比べるとわかりやすい。\\n\\n限定用法）He is a kind boy.（彼は親切な少年だ）＝ kind が boy を説明\\n叙述用法）He is kind.（彼は親切だ）＝ kind が主語 He を説明\\n\\n■ be動詞を落とさない\\n日本語の「この本はおもしろい」には「〜だ」にあたる語がはっきり出てこないため、英語でも be動詞を落としてしまう誤りが非常に多い。\\n\\n正）This book is interesting.\\n誤）This book interesting.\\n\\n英語では「〜は〜だ」という文に必ず動詞が必要である。形容詞だけでは文にならない。\\n\\n■ 主語に合わせて be動詞を選ぶ\\nI am／You are／He is／They are と、主語によって be動詞の形が変わる点も忘れない。\\n\\n例）I am hungry.／You are tired.／She is happy.／We are ready.\\n\\n★ ポイント：形容詞を見たら「これは名詞を説明しているのか、主語を説明しているのか」と自分に問う。名詞の前なら限定用法、be動詞のあとなら叙述用法である。\",\"figureId\":\"xf_eigo_s228\"},{\"heading\":\"look・sound・feel などのあとも形容詞\",\"body\":\"be動詞のほかにも、あとに形容詞を置いて主語の様子を説明する動詞がある。中学入試でよく出るのは次の動詞である。\\n\\nlook（〜に見える）／sound（〜に聞こえる）／feel（〜に感じる）／taste（〜の味がする）／smell（〜のにおいがする）／become・get（〜になる）\\n\\n例）You look happy.（あなたはうれしそうに見える）\\n例）That sounds interesting.（それはおもしろそうだ）\\n例）I feel sick.（気分が悪い）\\n例）This cake tastes good.（このケーキはおいしい）\\n例）These flowers smell sweet.（この花はよい香りがする）\\n例）It is getting cold.（寒くなってきた）\\n例）He became famous.（彼は有名になった）\\n\\n■ ここを副詞にしてはいけない\\n「うれしそうに見える」の「〜そうに」につられて happily としてしまう誤りが非常に多い。\\n\\n正）You look happy.\\n誤）You look happily.\\n\\nこれらの動詞のあとに来る語は、動作のしかたを説明しているのではなく、主語がどんな状態かを説明している。だから形容詞でなければならない。\\n\\n■ look at との区別\\nlook のあとに at が付くと「〜を見る」という動作の意味になり、そのときは副詞で修飾する。\\n\\n例）He looked at me carefully.（彼は私を注意深く見た）\\n\\n⚠ 注意：〈look＋形容詞〉は「〜に見える」、〈look at＋名詞〉は「〜を見る」。at があるかないかで意味も後ろの品詞も変わる。\",\"mangaId\":\"eigo_s228_xm\"}],\"trapExamples\":[{\"question\":\"「あなたは幸せそうに見える。」を英語にしなさい。\",\"wrongAnswer\":\"You look happily.\",\"trapExplanation\":\"日本語の「幸せそうに」の「〜に」を副詞のしるしだと考え、happy を happily に変えてしまう。副詞は動詞を説明するもの、という規則を機械的にあてはめた結果の誤り。\",\"correctAnswer\":\"You look happy.\",\"correctExplanation\":\"look・sound・feel・taste・smell のあとに来る語は、主語がどんな状態かを説明するので形容詞になる。You と happy が「あなた＝幸せ」という関係になっている。同じく That sounds interesting.、This cake tastes good. も形容詞である。\"},{\"question\":\"「この本はおもしろい。」を英語にしなさい。\",\"wrongAnswer\":\"This book interesting.\",\"trapExplanation\":\"日本語では「この本はおもしろい」に動詞らしい語が見あたらないため、英語でも be動詞が要らないと感じてしまう。\",\"correctAnswer\":\"This book is interesting.\",\"correctExplanation\":\"英語の文には必ず動詞が必要である。〈主語＋be動詞＋形容詞〉で「〜は…だ」を表すので、is を落としてはいけない。主語が複数なら These books are interesting. となる。\"}]}",
"{\"id\":\"eigo_s229\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"-ing・-ed の形容詞と、something のあとに置く形容詞\",\"description\":\"exciting と excited の使い分け、および -thing で終わる語を後ろから説明する語順を身につける\",\"intro\":\"I'm exciting. と言うと、「私は人をわくわくさせる人です」という意味になってしまいます。言いたいのが「わくわくしている」なら I'm excited. です。-ing と -ed のちがいが、そのまま「させる側」と「される側」のちがいになります。\",\"order\":729,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"-ing の形容詞は「（もの・ことが）〜させる」、-ed の形容詞は「（人が）〜させられた気持ち」。\",\"The game was exciting.（試合がわくわくさせる）／I was excited.（私がわくわくした）。\",\"interesting/interested、surprising/surprised、boring/bored、tiring/tired も同じ関係。\",\"something・anything・nothing を説明する形容詞は後ろに置く（something cold）。\",\"〈something＋形容詞＋to 不定詞〉の順（something cold to drink）。\"],\"sections\":[{\"heading\":\"exciting と excited のちがい\",\"mangaId\":\"eigo_s229_manga\",\"body\":\"動詞から作られた -ing・-ed の形は、そのまま形容詞として使うことができる。二つの形の意味のちがいをはっきりさせておく。\\n\\n■ -ing の形容詞＝「（人を）〜させるような」\\nもの・こと・できごとが主語になる。\\n\\n例）The game was exciting.（その試合はわくわくするものだった）\\n例）This book is interesting.（この本はおもしろい）\\n例）The news was surprising.（その知らせは驚くべきものだった）\\n例）The movie was boring.（その映画は退屈だった）\\n\\n■ -ed の形容詞＝「〜させられた気持ちだ」\\n人が主語になる。\\n\\n例）I was excited.（私はわくわくした）\\n例）I am interested in science.（私は理科に興味がある）\\n例）We were surprised at the news.（私たちはその知らせに驚いた）\\n例）He was bored.（彼は退屈していた）\\n\\n■ 見分け方\\n主語が人か、もの・ことかで決める。「試合」がわくわくさせる側、「私」がわくわくさせられる側である。\\n\\n例）I was excited about the exciting game.（私はそのわくわくする試合に興奮した）\\n\\nこの一文に両方の形が出ているので、まるごと覚えてしまうとよい。\\n\\n★ ポイント：be interested in ~（〜に興味がある）、be surprised at ~（〜に驚く）は前置詞ごと熟語で覚える。\",\"figureId\":\"xf_eigo_s229\"},{\"heading\":\"something を説明する形容詞は後ろ\",\"body\":\"形容詞は名詞の前に置くのが原則だが、-thing・-body・-one で終わる語を説明するときだけは後ろに置く。\\n\\n例）something cold（何か冷たいもの）\\n例）anything interesting（何かおもしろいもの）\\n例）nothing special（特別なことは何もない）\\n例）someone kind（だれか親切な人）\\n\\n例文）I want something cold to drink.（何か冷たい飲み物がほしい）\\n例文）Did you see anything strange?（何か変なものを見ましたか）\\n例文）Nothing special happened yesterday.（昨日は特に何も起こらなかった）\\n\\n■ to 不定詞が続くときの語順\\n〈something＋形容詞＋to＋動詞の原形〉の順になる。形容詞が先、to 不定詞が後である。\\n\\n正）something cold to drink（何か冷たい飲み物）\\n誤）something to drink cold\\n誤）cold something to drink\\n\\n例）I have something important to tell you.（あなたに話す大事なことがある）\\n例）Give me something hot to eat.（何か温かい食べ物をください）\\n\\n■ 疑問文・否定文では anything\\nsomething は肯定文、anything は疑問文・否定文で使うのが原則である。\\n\\n例）I have something to do.／Do you have anything to do?／I don't have anything to do.\\n\\n⚠ 注意：この後置の規則は -thing・-body・-one で終わる語だけ。ふつうの名詞には使えない（cold water を water cold とは言わない）。\"}],\"trapExamples\":[{\"question\":\"「私はその試合にわくわくした。」を英語にしなさい。\",\"wrongAnswer\":\"I was exciting.\",\"trapExplanation\":\"日本語の「わくわくした」がそのまま exciting に見えるうえ、-ing のほうがよく目にする形なので選んでしまう。しかし I was exciting. は「私は（他人を）わくわくさせる人だった」という意味になってしまう。\",\"correctAnswer\":\"I was excited about the game.\",\"correctExplanation\":\"人が「〜させられた気持ち」を表すときは -ed の形を使う。わくわくさせているのは試合のほうなので、The game was exciting. と I was excited. がセットになる。interested / interesting、surprised / surprising も同じ関係である。\"},{\"question\":\"「何か冷たい飲み物がほしい。」を英語にしなさい。\",\"wrongAnswer\":\"I want cold something to drink.\",\"trapExplanation\":\"「形容詞は名詞の前」という原則をそのままあてはめて、cold を something の前に置いてしまう。\",\"correctAnswer\":\"I want something cold to drink.\",\"correctExplanation\":\"-thing・-body・-one で終わる語を説明する形容詞だけは、例外的に後ろに置く。さらに to 不定詞が続くときは〈something＋形容詞＋to＋動詞の原形〉の順になる。something hot to eat、something important to tell you も同じ形である。\"}]}",
"{\"id\":\"eigo_s230\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数えられる名詞・数えられない名詞と many / much\",\"description\":\"可算名詞・不可算名詞の区別をもとに、many と much を正しく使い分ける\",\"intro\":\"「本がたくさんある」は many books、「水がたくさんある」は much water です。日本語ではどちらも「たくさん」ですみます。英語では、一つ二つと数えられるかどうかで語を選び分けるのです。まずは名詞を二つの仲間に分けるところから始めます。\",\"order\":730,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"many＋数えられる名詞の複数形（many books）／much＋数えられない名詞（much water）。\",\"water・milk・money・time・homework・information・bread・rice・news は数えられない名詞。\",\"数えられない名詞は複数形にしない（homeworks・informations とは言わない）。\",\"much は肯定文ではあまり使わず、ふつう a lot of を使う（I have a lot of money.）。\",\"数えられない名詞を数えるときは容器や単位を使う（a glass of water, two cups of tea）。\"],\"sections\":[{\"heading\":\"数えられる名詞と数えられない名詞\",\"body\":\"英語の名詞は「一つ、二つと数えられるもの」と「数えられないもの」に分かれる。この区別が数量を表す形容詞の使い分けの土台になる。\\n\\n■ 数えられる名詞（可算名詞）\\n形がはっきりしていて一つ二つと数えられるもの。単数には a／an を付け、二つ以上なら複数形にする。\\n\\n例）a book / two books／an apple / three apples／a student / many students\\n\\n■ 数えられない名詞（不可算名詞）\\n液体・材料・目に見えない概念など、形が決まっていないもの。a／an を付けず、複数形にもしない。\\n\\n液体・材料）water, milk, tea, coffee, juice, bread, rice, paper, money\\n目に見えないもの）time, work, homework, information, news, advice, music, love\\n\\n例）I need money.（× a money、× moneys）\\n例）I have a lot of homework.（× homeworks）\\n\\n■ 数えたいときは容器・単位を使う\\n数えられない名詞を数えるときは、入れ物や単位を表す語をつける。\\n\\n例）a glass of water（コップ1杯の水）／two cups of tea（お茶2杯）／three pieces of paper（紙3枚）／a slice of bread（パン1枚）\\n\\n★ ポイント：日本人がまちがえやすいのは homework・information・news・advice の4語。どれも英語では数えられない名詞である。\"},{\"heading\":\"many と much の使い分け\",\"body\":\"「たくさんの」を表す形容詞は、後ろの名詞が数えられるかどうかで使い分ける。\\n\\n■ many＋数えられる名詞の複数形\\n例）many books（たくさんの本）／many students／many friends／many countries\\n\\n■ much＋数えられない名詞\\n例）much water（たくさんの水）／much money／much time／much snow\\n\\n正）I have many friends.\\n正）I don't have much time.\\n誤）I have much friends.\\n誤）I don't have many time.\\n\\n■ much は肯定文ではあまり使わない\\nmuch は否定文・疑問文でよく使われるが、ふつうの肯定文ではかたい言い方になる。肯定文では a lot of を使うのが自然である。\\n\\n自然）I have a lot of money.\\n不自然）I have much money.\\n\\n一方 many は肯定文でも自然に使える。\\n\\n例）Many students came to the party.（多くの生徒がパーティーに来た）\\n\\n■ 疑問文の How many / How much\\n数をたずねるときは How many＋複数形、量や値段をたずねるときは How much を使う。\\n\\n例）How many books do you have?（本を何冊持っていますか）\\n例）How much water do you need?（水がどれくらい必要ですか）\\n例）How much is this bag?（このかばんはいくらですか）\\n\\n⚠ 注意：How many のあとの名詞は必ず複数形（How many book ではなく How many books）。\"},{\"heading\":\"なぜ homework は数えられず、なぜ肯定文で much を避けるのか\",\"mangaId\":\"eigo_s230_manga\",\"body\":\"英語で「数えられる」とは、**形がはっきりしていて一つ二つと区切れる**ことです。water や bread は区切りがなく、homework・information・news・advice は目に見えない「まとまり」なので、英語では数えません。日本語では「宿題が三つ」と数えるので、そのまま many homeworks と書いてしまいますが、英語の感覚では区切れないものです。数えたいときは a glass of water・two pieces of homework のように**容器や単位で区切ります**。\\n\\nmany と much を使い分けるのは、many が「数」、much が「量」を表す語だからです。much が肯定文でかたく響くのは、英語の習慣として much は否定文・疑問文（I don't have much time. ／ How much 〜?）で使われることが多く、肯定文では a lot of が自然だからです。many は肯定文でもふつうに使えます。\\n\\n■ 確かめのしかた\\n①名詞が**数えられるか**を先に決める。homework・information・news・advice・furniture・money・time は数えられない。\\n②数えられる→many＋複数形（many books）、数えられない→much（much water）。× many waters、× much friends。\\n③肯定文なら a lot of（I have a lot of homework.）。much は否定文・疑問文で。\\n④数をたずねる→How many＋複数形、量・値段をたずねる→How much。× How many book。\\n\\n★ ここがポイント：英語の「数えられる」は**形がはっきりして区切れる**こと。homework・information は区切れないので複数形にせず、much か a lot of。**肯定文は a lot of、否定・疑問は much**が自然。\",\"figureId\":\"xf_eigo_s230\"}],\"trapExamples\":[{\"question\":\"「たくさんの水」を英語にしなさい。\",\"wrongAnswer\":\"many waters\",\"trapExplanation\":\"「たくさんの」＝many と一対一で覚えていると、後ろの名詞が数えられるかどうかを確かめずに many を選んでしまう。さらに「たくさん」なので複数形にしなければと考えて s を付けてしまう。\",\"correctAnswer\":\"much water（肯定文では a lot of water）\",\"correctExplanation\":\"water は数えられない名詞なので many は使えず、複数形にもしない。数えられない名詞には much を使う。ただし肯定文では much はかたいので、I drank a lot of water. のように a lot of を使うのが自然である。\"},{\"question\":\"「私は宿題がたくさんある。」を英語にしなさい。\",\"wrongAnswer\":\"I have many homeworks.\",\"trapExplanation\":\"日本語では「宿題」を一つ二つと数える感覚があるため、英語でも数えられる名詞だと思いこみ、複数形にして many を付けてしまう。\",\"correctAnswer\":\"I have a lot of homework.\",\"correctExplanation\":\"homework は英語では数えられない名詞で、複数形 homeworks は存在しない。したがって many も使えない。同じように information・news・advice・furniture も数えられない名詞である。数えたいときは two pieces of homework のように単位を付ける。\"}]}",
"{\"id\":\"eigo_s231\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a lot of / lots of / plenty of ─ 両方に使える便利な表現\",\"description\":\"数えられる名詞にも数えられない名詞にも使える a lot of の用法と、be動詞の一致を確認する\",\"intro\":\"many と much の使い分けはめんどうです。ところが a lot of なら、本にも水にも使えます。a lot of books も a lot of water も正しい形です。便利な表現ですが、そのあとの be動詞が is か are かは、うしろの名詞で決まります。ここだけは油断できません。\",\"order\":731,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"a lot of は数えられる名詞にも数えられない名詞にも使える（a lot of books / a lot of water）。\",\"be動詞や動詞の形は a lot of の後ろの名詞に合わせる（There are a lot of books.）。\",\"lots of は a lot of のくだけた言い方で、意味は同じ。\",\"plenty of は「十分にたくさんの」という意味。\",\"a lot は of を付けずに副詞として使える（I study a lot.）。\"],\"sections\":[{\"heading\":\"a lot of はどちらにも使える\",\"body\":\"many は数えられる名詞、much は数えられない名詞にしか使えないが、a lot of はどちらにも使える。そのため会話でも作文でも非常に便利である。\\n\\n■ 数えられる名詞につく場合\\n例）a lot of books（たくさんの本）／a lot of students／a lot of people\\n\\n■ 数えられない名詞につく場合\\n例）a lot of water（たくさんの水）／a lot of money／a lot of time／a lot of snow\\n\\n例文）I have a lot of friends in Osaka.（大阪にたくさんの友達がいる）\\n例文）We had a lot of rain last month.（先月は雨がたくさん降った）\\n\\n■ 動詞は後ろの名詞に合わせる\\na lot of 自体は単数でも複数でもない。動詞の形を決めるのは、後ろに来る名詞である。\\n\\n例）There are a lot of books on the desk.（本＝複数なので are）\\n例）There is a lot of water in the bottle.（水＝数えられないので is）\\n例）A lot of students like this song.（students＝複数なので like）\\n例）A lot of time is needed.（time＝数えられないので is）\\n\\n「a lot of は複数っぽいから always are」と決めつけないこと。\\n\\n★ ポイント：of を落として a lot books としてはいけない。名詞が続くときは必ず a lot of の形である。\",\"figureId\":\"xf_eigo_s231\",\"mangaId\":\"eigo_s231_xm\"},{\"heading\":\"lots of・plenty of と、副詞の a lot\",\"body\":\"a lot of の仲間の表現もあわせて覚えておく。\\n\\n■ lots of\\na lot of とまったく同じ意味で、より会話的でくだけた言い方。\\n\\n例）I have lots of homework today.（今日は宿題がたくさんある）\\n例）There were lots of people in the park.\\n\\n■ plenty of\\n「十分にたくさんの」という意味で、足りているという気持ちを含む。\\n\\n例）We have plenty of time.（時間はたっぷりある）\\n例）There is plenty of food for everyone.\\n\\n■ 副詞としての a lot\\n名詞を続けずに a lot だけで使うと「たくさん、とても」という副詞になる。このときは of を付けない。\\n\\n例）He eats a lot.（彼はたくさん食べる）\\n例）Thank you a lot.（どうもありがとう）\\n例）I study a lot every day.（毎日たくさん勉強する）\\n\\nさらに比較級の前に置くと「ずっと」という強めの意味になる。\\n\\n例）This bag is a lot bigger than that one.（このかばんはあれよりずっと大きい）\\n\\n⚠ 注意：後ろに名詞があれば a lot of、名詞がなければ a lot。この一点で of の有無が決まる。\"}],\"trapExamples\":[{\"question\":\"（　）に is か are を入れなさい。There（　）a lot of books on the desk.\",\"wrongAnswer\":\"There is a lot of books on the desk.\",\"trapExplanation\":\"a lot of の a や、直前に来る lot（単数の形）に目がいって、単数だと判断して is を選んでしまう。\",\"correctAnswer\":\"There are a lot of books on the desk.\",\"correctExplanation\":\"a lot of の文で be動詞を決めるのは、a lot of ではなく後ろの名詞である。books は複数形なので are になる。反対に There is a lot of water in the bottle. は water が数えられない名詞なので is になる。\"},{\"question\":\"「彼はとてもたくさん食べる。」を英語にしなさい。\",\"wrongAnswer\":\"He eats a lot of.\",\"trapExplanation\":\"a lot of をひとまとまりの決まり文句として覚えているため、後ろに名詞がなくても of を付けたままにしてしまう。\",\"correctAnswer\":\"He eats a lot.\",\"correctExplanation\":\"of は後ろに名詞を続けるときにだけ必要な語である。名詞が続かないときは a lot だけで「たくさん」という副詞になる。He eats a lot of rice.（彼はご飯をたくさん食べる）のように名詞があるときだけ of を付ける。\"}]}",
"{\"id\":\"eigo_s232\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"a few / few と a little / little\",\"description\":\"a の有無で意味が正反対になる四つの数量表現を、度合いの図とともに整理する\",\"intro\":\"I have a few friends. は「友だちが何人かいる」、I have few friends. は「友だちがほとんどいない」。a があるかないかだけで、意味が正反対になります。話し手の気持ちまで変わってしまう、一語のこわさを体感する単元です。\",\"order\":732,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"a few＋数えられる名詞の複数形＝「少しはある」（プラスの気持ち）。\",\"few＋数えられる名詞の複数形＝「ほとんどない」（マイナスの気持ち）。\",\"a little＋数えられない名詞＝「少しはある」／little＋数えられない名詞＝「ほとんどない」。\",\"a が付けば肯定的、a が付かなければ否定的、と覚える。\",\"only a few / quite a few（かなり多くの）など、前に語がつくと意味が変わることがある。\"],\"sections\":[{\"heading\":\"四つの表現を表で整理する\",\"mangaId\":\"eigo_s232_manga\",\"body\":\"「少し」を表す表現は、後ろの名詞が数えられるかどうかと、a が付くかどうかの組み合わせで四つに分かれる。\\n\\n■ 数えられる名詞（複数形）につくもの\\na few ＝ 少しはある（2、3の）\\nfew ＝ ほとんどない\\n\\n例）I have a few friends here.（ここに友達が少しはいる）\\n例）I have few friends here.（ここにはほとんど友達がいない）\\n\\n■ 数えられない名詞につくもの\\na little ＝ 少しはある\\nlittle ＝ ほとんどない\\n\\n例）There is a little milk in the glass.（コップに牛乳が少し入っている）\\n例）There is little milk in the glass.（コップにはほとんど牛乳がない）\\n\\n■ 覚え方\\na が付いていれば「あるよ」という気持ち、a がなければ「ないんだ」という気持ちである。たった一文字で意味が正反対になるので、入試では非常によく問われる。\\n\\n例）We have a little time.（少し時間がある → まだ大丈夫）\\n例）We have little time.（ほとんど時間がない → 急がなければ）\\n\\n★ ポイント：訳すときは「a あり＝少しはある」「a なし＝ほとんどない」と機械的に置きかえてよい。\",\"figureId\":\"lf_eigoext07_232\"},{\"heading\":\"まぎらわしい使い方\",\"body\":\"■ only a few / only a little\\nonly が付くと「ほんの少ししか」という否定的な意味になり、few・little に近づく。\\n\\n例）I have only a few coins.（小銭がほんの少ししかない）\\n\\n■ quite a few\\n形は few だが、意味は「かなり多くの」という肯定的な意味になる特別な表現である。\\n\\n例）Quite a few people came to the concert.（かなり多くの人がコンサートに来た）\\n\\n■ a little の副詞用法\\na little は形容詞だけでなく、副詞として「少し」の意味でも使える。\\n\\n例）I am a little tired.（少し疲れている）\\n例）Please wait a little.（少し待ってください）\\n例）This bag is a little heavier than that one.（このかばんはあれより少し重い）\\n\\n■ 数えられない名詞につく little は「小さい」ではない\\nlittle には「小さい」という別の意味もある。〈a little＋数えられる名詞の単数〉なら「小さな」の意味である。\\n\\n例）a little dog（小さな犬）＝ a small dog\\n例）a little water（少しの水）\\n\\n後ろの名詞が数えられるかどうかで意味が変わるので、名詞を先に確かめる。\\n\\n⚠ 注意：a few water、a little books のように、可算・不可算をとりちがえる誤りが最も多い。まず名詞を見る習慣をつける。\"}],\"trapExamples\":[{\"question\":\"「コップに水が少し入っている。」を英語にしなさい。\",\"wrongAnswer\":\"There are a few water in the glass.\",\"trapExplanation\":\"「少し」＝a few と一対一で覚えているため、後ろの名詞が数えられるかどうかを確かめずに a few を選んでしまう。さらに be動詞も are にしてしまう。\",\"correctAnswer\":\"There is a little water in the glass.\",\"correctExplanation\":\"water は数えられない名詞なので a few ではなく a little を使う。数えられない名詞は単数あつかいなので be動詞も is になる。〈a few＋複数形〉〈a little＋数えられない名詞〉という組み合わせを固定して覚える。\"},{\"question\":\"次の文を日本語にしなさい。I have few friends in this town.\",\"wrongAnswer\":\"私はこの町に友達が少しいる。\",\"trapExplanation\":\"few を「少し」と訳してしまい、a few との区別を意識していない。a が一文字ないだけなので見落としやすい。\",\"correctAnswer\":\"私はこの町にはほとんど友達がいない。\",\"correctExplanation\":\"a の付かない few・little は「ほとんどない」という否定的な意味になる。「少しはいる」と言いたいなら I have a few friends in this town. としなければならない。a の有無で意味が正反対になる点が入試のねらいめである。\"}]}",
"{\"id\":\"eigo_s233\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"some と any の使い分け\",\"description\":\"肯定文の some と疑問文・否定文の any、およびすすめる場面での例外を理解する\",\"intro\":\"肯定文では some、疑問文と否定文では any——そう習います。ところが Would you like some tea? には some が使われます。人にすすめる場面では、相手が「はい」と言うと思って some を使うのです。決まりと例外を、場面ごとに理解していきます。\",\"order\":733,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"原則、some は肯定文、any は疑問文・否定文で使う。\",\"some も any も、数えられる名詞（複数形）と数えられない名詞の両方に使える。\",\"人にすすめたり頼んだりする疑問文では some を使う（Would you like some tea?）。\",\"not ~ any = no。I don't have any pens. = I have no pens.\",\"否定文の any のあとの数えられる名詞は複数形（not any books）。\"],\"sections\":[{\"heading\":\"基本の使い分け\",\"mangaId\":\"eigo_s233_manga\",\"body\":\"some と any はどちらも「いくらかの」を表すが、使う文の種類で使い分けるのが原則である。\\n\\n■ 肯定文 → some\\n例）I have some pens.（ペンを何本か持っている）\\n例）There is some milk in the bottle.（びんに牛乳が少し入っている）\\n例）Some students are playing soccer.（何人かの生徒がサッカーをしている）\\n\\n■ 疑問文 → any\\n例）Do you have any pens?（ペンを持っていますか）\\n例）Are there any apples in the box?（箱にりんごが入っていますか）\\n\\n■ 否定文 → any\\n例）I don't have any pens.（ペンを1本も持っていない）\\n例）There isn't any milk in the bottle.（びんに牛乳が全くない）\\n\\n■ どちらも可算・不可算の両方に使える\\nsome・any は many・much とちがって、後ろの名詞の種類を選ばない。\\n\\n例）some books（複数形）／some water（数えられない名詞）\\n例）any books／any water\\n\\n■ 否定文のあとの名詞は複数形\\n数えられる名詞の場合、any のあとは複数形にする。\\n\\n正）I don't have any books.\\n誤）I don't have any book.\\n\\n★ ポイント：まず文の種類（肯定・疑問・否定）を見て some か any かを決め、次に名詞の形を整える、という順で考える。\",\"figureId\":\"xf_eigo_s233\"},{\"heading\":\"すすめる疑問文の some と、not any = no\",\"body\":\"■ 疑問文でも some を使う場合\\n相手にものをすすめたり、何かを頼んだりする疑問文では、答えが Yes になることを期待しているので some を使う。\\n\\n例）Would you like some tea?（お茶はいかがですか）\\n例）Do you want some cake?（ケーキはいかが）\\n例）Can I have some water?（水をいただけますか）\\n例）Shall I bring you some coffee?\\n\\nふつうの質問（あるかどうかを本当に知りたい質問）では any を使う。\\n\\n例）Do you have any questions?（質問はありますか）\\n\\n■ not ~ any は no で言いかえられる\\n否定文の not ~ any は、no を使って一語で表せる。\\n\\n例）I don't have any brothers. ＝ I have no brothers.（兄弟がいない）\\n例）There aren't any students in the room. ＝ There are no students in the room.\\n\\nno を使うときは don't・isn't などの否定語を重ねてはいけない。\\n\\n正）I have no money.\\n誤）I don't have no money.\\n\\n■ 肯定文の any\\n肯定文で any を使うと「どんな〜でも」という意味になる。\\n\\n例）Any student can join the club.（どの生徒でもそのクラブに入れる）\\n例）You can take any book you like.（好きな本をどれでも取っていいよ）\\n\\n⚠ 注意：Would you like some ~? は入試頻出。「疑問文だから any」と機械的に選ぶと誤る。\"}],\"trapExamples\":[{\"question\":\"（　）に some か any を入れなさい。Are there（　）pens on the desk?\",\"wrongAnswer\":\"Are there some pens on the desk?\",\"trapExplanation\":\"日本語では「机の上にペンが何本かありますか」と「何本か」がそのまま出てくるため、肯定文で覚えた some をそのまま使ってしまう。\",\"correctAnswer\":\"Are there any pens on the desk?\",\"correctExplanation\":\"あるかどうかを本当にたずねる疑問文では any を使う。some を使うのは、Would you like some tea? のように相手にすすめたり頼んだりする疑問文だけである。この文はただの質問なので any が正しい。\"},{\"question\":\"「私は本を1冊も持っていない。」を英語にしなさい。\",\"wrongAnswer\":\"I don't have any book.\",\"trapExplanation\":\"「1冊も」という日本語から単数のイメージが働き、any のあとを単数形にしてしまう。some/any の選択は正しくても名詞の形でまちがえる典型例。\",\"correctAnswer\":\"I don't have any books.（= I have no books.）\",\"correctExplanation\":\"否定文の any のあとに来る数えられる名詞は複数形にする。「1冊も持っていない」は「本というものを持っていない」という意味なので books となる。no を使って I have no books. と書きかえることもできるが、そのときは don't を重ねない。\"}]}",
"{\"id\":\"eigo_s234\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"all / most / both / every / each ─ 数量を表すその他の語\",\"description\":\"全体や一部を表す語のあとの名詞の形と、動詞の単数・複数の一致を身につける\",\"intro\":\"every と all は、どちらも「全部」を表します。ところが Every student is here. の student は単数、All the students are here. の students は複数です。同じ意味なのに形がちがう。ものの数え方に対する英語のとらえ方が表れる部分です。\",\"order\":734,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"every＋単数名詞＋単数動詞（Every student is here.）。\",\"each＋単数名詞＋単数動詞（Each boy has a ball.）。\",\"all＋複数名詞＋複数動詞（All the students are here.）。\",\"both＋複数名詞＝「両方とも」で複数あつかい（Both books are new.）。\",\"most of ~ / all of ~ / both of ~ のように of を使うときは the や my が必要（most of the students）。\"],\"sections\":[{\"heading\":\"every・each は単数あつかい\",\"body\":\"「すべての」「それぞれの」を表す every と each は、意味は複数のようでも文法上は単数としてあつかう。ここが入試の最大のねらいめである。\\n\\n■ every＋単数名詞\\n例）Every student is here.（生徒はみんなここにいる）\\n例）Every boy likes soccer.（どの男の子もサッカーが好きだ）\\n例）Every house has a garden.\\n\\n名詞は単数形、動詞も三人称単数の形（is・likes・has）になる。\\n\\n■ each＋単数名詞\\n例）Each student has a textbook.（それぞれの生徒が教科書を持っている）\\n例）Each of the boys was busy.（少年たちのそれぞれが忙しかった）\\n\\n■ everyone・everybody も単数\\n例）Everyone is happy.（みんな幸せだ）\\n例）Everybody knows him.（みんな彼を知っている）\\n\\n日本語の「みんな」は複数の感じがするので are・know としがちだが、英語では単数あつかいである。\\n\\n■ every は時間の表現にも使う\\n例）every day（毎日）／every Sunday（毎週日曜日）／every three days（3日ごとに）\\n\\n★ ポイント：every・each・everyone・everybody を見たら、動詞は必ず単数の形と反射的に判断する。\",\"figureId\":\"xf_eigo_s234\",\"mangaId\":\"eigo_s234_xm\"},{\"heading\":\"all・both・most は複数あつかい\",\"body\":\"■ all（すべての）\\n数えられる名詞なら複数形＋複数動詞、数えられない名詞なら単数動詞になる。\\n\\n例）All the students are here.（生徒は全員ここにいる）\\n例）All my friends like music.\\n例）All the water was gone.（水はすべてなくなっていた）\\n\\n■ both（両方の）\\n必ず2つ・2人について使い、複数あつかいである。\\n\\n例）Both books are new.（両方の本とも新しい）\\n例）Both of them are my friends.（彼らは2人とも私の友達だ）\\n例）I like both.（両方とも好きだ）\\n\\n「両方とも〜ない」は not both ではなく neither を使うが、中学入試では both の肯定の形をおさえれば十分である。\\n\\n■ most（ほとんどの）\\n例）Most students like this song.（ほとんどの生徒がこの歌を好きだ）\\n例）Most of the students in my class play sports.\\n\\n■ of を使うときの注意\\nall of・both of・most of のように of を続ける場合、そのあとの名詞には the・my・these などが必要である。\\n\\n正）most of the students／both of my friends／all of these books\\n誤）most of students／both of friends\\n\\nof を使わないときは the などは不要である。\\n\\n正）most students（ほとんどの生徒）\\n\\n⚠ 注意：Every student are here. のように every に複数動詞をつける誤りが最頻出。every は単数である。\"}],\"trapExamples\":[{\"question\":\"（　）に is か are を入れなさい。Every student in this class（　）kind.\",\"wrongAnswer\":\"Every student in this class are kind.\",\"trapExplanation\":\"「すべての生徒」という日本語の意味が複数なので are を選んでしまう。さらに直前の this class にも引っぱられる。\",\"correctAnswer\":\"Every student in this class is kind.\",\"correctExplanation\":\"every のあとの名詞は単数形で、動詞も単数の形になる。意味は複数でも、文法上は一人ひとりを取り上げる言い方なので単数あつかいである。同じく Everyone is happy.、Each boy has a ball. も単数の動詞を使う。\"},{\"question\":\"「私はその本を両方とも読んだ。」を英語にしなさい。\",\"wrongAnswer\":\"I read both book.\",\"trapExplanation\":\"both を「両方の」という形容詞として名詞の前に置くところまでは正しいが、日本語に複数を表すしるしがないため、名詞を単数のままにしてしまう。\",\"correctAnswer\":\"I read both books.（= I read both of the books.）\",\"correctExplanation\":\"both は必ず2つのものについて使うので、後ろの名詞は複数形にする。of を使って both of the books と書くこともできるが、そのときは the や my が必要である。both of books は誤りである。\"}]}",
"{\"id\":\"eigo_s235\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"副詞のはたらき ─ 何を説明する語か\",\"description\":\"副詞が動詞・形容詞・他の副詞・文全体を説明することを、形容詞との対比で理解する\",\"intro\":\"He is a slow walker. と He walks slowly. — 意味はほぼ同じですが、slow は名詞を、slowly は動詞を説明しています。説明する相手がちがうと、語の形も変わるのです。副詞が何を説明する語なのかを、形容詞と比べながらつかみます。\",\"order\":735,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"形容詞は名詞を説明する語、副詞は名詞以外（動詞・形容詞・副詞・文全体）を説明する語。\",\"動詞を説明する例：He runs fast.／形容詞を説明する例：It is very hot.\",\"他の副詞を説明する例：He runs very fast.\",\"good は形容詞、well は副詞。He is a good player. = He plays well.\",\"fast・hard・early は形容詞と副詞が同じ形。fastly という語は存在しない。\"],\"sections\":[{\"heading\":\"副詞が説明するもの\",\"body\":\"形容詞が名詞を説明する語であるのに対し、副詞は名詞以外のものを説明する語である。何を説明しているかで四つに分けられる。\\n\\n■ ①動詞を説明する（どのように・いつ・どこで）\\n例）He runs fast.（彼は速く走る）\\n例）She sings beautifully.（彼女は美しく歌う）\\n例）I got up early today.（今日は早く起きた）\\n\\n■ ②形容詞を説明する（どのくらい）\\n例）It is very hot today.（今日はとても暑い）\\n例）This question is too difficult.（この問題は難しすぎる）\\n例）He is so kind.（彼はとても親切だ）\\n\\n■ ③他の副詞を説明する\\n例）He runs very fast.（彼はとても速く走る）\\n例）She speaks English quite well.（彼女は英語をかなり上手に話す）\\n\\n■ ④文全体を説明する\\n例）Luckily, we won the game.（幸運にも私たちは試合に勝った）\\n例）Fortunately, it didn't rain.\\n\\n■ 形容詞と副詞の対比\\n同じ内容を形容詞で言うか副詞で言うかで、文の形が変わる。\\n\\n形容詞）He is a good soccer player.（彼はよいサッカー選手だ）\\n副詞）He plays soccer well.（彼は上手にサッカーをする）\\n\\n形容詞）She is a fast runner.\\n副詞）She runs fast.\\n\\n★ ポイント：名詞を説明しているなら形容詞、動詞を説明しているなら副詞。文の中で何を説明しているかを確かめてから品詞を決める。\",\"figureId\":\"xf_eigo_s235\"},{\"heading\":\"good と well、fast と fastly\",\"mangaId\":\"eigo_s235_manga\",\"body\":\"■ good は形容詞、well は副詞\\n「よい・上手な」は good、「よく・上手に」は well である。日本語では区別があいまいなので誤りやすい。\\n\\n正）He is a good singer.（形容詞。名詞 singer を説明）\\n正）He sings well.（副詞。動詞 sings を説明）\\n誤）He sings good.\\n\\nwell には「健康な」という形容詞の意味もある。\\n\\n例）I am well.（元気です）\\n例）Get well soon.（早くよくなってね）\\n\\n■ fastly という語はない\\nfast は形容詞（速い）と副詞（速く）の両方で同じ形を使う。-ly を付けた fastly という語は英語に存在しない。\\n\\n正）He is a fast runner.（形容詞）\\n正）He runs fast.（副詞）\\n誤）He runs fastly.\\n\\n同じように形容詞と副詞が同じ形の語には、hard（熱心な・熱心に）、early（早い・早く）、late（遅い・遅く）、high（高い・高く）、long（長い・長く）がある。\\n\\n例）This is hard work.（形容詞）／He works hard.（副詞）\\n例）I took an early train.（形容詞）／I got up early.（副詞）\\n\\n■ very と much のちがい\\nvery は形容詞・副詞の原級を強める。much は動詞や比較級を強める。\\n\\n例）very tall（とても背が高い）／I like it very much.（とても好きだ）\\n\\n⚠ 注意：He sings good. と He runs fastly. は入試の定番の誤文。どちらも副詞にすべきところで形をまちがえている。\"}],\"trapExamples\":[{\"question\":\"「彼は上手に歌う。」を英語にしなさい。\",\"wrongAnswer\":\"He sings good.\",\"trapExplanation\":\"日本語の「上手に」が「上手な」と同じ語感なので、まず思い浮かぶ good をそのまま使ってしまう。good と well の品詞のちがいを意識していない。\",\"correctAnswer\":\"He sings well.\",\"correctExplanation\":\"good は名詞を説明する形容詞、well は動詞を説明する副詞である。ここでは動詞 sings を説明しているので well を使う。名詞を使って言いかえるなら He is a good singer. となる。\"},{\"question\":\"「私はとても速く走ることができる。」を英語にしなさい。\",\"wrongAnswer\":\"I can run very fastly.\",\"trapExplanation\":\"「副詞は形容詞に -ly を付けて作る」という規則を知っているために、fast にも機械的に -ly を付けてしまう。しかし fastly という語は存在しない。\",\"correctAnswer\":\"I can run very fast.\",\"correctExplanation\":\"fast は形容詞も副詞も同じ形で使う語である。hard・early・late・high・long も同じ仲間で、-ly を付けない。ただし hard に -ly を付けた hardly は別の語（ほとんど〜ない）なので、意味がまったく変わってしまう。\"}]}",
"{\"id\":\"eigo_s236\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞から副詞をつくる ─ -ly のつけ方と意味が変わる語\",\"description\":\"-ly のつづりの規則と、hard / hardly のように意味が変わる語の区別を身につける\",\"intro\":\"hard に -ly を付けると hardly ですが、意味は「一生けんめいに」ではなく「ほとんど〜ない」です。He hardly works. は「彼はほとんど働かない」。-ly を付ければ意味はそのままで副詞になる、という思いこみが通じない語があります。まとめて確かめておきましょう。\",\"order\":736,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"多くの副詞は〈形容詞＋-ly〉でつくる（slow → slowly、careful → carefully）。\",\"〈子音字＋y〉で終わる語は y を i に変えて -ly（easy → easily、happy → happily）。\",\"-le で終わる語は e を取って -y（gentle → gently、simple → simply）。true → truly も注意。\",\"hard（熱心に）と hardly（ほとんど〜ない）は意味がまったくちがう。late/lately、near/nearly も同様。\",\"friendly・lovely・lonely は -ly で終わるが形容詞である。\"],\"sections\":[{\"heading\":\"-ly のつけ方\",\"body\":\"多くの副詞は形容詞に -ly を付けて作る。つづりの変化には四つの型がある。\\n\\n■ ①そのまま -ly を付ける（いちばん多い）\\nslow → slowly（ゆっくり）／quick → quickly（すばやく）／careful → carefully（注意深く）／quiet → quietly（静かに）／loud → loudly（大声で）／sudden → suddenly（突然）／usual → usually（ふつう）／kind → kindly（親切に）\\n\\n■ ②〈子音字＋y〉→ y を i に変えて -ly\\neasy → easily（簡単に）／happy → happily（幸せに）／angry → angrily（怒って）／busy → busily／heavy → heavily（激しく）／lucky → luckily（幸運にも）\\n\\n例）It rained heavily last night.（昨夜は激しく雨が降った）\\n\\n■ ③-le で終わる語 → e を取って -y\\ngentle → gently（やさしく）／simple → simply（単純に）／possible → possibly\\n\\n■ ④特別な形\\ntrue → truly（e を取る）／good → well（形が全く変わる）／full → fully（l が二つ）\\n\\n■ 形容詞と副詞が同じ形の語\\nfast, hard, early, late, high, long, near, straight は -ly を付けずにそのまま副詞として使う。\\n\\n★ ポイント：easily・happily の i への変化は、比較級 easier・happier と同じ規則である。まとめて覚えると効率がよい。\",\"figureId\":\"xf_eigo_s236\"},{\"heading\":\"-ly が付くと意味が変わる語\",\"body\":\"-ly を付けると意味がまったく変わってしまう語がある。入試で頻出なので必ず区別する。\\n\\n■ hard と hardly\\nhard ＝ 熱心に、激しく／hardly ＝ ほとんど〜ない\\n\\n例）He studies hard.（彼は熱心に勉強する）\\n例）He hardly studies.（彼はほとんど勉強しない）\\n\\nhardly はそれ自体が否定の意味を持つので、not を重ねてはいけない。\\n\\n正）I can hardly see it.（ほとんど見えない）\\n誤）I can't hardly see it.\\n\\n■ late と lately\\nlate ＝ 遅く／lately ＝ 最近\\n\\n例）I got up late this morning.（今朝は遅く起きた）\\n例）I haven't seen him lately.（最近彼に会っていない）\\n\\n■ near と nearly\\nnear ＝ 近くに／nearly ＝ ほとんど、およそ\\n\\n例）He lives near.（彼は近くに住んでいる）\\n例）It is nearly ten o'clock.（もうすぐ10時だ）\\n\\n■ high と highly\\nhigh ＝ 高く（高さ）／highly ＝ 大いに、非常に\\n\\n例）The bird flew high.（鳥は高く飛んだ）\\n\\n■ -ly で終わるのに形容詞の語\\nfriendly（親しみのある）、lovely（すてきな）、lonely（ひとりぼっちの）、ugly（みにくい）は -ly で終わるが形容詞である。\\n\\n例）He is a friendly boy.（○）／He spoke to me friendly.（×）\\n\\n⚠ 注意：「一生けんめい勉強する」を He studies hardly. と書くと、意味が正反対の「ほとんど勉強しない」になってしまう。\",\"mangaId\":\"eigo_s236_xm\"}],\"trapExamples\":[{\"question\":\"「彼は一生けんめい勉強する。」を英語にしなさい。\",\"wrongAnswer\":\"He studies hardly.\",\"trapExplanation\":\"「副詞は -ly を付ける」という規則を機械的にあてはめ、hard に -ly を付けてしまう。しかし hardly は「ほとんど〜ない」という別の語で、意味が正反対になる。\",\"correctAnswer\":\"He studies hard.\",\"correctExplanation\":\"hard は形容詞（熱心な・かたい）と副詞（熱心に）が同じ形の語で、-ly を付ける必要はない。hardly は「ほとんど〜ない」という否定の意味の副詞である。late/lately、near/nearly も同じように意味が変わる組み合わせである。\"},{\"question\":\"easy を副詞に変えなさい。\",\"wrongAnswer\":\"easyly\",\"trapExplanation\":\"「形容詞＋-ly」という規則をそのままあてはめ、語尾の y を残したまま -ly を付けてしまう。\",\"correctAnswer\":\"easily\",\"correctExplanation\":\"〈子音字＋y〉で終わる語は、y を i に変えてから -ly を付ける。happy → happily、angry → angrily、lucky → luckily も同じ規則である。これは比較級の easy → easier、happy → happier と同じ変化なので、あわせて覚えるとよい。\"}]}",
"{\"id\":\"eigo_s237\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"副詞の位置と語順 ─ 様態・場所・時の順\",\"description\":\"目的語と副詞の位置関係、および「どのように→どこで→いつ」という並び順を身につける\",\"intro\":\"I like very much English. と書きたくなりますが、正しくは I like English very much. です。英語では動詞と目的語の間に副詞を割りこませません。さらに副詞が重なるときは「どのように→どこで→いつ」の順。位置には決まりがあるのです。\",\"order\":737,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"動詞に目的語があるときは〈動詞＋目的語＋副詞〉（He speaks English well.）。\",\"副詞を二つ以上ならべるときは〈様態→場所→時〉の順。\",\"時を表す語句は文頭に出してもよい（Yesterday I played tennis.）。\",\"場所より時があとに来る（in the park yesterday）。日本語と逆になりやすい。\",\"very・too・so などの程度の副詞は、説明する語のすぐ前に置く。\"],\"sections\":[{\"heading\":\"目的語と副詞の位置\",\"body\":\"動詞を説明する副詞は、原則として動詞のあとに置く。ただし動詞に目的語があるときは、目的語のあとに置く。\\n\\n正）He speaks English well.（彼は英語を上手に話す）\\n誤）He speaks well English.\\n\\n正）She plays the piano beautifully.\\n誤）She plays beautifully the piano.\\n\\n英語では動詞と目的語のつながりが強く、その間に副詞を割りこませない。日本語では「上手に英語を話す」と副詞が前に来るので、そのまま英語にすると誤ってしまう。\\n\\n■ 目的語がないときは動詞のすぐあと\\n例）He runs fast.／She sings well.／They arrived late.\\n\\n■ 程度を表す副詞は説明する語のすぐ前\\nvery・too・so・quite・really などは、説明する形容詞や副詞のすぐ前に置く。\\n\\n例）It is very hot.（very が hot を説明）\\n例）He runs very fast.（very が fast を説明）\\n例）This box is too heavy.（重すぎる）\\n\\n■ 頻度の副詞は別の規則\\nalways・usually などの頻度の副詞は位置の規則がちがう。これは次の課で学ぶ。\\n\\n★ ポイント：〈動詞＋目的語〉のかたまりを壊さない。副詞はそのかたまりの外側に置く。\",\"figureId\":\"lf_eigoext07_237\"},{\"heading\":\"様態・場所・時の順番\",\"mangaId\":\"eigo_s237_manga\",\"body\":\"副詞（副詞句）を二つ以上ならべるときは、〈様態（どのように）→場所（どこで）→時（いつ）〉の順にする。\\n\\n例）I played tennis hard in the park yesterday.\\n　　　　　　　　　　様態　　　　場所　　　　時\\n（私は昨日公園で一生けんめいテニスをした）\\n\\n例）He studied quietly in his room last night.\\n例）She sang beautifully at the concert yesterday.\\n\\n■ 場所より時があと\\nとくにまちがえやすいのが場所と時の順である。英語では場所が先、時があとになる。\\n\\n正）I played soccer in the park yesterday.\\n誤）I played soccer yesterday in the park.\\n\\n日本語では「昨日公園で」と時を先に言うことが多いので、そのまま英語にすると誤る。\\n\\n■ 時を表す語句は文頭に出せる\\n時を表す語句だけは、強調のため文頭に置くことができる。このときはコンマを付けてもよい。\\n\\n例）Yesterday I played soccer in the park.\\n例）Last summer, we went to Okinawa.\\n\\n場所を表す語句を文頭に出すことは、中学入試の範囲ではほとんどない。\\n\\n■ 大きい場所・小さい場所の順\\n場所を二つ重ねるときは、小さい場所から大きい場所の順に置く。\\n\\n例）He lives in Kita-ku in Osaka.（大阪の北区に住んでいる）\\n\\n⚠ 注意：語順整序（並べかえ）問題では、まず動詞と目的語を作り、そのあとに様態・場所・時を順に付け足すと正解しやすい。\"}],\"trapExamples\":[{\"question\":\"「彼は英語を上手に話す。」を英語にしなさい。\",\"wrongAnswer\":\"He speaks well English.\",\"trapExplanation\":\"日本語の「上手に英語を話す」という語順のまま英語にしてしまう。副詞は動詞の直後という覚え方だけをしていると、目的語があるときに誤る。\",\"correctAnswer\":\"He speaks English well.\",\"correctExplanation\":\"英語では動詞と目的語の間に副詞を入れない。〈動詞＋目的語＋副詞〉の順になるので He speaks English well. が正しい。同じく She plays the piano well.、I like this song very much. も目的語のあとに副詞が来る。\"},{\"question\":\"「私は昨日公園でテニスをした。」を英語にしなさい。\",\"wrongAnswer\":\"I played tennis yesterday in the park.\",\"trapExplanation\":\"日本語が「昨日公園で」と時を先に言う語順なので、そのまま英語に置きかえてしまう。意味は通じるが、英語としては不自然な語順になる。\",\"correctAnswer\":\"I played tennis in the park yesterday.\",\"correctExplanation\":\"英語では〈様態→場所→時〉の順にならべる。場所が先、時があとである。時を強調したいときだけ Yesterday I played tennis in the park. のように文頭に出すことができる。\"}]}",
"{\"id\":\"eigo_s238\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"頻度の副詞①：always から never までの度合い\",\"description\":\"always・usually・often・sometimes・never の意味の強さを、度合いの図で順序づけて覚える\",\"intro\":\"sometimes と often と usually を、強い順にならべられますか。日本語の「ときどき」「よく」「たいてい」と一対一で対応させようとすると、どこかでずれます。英語の頻度の副詞は、目盛りの上にならべて位置関係で覚えるほうが確実です。\",\"order\":738,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"度合いの順は always（いつも）＞ usually（たいてい）＞ often（よく）＞ sometimes（ときどき）＞ never（決して〜ない）。\",\"seldom・rarely は「めったに〜ない」で、never の少し手前。\",\"never・seldom・rarely はそれ自体が否定の意味を持つので not を重ねない。\",\"never を使う文の動詞は肯定の形のまま（He never gets angry.）。三単現も忘れない。\",\"How often ~? は頻度をたずねる疑問文。\"],\"sections\":[{\"heading\":\"頻度の副詞の順序\",\"body\":\"どれくらいの回数そうするかを表す副詞を頻度の副詞という。中学入試で必要なのは次の語である。度合いの強い順にならべる。\\n\\nalways（いつも・100パーセント）\\nusually（たいてい・ふつう）\\noften（よく・しばしば）\\nsometimes（ときどき）\\nseldom・rarely（めったに〜ない）\\nnever（決して〜ない・0パーセント）\\n\\n例）I always get up at six.（私はいつも6時に起きる）\\n例）She usually walks to school.（彼女はたいてい歩いて学校へ行く）\\n例）We often play soccer after school.（私たちは放課後よくサッカーをする）\\n例）He sometimes comes late.（彼はときどき遅れて来る）\\n例）I never eat natto.（私は決して納豆を食べない）\\n\\n■ 意味の取りちがえに注意\\nusually を「いつも」、often を「ときどき」と訳してしまう誤りが多い。usually は「たいてい・ふつうは」、often は「よく・しばしば」で、sometimes（ときどき）より回数が多い。\\n\\n■ 選択問題での考え方\\n「毎朝かならず」なら always、「週に4、5回」なら usually か often、「月に1、2回」なら sometimes、「一度もない」なら never である。\\n\\n★ ポイント：右の図で always から never までの度合いを目で見て覚えると、選択問題で迷わなくなる。\",\"figureId\":\"lf_eigoext07_238\"},{\"heading\":\"never・seldom は否定語\",\"body\":\"never・seldom・rarely は、それ自体に「〜ない」という否定の意味が含まれている。したがって not や don't を重ねてはいけない。\\n\\n正）He never gets angry.（彼は決して怒らない）\\n誤）He doesn't never get angry.\\n誤）He never doesn't get angry.\\n\\n正）She rarely watches TV.（彼女はめったにテレビを見ない）\\n誤）She doesn't rarely watch TV.\\n\\n■ 動詞の形に注意\\nnever を使う文は形の上では肯定文なので、三人称単数現在の s を付ける必要がある。\\n\\n正）He never eats breakfast.\\n誤）He never eat breakfast.\\n\\n否定文だと思って動詞を原形にしてしまう誤りが非常に多い。\\n\\n■ 過去の文でも同じ\\n例）I never went there.（私は一度もそこへ行かなかった）\\n例）He never told me the truth.\\n\\n■ How often ~? で頻度をたずねる\\n例）How often do you play tennis?（どれくらいの頻度でテニスをしますか）\\n　　— Twice a week.（週に2回です）\\n例）How often does he go to the library?\\n　　— About once a month.（月に1回くらいです）\\n\\n⚠ 注意：never は not よりも強い否定である。「〜ない」を表したいだけなら don't を使い、「一度も〜ない」と強く言いたいときに never を使う。\",\"mangaId\":\"eigo_s238_xm\"}],\"trapExamples\":[{\"question\":\"「彼は決して怒らない。」を英語にしなさい。\",\"wrongAnswer\":\"He doesn't never get angry.\",\"trapExplanation\":\"日本語の「怒らない」に引かれて否定文を作り、そのうえで「決して」を表す never を足してしまう。否定の語を二重に使っていることに気づかない。\",\"correctAnswer\":\"He never gets angry.\",\"correctExplanation\":\"never は「決して〜ない」という否定の意味をすでに含んでいるので、doesn't と重ねてはいけない。また文の形は肯定文なので、三人称単数の s を付けて gets となる。seldom・rarely も同じく否定語なので not を重ねない。\"},{\"question\":\"次の文を日本語にしなさい。She usually walks to school.\",\"wrongAnswer\":\"彼女はときどき歩いて学校へ行く。\",\"trapExplanation\":\"usually と sometimes を混同している。usually を「ときどき」、often を「たまに」のように、頻度の副詞の度合いをあいまいに覚えていると訳がずれる。\",\"correctAnswer\":\"彼女はたいてい歩いて学校へ行く。\",\"correctExplanation\":\"usually は「たいてい・ふつうは」で、always に次いで回数が多い。「ときどき」は sometimes である。度合いの順は always ＞ usually ＞ often ＞ sometimes ＞ never なので、この順を図で覚えておくと訳も選択問題も正確になる。\"}]}",
"{\"id\":\"eigo_s239\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"頻度の副詞②：文のどこに置くか\",\"description\":\"be動詞のあと・一般動詞の前・助動詞のあと、という頻度の副詞の位置の規則を身につける\",\"intro\":\"always を文のどこに置くか。I always am busy. ではなく I am always busy. が正しい形です。be動詞なら後ろ、一般動詞なら前。この一点だけで正誤が分かれる問題が、入試ではくり返し出ます。理由まで含めて理解しておきましょう。\",\"order\":739,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"be動詞があるときは be動詞のあと（He is always busy.）。\",\"一般動詞だけのときは動詞の前（He always goes to school by bike.）。\",\"助動詞（can・will・must）があるときは助動詞のあと（I will always help you.）。\",\"sometimes・usually・often は文頭・文末にも置けるが、always・never は原則この位置。\",\"not との順は not の前後で意味が変わるので、中学入試では always は not のあとに置く形だけ覚える。\"],\"sections\":[{\"heading\":\"三つの位置の規則\",\"body\":\"頻度の副詞は、ほかの副詞と位置の規則がちがう。文末ではなく文の途中に入りこむのが特徴である。\\n\\n■ ①be動詞があるとき → be動詞のあと\\n例）He is always busy.（彼はいつも忙しい）\\n例）She is usually kind.（彼女はたいてい親切だ）\\n例）I am never late for school.（私は決して学校に遅れない）\\n\\n■ ②一般動詞だけのとき → 一般動詞の前\\n例）He always goes to school by bike.（彼はいつも自転車で学校へ行く）\\n例）We often play soccer.（私たちはよくサッカーをする）\\n例）She never eats meat.（彼女は決して肉を食べない）\\n\\n■ ③助動詞があるとき → 助動詞のあと\\n例）I will always help you.（いつでも助けます）\\n例）You can always call me.（いつでも電話していいよ）\\n例）He must always be careful.\\n\\nbe動詞と助動詞のときは「あと」、一般動詞のときは「前」と覚える。be動詞と助動詞は仲間なので、同じあつかいになると考えるとよい。\\n\\n■ 否定文・疑問文でも位置は同じ\\n例）He doesn't always get up early.（彼はいつも早起きするとはかぎらない）\\n例）Do you often go to the library?（よく図書館へ行きますか）\\n\\n★ ポイント：まず文の中に be動詞か助動詞があるかを探す。あればそのあと、なければ一般動詞の前に置く。\",\"figureId\":\"lf_eigoext07_239\",\"mangaId\":\"eigo_s239_xm\"},{\"heading\":\"文頭・文末に置ける語\",\"body\":\"頻度の副詞のうち sometimes・usually・often・generally は、文頭や文末に置くこともできる。意味は変わらないが、文頭に置くと強調される。\\n\\n例）Sometimes I walk to school.（＝ I sometimes walk to school.）\\n例）I go to the library often.（＝ I often go to the library.）\\n例）Usually we have lunch at noon.\\n\\n■ always・never は文の途中だけ\\nalways と never は原則として文頭・文末には置かない。\\n\\n正）He is always busy.\\n誤）Always he is busy.\\n誤）He is busy always.\\n\\n■ 複数の要素があるときの順\\nbe動詞と一般動詞の両方があるように見える文（進行形・受動態）では、be動詞のあとに置く。\\n\\n例）He is always studying.（彼はいつも勉強している）\\n例）This shop is always crowded.（この店はいつも混んでいる）\\n\\n■ 完了形では have のあと\\n例）I have never been to Kyoto.（京都へ行ったことがない）\\n例）She has always wanted a dog.\\n\\n■ 頻度をたずねる文への答え\\n例）How often do you go swimming?\\n　　— I usually go swimming twice a week.\\n\\n⚠ 注意：He always is busy. は誤り。be動詞のあとが正しい位置である。逆に He goes always to school. も誤りで、一般動詞の前に置く。\"}],\"trapExamples\":[{\"question\":\"「彼はいつも忙しい。」を英語にしなさい。\",\"wrongAnswer\":\"He always is busy.\",\"trapExplanation\":\"「頻度の副詞は動詞の前」という規則だけを覚えていると、be動詞にもそのままあてはめて動詞の前に置いてしまう。\",\"correctAnswer\":\"He is always busy.\",\"correctExplanation\":\"be動詞があるときは be動詞のあとに置く。一般動詞の前に置くのは、be動詞も助動詞もない文のときだけである。助動詞がある文も同じで、I will always help you. のように助動詞のあとに置く。\"},{\"question\":\"「彼はいつも自転車で学校へ行く。」を英語にしなさい。\",\"wrongAnswer\":\"He goes always to school by bike.\",\"trapExplanation\":\"ふつうの副詞と同じように「動詞のあとに置く」と考えてしまう。fast や well は動詞のあとでよいが、頻度の副詞は規則がちがう。\",\"correctAnswer\":\"He always goes to school by bike.\",\"correctExplanation\":\"一般動詞だけの文では、頻度の副詞は動詞の前に置く。be動詞や助動詞があるときだけ、そのあとに置く。fast・well などの様態の副詞とは位置の規則が別であることをはっきり区別する。\"}]}",
"{\"id\":\"eigo_s240\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"回数の表し方 ─ once / twice / three times a week\",\"description\":\"具体的な回数を表す言い方と、every day 型の表現の書き方を正確に身につける\",\"intro\":\"「週に3回」は three times a week です。ここで「1回」は one time ではなく once、「2回」は twice と、特別な語を使います。3回からは three times と規則的になるのに、はじめの二つだけが例外。よく使う語ほど古い形が残っているのです。\",\"order\":740,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"1回は once、2回は twice、3回以上は three times のように times を使う。\",\"「週に3回」は three times a week。a は「〜につき」の意味。\",\"every day（毎日）は2語。everyday は「日常の」という形容詞で意味がちがう。\",\"on Sundays（毎週日曜日に）のように複数形で習慣を表すことがある。\",\"How often ~? への答えは Twice a week. のように回数だけでよい。\"],\"sections\":[{\"heading\":\"回数の言い方\",\"body\":\"頻度の副詞よりもはっきり回数を示したいときは、次の言い方を使う。\\n\\n■ 回数の基本\\nonce（1回）／twice（2回）／three times（3回）／four times（4回）／many times（何度も）\\n\\n1回と2回だけは特別な語を使い、3回以上は〈数＋times〉である。two times とは言わずに twice を使うのが普通である。\\n\\n例）I have been to Kyoto once.（京都に1度行ったことがある）\\n例）I read the book twice.（その本を2回読んだ）\\n例）He called me three times yesterday.\\n\\n■ 「〜につき何回」\\n〈回数＋a＋期間〉で「〜につき…回」を表す。この a は「〜につき」という意味である。\\n\\n例）three times a week（週に3回）\\n例）once a month（月に1回）\\n例）twice a year（年に2回）\\n例）five times a day（1日に5回）\\n\\n例文）I play tennis twice a week.（私は週に2回テニスをする）\\n例文）We have a test once a month.\\n\\n正）three times a week\\n誤）three times in a week\\n誤）three time a week（times の s を落とさない）\\n\\n★ ポイント：a を per に置きかえた three times per week も同じ意味だが、中学入試では a を使う形で覚えておけばよい。\",\"figureId\":\"xf_eigo_s240\"},{\"heading\":\"every day 型の表現\",\"body\":\"■ every＋時を表す語\\nevery day（毎日）／every week（毎週）／every month（毎月）／every year（毎年）／every Sunday（毎週日曜日）／every morning（毎朝）\\n\\n例）I study English every day.（毎日英語を勉強する）\\n例）We visit our grandmother every summer.\\n\\n■ every day と everyday のちがい\\n2語の every day は「毎日」という副詞、1語の everyday は「日常の」という形容詞である。まったく別の語なので書きまちがえてはいけない。\\n\\n正）I study English every day.（毎日勉強する）\\n正）This is an everyday event.（これは日常のできごとだ）\\n誤）I study English everyday.\\n\\n■ every＋数＋複数名詞\\n「〜おきに」を表す。\\n\\n例）every three days（3日ごとに）\\n例）every two weeks（2週間ごとに）\\n\\n■ on Sundays（複数形）\\n曜日を複数形にすると「毎週その曜日に」という習慣の意味になる。\\n\\n例）I play soccer on Sundays.（日曜日にはサッカーをする）\\n例）The shop is closed on Mondays.\\n\\n■ 位置\\nこれらの語句は原則として文末に置く。強調するときだけ文頭に出す。\\n\\n例）I go to the gym twice a week.\\n例）Every morning, I walk my dog.\\n\\n⚠ 注意：every day を1語で書く誤りは減点対象になりやすい。「毎日」は必ず2語である。\",\"mangaId\":\"eigo_s240_xm\"}],\"trapExamples\":[{\"question\":\"「私は週に3回サッカーをする。」を英語にしなさい。\",\"wrongAnswer\":\"I play soccer three times in a week.\",\"trapExplanation\":\"日本語の「週に」の「に」を前置詞 in だと考えて、in a week としてしまう。あるいは times の s を落として three time としてしまう。\",\"correctAnswer\":\"I play soccer three times a week.\",\"correctExplanation\":\"「〜につき何回」は〈回数＋a＋期間〉で表し、前置詞は使わない。この a は「〜につき」という意味である。once a month（月に1回）、twice a year（年に2回）も同じ形で、3回以上のときは times と複数形にする。\"},{\"question\":\"「私は毎日英語を勉強する。」を英語にしなさい。\",\"wrongAnswer\":\"I study English everyday.\",\"trapExplanation\":\"発音が同じで見た目も似ているため、1語の everyday と2語の every day を区別せずに書いてしまう。辞書に everyday という語が載っていることも混乱のもとになる。\",\"correctAnswer\":\"I study English every day.\",\"correctExplanation\":\"「毎日」という意味の副詞は2語の every day である。1語の everyday は「日常の」という形容詞で、an everyday event（日常のできごと）のように名詞の前で使う。品詞も意味もちがう別の語である。\"}]}",
"{\"id\":\"eigo_s241\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較の三つの形 ─ 原級・比較級・最上級\",\"description\":\"比較の基本となる三つの形と、それぞれを使う文の形を図で確認する\",\"intro\":\"Tom is tall. / Tom is taller than Ken. / Tom is the tallest in his class. — 同じ tall が三つの形に変わります。日本語なら「背が高い」「より高い」「いちばん高い」と、語をそえるだけですみます。英語は語そのものを変える。まずは全体の地図を見ましょう。\",\"order\":741,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"原級＝もとの形（tall）、比較級＝〜より…（taller）、最上級＝いちばん…（tallest）。\",\"比較級の文には than、最上級の文には the が必要。\",\"〈A is 比較級 than B.〉／〈A is the 最上級 in / of ~.〉が基本の形。\",\"比較級・最上級は形容詞だけでなく副詞にも使う（faster、fastest）。\",\"副詞の最上級では the を省略することがある（He runs fastest.）。\"],\"sections\":[{\"heading\":\"三つの形と基本の文\",\"mangaId\":\"eigo_s241_manga\",\"body\":\"英語で二つ以上のものを比べるときは、形容詞・副詞の形を変える。形は三つある。\\n\\n原級（もとの形）：tall（背が高い）\\n比較級：taller（もっと背が高い）\\n最上級：tallest（いちばん背が高い）\\n\\n■ 原級を使う文\\n例）Ken is tall.（ケンは背が高い）\\n\\n■ 比較級を使う文 ─ than が必要\\n〈A is 比較級 than B.〉で「AはBより〜だ」を表す。\\n\\n例）Ken is taller than Yuki.（ケンはユキより背が高い）\\n例）This book is more interesting than that one.\\n例）He runs faster than I do.\\n\\n■ 最上級を使う文 ─ the が必要\\n〈A is the 最上級 in / of ~.〉で「Aは〜の中でいちばん…だ」を表す。\\n\\n例）Ken is the tallest of the three.（ケンは3人の中でいちばん背が高い）\\n例）Mt. Fuji is the highest mountain in Japan.\\n\\n最上級には必ず the を付ける。「いちばん」は一つに決まるものなので the が必要だと考えるとよい。\\n\\n■ 副詞にも使う\\n例）He runs fast. → He runs faster than Tom. → He runs (the) fastest of the three.\\n\\n副詞の最上級では the を省略してもよいが、付けても誤りではない。\\n\\n★ ポイント：比較級を見たら than を探す、最上級を見たら the と in / of を探す。この二つがそろって初めて文が完成する。\",\"figureId\":\"lf_eigoext07_241\"},{\"heading\":\"比較の文を読み解く手順\",\"body\":\"比較の文は、次の三点を確かめれば正確に読める。\\n\\n■ ①何と何を比べているか\\nthan のあとが比べる相手である。\\n\\n例）Ken is taller than Yuki. → 比べているのはケンとユキ。\\n\\n■ ②どちらが上か\\n比較級の前にある主語のほうが上である。\\n\\n例）Ken is taller than Yuki. → 背が高いのはケン。\\n\\n■ ③どの範囲でいちばんか\\n最上級では in / of のあとが範囲である。\\n\\n例）Ken is the tallest of the three. → 3人の中での話。\\n\\n■ 書きかえの練習\\n同じ内容を比較級でも最上級でも表せることがある。\\n\\n例）Ken is taller than Yuki. Ken is taller than Tom.\\n　→ Ken is the tallest of the three.（3人の中でいちばん）\\n\\n■ 比較級と最上級の使い分け\\n2つ（2人）を比べるときは比較級、3つ（3人）以上のときは最上級を使う。\\n\\n例）Which is bigger, Japan or Australia?（2つ → 比較級）\\n例）Which is the biggest of the three?（3つ → 最上級）\\n\\n⚠ 注意：最上級の the を落とす誤りが最も多い。He is fastest runner in his class. は誤りで、the fastest runner としなければならない。\"}],\"trapExamples\":[{\"question\":\"「ケンはトムより背が高い。」を英語にしなさい。\",\"wrongAnswer\":\"Ken is more tall than Tom.\",\"trapExplanation\":\"「もっと」という日本語の感覚から more を使ってしまう。more を使う語と -er を使う語の区別ができていない。\",\"correctAnswer\":\"Ken is taller than Tom.\",\"correctExplanation\":\"tall は短い語（1音節）なので -er を付けて taller とする。more を使うのは beautiful・interesting のような長い語である。more tall のように、more と -er を両方使うことも絶対にない。\"},{\"question\":\"「彼はクラスでいちばん速い走者だ。」を英語にしなさい。\",\"wrongAnswer\":\"He is fastest runner in his class.\",\"trapExplanation\":\"最上級の形（fastest）を作ることに気を取られて、その前に必要な the を落としてしまう。日本語の「いちばん速い走者」には the にあたる語がないため気づきにくい。\",\"correctAnswer\":\"He is the fastest runner in his class.\",\"correctExplanation\":\"最上級には必ず the を付ける。「いちばん」は一つに決まるものなので the が必要になる。ただし副詞の最上級（He runs fastest.）では the を省略することがある。ここは runner という名詞が続く形容詞の最上級なので the が必要である。\"}]}",
"{\"id\":\"eigo_s242\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"-er / -est をつける語と more / most を使う語\",\"description\":\"語の長さ（音節）による比較級・最上級の作り方の使い分けを判断できるようにする\",\"intro\":\"tall は taller、beautiful は more beautiful。なぜ beautifuller と言わないのでしょう。理由は語の長さです。長い語に -er を付けると発音しにくくなるので、前に more を置きます。見分ける手がかりは、語をいくつの音のまとまりで読むかにあります。\",\"order\":742,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"短い語（1音節）は -er / -est を付ける（tall → taller → tallest）。\",\"2音節でも -y で終わる語は -er / -est（easy → easier → easiest）。\",\"長い語（3音節以上、および多くの2音節語）は more / most を前に置く。\",\"more・most を使うとき、もとの形容詞は変化させない（more beautiful）。\",\"-er と more を同時に使うことは絶対にない（more taller は誤り）。\"],\"sections\":[{\"heading\":\"語の長さで決まる\",\"mangaId\":\"eigo_s242_manga\",\"body\":\"比較級・最上級の作り方は、その語の長さ（音節の数）で決まる。音節とは、母音を中心とした音のまとまりのことである。\\n\\n■ 短い語 → -er / -est\\n1音節の語はすべて -er / -est を付ける。\\n\\ntall → taller → tallest／fast → faster → fastest／long → longer → longest／old → older → oldest／young → younger → youngest／small → smaller → smallest／high → higher → highest／short → shorter → shortest／new → newer → newest／cheap → cheaper → cheapest\\n\\n■ 2音節でも -y で終わる語 → -er / -est\\neasy → easier → easiest／happy → happier → happiest／busy → busier → busiest／early → earlier → earliest／pretty → prettier → prettiest／heavy → heavier → heaviest\\n\\ny を i に変えるのを忘れない。\\n\\n■ 長い語 → more / most\\n3音節以上の語と、多くの2音節語は more / most を前に置く。\\n\\nbeautiful → more beautiful → most beautiful\\ninteresting → more interesting → most interesting\\ndifficult → more difficult → most difficult\\nimportant → more important → most important\\nfamous → more famous → most famous\\nuseful → more useful → most useful\\n\\n★ ポイント：迷ったら「その語を発音して手をたたく回数」を数える。1回なら -er、3回以上なら more である。\",\"figureId\":\"lf_eigoext07_242\"},{\"heading\":\"まちがえやすい点\",\"body\":\"■ more を使うとき、もとの語は変えない\\nmore を使う場合、形容詞そのものは原級のままである。\\n\\n正）more beautiful／most beautiful\\n誤）more beautifuler／most beautifulest\\n\\n■ -er と more を同時に使わない\\nどちらか一方だけを使う。両方使うことは絶対にない。\\n\\n誤）more taller／more bigger／most tallest\\n\\n■ most には the を付ける\\n最上級なので the が必要である。\\n\\n正）the most beautiful flower\\n誤）most beautiful flower（最上級として使う場合）\\n\\nなお、the の付かない most には「非常に」という別の意味があるが、中学入試では扱わない。\\n\\n■ 覚えておきたい2音節語の区分\\n-er 型：easy, happy, busy, early, pretty, heavy, angry, lucky, simple\\nmore 型：famous, useful, careful, helpful, active, tired, boring, common\\n\\n■ 副詞の場合\\n-ly で終わる副詞は more / most を使う。\\n\\n例）slowly → more slowly → most slowly\\n例）carefully → more carefully → most carefully\\n例）beautifully → more beautifully → most beautifully\\n\\nただし early は -ly で終わっているように見えるが、earlier → earliest と変化する例外である。\\n\\n⚠ 注意：early は形が -ly でも -er 型。反対に slowly は -ly なので more 型。この2語の区別が入試で問われる。\"}],\"trapExamples\":[{\"question\":\"「この本はあの本より役に立つ。」を英語にしなさい。\",\"wrongAnswer\":\"This book is usefuler than that one.\",\"trapExplanation\":\"「比較級は -er を付ける」という規則だけを覚えていると、語の長さを確かめずに -er を付けてしまう。useful は2音節で -y で終わらないので more 型である。\",\"correctAnswer\":\"This book is more useful than that one.\",\"correctExplanation\":\"useful は more / most を使う語である。-er を付けるのは1音節の語と、-y で終わる2音節語だけである。同じく famous、careful、helpful も more famous、more careful、more helpful となる。\"},{\"question\":\"「この問題はあの問題よりも簡単だ。」を英語にしなさい。\",\"wrongAnswer\":\"This question is more easy than that one.\",\"trapExplanation\":\"2音節の語だから more を使うと考えてしまう。easy は2音節だが -y で終わるので -er 型である、という例外を知らないと引っかかる。\",\"correctAnswer\":\"This question is easier than that one.\",\"correctExplanation\":\"2音節でも -y で終わる語は -er / -est を付ける。さらに〈子音字＋y〉なので y を i に変えて easier とする。happy → happier、busy → busier、early → earlier、heavy → heavier も同じ仲間である。\"}]}",
"{\"id\":\"eigo_s243\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較級・最上級のつづりの変化\",\"description\":\"e で終わる語・y で終わる語・子音字を重ねる語という三つのつづり変化を正確に覚える\",\"intro\":\"big の比較級は biger ではなく bigger と、g を重ねます。easy は easyer ではなく easier と、y を i に変えます。どちらも読み方を保つためのつづりの決まりです。三つの型に分けて覚えれば、初めて見る語でも自分で変化させられます。\",\"order\":743,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"e で終わる語は -r / -st だけを付ける（large → larger → largest）。\",\"〈子音字＋y〉は y を i に変えて -er / -est（easy → easier → easiest）。\",\"〈短母音＋子音字〉で終わる1音節語は子音字を重ねる（big → bigger → biggest）。\",\"hot → hotter、sad → sadder、thin → thinner、fat → fatter も同じ型。\",\"new・slow は w で終わる（w は重ねない）ので newer、slower。clean・cheap のように母音字が二つ並ぶ語も重ねない。\"],\"sections\":[{\"heading\":\"三つのつづり変化\",\"body\":\"-er / -est を付ける語には、つづりが変わる型が三つある。動詞の -ing・-ed の変化とほぼ同じ規則なので、あわせて覚えるとよい。\\n\\n■ ①e で終わる語 → -r / -st だけを付ける\\nlarge → larger → largest\\nnice → nicer → nicest\\nwide → wider → widest\\nlate → later → latest\\nfine → finer → finest\\nsimple → simpler → simplest\\n\\ne を二つ重ねて largeer とはしない。\\n\\n■ ②〈子音字＋y〉→ y を i に変えて -er / -est\\neasy → easier → easiest\\nhappy → happier → happiest\\nbusy → busier → busiest\\nearly → earlier → earliest\\nheavy → heavier → heaviest\\npretty → prettier → prettiest\\nangry → angrier → angriest\\n\\n■ ③〈短母音＋子音字〉で終わる1音節語 → 子音字を重ねる\\nbig → bigger → biggest\\nhot → hotter → hottest\\nsad → sadder → saddest\\nthin → thinner → thinnest\\nfat → fatter → fattest\\nred → redder → reddest\\n\\n母音字が一つで、そのあとに子音字が一つだけ来る語が対象である。\\n\\n★ ポイント：③は「短い母音の音を守るために子音字を重ねる」と考えるとよい。重ねないと bigger が「バイガー」のような発音に見えてしまう。\",\"figureId\":\"xf_eigo_s243\",\"mangaId\":\"eigo_s243_xm\"},{\"heading\":\"重ねない語との区別\",\"body\":\"子音字を重ねるのは〈短母音＋子音字1つ〉の1音節語だけである。次のような語は重ねない。\\n\\n■ w で終わる語・母音字が二つ並ぶ語\\nnew → newer → newest（w は重ねない）\\nslow → slower → slowest（w は重ねない）\\nclean → cleaner → cleanest\\ncheap → cheaper → cheapest\\ngreat → greater → greatest\\ncool → cooler → coolest\\n\\n■ 子音字が二つ以上で終わる語\\nlong → longer → longest（ng で終わる）\\nstrong → stronger → strongest\\nfast → faster → fastest（st で終わる）\\nyoung → younger → youngest\\nshort → shorter → shortest\\nold → older → oldest\\n\\n■ y の前が母音字のとき\\n〈母音字＋y〉の場合は y を i に変えない。ただし比較級で問われることはまれである。\\n\\n■ まとめて確かめる練習\\nbig → bigger（重ねる）／new → newer（重ねない）\\nhot → hotter（重ねる）／short → shorter（重ねない）\\nsad → sadder（重ねる）／cheap → cheaper（重ねない）\\n\\n■ 最上級でも同じ規則\\n比較級で子音字を重ねた語は、最上級でも重ねる。\\n\\n例）the biggest／the hottest／the saddest\\n\\n⚠ 注意：hotest・biger・happyer は入試の誤答の定番。「短母音＋子音字1つなら重ねる」「子音字＋y なら i に変える」を口に出して確かめる習慣をつける。\"}],\"trapExamples\":[{\"question\":\"big の比較級を書きなさい。\",\"wrongAnswer\":\"biger\",\"trapExplanation\":\"「比較級は -er を付けるだけ」と覚えているため、つづりの変化を確かめずにそのまま -er を付けてしまう。\",\"correctAnswer\":\"bigger\",\"correctExplanation\":\"〈短母音＋子音字1つ〉で終わる1音節の語は、最後の子音字を重ねてから -er を付ける。hot → hotter、sad → sadder、thin → thinner、fat → fatter も同じ規則である。一方 new は w で終わるので重ねず、cheap は母音字が二つ並ぶので重ねない。\"},{\"question\":\"「この絵はあの絵よりすてきだ。」を英語にしなさい。\",\"wrongAnswer\":\"This picture is more nice than that one.\",\"trapExplanation\":\"nice を「すてきな」という少し長い意味の語だと感じて more を選んでしまう。音節の数ではなく日本語の訳の長さで判断すると誤る。\",\"correctAnswer\":\"This picture is nicer than that one.\",\"correctExplanation\":\"nice は1音節の短い語なので -er を付ける。ただし e で終わっているので -r だけを付けて nicer となる。large → larger、wide → wider、late → later も同じ型である。\"}]}",
"{\"id\":\"eigo_s244\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"more / most 型の代表語を覚える\",\"description\":\"中学入試で頻出の long word（長い形容詞）をまとめて覚え、正しい形で使えるようにする\",\"intro\":\"important、interesting、difficult、expensive——これらはすべて more を付けて比べます。共通しているのは語が長いことです。よく出る語をまとまりで覚えてしまえば、テストのときに「-er か more か」と迷う時間がなくなります。\",\"order\":744,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"more / most 型の代表語：beautiful, interesting, difficult, important, famous, popular, useful, expensive, exciting, wonderful, careful, delicious, dangerous。\",\"最上級は the most ~ の形（the most beautiful）。the を落とさない。\",\"more / most を使うときは、形容詞そのものは原級のまま。\",\"-ly で終わる副詞も more / most 型（more slowly、most carefully）。\",\"語の意味ではなく音節の数で判断する。\"],\"sections\":[{\"heading\":\"覚えておきたい more / most 型\",\"body\":\"more / most を使う形容詞・副詞は、中学入試で出るものがほぼ決まっている。次のリストをそのまま覚えてしまうのが最短である。\\n\\n■ 3音節以上の形容詞\\nbeautiful（美しい）／interesting（おもしろい）／difficult（難しい）／important（大切な）／expensive（高価な）／exciting（わくわくする）／wonderful（すばらしい）／dangerous（危険な）／delicious（おいしい）／popular（人気のある）／comfortable（快適な）\\n\\n■ 2音節で more 型の形容詞\\nfamous（有名な）／useful（役に立つ）／careful（注意深い）／helpful（助けになる）／boring（退屈な）／tired（疲れた）／active（活発な）／common（共通の）／crowded（混雑した）\\n\\n■ 例文で確かめる\\n例）This flower is more beautiful than that one.（この花はあの花より美しい）\\n例）Science is more interesting than math for me.\\n例）Health is more important than money.（健康はお金より大切だ）\\n例）This is the most expensive bag in the shop.\\n例）He is the most famous singer in Japan.\\n\\n■ 副詞も同じ\\n例）Please speak more slowly.（もっとゆっくり話してください）\\n例）She writes more carefully than I do.\\n\\n★ ポイント：語の意味の重さではなく、音節の数で決まる。short（短い）も long（長い）も1音節なので、どちらも -er 型である。\",\"figureId\":\"xf_eigo_s244\"},{\"heading\":\"the most の the を落とさない\",\"body\":\"more / most 型の最上級でとくに多い誤りが、the の落としである。\\n\\n正）This is the most expensive bag in the shop.\\n誤）This is most expensive bag in the shop.\\n\\n正）She is the most popular singer of all.\\n誤）She is most popular singer of all.\\n\\n■ 名詞がなくても the は必要\\n最上級のあとに名詞がなくても the を付ける。\\n\\n例）This question is the most difficult of the five.（この問題は5問の中でいちばん難しい）\\n例）That movie was the most exciting of all.\\n\\n■ more のあとに than を忘れない\\n比較級の文には than が必要である。\\n\\n正）This book is more interesting than that one.\\n誤）This book is more interesting that one.\\n\\n■ than のあとの繰り返しは one / ones で\\n同じ名詞を繰り返すかわりに one（単数）／ones（複数）を使う。\\n\\n例）This bag is more expensive than that one.\\n例）These shoes are more comfortable than those.\\n\\n■ 比較級・最上級の書きかえ\\n例）Tom is more careful than Ken.\\n　＝ Ken is less careful than Tom.（中学入試では参考程度）\\n\\n⚠ 注意：the most beautiful のように the・most・原級の三つがそろって初めて最上級になる。どれか一つでも欠けると誤りになる。\",\"mangaId\":\"eigo_s244_xm\"}],\"trapExamples\":[{\"question\":\"「これは花の中でいちばん美しい。」を英語にしなさい。\",\"wrongAnswer\":\"This is the beautifullest flower.\",\"trapExplanation\":\"最上級は -est を付けるものだと覚えているため、長い語にも機械的に -est を付けてしまう。beautifullest という語は存在しない。\",\"correctAnswer\":\"This is the most beautiful flower.\",\"correctExplanation\":\"beautiful は3音節の長い語なので、most を前に置いて最上級を作る。形容詞そのものは原級のまま変化させない。同じく the most interesting、the most important、the most difficult となる。\"},{\"question\":\"「これはすべての中でいちばん高価だ。」を英語にしなさい。\",\"wrongAnswer\":\"This is most expensive of all.\",\"trapExplanation\":\"most を付ければ最上級になると考え、その前の the を落としてしまう。日本語の「いちばん高価だ」には the にあたる語がないため気づきにくい。\",\"correctAnswer\":\"This is the most expensive of all.\",\"correctExplanation\":\"最上級には必ず the が必要である。〈the＋most＋原級〉の三つがそろって最上級になる。あとに名詞がなくても the は省略できない。範囲を表す of all（すべての中で）もセットで覚えておく。\"}]}",
"{\"id\":\"eigo_s245\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較級・最上級を使う基本文の組み立て\",\"description\":\"形容詞と副詞の両方について、比較級・最上級を使った文を正しく組み立てられるようにする\",\"intro\":\"This book is more interesting than that one. と He runs faster than I do. — 形容詞の比較と副詞の比較では、文の作りが少しちがいます。どちらも than のあとに何を置くかがかぎです。基本の型を、手を動かしながら固めていきます。\",\"order\":745,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"〈A＋be動詞＋比較級＋than＋B〉が形容詞の比較級の基本形。\",\"〈A＋一般動詞＋比較級＋than＋B〉が副詞の比較級の基本形（He runs faster than Tom.）。\",\"2つ（2人）を比べるときは比較級、3つ（3人）以上のときは最上級。\",\"than のあとの繰り返しは one / ones、または do / does / did で受ける。\",\"最上級の範囲は in（場所・集団）か of（数・仲間）で表す。\"],\"sections\":[{\"heading\":\"形容詞と副詞、それぞれの基本形\",\"body\":\"比較の文は、形容詞を使う場合と副詞を使う場合で形が少しちがう。\\n\\n■ 形容詞の比較級 ─ be動詞を使う\\n〈A＋be動詞＋比較級＋than＋B〉\\n\\n例）Ken is taller than Tom.（ケンはトムより背が高い）\\n例）This bag is heavier than that one.\\n例）Today is colder than yesterday.\\n\\n■ 副詞の比較級 ─ 一般動詞を使う\\n〈A＋一般動詞＋比較級＋than＋B〉\\n\\n例）Ken runs faster than Tom.（ケンはトムより速く走る）\\n例）She gets up earlier than her brother.\\n例）He speaks English better than I do.\\n\\nbe動詞と一般動詞を混ぜて Ken is run faster ... としないように注意する。\\n\\n■ 形容詞の最上級\\n〈A＋be動詞＋the＋最上級＋in / of ~〉\\n\\n例）Ken is the tallest in his class.\\n例）This is the biggest dog of the five.\\n\\n■ 副詞の最上級\\n〈A＋一般動詞＋(the)＋最上級＋in / of ~〉\\n\\n例）Ken runs (the) fastest of the three.\\n例）She sings (the) best in our school.\\n\\n副詞の最上級では the を省略できるが、付けても誤りではない。\\n\\n★ ポイント：文を作るときは、まず主語と動詞（be動詞か一般動詞か）を決めてから、比較級・最上級を入れる。\",\"figureId\":\"xf_eigo_s245\"},{\"heading\":\"比較する相手をそろえる\",\"mangaId\":\"eigo_s245_manga\",\"body\":\"比較の文では、比べる二つが同じ種類のものでなければならない。\\n\\n■ 名詞の繰り返しは one / ones\\n例）This bag is bigger than that one.（one＝bag）\\n例）These pencils are longer than those.\\n\\n■ 動詞の繰り返しは do / does / did\\n例）He runs faster than I do.（do＝run）\\n例）She studies harder than he does.\\n例）I got up earlier than my sister did.\\n\\n■ 所有を表すときは mine / yours など\\n例）My bag is bigger than yours.（yours＝your bag）\\n例）His house is newer than mine.\\n\\nthan のあとに you・he をそのまま置くと「かばんと人」を比べることになってしまう。\\n\\n誤）My bag is bigger than you.（私のかばんはあなたより大きい？）\\n正）My bag is bigger than yours.\\n\\n■ 2つなら比較級、3つ以上なら最上級\\n比べる数によって形が決まる。\\n\\n例）Which is bigger, Japan or Australia?（2つ → 比較級）\\n例）Which is the biggest of the three?（3つ → 最上級）\\n例）She plays the piano best of the three.（3人 → 最上級）\\n\\n⚠ 注意：of the three（3人の中で）とあるのに比較級 better を使ってしまう誤りが多い。範囲を示す語句を見て、比較級か最上級かを判断する。\"}],\"trapExamples\":[{\"question\":\"「私のかばんはあなたのかばんより大きい。」を英語にしなさい。\",\"wrongAnswer\":\"My bag is bigger than you.\",\"trapExplanation\":\"日本語の「あなたのかばんより」を短く「あなたより」と考えてしまい、than のあとに you を置いてしまう。これでは「かばん」と「あなた」という別の種類のものを比べることになる。\",\"correctAnswer\":\"My bag is bigger than yours.\",\"correctExplanation\":\"比較の文では同じ種類のものどうしを比べる。your bag の繰り返しをさけるには yours（あなたのもの）を使う。同じく His house is newer than mine.（mine＝my house）となる。名詞の繰り返しは one / ones でも表せる。\"},{\"question\":\"「彼女は3人の中でいちばん上手にピアノを弾く。」を英語にしなさい。\",\"wrongAnswer\":\"She plays the piano better of the three.\",\"trapExplanation\":\"「上手に」という日本語に対して well の比較級 better がすぐ思い浮かぶため、比べる相手が3人であることを確かめずに比較級を使ってしまう。\",\"correctAnswer\":\"She plays the piano (the) best of the three.\",\"correctExplanation\":\"3つ（3人）以上の中でいちばんと言うときは最上級を使う。well の最上級は best である。of the three という範囲を示す語句が最上級のしるしになる。2人を比べるときだけ better than ~ の形になる。\"}]}",
"{\"id\":\"eigo_s246\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則変化①：good / well → better → best、bad → worse → worst\",\"description\":\"もっとも出題される二組の不規則変化と、like ~ better / best の言い方を身につける\",\"intro\":\"good の比較級は gooder ではなく better、最上級は best です。bad は worse、worst と変わります。もっともよく使う語ほど、規則から外れた形をしているのです。日本語の「よい・よりよい」とはまったくちがう形なので、音ごと覚えてしまうのが早道です。\",\"order\":746,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"good（よい）も well（上手に・元気な）も、比較級 better・最上級 best。\",\"bad（悪い）と ill（病気の）は、比較級 worse・最上級 worst。\",\"I like A better than B.（BよりAが好き）／I like A the best.（Aがいちばん好き）。\",\"gooder・weller・badder という形は存在しない。\",\"more better のように more と重ねてはいけない。\"],\"sections\":[{\"heading\":\"good / well → better → best\",\"body\":\"いくつかの語は -er / -est も more / most も使わず、まったく形の変わる不規則変化をする。中でも最重要なのが good と well である。\\n\\ngood（よい・形容詞）→ better → best\\nwell（上手に・副詞／元気な・形容詞）→ better → best\\n\\n形容詞の good と副詞の well が、比較級・最上級では同じ形になるのが特徴である。\\n\\n例）This book is good. → This book is better than that one. → This book is the best of the three.\\n例）He plays tennis well. → He plays tennis better than Tom. → He plays tennis (the) best in his class.\\n\\n■ bad → worse → worst\\nbad（悪い）→ worse → worst\\nill（病気の）も同じく worse → worst と変化する。\\n\\n例）The weather is bad today. → It is worse than yesterday. → It was the worst day of the year.\\n例）My score is worse than yours.（私の点数はあなたより悪い）\\n\\n■ 存在しない形\\ngooder、goodest、weller、badder、baddest、more good、more bad はいずれも誤りである。不規則変化の語には more を付けない。\\n\\n■ 例文で定着させる\\n例）Which is better, tea or coffee?（お茶とコーヒーではどちらがよいですか）\\n例）This is the best restaurant in this town.\\n例）Today is the worst day of my life.\\n\\n★ ポイント：better と best は、good と well という二つの語の比較級・最上級を兼ねている。文の中で形容詞か副詞かを見分けて訳す。\"},{\"heading\":\"like ~ better / the best\",\"body\":\"「〜のほうが好き」「〜がいちばん好き」は、この不規則変化を使って表す。\\n\\n■ like A better than B ＝ BよりAが好き\\n例）I like soccer better than baseball.（野球よりサッカーが好きだ）\\n例）She likes cats better than dogs.\\n例）Which do you like better, summer or winter?（夏と冬ではどちらが好きですか）\\n　　— I like summer better.\\n\\n■ like A the best ＝ Aがいちばん好き\\n3つ以上の中でいちばん好きと言うときは the best を使う。\\n\\n例）I like soccer the best of all sports.（すべてのスポーツの中でサッカーがいちばん好きだ）\\n例）Which season do you like the best?（どの季節がいちばん好きですか）\\n　　— I like spring the best.\\n\\n■ 位置に注意\\nbetter・the best は目的語のあとに置く。\\n\\n正）I like soccer better than baseball.\\n誤）I like better soccer than baseball.\\n\\n■ よくある誤り\\n誤）I like soccer more better than baseball.（more と better の重複）\\n誤）I like soccer than baseball.（better の落とし）\\n誤）I like soccer the better of all sports.（3つ以上なら the best）\\n\\n⚠ 注意：2つを比べるときは better、3つ以上なら the best。「どちらが」なら better、「どれがいちばん」なら the best と判断する。\"},{\"heading\":\"なぜ good の比較級は gooder ではないのか\",\"mangaId\":\"eigo_s246_manga\",\"body\":\"good・bad・well のように、**もっともよく使う語ほど不規則な形**をしています。よく使う語は昔の形がそのまま残りやすく、規則で作った gooder・badder に置きかわらなかったからです。better・best はもともと別の語で、good の比較級・最上級として使われるようになりました。だから音ごと覚えるしかなく、more good・more better のように more を付けると、比較級を二重にしたことになって誤りです。\\n\\n形容詞の good と副詞の well が同じ better・best になるので、文の中でどちらの意味かは**何を修飾しているか**で決めます。This book is better（本がよい→形容詞）、He swims better（泳ぎ方が上手→副詞）。like A better than B は「B より A が好き」で、better は目的語（A）のあとに置きます。\\n\\n■ 確かめのしかた\\n①good／well→**better→best**、bad／ill→**worse→worst**。gooder・weller・badder・more good は存在しない。\\n②比較級を作ったら、**more が重なっていないか**。× more well、× more better。\\n③like A better than B（2つを比べる）、like A the best（3つ以上）。「どちらが」なら better、「どれがいちばん」なら the best。\\n④better の位置は目的語のあと。× I like better soccer than baseball。× I like soccer than baseball（better の落とし）。\\n\\n★ ここがポイント：よく使う語ほど**昔の形が残って不規則**（good→better→best、bad→worse→worst）。不規則な語に **more を重ねない**。like A better than B は「B より A が好き」で、better は目的語のあと。\",\"figureId\":\"xf_eigo_s246\"}],\"trapExamples\":[{\"question\":\"「彼は私より上手に泳ぐ。」を英語にしなさい。\",\"wrongAnswer\":\"He swims more well than I do.\",\"trapExplanation\":\"well を長い語ではないと感じつつも -er の付け方がわからず、迷って more を付けてしまう。あるいは weller という存在しない形を作ってしまう。\",\"correctAnswer\":\"He swims better than I do.\",\"correctExplanation\":\"well は不規則変化で、比較級は better、最上級は best である。weller・more well という形は存在しない。形容詞の good も同じく better・best と変化する。不規則変化の語には more を付けない。\"},{\"question\":\"「私は野球よりサッカーのほうが好きだ。」を英語にしなさい。\",\"wrongAnswer\":\"I like soccer more better than baseball.\",\"trapExplanation\":\"「もっと好き」という日本語の感覚から more を足してしまい、比較級 better と重ねてしまう。比較級は一度だけでよいという原則を忘れている。\",\"correctAnswer\":\"I like soccer better than baseball.\",\"correctExplanation\":\"better はそれ自体が well の比較級なので、more と重ねてはいけない。〈like A better than B〉で「BよりAが好き」を表す。3つ以上の中でいちばん好きなら I like soccer the best of all sports. となる。\"}]}",
"{\"id\":\"eigo_s247\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則変化②：many / much → more → most、little → less → least\",\"description\":\"数量を表す語の不規則変化と、more が持つ二つの意味を整理する\",\"intro\":\"many も much も、比較級は同じ more、最上級も同じ most です。数のほうも量のほうも、一つの形にまとまってしまいます。反対に little は less、least と変わります。少しややこしいので、表にして一度で頭に入れてしまいましょう。\",\"order\":747,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"many（数が多い）も much（量が多い）も、比較級 more・最上級 most。\",\"little（量が少ない）→ less → least。few（数が少ない）→ fewer → fewest。\",\"more には「より多くの」と「もっと〜」の二つの働きがある。\",\"the most money（いちばん多くのお金）のように名詞を伴うことも多い。\",\"more books than you のように、名詞の前に置いて数量を比べる。\"],\"sections\":[{\"heading\":\"many / much → more → most\",\"body\":\"数量を表す many・much も不規則変化をする。しかもどちらも比較級が more、最上級が most になる。\\n\\nmany（数が多い）→ more → most\\nmuch（量が多い）→ more → most\\n\\n■ 数を比べる\\n例）I have more books than you.（私はあなたより多くの本を持っている）\\n例）She has more friends than I do.\\n例）He has the most books in his class.（彼はクラスでいちばん多くの本を持っている）\\n\\n■ 量を比べる\\n例）I have more money than my brother.（兄より多くのお金を持っている）\\n例）We need more time.（もっと時間が必要だ）\\n例）He has the most money of the three.\\n\\n■ more の二つの働き\\nmore には二つの働きがあり、これを混同すると読みまちがえる。\\n\\n①many / much の比較級として「より多くの」\\n例）more books（より多くの本）\\n\\n②長い形容詞・副詞の比較級を作る語として「もっと〜」\\n例）more beautiful（より美しい）\\n\\n見分け方は、more のあとに名詞が来るか形容詞が来るかである。名詞なら①、形容詞・副詞なら②である。\\n\\n★ ポイント：more books は「本の数が多い」、more beautiful は「美しさの程度が上」。あとに続く語で判断する。\"},{\"heading\":\"little → less → least、few → fewer → fewest\",\"body\":\"「少ない」を表す語も不規則変化をする。数と量で語がちがう点に注意する。\\n\\n■ little（量が少ない）→ less → least\\n例）I have less time than you.（あなたより時間が少ない）\\n例）He drinks less coffee than before.\\n例）This is the least expensive of the three.（3つの中でいちばん安い）\\n\\nless を使うときは、数えられない名詞が続く。\\n\\n■ few（数が少ない）→ fewer → fewest\\n例）There are fewer students this year.（今年は生徒が少ない）\\n例）He made fewer mistakes than I did.\\n\\nfewer を使うときは、数えられる名詞の複数形が続く。\\n\\n■ 使い分けのまとめ\\n数が多い：many → more → most（more books）\\n量が多い：much → more → most（more water）\\n数が少ない：few → fewer → fewest（fewer books）\\n量が少ない：little → less → least（less water）\\n\\n■ little の別の意味\\nlittle には「小さい」という意味もあり、その場合は smaller・smallest を使うのがふつうである。\\n\\n例）a little dog（小さな犬）→ a smaller dog\\n\\n⚠ 注意：less time（時間が少ない）を littler time としない。littler という形は数量の意味では使わない。\"},{\"heading\":\"なぜ many も much も more になり、なぜ little は less なのか\",\"mangaId\":\"eigo_s247_manga\",\"body\":\"many（数が多い）と much（量が多い）は、肯定の原級では数と量で語を分けますが、**比較すると「もっと多い」という一つの意味**にまとまるので、比較級・最上級は more・most の一つの形になります。more books（数）も more water（量）も同じ more です。逆に「少ない」は、比較しても数（fewer books）と量（less water）を分けたままなので、few→fewer→fewest、little→less→least と別々に変化します。\\n\\nmore に二つの働き（many/much の比較級と、長い形容詞の比較級を作る語）があるので、**more のあとに名詞が来るか、形容詞が来るか**で読み分けます。more books は「本の数が多い」、more beautiful は「美しさの程度が上」です。数量の little の比較級を規則どおり littler としないのは、less という別の語が決まっているからです。\\n\\n■ 確かめのしかた\\n①数が多い：many→more→most。量が多い：much→more→most。「あなたより多くの本」→more books than you（× many books than）。\\n②数が少ない：few→fewer→fewest（fewer students）。量が少ない：little→less→least（less time）。× littler time。\\n③more のあとが**名詞**なら「より多くの」、**形容詞・副詞**なら「もっと〜」。\\n④「小さい」の little は smaller・smallest（a smaller dog）。数量の little とは別の変化。\\n\\n★ ここがポイント：比較すると数も量も「もっと多い」にまとまるので **many/much→more→most**。「少ない」は数（few→fewer）と量（little→less）を分けたまま。more は**あとの語（名詞か形容詞か）**で読み分ける。\",\"figureId\":\"xf_eigo_s247\"}],\"trapExamples\":[{\"question\":\"「私はあなたより多くの本を持っている。」を英語にしなさい。\",\"wrongAnswer\":\"I have many books than you.\",\"trapExplanation\":\"「多くの本」という日本語をそのまま many books と訳し、その後に than を続けてしまう。比較の文なので many を比較級にしなければならないことに気づかない。\",\"correctAnswer\":\"I have more books than you (do).\",\"correctExplanation\":\"many の比較級は more である。〈more＋名詞＋than〉の形で数量を比べる。much の比較級も more なので、I have more money than you. のように量にも使える。最上級は the most books となる。\"},{\"question\":\"「私はあなたより時間が少ない。」を英語にしなさい。\",\"wrongAnswer\":\"I have littler time than you.\",\"trapExplanation\":\"「少ない」＝little と覚えているため、規則どおり -er を付けて littler としてしまう。数量を表す little の比較級が less という別の語であることを知らない。\",\"correctAnswer\":\"I have less time than you (do).\",\"correctExplanation\":\"数量を表す little の比較級は less、最上級は least である。数えられない名詞（time・water・money）と使う。数えられる名詞の場合は few → fewer → fewest を使い、fewer books のようになる。\"}]}",
"{\"id\":\"eigo_s248\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不規則変化③：far → farther / further と総整理\",\"description\":\"far の変化を確認したうえで、不規則変化する語をまとめて整理し確実に使えるようにする\",\"intro\":\"far の比較級には farther と further の二つがあります。実際のきょりには farther、「さらに進んだ」という意味には further を使うのが目安です。ここまでに出てきた不規則変化をすべて集めて、抜けがないか点検しておきましょう。\",\"order\":748,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"far → farther → farthest（距離が遠い）／far → further → furthest（程度がさらに進む）。\",\"中学入試では距離の farther を中心に覚えればよい。\",\"不規則変化の語：good/well、bad/ill、many/much、little、far。\",\"far は比較級の前に置いて「ずっと」と強める用法もある（far more interesting）。\",\"不規則変化の語には -er も more も付けない。\"],\"sections\":[{\"heading\":\"far の変化\",\"mangaId\":\"eigo_s248_manga\",\"body\":\"far（遠い・遠くに）は二通りの変化を持つ。\\n\\n■ 距離を表すとき：far → farther → farthest\\n例）His house is farther than mine.（彼の家は私の家より遠い）\\n例）Which is farther, the station or the library?（駅と図書館ではどちらが遠いですか）\\n例）This is the farthest point from the school.\\n\\n■ 程度がさらに進むとき：far → further → furthest\\n例）We need further information.（さらに詳しい情報が必要だ）\\n例）Let's discuss it further.\\n\\n中学入試で問われるのはほとんどが距離のほうなので、まず farther を確実に覚え、further は「さらに詳しい」という意味で出てきたら理解できればよい。\\n\\n■ よくある誤り\\n誤）farer、farrer、more far\\n正）farther\\n\\nfar には -er も more も付けない。\\n\\n■ far のもう一つの働き ─ 比較級を強める\\nfar を比較級の前に置くと「ずっと・はるかに」という強調になる。\\n\\n例）This book is far more interesting than that one.（この本はあの本よりずっとおもしろい）\\n例）He is far taller than me.\\n\\n★ ポイント：far 自体が変化する場合（farther）と、他の比較級を強める場合（far more ~）を区別する。\"},{\"heading\":\"不規則変化の総整理\",\"body\":\"中学入試で必要な不規則変化はこれだけである。表で一気に覚えてしまう。\\n\\ngood（よい）／well（上手に・元気な）→ better → best\\nbad（悪い）／ill（病気の）→ worse → worst\\nmany（数が多い）／much（量が多い）→ more → most\\nlittle（量が少ない）→ less → least\\nfew（数が少ない）→ fewer → fewest\\nfar（遠い）→ farther → farthest（distance）／further → furthest（degree）\\n\\n■ 覚え方のこつ\\n①good と well が同じ better・best になる\\n②bad と ill が同じ worse・worst になる\\n③many と much が同じ more・most になる\\nこのように「二つの語が一つの形にまとまる」という特徴でグループ化すると覚えやすい。\\n\\n■ 確認問題の形で\\nThis is a good book. → This is a better book than that one. → This is the best book of the three.\\nThe weather is bad. → The weather is worse than yesterday. → It is the worst weather of the year.\\nI have much money. → I have more money than you. → I have the most money.\\n\\n■ 絶対にしない誤り\\ngooder／goodest／weller／badder／worser／more better／most best／farer／littler（数量の意味で）\\n\\nworse に -er を付けた worser も存在しない形である。\\n\\n⚠ 注意：不規則変化の語は、変化した形にさらに -er や more を足さない。better が最終形である。\",\"figureId\":\"xf_eigo_s248\"}],\"trapExamples\":[{\"question\":\"「彼の家は私の家より遠い。」を英語にしなさい。\",\"wrongAnswer\":\"His house is farer than mine.\",\"trapExplanation\":\"far が1音節の短い語なので、規則どおり -er を付けて farer としてしまう。far が不規則変化することを知らないと必ず引っかかる。\",\"correctAnswer\":\"His house is farther than mine.\",\"correctExplanation\":\"far は不規則変化で、距離を表すときは farther → farthest となる。程度がさらに進む意味では further → furthest を使う。farer・more far という形は存在しない。\"},{\"question\":\"「私の点数は昨日より悪い。」を英語にしなさい。\",\"wrongAnswer\":\"My score is more bad than yesterday.\",\"trapExplanation\":\"bad の比較級 worse を思い出せず、規則的な作り方にたよって more を付けてしまう。badder という形を作ってしまうこともある。\",\"correctAnswer\":\"My score is worse than yesterday.\",\"correctExplanation\":\"bad の比較級は worse、最上級は worst である。more bad・badder・worser はいずれも誤りである。ill（病気の）も同じく worse・worst と変化する。不規則変化の語には more も -er も付けない。\"}]}",
"{\"id\":\"eigo_s249\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"as ~ as ─ 「同じくらい〜だ」\",\"description\":\"二つの as ではさんで「同じくらい」を表す原級比較の形を身につける\",\"intro\":\"Tom is as tall as Ken. は「トムはケンと同じくらい背が高い」という意味です。二つの as ではさまれた真ん中には、taller ではなく tall がそのまま入ります。比べているのに形を変えない、というのがこの表現の意外なところです。\",\"order\":749,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"〈A is as 原級 as B.〉で「AはBと同じくらい〜だ」を表す。\",\"as と as の間に入るのは必ず原級。比較級・最上級は入れない。\",\"副詞にも使える（She runs as fast as her brother.）。\",\"as のあとで名詞を繰り返すときは mine / yours / one を使う。\",\"〈as many＋複数名詞＋as〉〈as much＋数えられない名詞＋as〉で数量も比べられる。\"],\"sections\":[{\"heading\":\"as ~ as の基本\",\"mangaId\":\"eigo_s249_manga\",\"body\":\"二つのものが同じ程度であることを表すときは、形容詞・副詞を二つの as ではさむ。\\n\\n■ 基本の形\\n〈A＋be動詞＋as＋原級＋as＋B〉\\n\\n例）Ken is as tall as Tom.（ケンはトムと同じくらい背が高い）\\n例）This book is as interesting as that one.（この本はあの本と同じくらいおもしろい）\\n例）Today is as hot as yesterday.\\n\\n最初の as が「同じくらい」、二つめの as が「〜と」にあたる。\\n\\n■ 副詞にも使える\\n〈A＋一般動詞＋as＋原級＋as＋B〉\\n\\n例）She runs as fast as her brother.（彼女は兄と同じくらい速く走る）\\n例）He studies as hard as I do.\\n例）I get up as early as my mother.\\n\\n■ 間に入るのは必ず原級\\nas と as の間には、変化させていないもとの形（原級）を入れる。\\n\\n正）as tall as／as interesting as／as fast as\\n誤）as taller as／as more interesting as／as faster as\\n\\n「同じくらい」なのだから、比べて差をつける比較級は必要ない、と考えるとよい。\\n\\n■ 比べる相手をそろえる\\n例）My bag is as big as yours.（yours＝your bag）\\n例）This pen is as good as that one.（one＝pen）\\n\\n★ ポイント：as ~ as を見たら、間の語が原級になっているかをまず確かめる。ここが最頻出の出題ポイントである。\",\"figureId\":\"lf_eigoext07_249\"},{\"heading\":\"数量を比べる as many / as much\",\"body\":\"数や量が同じであることを表すときは、as と as の間に〈many＋複数名詞〉〈much＋数えられない名詞〉を入れる。\\n\\n■ as many＋複数名詞＋as\\n例）I have as many books as you.（あなたと同じくらい多くの本を持っている）\\n例）She has as many friends as her sister.\\n\\n■ as much＋数えられない名詞＋as\\n例）I have as much money as he does.（彼と同じくらいお金を持っている）\\n例）We need as much time as you.\\n\\n名詞は as と as の間に入れる。外に出してはいけない。\\n\\n正）as many books as you\\n誤）as many as you books\\n\\n■ 〈as＋原級＋as〉のあとの形\\nas のあとには名詞・代名詞のほか、主語＋動詞を続けることもできる。\\n\\n例）He is as busy as I am.\\n例）She sings as well as her mother does.\\n\\n■ 進級のための整理\\n同じくらい：A is as tall as B.\\nAのほうが上：A is taller than B.\\nBのほうが上：A is not as tall as B.（次の課）\\n\\n⚠ 注意：as many books as のように、名詞は必ず二つの as の内側に置く。並べかえ問題で頻出である。\"}],\"trapExamples\":[{\"question\":\"「ケンはトムと同じくらい背が高い。」を英語にしなさい。\",\"wrongAnswer\":\"Ken is as taller as Tom.\",\"trapExplanation\":\"「背が高い」を比べる文だと考えて、反射的に比較級 taller を使ってしまう。比較の文にはすべて比較級が必要だと思いこんでいると引っかかる。\",\"correctAnswer\":\"Ken is as tall as Tom.\",\"correctExplanation\":\"as と as の間に入るのは必ず原級である。「同じくらい」なので差をつける比較級は使わない。長い語も同じで、as more interesting as ではなく as interesting as となる。\"},{\"question\":\"「私の犬はあなたの犬と同じくらい大きい。」を英語にしなさい。\",\"wrongAnswer\":\"My dog is as big as your.\",\"trapExplanation\":\"your dog の dog を省略するところまでは考えたが、your のままにしてしまう。所有格の your は後ろに名詞がないと使えないことを忘れている。\",\"correctAnswer\":\"My dog is as big as yours.（= as your dog）\",\"correctExplanation\":\"後ろに名詞を置かずに「あなたのもの」を表すときは、所有代名詞の yours を使う。mine・yours・his・hers・ours・theirs がその形である。名詞を残して as your dog と書いてもよい。\"}]}",
"{\"id\":\"eigo_s250\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"not as ~ as ─ 「〜ほど…ない」\",\"description\":\"原級比較の否定形の意味を正しくとらえ、比較級を使った文に書きかえられるようにする\",\"intro\":\"Tom is not as tall as Ken. は「トムはケンほど背が高くない」。つまりケンのほうが高いのです。「同じくらい高くない」と日本語で考えるとまよいますが、not が付くと「およばない」という意味になります。比較級を使った文への書きかえもできます。\",\"order\":750,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"〈A is not as 原級 as B.〉は「AはBほど〜ない」＝Bのほうが上、という意味。\",\"「同じくらい〜ない」と訳すのは誤り。\",\"A is not as tall as B. ＝ B is taller than A.（主語が入れかわる）。\",\"not so ~ as という形も同じ意味で使われる。\",\"書きかえのときは主語を入れかえるのを忘れない。\"],\"sections\":[{\"heading\":\"意味のとらえ方\",\"body\":\"as ~ as を否定文にすると「〜ほど…ない」という意味になる。\\n\\n■ 基本の形\\n〈A＋be動詞＋not as＋原級＋as＋B〉\\n\\n例）Tom is not as tall as Ken.（トムはケンほど背が高くない）\\n例）This book is not as interesting as that one.（この本はあの本ほどおもしろくない）\\n例）Today is not as cold as yesterday.（今日は昨日ほど寒くない）\\n\\n■ 意味を正しくつかむ\\n「トムはケンほど背が高くない」ということは、ケンのほうが背が高いという意味である。「二人とも背が高くない」という意味ではないし、「同じくらい高くない」でもない。\\n\\nTom is not as tall as Ken. → 背が高いのはケン。\\n\\n■ 副詞の場合\\n例）He doesn't run as fast as I do.（彼は私ほど速く走らない）\\n例）She doesn't study as hard as her brother.\\n\\n一般動詞の文では don't / doesn't / didn't を使って否定する。\\n\\n■ not so ~ as\\nnot as ~ as は not so ~ as と書くこともでき、意味は同じである。\\n\\n例）Tom is not so tall as Ken.\\n\\n★ ポイント：not as ~ as を見たら、「as のあとの人・ものが上」と反射的に判断する。\",\"figureId\":\"lf_eigoext07_250\"},{\"heading\":\"比較級への書きかえ\",\"body\":\"not as ~ as の文は、比較級を使って書きかえられる。このとき主語が入れかわるのが最大のポイントである。\\n\\n■ 書きかえの手順\\n①not as ~ as の文で、下のほうが主語（A）、上のほうが as のあと（B）。\\n②比較級の文では上のほう（B）を主語にする。\\n③形容詞を比較級にして than でつなぐ。\\n\\n例）Tom is not as tall as Ken.\\n　＝ Ken is taller than Tom.（ケンのほうが背が高い）\\n\\n例）This book is not as interesting as that one.\\n　＝ That book is more interesting than this one.\\n\\n例）I don't run as fast as he does.\\n　＝ He runs faster than I do.\\n\\n■ 主語を入れかえない誤り\\n誤）Tom is not as tall as Ken. ＝ Tom is taller than Ken.\\nこれでは意味が正反対になってしまう。\\n\\n■ 原級での書きかえも\\n逆に、比較級の文を not as ~ as に書きかえるときも主語を入れかえる。\\n\\n例）Ken is taller than Tom. ＝ Tom is not as tall as Ken.\\n\\n■ 三つの形をまとめて\\nKen is taller than Tom.（ケンのほうが上）\\nKen is as tall as Tom.（同じくらい）\\nKen is not as tall as Tom.（トムのほうが上）\\n\\n⚠ 注意：書きかえ問題では、まず「どちらが上か」を日本語で確かめてから英文を作る。主語の入れかえを機械的にできるようにしておく。\"},{\"heading\":\"なぜ not as 〜 as は「as のあとが上」で、なぜ書きかえで主語が入れかわるのか\",\"mangaId\":\"eigo_s250_manga\",\"body\":\"as tall as は「ケンと同じ高さに達している」という意味です。それに not を付けると「**その高さに達していない**」＝「ケンほど高くない」になります。「同じくらい高くない（二人とも低い）」ではなく、「ケンの高さにおよばない」なので、as のあとの人（ケン）のほうが上です。not as 〜 as を見たら「as のあとが上」と反射的に判断します。\\n\\n比較級に書きかえるとき主語が入れかわるのは、比較級の文（B is taller than A.）が**上のほうを主語にして言う形**だからです。not as 〜 as では下のほう（Tom）が主語、上のほう（Ken）が as のあと。同じ関係を比較級で言うと、上の Ken を主語にして Ken is taller than Tom. になります。主語をそのままにして Tom is taller than Ken. とすると、上下が逆転して意味が反対になります。\\n\\n■ 確かめのしかた\\n①not as 〜 as の文を訳したら、**どちらが上か**を日本語で言う。Tom is not as tall as Ken.→ケンが上。「同じくらい〜ない」は×。\\n②比較級に書きかえるとき、**上のほうを主語**にする。Ken is taller than Tom.\\n③逆に比較級→not as 〜 as も主語を入れかえる。Ken is taller than Tom.＝Tom is not as tall as Ken.\\n④三つの形を並べて確かめる：Ken is taller than Tom.（ケンが上）／Ken is as tall as Tom.（同じ）／Ken is not as tall as Tom.（トムが上）。一般動詞は don't / doesn't で否定（He doesn't run as fast as I do.）。\\n\\n★ ここがポイント：not as 〜 as は「**その高さに達していない**」なので **as のあとが上**。比較級は**上のほうを主語にする形**なので、書きかえでは**主語を入れかえる**。まず「どちらが上か」を日本語で確かめてから書く。\"}],\"trapExamples\":[{\"question\":\"次の文を日本語にしなさい。Tom is not as tall as Ken.\",\"wrongAnswer\":\"トムとケンは同じくらい背が高くない。\",\"trapExplanation\":\"as ~ as を「同じくらい」と覚えているため、not を足して「同じくらい〜ない」と直訳してしまう。二人とも背が低い、という誤った意味に読んでしまう。\",\"correctAnswer\":\"トムはケンほど背が高くない。（＝ケンのほうが背が高い）\",\"correctExplanation\":\"not as ~ as は「〜ほど…ない」という意味で、as のあとに来る人・もののほうが上である。この文はケンのほうが背が高いことを表す。比較級で書きかえると Ken is taller than Tom. となる。\"},{\"question\":\"Ken is taller than Tom. をほぼ同じ意味の not as ~ as の文に書きかえなさい。\",\"wrongAnswer\":\"Ken is not as tall as Tom.\",\"trapExplanation\":\"もとの文の主語 Ken をそのまま主語にして書きかえてしまう。not as ~ as では上下の関係が逆になることに気づかず、意味が正反対の文を作ってしまう。\",\"correctAnswer\":\"Tom is not as tall as Ken.\",\"correctExplanation\":\"not as ~ as では、主語のほうが下、as のあとのほうが上になる。もとの文でケンのほうが上なので、書きかえた文ではトムを主語にしなければならない。書きかえのときは主語を入れかえる、と覚える。\"}]}",
"{\"id\":\"eigo_s251\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"as ~ as possible / as ~ as one can\",\"description\":\"「できるだけ〜」を表す二つの言い方と、その中に入る語の形を身につける\",\"intro\":\"「できるだけ早く来て」は Come as soon as possible. です。as soon as you can とも言えます。急いでほしい気持ちを表す、会話でとてもよく使う形です。possible を使うか can を使うかで、うしろの作りが少し変わります。\",\"order\":751,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"〈as＋原級＋as possible〉＝「できるだけ〜」。\",\"〈as＋原級＋as＋主語＋can / could〉も同じ意味。主語と時制を文に合わせる。\",\"as soon as possible（できるだけ早く）は最頻出。\",\"as many＋複数名詞＋as possible（できるだけ多くの〜）の語順に注意。\",\"過去の文では could を使う（as fast as he could）。\"],\"sections\":[{\"heading\":\"二つの言い方\",\"body\":\"「できるだけ〜」は、原級比較を使って表す。二通りの言い方があり、どちらも同じ意味である。\\n\\n■ ①as＋原級＋as possible\\n例）Please come as soon as possible.（できるだけ早く来てください）\\n例）Run as fast as possible.\\n例）Speak as slowly as possible.\\n\\n■ ②as＋原級＋as＋主語＋can\\n例）Please come as soon as you can.\\n例）Run as fast as you can.\\n例）I studied as hard as I could.\\n\\n②では主語を文の主語に合わせる。命令文なら you、I が主語なら I、he が主語なら he である。\\n\\n正）He ran as fast as he could.\\n誤）He ran as fast as you can.\\n\\n■ 時制も合わせる\\n過去の文では could を使う。\\n\\n例）She walked as quietly as she could.（彼女はできるだけ静かに歩いた）\\n例）I ate as much as I could.\\n\\n■ as soon as possible\\n「できるだけ早く」を表すこの表現は、手紙やメールでもよく使われる最頻出の形である。\\n\\n例）Please call me back as soon as possible.\\n\\n★ ポイント：possible を使う言い方は主語が要らないので簡単だが、can を使う言い方では主語と時制をそろえる必要がある。\",\"figureId\":\"xf_eigo_s251\",\"mangaId\":\"eigo_s251_xm\"},{\"heading\":\"数量を入れる形\",\"body\":\"「できるだけ多くの〜」のように名詞を入れるときは、名詞を二つの as の内側に置く。\\n\\n■ as many＋複数名詞＋as possible\\n例）Read as many books as possible.（できるだけ多くの本を読みなさい）\\n例）I want to meet as many people as I can.\\n\\n■ as much＋数えられない名詞＋as possible\\n例）Drink as much water as possible.（できるだけ多くの水を飲みなさい）\\n例）He saved as much money as he could.\\n\\n数えられる名詞なら many、数えられない名詞なら much である。ここで many と much を取りちがえる誤りが多い。\\n\\n誤）as much books as possible\\n正）as many books as possible\\n\\n■ 語順の確認\\n〈as＋many / much＋名詞＋as＋possible / 主語＋can〉\\n\\n名詞を外に出してしまう誤りが多い。\\n\\n誤）as many as possible books\\n正）as many books as possible\\n\\n■ よく使う表現\\nas soon as possible（できるだけ早く）\\nas fast as possible（できるだけ速く）\\nas often as possible（できるだけ頻繁に）\\nas carefully as possible（できるだけ注意深く）\\nas early as possible（できるだけ早い時刻に）\\n\\nsoon（時期が早い）と early（時刻が早い）と fast（速度が速い）の区別も確かめておく。\\n\\n⚠ 注意：as ~ as possible の as のあとに you を入れて as soon as you possible とする誤りがある。possible を使うときは主語を入れない。\"}],\"trapExamples\":[{\"question\":\"「できるだけ速く走りなさい。」を英語にしなさい。（can を使って）\",\"wrongAnswer\":\"Run as fast as can.\",\"trapExplanation\":\"as ~ as possible の形をまねて、can のほうにも主語を入れずに書いてしまう。can は助動詞なので、主語がなければ文にならない。\",\"correctAnswer\":\"Run as fast as you can.\",\"correctExplanation\":\"〈as＋原級＋as＋主語＋can〉の形では、必ず主語が必要である。命令文なので主語は you になる。possible を使うなら Run as fast as possible. と主語なしで書ける。過去の文なら as fast as he could のように could を使う。\"},{\"question\":\"「できるだけ多くの本を読みなさい。」を英語にしなさい。\",\"wrongAnswer\":\"Read as much books as possible.\",\"trapExplanation\":\"「できるだけ多く」というひとかたまりの意味に気を取られて、後ろの名詞が数えられるかどうかを確かめずに much を選んでしまう。\",\"correctAnswer\":\"Read as many books as possible.\",\"correctExplanation\":\"books は数えられる名詞の複数形なので many を使う。数えられない名詞なら as much water as possible のように much を使う。名詞は必ず二つの as の内側に置き、as many as possible books としない。\"}]}",
"{\"id\":\"eigo_s252\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"倍数の表し方 ─ twice as ~ as\",\"description\":\"「〜の2倍」「〜の3倍」を原級比較で表す形を、比較級との混同をさけて身につける\",\"intro\":\"「2倍」は twice as large as、「3倍」は three times as large as です。ここで larger としないことに注意します。日本語の「2倍大きい」につられて比較級を使うと形がくずれます。倍数は原級ではさむ、と覚えてしまいましょう。\",\"order\":752,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"〈倍数＋as＋原級＋as〉で「〜の何倍…だ」を表す。\",\"2倍は twice、3倍以上は three times のように times を使う。\",\"half as ~ as は「〜の半分の…」。\",\"倍数の文でも as と as の間は原級（twice as heavy as）。\",\"twice heavier than のように比較級と混ぜてはいけない。\"],\"sections\":[{\"heading\":\"倍数の基本形\",\"body\":\"「〜の2倍の大きさだ」のように倍数を表すときも、原級比較の形を使う。\\n\\n■ 基本の形\\n〈A＋be動詞＋倍数＋as＋原級＋as＋B〉\\n\\n例）This box is twice as heavy as that one.（この箱はあの箱の2倍の重さだ）\\n例）My room is three times as large as yours.（私の部屋はあなたの部屋の3倍の広さだ）\\n例）This river is four times as long as that one.\\n\\n■ 倍数の言い方\\n2倍：twice（two times とはあまり言わない）\\n3倍：three times\\n4倍：four times\\n半分：half\\n\\n例）This bag is half as heavy as that one.（このかばんはあのかばんの半分の重さだ）\\n\\n■ 語順\\n倍数は最初の as の前に置く。\\n\\n正）twice as heavy as\\n誤）as twice heavy as\\n誤）as heavy twice as\\n\\n■ 数量を入れる形\\n例）He has twice as many books as I do.（彼は私の2倍の本を持っている）\\n例）She drinks twice as much water as I do.\\n\\n名詞は二つの as の内側に入れる。\\n\\n★ ポイント：倍数の文でも「as と as の間は原級」という規則は変わらない。倍数の語だけが前に足されると考える。\",\"figureId\":\"lf_eigoext07_252\"},{\"heading\":\"比較級と混ぜない\",\"body\":\"倍数の表現でもっとも多い誤りは、比較級と混ぜてしまうことである。\\n\\n誤）This box is twice heavier than that one.\\n正）This box is twice as heavy as that one.\\n\\n倍数は「何倍」という同じ物差しでの比べ方なので、差をつける比較級ではなく原級比較を使う。\\n\\n■ よくある誤りの形\\n誤）three times as larger as\\n誤）twice as more heavy as\\n誤）twice bigger than\\n\\nいずれも as と as の間に比較級を入れてしまっている。\\n\\n■ 別の言い方（参考）\\n倍数は名詞を使って表すこともできる。\\n\\n例）This box is twice the weight of that one.（この箱はあの箱の2倍の重さだ）\\n例）My room is three times the size of yours.\\n\\n中学入試では as ~ as の形で書ければ十分である。\\n\\n■ 日本語からの組み立て手順\\n①何倍かを決める（twice / three times）\\n②形容詞を原級のまま置く\\n③as ではさむ\\n④比べる相手を置く\\n\\n例）「この木はあの木の2倍の高さだ」\\n→ twice ＋ as tall as ＋ that tree\\n→ This tree is twice as tall as that one.\\n\\n⚠ 注意：twice を使うときは as を二つとも忘れないこと。twice as tall that one のように片方を落とす誤りも多い。\",\"mangaId\":\"eigo_s252_xm\"}],\"trapExamples\":[{\"question\":\"「この箱はあの箱の2倍の重さだ。」を英語にしなさい。\",\"wrongAnswer\":\"This box is twice heavier than that one.\",\"trapExplanation\":\"「2倍重い」という日本語から「比べているのだから比較級」と考え、heavier than を使ってしまう。倍数が原級比較の形を使うことを知らないと引っかかる。\",\"correctAnswer\":\"This box is twice as heavy as that one.\",\"correctExplanation\":\"倍数は〈倍数＋as＋原級＋as〉の形で表す。as と as の間は原級なので heavy のままである。3倍なら three times as heavy as、半分なら half as heavy as となる。\"},{\"question\":\"「私の部屋はあなたの部屋の3倍の広さだ。」を英語にしなさい。\",\"wrongAnswer\":\"My room is three times as larger as yours.\",\"trapExplanation\":\"倍数のあとに as ~ as を使うところまでは正しいが、「広い」を比べているという意識から、間の語を比較級 larger にしてしまう。\",\"correctAnswer\":\"My room is three times as large as yours.\",\"correctExplanation\":\"as と as の間に入るのは必ず原級である。倍数が付いても規則は変わらない。3倍以上は three times、four times のように times を使い、2倍だけは twice という語を使う。\"}]}",
"{\"id\":\"eigo_s253\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較級＋than の使い方をかためる\",\"description\":\"than のあとに置く語の形をそろえ、比較級の文を正確に組み立てる\",\"intro\":\"He is taller than me. と He is taller than I am. — どちらも耳にします。than のあとに何を置くかは、実は少しゆれのある部分です。ただし試験では形をそろえた言い方が求められます。何と何を比べているのかを、はっきりさせる練習をします。\",\"order\":753,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"比較級の文には than が必要。than を落とすと文が成り立たない。\",\"than のあとは〈主語＋動詞〉でもよい（than I am / than he does）。\",\"所有を表すときは mine / yours / his / hers を使う。\",\"名詞の繰り返しは one / ones で受ける。\",\"比較級にするのを忘れて原級のまま than を続ける誤りが多い。\"],\"sections\":[{\"heading\":\"than のあとに置く形\",\"body\":\"比較級の文では than のあとに比べる相手を置く。このとき、比べる二つが同じ種類になるように形をそろえる。\\n\\n■ 人を比べる\\n例）Ken is taller than Tom.\\n例）He is older than I am.（＝ than me）\\n例）She studies harder than her sister does.\\n\\nthan のあとは〈主語＋be動詞〉や〈主語＋do / does / did〉で受けるのが正式な形である。会話では than me のように目的格を使うことも多い。\\n\\n■ ものを比べる ─ one / ones\\n例）This bag is bigger than that one.（one＝bag）\\n例）These pencils are longer than those.\\n例）This question is easier than the last one.\\n\\n■ 所有を表す ─ mine / yours\\n例）My bag is bigger than yours.（yours＝your bag）\\n例）His house is newer than mine.\\n例）Her bike is more expensive than his.\\n\\n■ 動詞の繰り返し ─ do / does / did\\n例）He runs faster than I do.\\n例）She speaks English better than he does.\\n例）I got up earlier than my brother did.\\n\\n現在の文なら do / does、過去の文なら did を使う。\\n\\n★ ポイント：than のあとを見て「何と何を比べているか」が同じ種類になっているかを必ず確かめる。\",\"figureId\":\"xf_eigo_s253\"},{\"heading\":\"比較級にし忘れない\",\"body\":\"比較の文で意外に多い誤りが、than を書いたのに形容詞を原級のままにしてしまうことである。\\n\\n誤）This book is difficult than that one.\\n正）This book is more difficult than that one.\\n\\n誤）Today is hot than yesterday.\\n正）Today is hotter than yesterday.\\n\\nthan があるということは比べている文なので、必ず比較級にしなければならない。\\n\\n■ 逆に、比較級なのに than を落とす誤り\\n誤）This book is more difficult that one.\\n正）This book is more difficult than that one.\\n\\nthan と that を書きまちがえる誤りも多いので注意する。\\n\\n■ 比較級のあとに名詞が来る形\\n比較級は名詞の前に置くこともできる。\\n\\n例）I need a bigger bag.（もっと大きなかばんが必要だ）\\n例）He is a better player than me.\\n例）Do you have a smaller size?\\n\\n■ than のあとに文が続く形\\n例）This question is easier than I thought.（思っていたより簡単だ）\\n例）He came earlier than we expected.\\n\\n■ 語順の整理\\n〈主語＋動詞＋比較級＋than＋比べる相手〉\\n\\n⚠ 注意：than の直前が原級のままになっていないか、書き終えたら必ず見直す。\",\"mangaId\":\"eigo_s253_xm\"}],\"trapExamples\":[{\"question\":\"「この本はあの本より難しい。」を英語にしなさい。\",\"wrongAnswer\":\"This book is difficult than that one.\",\"trapExplanation\":\"than を書けば比べる意味になると思い、形容詞を比較級にするのを忘れてしまう。とくに more を使う長い語では、比較級にしたつもりでも more を落としがちである。\",\"correctAnswer\":\"This book is more difficult than that one.\",\"correctExplanation\":\"than がある文では、形容詞・副詞を必ず比較級にする。difficult は3音節の長い語なので more difficult となる。one は book の繰り返しをさけるための語である。\"},{\"question\":\"「私のかばんはあなたのより大きい。」を英語にしなさい。\",\"wrongAnswer\":\"My bag is bigger than your.\",\"trapExplanation\":\"your bag の bag を省略するところまで考えたが、your のままにしてしまう。your は後ろに名詞がないと使えない語である。\",\"correctAnswer\":\"My bag is bigger than yours.\",\"correctExplanation\":\"後ろに名詞を置かずに「あなたのもの」を表すときは所有代名詞 yours を使う。mine・yours・his・hers・ours・theirs がその形である。名詞を残して than your bag と書くこともできる。\"}]}",
"{\"id\":\"eigo_s254\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"much / far / a lot による比較級の強調\",\"description\":\"「ずっと〜だ」を表す比較級の強調と、very を使えないことを理解する\",\"intro\":\"「ずっと大きい」と強めたいとき、very bigger とは言えません。very は原級専用で、比較級を強めるときは much bigger のように much を使います。日本語ではどちらも「とても」「ずっと」でつながるので、まちがえやすい部分です。\",\"order\":754,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"比較級を強めるときは much / far / a lot を前に置く（much taller）。\",\"very は比較級を強めることができない（very taller は誤り）。\",\"very は原級を強める（very tall）。\",\"even / still も比較級を強められる（even better）。\",\"much は原級を強めることはできない（much tall は誤り）。\"],\"sections\":[{\"heading\":\"「ずっと〜だ」の表し方\",\"mangaId\":\"eigo_s254_manga\",\"body\":\"比較級に「ずっと・はるかに」という強めの意味を足したいときは、比較級の前に much・far・a lot を置く。\\n\\n例）He is much taller than me.（彼は私よりずっと背が高い）\\n例）This book is far more interesting than that one.（この本はあの本よりはるかにおもしろい）\\n例）This bag is a lot bigger than that one.\\n例）Today is much colder than yesterday.\\n\\n■ 使える語\\nmuch（ずっと）／far（はるかに）／a lot（ずっと）／even（さらに）／still（さらに）／a little（少し）\\n\\n例）This one is even better.（こちらのほうがさらによい）\\n例）This bag is a little heavier than that one.（少し重い）\\n\\n■ very は使えない\\nvery は比較級を強めることができない。\\n\\n誤）He is very taller than me.\\n正）He is much taller than me.\\n\\n■ very が使えるのは原級\\nvery は原級（もとの形）を強める語である。\\n\\n正）He is very tall.（彼はとても背が高い）\\n誤）He is much tall.\\n\\nmuch と very は使う場所が正反対だと覚えるとよい。\\n\\n★ ポイント：比較級には much、原級には very。この対応を反射的に出せるようにする。\",\"figureId\":\"lf_eigoext07_254\"},{\"heading\":\"最上級の強調と、much の他の使い方\",\"body\":\"■ 最上級を強めるときは by far / much\\n例）This is by far the best movie of the year.（これは今年断然いちばんの映画だ）\\n例）He is much the tallest in his class.（参考）\\n\\n中学入試では by far the best の形を知っていれば十分である。\\n\\n■ much の他の使い方\\n①数えられない名詞につく「たくさんの」\\n例）I don't have much time.\\n\\n②動詞を強める「とても」\\n例）I like it very much.（とても好きだ）\\n例）Thank you very much.\\n\\nこのときは very much の形で使う。much だけでは動詞を強められない。\\n\\n■ a lot の二つの使い方\\n①比較級の前で「ずっと」\\n例）This is a lot better.\\n\\n②動詞のあとで「たくさん」\\n例）He eats a lot.\\n\\n■ 整理して覚える\\n原級を強める：very（very tall）\\n比較級を強める：much / far / a lot / even（much taller）\\n動詞を強める：very much（like it very much）\\n最上級を強める：by far（by far the best）\\n\\n⚠ 注意：Thank you much. は誤りで Thank you very much. が正しい。much を単独で動詞の強調に使わない。\"},{\"heading\":\"なぜ very は比較級を強められないのか\",\"mangaId\":\"eigo_s254_verymuch_manga\",\"body\":\"very は「とても」と、**その性質の程度が高い**ことを表す語です。tall（背が高い）の程度を上げて very tall と言えます。ところが taller（〜より高い）は、程度ではなく**二つの差**を表す形です。差を強めるには「差が大きい」と言う必要があり、それを表すのが much・far・a lot（ずっと・はるかに）です。very は程度の語なので、差の形（比較級）には付けられません。逆に much は差の語なので、原級（tall）には付けられません。だから使う場所が正反対になります。\\n\\n最上級を強める by far も「他と比べて差が大きい」という意味で、比較級と同じ仲間です。動詞を強めるときに very much と二語になるのは、much だけでは動詞の程度を表せないからで、Thank you much. は誤りです。\\n\\n■ 確かめのしかた\\n①強めたい語が**原級か比較級か**を見る。原級→very（very tall）。比較級→much / far / a lot / even（much taller）。\\n②× very taller、× much tall になっていないか。\\n③最上級→by far（by far the best）。動詞→very much（like it very much）。\\n④a little（少し）も比較級に付く（a little heavier）。even は「さらに」（even better）。\\n\\n★ ここがポイント：very は**程度**、much は**差**を表す語なので、**原級には very、比較級には much**（very tall／much taller）。最上級は by far、動詞は very much。\"}],\"trapExamples\":[{\"question\":\"「彼は私よりずっと背が高い。」を英語にしなさい。\",\"wrongAnswer\":\"He is very taller than me.\",\"trapExplanation\":\"「ずっと」という強調の日本語に対して、いちばんよく知っている強調語 very を使ってしまう。very が原級専用の強調語であることを意識していない。\",\"correctAnswer\":\"He is much taller than me.\",\"correctExplanation\":\"比較級を強めるときは much・far・a lot・even を使う。very は比較級を強められない。逆に very tall（とても背が高い）は正しく、much tall は誤りである。強める場所によって語が決まっている。\"},{\"question\":\"「彼はとても背が高い。」を英語にしなさい。\",\"wrongAnswer\":\"He is much tall.\",\"trapExplanation\":\"「much は強調の語」と覚えたばかりのときに、原級にも使えると考えてしまう。比較級専用の強調語であることを取りちがえている。\",\"correctAnswer\":\"He is very tall.\",\"correctExplanation\":\"原級（もとの形）を強めるのは very である。much は比較級を強めるための語なので、原級に付けることはできない。〈very＋原級〉〈much＋比較級〉という対応で覚える。\"}]}",
"{\"id\":\"eigo_s255\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較級 and 比較級 ─ 「だんだん〜」\",\"description\":\"同じ比較級を and でつないで変化が進むことを表す形を身につける\",\"intro\":\"It is getting hotter and hotter. は「だんだん暑くなってきている」という意味です。同じ比較級を and でつなぐと、変化が進んでいく様子を表せます。日本語の「だんだん」にあたる一語を探しても出てきません。形をくり返すことで表現するのです。\",\"order\":755,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"〈比較級＋and＋比較級〉で「だんだん〜、ますます〜」を表す。\",\"-er 型は hotter and hotter のように比較級を二回くり返す。\",\"more 型は more and more popular（more だけをくり返す）。\",\"get / become とともに使うことが多い（It is getting colder and colder.）。\",\"原級をくり返す hot and hot は誤り。\"],\"sections\":[{\"heading\":\"基本の形\",\"body\":\"同じ比較級を and でつなぐと「だんだん〜、ますます〜」という変化の進行を表す。\\n\\n■ -er 型の場合 ─ 比較級を二回くり返す\\n例）It is getting hotter and hotter.（だんだん暑くなってきている）\\n例）The days are getting shorter and shorter.（日がだんだん短くなっている）\\n例）He became stronger and stronger.\\n例）The rain got heavier and heavier.\\n\\n■ more 型の場合 ─ more だけをくり返す\\n例）This song is getting more and more popular.（この歌はますます人気が出てきている）\\n例）The problem became more and more difficult.\\n例）She is getting more and more beautiful.\\n\\n正）more and more popular\\n誤）more popular and more popular\\n誤）more popular and popular\\n\\nmore の部分だけをくり返すのが規則である。\\n\\n■ 原級をくり返さない\\n誤）It is getting hot and hot.\\n正）It is getting hotter and hotter.\\n\\n■ よく使う動詞\\nget（〜になる）／become（〜になる）／grow（〜になる）\\n\\n例）It is getting darker and darker.（だんだん暗くなってきた）\\n例）The city grew bigger and bigger.\\n\\n★ ポイント：右の図のように、時間とともに一定の方向へ変化が進む場面で使う表現である。\",\"figureId\":\"lf_eigoext07_255\",\"mangaId\":\"eigo_s255_xm\"},{\"heading\":\"似た形の表現\",\"body\":\"■ more and more＋名詞\\n「ますます多くの〜」という意味で名詞に付けることもできる。\\n\\n例）More and more people are using smartphones.（ますます多くの人がスマートフォンを使っている）\\n例）More and more students study English.\\n\\nこのときの more は many の比較級である。\\n\\n■ less and less\\n「ますます少なく」を表す。\\n\\n例）He has less and less time.（彼はますます時間がなくなっている）\\n\\n■ 不規則変化の語では\\nbetter and better（ますますよく）／worse and worse（ますます悪く）\\n\\n例）His English is getting better and better.（彼の英語はどんどん上達している）\\n例）The weather got worse and worse.（天気はどんどん悪くなった）\\n\\n■ 進行形と組み合わせる\\n変化の途中であることを表すため、be getting のように進行形にすることが多い。\\n\\n例）It is getting colder and colder.（だんだん寒くなってきている）\\n例）The line is getting longer and longer.\\n\\n■ 過去の文\\n例）It got hotter and hotter.（だんだん暑くなった）\\n例）The music became louder and louder.\\n\\n⚠ 注意：more 型の語では more and more popular のように、形容詞は最後に一度だけ書く。二回書かないこと。\"}],\"trapExamples\":[{\"question\":\"「その歌はますます人気が出てきている。」を英語にしなさい。\",\"wrongAnswer\":\"The song is getting more popular and more popular.\",\"trapExplanation\":\"-er 型の hotter and hotter をまねて、比較級のかたまりをそのまま二回くり返してしまう。more 型では more だけをくり返すという規則を知らないと引っかかる。\",\"correctAnswer\":\"The song is getting more and more popular.\",\"correctExplanation\":\"more を使う長い語では、more and more＋形容詞の形にする。形容詞は最後に一度だけ書く。more and more difficult、more and more beautiful も同じ形である。-er 型なら hotter and hotter のように比較級を二回くり返す。\"},{\"question\":\"「だんだん暖かくなってきた。」を英語にしなさい。\",\"wrongAnswer\":\"It is getting warm and warm.\",\"trapExplanation\":\"「暖かく、暖かく」という日本語のくり返しの感覚から、原級をそのまま二回ならべてしまう。変化を表すには比較級でなければならないことに気づかない。\",\"correctAnswer\":\"It is getting warmer and warmer.\",\"correctExplanation\":\"「だんだん〜」を表すときは比較級をくり返す。warm の比較級は warmer なので warmer and warmer となる。原級をならべた warm and warm は誤りである。get や become とともに使うことが多い。\"}]}",
"{\"id\":\"eigo_s256\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較級を使った疑問文 ─ Which is bigger, A or B?\",\"description\":\"二つを比べてたずねる疑問文の形と、答え方を身につける\",\"intro\":\"「富士山と高尾山では、どちらが高いですか」は Which is higher, Mt. Fuji or Mt. Takao? です。二つを比べてたずねるときは Which を使い、最後に or でならべます。答えるときは Yes や No ではなく、えらんだほうを言います。\",\"order\":756,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"2つを比べてたずねるときは比較級を使う（Which is bigger, A or B?）。\",\"3つ以上なら最上級を使う（Which is the biggest of the three?）。\",\"A と B は or でつなぐ（and ではない）。\",\"人についてたずねるときは Who を使う（Who is taller, Ken or Tom?）。\",\"答えは A is. / I like A better. のように短く答えられる。\"],\"sections\":[{\"heading\":\"疑問文の作り方\",\"body\":\"二つのものを比べて「どちらが〜ですか」とたずねるときは、疑問詞のあとに比較級を置く。\\n\\n■ 基本の形\\n〈Which is＋比較級, A or B?〉\\n\\n例）Which is bigger, Japan or Australia?（日本とオーストラリアではどちらが大きいですか）\\n　　— Australia is.（オーストラリアです）\\n例）Which is longer, the Shinano River or the Tone River?\\n例）Which is more useful, this book or that one?\\n\\n■ 人についてたずねるときは Who\\n例）Who is taller, Ken or Tom?（ケンとトムではどちらが背が高いですか）\\n　　— Ken is.\\n例）Who runs faster, you or your brother?\\n　　— I do.\\n\\n■ A と B は or でつなぐ\\n二つのうちどちらか一方を選んでもらうので、必ず or を使う。\\n\\n正）Which do you like better, spring or fall?\\n誤）Which do you like better, spring and fall?\\n\\n■ 一般動詞の疑問文\\n例）Which do you like better, tea or coffee?（お茶とコーヒーではどちらが好きですか）\\n　　— I like tea better.\\n例）Which do you use more often, a pencil or a pen?\\n\\n★ ポイント：比べるのが2つなら比較級、3つ以上なら最上級。文中の or の前後にいくつあるかを数えて判断する。\",\"figureId\":\"xf_eigo_s256\",\"mangaId\":\"eigo_s256_xm\"},{\"heading\":\"答え方と、最上級の疑問文との区別\",\"body\":\"■ 答え方\\nbe動詞の文なら〈主語＋is / are.〉、一般動詞の文なら〈主語＋do / does.〉で答えられる。\\n\\n例）Which is bigger, Japan or Australia? — Australia is.\\n例）Who runs faster, Ken or Tom? — Ken does.\\n例）Which do you like better, dogs or cats? — I like dogs better.\\n\\n「I like dogs.」だけでも通じるが、better を付けると比較の答えとしてより正確になる。\\n\\n■ 3つ以上のときは最上級\\n例）Which is the biggest of the three?（3つの中でどれがいちばん大きいですか）\\n例）Which season do you like the best, spring, summer, fall or winter?\\n　　— I like summer the best.\\n\\nor の前後に三つ以上ならんでいたら最上級である。\\n\\n■ 比較級と最上級の使い分けの練習\\nWhich is longer, this pencil or that one?（2つ → 比較級）\\nWhich is the longest of the three pencils?（3つ → 最上級）\\n\\n■ How で程度をたずねる\\n例）How tall is he?（彼はどれくらいの背の高さですか）\\n例）How old is your sister?\\n\\nこれらは比較の形ではないが、程度をたずねる表現としてあわせて覚えておく。\\n\\n⚠ 注意：Which do you like better, A and B? のように and を使う誤りが多い。選択をたずねる疑問文では or である。\"}],\"trapExamples\":[{\"question\":\"「日本とオーストラリアではどちらが大きいですか。」を英語にしなさい。\",\"wrongAnswer\":\"Which is the biggest, Japan or Australia?\",\"trapExplanation\":\"「どちらが大きいですか」という日本語から「いちばん大きい」という最上級のイメージを持ってしまう。比べているのが2つだけであることを確かめていない。\",\"correctAnswer\":\"Which is bigger, Japan or Australia?\",\"correctExplanation\":\"比べる対象が2つのときは比較級を使う。最上級を使うのは3つ以上のときである。or の前後にいくつならんでいるかを数えれば判断できる。答えは Australia is. となる。\"},{\"question\":\"「あなたは春と秋ではどちらが好きですか。」を英語にしなさい。\",\"wrongAnswer\":\"Which do you like better, spring and fall?\",\"trapExplanation\":\"日本語の「春と秋」の「と」をそのまま and に置きかえてしまう。選択をたずねる疑問文では or を使うという決まりを知らないと必ずまちがえる。\",\"correctAnswer\":\"Which do you like better, spring or fall?\",\"correctExplanation\":\"どちらか一方を選んでもらう疑問文では or でつなぐ。and を使うと「春と秋の両方」という意味になってしまう。答えは I like spring better. のように better を付けて答える。\"}]}",
"{\"id\":\"eigo_s257\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"最上級の in と of の使い分け\",\"description\":\"最上級の範囲を示す前置詞 in と of を、意味のちがいから正しく選べるようにする\",\"intro\":\"the tallest in my class と the tallest of the three。同じ「〜の中で」なのに in と of に分かれます。境目は、場所や集団の範囲を表すのか、数や仲間をならべているのか。日本語の「で」「の中で」からは、まったく区別できないところです。\",\"order\":757,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"in＋場所や集団（範囲を一つのまとまりとして表す）：in Japan, in my class, in the world。\",\"of＋比べる仲間の集まり（数や all）：of the three, of all, of us, of the four。\",\"of のあとは複数を表す語が来る。in のあとは単数の場所・集団が来る。\",\"in my family / in my school は集団なので in。\",\"of the year / of the day のように期間を全体としてとらえる形もある。\"],\"sections\":[{\"heading\":\"in と of の見分け方\",\"mangaId\":\"eigo_s257_manga\",\"body\":\"最上級の文では「どの範囲でいちばんか」を in か of で示す。この使い分けが入試の定番である。\\n\\n■ in＋場所・集団（ひとまとまりの範囲）\\nin Japan（日本で）／in the world（世界で）／in my class（私のクラスで）／in my family（私の家族で）／in this town（この町で）／in our school（私たちの学校で）\\n\\n例）Mt. Fuji is the highest mountain in Japan.\\n例）He is the tallest boy in his class.\\n例）This is the oldest building in this town.\\n\\n■ of＋比べる仲間の集まり（数を表す語や all）\\nof the three（3つの中で）／of the five（5人の中で）／of all（すべての中で）／of us（私たちの中で）／of the four seasons（四季の中で）\\n\\n例）Ken is the tallest of the three.\\n例）This is the best of all.\\n例）Which do you like the best of the four seasons?\\n\\n■ 見分け方\\nof のあとには「複数」や「数を表す語」が来る。in のあとには単数形の場所や集団が来る。\\n\\nof the three（three＝数）→ of\\nin my class（class＝集団の単数）→ in\\n\\n★ ポイント：あとに来る語が「数・all・us」なら of、「場所・クラス・国・世界」なら in、と覚える。\",\"figureId\":\"lf_eigoext07_257\"},{\"heading\":\"まちがえやすい組み合わせ\",\"body\":\"■ my class は集団だが単数 → in\\n「クラスの中で」は人が何人もいるので of と思いがちだが、class という一つのまとまりを範囲としているので in を使う。\\n\\n正）He is the fastest in my class.\\n誤）He is the fastest of my class.\\n\\n同じく in my family、in our school、in the group となる。\\n\\n■ all the students は複数 → of\\n複数形の名詞が並ぶときは of を使う。\\n\\n正）He is the tallest of all the students.\\n例）She is the youngest of the five children.\\n\\n■ 期間を表すとき\\nof the year（1年で）／of the day（1日で）／of the week（1週間で）\\n\\n例）Today is the hottest day of the year.（今日は1年でいちばん暑い日だ）\\n例）This is the busiest time of the day.\\n\\n■ in の代表例をまとめて\\nin Japan／in the world／in Asia／in my class／in my family／in this city／in our school／in the group\\n\\n■ of の代表例をまとめて\\nof the three／of the four／of all／of us／of them／of all the students／of the year\\n\\n■ 副詞の最上級でも同じ\\n例）He runs fastest of the three.\\n例）She sings best in her school.\\n\\n⚠ 注意：「3人の中で」を in the three としない。数を表す語の前は of である。\"}],\"trapExamples\":[{\"question\":\"「彼は3人の中でいちばん背が高い。」を英語にしなさい。\",\"wrongAnswer\":\"He is the tallest in the three.\",\"trapExplanation\":\"「〜の中で」という日本語から、範囲を表す in を選んでしまう。in と of の使い分けの基準が、あとに来る語の性質で決まることを意識していない。\",\"correctAnswer\":\"He is the tallest of the three.\",\"correctExplanation\":\"数を表す語（the three、the five、all、us）が続くときは of を使う。in を使うのは in Japan、in my class のように場所や集団を一つのまとまりとして表すときである。\"},{\"question\":\"「富士山は日本でいちばん高い山だ。」を英語にしなさい。\",\"wrongAnswer\":\"Mt. Fuji is the highest mountain of Japan.\",\"trapExplanation\":\"「日本の山の中で」と考えて、山という複数の仲間を想定し of を選んでしまう。しかし文の中で範囲を示しているのは Japan という場所である。\",\"correctAnswer\":\"Mt. Fuji is the highest mountain in Japan.\",\"correctExplanation\":\"場所を表す語が範囲になるときは in を使う。in Japan、in the world、in this town、in my class がその例である。of を使うのは of the three、of all のように数や仲間の集まりが続くときである。\"}]}",
"{\"id\":\"eigo_s258\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"one of the ＋ 最上級 ＋ 複数名詞\",\"description\":\"「もっとも〜な…の一つ」を表す形と、主語になったときの動詞の形を身につける\",\"intro\":\"「もっとも有名な選手の一人」は one of the most famous players です。ここで players と複数にすることに注意します。「一人」と言っているのに複数形、という日本語の感覚と合わない形です。主語になったときの動詞の形もあわせて確かめます。\",\"order\":758,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"〈one of the＋最上級＋複数名詞〉で「もっとも〜な…の一つ」を表す。\",\"名詞は必ず複数形（one of the highest mountains）。\",\"one of ~ が主語のときは単数あつかい（One of my friends lives in Osaka.）。\",\"「一人」でも複数形にする点が日本語の感覚とちがう。\",\"in / of による範囲の示し方は最上級の規則と同じ。\"],\"sections\":[{\"heading\":\"基本の形と複数形\",\"body\":\"「日本でもっとも高い山の一つ」のような言い方は、〈one of the＋最上級＋複数名詞〉で表す。\\n\\n例）Mt. Kita is one of the highest mountains in Japan.（北岳は日本でもっとも高い山の一つだ）\\n例）He is one of the most famous singers in Japan.\\n例）This is one of the oldest temples in Kyoto.\\n例）Kyoto is one of the most popular cities in Japan.\\n\\n■ 名詞は必ず複数形\\n「一つ」と言っているので単数形にしたくなるが、英語では「高い山たちのうちの一つ」と考えるので複数形になる。\\n\\n正）one of the highest mountains\\n誤）one of the highest mountain\\n\\n正）one of the most famous singers\\n誤）one of the most famous singer\\n\\nof は「〜のうちの」を表す語なので、そのあとには必ず二つ以上のものが来る。one of the students、one of my friends も同じである。\\n\\n■ 範囲の示し方\\n最上級と同じく in / of を使う。\\n\\n例）one of the tallest buildings in the world\\n例）one of the best players of all\\n\\n★ ポイント：「一つ」でも複数形。この一点が入試の出題ねらいである。書き終えたら名詞に s が付いているかを確かめる。\",\"figureId\":\"lf_eigoext07_258\"},{\"heading\":\"主語になったときの動詞\",\"body\":\"one of ~ が主語になるとき、動詞は単数の形にする。主語の中心は「one（一つ）」だからである。\\n\\n正）One of my friends lives in Osaka.（友達の一人が大阪に住んでいる）\\n誤）One of my friends live in Osaka.\\n\\n正）One of the students is absent today.\\n誤）One of the students are absent today.\\n\\n直前の複数名詞（friends、students）に引かれて複数の動詞にしてしまう誤りが非常に多い。\\n\\n■ 見分け方\\n主語の中心になる語を探す。One of my friends の中心は One なので単数である。\\n\\n■ 最上級と組み合わせた例\\n例）One of the highest mountains in Japan is Mt. Kita.\\n例）One of the most difficult subjects is math.\\n\\n■ each of / every one of も同じ\\n例）Each of the boys has a bike.\\n例）Every one of them was happy.\\n\\nいずれも中心の語が単数なので、動詞も単数の形になる。\\n\\n■ 書きかえの練習\\nMt. Fuji is the highest mountain in Japan.（いちばん高い）\\nMt. Kita is one of the highest mountains in Japan.（高い山の一つ）\\n\\n「いちばん」なのか「〜の一つ」なのかで、名詞の形が変わる点を確かめておく。\\n\\n⚠ 注意：of のあとに複数名詞、動詞は単数。この二つが同時に問われることが多い。\",\"mangaId\":\"eigo_s258_xm\"}],\"trapExamples\":[{\"question\":\"「彼は日本でもっとも有名な歌手の一人だ。」を英語にしなさい。\",\"wrongAnswer\":\"He is one of the most famous singer in Japan.\",\"trapExplanation\":\"日本語の「歌手の一人」が単数なので、英語でも singer を単数形にしてしまう。one という語に引かれて、後ろの名詞まで単数にしてしまう典型的な誤りである。\",\"correctAnswer\":\"He is one of the most famous singers in Japan.\",\"correctExplanation\":\"〈one of the＋最上級＋複数名詞〉の形では、名詞を必ず複数形にする。of は「〜のうちの」という意味なので、そのあとには二つ以上のものが来なければならない。one of the highest mountains も同じである。\"},{\"question\":\"（　）に live か lives を入れなさい。One of my friends（　）in Osaka.\",\"wrongAnswer\":\"One of my friends live in Osaka.\",\"trapExplanation\":\"動詞の直前にある friends が複数形なので、そのまま複数の動詞 live を選んでしまう。主語の中心がどの語かを確かめていない。\",\"correctAnswer\":\"One of my friends lives in Osaka.\",\"correctExplanation\":\"主語の中心は One なので単数あつかいになり、動詞は lives となる。直前の複数名詞に引かれないよう、主語の中心語を探す習慣をつける。One of the students is absent. も同じ考え方である。\"}]}",
"{\"id\":\"eigo_s259\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"最上級を使った疑問文と like ~ the best\",\"description\":\"「どれがいちばん〜ですか」の形と答え方、および疑問詞が主語になる文の動詞を確認する\",\"intro\":\"「どの季節がいちばん好きですか」は Which season do you like the best? です。答えは I like spring the best. となります。like と best をはなして置くこの形は、日本語の語順とはかなりちがいます。決まった型として覚えてしまいましょう。\",\"order\":759,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"〈Which / What＋名詞＋do you like the best?〉で「どれがいちばん好きですか」。\",\"3つ以上の中から選ぶときは the best、2つなら better。\",\"Who が主語のときは三人称単数あつかい（Who runs the fastest?）。\",\"Which is the 最上級＋名詞＋in / of ~? の形も頻出。\",\"答えは I like ~ the best. / ~ is. のように答える。\"],\"sections\":[{\"heading\":\"「いちばん〜なのはどれ」の疑問文\",\"body\":\"三つ以上の中からいちばんのものをたずねるときは、最上級を使った疑問文を作る。\\n\\n■ Which を使う形\\n例）Which is the longest river in Japan?（日本でいちばん長い川はどれですか）\\n　　— The Shinano River is.\\n例）Which is the biggest of the three?\\n例）Which season do you like the best?（どの季節がいちばん好きですか）\\n　　— I like spring the best.\\n\\n■ What を使う形\\n選ぶ範囲が限られていないときは What を使う。\\n\\n例）What sport do you like the best?（何のスポーツがいちばん好きですか）\\n　　— I like soccer the best.\\n例）What is the most popular sport in your school?\\n\\nWhich は限られた選択肢の中から、What は範囲を決めずにたずねるときに使う。\\n\\n■ Who を使う形\\n例）Who is the tallest in your class?（クラスでいちばん背が高いのはだれですか）\\n　　— Ken is.\\n例）Who runs the fastest of the three?\\n　　— Tom does.\\n\\n■ like ~ the best\\n3つ以上の中でいちばん好きと言うときは the best を使う。2つを比べるときは better である。\\n\\n例）I like summer the best of the four seasons.\\n例）I like tea better than coffee.（2つ）\\n\\n★ ポイント：選択肢がいくつあるかを数えてから、better か the best かを決める。\",\"figureId\":\"xf_eigo_s259\"},{\"heading\":\"疑問詞が主語になる文\",\"body\":\"Who・What・Which が主語になるとき、その疑問文は〈疑問詞＋動詞 ~?〉という語順になり、do / does を使わない。\\n\\n例）Who runs the fastest in your class?（だれがいちばん速く走りますか）\\n例）Who speaks English the best?\\n例）What makes you happy?\\n\\n■ 動詞は三人称単数あつかい\\n主語になった疑問詞は三人称単数として扱うので、現在の文では動詞に s が付く。\\n\\n正）Who speaks English the best in your class?\\n誤）Who speak English the best in your class?\\n\\n■ do を使う形との区別\\n主語が you や he のように別にあるときは、do / does を使う。\\n\\n例）Who do you like the best?（あなたはだれがいちばん好きですか）← 主語は you\\n例）Who likes this song the best?（だれがこの歌をいちばん好きですか）← 主語は Who\\n\\n前者は「あなたが」だれを好きかを問い、後者は「だれが」好きかを問う。\\n\\n■ 答え方\\n例）Who runs the fastest? — Ken does.\\n例）Who is the tallest? — Tom is.\\n例）Which do you like the best? — I like this one the best.\\n\\n■ How で程度をたずねる形もあわせて\\n例）How tall is he? — He is 160 centimeters tall.\\n\\n⚠ 注意：Who が主語のときは do を入れない。Who does run fastest? は誤りである。\",\"mangaId\":\"eigo_s259_xm\"}],\"trapExamples\":[{\"question\":\"「あなたはどの季節がいちばん好きですか。」を英語にしなさい。\",\"wrongAnswer\":\"Which season do you like better?\",\"trapExplanation\":\"「好き」を比べる文で better を使う形を覚えていると、選択肢の数を確かめずに better を選んでしまう。季節は四つあるので最上級でなければならない。\",\"correctAnswer\":\"Which season do you like the best?\",\"correctExplanation\":\"3つ以上の中からいちばんを選ぶときは the best を使う。2つを比べるときだけ better である。答えは I like spring the best. となる。of the four seasons を加えて範囲を示すこともできる。\"},{\"question\":\"「だれがあなたのクラスでいちばん上手に英語を話しますか。」を英語にしなさい。\",\"wrongAnswer\":\"Who speak English the best in your class?\",\"trapExplanation\":\"Who が主語のときの動詞の形をあいまいに覚えており、原形のままにしてしまう。疑問文だから動詞は原形、という思いこみも働く。\",\"correctAnswer\":\"Who speaks English the best in your class?\",\"correctExplanation\":\"疑問詞 Who が主語になるときは三人称単数あつかいになるので、現在の文では動詞に s を付ける。また do / does は使わず〈疑問詞＋動詞〉の語順になる。答えは Ken does. のように does で受ける。\"}]}",
"{\"id\":\"eigo_s260\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"総合演習 ─ 形容詞・副詞・比較のまとめ\",\"description\":\"このユニットで学んだ内容を、表やグラフを読み取って英文にする形で総復習する\",\"intro\":\"表やグラフを見て、「AはBより高い」「Cがいちばん安い」と英語で言えるでしょうか。比較の表現は、資料を読み取って説明する場面でこそ力を発揮します。ここまでに学んだ原級・比較級・最上級を、実際の数値を使ってまとめて確かめます。\",\"order\":760,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"比較級には than、最上級には the と in / of がセットで必要。\",\"as と as の間は必ず原級。not as ~ as は「〜ほど…ない」。\",\"比較級を強めるのは much / far / a lot。原級を強めるのは very。\",\"タイムや順位のグラフでは「数値が小さい＝速い」など読みかえに注意する。\",\"不規則変化 good/well→better→best、bad→worse→worst、many/much→more→most を最終確認。\"],\"sections\":[{\"heading\":\"グラフを英文にする\",\"body\":\"入試では表やグラフを読み取って英文を選ぶ問題が出る。次の50メートル走のタイムを例に練習する。\\n\\nケン 8.0秒／トム 8.5秒／サム 9.0秒\\n\\nこのデータから作れる英文は次のとおりである。\\n\\n例）Ken runs the fastest of the three.（ケンが3人の中でいちばん速い）\\n例）Sam runs the slowest of the three.\\n例）Tom runs faster than Sam.（トムはサムより速い）\\n例）Sam doesn't run as fast as Ken.（サムはケンほど速く走らない）\\n例）Ken's time is the shortest of the three.（ケンのタイムがいちばん短い）\\n\\n■ 数値の読みかえに注意\\nタイムは「数値が小さいほど速い」ため、グラフの棒が短い人がいちばん速い。数値の大小と速さの大小が逆になるので、ここで取りちがえる受験生が多い。\\n\\n反対に身長や体重のグラフでは、数値が大きいほど tall・heavy になる。\\n\\n■ 書きかえの確認\\nKen runs faster than Tom. ＝ Tom doesn't run as fast as Ken.\\nKen runs the fastest of the three. ＝ No one runs faster than Ken. （参考）\\n\\n★ ポイント：グラフ問題では、まず日本語で「だれがいちばん〜か」を確かめてから英文を作る。\",\"figureId\":\"lf_eigoext07_260\",\"mangaId\":\"eigo_s260_xm\"},{\"heading\":\"総まとめのチェックリスト\",\"body\":\"このユニットで学んだ内容を、確認の順に整理する。\\n\\n■ 形容詞\\n①名詞の前に置く（a big dog）。冠詞・所有格はさらに前（my new bike）。\\n②be動詞・look・sound のあとに置く（You look happy.）。副詞にしない。\\n③something を説明する形容詞は後ろ（something cold to drink）。\\n\\n■ 数量の形容詞\\nmany＋複数形／much＋数えられない名詞／a lot of は両方に使える。\\na few・a little＝少しある／few・little＝ほとんどない。\\nsome は肯定文、any は疑問文・否定文。すすめる疑問文では some。\\nevery・each は単数あつかい。all・both は複数あつかい。\\n\\n■ 副詞\\n形容詞に -ly を付けて作る（easy → easily）。fast・hard・early は同じ形。\\nhard（熱心に）と hardly（ほとんど〜ない）は別の語。\\n語順は〈動詞＋目的語＋副詞〉、〈様態→場所→時〉。\\n頻度の副詞は be動詞・助動詞のあと、一般動詞の前。\\n\\n■ 比較\\n比較級＋than／the＋最上級＋in・of。\\n短い語は -er / -est、長い語は more / most。\\nつづり変化：large → larger／easy → easier／big → bigger。\\n不規則変化：good・well → better → best／bad → worse → worst／many・much → more → most／little → less → least／far → farther → farthest。\\nas ~ as は原級。not as ~ as は「〜ほど…ない」。\\nmuch・far・a lot は比較級を強め、very は原級を強める。\\none of the＋最上級＋複数名詞。動詞は単数。\\n\\n⚠ 注意：答案を書き終えたら、①than・the が抜けていないか、②as と as の間が原級か、③名詞の単数複数は正しいか、の三点を必ず見直す。\"}],\"trapExamples\":[{\"question\":\"50メートル走のタイムはケン8.0秒、トム8.5秒、サム9.0秒だった。「ケンは3人の中でいちばん速い」を英語にしなさい。\",\"wrongAnswer\":\"Ken is the faster of the three.\",\"trapExplanation\":\"比べているという意識から比較級 faster を選び、さらに the を付けてしまう。3人を比べていることを数えていないうえ、〈the＋比較級〉という存在しない形を作っている。\",\"correctAnswer\":\"Ken runs the fastest of the three.（= Ken is the fastest of the three.）\",\"correctExplanation\":\"3人以上を比べるときは最上級を使う。fast の最上級は fastest で、前に the を付ける。範囲は数を表す語なので of the three となる。2人だけなら Ken is faster than Tom. のように比較級を使う。\"},{\"question\":\"「サムはケンほど速く走らない。」を英語にしなさい。\",\"wrongAnswer\":\"Sam doesn't run as faster as Ken.\",\"trapExplanation\":\"「速く走らない」という比較の文なので、as と as の間にも比較級を入れなければならないと考えてしまう。否定文にしたことで比較級が必要だと思いこむ誤りである。\",\"correctAnswer\":\"Sam doesn't run as fast as Ken.\",\"correctExplanation\":\"as と as の間に入るのは、肯定でも否定でも必ず原級である。not as ~ as は「〜ほど…ない」という意味で、as のあとのケンのほうが速いことを表す。比較級で書きかえると Ken runs faster than Sam. となる。\"}]}",
"{\"id\":\"eigo_s261\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時の前置詞①：at・on・in を「幅」で選ぶ\",\"description\":\"時刻には at、日には on、月や年には in。時間の幅の大きさで前置詞が決まることを理解する\",\"intro\":\"「7時に」「日曜日に」「4月に」——日本語はどれも「に」ですみます。ところが英語は at seven、on Sunday、in April と、三つに分かれます。えらび方の手がかりは、その時間の「はば」の大きさです。せまいほど at、広いほど in になります。\",\"order\":761,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"at ＝ 時刻のように「一点」と見る時間（at seven, at noon, at night）。\",\"on ＝ 日・曜日・日付のように「一日」の時間（on Monday, on May 5）。\",\"in ＝ 月・季節・年・世紀のように「広がりのある」時間（in May, in summer, in 2026）。\",\"幅の順は at ＜ on ＜ in。せまいほど at、広いほど in と覚える。\",\"in the morning / in the afternoon / in the evening は in、at night だけ at。\"],\"sections\":[{\"heading\":\"時間の幅で三つを選び分ける\",\"body\":\"英語では「いつ」を表すとき、その時間をどれくらいの大きさで見ているかによって前置詞が変わる。日本語ではどれも「〜に」で済んでしまうので、ここが中学受験の英語でいちばん点差のつくところである。\\n\\n■ at ＝ 一点として見る時間\\n時計の針が指す一瞬をイメージする。\\n例）at six o'clock（六時に）／at noon（正午に）／at midnight（真夜中に）／at night（夜に）／at that time（そのとき）\\n\\n■ on ＝ 一日として見る時間\\nカレンダーの一マスをイメージする。曜日・日付・特定の日はすべて on。\\n例）on Monday（月曜日に）／on May 5（五月五日に）／on my birthday（私の誕生日に）／on New Year's Day（元日に）\\n\\n■ in ＝ 広がりのある時間\\n月・季節・年・世紀のように、何日も何か月も続く長い時間は in。\\n例）in May（五月に）／in summer（夏に）／in 2026（二〇二六年に）／in the 21st century（二十一世紀に）\\n\\n★ ポイント：at（点）→ on（一日）→ in（広がり）と、右に行くほど時間の幅が大きくなる。まず「これはどれくらいの長さの時間か」を考えれば、ほとんどの問題は解ける。\",\"figureId\":\"lf_eigoext08_261\",\"mangaId\":\"eigo_s261_xm\"},{\"heading\":\"幅で決められない例外を覚える\",\"body\":\"幅の考え方でうまくいかないものが少しだけある。数が少ないので、そのまま覚えてしまうのが早い。\\n\\n■ 一日の時間帯は in だが、night だけ at\\n例）in the morning（朝に）／in the afternoon（午後に）／in the evening（夕方に）／at night（夜に）\\n「夜」も何時間もあるのに at を使う。昔の人が「夜＝暗い一点」として感じていた名残と考えて、at night だけは特別だと覚える。\\n\\n■ 「〜の日の朝」は on になる\\nmorning でも「五月五日の朝」のように日付が付くと、その日一日をさす扱いになって on に変わる。\\n例）on the morning of May 5（五月五日の朝に）／on a rainy morning（ある雨の朝に）\\n\\n■ 食事の時間は at\\n例）at breakfast（朝食のときに）／at lunch／at dinner\\n\\n⚠ 注意：日本語の「五月に」「五月五日に」はどちらも「に」だが、英語では in May と on May 5 で前置詞が変わる。日付が付いた瞬間に in から on へ切りかわると覚えておく。\"}],\"trapExamples\":[{\"question\":\"「私は五月五日に生まれました。」を英語にしなさい。\",\"wrongAnswer\":\"I was born in May 5.\",\"trapExplanation\":\"「五月に＝in May」と習ったばかりなので、日付が付いても同じ in を使ってしまう。日本語ではどちらも「五月に」「五月五日に」と同じ「に」なので、区別する手がかりがない。\",\"correctAnswer\":\"I was born on May 5.\",\"correctExplanation\":\"月だけなら幅が広いので in May、日付まで決まると「一日」になるので on May 5 となる。in May 5 という言い方は存在しない。「日付・曜日・特定の日はすべて on」と覚え、May 5 / Monday / my birthday / New Year's Day はまとめて on の仲間に入れておく。\"},{\"question\":\"「私たちは夜に星を見ました。」の空所に入る語を答えなさい。　We saw the stars (　) night.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"in the morning・in the afternoon・in the evening を先に覚えているため、同じ仲間だと考えて in the night としてしまう。\",\"correctAnswer\":\"at\",\"correctExplanation\":\"一日の時間帯のうち night だけは at night という形をとる。しかも the が付かない点も要注意で、at the night とは言わない。「朝・昼・夕方は in ＋ the、夜だけ at night」と、セットで声に出して覚えるのが確実である。\"}]}",
"{\"id\":\"eigo_s262\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時の前置詞②：on を使う場合を確実にする\",\"description\":\"曜日・日付・特定の日・「〜の日の朝」など、on を使う時の表現を整理する\",\"intro\":\"「日曜日に」は on Sunday、「4月1日に」は on April 1、「クリスマスの朝に」は on Christmas morning です。朝なのに in the morning ではなく on になります。特定の日と結びついたとたん、前置詞が on に乗りかえるのです。ここがよく問われます。\",\"order\":762,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"曜日は on Monday。複数の曜日をまとめて言うときは on Mondays（毎週月曜に）。\",\"日付は on April 1 / on the first of April。\",\"特定の日は on my birthday, on Christmas Day, on New Year's Day。\",\"「〜曜日の朝」「〜日の朝」は in ではなく on Sunday morning / on the morning of May 5。\",\"週末は on weekends（アメリカ英語）／at the weekend（イギリス英語）。入試では on weekends を覚えておけばよい。\"],\"sections\":[{\"heading\":\"on を使う四つのグループ\",\"body\":\"on を使う時の表現は、次の四つに整理できる。どれも「カレンダーの一マス＝一日」に関係している。\\n\\n■ ①曜日\\n例）on Monday（月曜日に）／on Sunday（日曜日に）\\n複数形にすると「毎週〜曜日に」の意味になる。\\n例）I play tennis on Sundays.（私は毎週日曜日にテニスをします。）\\n\\n■ ②日付\\n例）on May 5（五月五日に）／on the fifth of May（同じ意味の別の言い方）\\nアメリカ式では「月→日」の順に書き、May 5 と書いて May fifth と読む。\\n\\n■ ③特定の日・記念日\\n例）on my birthday（私の誕生日に）／on Christmas Day（クリスマスの日に）／on New Year's Day（元日に）／on that day（その日に）／on the last day of school（学校の最終日に）\\n\\n■ ④「〜の日の朝・昼・夜」\\nmorning・afternoon・evening・night も、どの日かがはっきり決まると on になる。\\n例）on Sunday morning（日曜日の朝に）／on the morning of May 5（五月五日の朝に）／on a cold night（ある寒い夜に）\\n\\n★ ポイント：④がいちばん出題される。「日付や曜日がくっついたら on」という一文を丸ごと覚えておく。\",\"figureId\":\"xf_eigo_s262\"},{\"heading\":\"同じ語でも前置詞が変わることを実感する\",\"body\":\"同じ morning という語でも、前に付く語によって前置詞が in と on の間で行ったり来たりする。次の三つを並べて比べておく。\\n\\n例）in the morning（ふつうに「朝に」）\\n例）on Sunday morning（日曜日の朝に）\\n例）on the morning of the party（パーティーの日の朝に）\\n\\n一つ目は「朝という時間帯」を広く指しているので in、二つ目と三つ目は「特定の一日の朝」を指しているので on になる。「どの日か決まっているかどうか」で判断すればよい。\\n\\n■ 前置詞を付けない言い方との組み合わせ\\nthis morning（今朝）・yesterday morning（昨日の朝）・tomorrow morning（明日の朝）には前置詞を付けない。\\n例）I got up at six this morning.（私は今朝六時に起きました。）\\n　　× in this morning / × on this morning とはしない。\\n\\n⚠ 注意：this・last・next・every が付いたら前置詞は消える。この規則は on にも in にも at にも共通なので、s264 でくわしく学習する。\",\"mangaId\":\"eigo_s262_xm\"}],\"trapExamples\":[{\"question\":\"「私は五月五日の朝に彼に会いました。」の空所に入る語を答えなさい。　I met him (　) the morning of May 5.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「朝に＝in the morning」という形をそのまま当てはめてしまう。文が長いため、後ろに of May 5 が付いていることを見落としやすい。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"the morning of May 5 は「五月五日という一日の朝」であり、日付が決まっている。日付や曜日が結び付いた時間帯は on になるので on the morning of May 5 が正しい。うしろに of ＋ 日付、または前に曜日が付いていないかを必ず確かめてから前置詞を選ぶ。\"},{\"question\":\"「私たちは日曜日の朝にサッカーをします。」を英語にしなさい。\",\"wrongAnswer\":\"We play soccer in Sunday morning.\",\"trapExplanation\":\"in the morning を覚えているうえに、日本語の語順「日曜日の朝に」をそのまま置きかえようとして、in を残したまま Sunday を差しこんでしまう。\",\"correctAnswer\":\"We play soccer on Sunday morning.\",\"correctExplanation\":\"Sunday という曜日が付いているので on を使い、the も付けずに on Sunday morning とする。in the morning の the は「曜日が付くと消える」と覚えておくとよい。同じように on Monday afternoon, on Friday evening も the を入れない。\"}]}",
"{\"id\":\"eigo_s263\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時の前置詞③：in と at の残りの用法\",\"description\":\"一日の時間帯・季節・年のほか、「〜後に」を表す in と、at を使う時刻表現を整理する\",\"intro\":\"in the morning とは言うのに、なぜ at night なのでしょう。朝・昼・夕方は in、夜だけ at です。理屈で説明しづらい部分ですが、決まった形として覚えるしかありません。また「3日後に」を in three days と言うのも、日本語からは出てきにくい形です。\",\"order\":763,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"in the morning / in the afternoon / in the evening は the が必要。\",\"at noon（正午）・at midnight（真夜中）・at night（夜）は the を付けない。\",\"in ＋ 期間 で「今から〜後に」。in two hours ＝ 二時間後に。\",\"「〜後に」を after で表すのは過去の話のとき。未来のことは in を使う。\",\"in time（間に合って）と on time（時間どおりに）は意味がちがう。\"],\"sections\":[{\"heading\":\"一日の時間帯を時計の上で整理する\",\"body\":\"一日を時計の上で区切ると、どこで in と at が入れかわるのかが見えてくる。\\n\\n■ in を使う時間帯（the が必要）\\nin the morning（朝・午前中に。だいたい夜明けから正午まで）\\nin the afternoon（午後に。正午から夕方まで）\\nin the evening（夕方・晩に。日暮れから寝るころまで）\\n\\n■ at を使う時刻（the を付けない）\\nat noon（正午に）／at midnight（真夜中の十二時に）／at night（夜に）／at dawn（夜明けに）\\n\\n■ 時刻そのもの\\nat seven（七時に）／at seven thirty（七時三十分に）／at about eight（八時ごろに）\\n\\n例）I get up at six in the morning.（私は朝六時に起きます。）\\nこの文のように、時刻（at six）と時間帯（in the morning）は同じ文の中で重ねて使える。英語では「せまい方を先に、広い方を後に」並べるのがふつうである。\\n\\n★ ポイント：時刻・正午・真夜中・夜は at、朝・午後・夕方は in ＋ the。\",\"figureId\":\"lf_eigoext08_263\"},{\"heading\":\"「〜後に」の in と、まぎらわしい熟語\",\"body\":\"in にはもう一つ、時間の長さと結び付いた大切な用法がある。\\n\\n■ in ＋ 期間 ＝ 「今から〜後に」\\n例）I will be back in an hour.（私は一時間後に戻ります。）\\n例）He will come in ten minutes.（彼は十分後に来ます。）\\nこの in は「一時間という時間が過ぎたところで」という意味で、未来のことに使う。\\n\\n■ after ＋ 期間 は過去の話のとき\\n例）He came back after two hours.（彼は二時間後に戻ってきた。）\\n過去の出来事を語るときは after ＋ 期間が使える。「未来は in、過去は after」と対にして覚える。\\n\\n■ まぎらわしい熟語\\nin time（間に合って）… I got to the station in time.（私は駅に間に合った。）\\non time（時間どおりに）… The train left on time.（電車は時間どおりに出発した。）\\nin time は「ぎりぎりでも間に合った」、on time は「ぴったり定刻に」という感じのちがいがある。\\n\\n⚠ 注意：「三日後に会いましょう」は See you in three days. である。after three days としないよう気をつける。\"},{\"heading\":\"なぜ朝は in で夜は at なのか、なぜ「〜後に」が in なのか\",\"mangaId\":\"eigo_s263_manga\",\"body\":\"in は「幅のある時間の中に」、at は「一点の時刻に」を表します。朝・午後・夕方は活動する時間の幅としてとらえるので in the morning、時刻（seven）・正午（noon）・真夜中（midnight）は時計の針が一か所を指す一点なので at です。night が at なのは、昔から夜を活動の「幅」ではなく、一日の区切りの「点」のようにとらえてきたからで、理屈より決まった形として覚えます。\\n\\n「〜後に」が in なのは、in three days が「三日という幅を過ぎたところで」という意味だからです。今を出発点にして未来のことを言うときに使います。after は「〜のあとで」と、過去の出来事を語るときに使います（He came back after two hours.）。日本語の辞書で「後に」を引くと after が出るので、未来にも after を使ってしまう誤りが多く、「未来は in、過去は after」と対で覚えます。\\n\\n■ 確かめのしかた\\n①**幅なら in、一点なら at**：in the morning／in the afternoon／in the evening（the が要る）、at seven／at noon／at midnight／at night（the は付けない）。\\n②時刻と時間帯を重ねるときは、せまい方を先に：at six in the morning。\\n③「今から〇後に」（未来）→in＋期間（I will be back in two hours.）。過去の話→after＋期間。\\n④in time（間に合って）と on time（時間どおりに）を区別する。\\n\\n★ ここがポイント：in は**幅**、at は**一点**（朝・午後は幅、時刻・正午・夜は点）。「〜後に」は**未来なら in＋期間、過去なら after＋期間**。\"}],\"trapExamples\":[{\"question\":\"「私は二時間後に戻ります。」を英語にしなさい。\",\"wrongAnswer\":\"I will be back after two hours.\",\"trapExplanation\":\"日本語の「〜後に」を辞書で引くと after が出てくるため、未来の話でも after を使ってしまう。after は「〜のあとで」という意味なので、日本語だけを見ていると誤りに気づけない。\",\"correctAnswer\":\"I will be back in two hours.\",\"correctExplanation\":\"今を出発点にして「これから二時間たったら」という未来のことを言うときは in ＋ 期間を使う。after ＋ 期間は He came back after two hours. のように、すでに起きた過去の出来事を語るときに使う。「未来は in、過去は after」と対で覚える。\"},{\"question\":\"「私たちは正午に昼食を食べます。」の空所に入る語を答えなさい。　We have lunch (　) noon.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"in the morning・in the afternoon を先に覚えているため、昼に関係する語はすべて in だと思いこんでしまう。\",\"correctAnswer\":\"at\",\"correctExplanation\":\"noon は「昼の十二時」という一点の時刻なので at noon となる。同じ理由で at midnight（真夜中の十二時に）も at である。「時計の針が一か所を指すものは at」と考えれば、at seven・at noon・at midnight・at night をまとめて処理できる。\"}]}",
"{\"id\":\"eigo_s264\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時の前置詞④：前置詞を付けない言い方\",\"description\":\"today・last week・every day など、前置詞を付けてはいけない時の表現を覚える\",\"intro\":\"「今日、公園へ行きました」を on today と書いてしまう人がいます。today・yesterday・last week・every day には前置詞を付けません。これらの語が、もともと副詞のはたらきをしているからです。付けないことを覚える、めずらしい単元です。\",\"order\":764,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"today, tomorrow, yesterday, tonight には前置詞を付けない。\",\"this・last・next・every が付いた時の言い方には前置詞を付けない（this morning, last night, next week, every day）。\",\"all day（一日中）・all night（一晩中）も前置詞なし。\",\"× in yesterday / × on last Sunday / × in every morning はすべて誤り。\",\"前置詞が要るかどうかは「頭に this・last・next・every が付いていないか」で見分ける。\"],\"sections\":[{\"heading\":\"前置詞が消える言い方\",\"body\":\"英語には「時を表す語なのに前置詞を付けてはいけない」グループがある。ここを知らないと、正しい前置詞を選べても余計な語を書いて減点されてしまう。\\n\\n■ ①それだけで「いつ」を表す語\\ntoday（今日）／tomorrow（明日）／yesterday（昨日）／tonight（今夜）／now（今）／then（そのとき）\\n例）I will go there tomorrow.（私は明日そこへ行きます。）\\n　　× I will go there on tomorrow.\\n\\n■ ②this・last・next・every が付いた形\\nthis morning（今朝）／this year（今年）／last night（昨夜）／last Sunday（この前の日曜日）／next week（来週）／next month（来月）／every day（毎日）／every Sunday（毎週日曜日）\\n例）We had a party last Saturday.（私たちはこの前の土曜日にパーティーをしました。）\\n　　× on last Saturday\\n\\n■ ③all が付いた形\\nall day（一日中）／all night（一晩中）／all year（一年中）\\n例）It rained all day.（一日中雨が降った。）\\n\\n★ ポイント：this・last・next・every・all のどれかが頭に付いていたら、前置詞は書かない。この五語を呪文のように覚えておくと迷わない。\",\"figureId\":\"xf_eigo_s264\"},{\"heading\":\"前置詞が要る形と要らない形を並べて確かめる\",\"body\":\"同じ Sunday でも、前に付く語によって前置詞が要ったり要らなかったりする。次の対で確認する。\\n\\n前置詞が要る　… on Sunday（日曜日に）／in May（五月に）／at seven（七時に）\\n前置詞が要らない … last Sunday（この前の日曜日に）／next May（来年の五月に）／this morning（今朝）\\n\\n例）I saw him on Sunday.（私は日曜日に彼に会いました。）\\n例）I saw him last Sunday.（私はこの前の日曜日に彼に会いました。）\\nどちらも日本語では「日曜日に」だが、last が付いた瞬間に on が消える。\\n\\n■ every の付いた形は頻度を表す\\n例）I practice the piano every day.（私は毎日ピアノを練習します。）\\n例）She goes to the library every Saturday.（彼女は毎週土曜日に図書館へ行きます。）\\nevery Saturday は on Saturdays（毎週土曜日に）と同じ意味を表す。ただし every のほうには前置詞を付けない。\\n\\n⚠ 注意：英作文で日本語の「〜に」を機械的に前置詞に置きかえると、× in every morning のような誤りが生まれる。書き終えたら「this・last・next・every・all が付いていないか」を必ず見直す。\",\"mangaId\":\"eigo_s264_xm\"}],\"trapExamples\":[{\"question\":\"「私はこの前の日曜日に彼に会いました。」を英語にしなさい。\",\"wrongAnswer\":\"I met him on last Sunday.\",\"trapExplanation\":\"「日曜日に＝on Sunday」という形を強く覚えているので、last が付いても on を残してしまう。日本語の「この前の日曜日に」に「に」があることも、前置詞を書きたくなる原因になる。\",\"correctAnswer\":\"I met him last Sunday.\",\"correctExplanation\":\"last・next・this・every が付いた時の表現には前置詞を付けない。last Sunday はそれだけで副詞のはたらきをするので、on は不要である。同じように次の日曜日は next Sunday、今週の日曜日は this Sunday となり、いずれも前置詞は書かない。\"},{\"question\":\"「私は毎朝六時に起きます。」の下線部の誤りを直しなさい。　I get up at six in every morning.\",\"wrongAnswer\":\"誤りはない（in every morning のままでよい）\",\"trapExplanation\":\"in the morning という形が頭にあるため、the を every に置きかえただけの in every morning を正しい形だと感じてしまう。\",\"correctAnswer\":\"I get up at six every morning.\",\"correctExplanation\":\"every が付いた形には前置詞を付けないので in は不要である。in the morning（朝に）と every morning（毎朝）は別の形だと区別して覚える。なお at six の at は時刻に付く前置詞なのでそのまま残す。消すのは every の前の in だけである。\"}]}",
"{\"id\":\"eigo_s265\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"場所の前置詞①：at・on・in を「点・面・中」で選ぶ\",\"description\":\"場所の at は点、on は接している面、in は内部。三つのイメージを図で区別する\",\"intro\":\"「駅で待つ」は at the station、「かべにかかっている」は on the wall、「箱の中」は in the box。at は点、on は接している面、in は内部です。日本語の「で」「に」からは区別できないので、絵でイメージをつかむのが近道になります。\",\"order\":765,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"at ＝ 地図の上の一点として見る場所（at the bus stop, at the door, at the corner）。\",\"on ＝ 何かの面にくっついている場所（on the desk, on the wall, on the floor）。\",\"in ＝ 囲まれた内部（in the box, in the room, in Osaka）。\",\"on は「上」ではなく「接している」がもとの意味。かべや天井でも on を使う。\",\"同じ場所でも見方が変われば前置詞が変わる（at the station ／ in the station）。\"],\"sections\":[{\"heading\":\"三つの前置詞の元のイメージ\",\"mangaId\":\"eigo_s265_manga\",\"body\":\"場所を表す at・on・in も、時の前置詞と同じように「どういう見方をしているか」で決まる。日本語の「〜に」「〜で」だけを手がかりにすると必ず迷うので、イメージごと覚えてしまう。\\n\\n■ at ＝ 点\\n広い地図の上に打った一つの印をイメージする。大きさを考えず、ただ「そこ」と指さす感じである。\\n例）at the bus stop（バス停で）／at the door（ドアのところで）／at the corner（角で）／at the station（駅で）\\n\\n■ on ＝ 接している面\\n「上」と訳すことが多いが、本当の意味は「くっついている」である。だから、かべや天井でも on を使う。\\n例）on the desk（机の上に）／on the wall（かべに）／on the floor（ゆかに）／on the ceiling（天井に）\\n\\n■ in ＝ 囲まれた内部\\n箱・部屋・町のように、周りを囲まれた空間の中にあるとき。\\n例）in the box（箱の中に）／in the room（部屋の中に）／in Osaka（大阪に）／in the water（水の中に）\\n\\n★ ポイント：「上」だから on、と訳語で決めてはいけない。「くっついているか」「囲まれているか」「ただの一点か」で判断する。\",\"figureId\":\"lf_eigoext08_265\"},{\"heading\":\"同じ場所でも見方で前置詞が変わる\",\"body\":\"英語では、同じ場所を指していても、話し手がどう見ているかで前置詞が変わることがある。\\n\\n例）I met him at the station.（私は駅で彼に会いました。）\\n例）There is a bookstore in the station.（駅の中に本屋があります。）\\n一つ目は「駅という地点で」という意味なので at、二つ目は「駅の建物の内部に」という意味なので in を使う。\\n\\n例）The children are playing at the park.（子どもたちは公園で遊んでいます。）\\n例）There are many trees in the park.（公園の中には木がたくさんあります。）\\nこれも同じで、「待ち合わせ場所としての公園」なら at、「囲まれた空間としての公園」なら in になる。\\n\\n■ 町や国は in\\n広い場所は当然「囲まれた空間」なので in を使う。\\n例）I live in Japan.（私は日本に住んでいます。）\\n例）She was born in Osaka.（彼女は大阪で生まれました。）\\n\\n⚠ 注意：日本語で「〜で」と言うからといって、いつも at になるわけではない。「駅で買った」「駅の中で買った」のように、日本語のほうがあいまいなことも多い。英語では中にいるかどうかをはっきりさせる必要がある。\"}],\"trapExamples\":[{\"question\":\"「かべに一枚の絵がかかっています。」の空所に入る語を答えなさい。　There is a picture (　) the wall.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"日本語が「かべに」なので「中に」の in を選んでしまう。また on を「上に」とだけ覚えていると、かべは上ではないので on を候補から外してしまう。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"on のもとの意味は「上」ではなく「接している」である。絵はかべの表面にくっついているので on the wall となる。同じ理由で天井のハエは a fly on the ceiling、ゆかのボールは a ball on the floor と、上下に関係なく on を使う。in the wall と言うと、かべの内部に絵が埋めこまれていることになってしまう。\"},{\"question\":\"「彼はバス停で待っていました。」を英語にしなさい。\",\"wrongAnswer\":\"He was waiting in the bus stop.\",\"trapExplanation\":\"「バス停」という建物のようなものを思いうかべ、その中で待っているつもりで in を選んでしまう。日本語の「〜で」からも in を連想しやすい。\",\"correctAnswer\":\"He was waiting at the bus stop.\",\"correctExplanation\":\"バス停は地図の上の一点として見る場所なので at を使う。同じ仲間に at the door（ドアのところで）、at the corner（角で）、at the gate（門のところで）がある。「そこは囲まれた空間か、それとも地点か」を考えれば、in と at の区別はほとんど解決する。\"}]}",
"{\"id\":\"eigo_s266\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"場所の前置詞②：at と in の使い分け・home の注意\",\"description\":\"建物と都市、arrive at と arrive in、前置詞の要らない home の使い方を身につける\",\"intro\":\"「家にいます」を I am in my home. と言うと不自然です。英語では I am at home. と、at を使い the も my も付けません。home はとても特別な語なのです。arrive at と arrive in の使い分けもあわせて整理します。\",\"order\":766,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"せまい場所や地点には at、広い場所には in（arrive at the station / arrive in Tokyo）。\",\"「〜に着く」は arrive at ／ arrive in ／ get to ／ reach（reach は前置詞不要）。\",\"at school は「学校で（勉強や活動をしている）」、in the school は「校舎の中に」。\",\"home は副詞なので go home / come home / be at home のように to や in を付けない。\",\"at home（家で）・at work（仕事中で）・at table（食事中で）は the が付かない。\"],\"sections\":[{\"heading\":\"せまい場所は at、広い場所は in\",\"mangaId\":\"eigo_s266_manga\",\"body\":\"at と in の境目は「その場所を一点と見るか、広がりのある空間と見るか」で決まる。とくに「〜に着く」を表す動詞と一緒に問われることが多い。\\n\\n■ 到着を表す言い方\\narrive at ＋ せまい場所（駅・空港・ホテル・学校）\\narrive in ＋ 広い場所（国・都市）\\n例）We arrived at the airport at ten.（私たちは十時に空港に着きました。）\\n例）We arrived in London last night.（私たちは昨夜ロンドンに着きました。）\\n\\n■ 同じ意味の別の言い方\\nget to ＋ 場所（口語的でよく使う）\\n例）I got to school at eight.（私は八時に学校に着きました。）\\nreach ＋ 場所（reach は他動詞なので前置詞を付けない）\\n例）We reached the top of the mountain.（私たちは山頂に着きました。）\\n　　× We reached to the top.\\n\\n★ ポイント：arrive は自分では場所を取れないので前置詞（at / in）が必要、reach は前置詞なしで場所を取る。この対比がそのまま入試問題になる。\",\"figureId\":\"xf_eigo_s266\"},{\"heading\":\"at school と in the school、そして home\",\"body\":\"建物を表す語には、the を付けずに使うと「本来の目的で使っている」という意味になるものがある。\\n\\n■ the を付けない形\\nat school（授業を受けている・在学している）／in bed（寝ている）／at church（礼拝している）／in hospital（入院している）\\n例）My brother is at school now.（兄は今学校に行っています。）\\n\\n■ the を付けた形\\nin the school（校舎の中にいる。掃除や見学かもしれない）\\n例）There is a swimming pool in the school.（その学校の中にはプールがあります。）\\n\\n■ home は副詞\\nhome は「家へ・家に」という意味をそれ自身が持っているので、go / come / get の後に前置詞を付けない。\\n例）I go home at five.（私は五時に家に帰ります。）　× go to home\\n例）He came home late.（彼は遅く帰宅した。）　× came to home\\nただし「家で」と状態を表すときは at home と at が付く。\\n例）I stayed at home yesterday.（私は昨日家にいました。）\\n\\n⚠ 注意：go home は前置詞なし、be at home は前置詞あり。動きを表すか、いる場所を表すかで区別する。\"}],\"trapExamples\":[{\"question\":\"「私たちは昨日東京に着きました。」の下線部の誤りを直しなさい。　We arrived to Tokyo yesterday.\",\"wrongAnswer\":\"誤りはない（arrived to Tokyo でよい）\",\"trapExplanation\":\"「〜に」という日本語と、go to Tokyo という形の記憶が結び付いて、arrive にも to を付けてしまう。to は「〜へ向かって」という方向の語で、到着した結果を表す arrive とは組み合わない。\",\"correctAnswer\":\"We arrived in Tokyo yesterday.\",\"correctExplanation\":\"arrive の後には at か in が来る。東京のような都市は広い空間なので in を使い、駅や空港のようなせまい地点なら arrive at the station となる。arrive to という形は存在しない。to を使いたいときは We got to Tokyo yesterday. のように get to にする。\"},{\"question\":\"「私は今家にいます。」を英語にしなさい。\",\"wrongAnswer\":\"I am in home now.\",\"trapExplanation\":\"「家の中にいる」という日本語のイメージから in を選び、さらに home をふつうの名詞だと思って前置詞を付けてしまう。\",\"correctAnswer\":\"I am at home now.\",\"correctExplanation\":\"「家にいる」という状態は決まった言い方で at home と表す。in home という形は使わない。また go home（家へ帰る）・come home（帰宅する）のように動きを表すときは、home が副詞になるので前置詞をまったく付けない。「動くときは前置詞なし、いるときは at home」と対で覚える。\"}]}",
"{\"id\":\"eigo_s267\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"場所の前置詞③：on は「接している」\",\"description\":\"かべ・天井・階・乗り物など、on が上下に関係なく使われる場面を整理する\",\"intro\":\"「電車の中で」を in the train と言ってしまいがちですが、ふつうは on the train です。バスも飛行機も on を使います。日本語の「中」につられて in にすると、たちまち不自然になります。on は上だけでなく「接している」というイメージだからです。\",\"order\":767,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"on のもとの意味は「接している」。上でも横でも下でも、くっついていれば on。\",\"on the wall（かべに）・on the ceiling（天井に）・on the floor（ゆかに）。\",\"階は on the second floor（二階に）。in the second floor とはしない。\",\"電車・バス・飛行機・船は on、車・タクシーは in（on the train ／ in the car）。\",\"on page ten（十ページに）・on the left（左側に）・on the river（川のほとりに）も on。\"],\"sections\":[{\"heading\":\"「上」ではなく「接している」で考える\",\"body\":\"on を「上に」とだけ覚えていると、かべや天井の話になったとたんに選べなくなる。on の本当の意味は「面にふれている」ことである。\\n\\n■ 上でなくても on\\n例）a picture on the wall（かべにかかっている絵）\\n例）a fly on the ceiling（天井にとまっているハエ）\\n例）a ball on the floor（ゆかにあるボール）\\n天井のハエは「下向きにくっついている」が、それでも接しているので on を使う。\\n\\n■ 階数は on\\n例）My room is on the second floor.（私の部屋は二階にあります。）\\n建物の階は「その面の上に立っている」と考えるので on になる。in the second floor とは言わない。\\n\\n■ 線や面に沿った場所\\n例）Osaka is on the Yodo River.（大阪は淀川のほとりにあります。）\\n例）The bank is on Main Street.（銀行はメインストリート沿いにあります。）\\n例）The answer is on page ten.（答えは十ページにあります。）\\n例）Turn right at the corner. The post office is on your left.（角を右に曲がってください。郵便局は左手にあります。）\\n\\n★ ポイント：かべ・天井・ゆか・階・道・ページ・左右は、すべて on の仲間である。\",\"figureId\":\"lf_eigoext08_267\"},{\"heading\":\"乗り物の on と in\",\"body\":\"乗り物に「乗っている」と言うとき、on と in が乗り物の種類で分かれる。中学入試でもよく問われる。\\n\\n■ on を使う乗り物（立って歩けるくらい大きいもの）\\non the train（電車で）／on the bus（バスで）／on the plane（飛行機で）／on the ship（船で）／on a bike（自転車で）／on a horse（馬に乗って）\\n例）I read a book on the train.（私は電車の中で本を読みました。）\\n\\n■ in を使う乗り物（体を囲まれるくらい小さいもの）\\nin the car（車で）／in a taxi（タクシーで）\\n例）They were talking in the car.（彼らは車の中で話していました。）\\n\\n■ 手段を表すときは by ＋ 無冠詞\\n「〜で行く」と交通手段を言うときは、the も a も付けずに by を使う。\\n例）I go to school by bus.（私はバスで学校へ行きます。）\\n　　× by the bus ／ × by a bus\\nただし「歩いて」は on foot という決まった形で、by は使わない。\\n\\n⚠ 注意：同じバスでも、「バスで通学する」は by bus、「バスの中で本を読む」は on the bus。手段か場所かで前置詞が変わる。\",\"mangaId\":\"eigo_s267_xm\"}],\"trapExamples\":[{\"question\":\"「私の教室は三階にあります。」の空所に入る語を答えなさい。　My classroom is (　) the third floor.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「三階に（建物の中に）ある」と考えて in を選んでしまう。日本語の「〜階に」からは、接触のイメージがまったく浮かばない。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"階は「そのゆかの面の上にある」と考えるので on the third floor となる。in the third floor とは言わない。あわせて「一階」はアメリカ英語で the first floor、イギリス英語では the ground floor と呼ぶことも覚えておくとよい。\"},{\"question\":\"「私は電車の中で本を読みました。」を英語にしなさい。\",\"wrongAnswer\":\"I read a book in the train.\",\"trapExplanation\":\"「電車の中で」という日本語に「中」があるため、迷わず in を選んでしまう。in the car（車の中で）が正しいことも、この誤りを後押ししてしまう。\",\"correctAnswer\":\"I read a book on the train.\",\"correctExplanation\":\"電車・バス・飛行機・船のように、中を立って歩ける大きな乗り物は on を使う。体を囲まれる小さな乗り物である車やタクシーだけが in the car / in a taxi となる。「大きい乗り物は on、小さい乗り物は in」と大きさで区別する。\"}]}",
"{\"id\":\"eigo_s268\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"場所の前置詞④：住所は at → on → in の入れ子\",\"description\":\"番地は at、通りは on、市や国は in。せまい順に並べる英語の書き方を身につける\",\"intro\":\"英語の住所は、番地・通り・市・国の順に書きます。日本語とちょうど逆で、せまいところから始まるのです。しかも前置詞も at 5 Green Street、on Green Street、in Osaka と変わります。順番と前置詞が対応していることを見ていきましょう。\",\"order\":768,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"番地（一点）は at、通りは on、市・県・国は in。\",\"英語の住所はせまい方から広い方へ並べる（日本語と逆）。\",\"live in Osaka / live on Main Street / live at 3-2-1 Umeda。\",\"「大阪の梅田に」は in Umeda, Osaka の順に書く。\",\"前置詞は「その場所をどれくらいの大きさで見ているか」で決まる、という原則は場所でも同じ。\"],\"sections\":[{\"heading\":\"三重の入れ子になった場所の言い方\",\"body\":\"場所の at・on・in は、住所を書くときに三段重ねで現れる。せまいものから広いものへ、at → on → in と変わっていく。\\n\\n■ at ＝ 番地（地図の上の一点）\\n例）He lives at 3-2-1 Umeda.（彼は梅田三丁目二番一号に住んでいます。）\\n\\n■ on ＝ 通り（線として見る場所）\\n例）He lives on Main Street.（彼はメインストリートに住んでいます。）\\n通りは線なので「線に接している」という on の意味とぴったり合う。\\n\\n■ in ＝ 市・県・国（広がりのある空間）\\n例）He lives in Osaka.（彼は大阪に住んでいます。）\\n例）He lives in Japan.（彼は日本に住んでいます。）\\n\\n同じ人の住所でも、どのレベルで言うかによって前置詞が変わる。「その場所は点か、線か、広がりか」を考えれば選べる。\\n\\n★ ポイント：at（番地）＜ on（通り）＜ in（市・国）。時の前置詞とまったく同じ順番なので、時と場所をセットで覚えると効率がよい。\",\"figureId\":\"lf_eigoext08_268\"},{\"heading\":\"英語の住所は日本語と逆の順に並べる\",\"body\":\"日本語の住所は「日本、大阪府、大阪市、天王寺区…」と広い方から書くが、英語は逆にせまい方から広い方へ並べる。\\n\\n例）3-2-1 Umeda, Kita-ku, Osaka, Japan\\n例）I live in Umeda, Osaka.（私は大阪の梅田に住んでいます。）\\n\\n英作文では「大阪の梅田に」という日本語の順につられて Osaka Umeda と書いてしまいがちだが、英語では Umeda, Osaka の順になる。人の名前が「名 → 姓」の順であるのと同じ考え方で、英語は「小さい方が先」だと覚えるとよい。\\n\\n■ 場所を二つ重ねるときの前置詞\\n広い場所を後から付け足すときは、前置詞は一つだけでよい。\\n例）She was born in Kobe, Hyogo.（彼女は兵庫県の神戸で生まれました。）\\nin を二回くり返して in Kobe in Hyogo とはしない。\\n\\n■ 手紙のあて名でも同じ\\n封筒には名前 → 番地 → 市 → 国の順に書く。日本の住所を英語で書く練習は、英語入試の英作文でも出題されることがある。\\n\\n⚠ 注意：通りの名前に付く前置詞は on である。in Main Street としない（イギリス英語では in を使うこともあるが、入試では on で覚えておく）。\",\"mangaId\":\"eigo_s268_xm\"}],\"trapExamples\":[{\"question\":\"「彼はメインストリートに住んでいます。」の空所に入る語を答えなさい。　He lives (　) Main Street.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「〜に住んでいる」は live in と覚えているため、後ろに来る語が通りでも in を選んでしまう。live in Osaka という形が強く印象に残っているのが原因である。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"通りは線として見る場所なので、線に接するという意味の on を使う。live in は Osaka・Japan のように囲まれた広がりのある場所に使い、通りには on、番地には at を使う。「番地は at、通りは on、市や国は in」と三段階で覚える。\"},{\"question\":\"「彼は大阪の梅田に住んでいます。」を英語にしなさい。\",\"wrongAnswer\":\"He lives in Osaka Umeda.\",\"trapExplanation\":\"日本語の「大阪の梅田」という語順をそのまま英語に置きかえてしまう。英語では場所をせまい方から並べる決まりがあることを知らないと必ず間違える。\",\"correctAnswer\":\"He lives in Umeda, Osaka.\",\"correctExplanation\":\"英語の住所はせまい方から広い方へ並べるので Umeda, Osaka の順になる。前置詞は先頭に一つだけ置き、in Umeda in Osaka のようにくり返さない。日本語と順番が逆になるという点は、英作文でくり返し出題される重要事項である。\"}]}",
"{\"id\":\"eigo_s269\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"位置の前置詞①：under・over・above・below\",\"description\":\"真上・真下を表す over と under、高さだけを比べる above と below を区別する\",\"intro\":\"「橋の上を通る」と「雲の上を飛ぶ」。日本語ではどちらも「上」ですが、英語では over と above に分かれます。over は真上をおおうように、above は高さだけを比べる語です。真下の under と below も同じ関係。四つを図で見分けます。\",\"order\":769,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"under ＝ 真下（おおわれている感じ）。over ＝ 真上（おおうように）。\",\"above ＝ ある高さより上（真上でなくてよい）。below ＝ ある高さより下。\",\"over には「〜を越えて」「〜以上」の意味もある（jump over, over ten years old）。\",\"under には「〜未満」の意味もある（under ten years old ＝ 十歳未満）。\",\"on は接している、over は接していない。この一点で on と over は区別できる。\"],\"sections\":[{\"heading\":\"四つの位置を上下の図で整理する\",\"body\":\"上下の位置を表す前置詞は四つある。「真上・真下かどうか」と「おおっているかどうか」の二点で区別する。\\n\\n■ under（真下に、おおわれて）\\n例）The cat is under the desk.（ねこは机の下にいます。）\\n例）I put my bag under the chair.（私はかばんをいすの下に置きました。）\\n\\n■ over（真上に、おおうように）\\n例）There is a bridge over the river.（川に橋がかかっています。）\\n例）A bird flew over my head.（鳥が私の頭上を飛んだ。）\\nover は「おおいかぶさる」感じなので、橋のように上に広がるものと相性がよい。\\n\\n■ above（〜より上に）\\n真上でなくてもよく、ただ高さを比べているだけ。\\n例）The sun rose above the mountains.（太陽が山の上に昇った。）\\n例）The plane is flying above the clouds.（飛行機は雲の上を飛んでいます。）\\n\\n■ below（〜より下に）\\n例）The temperature was below zero.（気温は零度より下、氷点下でした。）\\n例）Write your name below the line.（線の下に名前を書きなさい。）\\n\\n★ ポイント：over と under は「真上・真下」で対、above と below は「高さの比較」で対になっている。\",\"figureId\":\"lf_eigoext08_269\"},{\"heading\":\"over と under の数の意味・on との区別\",\"mangaId\":\"eigo_s269_manga\",\"body\":\"over と under には位置以外の意味もあり、そちらも入試でよく問われる。\\n\\n■ 数の「〜を越えて／〜未満」\\nover ten years old（十歳を越えて＝十一歳以上）\\nunder ten years old（十歳未満＝九歳以下）\\n例）Children under six can enter free.（六歳未満の子どもは無料で入れます。）\\n「以上・以下」と訳すと数がずれることがあるので、over は「それより多い」、under は「それより少ない」と考える。\\n\\n■ 「〜を越えて」の動き\\n例）The boy jumped over the fence.（少年はさくを飛びこえた。）\\n例）We walked over the bridge.（私たちは橋をわたった。）\\n\\n■ on と over のちがい\\non は接している、over は接していない。\\n例）There is a cloth on the table.（テーブルの上に布がかけてある。ふれている）\\n例）There is a lamp over the table.（テーブルの上にランプがつってある。ふれていない）\\n\\n⚠ 注意：日本語ではどちらも「テーブルの上」と言うので、接しているかどうかを自分で判断しなければならない。「さわれるか」を考えるとよい。\"}],\"trapExamples\":[{\"question\":\"「川に橋がかかっています。」の空所に入る語を答えなさい。　There is a bridge (　) the river.\",\"wrongAnswer\":\"above the river\",\"trapExplanation\":\"「川の上」という日本語から、「〜より上」を意味する above を選んでしまう。above も under も上下を表すので、どちらでもよいように見えてしまうのが落とし穴である。\",\"correctAnswer\":\"over the river\",\"correctExplanation\":\"橋は川をおおうように真上にかかっているので over を使う。above は「単に高さが上」というだけで、おおう感じがないため橋には合わない。over ＝ おおうように真上、above ＝ 位置が高いだけ、と区別する。同じ理由で「頭上を飛ぶ」は fly over my head である。\"},{\"question\":\"「六歳未満の子どもは無料です。」の英文として正しいものを選びなさい。　Children (　) six are free.\",\"wrongAnswer\":\"below six\",\"trapExplanation\":\"「未満＝下」と考えて below を選んでしまう。below も「より下」を表すので意味は近く見えるが、年齢や数の「〜未満」には使わない。\",\"correctAnswer\":\"under six\",\"correctExplanation\":\"年齢や数量が「〜より少ない」ことを表すのは under である。below は温度や線の位置のように、目盛りや基準線より下にあることを表すのに使う（below zero ＝ 零度より下）。「年齢・値段・数は under と over、目盛りは below と above」と使い分ける。\"}]}",
"{\"id\":\"eigo_s270\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"位置の前置詞②：between と among\",\"description\":\"二つの間の between、三つ以上の中の among。前置詞の後の代名詞の形にも注意する\",\"intro\":\"「二人の間に」は between、「大勢の中で」は among。数が二つか三つ以上かで決まります。しかも between you and me のように、前置詞のあとの代名詞は me や him という形になります。I や he とは書けません。二つの注意点を同時におさえます。\",\"order\":770,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"between ＝ 二つのものの間（between A and B の形が基本）。\",\"among ＝ 三つ以上の集まりの中（among the trees, among the students）。\",\"between の後に and 以外を使うときは between the two countries のように複数形。\",\"前置詞の後の代名詞は目的格。between you and me が正しく、between you and I は誤り。\",\"among の後は必ず複数の名詞か集合を表す語（among us, among people）。\"],\"sections\":[{\"heading\":\"between と among の使い分け\",\"mangaId\":\"eigo_s270_manga\",\"body\":\"「〜の間に」を表す前置詞は二つあり、いくつのものにはさまれているかで使い分ける。\\n\\n■ between ＝ 二つの間\\n例）The bank is between the post office and the school.（銀行は郵便局と学校の間にあります。）\\n例）There is a big difference between the two pictures.（その二枚の絵には大きなちがいがあります。）\\nbetween A and B という形で使うのがふつうで、and を使わないときは複数形の名詞を置く。\\n例）between the two countries（その二国の間で）\\n\\n■ among ＝ 三つ以上の中\\n例）The house stands among the trees.（その家は木々の間に立っています。）\\n例）He is popular among the students.（彼は生徒たちの間で人気がある。）\\namong の後には必ず複数を表す語が来る。among the tree のように単数形にすることはできない。\\n\\n■ 三つ以上でも between を使う場合\\n一つ一つをはっきり区別しているときは、三つ以上でも between を使う。\\n例）Japan lies between China, Korea and Russia.\\n中学入試では「二つなら between、三つ以上なら among」で答えて問題ない。\\n\\n★ ポイント：among は「集まりの中にまぎれている」感じ、between は「二つにはさまれている」感じ。\",\"figureId\":\"lf_eigoext08_270\"},{\"heading\":\"前置詞の後は目的格\",\"body\":\"between のところで必ず問われるのが、代名詞の形である。前置詞の後に来る代名詞は、主語の形（主格）ではなく目的語の形（目的格）にしなければならない。\\n\\n主格　　I / we / he / she / they / who\\n目的格　me / us / him / her / them / whom\\n\\n例）This is a secret between you and me.（これはあなたと私だけの秘密です。）\\n　　× between you and I\\n\\n例）He sat between his father and me.（彼はお父さんと私の間にすわった。）\\n例）There is nothing between us.（私たちの間には何もない。）\\n\\n■ なぜ間違えるのか\\n「あなたと私は」という日本語につられて you and I という形を反射的に思い出してしまうからである。you and I が正しいのは主語のときだけで、前置詞の後や動詞の目的語では you and me になる。\\n例）You and I are good friends.（あなたと私は仲のよい友達です。）… 主語なので I\\n例）He invited you and me.（彼はあなたと私を招待した。）… 目的語なので me\\n\\n⚠ 注意：among us（私たちの間で）、between them（彼らの間で）のように、among や between の後もすべて目的格になる。\"}],\"trapExamples\":[{\"question\":\"「彼は三人の少年の間に立っていました。」の空所に入る語を答えなさい。　He was standing (　) the three boys.\",\"wrongAnswer\":\"between\",\"trapExplanation\":\"「〜の間に」という日本語から、まず思いうかぶ between を選んでしまう。日本語には二つの間か三つ以上の中かを区別する言い方がないので、意識しないと選び分けられない。\",\"correctAnswer\":\"among\",\"correctExplanation\":\"three boys は三人＝三つ以上なので among を使う。between は二つのものにはさまれているときに使い、between the two boys のように二つを示す語と組む。「二つなら between、三つ以上なら among」と数で判断する習慣をつける。\"},{\"question\":\"「これはあなたと私だけの秘密です。」の下線部の誤りを直しなさい。　This is a secret between you and I.\",\"wrongAnswer\":\"誤りはない（between you and I でよい）\",\"trapExplanation\":\"You and I are good friends. のような文で覚えた you and I という形が耳に残っており、ていねいで正しい言い方のように感じてしまう。\",\"correctAnswer\":\"This is a secret between you and me.\",\"correctExplanation\":\"between は前置詞なので、後ろの代名詞は目的格の me になる。you and I が使えるのは主語のときだけである。見分け方は簡単で、you and を隠して between I と読んでみればおかしいと気づける。同じ方法で He invited you and me. も確かめられる。\"}]}",
"{\"id\":\"eigo_s271\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"位置の前置詞③：in front of・behind・next to\",\"description\":\"前後・となり・向かいを表す表現と、in front of と in the front of のちがいを学ぶ\",\"intro\":\"in front of と in the front of は、the があるかないかだけのちがいですが、意味は「〜の前に」と「〜の前方に」で別ものです。バスの外に立っているのか、バスの中の前のほうにいるのか。the 一語で場所が変わってしまいます。\",\"order\":771,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"in front of ＝ 〜の前に（外側から見て前）。behind ＝ 〜の後ろに。\",\"in the front of ＝ 〜の中の前の部分に（the が入ると内部になる）。\",\"next to ＝ beside ＝ by ＝ 〜のとなりに。\",\"across from ＝ opposite ＝ 〜の向かいに（道をはさんだ反対側）。\",\"in front of は三語で一つの前置詞のはたらきをする（群前置詞）。\"],\"sections\":[{\"heading\":\"前・後ろ・となり・向かい\",\"body\":\"絵を見て場所を答える問題では、次の四種類がくり返し出題される。\\n\\n■ in front of（〜の前に）\\n例）There is a car in front of the house.（家の前に車があります。）\\n例）He is standing in front of the door.（彼はドアの前に立っています。）\\n三語まとめて一つの前置詞のようにはたらくので、front の前後の語を落とさないように書く。\\n\\n■ behind（〜の後ろに）\\n例）The boy is hiding behind the tree.（少年は木の後ろにかくれています。）\\n例）My house is behind the station.（私の家は駅の裏にあります。）\\n\\n■ next to ／ beside ／ by（〜のとなりに）\\n例）She sat next to me.（彼女は私のとなりにすわりました。）\\n例）There is a bank beside the hospital.（病院のとなりに銀行があります。）\\n\\n■ across from ／ opposite（〜の向かいに）\\n例）The library is across from the park.（図書館は公園の向かいにあります。）\\n道や広場をはさんで反対側にある、という意味である。\\n\\n★ ポイント：となりは next to（横にくっついている）、向かいは across from（何かをはさんで反対側）。日本語ではどちらも「そばに」と言えてしまうので、位置を絵にして確かめる。\",\"figureId\":\"lf_eigoext08_271\"},{\"heading\":\"in front of と in the front of のちがい\",\"body\":\"一語 the が入るかどうかで、意味が外と内に分かれる有名な組み合わせがある。\\n\\n■ in front of ＝ そのものの外側の前\\n例）A boy is standing in front of the bus.（少年はバスの前に立っています。）\\nバスの外にいて、バスの正面に立っている場面である。\\n\\n■ in the front of ＝ そのものの内部の前の部分\\n例）A boy is sitting in the front of the bus.（少年はバスの前の方の席にすわっています。）\\nバスの中にいて、車内の前方にいる場面である。\\n\\n同じように in the back of the bus と言えば「バスの車内の後ろの方に」となる。\\n\\n■ 似た形の群前置詞\\nin front of（〜の前に）／in the middle of（〜の真ん中に）／at the end of（〜の終わりに）／on the side of（〜の側面に）／in the center of（〜の中心に）\\n例）There is a table in the middle of the room.（部屋の真ん中にテーブルがあります。）\\n\\n⚠ 注意：in front of the bus と the front of the bus（バスの前部）は別物である。the が付いたら「そのものの一部分」を指していると考える。\",\"mangaId\":\"eigo_s271_xm\"}],\"trapExamples\":[{\"question\":\"「少年はバスの前の方の席にすわっていました。」を英語にしなさい。\",\"wrongAnswer\":\"A boy was sitting in front of the bus.\",\"trapExplanation\":\"「バスの前」という日本語だけを見て、覚えたばかりの in front of を当てはめてしまう。これだとバスの外に立っている意味になり、絵の場面とまったく合わなくなる。\",\"correctAnswer\":\"A boy was sitting in the front of the bus.\",\"correctExplanation\":\"the が入ると「そのものの内部の前の部分」を表す。バスの車内の前方にすわっているのだから in the front of the bus が正しい。外側の正面なら in front of the bus となる。the 一語で外と内が入れかわる、という点をそのまま覚えておく。\"},{\"question\":\"「郵便局は駅の向かいにあります。」の空所に入る表現を選びなさい。　The post office is (　) the station.\",\"wrongAnswer\":\"in front of\",\"trapExplanation\":\"「駅の前にある」と言いかえられる日本語なので、in front of で通じると思ってしまう。しかし in front of は建物のすぐ正面（同じ側）を指し、道をはさんだ反対側の意味にはならない。\",\"correctAnswer\":\"across from\",\"correctExplanation\":\"道路や広場をはさんで反対側にあるときは across from（＝opposite）を使う。in front of は「その建物のすぐ前の空間」なので、駅前広場に立っているイメージになる。地図の問題では「同じ側か、道の反対側か」を必ず確かめて選ぶ。\"}]}",
"{\"id\":\"eigo_s272\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"位置の前置詞④：near・by・around・along・against\",\"description\":\"近さを表す near と by、周り・沿って・寄りかかってを表す前置詞を整理する\",\"intro\":\"near the station と by the station——どちらも「駅の近く」ですが、by のほうがすぐそばを表します。近さにも段階があるのです。そのほか around（まわりを）、along（沿って）、against（寄りかかって）も、動きのイメージで区別できます。\",\"order\":772,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"near ＝ 近くに（少し離れていてもよい）。by ＝ すぐそばに（near より近い）。\",\"near は前置詞なので、ふつう near my school のように to を入れずに書く。\",\"around ＝ 〜の周りに／〜のあちこちに／約〜（数の前では「約」）。\",\"along ＝ 〜に沿って（川・道・かべなど細長いものに沿って）。\",\"against ＝ 〜に寄りかかって／〜に反対して。\"],\"sections\":[{\"heading\":\"近さを表す near と by\",\"body\":\"「近くに」を表す語は複数あり、距離の感じ方でえらび分ける。\\n\\n■ near（近くに）\\n例）I live near the station.（私は駅の近くに住んでいます。）\\n例）There is a park near my house.（私の家の近くに公園があります。）\\nnear は前置詞なので、後ろに直接名詞を置く。near to という言い方もあるが、ふつうは to を入れずに書く。\\n\\n■ by（すぐそばに）\\n例）She was sitting by the window.（彼女は窓ぎわにすわっていました。）\\n例）He stood by me.（彼は私のすぐそばに立っていた。）\\nby は near よりも近く、手が届くくらいの距離を表す。\\n\\n■ 比較のことば\\nnear は形容詞にもなり、the nearest station（いちばん近い駅）のように変化する。\\n例）Where is the nearest station?（いちばん近い駅はどこですか。）\\n\\n■ nearby は副詞\\n例）There is a hospital nearby.（近くに病院があります。）\\nnearby は一語で「近くに」という副詞なので、後ろに名詞を置かない。\\n\\n★ ポイント：near ＋ 名詞、nearby は単独で使う。この二つを混ぜて near by my house と書くのが典型的な誤りである。\",\"figureId\":\"xf_eigo_s272\"},{\"heading\":\"around・along・against\",\"body\":\"位置を表す前置詞のうち、意味が二つ以上あるものは意味の取りちがえで失点しやすい。\\n\\n■ around（周りに・あちこちに・約）\\n例）The children sat around the fire.（子どもたちは火の周りにすわった。）\\n例）He traveled around the world.（彼は世界中を旅した。）\\n例）There were around thirty people.（三十人ほどいました。）\\n数の前に置かれた around は「約」の意味になる。about と同じである。\\n\\n■ along（〜に沿って）\\n例）We walked along the river.（私たちは川に沿って歩きました。）\\n例）There are many shops along this street.（この通り沿いには店がたくさんあります。）\\n川・道・かべ・海岸のように細長いものと組み合わせて使う。\\n\\n■ against（〜に寄りかかって・〜に反対して）\\n例）He put his bike against the wall.（彼は自転車をかべに立てかけた。）\\n例）I am against the plan.（私はその計画に反対です。）\\n物にぶつける・押しつけるイメージから、「反対する」の意味も生まれている。\\n\\n⚠ 注意：around ＋ 数字は「約」。「周りに」と訳して意味の分からない文になったら、数字が来ていないかを確かめる。\",\"mangaId\":\"eigo_s272_xm\"}],\"trapExamples\":[{\"question\":\"「私は学校の近くに住んでいます。」の下線部の誤りを直しなさい。　I live near to my school.\",\"wrongAnswer\":\"誤りはない（near to のままでよい）\",\"trapExplanation\":\"next to（〜のとなりに）や close to（〜に近い）という形を覚えているため、near にも to が必要だと考えてしまう。「近い」という意味の語はすべて to を取るように感じられるのが原因である。\",\"correctAnswer\":\"I live near my school.\",\"correctExplanation\":\"near はそれ自体が前置詞なので、後ろに直接名詞を置き、ふつうは to を入れない（near to という形も使われるが、入試の答案では near my school と書く）。to が必要なのは close to my school や next to my school のように close・next を使うときである。語ごとに覚え分ける。\"},{\"question\":\"次の英文の下線部の意味を答えなさい。　There were around thirty students in the gym.\",\"wrongAnswer\":\"三十人の生徒たちの周りに\",\"trapExplanation\":\"around を「〜の周りに」とだけ覚えているため、後ろに数字が来ていても同じように訳してしまう。「三十人の周りに」と訳すと日本語として意味が通らないのに、そのまま書いてしまう受験生が多い。\",\"correctAnswer\":\"約三十人（三十人ほど）\",\"correctExplanation\":\"around の後に数字が来ると「約〜」という意味になり、about と同じはたらきをする。訳は「体育館には三十人ほどの生徒がいました。」となる。訳して意味が通らないときは、その語に別の意味がないかを疑う。about も「〜について」と「約〜」の二つの意味を持つ同じ仲間である。\"}]}",
"{\"id\":\"eigo_s273\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"位置の前置詞⑤：絵の描写問題を解く\",\"description\":\"There is / There are と位置の前置詞を組み合わせ、絵の場面を英語で説明する\",\"intro\":\"「机の上に本が3冊あります」を英語で言えますか。There are three books on the desk. です。絵を見て場面を説明する問題では、There is / There are と位置の前置詞を組み合わせます。ここまで学んだ前置詞を、実際に使ってみる回です。\",\"order\":773,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"There is ＋ 単数名詞／There are ＋ 複数名詞 ＋ 場所を表す語句、の順に並べる。\",\"場所を表す語句は文の最後に置く（There is a cat under the desk.）。\",\"名詞を後ろから説明する前置詞句は、近いものから順に並べる（in the bag on the desk）。\",\"the が付いた名詞は There is の文で主語にしない（The cat is under the desk. とする）。\",\"絵の問題では、まず「何が」「どこに」を日本語で言ってから英語に直す。\"],\"sections\":[{\"heading\":\"There is / There are の文で位置を説明する\",\"body\":\"絵を見て説明する問題では、There is / There are の文がほぼ必ず登場する。\\n\\n■ 基本の形\\nThere is ＋ 単数の名詞 ＋ 場所\\nThere are ＋ 複数の名詞 ＋ 場所\\n例）There is a cat under the desk.（机の下にねこが一匹います。）\\n例）There are two books on the chair.（いすの上に本が二冊あります。）\\n\\n■ 場所は最後\\n日本語は「机の下にねこがいます」と場所を先に言うが、英語は「いる → 何が → どこに」の順である。語順を日本語のまま書かないように注意する。\\n\\n■ the が付く名詞は There is を使わない\\nThere is の文は「初めて話題に出すもの」を紹介する文なので、すでに話題になっているものには使わない。\\n例）× There is the cat under the desk.\\n　　○ The cat is under the desk.（そのねこは机の下にいます。）\\n\\n■ 疑問文と否定文\\n例）Is there a park near your house?（あなたの家の近くに公園はありますか。）\\n　－ Yes, there is. ／ No, there is not.\\n例）There are not any children in the park.（公園には子どもが一人もいません。）\\n\\n★ ポイント：まず単数か複数かを見て is か are を決め、次に場所の前置詞を選ぶ。この二段構えで解く。\",\"figureId\":\"lf_eigoext08_273\"},{\"heading\":\"前置詞句を重ねるときの語順\",\"body\":\"絵の描写では「机の上のかばんの中に」のように、場所の説明が二重になることがある。英語では、説明したい名詞のすぐ後ろに、近い場所から順に置いていく。\\n\\n例）A pen is in the bag on the desk.（ペンは机の上のかばんの中にあります。）\\nペン → かばんの中（in the bag） → その かばんは机の上（on the desk）、という順である。日本語とは逆に、うしろから前へ読むと日本語の順になる。\\n\\n例）The boy under the tree in the park is my brother.\\n（公園の木の下にいる少年は私の弟です。）\\n\\n■ 名詞を後ろから説明する前置詞句\\n前置詞句は、直前の名詞を説明する。\\n例）the book on the desk（机の上の本）\\n例）the girl with long hair（長い髪の少女）\\n例）the man in the blue shirt（青いシャツを着た男の人）\\n\\n■ 描写問題の解き方の手順\\n①主語になるものを決める（何について言うか）\\n②単数か複数かを確かめる\\n③場所を表す前置詞をせまい順に並べる\\n\\n⚠ 注意：in the desk on the bag のように順を逆にすると、「かばんの上の机の中に」というまったく別の意味になってしまう。近い場所から書く、という原則を守る。\",\"mangaId\":\"eigo_s273_xm\"}],\"trapExamples\":[{\"question\":\"「ペンは机の上のかばんの中にあります。」を英語にしなさい。\",\"wrongAnswer\":\"A pen is in the desk on the bag.\",\"trapExplanation\":\"日本語の「机の上の → かばんの中に」という語順のまま英語に置きかえてしまい、名詞と前置詞の組み合わせが入れかわってしまう。前置詞だけを見ると in も on も出ているので、書いた本人は正しく訳せた気になってしまう。\",\"correctAnswer\":\"A pen is in the bag on the desk.\",\"correctExplanation\":\"英語では、ペンにいちばん近い場所（かばんの中＝in the bag）を先に書き、そのかばんがどこにあるか（机の上＝on the desk）を後ろに続ける。日本語は逆順なので、うしろから読むと日本語の語順に一致する。前置詞句を重ねるときは「近い場所から」と覚える。\"},{\"question\":\"「その少女は木の下のベンチにすわっています。」の空所に入る語を答えなさい。　The girl is sitting (　) the bench under the tree.\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「ベンチにすわる」という日本語から「中に入る」感じを受け取り、さらに sit in a chair（ひじかけいすにすわる）という表現の記憶が混ざって in を選んでしまう。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"ベンチは平らな面なので、面に接することを表す on を使って sit on the bench となる。同じ理由で sit on the chair、sit on the floor も on である。「囲まれているか、面に接しているか」で in と on を判断する原則は、すわる場所でも変わらない。\"}]}",
"{\"id\":\"eigo_s274\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"方向の前置詞①：to と for\",\"description\":\"到達点を表す to と、向かう方向を表す for のちがいを、動詞との組み合わせで覚える\",\"intro\":\"I went to Osaka. は大阪に着いたことを表しますが、I left for Osaka. は大阪に向かって出発しただけで、着いたかどうかまでは言っていません。to は到達点、for は向かう方向。日本語の「〜へ」の一語では見えないちがいです。\",\"order\":774,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"to ＝ 到達点（go to school, come to my house, walk to the station）。\",\"for ＝ 向かう方向（leave for Tokyo, start for school, the train for Osaka）。\",\"leave ＋ 場所 は「〜を出発する」、leave for ＋ 場所 は「〜へ向けて出発する」。\",\"home・there・here は副詞なので to を付けない（go home, go there）。\",\"give / show / send は「人に」を to、buy / make は for（give it to me / make it for me）。\"],\"sections\":[{\"heading\":\"到達点の to、方向の for\",\"body\":\"どちらも「〜へ」と訳すが、to は着いたところまで、for は向きだけを表す。\\n\\n■ to ＝ 到達点まで含む\\n例）I go to school by bus.（私はバスで学校へ行きます。）\\n例）He walked to the station.（彼は駅まで歩いた。）\\n例）Please come to my house.（私の家に来てください。）\\n\\n■ for ＝ 向かう方向\\n例）He left for Tokyo yesterday.（彼は昨日東京へ向けて出発した。）\\n例）This train is for Osaka.（この電車は大阪行きです。）\\n例）We started for the park at nine.（私たちは九時に公園へ向けて出発した。）\\nfor の文は「向かった」と言っているだけで、着いたかどうかは言っていない。\\n\\n■ leave の二つの形\\nleave ＋ 場所 ＝ その場所を出る\\n例）He left Tokyo.（彼は東京を出発した。＝東京から離れた）\\nleave for ＋ 場所 ＝ その場所へ向けて出発する\\n例）He left for Tokyo.（彼は東京へ向けて出発した。）\\n一語 for が入るだけで、東京が出発地から目的地に変わる。\\n\\n★ ポイント：to は「矢印が刺さって止まる」、for は「矢印が向いているだけ」とイメージする。\",\"figureId\":\"lf_eigoext08_274\",\"mangaId\":\"eigo_s274_xm\"},{\"heading\":\"to を付けない語と、to と for を使う動詞\",\"body\":\"to は「〜へ」を表す代表的な前置詞だが、付けてはいけない場合がある。\\n\\n■ home・there・here は副詞\\n例）I go home at five.（私は五時に家へ帰ります。）　× go to home\\n例）Let's go there tomorrow.（明日そこへ行こう。）　× go to there\\n例）Come here.（ここへ来なさい。）　× come to here\\nこれらの語は「〜へ」という意味をそれ自身が持っている。\\n\\n■ 人に何かをわたす動詞\\nto を使う動詞 … give（与える）／show（見せる）／send（送る）／teach（教える）／tell（話す）／lend（貸す）\\n例）I gave a book to him.（私は彼に本をあげた。）\\nfor を使う動詞 … buy（買う）／make（作る）／cook（料理する）／get（手に入れる）／find（見つける）\\n例）She made a cake for me.（彼女は私にケーキを作ってくれた。）\\n\\n■ 見分け方\\n相手に直接手わたす感じの動詞は to、相手のために何かをしてあげる感じの動詞は for になる。give は物が相手まで届くので to、make は作った時点では相手に届いていないので for、と考えるとよい。\\n\\n⚠ 注意：I gave him a book. のように「人 → 物」の語順で書くときは、to も for も使わない。前置詞が要るのは「物 → 人」の語順にしたときだけである。\"}],\"trapExamples\":[{\"question\":\"「私は昨日早く家に帰りました。」の下線部の誤りを直しなさい。　I went to home early yesterday.\",\"wrongAnswer\":\"誤りはない（went to home でよい）\",\"trapExplanation\":\"go to school・go to the park と同じ形だと考えて、home にも to を付けてしまう。「家へ」という日本語に「へ」があることも、to を書きたくなる原因になる。\",\"correctAnswer\":\"I went home early yesterday.\",\"correctExplanation\":\"home は「家へ」という意味をそれ自身に含む副詞なので、to を付けない。同じ仲間に there（そこへ）、here（ここへ）、upstairs（上の階へ）、abroad（外国へ）がある。ただし「家で」という状態を表す at home では前置詞が必要なので、動きか状態かで区別する。\"},{\"question\":\"「彼は大阪へ向けて出発しました。」を英語にしなさい。\",\"wrongAnswer\":\"He left to Osaka.\",\"trapExplanation\":\"「〜へ」という日本語をそのまま to に置きかえてしまう。go to Osaka という形になじんでいるため、leave にも同じ to が使えると思いこむのが原因である。\",\"correctAnswer\":\"He left for Osaka.\",\"correctExplanation\":\"leave の後に前置詞なしで場所を置くと「その場所を出る」、for を置くと「その場所へ向かう」となる。leave to という形は使わない。同じ仲間に start for（〜へ出発する）、a train for Osaka（大阪行きの電車）がある。「出発の行き先は for」と覚える。\"}]}",
"{\"id\":\"eigo_s275\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"方向の前置詞②：from・into・out of\",\"description\":\"起点の from、外から中への into、中から外への out of を、対で覚える\",\"intro\":\"from は出発点、into は外から中へ、out of は中から外へ。He came into the room. と He went out of the room. は、ちょうど反対の動きです。in や out が場所を表すのに対し、into と out of は動きを表します。対にして覚えましょう。\",\"order\":775,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"from ＝ 起点（〜から）。from A to B で「AからBまで」。\",\"into ＝ 外から中への動き（go into the room, jump into the pool）。\",\"out of ＝ 中から外への動き（come out of the room, get out of the car）。\",\"out of は二語で一つの前置詞。out from とはしない。\",\"be made from（材料が見た目で分からない）と be made of（見た目で分かる）を区別する。\"],\"sections\":[{\"heading\":\"起点の from と、A から B まで\",\"body\":\"from は「そこから始まる」という起点を表す。to と組み合わせて範囲を表す形が重要である。\\n\\n■ from ＝ 〜から\\n例）I am from Osaka.（私は大阪の出身です。）\\n例）This letter is from my friend in Canada.（この手紙はカナダの友達からのものです。）\\n例）The wind is blowing from the north.（風が北から吹いています。）\\n\\n■ from A to B ＝ AからBまで\\n場所にも時間にも使える。\\n例）This train goes from Tokyo to Osaka.（この電車は東京から大阪まで行きます。）\\n例）I study from seven to nine every evening.（私は毎晩七時から九時まで勉強します。）\\n例）The shop is open from Monday to Friday.（その店は月曜から金曜まで開いています。）\\n\\n時間の「〜まで」には until もあるが、from とセットで使うときは to のほうがふつうである。\\n\\n■ 距離を表す from\\n例）My school is ten minutes from here.（私の学校はここから十分のところにあります。）\\n例）How far is it from here to the station?（ここから駅までどのくらいありますか。）\\n\\n★ ポイント：from は「出発点」、to は「到着点」。この二つで一つの線を作る。\",\"figureId\":\"xf_eigo_s275\"},{\"heading\":\"into と out of は動きの向き\",\"body\":\"in と on が「どこにあるか」を表すのに対し、into と out of は「どちらへ動くか」を表す。\\n\\n■ into ＝ 外から中へ\\n例）He went into the room.（彼は部屋の中へ入っていった。）\\n例）The boy jumped into the pool.（少年はプールに飛びこんだ。）\\n例）Please put the milk into the glass.（牛乳をコップに入れてください。）\\n\\n■ out of ＝ 中から外へ\\n例）She came out of the house.（彼女は家から出てきた。）\\n例）He got out of the car.（彼は車から降りた。）\\n例）Take the book out of the bag.（かばんから本を取り出しなさい。）\\nout of は二語で一つの前置詞のはたらきをする。out from という形は使わない。\\n\\n■ 乗り物の乗り降り\\nget on the bus（バスに乗る）／get off the bus（バスを降りる）… 大きい乗り物\\nget into the car（車に乗る）／get out of the car（車から降りる）… 小さい乗り物\\non と in で分けたのと同じ理由で、乗り物の大きさによって語が変わる。\\n\\n⚠ 注意：into は「動き」なので、be動詞の文では使わない。× He is into the room. は誤りで、いる場所を言うなら He is in the room. とする。\",\"mangaId\":\"eigo_s275_xm\"}],\"trapExamples\":[{\"question\":\"「彼女は部屋から出てきました。」の下線部の誤りを直しなさい。　She came out from the room.\",\"wrongAnswer\":\"誤りはない（out from でよい）\",\"trapExplanation\":\"「〜から」という日本語がそのまま from と結び付き、out と組み合わせて out from としてしまう。from が「起点」を表すのは正しいので、意味の上ではもっともらしく感じられる。\",\"correctAnswer\":\"She came out of the room.\",\"correctExplanation\":\"「中から外へ」の動きは out of という二語で一つの前置詞として使う。out from という形は使わない。反対の「外から中へ」は into である。come out of / get out of / take out of をひとまとまりの表現として覚えておく。\"},{\"question\":\"「この電車は東京から大阪まで行きます。」の空所に入る語を答えなさい。　This train goes from Tokyo (　) Osaka.\",\"wrongAnswer\":\"until\",\"trapExplanation\":\"「〜まで」という日本語を辞書で引くと until が出てくるため、場所にも until を使ってしまう。日本語の「まで」が時間にも場所にも使えることが誤りのもとになっている。\",\"correctAnswer\":\"to\",\"correctExplanation\":\"until（till）は時間にしか使えない前置詞で、場所の「〜まで」には to を使う。from Tokyo to Osaka（東京から大阪まで）、from seven to nine（七時から九時まで）のように、from と対で使うときは時間でも to が自然である。「until は時間専用」と覚えておく。\"}]}",
"{\"id\":\"eigo_s276\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"方向の前置詞③：through・across・along・over\",\"description\":\"通り抜ける・横切る・沿って進む・越えるという移動のしかたを区別する\",\"intro\":\"川を「わたる」は across、トンネルを「ぬける」は through、川に「そって歩く」は along、へいを「こえる」は over。日本語ではどれも移動を表す言葉ですが、英語は動きのかたちで前置詞を選びます。絵にすると区別しやすくなります。\",\"order\":776,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"through ＝ 中を通り抜ける（トンネル・森・窓・ドア）。\",\"across ＝ 表面を横切る（道・川・部屋）。cross（動詞）＝ go across。\",\"along ＝ 細長いものに沿って進む（川・道・海岸）。\",\"over ＝ 越えていく（さく・山・橋）。\",\"around ＝ 回って進む（角を曲がる・世界を回る）。\"],\"sections\":[{\"heading\":\"四つの進み方を絵で区別する\",\"mangaId\":\"eigo_s276_manga\",\"body\":\"移動を表す前置詞は、進む道すじの形で決まる。日本語ではどれも「〜を」と言ってしまうので、絵で覚えるのがいちばん確実である。\\n\\n■ through ＝ 中を通り抜ける\\n例）The train went through a long tunnel.（電車は長いトンネルを通り抜けた。）\\n例）We walked through the forest.（私たちは森の中を歩いて抜けた。）\\n例）A bird came in through the window.（鳥が窓から入ってきた。）\\n\\n■ across ＝ 表面を横切る\\n例）We walked across the street.（私たちは道を横断した。）\\n例）He swam across the river.（彼は川を泳いでわたった。）\\nacross ＋ 名詞は、動詞 cross ＋ 名詞に書きかえられる。\\n例）He crossed the river.（同じ意味）\\n\\n■ along ＝ 沿って進む\\n例）We walked along the river.（私たちは川に沿って歩いた。）\\n横切るのではなく、川と同じ向きに進んでいる点がちがう。\\n\\n■ over ＝ 越えていく\\n例）The cat jumped over the wall.（ねこはへいを飛びこえた。）\\n例）We went over the mountain.（私たちは山を越えて行った。）\\n\\n★ ポイント：through は中を、across は横に、along は沿って、over は上を越えて。四つの矢印の形をそのまま覚える。\",\"figureId\":\"lf_eigoext08_276\"},{\"heading\":\"入試でねらわれる組み合わせ\",\"body\":\"どの前置詞と組むかが決まっている言い方があるので、まとめて覚えておく。\\n\\n■ よく出る組み合わせ\\ngo through the gate（門を通り抜ける）\\nlook through the window（窓越しに見る）\\nwalk across the bridge（橋をわたる）… 橋の面の上を横切るので across\\nswim across the river（川を泳いでわたる）\\nrun along the beach（浜辺に沿って走る）\\nclimb over the fence（さくをよじ登って越える）\\ngo around the corner（角を曲がる）\\ntravel around the world（世界中を旅する）\\n\\n■ across と over の使い分け\\n橋のように平らな面をわたるときは across、へいや山のように高いものを越えるときは over を使う。\\n例）walk across the bridge（橋をわたる）\\n例）jump over the fence（さくを飛びこえる）\\n\\n■ through の別の意味\\n時間について使うと「〜の間ずっと」となる。\\n例）It rained through the night.（一晩中雨が降った。）\\n\\n⚠ 注意：日本語の「わたる」は across も over も cross も表せる。英語では「面を横切るのか、越えるのか」を必ず選ばなければならない。\"}],\"trapExamples\":[{\"question\":\"「私たちは道を横断しました。」の空所に入る語を答えなさい。　We walked (　) the street.\",\"wrongAnswer\":\"through\",\"trapExplanation\":\"「道を通って」という日本語のイメージから through を選んでしまう。through は「中を通り抜ける」なので、道の内部を進む＝道に沿って進む意味に近くなり、横断したことにならない。\",\"correctAnswer\":\"across\",\"correctExplanation\":\"道の一方の側からもう一方の側へ横切るときは across を使う。through はトンネル・森・窓のように「囲まれた中を抜ける」ときに使う。walk across the street は cross the street と書きかえられることも合わせて覚える。\"},{\"question\":\"「私たちは川に沿って歩きました。」を英語にしなさい。\",\"wrongAnswer\":\"We walked across the river.\",\"trapExplanation\":\"川と walk が結び付いた例文として across the river をよく見るため、「沿って」でも同じ前置詞を使ってしまう。across を「川といえばこれ」と丸暗記していると起こりやすい誤りである。\",\"correctAnswer\":\"We walked along the river.\",\"correctExplanation\":\"川と同じ向きに、川ぎわを進むのだから along を使う。across は川を横切って向こう岸へわたるという、まったく別の動きを表す。along the street（通りに沿って）、along the beach（海岸沿いに）も同じ形である。矢印の向きが川と平行か直角かで選ぶ。\"}]}",
"{\"id\":\"eigo_s277\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"方向の前置詞④：up・down・past・toward\",\"description\":\"上る・下る・通り過ぎる・〜の方へ、という動きの表現と前置詞の要否を確かめる\",\"intro\":\"「坂をのぼる」は go up the hill、「その店を通りすぎる」は go past the shop。日本語ではどちらも「〜を」で共通していますが、英語ではそれぞれちがう前置詞が入ります。また home のように前置詞が要らない語もある。要るか要らないかも確かめます。\",\"order\":777,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"up ＝ 〜を上って、down ＝ 〜を下って。前置詞なので to を付けない。\",\"past ＝ 〜を通り過ぎて（walk past the shop）。\",\"toward ＝ 〜の方へ（到達は含まない。for と似た感じ）。\",\"go up the stairs（階段を上る）／go down the street（通りを進む）。\",\"pass by ＝ そばを通り過ぎる。pass through ＝ 中を通り抜ける。\"],\"sections\":[{\"heading\":\"up・down・past・toward の使い方\",\"body\":\"動きを表す前置詞のうち、日本語との対応がずれやすいものを整理する。\\n\\n■ up ＝ 〜を上って／down ＝ 〜を下って\\n例）He went up the stairs.（彼は階段を上った。）\\n例）She ran down the hill.（彼女は丘をかけ下りた。）\\nup も down も前置詞なので、後ろに直接名詞を置く。× go up to the stairs とはしない。\\nなお down the street は「通りを（先の方へ）進んで」という意味で、坂を下るとは限らない。\\n例）Go down this street and turn left at the second corner.（この通りを進んで、二つ目の角を左に曲がりなさい。）\\n\\n■ past ＝ 〜を通り過ぎて\\n例）I walked past the post office.（私は郵便局の前を通り過ぎた。）\\n例）The bus went past the school.（バスは学校の前を通り過ぎた。）\\npast は時刻にも使う。\\n例）It is ten past seven.（七時十分です。）\\n\\n■ toward ＝ 〜の方へ\\n例）He walked toward the station.（彼は駅の方へ歩いていった。）\\n到着したかどうかは言っていない点で to とちがい、for に近い。\\n\\n★ ポイント：up・down・past は前置詞なので、後ろに前置詞を重ねない。\",\"figureId\":\"xf_eigo_s277\",\"mangaId\":\"eigo_s277_xm\"},{\"heading\":\"道案内の表現でまとめて確かめる\",\"body\":\"方向の前置詞は、道案内の会話文でまとめて出題されることが多い。次の言い方をひとかたまりで覚える。\\n\\n例）Go straight along this street.（この通りをまっすぐ行ってください。）\\n例）Turn right at the second corner.（二つ目の角を右に曲がってください。）\\n例）Walk past the bank.（銀行を通り過ぎてください。）\\n例）Cross the street at the traffic light.（信号のところで道をわたってください。）\\n例）The library is on your left.（図書館は左手にあります。）\\n例）You will see it in front of the park.（公園の前に見えますよ。）\\n例）It takes about five minutes on foot.（歩いて五分ほどです。）\\n\\n■ 使う前置詞のまとめ\\n角では at（at the corner）、通りには along か down、左右には on（on your left）、目印の建物には in front of や next to を使う。\\n\\n■ 気をつけたい形\\ngo straight（まっすぐ行く）… straight は副詞なので前置詞を付けない\\non foot（徒歩で）… by foot とは言わない\\n\\n⚠ 注意：道案内では「通り過ぎる」を pass through と書く誤りが多い。pass through は建物などの中を通り抜ける意味になってしまう。\"}],\"trapExamples\":[{\"question\":\"「私たちは郵便局の前を通り過ぎました。」を英語にしなさい。\",\"wrongAnswer\":\"We passed through the post office.\",\"trapExplanation\":\"「通り過ぎる」の「通り」から through を連想してしまう。through には「通り抜ける」という意味があるので、日本語だけを見ていると自然に感じられるが、これでは郵便局の建物の中を歩いて抜けた意味になる。\",\"correctAnswer\":\"We walked past the post office.\",\"correctExplanation\":\"建物のそばを通り過ぎるときは past を使い、walk past ／ go past ／ drive past の形にする。pass through は「中を通り抜ける」なので、トンネルや森のときに使う。なお We passed the post office. と動詞 pass を使う言い方も正しい。\"},{\"question\":\"「彼は階段を上りました。」の下線部の誤りを直しなさい。　He went up to the stairs.\",\"wrongAnswer\":\"誤りはない（up to the stairs でよい）\",\"trapExplanation\":\"go to school のように「行く」には to が要ると覚えているため、up の後にも to を付けてしまう。up to には「〜まで」という別の意味があるので、形だけ見ると正しそうに見えるのも原因である。\",\"correctAnswer\":\"He went up the stairs.\",\"correctExplanation\":\"up は前置詞なので、後ろに直接名詞を置いて go up the stairs とする。to を入れた go up to は「〜のところまで近づく」という別の意味になる（He went up to the door. ＝ 彼はドアのところまで行った）。down も同じで、go down the street に to は入れない。\"}]}",
"{\"id\":\"eigo_s278\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"期間の前置詞①：for と during\",\"description\":\"長さを表す for と、特定の期間の名前と組む during を確実に区別する\",\"intro\":\"「3日間」は for three days、「夏休みの間」は during the summer vacation。どちらも日本語では「間」です。えらび方は、うしろに来る語で決まります。数字で長さを言うなら for、期間の名前を言うなら during。この一点で見分けられます。\",\"order\":778,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"for ＋ 期間の長さ（for three days, for a week, for two hours）。\",\"during ＋ 特定の期間の名前（during the summer vacation, during the class）。\",\"for の後には数を表す語、during の後には the が付いた語が来ることが多い。\",\"「どのくらいの間？」に答えるのが for、「いつの間に？」に答えるのが during。\",\"during は前置詞なので、後ろに文（主語＋動詞）を置けない。\"],\"sections\":[{\"heading\":\"for は長さ、during は期間の名前\",\"body\":\"どちらも「〜の間」と訳すが、後ろに来る語がまったくちがう。\\n\\n■ for ＋ 期間の長さ\\n「どのくらいの間か」を数で答える語が来る。\\n例）I studied for three hours.（私は三時間勉強しました。）\\n例）He has lived here for ten years.（彼はここに十年間住んでいます。）\\n例）We stayed in Kyoto for a week.（私たちは京都に一週間泊まりました。）\\n\\n■ during ＋ 特定の期間の名前\\n「いつの間か」を表す語が来る。the や my が付いた名詞が多い。\\n例）I visited Hokkaido during the summer vacation.（私は夏休みの間に北海道を訪れました。）\\n例）He slept during the class.（彼は授業中ずっとねむっていました。）\\n例）It snowed a lot during the winter.（その冬はたくさん雪が降りました。）\\n\\n■ 質問文で確かめる\\nHow long did you stay?（どのくらい泊まりましたか。）→ For three days.（三日間です。）\\nWhen did you visit him?（いつ訪ねましたか。）→ During the vacation.（休みの間です。）\\n答え方のちがいがそのまま前置詞のちがいになっている。\\n\\n★ ポイント：後ろに数字が見えたら for、the ＋ 行事や季節の名前が見えたら during。\",\"figureId\":\"lf_eigoext08_278\",\"mangaId\":\"eigo_s278_xm\"},{\"heading\":\"for のいろいろな意味\",\"body\":\"for は期間以外にもよく使われる前置詞なので、代表的な意味をまとめて確認しておく。\\n\\n■ ①〜の間（期間）\\n例）I waited for an hour.（私は一時間待ちました。）\\n\\n■ ②〜のために（目的・利益）\\n例）This present is for you.（このプレゼントはあなたのためのものです。）\\n例）I made lunch for my brother.（私は弟のために昼食を作りました。）\\n\\n■ ③〜へ向けて（行き先）\\n例）He left for Osaka.（彼は大阪へ向けて出発した。）\\n\\n■ ④〜と引きかえに\\n例）I bought this book for 500 yen.（私はこの本を五百円で買いました。）\\n\\n■ ⑤よく出る熟語\\nfor example（例えば）／for the first time（初めて）／for a long time（長い間）／wait for（〜を待つ）／look for（〜をさがす）／be famous for（〜で有名だ）／thank you for（〜をありがとう）\\n\\n⚠ 注意：wait for、look for のように動詞と結び付いた for は「〜を」と訳すので、期間の for と混同しないこと。前後の語を見て判断する。\"}],\"trapExamples\":[{\"question\":\"「私は夏休みの間に北海道へ行きました。」の空所に入る語を答えなさい。　I went to Hokkaido (　) the summer vacation.\",\"wrongAnswer\":\"for\",\"trapExplanation\":\"「〜の間」という日本語から、先に習った for を選んでしまう。for も during も同じ訳になるため、日本語だけを手がかりにすると区別できない。\",\"correctAnswer\":\"during\",\"correctExplanation\":\"the summer vacation は「夏休み」という特定の期間の名前なので during を使う。for の後には for two weeks のように長さを表す数の語が来る。「the ＋ 行事や季節の名前なら during、数字なら for」と、後ろの語で機械的に判断できるようにしておく。\"},{\"question\":\"「私は三時間ずっとテレビを見ていました。」を英語にしなさい。\",\"wrongAnswer\":\"I watched TV during three hours.\",\"trapExplanation\":\"「三時間の間ずっと」という日本語の「間」が強く感じられるため、during を選んでしまう。during を「〜の間ずっと」と訳して覚えていると、この誤りが起きやすい。\",\"correctAnswer\":\"I watched TV for three hours.\",\"correctExplanation\":\"three hours は期間の長さを表す語なので for を使う。during three hours という形は使わない。during の後に置けるのは the class・the vacation・my stay のように「いつのことか」を表す名前だけである。数字が見えたら for、と機械的に決めてよい。\"}]}",
"{\"id\":\"eigo_s279\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"期間の前置詞②：since と for（現在完了とともに）\",\"description\":\"起点を表す since と長さを表す for を、現在完了の文の中で使い分ける\",\"intro\":\"I have lived here for ten years. と I have lived here since 2016. — 前者は長さ、後者は始まった時点を表します。日本語ではどちらも「10年前から」と言えてしまいます。現在完了の文で必ずセットで出るので、区別を体にいれておきましょう。\",\"order\":779,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"since ＋ 起点（since 2020, since last year, since I was a child）。\",\"for ＋ 長さ（for six years, for a long time）。\",\"since は現在完了（have ＋ 過去分詞）とともに使うのが原則。\",\"since は接続詞にもなり、後ろに文（主語＋動詞）を置ける（since I came to Japan）。\",\"How long ...? には For ... または Since ... で答える。\"],\"sections\":[{\"heading\":\"since は起点、for は長さ\",\"body\":\"現在完了の文で「いつから」「どのくらい」を表すときの前置詞である。同じ内容を二通りに言えることが多い。\\n\\n■ since ＝ 〜から（起点の一点）\\n例）I have lived here since 2020.（私は二〇二〇年からここに住んでいます。）\\n例）He has been sick since last Monday.（彼はこの前の月曜日からずっと具合が悪い。）\\n\\n■ for ＝ 〜の間（長さ）\\n例）I have lived here for six years.（私は六年間ここに住んでいます。）\\n例）He has been sick for a week.（彼は一週間ずっと具合が悪い。）\\n\\n同じ場面を、起点で言うか長さで言うかのちがいである。二〇二六年に立って言えば、since 2020 と for six years は同じことを表す。\\n\\n■ 答え方\\nHow long have you lived here?（どのくらいここに住んでいますか。）\\n　－ For six years.（六年間です。）\\n　－ Since 2020.（二〇二〇年からです。）\\n\\n★ ポイント：since の後ろは「時の一点」、for の後ろは「時の長さ」。年号・曜日・出来事なら since、数字＋単位なら for。\",\"figureId\":\"lf_eigoext08_279\",\"mangaId\":\"eigo_s279_xm\"},{\"heading\":\"since は接続詞にもなる\",\"body\":\"since は前置詞としても接続詞としても使える。接続詞のときは後ろに主語と動詞のある文が来る。\\n\\n■ 前置詞の since（後ろは名詞）\\n例）I have known him since last year.（私は去年から彼を知っています。）\\n\\n■ 接続詞の since（後ろは文）\\n例）I have known him since I was a child.（私は子どものころから彼を知っています。）\\n例）Ten years have passed since he came to Japan.（彼が日本に来てから十年になります。）\\n接続詞の since が導く文の動詞は過去形にする。since I have been a child とはしない。\\n\\n■ since を使う文の時制\\n主となる文は現在完了、since の後ろは過去（の一点）というのが基本の組み合わせである。\\n例）She has been busy since she started her new job.\\n（彼女は新しい仕事を始めてからずっと忙しい。）\\n\\n■ since の別の意味\\n理由を表す接続詞にもなる（＝because）。\\n例）Since it was raining, we stayed home.（雨が降っていたので、私たちは家にいました。）\\n\\n⚠ 注意：since を使いながら現在形のままにする誤りが非常に多い。since が見えたら have ＋ 過去分詞になっているかを必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"「私は三年間ここに住んでいます。」の下線部の誤りを直しなさい。　I have lived here since three years.\",\"wrongAnswer\":\"誤りはない（since three years でよい）\",\"trapExplanation\":\"「三年間ここに住んでいる」＝「三年前からここに住んでいる」と頭の中で言いかえてしまい、「〜から」の since を選んでしまう。日本語で言いかえられるので、誤りに気づきにくい。\",\"correctAnswer\":\"I have lived here for three years.\",\"correctExplanation\":\"three years は期間の長さなので for を使う。since の後ろに置けるのは since 2023、since last year、since I was ten のような「時の一点」だけである。「三年前から」と言いたければ since three years ago と ago を付ける必要がある。\"},{\"question\":\"「私は昨日からずっと忙しい。」を英語にしなさい。\",\"wrongAnswer\":\"I am busy since yesterday.\",\"trapExplanation\":\"「今も忙しい」ので現在形でよいと考えてしまう。日本語の「〜からずっと」には動詞の形の変化がないため、時制を変える必要に気づきにくい。\",\"correctAnswer\":\"I have been busy since yesterday.\",\"correctExplanation\":\"since は「過去のある時点から今まで続いている」ことを表すので、動詞は現在完了（have ＋ 過去分詞）にする。be動詞の過去分詞は been なので have been busy となる。「since が見えたら have ＋ 過去分詞」とセットで覚えておくと、この誤りは防げる。\"}]}",
"{\"id\":\"eigo_s280\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"期間の前置詞③：until と by\",\"description\":\"動作が続く終わりを表す until と、締め切りの一点を表す by を区別する\",\"intro\":\"I will wait until five. は5時までずっと待つこと、I will come by five. は5時までのどこかで来ることです。日本語ではどちらも「5時まで」。動作が続くのか、期限だけを示すのか。この差を知らないと、待ちぼうけになりかねません。\",\"order\":780,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"until（till）＝ 〜までずっと（動作や状態が続く）。\",\"by ＝ 〜までに（その時までに一回すればよい期限）。\",\"続く動詞（wait, stay, sleep, work）には until、一回で終わる動詞（come, finish, return）には by。\",\"until は接続詞にもなる（until he comes）。by は前置詞だけで、by the time ... の形で文を続ける。\",\"by the time ＋ 文の節は、時を表す節なので、未来のことでも現在形で書く（will を使わない）。\"],\"sections\":[{\"heading\":\"線の until、点の by\",\"mangaId\":\"eigo_s280_manga\",\"body\":\"どちらも日本語では「〜まで」だが、until は終わりまで続く線、by は締め切りの点である。\\n\\n■ until（till）＝ 〜までずっと\\n例）I will wait here until five.（私は五時までここで待ちます。）\\n例）He studied until midnight.（彼は真夜中まで勉強した。）\\n例）The shop is open until nine.（その店は九時まで開いています。）\\n五時になるまで、待つという動作がずっと続いている。\\n\\n■ by ＝ 〜までに\\n例）Come here by five.（五時までにここへ来なさい。）\\n例）Please finish your homework by tomorrow.（明日までに宿題を終わらせてください。）\\n例）I will be back by seven.（私は七時までには戻ります。）\\n五時より前のどこかで一度来ればよく、来る動作がずっと続くわけではない。\\n\\n■ 動詞で見分ける\\nuntil と組む動詞 … wait（待つ）、stay（とどまる）、sleep（ねむる）、work（働く）、be open（開いている）\\nby と組む動詞 … come（来る）、finish（終える）、return（返す）、arrive（着く）、send（送る）\\n\\n★ ポイント：「その時までずっと続くか、それとも一回で済むか」で決める。\",\"figureId\":\"lf_eigoext08_280\"},{\"heading\":\"until の接続詞用法と by the time\",\"body\":\"until は前置詞にも接続詞にもなるが、by は前置詞だけである。文を続けたいときは by the time という形を使う。\\n\\n■ until ＋ 名詞（前置詞）\\n例）Please wait until three o'clock.（三時まで待ってください。）\\n\\n■ until ＋ 文（接続詞）\\n例）Please wait here until I come back.（私が戻るまでここで待っていてください。）\\n時を表す接続詞なので、未来のことでも現在形で書く（will を使わない）。\\n\\n■ by the time ＋ 文\\n例）By the time he arrived, the game had started.（彼が着くころには試合は始まっていた。）\\n例）I will finish it by the time you come.（あなたが来るまでにそれを終わらせます。）\\nby は後ろに文を置けないので、by the time という三語の形にする。\\n\\n■ not ... until 〜\\n「〜して初めて…する」という言い方になる。\\n例）I did not know the news until yesterday.（私は昨日までそのニュースを知らなかった。＝昨日初めて知った。）\\n\\n⚠ 注意：by の後ろに主語＋動詞の文を置く誤り（× by he comes）が非常に多い。文を置くなら by the time he comes とする。\"}],\"trapExamples\":[{\"question\":\"「五時までにここへ来なさい。」の空所に入る語を答えなさい。　Come here (　) five.\",\"wrongAnswer\":\"until\",\"trapExplanation\":\"「五時まで」という日本語がそのまま until と結び付いてしまう。「までに」と「まで」の一字のちがいが、英語では別の前置詞になることを意識していないと必ず間違える。\",\"correctAnswer\":\"by\",\"correctExplanation\":\"「来る」は一回で終わる動作なので、締め切りを表す by を使う。until five にすると「五時までずっと来つづける」というおかしな意味になってしまう。日本語の「までに」は by、「までずっと」は until と、一字のちがいを前置詞のちがいに結び付けて覚える。\"},{\"question\":\"「私は五時までここで待ちます。」を英語にしなさい。\",\"wrongAnswer\":\"I will wait here by five.\",\"trapExplanation\":\"前の問題で「〜まで＝by」と覚えなおしてしまい、今度は続く動作にも by を使ってしまう。二つの語を行ったり来たりして混乱するのが、この単元の典型的な失点である。\",\"correctAnswer\":\"I will wait here until five.\",\"correctExplanation\":\"「待つ」は五時になるまで続く動作なので until を使う。by five にすると「五時までのどこかで一度待つ」という意味不明の文になる。動詞が wait・stay・sleep・work のように「続く動作」なら until、come・finish・return のように「一回で終わる動作」なら by、と動詞で判断する。\"}]}",
"{\"id\":\"eigo_s281\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"期間の前置詞④：during と while、when との関係\",\"description\":\"後ろに名詞が来る前置詞と、後ろに文が来る接続詞を見分ける力をつける\",\"intro\":\"「夏休みの間に」は during the summer vacation、「私が寝ている間に」は while I was sleeping。日本語では同じ「間」でも、うしろに名詞が来るか文が来るかで語が変わります。前置詞と接続詞のちがいが、いちばんはっきり出る組み合わせです。\",\"order\":781,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"during ＋ 名詞（前置詞）／while ＋ 主語＋動詞（接続詞）。\",\"while ＝ 〜している間に。長く続いている動作と組むことが多い。\",\"when ＝ 〜するとき（一時点でも期間でもよい）。\",\"前置詞か接続詞かは「後ろに主語と動詞があるか」だけで見分けられる。\",\"during my stay ＝ while I stayed のように書きかえができる。\"],\"sections\":[{\"heading\":\"後ろに何が来るかで語を選ぶ\",\"body\":\"同じ「〜の間に」でも、後ろに名詞が来るなら前置詞、文が来るなら接続詞を使わなければならない。これは前置詞と接続詞の学習全体でいちばん大切な区別である。\\n\\n■ during ＋ 名詞（前置詞）\\n例）I read three books during the summer vacation.（私は夏休みの間に本を三冊読みました。）\\n例）Don't talk during the class.（授業中はおしゃべりをしてはいけません。）\\n\\n■ while ＋ 主語＋動詞（接続詞）\\n例）The phone rang while I was taking a bath.（私がおふろに入っている間に電話が鳴った。）\\n例）While she was cooking, he cleaned the room.（彼女が料理をしている間に、彼は部屋をそうじした。）\\n\\n■ 書きかえ\\nduring my stay in Kyoto（京都に滞在している間に）\\n＝ while I stayed in Kyoto\\n名詞の形にするか、文の形にするかのちがいだけである。\\n\\n■ 同じ関係にある組み合わせ\\nbecause of ＋ 名詞 ／ because ＋ 文\\nin spite of ＋ 名詞 ／ though ＋ 文\\nduring ＋ 名詞 ／ while ＋ 文\\n\\n★ ポイント：空所の後ろを見て、主語＋動詞があれば接続詞、名詞だけなら前置詞を選ぶ。\",\"figureId\":\"xf_eigo_s281\"},{\"heading\":\"while と when のちがい\",\"mangaId\":\"eigo_s281_manga\",\"body\":\"while も when も「〜のとき」と訳せるが、時間のはばがちがう。\\n\\n■ while ＝ 〜している間（続いている時間）\\n例）While I was walking, it began to rain.（歩いている間に、雨が降り始めた。）\\nwhile の中の動詞は進行形（be動詞＋ing）になることが多い。\\n\\n■ when ＝ 〜するとき（一時点でもよい）\\n例）When I got home, my mother was cooking.（私が家に着いたとき、母は料理をしていた。）\\nwhen の中には、短い動作を表す動詞が来ることも多い。\\n\\n■ 二つを重ねた形\\n例）When I visited him, he was studying.（私が彼を訪ねたとき、彼は勉強していた。）\\n「短い動作（訪ねた）」と「続いている動作（勉強していた）」の組み合わせでは、短い方に when、長い方に進行形を使う。\\n\\n■ 未来のことは現在形\\nwhile も when も時を表す接続詞なので、未来のことでも will を使わずに現在形で書く。\\n例）I will read a book while I wait for the bus.（バスを待っている間、本を読みます。）\\n\\n⚠ 注意：while の後ろに名詞だけを置く誤り（× while my stay）が多い。名詞なら during にする。\"}],\"trapExamples\":[{\"question\":\"「私がねている間に電話が鳴りました。」の空所に入る語を答えなさい。　The phone rang (　) I was sleeping.\",\"wrongAnswer\":\"during\",\"trapExplanation\":\"「〜している間に」という日本語から during を選んでしまう。during は「〜の間」と訳せるので意味の上では合っているように見えるが、後ろに I was sleeping という文が続いている点を見落としている。\",\"correctAnswer\":\"while\",\"correctExplanation\":\"後ろに主語（I）と動詞（was sleeping）のある文が続いているので、接続詞の while を使う。during は前置詞なので、during my sleep のように名詞しか置けない。「後ろが文なら接続詞、名詞なら前置詞」という見分け方は、because と because of、though と in spite of にもそのまま使える。\"},{\"question\":\"「私は京都に滞在している間に、たくさんの寺を訪れました。」を英語にしなさい。\",\"wrongAnswer\":\"I visited many temples while my stay in Kyoto.\",\"trapExplanation\":\"前の問題で「〜している間に＝while」と覚えたため、後ろが名詞でも while を使ってしまう。while と during を訳語だけで覚えていると、こうして逆向きの誤りが起きる。\",\"correctAnswer\":\"I visited many temples during my stay in Kyoto.\",\"correctExplanation\":\"my stay は名詞なので、前置詞の during を使う。while にしたければ while I stayed in Kyoto のように文の形に直す必要がある。訳語ではなく「後ろの形」で選ぶ、という原則をここで徹底しておくと、以降の接続詞の学習が楽になる。\"}]}",
"{\"id\":\"eigo_s282\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"その他の前置詞①：with と without\",\"description\":\"道具・同伴・特徴を表す with と、その反対の without の使い方を身につける\",\"intro\":\"with は「〜といっしょに」だけの語ではありません。cut it with a knife なら道具、a girl with long hair なら特徴を表します。反対の without も同じように広く使えます。一つの前置詞が持つ意味の広がりを、場面ごとに見ていきましょう。\",\"order\":782,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"with ＝ 〜と一緒に／〜を使って／〜を持っている。\",\"道具は with、交通手段や動作をする人は by（cut with a knife / by bus / by Soseki）。\",\"with は名詞を後ろから説明できる（the girl with long hair）。\",\"without ＝ 〜なしで。前置詞なので後ろの動詞は ing 形（without saying a word）。\",\"be filled with（〜でいっぱいだ）、be covered with（〜におおわれている）は熟語で覚える。\"],\"sections\":[{\"heading\":\"with の三つの意味\",\"body\":\"with は使う場面が広い前置詞なので、意味を三つに分けて整理する。\\n\\n■ ①〜と一緒に（同伴）\\n例）I went to the park with my friends.（私は友達と公園へ行きました。）\\n例）She lives with her grandmother.（彼女は祖母と一緒に住んでいます。）\\n\\n■ ②〜を使って（道具）\\n例）He cut the bread with a knife.（彼はナイフでパンを切りました。）\\n例）Write your name with a pen.（ペンで名前を書きなさい。）\\n道具には with、交通手段には by を使う。この区別が入試でよく問われる。\\n例）I go to school by bike.（私は自転車で学校へ行きます。）… 手段なので by\\n\\n■ ③〜を持っている（特徴）\\n名詞を後ろから説明する形で使う。\\n例）the girl with long hair（長い髪の少女）\\n例）a house with a large garden（大きな庭のある家）\\n例）Do you know the boy with glasses?（めがねをかけた少年を知っていますか。）\\n\\n★ ポイント：「一緒に」「使って」「持っている」の三つを覚えれば、with の問題はほとんど解ける。\",\"figureId\":\"xf_eigo_s282\"},{\"heading\":\"without と、with を使う熟語\",\"body\":\"without は with の反対で「〜なしで」を表す。前置詞なので、後ろに動詞を続けたいときは ing 形（動名詞）にする。\\n\\n■ without ＋ 名詞\\n例）I can't read without my glasses.（私はめがねなしでは読めません。）\\n例）He went out without an umbrella.（彼はかさを持たずに出かけた。）\\n\\n■ without ＋ 動詞のing形\\n例）He left the room without saying a word.（彼は一言も言わずに部屋を出て行った。）\\n例）She went out without eating breakfast.（彼女は朝食を食べずに出かけた。）\\n× without say / × without to say とはしない。前置詞の後ろの動詞は必ず ing 形になる。\\n\\n■ with を使う重要熟語\\nbe filled with ...（〜でいっぱいである）\\n例）The box was filled with old books.（箱は古い本でいっぱいだった。）\\nbe covered with ...（〜でおおわれている）\\n例）The mountain was covered with snow.（山は雪でおおわれていた。）\\nbe pleased with ...（〜が気に入っている）\\nhelp ... with ～（…の～を手伝う）\\n例）He helped me with my homework.（彼は私の宿題を手伝ってくれた。）\\nagree with ...（〜に賛成する）\\n\\n⚠ 注意：help me my homework とは言わない。手伝う内容の前には with が必要である。\",\"mangaId\":\"eigo_s282_xm\"}],\"trapExamples\":[{\"question\":\"「彼はナイフでパンを切りました。」の空所に入る語を答えなさい。　He cut the bread (　) a knife.\",\"wrongAnswer\":\"by\",\"trapExplanation\":\"「〜で」という日本語が、go by bus（バスで行く）の by と結び付いてしまう。日本語の助詞「で」は手段にも道具にも使えるため、区別する手がかりが日本語には残っていない。\",\"correctAnswer\":\"with\",\"correctExplanation\":\"手に持って使う道具には with を使う。by が使えるのは by bus・by train のような交通手段や、by Soseki（漱石によって）のような動作をする人を表すときである。「手に持てるものは with、乗り物や作った人は by」と区別して覚える。\"},{\"question\":\"「彼は一言も言わずに部屋を出て行きました。」の下線部の誤りを直しなさい。　He left the room without say a word.\",\"wrongAnswer\":\"誤りはない（without say でよい）\",\"trapExplanation\":\"「言わずに」という日本語をそのまま英語にしようとして、動詞の原形をそのまま置いてしまう。without を接続詞のように感じてしまうのが原因である。\",\"correctAnswer\":\"He left the room without saying a word.\",\"correctExplanation\":\"without は前置詞なので、後ろに動詞を置くときは ing 形（動名詞）にする。同じ理由で before eating（食べる前に）、after finishing（終えた後で）、be good at swimming（泳ぐのが得意だ）も ing 形になる。「前置詞の後ろの動詞は ing」と一つの規則として覚えておく。\"}]}",
"{\"id\":\"eigo_s283\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"その他の前置詞②：of と about\",\"description\":\"所有・部分・材料の of と、話題や見当を表す about を整理する\",\"intro\":\"a picture of my father は父を写した写真、a book about dogs は犬について書かれた本です。of は「そのものの一部」、about は「〜について」。日本語ではどちらも「父の写真」「犬の本」と「の」でつなげるので、意識して使い分ける必要があります。\",\"order\":783,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"of ＝ 〜の（所有・部分・材料）。the door of the room, a cup of tea。\",\"be made of ＝ 材料が見て分かる（wood, paper, glass）。be made from ＝ 見て分からない（milk, grapes）。\",\"about ＝ 〜について（話題）／約〜（数の前）。\",\"数の前の about・around は「約」。about ten minutes ＝ 十分ほど。\",\"of は「AのB」を B of A の語順で表す（日本語と逆になる）。\"],\"sections\":[{\"heading\":\"of の使い方と語順\",\"body\":\"of は「〜の」と訳す前置詞で、日本語とは語順が逆になる点にまず慣れる必要がある。\\n\\n■ 語順に注意\\n日本語「その部屋のドア」→ 英語 the door of the room\\n日本語「この本の題名」→ 英語 the title of this book\\n「A の B」は B of A の順に並ぶ。日本語の順のまま the room of the door と書くと、意味が逆になってしまう。\\n\\n■ ①所有・関係\\n例）the name of the city（その都市の名前）\\n例）the end of the story（物語の終わり）\\n人が持ち主のときは of よりも my father's car のように所有格を使うことが多い。\\n\\n■ ②部分・分量\\n例）a cup of tea（一杯の紅茶）／a glass of water（コップ一杯の水）／a piece of paper（一枚の紙）／a lot of books（たくさんの本）\\n数えられない名詞の量を表すときにも of を使う。\\n\\n■ ③材料\\n例）This desk is made of wood.（この机は木でできています。）\\n例）The house is made of stone.（その家は石でできています。）\\n\\n★ ポイント：of は「AのB」を後ろから説明する語。長い日本語ほど、うしろから訳すと英語の順になる。\"},{\"heading\":\"be made of と be made from、そして about\",\"body\":\"材料を表す言い方には二通りあり、見た目で材料が分かるかどうかで使い分ける。\\n\\n■ be made of ＝ 材料の形が残っている\\n例）This chair is made of wood.（このいすは木でできています。）\\n木でできたいすは、見れば木だと分かる。\\n\\n■ be made from ＝ 材料の形が変わっている\\n例）Cheese is made from milk.（チーズは牛乳から作られます。）\\n例）Wine is made from grapes.（ワインはぶどうから作られます。）\\nチーズを見ても牛乳には見えない。このように、姿が変わってしまう場合は from を使う。\\n\\n■ その他の made 表現\\nbe made in ＋ 場所（〜製である）：This car was made in Japan.\\nbe made into ＋ 製品（〜に作りかえられる）：Milk is made into cheese.\\n\\n■ about の二つの意味\\n①〜について（話題）\\n例）We talked about the movie.（私たちはその映画について話しました。）\\n例）This is a book about animals.（これは動物についての本です。）\\n②約〜（数の前）\\n例）It takes about ten minutes.（十分ほどかかります。）\\n例）There were about fifty people.（五十人ほどいました。）\\n\\n⚠ 注意：「約十分間」は for about ten minutes の順に書く。about for とはしない。\"},{\"heading\":\"なぜ of は語順が逆になり、なぜ of と from を使い分けるのか\",\"mangaId\":\"eigo_s283_manga\",\"body\":\"英語は「中心になる語を先に言い、説明をあとに足す」ことばです。「その部屋のドア」なら、中心は「ドア」なので the door を先に言い、どの部屋のドアかを of the room であとから足します。だから「A の B」は B of A の順になり、日本語の順のまま the room of the door と書くと、中心が「部屋」になって意味が逆転します。長い日本語ほど、うしろから訳すと英語の順になります。\\n\\nbe made of と be made from の区別は、**材料の形が残っているか**で決まります。木の机は見れば木だと分かるので of、チーズは見ても牛乳だと分からないので from。of は「そのものの一部・材料そのまま」、from は「出発点から変化した」という前置詞の意味のちがいがそのまま表れています。about が「約」を表すときは、about ten minutes のように数のすぐ前に置くので、for about ten minutes の順になります。\\n\\n■ 確かめのしかた\\n①「A の B」を英語にしたら、**中心の語（B）が先**か。the title of this book（この本の題名）。\\n②材料は**見て分かるか**。分かる（wood・paper・stone・glass）→of。分からない（milk・grapes）→from。\\n③about が「約」なら、**数のすぐ前**に置く。for about thirty minutes（× about for）。at about seven、in about a week。\\n④of の三つの使い方：所有（the name of the city）、部分・分量（a cup of tea）、材料（made of wood）。\\n\\n★ ここがポイント：英語は**中心の語を先に言う**ので「A の B」は **B of A**。材料は**見て分かるなら of、分からないなら from**。「約」の about は数のすぐ前。\",\"figureId\":\"xf_eigo_s283\"}],\"trapExamples\":[{\"question\":\"「この机は木でできています。」の空所に入る語を答えなさい。　This desk is made (　) wood.\",\"wrongAnswer\":\"from\",\"trapExplanation\":\"Cheese is made from milk. という文を先に覚えていると、材料を表すのはすべて from だと思ってしまう。日本語ではどちらも「〜でできている」「〜から作られる」と言えるので区別がつかない。\",\"correctAnswer\":\"of\",\"correctExplanation\":\"木の机は、見れば材料が木だと分かるので be made of を使う。牛乳からできたチーズのように、見ても元の材料が分からないものは be made from を使う。「見て分かるなら of、分からないなら from」と判断する。ほかに紙・ガラス・石・鉄はふつう of の仲間である。\"},{\"question\":\"「私は約三十分待ちました。」を英語にしなさい。\",\"wrongAnswer\":\"I waited about for thirty minutes.\",\"trapExplanation\":\"「約」を先に訳したくなるため、about を for の前に置いてしまう。日本語では「約三十分」と、まず「約」を言うので、その順のまま英語に置きかえてしまうのが原因である。\",\"correctAnswer\":\"I waited for about thirty minutes.\",\"correctExplanation\":\"前置詞 for が先に来て、その後ろに about thirty minutes（約三十分）というかたまりが続く。about は thirty minutes という数の部分だけを修飾しているので、数のすぐ前に置く。同じ形で at about seven（七時ごろに）、in about a week（一週間ほどで）も覚えておく。\"}]}",
"{\"id\":\"eigo_s284\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"その他の前置詞③：like・as と群前置詞\",\"description\":\"「〜のように」の like と「〜として」の as、二語以上でできた前置詞を学ぶ\",\"intro\":\"He works like a teacher. と He works as a teacher. — 前者は「先生のように働く」で本当は先生ではなく、後者は「先生として働く」で本当に先生です。like と as で、事実かどうかが変わってしまいます。二語以上でできた前置詞もあわせて学びます。\",\"order\":784,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"like ＝ 〜のように（実際はちがうが似ている）。\",\"as ＝ 〜として（実際にそうである）。work as a teacher。\",\"like は前置詞、as は前置詞にも接続詞にもなる。\",\"群前置詞：because of（〜のせいで）、thanks to（〜のおかげで）、instead of（〜の代わりに）、according to（〜によれば）、in spite of（〜にもかかわらず）。\",\"because ＋ 文／because of ＋ 名詞。形で使い分ける。\"],\"sections\":[{\"heading\":\"like と as のちがい\",\"mangaId\":\"eigo_s284_manga\",\"body\":\"どちらも「〜のように」と訳せるが、実際にそうなのかどうかで意味が大きく変わる。\\n\\n■ like ＝ 〜のように（似ているだけ）\\n例）He swims like a fish.（彼は魚のように泳ぐ。）… 彼は魚ではない\\n例）She sings like a professional singer.（彼女はプロの歌手のように歌う。）… プロではない\\n例）It looks like rain.（雨が降りそうだ。）\\n\\n■ as ＝ 〜として（実際にそうである）\\n例）He works as a teacher.（彼は先生として働いている。）… 実際に先生である\\n例）I used the box as a chair.（私はその箱をいすとして使った。）\\n例）She is famous as a pianist.（彼女はピアニストとして有名だ。）\\n\\n■ 比べてみる\\nHe worked like a doctor.（彼は医者のように働いた。）… 医者ではない\\nHe worked as a doctor.（彼は医者として働いた。）… 医者である\\n一語ちがうだけで、その人の職業が変わってしまう。\\n\\n■ as は接続詞にもなる\\n例）As I was tired, I went to bed early.（疲れていたので早く寝ました。）… 理由\\n例）Do as I say.（私が言うとおりにしなさい。）… 様態\\n\\n★ ポイント：like は「本物ではないがそっくり」、as は「本物である」。\",\"figureId\":\"xf_eigo_s284\"},{\"heading\":\"二語以上でできた前置詞（群前置詞）\",\"body\":\"二語や三語がまとまって、一つの前置詞のはたらきをするものを群前置詞という。後ろには必ず名詞（または動名詞）が来る。\\n\\n■ よく出る群前置詞\\nbecause of ...（〜のせいで・〜が原因で）\\n例）The game was canceled because of the rain.（雨のため試合は中止になった。）\\nthanks to ...（〜のおかげで）\\n例）Thanks to your help, I finished it.（あなたの助けのおかげで終わりました。）\\ninstead of ...（〜の代わりに）\\n例）I drank tea instead of coffee.（コーヒーの代わりに紅茶を飲みました。）\\naccording to ...（〜によれば）\\n例）According to the news, it will snow tomorrow.（ニュースによれば明日は雪が降るそうだ。）\\nin spite of ...（〜にもかかわらず）\\n例）He went out in spite of the rain.（雨にもかかわらず彼は出かけた。）\\nin front of ...（〜の前に）／in the middle of ...（〜の真ん中に）／for example（例えば）\\n\\n■ 前置詞か接続詞かの見分け\\nbecause of ＋ 名詞 ／ because ＋ 主語＋動詞\\nin spite of ＋ 名詞 ／ though ＋ 主語＋動詞\\n\\n⚠ 注意：because of の後ろに文を置く誤り（× because of it was raining）が多い。文を置くなら of を取る。\"}],\"trapExamples\":[{\"question\":\"「彼は先生として働いています。」の空所に入る語を答えなさい。　He works (　) a teacher.\",\"wrongAnswer\":\"like\",\"trapExplanation\":\"「〜のように」と「〜として」の区別が日本語であいまいなため、よく知っている like を選んでしまう。like a teacher と書くと「先生ではないが、先生のような働き方をしている」という別の意味になってしまう。\",\"correctAnswer\":\"as\",\"correctExplanation\":\"実際にその職業や役割についているときは as を使う。like は「実際はちがうが似ている」ことを表す。He swims like a fish.（彼は魚のように泳ぐ）の彼が魚でないのと同じで、like を使うとその人は先生ではないことになる。実在するかどうかで選び分ける。\"},{\"question\":\"「雨のせいで試合は中止になりました。」の下線部の誤りを直しなさい。　The game was canceled because the rain.\",\"wrongAnswer\":\"誤りはない（because the rain でよい）\",\"trapExplanation\":\"「〜のせいで」という日本語から because を選ぶところまでは正しいが、because が接続詞であることを意識していないため、後ろに名詞だけを置いてしまう。\",\"correctAnswer\":\"The game was canceled because of the rain.\",\"correctExplanation\":\"because は接続詞なので、後ろには主語＋動詞のある文が必要である。the rain という名詞だけを置くなら、群前置詞の because of にしなければならない。because it rained（雨が降ったので）と書けば because のままでも正しい。「名詞なら because of、文なら because」と形で決める。\"}]}",
"{\"id\":\"eigo_s285\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"等位接続詞①：and・but・or・so の基本\",\"description\":\"対等なものをつなぐ四つの接続詞と、つなぐときに形をそろえる原則を学ぶ\",\"intro\":\"I like apples and orange. と書くと、少しちぐはぐです。and でつなぐときは apples and oranges のように形をそろえます。等位接続詞は対等なものをつなぐ語なので、両側の形がそろっている必要があるのです。四つの語をまとめて整理します。\",\"order\":785,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"and（そして）／but（しかし）／or（または）／so（だから）は対等なものをつなぐ。\",\"つなぐものは同じ形にそろえる（名詞と名詞、ing形とing形）。\",\"三つ以上を並べるときは A, B, and C の形（最後だけ and）。\",\"否定文の「〜も…も」は or を使う（I don't like cats or dogs.）。\",\"日本語の「〜なので、だから」につられて because と so を同じ文で二つ使わない。\"],\"sections\":[{\"heading\":\"四つの等位接続詞\",\"body\":\"等位接続詞は、語と語、句と句、文と文を対等な関係でつなぐ。\\n\\n■ and（そして・と）\\n例）Tom and Ken are good friends.（トムとケンは仲のよい友達です。）\\n例）I got up early and went for a walk.（私は早く起きて散歩に行きました。）\\n\\n■ but（しかし）\\n例）He is young but very strong.（彼は若いがとても力が強い。）\\n例）I called him, but he did not answer.（私は彼に電話したが、彼は出なかった。）\\n\\n■ or（または）\\n例）Which do you like better, summer or winter?（夏と冬ではどちらが好きですか。）\\n例）You can go by bus or by train.（バスか電車で行けます。）\\n否定文では「〜も…も（ない）」の意味になる。\\n例）I don't like cats or dogs.（私はねこも犬も好きではありません。）\\n\\n■ so（だから）\\n例）It was raining, so we stayed home.（雨が降っていたので、私たちは家にいました。）\\nso は結果を表し、because（理由）とちょうど逆向きの関係になる。\\n例）We stayed home because it was raining.（同じ内容を理由から言った文）\\n\\n■ 三つ以上並べるとき\\n例）I bought apples, oranges, and bananas.（私はりんごとみかんとバナナを買いました。）\\n\\n★ ポイント：and・but・or・so は文の先頭に置くより、二つをつなぐ位置に置くのが基本である。\",\"figureId\":\"xf_eigo_s285\"},{\"heading\":\"つなぐものは形をそろえる\",\"body\":\"等位接続詞でつなぐときは、前後を同じ種類・同じ形にそろえなければならない。これを並列といい、英作文の減点で最も多い項目の一つである。\\n\\n■ 名詞と名詞\\n例）I like apples and oranges.（りんごとみかんが好きです。）\\n\\n■ 動詞と動詞（形もそろえる）\\n例）He opened the door and went out.（彼はドアを開けて出て行った。）… 過去形と過去形\\n　　× He opened the door and go out.\\n\\n■ ing形とing形\\n例）I like reading books and listening to music.（私は読書と音楽を聞くことが好きです。）\\n　　× I like reading books and to listen to music.\\n\\n■ 形容詞と形容詞\\n例）She is kind and cheerful.（彼女は親切で明るい。）\\n\\n■ to 不定詞と to 不定詞\\n例）I want to eat lunch and to take a rest.（昼食を食べて休みたい。）\\n二つ目の to は省略してもよい。\\n\\n⚠ 注意：日本語の「〜ので、だから…」を英語にするとき、Because ... , so ... と両方書いてしまう誤りが非常に多い。英語では理由を because で表したら so は書かない。どちらか一方だけを使う。\",\"mangaId\":\"eigo_s285_xm\"}],\"trapExamples\":[{\"question\":\"「私は音楽を聞くことと歌うことが好きです。」の下線部の誤りを直しなさい。　I like listening to music and to sing.\",\"wrongAnswer\":\"誤りはない（and to sing でよい）\",\"trapExplanation\":\"like の後には ing 形も to 不定詞もどちらも使えると習うため、一つの文の中で両方を混ぜても正しいと思ってしまう。日本語では「聞くことと歌うこと」と同じ形になっているのに、英語では形がずれていることに気づけない。\",\"correctAnswer\":\"I like listening to music and singing.\",\"correctExplanation\":\"and でつなぐものは同じ形にそろえる。前が listening という ing 形なので、後ろも singing にする。両方を to 不定詞にして I like to listen to music and to sing. としてもよいが、ing と to をまぜてはいけない。「and・but・or の前後は同じ形」と覚える。\"},{\"question\":\"「彼は疲れていたので、早く寝ました。」を英語にしなさい。\",\"wrongAnswer\":\"Because he was tired, so he went to bed early.\",\"trapExplanation\":\"日本語の「疲れていたので、だから早く寝た」という言い方に引きずられ、because と so を両方書いてしまう。日本語では自然なので、書いた本人は誤りだと気づきにくい。\",\"correctAnswer\":\"Because he was tired, he went to bed early.（または He was tired, so he went to bed early.）\",\"correctExplanation\":\"英語では、理由と結果を結ぶ語は一つだけでよい。because で理由を示したら so は書かず、so で結果を示したら because は書かない。二つ使うと接続詞が重なってしまい誤りになる。同じ誤りが though と but の組み合わせでも起こるので注意する。\"}]}",
"{\"id\":\"eigo_s286\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"等位接続詞②：命令文, and 〜／命令文, or 〜\",\"description\":\"「そうすれば」の and と「そうしないと」の or を、条件文への書きかえとともに覚える\",\"intro\":\"Get up early, and you can see the sunrise.（早く起きなさい、そうすれば日の出が見られる）。Get up early, or you will be late.（早く起きなさい、さもないとおくれる）。and と or の一語で、ごほうびと警告が入れかわります。\",\"order\":786,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"命令文, and ... ＝ 「〜しなさい、そうすれば…」。\",\"命令文, or ... ＝ 「〜しなさい、そうしないと…」。\",\"and の後は良い結果、or の後は悪い結果が来ることが多い。\",\"If you ... , you will ～ ／ If you don't ... , you will ～ に書きかえられる。\",\"and・or の後の文は未来のことなので will を使う。\"],\"sections\":[{\"heading\":\"二つに分かれる結果\",\"body\":\"命令文の後にコンマを打って and か or を続けると、その命令に従った場合・従わなかった場合の結果を表せる。中学入試でくり返し出題される重要表現である。\\n\\n■ 命令文, and ...（〜しなさい、そうすれば…）\\n例）Hurry up, and you will catch the bus.（急ぎなさい、そうすればバスに間に合います。）\\n例）Study hard, and you will pass the exam.（一生けんめい勉強しなさい、そうすれば試験に合格します。）\\n例）Turn left, and you will see the post office.（左に曲がりなさい、そうすれば郵便局が見えます。）\\n\\n■ 命令文, or ...（〜しなさい、そうしないと…）\\n例）Hurry up, or you will miss the bus.（急ぎなさい、そうしないとバスに乗り遅れます。）\\n例）Study hard, or you will fail the exam.（勉強しなさい、そうしないと試験に落ちます。）\\n例）Put on your coat, or you will catch a cold.（コートを着なさい、そうしないとかぜをひきますよ。）\\n\\n■ 見分け方\\nand の後ろには「良い結果」、or の後ろには「悪い結果」が来ることが多い。catch the bus（間に合う）なら and、miss the bus（乗り遅れる）なら or である。\\n\\n★ ポイント：命令に従った先が and の道、従わなかった先が or の道。一つの命令から二本の道が分かれると考える。\",\"figureId\":\"lf_eigoext08_286\",\"mangaId\":\"eigo_s286_xm\"},{\"heading\":\"if を使った文への書きかえ\",\"body\":\"この形は、if を使った条件文に書きかえられる。書きかえ問題としてよく出題される。\\n\\n■ and の書きかえ\\nHurry up, and you will catch the bus.\\n＝ If you hurry up, you will catch the bus.（急げば、バスに間に合います。）\\n\\n■ or の書きかえ\\nHurry up, or you will miss the bus.\\n＝ If you do not hurry up, you will miss the bus.（急がなければ、バスに乗り遅れます。）\\n＝ Unless you hurry up, you will miss the bus.\\nor の場合は、if の文を否定にすることを忘れない。ここが書きかえ問題の急所である。\\n\\n■ 結果の文は未来形\\nand・or の後ろの文は、これから起こることなので will を使う。\\n例）Get up early, and you will feel better.\\n　　× Get up early, and you feel better.\\n一方、if の文の中は未来のことでも現在形で書く（if you hurry up）。同じ文の中で形がちがう点に注意する。\\n\\n■ 命令文の作り方の確認\\n動詞の原形で始める。ていねいにするなら please を付ける。\\n例）Please be quiet, or the baby will wake up.（静かにしてください、そうしないと赤ちゃんが起きてしまいます。）\\n\\n⚠ 注意：or の書きかえで If you hurry up, ... と肯定のまま書くと、意味が正反対になってしまう。\"}],\"trapExamples\":[{\"question\":\"「急ぎなさい、そうしないと遅れますよ。」の空所に入る語を答えなさい。　Hurry up, (　) you will be late.\",\"wrongAnswer\":\"and\",\"trapExplanation\":\"日本語の「そうしないと」を読み飛ばし、「急ぎなさい、そして…」と続けて読んでしまう。and のほうが先に習う語なので、迷ったときに選びやすいことも原因である。\",\"correctAnswer\":\"or\",\"correctExplanation\":\"「そうしないと」なので or を使う。後ろの you will be late（遅れる）は悪い結果なので、その点からも or だと判断できる。and なら Hurry up, and you will be on time.（急げば間に合います）のように良い結果が続く。後ろが良い結果か悪い結果かで見分ける。\"},{\"question\":\"「急ぎなさい、そうすればバスに間に合いますよ。」の下線部の誤りを直しなさい。　Hurry up, and you catch the bus.\",\"wrongAnswer\":\"誤りはない（you catch the bus でよい）\",\"trapExplanation\":\"if の文の中では未来のことでも現在形を使う、という規則を覚えていると、それをこの形にも当てはめて現在形のままにしてしまう。日本語の「間に合いますよ」も現在形に見えるので気づきにくい。\",\"correctAnswer\":\"Hurry up, and you will catch the bus.\",\"correctExplanation\":\"and・or の後ろは「これから起こる結果」を述べる部分なので、will を使った未来の文にする。現在形にしてよいのは If you hurry up, ... のように if が導く文の中だけである。同じ内容を if で書くと If you hurry up, you will catch the bus. となり、前が現在形、後ろが will になる。\"}]}",
"{\"id\":\"eigo_s287\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"等位接続詞③：and でつないだ主語と、選択疑問文\",\"description\":\"A and B が主語のときの動詞の形、選択疑問文の or、語順の決まりを確かめる\",\"intro\":\"Ken and Tom is my friends. と書きたくなりますが、正しくは Ken and Tom are my friends. です。and でつないだ主語は二人分なので複数あつかいになります。ただし bread and butter のように、一つのものとして扱う例外もあります。\",\"order\":787,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"A and B が主語なら複数扱い（Tom and I are ...）。\",\"英語では自分を最後に置く（you and I / Tom and I）。\",\"選択疑問文（AかBか）は or を使い、Yes / No では答えない。\",\"選択疑問文は or の前を上げ調子、後ろを下げ調子で読む。\",\"not A but B ＝ AではなくB。B の側が本当に言いたいこと。\"],\"sections\":[{\"heading\":\"and でつないだ主語と動詞の形\",\"body\":\"and で二つの語をつないで主語にすると、その主語は複数として扱う。\\n\\n例）Tom and Ken are classmates.（トムとケンは同級生です。）\\n例）My father and mother are teachers.（父と母は先生です。）\\n例）You and I are good friends.（あなたと私は仲のよい友達です。）\\n一つ一つは単数でも、and でつなげば二人以上になるので be動詞は are になる。\\n\\n■ 自分は最後に置く\\n英語では、自分をさす I や me は最後に置くのがふつうである。\\n例）Tom and I went to the park.（トムと私は公園へ行きました。）\\n　　× I and Tom went to the park.\\n例）He invited you and me.（彼はあなたと私を招待しました。）\\n主語なら I、目的語や前置詞の後なら me になる点も忘れない。\\n\\n■ 一体のものは単数扱い\\n二つの語が結び付いて一つのものを表す場合は単数として扱う。\\n例）Bread and butter is my breakfast.（バターをぬったパンが私の朝食です。）\\n中学入試ではここまで問われることは少ないが、and でつないでも必ず複数になるとは限らないことは知っておくとよい。\\n\\n★ ポイント：A and B は複数、動詞は are / were / 原形（三単現の s は付けない）。\",\"figureId\":\"xf_eigo_s287\"},{\"heading\":\"選択疑問文と not A but B\",\"body\":\"or を使って「AかBか」をたずねる文を選択疑問文という。答え方が特殊なので注意する。\\n\\n■ 選択疑問文\\n例）Which do you like better, summer or winter?（夏と冬ではどちらが好きですか。）\\n　－ I like summer better.（夏の方が好きです。）\\n例）Do you go to school by bus or by bike?（あなたはバスで学校へ行きますか、それとも自転車ですか。）\\n　－ I go by bike.（自転車で行きます。）\\nYes や No では答えられない。必ずどちらかを選んで答える。\\n\\n■ 読み方\\nor の前を上げて読み、最後を下げて読む。ふつうの疑問文のように最後まで上げてしまうと、意味が変わってしまう。\\n\\n■ not A but B（AではなくB）\\n例）He is not a teacher but a doctor.（彼は先生ではなく医者です。）\\n例）I want not coffee but tea.（私が欲しいのはコーヒーではなく紅茶です。）\\nbut の後ろが本当に言いたい内容である。\\n\\n■ A or B が主語のときの動詞\\nor でつないだ主語の場合、動詞は近い方（B）に合わせる。\\n例）Either you or he is wrong.（あなたか彼のどちらかが間違っています。）\\nくわしくは相関接続詞のところで学習する。\\n\\n⚠ 注意：選択疑問文で Yes, I do. と答えるのは誤り。どちらを選ぶかを答える。\",\"mangaId\":\"eigo_s287_xm\"}],\"trapExamples\":[{\"question\":\"「トムと私は同級生です。」を英語にしなさい。\",\"wrongAnswer\":\"I and Tom is classmates.\",\"trapExplanation\":\"日本語の「私とトムは」という言い方の順にひかれて I を先に置いてしまい、さらに直前の Tom だけを見て be動詞を is にしてしまう。二つの誤りが同時に起きやすい典型的な文である。\",\"correctAnswer\":\"Tom and I are classmates.\",\"correctExplanation\":\"英語では自分を表す I は最後に置くので Tom and I の順にする。また Tom and I は二人なので複数扱いになり、be動詞は are になる。動詞の直前の語（I）だけを見て決めるのではなく、主語全体が何人なのかを見て決める。\"},{\"question\":\"「あなたは夏と冬のどちらが好きですか。」の空所に入る語を答えなさい。　Which do you like better, summer (　) winter?\",\"wrongAnswer\":\"and\",\"trapExplanation\":\"日本語が「夏と冬」となっているため、「と」をそのまま and に置きかえてしまう。日本語では選択でも「と」を使うので、区別する手がかりが日本語にない。\",\"correctAnswer\":\"or\",\"correctExplanation\":\"二つのうちどちらかを選ばせる選択疑問文では or を使う。and にすると「夏と冬の両方」という意味になってしまい、どちらが好きかという問いと合わなくなる。答えるときは Yes / No ではなく I like summer better. のようにどちらかを選んで答える。\"}]}",
"{\"id\":\"eigo_s288\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"従属接続詞①：時を表す when・before・after・as soon as\",\"description\":\"時を表す副詞節では未来のことも現在形で表す、という重要な規則を身につける\",\"intro\":\"「彼が来たら電話します」は I will call you when he comes. です。「来たら」は未来のことなのに、comes と現在形になっています。時を表す文の中では未来のことも現在形で表す、という英語独特の決まりがあるからです。まずここをおさえます。\",\"order\":788,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"時を表す接続詞：when（〜のとき）／before（〜の前に）／after（〜の後で）／until（〜まで）／as soon as（〜するとすぐに）。\",\"時を表す副詞節の中では、未来のことでも will を使わず現在形で書く。\",\"接続詞の文が前に来るときはコンマで区切る（When he comes, ...）。\",\"同じ when でも「いつ〜か」を表す名詞節では will が使える。\",\"間接疑問の語順は「疑問詞＋主語＋動詞」。疑問文の語順にしない。\"],\"sections\":[{\"heading\":\"時を表す副詞節では未来を現在形で表す\",\"body\":\"接続詞が文と文をつなぐとき、後ろに続く文のかたまりを節という。時を表す接続詞が作る節の中では、未来のことでも will を使わずに現在形で書く、という大切な規則がある。\\n\\n■ 規則の確認\\n例）When he comes, I will tell him.（彼が来たら、私が彼に伝えます。）\\n　　× When he will come, I will tell him.\\n例）I will wait here until she comes back.（彼女が戻るまでここで待ちます。）\\n例）Let's go out after the rain stops.（雨がやんだら出かけましょう。）\\n例）I will call you as soon as I arrive.（着いたらすぐに電話します。）\\n\\nどの文も、接続詞の節の中は現在形、主となる文には will が使われている。日本語ではどちらも「〜たら」「〜します」と未来のことなので、意識しないと両方に will を書いてしまう。\\n\\n■ 時を表す接続詞の仲間\\nwhen（〜のとき）／while（〜している間に）／before（〜する前に）／after（〜した後で）／until, till（〜するまで）／as soon as（〜するとすぐに）／by the time（〜するまでに）\\n\\n■ コンマの位置\\n接続詞の節を前に置くときはコンマで区切り、後ろに置くときはコンマを打たない。\\n例）When I got home, my mother was cooking.\\n例）My mother was cooking when I got home.\\n\\n★ ポイント：時を表す接続詞が見えたら、その節の中に will が入っていないかを必ず確かめる。\",\"figureId\":\"lf_eigoext08_288\",\"mangaId\":\"eigo_s288_xm\"},{\"heading\":\"副詞節と名詞節を見分ける\",\"body\":\"同じ when でも、「〜するとき」という意味なら副詞節、「いつ〜か」という意味なら名詞節になる。名詞節の中では未来のことに will を使ってよい。\\n\\n■ 副詞節（〜するとき）… 現在形\\n例）I will go out when he comes.（彼が来たら出かけます。）\\nこの when 以下は「いつ出かけるか」を説明しているので副詞のはたらきをしている。\\n\\n■ 名詞節（いつ〜か）… will を使える\\n例）I don't know when he will come.（彼がいつ来るのか私は知りません。）\\nこの when 以下は know の目的語になっているので、名詞のはたらきをしている。\\n\\n■ 見分け方\\n接続詞の節を取りのぞいても文が成り立つなら副詞節、取りのぞくと文が成り立たないなら名詞節である。\\nI will go out（成り立つ）→ 副詞節\\nI don't know（何を知らないのか分からない）→ 名詞節\\n\\n■ 間接疑問の語順\\n名詞節の中は疑問文の語順にしない。「疑問詞＋主語＋動詞」の順に並べる。\\n例）Do you know where he lives?（彼がどこに住んでいるか知っていますか。）\\n　　× Do you know where does he live?\\n\\n⚠ 注意：if も同じように、「もし〜なら」の副詞節では現在形、「〜かどうか」の名詞節では will が使える。次の課でくわしく学習する。\"}],\"trapExamples\":[{\"question\":\"「彼が来たら、私に教えてください。」の下線部の誤りを直しなさい。　When he will come, please tell me.\",\"wrongAnswer\":\"誤りはない（when he will come でよい）\",\"trapExplanation\":\"彼が来るのはこれからのことなので、当然 will が要ると考えてしまう。日本語の「来たら」も未来を指しているため、時制をそのまま置きかえると誤りになる。\",\"correctAnswer\":\"When he comes, please tell me.\",\"correctExplanation\":\"時を表す接続詞が作る副詞節の中では、未来のことでも現在形で書く。he は三人称単数なので comes と s を付けることも忘れない。同じ規則が before、after、until、as soon as にも当てはまり、I will call you as soon as I arrive. のように現在形にする。\"},{\"question\":\"「彼がいつ来るか知っていますか。」の下線部の誤りを直しなさい。　Do you know when will he come?\",\"wrongAnswer\":\"誤りはない（when will he come でよい）\",\"trapExplanation\":\"When will he come?（彼はいつ来ますか）という疑問文の語順をそのまま文の中に入れてしまう。もとの疑問文が正しい形なので、そのまま使えるように感じてしまうのが原因である。\",\"correctAnswer\":\"Do you know when he will come?\",\"correctExplanation\":\"疑問詞が文の中に組みこまれると、その後ろは「主語＋動詞」の順にもどる。これを間接疑問という。またこの when は「いつ来るか」という名詞のはたらきをしているので、未来のことに will を使ってよい。「語順は平叙文、時制は素直に」と覚える。\"}]}",
"{\"id\":\"eigo_s289\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"従属接続詞②：条件を表す if と unless\",\"description\":\"「もし〜なら」の if と「〜しなければ」の unless、名詞節の if を区別する\",\"intro\":\"「急がないと電車に乗りおくれるよ」は Unless you hurry, you will miss the train. と言えます。unless は「もし〜しなければ」という意味で、if not とほぼ同じはたらきです。否定の意味がすでに入っているので、not を重ねないよう注意します。\",\"order\":789,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"if ＝ もし〜なら。条件を表す副詞節の中では未来のことも現在形。\",\"unless ＝ もし〜しなければ（＝ if ... not）。unless の中を否定にしない。\",\"「〜かどうか」の if は名詞節なので will を使える（I don't know if he will come.）。\",\"if の節が前に来るときはコンマで区切る。\",\"if I were ... のような仮定法は中学入試では原則不要。まず基本の条件文を確実にする。\"],\"sections\":[{\"heading\":\"条件の if と、未来を現在形で表す規則\",\"mangaId\":\"eigo_s289_manga\",\"body\":\"if は「もし〜なら」と条件を表す接続詞である。時を表す接続詞と同じく、条件を表す副詞節の中では未来のことでも現在形で書く。\\n\\n■ 基本の形\\n例）If it rains tomorrow, I will stay home.（もし明日雨が降ったら、私は家にいます。）\\n　　× If it will rain tomorrow, ...\\n例）If you are free, let's play tennis.（もしひまなら、テニスをしましょう。）\\n例）If you don't hurry, you will be late.（急がなければ、遅れますよ。）\\n\\n■ 語順は入れかえられる\\n例）I will stay home if it rains tomorrow.\\n節を後ろに置くときはコンマを打たない。\\n\\n■ unless ＝ if ... not\\n例）Unless you hurry, you will be late.（急がなければ、遅れますよ。）\\n＝ If you do not hurry, you will be late.\\nunless にはすでに「〜しなければ」という否定の意味が入っているので、その中の動詞をさらに否定形にしてはいけない。\\n\\n■ 命令文, or 〜 との関係\\nHurry up, or you will be late.\\n＝ If you do not hurry up, you will be late.\\n＝ Unless you hurry up, you will be late.\\n同じ内容を三通りに書ける。書きかえ問題でよく問われる。\\n\\n★ ポイント：if の中は現在形、主となる文には will。unless の中は否定にしない。\",\"figureId\":\"xf_eigo_s289\"},{\"heading\":\"「〜かどうか」の if は別のはたらき\",\"body\":\"if には「〜かどうか」という意味もある。このときは名詞のはたらきをする節を作るので、規則が変わる。\\n\\n■ 条件の if（副詞節）… 現在形\\n例）I will go if he comes tomorrow.（明日彼が来るなら、私は行きます。）\\n\\n■ 「〜かどうか」の if（名詞節）… will を使える\\n例）I don't know if he will come tomorrow.（彼が明日来るかどうか、私は知りません。）\\n例）I wonder if it will be sunny tomorrow.（明日晴れるかどうかと思う。）\\nこの if は whether と言いかえられる。know や wonder、ask などの目的語になっている点が特徴である。\\n\\n■ 見分け方\\n「もし〜なら」と訳せるなら副詞節（現在形）、「〜かどうか」と訳せるなら名詞節（will を使える）。訳してみるのが最も確実である。\\n\\n■ 比べてみる\\nI don't know if he comes tomorrow.（彼が明日来るなら、私は知らない）… 不自然\\nI don't know if he will come tomorrow.（彼が明日来るかどうか知らない）… 自然\\nknow の後ろは「知らない内容」なので、名詞節と考えるのが正しい。\\n\\n⚠ 注意：「〜かどうか」の意味では unless に置きかえられない。unless はいつでも「もし〜しなければ」の意味である。\"}],\"trapExamples\":[{\"question\":\"「彼が明日来るかどうか、私は知りません。」の下線部の誤りを直しなさい。　I don't know if he comes tomorrow.\",\"wrongAnswer\":\"誤りはない（if he comes でよい）\",\"trapExplanation\":\"「if の中では未来のことでも現在形」という規則を覚えたばかりなので、意味を考えずに機械的に現在形にしてしまう。規則を覚えた直後ほど起きやすい誤りである。\",\"correctAnswer\":\"I don't know if he will come tomorrow.\",\"correctExplanation\":\"この if は「〜かどうか」の意味で、know の目的語になる名詞節を作っている。名詞節の中では未来のことに will を使ってよい。現在形にしてよいのは「もし〜なら」という条件の副詞節のときだけである。訳して「もし」が入るかどうかで判断する。\"},{\"question\":\"「急がなければ、遅れますよ。」の下線部の誤りを直しなさい。　Unless you don't hurry, you will be late.\",\"wrongAnswer\":\"誤りはない（unless you don't hurry でよい）\",\"trapExplanation\":\"日本語の「急がなければ」に「ない」が入っているため、英語でも don't を書いてしまう。unless の意味を「もし〜なら」とだけ覚えていると、否定を自分で足したくなる。\",\"correctAnswer\":\"Unless you hurry, you will be late.\",\"correctExplanation\":\"unless は一語で「もし〜しなければ」という意味を持つので、その中の動詞を否定形にすると二重否定になり、「急ぐなら遅れる」という逆の意味になってしまう。if を使うなら If you don't hurry, you will be late. と、こちらは否定形が必要である。\"}]}",
"{\"id\":\"eigo_s290\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"従属接続詞③：理由と譲歩の because・though\",\"description\":\"理由を表す because と、「〜だけれども」の though を、日本語との差に注意して使う\",\"intro\":\"「雨がふったので家にいた」を Because it rained, so I stayed home. と書くと誤りになります。日本語の「〜ので、だから」の感覚で because と so を両方使ってしまうのですが、英語ではどちらか一つです。though との使い分けもあわせて確かめます。\",\"order\":790,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"because ＝ 〜なので（理由）。後ろには主語＋動詞のある文が来る。\",\"because of ＋ 名詞。形で使い分ける。\",\"though（although）＝ 〜だけれども（譲歩）。\",\"though と but を同じ文で二つ使わない。because と so も同様。\",\"Why ...? への答えは Because ... で始める（この場合だけ Because ～ だけで答えの文になる）。\"],\"sections\":[{\"heading\":\"理由を表す because と、その仲間\",\"body\":\"理由を表す接続詞は、日本語の「〜ので」「〜から」にあたる。\\n\\n■ because ＝ 〜なので\\n例）I stayed home because it was raining.（雨が降っていたので、私は家にいました。）\\n例）Because he was sick, he did not come to school.（病気だったので、彼は学校に来ませんでした。）\\n\\n■ Why の答えは Because\\n例）Why were you late?（なぜ遅れたのですか。）\\n　－ Because I missed the bus.（バスに乗り遅れたからです。）\\nBecause ～ だけで文を終えるのはふつう避けるが（主となる文が必要）、Why への答えのときは Because ～ だけで文を作ってよい。\\n\\n■ since ／ as も理由を表す\\n例）Since it was cold, we stayed inside.（寒かったので、私たちは中にいました。）\\n例）As I was busy, I could not call you.（忙しかったので、電話できませんでした。）\\nbecause がいちばん強く理由を示し、since と as はやや軽い言い方である。\\n\\n■ so は結果\\n例）It was raining, so I stayed home.（雨が降っていたので、家にいました。）\\nbecause が理由の側、so が結果の側から同じことを述べている。\\n\\n★ ポイント：because ＋ 文、because of ＋ 名詞。後ろの形で必ず確かめる。\",\"figureId\":\"xf_eigo_s290\"},{\"heading\":\"譲歩を表す though と、接続詞を重ねない原則\",\"body\":\"though（または although）は「〜だけれども」という譲歩を表す。日本語の言い方の影響で誤りやすい形なので注意する。\\n\\n■ though ＝ 〜だけれども\\n例）Though he is young, he is very strong.（彼は若いけれども、とても力が強い。）\\n例）Although it was raining, we went out.（雨が降っていたけれども、私たちは出かけました。）\\nthough と although は意味は同じで、although のほうがややかたい言い方である。\\n\\n■ 接続詞を二つ重ねない\\n日本語では「若いけれども、しかし強い」と言えるが、英語では though と but を同じ文で使ってはいけない。\\n　　× Though he is young, but he is very strong.\\n　　○ Though he is young, he is very strong.\\n　　○ He is young, but he is very strong.\\n同じ理由で、Because ... , so ... も誤りである。\\n\\n■ in spite of ＋ 名詞\\n例）In spite of the rain, we went out.（雨にもかかわらず、私たちは出かけました。）\\nthough ＋ 文 ／ in spite of ＋ 名詞、という対応は because と because of の関係と同じである。\\n\\n■ 譲歩の書きかえ\\nThough he was tired, he kept working.\\n＝ He was tired, but he kept working.\\n\\n⚠ 注意：「〜けれども」を英語にするとき、though と but のどちらか一方だけを使う。これは日本語との差から生まれる誤りで、入試でもねらわれやすい。\",\"mangaId\":\"eigo_s290_xm\"}],\"trapExamples\":[{\"question\":\"「彼は若いけれども、とても力が強い。」の下線部の誤りを直しなさい。　Though he is young, but he is very strong.\",\"wrongAnswer\":\"誤りはない（though ... but ... でよい）\",\"trapExplanation\":\"日本語の「若いけれども、しかし強い」という言い方をそのまま英語に置きかえてしまう。日本語では「けれども」と「しかし」を重ねても自然なので、誤りに気づきにくい。\",\"correctAnswer\":\"Though he is young, he is very strong.\",\"correctExplanation\":\"英語では二つの文をつなぐ語は一つでよい。though を使ったら but は書かない。but を使いたければ He is young, but he is very strong. とする。同じ誤りが Because ... , so ... でも起こる。「接続詞は一文に一つ」と覚えておく。\"},{\"question\":\"「雨のせいで試合は中止になりました。」の下線部の誤りを直しなさい。　The game was canceled because of it was raining.\",\"wrongAnswer\":\"誤りはない（because of it was raining でよい）\",\"trapExplanation\":\"because of（〜のせいで）という熟語を覚えたばかりで、後ろに文を続けてしまう。「雨のせいで」という日本語からは because of が自然に出てくるので、形の誤りに気づけない。\",\"correctAnswer\":\"The game was canceled because it was raining.（または because of the rain）\",\"correctExplanation\":\"because of は前置詞のはたらきをするので、後ろには名詞しか置けない。it was raining という文を置くなら of を取って because にする。名詞で書くなら because of the rain とする。「文なら because、名詞なら because of」と後ろの形で決める。\"}]}",
"{\"id\":\"eigo_s291\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"従属接続詞④：that 節と時制の一致\",\"description\":\"「〜ということ」をまとめる that の使い方と、主節が過去のときの時制の一致を学ぶ\",\"intro\":\"I think that he is kind. の that は「〜ということ」をまとめる語で、省略できます。ところが I thought that he was kind. のように、前を過去にすると後ろも過去に変わります。日本語では「親切だと思った」と、後半をそのままにできる部分です。\",\"order\":791,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"that ＝ 〜ということ。think, know, say, hope などの後ろで目的語になる。\",\"この that は省略できる（I think (that) he is right.）。\",\"be glad that ... ／ be sure that ... のように形容詞の後にも使う。\",\"so ... that 〜 ＝ とても…なので〜。\",\"主となる文が過去形なら、that 節の中も過去形にそろえる（時制の一致）。\"],\"sections\":[{\"heading\":\"that が作る名詞のかたまり\",\"body\":\"接続詞の that は、後ろの文全体を「〜ということ」という一つの名詞のかたまりに変える。\\n\\n■ 動詞の目的語になる that 節\\n例）I think that he is right.（私は彼が正しいと思います。）\\n例）I know that she likes music.（私は彼女が音楽が好きだと知っています。）\\n例）He said that he was busy.（彼は忙しいと言いました。）\\nこの that は省略できる。\\n例）I think he is right.（同じ意味）\\n\\n■ that 節を取る主な動詞\\nthink（思う）／know（知っている）／say（言う）／hope（望む）／believe（信じる）／hear（聞く）／find（分かる）\\n\\n■ 形容詞の後の that 節\\n例）I am glad that you came.（あなたが来てくれてうれしいです。）\\n例）I am sure that he will win.（彼はきっと勝つと思います。）\\n例）I am afraid that it will rain.（残念ながら雨が降りそうです。）\\n\\n■ so ... that 〜（とても…なので〜）\\n例）He was so tired that he went to bed early.（彼はとても疲れていたので早く寝た。）\\n例）The book was so interesting that I read it twice.（その本はとてもおもしろかったので二回読んだ。）\\n\\n★ ポイント：that の後ろには必ず「主語＋動詞」がそろった文が来る。\",\"figureId\":\"xf_eigo_s291\"},{\"heading\":\"時制の一致\",\"body\":\"主となる文の動詞が過去形のとき、that 節の中の動詞も過去形にそろえる。これを時制の一致という。日本語にはない規則なので、意識して身につける必要がある。\\n\\n■ 現在の文\\n例）He says that he is busy.（彼は忙しいと言っています。）\\n\\n■ 過去の文\\n例）He said that he was busy.（彼は忙しいと言いました。）\\n日本語では「忙しいと言いました」と、後ろは現在形のように言うが、英語では was に変える。\\n\\n■ そろえ方\\n現在形 → 過去形（is → was、like → liked）\\n現在完了・過去形 → 過去完了（has → had、was → had been）\\nwill → would、can → could、may → might\\n例）She said that she would come.（彼女は来るつもりだと言った。）\\n例）I thought that he could swim.（私は彼が泳げると思っていた。）\\n\\n■ 一致させない場合\\n変わらない事実や現在も続く習慣は現在形のままでよい。\\n例）He said that the earth goes around the sun.（彼は地球は太陽の周りを回っていると言った。）\\n中学入試ではここまで問われることは多くないが、原則として過去にそろえると考えておけばよい。\\n\\n⚠ 注意：say を過去形にしたのに、that 節を現在形のまま残す誤りが非常に多い。said が見えたら that 節の動詞の形を必ず見直す。\",\"mangaId\":\"eigo_s291_xm\"}],\"trapExamples\":[{\"question\":\"「彼は忙しいと言いました。」の下線部の誤りを直しなさい。　He said that he is busy.\",\"wrongAnswer\":\"誤りはない（he is busy でよい）\",\"trapExplanation\":\"日本語では「忙しいと言いました」と、後半を現在形のまま言うので、英語でも is のままにしてしまう。今も忙しいのだから現在形でよい、と考えてしまうのも原因である。\",\"correctAnswer\":\"He said that he was busy.\",\"correctExplanation\":\"主となる文の動詞が said と過去形なので、that 節の中も過去形の was にそろえる。これを時制の一致という。同じように He said that he would come.（来ると言った）、She said that she could swim.（泳げると言った）のように、will は would、can は could に変える。\"},{\"question\":\"「私は彼がどこに住んでいるか知りません。」の下線部の誤りを直しなさい。　I don't know where does he live.\",\"wrongAnswer\":\"誤りはない（where does he live でよい）\",\"trapExplanation\":\"Where does he live?（彼はどこに住んでいますか）という疑問文をそのまま文の中に入れてしまう。もとの疑問文が正しい形なので、そのまま使えると感じてしまう。\",\"correctAnswer\":\"I don't know where he lives.\",\"correctExplanation\":\"疑問詞のかたまりが文の中に入ると「疑問詞＋主語＋動詞」の順になり、does は使わない。does が消えるかわりに動詞に三単現の s が付いて lives となる点も重要である。この間接疑問は that 節と同じく名詞のはたらきをするので、know の目的語になっている。\"}]}",
"{\"id\":\"eigo_s292\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"相関接続詞①：both A and B ／ not only A but also B\",\"description\":\"「AもBも」「AだけでなくBも」を表す形と、そのときの動詞の形を学ぶ\",\"intro\":\"both A and B は「AもBも」という意味です。Both Ken and Tom are tall. のように、二人分なので動詞は複数の形になります。一方 not only A but also B は「AだけでなくBも」。よく似た形が続くので、意味と動詞の形をセットで覚えます。\",\"order\":792,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"both A and B ＝ AもBも両方とも。主語なら複数扱い。\",\"both は必ず and とセット。both A or B とはしない。\",\"not only A but also B ＝ AだけでなくBも。\",\"not only A but also B が主語のときは、動詞は B に合わせる。\",\"not only A but also B ＝ B as well as A（AとBの順が入れかわる）。\"],\"sections\":[{\"heading\":\"both A and B\",\"body\":\"二つの語をペアで使って意味を作る接続詞を相関接続詞という。まず both A and B から確認する。\\n\\n■ both A and B ＝ AもBも両方とも\\n例）I like both English and math.（私は英語も数学も両方好きです。）\\n例）Both Tom and Ken are my friends.（トムもケンも私の友達です。）\\n例）She can play both the piano and the violin.（彼女はピアノもバイオリンも弾けます。）\\n\\n■ 主語になると複数扱い\\nBoth Tom and Ken are ... のように、両方合わせて二人以上になるので be動詞は are になる。is にしない。\\n\\n■ A と B は同じ形にそろえる\\n例）He is both kind and clever.（彼は親切でもあり賢くもある。）… 形容詞と形容詞\\n例）I like both swimming and skiing.（私は水泳もスキーも好きだ。）… ing形とing形\\n相関接続詞でも、等位接続詞と同じく前後の形をそろえる。\\n\\n■ セットの相手をまちがえない\\nboth は必ず and と組む。both A or B とは言わない。同じように either は or、neither は nor と組む。組み合わせが決まっていることが、相関接続詞の最大の特徴である。\\n\\n★ ポイント：both ... and ... は「二つとも」。主語なら動詞は複数形。\",\"figureId\":\"xf_eigo_s292\"},{\"heading\":\"not only A but also B\",\"body\":\"not only A but also B は「AだけでなくBも」という意味で、B のほうに重点がある。\\n\\n■ 基本の形\\n例）He speaks not only English but also French.（彼は英語だけでなくフランス語も話します。）\\n例）She is not only kind but also cheerful.（彼女は親切なだけでなく明るくもある。）\\nalso は省略できる。\\n例）He speaks not only English but French.\\n\\n■ 主語のときは B に合わせる\\n例）Not only he but also I am a member.（彼だけでなく私もその一員です。）\\n動詞は近い方、つまり but also の後ろにある I に合わせるので am になる。he に合わせて is とするのは誤りである。\\n\\n■ B as well as A への書きかえ\\nnot only A but also B ＝ B as well as A\\n例）He speaks not only English but also French.\\n＝ He speaks French as well as English.\\n書きかえると A と B の順が入れかわる点に注意する。as well as を使うときは、動詞は前の主語（B にあたる語）に合わせる。\\n例）She as well as her sisters is a student.（姉妹たちだけでなく彼女も学生です。）\\n\\n⚠ 注意：書きかえ問題では A と B の順が入れかわるため、そのまま同じ順で書いてしまう誤りが多い。日本語に直して確かめる。\",\"mangaId\":\"eigo_s292_xm\"}],\"trapExamples\":[{\"question\":\"「彼だけでなく私もその一員です。」の下線部の誤りを直しなさい。　Not only he but also I is a member.\",\"wrongAnswer\":\"誤りはない（I is でよい）\",\"trapExplanation\":\"文の先頭にある he を主語だと思いこみ、三人称単数の is を選んでしまう。日本語の「彼だけでなく私も」でも先に彼が出てくるので、そちらに引っぱられやすい。\",\"correctAnswer\":\"Not only he but also I am a member.\",\"correctExplanation\":\"not only A but also B が主語のときは、動詞は近い方の B に合わせる。ここでは I なので am になる。同じ規則が either A or B、neither A nor B にも当てはまる。「動詞のいちばん近くにある語に合わせる」と覚えておく。\"},{\"question\":\"「私は英語も数学も両方好きです。」の空所に入る語を答えなさい。　I like both English (　) math.\",\"wrongAnswer\":\"or\",\"trapExplanation\":\"「英語も数学も」という日本語から「どちらでも」というニュアンスを感じ取り、選択の or を選んでしまう。either ... or ... という形を先に覚えていると、both にも or を使ってしまう。\",\"correctAnswer\":\"and\",\"correctExplanation\":\"both は必ず and とセットで使い、both A and B の形になる。or と組むのは either で、either A or B（AかBかどちらか）となる。nor と組むのは neither である。「both と and」「either と or」「neither と nor」の三つの組み合わせを丸ごと覚える。\"}]}",
"{\"id\":\"eigo_s293\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"相関接続詞②：either A or B ／ neither A nor B\",\"description\":\"「AかBのどちらか」「AもBも〜ない」を表す形と、否定文の「〜も」の言い方を学ぶ\",\"intro\":\"either A or B は「AかBのどちらか」、neither A nor B は「AもBも〜ない」。nor という見なれない語が出てきます。また「私も〜ない」と言うときは Me too. ではなく Me neither. です。否定になると「も」の言い方まで変わるのです。\",\"order\":793,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"either A or B ＝ AかBのどちらか。\",\"neither A nor B ＝ AもBも〜ない（not は使わない）。\",\"neither にはすでに否定の意味があるので、二重否定にしない。\",\"肯定文の「〜も」は too、否定文の「〜も」は either。\",\"Me too.（私も）／Me neither.（私も〜ない）。\"],\"sections\":[{\"heading\":\"either A or B と neither A nor B\",\"body\":\"either と neither は形が似ているが、意味は正反対である。\\n\\n■ either A or B ＝ AかBのどちらか\\n例）You can have either tea or coffee.（紅茶かコーヒーのどちらかをどうぞ。）\\n例）Either you or he must go.（あなたか彼のどちらかが行かなければならない。）\\n例）He will come either today or tomorrow.（彼は今日か明日のどちらかに来ます。）\\n\\n■ neither A nor B ＝ AもBも〜ない\\n例）Neither Tom nor Ken came to the party.（トムもケンもパーティーに来ませんでした。）\\n例）I like neither cats nor dogs.（私はねこも犬も好きではありません。）\\nneither にはすでに「どちらも〜ない」という否定の意味が入っているので、not を重ねて使わない。\\n\\n■ 主語のときは B に合わせる\\n例）Either you or he is wrong.（あなたか彼のどちらかが間違っています。）\\n例）Neither he nor I am tired.（彼も私も疲れていません。）\\nどちらも動詞に近い方の語に合わせる。\\n\\n■ 書きかえ\\nNeither Tom nor Ken came. ＝ Tom did not come, and Ken did not come.\\n\\n★ ポイント：either は or、neither は nor。neither の文に not を入れてはいけない。\",\"figureId\":\"xf_eigo_s293\"},{\"heading\":\"「〜も」の言い方：too と either\",\"body\":\"日本語の「私も」は、肯定文と否定文で英語の言い方が変わる。\\n\\n■ 肯定文の「〜も」は too\\n例）I like music, too.（私も音楽が好きです。）\\n例）He is a student, too.（彼も学生です。）\\n\\n■ 否定文の「〜も」は either\\n例）I don't like music, either.（私も音楽が好きではありません。）\\n例）He is not a student, either.（彼も学生ではありません。）\\n否定文で too を使うことはできない。\\n\\n■ 短い受け答え\\nA: I like tennis.（私はテニスが好きです。）\\nB: Me too. ／ So do I.（私もです。）\\nA: I don't like tennis.（私はテニスが好きではありません。）\\nB: Me neither. ／ Neither do I.（私もです。）\\n否定に同意するときは neither を使う。\\n\\n■ also の位置\\nalso は「〜も」を表す副詞で、ふつう動詞の前（be動詞や助動詞の後）に置く。\\n例）He also plays the guitar.（彼はギターも弾きます。）\\n例）She is also a good singer.（彼女は歌もうまい。）\\n\\n⚠ 注意：I don't like it too. は誤り。否定文では either にする。会話文の空所補充でよく問われる。\",\"mangaId\":\"eigo_s293_xm\"}],\"trapExamples\":[{\"question\":\"「私もそれが好きではありません。」の下線部の誤りを直しなさい。　I don't like it too.\",\"wrongAnswer\":\"誤りはない（it too でよい）\",\"trapExplanation\":\"「〜も」を too と覚えているため、否定文でもそのまま使ってしまう。日本語では「私も好きです」と「私も好きではありません」で「も」の形が変わらないので、区別する手がかりがない。\",\"correctAnswer\":\"I don't like it, either.\",\"correctExplanation\":\"否定文で「〜も」と言うときは either を使う。too が使えるのは肯定文だけである。会話では Me neither.（私も好きではない）という言い方もよく使う。「肯定は too、否定は either」と対で覚えておくと、会話文の問題で確実に得点できる。\"},{\"question\":\"「彼も私もその答えを知りませんでした。」の下線部の誤りを直しなさい。　Neither he nor I didn't know the answer.\",\"wrongAnswer\":\"誤りはない（didn't know でよい）\",\"trapExplanation\":\"日本語が「知りませんでした」と否定なので、動詞も否定形にしなければならないと考えてしまう。neither がすでに否定を表していることを見落としている。\",\"correctAnswer\":\"Neither he nor I knew the answer.\",\"correctExplanation\":\"neither は一語で「どちらも〜ない」という否定を表すので、動詞をさらに否定形にすると二重否定になり意味が反対になってしまう。動詞は肯定形のまま knew とする。同じように I like neither cats nor dogs. も don't を入れない。\"}]}",
"{\"id\":\"eigo_s294\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"相関接続詞③：主語と動詞の一致をまとめる\",\"description\":\"both・either・neither・not only・as well as が主語のときの動詞の形を整理する\",\"intro\":\"Both Ken and Tom are 〜 と Either Ken or Tom is 〜。どちらも二人ならんでいるのに、動詞が are と is に分かれます。both は二人まとめて、either はどちらか一人だからです。ならんだ語を見て動詞を決める手順を作っておきましょう。\",\"order\":794,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"both A and B ＝ 複数扱い（are / were / 原形）。\",\"either A or B ／ neither A nor B ／ not only A but also B ＝ 動詞は B に合わせる。\",\"A as well as B ＝ 動詞は A（前の語）に合わせる。\",\"as well as だけ「前の語に合わせる」ので、他と反対だと覚える。\",\"迷ったら、動詞にいちばん近い語を見る（as well as を除く）。\"],\"sections\":[{\"heading\":\"三つのグループに分けて覚える\",\"body\":\"相関接続詞が主語に使われたとき、動詞をどの語に合わせるかは形によって決まっている。三つに分けて整理する。\\n\\n■ ①複数扱いになるもの\\nboth A and B\\n例）Both Tom and Ken are my friends.（トムもケンも私の友達です。）\\n例）Both my father and my mother were teachers.（父も母も先生でした。）\\n二人以上になるので、常に複数の形を使う。\\n\\n■ ②動詞に近い方（B）に合わせるもの\\neither A or B ／ neither A nor B ／ not only A but also B\\n例）Either you or he is wrong.（あなたか彼のどちらかが間違っている。）\\n例）Neither he nor I am late.（彼も私も遅れていない。）\\n例）Not only she but also they are students.（彼女だけでなく彼らも学生です。）\\nどれも but also や or の直後にある語を見て動詞を決める。\\n\\n■ ③前の語（A）に合わせるもの\\nA as well as B\\n例）She as well as her friends is a student.（友達だけでなく彼女も学生です。）\\nas well as は「〜と同様に」と付け足す言い方なので、主役は前の A である。\\n\\n★ ポイント：as well as だけが例外的に「前に合わせる」。それ以外は「近い方に合わせる」。\",\"figureId\":\"xf_eigo_s294\",\"mangaId\":\"eigo_s294_xm\"},{\"heading\":\"書きかえと組み合わせて確かめる\",\"body\":\"動詞の一致は、書きかえ問題とセットで出題されることが多い。書きかえた後に動詞の形を直し忘れる誤りに注意する。\\n\\n■ not only A but also B ⇔ B as well as A\\n例）Not only his brothers but also he is a doctor.\\n（兄弟だけでなく彼も医者です。）… 動詞は近い he に合わせて is\\n＝ He as well as his brothers is a doctor.\\n（同じ意味）… 動詞は前の He に合わせて is\\nたまたま両方 is になっているが、語順を入れかえるときに主語がどれになるかを必ず考える。\\n\\n■ 順を入れかえた場合\\nNot only he but also his brothers are doctors.\\n（彼だけでなく兄弟も医者です。）… 近い his brothers に合わせて are\\nこのように、A と B を入れかえると動詞の形も変わることがある。\\n\\n■ 手順\\n①どの相関接続詞かを見る\\n②複数扱いか、近い方か、前の語かを決める\\n③その語が単数か複数か、何人称かを確かめて動詞を選ぶ\\n\\n■ 否定の形にも注意\\nneither A nor B の文では、動詞に not を入れない。\\n例）Neither he nor she knows the answer.（彼も彼女もその答えを知らない。）\\n\\n⚠ 注意：主語が長くなると、動詞の直前の語だけを見て決めてしまいがちである。必ず主語全体の形を確かめる。\"}],\"trapExamples\":[{\"question\":\"「彼女だけでなく彼らも学生です。」の下線部の誤りを直しなさい。　Not only she but also they is students.\",\"wrongAnswer\":\"誤りはない（they is でよい）\",\"trapExplanation\":\"文の先頭にある she を主語だと考えて、三人称単数の is を選んでしまう。日本語も「彼女だけでなく」と先に彼女が出てくるため、そちらに引きずられやすい。\",\"correctAnswer\":\"Not only she but also they are students.\",\"correctExplanation\":\"not only A but also B が主語のときは、動詞に近い方の B に合わせる。ここでは they なので are になり、補語も複数形の students になる。「but also の後ろの語を見て動詞を決める」と手順を固定しておけば、主語が長くなっても迷わない。\"},{\"question\":\"「友達だけでなく彼女も学生です。」の空所に入る語を答えなさい。　She as well as her friends (　) a student.\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"動詞のすぐ前にある her friends が複数なので are を選んでしまう。not only A but also B で「近い方に合わせる」と覚えた直後だと、同じ規則をここにも当てはめてしまう。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"A as well as B は「Bと同様にAも」という意味で、主役は前の A である。したがって動詞は She に合わせて is になる。as well as だけが「前の語に合わせる」例外で、either or・neither nor・not only but also は「近い方に合わせる」。二つのグループに分けて覚えておく。\"}]}",
"{\"id\":\"eigo_s295\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"前置詞・接続詞の総合演習\",\"description\":\"同じ語が前置詞にも接続詞にもなる場合を見分け、単元全体を入試レベルで確認する\",\"intro\":\"before・after・since は、前置詞にも接続詞にもなります。after school なら前置詞、after I came home なら接続詞です。うしろに名詞が来るか、主語と動詞が来るかで見分けます。単元のしめくくりとして、まぎらわしい語を入試レベルで確かめます。\",\"order\":795,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"前置詞の後ろは名詞（または動名詞）、接続詞の後ろは主語＋動詞のある文。\",\"before・after・since・until・as は前置詞にも接続詞にもなる。\",\"during（前置詞）と while（接続詞）、because of（前置詞）と because（接続詞）はペアで覚える。\",\"空所補充では、まず空所の後ろの形を見る。\",\"this・last・next・every が付いた時の語には前置詞を付けない。\"],\"sections\":[{\"heading\":\"前置詞か接続詞かを後ろの形で見分ける\",\"body\":\"この単元の総まとめとして、いちばん大切な判断のしかたを確認する。空所補充では、空所の後ろの形を見ればほとんど決まる。\\n\\n■ 前置詞の後ろ … 名詞・代名詞・動名詞\\nduring the vacation（休みの間）／because of the rain（雨のせいで）／in spite of the rain（雨にもかかわらず）／before dinner（夕食の前に）／without saying（言わずに）\\n\\n■ 接続詞の後ろ … 主語＋動詞のある文\\nwhile I was sleeping（私がねている間に）／because it rained（雨が降ったので）／though it rained（雨が降ったけれども）／before I ate dinner（夕食を食べる前に）\\n\\n■ ペアで覚える組み合わせ\\nduring ＋ 名詞 ／ while ＋ 文\\nbecause of ＋ 名詞 ／ because ＋ 文\\nin spite of ＋ 名詞 ／ though ＋ 文\\nduring my stay ＝ while I stayed\\n\\n■ どちらにもなる語\\nbefore・after・since・until（till）・as は、前置詞にも接続詞にもなる。\\n例）before dinner（前置詞）／before I had dinner（接続詞）\\n例）since 2020（前置詞）／since I was a child（接続詞）\\n\\n★ ポイント：訳して選ぶのではなく、後ろに主語と動詞があるかどうかで選ぶ。これがいちばん速く、まちがえない。\",\"figureId\":\"xf_eigo_s295\",\"mangaId\":\"eigo_s295_xm\"},{\"heading\":\"単元全体の総まとめ\",\"body\":\"入試直前に確認しておきたい要点を、一覧にしておく。\\n\\n■ 時の前置詞\\nat ＋ 時刻・noon・night ／ on ＋ 曜日・日付・特定の日 ／ in ＋ 月・季節・年・午前午後\\nthis・last・next・every が付いたら前置詞なし\\nin ＋ 期間 ＝ 〜後に（未来）\\n\\n■ 場所の前置詞\\nat ＝ 点／on ＝ 接している／in ＝ 内部\\n番地は at、通りは on、市や国は in\\n乗り物は大きければ on、小さければ in、手段なら by ＋ 無冠詞\\n\\n■ 位置と方向\\nunder と over は真下・真上、below と above は高さの比較\\nbetween は二つ、among は三つ以上\\nthrough（中を抜ける）／across（横切る）／along（沿って）／over（越える）\\n\\n■ 期間\\nfor ＋ 長さ ／ during ＋ 期間の名前 ／ since ＋ 起点（現在完了とともに）\\nuntil ＝ 〜までずっと ／ by ＝ 〜までに\\n\\n■ 接続詞\\n時と条件の副詞節では未来のことも現在形\\n命令文, and ＝ そうすれば ／ 命令文, or ＝ そうしないと\\nboth と and、either と or、neither と nor が組み合わせ\\n動詞は近い方に合わせる（as well as だけ前の語に合わせる）\\n\\n⚠ 注意：英作文では、書き終えたら「前置詞は要るか」「後ろの形は合っているか」「時制は正しいか」を必ず見直す。\"}],\"trapExamples\":[{\"question\":\"空所に入る語を選びなさい。　(　) I was a child, I lived in Osaka.　［During / While］\",\"wrongAnswer\":\"During\",\"trapExplanation\":\"「子どものころ、〜の間」という日本語から during を選んでしまう。during も「〜の間」と訳せるので意味の上では合っているように見えるが、後ろに I was a child という文が続いている点を見落としている。\",\"correctAnswer\":\"While\",\"correctExplanation\":\"後ろに主語（I）と動詞（was）のある文が続いているので、接続詞の while を使う。during は前置詞なので during my childhood のように名詞しか置けない。空所補充では、まず後ろの形を見て「文なら接続詞、名詞なら前置詞」と決めるのが最も確実な解き方である。\"},{\"question\":\"「私は毎朝六時に起きて学校へ行きます。」の下線部の誤りを直しなさい。　I get up at six in every morning and go to school.\",\"wrongAnswer\":\"誤りはない（in every morning でよい）\",\"trapExplanation\":\"in the morning という形が頭にあるため、the を every に置きかえた in every morning を正しい形だと感じてしまう。at six の at が正しいので、文全体が正しく見えてしまうことも原因である。\",\"correctAnswer\":\"I get up at six every morning and go to school.\",\"correctExplanation\":\"this・last・next・every が付いた時の表現には前置詞を付けないので、in は不要である。at six の at は時刻に付く前置詞なのでそのまま残す。また and でつないだ動詞は形をそろえるので、get up と go の両方を現在形にする点も確認しておく。\"}]}",
"{\"id\":\"eigo_s296\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不定詞①：to＋動詞の原形と三つのはたらき\",\"description\":\"不定詞の形をつかみ、名詞的・形容詞的・副詞的の三用法があることを知る\",\"intro\":\"「わたしは泳ぐのが好きです」を英語にするとき、I like swim. とは書けません。like のあとに動詞をそのまま置けないからです。英語では動詞を文の途中に入れるとき、to を付けて「動詞ではない何か」に変える必要があります。その変身のしかたを見ていきます。\",\"order\":796,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"不定詞＝to＋動詞の原形。主語が三人称単数でも、文が過去形でも、to のあとは必ず原形。\",\"三つの用法：名詞的用法（〜すること）・形容詞的用法（〜するための）・副詞的用法（〜するために など）。\",\"用法の見分けは日本語訳ではなく「文の中でどのはたらきをしているか」で決める。\",\"前置詞の to（to school）とは別物。前置詞の to のあとは名詞、不定詞の to のあとは動詞の原形。\",\"不定詞の否定は not to＋動詞の原形。to not とは書かない。\"],\"sections\":[{\"heading\":\"不定詞の形は一つだけ\",\"body\":\"不定詞は「to ＋ 動詞の原形」という、たった一つの形しかない。まわりがどんな形でも、to のあとの動詞は絶対に変化しない。\\n\\n例）I want to play soccer.（わたしはサッカーをしたい）\\n例）She wants to play soccer.（彼女はサッカーをしたい）\\n例）He wanted to play soccer.（彼はサッカーをしたかった）\\n\\n■ 三人称単数の s は付けない\\n二番目の文で s が付いているのは wants だけである。to play を to plays にしてはいけない。s を付けるかどうかを決めるのは「文の主語と結びついた動詞」だけであり、to のあとの動詞は主語と直接結びついていないからである。\\n\\n■ 過去形にもしない\\n三番目の文で過去にしているのも wanted だけで、to play はそのままである。「したかった」の「したい」の部分だけが過去になり、「サッカーをする」という中身は形を変えない。\\n\\n■ 否定は not を to の前に置く\\n例）I decided not to go to the party.（わたしはパーティーに行かないことに決めた）\\n「行かないこと」とひとかたまりで否定するので、not は to のすぐ前に置く。\\n\\n★ ポイント：不定詞が出てきたら、まず「to ＋ 原形」の二語をひとかたまりの箱として囲む。この箱は文の中で名詞・形容詞・副詞のどれかのはたらきをする。\",\"mangaId\":\"eigo_s296_xm\"},{\"heading\":\"三つの用法の見取り図\",\"body\":\"同じ「to ＋ 原形」でも、文の中での役目によって三つに分けられる。\\n\\n■ ①名詞的用法（〜すること）\\n名詞と同じはたらきをして、主語・目的語・補語になる。\\n例）I like to read books.（読むことが好きだ）… like の目的語\\n例）To swim is fun.（泳ぐことは楽しい）… 主語\\n\\n■ ②形容詞的用法（〜するための・〜すべき）\\nすぐ前の名詞を、後ろから説明する。\\n例）I have a lot of homework to do.（するべき宿題がたくさんある）… homework を説明\\n\\n■ ③副詞的用法（〜するために・〜して）\\n動詞や形容詞に説明を付け加える。目的や感情の原因を表す。\\n例）I went to the park to play soccer.（サッカーをするために公園へ行った）\\n例）I am happy to see you.（あなたに会えてうれしい）\\n\\n■ 見分けの手順\\nまず不定詞の直前を見る。直前が名詞なら形容詞的用法の可能性が高い。動詞の直後で「〜することを」と入るなら名詞的用法。文全体から取りのぞいても文が成り立つなら副詞的用法である。\\n\\n⚠ 注意：日本語訳だけで決めようとすると失敗する。「〜するために」と訳せても、その部分を消して文が成り立たないなら名詞的用法である。\",\"figureId\":\"lf_eigoext09_296\"}],\"trapExamples\":[{\"question\":\"（　）に become を適する形にして入れなさい。She wants (　) a doctor.\",\"wrongAnswer\":\"to becomes\",\"trapExplanation\":\"主語 She が三人称単数なので、文中の動詞にはすべて s を付けなければいけないと思いこみ、to のあとの動詞にまで s を付けてしまう。\",\"correctAnswer\":\"to become\",\"correctExplanation\":\"s が付くのは主語と直接結びついた動詞だけである。この文では wants にすでに s が付いており、to のあとは必ず原形なので to become が正しい。「She wanted to become a doctor.」のように過去の文でも to become は変わらない。\"},{\"question\":\"誤りを直しなさい。I decided not go to the party.\",\"wrongAnswer\":\"I don't decided to go to the party.\",\"trapExplanation\":\"「行かないことに決めた」という日本語につられて、否定は文全体の動詞に付けるものだと考え、don't を decided の前に出してしまう。それでは「決めなかった」という別の意味になる。\",\"correctAnswer\":\"I decided not to go to the party.\",\"correctExplanation\":\"否定したいのは「決めた」ではなく「行くこと」の方である。不定詞の内容だけを否定するときは not を to のすぐ前に置いて not to go とする。「決めなかった」なら I didn't decide to go to the party. となり、意味がまったく変わる。\"}]}",
"{\"id\":\"eigo_s297\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"名詞的用法①：want to 〜／like to 〜（〜することを）\",\"description\":\"動詞の目的語になる不定詞をつかみ、want to・like to の語順を身につける\",\"intro\":\"「何か飲みたい」を I want drink. と言っても通じません。英語は動詞を二つ続けて並べられないからです。あいだに to を一つ入れて I want to drink. とすると、とたんに正しい文になります。この to のはたらきと、いっしょに使う動詞を身につけます。\",\"order\":797,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"名詞的用法の不定詞は「〜すること」と訳し、名詞と同じ位置に入る。\",\"want to 〜＝〜したい／like to 〜＝〜するのが好き／need to 〜＝〜する必要がある。\",\"語順は「主語＋動詞＋to＋動詞の原形＋（その他）」。動詞が二つ続いて見えるのが特徴。\",\"want のあとに名詞を置けば「〜がほしい」、to＋原形を置けば「〜したい」。\",\"疑問文・否定文は前の動詞だけを変える（Do you want to 〜? / I don't want to 〜.）。\"],\"sections\":[{\"heading\":\"「〜したい」「〜するのが好き」の作り方\",\"body\":\"動詞のすぐ後ろに置かれた不定詞は、その動詞の目的語になる。日本語では「〜することを」「〜するのが」と訳す。\\n\\n例）I want to drink water.（わたしは水を飲みたい）\\n例）She likes to sing songs.（彼女は歌を歌うのが好きだ）\\n例）We need to leave now.（わたしたちは今出発する必要がある）\\n\\n■ want の二つの使い方\\n名詞を置く場合　　例）I want a new bike.（新しい自転車がほしい）\\n不定詞を置く場合　例）I want to buy a new bike.（新しい自転車を買いたい）\\n「ほしい」のか「したい」のかで、後ろに置くものが変わる。\\n\\n■ 動詞が二つ並んで見える\\nwant to drink のように、動詞が二つ続いているように見えるのが名詞的用法の目印である。英語では動詞を二つそのまま並べることはできないので、あいだに to を入れて「二つ目は動詞ではなく名詞のかたまりですよ」と示している。\\n\\n■ 疑問文・否定文\\n例）Do you want to go to the zoo?（動物園に行きたいですか）\\n例）I don't want to go there.（そこには行きたくない）\\n形を変えるのは前の動詞（want）だけで、to go は最後まで原形のままである。\\n\\n★ ポイント：「したい」＝want to、「する必要がある」＝need to、「〜しようとする」＝try to は、そのまま二語セットで覚えてしまうとよい。\",\"figureId\":\"lf_eigoext09_297\",\"mangaId\":\"eigo_s297_xm\"},{\"heading\":\"would like to 〜 とていねいな言い方\",\"body\":\"want to 〜 はまっすぐな言い方なので、ていねいに言いたいときは would like to 〜 を使う。\\n\\n例）I would like to have a cup of tea.（紅茶を一杯いただきたいのですが）\\n例）Would you like to come with us?（わたしたちといっしょに来ませんか）\\n\\n短縮形は I'd like to 〜 となる。中学受験の英語入試でも、ていねいな会話文の中でよく出る。\\n\\n■ 「〜がほしい」のていねい形\\n例）I would like some water.（お水をいただきたいのですが）\\nこのように would like のあとに名詞を置くこともでき、その場合は「〜がほしい」の意味になる。\\n\\n■ Would you like 〜? は勧める表現\\n例）Would you like some cake?（ケーキはいかがですか）\\n食べ物をすすめるときの決まり文句で、答え方は Yes, please.（はい、お願いします）／ No, thank you.（いいえ、けっこうです）である。\\n\\n⚠ 注意：would like のあとの動詞は必ず to を付ける。would like go とはできない。また Would you like to 〜? は「〜しませんか」という誘いなので、Do you want to 〜? よりていねいだと覚えておく。\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしは水を飲みたい」\",\"wrongAnswer\":\"I want drink water.\",\"trapExplanation\":\"「飲みたい」を want と drink の二語で表そうとして、動詞を二つそのまま並べてしまう。日本語では「飲み＋たい」とくっつくので、英語でも直接つながると思いこみやすい。\",\"correctAnswer\":\"I want to drink water.\",\"correctExplanation\":\"英語では動詞を二つ続けて置けない。二つ目の動詞は to を付けて名詞のかたまり（不定詞）にしてから、want の目的語として置く。「I want water.（水がほしい）」と「I want to drink water.（水を飲みたい）」のちがいを声に出して確かめるとよい。\"},{\"question\":\"（　）に適する語を入れなさい。My sister likes (　) (　) pictures.（絵をかくのが好きだ）\",\"wrongAnswer\":\"likes to draws\",\"trapExplanation\":\"主語 My sister が三人称単数だと意識しすぎて、to のあとの draw にまで s を付けてしまう。likes の s に引っぱられる典型的なまちがいである。\",\"correctAnswer\":\"to draw\",\"correctExplanation\":\"三単現の s は主語と直接結びついた動詞（likes）だけに付ける。to のあとは何があっても原形なので to draw。過去の文 My sister liked to draw pictures. でも to draw は変わらない。\"}]}",
"{\"id\":\"eigo_s298\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"名詞的用法②：目的語になる不定詞（hope・decide・try・begin）\",\"description\":\"want・like 以外の、目的語に不定詞をとる重要動詞をまとめて覚える\",\"intro\":\"「医者になりたい」も「医者になろうと決めた」も「医者になろうとした」も、英語ではどれも「動詞＋to＋原形」で作れます。ちがうのは前の動詞だけです。want の形をひとつ覚えれば、hope・decide・try に入れかえるだけで言えることが一気に増えます。\",\"order\":798,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"hope to 〜（〜したいと望む）／decide to 〜（〜することに決める）／try to 〜（〜しようとする）。\",\"begin to 〜・start to 〜（〜し始める）／learn to 〜（〜できるようになる）。\",\"promise to 〜（〜すると約束する）／plan to 〜（〜する計画だ）も入試頻出。\",\"hope to のあとは自分がすること。相手がすることを望むときは hope (that) 節を使う。\",\"「〜しようとしたが、できなかった」は tried to 〜 で表せる。\"],\"sections\":[{\"heading\":\"目的語に不定詞をとる代表的な動詞\",\"body\":\"「これから〜する」という中身を目的語にとる動詞は、不定詞と相性がよい。次の動詞はそのまま二語セットで覚える。\\n\\n例）I hope to see you again.（またあなたに会えることを願っています）\\n例）We decided to go camping.（わたしたちはキャンプに行くことに決めた）\\n例）He tried to open the door.（彼はドアを開けようとした）\\n例）It began to rain.（雨が降り始めた）\\n例）She learned to ride a bike.（彼女は自転車に乗れるようになった）\\n例）I promised to help my mother.（母を手伝うと約束した）\\n例）They plan to visit Kyoto.（彼らは京都を訪れる計画だ）\\n\\n■ 共通するイメージ\\nどれも「まだ実現していないこれからのこと」を目的語にしている。望む・決める・試す・始める・約束する・計画する——いずれも行動より前の段階を表す動詞である。この「未来向き」の感じが、不定詞をとる動詞の共通点である。\\n\\n★ ポイント：begin と start は不定詞でも動名詞でも目的語にできる（It began to rain. ＝ It began raining.）。しかし hope・decide・promise・plan は不定詞しか目的語にできない。この区別はあとの単元で詳しく学ぶ。\",\"figureId\":\"xf_eigo_s298\"},{\"heading\":\"hope to と hope that のちがい\",\"body\":\"hope は「〜であればいいなと願う」という動詞で、後ろの形によって願う中身が変わる。\\n\\n■ hope to ＋ 原形（自分がすること）\\n例）I hope to become a teacher.（先生になりたいと思っている）\\n不定詞のあとに主語を書けないので、「〜するのは文の主語（I）自身」に限られる。\\n\\n■ hope (that) ＋ 主語＋動詞（相手や他の人のこと）\\n例）I hope (that) you will get well soon.（あなたが早くよくなることを願っています）\\n別の人がすることを願うときは、that のあとにその人を主語として書く。that は省略できる。\\n\\n■ try to と try 〜ing のちがい\\n例）I tried to call him.（彼に電話しようとした＝実際にはできなかったことが多い）\\n例）I tried calling him.（ためしに電話してみた＝実際にかけた）\\ntry to は「しようと努力する」、try 〜ing は「ためしにやってみる」である。\\n\\n⚠ 注意：I hope you to come. は誤り。hope は「人＋to〜」の形をとらない。I want you to come.（あなたに来てほしい）の want とは形がちがうので混同しないこと。\",\"mangaId\":\"eigo_s298_xm\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしはあなたが試合に勝つことを願っています」\",\"wrongAnswer\":\"I hope you to win the game.\",\"trapExplanation\":\"want you to 〜（あなたに〜してほしい）の形を覚えていると、hope も同じように「hope ＋ 人 ＋ to 〜」と書けると思いこんでしまう。\",\"correctAnswer\":\"I hope (that) you will win the game.\",\"correctExplanation\":\"hope は「人＋to〜」の形をとらない動詞である。自分以外の人について願うときは hope のあとに「主語＋動詞」の文をそのまま続ける。自分のことなら I hope to win the game.（勝ちたいと思っている）と不定詞で言える。\"},{\"question\":\"（　）に適するものを選びなさい。It began (　) hard.（激しく降り始めた）　ア to rain　イ to rained　ウ rain\",\"wrongAnswer\":\"ウ rain\",\"trapExplanation\":\"began がすでに動詞なので、後ろは原形をそのまま置けばよいと考えてしまう。助動詞のあとが原形になる（can rain）ルールと混同するのが原因である。\",\"correctAnswer\":\"ア to rain\",\"correctExplanation\":\"began は助動詞ではなく一般動詞なので、後ろに動詞をそのまま置くことはできない。目的語として置くには to を付けて不定詞にする。イ to rained は to のあとが原形になっていないので誤り。なお It began raining hard. も正しい言い方である。\"}]}",
"{\"id\":\"eigo_s299\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"名詞的用法③：主語・補語になる不定詞\",\"description\":\"To 〜 is ... の主語用法と、My dream is to 〜 の補語用法をおさえる\",\"intro\":\"「サッカーをすることは楽しい」の主語は、「サッカーをすること」という長いかたまりです。英語でもそのまま先頭に置けて、To play soccer is fun. となります。ではこのとき動詞は is か are か——迷いやすいところです。主語や補語になる不定詞を整理します。\",\"order\":799,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"不定詞は主語にもなる。To play tennis is fun.（テニスをすることは楽しい）\",\"主語が不定詞のとき、動詞は is（三人称単数扱い）を使う。\",\"be動詞のあとに置くと補語になる。My dream is to be a vet.（わたしの夢は獣医になることだ）\",\"主語の不定詞は重いので、ふつうは It is fun to play tennis. と It で言いかえる。\",\"名詞的用法は「主語・目的語・補語」の三か所に入る、と場所で覚える。\"],\"sections\":[{\"heading\":\"主語になる不定詞・補語になる不定詞\",\"body\":\"不定詞は名詞と同じはたらきをするので、名詞が入る場所ならどこにでも入る。\\n\\n■ 主語になる（文の先頭）\\n例）To play tennis is fun.（テニスをすることは楽しい）\\n例）To get up early is good for your health.（早く起きることは健康によい）\\n主語は「〜すること」という一つのまとまりなので、動詞は is を使う。To play tennis are fun. とはしない。\\n\\n■ 補語になる（be動詞のあと）\\n例）My dream is to be a vet.（わたしの夢は獣医になることだ）\\n例）Her job is to teach English.（彼女の仕事は英語を教えることだ）\\n「主語＝不定詞の内容」という形で、イコールの関係になっている。\\n\\n■ 目的語になる（動詞のあと）\\n例）I like to play tennis.（テニスをするのが好きだ）\\n\\nこのように名詞的用法は主語・補語・目的語の三か所に現れる。どの位置にあるかを確かめれば、日本語訳に頼らなくても名詞的用法だと判断できる。\\n\\n★ ポイント：不定詞を取りのぞくと文が成り立たなくなる（To play tennis is fun. から To play tennis を消すと is fun だけになる）なら、それは名詞的用法である。\",\"figureId\":\"lf_eigoext09_299\",\"mangaId\":\"eigo_s299_xm\"},{\"heading\":\"主語の不定詞は It で言いかえるのがふつう\",\"body\":\"英語では「長くて重いものは後ろへ回す」という習慣がある。そのため主語が不定詞のときは、形だけの主語 It を先頭に置き、本当の主語である不定詞を後ろへ送るのがふつうである。\\n\\n例）To play tennis is fun.\\n　→ It is fun to play tennis.（テニスをすることは楽しい）\\n例）To speak English is not easy.\\n　→ It is not easy to speak English.（英語を話すことは簡単ではない）\\n\\nこの It には「それ」という意味はなく、訳さない。くわしくは It is ... to 〜 の単元で学ぶ。\\n\\n■ 補語の不定詞は言いかえない\\n例）My dream is to travel around the world.（わたしの夢は世界中を旅することだ）\\n補語の位置はもともと文の後ろなので、そのままでよい。\\n\\n■ 主語が不定詞のときの動詞\\n例）To read books is important.（○）\\n例）To read books are important.（×）\\n不定詞のかたまりは、どんなに長くても一つのものとして扱うので、動詞は is・was など単数の形にする。\\n\\n⚠ 注意：To play tennis is fun. は文法的に正しいが、実際の英文では It is fun to play tennis. の方がずっとよく使われる。英作文ではどちらも正解になるが、書きかえ問題では必ず It の形を求められる。\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。To collect stamps (　) my hobby.（切手を集めることがわたしの趣味です）\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"stamps が複数形なので、すぐ前の名詞に引っぱられて are を選んでしまう。主語は stamps ではなく「To collect stamps（切手を集めること）」全体である。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"主語は「To collect stamps」というひとかたまりの内容で、これは一つのことがらなので単数扱いになる。したがって is が正しい。同じ理由で To read books is important.（○）／are（×）となる。\"},{\"question\":\"次の文の不定詞は何用法か。My dream is to visit Australia.\",\"wrongAnswer\":\"副詞的用法（〜するために）\",\"trapExplanation\":\"「オーストラリアを訪れるために」と訳してしまうと副詞的用法に見える。しかしそう訳すと「わたしの夢はオーストラリアを訪れるためにある」となり、日本語として意味が通らない。\",\"correctAnswer\":\"名詞的用法（〜すること）\",\"correctExplanation\":\"be動詞 is のあとに置かれて「わたしの夢＝オーストラリアを訪れること」というイコールの関係を作っているので、補語になる名詞的用法である。to visit Australia を消すと My dream is. となって文が成り立たない点も、名詞的用法である証拠になる。\"}]}",
"{\"id\":\"eigo_s300\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞的用法①：something to drink（-thing の後ろ）\",\"description\":\"something・anything などを後ろから説明する不定詞の語順を身につける\",\"intro\":\"「何か冷たい飲み物」を英語にするとき、cold something drink のように前から並べたくなります。ところが正しくは something cold to drink。-thing で終わる語だけは、説明の語がすべてうしろに回ります。日本語と逆になるこの並び方を身につけます。\",\"order\":800,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"形容詞的用法の不定詞は、すぐ前の名詞を後ろから説明して「〜するための・〜すべき」を表す。\",\"something to drink（何か飲み物）／something to eat（何か食べ物）が代表例。\",\"-thing で終わる語は形容詞も後ろに置く。something cold（何か冷たいもの）。\",\"語順は「something ＋ 形容詞 ＋ to ＋ 原形」。something cold to drink。\",\"疑問文・否定文では anything を使う。Do you have anything to eat?\"],\"sections\":[{\"heading\":\"名詞を後ろから説明する不定詞\",\"body\":\"形容詞的用法の不定詞は、直前の名詞にくっついて「どんな名詞か」を説明する。日本語では「〜するための」「〜すべき」と訳す。\\n\\n例）I want something to drink.（何か飲むもの＝飲み物がほしい）\\n例）Give me something to eat.（何か食べるものをください）\\n例）I have a lot of homework to do.（するべき宿題がたくさんある）\\n\\n■ 訳し上げるのがコツ\\n英語は「something ← to drink」と後ろから前へかかる。日本語にするときは後ろから先に訳して「飲むための → もの」とすると自然になる。\\n\\n■ -thing で終わる語は形容詞も後ろ\\nふつうの名詞は cold water のように形容詞が前に付くが、something・anything・nothing・everything は形容詞を後ろに置く。\\n例）something cold（何か冷たいもの）\\n例）something interesting（何かおもしろいこと）\\n\\n■ 形容詞と不定詞の両方を付ける語順\\n例）I want something cold to drink.（何か冷たい飲み物がほしい）\\n形容詞が先、不定詞が後ろ、という順番は絶対に入れかわらない。\\n\\n★ ポイント：「何か冷たい飲み物」＝ something（もの）＋ cold（冷たい）＋ to drink（飲むための）と、日本語とは逆の順に並べる。\",\"figureId\":\"lf_eigoext09_300\",\"mangaId\":\"eigo_s300_xm\"},{\"heading\":\"something・anything・nothing の使い分け\",\"body\":\"-thing の語は、文の種類によって使い分ける。\\n\\n■ 肯定文は something\\n例）I have something to tell you.（あなたに話すことがある）\\n\\n■ 疑問文・否定文は anything\\n例）Do you have anything to eat?（何か食べるものはありますか）\\n例）I don't have anything to do today.（今日はすることが何もない）\\n\\n■ nothing は一語で否定を表す\\n例）I have nothing to do today.（今日はすることが何もない）\\n上の don't have anything と同じ意味である。nothing を使うときは don't を付けない。\\n\\n■ 人にすすめる疑問文では something\\n例）Would you like something to drink?（何かお飲み物はいかがですか）\\n「どうぞ」と相手にすすめる気持ちがあるときは、疑問文でも something を使う。レストランの会話文でよく出る。\\n\\n⚠ 注意：I don't have nothing to do. のように否定を二つ重ねてはいけない。英語では否定は文に一つだけである。「何もない」は don't 〜 anything か nothing のどちらか一方で表す。\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「何か冷たい飲み物がほしい」\",\"wrongAnswer\":\"I want cold something to drink.\",\"trapExplanation\":\"日本語の「冷たい飲み物」や cold water の語順につられて、形容詞を something の前に置いてしまう。ふつうの名詞では正しい語順なので、よけいにまちがえやすい。\",\"correctAnswer\":\"I want something cold to drink.\",\"correctExplanation\":\"something・anything・nothing・everything は、形容詞を必ず後ろに置く特別な語である。そのあとに不定詞が続くので、「something ＋ 形容詞 ＋ to ＋ 原形」の順になる。something hot to eat（何か温かい食べ物）も同じ形である。\"},{\"question\":\"（　）に適する語を入れなさい。I don't have (　) to do today.（今日はすることが何もない）\",\"wrongAnswer\":\"nothing\",\"trapExplanation\":\"日本語の「何もない」につられて nothing を選んでしまう。しかし文にはすでに don't があるので、否定が二重になってしまう。\",\"correctAnswer\":\"anything\",\"correctExplanation\":\"英語では一つの文に否定は一つだけである。don't がある文では anything を使い、I don't have anything to do today. とする。don't を使わずに I have nothing to do today. と書けば、これも同じ意味で正しい。\"}]}",
"{\"id\":\"eigo_s301\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞的用法②：a lot of homework to do（名詞を後ろから）\",\"description\":\"ふつうの名詞に不定詞が後ろから付く形を、代表例とともに練習する\",\"intro\":\"「やるべき宿題」「読む本」「話す時間」——日本語ではどれも説明が名詞の前に来ます。英語ではこれが逆で、homework to do、books to read、time to talk と、必ず名詞のうしろに置きます。この一つの型で、言えることがぐんと増えます。\",\"order\":801,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"「〜するための○○」「〜すべき○○」は、名詞のすぐ後ろに不定詞を置く。\",\"a lot of homework to do（するべき宿題）／many books to read（読むべき本）。\",\"time to 〜（〜する時間）／a chance to 〜（〜する機会）／a way to 〜（〜する方法）。\",\"日本語とは逆に「名詞 → 不定詞」の順。不定詞が名詞の前に出ることはない。\",\"the first / the last / the only が付く名詞にも不定詞が後ろから付く。\"],\"sections\":[{\"heading\":\"名詞のすぐ後ろに置く\",\"body\":\"-thing の語だけでなく、ふつうの名詞にも不定詞は後ろから付く。\\n\\n例）I have a lot of homework to do.（するべき宿題がたくさんある）\\n例）She has many books to read.（彼女には読むべき本がたくさんある）\\n例）I have no time to watch TV.（テレビを見る時間がない）\\n例）This is a good chance to practice English.（これは英語を練習するよい機会だ）\\n例）Do you know a way to solve this problem?（この問題を解く方法を知っていますか）\\n\\n■ 位置を絶対にまちがえない\\n不定詞は説明したい名詞の「すぐ後ろ」に置く。to do a lot of homework のように前に出すと、「宿題をたくさんすること」という別の意味（名詞的用法）になってしまう。\\n例）I have a lot of homework to do.（するべき宿題がたくさんある）\\n例）I want to do a lot of homework.（宿題をたくさんしたい）\\n語順が変わると用法も意味も変わる。\\n\\n■ よく使う組み合わせ\\ntime to go（行く時間）／something to say（言うべきこと）／a place to stay（泊まる場所）／money to buy it（それを買うためのお金）\\n\\n★ ポイント：「〜すべき○○」と日本語で言えるときは、必ず「○○ ＋ to ＋ 原形」の順に並べる。\",\"figureId\":\"xf_eigo_s301\",\"mangaId\":\"eigo_s301_xm\"},{\"heading\":\"the first・the only と組み合わせる形\",\"body\":\"順番や唯一性を表す語が付いた名詞にも、不定詞が後ろから付く。上位校の入試や英検3級以上でよく出る形である。\\n\\n例）He was the first person to arrive.（彼は最初に到着した人だった）\\n例）She was the last one to leave the room.（彼女は最後に部屋を出た人だった）\\n例）Tom is the only student to know the answer.（トムはその答えを知っている唯一の生徒だ）\\n\\n■ 訳し方\\n「the first ＋ 名詞 ＋ to 〜」は「最初に〜した○○」と訳す。「〜するための」とすると不自然になるので、順番の語といっしょのときは「最初に〜した」「最後に〜した」と覚えてしまうとよい。\\n\\n■ 名詞的用法との見分け\\n例）I want to be the first to arrive.（最初に着く人になりたい）\\nこの文には to be（名詞的用法）と to arrive（形容詞的用法）が両方入っている。to be は want の目的語、to arrive は the first を説明している。位置を見れば区別できる。\\n\\n⚠ 注意：the first to arrive は「最初に到着した」であり、「最初に到着するつもり」ではない。文全体の時制（was／is）で、いつのことかが決まる。\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしには読むべき本が何冊かある」\",\"wrongAnswer\":\"I have to read some books.\",\"trapExplanation\":\"「読むべき」という日本語から have to（〜しなければならない）を連想して、have と to を続けて書いてしまう。その結果「本を読まなければならない」という別の文になる。\",\"correctAnswer\":\"I have some books to read.\",\"correctExplanation\":\"説明したい名詞（some books）を先に置き、そのすぐ後ろに to read を付ける。have to は「主語＋have to＋原形」で助動詞のはたらきをするが、この文の have は「持っている」という本来の意味である。名詞をあいだにはさむかどうかで、意味がまったく変わる。\"},{\"question\":\"次の文の不定詞は何用法か。She had no time to eat lunch.\",\"wrongAnswer\":\"副詞的用法（昼食を食べるために）\",\"trapExplanation\":\"「昼食を食べるために」と訳せてしまうため、目的を表す副詞的用法だと判断してしまう。しかしそれでは「食べるために時間がなかった」となり意味が通らない。\",\"correctAnswer\":\"形容詞的用法（昼食を食べる時間）\",\"correctExplanation\":\"to eat lunch は直前の名詞 time を説明していて、「昼食を食べる（ための）時間」というかたまりを作っている。判断のこつは、不定詞の直前が名詞かどうかを見ること。名詞の直後にあり、その名詞の内容を説明していれば形容詞的用法である。\"}]}",
"{\"id\":\"eigo_s302\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞的用法③：修飾は前からか後ろからか\",\"description\":\"名詞を説明する語の位置の原則（一語は前・二語以上は後ろ）を理解する\",\"intro\":\"a big house は「大きい家」で前から、a house to live in は「住む家」でうしろから説明します。同じ家の説明なのに、なぜ位置がちがうのでしょう。実は語数で決まっていて、この原則は不定詞にも分詞にも関係代名詞にも共通します。\",\"order\":802,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"一語の形容詞は名詞の前から修飾する（a big house）。\",\"二語以上のかたまり（不定詞・分詞句・関係詞節）は名詞の後ろから修飾する。\",\"この原則は不定詞・分詞・関係代名詞のすべてに共通する、英語の大原則である。\",\"-thing の語だけは例外で、一語の形容詞も後ろに置く（something cold）。\",\"後ろから説明された名詞は、日本語では後ろから前へ訳し上げる。\"],\"sections\":[{\"heading\":\"英語の修飾の大原則\",\"body\":\"名詞を説明する語は、長さによって置く場所が決まっている。この原則を知っておくと、これから学ぶ分詞・関係代名詞まで一気に見通せるようになる。\\n\\n■ 一語なら名詞の前\\n例）a big house（大きな家）\\n例）an interesting book（おもしろい本）\\n例）a sleeping baby（眠っている赤ちゃん）\\n\\n■ 二語以上のかたまりなら名詞の後ろ\\n例）a house to live in（住むための家）… 不定詞\\n例）the baby sleeping in the bed（ベッドで眠っている赤ちゃん）… 分詞句\\n例）the book which I read yesterday（わたしが昨日読んだ本）… 関係詞節\\n\\n同じ「眠っている赤ちゃん」でも、sleeping 一語なら前、sleeping in the bed という二語以上のかたまりなら後ろになる。\\n\\n■ 日本語との決定的なちがい\\n日本語は「わたしが昨日読んだ本」のように、どんなに長い説明でも必ず名詞の前に置く。英語は逆に、長い説明はすべて名詞の後ろに置く。この向きのちがいが、英語の長文読解でつまずく最大の原因である。\\n\\n★ ポイント：名詞が出てきたら、その直後まで目を走らせる。to＋原形・〜ing・過去分詞・who/which/that があれば、そこから後ろは全部その名詞の説明である。\",\"figureId\":\"lf_eigoext09_302\",\"mangaId\":\"eigo_s302_xm\"},{\"heading\":\"訳し上げの練習\",\"body\":\"後ろから説明された名詞は、日本語にするとき順番をひっくり返す。\\n\\n例）This is the best way to learn English.\\n　　→ これは英語を学ぶための最もよい方法だ。\\n例）I need a friend to talk with.\\n　　→ わたしには話し相手が必要だ。\\n例）She has a lot of work to finish today.\\n　　→ 彼女には今日終わらせるべき仕事がたくさんある。\\n\\n■ かたまりの切れ目を見つける\\n長い文では、どこまでが名詞の説明かを見きわめる必要がある。\\n例）The boy standing by the door is my brother.\\nこの文では The boy standing by the door までが主語である。動詞 is が出てきたところで説明部分が終わる、と判断する。\\n\\n■ 主語が長くなる文に慣れる\\n例）The students who study hard get good results.\\n主語は The students who study hard（一生けんめい勉強する生徒たち）で、動詞は get である。名詞のあとに who/which/that が来たら、そこから動詞が二つ目に出てくるまでが説明のかたまりだと考えるとよい。\\n\\n⚠ 注意：「後ろから説明する」形に慣れていないと、the book to read を「本を読む」のように前から順に読んでしまい、文の意味を取りちがえる。名詞と説明のかたまりは必ずセットで囲むくせをつける。\"}],\"trapExamples\":[{\"question\":\"日本語に合うように並べかえなさい。「わたしは何か温かい食べ物がほしい」　want / I / to / hot / eat / something\",\"wrongAnswer\":\"I want hot something to eat.\",\"trapExplanation\":\"「一語の形容詞は名詞の前」という原則を覚えたばかりだと、それを something にも当てはめて hot を前に置いてしまう。\",\"correctAnswer\":\"I want something hot to eat.\",\"correctExplanation\":\"-thing で終わる語（something・anything・nothing・everything）は、この原則の唯一の例外で、一語の形容詞も後ろに置く。「something ＋ 形容詞 ＋ to ＋ 原形」の順を、例外として丸ごと覚えておく。\"},{\"question\":\"下線部はどこまでが主語か。The girl playing the piano over there is my sister.\",\"wrongAnswer\":\"The girl だけが主語で、playing 以下は進行形の動詞\",\"trapExplanation\":\"「The girl is playing the piano（女の子はピアノをひいている）」という進行形の文だと思いこみ、playing を文の動詞として読んでしまう。be動詞が離れた位置にあるので気づきにくい。\",\"correctAnswer\":\"The girl playing the piano over there までが主語（動詞は is）\",\"correctExplanation\":\"playing the piano over there は The girl を後ろから説明するかたまりで、「あそこでピアノをひいている女の子」となる。進行形なら The girl is playing 〜 のように be動詞が 〜ing の直前に来る。be動詞がないまま 〜ing が名詞の直後に続いていたら、それは説明のかたまりだと判断する。\"}]}",
"{\"id\":\"eigo_s303\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形容詞的用法④：a friend to play with（前置詞が残る形）\",\"description\":\"「いっしょに遊ぶ友だち」「住む家」など、文末に前置詞が残る形をおさえる\",\"intro\":\"「いっしょに遊ぶ友だち」を a friend to play で止めると、英語としては足りません。「友だちと遊ぶ」は play with a friend なので、with が必要なのです。文の最後にぽつんと前置詞が残るふしぎな形の理由を、もとの文に戻して確かめます。\",\"order\":803,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"a friend to play with（いっしょに遊ぶ友だち）のように、文末に前置詞が残ることがある。\",\"「〜と話す」なら talk with、「〜に住む」なら live in と、もとの言い方に必要な前置詞が残る。\",\"見分け方：不定詞の中身を文に戻したとき前置詞が必要なら、その前置詞を最後に置く。\",\"a house to live in（住む家）／a pen to write with（書くためのペン）／a chair to sit on（すわるいす）。\",\"前置詞を落とすと減点される。入試で最も差がつくポイントの一つ。\"],\"sections\":[{\"heading\":\"なぜ最後に前置詞が残るのか\",\"mangaId\":\"eigo_s303_manga\",\"body\":\"「いっしょに遊ぶ友だち」を英語にするとき、a friend to play では足りない。play with a friend（友だちといっしょに遊ぶ）というもとの言い方に with が必要だからである。\\n\\n例）I want a friend to play with.（いっしょに遊ぶ友だちがほしい）\\n例）I need a house to live in.（住む家が必要だ）\\n例）Give me a pen to write with.（書くためのペンをください）\\n例）There is no chair to sit on.（すわるいすがない）\\n\\n■ 確かめ方\\n説明されている名詞を、不定詞の後ろに戻してみる。\\n　a friend to play with → play with a friend（○ 友だちと遊ぶ）\\n　a friend to play → play a friend（× 友だちを遊ぶ？意味が通らない）\\n戻したときに前置詞が必要なら、その前置詞を文末に残す。\\n\\n■ 前置詞がいらない場合\\n例）I have some books to read.\\n　→ read some books（本を読む）で前置詞は不要なので、to read だけでよい。\\n例）She has a lot of work to do.\\n　→ do a lot of work（仕事をする）も前置詞は不要である。\\n\\n★ ポイント：「〜する」の部分が目的語を直接とるかどうかで決まる。読む・する・食べるは直接とる（前置詞なし）、遊ぶ・住む・すわるは前置詞が必要である。\",\"figureId\":\"xf_eigo_s303\"},{\"heading\":\"入試でねらわれる形\",\"body\":\"文末の前置詞は、書き落としても文が通じてしまうように見えるため、受験生が最も落としやすい部分である。だからこそ出題される。\\n\\n例）I have no friends to talk with.（話し相手がいない）\\n例）This is a good place to swim in.（ここは泳ぐのによい場所だ）\\n例）He needs someone to work with.（彼はいっしょに働く人を必要としている）\\n例）Do you have anything to write on?（何か書くもの＝紙はありますか）\\n\\n■ write with と write on のちがい\\n例）something to write with（書くための道具＝ペン・えんぴつ）\\n例）something to write on（書くための面＝紙・ノート）\\n道具には with、面には on を使う。この二つを入れかえる問題は英検3級・上位校の入試で頻出である。\\n\\n■ 場所を表すときは in / at\\n例）a place to live in（住む場所）\\n例）a room to study in（勉強する部屋）\\nただし live や study が「そこで」の意味をすでに含んでいる文脈では省かれることもあり、実際の英文では a place to live のように使われる場合もある。中学受験の答案では前置詞を付ける形で覚えておけばよい。\\n\\n⚠ 注意：前置詞は必ず文の最後に置き、to の前には出さない。a friend with to play とは絶対に書かない。\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしはいっしょに遊ぶ友だちがほしい」\",\"wrongAnswer\":\"I want a friend to play.\",\"trapExplanation\":\"「遊ぶ友だち」という日本語をそのまま a friend to play と写してしまう。日本語には「といっしょに」にあたる語が表れないので、必要な with に気づけない。\",\"correctAnswer\":\"I want a friend to play with.\",\"correctExplanation\":\"不定詞の中身を文に戻すと play with a friend となり、with がなければ意味が成り立たない。したがって with を文末に残して a friend to play with とする。同じ理由で a house to live in、a chair to sit on も前置詞が必要である。\"},{\"question\":\"（　）に with か on のどちらかを入れなさい。Do you have anything to write (　)?（何か書く紙はありますか）\",\"wrongAnswer\":\"with\",\"trapExplanation\":\"「書くもの」＝ write with で覚えていると、日本語の「書くもの」だけを見て機械的に with を選んでしまう。しかし求めているのはペンではなく紙である。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"write on 〜 は「〜の上に書く」で、紙やノートなど書く面を表す。write with 〜 は「〜を使って書く」で、ペンやえんぴつなど道具を表す。日本語の「書くもの」は両方を指せるので、かっこの後ろの日本語（紙・ペン）を必ず確かめてから前置詞を選ぶ。\"}]}",
"{\"id\":\"eigo_s304\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"副詞的用法①：目的「〜するために」\",\"description\":\"動作の目的を表す不定詞をつかみ、「なぜ？」に答える形として理解する\",\"intro\":\"「なぜ公園へ行ったの？」に「サッカーをするために」と答えたいとき、英語では To play soccer. のひとことで足ります。because を使わなくてよいのです。動作の目的を to＋動詞の原形で表すこの言い方を、Why への答え方とあわせて練習します。\",\"order\":804,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"副詞的用法の代表は目的で、「〜するために」と訳す。\",\"文の骨組み（主語＋動詞）が先にあり、その後ろに目的の不定詞を付け足す。\",\"Why 〜? への答えとして、To 〜. と不定詞だけで答えられる。\",\"はっきり目的を示したいときは in order to 〜 を使う（上位校向け）。\",\"不定詞を取りのぞいても文が成り立つなら副詞的用法である。\"],\"sections\":[{\"heading\":\"「なぜ？」に答える不定詞\",\"mangaId\":\"eigo_s304_manga\",\"body\":\"副詞的用法の不定詞は、動詞に説明を付け加える。いちばん多いのが目的を表す使い方である。\\n\\n例）I went to the library to borrow some books.（本を借りるために図書館へ行った）\\n例）She got up early to catch the first train.（始発電車に乗るために早く起きた）\\n例）We use a dictionary to look up new words.（新しい単語を調べるために辞書を使う）\\n\\n■ 文の骨組みは前半だけ\\n上の一つ目の文は、to borrow some books を消しても I went to the library. として立派に成り立つ。つまり不定詞は、完成した文にあとから付け足された「おまけ」である。これが名詞的用法（消すと文が壊れる）との決定的なちがいである。\\n\\n■ Why への答えになる\\n例）Why did you go to the library? — To borrow some books.（本を借りるためです）\\nBecause I wanted to borrow some books. と答えてもよい。To 〜 と答えられる不定詞は、必ず目的の副詞的用法である。\\n\\n■ 文頭に出すこともできる\\n例）To catch the first train, she got up early.\\n目的を強調したいときは前に出し、コンマで区切る。\\n\\n★ ポイント：判定は「消してみる」。消しても文が成り立てば副詞的用法、成り立たなければ名詞的用法である。\",\"figureId\":\"lf_eigoext09_304\"},{\"heading\":\"in order to と so that（上位校向け）\",\"body\":\"目的をはっきり示したいときや、書き言葉では in order to 〜 を使う。\\n\\n例）He studied hard in order to pass the exam.（彼は試験に合格するために一生けんめい勉強した）\\n例）I left home early in order not to be late.（遅れないように早く家を出た）\\n\\n否定は in order not to 〜 の順になる。not の位置に注意する。\\n\\n■ so that ... can 〜 への書きかえ\\n例）He studied hard to pass the exam.\\n　→ He studied hard so that he could pass the exam.\\nso that を使うと、目的の中身に別の主語を立てられる。\\n例）I spoke slowly so that everyone could understand me.（みんながわかるようにゆっくり話した）\\n不定詞では「わたしがわかる」ことしか表せないので、他の人を主語にしたいときは so that を使う。\\n\\n■ 「〜しないために」\\n例）Be careful not to catch a cold.（かぜをひかないように気をつけて）\\nnot は to の前に置く。\\n\\n⚠ 注意：日本語の「〜するように」につられて、for を使って for pass the exam などとしてはいけない。前置詞 for のあとに動詞の原形は置けない。目的を表すのは to＋原形か、for＋名詞（for the exam）である。\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「彼女は英語を勉強するためにアメリカへ行った」\",\"wrongAnswer\":\"She went to America for study English.\",\"trapExplanation\":\"「〜のために」＝ for と覚えているため、for のあとに動詞をそのまま続けてしまう。前置詞のあとに動詞の原形は置けないという原則を忘れている。\",\"correctAnswer\":\"She went to America to study English.\",\"correctExplanation\":\"目的を表して「〜するために」と言うときは to＋動詞の原形を使う。for を使うなら後ろは名詞にして for her English study のようにしなければならない。どうしても for を使いたいなら for studying English と動名詞にする必要がある。\"},{\"question\":\"次の文の不定詞は何用法か。I went to the store to buy some eggs.\",\"wrongAnswer\":\"名詞的用法（卵を買うこと）\",\"trapExplanation\":\"「卵を買うこと」と名詞のように訳せてしまうので、名詞的用法だと判断してしまう。went の直後にあることも、目的語だと思わせる原因になる。\",\"correctAnswer\":\"副詞的用法（卵を買うために）\",\"correctExplanation\":\"to buy some eggs を消すと I went to the store. となり、文はきちんと成り立つ。名詞的用法なら消したときに目的語がなくなって文が壊れる。また go は目的語をとらない動詞なので、後ろの不定詞は目的語ではありえない。\"}]}",
"{\"id\":\"eigo_s305\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"副詞的用法②：感情の原因「〜して（うれしい）」\",\"description\":\"be glad to 〜 など、感情を表す形容詞のあとに続く不定詞をおさえる\",\"intro\":\"I am glad. だけでは「うれしい」で終わってしまいます。「あなたに会えてうれしい」と理由まで言うには、うしろに to see you を足して I am glad to see you. とします。感情のことばのあとに続く不定詞が、その気持ちの原因を表すしくみを見ます。\",\"order\":805,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"感情を表す形容詞のあとの不定詞は、その感情の原因を表して「〜して」と訳す。\",\"be glad to 〜／be happy to 〜／be sad to 〜／be sorry to 〜／be surprised to 〜。\",\"語順は「be動詞＋感情の形容詞＋to＋動詞の原形」。\",\"Nice to meet you. は「お会いできてうれしい」で、この用法の決まり文句。\",\"感情の形容詞の直後にあるかどうかで、目的の用法と区別する。\"],\"sections\":[{\"heading\":\"うれしい・悲しい・驚いた理由を示す\",\"body\":\"感情を表す形容詞のあとに不定詞を置くと、「なぜその気持ちになったのか」を説明できる。\\n\\n例）I am glad to see you.（あなたに会えてうれしい）\\n例）We were happy to hear the news.（その知らせを聞いてうれしかった）\\n例）She was sad to leave her friends.（友だちと別れて悲しかった）\\n例）I was surprised to see him there.（そこで彼を見て驚いた）\\n例）I'm sorry to hear that.（それを聞いて気の毒に思います）\\n\\n■ 訳は「〜して」\\n目的の用法は「〜するために」、感情の原因は「〜して」と訳し分ける。直前に感情の形容詞（glad・happy・sad・sorry・surprised・excited）があれば、原因の用法だと判断してよい。\\n\\n■ あいさつの決まり文句\\n例）Nice to meet you.（はじめまして＝お会いできてうれしい）\\n例）I'm happy to be here.（ここに来られてうれしいです）\\nどちらも感情の原因を表す不定詞である。\\n\\n■ 感情の形容詞の一覧\\nglad（うれしい）／happy（幸せな）／sad（悲しい）／sorry（気の毒に思う・残念な）／surprised（驚いた）／excited（わくわくした）／disappointed（がっかりした）\\n\\n★ ポイント：be surprised・be excited のように、感情を表す語には過去分詞から生まれたものが多い。be動詞とセットで覚える。\",\"figureId\":\"xf_eigo_s305\",\"mangaId\":\"eigo_s305_xm\"},{\"heading\":\"同じ形でちがう意味になる文\",\"body\":\"不定詞の直前にある語を見ないと、意味を取りちがえることがある。\\n\\n例）I was happy to help him.（彼を手伝えてうれしかった）… 原因\\n例）I called him to help him.（彼を手伝うために電話した）… 目的\\nどちらも to help him だが、直前が形容詞 happy か、動詞 called かで用法が変わる。\\n\\n■ sorry の二つの意味\\n例）I'm sorry to hear that.（それを聞いて残念に思う）… 気の毒\\n例）I'm sorry to be late.（遅れてすみません）… おわび\\nsorry は「残念に思う」と「すまなく思う」の両方を表すので、文脈で判断する。\\n\\n■ 会話でよく出る形\\n例）I'm glad to help you.（お手伝いできてうれしいです）\\n例）Are you excited to go to Tokyo Disneyland?（東京ディズニーランドに行くのが楽しみですか）\\n例）He was disappointed to lose the game.（試合に負けてがっかりした）\\n\\n⚠ 注意：I am glad to see you. の to see you を「あなたに会うために」と訳すと「あなたに会うためにうれしい」となって意味が通らない。感情の形容詞のあとでは必ず「〜して」と訳す。\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。She was surprised to find the door open.\",\"wrongAnswer\":\"彼女はドアが開いているのを見つけるために驚いた。\",\"trapExplanation\":\"不定詞＝「〜するために」と一つだけ覚えていると、感情の形容詞のあとでも機械的に目的で訳してしまい、日本語として通らない文になる。\",\"correctAnswer\":\"彼女はドアが開いているのを見つけて驚いた。\",\"correctExplanation\":\"surprised は感情を表す形容詞なので、そのあとの不定詞は驚いた原因を表す。「〜して」と訳す。訳したあと日本語として自然かどうかを必ず確かめると、この種のまちがいは防げる。\"},{\"question\":\"（　）に適する語を入れなさい。I'm (　) to meet you.（お会いできてうれしいです）\",\"wrongAnswer\":\"happily\",\"trapExplanation\":\"「うれしく」という日本語の感じから副詞 happily を選んでしまう。しかし be動詞のあとに置けるのは形容詞であって副詞ではない。\",\"correctAnswer\":\"happy（または glad）\",\"correctExplanation\":\"be動詞のあとには主語の様子を表す形容詞が入る。したがって happy か glad が正しい。「感情の形容詞＋to＋原形」がこの用法の決まった形であり、副詞が入る余地はない。\"}]}",
"{\"id\":\"eigo_s306\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"副詞的用法③：結果と判断の根拠\",\"description\":\"grow up to be 〜 の結果用法と、be kind to 〜 の判断の根拠をおさえる\",\"intro\":\"He grew up to be a doctor. を「医者になるために育った」と訳すと、なんだか変です。正しくは「成長して医者になった」。同じ to＋原形でも、前から順に訳す用法があるのです。訳し方でつまずきやすい結果と判断の根拠を整理します。\",\"order\":806,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"結果の用法：grow up to be 〜（成長して〜になる）、live to be 〜（生きて〜歳になる）。\",\"結果の用法は前から順に訳す（「〜して、そして…になった」）。\",\"判断の根拠：He is kind to help me.（手伝ってくれるとは親切だ）。\",\"判断の根拠では、人の性質を表す形容詞（kind・careless・clever）が使われる。\",\"結果・根拠は上位校向け。まず目的と感情の原因を確実にしてから取り組む。\"],\"sections\":[{\"heading\":\"結果を表す不定詞\",\"body\":\"ふつう不定詞は「これからのこと」を表すが、決まった言い方の中では「その結果どうなったか」を表すことがある。訳すときは前から順に読む。\\n\\n例）He grew up to be a famous doctor.（彼は成長して有名な医者になった）\\n例）My grandfather lived to be ninety.（祖父は九十歳まで生きた）\\n例）She went to the station only to find the train had left.（駅へ行ったが、電車はもう出たあとだった）\\n\\n■ 前から訳すのがこつ\\n「有名な医者になるために成長した」と後ろから訳すと不自然になる。結果の用法は、起きた順に「成長した → その結果、医者になった」と訳す。\\n\\n■ 覚えるべき決まり文句\\ngrow up to be 〜（成長して〜になる）\\nlive to be 〜（〜歳まで生きる）\\nonly to 〜（〜しただけだった・結局〜した）\\nnever to 〜（そして二度と〜しなかった）\\n\\n■ 目的との見分け\\n目的なら「〜するために」で意味が通る。通らずに「そして〜した」の方が自然なら結果である。grow up・live のように、目的を持って行うわけではない動詞のあとでは結果になりやすい。\\n\\n★ ポイント：中学受験で必ず押さえるのは grow up to be 〜 と live to be 〜 の二つ。この二つは丸ごと暗記してよい。\",\"figureId\":\"xf_eigo_s306\",\"mangaId\":\"eigo_s306_xm\"},{\"heading\":\"判断の根拠を表す不定詞\",\"body\":\"人の性質を表す形容詞のあとに不定詞を置くと、「そう判断した理由」を表す。\\n\\n例）He is kind to help old people.（お年寄りを助けるとは、彼は親切だ）\\n例）You were careless to leave your umbrella on the train.（電車にかさを忘れるとは、あなたは不注意だった）\\n例）She was clever to solve the problem.（その問題を解くとは、彼女は賢い）\\n\\n■ 感情の原因との区別\\n感情の形容詞（glad・sad・surprised）→ 原因「〜して」\\n性質の形容詞（kind・careless・clever・foolish）→ 根拠「〜するとは」\\n主語がどんな人かを述べているのが根拠の用法である。\\n\\n■ It is 〜 of 人 to ... との関係\\n例）It is kind of you to help me.（手伝ってくださるとは、ご親切に）\\nこれは You are kind to help me. とほぼ同じ内容である。性質を表す形容詞では for ではなく of を使う点が入試でねらわれる。\\n\\n⚠ 注意：He is kind to help me. の to help me を「助けるために」と訳すと「助けるために親切だ」となって意味が通らない。形容詞が感情か性質かを先に確かめる習慣をつける。\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。My grandmother lived to be one hundred.\",\"wrongAnswer\":\"祖母は百歳になるために生きた。\",\"trapExplanation\":\"不定詞＝目的と決めつけて「〜になるために」と訳してしまう。しかし人は百歳になることを目的に生きるわけではなく、日本語として不自然である。\",\"correctAnswer\":\"祖母は百歳まで生きた。\",\"correctExplanation\":\"live to be 〜 は結果を表す決まった言い方で、「生きて、その結果〜歳になった」という意味になる。前から順に訳すのがこつ。同じ形の grow up to be 〜（成長して〜になる）とセットで覚えておく。\"},{\"question\":\"（　）に for か of を入れなさい。It was kind (　) you to carry my bag.（かばんを運んでくださるとはご親切に）\",\"wrongAnswer\":\"for\",\"trapExplanation\":\"It is ... for 人 to 〜 の形を先に習っているため、すべて for でよいと思いこんでしまう。形容詞の種類によって前置詞が変わることに気づけない。\",\"correctAnswer\":\"of\",\"correctExplanation\":\"kind・careless・clever・foolish など、人の性質を表す形容詞のときは of を使う。easy・difficult・important・necessary など、ことがらの性質を表す形容詞のときは for を使う。「その人がどんな人かを言っているなら of」と覚える。\"}]}",
"{\"id\":\"eigo_s307\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不定詞の総合：三用法の見分け方\",\"description\":\"三用法を判別する手順を固め、入試の用法識別問題に対応できるようにする\",\"intro\":\"不定詞の形はどれも to＋動詞の原形で、見た目はまったく同じです。それなのに入試では用法を答えさせられます。手がかりは訳し方ではなく、その不定詞を消したときに文が壊れるかどうか。三つの用法を機械的に見分ける手順をつくります。\",\"order\":807,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"手順①：不定詞を消してみる。文が壊れれば名詞的用法。\",\"手順②：直前が名詞なら形容詞的用法（その名詞の説明になっているか確かめる）。\",\"手順③：消しても文が成り立ち、直前が動詞や形容詞なら副詞的用法。\",\"副詞的用法の内わけは、目的が最も多く、次に感情の原因、結果や根拠はまれ。\",\"訳だけで決めない。位置と、消したときに文が成り立つかで決める。\"],\"sections\":[{\"heading\":\"三段階の判別手順\",\"body\":\"用法を問う問題は、次の手順を上から順に当てはめれば必ず解ける。\\n\\n■ 手順① 不定詞を消してみる\\n例）I want to play tennis. → I want. となり文が壊れる → 名詞的用法\\n例）I have homework to do. → I have homework. で成り立つ → 名詞的用法ではない\\n例）I went there to see him. → I went there. で成り立つ → 名詞的用法ではない\\n\\n■ 手順② 直前が名詞かどうかを見る\\n例）I have homework to do. → 直前が homework（名詞）で、「するべき宿題」と説明している → 形容詞的用法\\n\\n■ 手順③ 残りは副詞的用法\\n例）I went there to see him. → 直前は there（副詞）で、went の目的を説明 → 副詞的用法\\n\\n■ まぎらわしい例で確かめる\\n例）I have no time to play.（遊ぶ時間がない）… 直前が time → 形容詞的用法\\n例）I have time to play.（遊ぶ時間がある）… 同じく形容詞的用法\\n例）I came here to play.（遊ぶためにここへ来た）… 直前が here → 副詞的用法\\n\\n★ ポイント：直前が名詞でも、その名詞の説明になっていなければ形容詞的用法ではない。「I want money to buy a game.（ゲームを買うためのお金）」は形容詞的用法だが、「I asked him to come.」の him は説明されているのではないので形容詞的用法にはならない。\",\"figureId\":\"lf_eigoext09_307\",\"mangaId\":\"eigo_s307_xm\"},{\"heading\":\"一文に二つ以上の不定詞が入る場合\",\"body\":\"入試の長文では、一つの文に不定詞がいくつも出てくる。それぞれ別々に判定する。\\n\\n例）I want to buy a book to read on the train.\\n　to buy → want の目的語（名詞的用法）\\n　to read → a book を説明（形容詞的用法）\\n　訳）電車の中で読む本を買いたい。\\n\\n例）She went to the store to buy something to eat.\\n　to buy → went の目的（副詞的用法）\\n　to eat → something を説明（形容詞的用法）\\n　訳）彼女は何か食べるものを買いに店へ行った。\\n\\n■ 順番に切って読む\\n長い文では、to が出てくるたびに直前の語を見て役目を決め、かたまりごとに切って読む。前から順に処理すれば、どんなに不定詞が並んでも読み解ける。\\n\\n■ 頻度の目安\\n入試に出る不定詞は名詞的用法が最も多く、次に副詞的用法（その大半は目的）、形容詞的用法が続く。まぎらわしいのは形容詞的用法と副詞的用法の区別なので、「直前が名詞か」を必ず確かめる。\\n\\n⚠ 注意：It is easy to swim. の to swim は形式主語 It が指す本当の主語なので名詞的用法である。「泳ぐために簡単だ」と副詞的に訳してはいけない。\"}],\"trapExamples\":[{\"question\":\"次の文の不定詞は何用法か。I have a lot of things to tell you.\",\"wrongAnswer\":\"副詞的用法（あなたに話すために）\",\"trapExplanation\":\"to tell you を「あなたに話すために」と訳すと一見通じるので、目的の副詞的用法だと判断してしまう。文末にあることも副詞的だと感じさせる。\",\"correctAnswer\":\"形容詞的用法（あなたに話すべきこと）\",\"correctExplanation\":\"直前が things という名詞で、「あなたに話すべきこと」とその名詞の中身を説明している。手順どおり「直前が名詞か」「その名詞の説明になっているか」を確かめれば、形容詞的用法だとわかる。\"},{\"question\":\"次の文の不定詞は何用法か。To see is to believe.\",\"wrongAnswer\":\"主語の To see は名詞的用法、is のあとの to believe は副詞的用法\",\"trapExplanation\":\"文の後半にある不定詞は副詞的用法が多いという思いこみから、位置だけで判断してしまう。\",\"correctAnswer\":\"両方とも名詞的用法（見ることは信じることだ＝百聞は一見にしかず）\",\"correctExplanation\":\"To see は主語、to believe は be動詞のあとの補語で、どちらも名詞のはたらきをしている。be動詞のあとの不定詞は「主語＝不定詞の内容」というイコール関係を作るので名詞的用法である。to believe を消すと To see is. となって文が壊れる点でも確かめられる。\"}]}",
"{\"id\":\"eigo_s308\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞＋不定詞①：how to 〜（〜のしかた）\",\"description\":\"how to＋動詞の原形で「〜のしかた」を表す形を身につける\",\"intro\":\"「自転車の乗り方を知っている」の「乗り方」は、英語では ride の名詞形ではありません。how to ride と二語をくっつけて、名詞のかたまりにします。「〜のしかた」をこの形で言えるようになると、説明する文が一気に書きやすくなります。\",\"order\":808,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"how to＋動詞の原形＝「〜のしかた」「どうやって〜すればよいか」。\",\"「疑問詞＋不定詞」はひとかたまりで名詞のはたらきをする（目的語になる）。\",\"know how to 〜（〜のしかたを知っている）／learn how to 〜（〜のしかたを習う）。\",\"tell me how to 〜（〜のしかたを教えて）は道案内・説明でよく使う。\",\"how to のあとも必ず動詞の原形。主語は書かない。\"],\"sections\":[{\"heading\":\"how to のかたまりを作る\",\"body\":\"疑問詞のあとに不定詞を置くと、「どうやって〜すればよいか」という内容をひとかたまりの名詞として表せる。\\n\\n例）I know how to swim.（わたしは泳ぎ方を知っている＝泳げる）\\n例）He learned how to use a computer.（彼はコンピューターの使い方を習った）\\n例）Please tell me how to get to the station.（駅への行き方を教えてください）\\n例）Do you know how to make curry?（カレーの作り方を知っていますか）\\n\\n■ ひとかたまりで名詞になる\\nhow to swim は「泳ぎ方」という一つの名詞のかたまりとして、know の目的語になっている。だから I know how to swim. は「主語＋動詞＋目的語」の形である。\\n\\n■ 主語は書かない\\n例）I know how to swim.（○）\\n例）I know how I to swim.（×）\\n不定詞の中に主語を入れることはできない。だれがするのかは、文の主語からわかると考える。\\n\\n■ can への書きかえ\\n例）I know how to swim. ≒ I can swim.（泳げる）\\nknow how to 〜 は「やり方がわかっている＝できる」という意味になることが多い。\\n\\n★ ポイント：how to＋原形は「〜のしかた」という名詞のかたまり。目的語の位置にすっぽり入る、と形で覚える。\",\"figureId\":\"lf_eigoext09_308\"},{\"heading\":\"道案内と説明の会話\",\"body\":\"how to 〜 は、道をたずねる場面や作り方を説明する場面で必ず出てくる。中学受験の会話文問題でも定番である。\\n\\n例）Could you tell me how to get to the museum?（博物館への行き方を教えていただけますか）\\n例）I don't know how to say it in English.（それを英語で何と言えばよいかわかりません）\\n例）She showed me how to fold a paper crane.（彼女は折り鶴の折り方を見せてくれた）\\n\\n■ 「教える」の動詞\\ntell（言って教える）／show（見せて教える）／teach（教科として教える）\\n例）My father taught me how to ride a bike.（父は自転車の乗り方を教えてくれた）\\nどれも「人＋how to 〜」の順に並べる。\\n\\n■ 答え方の例\\nGo straight and turn right at the second corner.（まっすぐ行って、二つ目の角を右に曲がってください）\\nIt's next to the post office.（郵便局のとなりです）\\n\\n⚠ 注意：how to のあとに to を重ねてしまうミスが多い。how to to get とは書かない。また get to the station の to は前置詞なので、how to get to 〜 と to が二回出てくるのは正しい形である。\",\"mangaId\":\"eigo_s308_xm\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしはギターのひき方を知りません」\",\"wrongAnswer\":\"I don't know how to playing the guitar.\",\"trapExplanation\":\"「〜すること」を表す形として動名詞を先に思い出してしまい、how to のあとを playing にしてしまう。to のあとは必ず原形という原則を忘れている。\",\"correctAnswer\":\"I don't know how to play the guitar.\",\"correctExplanation\":\"「疑問詞＋to＋動詞の原形」が決まった形で、to のあとが 〜ing になることはない。なお how playing とも書けない。「how to ＋ 原形」を一つのかたまりとして暗記してしまうのが確実である。\"},{\"question\":\"（　）に適する語を入れなさい。Please tell me (　) to get to the station.（駅への行き方を教えてください）\",\"wrongAnswer\":\"where\",\"trapExplanation\":\"「駅へ」という場所の語につられて where を選んでしまう。where to go なら「どこへ行けばよいか」で、行き方をたずねる内容にはならない。\",\"correctAnswer\":\"how\",\"correctExplanation\":\"たずねているのは行き先ではなく「どうやって行くか」なので how を使う。where to go は「どこへ行けばよいか」、how to get to 〜 は「〜への行き方」。日本語の「駅への行き方」の「方」が方法を指していることに注目する。\"}]}",
"{\"id\":\"eigo_s309\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞＋不定詞②：what to / when to / where to / which to\",\"description\":\"how 以外の疑問詞と不定詞の組み合わせを、意味のちがいとともに覚える\",\"intro\":\"how to だけ覚えても、「何を買えばいいか」「いつ出発すればいいか」は言えません。how のところを what・when・where・which に取りかえるだけで、そのまま通じる形になります。四つの疑問詞のちがいと、意味の変わり方をまとめます。\",\"order\":809,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"what to do（何をすべきか）／when to start（いつ始めるべきか）／where to go（どこへ行くべきか）。\",\"which to buy（どちらを買うべきか）／which book to buy（どの本を買うべきか）。\",\"どれも「〜すべきか」という意味を含み、名詞のかたまりとして目的語になる。\",\"why to 〜 という形はない。理由は why 節（why I should 〜）で表す。\",\"I don't know what to do. は「どうしたらよいかわからない」の決まり文句。\"],\"sections\":[{\"heading\":\"疑問詞ごとの意味\",\"body\":\"疑問詞を変えると、たずねる中身が変わる。\\n\\n例）I don't know what to do.（何をすればよいかわからない）\\n例）Please tell me when to start.（いつ始めればよいか教えてください）\\n例）We didn't know where to go.（どこへ行けばよいかわからなかった）\\n例）I can't decide which to choose.（どちらを選べばよいか決められない）\\n\\n■ which は名詞を続けられる\\n例）I can't decide which book to buy.（どの本を買えばよいか決められない）\\n例）Tell me which way to go.（どちらの道を行けばよいか教えて）\\nwhich のあとに名詞を置くと「どの○○を」となる。what も同じように what time to leave（何時に出発すべきか）のように使える。\\n\\n■ 使う動詞\\nknow（知っている）／tell（教える）／ask（たずねる）／decide（決める）／learn（習う）／show（見せて教える）／forget（忘れる）\\n例）I forgot where to put my key.（かぎをどこに置けばよいか忘れた）\\n\\n■ why には使えない\\n例）I don't know why to go.（×）\\n理由をたずねる why は不定詞と組み合わせられない。I don't know why I should go.（なぜ行かなければならないのかわからない）のように、主語＋動詞の形で表す。\\n\\n★ ポイント：how・what・when・where・which の五つは不定詞と組める。why だけは組めない、と例外で覚える。\",\"figureId\":\"xf_eigo_s309\",\"mangaId\":\"eigo_s309_xm\"},{\"heading\":\"会話でよく使う表現\",\"body\":\"疑問詞＋不定詞は、困っている場面や相談の場面で自然に使われる。会話文の空所補充でねらわれる。\\n\\n例）I don't know what to say.（何と言えばよいかわからない）\\n例）What should I do? — I don't know what to do, either.（どうしよう。—わたしにもどうしたらよいかわからない）\\n例）Do you know where to buy tickets?（切符をどこで買えばよいか知っていますか）\\n例）Let's decide when to meet.（いつ会うか決めましょう）\\n\\n■ 「〜すべきか」の should を補って考える\\nwhat to do ≒ what I should do\\nwhere to go ≒ where I should go\\nこのように should を補うと意味がはっきりする。書きかえ問題ではこの関係が問われる。\\n\\n例）I don't know what to do.\\n　＝ I don't know what I should do.\\n\\n■ 目的語が二つある形\\n例）Please tell me what to bring.（何を持っていけばよいか教えてください）\\ntell のあとに「me（人）＋ what to bring（もの）」と二つ並ぶ形になる。人が先、内容が後ろである。\\n\\n⚠ 注意：what to do の to のあとに主語を入れて what to I do とは書かない。主語を入れたいなら what I should do のように should の形にする。\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。I don't know (　) to buy for her birthday.（誕生日に何を買えばよいかわからない）\",\"wrongAnswer\":\"how\",\"trapExplanation\":\"疑問詞＋不定詞を how to 〜 の形で最初に習うため、意味を確かめずに how を入れてしまう。how to buy なら「買い方」になり、贈り物を選ぶ話にならない。\",\"correctAnswer\":\"what\",\"correctExplanation\":\"たずねているのは買う方法ではなく「何を」買うかなので what を使う。「何を」＝what、「どうやって」＝how、「いつ」＝when、「どこで」＝where と、日本語のたずねる中身に合わせて選ぶ。\"},{\"question\":\"誤りを直しなさい。I don't know why to be late for school.\",\"wrongAnswer\":\"why to be late のままでよい\",\"trapExplanation\":\"how to・what to が使えるので、why でも同じように不定詞を続けられると考えてしまう。疑問詞と不定詞は何でも組み合わせられると思いこむのが原因である。\",\"correctAnswer\":\"I don't know why I was late for school.（なぜ遅刻したのかわからない）\",\"correctExplanation\":\"why だけは不定詞と組み合わせられない。理由を表すときは why のあとに主語＋動詞を続ける。「疑問詞＋不定詞」が使えるのは how・what・when・where・which の五つだと覚えておく。\"}]}",
"{\"id\":\"eigo_s310\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"疑問詞＋不定詞③：間接疑問との書きかえ\",\"description\":\"疑問詞＋不定詞と「疑問詞＋主語＋動詞」の言いかえを整理する\",\"intro\":\"I don't know what to do. と I don't know what I should do. は、ほぼ同じ意味です。入試では片方をもう片方に書きかえさせます。このとき what のあとを疑問文の語順にしてしまう人が多いので、語順の決まりをここで固めます。\",\"order\":810,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"疑問詞＋不定詞 ≒ 疑問詞＋主語＋should＋動詞の原形。\",\"間接疑問（文の中に入った疑問文）の語順は「疑問詞＋主語＋動詞」。疑問文の語順にしない。\",\"I don't know what to do. ＝ I don't know what I should do.\",\"主語がちがう場合は不定詞では表せないので、間接疑問を使う。\",\"間接疑問では do／does／did を使わない（what he wants であって what does he want ではない）。\"],\"sections\":[{\"heading\":\"間接疑問の語順\",\"body\":\"疑問文が別の文の中に入ると、語順がふつうの文（主語＋動詞）にもどる。これを間接疑問という。\\n\\n例）Where does he live?（彼はどこに住んでいますか）\\n　→ I don't know where he lives.（彼がどこに住んでいるか知らない）\\n例）What is this?（これは何ですか）\\n　→ Tell me what this is.（これが何か教えて）\\n例）When did she come?（彼女はいつ来ましたか）\\n　→ I don't know when she came.（彼女がいつ来たか知らない）\\n\\n■ 三つの変化\\n①疑問詞のあとを「主語＋動詞」の順にもどす\\n②do・does・did は消し、その分を動詞の形に反映させる（lives・came）\\n③文末のクエスチョンマークは、文全体が疑問文でなければ付けない\\n\\n■ 不定詞との関係\\n例）I don't know what to do. ＝ I don't know what I should do.\\n例）Tell me how to use it. ＝ Tell me how I should use it.\\n不定詞の形は短く言えるが、主語を示せない。だれがするのかを変えたいときは間接疑問にする。\\n\\n★ ポイント：間接疑問は「疑問文の顔をした、ふつうの語順の名詞のかたまり」である。\",\"figureId\":\"xf_eigo_s310\",\"mangaId\":\"eigo_s310_xm\"},{\"heading\":\"不定詞では表せない場合\",\"body\":\"疑問詞＋不定詞は、動作をする人が文の主語（または相手）と同じときにしか使えない。\\n\\n例）I don't know what to do.（わたしが何をすべきか）\\n例）Tell me what to do.（わたしが何をすべきか）\\nどちらも動作をするのは「わたし」である。\\n\\n■ 別の人が主語のとき\\n例）I don't know what he should do.（彼が何をすべきかわからない）\\nこれを I don't know what to do. と書いてしまうと「わたしが何をすべきか」となり、意味が変わってしまう。動作をする人がちがうときは、必ず間接疑問を使う。\\n\\n■ 時制のあるなし\\n不定詞には時制がないので、いつのことかは文全体で決まる。\\n例）I didn't know what to say.（何を言えばよいかわからなかった）\\n間接疑問なら動詞の形で時を示せる。\\n例）I don't know where he went.（彼がどこへ行ったか知らない）\\n過去のことは、不定詞では表せず間接疑問が必要である。\\n\\n⚠ 注意：I don't know what does he want. は誤り。文の中に入った疑問文では does を使わず、I don't know what he wants. とする。この語順のまちがいは入試で最も多い減点箇所の一つである。\"}],\"trapExamples\":[{\"question\":\"誤りを直しなさい。Do you know where does she live?\",\"wrongAnswer\":\"where does she live のままでよい\",\"trapExplanation\":\"Where does she live? という疑問文をそのまま文の中に入れてしまう。疑問文が二つ重なっていることに気づけない。\",\"correctAnswer\":\"Do you know where she lives?\",\"correctExplanation\":\"文の中に入った疑問文（間接疑問）は「疑問詞＋主語＋動詞」の語順にもどる。does は消し、その分を lives と三単現の形にして表す。文全体は Do you know 〜? という疑問文なので、クエスチョンマークは文末に付ける。\"},{\"question\":\"同じ意味の文にしなさい。I don't know what I should say.\",\"wrongAnswer\":\"I don't know what should to say.\",\"trapExplanation\":\"不定詞に直すときに should を残したまま to を加えてしまう。助動詞と不定詞は同時には使えない。\",\"correctAnswer\":\"I don't know what to say.\",\"correctExplanation\":\"「疑問詞＋主語＋should＋原形」は、主語と should を消して「疑問詞＋to＋原形」に置きかえられる。should to のように助動詞と to を並べることはできない。動作をする人が文の主語と同じときにだけ、この書きかえができる。\"}]}",
"{\"id\":\"eigo_s311\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"It is ... to 〜①：形式主語の It\",\"description\":\"重い主語を後ろへ回し、先頭に It を置く形をつかむ\",\"intro\":\"It is easy to swim. の It は「それ」ではありません。訳すと「泳ぐことは簡単だ」で、It にあたる日本語がどこにもないのです。英語は長い主語を先頭に置くのをきらい、軽い It を先に立てて本体をうしろへ回します。その事情を見ていきます。\",\"order\":811,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"It is ... to 〜 の It は形だけの主語で、「それ」とは訳さない。\",\"本当の主語は to 以下。「〜することは…だ」と後ろから訳し上げる。\",\"To swim is easy. ＝ It is easy to swim. の書きかえができるようにする。\",\"It のあとの be動詞は is・was など単数の形。\",\"よく使う形容詞：easy・difficult（hard）・important・necessary・interesting・fun・dangerous。\"],\"sections\":[{\"heading\":\"重いものは後ろへ回す\",\"body\":\"英語には「長いかたまりを文の先頭に置きたくない」という性質がある。そこで主語が不定詞のときは、先頭に形だけの主語 It を置き、本当の主語を後ろへ送る。\\n\\n例）To speak English is difficult.\\n　→ It is difficult to speak English.（英語を話すことは難しい）\\n例）To get up early is good for you.\\n　→ It is good for you to get up early.（早起きはあなたにとってよい）\\n\\n■ It は訳さない\\nこの It には「それ」という意味はまったくない。「〜することは…だ」と、to 以下から訳し上げる。\\n\\n■ よく使う形容詞\\neasy（簡単だ）／difficult・hard（難しい）／important（大切だ）／necessary（必要だ）／interesting（おもしろい）／fun（楽しい）／dangerous（危険だ）／impossible（不可能だ）\\n\\n例）It is important to help each other.（たがいに助け合うことは大切だ）\\n例）It is dangerous to swim in this river.（この川で泳ぐのは危険だ）\\n例）It is fun to play with a dog.（犬と遊ぶのは楽しい）\\n\\n■ 名詞を使う形もある\\n例）It is a good idea to start early.（早く始めるのはよい考えだ）\\n形容詞だけでなく「a good idea」のような名詞も入れられる。\\n\\n★ ポイント：It で始まって、あとに to＋原形が出てきたら、その It は形式主語だと考えてよい。\",\"figureId\":\"lf_eigoext09_311\",\"mangaId\":\"eigo_s311_xm\"},{\"heading\":\"否定文・疑問文と、時制の変化\",\"body\":\"形式主語の文も、ふつうの be動詞の文と同じように否定・疑問にできる。\\n\\n例）It is not easy to learn a foreign language.（外国語を学ぶのは簡単ではない）\\n例）Is it difficult to play the violin?（バイオリンをひくのは難しいですか）\\n　— Yes, it is. / No, it isn't.\\n答えの it もそのまま使う。\\n\\n■ 過去の文\\n例）It was interesting to visit the old temple.（その古い寺を訪れるのはおもしろかった）\\nbe動詞を was にするだけで、to visit は変わらない。\\n\\n■ 天気の it との区別\\n例）It is rainy today.（今日は雨だ）… 天気の it\\n例）It is fun to play in the rain.（雨の中で遊ぶのは楽しい）… 形式主語の it\\nどちらも訳さない it だが、後ろに to＋原形があるかどうかで区別する。\\n\\n■ 長い主語を実際に見くらべる\\nTo read many books when you are young is important.\\nIt is important to read many books when you are young.\\n下の形の方が、主語がすぐ終わるので意味を取りやすい。実際の英文ではほとんどが下の形である。\\n\\n⚠ 注意：It is easy swim. のように to を落とさない。また It is easy to swimming. のように to のあとを 〜ing にしない。\"}],\"trapExamples\":[{\"question\":\"同じ意味の文にしなさい。To ride a bike is easy for me.\",\"wrongAnswer\":\"This is easy to ride a bike for me.\",\"trapExplanation\":\"形式主語には「それ」を指す語を置けばよいと考え、This や That を使ってしまう。形式主語に使えるのは It だけである。\",\"correctAnswer\":\"It is easy for me to ride a bike.\",\"correctExplanation\":\"後ろに回した不定詞の代わりに先頭に置けるのは It だけで、This・That は使えない。また for me（だれにとって）は形容詞のすぐあと、to の前に置くのが決まった順である。\"},{\"question\":\"日本語に直しなさい。It is important to keep your room clean.\",\"wrongAnswer\":\"それは、あなたの部屋をきれいに保つために大切だ。\",\"trapExplanation\":\"It を「それ」と訳し、to 以下を「〜するために」と副詞的に訳してしまう。二重にまちがえた結果、日本語として意味の通らない文になる。\",\"correctAnswer\":\"自分の部屋をきれいにしておくことは大切だ。\",\"correctExplanation\":\"形式主語の It は訳さず、to 以下を主語として「〜することは…だ」と訳し上げる。It のすぐあとが be動詞＋形容詞で、そのあとに to＋原形が続いていれば、この形だと判断できる。\"}]}",
"{\"id\":\"eigo_s312\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"It is ... to 〜②：for 人 と of 人\",\"description\":\"「だれにとって」を表す for 人 の位置と、of を使う場合を区別する\",\"intro\":\"It is easy to swim. は「だれにとって簡単なのか」を言っていません。「わたしには簡単だ」と付け加えるには、to の前に for me を入れます。ところが親切さを言う文では of you を使います。for と of の分かれ目をはっきりさせます。\",\"order\":812,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"「だれにとって」は for 人 で表し、形容詞のあと・to の前に置く。\",\"It is easy for me to swim.（わたしにとって泳ぐことは簡単だ）\",\"for 人 は不定詞の意味上の主語。「その人が〜する」という関係になる。\",\"人の性質を表す形容詞（kind・careless・clever・foolish）のときは of 人 を使う。\",\"代名詞は for me・for him など目的格にする（for I とはしない）。\"],\"sections\":[{\"heading\":\"for 人 の位置と意味\",\"mangaId\":\"eigo_s312_forhito_manga\",\"body\":\"不定詞の動作をするのがだれかを示したいときは、to の前に「for ＋ 人」を置く。\\n\\n例）It is easy for me to swim.（わたしにとって泳ぐことは簡単だ）\\n例）It is difficult for children to read this book.（子どもたちがこの本を読むのは難しい）\\n例）It is necessary for us to study every day.（わたしたちが毎日勉強することは必要だ）\\n\\n■ 位置は必ず「形容詞のあと・to の前」\\n例）It is easy for me to swim.（○）\\n例）It is for me easy to swim.（×）\\n例）For me it is easy to swim.（強調のためなら可能だが、答案では上の形にする）\\n\\n■ 「〜にとって」ではなく「〜が」と訳す方がよい場合\\n例）It is important for you to practice every day.\\n　→ あなたが毎日練習することが大切だ。\\nfor のあとの人は、不定詞の動作をする人（意味上の主語）である。「わたしにとって泳ぐ」ではなく「わたしが泳ぐ」という関係になっている。\\n\\n■ 代名詞の形\\nI → for me／he → for him／she → for her／we → for us／they → for them\\n前置詞のあとなので目的格を使う。\\n\\n★ ポイント：It is ... for 人 to 〜 は「人が〜するのは…だ」と訳すと、意味がすっきり通ることが多い。\",\"figureId\":\"xf_eigo_s312\"},{\"heading\":\"of を使う形容詞\",\"body\":\"形容詞が「人の性質」を表すときだけは、for ではなく of を使う。\\n\\n例）It is kind of you to help me.（手伝ってくださるとはご親切に）\\n例）It was careless of him to lose the key.（かぎをなくすとは彼は不注意だった）\\n例）It is clever of her to solve the problem.（その問題を解くとは彼女は賢い）\\n\\n■ 見分け方\\n「人 is 形容詞」と言いかえて意味が通るなら of。\\n　It is kind of you to help me. → You are kind.（○ 意味が通る）→ of\\n　It is easy for me to swim. → I am easy.（× 意味が通らない）→ for\\n\\n■ of を使う形容詞\\nkind（親切な）／nice（やさしい）／careless（不注意な）／clever（賢い）／wise（賢明な）／foolish・silly（おろかな）／polite（礼儀正しい）\\n\\n■ for を使う形容詞\\neasy／difficult・hard／important／necessary／possible／impossible／dangerous／interesting／natural\\n\\n■ 書きかえ\\n例）It is kind of you to help me. ＝ You are kind to help me.\\nof の文は「人＋be動詞＋形容詞＋to 〜」に書きかえられる。for の文はこの書きかえができない。\\n\\n⚠ 注意：It is kind for you to help me. は誤り。性質を表す形容詞では必ず of を使う。この一問で差が付く出題が多い。\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。It is difficult (　) me to answer this question.\",\"wrongAnswer\":\"of\",\"trapExplanation\":\"of you を使う形をあとから習うと、「人を示すときは of」と単純化してしまい、形容詞の種類を確かめずに of を選んでしまう。\",\"correctAnswer\":\"for\",\"correctExplanation\":\"difficult は「ことがらが難しい」ことを表す形容詞なので for を使う。確かめ方は「I am difficult.」と言いかえてみること。意味が通らないので for である。「You are kind.」のように言いかえて通る形容詞（kind・careless など）のときだけ of を使う。\"},{\"question\":\"日本語に合う英文にしなさい。「彼にとって英語を話すことは簡単だ」\",\"wrongAnswer\":\"It is easy for he to speak English.\",\"trapExplanation\":\"「彼にとって」の「彼」をそのまま主格 he で書いてしまう。日本語では「彼」の形が変わらないため、格の区別を忘れやすい。\",\"correctAnswer\":\"It is easy for him to speak English.\",\"correctExplanation\":\"for は前置詞なので、そのあとの代名詞は目的格にする。he → him、she → her、they → them、we → us、I → me。同じ理由で to me、with her なども目的格になる。\"}]}",
"{\"id\":\"eigo_s313\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"too ... to 〜：〜すぎて…できない\",\"description\":\"程度が行きすぎて実現できないことを表す too ... to の形をおさえる\",\"intro\":\"This tea is too hot to drink. のどこにも not はありません。それでも意味は「熱すぎて飲めない」と否定になります。too という一語が「行きすぎ」を表し、その結果できない、という含みを持つからです。この形のしくみを見ます。\",\"order\":813,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"too ＋ 形容詞・副詞 ＋ to ＋ 原形＝「あまりに…すぎて〜できない」。\",\"英文には not がないのに、日本語では「できない」と否定になる。\",\"too は「多すぎ・行きすぎ」を表す語。very とはちがう。\",\"so ... that ... can't 〜 に書きかえられる。\",\"「だれにとって」を入れるときは too ... for 人 to 〜 の順。\"],\"sections\":[{\"heading\":\"否定の語がないのに「できない」\",\"body\":\"too ... to 〜 は、程度が行きすぎているために実現できない、という意味を表す。\\n\\n例）This coffee is too hot to drink.（このコーヒーは熱すぎて飲めない）\\n例）He is too young to drive a car.（彼は若すぎて車を運転できない）\\n例）I was too tired to walk any more.（疲れすぎてそれ以上歩けなかった）\\n例）The box is too heavy to carry.（その箱は重すぎて運べない）\\n\\n■ not がないのに否定の意味\\n英文のどこにも not はないが、日本語にすると「〜できない」となる。too という語自体に「限度をこえている」という意味があるからである。\\n\\n■ very との決定的なちがい\\n例）This coffee is very hot.（このコーヒーはとても熱い）… 飲めるかどうかは言っていない\\n例）This coffee is too hot to drink.（熱すぎて飲めない）… 飲めないと言っている\\nvery は程度が大きいだけ、too は「大きすぎて困る」である。\\n\\n■ 「だれにとって」を入れる\\n例）This book is too difficult for me to read.（この本はわたしには難しすぎて読めない）\\nfor 人 は too ... と to の間に入れる。\\n\\n★ ポイント：too が出てきたら「行きすぎ→無理」と反応する。訳すときは必ず最後を「〜できない」で結ぶ。\",\"figureId\":\"lf_eigoext09_313\",\"mangaId\":\"eigo_s313_xm\"},{\"heading\":\"so ... that ... can't 〜 への書きかえ\",\"body\":\"too ... to 〜 は、so ... that ... can't 〜 の形に書きかえられる。入試の書きかえ問題の定番である。\\n\\n例）He is too busy to help us.\\n　＝ He is so busy that he can't help us.（彼はとても忙しいのでわたしたちを手伝えない）\\n\\n■ 書きかえの手順\\n①too → so にする\\n②to → that ＋ 主語 ＋ can't（過去なら couldn't）にする\\n③that のあとの主語は、文の主語をもう一度書く\\n\\n例）The tea was too hot to drink.\\n　＝ The tea was so hot that I couldn't drink it.\\n過去の文なので couldn't になる。また that 以下は完全な文にしなければならないので、drink の目的語 it を必ず書く点に注意する。\\n\\n■ 目的語の it を落とさない\\ntoo ... to 〜 の形では、to drink のあとに目的語を書かない（The tea was too hot to drink it. は誤り）。しかし that の文では drink it と書く必要がある。この「it の有無」が入試でねらわれる。\\n\\n⚠ 注意：too ... to 〜 の to のあとに目的語を重ねて書くのは誤り。主語がすでにその目的語だからである。\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。This question is too difficult for me to answer.\",\"wrongAnswer\":\"この問題はわたしにとってとても難しくて答えられる。\",\"trapExplanation\":\"too を very と同じ「とても」と考えてしまい、not がないので肯定の意味だと判断してしまう。英文に否定語が見えないことが最大の落とし穴である。\",\"correctAnswer\":\"この問題はわたしには難しすぎて答えられない。\",\"correctExplanation\":\"too ... to 〜 は「…すぎて〜できない」という否定の意味を含む。not がなくても否定で訳す。very とちがい、too は「限度をこえている」ことを表す語である。\"},{\"question\":\"同じ意味の文にしなさい。The bag was too heavy for me to carry.\",\"wrongAnswer\":\"The bag was so heavy that I couldn't carry.\",\"trapExplanation\":\"too ... to 〜 の形では目的語を書かないため、そのまま that の文に写して carry の目的語を落としてしまう。\",\"correctAnswer\":\"The bag was so heavy that I couldn't carry it.\",\"correctExplanation\":\"that 以下は主語と動詞のそろった完全な文にしなければならないので、carry の目的語 it（＝the bag）が必要である。too ... to 〜 の形では主語が目的語を兼ねるので書かないが、書きかえたときは必ず補う。\"}]}",
"{\"id\":\"eigo_s314\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"... enough to 〜：〜するのに十分…だ\",\"description\":\"enough の位置に注意しながら、条件を満たしていることを表す形を学ぶ\",\"intro\":\"「彼は泳げるくらい強い」を英語にするとき、enough を strong の前に置きたくなります。しかし正しいのは strong enough to swim で、形容詞のあとです。ところが名詞に付くときは enough money と前に置きます。位置の決まりを整理します。\",\"order\":814,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"形容詞・副詞 ＋ enough ＋ to ＋ 原形＝「〜するのに十分…だ」。\",\"enough は形容詞・副詞の「後ろ」に置く（old enough であって enough old ではない）。\",\"名詞を修飾するときだけ enough は名詞の「前」に置く（enough money）。\",\"so ... that ... can 〜 に書きかえられる。\",\"too ... to 〜（できない）と enough to 〜（できる）は反対の意味になる。\"],\"sections\":[{\"heading\":\"enough の位置\",\"body\":\"enough は「十分に」という意味で、置く場所が語の種類によって決まっている。\\n\\n■ 形容詞・副詞のあと\\n例）He is old enough to drive a car.（彼は車を運転できる年齢だ）\\n例）She is tall enough to reach the shelf.（彼女は棚に手が届くほど背が高い）\\n例）He ran fast enough to catch the bus.（彼はバスに間に合うほど速く走った）\\n\\n■ 名詞の前\\n例）I have enough money to buy the ticket.（切符を買うのに十分なお金がある）\\n例）We have enough time to finish it.（それを終えるのに十分な時間がある）\\n\\n形容詞・副詞なら後ろ、名詞なら前。この使い分けだけで一問取れる出題がある。\\n\\n■ 訳し方\\n「〜するのに十分…だ」が基本だが、日本語としては「…なので〜できる」と訳すと自然になることが多い。\\n例）He is kind enough to help me.（彼は親切なのでわたしを手伝ってくれる＝親切にも手伝ってくれる）\\n\\n★ ポイント：old enough to 〜、tall enough to 〜 のように「形容詞 → enough → to」の順を音で覚えてしまうとまちがえない。\",\"figureId\":\"lf_eigoext09_314\",\"mangaId\":\"eigo_s314_xm\"},{\"heading\":\"too ... to との対比と書きかえ\",\"body\":\"too ... to 〜 と enough to 〜 は、ちょうど反対の意味を表す。\\n\\n例）He is too young to drive a car.（若すぎて運転できない）\\n例）He is old enough to drive a car.（運転できる年齢だ）\\n同じ内容を、足りない側から言うか、足りている側から言うかのちがいである。\\n\\n■ so ... that ... can 〜 への書きかえ\\n例）She is rich enough to buy the car.\\n　＝ She is so rich that she can buy the car.（彼女はとても裕福なのでその車を買える）\\ntoo の場合は can't、enough の場合は can になる。\\n\\n例）He was strong enough to lift the box.\\n　＝ He was so strong that he could lift the box.\\n過去の文なので could を使う。書きかえた文では lift の目的語 the box をきちんと書く。\\n\\n■ 否定の形\\n例）He is not old enough to drive a car.（彼は運転できる年齢ではない）\\n＝ He is too young to drive a car.\\nnot enough と too はほぼ同じ内容を表す。\\n\\n⚠ 注意：enough を形容詞の前に置いて enough old とするのは誤り。名詞の前に置く enough money と混同しないこと。\"}],\"trapExamples\":[{\"question\":\"日本語に合うように並べかえなさい。「彼は本を運べるほど強い」　strong / he / to / is / carry / enough / the books\",\"wrongAnswer\":\"He is enough strong to carry the books.\",\"trapExplanation\":\"「十分に強い」という日本語の語順（十分に→強い）につられて、enough を形容詞の前に置いてしまう。very strong の語順の記憶も影響する。\",\"correctAnswer\":\"He is strong enough to carry the books.\",\"correctExplanation\":\"enough が形容詞・副詞を修飾するときは、必ずその後ろに置く。前に置くのは名詞を修飾するとき（enough books）だけである。「形容詞→enough→to＋原形」の順を固定して覚える。\"},{\"question\":\"同じ意味の文にしなさい。This box is light enough for me to carry.\",\"wrongAnswer\":\"This box is so light that I can't carry it.\",\"trapExplanation\":\"too ... to 〜 の書きかえ（can't を使う）と混同して、enough の文でも can't を使ってしまう。二つの形が似ているため取りちがえやすい。\",\"correctAnswer\":\"This box is so light that I can carry it.\",\"correctExplanation\":\"enough to 〜 は条件を満たしていて「できる」という意味なので can を使う。「できない」の can't を使うのは too ... to 〜 の方である。too は行きすぎて無理、enough は十分でできる、と反対の意味であることを押さえる。\"}]}",
"{\"id\":\"eigo_s315\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"不定詞の総仕上げ：書きかえパターンの整理\",\"description\":\"too/enough/It is ... to/疑問詞＋不定詞の書きかえを一気に確認する\",\"intro\":\"入試では「ほぼ同じ内容の文に書きかえなさい」という問題がよく出ます。不定詞ではその材料が決まっていて、To 〜 is … と It is … to 〜、too … to 〜 と so … that … can't 〜 などのペアです。どちらからでも変換できるようにします。\",\"order\":815,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"To 〜 is ... ＝ It is ... to 〜（形式主語）。\",\"too ... to 〜 ＝ so ... that ... can't 〜（目的語の it を補う）。\",\"... enough to 〜 ＝ so ... that ... can 〜。\",\"疑問詞＋to＋原形 ＝ 疑問詞＋主語＋should＋原形。\",\"書きかえでは時制（can／could）と目的語の有無を必ず確認する。\"],\"sections\":[{\"heading\":\"四つの書きかえを並べて確認\",\"body\":\"不定詞の書きかえは、入試で必ず一問は出る。四つの型を並べて覚える。\\n\\n■ ①形式主語\\nTo learn English is important.\\n＝ It is important to learn English.\\n\\n■ ②too ... to 〜\\nHe is too tired to work.\\n＝ He is so tired that he can't work.\\n\\n■ ③enough to 〜\\nShe is old enough to go alone.\\n＝ She is so old that she can go alone.\\n\\n■ ④疑問詞＋不定詞\\nI don't know how to use it.\\n＝ I don't know how I should use it.\\n\\n■ 時制をそろえる\\n例）The soup was too hot to eat.\\n　＝ The soup was so hot that I couldn't eat it.\\nもとの文が過去なら、書きかえた文の助動詞も過去（couldn't・could）にする。ここを現在のままにする答案が非常に多い。\\n\\n★ ポイント：書きかえたあと、必ず声に出して読み、主語と動詞がそろっているかを確かめる。\",\"figureId\":\"xf_eigo_s315\",\"mangaId\":\"eigo_s315_xm\"},{\"heading\":\"見落としやすいチェックポイント\",\"body\":\"書きかえ問題では、次の三点を必ず確認する。\\n\\n■ ①目的語の it を補ったか\\ntoo ... to 〜 や enough to 〜 の形では、不定詞の目的語を書かない。しかし that の文に直したら、その目的語を必ず書く。\\n例）This tea is too hot to drink. → so hot that I can't drink it.\\n\\n■ ②主語をもう一度書いたか\\nthat のあとは完全な文なので、主語を書く必要がある。\\n例）He is so busy that he can't come.（he を二回書く）\\n\\n■ ③for 人 を主語に変えたか\\ntoo ... for 人 to 〜 を書きかえるときは、for のあとの人が that の文の主語になる。\\n例）The book is too difficult for me to read.\\n　＝ The book is so difficult that I can't read it.\\nfor me が I になっている点に注意する。\\n\\n■ 総合練習\\n例）It is easy for him to answer the question.\\n　→ 不定詞の主語は he、内容は答えること。To answer the question is easy for him. とも書ける。\\n\\n⚠ 注意：so ... that の that は接続詞なので省略できる場合もあるが、答案では必ず書く。省略すると採点者に伝わりにくい。\"}],\"trapExamples\":[{\"question\":\"同じ意味の文にしなさい。The problem was too hard for us to solve.\",\"wrongAnswer\":\"The problem was so hard that we can't solve it.\",\"trapExplanation\":\"for us を we に変えるところまではできても、もとの文が過去（was）であることを見落とし、can't のまま書いてしまう。\",\"correctAnswer\":\"The problem was so hard that we couldn't solve it.\",\"correctExplanation\":\"書きかえでは時制をそろえるのが原則である。もとの文が was なので、that 以下も過去にして couldn't とする。あわせて solve の目的語 it を補うことも忘れない。\"},{\"question\":\"同じ意味の文にしなさい。To play the piano is not easy.\",\"wrongAnswer\":\"It is not easy playing the piano.\",\"trapExplanation\":\"「〜すること」を表す形として動名詞も習っているため、後ろへ回すときに 〜ing にしてしまう。形式主語 It が受けられるのは不定詞である。\",\"correctAnswer\":\"It is not easy to play the piano.\",\"correctExplanation\":\"形式主語 It は、後ろに回した to＋原形（不定詞）を指す。動名詞をそのまま It で受ける形は中学段階では使わない。「It is ... to 〜」を決まった形として覚える。\"}]}",
"{\"id\":\"eigo_s316\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動名詞①：〜ing が名詞になる（四つの位置）\",\"description\":\"動名詞の作り方と、文の中で入る四か所を整理する\",\"intro\":\"不定詞で「〜すること」が言えるようになったのに、英語にはもう一つ同じ意味の形があります。動詞に ing を付けた動名詞です。二つもあるのはむだに見えますが、入る場所も相性のよい動詞もちがいます。まずは動名詞が置ける四か所を確かめます。\",\"order\":816,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"動名詞＝動詞の 〜ing 形が名詞のはたらきをするもの。「〜すること」と訳す。\",\"入る場所は四つ：主語・動詞の目的語・be動詞のあとの補語・前置詞のあと。\",\"進行形の 〜ing とは形が似ている。be動詞のあとでも、「主語＝〜すること」の関係なら動名詞（My hobby is playing tennis.）。\",\"動名詞が主語のときの動詞は is・was など単数の形。\",\"前置詞のあとに動詞を置くときは、必ず動名詞にする（不定詞は置けない）。\"],\"sections\":[{\"heading\":\"動名詞の作り方と四つの位置\",\"body\":\"動詞に ing を付けると「〜すること」という名詞のかたまりになる。これを動名詞という。\\n\\n■ 作り方\\nふつうは ing を付ける：play → playing／read → reading\\ne で終わる語は e をとって ing：make → making／write → writing／come → coming\\n短母音＋子音字で終わる語は子音字を重ねる：run → running／swim → swimming／sit → sitting\\n\\n■ 入る四つの位置\\n①主語\\n例）Playing tennis is fun.（テニスをすることは楽しい）\\n②動詞の目的語\\n例）I enjoy playing tennis.（テニスをすることを楽しむ）\\n③be動詞のあとの補語\\n例）My hobby is playing tennis.（わたしの趣味はテニスをすることだ）\\n④前置詞のあと\\n例）He is good at playing tennis.（彼はテニスをするのが得意だ）\\n\\n①〜③は不定詞の名詞的用法と同じ位置だが、④だけは動名詞にしかできない。前置詞のあとに to＋原形は置けないからである。\\n\\n★ ポイント：「前置詞のあとは必ず 〜ing」。この一点だけでも確実に覚えておくと、入試で得点できる。\",\"figureId\":\"lf_eigoext09_316\"},{\"heading\":\"進行形の 〜ing との見分け方\",\"body\":\"動名詞も進行形も 〜ing の形をしているが、はたらきがまったくちがう。\\n\\n■ 進行形は be動詞とセット\\n例）He is playing tennis now.（彼は今テニスをしている）\\nbe動詞（is）＋ 〜ing で「今〜している最中だ」を表す。\\n\\n■ 動名詞は名詞のかたまり\\n例）His hobby is playing tennis.（彼の趣味はテニスをすることだ）\\n形は is playing でそっくりだが、意味は「趣味＝テニスをすること」というイコール関係である。\\n\\n■ 見分けの手順\\n主語が人で「今している最中」の意味なら進行形。主語がものごと（hobby・dream・job）で「主語＝〜すること」の関係なら動名詞である。\\n例）My job is teaching English.（わたしの仕事は英語を教えることだ）… job は英語を教えている最中にはなれないので動名詞。\\n\\n■ 動名詞が主語のときの動詞\\n例）Reading books is fun.（○）\\n例）Reading books are fun.（×）\\n不定詞のときと同じで、動名詞のかたまりは一つのことがらなので単数扱いになる。\\n\\n⚠ 注意：Swimming is my favorite sport. の Swimming は動名詞の主語である。「泳いでいる」と進行形に訳さないこと。\",\"mangaId\":\"eigo_s316_xm\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。Reading English books (　) interesting.\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"books が複数形なので、直前の名詞に引っぱられて are を選んでしまう。主語が「Reading English books」というひとかたまりであることを見落としている。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"動名詞のかたまりは、どれだけ長くても一つのことがらとして単数扱いする。したがって is が正しい。不定詞が主語のときと同じルールである。\"},{\"question\":\"次の文の 〜ing は動名詞か進行形か。My dream is traveling around the world.\",\"wrongAnswer\":\"進行形（夢が世界中を旅している）\",\"trapExplanation\":\"is ＋ 〜ing の形を見た瞬間に進行形だと決めつけてしまう。形だけで判断して、意味が通るかを確かめていない。\",\"correctAnswer\":\"動名詞（わたしの夢は世界中を旅することだ）\",\"correctExplanation\":\"主語は My dream で、夢が旅をしている最中になることはありえない。「わたしの夢＝世界中を旅すること」というイコールの関係なので、be動詞のあとの補語になる動名詞である。主語がその動作を実際にしているかどうかで判断する。\"}]}",
"{\"id\":\"eigo_s317\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動名詞②：主語・補語になる動名詞\",\"description\":\"文の先頭と be動詞のあとに置かれた動名詞を読み書きできるようにする\",\"intro\":\"「写真をとることが趣味です」を英語で言うとき、My hobby is take pictures. とはできません。is のあとに動詞をそのまま置けないからです。taking に変えれば通じます。文の先頭と be動詞のあと、この二か所での使い方を練習します。\",\"order\":817,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"主語の位置：Playing soccer is fun.（サッカーをすることは楽しい）\",\"補語の位置：My hobby is collecting stamps.（趣味は切手集めだ）\",\"主語には不定詞も使えるが、日常的なことがらは動名詞の方が自然。\",\"主語が動名詞のとき、動詞は単数扱い（is／was）。\",\"「趣味は〜です」「仕事は〜です」は動名詞で表すのが決まった言い方。\"],\"sections\":[{\"heading\":\"主語になる動名詞\",\"body\":\"動名詞を文の先頭に置くと、「〜することは」という主語になる。\\n\\n例）Playing the piano is a lot of fun.（ピアノをひくことはとても楽しい）\\n例）Getting up early is good for your health.（早起きは健康によい）\\n例）Studying English every day is important.（毎日英語を勉強することは大切だ）\\n例）Walking in the park makes me happy.（公園を歩くとわたしは幸せな気持ちになる）\\n\\n■ 不定詞との使い分け\\nTo play the piano is fun. も文法的には正しいが、ふだんくり返し行うことがらや一般的なことがらは動名詞で表す方が自然である。逆に、これからの計画や一回きりのことは不定詞や It is ... to 〜 で表すことが多い。中学受験ではどちらも正解になるので、まず動名詞で書けるようにしておくとよい。\\n\\n■ 主語の長さに注意して読む\\n例）Reading a lot of books when you are young is very important.\\n主語は Reading a lot of books when you are young までで、動詞は is である。動名詞が主語のときは、動詞（is・was など）が出てくるところまでが主語だと考える。\\n\\n★ ポイント：文頭の 〜ing は、多くの場合「〜することは」という主語である。進行形の be動詞がないことを確かめる。\",\"figureId\":\"xf_eigo_s317\"},{\"heading\":\"補語になる動名詞\",\"body\":\"be動詞のあとに動名詞を置くと、「主語＝〜すること」というイコール関係を作る。\\n\\n例）My hobby is taking pictures.（わたしの趣味は写真をとることだ）\\n例）Her job is helping sick people.（彼女の仕事は病気の人を助けることだ）\\n例）The most important thing is doing your best.（最も大切なことは全力をつくすことだ）\\n\\n■ 会話でよく出る言い方\\n例）What is your hobby? — My hobby is reading books.（趣味は何ですか。—読書です）\\n例）My favorite thing is playing with my dog.（いちばん好きなことは犬と遊ぶことだ）\\n\\n■ 主語と補語を入れかえられる\\n例）My hobby is collecting stamps.\\n　＝ Collecting stamps is my hobby.\\nイコールの関係なので、前後を入れかえても意味は変わらない。\\n\\n■ 進行形と区別する練習\\n例）He is teaching English now.（彼は今英語を教えている）… 進行形\\n例）His job is teaching English.（彼の仕事は英語を教えることだ）… 動名詞\\n主語が人で「今」を表す語があれば進行形、主語が job・hobby・dream などなら動名詞である。\\n\\n⚠ 注意：My hobby is play tennis. は誤り。be動詞のあとに動詞の原形は置けない。playing（動名詞）か to play（不定詞）にする。\",\"mangaId\":\"eigo_s317_xm\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしの趣味は音楽を聞くことです」\",\"wrongAnswer\":\"My hobby is listen to music.\",\"trapExplanation\":\"「聞くこと」を listen とそのまま書いてしまう。be動詞のあとに動詞の原形を置くことはできないという原則が抜けている。\",\"correctAnswer\":\"My hobby is listening to music.\",\"correctExplanation\":\"be動詞のあとには名詞・形容詞にあたるものしか置けないので、動詞は動名詞 listening にする。to listen to music（不定詞）でも文法的には正しいが、趣味を述べるときは動名詞を使うのがふつうである。listen to 〜（〜を聞く）の to も落とさないこと。\"},{\"question\":\"（　）に適する語を入れなさい。Swimming in the sea (　) exciting.\",\"wrongAnswer\":\"are\",\"trapExplanation\":\"主語がどれか判断できないまま、直前の名詞 the sea や、文が長いことから複数を感じ取って are を選んでしまう。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"主語は Swimming in the sea（海で泳ぐこと）というひとかたまりで、一つのことがらなので単数扱いになり is を使う。動名詞が主語のときの動詞は必ず単数形にする。\"}]}",
"{\"id\":\"eigo_s318\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動名詞③：目的語になる動名詞（enjoy・finish・stop）\",\"description\":\"動名詞を目的語にとる代表的な動詞を、意味のまとまりで覚える\",\"intro\":\"I enjoyed to swim. は、言いたいことは伝わっても英語としては誤りです。enjoy はうしろに to を置けず、swimming としか結びつきません。なぜ動詞によって相手が決まっているのか——まずは動名詞としか組まない代表的な動詞を覚えます。\",\"order\":818,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"enjoy 〜ing（〜して楽しむ）／finish 〜ing（〜し終える）／stop 〜ing（〜するのをやめる）。\",\"enjoy・finish などのあとに to＋原形は置けない（stop to 〜 は「〜するために立ち止まる」で、別の意味の形）。\",\"How about 〜ing?（〜はどうですか）は前置詞 about のあとなので動名詞。\",\"Thank you for 〜ing.（〜してくれてありがとう）も前置詞のあとなので動名詞。\",\"否定は not 〜ing の順（動名詞の直前に not）。\"],\"sections\":[{\"heading\":\"動名詞を目的語にとる動詞\",\"body\":\"次の動詞は、目的語に動名詞をとる。to＋原形を置くことはできない。\\n\\n例）I enjoyed talking with you.（あなたと話せて楽しかった）\\n例）He finished doing his homework.（彼は宿題をし終えた）\\n例）She stopped watching TV.（彼女はテレビを見るのをやめた）\\n例）Would you mind opening the window?（窓を開けていただけませんか）\\n例）I gave up smoking.（たばこをやめた）\\n例）We practiced singing the song.（その歌を歌う練習をした）\\n\\n■ 覚え方\\nenjoy（楽しむ）・finish（終える）・stop（やめる）・give up（あきらめる）・mind（いやがる）・practice（練習する）・avoid（さける）——どれも「すでに始めている、または現に行っていること」を目的語にしている点で共通する。これから先のことを表す不定詞とは向きが逆である。\\n\\n■ 会話文でよく出る形\\n例）Did you enjoy watching the game?（試合を見て楽しかったですか）\\n例）Let's finish cleaning the room first.（まず部屋のそうじを終わらせよう）\\n\\n★ ポイント：enjoy to play・finish to do は誤り。enjoy・finish は動名詞専用、stop は「やめる」なら stop 〜ing（stop to 〜 は「〜するために立ち止まる」で別の意味）と最初に固めておく。\",\"figureId\":\"xf_eigo_s318\",\"mangaId\":\"eigo_s318_xm\"},{\"heading\":\"前置詞のあとの動名詞と決まり文句\",\"body\":\"前置詞のあとに動詞を置くときは、必ず動名詞にする。これは例外のない規則である。\\n\\n例）Thank you for helping me.（手伝ってくれてありがとう）\\n例）How about going shopping?（買い物に行くのはどうですか）\\n例）He is good at swimming.（彼は泳ぐのが得意だ）\\n例）She went out without saying goodbye.（彼女はさようならも言わずに出て行った）\\n例）Wash your hands before eating.（食べる前に手を洗いなさい）\\n例）After finishing lunch, we went out.（昼食を終えてから出かけた）\\n\\n■ How about 〜? の about は前置詞\\nHow about to go shopping? は誤りである。about のあとなので going にする。\\n\\n■ look forward to 〜ing に注意\\n例）I'm looking forward to seeing you.（あなたに会うのを楽しみにしています）\\nこの to は不定詞の to ではなく前置詞の to なので、あとは 〜ing になる。上位校でねらわれる形である。\\n\\n■ 動名詞の否定\\n例）I'm sorry for not calling you.（電話しなくてごめんなさい）\\nnot は動名詞のすぐ前に置く。\\n\\n⚠ 注意：before・after・without・by・for・at・about・of はすべて前置詞である。これらのあとに動詞を置くときは 〜ing にする、と丸ごと覚える。\"}],\"trapExamples\":[{\"question\":\"（　）に適するものを選びなさい。I enjoyed (　) with my friends.　ア to talk　イ talking　ウ talk\",\"wrongAnswer\":\"ア to talk\",\"trapExplanation\":\"want to・hope to のように「動詞＋to＋原形」の形を多く習っているため、enjoy でも同じように to を続けてしまう。\",\"correctAnswer\":\"イ talking\",\"correctExplanation\":\"enjoy は目的語に動名詞しかとらない動詞である。enjoy to talk とは言えない。finish・stop・give up・mind・practice も同じ仲間なので、まとめて動名詞専用として覚える。\"},{\"question\":\"誤りを直しなさい。How about to play tennis after school?\",\"wrongAnswer\":\"to play のままでよい\",\"trapExplanation\":\"「テニスをするのはどう？」という誘いの意味から不定詞を選んでしまう。about が前置詞であることを見落としている。\",\"correctAnswer\":\"How about playing tennis after school?\",\"correctExplanation\":\"about は前置詞なので、そのあとに動詞を置くときは必ず動名詞にする。同じ理由で Thank you for helping me.、He is good at playing the piano. も 〜ing になる。「前置詞のあとは 〜ing」は例外のない規則である。\"}]}",
"{\"id\":\"eigo_s319\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動名詞④：前置詞＋動名詞の重要表現\",\"description\":\"be good at 〜ing など、前置詞とセットで覚える表現を身につける\",\"intro\":\"「歌が得意です」は I am good at sing. ではありません。at は前置詞なので、うしろには名詞しか置けず、singing に変える必要があります。この決まりが分かると、be good at・be interested in・without などが同じ理屈で片づきます。\",\"order\":819,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"be good at 〜ing（〜が得意だ）／be interested in 〜ing（〜に興味がある）。\",\"be afraid of 〜ing（〜するのをこわがる）／be proud of 〜ing（〜を誇りに思う）。\",\"without 〜ing（〜せずに）／before 〜ing（〜する前に）／after 〜ing（〜したあとで）。\",\"look forward to 〜ing の to は前置詞。to のあとが 〜ing になる例外的な形。\",\"How about 〜ing? / What about 〜ing?（〜はどうですか）は提案の決まり文句。\"],\"sections\":[{\"heading\":\"be動詞＋形容詞＋前置詞のセット\",\"body\":\"形容詞と前置詞がセットになった表現は、後ろに動詞が来ると必ず動名詞になる。\\n\\n例）She is good at cooking.（彼女は料理が得意だ）\\n例）I am interested in learning Chinese.（中国語を学ぶことに興味がある）\\n例）He is afraid of making mistakes.（彼はまちがえるのをこわがっている）\\n例）They are proud of winning the game.（彼らは試合に勝ったことを誇りに思っている）\\n例）I am tired of waiting.（待つのにうんざりしている）\\n\\n■ 前置詞を落とさない\\nbe good at のように、at まで含めて一つの表現である。She is good cooking. は誤り。前置詞と形容詞をセットで音読して覚えるとよい。\\n\\n■ よく出る組み合わせ\\nbe good at（得意）／be bad at（苦手）／be interested in（興味がある）／be afraid of（こわい）／be proud of（誇りに思う）／be tired of（あきている）／be fond of（好きだ）\\n\\n■ 否定の形\\n例）I am not good at speaking in front of people.（人前で話すのが得意ではない）\\n\\n★ ポイント：これらは受動態の be interested in 〜 とも重なる表現である。あとで受動態を学ぶときに、同じ形が出てくることを思い出せるようにしておく。\",\"figureId\":\"xf_eigo_s319\",\"mangaId\":\"eigo_s319_xm\"},{\"heading\":\"時・方法を表す前置詞と動名詞\",\"body\":\"時や方法を表す前置詞のあとでも、動詞は動名詞になる。\\n\\n例）Wash your hands before eating lunch.（昼食を食べる前に手を洗いなさい）\\n例）After doing my homework, I watched TV.（宿題をしたあとテレビを見た）\\n例）He left without saying anything.（彼は何も言わずに出て行った）\\n例）You can improve your English by reading many books.（たくさん本を読むことで英語を上達させられる）\\n例）Thank you for inviting me.（招待してくれてありがとう）\\n\\n■ by 〜ing は「〜することによって」\\n方法や手段を表す。入試の英作文でよく使う。\\n例）We can save water by turning off the tap.（じゃ口を閉めることで水を節約できる）\\n\\n■ look forward to 〜ing の落とし穴\\n例）I'm looking forward to seeing you again.（またお会いできるのを楽しみにしています）\\nこの to は前置詞なので、後ろは動名詞になる。to see としてはいけない。手紙文・メール文の結びで頻出である。\\n\\n■ 前置詞と不定詞の to を見分ける\\n不定詞の to のあとは原形、前置詞の to のあとは名詞か動名詞。to school（前置詞）／to go（不定詞）のように、後ろを見れば判断できる。\\n\\n⚠ 注意：Thank you for to help me. は誤り。for は前置詞なので Thank you for helping me. とする。\"}],\"trapExamples\":[{\"question\":\"（　）に適する形を入れなさい。I'm looking forward to (　) you next month.（see を使って）\",\"wrongAnswer\":\"see\",\"trapExplanation\":\"to があるので不定詞だと考え、後ろを原形にしてしまう。look forward to の to が前置詞であることは形からは見分けにくいので、非常に多いまちがいである。\",\"correctAnswer\":\"seeing\",\"correctExplanation\":\"look forward to 〜 の to は前置詞なので、後ろには名詞か動名詞しか置けない。look forward to the party（名詞）と同じ感覚で、動詞なら seeing にする。決まり文句として「to のあとは 〜ing」と覚えてしまう。\"},{\"question\":\"日本語に合う英文にしなさい。「彼は何も言わずに部屋を出て行った」\",\"wrongAnswer\":\"He left the room without to say anything.\",\"trapExplanation\":\"「言わずに」という否定的な意味から not to say を思いうかべ、without のあとに不定詞を続けてしまう。without が前置詞であることを見落としている。\",\"correctAnswer\":\"He left the room without saying anything.\",\"correctExplanation\":\"without は前置詞なので、後ろの動詞は必ず動名詞にする。without 〜ing で「〜せずに」という意味になり、without 自体に否定の意味が入っているので not は不要である。\"}]}",
"{\"id\":\"eigo_s320\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"目的語の形①：三つのグループに分ける\",\"description\":\"不定詞専用・動名詞専用・どちらも可の動詞を分類して全体像をつかむ\",\"intro\":\"to と ing のどちらを置くかは、その場で考えても答えは出ません。うしろに来る形は、前の動詞ごとに決まっているからです。英語の動詞は「to だけ」「ing だけ」「どちらでもよい」の三組に分かれます。全体の地図をここで作ります。\",\"order\":820,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"動詞は目的語の形で三つに分かれる：不定詞だけ・動名詞だけ・どちらもよい。\",\"不定詞だけ：want・hope・decide・promise・plan・wish・expect。\",\"動名詞だけ：enjoy・finish・stop・give up・mind・practice・avoid。\",\"どちらもよい：like・love・begin・start・continue。\",\"「これから」は不定詞、「すでに・現に」は動名詞、というイメージで整理する。\"],\"sections\":[{\"heading\":\"三つのグループ\",\"body\":\"動詞のあとに別の動詞を続けるとき、to＋原形にするか 〜ing にするかは、前の動詞によって決まっている。\\n\\n■ ①不定詞だけをとる動詞\\nwant（したい）・hope（願う）・decide（決める）・promise（約束する）・plan（計画する）・wish（望む）・expect（期待する）・need（必要とする）\\n例）I want to go home.（○）／I want going home.（×）\\n\\n■ ②動名詞だけをとる動詞\\nenjoy（楽しむ）・finish（終える）・stop（やめる）・give up（あきらめる）・mind（いやがる）・practice（練習する）・avoid（さける）\\n例）I enjoy playing tennis.（○）／I enjoy to play tennis.（×）\\n\\n■ ③どちらでもよい動詞\\nlike（好む）・love（大好きだ）・begin（始める）・start（始める）・continue（続ける）\\n例）I like to swim. ＝ I like swimming.（泳ぐのが好きだ）\\n例）It began to rain. ＝ It began raining.（雨が降り始めた）\\n\\n■ 意味で覚える\\n不定詞専用の動詞は「まだしていない、これからのこと」を目的語にする。動名詞専用の動詞は「すでに始めていること・現にしていること」を目的語にする。この向きのちがいを意識すると、覚えていない動詞でも推測できる。\\n\\n★ ポイント：まず①と②の代表七語ずつを完全に暗記する。入試ではほぼこの範囲から出る。\",\"figureId\":\"lf_eigoext09_320\",\"mangaId\":\"eigo_s320_xm\"},{\"heading\":\"空所補充問題の解き方\",\"body\":\"入試では「（　）内の語を適する形にしなさい」という形で出る。手順は決まっている。\\n\\n■ 手順\\n①（　）の直前の動詞を確認する\\n②その動詞がどのグループかを思い出す\\n③不定詞専用なら to＋原形、動名詞専用なら 〜ing にする\\n\\n例）She finished (write) the letter. → 動名詞専用 → writing\\n例）They decided (visit) Kyoto. → 不定詞専用 → to visit\\n例）He likes (play) the guitar. → どちらも可 → to play でも playing でもよい\\n\\n■ 前置詞の直後は無条件で動名詞\\n例）He is good at (cook). → cooking\\n例）Thank you for (invite) me. → inviting\\n動詞のグループを考える必要すらない。前置詞が見えたら 〜ing である。\\n\\n■ まちがえやすい組み合わせ\\n例）I hope to see you.（○）／I hope seeing you.（×）\\n例）Would you mind opening the window?（○）／Would you mind to open 〜?（×）\\n例）We practiced playing the song.（○）／We practiced to play 〜（×）\\n\\n⚠ 注意：need は「必要とする」の意味では不定詞をとる（I need to sleep.）。物を主語にした need 〜ing（The car needs washing.）は高校で学ぶ形なので、中学受験では不定詞で覚えておけばよい。\"}],\"trapExamples\":[{\"question\":\"（　）内を適する形にしなさい。He finished (read) the book last night.\",\"wrongAnswer\":\"to read\",\"trapExplanation\":\"「読み終えた」という日本語から「読むことを終えた」と考え、目的語を to read という不定詞にしてしまう。want to の形に引っぱられるのが原因である。\",\"correctAnswer\":\"reading\",\"correctExplanation\":\"finish は動名詞だけを目的語にとる動詞である。finish to read とは言えない。enjoy・stop・give up・mind・practice・avoid も同じ仲間なので、七語をまとめて覚えておく。\"},{\"question\":\"（　）内を適する形にしなさい。They decided (go) to the museum.\",\"wrongAnswer\":\"going\",\"trapExplanation\":\"直前に動詞があるから 〜ing にするのだろうと形だけで判断してしまう。decide がどのグループかを確かめていない。\",\"correctAnswer\":\"to go\",\"correctExplanation\":\"decide は不定詞だけを目的語にとる動詞である。「行くことに決めた」というのはこれから行うことなので、未来向きの不定詞が合う。want・hope・promise・plan・wish・expect も同じ仲間である。\"}]}",
"{\"id\":\"eigo_s321\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"目的語の形②：動名詞だけをとる動詞\",\"description\":\"enjoy・finish・stop・give up・mind・practice・avoid を確実にする\",\"intro\":\"enjoy・finish・stop・practice——この仲間に共通するのは、すでに始まっていること、実際にしていることを扱う点です。だからうしろは ing になります。丸暗記の前にまとまりで感じをつかんでおくと、選びまちがえが減ります。\",\"order\":821,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"動名詞専用：enjoy・finish・stop・give up・mind・practice・avoid・keep。\",\"Would you mind 〜ing? は「〜していただけませんか」というていねいな依頼。\",\"mind の質問に「いいですよ」と答えるときは No, not at all. などと否定で答える。\",\"keep 〜ing は「〜し続ける」。\",\"enjoy・finish・mind などに to＋原形を続けたら誤りになる（stop to 〜 は「〜するために立ち止まる」で別の意味）。\"],\"sections\":[{\"heading\":\"動名詞専用の動詞をまとめて覚える\",\"body\":\"次の動詞は、目的語に動名詞しかとらない。\\n\\n例）We enjoyed swimming in the sea.（海で泳いで楽しんだ）\\n例）Have you finished cleaning your room?（部屋のそうじは終わりましたか）\\n例）Stop talking, please.（話すのをやめてください）\\n例）He gave up trying to fix it.（彼はそれを直そうとするのをあきらめた）\\n例）She practices playing the violin every day.（彼女は毎日バイオリンの練習をする）\\n例）You should avoid eating too much.（食べすぎはさけるべきだ）\\n例）The baby kept crying all night.（赤ちゃんは一晩じゅう泣き続けた）\\n\\n■ 共通するイメージ\\n楽しむ・終える・やめる・あきらめる・練習する・さける・続ける——どれも「すでに行っていること」や「くり返し行うこと」を対象にしている。だから、実際に行われている感じの強い動名詞が合う。\\n\\n■ keep 〜ing\\n例）Keep going straight.（まっすぐ進み続けてください）\\n道案内でよく使う。\\n\\n★ ポイント：enjoy to play・finish to do・stop to talk（別の意味になる）などは入試の定番のひっかけである。\",\"figureId\":\"xf_eigo_s321\"},{\"heading\":\"Would you mind 〜ing? の受け答え\",\"body\":\"mind はもともと「いやだと思う」という意味の動詞である。この意味を知らないと、答え方をまちがえる。\\n\\n例）Would you mind opening the window?\\n　直訳：窓を開けることをいやだと思いますか\\n　意味：窓を開けていただけませんか\\n\\n■ 答え方\\n承知するとき：No, not at all.（いいえ、まったくかまいません）／ Of course not.／ Certainly not.\\n断るとき：I'm sorry, but I have a cold.（すみませんが、かぜをひいているので）\\n\\n「いいですよ」と引き受けるのに No で答えるのは、「いやだと思いますか」に対して「いやではありません」と答えているからである。\\n\\n■ Do you mind 〜? も同じ\\n例）Do you mind waiting a few minutes?（数分待っていただけますか）\\n— Not at all.（かまいませんよ）\\n\\n■ ていねいさの比較\\nPlease open the window.（ふつう）\\nCan you open the window?（親しい相手に）\\nCould you open the window?（ていねい）\\nWould you mind opening the window?（最もていねい）\\n\\n⚠ 注意：Would you mind to open the window? は誤り。mind は動名詞専用なので opening にする。\",\"mangaId\":\"eigo_s321_xm\"}],\"trapExamples\":[{\"question\":\"Would you mind closing the door? に対し「いいですよ」と答えるとき、適切なものはどれか。　ア Yes, I do.　イ No, not at all.\",\"wrongAnswer\":\"ア Yes, I do.\",\"trapExplanation\":\"「いいですよ」＝Yes と考えてしまう。しかし mind は「いやだと思う」という意味なので、Yes と答えると「いやです」という断りになってしまう。\",\"correctAnswer\":\"イ No, not at all.\",\"correctExplanation\":\"Would you mind 〜ing? は「〜するのをいやだと思いますか」という質問である。引き受けるときは「いやではありません」＝No, not at all. や Of course not. と答える。日本語の「はい・いいえ」と逆になる代表的な表現である。\"},{\"question\":\"（　）内を適する形にしなさい。The children kept (play) in the rain.\",\"wrongAnswer\":\"to play\",\"trapExplanation\":\"「遊び続けた」を「遊ぶことを続けた」と考えて不定詞にしてしまう。keep が動名詞専用であることを知らないと起こるまちがいである。\",\"correctAnswer\":\"playing\",\"correctExplanation\":\"keep 〜ing で「〜し続ける」という意味になる。keep to play とは言えない。すでに行っている動作が続いていることを表すので、動名詞が合う。同じ仲間の enjoy・finish・stop・give up・mind・practice・avoid もあわせて確認する。\"}]}",
"{\"id\":\"eigo_s322\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"目的語の形③：不定詞だけをとる動詞\",\"description\":\"want・hope・decide・promise・plan・wish・expect を確実にする\",\"intro\":\"want・hope・decide・promise・plan——これらはどれも、まだしていないこれからのことを表します。だからうしろは、これから向かう感じのある to＋原形になります。あわせて want 人 to 〜 のような、人をはさむ形も確かめます。\",\"order\":822,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"不定詞専用：want・hope・decide・promise・plan・wish・expect・agree・refuse。\",\"want 人 to 〜（人に〜してほしい）という形も重要。\",\"tell 人 to 〜（〜するように言う）／ask 人 to 〜（〜するよう頼む）。\",\"これらの動詞に 〜ing を続けたら誤りになる。\",\"want 人 to 〜 と hope の形のちがいに注意（hope 人 to 〜 は不可）。\"],\"sections\":[{\"heading\":\"不定詞専用の動詞と「人＋to」の形\",\"body\":\"次の動詞は、目的語に不定詞しかとらない。どれも「これからのこと」を表す。\\n\\n例）I want to be a scientist.（科学者になりたい）\\n例）We hope to see you soon.（すぐにお会いできることを願っています）\\n例）He decided to study abroad.（彼は留学することに決めた）\\n例）She promised to come early.（彼女は早く来ると約束した）\\n例）They plan to build a new library.（彼らは新しい図書館を建てる計画だ）\\n例）I expect to arrive at six.（六時に着く見こみだ）\\n\\n■ 「人に〜してほしい」の形\\n例）I want you to help me.（あなたに手伝ってほしい）\\n例）My mother told me to clean my room.（母はわたしに部屋をそうじするように言った）\\n例）He asked me to open the door.（彼はわたしにドアを開けるよう頼んだ）\\n「動詞＋人＋to＋原形」の順に並べる。この形をとる動詞は want・tell・ask が代表である。\\n\\n■ 訳し分け\\nwant 人 to 〜：〜してほしい\\ntell 人 to 〜：〜するように言う（命令に近い）\\nask 人 to 〜：〜するよう頼む（お願い）\\n\\n★ ポイント：「人＋to」の形をとれるのは want・tell・ask など。hope はこの形をとれないので、hope you to 〜 は誤りである。\",\"figureId\":\"xf_eigo_s322\"},{\"heading\":\"否定と、命令文の書きかえ\",\"body\":\"「人に〜しないように言う」は、not を to の前に置く。\\n\\n例）My mother told me not to go out at night.（母はわたしに夜に外出しないように言った）\\n例）He asked me not to tell anyone.（彼はだれにも言わないでほしいと頼んだ）\\n\\n■ 命令文からの書きかえ\\n例）She said to me, \\\"Open the window.\\\"\\n　→ She told me to open the window.（彼女はわたしに窓を開けるように言った）\\n例）He said to me, \\\"Don't be late.\\\"\\n　→ He told me not to be late.（彼はわたしに遅れないように言った）\\n命令文が肯定なら to＋原形、否定なら not to＋原形になる。\\n\\n例）\\\"Please help me,\\\" he said to me.\\n　→ He asked me to help him.（彼はわたしに手伝ってくれるよう頼んだ）\\nplease が付いた依頼の命令文は ask を使い、代名詞は me → him のように変える。\\n\\n■ 主語の変化に注意\\n書きかえたとき、もとの文の me や him がだれを指すかが変わることがある。「だれがだれに何をするのか」を必ず確かめる。\\n\\n⚠ 注意：told me to not go out のように not を to のあとに置くのは誤り。not は必ず to の前である。\",\"mangaId\":\"eigo_s322_xm\"}],\"trapExamples\":[{\"question\":\"日本語に合う英文にしなさい。「わたしは彼に手伝ってほしい」\",\"wrongAnswer\":\"I want he to help me.\",\"trapExplanation\":\"「彼に」の部分をそのまま主格 he で書いてしまう。want のあとの人は目的語なので目的格にしなければならない。\",\"correctAnswer\":\"I want him to help me.\",\"correctExplanation\":\"want 人 to 〜 の「人」は目的語の位置なので目的格にする。he → him、she → her、they → them、I → me。同じ形の tell him to 〜、ask her to 〜 も同様である。\"},{\"question\":\"命令文を書きかえなさい。My father said to me, \\\"Don't watch TV before dinner.\\\"\",\"wrongAnswer\":\"My father told me to don't watch TV before dinner.\",\"trapExplanation\":\"もとの命令文の Don't をそのまま残してしまう。「to＋原形」の形の中に don't を入れることはできない。\",\"correctAnswer\":\"My father told me not to watch TV before dinner.\",\"correctExplanation\":\"否定の命令文を書きかえるときは、don't を消して not を to の前に置く。「told 人 not to＋原形」が決まった形である。not to watch の順序（not が先）も重要である。\"}]}",
"{\"id\":\"eigo_s323\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"目的語の形④：意味が変わる stop・remember・forget・try\",\"description\":\"不定詞と動名詞で意味が変わる動詞を、時間の向きで整理する\",\"intro\":\"He stopped to smoke. と He stopped smoking. は、たった一語のちがいで意味が正反対になります。前者はたばこを吸うために立ち止まり、後者はたばこをやめたのです。to はこれから、ing はもうしたこと。時間の向きで整理します。\",\"order\":823,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"stop to 〜＝〜するために立ち止まる／stop 〜ing＝〜するのをやめる。\",\"remember to 〜＝忘れずに〜する／remember 〜ing＝〜したことを覚えている。\",\"forget to 〜＝〜するのを忘れる／forget 〜ing＝〜したことを忘れる。\",\"try to 〜＝〜しようと努力する／try 〜ing＝ためしに〜してみる。\",\"不定詞は「これから」、動名詞は「すでに・実際に」の向きを表す。\"],\"sections\":[{\"heading\":\"時間の向きで区別する\",\"body\":\"同じ動詞でも、後ろが不定詞か動名詞かで意味が変わるものがある。区別のかぎは「時間の向き」である。不定詞はこれからのこと、動名詞はすでにしたこと・現にしていることを指す。\\n\\n■ stop\\n例）He stopped to smoke.（彼はたばこを吸うために立ち止まった）… これから吸う\\n例）He stopped smoking.（彼はたばこを吸うのをやめた）… もう吸わない\\nstop to 〜 の不定詞は目的語ではなく、目的を表す副詞的用法である。\\n\\n■ remember\\n例）Remember to lock the door.（忘れずにドアにかぎをかけなさい）… これからかける\\n例）I remember locking the door.（ドアにかぎをかけたことを覚えている）… すでにかけた\\n\\n■ forget\\n例）Don't forget to call me.（電話するのを忘れないで）… これからかける\\n例）I'll never forget visiting Kyoto.（京都を訪れたことを決して忘れない）… すでに訪れた\\n\\n■ try\\n例）I tried to open the window.（窓を開けようとした）… 努力したができなかった感じ\\n例）I tried opening the window.（ためしに窓を開けてみた）… 実際に開けた\\n\\n★ ポイント：不定詞＝未来向き、動名詞＝過去・現実向き。この一本の軸で四つの動詞をまとめて整理できる。\",\"figureId\":\"lf_eigoext09_323\",\"mangaId\":\"eigo_s323_xm\"},{\"heading\":\"文脈から判断する練習\",\"body\":\"試験では、前後の文から時間の向きを読み取って選ぶ問題が出る。\\n\\n例）I remember (see) him somewhere before.\\n　before（以前に）があるので、すでに会ったこと → seeing\\n\\n例）Please remember (bring) your umbrella tomorrow.\\n　tomorrow（明日）があるので、これから持ってくること → to bring\\n\\n例）She stopped (talk) when the teacher came in.\\n　先生が入ってきて話すのをやめた → talking\\n\\n例）He stopped (buy) a drink on his way home.\\n　飲み物を買うために立ち止まった → to buy\\n\\n■ 手がかりになる語\\nbefore・yesterday・last week → 動名詞（すでにしたこと）\\ntomorrow・next time・don't forget → 不定詞（これからのこと）\\n\\n■ 訳の確認\\n迷ったら両方の訳を作ってみて、文脈に合う方を選ぶ。「彼はたばこを吸うために立ち止まった」と「彼はたばこをやめた」では、話の流れがまったくちがう。\\n\\n⚠ 注意：stop to 〜 の to＋原形は目的語ではないので、「〜することをやめる」という意味には絶対にならない。「やめる」と言いたいときは必ず stop 〜ing である。\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。My father stopped smoking last year.\",\"wrongAnswer\":\"父は去年たばこを吸うために立ち止まった。\",\"trapExplanation\":\"stop to 〜 と stop 〜ing の区別があいまいなまま、stop を「立ち止まる」の意味に取ってしまう。last year という語とも合わない訳になる。\",\"correctAnswer\":\"父は去年たばこをやめた。\",\"correctExplanation\":\"stop 〜ing は「（すでにしていたことを）やめる」という意味である。stop to 〜 なら「〜するために立ち止まる」で、この to＋原形は目的を表す副詞的用法になる。動名詞は「すでに行っていること」を指す、という向きで覚える。\"},{\"question\":\"（　）内を適する形にしなさい。Don't forget (post) this letter tomorrow.\",\"wrongAnswer\":\"posting\",\"trapExplanation\":\"forget 〜ing（〜したことを忘れる）の形を覚えていると、意味を確かめずに動名詞を選んでしまう。tomorrow という語を見落としている。\",\"correctAnswer\":\"to post\",\"correctExplanation\":\"tomorrow があるので、これから出す手紙のことである。「これから〜するのを忘れない」は forget to 〜 を使う。forget 〜ing は「（過去に）〜したことを忘れる」で、I'll never forget seeing him.（彼に会ったことを忘れない）のように使う。\"}]}",
"{\"id\":\"eigo_s324\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"分詞①：現在分詞が名詞の前に付く（a sleeping baby）\",\"description\":\"〜ing 一語が名詞を前から修飾する形をつかむ\",\"intro\":\"「眠っている赤ちゃん」を a baby sleeping と言いたくなりますが、ふつうは a sleeping baby です。ing の形はもとは動詞なのに、一語のときは形容詞と同じように名詞の前に立ちます。動詞が名詞を説明する側に回る使い方を見ます。\",\"order\":824,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"現在分詞（〜ing）は「〜している」という意味で名詞を説明する。\",\"一語だけのときは名詞の前に置く（a sleeping baby＝眠っている赤ちゃん）。\",\"a running boy（走っている少年）／a crying child（泣いている子ども）。\",\"動名詞の 〜ing（〜すること）とは意味がちがう（a sleeping bag＝寝袋）。\",\"進行形（be動詞＋〜ing）とも区別する。前に be動詞があるかを確かめる。\"],\"sections\":[{\"heading\":\"「〜している○○」の言い方\",\"body\":\"動詞に ing を付けた形（現在分詞）は、「〜している」という意味で名詞を説明できる。説明する語が一語だけのときは、形容詞と同じように名詞の前に置く。\\n\\n例）Look at the sleeping baby.（眠っている赤ちゃんを見て）\\n例）The running boy is my brother.（走っている少年はわたしの弟だ）\\n例）I heard a crying child.（泣いている子どもの声が聞こえた）\\n例）Don't touch the burning candle.（燃えているろうそくにさわらないで）\\n\\n■ 形容詞と同じ位置\\na big house（大きな家）の big と同じ位置に sleeping が入る、と考えればよい。\\na big baby（大きな赤ちゃん）／a sleeping baby（眠っている赤ちゃん）\\n\\n■ 進行形との区別\\n例）The baby is sleeping.（赤ちゃんは眠っている）… 進行形の文\\n例）the sleeping baby（眠っている赤ちゃん）… 名詞のかたまり\\n進行形は be動詞とセットで文の動詞になる。分詞の形容詞用法は be動詞を伴わず、名詞にくっついてかたまりを作る。\\n\\n★ ポイント：〜ing のあとに名詞が続いていて、その前に be動詞がなければ、その 〜ing は名詞を説明する現在分詞である。\",\"figureId\":\"lf_eigoext09_324\"},{\"heading\":\"動名詞が名詞に付く場合との区別\",\"body\":\"〜ing ＋ 名詞の形には、実は二種類ある。\\n\\n■ 現在分詞：「〜している○○」\\n例）a sleeping baby（眠っている赤ちゃん）… 赤ちゃんが眠っている\\n例）a swimming boy（泳いでいる少年）… 少年が泳いでいる\\n\\n■ 動名詞：「〜するための○○」（用途を表す）\\n例）a sleeping bag（寝袋）… ふくろが眠っているのではない\\n例）a swimming pool（プール）… プールが泳いでいるのではない\\n例）a waiting room（待合室）／a shopping bag（買い物ぶくろ）\\n\\n■ 見分け方\\n「その名詞が〜している」と言えるなら現在分詞、「〜するための道具・場所」なら動名詞である。\\n　The baby is sleeping.（○）→ a sleeping baby は現在分詞\\n　The bag is sleeping.（×）→ a sleeping bag は動名詞\\n\\n■ 訳し方の注意\\na sleeping bag を「眠っているふくろ」と訳すと意味が通らない。おかしいと感じたら、用途を表す動名詞ではないかを疑う。\\n\\n⚠ 注意：中学受験ではこの区別を細かく問われることは少ないが、a swimming pool・a shopping mall などの語を「泳いでいるプール」と読まないよう、意味で確かめる習慣をつけておく。\",\"mangaId\":\"eigo_s324_xm\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。The crying girl is my sister.\",\"wrongAnswer\":\"泣いている女の子はわたしの姉妹である。（The girl is crying. と同じ文だと考える）\",\"trapExplanation\":\"訳自体はほぼ合っていても、crying を文の動詞だと考えると、is my sister との関係が説明できなくなる。進行形と分詞の区別ができていないと、長い文で必ず行きづまる。\",\"correctAnswer\":\"泣いている女の子はわたしの妹（姉）だ。The crying girl までが主語、is が動詞。\",\"correctExplanation\":\"crying は The girl を前から説明する現在分詞で、The crying girl 全体が主語になっている。文の動詞は is である。進行形なら The girl is crying. のように be動詞が 〜ing の直前に来る。文の骨組みを見つける練習として重要である。\"},{\"question\":\"日本語に直しなさい。I bought a new sleeping bag.\",\"wrongAnswer\":\"わたしは新しい眠っているふくろを買った。\",\"trapExplanation\":\"〜ing ＋ 名詞をすべて「〜している○○」と訳してしまう。ふくろが眠るはずがないのに、形だけで機械的に処理している。\",\"correctAnswer\":\"わたしは新しい寝袋を買った。\",\"correctExplanation\":\"a sleeping bag の sleeping は「眠るための」という用途を表す動名詞である。「その名詞が〜している」と言えるかどうかで判断する。a swimming pool（泳ぐためのプール）、a waiting room（待つための部屋）も同じ形である。\"}]}",
"{\"id\":\"eigo_s325\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"分詞②：二語以上は名詞の後ろ（the boy running in the park）\",\"description\":\"現在分詞のかたまりが名詞を後ろから説明する形を読めるようにする\",\"intro\":\"a sleeping baby は前から、the boy running in the park はうしろから説明します。同じ ing なのに位置が変わるのは、running in the park が四語のかたまりだからです。長いものはうしろへ——英語のこの原則をもう一度確かめます。\",\"order\":825,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"現在分詞に語句が付いて二語以上になったら、名詞の後ろに置く。\",\"the boy running in the park（公園で走っている少年）。\",\"日本語に訳すときは後ろから前へ訳し上げる。\",\"主語が長くなるので、文の動詞がどれかを見きわめる必要がある。\",\"関係代名詞を使った文（the boy who is running）とほぼ同じ意味になる。\"],\"sections\":[{\"heading\":\"後ろから説明するかたまり\",\"body\":\"現在分詞に語句が付いて長くなると、名詞の後ろに回る。英語の大原則「一語は前、二語以上は後ろ」のとおりである。\\n\\n例）The boy running in the park is my brother.（公園で走っている少年はわたしの弟だ）\\n例）Do you know the girl playing the piano?（ピアノをひいている女の子を知っていますか）\\n例）The man standing by the door is our teacher.（ドアのそばに立っている男の人はわたしたちの先生だ）\\n例）Look at the cat sleeping on the sofa.（ソファの上で眠っているねこを見て）\\n\\n■ 前と後ろの対応\\na sleeping baby（一語→前）\\nthe baby sleeping in the bed（四語→後ろ）\\n同じ sleeping でも、後ろに語句が付くかどうかで位置が変わる。\\n\\n■ 訳し上げる\\nThe boy running in the park → 公園で走っている少年\\n英語では「少年 ← 公園で走っている」の順、日本語では逆になる。\\n\\n★ ポイント：名詞のすぐ後ろに 〜ing が来て、その前に be動詞がなければ、そこから後ろは名詞の説明である。\",\"figureId\":\"xf_eigo_s325\"},{\"heading\":\"文の動詞を見つける\",\"body\":\"分詞のかたまりが主語に付くと、主語が長くなって動詞が遠くなる。読解でつまずく最大の原因なので、切り分けの練習をする。\\n\\n例）The students studying in the library are my classmates.\\n　主語：The students studying in the library（図書館で勉強している生徒たち）\\n　動詞：are\\n　訳：図書館で勉強している生徒たちはわたしのクラスメートだ。\\n\\n例）The woman talking with my mother is a doctor.\\n　主語：The woman talking with my mother\\n　動詞：is\\n　訳：母と話している女性は医者だ。\\n\\n■ 手順\\n①文の先頭から名詞を見つける\\n②その直後に 〜ing があれば、説明のかたまりが始まったと考える\\n③次に出てくる be動詞や一般動詞が、文の本当の動詞である\\n\\n■ 関係代名詞との関係\\n例）The boy running in the park ＝ The boy who is running in the park\\n分詞は関係代名詞＋be動詞を省いた形と考えることもできる。あとの単元で学ぶ関係代名詞とつながる大切な見方である。\\n\\n⚠ 注意：The boy running in the park is my brother. を「少年は公園で走っている」と読むと、後ろの is my brother が宙にういてしまう。動詞が二つあるように見えたら、前の 〜ing は説明のかたまりだと考える。\",\"mangaId\":\"eigo_s325_xm\"}],\"trapExamples\":[{\"question\":\"日本語に直しなさい。The girl singing on the stage is my sister.\",\"wrongAnswer\":\"女の子はステージの上で歌っていて、わたしの姉だ。\",\"trapExplanation\":\"singing を文の動詞だと考えて進行形のように訳し、そのあとの is my sister を無理につなげてしまう。be動詞がないことに気づいていない。\",\"correctAnswer\":\"ステージの上で歌っている女の子はわたしの姉だ。\",\"correctExplanation\":\"singing の前に be動詞がないので、これは The girl を後ろから説明する現在分詞である。The girl singing on the stage までが主語で、文の動詞は is。「名詞＋〜ing」で be動詞がなければ説明のかたまりだと判断する。\"},{\"question\":\"日本語に合うように並べかえなさい。「向こうで走っている犬はわたしのです」　running / the / over there / dog / is / mine\",\"wrongAnswer\":\"The running over there dog is mine.\",\"trapExplanation\":\"「一語なら名詞の前」というルールだけを覚えていて、running に over there が付いて二語以上になっていることを見落としてしまう。\",\"correctAnswer\":\"The dog running over there is mine.\",\"correctExplanation\":\"説明が二語以上のかたまりになったら、名詞の後ろに置く。running over there は三語のかたまりなので The dog の後ろに回す。前に置けるのは a running dog のように分詞が一語のときだけである。\"}]}",
"{\"id\":\"eigo_s326\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"分詞③：過去分詞が名詞を説明する（〜される・〜された）\",\"description\":\"過去分詞の形容詞用法を、前置と後置の両方でおさえる\",\"intro\":\"a broken window の broken は、こわれた結果の状態を表しています。窓は自分でこわれたのではなく、こわされた側です。ing が「している」なら、過去分詞は「される・された」。受け身の意味で名詞を説明する形をおさえます。\",\"order\":826,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"過去分詞は「〜される・〜された」という受け身の意味で名詞を説明する。\",\"一語なら名詞の前（a broken window＝こわれた窓）。\",\"二語以上なら名詞の後ろ（a letter written in English＝英語で書かれた手紙）。\",\"規則動詞の過去分詞は 〜ed、不規則動詞は個別に覚える（write－wrote－written）。\",\"現在分詞は「する側」、過去分詞は「される側」を表す。\"],\"sections\":[{\"heading\":\"「〜された○○」の言い方\",\"body\":\"過去分詞を名詞に付けると、「〜される」「〜された」という受け身の意味を表す。\\n\\n■ 一語なら前\\n例）a broken window（こわれた窓）\\n例）a used car（中古車＝使われた車）\\n例）boiled eggs（ゆで卵＝ゆでられた卵）\\n例）fried chicken（フライドチキン＝油であげられたとり肉）\\n\\n■ 二語以上なら後ろ\\n例）This is a letter written in English.（これは英語で書かれた手紙だ）\\n例）The book read by many people is famous.（多くの人に読まれているその本は有名だ）\\n例）I like the picture painted by Picasso.（ピカソによってかかれたその絵が好きだ）\\n例）The language spoken in Brazil is Portuguese.（ブラジルで話されている言語はポルトガル語だ）\\n\\n■ 過去分詞の作り方\\n規則動詞：play → played／use → used／cook → cooked\\n不規則動詞：write → written／break → broken／speak → spoken／take → taken／make → made／see → seen／know → known／build → built\\n\\n★ ポイント：過去分詞は受動態でも使うので、不規則動詞の変化表（原形・過去形・過去分詞）を必ず覚えておく。\",\"figureId\":\"lf_eigoext09_326\"},{\"heading\":\"過去形と過去分詞を混同しない\",\"mangaId\":\"eigo_s326_manga\",\"body\":\"過去分詞は過去形とは別物である。形が同じ動詞が多いので、位置で判断する。\\n\\n例）I read the book written by him.（彼によって書かれた本を読んだ）\\n文の動詞は read（過去形）、written は the book を説明する過去分詞である。\\n\\n例）The window broken by the boy was mine.（その少年にこわされた窓はわたしのものだった）\\n主語は The window broken by the boy、動詞は was である。broken を文の動詞と読んでしまうと、was の行き場がなくなる。\\n\\n■ 規則動詞では形が同じ\\n例）The car used by my father is old.（父が使っている車は古い）\\nused は過去形とも過去分詞とも同じ形だが、あとに was／is などの動詞が続くことから、ここでは過去分詞だとわかる。\\n\\n■ 判断の手順\\n①名詞のすぐあとに動詞らしい語があるか\\n②その語のあとにもう一つ動詞（is・was・are など）があるか\\n③あれば、最初の語は名詞を説明する分詞である\\n\\n⚠ 注意：I know a boy called Ken.（ケンと呼ばれている少年を知っている）のように、called＝「〜と呼ばれる」の形は入試頻出である。call－called－called と変化する規則動詞である。\"}],\"trapExamples\":[{\"question\":\"（　）内を適する形にしなさい。This is a book (write) by Natsume Soseki.\",\"wrongAnswer\":\"writing\",\"trapExplanation\":\"分詞といえば 〜ing と覚えてしまい、本が「書く側」なのか「書かれる側」なのかを考えずに現在分詞を選んでしまう。\",\"correctAnswer\":\"written\",\"correctExplanation\":\"本は書かれるものなので、受け身の意味を表す過去分詞 written を使う。write－wrote－written と変化する不規則動詞である。「〜している」なら現在分詞、「〜される・された」なら過去分詞、と意味で選ぶ。\"},{\"question\":\"日本語に直しなさい。The letter written in French was difficult to read.\",\"wrongAnswer\":\"その手紙はフランス語で書いた、そして読むのが難しかった。\",\"trapExplanation\":\"written を文の動詞（過去形）だと考えてしまい、そのあとの was の位置づけができなくなる。分詞のかたまりが主語に付いていることを見落としている。\",\"correctAnswer\":\"フランス語で書かれたその手紙は読むのが難しかった。\",\"correctExplanation\":\"written in French は The letter を後ろから説明する過去分詞のかたまりで、主語は The letter written in French、文の動詞は was である。動詞らしい語が二つ並んだら、前の方が分詞ではないかを疑う。\"}]}",
"{\"id\":\"eigo_s327\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"分詞④：現在分詞と過去分詞の使い分け\",\"description\":\"「する側」か「される側」かで分詞を選べるようにする\",\"intro\":\"the boy calling my name と the boy called Ken。前者は名前を呼んでいる少年、後者はケンと呼ばれている少年です。ing か過去分詞かを決めるのは、説明される名詞が「する側」か「される側」かの一点だけ。この判断を練習します。\",\"order\":827,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"説明される名詞が動作をする側なら現在分詞（〜ing）。\",\"説明される名詞が動作をされる側なら過去分詞。\",\"the boy calling my name（わたしの名を呼んでいる少年）／the boy called Ken（ケンと呼ばれる少年）。\",\"exciting（わくわくさせる）と excited（わくわくした）の使い分けも同じ考え方。\",\"迷ったら「名詞は〜しているのか、〜されるのか」と日本語で確かめる。\"],\"sections\":[{\"heading\":\"する側か、される側か\",\"mangaId\":\"eigo_s327_manga\",\"body\":\"現在分詞と過去分詞のどちらを使うかは、説明される名詞と動作の関係で決まる。\\n\\n■ 名詞が動作をする側 → 現在分詞\\n例）the boy calling my name（わたしの名を呼んでいる少年）… 少年が呼んでいる\\n例）the girl reading a book（本を読んでいる女の子）… 女の子が読んでいる\\n例）the dog running in the yard（庭を走っている犬）\\n\\n■ 名詞が動作をされる側 → 過去分詞\\n例）the boy called Ken（ケンと呼ばれている少年）… 少年が呼ばれている\\n例）the book read by many people（多くの人に読まれる本）\\n例）the window broken by the ball（ボールでこわされた窓）\\n\\n■ 同じ動詞で見くらべる\\n例）the man teaching English（英語を教えている男の人）\\n例）English taught by him（彼によって教えられている英語）\\n同じ teach でも、主語になる名詞が教える側か教えられる側かで形が変わる。\\n\\n■ 確かめ方\\n名詞を主語にして文を作ってみる。\\n　The boy calls my name.（少年が呼ぶ）→ 現在分詞 calling\\n　The boy is called Ken.（少年が呼ばれる）→ 過去分詞 called\\n\\n★ ポイント：「する側＝〜ing」「される側＝過去分詞」。この一行が分詞の全部である。\",\"figureId\":\"xf_eigo_s327\"},{\"heading\":\"exciting と excited\",\"body\":\"感情を表す語にも、同じ「する側・される側」の考え方が当てはまる。\\n\\n■ 〜ing：まわりをそういう気持ちにさせる\\n例）The game was exciting.（その試合はわくわくさせるものだった＝おもしろかった）\\n例）This is an interesting book.（これはおもしろい本だ）\\n例）The news was surprising.（その知らせは驚くべきものだった）\\n\\n■ 過去分詞：人がそういう気持ちにさせられた\\n例）I was excited.（わたしはわくわくした）\\n例）I am interested in science.（わたしは科学に興味がある）\\n例）We were surprised at the news.（わたしたちはその知らせに驚いた）\\n\\n■ 使い分けのこつ\\n人が主語なら過去分詞、ものごとが主語なら 〜ing になることが多い。\\n例）I was bored.（退屈した）／The movie was boring.（その映画は退屈だった）\\n「I am boring.」と書くと「わたしは退屈な人間だ」という意味になってしまう。\\n\\n■ 前置詞とセットで覚える\\nbe interested in（〜に興味がある）／be surprised at（〜に驚く）／be excited about（〜にわくわくする）\\n\\n⚠ 注意：I am interesting in music. は誤り。「わたしが興味を持っている」のだから I am interested in music. とする。この一語のちがいで意味が正反対になる。\"}],\"trapExamples\":[{\"question\":\"（　）内を適する形にしなさい。I know the girl (call) Mary.\",\"wrongAnswer\":\"calling\",\"trapExplanation\":\"「〜している」の形をとりあえず選んでしまい、少女が呼んでいるのか呼ばれているのかを考えない。calling Mary だと「メアリーを呼んでいる少女」となり、意味が変わる。\",\"correctAnswer\":\"called\",\"correctExplanation\":\"「メアリーと呼ばれている少女」なので、される側を表す過去分詞 called を使う。the girl calling Mary（メアリーを呼んでいる少女）とはまったく別の意味になるので、名詞が「する側」か「される側」かを必ず確かめる。\"},{\"question\":\"（　）に適する語を入れなさい。I am (　) in Japanese history.（日本の歴史に興味がある）\",\"wrongAnswer\":\"interesting\",\"trapExplanation\":\"「おもしろい」＝interesting と覚えているため、興味を持っているのが自分であることを考えずに 〜ing を選んでしまう。\",\"correctAnswer\":\"interested\",\"correctExplanation\":\"人が興味を持たされている側なので過去分詞 interested を使い、be interested in 〜 の形にする。interesting は「（まわりを）おもしろがらせる」という意味で、Japanese history is interesting. のようにものごとを主語にして使う。\"}]}",
"{\"id\":\"eigo_s328\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞①：二つの文を一つにする（主格の who）\",\"description\":\"関係代名詞のはたらきを理解し、人を先行詞とする主格の who を使えるようにする\",\"intro\":\"「わたしには京都に住んでいるおじがいます」を英語にすると、二つの文に分かれてしまいます。I have an uncle. He lives in Kyoto. これを一文にするために英語が用意したのが関係代名詞です。He を who に変えるだけでつながります。\",\"order\":828,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"関係代名詞は「代名詞」と「接着剤」の二役を同時に果たす語。\",\"説明される名詞を先行詞といい、関係代名詞はそのすぐ後ろに置く。\",\"先行詞が人で、あとに動詞が続くときは主格の who を使う。\",\"who のあとの動詞は、先行詞の数に合わせる（a boy who plays／boys who play）。\",\"関係詞のかたまりは、名詞を後ろから説明する（英語の大原則どおり）。\"],\"sections\":[{\"heading\":\"二つの文をつなぐしくみ\",\"body\":\"次の二つの文を、一つにまとめてみる。\\n\\n　I know a boy.（わたしはある少年を知っている）\\n　He plays the piano well.（彼はピアノを上手にひく）\\n\\n二つ目の文の He は、一つ目の a boy を指している。この He を who に変えて、a boy のすぐ後ろにくっつける。\\n\\n　→ I know a boy who plays the piano well.（わたしはピアノを上手にひく少年を知っている）\\n\\n■ 関係代名詞の二つの役目\\n①代名詞の役目：He の代わりをして、あとの文の主語になっている\\n②接着剤の役目：二つの文をつなげている\\nこの二役を同時に果たすので「関係代名詞」という。\\n\\n■ 先行詞\\n説明される名詞（この文では a boy）を先行詞という。関係代名詞は必ず先行詞のすぐ後ろに置く。\\n\\n■ もっと例を見る\\n例）The girl who won the race is my friend.（レースに勝った女の子はわたしの友だちだ）\\n例）I have a friend who lives in America.（アメリカに住んでいる友だちがいる）\\n例）Do you know the man who is talking with Ken?（ケンと話している男の人を知っていますか）\\n\\n★ ポイント：who のあとには必ず動詞が来る。これが主格の目印である。\",\"figureId\":\"lf_eigoext09_328\",\"mangaId\":\"eigo_s328_xm\"},{\"heading\":\"動詞の形を先行詞に合わせる\",\"body\":\"who のあとの動詞は、先行詞の人称と数に合わせる。ここが入試でよくねらわれる。\\n\\n例）I have a friend who lives in Osaka.（大阪に住んでいる友だちが一人いる）\\n　先行詞 a friend は単数 → lives（s が付く）\\n例）I have friends who live in Osaka.（大阪に住んでいる友だちがいる）\\n　先行詞 friends は複数 → live（s は付かない）\\n\\n■ 時制もそろえる\\n例）I met a girl who was from Canada.（カナダ出身の女の子に会った）\\n文全体が過去なので、関係詞のあとの動詞も過去にする。\\n\\n■ 主語が長くなる文\\n例）The students who study hard get good grades.\\n　主語：The students who study hard（一生けんめい勉強する生徒たち）\\n　動詞：get\\n関係詞のかたまりが主語に付くと動詞が遠くなる。二つ目の動詞が文全体の動詞である。\\n\\n■ 訳し上げる\\nThe man who lives next door is a teacher.\\n→ となりに住んでいる男の人は先生だ。\\n関係詞のかたまりは、日本語では名詞の前に置いて訳す。\\n\\n⚠ 注意：I know a boy who he plays the piano. は誤り。who がすでに主語のはたらきをしているので、he を重ねて書いてはいけない。\"}],\"trapExamples\":[{\"question\":\"二つの文を一つにしなさい。I have a friend. She can speak French.\",\"wrongAnswer\":\"I have a friend who she can speak French.\",\"trapExplanation\":\"もとの文の She を消し忘れて、who といっしょに残してしまう。関係代名詞が代名詞の役目を兼ねていることが理解できていない。\",\"correctAnswer\":\"I have a friend who can speak French.\",\"correctExplanation\":\"who は She の代わりとしてあとの文の主語になっているので、She は消さなければならない。関係代名詞は「代名詞＋接着剤」の二役をこなす語である。主語が二つ並んでいたら、必ずどちらかが余分である。\"},{\"question\":\"（　）内を適する形にしなさい。I have a friend who (live) in London.\",\"wrongAnswer\":\"live\",\"trapExplanation\":\"文の主語が I なので、動詞にも s は要らないと考えてしまう。who のあとの動詞が合わせるのは先行詞であることを見落としている。\",\"correctAnswer\":\"lives\",\"correctExplanation\":\"who のあとの動詞は先行詞 a friend（三人称単数）に合わせるので lives になる。先行詞が friends なら live である。文全体の主語 I ではなく、直前の先行詞を見るのが鉄則である。\"}]}",
"{\"id\":\"eigo_s329\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞②：主格の which・that（もの・動物）\",\"description\":\"先行詞がもの・動物のときの主格の関係代名詞を使えるようにする\",\"intro\":\"先行詞が人なら who、では犬やバスのときはどうするのでしょう。英語は人とそれ以外を区別するので、もの・動物には which を使います。that はそのどちらにも使える便利な語です。使い分けの境目を、例文で確かめていきます。\",\"order\":829,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"先行詞がもの・動物のときは which を使う。that でも代用できる。\",\"主格なので、関係代名詞のあとには動詞が続く。\",\"a bus which goes to the station（駅へ行くバス）。\",\"先行詞が人でも that は使える（who の代わり）。\",\"動詞の形は先行詞の数に合わせる（a book which is 〜／books which are 〜）。\"],\"sections\":[{\"heading\":\"which と that の使い分け\",\"body\":\"先行詞がもの・動物のときは which を使う。that はもの・人のどちらにも使える万能の関係代名詞である。\\n\\n例）This is the bus which goes to the station.（これは駅へ行くバスです）\\n例）I have a dog which has long ears.（耳の長い犬を飼っている）\\n例）The house which stands on the hill is very old.（丘の上に建っている家はとても古い）\\n\\n■ that で言いかえる\\n例）This is the bus that goes to the station.\\n例）I know a boy that plays the piano well.（人が先行詞でも that が使える）\\n\\n■ 使い分けのまとめ\\n先行詞が人　　→ who／that\\n先行詞がもの・動物 → which／that\\n\\n■ 二つの文をつなぐ手順（which の場合）\\n　I want a computer.（コンピューターがほしい）\\n　It is small and light.（それは小さくて軽い）\\n　→ I want a computer which is small and light.\\nIt を which に変え、先行詞 a computer のすぐ後ろに置く。\\n\\n★ ポイント：which のあとに動詞が来ていれば主格。先行詞の数に合わせて is／are、has／have を選ぶ。\",\"figureId\":\"xf_eigo_s329\",\"mangaId\":\"eigo_s329_xm\"},{\"heading\":\"長い文を読み解く\",\"body\":\"関係代名詞が入ると文が長くなるので、かたまりの切れ目を見つける練習が必要である。\\n\\n例）The train which leaves at six is always crowded.\\n　主語：The train which leaves at six（六時に出る電車）\\n　動詞：is\\n　訳：六時に出る電車はいつもこんでいる。\\n\\n例）I like books which have a lot of pictures.\\n　先行詞：books（複数）→ have（s は付かない）\\n　訳：わたしは絵がたくさんある本が好きだ。\\n\\n例）This is the letter which came from my uncle.\\n　訳：これはおじから来た手紙だ。\\n\\n■ 手順\\n①名詞のすぐあとに who・which・that があるか見る\\n②あれば、そこから説明のかたまりが始まる\\n③次に出てくる動詞（二つ目の動詞）が文全体の動詞\\n\\n■ 主語と動詞の数の一致\\n例）The books which are on the desk are mine.\\nare が二回出てくるが、一つ目は関係詞の中の動詞（先行詞 books に合わせる）、二つ目が文全体の動詞である。\\n\\n⚠ 注意：I have a dog which it has long ears. は誤り。which が主語のはたらきをしているので it は不要である。\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。This is the train (　) goes to Kyoto.\",\"wrongAnswer\":\"who\",\"trapExplanation\":\"関係代名詞といえば who と覚えてしまい、先行詞が人かものかを確かめずに選んでしまう。\",\"correctAnswer\":\"which（または that）\",\"correctExplanation\":\"先行詞 the train はものなので which を使う。that でもよい。who を使えるのは先行詞が人のときだけである。「人＝who、もの＝which、どちらでも＝that」と整理しておく。\"},{\"question\":\"（　）内を適する形にしなさい。I like the songs which (be) popular among young people.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"直前が which という単数のような語なので、機械的に is を選んでしまう。合わせるのは先行詞であることを忘れている。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"関係代名詞のあとの動詞は先行詞に合わせる。先行詞は the songs で複数なので are になる。先行詞が the song なら is である。which や that 自体には単数・複数の区別がないので、必ず先行詞を見る。\"}]}",
"{\"id\":\"eigo_s330\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞③：目的格の which・that（穴があく位置）\",\"description\":\"関係詞のあとに主語＋動詞が続く目的格の形を理解する\",\"intro\":\"the book which I read yesterday を見ると、read のうしろに目的語がありません。ふつうなら「何を読んだのか」が必要なはずです。実はその抜けた場所こそ、先行詞 the book が入るべき穴です。この穴に気づけると関係詞は読めます。\",\"order\":830,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"関係代名詞のあとに「主語＋動詞」が続くときは目的格。\",\"目的格の関係詞のあとは、目的語が抜けた「穴」のある文になる。\",\"the book which I read yesterday（わたしが昨日読んだ本）。\",\"目的格には which・that を使う（先行詞が人なら whom・who・that）。\",\"穴の位置に先行詞を戻すと、もとの二文にもどせる。\"],\"sections\":[{\"heading\":\"主格と目的格の見分け方\",\"mangaId\":\"eigo_s330_manga\",\"body\":\"関係代名詞のあとに何が続くかで、主格か目的格かが決まる。\\n\\n■ 主格：関係詞のあとが動詞\\n例）This is the book which made me cry.（わたしを泣かせた本だ）\\nwhich が主語のはたらきをしている。\\n\\n■ 目的格：関係詞のあとが主語＋動詞\\n例）This is the book which I read last week.（先週わたしが読んだ本だ）\\nwhich は read の目的語のはたらきをしている。\\n\\n■ 「穴」を意識する\\n目的格の文では、関係詞のあとの文に目的語がない。\\n　This is the book which I read ★ last week.\\n　★の位置に the book が入るはずだった、と考える。\\n\\n■ 二つの文にもどしてみる\\n　This is the book.（これはその本だ）\\n　I read it last week.（わたしは先週それを読んだ）\\n　it（＝the book）を which に変えて前に出すと、上の文になる。\\n\\n★ ポイント：関係代名詞のあとを見る。動詞なら主格、主語＋動詞なら目的格。この一手で必ず判別できる。\",\"figureId\":\"lf_eigoext09_330\"},{\"heading\":\"目的格の例文と作り方\",\"body\":\"目的格の関係代名詞を使った文を、作り方の手順とともに確認する。\\n\\n例）The movie which we saw yesterday was very sad.（昨日わたしたちが見た映画はとても悲しかった）\\n例）Is this the bag that you bought in Tokyo?（これは東京で買ったかばんですか）\\n例）The cake which my mother made was delicious.（母が作ったケーキはおいしかった）\\n\\n■ 作り方の手順\\n　This is the picture.（これはその写真だ）\\n　I took it in Kyoto.（京都でそれをとった）\\n①二文に共通する語を見つける（the picture ＝ it）\\n②あとの文の it を which に変える\\n③which を文の先頭に出す（which I took in Kyoto）\\n④先行詞のすぐ後ろにつなぐ\\n　→ This is the picture which I took in Kyoto.\\n\\n■ 目的語を残さない\\n例）This is the picture which I took it in Kyoto.（×）\\nwhich がすでに目的語なので it は書かない。主格のときに主語を重ねないのと同じ理屈である。\\n\\n■ 先行詞が人の目的格\\n例）The man whom I met yesterday is a doctor.（昨日会った男の人は医者だ）\\nかたい言い方では whom、ふつうは who または that を使い、実際には省略することが多い。\\n\\n⚠ 注意：目的格の関係代名詞は省略できる（次の課で学ぶ）。省略された文を読めるようにしておくことが、長文読解では決定的に重要である。\"}],\"trapExamples\":[{\"question\":\"二つの文を一つにしなさい。This is the letter. I got it yesterday.\",\"wrongAnswer\":\"This is the letter which I got it yesterday.\",\"trapExplanation\":\"もとの文の it を消し忘れてしまう。which がすでに got の目的語になっていることに気づいていない。\",\"correctAnswer\":\"This is the letter which I got yesterday.\",\"correctExplanation\":\"目的格の関係代名詞は、あとの文の目的語の代わりをしている。したがって it は消す。目的格の文では「関係詞のあとに目的語が抜けた穴がある」のが正しい形である。\"},{\"question\":\"次の関係代名詞は主格か目的格か。I know a girl that speaks three languages.\",\"wrongAnswer\":\"目的格（わたしが知っている女の子、なので）\",\"trapExplanation\":\"「わたしが知っている女の子」という日本語訳から、that を know の目的語だと考えてしまう。しかし know の目的語はすでに a girl であり、that は別のはたらきをしている。\",\"correctAnswer\":\"主格\",\"correctExplanation\":\"that のすぐあとが speaks という動詞なので主格である。that speaks three languages（三か国語を話す）が a girl を説明している。関係詞のあとが動詞なら主格、主語＋動詞なら目的格、と形で判断する。\"}]}",
"{\"id\":\"eigo_s331\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞④：先行詞が人のときの目的格\",\"description\":\"whom・who・that の使い分けと、実際の英文での自然な形を知る\",\"intro\":\"「昨日会った男の人」は the man whom I met yesterday ですが、実際の会話ではふつう the man I met yesterday と言います。whom は正式すぎて、日常ではあまり使われないのです。教科書の形と実際の形、その両方を知っておきます。\",\"order\":831,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"先行詞が人で目的格のときは whom が正式だが、who や that も使われる。\",\"会話では省略するのがふつう（the man I met yesterday）。\",\"the boy whom I saw at the park（公園で見かけた少年）。\",\"主格の who と目的格の whom は、あとに続く形で区別する。\",\"入試では「省略されている関係代名詞を補う」形で問われることが多い。\"],\"sections\":[{\"heading\":\"whom・who・that の使い分け\",\"body\":\"先行詞が人で、関係代名詞が目的語のはたらきをするときは whom を使う。ただし、ふだんの英語では who や that を使ったり、省略したりすることが多い。\\n\\n例）The man whom I met yesterday is a famous writer.（昨日会った男の人は有名な作家だ）\\n例）The girl who(m) you saw is my sister.（あなたが見かけた女の子はわたしの妹だ）\\n例）The student that our teacher praised is Ken.（先生がほめた生徒はケンだ）\\n\\n■ 主格との対比\\n主格：The man who lives next door is kind.（となりに住んでいる男の人は親切だ）… who のあとが動詞\\n目的格：The man whom I met is kind.（わたしが会った男の人は親切だ）… whom のあとが主語＋動詞\\n\\n■ 前置詞が残る場合\\n例）The girl whom I talked with is Yumi.（わたしが話をした女の子はユミだ）\\nもとの文が I talked with her. なので、with が文末に残る。不定詞の a friend to play with と同じ考え方である。\\n\\n★ ポイント：中学受験では whom を書けなくても、who・that で言いかえられれば十分な場合が多い。ただし読解のために whom を見て意味が取れるようにしておく。\",\"figureId\":\"xf_eigo_s331\",\"mangaId\":\"eigo_s331_xm\"},{\"heading\":\"関係代名詞のまとめ表\",\"body\":\"ここまでの関係代名詞を、先行詞と格で整理する。\\n\\n■ 先行詞が人\\n主格：who（that）　例）the boy who runs fast\\n目的格：whom・who（that）　例）the boy whom I know\\n\\n■ 先行詞がもの・動物\\n主格：which（that）　例）the cat which sleeps here\\n目的格：which（that）　例）the cat which I saw\\n\\n■ 判別の手順\\n①先行詞は人か、ものか → who 系か which 系かが決まる\\n②関係詞のあとは動詞か、主語＋動詞か → 主格か目的格かが決まる\\n\\n■ 練習\\n例）I have an uncle (　) works in Canada.\\n　先行詞 an uncle は人、あとは動詞 works → who（主格）\\n例）The book (　) I borrowed was interesting.\\n　先行詞 The book はもの、あとは主語＋動詞 → which（目的格）\\n\\n■ that が好まれる場合\\n先行詞に the only・the first・the best・all・every などが付くときは that を使うのがふつうである。\\n例）This is the best movie that I have ever seen.（これは今まで見た中で最高の映画だ）\\n\\n⚠ 注意：who・whom・which・that はどれも「だれ・どれ」とは訳さない。関係代名詞は疑問詞ではないので、訳語を当てずに「後ろから説明するかたまり」として処理する。\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。The woman (　) I met at the station was Ms. Green.\",\"wrongAnswer\":\"which\",\"trapExplanation\":\"先行詞を確かめずに、目的格といえば which と覚えてしまう。The woman が人であることを見落としている。\",\"correctAnswer\":\"whom（who／that でもよい）\",\"correctExplanation\":\"先行詞 The woman は人なので which は使えない。目的格なので whom が正式だが、who や that でもよい。「人か、ものか」を先に決め、そのあとで「主格か、目的格か」を決める二段階で考える。\"},{\"question\":\"次の文の関係代名詞は主格か目的格か。The boy who is running over there is my brother.\",\"wrongAnswer\":\"目的格（わたしの弟、だから）\",\"trapExplanation\":\"文全体の意味だけで判断してしまい、who の直後を確認していない。is という動詞が続いていることに注意が向いていない。\",\"correctAnswer\":\"主格\",\"correctExplanation\":\"who のあとが is running という動詞なので主格である。目的格なら who のあとに「主語＋動詞」が続く（The boy who I saw 〜）。判別は必ず関係詞の直後の形で行う。\"}]}",
"{\"id\":\"eigo_s332\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞⑤：that を使う場合・使えない場合\",\"description\":\"that が好まれる先行詞と、that の他の用法との区別を整理する\",\"intro\":\"that はどんな先行詞にも使える万能選手ですが、逆に that でなければならない場面もあります。the first・the only・the best、all や every が付くときです。なぜそこだけ that なのかを、意味の面から考えてみます。\",\"order\":832,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"that は人にもものにも使える万能の関係代名詞（主格・目的格の両方）。\",\"先行詞に the only・the first・the best・all・every が付くときは that を使う。\",\"先行詞が「人＋もの」のときも that を使う。\",\"接続詞の that（I think that 〜）や指示語の that とは別物。\",\"関係代名詞の that のあとには、必ず不完全な文（主語か目的語が欠けた文）が来る。\"],\"sections\":[{\"heading\":\"that が好まれる場合\",\"body\":\"that は who・which の代わりに使える便利な関係代名詞だが、特に that を使うのがふつうという場面がある。\\n\\n■ 先行詞に最上級・序数・only・all・every が付くとき\\n例）This is the most interesting book that I have ever read.（今まで読んだ中で最もおもしろい本だ）\\n例）She was the first student that came to school.（最初に学校に来た生徒だった）\\n例）He is the only friend that helped me.（助けてくれたただ一人の友だちだ）\\n例）This is all that I know.（これがわたしの知っているすべてだ）\\n\\n■ 先行詞が「人ともの」の両方のとき\\n例）Look at the boy and the dog that are running.（走っている少年と犬を見て）\\n人には who、ものには which を使うが、両方が並んでいるときはどちらも使えないので that を使う。\\n\\n■ 先行詞が everything・something・anything のとき\\n例）Tell me everything that you know.（あなたが知っていることをすべて教えて）\\n\\n★ ポイント：迷ったら that を使ってよい場面が多い。ただし前置詞の直後（in which など）や、コンマのあとの関係詞では that は使えないが、これは高校で学ぶ内容である。\",\"figureId\":\"xf_eigo_s332\"},{\"heading\":\"いろいろな that を区別する\",\"body\":\"that は関係代名詞のほかにも使い方があるので、区別できるようにする。\\n\\n■ ①指示語の that（あれ・あの）\\n例）That is my house.（あれはわたしの家だ）\\n例）I like that picture.（あの絵が好きだ）\\n\\n■ ②接続詞の that（〜ということ）\\n例）I think that he is right.（彼は正しいと思う）\\n例）I know that she likes music.（彼女が音楽好きだと知っている）\\n接続詞の that のあとには、主語も目的語もそろった完全な文が来る。\\n\\n■ ③関係代名詞の that\\n例）This is the book that I bought yesterday.（昨日買った本だ）\\n関係代名詞の that のあとには、主語か目的語が欠けた不完全な文が来る（I bought の目的語がない）。\\n\\n■ 見分けの手順\\nthat のあとの文を見る。\\n　完全な文（主語も目的語もある）→ 接続詞\\n　不完全な文（主語か目的語がない）→ 関係代名詞\\n　あとに名詞が続く、または一語で文の主語になっている → 指示語\\n\\n■ 練習\\n例）I know that boy.（あの少年を知っている）… 指示語\\n例）I know that he is kind.（彼が親切だと知っている）… 接続詞\\n例）I know a boy that is kind.（親切な少年を知っている）… 関係代名詞\\n\\n⚠ 注意：接続詞の that は省略できる（I think he is right.）が、主格の関係代名詞の that は省略できない。省略できるのは目的格の関係代名詞である。\",\"mangaId\":\"eigo_s332_xm\"}],\"trapExamples\":[{\"question\":\"次の文の that のはたらきは何か。I believe that she will come.\",\"wrongAnswer\":\"関係代名詞（彼女が来るということを信じる、の「ということ」が先行詞）\",\"trapExplanation\":\"that という語を見ると反射的に関係代名詞だと考えてしまう。that の前に先行詞になる名詞がないことを確認していない。\",\"correctAnswer\":\"接続詞（〜ということ）\",\"correctExplanation\":\"that の前に名詞（先行詞）がなく、あとには she will come という主語も動詞もそろった完全な文が続いている。したがって接続詞である。関係代名詞の that なら、あとの文は主語か目的語が欠けた不完全な文になる。\"},{\"question\":\"（　）に適する語を入れなさい。This is the best cake (　) I have ever eaten.\",\"wrongAnswer\":\"who\",\"trapExplanation\":\"関係代名詞を who と決めつけてしまう。先行詞 cake がものであることも、最上級が付いていることも見ていない。\",\"correctAnswer\":\"that（which でもよい）\",\"correctExplanation\":\"先行詞 the best cake はもので、しかも最上級が付いているので that を使うのがふつうである。which も文法的には正しい。先行詞が人でないので who は使えない。\"}]}",
"{\"id\":\"eigo_s333\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞の省略①：目的格は省ける\",\"description\":\"省略できる関係代名詞とできない関係代名詞を、形の上で区別する\",\"intro\":\"I like the book you gave me. は、名詞のあとにいきなり「主語＋動詞」が続くふしぎな形です。これは目的格の関係代名詞が省かれた跡です。省けるものと省けないものがあり、その線引きは形の上ではっきり決まっています。\",\"order\":833,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"目的格の関係代名詞（which・that・whom）は省略できる。\",\"主格の関係代名詞（who・which・that）は省略できない。\",\"省略されると「名詞＋主語＋動詞」という形になる。\",\"the book I read yesterday＝the book which I read yesterday。\",\"実際の英文では省略されている方が多いので、読めることが最優先。\"],\"sections\":[{\"heading\":\"省略できるのは目的格だけ\",\"body\":\"関係代名詞は、目的格のときだけ省略できる。主格は省略できない。\\n\\n■ 目的格（省略できる）\\n例）This is the book which I read yesterday.\\n　→ This is the book I read yesterday.（昨日わたしが読んだ本だ）\\n例）The man whom I met was kind.\\n　→ The man I met was kind.（わたしが会った男の人は親切だった）\\n\\n■ 主格（省略できない）\\n例）I know a boy who plays the piano.（○）\\n例）I know a boy plays the piano.（×）\\n主格を省略すると、動詞が二つ並んで意味が取れなくなってしまう。\\n\\n■ なぜ目的格は省けるのか\\n目的格の関係詞のあとには「主語＋動詞」が続く。名詞のすぐあとにまた主語が来る形は、関係詞がなくても「ここから説明が始まる」とわかるので、省いても混乱しない。\\n\\n■ 省略された形の特徴\\n「名詞 ＋ 主語 ＋ 動詞」と並んでいたら、関係代名詞が省略されていると考える。\\n例）the picture he took（彼がとった写真）\\n例）the song we sang（わたしたちが歌った歌）\\n\\n★ ポイント：関係詞の直後が主語（I・he・we・my mother など）なら省略できる。直後が動詞なら省略できない。\",\"figureId\":\"lf_eigoext09_333\",\"mangaId\":\"eigo_s333_xm\"},{\"heading\":\"省略された文を読む練習\",\"body\":\"実際の英文では、目的格の関係代名詞はほとんど省略される。読めるようにしておくことが最優先である。\\n\\n例）The cake my mother made was delicious.（母が作ったケーキはおいしかった）\\n　＝ The cake which my mother made was delicious.\\n例）Is this the key you are looking for?（これがあなたのさがしているかぎですか）\\n　＝ Is this the key which you are looking for?\\n例）The people I met in Kyoto were very kind.（京都で会った人々はとても親切だった）\\n\\n■ 動詞が二つあることに気づく\\nThe cake my mother made was delicious. には made と was の二つの動詞がある。動詞が二つあるのに接続詞がないときは、関係代名詞が省略されていると考える。\\n\\n■ 切り分けの手順\\n①名詞のすぐあとに主語らしい語（名詞・代名詞）が来ていないか\\n②来ていれば、そこから説明のかたまりが始まる\\n③二つ目の動詞が文全体の動詞\\n\\n■ 主語の中に入る場合\\n例）The book I bought yesterday is very interesting.\\n　主語：The book I bought yesterday（昨日買った本）\\n　動詞：is\\n\\n⚠ 注意：The man I met was kind. を「男の人はわたしに会った」と読むと was kind が宙にういてしまう。名詞のあとに突然別の主語が現れたら、省略された関係代名詞を補って読む。\"}],\"trapExamples\":[{\"question\":\"関係代名詞を省略できるのはどちらか。ア The girl who sings well is Emi.　イ The song which she sang was nice.\",\"wrongAnswer\":\"ア\",\"trapExplanation\":\"関係代名詞はどれも省略できると思いこみ、格を確かめずに答えてしまう。who のあとが動詞であることを見ていない。\",\"correctAnswer\":\"イ\",\"correctExplanation\":\"アの who は直後が動詞 sings なので主格で、省略できない。イの which は直後が she sang という主語＋動詞なので目的格で、The song she sang was nice. と省略できる。省略できるのは目的格だけである。\"},{\"question\":\"日本語に直しなさい。The letter I received this morning was from my grandmother.\",\"wrongAnswer\":\"手紙は今朝わたしを受け取り、祖母から来た。\",\"trapExplanation\":\"The letter を主語、received を文の動詞と読んでしまい、あとの was の位置づけができなくなる。省略された関係代名詞に気づいていない。\",\"correctAnswer\":\"今朝わたしが受け取った手紙は祖母からのものだった。\",\"correctExplanation\":\"The letter のすぐあとに I という別の主語が来ているので、ここに目的格の関係代名詞（which／that）が省略されている。主語は The letter I received this morning、文の動詞は was である。名詞＋主語＋動詞の並びを見たら省略を疑う。\"}]}",
"{\"id\":\"eigo_s334\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係代名詞の省略②：長文で見抜く練習\",\"description\":\"省略・分詞・不定詞が混ざった長い名詞のかたまりを読み解く\",\"intro\":\"長文でつまずく原因の多くは、単語ではなく「文の本当の動詞がどれか分からない」ことです。名詞のうしろに不定詞・分詞・関係詞節がくっつくと、動詞らしきものが二つも三つも並んで見えます。かたまりを切り分ける練習をします。\",\"order\":834,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"名詞の後ろに付く説明は、不定詞・分詞・関係詞節の三種類。\",\"いずれも「名詞 ← 後ろから説明」という同じしくみである。\",\"文の本当の動詞を見つけることが、長文読解の第一歩。\",\"動詞が二つ以上あって接続詞がなければ、どこかが説明のかたまりである。\",\"主語が長いときほど、区切りを鉛筆で示しながら読む。\"],\"sections\":[{\"heading\":\"三種類の後置修飾を並べて確認\",\"body\":\"名詞を後ろから説明する形は、これまでに三つ学んだ。すべて同じしくみである。\\n\\n■ ①不定詞\\n例）I have a lot of homework to do.（するべき宿題）\\n■ ②分詞\\n例）The boy running in the park is Ken.（走っている少年）\\n例）The letter written in English is from Tom.（英語で書かれた手紙）\\n■ ③関係詞節\\n例）The book which I bought is interesting.（買った本）\\n例）The book I bought is interesting.（省略形）\\n\\nどれも「名詞 ＋ 説明のかたまり」という同じ形をしている。日本語にするときは、必ず後ろから前へ訳し上げる。\\n\\n■ 言いかえの関係\\n例）the boy running in the park ＝ the boy who is running in the park\\n例）the letter written in English ＝ the letter which was written in English\\n分詞は「関係代名詞＋be動詞」を省いた形と見ることもできる。この見方ができると、両方をまとめて理解できる。\\n\\n★ ポイント：名詞が出てきたら、その直後に to＋原形・〜ing・過去分詞・who/which/that・主語 のどれかが来ていないかを確認する。\"},{\"heading\":\"文の骨組みを取り出す\",\"body\":\"長い文を読むときは、まず文の骨組み（主語と動詞）を取り出す。\\n\\n例）The students who study English every day can speak it well.\\n　主語：The students who study English every day\\n　動詞：can speak\\n　訳：毎日英語を勉強する生徒たちは、それを上手に話すことができる。\\n\\n例）The book my father gave me for my birthday is very useful.\\n　主語：The book my father gave me for my birthday\\n　動詞：is\\n　訳：父が誕生日にくれた本はとても役に立つ。\\n\\n例）The girl standing at the gate with a red bag is my cousin.\\n　主語：The girl standing at the gate with a red bag\\n　動詞：is\\n　訳：赤いかばんを持って門のところに立っている女の子はわたしのいとこだ。\\n\\n■ 手順のまとめ\\n①文の先頭の名詞をさがす\\n②その直後から説明が始まっていないか確認する\\n③説明のかたまりが終わったところに出てくる動詞が、文全体の動詞\\n④骨組みだけを先に訳し、あとから説明を組みこむ\\n\\n⚠ 注意：説明のかたまりの中にある動詞（study・gave・standing）を文全体の動詞とまちがえると、訳が根本から狂う。動詞が複数あるときは、必ずどれが骨組みかを決めてから訳す。\",\"figureId\":\"xf_eigo_s334\",\"mangaId\":\"eigo_s334_xm\"}],\"trapExamples\":[{\"question\":\"文全体の動詞はどれか。The man who lives next to us works at a bank.\",\"wrongAnswer\":\"lives\",\"trapExplanation\":\"主語のすぐあとに出てくる動詞を、文全体の動詞だと思いこんでしまう。who から始まる説明のかたまりの中の動詞であることを見落としている。\",\"correctAnswer\":\"works\",\"correctExplanation\":\"who lives next to us は The man を説明するかたまりで、その中の動詞が lives である。説明が終わったあとに出てくる works が文全体の動詞になる。訳は「わたしたちのとなりに住んでいる男の人は銀行で働いている」。\"},{\"question\":\"日本語に直しなさい。The pictures he took in Australia were beautiful.\",\"wrongAnswer\":\"その写真は彼をオーストラリアで撮り、美しかった。\",\"trapExplanation\":\"The pictures を主語、took を文の動詞と読んでしまう。名詞のすぐあとに he という別の主語が来ていることに気づいていない。\",\"correctAnswer\":\"彼がオーストラリアでとった写真は美しかった。\",\"correctExplanation\":\"The pictures のあとに he という主語が続いているので、ここに目的格の関係代名詞が省略されている。主語は The pictures he took in Australia、文の動詞は were である。were が複数形になっていることも、主語が The pictures であることの手がかりになる。\"}]}",
"{\"id\":\"eigo_s335\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係副詞①：where（場所）と when（時）\",\"description\":\"場所や時を表す名詞を説明する where・when の使い方を学ぶ\",\"intro\":\"This is the house where he lived. の where を which に変えると誤りになります。lived は目的語を必要としない動詞で、うしろの文には抜けがないからです。「穴」があるかないかで、関係代名詞と関係副詞が分かれます。\",\"order\":835,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"先行詞が場所（place・town・house）なら where を使う。\",\"先行詞が時（day・time・year）なら when を使う。\",\"where・when のあとには、主語も目的語もそろった完全な文が来る。\",\"関係代名詞のあとは不完全な文、関係副詞のあとは完全な文、という点で区別する。\",\"the place where I was born（わたしが生まれた場所）／the day when we met（出会った日）。\"],\"sections\":[{\"heading\":\"where と when の使い方\",\"body\":\"場所や時を表す名詞を説明するときは、関係副詞 where・when を使う。\\n\\n■ where（場所）\\n例）This is the house where I was born.（これはわたしが生まれた家だ）\\n例）I want to visit the town where my grandmother lives.（祖母が住んでいる町を訪れたい）\\n例）The park where we played is near the station.（わたしたちが遊んだ公園は駅の近くだ）\\n\\n■ when（時）\\n例）I remember the day when we first met.（わたしたちが初めて会った日を覚えている）\\n例）Spring is the season when many flowers bloom.（春は多くの花がさく季節だ）\\n例）Sunday is the day when I can relax.（日曜日はゆっくりできる日だ）\\n\\n■ 二つの文から作る\\n　This is the house.（これはその家だ）\\n　I was born in it.（わたしはそこで生まれた）\\n　→ in it をまとめて where にする\\n　→ This is the house where I was born.\\n\\n★ ポイント：where・when は「前置詞＋関係代名詞」をまとめた形だと考えるとよい。だから、あとに続く文には前置詞も目的語も残らず、完全な形になる。\",\"figureId\":\"lf_eigoext09_335\"},{\"heading\":\"関係代名詞との区別\",\"body\":\"where・when を使うか、which・that を使うかは、あとに続く文が完全かどうかで決まる。\\n\\n■ あとが不完全な文 → 関係代名詞\\n例）This is the house which my father built.（父が建てた家だ）\\n　built の目的語が欠けている（不完全）→ which\\n\\n■ あとが完全な文 → 関係副詞\\n例）This is the house where my father lives.（父が住んでいる家だ）\\n　lives は目的語を必要としない（完全）→ where\\n\\n同じ the house が先行詞でも、あとの文の形によって使う語が変わる。\\n\\n■ 練習\\n例）I know the town (　) is famous for its castle.\\n　is famous 〜 は主語が欠けている → which（関係代名詞）\\n例）I know the town (　) my uncle lives.\\n　my uncle lives は完全な文 → where（関係副詞）\\n\\n■ why と how\\n例）This is the reason why he was late.（これが彼が遅れた理由だ）\\n例）This is how he solved the problem.（これが彼の問題の解き方だ）\\nwhy は先行詞 the reason とともに使い、how は先行詞なしで「〜する方法」を表す。上位校では出題されることがある。\\n\\n⚠ 注意：関係副詞のあとの文には、場所や時を表す語（there・then）を残してはいけない。This is the house where I was born there. は誤りである。\",\"mangaId\":\"eigo_s335_xm\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。This is the school (　) my mother studied.\",\"wrongAnswer\":\"which\",\"trapExplanation\":\"先行詞が the school というものなので which を選んでしまう。あとに続く my mother studied が完全な文であることを確かめていない。\",\"correctAnswer\":\"where\",\"correctExplanation\":\"my mother studied は主語も動詞もそろった完全な文なので、関係代名詞は入らない。「母が勉強した学校」＝場所を表すので関係副詞 where を使う。which を使うなら This is the school which my mother built.（母が建てた学校）のように、目的語の欠けた文が続く。\"},{\"question\":\"誤りを直しなさい。I will never forget the day when we met on that day.\",\"wrongAnswer\":\"when we met on that day のままでよい\",\"trapExplanation\":\"「その日に会った」という日本語をそのまま英語にしようとして、when を使ったうえに on that day も書いてしまう。同じ内容を二回言っていることに気づいていない。\",\"correctAnswer\":\"I will never forget the day when we met.\",\"correctExplanation\":\"when がすでに「その日に」という意味を含んでいるので、on that day は不要である。関係副詞のあとの文からは、時や場所を表す語句を取りのぞいて完全な文にする。同じ理由で where 〜 there も誤りになる。\"}]}",
"{\"id\":\"eigo_s336\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"関係詞の総合：どれを入れるかの手順\",\"description\":\"関係代名詞・関係副詞の選択を、三段階の手順で確実にする\",\"intro\":\"入試では空所に who・which・that・where・when のどれを入れるかが問われます。当てずっぽうではなく、先行詞は何か、うしろの文は完全か——この二つを順に確かめれば必ず一つに決まります。その手順を固めます。\",\"order\":836,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"手順①：先行詞は人か、もの・動物か、場所か、時か。\",\"手順②：あとに続く文は完全か、不完全か。\",\"手順③：不完全なら関係代名詞、完全なら関係副詞。\",\"不完全な文のうち、主語が欠けていれば主格、目的語が欠けていれば目的格。\",\"目的格なら省略できる、というところまで一続きで確認する。\"],\"sections\":[{\"heading\":\"三段階の判別手順\",\"body\":\"関係詞の選択問題は、次の手順で必ず解ける。\\n\\n■ 手順① 先行詞の種類を見る\\n人 → who／whom／that\\nもの・動物 → which／that\\n場所 → where（ただし完全な文が続くとき）\\n時 → when（ただし完全な文が続くとき）\\n\\n■ 手順② あとの文が完全か不完全かを見る\\n主語が欠けている → 主格の関係代名詞\\n目的語が欠けている → 目的格の関係代名詞\\nどこも欠けていない → 関係副詞\\n\\n■ 手順③ 当てはめる\\n例）I have a friend (　) can play the guitar.\\n　先行詞は人、あとは can play で主語が欠けている → who（主格）\\n例）The bag (　) I bought yesterday is red.\\n　先行詞はもの、あとは I bought で目的語が欠けている → which（目的格・省略可）\\n例）This is the room (　) we have lunch.\\n　先行詞は場所、we have lunch は完全 → where\\n\\n★ ポイント：まず「あとの文に欠けているところがあるか」を見る。ここを見れば、関係代名詞と関係副詞をまちがえることはない。\"},{\"heading\":\"二文を一文にまとめる練習\",\"body\":\"記述問題では、二つの文を一つにまとめさせる形がよく出る。\\n\\n例）I know a girl. She lives in Kobe.\\n　共通する語：a girl ＝ She（主語）→ 主格 who\\n　→ I know a girl who lives in Kobe.\\n\\n例）This is the camera. My father bought it last year.\\n　共通する語：the camera ＝ it（目的語）→ 目的格 which\\n　→ This is the camera which my father bought last year.\\n　（省略して This is the camera my father bought last year. でもよい）\\n\\n例）I visited the city. My aunt lives there.\\n　共通する語：the city ＝ there（場所を表す副詞）→ 関係副詞 where\\n　→ I visited the city where my aunt lives.\\n\\n■ 手順のまとめ\\n①二文に共通する語を見つける\\n②あとの文でその語がどんなはたらきをしているかを見る（主語・目的語・場所や時を表す副詞）\\n③主語なら主格、目的語なら目的格、副詞なら関係副詞\\n④関係詞を先行詞のすぐ後ろに置き、あとの文からもとの語を消す\\n\\n⚠ 注意：もとの語（She・it・there）を消し忘れるのが最も多いミスである。関係詞に置きかえた語は必ず消す。\"},{\"heading\":\"なぜ「あとの文が完全か」で関係代名詞と関係副詞が分かれるのか\",\"mangaId\":\"eigo_s336_manga\",\"body\":\"関係代名詞（who・which・that）は、もとの文の**主語や目的語だった名詞**を置きかえた語です。だから関係代名詞のあとの文には、主語か目的語が欠けています（can play the guitar には主語がない）。関係副詞（where・when）は、もとの文の**there・then のような副詞**を置きかえた語なので、あとの文には主語も目的語もそろっています（we have lunch は完全）。つまり「あとの文に欠けた所があるか」を見れば、どちらの仲間かが決まり、欠けているのが主語なら主格、目的語なら目的格と分かります。\\n\\n二文を一文にするときに、もとの語（She・it・there）を消し忘れる誤りが多いのは、関係詞が**その語の代わり**になっていることを意識していないからです。関係詞を置いたら、置きかえた語は必ず消します。前置詞が残る場合（play in it→which I often play in）は in を文末に残すか、in it をまとめて where にします。\\n\\n■ 確かめのしかた\\n①**先行詞の種類**：人→who／that、もの→which／that、場所→where、時→when。\\n②**あとの文が完全か**：主語が欠けている→主格、目的語が欠けている→目的格、欠けていない→関係副詞。the day (　) I first met her→完全→when。\\n③二文を一文にするときは、共通する語を見つけ、あとの文でのはたらき（主語・目的語・副詞）を見て、関係詞に置きかえ、**もとの語を消す**。\\n④目的格は省略できる。目的格かどうかを確かめてから省略する。\\n\\n★ ここがポイント：関係代名詞は**名詞の代わり**なのであとの文が不完全、関係副詞は**副詞の代わり**なのであとの文が完全。**先行詞→あとの文が完全か**の順に見て、置きかえた語は必ず消す。\",\"figureId\":\"xf_eigo_s336\"}],\"trapExamples\":[{\"question\":\"二つの文を一つにしなさい。This is the park. I often play in it.\",\"wrongAnswer\":\"This is the park which I often play in it.\",\"trapExplanation\":\"it を which に置きかえて前に出したあと、もとの it を消し忘れてしまう。前置詞 in が残ることにも気づきにくい。\",\"correctAnswer\":\"This is the park which I often play in.（または This is the park where I often play.）\",\"correctExplanation\":\"it を which に変えて先行詞のすぐ後ろに置いたら、もとの it は消す。前置詞 in は文末に残る。in it をまとめて where にすれば This is the park where I often play. となり、こちらの方が自然である。\"},{\"question\":\"（　）に適する語を入れなさい。I remember the day (　) I first met her.\",\"wrongAnswer\":\"which\",\"trapExplanation\":\"先行詞 the day を「もの」と考えて which を選んでしまう。あとの I first met her に何も欠けていないことを確かめていない。\",\"correctAnswer\":\"when\",\"correctExplanation\":\"I first met her は主語も目的語もそろった完全な文なので、関係代名詞は入らない。先行詞が the day という時を表す語なので関係副詞 when を使う。「あとの文が完全かどうか」を必ず先に確認する。\"}]}",
"{\"id\":\"eigo_s337\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"受動態①：be動詞＋過去分詞と語順の入れかえ\",\"description\":\"能動態から受動態への書きかえを、語順の動きとしてつかむ\",\"intro\":\"「この写真はケンがとった」と「この写真はケンによってとられた」。同じ出来事でも、話の主役をどちらにするかで文の形が変わります。主役を入れかえるための道具が受動態です。語順がどう動くのかを、矢印で追いかけます。\",\"order\":837,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"受動態＝be動詞＋過去分詞。「〜される」「〜された」という意味。\",\"能動態の目的語が受動態の主語になり、能動態の主語は by 〜 として文末へ回る。\",\"be動詞は新しい主語の人称・数と、もとの文の時制に合わせる。\",\"Tom broke the window. → The window was broken by Tom.\",\"目的語のない文（go・come・run など）は受動態にできない。\"],\"sections\":[{\"heading\":\"語順が入れかわるしくみ\",\"mangaId\":\"eigo_s337_manga\",\"body\":\"受動態は「〜される」という言い方で、be動詞＋過去分詞で作る。\\n\\n例）Tom broke the window.（トムが窓をこわした）… 能動態\\n　→ The window was broken by Tom.（窓はトムによってこわされた）… 受動態\\n\\n■ 書きかえの三つの手順\\n①能動態の目的語（the window）を、受動態の主語にする\\n②動詞を「be動詞＋過去分詞」にする。be動詞はもとの文の時制と新しい主語に合わせる（過去＋単数 → was）\\n③能動態の主語（Tom）を by のあとに置き、文末に回す\\n\\n■ もっと例を見る\\n例）Many people love this song.\\n　→ This song is loved by many people.（この歌は多くの人に愛されている）\\n例）My mother made this cake.\\n　→ This cake was made by my mother.（このケーキは母によって作られた）\\n例）They speak English in Australia.\\n　→ English is spoken in Australia.（オーストラリアでは英語が話されている）\\n\\n■ by のあとは目的格\\n例）She helped me. → I was helped by her.\\nby のあとの代名詞は目的格にする（she → her）。\\n\\n★ ポイント：主語と目的語が入れかわり、動詞が be動詞＋過去分詞になる。この二つの動きを図でつかむ。\",\"figureId\":\"lf_eigoext09_337\"},{\"heading\":\"受動態にできない文\",\"body\":\"受動態を作るには、能動態に目的語がなければならない。目的語をとらない動詞は受動態にできない。\\n\\n■ 受動態にできない動詞の例\\ngo（行く）／come（来る）／run（走る）／sleep（眠る）／happen（起こる）／arrive（到着する）\\n例）He goes to school. → He is gone to school.（×）\\n「学校へ行かれる」という文は作れない。\\n\\n■ be動詞の形を決める二つの条件\\n①もとの文の時制（現在か過去か）\\n②新しい主語の人称と数\\n例）They clean the rooms every day.\\n　→ The rooms are cleaned every day.（現在・複数 → are）\\n例）He wrote these letters.\\n　→ These letters were written by him.（過去・複数 → were）\\n\\n■ 過去分詞を正しく使う\\n不規則動詞は必ず覚える。\\nwrite－wrote－written／speak－spoke－spoken／break－broke－broken／take－took－taken／build－built－built／make－made－made／see－saw－seen／know－knew－known／give－gave－given／eat－ate－eaten\\n\\n⚠ 注意：受動態の動詞部分に過去形を使うのは誤り。The window was broke by Tom. ではなく was broken である。過去形と過去分詞のちがいを必ず確認する。\"}],\"trapExamples\":[{\"question\":\"受動態に書きかえなさい。My brother washed the car yesterday.\",\"wrongAnswer\":\"The car is washed by my brother yesterday.\",\"trapExplanation\":\"受動態の be動詞をいつも is・are にしてしまい、もとの文が過去（washed）であることを反映させ忘れる。yesterday という語があっても気づかない。\",\"correctAnswer\":\"The car was washed by my brother yesterday.\",\"correctExplanation\":\"受動態の be動詞は、もとの文の時制と新しい主語に合わせる。もとが過去で、新しい主語 The car が単数なので was を使う。時制は動詞の過去分詞ではなく be動詞で示すことを覚えておく。\"},{\"question\":\"誤りを直しなさい。The window was broke by the boy.\",\"wrongAnswer\":\"was broke のままでよい\",\"trapExplanation\":\"過去のことだから過去形 broke を使えばよいと考えてしまう。be動詞のあとに来るのは過去分詞であることが抜けている。\",\"correctAnswer\":\"The window was broken by the boy.\",\"correctExplanation\":\"受動態は「be動詞＋過去分詞」で作る。break の変化は break－broke－broken なので、過去分詞は broken である。時を表すのは was の方なので、broke を重ねる必要はない。不規則動詞は三つの形をセットで暗記する。\"}]}",
"{\"id\":\"eigo_s338\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"受動態②：by の省略と、覚えるべき過去分詞\",\"description\":\"by 〜 を省く場合を知り、不規則動詞の過去分詞を確実にする\",\"intro\":\"English is spoken in many countries. には、だれが話すのかが書かれていません。「人々によって」はわざわざ言うまでもないからです。受動態は、する人よりされるものに目を向けたいときに選ばれます。あわせて過去分詞を確実にします。\",\"order\":838,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"だれがしたか言う必要がないときは by 〜 を省く。\",\"English is spoken in many countries.（by people は書かない）\",\"受動態は「する人」より「されるもの」に注目したいときに使う。\",\"不規則動詞の過去分詞（written・spoken・broken・taken・known・built）は必ず暗記。\",\"規則動詞は過去形と過去分詞が同じ形（used・cleaned・visited）。\"],\"sections\":[{\"heading\":\"by 〜 を省くとき\",\"body\":\"受動態では、by のあとの語を書かないことの方が多い。次の場合は省くのがふつうである。\\n\\n■ ①だれがするか明らかなとき\\n例）This school was built in 1950.（この学校は1950年に建てられた）\\n建てたのは建設業者だが、言う必要がない。\\n\\n■ ②だれがするか一般的すぎるとき\\n例）English is spoken in many countries.（英語は多くの国で話されている）\\nby people と書く必要はない。\\n\\n■ ③だれがしたかわからないとき\\n例）My bike was stolen last night.（昨夜、自転車がぬすまれた）\\nぬすんだ人がわからないので by は書けない。\\n\\n■ 受動態を使う理由\\n受動態は「する人」よりも「されるもの」に話の中心を置きたいときに使う。だから by 〜 は必要なときだけ書き加える。\\n\\n例）This picture was painted by Picasso.（ピカソによってかかれた）… だれがかいたかが大事なので by が必要\\n例）This temple was built 400 years ago.（400年前に建てられた）… だれが建てたかは重要でないので by なし\\n\\n★ ポイント：入試の英作文では、by 〜 を書くかどうか迷ったら「その情報が大事かどうか」で判断する。\",\"mangaId\":\"eigo_s338_xm\"},{\"heading\":\"過去分詞の暗記\",\"body\":\"受動態を書くには、過去分詞を正確に覚えている必要がある。\\n\\n■ 規則動詞（過去形と過去分詞が同じ）\\nplay－played－played／use－used－used／clean－cleaned－cleaned／visit－visited－visited／invite－invited－invited／call－called－called\\n\\n■ 不規則動詞（三つとも形がちがう）\\nwrite－wrote－written（書く）\\nspeak－spoke－spoken（話す）\\nbreak－broke－broken（こわす）\\ntake－took－taken（とる）\\ngive－gave－given（あたえる）\\nknow－knew－known（知っている）\\nsee－saw－seen（見る）\\neat－ate－eaten（食べる）\\nsing－sang－sung（歌う）\\ndrive－drove－driven（運転する）\\n\\n■ 不規則動詞（過去形と過去分詞が同じ）\\nbuild－built－built（建てる）／make－made－made（作る）／teach－taught－taught（教える）／buy－bought－bought（買う）／find－found－found（見つける）／send－sent－sent（送る）\\n\\n■ 原形・過去形・過去分詞が全部同じ\\nput－put－put（置く）／cut－cut－cut（切る）／read－read－read（読む・発音は過去形と過去分詞がレッド）\\n\\n⚠ 注意：受動態の文で過去形を使ってしまうミスが非常に多い。「be動詞のあとは必ず過去分詞」と唱えて確認する。\",\"figureId\":\"xf_eigo_s338\"}],\"trapExamples\":[{\"question\":\"受動態に書きかえなさい。People speak English in Canada.\",\"wrongAnswer\":\"English is spoken by people in Canada.\",\"trapExplanation\":\"受動態には必ず by 〜 が必要だと思いこみ、書かなくてよい by people をわざわざ書いてしまう。文としては通じるが不自然である。\",\"correctAnswer\":\"English is spoken in Canada.\",\"correctExplanation\":\"主語が people のように「一般の人々」を表すときは、by 〜 を省くのがふつうである。だれが話すかは明らかで、情報として意味がないからである。同じ理由で They sell books here. → Books are sold here. のように by them も書かない。\"},{\"question\":\"（　）内を適する形にしなさい。These pictures were (take) by my father.\",\"wrongAnswer\":\"took\",\"trapExplanation\":\"「とった」という過去の意味から過去形 took を選んでしまう。be動詞 were がすでに過去を示していることに気づいていない。\",\"correctAnswer\":\"taken\",\"correctExplanation\":\"受動態は「be動詞＋過去分詞」なので、be動詞のあとには過去分詞が来る。take－took－taken なので taken が正しい。時を表すのは were の方であり、過去分詞は時制を表さない。\"}]}",
"{\"id\":\"eigo_s339\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"受動態③：時制・否定文・疑問文\",\"description\":\"受動態の否定文・疑問文の作り方と、助動詞との組み合わせをおさえる\",\"intro\":\"受動態は be動詞＋過去分詞なので、否定文も疑問文も be動詞の文とまったく同じ作り方で片づきます。not は be動詞のあと、疑問文は be動詞を主語の前に出すだけです。新しく覚えることは、実はほとんどありません。\",\"order\":839,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"否定文は be動詞のあとに not を置く（is not made／was not written）。\",\"疑問文は be動詞を主語の前に出す（Is this made in Japan?）。\",\"答えるときも be動詞を使う（Yes, it is. / No, it isn't.）。\",\"助動詞があるときは「助動詞＋be＋過去分詞」（will be sold／can be seen）。\",\"疑問詞で始まる受動態の疑問文（When was it built?）も頻出。\"],\"sections\":[{\"heading\":\"否定文と疑問文の作り方\",\"body\":\"受動態はbe動詞の文なので、否定文・疑問文の作り方もbe動詞の文と同じである。\\n\\n■ 否定文：be動詞のあとに not\\n例）This book is not read by young people.（この本は若い人には読まれていない）\\n例）The letter was not written in English.（その手紙は英語で書かれていなかった）\\n短縮形は isn't・wasn't・aren't・weren't を使う。\\n\\n■ 疑問文：be動詞を主語の前に出す\\n例）Is this car made in Japan?（この車は日本で作られていますか）\\n　— Yes, it is. / No, it isn't.\\n例）Was this picture painted by Monet?（この絵はモネによってかかれましたか）\\n　— Yes, it was. / No, it wasn't.\\n\\n■ do・does・did は使わない\\n例）Does this car made in Japan?（×）\\n受動態は be動詞の文なので、do・does・did は登場しない。ここは入試で必ずねらわれる。\\n\\n■ 疑問詞で始まる疑問文\\n例）When was this temple built?（この寺はいつ建てられましたか）\\n例）Where is rice grown in Japan?（日本ではどこで米が作られていますか）\\n例）By whom was this book written?（この本はだれによって書かれましたか）\\n最後の形はかたい言い方で、ふつうは Who was this book written by? と言う。\\n\\n★ ポイント：受動態の文を見たら「be動詞の文」と考える。否定も疑問も be動詞のルールどおりに処理する。\"},{\"heading\":\"助動詞のある受動態と未来の受動態\",\"mangaId\":\"eigo_s339_manga\",\"body\":\"助動詞といっしょに使うときは、「助動詞＋be＋過去分詞」の形になる。助動詞のあとは必ず原形なので、be動詞は be の形になる。\\n\\n例）This song will be sung at the concert.（この歌はコンサートで歌われるだろう）\\n例）Mt. Fuji can be seen from here.（ここから富士山が見える＝見られる）\\n例）The homework must be finished by tomorrow.（宿題は明日までに終えられなければならない）\\n例）This room should be cleaned every day.（この部屋は毎日そうじされるべきだ）\\n\\n■ 否定文・疑問文\\n例）This song will not be sung at the concert.\\n例）Can Mt. Fuji be seen from here? — Yes, it can.\\n助動詞のあとに not を置き、疑問文では助動詞を主語の前に出す。\\n\\n■ 進行形の受動態は中学範囲外\\n「〜されているところだ」（is being built）は高校で学ぶ形なので、中学受験では覚えなくてよい。\\n\\n■ 現在完了の受動態\\n例）This book has been read by many people.（この本は多くの人に読まれてきた）\\n上位校の長文では出てくることがあるので、形だけ知っておくとよい。\\n\\n⚠ 注意：will is sold・can is seen のように、助動詞のあとに is を置くのは誤り。助動詞のあとは必ず原形の be である。\",\"figureId\":\"xf_eigo_s339\"}],\"trapExamples\":[{\"question\":\"疑問文にしなさい。This computer is used by many students.\",\"wrongAnswer\":\"Does this computer used by many students?\",\"trapExplanation\":\"一般動詞の文の疑問文の作り方（do・does を使う）を当てはめてしまう。used という語の見た目から一般動詞の文だと錯覚するのが原因である。\",\"correctAnswer\":\"Is this computer used by many students?\",\"correctExplanation\":\"受動態は be動詞の文なので、疑問文では be動詞（is）を主語の前に出す。do・does・did は使わない。答えるときも Yes, it is. / No, it isn't. と be動詞で答える。\"},{\"question\":\"（　）に適する語を入れなさい。The concert will (　) held next Sunday.（コンサートは次の日曜に開かれる）\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"受動態は「be動詞＋過去分詞」だと覚えているため、主語に合わせて is を入れてしまう。will のあとが原形になることを忘れている。\",\"correctAnswer\":\"be\",\"correctExplanation\":\"助動詞 will のあとは必ず動詞の原形なので、be動詞は原形の be になる。「助動詞＋be＋過去分詞」が受動態と助動詞を組み合わせた形である。can be seen、must be finished も同じ形である。\"}]}",
"{\"id\":\"eigo_s340\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"受動態④：by 以外の前置詞を使う表現\",\"description\":\"be interested in など、by を使わない受動態の決まり文句を覚える\",\"intro\":\"「わたしは音楽に興味があります」は I am interested by music. ではなく in music です。受動態の形なのに by を使わない表現がいくつもあり、しかも入試でよく問われます。前置詞ごとにまとめて覚えてしまいましょう。\",\"order\":840,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"be interested in 〜（〜に興味がある）／be surprised at 〜（〜に驚く）。\",\"be covered with 〜（〜でおおわれている）／be filled with 〜（〜でいっぱいだ）。\",\"be known to 〜（〜に知られている）／be made of 〜・be made from 〜。\",\"be made of は材料が見てわかるとき、be made from は見てわからないとき。\",\"これらは by を使わないので、前置詞ごと丸暗記する。\"],\"sections\":[{\"heading\":\"by を使わない受動態\",\"body\":\"受動態の形をしていても、by ではなく決まった前置詞を使う表現がある。丸ごと覚えてしまう。\\n\\n例）I am interested in science.（わたしは科学に興味がある）\\n例）We were surprised at the news.（わたしたちはその知らせに驚いた）\\n例）The mountain is covered with snow.（その山は雪でおおわれている）\\n例）The box was filled with old books.（その箱は古い本でいっぱいだった）\\n例）He is known to everyone in this town.（彼はこの町のみんなに知られている）\\n例）She was pleased with the present.（彼女はそのプレゼントを喜んだ）\\n\\n■ 前置詞ごと覚える\\ninterested in（興味がある）／surprised at（驚く）／covered with（おおわれている）／filled with（いっぱいだ）／known to（知られている）／pleased with（喜ぶ）／satisfied with（満足する）／worried about（心配する）\\n\\n■ 感情を表すものが多い\\n「驚かされる」「喜ばされる」というように、日本語では能動的に感じるものが英語では受け身の形になる。日本語との感覚のちがいに注意する。\\n\\n★ ポイント：be動詞＋過去分詞＋前置詞を、三語まとめて声に出して覚える。前置詞だけを答えさせる出題が非常に多い。\"},{\"heading\":\"be made of と be made from\",\"body\":\"「〜で作られている」を表す言い方は、材料が見た目でわかるかどうかで使い分ける。\\n\\n■ be made of：材料の形が残っている（見ればわかる）\\n例）This desk is made of wood.（この机は木で作られている）\\n例）The bag is made of leather.（そのかばんは革で作られている）\\n\\n■ be made from：材料の形が変わっている（見てもわからない）\\n例）Wine is made from grapes.（ワインはぶどうから作られる）\\n例）Cheese is made from milk.（チーズは牛乳から作られる）\\n例）Paper is made from wood.（紙は木から作られる）\\n\\n同じ木でも、机なら見て木とわかるので of、紙は見ても木とわからないので from を使う。\\n\\n■ be made into：材料を主語にする言い方\\n例）Grapes are made into wine.（ぶどうはワインに加工される）\\n「材料 → 製品」の向きで言うときは into を使う。\\n\\n■ be made in：産地\\n例）This car was made in Japan.（この車は日本で作られた）\\n場所を表すときは in である。\\n\\n⚠ 注意：of・from・into・in の四つはすべて出題される。「見てわかる＝of」「変化している＝from」「材料が主語＝into」「場所＝in」と整理して覚える。\",\"figureId\":\"xf_eigo_s340\",\"mangaId\":\"eigo_s340_xm\"}],\"trapExamples\":[{\"question\":\"（　）に適する語を入れなさい。The top of the mountain was covered (　) snow.\",\"wrongAnswer\":\"by\",\"trapExplanation\":\"受動態には by を使うと覚えているため、前置詞を考えずに by を入れてしまう。covered with が決まった形であることを知らない。\",\"correctAnswer\":\"with\",\"correctExplanation\":\"be covered with 〜（〜でおおわれている）は by を使わない受動態の決まり文句である。同じ仲間に be filled with（〜でいっぱいだ）、be pleased with（〜を喜ぶ）がある。「be動詞＋過去分詞＋前置詞」を三語セットで覚えることが唯一の対策である。\"},{\"question\":\"（　）に of か from を入れなさい。Butter is made (　) milk.\",\"wrongAnswer\":\"of\",\"trapExplanation\":\"「〜で作られる」＝be made of と一つだけ覚えていると、材料が見てわかるかどうかを考えずに of を選んでしまう。\",\"correctAnswer\":\"from\",\"correctExplanation\":\"バターを見ても牛乳の形は残っていない。このように材料が姿を変えているときは be made from を使う。木で作った机（This desk is made of wood.）のように、見て材料がわかるときは be made of である。\"}]}",
"{\"id\":\"eigo_s341\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"身のまわりの語彙①：家族を表す語\",\"description\":\"家族を表す英単語と、日本語の「兄・弟・姉・妹」を英語でどう言い分けるかを身につける\",\"intro\":\"「兄」と「弟」を英語でどう言い分けるでしょうか。実は brother の一語しかありません。英語は上下より、男か女かのほうを大事にする言語だからです。どうしても年上と言いたいときの言い方も含めて、家族の語をまとめて覚えます。\",\"order\":841,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"father（父）／mother（母）／parents（両親）／brother（兄弟）／sister（姉妹）が土台。\",\"英語の brother・sister には年上・年下の区別がない。年齢を言いたいときは older / younger を付ける。\",\"grandfather・grandmother は「祖父・祖母」、uncle は「おじ」、aunt は「おば」、cousin は「いとこ」。\",\"parents・grandparents は必ず複数形。These are my parents. のように主語も複数で受ける。\",\"呼びかけには Dad / Mom を使い、大文字で書く（人の名前のあつかい）。\",\"「家族は何人ですか」は How many people are there in your family? が定番。\"],\"sections\":[{\"heading\":\"家族を表す基本の単語\",\"body\":\"家族の語は英検5級・4級で必ず出る、いちばん基本的な語彙のまとまりである。まず次の語を確実に書けるようにする。\\n\\n■ 直接の家族\\nfather（父）／mother（母）／parents（両親）／brother（兄・弟）／sister（姉・妹）／son（息子）／daughter（娘）／husband（夫）／wife（妻）／baby（赤ちゃん）\\n\\n■ 親せき\\ngrandfather（祖父）／grandmother（祖母）／grandparents（祖父母）／uncle（おじ）／aunt（おば）／cousin（いとこ）／nephew（おい）／niece（めい）\\n\\n■ まとめて言う語\\nfamily（家族）／relative（親せき）\\n\\n例）I have two brothers and one sister.（私には兄弟が二人、姉妹が一人います。）\\n例）My grandmother lives in Osaka.（祖母は大阪に住んでいます。）\\n\\n★ ポイント：parents と grandparents は「二人以上」を指すので、いつも複数形で使い、動詞も複数に合わせる。My parents are teachers.（× My parents is …）\\n\\n⚠ 注意：つづりをまちがえやすい語が多い。daughter の gh、cousin の ou、niece の ie は書いて覚える。aunt は「アント」と読み、ant（アリ）とつづりも意味もちがう。\",\"figureId\":\"lf_eigoext10_341\"},{\"heading\":\"「兄」と「弟」、「姉」と「妹」の言い分け\",\"body\":\"日本語は「兄／弟」「姉／妹」を必ず区別するが、英語の brother・sister には年上・年下の区別がない。ここが日本人にとって最大のつまずきどころである。\\n\\n■ 年齢をはっきり言いたいとき\\nolder brother（兄）／younger brother（弟）／older sister（姉）／younger sister（妹）\\nくだけた言い方では big brother（兄）／little sister（妹）も使う。\\n\\n例）I have an older brother.（私には兄が一人います。）\\n例）My younger sister is six years old.（妹は6歳です。）\\n\\n■ 英文を日本語にするときの読み取り\\n英文に older・younger が付いていなければ、年上か年下かは文脈から判断する。\\n例）I have a brother. He is five years old.\\n　→ 話し手は小学生なので、この brother は「弟」と訳すのが自然。\\n逆に、日本語を英語にするときに「兄」を単に brother と書いても、英語としてはまちがいではない。ただし「兄が一人います」と年上であることを問う問題では older brother と書くほうが安全である。\\n\\n★ ポイント：an older brother の an を忘れない。older は母音で始まるので a ではなく an になる。\",\"mangaId\":\"eigo_s341_xm\"},{\"heading\":\"家族について話す会話表現\",\"body\":\"家族の語は、次の決まり文句とセットで覚えると入試でそのまま使える。\\n\\n■ 人数をたずねる\\nHow many people are there in your family?（ご家族は何人ですか。）\\n— There are four people in my family.（4人です。）\\n— We are a family of four. という言い方もある。\\n\\n■ 家族を紹介する\\nThis is my mother.（こちらは私の母です。）\\nThese are my parents.（こちらは私の両親です。）\\n※ 紹介するときは He is … ではなく This is … を使うのがふつう。\\n\\n■ 家族についてたずねる\\nDo you have any brothers or sisters?（兄弟姉妹はいますか。）\\n— Yes, I have one sister.／— No, I don't. I'm an only child.（いいえ、一人っ子です。）\\nWhat does your father do?（お父さんの仕事は何ですか。）\\n— He is a doctor.\\n\\n★ ポイント：所有格 my / your / his / her / our / their を正しく選ぶ。Ken and his sister（ケンと彼の姉）／Aya and her mother（アヤと彼女の母）のように、直前の人物に合わせる。\"}],\"trapExamples\":[{\"question\":\"「こちらは私の両親です。」を英語にしなさい。\",\"wrongAnswer\":\"This is my parents.\",\"trapExplanation\":\"日本語が「こちらは」と一つのまとまりで始まるので、そのまま This is で書き出してしまう。日本語には単数・複数の区別がないため、主語が二人であることを見落とす。\",\"correctAnswer\":\"These are my parents.\",\"correctExplanation\":\"parents は「父と母の二人」を指す複数の語なので、指し示す語も these、be動詞も are にする。同じように These are my grandparents. も複数で受ける。一人なら This is my father. と単数にする。\"},{\"question\":\"次の英文の brother を日本語にしなさい。 I have a brother. He is five years old.\",\"wrongAnswer\":\"兄\",\"trapExplanation\":\"brother を機械的に「兄」と覚えているため、文の後半の年齢の情報を読まずに訳してしまう。日本語では年上・年下を必ず区別するのに、英語では区別しないという感覚のちがいが原因。\",\"correctAnswer\":\"弟\",\"correctExplanation\":\"英語の brother は年上・年下の両方を指す語で、どちらかは文脈で決まる。ここでは「5歳」とあり、話し手（小学生）より年下と考えられるので「弟」と訳す。年上・年下をはっきり示したいときは older brother / younger brother と書く。\"}]}",
"{\"id\":\"eigo_s342\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"身のまわりの語彙②：体の部分を表す語\",\"description\":\"顔・体の各部を表す語と、二つで一組の部分・不規則な複数形を整理する\",\"intro\":\"「歯がいたい」と言うとき、tooth と teeth のどちらを使うか迷ったことはありませんか。目・耳・手・足のように二つそろっている部分は、ふつう複数形で使います。しかも tooth は teeth、foot は feet と形が不規則に変わります。\",\"order\":842,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"head（頭）・face（顔）・eye（目）・ear（耳）・nose（鼻）・mouth（口）が顔の基本語。\",\"目・耳・手・足のように二つある部分は、ふつう複数形で使う（eyes, ears, hands, feet）。\",\"不規則な複数形に注意：tooth → teeth、foot → feet。\",\"hair（髪）は数えず、いつも単数あつかい。Her hair is long.（× hairs are）\",\"体の不調は have を使う。I have a headache.（頭が痛い）／I have a cold.（かぜをひいている）\",\"体の部分には the ではなく my / your などの所有格を付けるのがふつう。Wash your hands.\"],\"sections\":[{\"heading\":\"顔と体の基本語\",\"body\":\"体の部分の語は、健康・スポーツ・道案内など多くの話題に出てくる。上から順に整理して覚える。\\n\\n■ 顔まわり\\nhead（頭）／hair（髪）／face（顔）／eye（目）／eyebrow（まゆ）／ear（耳）／nose（鼻）／mouth（口）／lip（くちびる）／tooth（歯）／tongue（舌）／neck（首）\\n\\n■ 上半身\\nshoulder（肩）／arm（うで）／elbow（ひじ）／hand（手）／finger（指）／back（背中）／chest（胸）／stomach（おなか）\\n\\n■ 下半身\\nleg（ももからくるぶしまでのあし）／knee（ひざ）／foot（足首から先）／toe（足の指）\\n\\n★ ポイント：日本語の「あし」は英語で二つに分かれる。ももからくるぶしまでが leg、くるぶしから先が foot である。「足が痛い」も、どこが痛いのかで語がちがう。\\n\\n例）I have long legs.（私は足が長い。）\\n例）My foot hurts.（足（の先）が痛い。）\\n\\n⚠ 注意：knee の k、stomach の ch は発音しない・読み方が特殊なので、書き取りでまちがえやすい。\",\"figureId\":\"lf_eigoext10_342\"},{\"heading\":\"複数形と数え方のきまり\",\"body\":\"体の部分は二つ、あるいはたくさんあるものが多いので、複数形の作り方が問われる。\\n\\n■ 不規則に変わる複数形\\ntooth（歯）→ teeth／foot（足）→ feet\\nこれは -s を付けるのではなく、語の中の母音が変わるタイプである。Brush your teeth.（歯をみがきなさい。）／My feet are cold.（足が冷たい。）\\n\\n■ ふつうに -s を付けるもの\\neye → eyes／ear → ears／hand → hands／finger → fingers／leg → legs\\n\\n■ 数えない語\\nhair は「髪の毛全体」を指すときは数えられない名詞で、いつも単数あつかいにする。\\n例）Her hair is long and black.（彼女の髪は長くて黒い。）\\n※ 1本ずつの毛を指すときだけ a hair / two hairs と数えるが、小学生の入試ではまず出ない。\\n\\n■ 二つで一組\\n目・耳・手・足について「両方」を言うときは複数形にするのが自然。\\n例）Close your eyes.（目を閉じなさい。） Wash your hands.（手を洗いなさい。）\\n\\n⚠ 注意：Close your eye. と単数にすると「片目を閉じる」という意味になってしまう。\",\"mangaId\":\"eigo_s342_xm\"},{\"heading\":\"体の調子を伝える表現\",\"body\":\"体の部分の語は、次の言い方とセットで覚えると会話問題に強くなる。\\n\\n■ have を使う言い方（いちばん多い）\\nI have a headache.（頭が痛い。）／I have a stomachache.（おなかが痛い。）／I have a toothache.（歯が痛い。）／I have a fever.（熱がある。）／I have a cold.（かぜをひいている。）\\n※ -ache は「痛み」を表す語。head + ache → headache のように組み合わさっている。\\n\\n■ hurt を使う言い方\\nMy leg hurts.（足が痛い。）／I hurt my arm.（うでをけがした。）\\n\\n■ 相手を気づかう表現\\nWhat's wrong?／What's the matter?（どうしたのですか。）\\n— I have a headache.\\nThat's too bad.（それはお気の毒に。）\\nTake care.（お大事に。）\\n\\n★ ポイント：体の部分の前には the ではなく my / your を付けるのが英語の習慣。Wash your hands.（× Wash the hands.）\"}],\"trapExamples\":[{\"question\":\"「歯をみがきなさい。」を英語にしなさい。\",\"wrongAnswer\":\"Brush your tooths.\",\"trapExplanation\":\"複数形は -s を付けると覚えているため、tooth にもそのまま -s を付けてしまう。不規則に変化する複数形であることを見落とす典型例。\",\"correctAnswer\":\"Brush your teeth.\",\"correctExplanation\":\"tooth の複数形は語中の母音が変わって teeth になる。同じ型に foot → feet がある。man → men、woman → women、child → children と合わせて、-s を付けない複数形としてまとめて覚える。\"},{\"question\":\"「彼女の髪は長い。」を英語にしなさい。\",\"wrongAnswer\":\"Her hairs are long.\",\"trapExplanation\":\"髪の毛は何本もあるから複数だ、と日本語の感覚で考えてしまう。数えられる名詞と数えられない名詞の区別が身についていないと必ず引っかかる。\",\"correctAnswer\":\"Her hair is long.\",\"correctExplanation\":\"hair は「髪全体」をひとまとまりとしてとらえる数えられない名詞なので、-s を付けず、be動詞も is にする。water・milk・bread・money なども同じ仲間である。\"}]}",
"{\"id\":\"eigo_s343\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"身のまわりの語彙③：衣服と身につけるもの\",\"description\":\"衣服の語と、wear / put on / a pair of の使い分けを身につける\",\"intro\":\"帽子はどれも hat でよさそうですが、野球帽は cap です。ふちがあるかないかで語が変わります。さらにズボンやくつは、いつも複数形。日本語の感覚のままだと数をまちがえやすい、身につけるものの語を整理します。\",\"order\":843,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"shirt・T-shirt・sweater・jacket・coat・cap・hat・shoes・socks が基本語。\",\"cap はふちのない帽子（野球帽）、hat はふちのある帽子。\",\"二本の足や手が入るものは複数形で使う：pants, shoes, socks, glasses, gloves。\",\"数えるときは a pair of shoes（くつ1足）／two pairs of socks（くつした2足）。\",\"wear は「身につけている」という状態、put on は「身につける」という動作。\",\"「〜が似合う」は look good on you、「着てみる」は try on。\"],\"sections\":[{\"heading\":\"衣服・持ち物の基本語\",\"body\":\"服装の語は、人物の描写や買い物の場面で必ず出る。\\n\\n■ 上に着るもの\\nshirt（シャツ）／T-shirt（Tシャツ）／blouse（ブラウス）／sweater（セーター）／jacket（上着）／coat（コート）／uniform（制服）\\n\\n■ 下にはくもの\\npants（ズボン）／jeans（ジーンズ）／skirt（スカート）／shorts（半ズボン）\\n\\n■ 足・頭・手\\nshoes（くつ）／socks（くつした）／boots（ブーツ）／cap（ふちのない帽子）／hat（ふちのある帽子）／gloves（手ぶくろ）\\n\\n■ 小物\\nglasses（めがね）／watch（うで時計）／bag（かばん）／umbrella（かさ）／ring（指輪）／scarf（マフラー）\\n\\n★ ポイント：cap と hat のちがいは入試でよく問われる。野球帽のように前にだけつばがあるものが cap、まわり全体につばがあるものが hat である。\\n\\n⚠ 注意：pants は日本語の「パンツ（下着）」ではなく「ズボン」を指す。下着は underwear という。\"},{\"heading\":\"a pair of と複数形\",\"body\":\"英語では、二つで一組になっているものは、一つの品物でも必ず複数形にする。\\n\\n■ いつも複数形で使う語\\nshoes（くつ）／socks（くつした）／pants（ズボン）／jeans／shorts／glasses（めがね）／gloves（手ぶくろ）／scissors（はさみ）／chopsticks（はし）\\n\\n例）My shoes are new.（私のくつは新しい。） ← is ではなく are\\n\\n■ 数えるときは a pair of\\na pair of shoes（くつ1足）／two pairs of socks（くつした2足）／a pair of glasses（めがね1つ）\\n※ pair は「対（つい）」という意味。数を増やすときは pair のほうに -s を付ける（two pairs of …）。\\n\\n例）I bought two pairs of shoes.（くつを2足買った。）\\n\\n■ 単数で使う語との比較\\nshirt・skirt・sweater・cap・bag などはふつうに a shirt / two shirts と数える。\\n\\n⚠ 注意：a pair of shoes が主語のときの動詞は、pair に合わせて単数になる。A pair of shoes is on the floor. 迷ったら「くつが1足床にある」＝一つのまとまり、と考える。\",\"figureId\":\"xf_eigo_s343\"},{\"heading\":\"wear と put on の使い分け\",\"body\":\"「着る」にあたる英語は一つではない。動作か状態かで使い分ける。\\n\\n■ wear ＝身につけている（状態）\\n例）She is wearing a red coat.（彼女は赤いコートを着ている。）\\n「今どんなかっこうか」を説明するときは wear を使う。服だけでなく、帽子・くつ・めがね・指輪・香水にも使える。\\n\\n■ put on ＝身につける（動作の瞬間）\\n例）Put on your jacket. It's cold outside.（上着を着なさい。外は寒いよ。）\\n反対の「ぬぐ」は take off。\\n例）Take off your shoes here.（ここでくつをぬいでください。）\\n\\n■ try on ＝試着する\\n例）Can I try this shirt on?（このシャツを試着してもいいですか。）\\n※ try it on のように代名詞は真ん中に入れる。try on it とは言わない。\\n\\n■ 似合う\\nThat shirt looks good on you.（そのシャツ、似合っているね。）\\n\\n★ ポイント：「今着ている」＝ be wearing、「これから着る」＝ put on。日本語ではどちらも「着る」なので、英作文では動作か状態かを必ず確かめる。\",\"mangaId\":\"eigo_s343_xm\"}],\"trapExamples\":[{\"question\":\"「私のくつは新しい。」を英語にしなさい。\",\"wrongAnswer\":\"My shoes is new.\",\"trapExplanation\":\"くつを「1足」という一つのまとまりでとらえてしまい、be動詞を単数の is にしてしまう。日本語には単数・複数の区別がないため気づきにくい。\",\"correctAnswer\":\"My shoes are new.\",\"correctExplanation\":\"shoes は左右二つで一組なので形は複数であり、動詞も are にする。数を言いたいときだけ a pair of shoes とし、その場合は A pair of shoes is new. と単数で受ける。socks・glasses・pants も同じ仲間。\"},{\"question\":\"（　）に入る語を答えなさい。 She is （　） a blue cap now.\",\"wrongAnswer\":\"putting on\",\"trapExplanation\":\"「かぶっている」を「かぶる」という動作だと考え、put on を選んでしまう。now があるので進行形にすればよいと機械的に処理するのも原因。\",\"correctAnswer\":\"wearing\",\"correctExplanation\":\"この文は「今、青い帽子をかぶっている（状態）」を表すので wear を使い、is wearing とする。putting on にすると「今まさに帽子をかぶろうとしている動作の最中」という不自然な意味になる。状態＝wear、動作＝put on と区別する。\"}]}",
"{\"id\":\"eigo_s344\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"身のまわりの語彙④：食べ物・飲み物と数え方\",\"description\":\"食べ物の語彙と、数えられる名詞・数えられない名詞の区別、単位の言い方を学ぶ\",\"intro\":\"りんごは an apple と数えられるのに、水やパンは a water、a bread とは言えません。形が決まっていないものは数えられない、というのが英語の考え方です。ではどう数えるのか——コップやきれを単位にする言い方を身につけます。\",\"order\":844,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"果物・野菜・肉・飲み物など、食べ物の語はジャンルごとにまとめて覚える。\",\"数えられる名詞（an apple, two eggs）と数えられない名詞（water, bread, rice）を区別する。\",\"数えられない名詞は a glass of water / a piece of cake / a cup of tea のように単位を付けて数える。\",\"数えられない名詞に many は使えない。much か a lot of を使う。\",\"「〜が好きです」は I like apples. のように複数形にするのがふつう。\",\"breakfast・lunch・dinner には冠詞を付けない。I have breakfast at seven.\"],\"sections\":[{\"heading\":\"食べ物・飲み物の基本語\",\"body\":\"食事や買い物の場面で必ず出る語をジャンル別に整理する。\\n\\n■ 果物（fruit）\\napple（りんご）／orange（オレンジ）／banana（バナナ）／grape（ぶどう）／peach（もも）／strawberry（いちご）／watermelon（すいか）／pineapple（パイナップル）\\n\\n■ 野菜（vegetable）\\ntomato（トマト）／potato（じゃがいも）／carrot（にんじん）／onion（たまねぎ）／cabbage（キャベツ）／cucumber（きゅうり）／corn（とうもろこし）\\n\\n■ 肉・魚・卵\\nmeat（肉）／beef（牛肉）／pork（ぶた肉）／chicken（とり肉）／fish（魚）／egg（卵）\\n\\n■ 主食・その他\\nrice（ごはん）／bread（パン）／noodles（めん）／soup（スープ）／salad（サラダ）／cheese（チーズ）／sugar（さとう）／salt（塩）\\n\\n■ 飲み物（drink）\\nwater（水）／milk（牛乳）／juice（ジュース）／tea（お茶）／coffee（コーヒー）\\n\\n⚠ 注意：tomato・potato の複数形は -es を付けて tomatoes・potatoes になる。strawberry は y を i に変えて strawberries となる。\"},{\"heading\":\"数えられる名詞と数えられない名詞\",\"body\":\"食べ物の語は、数えられるものと数えられないものがはっきり分かれる。この区別が英作文の得点を大きく左右する。\\n\\n■ 数えられる名詞（形がはっきりしているもの）\\napple, orange, egg, tomato, potato, cookie, hamburger\\n→ a / an を付けたり、-s を付けて複数にできる。\\n例）I eat an apple every morning.／She bought three eggs.\\n\\n■ 数えられない名詞（形が決まっていない・材料や液体）\\nwater, milk, juice, tea, coffee, bread, rice, meat, cheese, sugar, salt, soup\\n→ a / an を付けず、-s も付けない。\\n例）I drink milk every day.（× a milk／× milks）\\n\\n■ 単位を付けて数える\\na glass of water（コップ1杯の水）／a cup of tea（カップ1杯のお茶）／a piece of cake（ケーキ1切れ）／a slice of bread（パン1枚）／a bowl of rice（ごはん1杯）／a bottle of juice（1本のジュース）\\n数を増やすときは単位のほうに -s を付ける。two glasses of water（水2杯）\\n\\n★ ポイント：「多い」を表す語も変わる。数えられる名詞には many、数えられない名詞には much を使い、a lot of はどちらにも使える。\\n例）many apples ／ much water ／ a lot of apples ／ a lot of water\",\"figureId\":\"lf_eigoext10_344\"},{\"heading\":\"食事と好みを表す表現\",\"body\":\"食べ物の語は、次の言い方とセットで使えるようにしておく。\\n\\n■ 食事の名前\\nbreakfast（朝食）／lunch（昼食）／dinner（夕食）／snack（おやつ）\\n食事名には a も the も付けない。\\n例）I have breakfast at seven.（7時に朝食を食べます。）\\n例）What did you have for lunch?（昼食は何を食べましたか。）\\n※ 「〜を食べる」は eat のほか have もよく使う。\\n\\n■ 好きなものを言う\\nI like oranges very much.（オレンジが大好きです。）\\n※ 好きなものを一般的に言うときは複数形にするのがふつう。I like orange. だと「オレンジ色が好き」と受け取られる。\\nI don't like green peppers.（ピーマンは好きではありません。）\\nMy favorite food is curry and rice.（好きな食べ物はカレーライスです。）\\n\\n■ 食卓での表現\\nWould you like some tea?（お茶はいかがですか。）— Yes, please.／No, thank you.\\nHelp yourself.（ご自由にお取りください。）\\nIt's delicious.（とてもおいしい。）\\n\\n★ ポイント：すすめるときは any ではなく some を使う（Would you like some …?）。\"},{\"heading\":\"なぜパンや水は数えられず、なぜ単位で数えるのか\",\"mangaId\":\"eigo_s344_manga\",\"body\":\"英語で「数えられる」のは、**形が決まっていて、一つ二つと区切れるもの**です。りんごや卵は一つの形があるので an apple・two eggs。水・牛乳・パン・ごはん・肉は、量はあっても決まった形がなく、どこで一つと区切るかが決まりません。だから a も -s も付けません。数えたいときは、コップ・カップ・切れ・ボウルという**容器や単位で区切って**、a glass of water・two pieces of cake と言います。数が増えたら単位のほう（glasses・pieces）に -s を付けます。\\n\\ntwo cakes と言うと「ホールケーキ2台」の意味になるのは、cake を形のある一つのものとして数えたことになるからです。切り分けた一部は piece で数えます。「多い」を表す語も、数えられる名詞には many、数えられない名詞には much、どちらにも a lot of と分かれます。\\n\\n■ 確かめのしかた\\n①食べ物の語を見たら、**一つの形があるか**を言う。apple・egg・tomato→数えられる。water・bread・rice・meat・cheese→数えられない。\\n②数えられない語に a や -s を付けていないか（× a milk、× breads）。数えるなら単位：a slice of bread、a bowl of rice、two pieces of cake。\\n③How many＋数えられる複数形、How much＋数えられない名詞。How much water 〜?\\n④食事名（breakfast・lunch・dinner）には冠詞を付けない。好きなものは複数形（I like apples.）。すすめるときは some（Would you like some tea?）。\\n\\n★ ここがポイント：数えられるのは**形が決まっていて区切れるもの**。区切れないもの（水・パン・ごはん）は**容器や単位で区切って**数え、-s は単位のほうに付ける。many／much／a lot of もこの区別で決まる。\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 How （　） water do you drink every day?　［many / much］\",\"wrongAnswer\":\"many\",\"trapExplanation\":\"「どのくらいたくさん」と数をたずねる感覚から many を選んでしまう。How many を一つの決まり文句として覚えていると、後ろの名詞を確かめずに書いてしまう。\",\"correctAnswer\":\"much\",\"correctExplanation\":\"water は数えられない名詞なので many は使えず、How much water …? となる。many は数えられる名詞の複数形の前だけに使う（How many apples …?）。後ろの名詞に -s が付いているかどうかを必ず見てから選ぶ。\"},{\"question\":\"「私はケーキを2切れ食べた。」を英語にしなさい。\",\"wrongAnswer\":\"I ate two cakes.\",\"trapExplanation\":\"日本語の「2切れ」をそのまま「2つ」と考えて cake に -s を付けてしまう。two cakes だと「ホールケーキを丸ごと2台」という意味になってしまう。\",\"correctAnswer\":\"I ate two pieces of cake.\",\"correctExplanation\":\"切り分けた一部を数えるときは a piece of cake（1切れ）を使い、複数にするときは piece のほうに -s を付けて two pieces of cake とする。同じように a glass of water → two glasses of water と数える。\"}]}",
"{\"id\":\"eigo_s345\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"身のまわりの語彙⑤：家の中の部屋と家具\",\"description\":\"部屋・家具・家電の語と、家の中の場所を表す言い方を身につける\",\"intro\":\"「わたしの家には部屋が六つあります」と英語で紹介するには、部屋の名前がなければ始まりません。living room や bathroom には、日本の間取りとぴったり同じではない語もあります。家の中の語と位置の前置詞をまとめて使えるようにします。\",\"order\":845,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"living room（居間）・kitchen（台所）・bedroom（寝室）・bathroom（浴室・トイレ）が部屋の基本語。\",\"家具は desk・chair・table・bed・sofa・bookshelf、家電は TV・fridge・washing machine。\",\"部屋の中の位置は in / on / under / by / between などの前置詞で表す。\",\"「〜がある」は There is（単数）／ There are（複数）で始める。\",\"house は建物、home は「わが家」。I go home. には to を付けない。\",\"2階は the second floor、1階は the first floor（アメリカ英語）。\"],\"sections\":[{\"heading\":\"部屋と家の中の語\",\"body\":\"家の中を表す語は、There is / There are の文や道案内の練習でくり返し使う。\\n\\n■ 部屋\\nliving room（居間）／dining room（食堂）／kitchen（台所）／bedroom（寝室）／bathroom（浴室。アメリカではトイレも指す）／study（書斎）／room（部屋）\\n\\n■ 家のつくり\\ndoor（ドア）／window（窓）／wall（かべ）／floor（ゆか・階）／roof（屋根）／stairs（階段）／garden（庭）／yard（庭・敷地）／garage（車庫）／gate（門）\\n\\n■ 家具・道具\\ndesk（つくえ）／chair（いす）／table（テーブル）／bed（ベッド）／sofa（ソファー）／bookshelf（本だな）／closet（おしいれ）／curtain（カーテン）／clock（かけ時計）／lamp（電気スタンド）\\n\\n■ 家電\\nTV（テレビ）／computer（コンピューター）／fridge, refrigerator（冷蔵庫）／washing machine（洗たく機）／air conditioner（エアコン）／microwave（電子レンジ）\\n\\n★ ポイント：house は「建物としての家」、home は「自分が帰る家・家庭」。I'm at home.（家にいる）／My house is near the station.（私の家は駅の近くだ）\\n\\n⚠ 注意：go home の home は「家へ」という意味を自分の中に含むので、to を付けない（× go to home）。\",\"figureId\":\"lf_eigoext10_345\"},{\"heading\":\"There is / There are で家の中を説明する\",\"body\":\"「〜に…がある」と説明する言い方は、家の中の描写問題の定番である。\\n\\n■ 基本の形\\nThere is ＋ 単数の名詞 ＋ 場所を表す語句\\nThere are ＋ 複数の名詞 ＋ 場所を表す語句\\n\\n例）There is a bed in my room.（私の部屋にはベッドがあります。）\\n例）There are two windows in the kitchen.（台所には窓が二つあります。）\\n\\n■ be動詞は「後ろの名詞」に合わせる\\nThere is a chair and two desks. のように後ろが並ぶときは、いちばん近い名詞に合わせるのがふつう。混乱を避けるため、数の多いほうを先に書くとよい。\\n\\n■ 疑問文と否定文\\nIs there a computer in your room?（部屋にコンピューターはありますか。）\\n— Yes, there is.／No, there isn't.\\nHow many rooms are there in your house?（家に部屋はいくつありますか。）\\nThere isn't a TV in my room.（私の部屋にはテレビがありません。）\\n\\n⚠ 注意：「私の机は窓の近くにあります」のように、話し手も聞き手も知っているものの位置を言うときは、There is を使わず My desk is by the window. と言う。There is … は「新しく登場するもの」を示す形である。\",\"mangaId\":\"eigo_s345_xm\"},{\"heading\":\"家の中の位置を表す前置詞\",\"body\":\"部屋の中のようすを説明するには、位置を表す前置詞が欠かせない。\\n\\nin（〜の中に）／on（〜の上に・接している）／under（〜の下に）／by, near（〜のそばに）／in front of（〜の前に）／behind（〜の後ろに）／between A and B（AとBの間に）／next to（〜のとなりに）／above（〜の上方に）／over（〜の真上に）\\n\\n例）The cat is under the table.（ねこはテーブルの下にいます。）\\n例）The clock is on the wall.（時計はかべに掛かっています。）\\n例）My bag is between the desk and the bed.（私のかばんはつくえとベッドの間にあります。）\\n\\n★ ポイント：on は「上」という意味ではなく「くっついている」という意味。だからかべに掛かった時計も天井の電灯も on を使う。\\n例）There is a picture on the wall.（かべに絵がかかっている。）\\n\\n■ 階を言う\\non the first floor（1階に）／on the second floor（2階に）\\n※ アメリカ英語では地上階が first floor。イギリス英語では ground floor が地上階で、その上が first floor になる。中学受験ではアメリカ式で覚えてよい。\"}],\"trapExamples\":[{\"question\":\"「私は5時に家に帰ります。」を英語にしなさい。\",\"wrongAnswer\":\"I go to home at five.\",\"trapExplanation\":\"go to school / go to the park と同じ形だと考え、home にも to を付けてしまう。「家へ」の「へ」を to で表そうとする日本語からの直訳が原因。\",\"correctAnswer\":\"I go home at five.\",\"correctExplanation\":\"この home は「家へ」という方向の意味を自分の中に含む副詞なので、to は不要である。同じ仲間に go there（そこへ行く）、come here（ここへ来る）がある。ただし建物としての家を指す house なら go to my house と to が要る。\"},{\"question\":\"（　）に入る語を答えなさい。 There （　） three chairs in the kitchen.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"There is … を一つの決まり文句として覚えているため、後ろの名詞の数を確かめずに is と書いてしまう。日本語では「いすが3つある」も「いすが1つある」も同じ形なので気づきにくい。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"There is / There are の be動詞は、後ろに来る名詞の数に合わせる。ここは three chairs と複数なので are にする。「ある」ものが1つなら There is a chair …、2つ以上なら There are two chairs … と書き分ける。\"}]}",
"{\"id\":\"eigo_s346\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"学校①：教科と時間割\",\"description\":\"教科名の英語と、時間割・好きな教科をたずねる表現を身につける\",\"intro\":\"「音楽が好きです」を I like a music. と書くとまちがいです。教科名には a も the も付けず、複数形にもしません。さらに English や Japanese は国名からできた語なので、文の途中でも大文字で始めます。教科名の決まりを確かめます。\",\"order\":846,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"教科名は math・science・social studies・Japanese・English・music・P.E.・art が基本。\",\"国名からできた教科名（English, Japanese）は必ず大文字で書き始める。\",\"教科名には a も the も付けず、-s も付けない。I like music.\",\"math は mathematics の短い形、P.E. は physical education の頭文字。\",\"「何の教科が好きですか」は What subject do you like? が定番。\",\"「〜が得意だ」は be good at ＋ 教科名。I am good at math.\"],\"sections\":[{\"heading\":\"教科名を正しく書く\",\"body\":\"教科名は英検5級・4級で毎回のように出題される。つづりと大文字の使い方に気をつける。\\n\\n■ 主な教科\\nJapanese（国語）／English（英語）／math（算数・数学）／science（理科）／social studies（社会）／music（音楽）／art（図工・美術）／P.E.（体育）／home economics（家庭科）／calligraphy（習字）／moral education（道徳）\\n\\n★ ポイント：Japanese・English・Chinese・French のように国や民族からできた語は、文の途中でも必ず大文字で書き始める。これを小文字で書く誤りが非常に多い。\\n\\n■ 短くした形\\nmath は mathematics（数学）を短くした語。アメリカ英語では math、イギリス英語では maths と書く。\\nP.E. は physical education（体育）の頭文字。ピリオドを付けて書く。\\nsocial studies は二語で一つの教科名。studies と複数形になっているが、教科名として単数あつかいする。\\n例）Social studies is my favorite subject.\\n\\n⚠ 注意：教科名には a / an / the を付けず、-s も付けない。\\n例）I like science.（× I like a science.／× I like sciences.）\",\"figureId\":\"xf_eigo_s346\",\"mangaId\":\"eigo_s346_xm\"},{\"heading\":\"時間割と学校の一日\",\"body\":\"時間割や学校生活を説明するときに必要な語をまとめる。\\n\\n■ 学校生活の語\\nclass（授業・クラス）／lesson（授業）／subject（教科）／timetable, schedule（時間割）／homework（宿題）／test, exam（テスト）／recess, break（休み時間）／lunch break（昼休み）／club activity（クラブ活動）／homeroom（ホームルーム）\\n\\n■ 時間割を説明する\\nWe have four classes in the morning.（午前中に4時間授業があります。）\\nI have math on Monday.（月曜日に算数があります。）\\n※ 曜日には on を付ける。\\nThe first class starts at 8:40.（1時間目は8時40分に始まります。）\\n\\n■ 一日の流れ\\nI go to school at eight.／We clean our classroom after lunch.（昼食後に教室をそうじします。）／School is over at three.（学校は3時に終わります。）\\n\\n★ ポイント：homework は数えられない名詞なので、a homework とも homeworks とも言わない。量を言うときは a lot of homework とする。\\n例）I have a lot of homework today.（今日は宿題がたくさんある。）\"},{\"heading\":\"好きな教科をたずねる・答える\",\"body\":\"会話問題では、次のやりとりがそのまま出題される。\\n\\n■ たずね方\\nWhat subject do you like?（何の教科が好きですか。）\\nWhat is your favorite subject?（好きな教科は何ですか。）\\nDo you like English?（英語は好きですか。）\\n\\n■ 答え方\\nI like English (the) best.（英語がいちばん好きです。）\\nMy favorite subject is science.（好きな教科は理科です。）\\nI like math because it is fun.（算数が好きです。おもしろいから。）\\nI don't like P.E. very much.（体育はあまり好きではありません。）\\n\\n■ 得意・苦手を言う\\nI am good at English.（英語が得意です。）\\nI am not good at math.／I am poor at math.（算数が苦手です。）\\n※ be good at の後ろに動詞を置くときは -ing の形にする。\\n例）I am good at singing.（歌うのが得意です。）\\n\\n⚠ 注意：favorite にはすでに「いちばん好きな」という意味が入っているので、My most favorite subject … のように most を重ねない。\"}],\"trapExamples\":[{\"question\":\"「私は英語と音楽が好きです。」を英語にしなさい。\",\"wrongAnswer\":\"I like english and music.\",\"trapExplanation\":\"文の途中にあるので小文字でよいと考えてしまう。日本語には大文字・小文字の区別がないため、意識しないと必ず抜ける。\",\"correctAnswer\":\"I like English and music.\",\"correctExplanation\":\"国や言語からできた語（English, Japanese, Chinese, French）は、文のどこにあっても大文字で書き始める。一方、music・math・science・art などは固有の名前ではないので小文字のままでよい。同じ文の中で書き分けられるようにする。\"},{\"question\":\"（　）に入る語を答えなさい。 I am good at （　） the piano.\",\"wrongAnswer\":\"play\",\"trapExplanation\":\"be good at を「〜が得意だ」と丸暗記していると、後ろにそのまま動詞の原形を置いてしまう。at が前置詞であることを意識できていないのが原因。\",\"correctAnswer\":\"playing\",\"correctExplanation\":\"at は前置詞なので、後ろに動詞を置くときは必ず -ing の形（動名詞）にする。I am good at playing the piano. となる。同じ形に be interested in reading、Thank you for coming. がある。前置詞の後ろは名詞か -ing、と覚える。\"}]}",
"{\"id\":\"eigo_s347\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"学校②：文房具と持ち物\",\"description\":\"文房具の語と、持ち物を貸し借りするときの表現を身につける\",\"intro\":\"消しゴムを英語で言うとき、消す＋ゴムと考えて gum を使いたくなりますが、正しくは eraser です。はさみは scissors と、いつも複数形。日本語からそのまま作れない文房具の語を、実物と結びつけて覚えます。\",\"order\":847,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"pen・pencil・eraser・ruler・notebook・textbook・pencil case が基本語。\",\"消しゴムは eraser（イギリス英語では rubber）。「消しゴム」の直訳はしない。\",\"scissors（はさみ）は二枚の刃が組みになっているので、いつも複数形。\",\"「持っていますか」は Do you have …?、「貸してください」は Can I borrow …?\",\"「これはだれの〜ですか」は Whose … is this? — It's mine.（私のです）\",\"所有代名詞 mine / yours / his / hers / ours / theirs を使うと名詞をくり返さずにすむ。\"],\"sections\":[{\"heading\":\"文房具・持ち物の語\",\"body\":\"教室の場面で出てくる持ち物の語をまとめる。\\n\\n■ 筆記用具\\npen（ペン）／pencil（えんぴつ）／colored pencil（色えんぴつ）／mechanical pencil（シャープペンシル）／eraser（消しゴム）／pencil case（筆箱）／pencil sharpener（えんぴつけずり）／marker（マーカー）／crayon（クレヨン）／brush（筆）\\n\\n■ 紙・本\\nnotebook（ノート）／textbook（教科書）／dictionary（辞書）／paper（紙）／card（カード）／map（地図）\\n\\n■ 道具\\nruler（定規）／scissors（はさみ）／glue（のり）／stapler（ホチキス）／calculator（電たく）／bag（かばん）／school bag（通学かばん）／lunch box（弁当箱）／water bottle（水とう）\\n\\n⚠ 注意：日本語の「ノート」は note ではなく notebook。note は「メモ・覚え書き」の意味になる。「シャープペンシル」も和製英語で、英語では mechanical pencil という。\\n\\n★ ポイント：scissors は刃が二枚一組なのでいつも複数形。数えるときは a pair of scissors とする。glasses（めがね）と同じ考え方である。\\n\\n■ 数えられない語\\npaper（紙）は数えられない名詞。1枚は a piece of paper、2枚は two pieces of paper と数える。\",\"mangaId\":\"eigo_s347_xm\"},{\"heading\":\"持ち物についてのやりとり\",\"body\":\"教室での会話は、次の三つの型で答えられるようにする。\\n\\n■ 持っているかたずねる\\nDo you have a pencil?（えんぴつを持っていますか。）\\n— Yes, I do.／No, I don't.\\nDo you have an eraser? ← eraser は母音で始まるので an を付ける。\\n\\n■ 借りる・貸す\\nCan I borrow your eraser?（消しゴムを借りてもいいですか。）\\n— Sure. Here you are.（いいよ。はい、どうぞ。）\\nCan you lend me your ruler?（定規を貸してくれますか。）\\n※ borrow は「借りる」、lend は「貸す」。主語がどちらの立場かで使い分ける。\\n\\n■ だれのものかたずねる\\nWhose notebook is this?（これはだれのノートですか。）\\n— It's mine.／It's Ken's.（私のです。／ケンのです。）\\nWhose are these pencils?（これらのえんぴつはだれのものですか。）\\n— They are hers.\\n\\n★ ポイント：mine, yours, his, hers, ours, theirs は「〜のもの」を一語で表す所有代名詞。my notebook を mine と一語で言いかえられる。\\n⚠ 注意：Whose（だれの）と Who's（＝Who is）は発音が同じでつづりがちがう。書き取りで区別する。\",\"figureId\":\"xf_eigo_s347\"}],\"trapExamples\":[{\"question\":\"「これはだれのかばんですか。」を英語にしなさい。\",\"wrongAnswer\":\"Who's bag is this?\",\"trapExplanation\":\"whose と who's は発音がまったく同じなので、耳で覚えていると書くときに取りちがえる。「だれの」＝「だれは」と考えてしまうのも原因。\",\"correctAnswer\":\"Whose bag is this?\",\"correctExplanation\":\"whose は「だれの」という意味で、後ろに名詞が続く。who's は who is を短くした形で、Who's that boy?（あの少年はだれですか。）のように使う。後ろに名詞があれば whose、be動詞の働きが必要なら who's と判断する。\"},{\"question\":\"「はさみを持っていますか。」を英語にしなさい。\",\"wrongAnswer\":\"Do you have a scissor?\",\"trapExplanation\":\"日本語では「はさみを1本」と数えるので、単数形にして a を付けてしまう。二枚の刃が組みになっている道具だという英語の見方に気づかない。\",\"correctAnswer\":\"Do you have scissors?（または a pair of scissors）\",\"correctExplanation\":\"scissors はいつも複数形で使う語で、scissor という単数形はふつう使わない。数えるときは a pair of scissors（1丁）、two pairs of scissors（2丁）とする。glasses・pants・shoes と同じ仲間としてまとめて覚える。\"}]}",
"{\"id\":\"eigo_s348\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"学校③：一年の行事\",\"description\":\"入学式・運動会・修学旅行など学校行事の英語と、月と結びつけた言い方を学ぶ\",\"intro\":\"運動会や修学旅行には、そのまま当てはまる英語の一語がありません。sports day、school trip のように、二語を組み合わせて表します。行事の話をするときの「〜がある」に have を使うのもポイントです。月の言い方とセットで練習します。\",\"order\":848,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"entrance ceremony（入学式）・sports day（運動会）・school trip（修学旅行）・graduation ceremony（卒業式）が中心。\",\"行事の月を言うときは in April のように in を使う。日付なら on May 5 と on を使う。\",\"「〜がある」は We have ＋ 行事名。We have a sports day in October.\",\"summer vacation（夏休み）は数えられる名詞のようにあつかい、during summer vacation で「夏休みの間」。\",\"「楽しかった」は I enjoyed it very much.／It was a lot of fun.\",\"行事の思い出は過去形で書く。went・had・saw・was など不規則動詞に注意。\"],\"sections\":[{\"heading\":\"学校行事の英語\",\"body\":\"日本の学校行事は、英語では説明的な言い方になるものが多い。組み合わせで覚える。\\n\\n■ 一年の行事\\nentrance ceremony（入学式）／opening ceremony（始業式）／sports day, field day（運動会）／school trip（修学旅行・遠足）／field trip（遠足・校外学習）／school excursion（修学旅行）／music festival, chorus contest（音楽会・合唱コンクール）／school festival（学園祭・文化祭）／swimming meet（水泳大会）／marathon（マラソン大会）／graduation ceremony（卒業式）\\n\\n■ 休み\\nspring vacation（春休み）／summer vacation（夏休み）／winter vacation（冬休み）\\n※ イギリス英語では vacation ではなく holiday を使う。\\n\\n■ 行事を説明する\\nWe have a sports day in October.（10月に運動会があります。）\\nOur school festival is in November.（学園祭は11月です。）\\nWe went to Kyoto on our school trip.（修学旅行で京都に行きました。）\\n\\n★ ポイント：月の名前の前には in、日付の前には on を使う。\\n例）in April（4月に）／on April 8（4月8日に）\\n\\n⚠ 注意：月の名前も曜日の名前も必ず大文字で書き始める（April, May, Monday）。\",\"figureId\":\"lf_eigoext10_348\"},{\"heading\":\"行事の思い出を書く\",\"body\":\"「思い出に残っている行事」を書かせる問題は、英語入試で頻出である。過去形を正しく使うことが得点の分かれ目になる。\\n\\n■ よく使う過去形（不規則動詞）\\ngo → went（行った）／have → had（〜があった・食べた）／see → saw（見た）／eat → ate（食べた）／take → took（撮った・持っていった）／run → ran（走った）／sing → sang（歌った）／win → won（勝った）／is, am → was／are → were\\n\\n■ 書き方の型\\n① いつ・何があったか：Last October, we had a sports day.\\n② 何をしたか：I ran in the relay race.（リレーで走りました。）\\n③ 結果：My team won the race.（私のチームが勝ちました。）\\n④ 感想：I was very happy.／It was a lot of fun.\\n\\n例文）Last May, we went to Kyoto on our school trip. We visited many temples and took a lot of pictures. I enjoyed it very much.\\n\\n★ ポイント：感想は I enjoyed it very much.／It was exciting.／I had a good time. のどれかを覚えておけば必ず書ける。\\n\\n⚠ 注意：enjoy の後ろに動詞を置くときは -ing にする。I enjoyed swimming in the sea.（× enjoyed to swim）\"},{\"heading\":\"なぜ行事は二語で表し、なぜ enjoy のあとは -ing なのか\",\"mangaId\":\"eigo_s348_manga\",\"body\":\"運動会・修学旅行のような日本の学校行事には、そのまま当てはまる英語の一語がありません。英語では「スポーツの日」「学校の旅行」のように**説明する二語**（sports day・school trip）で表します。行事が「ある」と言うとき have を使うのは、行事を「持っている・経験する」ものとしてとらえるからで、We have a sports day in October. と言います。月には in（幅のある期間）、日付には on（一日）を使います。\\n\\nenjoy のあとの動詞を -ing にするのは、enjoy が「（今している・したこと）を楽しむ」という動詞で、**すでに起きている動作**を目的語にとるからです。-ing は「している最中の動作」を名詞にした形なので、enjoy と相性が合います。反対に want・hope・decide は「これからすること」を目的語にとるので、未来へ向かう to＋原形と組みます。enjoy -ing はセットで覚えます。\\n\\n■ 確かめのしかた\\n①行事は二語で：entrance ceremony／sports day／school trip／school festival／graduation ceremony。「〜がある」は We have ＋ 行事。\\n②**月→in、日付→on、時刻→at**：in October／on October 10／at seven。× on October。\\n③思い出は過去形で：went・had・saw・ate・took・ran・sang・won・was・were。\\n④enjoy・finish・stop のあとは -ing（enjoyed swimming）。want・hope・decide のあとは to＋原形。× enjoyed to swim。\\n\\n★ ここがポイント：行事は**説明する二語**で表し、「ある」は have。**月は in、日付は on**。enjoy は**すでにしていることを楽しむ**動詞なので -ing をとる。\"}],\"trapExamples\":[{\"question\":\"「私たちは10月に運動会があります。」を英語にしなさい。\",\"wrongAnswer\":\"We have a sports day on October.\",\"trapExplanation\":\"「〜に」をすべて on で表せると思いこんでしまう。曜日や日付で on を使う練習をした直後ほど、月にも on を付けてしまう。\",\"correctAnswer\":\"We have a sports day in October.\",\"correctExplanation\":\"月・年・季節のように幅のある期間には in を使い、日付・曜日のように一日を指すときには on を使う。in October（10月に）／on October 10（10月10日に）／on Sunday（日曜日に）と整理する。時刻には at を使う（at seven）。\"},{\"question\":\"「私は海で泳ぐのを楽しみました。」を英語にしなさい。\",\"wrongAnswer\":\"I enjoyed to swim in the sea.\",\"trapExplanation\":\"「〜することを楽しむ」という日本語から、「〜すること」＝to ＋ 動詞の原形だと考えてしまう。want to go などの形につられるのも原因。\",\"correctAnswer\":\"I enjoyed swimming in the sea.\",\"correctExplanation\":\"enjoy の後ろに動詞を置くときは必ず -ing の形にする。同じ仲間に finish・stop・practice がある。反対に、want・hope・decide・need は to ＋ 動詞の原形をとる。enjoy -ing はセットで暗記する。\"}]}",
"{\"id\":\"eigo_s349\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"学校④：教室で使う英語と学校の場所\",\"description\":\"先生の指示（教室英語）と、校内の場所を表す語を身につける\",\"intro\":\"Open your textbook. Stand up. 先生の指示は、どれも動詞から始まります。主語がないのは、相手が目の前の「あなた」に決まっているからです。命令文のこの性質を知ると、教室で聞こえる英語が一気に分かりやすくなります。\",\"order\":849,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"教室の指示は動詞で始まる命令文。Open your textbook. / Stand up. / Listen carefully.\",\"ていねいにするには please を文の始めか終わりに付ける。Please sit down.\",\"「〜しないで」は Don't ＋ 動詞の原形。Don't run in the hallway.\",\"校内の場所：classroom・gym・library・music room・school yard・teachers' room。\",\"「〜してもいいですか」は May I …? / Can I …?、「〜してくれますか」は Can you …?\",\"聞き取れないときは Pardon?／Could you say that again?（もう一度言ってください）。\"],\"sections\":[{\"heading\":\"先生が使う教室英語（命令文）\",\"body\":\"授業中に先生が使う言い方は、すべて動詞で始まる命令文である。主語の You を書かないのが特徴。\\n\\n■ よく使う指示\\nStand up.（立ちなさい。）／Sit down.（すわりなさい。）／Open your textbook to page 20.（教科書の20ページを開きなさい。）／Close your book.（本を閉じなさい。）／Look at the blackboard.（黒板を見なさい。）／Listen carefully.（よく聞きなさい。）／Repeat after me.（私のあとについてくり返しなさい。）／Read aloud.（声に出して読みなさい。）／Raise your hand.（手をあげなさい。）／Write your name here.（ここに名前を書きなさい。）／Be quiet.（静かにしなさい。）\\n\\n★ ポイント：be動詞の命令文は Be で始める。Be quiet.／Be careful.（気をつけて。）／Be kind to your friends.\\n\\n■ ていねいな言い方\\nPlease stand up.／Stand up, please.\\n※ 文の終わりに置くときはコンマを打つ。\\n\\n■ 禁止\\nDon't run in the hallway.（ろうかを走ってはいけません。）／Don't be late.（おくれないように。）／Don't forget your homework.（宿題を忘れないで。）\\n\\n⚠ 注意：Let's ＝「〜しましょう」は命令文と形が似ているが意味がちがう。Let's begin.（始めましょう。）は自分もいっしょに行う。\",\"figureId\":\"xf_eigo_s349\",\"mangaId\":\"eigo_s349_xm\"},{\"heading\":\"学校の中の場所と人\",\"body\":\"校内の場所を表す語は、道案内や紹介文でそのまま使える。\\n\\n■ 場所\\nclassroom（教室）／gym, gymnasium（体育館）／library（図書室）／music room（音楽室）／science room（理科室）／computer room（コンピューター室）／art room（図工室）／cooking room（調理室）／nurse's office（保健室）／teachers' room, staff room（職員室）／principal's office（校長室）／school yard, playground（校庭）／swimming pool（プール）／hallway, corridor（ろうか）／entrance（げんかん）／restroom（トイレ）\\n\\n■ 人\\nteacher（先生）／homeroom teacher（担任の先生）／principal（校長先生）／school nurse（保健の先生）／classmate（クラスメート）／student, pupil（児童・生徒）\\n\\n■ 場所を言う\\nThe library is on the second floor.（図書室は2階です。）\\nOur classroom is next to the music room.（私たちの教室は音楽室のとなりです。）\\n\\n⚠ 注意：teachers' room はアポストロフィが -s の後ろに付く（先生が複数いる部屋なので）。nurse's office は先生が一人なので -s の前に付く。\"},{\"heading\":\"生徒が使う教室英語\",\"body\":\"生徒の側から使う表現も、リスニングや会話の並べかえ問題で問われる。\\n\\n■ 許可を求める\\nMay I come in?（入ってもいいですか。）— Sure.／Of course.\\nCan I go to the restroom?（トイレに行ってもいいですか。）\\nMay I use your dictionary?（辞書を使ってもいいですか。）\\n※ May I …? のほうが Can I …? よりていねい。\\n\\n■ お願いする\\nCan you help me?（手伝ってくれますか。）\\nCould you speak more slowly?（もっとゆっくり話してもらえますか。）\\n※ Could you …? は Can you …? のていねいな形。\\n\\n■ わからないときに使う言い方\\nPardon?／Excuse me?（もう一度お願いします。）\\nCould you say that again?（もう一度言ってもらえますか。）\\nHow do you say \\\"つくえ\\\" in English?（「つくえ」は英語で何と言いますか。）\\nWhat does this word mean?（この語はどういう意味ですか。）\\nI don't understand.（わかりません。）\\nI have a question.（質問があります。）\\n\\n★ ポイント：May I …? は「私が〜してよいか」、Can you …? は「あなたが〜してくれるか」。主語がだれかを見れば、許可を求める文か依頼する文かが区別できる。\"}],\"trapExamples\":[{\"question\":\"「ろうかを走ってはいけません。」を英語にしなさい。\",\"wrongAnswer\":\"You don't run in the hallway.\",\"trapExplanation\":\"「〜してはいけません」を否定文だと考え、主語 You を付けたふつうの否定文にしてしまう。この形だと「あなたはろうかを走りません」という事実の説明になってしまう。\",\"correctAnswer\":\"Don't run in the hallway.\",\"correctExplanation\":\"禁止を表す命令文は、主語を書かずに Don't ＋ 動詞の原形で始める。be動詞の場合も Don't be late.（おくれないで）と Don't be … の形になる。主語 You を付けると命令ではなく事実を述べる文に変わってしまう。\"},{\"question\":\"（　）に入る語を選びなさい。 （　） I use your dictionary? — Sure, here you are.　［May / Can you］\",\"wrongAnswer\":\"Can you\",\"trapExplanation\":\"「〜してもいいですか」も「〜してくれますか」も日本語では相手にお願いする形なので、区別せずに Can you を選んでしまう。\",\"correctAnswer\":\"May\",\"correctExplanation\":\"辞書を使うのは「私」なので、主語は I になり、許可を求める May I …?（または Can I …?）を使う。Can you …? は「あなたが〜してくれますか」という依頼で、動作をするのは相手である。だれが動作をするのかで判断する。\"}]}",
"{\"id\":\"eigo_s350\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自然①：動物を表す語と鳴き声・複数形\",\"description\":\"ペット・家畜・野生動物の語と、不規則な複数形、動物にまつわる表現を学ぶ\",\"intro\":\"sheep は一匹でも百匹でも sheep のままだと知っていましたか。fish や deer も同じで、複数形になっても形が変わりません。逆に mouse は mice と大きく変わります。動物の語には、数え方のしかけがひそんでいます。\",\"order\":850,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"dog・cat・bird・fish・horse・cow・pig・sheep・rabbit が基本語。\",\"複数形が変わらない語：sheep → sheep、fish → fish、deer → deer。\",\"不規則な複数形：mouse → mice、goose → geese。\",\"動物を飼うのは keep か have。I have two dogs.／We keep a rabbit at school.\",\"動物を指す代名詞はふつう it。名前のあるペットだけ he / she で呼ぶことがある。\",\"animal（動物）・insect（昆虫）・bird（鳥）・fish（魚）とグループの語も覚える。\"],\"sections\":[{\"heading\":\"動物の語をグループで覚える\",\"body\":\"動物の語は数が多いので、生活の場面ごとにまとめて覚えると効率がよい。\\n\\n■ ペット\\ndog（犬）／cat（ねこ）／rabbit（うさぎ）／hamster（ハムスター）／bird（鳥）／goldfish（金魚）／turtle（かめ）\\n\\n■ 家畜・農場の動物\\ncow（牛）／horse（馬）／pig（ぶた）／sheep（ひつじ）／goat（やぎ）／chicken（にわとり）／duck（あひる）\\n\\n■ 野生動物・動物園\\nlion（ライオン）／tiger（とら）／elephant（ぞう）／bear（くま）／monkey（さる）／giraffe（きりん）／panda（パンダ）／wolf（おおかみ）／fox（きつね）／deer（しか）／snake（へび）／frog（かえる）\\n\\n■ 海の生き物\\nwhale（くじら）／dolphin（いるか）／shark（さめ）／octopus（たこ）／crab（かに）／penguin（ペンギン）\\n\\n■ 昆虫（insect）\\nbutterfly（ちょう）／beetle（かぶと虫）／ant（あり）／bee（はち）／dragonfly（とんぼ）／grasshopper（ばった）／spider（くも。厳密には昆虫ではない）\\n\\n⚠ 注意：giraffe の gi、elephant の ph、butterfly の tt はつづりをまちがえやすい。\"},{\"heading\":\"複数形に気をつける動物\",\"body\":\"動物の語には、-s を付けない複数形や形が変わる複数形が多い。入試の定番である。\\n\\n■ 単数と複数が同じ形\\nsheep → sheep（ひつじ）／deer → deer（しか）／fish → fish（魚）\\n例）There are ten sheep in the field.（野原にひつじが10頭いる。）\\n※ fish は種類のちがう魚を並べるときだけ fishes とすることがあるが、ふつうは fish のままでよい。\\n\\n■ 形が変わるもの\\nmouse → mice（ねずみ）／goose → geese（がちょう）／wolf → wolves（おおかみ）／leaf → leaves（葉）\\n※ -f, -fe で終わる語は f を v に変えて -es を付ける。knife → knives、life → lives も同じ。\\n\\n■ ふつうに -s / -es を付けるもの\\ndog → dogs／cat → cats／horse → horses／fox → foxes／monkey → monkeys\\n※ -x, -s, -sh, -ch で終わる語は -es を付ける（foxes, boxes）。\\n※ 語尾が「子音字＋y」なら y を i に変えて -es（butterfly → butterflies）。「母音字＋y」ならそのまま -s（monkey → monkeys、boy → boys）。\\n\\n★ ポイント：monkey は母音字（e）＋ y なので monkies ではなく monkeys。ここは必ず問われる。\",\"figureId\":\"xf_eigo_s350\",\"mangaId\":\"eigo_s350_xm\"},{\"heading\":\"動物についての表現\",\"body\":\"動物を話題にした会話は、次の型で答えられるようにしておく。\\n\\n■ ペットについて\\nDo you have any pets?（ペットを飼っていますか。）\\n— Yes, I have two dogs.／No, I don't.\\nWhat's your dog's name?（犬の名前は何ですか。）— His name is Pochi.\\nI take care of my dog every day.（毎日犬の世話をしています。）\\nI walk my dog before breakfast.（朝食前に犬を散歩させます。）\\n\\n■ 好きな動物\\nWhat animal do you like?（どんな動物が好きですか。）\\n— I like pandas (the) best.（パンダがいちばん好きです。）\\n※ 動物を一般的に「好き」と言うときは複数形にする。\\n\\n■ 動物の特徴を言う\\nElephants are very big.（ぞうはとても大きい。）\\nRabbits can run fast.（うさぎは速く走れる。）\\nPenguins can't fly.（ペンギンは飛べない。）\\nA whale is not a fish. It is an animal.（くじらは魚ではなく動物だ。）\\n\\n★ ポイント：「〜は一般に…だ」と言うときは、複数形（Elephants are …）か a ＋ 単数（An elephant is …）のどちらかを使う。\"}],\"trapExamples\":[{\"question\":\"「野原にひつじが5頭います。」を英語にしなさい。\",\"wrongAnswer\":\"There are five sheeps in the field.\",\"trapExplanation\":\"複数なら -s を付ける、という規則をすべての名詞にあてはめてしまう。sheep が単数と複数で同じ形だと知らないと必ず引っかかる。\",\"correctAnswer\":\"There are five sheep in the field.\",\"correctExplanation\":\"sheep は単数形と複数形が同じ形の語で、-s を付けない。同じ仲間に deer（しか）と fish（魚）がある。数が複数であることは five や動詞の are で示されるので、名詞の形は変えなくてよい。\"},{\"question\":\"次の語を複数形にしなさい。 monkey\",\"wrongAnswer\":\"monkies\",\"trapExplanation\":\"「y で終わる語は y を i に変えて -es」という規則だけを覚えていて、その前が母音字か子音字かを確かめない。butterfly → butterflies の直後だとよけいに引っかかる。\",\"correctAnswer\":\"monkeys\",\"correctExplanation\":\"y を i に変えるのは「子音字＋y」で終わる語だけである（city → cities、butterfly → butterflies）。monkey は e という母音字＋y なので、そのまま -s を付けて monkeys とする。boy → boys、day → days、key → keys も同じ形。\"}]}",
"{\"id\":\"eigo_s351\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自然②：植物と自然の風景\",\"description\":\"植物の部分・自然の地形を表す語と、自然を説明する言い方を学ぶ\",\"intro\":\"leaf の複数形を leafs と書くと誤りで、正しくは leaves です。f が v に変わってから es が付く型があるのです。木や葉、山や川といった自然の語は、この不規則な変化とともに覚えると入試で強くなります。\",\"order\":851,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"tree（木）・flower（花）・leaf（葉）・root（根）・seed（種）・branch（枝）が植物の基本語。\",\"leaf の複数形は leaves。f を v に変えて -es を付ける型。\",\"自然の地形：mountain・river・sea・lake・forest・field・beach・island。\",\"固有名詞の前の the に注意：the Pacific Ocean、Mt. Fuji（Mt. には the を付けない）。\",\"grass（草）・water（水）・air（空気）は数えられない名詞。\",\"「花がさく」は bloom、「木を植える」は plant a tree。\"],\"sections\":[{\"heading\":\"植物を表す語\",\"body\":\"理科的な話題や、季節の説明でよく出る語をまとめる。\\n\\n■ 植物の部分\\ntree（木）／plant（植物）／flower（花）／leaf（葉）／branch（枝）／trunk（みき）／root（根）／seed（種）／bud（つぼみ）／grass（草）／fruit（実・果物）\\n\\n■ 花の名前\\ncherry blossom（さくらの花）／rose（ばら）／tulip（チューリップ）／sunflower（ひまわり）／morning glory（あさがお）／lily（ゆり）\\n\\n■ 植物についての動詞\\ngrow（育つ・育てる）／plant（植える）／water（水をやる）／bloom（花がさく）／fall（落ちる）／pick（つむ）\\n\\n例）The cherry blossoms are beautiful in spring.（春はさくらの花が美しい。）\\n例）I water the flowers every morning.（毎朝、花に水をやります。）\\n※ water は「水」という名詞と「水をやる」という動詞の両方に使える。\\n\\n★ ポイント：leaf の複数形は leaves。f を v に変えて -es を付けるタイプで、knife → knives、life → lives、wolf → wolves と同じ仲間。\\n\\n⚠ 注意：grass（草）は数えられない名詞。glass（コップ・ガラス）とつづりが1字ちがうだけなので書き分ける。\",\"figureId\":\"xf_eigo_s351\",\"mangaId\":\"eigo_s351_xm\"},{\"heading\":\"自然の風景を表す語\",\"body\":\"風景の描写や、行った場所を説明する作文で使う語である。\\n\\n■ 地形\\nmountain（山）／hill（丘）／valley（谷）／river（川）／lake（湖）／pond（池）／sea（海）／ocean（大洋）／beach（浜辺）／island（島）／forest, woods（森）／field（野原・畑）／desert（砂ばく）／waterfall（滝）\\n\\n■ 空・宇宙\\nsky（空）／sun（太陽）／moon（月）／star（星）／cloud（雲）／rainbow（にじ）／Earth（地球）／space（宇宙）\\n\\n■ 自然を説明する\\nWe went to the sea last summer.（去年の夏、海に行きました。）\\nThere are a lot of trees in the forest.（森にはたくさんの木がある。）\\nMt. Fuji is the highest mountain in Japan.（富士山は日本でいちばん高い山だ。）\\nI can see many stars at night.（夜にはたくさんの星が見えます。）\\n\\n★ ポイント：the の使い方に注意する。the sun / the moon / the sky のように一つしかないものには the を付ける。山の名前は Mt. Fuji のように the を付けないが、海や川の名前には the を付ける（the Pacific Ocean、the Shinano River）。\\n\\n⚠ 注意：island の s は発音しない。desert（砂ばく）と dessert（デザート）はつづりも意味もちがうので区別する。\"}],\"trapExamples\":[{\"question\":\"次の語を複数形にしなさい。 leaf\",\"wrongAnswer\":\"leafs\",\"trapExplanation\":\"-s を付けるだけという基本の規則をそのままあてはめてしまう。日本語では「葉」の形が変わらないので、変化に気づくきっかけもない。\",\"correctAnswer\":\"leaves\",\"correctExplanation\":\"-f や -fe で終わる語は、f を v に変えて -es を付ける。leaf → leaves、knife → knives、life → lives、wolf → wolves がその代表である。ただし roof → roofs のように例外もあるので、代表語をセットで覚える。\"},{\"question\":\"「富士山は日本でいちばん高い山です。」を英語にしなさい。\",\"wrongAnswer\":\"The Mt. Fuji is the highest mountain in Japan.\",\"trapExplanation\":\"「いちばん高い」に the を付ける練習をした流れで、山の名前にも the を付けてしまう。the Pacific Ocean のような海の名前を覚えた直後にも起こりやすい。\",\"correctAnswer\":\"Mt. Fuji is the highest mountain in Japan.\",\"correctExplanation\":\"山ひとつの名前には the を付けない（Mt. Fuji、Mt. Everest）。一方、海・川・山脈には the を付ける（the Pacific Ocean、the Shinano River、the Japanese Alps）。最上級の the highest の the は必要なので、そこは落とさない。\"}]}",
"{\"id\":\"eigo_s352\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自然③：天気を表す語と言い方\",\"description\":\"天気の形容詞と名詞の使い分け、天気をたずねる決まり文句を身につける\",\"intro\":\"「今日は晴れです」の主語は何でしょう。日本語には主語がありませんが、英語では It is sunny today. と、天気専用の It を立てます。しかも sunny は形容詞で、sun は名詞。似た形の二語を混同しないところから始めます。\",\"order\":852,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"天気をたずねるのは How is the weather? または What is the weather like?\",\"答えるときの主語は It。It is sunny today.（今日は晴れです。）\",\"形容詞（sunny, rainy, cloudy, snowy, windy）と名詞（sun, rain, cloud, snow, wind）を区別する。\",\"「雨が降る」は動詞 rain も使える。It rains a lot in June.／It is raining now.\",\"気温は It is hot / warm / cool / cold. で表す。\",\"天気の It には「それ」という意味はない。訳さない主語である。\"],\"sections\":[{\"heading\":\"天気を表す語と、たずね方\",\"body\":\"天気の話題はあいさつがわりに使われ、会話問題で頻出する。\\n\\n■ たずね方\\nHow is the weather today?（今日の天気はどうですか。）\\nWhat is the weather like in Tokyo?（東京の天気はどうですか。）\\n※ like は「〜のような」という意味の前置詞。「好き」ではないので注意する。\\n\\n■ 答え方\\nIt is sunny.（晴れです。）／It is cloudy.（くもりです。）／It is rainy.（雨です。）／It is snowy.（雪です。）／It is windy.（風が強いです。）／It is foggy.（きりが出ています。）\\n\\n■ 気温\\nIt is hot.（暑い。）／It is warm.（暖かい。）／It is cool.（すずしい。）／It is cold.（寒い。）／It is humid.（むし暑い。）\\n\\n★ ポイント：この It は「それ」という意味を持たない、天気・気温・時刻・曜日・距離を言うときに使う特別な主語である。日本語に訳さない。\\n例）It is Monday today.（今日は月曜日だ。）／It is seven o'clock.（7時だ。）\\n\\n⚠ 注意：How is the weather? に対して I am sunny. や Today is sunny weather. とは答えない。必ず It is … で答える。\",\"figureId\":\"lf_eigoext10_352\"},{\"heading\":\"形容詞と名詞・動詞の使い分け\",\"body\":\"天気の語には、名詞・形容詞・動詞の三つの形があるものが多い。形を選びまちがえる誤答が非常に多い。\\n\\n■ 名詞と形容詞\\nsun（太陽）→ sunny（晴れた）／rain（雨）→ rainy（雨の）／cloud（雲）→ cloudy（くもった）／snow（雪）→ snowy（雪の）／wind（風）→ windy（風の強い）／fog（きり）→ foggy（きりの深い）\\n\\nbe動詞の後ろに置くのは形容詞のほうである。\\n例）It is rainy today.（○）／It is rain today.（×）\\n\\n■ 名詞の使い方\\nWe had a lot of rain last month.（先月は雨が多かった。）\\nThe snow is deep.（雪が深い。）\\n※ rain・snow は数えられない名詞なので、a rain / rains とはしない。\\n\\n■ 動詞の使い方\\nrain・snow は「雨が降る」「雪が降る」という動詞にもなる。\\nIt rains a lot in June.（6月はよく雨が降る。）← ふだんの習慣なので現在形\\nIt is raining now.（今、雨が降っている。）← 今この瞬間なので進行形\\nIt snowed yesterday.（昨日は雪が降った。）← 過去形\\n\\n★ ポイント：「今降っている」→ It is raining.／「よく降る」→ It rains often. と時制で区別する。三人称単数の it が主語なので、現在形では rains と -s が付く。\",\"mangaId\":\"eigo_s352_xm\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を答えなさい。 How is the weather? — It is （　）. （雨です）\",\"wrongAnswer\":\"rain\",\"trapExplanation\":\"「雨」＝rain と一語で覚えているため、be動詞の後ろにそのまま名詞を置いてしまう。日本語では「雨です」と名詞で答えるので、なおさら気づきにくい。\",\"correctAnswer\":\"rainy\",\"correctExplanation\":\"be動詞の後ろで「どんな状態か」を説明するのは形容詞である。天気を答えるときは sunny・cloudy・rainy・snowy・windy と -y の付いた形容詞を使う。名詞の rain は We had a lot of rain. のように使う。\"},{\"question\":\"「今、雪が降っています。」を英語にしなさい。\",\"wrongAnswer\":\"It snows now.\",\"trapExplanation\":\"「降っています」を現在形で表せると思ってしまう。日本語の「〜ています」が現在形なのか進行形なのか意識できていないのが原因。\",\"correctAnswer\":\"It is snowing now.\",\"correctExplanation\":\"今この瞬間に起きていることは現在進行形（be動詞＋-ing）で表す。It snows now. のような現在形は「ふだんくり返し起こること」を表すので、It snows a lot in Hokkaido.（北海道ではよく雪が降る）のように使う。now があれば進行形と判断する。\"}]}",
"{\"id\":\"eigo_s353\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自然④：季節と一年のうつりかわり\",\"description\":\"四季の語と、季節にまつわる行事・過ごし方の表現を身につける\",\"intro\":\"「秋」を英語で言うとき、fall と autumn のどちらが正しいのでしょうか。答えはどちらも正解で、アメリカでは fall、イギリスでは autumn が使われます。同じ英語でも国によって語が変わる例です。四季の語と使い方をまとめます。\",\"order\":853,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"spring（春）・summer（夏）・fall / autumn（秋）・winter（冬）が四季。\",\"「秋」はアメリカ英語で fall、イギリス英語で autumn。どちらも正解。\",\"季節には in を使う。in spring（春に）／in summer。\",\"「いちばん好きな季節」は My favorite season is spring. が定番。\",\"季節の名前はふつう小文字。月や曜日と混同しない。\",\"「梅雨」は the rainy season。season には the が付く。\"],\"sections\":[{\"heading\":\"四季を表す語と使い方\",\"body\":\"季節を話題にした問題は、英検5級から3級まで幅広く出題される。\\n\\n■ 四季\\nspring（春）／summer（夏）／fall または autumn（秋）／winter（冬）\\n\\n★ ポイント：秋の言い方は二つある。アメリカ英語では fall、イギリス英語では autumn を使う。入試ではどちらを書いても正解になる。fall には「落ちる」という動詞の意味もあり、木の葉が落ちる季節だから fall と呼ばれる。\\n\\n■ 季節と前置詞\\n季節の前には in を使う。\\n例）We have a lot of rain in June.（6月は雨が多い。）\\n例）It is very cold in winter.（冬はとても寒い。）\\n※ in the spring のように the を付ける言い方もあるが、付けないほうがふつう。\\n\\n■ 大文字・小文字\\n月の名前（April）と曜日の名前（Monday）は必ず大文字で始めるが、季節の名前（spring, summer）は文の途中では小文字のままでよい。ここは対比して覚える。\\n\\n■ 特別な季節\\nthe rainy season（梅雨）／the dry season（かんそうした季節）\\n例）The rainy season starts in June in Japan.（日本では梅雨は6月に始まる。）\",\"figureId\":\"lf_eigoext10_353\",\"mangaId\":\"eigo_s353_xm\"},{\"heading\":\"季節ごとの行事と過ごし方\",\"body\":\"「好きな季節とその理由」を書かせる問題は英語入試の定番である。理由まで書けるように、季節ごとの語をそろえておく。\\n\\n■ 春（spring）\\nwarm（暖かい）／cherry blossom（さくらの花）／entrance ceremony（入学式）／picnic（ピクニック）／new school year（新学年）\\n例）I like spring because the cherry blossoms are beautiful.\\n\\n■ 夏（summer）\\nhot（暑い）／summer vacation（夏休み）／swimming（水泳）／fireworks（花火）／festival（祭り）／camping（キャンプ）／beach（浜辺）／watermelon（すいか）\\n例）I like summer because I can swim in the sea.\\n\\n■ 秋（fall / autumn）\\ncool（すずしい）／colored leaves（紅葉）／sports day（運動会）／harvest（収穫）／reading（読書）\\n例）In fall, the leaves turn red and yellow.（秋には葉が赤や黄色に変わる。）\\n\\n■ 冬（winter）\\ncold（寒い）／snow（雪）／skiing（スキー）／New Year's Day（元日）／Christmas（クリスマス）／winter vacation（冬休み）\\n例）I like winter because I can go skiing.\\n\\n★ ポイント：理由を書くときは because を使い、「その季節にできること」を can で書くとまとめやすい。\\n形：I like ＋ 季節 ＋ because I can ＋ 動詞の原形 …．\"}],\"trapExamples\":[{\"question\":\"「冬はとても寒い。」を英語にしなさい。\",\"wrongAnswer\":\"It is very cold on winter.\",\"trapExplanation\":\"曜日や日付で on を使う練習をした流れで、季節にも on を付けてしまう。日本語の「〜は」「〜に」がすべて同じ形なので区別のきっかけがない。\",\"correctAnswer\":\"It is very cold in winter.\",\"correctExplanation\":\"季節・月・年のように幅のある期間には in を使う（in winter、in July、in 2026）。日付・曜日など特定の一日には on（on Monday、on May 5）、時刻には at（at seven）を使う。「広い→in、一日→on、一点→at」と大きさの順で覚える。\"},{\"question\":\"「秋には葉が赤くなります。」の「秋」にあたる英語として正しくないものはどれか。 ［fall / autumn / Fall Season］\",\"wrongAnswer\":\"autumn は誤り（fall だけが正しい）\",\"trapExplanation\":\"教科書で習ったほうだけを正解だと思いこみ、もう一方を誤りだと判断してしまう。アメリカ英語とイギリス英語のちがいだと知らないことが原因。\",\"correctAnswer\":\"fall も autumn も正しい（Fall Season は誤り）\",\"correctExplanation\":\"「秋」はアメリカ英語で fall、イギリス英語で autumn といい、どちらを書いても正解である。ただし季節名は文の途中では小文字で書き、season を付けて Fall Season のようには言わない。The leaves turn red in fall. のように使う。\"}]}",
"{\"id\":\"eigo_s354\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数①：基数の書き方と読み方\",\"description\":\"1から100までの数、大きな数の言い方と、つづりのまちがえやすい数を確認する\",\"intro\":\"thirteen と thirty は、書いても聞いてもまぎらわしい代表です。しかも four は forty になると u が消え、five は fifteen と形を変えます。数はすべての問題の土台なので、つづりの落とし穴をここでつぶしておきます。\",\"order\":854,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"13〜19 は -teen、20〜90 は -ty で終わる。thirteen と thirty を区別する。\",\"つづり注意：four → forty（u が消える）、five → fifteen / fifty、nine → ninth（e が消える。ninety は e が残る）。\",\"21以上はハイフンでつなぐ。twenty-one, thirty-five。\",\"百は hundred、千は thousand。数詞のあとの hundred には -s を付けない（three hundred）。\",\"百の位と十の位の間に and を入れることがある（two hundred and five）。\",\"数を表す語の後ろの名詞は複数形。three books（× three book）。\"],\"sections\":[{\"heading\":\"1から100までの数\",\"body\":\"数の英語は、聞き取り・書き取りの両方で出題される。まずつづりを正確に書けるようにする。\\n\\n■ 1〜12（形がばらばら）\\none, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve\\n\\n■ 13〜19（-teen で終わる）\\nthirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen\\n\\n■ 20〜90（-ty で終わる）\\ntwenty, thirty, forty, fifty, sixty, seventy, eighty, ninety\\n\\n★ ポイント：つづりが元の語から変わるものに注意する。\\nthree → thirteen, thirty（形が大きく変わる）\\nfour → fourteen（u あり）／forty（u が消える！）\\nfive → fifteen, fifty（ve が f に変わる）\\neight → eighteen, eighty（t が一つになる）\\nnine → nineteen, ninety（e は残る）／ninth（e が消える）\\n\\n■ 21以上\\ntwenty-one（21）／thirty-five（35）／forty-eight（48）／ninety-nine（99）\\n※ 十の位と一の位はハイフンでつなぐ。\\n\\n⚠ 注意：thirteen（13）と thirty（30）、fourteen（14）と forty（40）は聞き取りでまちがえやすい。-teen は後ろを強く、-ty は前を強く読む。\"},{\"heading\":\"大きな数の言い方\",\"body\":\"100以上の数は、位ごとに区切って読む。\\n\\n■ 百・千・百万\\nhundred（100）／thousand（1,000）／million（1,000,000）\\n\\n■ 読み方の例\\n100 → one hundred（または a hundred）\\n200 → two hundred\\n305 → three hundred (and) five\\n1,000 → one thousand\\n2,500 → two thousand five hundred\\n1,000,000 → one million\\n\\n★ ポイント：数を表す語のあとの hundred・thousand・million には -s を付けない。\\n例）three hundred students（○）／three hundreds students（×）\\nただし「何百もの」と漠然と言うときだけ hundreds of people（何百人もの人々）と -s と of が付く。\\n\\n■ 年号の読み方\\n1985 → nineteen eighty-five（19と85に分けて読む）\\n2026 → two thousand twenty-six または twenty twenty-six\\n\\n■ 数の後ろの名詞\\n数を表す語のあとの名詞は複数形にする。\\n例）I have three books.／There are twenty students in my class.\\n\\n⚠ 注意：0 の読み方は zero が基本だが、電話番号やスポーツの得点では oh（オー）と読むこともある。\"},{\"heading\":\"なぜ forty に u がなく、hundred に -s が付かないのか\",\"mangaId\":\"eigo_s354_manga\",\"body\":\"13〜19 の -teen は「10 と〜」、20〜90 の -ty は「〜十」という意味の語尾で、もとの数の語にくっついています。くっつくときに音が変わった語は、つづりも変わりました。four は fourteen では u が残りますが、forty では発音が変わって u が消えました。five は fifteen・fifty で ve が f に、three は thirteen・thirty で形が大きく変わります。eight＋teen は t が重なるので一つにします。**ただし nine は nineteen・ninety のどちらも e が残ります**（e が消えるのは ninth）。変わる語だけを名指しで覚えます。\\n\\nthree hundred に -s が付かないのは、数の語（three）が前にあるとき、hundred・thousand・million が**「百」という単位の名前**としてはたらくからです。単位は数えません（三百＝三つの百、と言わない）。「何百もの」と漠然と言うときだけ hundreds of people と -s と of が付きます。数のあとの名詞（students）は複数形です。\\n\\n■ 確かめのしかた\\n①変わる語を名指しで：three→thirteen／thirty、four→fourteen（u あり）／forty（u なし）、five→fifteen／fifty、eight→eighteen／eighty（t 一つ）。nine→nineteen／ninety は e が残る。\\n②-teen は後ろを強く、-ty は前を強く読む。thirteen と thirty の聞き分け。\\n③21以上はハイフン（twenty-one）。数のあとの hundred・thousand に -s を付けない（three hundred students）。漠然とした「何百もの」だけ hundreds of。\\n④数のあとの名詞は複数形（three books）。年号は二けたずつ（nineteen eighty-five）。\\n\\n★ ここがポイント：-teen・-ty がくっついて**音が変わった語だけつづりが変わる**（forty・fifty・thirty）。nine は ninety でも e が残る。数の語のあとの hundred は**単位の名前**なので -s を付けない。\",\"figureId\":\"xf_eigo_s354\"}],\"trapExamples\":[{\"question\":\"数字の 40 を英語のつづりで書きなさい。\",\"wrongAnswer\":\"fourty\",\"trapExplanation\":\"4 が four なので、そのまま -ty を付ければよいと考えてしまう。14 が fourteen と u を残す形なので、よけいに混乱する。\",\"correctAnswer\":\"forty\",\"correctExplanation\":\"40 は four の u が消えて forty になる。14 の fourteen には u が残るので、この二つは必ずセットで確認する。ほかにも five → fifteen / fifty（ve が f に変わる）、nine → ninth（e が消える。ninety は e が残る）が同じ型のひっかけである。\"},{\"question\":\"「私たちの学校には生徒が300人います。」を英語にしなさい。\",\"wrongAnswer\":\"Our school has three hundreds students.\",\"trapExplanation\":\"「300人」と複数だから hundred にも -s を付けるべきだと考えてしまう。students に -s を付ける流れで、そのまま hundred にも付けてしまう。\",\"correctAnswer\":\"Our school has three hundred students.\",\"correctExplanation\":\"数を表す語（three, five など）が前に付くとき、hundred・thousand・million には -s を付けない。-s が付くのは hundreds of students（何百人もの生徒）のように、はっきりした数を言わないときだけである。後ろの名詞 students は複数形にする。\"}]}",
"{\"id\":\"eigo_s355\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数②：序数（〜番目）の作り方\",\"description\":\"順番を表す序数の形と、日付・階・順位での使い方を身につける\",\"intro\":\"「五番目」は fiveth ではなく fifth です。数のことばに th を付けるだけに見えて、一・二・三は形がまったく変わり、five や nine もつづりがくずれます。日付や順位を言うときに必ず使うので、確実にしておきます。\",\"order\":855,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"序数はふつう基数に -th を付ける（four → fourth, six → sixth）。\",\"特別な形：first（1）・second（2）・third（3）。\",\"つづりが変わるもの：five → fifth、nine → ninth、twelve → twelfth、twenty → twentieth。\",\"数字で書くときは 1st, 2nd, 3rd, 4th のように最後の2文字を付ける。\",\"序数の前にはふつう the を付ける（the first day）。\",\"日付・階・順位・何番目かをたずねる文（Which …?）で使う。\"],\"sections\":[{\"heading\":\"序数の作り方\",\"body\":\"「〜番目」を表す語を序数という。日付を言うときに必ず必要になる。\\n\\n■ 特別な形（覚えるしかない）\\none → first（1番目）／two → second（2番目）／three → third（3番目）\\n\\n■ 基本は -th を付ける\\nfour → fourth／six → sixth／seven → seventh／ten → tenth／eleven → eleventh／thirteen → thirteenth\\n\\n■ つづりが変わるもの\\nfive → fifth（ve が f に）／eight → eighth（t は一つのまま、h を足す）／nine → ninth（e が消える）／twelve → twelfth（ve が f に）\\ntwenty → twentieth／thirty → thirtieth（y を ie に変えて -th）\\n\\n■ 21以上\\ntwenty-first（21番目）／twenty-second／twenty-third／thirtieth（30番目）／thirty-first（31番目）\\n※ 最後の位だけを序数にする。\\n\\n■ 数字で書くとき\\n1st, 2nd, 3rd, 4th, 5th … 21st, 22nd, 23rd, 30th, 31st\\n※ つづりの最後の2文字を付ける。first → 1st、second → 2nd、third → 3rd、fourth → 4th。\\n\\n★ ポイント：序数の前にはふつう the を付ける。the first, the second, the third。ただし日付では書き方によって省くことがある。\",\"figureId\":\"lf_eigoext10_355\",\"mangaId\":\"eigo_s355_xm\"},{\"heading\":\"序数を使う場面\",\"body\":\"序数は次の場面で必ず使う。使い方ごとに例文で覚える。\\n\\n■ 日付\\nMay 5（読み方：May fifth）／July 20（July twentieth）\\n※ 書くときは数字だけでよいが、読むときは必ず序数で読む。\\n\\n■ 階\\nOur classroom is on the third floor.（教室は3階です。）\\nThe library is on the first floor.\\n\\n■ 順位・順番\\nHe won first prize.（彼は1等賞をとった。）\\nThis is my second time in Kyoto.（京都に来るのは2回目です。）\\nTake the first street on your right.（1本目の道を右に。）\\n\\n■ 学年・回数\\nHe is in the sixth grade.（彼は6年生です。）\\nThis is the twentieth century.（これは20世紀です。）\\n\\n■ たずね方\\nWhich floor is the music room on?（音楽室は何階ですか。）\\n— It's on the fourth floor.\\n\\n⚠ 注意：ninth（9番目）は nine の e が落ちる。eighth（8番目）は eight に h だけを足すので t が二つ続かない（× eightth）。この二つは書き取りで頻出。\"}],\"trapExamples\":[{\"question\":\"「9番目」を英語のつづりで書きなさい。\",\"wrongAnswer\":\"nineth\",\"trapExplanation\":\"「基数に -th を付ける」という規則をそのままあてはめてしまう。nine のつづりを崩さずに残そうとするのが原因。\",\"correctAnswer\":\"ninth\",\"correctExplanation\":\"nine の e を落として ninth とする。同じようにつづりが変わるものに five → fifth、twelve → twelfth、eight → eighth（t を重ねない）、twenty → twentieth がある。「そのまま -th を付けない語（ninth・fifth・eighth・twelfth・twentieth）」としてまとめて覚える。\"},{\"question\":\"「私の誕生日は6月3日です。」を英語にしなさい（数字を使わずに書く場合の読み方を答える）。\",\"wrongAnswer\":\"My birthday is June three.\",\"trapExplanation\":\"日付の数字をそのまま基数で読んでしまう。日本語では「6月3日」と数をそのまま言うので、序数にする発想が出てこない。\",\"correctAnswer\":\"My birthday is June third.（書くときは June 3）\",\"correctExplanation\":\"日付の「日」は必ず序数で読む。June 3 と書いても読むときは June third となる。同じように May 1 は May first、July 20 は July twentieth と読む。月の名前は大文字で書き始めることも合わせて確認する。\"}]}",
"{\"id\":\"eigo_s356\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"曜日の言い方と一週間\",\"description\":\"曜日の名前とつづり、曜日をたずねる表現、on の使い方を確認する\",\"intro\":\"Wednesday を「ウェドネスデイ」と読んでみると、書けない理由が分かります。発音しない d が入っているからです。曜日は必ず大文字で始めるという決まりもあり、書きまちがえの多いところ。一週間分をまとめて確認します。\",\"order\":856,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"曜日は Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday。\",\"曜日の名前は必ず大文字で書き始める。\",\"Wednesday の d、Tuesday の ue、Thursday の ur はつづりのまちがえやすい部分。\",\"曜日には on を付ける。on Monday（月曜日に）。\",\"「毎週月曜日に」は on Mondays と複数形にする。\",\"「今日は何曜日ですか」は What day is it today? — It is Tuesday.\"],\"sections\":[{\"heading\":\"曜日の名前とつづり\",\"body\":\"曜日は書き取り問題の定番で、つづりのまちがえが非常に多い。\\n\\n■ 七つの曜日\\nSunday（日曜日）／Monday（月曜日）／Tuesday（火曜日）／Wednesday（水曜日）／Thursday（木曜日）／Friday（金曜日）／Saturday（土曜日）\\n\\n■ 短く書く形\\nSun. / Mon. / Tue. / Wed. / Thu. / Fri. / Sat.（ピリオドを付ける）\\n\\n★ ポイント：英語のカレンダーは日曜日から始まる。「週の始まりは日曜日」と覚えておくと、並べかえ問題で迷わない。\\n\\n■ つづりの要注意ポイント\\nWednesday … 発音しない d が入る（ウェンズデイ）。「ウェドネスデイ」と口の中で読みながら書くと覚えやすい。\\nTuesday … ue の順番。Tusday としない。\\nThursday … Thur の ur。Thirsday としない。\\nSaturday … Satur。Satarday としない。\\n\\n■ 大文字\\n曜日・月の名前は文の途中でも必ず大文字で書き始める。\\n例）I play soccer on Saturday.（× on saturday）\\n\\n■ 関連語\\ntoday（今日）／tomorrow（明日）／yesterday（昨日）／the day after tomorrow（あさって）／the day before yesterday（おととい）／weekday（平日）／weekend（週末）／every day（毎日）\",\"figureId\":\"lf_eigoext10_356\"},{\"heading\":\"曜日を使った表現\",\"body\":\"曜日は前置詞 on と結びつく。この組み合わせが問われる。\\n\\n■ 曜日には on\\nI go to swimming school on Monday.（月曜日にスイミングスクールに行きます。）\\nWe don't have school on Sunday.（日曜日は学校がありません。）\\n\\n■ 「毎週〜曜日に」は複数形\\nI play the piano on Wednesdays.（毎週水曜日にピアノをひきます。）\\n= every Wednesday\\n※ every を使うときは on を付けない（× on every Wednesday）。\\n\\n■ たずね方\\nWhat day is it today?（今日は何曜日ですか。）\\n— It is Tuesday (today).\\n※ 主語は It。天気や時刻と同じ、訳さない It である。\\nWhat day of the week is it?（何曜日ですか。）とていねいに言うこともある。\\n\\n■ 日付をたずねる文との区別\\nWhat day is it today? → 曜日をたずねる（It's Friday.）\\nWhat is the date today? → 日付をたずねる（It's May 5.）\\nこの二つは非常にまぎらわしいので、答えの形で区別する。\\n\\n⚠ 注意：weekend（週末）に付ける前置詞は on the weekend（アメリカ英語）または at the weekend（イギリス英語）。\",\"mangaId\":\"eigo_s356_xm\"}],\"trapExamples\":[{\"question\":\"「水曜日」を英語のつづりで書きなさい。\",\"wrongAnswer\":\"Wendsday\",\"trapExplanation\":\"発音が「ウェンズデイ」なので、聞こえたとおりに書いてしまう。d が発音されないため、耳だけで覚えていると必ず落とす。\",\"correctAnswer\":\"Wednesday\",\"correctExplanation\":\"Wednesday には発音しない d が入る。Wed-nes-day と三つに区切り、「ウェド・ネス・デイ」と読みながら書くと覚えやすい。同じように発音とつづりがずれる曜日に Tuesday（Tues-day）、Thursday（Thurs-day）がある。\"},{\"question\":\"「私は毎週土曜日にサッカーをします。」を英語にしなさい。\",\"wrongAnswer\":\"I play soccer on every Saturday.\",\"trapExplanation\":\"「土曜日に」は on Saturday だと覚えているので、every を足すときにも on を残してしまう。日本語では「毎週土曜日に」と「に」が付くので、なおさら前置詞を入れたくなる。\",\"correctAnswer\":\"I play soccer every Saturday.（または on Saturdays）\",\"correctExplanation\":\"every ＋ 曜日・時を表す語には前置詞を付けない（every day、every Sunday、every morning）。同じ意味を on で表すなら on Saturdays と複数形にする。この二つの言い方のどちらかを使い、混ぜないようにする。\"}]}",
"{\"id\":\"eigo_s357\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"月の名前と日付の言い方\",\"description\":\"12か月のつづりと、日付の書き方・読み方、誕生日をたずねる表現を学ぶ\",\"intro\":\"5月5日を英語で書くと May 5 ですが、5／5 のように数字だけにすると危険です。アメリカ式は月から、イギリス式は日から書くので、同じ 3／4 が三月四日にも四月三日にもなってしまいます。月のつづりとあわせて確かめます。\",\"order\":857,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"12か月の名前はすべて大文字で書き始める。\",\"つづり注意：February（r が二つ）、August（gu）、September〜December の -ber。\",\"日付はアメリカ式で「月→日→年」（May 5, 2026）。イギリス式は「日→月→年」。\",\"日は序数で読む（May 5 → May fifth）。\",\"月には in、日付には on を使う。in May／on May 5。\",\"「誕生日はいつですか」は When is your birthday? — It is April 8.\"],\"sections\":[{\"heading\":\"12か月の名前\",\"body\":\"月の名前は、日付・行事・季節の問題すべての土台になる。\\n\\nJanuary（1月）／February（2月）／March（3月）／April（4月）／May（5月）／June（6月）／July（7月）／August（8月）／September（9月）／October（10月）／November（11月）／December（12月）\\n\\n■ 短く書く形\\nJan. / Feb. / Mar. / Apr. / May / Jun. / Jul. / Aug. / Sep. / Oct. / Nov. / Dec.\\n※ May は短くしない（もともと3文字）。\\n\\n★ ポイント：つづりのまちがえやすいところ\\nFebruary … r が二つ入る（Feb-ru-ary）。「フェブルアリー」と読みながら書く。\\nAugust … gu の順。Augast としない。\\nSeptember, October, November, December … すべて -ber で終わる。この四つはまとめて覚える。\\nJanuary … -ary、February … -ruary。\\n\\n■ 大文字\\n月の名前は文の途中でも大文字で始める。\\n例）My birthday is in September.（× in september）\\n\\n⚠ 注意：4月は April で、Apirl と r と i を入れかえる誤りが多い。ゴールデンウィークの「エイプリル」の音から Apr-il と区切って書く。\"},{\"heading\":\"日付の書き方と読み方\",\"body\":\"日付の書き方は、アメリカ式とイギリス式で順番がちがう。中学受験ではアメリカ式で覚えてよい。\\n\\n■ アメリカ式（月→日→年）\\nMay 5, 2026 ／ July 20, 2026\\n読み方：May fifth, twenty twenty-six\\n\\n■ イギリス式（日→月→年）\\n5 May 2026 ／ 20 July 2026\\n読み方：the fifth of May\\n\\n★ ポイント：どちらの書き方でも、日は必ず序数で読む。書くときは 5 と数字だけでよいが、読むときは fifth となる。5th と書いてもよい。\\n\\n■ 前置詞の使い分け\\nin ＋ 月・年・季節：in May／in 2026／in summer\\non ＋ 日付・曜日：on May 5／on Monday\\nat ＋ 時刻：at seven\\n\\n例）I was born in May.（5月生まれです。）\\n例）I was born on May 5.（5月5日生まれです。）\\n※ 月だけなら in、日付まで言うなら on。\\n\\n■ 誕生日の会話\\nWhen is your birthday?（誕生日はいつですか。）\\n— It is April 8.／My birthday is April 8.\\nHow old are you?（何歳ですか。）— I'm twelve (years old).\\n\\n⚠ 注意：日付をたずねる文は What is the date today? である。What day is it today? は曜日をたずねる文なので混同しない。\",\"figureId\":\"xf_eigo_s357\",\"mangaId\":\"eigo_s357_xm\"}],\"trapExamples\":[{\"question\":\"「私の誕生日は9月10日です。」を英語にしなさい。\",\"wrongAnswer\":\"My birthday is in September 10.\",\"trapExplanation\":\"「9月」＝in September と覚えているため、日付が加わっても in を残してしまう。月と日付で前置詞が変わることを意識できていない。\",\"correctAnswer\":\"My birthday is on September 10.（または My birthday is September 10.）\",\"correctExplanation\":\"月だけを言うときは in September、日付まで言うときは on September 10 と on を使う。幅のある期間は in、特定の一日は on、というきまりで判断する。なお be動詞の後ろに直接日付を置く My birthday is September 10. も正しい言い方である。\"},{\"question\":\"「2月」を英語のつづりで書きなさい。\",\"wrongAnswer\":\"Febuary\",\"trapExplanation\":\"発音が「フェブアリー」に近く聞こえるため、r を一つ落としてしまう。January のつづりに引きずられるのも原因。\",\"correctAnswer\":\"February\",\"correctExplanation\":\"February は Feb-ru-ary と三つに区切り、r が二つ入ることを確認して書く。January は -uary、February は -ruary と、似ているようで一字ちがう。August（Augast としない）、April（Apirl としない）と合わせて要注意の月である。\"}]}",
"{\"id\":\"eigo_s358\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時刻の言い方\",\"description\":\"時刻の読み方（o'clock / past / to）と、時間をたずねる表現を身につける\",\"intro\":\"「七時です」を Seven is. とは言えません。英語では時刻を言う文にも主語が必要で、そこに It を置きます。天気のときと同じ、訳さない It です。o'clock を付ける場合と付けない場合のちがいも整理します。\",\"order\":858,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「何時ですか」は What time is it? — It is seven (o'clock).\",\"時刻の主語は It。訳さない特別な主語である。\",\"ちょうどの時刻には o'clock を付けられる（seven o'clock）。分があるときは付けない。\",\"数字を並べる言い方がいちばんかんたん：7:30 → seven thirty。\",\"30分は half past seven、15分は a quarter past seven とも言う。\",\"時刻には at を使う。I get up at six.\"],\"sections\":[{\"heading\":\"時刻の読み方\",\"body\":\"時刻の言い方には二通りある。まず簡単なほうを確実にする。\\n\\n■ ①数字をそのまま並べる（いちばん使いやすい）\\n7:00 → seven／7:05 → seven oh five／7:15 → seven fifteen／7:30 → seven thirty／7:45 → seven forty-five\\n※ 分が10より小さいときは、0 を oh と読んで seven oh five とする。\\n\\n■ ②past と to を使う言い方\\n30分までは past（過ぎ）、30分を過ぎたら to（前）を使う。\\n7:10 → ten past seven（7時を10分過ぎ）\\n7:15 → a quarter past seven（quarter＝4分の1時間＝15分）\\n7:30 → half past seven（half＝半分＝30分）\\n7:45 → a quarter to eight（8時まであと15分）\\n7:50 → ten to eight（8時まであと10分）\\n\\n★ ポイント：to を使う言い方では、後ろの数字が「次の時刻」になる。7:50 は eight（8時）を使って ten to eight と言う。ここを seven と書く誤りが非常に多い。\\n\\n■ o'clock\\nちょうどの時刻にだけ付けられる。\\n例）It is nine o'clock.（9時ちょうどです。）\\n分があるときは付けない（× nine thirty o'clock）。\\n\\n■ 午前・午後\\na.m.（午前）／p.m.（午後）／in the morning／in the afternoon／in the evening／at night\\n例）I get up at six a.m.／School starts at 8:30 in the morning.\",\"figureId\":\"lf_eigoext10_358\"},{\"heading\":\"時刻をたずねる・答える\",\"body\":\"時刻に関する会話は、リスニングでも筆記でも頻出である。\\n\\n■ たずね方\\nWhat time is it (now)?（今、何時ですか。）\\nDo you have the time?（今、何時かわかりますか。）※ ていねいなたずね方\\nWhat time is it in London?（ロンドンは何時ですか。）\\n\\n■ 答え方\\nIt is seven thirty.／It's half past seven.\\n※ 主語は必ず It。天気・曜日・日付と同じ、訳さない主語である。\\n\\n■ 「何時に〜しますか」\\nWhat time do you get up?（何時に起きますか。）\\n— I get up at six thirty.（6時30分に起きます。）\\nWhat time does the movie start?（映画は何時に始まりますか。）\\n— It starts at two.\\n\\n★ ポイント：時刻には前置詞 at を使う。at seven（7時に）／at noon（正午に）／at midnight（真夜中に）。\\n\\n■ 時間に関する語\\nminute（分）／hour（時間）／second（秒）／noon（正午）／midnight（真夜中）／早い・おそい：early / late\\n例）It takes thirty minutes by bus.（バスで30分かかります。）\\n例）Don't be late for school.（学校におくれないように。）\\n\\n⚠ 注意：What time is it? に I am seven. とは答えない。It is seven. である。I am seven. は「私は7歳です」の意味になってしまう。\"},{\"heading\":\"なぜ時刻の主語が It で、なぜ to のあとは次の時刻なのか\",\"mangaId\":\"eigo_s358_manga\",\"body\":\"英語の文には必ず主語が要ります。「七時です」には「何が」にあたる語がないので、天気や曜日と同じく、**訳さない It を主語に置いて形を整えます**。I am seven. と言うと「私は7歳です」になってしまうので、時刻は It is seven. です。o'clock は「〜時ちょうど」を表す語なので、分が付くとき（nine thirty）には付けません。\\n\\npast と to の言い方は、**時計の針の動き**をそのまま言葉にしたものです。30分までは「〇時を過ぎて〇分」なので ten past seven、30分を過ぎたら「次の〇時まであと〇分」と数えるので ten to eight。7:50 を ten to seven と言うと 6:50 の意味になります。to のあとには必ず次の時刻が来る、と覚えます。\\n\\n■ 確かめのしかた\\n①時刻の文の主語は **It**。What time is it?→It is seven.（× I am seven.）\\n②**ちょうどのときだけ o'clock**。It is nine o'clock.／It is nine thirty.（× nine thirty o'clock）\\n③past は30分まで、to は30分過ぎ。**to のあとは次の時刻**：7:45→a quarter to eight、7:50→ten to eight。\\n④時刻には at（at seven／at noon／at midnight）。分が10より小さいときは oh（seven oh five）。\\n\\n★ ここがポイント：時刻の文は**訳さない It が主語**で、o'clock は**ちょうどのときだけ**。to は「次の時刻まであと〇分」なので、**to のあとは次の時刻**（7:50＝ten to eight）。\"}],\"trapExamples\":[{\"question\":\"7:50 を past / to を使った言い方で表しなさい。\",\"wrongAnswer\":\"ten to seven\",\"trapExplanation\":\"「7時50分」の7という数字がそのまま使えると思ってしまう。to が「次の時刻まであと何分」を表すことを理解していないのが原因。\",\"correctAnswer\":\"ten to eight\",\"correctExplanation\":\"to は「〜時まであと…分」という意味なので、後ろには次の時刻を置く。7:50 は8時まであと10分なので ten to eight となる。ten to seven だと 6:50 の意味になってしまう。30分を過ぎたら次の時刻を使う、と覚える。\"},{\"question\":\"「今、9時30分です。」を英語にしなさい。\",\"wrongAnswer\":\"It is nine thirty o'clock.\",\"trapExplanation\":\"「〜時」＝o'clock と覚えているため、分があってもそのまま付けてしまう。o'clock がちょうどの時刻だけに使う語だと知らないことが原因。\",\"correctAnswer\":\"It is nine thirty.（または It is half past nine.）\",\"correctExplanation\":\"o'clock は「ちょうど…時」のときだけ使い、分が付くときには使わない。It is nine o'clock.（9時ちょうど）／It is nine thirty.（9時30分）と書き分ける。past を使うなら half past nine となる。\"}]}",
"{\"id\":\"eigo_s359\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"色を表す語と使い方\",\"description\":\"色の名前と、色をたずねる表現、形容詞としての語順を身につける\",\"intro\":\"「赤いかばん」は a red bag で、a bag red とは言いません。色を表す語は形容詞なので、必ず名詞の前に立つからです。色をたずねる What color is it? という決まった形とあわせて、そのまま使える形で覚えます。\",\"order\":859,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"red・blue・yellow・green・black・white・brown・pink・purple・orange・gray が基本。\",\"「何色ですか」は What color is it? — It is red.\",\"色は形容詞なので名詞の前に置く（a red bag）。名詞の後ろには置かない。\",\"色の語は名詞にもなる。Red is my favorite color.\",\"「濃い・うすい」は dark blue / light blue。\",\"orange は「オレンジ色」と「オレンジ（果物）」の両方の意味を持つ。\"],\"sections\":[{\"heading\":\"色の名前\",\"body\":\"色の語は、持ち物の説明や人物の描写でよく出る。\\n\\n■ 基本の色\\nred（赤）／blue（青）／yellow（黄）／green（緑）／black（黒）／white（白）／brown（茶）／pink（ピンク）／purple（むらさき）／orange（オレンジ）／gray, grey（灰色）／gold（金）／silver（銀）\\n\\n■ 濃さを言う\\ndark blue（濃い青・紺）／light blue（水色）／bright red（あざやかな赤）\\n\\n■ たずね方\\nWhat color is your bag?（かばんは何色ですか。）\\n— It is blue.／It's a blue bag.\\nWhat color do you like?（何色が好きですか。）\\n— I like green best.\\n\\n★ ポイント：color のつづりはアメリカ英語。イギリス英語では colour と書く。入試ではどちらでも正解になるが、教科書に合わせて color と書くのが無難である。\\n\\n⚠ 注意：orange は「オレンジ色の」という形容詞と「オレンジ（果物）」という名詞の両方に使う。an orange bag（オレンジ色のかばん）／an orange（オレンジ1個）。文の中での働きで見分ける。\"},{\"heading\":\"色を使った語順\",\"body\":\"色を表す語は形容詞なので、名詞の前に置く。ここが日本語との大きなちがいである。\\n\\n■ 形容詞は名詞の前\\na red car（赤い車）／white shoes（白いくつ）／a big blue bag（大きな青いかばん）\\n日本語も「赤い車」と前に置くので同じだが、a や the の位置に注意する。\\na red car（○）／red a car（×）\\n\\n■ be動詞の後ろに置く形\\nThis car is red.（この車は赤い。）\\nMy shoes are white.\\n※ このときは名詞を付けない（× This car is a red.）。\\n\\n■ 形容詞を並べる順番\\n数 → 大きさ → 形 → 色 → 材料 → 名詞\\n例）two big round black tables（大きくて丸い黒いテーブル2つ）\\n中学受験では「大きさ→色→名詞」の順（a big red ball）まで覚えておけば十分。\\n\\n■ 色を名詞として使う\\nRed is my favorite color.（赤が私の好きな色です。）\\nMy favorite color is blue.\\n\\n★ ポイント：What color …? の答え方は二通り。It is blue.（色そのものを答える）と It's a blue bag.（名詞ごと答える）のどちらでもよい。\",\"figureId\":\"xf_eigo_s359\",\"mangaId\":\"eigo_s359_xm\"}],\"trapExamples\":[{\"question\":\"「私は赤いかばんを持っています。」を英語にしなさい。\",\"wrongAnswer\":\"I have a bag red.\",\"trapExplanation\":\"「かばん、赤い」と説明を後ろに足す発想や、フランス語などの語順の知識から、形容詞を名詞の後ろに置いてしまう。英語では形容詞は名詞の前が原則。\",\"correctAnswer\":\"I have a red bag.\",\"correctExplanation\":\"英語では形容詞は名詞の前に置く。a red bag、white shoes、a big house となる。a や the はさらにその前に置く（a red bag であって red a bag ではない）。名詞の後ろに置けるのは、This bag is red. のように be動詞を使う形のときだけである。\"},{\"question\":\"（　）に入る語を答えなさい。 What color （　） your shoes? — They are white.\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"What color is …? を決まり文句として覚えているため、後ろの主語の数を確かめずに is にしてしまう。答えの They are white. まで読めば気づける。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"be動詞は主語 your shoes（複数）に合わせて are にする。shoes はいつも複数形で使う語なので、疑問文でも What color are your shoes? となる。答えも They are white. と複数で受ける。単数なら What color is your bag? である。\"}]}",
"{\"id\":\"eigo_s360\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形と大きさを表す語\",\"description\":\"図形の名前と、大小・長短を表す形容詞、比べる言い方を学ぶ\",\"intro\":\"square には「正方形」という名詞と「四角い」という形容詞の両方の使い方があります。一つの語で二つの品詞を持つ語は英語に多く、文の中の位置で見分けます。図形と大きさの語を、比べる言い方まで広げて使いこなします。\",\"order\":860,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"circle（円）・triangle（三角形）・square（正方形）・rectangle（長方形）が図形の基本。\",\"形容詞の形もある：round（丸い）・square（四角い）。\",\"大きさ・長さ：big / small、large / little、long / short、tall / short、high / low。\",\"tall は人や木など縦に細長いもの、high は山や建物など高さのあるものに使う。\",\"比べるときは -er ＋ than（bigger than）、いちばんは the ＋ -est。\",\"つづり注意：big → bigger、large → larger、long → longer。\"],\"sections\":[{\"heading\":\"形を表す語\",\"body\":\"図形の名前は、算数の話題や説明文で出てくる。\\n\\n■ 平面の図形\\ncircle（円）／triangle（三角形）／square（正方形）／rectangle（長方形）／diamond（ひし形）／star（星形）／oval（だ円）／line（線）／point（点）／angle（角）\\n\\n■ 立体\\ncube（立方体）／box（箱）／ball, sphere（球）／cone（円すい）／cylinder（円柱）／pyramid（角すい・ピラミッド）\\n\\n■ 形を表す形容詞\\nround（丸い）／square（四角い）／flat（平らな）／straight（まっすぐな）／curved（曲がった）／thick（厚い・太い）／thin（うすい・細い）／sharp（とがった）\\n\\n例）The moon is round.（月は丸い。）\\n例）This table is square.（このテーブルは四角い。）\\n\\n★ ポイント：square は「正方形」という名詞と「四角い」という形容詞の両方に使える。triangle は名詞だけで、「三角の」は triangular という別の形になる。\\n\\n■ 形をたずねる\\nWhat shape is it?（それはどんな形ですか。）\\n— It is a circle.／It is round.\",\"figureId\":\"lf_eigoext10_360\"},{\"heading\":\"大きさ・長さを表す語と比べ方\",\"body\":\"大小を表す形容詞は、比べる文（比較）でよく問われる。\\n\\n■ 反対の意味の組\\nbig ⇔ small（大きい⇔小さい）／large ⇔ little／long ⇔ short（長い⇔短い）／tall ⇔ short（背が高い⇔低い）／high ⇔ low（高い⇔低い）／wide ⇔ narrow（広い⇔せまい）／heavy ⇔ light（重い⇔軽い）／thick ⇔ thin（厚い⇔うすい）／deep ⇔ shallow（深い⇔浅い）\\n\\n★ ポイント：tall と high の使い分け\\ntall … 人・木・タワーなど、細長く立っているもの\\nhigh … 山・かべ・空など、高さそのものに注目するもの\\n例）He is tall.（彼は背が高い。）／Mt. Fuji is high.／Tokyo Skytree is very tall.\\n\\n■ 比べる言い方\\n比較級：形容詞 ＋ -er ＋ than（〜より…）\\n例）My bag is bigger than yours.（私のかばんはあなたのより大きい。）\\n最上級：the ＋ 形容詞 ＋ -est（いちばん…）\\n例）This is the longest river in Japan.（これは日本でいちばん長い川だ。）\\n\\n■ つづりの変化\\nbig → bigger → biggest（g を重ねる）／large → larger → largest（-r・-st を足すだけ）／heavy → heavier → heaviest（y を i に）／long → longer → longest（そのまま）\\n\\n⚠ 注意：good → better → best、bad → worse → worst は形が大きく変わる。\"},{\"heading\":\"なぜ tall と high を分け、なぜ bigger は g を重ねるのか\",\"mangaId\":\"eigo_s360_manga\",\"body\":\"tall は**細長く立っているものの背の高さ**、high は**地面からの高さそのもの**を表します。人・木・タワーは形が細長いので tall、山・かべ・空は高さに注目するので high。日本語ではどちらも「高い」なので、形をイメージして選びます。反対語も tall⇔short、high⇔low と別の組です。square が名詞（正方形）にも形容詞（四角い）にもなるのは、英語では同じ形の語が文の中の位置で品詞を変えるからで、a square（名詞）と is square（形容詞）を位置で見分けます。\\n\\nbig→bigger で g を重ねるのは、**短母音＋子音字一つ**で終わる語にそのまま -er を付けると、母音の読み方が変わって見えてしまうからです。子音字を重ねて「短い母音のまま」と示します（big→bigger、hot→hotter）。large のように e で終わる語は -r だけ、heavy のように y で終わる語は y を i に変えます。\\n\\n■ 確かめのしかた\\n①「高い」を英語にするとき、**細長く立っているものか、高さそのものか**。人・木・タワー→tall。山・かべ・空→high。\\n②反対の組で確かめる：big⇔small、long⇔short、tall⇔short、high⇔low、wide⇔narrow、heavy⇔light、thick⇔thin、deep⇔shallow。\\n③比較級のつづり：短母音＋子音字一つ→重ねる（bigger・hotter）、e で終わる→-r（larger）、y で終わる→i（heavier）、それ以外→-er（longer）。\\n④good→better→best、bad→worse→worst は形が変わる。形をたずねるのは What shape is it?\\n\\n★ ここがポイント：tall は**細長く立っているもの**、high は**高さそのもの**。比較級は**短母音＋子音字一つなら重ねる**（bigger）、e で終わるなら -r、y は i に。\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 My brother is very （　）. He plays basketball.　［high / tall］\",\"wrongAnswer\":\"high\",\"trapExplanation\":\"日本語ではどちらも「高い」なので、区別せずに high を選んでしまう。「背が高い」を「高い」と直訳する発想が原因。\",\"correctAnswer\":\"tall\",\"correctExplanation\":\"人の背の高さには tall を使う。high は山・建物・かべなど、地面からの高さそのものに注目するときに使う。tall は人・木・タワーのように細長く立っているもの、と覚える。反対語も tall ⇔ short、high ⇔ low と別の組になる。\"},{\"question\":\"「私のかばんはあなたのより大きい。」を英語にしなさい。\",\"wrongAnswer\":\"My bag is biger than yours.\",\"trapExplanation\":\"比較級は -er を付けるという規則だけを覚えていて、つづりの変化に気づかない。日本語で考えているかぎり、子音字を重ねる必要は思いつかない。\",\"correctAnswer\":\"My bag is bigger than yours.\",\"correctExplanation\":\"big のように「短母音＋子音字1字」で終わる語は、最後の子音字を重ねてから -er を付ける（big → bigger、hot → hotter、sad → sadder）。large のように e で終わる語は -r だけを足す（larger）。yours は「あなたのかばん」を一語で表す所有代名詞。\"}]}",
"{\"id\":\"eigo_s361\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数量を表す語（many / much / a few / a little）\",\"description\":\"「多い・少ない」を表す語を、数えられる名詞と数えられない名詞で使い分ける\",\"intro\":\"「たくさんの本」は many books、「たくさんの水」は much water。日本語ではどちらも「たくさん」なのに、英語では数えられるかどうかで語が変わります。a few と a little も同じ理由で分かれます。この線引きを身につけます。\",\"order\":861,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"数えられる名詞には many、数えられない名詞には much を使う。\",\"a lot of / lots of はどちらの名詞にも使える便利な語。\",\"「少しある」は a few（数えられる）／ a little（数えられない）。\",\"「ほとんどない」は few（数えられる）／ little（数えられない）。a の有無で意味が反対になる。\",\"some は肯定文、any は疑問文・否定文で使うのが原則。\",\"すすめる文（Would you like some …?）では疑問文でも some を使う。\"],\"sections\":[{\"heading\":\"many と much、a lot of\",\"body\":\"「たくさんの」を表す語は、後ろの名詞が数えられるかどうかで変わる。\\n\\n■ many ＋ 数えられる名詞の複数形\\nmany books（たくさんの本）／many students／many apples\\n■ much ＋ 数えられない名詞\\nmuch water（たくさんの水）／much money／much time／much snow\\n\\n■ a lot of / lots of ＋ どちらでもよい\\na lot of books（○）／a lot of water（○）\\n※ 迷ったら a lot of を使えば安全である。\\n\\n★ ポイント：ふつうの肯定文では much はあまり使わず、a lot of を使うのが自然。much は否定文・疑問文でよく使う。\\n例）I don't have much time.（時間があまりない。）\\n例）How much water do you drink?（水をどれくらい飲みますか。）\\n\\n■ How many / How much\\nHow many ＋ 複数形（数をたずねる）\\n例）How many pencils do you have?\\nHow much ＋ 数えられない名詞（量をたずねる）\\n例）How much sugar do you need?\\n※ How much is it?（いくらですか。）は値段をたずねる決まり文句。\",\"figureId\":\"lf_eigoext10_361\"},{\"heading\":\"a few と a little、few と little\",\"body\":\"「少し」を表す語も、数えられるかどうかで分かれる。さらに a が付くかどうかで意味が正反対になる。\\n\\n■ 数えられる名詞に使う\\na few ＋ 複数形 …「少しはある（数が2〜3）」プラスの気持ち\\nfew ＋ 複数形 …「ほとんどない」マイナスの気持ち\\n例）I have a few friends here.（ここには友達が何人かいる。）\\n例）I have few friends here.（ここにはほとんど友達がいない。）\\n\\n■ 数えられない名詞に使う\\na little ＋ 数えられない名詞 …「少しはある」\\nlittle ＋ 数えられない名詞 …「ほとんどない」\\n例）There is a little milk in the glass.（コップに牛乳が少し入っている。）\\n例）There is little milk in the glass.（コップに牛乳がほとんどない。）\\n\\n★ ポイント：a が付けば「ある」、a がなければ「ない」。この一語で意味が反対になるので、読み取り問題では必ず a の有無を確認する。\\n\\n■ a little のもう一つの使い方\\na little は「少し」という副詞にもなる。\\n例）I am a little tired.（少しつかれている。）\\n例）Please wait a little.（少し待ってください。）\\n\\n⚠ 注意：little には「小さい」という意味もある（a little dog ＝小さい犬）。後ろが数えられない名詞なら「少しの」、数えられる単数の名詞なら「小さい」と判断する。\",\"mangaId\":\"eigo_s361_xm\"},{\"heading\":\"some と any\",\"body\":\"「いくつかの・いくらかの」を表す some と any は、文の種類で使い分ける。\\n\\n■ 原則\\nsome … 肯定文で使う\\nany … 疑問文・否定文で使う\\n\\n例）I have some questions.（質問がいくつかあります。）\\n例）Do you have any questions?（質問はありますか。）\\n例）I don't have any questions.（質問はありません。）\\n\\n■ 数えられる名詞にも数えられない名詞にも使える\\nsome books／some water／any friends／any money\\n\\n■ 例外：すすめる・たのむときは疑問文でも some\\nWould you like some tea?（お茶はいかがですか。）\\nCan I have some water?（水をもらえますか。）\\n※ 相手が Yes と答えることを期待している文では some を使う。\\n\\n■ any の別の意味\\n肯定文の any は「どんな〜でも」という意味になる。\\n例）Any student can join the club.（どの生徒でもクラブに入れます。）\\n\\n★ ポイント：not any は「一つも〜ない」と全部を打ち消す。no ＋ 名詞 と言いかえられる。\\nI don't have any pens. ＝ I have no pens.\"}],\"trapExamples\":[{\"question\":\"次の英文を日本語にしなさい。 He has few friends in this town.\",\"wrongAnswer\":\"彼はこの町に友達が何人かいる。\",\"trapExplanation\":\"few を a few と同じ意味だと思いこみ、「少しはいる」と訳してしまう。a の一字がないだけなので、読み飛ばすと気づかない。\",\"correctAnswer\":\"彼はこの町にはほとんど友達がいない。\",\"correctExplanation\":\"a few は「少しはある」というプラスの意味、a のない few は「ほとんどない」というマイナスの意味になる。数えられない名詞では a little（少しある）と little（ほとんどない）が同じ関係になる。a の有無を必ず確認する。\"},{\"question\":\"（　）に入る語を選びなさい。 Would you like （　） coffee?　［some / any］\",\"wrongAnswer\":\"any\",\"trapExplanation\":\"「疑問文では any」という規則だけを覚えているため、機械的に any を選んでしまう。すすめる文が例外だと知らないのが原因。\",\"correctAnswer\":\"some\",\"correctExplanation\":\"相手にすすめる文やものをたのむ文では、疑問文でも some を使う（Would you like some tea? / Can I have some water?）。これは相手が Yes と答えることを期待しているためである。ふつうに有無をたずねる Do you have any coffee? では any を使う。\"}]}",
"{\"id\":\"eigo_s362\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"職業を表す語とたずね方\",\"description\":\"職業名の英語と、仕事をたずねる表現・将来の夢の言い方を身につける\",\"intro\":\"「わたしの父は先生です」は My father is teacher. ではなく、a teacher です。英語では職業を言うときに a を付けます。一人だと数えているわけではないのに付ける、この決まりを知らないと減点されます。たずね方までまとめます。\",\"order\":862,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"teacher・doctor・nurse・farmer・cook・driver など、-er / -or で終わる職業名が多い。\",\"職業名には a / an を付ける。He is a doctor.（× He is doctor.）\",\"「仕事は何ですか」は What do you do? または What is your job?\",\"What does your father do? に He is a teacher. と答える。\",\"将来の夢は I want to be a ＋ 職業名. で表す。\",\"「〜で働く」は work at / work for、「〜を教える」は teach。\"],\"sections\":[{\"heading\":\"職業を表す語\",\"body\":\"職業名は英検4級・3級で必ず出る。動詞と結びつけて覚えると忘れにくい。\\n\\n■ -er / -or で終わる職業名（動詞からできたものが多い）\\nteacher（先生。teach＝教える）／singer（歌手。sing）／dancer（ダンサー）／player（選手）／writer（作家。write）／farmer（農家。farm）／driver（運転手。drive）／cook（料理人。cook＝料理する）／baker（パン職人）／actor（俳優）／doctor（医者）／visitor（訪問者）\\n\\n■ そのほかの職業\\nnurse（看護師）／police officer（警察官）／fire fighter（消防士）／pilot（パイロット）／flight attendant（客室乗務員）／scientist（科学者）／engineer（技術者）／dentist（歯科医）／vet（じゅう医）／astronaut（宇宙飛行士）／artist（芸術家）／musician（音楽家）／cartoonist（まんが家）／chef（料理長）／clerk（店員）／office worker（会社員）／soccer player（サッカー選手）\\n\\n★ ポイント：cook は「料理人」という名詞と「料理する」という動詞の両方に使う。「料理する人」を cooker と言ってはいけない。cooker は「調理器具」の意味になってしまう。\\n\\n⚠ 注意：昔は policeman・fireman と男性を表す語を使っていたが、今は police officer・fire fighter と言うのがふつうである。\"},{\"heading\":\"職業についてたずねる・答える\",\"body\":\"職業をたずねる言い方は、いくつかの型を覚えておく。\\n\\n■ たずね方\\nWhat do you do?（お仕事は何ですか。）\\nWhat is your job?\\nWhat does your father do?（お父さんの仕事は何ですか。）\\n※ What do you do? は「あなたはふだん何をしていますか」＝「職業は何ですか」という決まった言い方である。\\n\\n■ 答え方\\nI am a teacher.（私は教師です。）\\nHe is a police officer.\\nShe works at a hospital.（彼女は病院で働いています。）\\nMy mother works for a bank.（母は銀行に勤めています。）\\n\\n★ ポイント：職業名には必ず a / an を付ける。母音で始まる語には an（an actor、an engineer、an artist、an office worker）。\\n\\n■ 将来の夢\\nI want to be a doctor.（医者になりたい。）\\nI want to be a soccer player in the future.（将来サッカー選手になりたい。）\\nMy dream is to be a pilot.（私の夢はパイロットになることです。）\\n※ want の後ろは to ＋ 動詞の原形。be動詞の原形は be である。\\n\\n■ 理由をそえる\\nI want to be a nurse because I want to help sick people.（病気の人を助けたいから看護師になりたい。）\\n\\n⚠ 注意：「〜になる」は become も使えるが、I want to become a doctor. のように to become とする。I want to be … のほうがよく使われる。\",\"figureId\":\"xf_eigo_s362\",\"mangaId\":\"eigo_s362_xm\"}],\"trapExamples\":[{\"question\":\"「私の父は医者です。」を英語にしなさい。\",\"wrongAnswer\":\"My father is doctor.\",\"trapExplanation\":\"日本語には「一人の」にあたる語がないので、a を落としてしまう。名前と同じように職業名をそのまま置いてしまうのが原因。\",\"correctAnswer\":\"My father is a doctor.\",\"correctExplanation\":\"職業を表す名詞は数えられる名詞なので、単数のときは必ず a / an を付ける。母音で始まる語には an を使う（an artist、an engineer）。ただし名前には冠詞を付けない（My name is Ken.）ので、そこと区別する。\"},{\"question\":\"「私は将来、教師になりたい。」を英語にしなさい。\",\"wrongAnswer\":\"I want to a teacher in the future.\",\"trapExplanation\":\"「〜になりたい」＝want to … と覚えているため、to の後ろに動詞を置くことを忘れ、いきなり名詞を続けてしまう。日本語に「である」にあたる動詞が表れないことも原因。\",\"correctAnswer\":\"I want to be a teacher in the future.\",\"correctExplanation\":\"want to の後ろには必ず動詞の原形が必要である。「〜である」を表す be動詞の原形は be なので、I want to be a teacher. となる。am や is を置いて I want to am … としないことも合わせて確認する。\"}]}",
"{\"id\":\"eigo_s363\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"町の建物と施設\",\"description\":\"町にある建物の語と、場所を説明する前置詞・There is の文を使いこなす\",\"intro\":\"「駅へ行く」は go to the station なのに、「学校へ行く」は go to school と the を付けません。建物そのものではなく、勉強するという目的で行く場合は無冠詞になるからです。町の語と冠詞の決まりを合わせて確認します。\",\"order\":863,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"station・hospital・library・post office・bank・park・museum が基本語。\",\"建物には the を付けることが多い（go to the station）。ただし go to school は無冠詞。\",\"位置は near / next to / across from / in front of / between で表す。\",\"「〜の角に」は on the corner of、「〜の向かい」は across from。\",\"「〜がありますか」は Is there a …? / Are there any …? でたずねる。\",\"shop と store はほぼ同じ意味。bookstore（本屋）・bakery（パン屋）など -store / -ery の形も覚える。\"],\"sections\":[{\"heading\":\"町にある建物・施設\",\"body\":\"町の建物の語は、道案内・地図問題で必ず必要になる。\\n\\n■ 公共の建物\\nstation（駅）／post office（郵便局）／bank（銀行）／hospital（病院）／library（図書館）／city hall（市役所）／police station（交番・警察署）／fire station（消防署）／school（学校）／museum（博物館・美術館）／zoo（動物園）／aquarium（水族館）／park（公園）／stadium（競技場）／airport（空港）／temple（寺）／shrine（神社）／church（教会）\\n\\n■ 店\\nsupermarket（スーパー）／convenience store（コンビニ）／bookstore（書店）／bakery（パン屋）／flower shop（花屋）／restaurant（レストラン）／cafe（喫茶店）／hotel（ホテル）／department store（デパート）／drugstore（薬局）／barbershop（理髪店）\\n\\n■ 町の中の語\\nstreet, road（通り）／corner（角）／bridge（橋）／crossing, intersection（交差点）／traffic light（信号）／sidewalk（歩道）／bus stop（バス停）／parking lot（駐車場）\\n\\n★ ポイント：日本語の「マンション」は英語では apartment（アメリカ）や flat（イギリス）という。mansion は「大邸宅」の意味になる。和製英語に注意する。\",\"figureId\":\"lf_eigoext10_363\"},{\"heading\":\"建物の場所を説明する\",\"body\":\"場所を説明するには、位置関係を表す語句が必要である。\\n\\n■ 位置を表す語句\\nnear（〜の近くに）／next to（〜のとなりに）／across from（〜の向かいに）／in front of（〜の前に）／behind（〜の後ろに）／between A and B（AとBの間に）／on the corner of（〜の角に）／around here（この辺りに）\\n\\n例）The post office is next to the bank.（郵便局は銀行のとなりです。）\\n例）The library is across from the station.（図書館は駅の向かいです。）\\n例）There is a park between the school and the hospital.（学校と病院の間に公園があります。）\\n\\n■ あるかどうかたずねる\\nIs there a supermarket near here?（この近くにスーパーはありますか。）\\n— Yes, there is. It's next to the post office.\\nAre there any restaurants around here?（この辺りにレストランはありますか。）\\n\\n■ the の使い方\\n建物を指すときは the を付けることが多い。go to the station／go to the library。\\nただし school・church・bed などは、本来の目的で使うときに冠詞を付けない。\\n例）I go to school by bus.（学校へ通っている）／I go to the school to see my brother.（建物としての学校に行く）\\n\\n⚠ 注意：「駅の前」は in front of the station。「駅前で」を before the station とは言わない。before は時間の「前」に使う。\"},{\"heading\":\"なぜ go to school は the が付かず、なぜ before は場所に使えないのか\",\"mangaId\":\"eigo_s363_manga\",\"body\":\"go to the station は「駅という建物へ行く」ですが、go to school は「勉強しに行く（通学する）」という**目的**を表します。school・church・bed・hospital のような語は、建物ではなく本来の目的（勉強・礼拝・睡眠・治療）で使うときに冠詞を付けません。建物として指すとき（弟に会いに学校の建物へ行く）は go to the school と the を付けます。冠詞の有無で、建物か目的かが分かれます。\\n\\nbefore が場所に使えないのは、before が**時間の「前」**（before dinner）を表す語だからです。場所の「前」は in front of、後ろは behind。日本語ではどちらも「前」なので区別できませんが、英語では時間（before／after）と場所（in front of／behind）で語が分かれています。\\n\\n■ 確かめのしかた\\n①school・church・bed が**目的**なら冠詞なし（go to school／go to bed）、**建物**なら the（go to the school to see my brother）。ふつうの建物は the（go to the station）。\\n②「〜の前」が時間か場所か。時間→before／after。場所→in front of／behind。× before the station。\\n③位置の語：near／next to／across from／between A and B／on the corner of。\\n④There is／There are は**あとの名詞の数**に合わせる。Are there any restaurants 〜?（複数）。マンションは apartment（mansion は大邸宅）。\\n\\n★ ここがポイント：school・bed は**目的なら冠詞なし、建物なら the**。「前」は**時間なら before、場所なら in front of**。There is／are はあとの名詞の数で決める。\"}],\"trapExamples\":[{\"question\":\"「郵便局は駅の前にあります。」を英語にしなさい。\",\"wrongAnswer\":\"The post office is before the station.\",\"trapExplanation\":\"before を「〜の前」とだけ覚えているため、場所にも使えると考えてしまう。日本語では時間の「前」も場所の「前」も同じ語なので区別できない。\",\"correctAnswer\":\"The post office is in front of the station.\",\"correctExplanation\":\"before は「〜より前に」という時間を表す語である（before dinner＝夕食前に）。場所の「〜の前に」は in front of を使う。反対の「〜の後ろに」は behind。時間なら before / after、場所なら in front of / behind と対にして覚える。\"},{\"question\":\"（　）に入る語を答えなさい。 （　） there any restaurants near here?\",\"wrongAnswer\":\"Is\",\"trapExplanation\":\"Is there …? を決まり文句として覚えていると、後ろの名詞が複数でも Is のまま書いてしまう。any が付いていることも見落としやすい。\",\"correctAnswer\":\"Are\",\"correctExplanation\":\"be動詞は後ろに来る名詞の数に合わせる。restaurants と複数なので Are there any restaurants …? となる。答えも Yes, there are. / No, there aren't. と複数で受ける。単数なら Is there a restaurant …? である。\"}]}",
"{\"id\":\"eigo_s364\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"乗り物と交通手段の言い方\",\"description\":\"乗り物の語と、by bus / on foot などの交通手段の表し方を身につける\",\"intro\":\"「バスで行く」は by bus で、a も the も付けません。ところが「歩いて」は by walk とは言えず、on foot です。交通手段の言い方には決まった形があり、そのまま覚えるのが近道。乗り物の語とセットで固めます。\",\"order\":864,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"bus・train・car・bike・taxi・plane・ship・subway が基本語。\",\"交通手段は by ＋ 乗り物（冠詞なし）。by bus, by train, by car。\",\"「歩いて」は on foot。by walk とは言わない。\",\"「〜に乗る」は take a bus / get on、「〜から降りる」は get off。\",\"「どうやって学校へ行きますか」は How do you go to school?\",\"「時間がかかる」は It takes ＋ 時間。It takes ten minutes by bike.\"],\"sections\":[{\"heading\":\"乗り物の語と交通手段の表し方\",\"mangaId\":\"eigo_s364_manga\",\"body\":\"通学や旅行の話題では、乗り物の語と by の使い方が問われる。\\n\\n■ 乗り物\\nbus（バス）／train（電車）／subway（地下鉄）／car（車）／taxi（タクシー）／bike, bicycle（自転車）／motorcycle（バイク）／plane, airplane（飛行機）／ship, boat（船）／truck（トラック）／ambulance（救急車）\\n\\n■ 交通手段は by ＋ 乗り物\\nby bus（バスで）／by train（電車で）／by car（車で）／by bike（自転車で）／by plane（飛行機で）／by taxi（タクシーで）\\n\\n★ ポイント：by の後ろの乗り物には a も the も付けない。\\n例）I go to school by bus.（○）／by a bus（×）／by the bus（×）\\n\\n■ 「歩いて」は on foot\\n例）I go to school on foot.（歩いて学校に行きます。）\\n= I walk to school.\\n※ by walk とは絶対に言わない。foot は単数形のままである。\\n\\n■ 特定の乗り物を言うときは in / on\\nin a car（車の中に）／in a taxi／on a bus／on a train／on a bike\\n※ 屋根のある小さな乗り物には in、立てるほど大きい乗り物や またがる乗り物には on を使う。\\n\\n例）I met him on the train.（電車の中で彼に会った。）\\n例）She got in the car.（彼女は車に乗り込んだ。）\"},{\"heading\":\"乗り降りと所要時間\",\"body\":\"乗り物にまつわる動詞と、時間の言い方をまとめる。\\n\\n■ 乗る・降りる\\ntake a bus（バスに乗る＝バスを利用する）\\nget on the bus（バスに乗り込む）⇔ get off the bus（バスを降りる）\\nget in the car（車に乗り込む）⇔ get out of the car（車から降りる）\\nride a bike（自転車に乗る）／drive a car（車を運転する）\\nchange trains（電車を乗りかえる）※ trains と複数形にする\\n\\n例）Take the No. 5 bus.（5番のバスに乗ってください。）\\n例）Get off at the third stop.（3つ目のバス停で降りてください。）\\n\\n■ 時間・距離をたずねる\\nHow do you go to school?（どうやって学校へ行きますか。）\\n— I go to school by bike.／I walk to school.\\nHow long does it take?（どれくらい時間がかかりますか。）\\n— It takes about twenty minutes.（20分ほどかかります。）\\nHow far is it from here to the station?（ここから駅までどれくらいですか。）\\n— It's about one kilometer.\\n\\n★ ポイント：時間がかかることを表す It takes … の主語は It。この It も訳さない主語である。\\n例）It takes ten minutes by bike.（自転車で10分かかる。）\\n\\n⚠ 注意：get on は「大きい乗り物・またがる乗り物」に、get in は「車・タクシー」に使う。\"},{\"heading\":\"なぜ by bus には冠詞が付かず、なぜ「歩いて」は on foot なのか\",\"mangaId\":\"eigo_s364_bybus_manga\",\"body\":\"by bus の bus は、**特定のバス（あのバス）ではなく「バスという手段」**を表しています。手段として言うときは、どのバスかは問題にしないので、a も the も付けません。特定の乗り物の中にいることを言うときは、in a car・on the train のように in／on と冠詞を使います。「歩いて」が on foot なのは、walk が動詞であって乗り物の名前ではないからです。by のあとに置けるのは乗り物の名前だけで、足（foot）を使う手段は on foot という決まった形になります。\\n\\nget on と get in を分けるのは、乗り物の**大きさと形**によります。バス・電車のように中で立てる乗り物、自転車のようにまたがる乗り物には on、車・タクシーのように屋根のある小さな乗り物には in。降りるときも get off／get out of と対になります。\\n\\n■ 確かめのしかた\\n①**手段**なら by＋乗り物（冠詞なし）：by bus／by train／by bike。× by a bus。**特定の乗り物の中**なら on the train／in a taxi。\\n②「歩いて」→on foot（× by walk、× on feet）。または I walk to school.\\n③乗る・降りる：get on／get off（バス・電車・自転車）、get in／get out of（車・タクシー）。乗りかえは change trains（複数形）。\\n④「時間がかかる」の主語は It：It takes twenty minutes by bike. たずね方は How do you go to 〜?／How long does it take?\\n\\n★ ここがポイント：by bus は**手段**なので冠詞なし、特定の乗り物の中は on／in。「歩いて」は乗り物ではないので **on foot**。乗り物の大きさで get on／get in を分ける。\",\"figureId\":\"xf_eigo_s364\"}],\"trapExamples\":[{\"question\":\"「私は歩いて学校に行きます。」を英語にしなさい。\",\"wrongAnswer\":\"I go to school by walk.\",\"trapExplanation\":\"by bus / by train と同じ形で交通手段を表せると考え、「歩く」も by の後ろに置いてしまう。walk が動詞であることも見落としている。\",\"correctAnswer\":\"I go to school on foot.（または I walk to school.）\",\"correctExplanation\":\"「歩いて」は on foot という決まった言い方で、by walk とは言わない。foot は単数形のままにする（× on feet）。もっとかんたんに I walk to school. と動詞 walk を使ってもよい。by の後ろに置けるのは乗り物の名前だけである。\"},{\"question\":\"「私は毎日バスで学校に行きます。」を英語にしなさい。\",\"wrongAnswer\":\"I go to school by a bus every day.\",\"trapExplanation\":\"数えられる名詞には a を付けるという規則を、by の後ろにもあてはめてしまう。日本語の「バスで」には冠詞にあたる語がないため確認しにくい。\",\"correctAnswer\":\"I go to school by bus every day.\",\"correctExplanation\":\"交通手段を表す by ＋ 乗り物には冠詞を付けない（by bus、by train、by car、by bike）。特定のバスを指すときだけ on the bus のように on / in を使う。「歩いて」だけは by ではなく on foot になることも合わせて覚える。\"}]}",
"{\"id\":\"eigo_s365\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"町・職業・乗り物の総合演習\",\"description\":\"ここまでの語彙を使い、自分の町を紹介する文章の型を身につける\",\"intro\":\"自分の町を英語で紹介するとしたら、何から書きますか。場所、あるもの、できること、そして自分の気持ち——この順に並べると、それだけで立派な紹介文になります。ここまでに覚えた語彙を、書く力に変えていきます。\",\"order\":865,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"町の紹介は「①どこにあるか ②何があるか ③何ができるか ④気持ち」の順で書く。\",\"「〜がある」は There is / There are、「〜で有名だ」は be famous for。\",\"「〜することができる」は You can ＋ 動詞の原形。\",\"「私の町には〜がある」は My town has … とも言える。\",\"文と文は and / but / so / because でつなぐ。\",\"一文を短くし、主語と動詞をはっきりさせると減点されにくい。\"],\"sections\":[{\"heading\":\"自分の町を紹介する型\",\"body\":\"英語入試では「あなたの町を紹介しなさい」という自由英作文がよく出る。次の四つの順で書けば必ずまとまる。\\n\\n■ ①どこにあるか\\nI live in Osaka.（大阪に住んでいます。）\\nMy town is near Tokyo.（私の町は東京の近くです。）\\nIt is a small town in Nara.（奈良にある小さな町です。）\\n\\n■ ②何があるか\\nThere are two parks in my town.（町には公園が二つあります。）\\nWe have a big library near the station.（駅の近くに大きな図書館があります。）\\nMy town is famous for its old temple.（私の町は古いお寺で有名です。）\\n\\n■ ③そこで何ができるか\\nYou can enjoy beautiful flowers in spring.（春には美しい花が楽しめます。）\\nYou can eat delicious noodles there.（そこでおいしいめん類が食べられます。）\\n\\n■ ④気持ち・まとめ\\nI like my town very much.（私は自分の町がとても好きです。）\\nPlease come and visit us.（ぜひ来てください。）\\n\\n★ ポイント：文をつなぐ語を使うと、英語らしい流れになる。and（そして）／but（しかし）／so（だから）／because（なぜなら）\\n例）My town is small, but it is very beautiful.\",\"figureId\":\"xf_eigo_s365\"},{\"heading\":\"人と場所を組み合わせて書く\",\"body\":\"職業・建物・乗り物の語をまとめて使う練習をする。\\n\\n■ 人と働く場所\\nA doctor works at a hospital.（医者は病院で働く。）\\nA teacher works at a school.\\nA police officer works at a police station.\\nA cook works at a restaurant.\\n※ 「〜で働く」は work at ＋ 場所、「〜の会社に勤める」は work for ＋ 会社名。\\n\\n■ 場所と、そこでできること\\nWe can borrow books at the library.（図書館で本を借りられる。）\\nWe can see many animals at the zoo.\\nWe can buy stamps at the post office.（郵便局で切手が買える。）\\nWe can send letters at the post office.\\n\\n■ 行き方を加える\\nI go to the library by bike. It takes ten minutes.\\n（自転車で図書館に行きます。10分かかります。）\\n\\n⚠ 注意：三人称単数が主語のときは動詞に -s を付ける（A doctor works …）。複数なら付けない（Doctors work …）。自由英作文でいちばん多い減点箇所なので、書き終えたら必ず見直す。\",\"mangaId\":\"eigo_s365_xm\"}],\"trapExamples\":[{\"question\":\"「私の町には大きな公園が二つあります。」を英語にしなさい。\",\"wrongAnswer\":\"My town has two big park.\",\"trapExplanation\":\"two と数を書いたことで満足してしまい、名詞を複数形にするのを忘れる。日本語では数を言っても名詞の形が変わらないため気づきにくい。\",\"correctAnswer\":\"My town has two big parks.（または There are two big parks in my town.）\",\"correctExplanation\":\"二つ以上を表す数の後ろでは、名詞を必ず複数形にする（two parks、three books）。There are を使う形なら There are two big parks in my town. となり、be動詞も複数の are にする。数・名詞の形・動詞の形の三つをそろえる。\"},{\"question\":\"（　）に入る語を答えなさい。 A doctor （　） at a hospital.\",\"wrongAnswer\":\"work\",\"trapExplanation\":\"A doctor を「医者というもの一般」ととらえ、複数の感覚で動詞に -s を付けない。日本語では動詞が主語によって変わらないため、確認する習慣がないと落とす。\",\"correctAnswer\":\"works\",\"correctExplanation\":\"A doctor は三人称単数なので、現在形の動詞には -s を付けて works とする。複数形の Doctors work at hospitals. なら -s は付けない。英作文では書き終えたあとに「主語は三人称単数か」「動詞に -s があるか」を必ず確認する。\"}]}",
"{\"id\":\"eigo_s366\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語①：get を使う表現\",\"description\":\"get の基本の意味と、get up / get to / get on などの熟語を整理する\",\"intro\":\"get は「手に入れる」と覚えている人が多いのですが、get up も get to も get on も同じ get です。中心にあるのは、ある状態や場所にたどりつくという感じ。この一つのイメージから、熟語を枝分かれさせて整理します。\",\"order\":866,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"get の中心の意味は「手に入れる」と「（ある状態・場所に）たどりつく」。\",\"get up（起きる）／get to ＋ 場所（〜に着く）／get on ⇔ get off（乗る⇔降りる）。\",\"get to the station には to が必要。arrive at と同じ意味。\",\"get home / get there には to を付けない。\",\"get ＋ 形容詞 で「〜になる」。get angry（怒る）／get better（よくなる）。\",\"get の過去形・過去分詞は got。got up、got to のように使う。\"],\"sections\":[{\"heading\":\"get の中心の意味\",\"body\":\"get は英語でもっともよく使われる動詞の一つで、たくさんの意味を持つ。ばらばらに覚えるのではなく、中心の意味からつかむ。\\n\\n■ ①手に入れる・もらう\\nI got a new bike for my birthday.（誕生日に新しい自転車をもらった。）\\nWhere did you get that book?（その本はどこで手に入れたの。）\\n\\n■ ②（場所に）たどりつく\\nI get to school at eight.（8時に学校に着く。）\\nWhat time did you get home?（何時に家に着きましたか。）\\n※ get to ＋ 場所。ただし home・there・here には to を付けない。\\n\\n■ ③（状態に）なる\\nget ＋ 形容詞 で「〜の状態になる」という変化を表す。\\nIt is getting dark.（暗くなってきた。）\\nShe got angry.（彼女は怒った。）\\nI got tired.（つかれた。）\\nMy father got sick last week.（父は先週病気になった。）\\n\\n★ ポイント：be動詞は「〜である」という状態、get は「〜になる」という変化を表す。\\nHe is angry.（怒っている）／He got angry.（怒った＝怒った状態になった）\\n\\n■ 過去形\\nget の過去形は got。過去分詞もアメリカ英語では gotten も使うが、中学受験では got を覚えておけばよい。\",\"figureId\":\"xf_eigo_s366\"},{\"heading\":\"get を使う重要熟語\",\"body\":\"熟語はまとまりで、例文ごと覚える。\\n\\n■ get up（起きる・起き上がる）\\nI get up at six every morning.（毎朝6時に起きます。）\\n※ wake up は「目が覚める」、get up は「起き上がる」。I wake up at six, but I get up at six thirty. のように使い分ける。\\n\\n■ get to ＋ 場所（〜に着く）\\nHow can I get to the station?（駅にはどう行けばよいですか。）← 道をたずねる決まり文句\\nWe got to the museum at ten.\\n＝ We arrived at the museum at ten.／We reached the museum at ten.\\n※ arrive には at / in が必要、reach には前置詞が不要。\\n\\n■ get on ⇔ get off（乗る⇔降りる）\\nGet on the bus at the next stop.／Get off at Osaka Station.\\n\\n■ get in ⇔ get out of（車に乗る⇔降りる）\\nHe got in the taxi.／She got out of the car.\\n\\n■ そのほか\\nget together（集まる）／get well（よくなる）／get married（結婚する）／get lost（道に迷う）\\n\\n★ ポイント：How can I get to …? は道案内の問題で必ず出る。丸ごと暗記する。\",\"mangaId\":\"eigo_s366_xm\"}],\"trapExamples\":[{\"question\":\"「私は毎朝6時に起きます。」を英語にしなさい。\",\"wrongAnswer\":\"I get up in six every morning.\",\"trapExplanation\":\"in the morning という言い方を覚えているため、時刻にも in を使ってしまう。「6時に」の「に」をどの前置詞で表すか判断できていない。\",\"correctAnswer\":\"I get up at six every morning.\",\"correctExplanation\":\"時刻には at を使う（at six、at 7:30、at noon）。in を使うのは in the morning、in April、in 2026 のように幅のある時間である。every morning には前置詞を付けないことも合わせて確認する。\"},{\"question\":\"「駅にはどう行けばよいですか。」を英語にしなさい。\",\"wrongAnswer\":\"How can I get the station?\",\"trapExplanation\":\"get を「行く・着く」と覚えていると、後ろに場所をそのまま続けてしまう。日本語の「駅に行く」の「に」が to にあたることに気づかない。\",\"correctAnswer\":\"How can I get to the station?\",\"correctExplanation\":\"「〜に着く」の意味の get には必ず to が必要である（get to the station、get to school）。ただし home・there・here は方向の意味を含むので to を付けない（get home、get there）。to のいらない reach（reach the station）と比べて整理する。\"}]}",
"{\"id\":\"eigo_s367\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語②：take を使う表現\",\"description\":\"take の基本の意味と、take a bath / take care of / It takes … の使い方を学ぶ\",\"intro\":\"take a bath は「風呂を取る」ではなく「風呂に入る」、take a walk は「散歩する」です。手に取るという動作から広がって、take は多くの決まり文句を作ります。時間がかかることを表す It takes … の形まで確かめます。\",\"order\":867,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"take の中心の意味は「手に取る・持っていく」。\",\"take a bath（風呂に入る）／take a picture（写真をとる）／take a walk（散歩する）。\",\"take care of ＝ look after（〜の世話をする）。\",\"「時間がかかる」は It takes ＋ 時間（＋ to ＋ 動詞の原形）。\",\"take a bus（バスを利用する）／take off（ぬぐ・離陸する）。\",\"take の過去形は took、過去分詞は taken。\"],\"sections\":[{\"heading\":\"take の中心の意味と熟語\",\"body\":\"take は「手に取る」が中心の意味である。そこから「持っていく」「利用する」「（時間を）とる」と広がる。\\n\\n■ ①手に取る・持っていく\\nTake this umbrella with you.（このかさを持っていきなさい。）\\nDon't forget to take your lunch.（弁当を持っていくのを忘れないで。）\\n\\n■ ②「する」にあたる決まり文句\\ntake a bath（ふろに入る）／take a shower（シャワーをあびる）／take a picture, take a photo（写真をとる）／take a walk（散歩する）／take a rest, take a break（休けいする）／take a look（見てみる）／take a seat（席につく）／take a test（テストを受ける）／take a lesson（レッスンを受ける）\\n\\n例）I take a bath before dinner.（夕食前にふろに入ります。）\\n例）May I take a picture here?（ここで写真をとってもいいですか。）\\n\\n■ ③乗り物を利用する\\nTake the No. 3 bus.（3番のバスに乗りなさい。）\\nI take the train to school.（電車で通学しています。）\\n\\n■ ④世話をする\\ntake care of ＝ look after\\n例）I take care of my dog every day.（毎日犬の世話をします。）\\n例）Please take care of yourself.（お体を大切に。）\\n\\n⚠ 注意：take a picture は「写真をとる」。「絵をかく」は draw a picture である。同じ a picture でも動詞がちがう。\"},{\"heading\":\"It takes … の形と take off\",\"body\":\"時間を表す take は入試頻出である。形をきちんと覚える。\\n\\n■ It takes ＋ 時間\\nIt takes ten minutes.（10分かかります。）\\nIt takes about an hour by train.（電車で1時間ほどかかります。）\\n※ 主語は訳さない It。\\n\\n■ It takes ＋ 人 ＋ 時間 ＋ to ＋ 動詞の原形\\nIt takes me twenty minutes to go to school.（学校に行くのに20分かかります。）\\nIt took him two hours to finish the work.（彼はその仕事を終えるのに2時間かかった。）\\n\\n■ How long does it take?\\nHow long does it take from here to the station?（ここから駅までどれくらいかかりますか。）\\n— It takes about ten minutes on foot.（歩いて10分ほどです。）\\n\\n★ ポイント：「（お金が）かかる」は take ではなく cost を使う。\\n例）It costs 500 yen.（500円かかる。）\\n\\n■ take off\\n①（服・くつを）ぬぐ：Take off your shoes.（くつをぬぎなさい。）⇔ put on\\n②（飛行機が）離陸する：The plane took off at nine.（飛行機は9時に離陸した。）\\n\\n■ そのほか\\ntake part in（〜に参加する）／take out（取り出す・持ち帰る）／take away（持ち去る）\\n例）I took part in the speech contest.（スピーチコンテストに参加した。）\"},{\"heading\":\"なぜ take が「する」を表し、なぜ時間の主語が It なのか\",\"mangaId\":\"eigo_s367_manga\",\"body\":\"take の中心の意味は「手に取る」です。そこから「（機会や行動を）取る」に広がり、take a bath（入浴という行動を取る）、take a walk（散歩を取る）、take a picture（写真を取る）のように、**名詞で表した行動を「取る＝する」**と言えるようになりました。take a bus は「バスという手段を取る」、take care of は「世話という役目を引き受ける」です。だから日本語の「する」から do を選ばず、take ＋ 名詞のかたまりで覚えます。\\n\\n「時間がかかる」の主語が It なのは、時刻や天気と同じで**「何が」にあたる語がない**からです。「私は20分かかる」と日本語で言えても、英語では時間を取るのは「私」ではなく状況なので、It takes twenty minutes. とし、人を入れるなら It takes me twenty minutes to 〜 の形にします。お金がかかるときは take ではなく cost を使います。\\n\\n■ 確かめのしかた\\n①take＋名詞のかたまりで言えるか：take a bath／shower／picture／walk／rest／seat／test。「絵をかく」は draw a picture。\\n②take care of＝look after。「世話をする」の「する」を do にしていないか。\\n③時間がかかる→主語は **It**：It takes＋時間、It takes＋人＋時間＋to＋原形。× I take twenty minutes to school。\\n④お金→cost（It costs 500 yen.）。take off（ぬぐ・離陸する）⇔ put on。take part in（参加する）。過去形 took、過去分詞 taken。\\n\\n★ ここがポイント：take は「手に取る」から**「行動を取る＝する」**に広がった動詞なので、take＋名詞のかたまりで覚える。時間がかかる文は**「何が」がないので It が主語**、お金は cost。\",\"figureId\":\"xf_eigo_s367\"}],\"trapExamples\":[{\"question\":\"「学校まで歩いて20分かかります。」を英語にしなさい。\",\"wrongAnswer\":\"I take twenty minutes to school on foot.\",\"trapExplanation\":\"日本語の「（私は）20分かかる」に引きずられて、主語を I にしてしまう。時間を表す文の主語が It になることを知らないと必ず起こる。\",\"correctAnswer\":\"It takes twenty minutes to get to school on foot.（または It takes me twenty minutes to walk to school.）\",\"correctExplanation\":\"時間がかかることを表す文の主語は、訳さない It にする。It takes ＋ 時間、人を入れるなら It takes ＋ 人 ＋ 時間 ＋ to ＋ 動詞の原形。天気・時刻・曜日の It と同じ仲間である。\"},{\"question\":\"（　）に入る語を選びなさい。 I will （　） care of your cat while you are away.　［take / do］\",\"wrongAnswer\":\"do\",\"trapExplanation\":\"「世話をする」の「する」を do だと考えてしまう。熟語をまとまりで覚えず、日本語の動詞から英語を選ぼうとするのが原因。\",\"correctAnswer\":\"take\",\"correctExplanation\":\"「〜の世話をする」は take care of というまとまりで覚える。同じ意味の look after と言いかえられる。熟語は日本語から一語ずつ置きかえるのではなく、take care of / look after のようにひとかたまりで暗記する。\"}]}",
"{\"id\":\"eigo_s368\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語③：make と have を使う表現\",\"description\":\"make（作る・〜にする）と have（持つ・食べる・ある）の広い意味を整理する\",\"intro\":\"The news made me happy. を「そのニュースはわたしを幸せに作った」と訳すと変です。make には「〜の状態にする」という使い方があるからです。have も「持つ」だけでは足りません。二つの動詞の意味の広がりを見ます。\",\"order\":868,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"make の中心は「作る・作り出す」。make a cake／make friends（友達になる）。\",\"make ＋ 人 ＋ 形容詞 で「人を〜にする」。The news made me happy.\",\"be made of（材料が見てわかる）／be made from（見てわからない）。\",\"have の中心は「持っている」。そこから「食べる・飲む」「（行事が）ある」に広がる。\",\"have a good time（楽しく過ごす）／have a cold（かぜをひく）。\",\"have to ＋ 動詞の原形 で「〜しなければならない」。三単現は has to。\"],\"sections\":[{\"heading\":\"make を使う表現\",\"body\":\"make は「何かを作り出す」が中心の意味である。\\n\\n■ ①作る\\nMy mother makes breakfast every morning.（母は毎朝、朝食を作る。）\\nI made a birthday card for my friend.（友達に誕生日カードを作った。）\\n\\n■ ②make ＋ 人・物 ＋ 形容詞（〜を…にする）\\nThe news made me happy.（その知らせは私をうれしくさせた＝それを聞いてうれしかった。）\\nMusic makes us happy.\\nThis makes me sad.\\n\\n■ ③熟語\\nmake friends (with)（（〜と）友達になる）※ friends と複数形にする\\nmake a mistake（まちがえる）\\nmake a speech（スピーチをする）\\nmake a plan（計画を立てる）\\nmake a noise（音を立てる）\\nmake up one's mind（決心する）\\n\\n例）I made friends with a girl from Canada.（カナダから来た女の子と友達になった。）\\n\\n■ ④材料を言う\\nbe made of ＋ 材料（見て何からできているかわかる）\\n例）This desk is made of wood.（この机は木でできている。）\\nbe made from ＋ 材料（見てもわからない・形が変わっている）\\n例）Cheese is made from milk.（チーズは牛乳から作られる。）\\nbe made in ＋ 場所（〜製）\\n例）This car was made in Japan.\\n\\n★ ポイント：of と from の区別は入試頻出。「見た目で材料がわかるか」で判断する。\",\"figureId\":\"xf_eigo_s368\",\"mangaId\":\"eigo_s368_xm\"},{\"heading\":\"have を使う表現\",\"body\":\"have は「持っている」が中心だが、日本語の「持つ」よりはるかに広く使う。\\n\\n■ ①持っている・飼っている\\nI have two dogs.（犬を2ひき飼っている。）\\nDo you have a pen?\\n\\n■ ②食べる・飲む\\nI have breakfast at seven.（7時に朝食を食べる。）\\nLet's have lunch together.\\nWould you like to have some tea?\\n※ eat / drink の代わりに使える便利な語。\\n\\n■ ③（行事・授業が）ある\\nWe have a sports day in October.\\nWe have four classes in the morning.\\nI have a piano lesson on Saturdays.\\n\\n■ ④病気・状態\\nI have a cold.（かぜをひいている。）／I have a headache.／I have a fever.\\n\\n■ ⑤熟語\\nhave a good time（楽しい時をすごす）／have a party（パーティーを開く）／have fun（楽しむ）／have no idea（わからない）\\n\\n例）We had a good time at the party.（パーティーで楽しくすごした。）\\n\\n■ ⑥have to（〜しなければならない）\\nI have to do my homework.（宿題をしなければならない。）\\nHe has to go now.（彼はもう行かなければならない。）※ 三人称単数は has to\\n否定は don't have to（〜しなくてよい）。must not（〜してはいけない）と意味がちがうので注意する。\\n\\n⚠ 注意：have の過去形は had。「持っていた・食べた・あった」すべて had になる。\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 Butter is made （　） milk.　［of / from］\",\"wrongAnswer\":\"of\",\"trapExplanation\":\"be made of を先に習うため、材料と聞くと反射的に of を選んでしまう。牛乳とバターでは見た目がまったく変わることに注意が向かない。\",\"correctAnswer\":\"from\",\"correctExplanation\":\"材料が見た目でわかるときは be made of（This desk is made of wood.）、加工されて見た目が変わり材料がわからないときは be made from（Butter is made from milk. / Wine is made from grapes.）を使う。もとの形が残っているかどうかで判断する。\"},{\"question\":\"「私は彼女と友達になった。」を英語にしなさい。\",\"wrongAnswer\":\"I made a friend with her.\",\"trapExplanation\":\"友達になる相手は一人なので、a friend と単数にしてしまう。日本語の「友達になる」をそのまま一語ずつ置きかえるのが原因。\",\"correctAnswer\":\"I made friends with her.\",\"correctExplanation\":\"「友達になる」は make friends with … と、friends を複数形にするのが決まりである。友達関係は二人以上の間に成り立つものだからと考えるとよい。同じように shake hands with …（〜と握手する）も hands と複数形にする。\"}]}",
"{\"id\":\"eigo_s369\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語④：look を使う表現\",\"description\":\"look at / look for / look after / look like など、look の熟語を意味ごとに区別する\",\"intro\":\"look at は「見る」、look for は「さがす」、look after は「世話をする」。同じ look なのに、うしろの前置詞が変わるだけで意味がまるでちがいます。前置詞まで含めて一つの語として覚えるべき理由が、ここにあります。\",\"order\":869,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"look at（〜を見る）／look for（〜をさがす）／look after（〜の世話をする）。\",\"look ＋ 形容詞 で「〜に見える」。You look happy.\",\"look like ＋ 名詞 で「〜に似ている・〜のように見える」。\",\"look forward to ＋ -ing（〜を楽しみに待つ）。to の後ろは動詞の原形ではない。\",\"Look out! ＝ Watch out!（危ない！）\",\"前置詞が変わると意味が大きく変わるので、セットで暗記する。\"],\"sections\":[{\"heading\":\"look ＋ 前置詞で意味が変わる\",\"body\":\"look は後ろに続く前置詞によって意味がまったく変わる。ここが入試の狙われどころである。\\n\\n■ look at ＋ もの（〜を見る）\\nLook at the blackboard.（黒板を見なさい。）\\nLook at that beautiful bird.\\n\\n■ look for ＋ もの（〜をさがす）\\nI am looking for my key.（かぎをさがしています。）\\nWhat are you looking for?（何をさがしているのですか。）\\n※ 見つかったかどうかは問わない。「さがしている最中」を表す。\\n\\n■ look after ＋ 人・動物（〜の世話をする）\\nShe looks after her little brother.（彼女は弟の世話をする。）\\n＝ She takes care of her little brother.\\n\\n■ look out（気をつける）\\nLook out! A car is coming.（危ない！ 車が来る。）\\n＝ Watch out!／Be careful!\\n\\n★ ポイント：at＝一点を見る、for＝求める、after＝後ろについて面倒をみる、と前置詞のイメージから覚えると忘れにくい。\\n\\n⚠ 注意：look at は「意識して見る」動作。ただ目に入る see とはちがう（別の課でくわしく学ぶ）。\",\"figureId\":\"xf_eigo_s369\"},{\"heading\":\"look ＋ 形容詞と look like\",\"body\":\"look には「〜に見える」という意味もある。後ろに何が来るかで形が変わる。\\n\\n■ look ＋ 形容詞（〜に見える）\\nYou look happy today.（今日はうれしそうだね。）\\nShe looks tired.（彼女はつかれているようだ。）\\nThat cake looks delicious.（そのケーキはおいしそうだ。）\\n※ 後ろに形容詞が直接くる。be動詞は不要。\\n\\n■ look like ＋ 名詞（〜のように見える・〜に似ている）\\nHe looks like his father.（彼は父親に似ている。）\\nThat cloud looks like a rabbit.（あの雲はうさぎのように見える。）\\nIt looks like rain.（雨が降りそうだ。）\\n※ 後ろに名詞が来るときだけ like が必要。\\n\\n★ ポイント：後ろが形容詞なら like は付けない、名詞なら like を付ける。\\nYou look happy.（○）／You look like happy.（×）\\nHe looks like a teacher.（○）／He looks a teacher.（×）\\n\\n■ look forward to ＋ 名詞・-ing（〜を楽しみに待つ）\\nI am looking forward to the summer vacation.\\nI am looking forward to seeing you.（あなたに会うのを楽しみにしています。）\\n⚠ 注意：この to は前置詞なので、後ろに動詞を置くときは必ず -ing にする。to see とはしない。手紙やメールの結びによく使われる表現である。\",\"mangaId\":\"eigo_s369_xm\"}],\"trapExamples\":[{\"question\":\"（　）に入る語句を選びなさい。 You （　） very happy today.　［look / look like］\",\"wrongAnswer\":\"look like\",\"trapExplanation\":\"「〜のように見える」＝look like と丸暗記しているため、後ろの語が形容詞か名詞かを確かめずに選んでしまう。\",\"correctAnswer\":\"look\",\"correctExplanation\":\"happy は形容詞なので、like を付けずに look happy とする。like が必要なのは後ろに名詞が来るときだけである（He looks like his father.）。後ろの語の品詞を見て決める、という手順を身につける。\"},{\"question\":\"「あなたに会えるのを楽しみにしています。」を英語にしなさい。\",\"wrongAnswer\":\"I am looking forward to see you.\",\"trapExplanation\":\"to を「to ＋ 動詞の原形」の to だと思いこんでしまう。want to see、hope to see と同じ形に見えるのが原因。\",\"correctAnswer\":\"I am looking forward to seeing you.\",\"correctExplanation\":\"look forward to の to は前置詞なので、後ろには名詞か動詞の -ing 形が来る。I am looking forward to seeing you.／to the party. となる。前置詞の後ろは -ing、というきまりは be good at -ing、Thank you for -ing とも共通である。\"}]}",
"{\"id\":\"eigo_s370\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語⑤：put を使う表現と代名詞の位置\",\"description\":\"put on / put off / put away などの熟語と、代名詞が入るときの語順を学ぶ\",\"intro\":\"「コートを着なさい」は Put on your coat. ですが、「それを着なさい」は Put it on. です。Put on it. とは言えません。代名詞が来ると語順が変わる——この決まりを知らないと、並べかえ問題で必ず落とします。\",\"order\":870,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"put の中心の意味は「置く」。put ＋ 場所を表す語句がふつうの形。\",\"put on（身につける）⇔ take off（ぬぐ）。\",\"put away（かたづける）／put up（かかげる・立てる）／put off（延期する）。\",\"代名詞（it, them）は put it on のように動詞と副詞の間に置く。\",\"名詞なら put on your coat / put your coat on のどちらでもよい。\",\"put の過去形・過去分詞は put（形が変わらない）。\"],\"sections\":[{\"heading\":\"put の基本と熟語\",\"body\":\"put は「置く」が中心の意味で、後ろに場所を表す語句が続くのがふつうである。\\n\\n■ 基本の形\\nPut the book on the desk.（本を机の上に置きなさい。）\\nPut your bag here.（かばんをここに置きなさい。）\\nDon't put your feet on the chair.\\n\\n■ put on（身につける）\\nPut on your jacket.（上着を着なさい。）\\n※ 服・くつ・帽子・めがねすべてに使える。反対は take off。\\n⚠ 「着ている状態」は wear で表す。put on は身につける動作。\\n\\n■ put away（かたづける・しまう）\\nPut away your toys.（おもちゃをかたづけなさい。）\\n\\n■ put up（あげる・はる・立てる）\\nPut up your hand.（手をあげなさい。）＝ Raise your hand.\\nWe put up a tent.（テントを立てた。）\\n\\n■ put off（延期する）\\nThey put off the game because of the rain.（雨のため試合を延期した。）\\n＝ They postponed the game.\\n\\n■ put down（下に置く）\\nPut down your pencil.（えんぴつを置きなさい。）\\n\\n★ ポイント：put は過去形も過去分詞も put で、形が変わらない。cut・hit・set・let も同じ仲間である。\\n例）I put the letter in the box yesterday.（昨日、手紙を箱に入れた。）← put は過去形\"},{\"heading\":\"代名詞が入るときの語順\",\"body\":\"put on のように「動詞＋副詞」の熟語では、目的語の位置に決まりがある。\\n\\n■ 名詞のときは前でも後ろでもよい\\nPut on your coat.（○）\\nPut your coat on.（○）\\nどちらも正しい。\\n\\n■ 代名詞（it, them, him, her）のときは必ず間にはさむ\\nPut it on.（○）\\nPut on it.（×）\\nTake them off.（○）／Take off them.（×）\\n\\n★ ポイント：「代名詞は真ん中」と覚える。it や them は短くて軽いことばなので、文の最後に置かず、動詞のすぐ後ろに置く。\\n\\n■ 同じきまりが働く熟語\\nput on / take off（身につける・ぬぐ）\\nturn on / turn off（つける・消す）\\n　例）Turn on the TV.／Turn it on.（× Turn on it.）\\npick up（拾う）\\n　例）Pick up the pen.／Pick it up.\\ntry on（試着する）\\n　例）Can I try it on?\\nlook up（辞書で調べる）\\n　例）Look up the word.／Look it up.\\n\\n■ 前置詞の熟語とのちがい\\nlook at・look for・listen to のような「動詞＋前置詞」の熟語では、代名詞も後ろに置く。\\nLook at it.（○）／Look it at.（×）\\nListen to me.（○）\\n\\n⚠ 注意：見分け方は「後ろの語が名詞なしで意味を持つか」。on / off / up / down は単独でも意味を持つ副詞、at / to / for は必ず名詞を必要とする前置詞である。\",\"figureId\":\"xf_eigo_s370\",\"mangaId\":\"eigo_s370_xm\"}],\"trapExamples\":[{\"question\":\"「（そのシャツを）試着してもいいですか。」を、shirt を it に置きかえて英語にしなさい。\",\"wrongAnswer\":\"Can I try on it?\",\"trapExplanation\":\"try on を一つのかたまりとして覚えているため、後ろにそのまま it を続けてしまう。名詞のときは try on the shirt と言えるので、同じでよいと考えてしまう。\",\"correctAnswer\":\"Can I try it on?\",\"correctExplanation\":\"「動詞＋副詞」の熟語では、代名詞（it, them）は必ず動詞と副詞の間にはさむ。try it on、put it on、turn it off、pick it up となる。名詞のときだけ try on the shirt / try the shirt on のどちらでもよい。「代名詞は真ん中」と覚える。\"},{\"question\":\"次の英文の put は現在形か過去形か。 I put the letter in the box yesterday.\",\"wrongAnswer\":\"現在形\",\"trapExplanation\":\"過去形なら -ed が付くか形が変わるはずだと考え、形が同じ put を現在形だと判断してしまう。yesterday という手がかりを見落としている。\",\"correctAnswer\":\"過去形\",\"correctExplanation\":\"put は原形・過去形・過去分詞がすべて put で形が変わらない動詞である。文末の yesterday から過去の文だとわかる。同じ仲間に cut・hit・set・let・read（読み方だけ変わる）があり、時を表す語で判断する必要がある。\"}]}",
"{\"id\":\"eigo_s371\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動詞の熟語⑥：come と go の使い分け\",\"description\":\"come と go の方向のちがいと、come from / go to などの熟語を整理する\",\"intro\":\"「今行きます」を I am going. と言うと、相手のところへは行かないという意味になってしまいます。正しくは I am coming. です。英語の come と go は、話し手ではなく相手を基準に方向が決まるからです。\",\"order\":871,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"go は話し手から遠ざかる方向、come は話し手や相手に近づく方向。\",\"「今行きます」は I'm coming.（× I'm going.）相手のほうへ向かうから。\",\"come from ＝ be from（〜の出身である）。\",\"go to ＋ 場所。ただし go home / go there には to を付けない。\",\"go -ing で「〜しに行く」。go shopping／go fishing／go swimming。\",\"come true（実現する）／go out（外出する）／come back（もどる）。\"],\"sections\":[{\"heading\":\"come と go の方向のちがい\",\"mangaId\":\"eigo_s371_manga\",\"body\":\"come と go は「来る」「行く」と覚えるだけでは足りない。基準になる人がどこにいるかで決まる。\\n\\n■ go ＝ 話し手のいる場所から遠ざかる\\nI go to school at eight.（学校へ行く。）\\nHe went to the park.\\n\\n■ come ＝ 話し手のいる場所、または相手のいる場所に近づく\\nCome here.（こっちに来て。）\\nMy friend came to my house yesterday.（友達が昨日、家に来た。）\\n\\n★ ポイント：日本語と食いちがう場面がある。母親に「ごはんですよ」と呼ばれて「今行く！」と答えるとき、英語では I'm coming! と言う。相手（母親）のいるほうへ近づくからである。ここを I'm going! と言うと「（どこかへ）出かけます」という意味になってしまう。\\n\\n例）Dinner is ready!（ごはんですよ！）— I'm coming!（今行きます！）\\n例）Can you come to my birthday party?（誕生日パーティーに来られますか。）\\n　　— Sure, I'll come.（もちろん、行きます。）\\n※ 相手のところへ行くので come を使う。\\n\\n⚠ 注意：日本語の「行く」を機械的に go にしないこと。だれのところへ向かうのかを考える。\",\"figureId\":\"lf_eigoext10_371\"},{\"heading\":\"come と go の熟語\",\"body\":\"どちらの動詞も熟語が多い。よく出るものをまとめる。\\n\\n■ come の熟語\\ncome from ＝ be from（〜の出身である）\\n　例）I come from Osaka.＝ I am from Osaka.\\n　　Where do you come from?＝ Where are you from?\\ncome back（もどる）\\n　例）He came back at six.\\ncome true（実現する）\\n　例）My dream came true.（夢がかなった。）\\ncome in（入る）\\n　例）May I come in? — Sure, come in.\\ncome and see（会いに来る）\\n　例）Please come and see me.\\n\\n■ go の熟語\\ngo to ＋ 場所（〜へ行く）\\n　例）go to the library／go to bed（ねる）※ bed には the を付けない\\ngo home / go there（家へ帰る／そこへ行く）※ to を付けない\\ngo out（外出する）\\n　例）My parents went out.\\ngo back（もどる）\\ngo on（続ける）\\n\\n■ go ＋ -ing（〜しに行く）\\ngo shopping（買い物に行く）／go fishing（つりに行く）／go swimming（泳ぎに行く）／go skiing（スキーに行く）／go camping（キャンプに行く）／go hiking（ハイキングに行く）\\n\\n★ ポイント：go shopping の後ろの場所には at や in を使う。\\n例）I went shopping at the department store.（× to the department store）\"}],\"trapExamples\":[{\"question\":\"「ごはんですよ。」「今行きます！」の「今行きます」を英語にしなさい。\",\"wrongAnswer\":\"I'm going!\",\"trapExplanation\":\"日本語の「行く」をそのまま go に置きかえてしまう。come を「来る」と一対一で覚えていると、相手のほうへ向かう場合に使えることに気づけない。\",\"correctAnswer\":\"I'm coming!\",\"correctExplanation\":\"come は「話し手または相手のいる場所へ近づく」ことを表す。呼ばれて相手のところへ向かうので come を使う。I'm going! と言うと「（別のどこかへ）出かけます」という意味になってしまう。Can you come to my party? — Yes, I'll come. も同じ考え方である。\"},{\"question\":\"「私は昨日、買い物に行きました。」を英語にしなさい。\",\"wrongAnswer\":\"I went to shopping yesterday.\",\"trapExplanation\":\"go to school、go to the park と同じ形だと考え、shopping の前にも to を入れてしまう。go to … を一つの決まり文句として覚えているのが原因。\",\"correctAnswer\":\"I went shopping yesterday.\",\"correctExplanation\":\"「〜しに行く」は go ＋ -ing の形で、to は入れない（go shopping、go fishing、go swimming、go camping）。to が必要なのは go to ＋ 場所のとき（go to the store）。さらに go home、go there には to を付けない点も合わせて整理する。\"}]}",
"{\"id\":\"eigo_s372\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"前置詞の熟語①：be動詞＋形容詞＋前置詞\",\"description\":\"be good at / be famous for / be interested in など、決まった前置詞をとる形を覚える\",\"intro\":\"「サッカーが得意だ」の「が」は、英語では at になります。be good at soccer です。なぜ at なのかを考えても答えは出ません。形容詞ごとに、組む前置詞が決まっているからです。よく出る組み合わせをまとめて覚えます。\",\"order\":872,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"be good at ＋ 名詞・-ing（〜が得意だ）。反対は be poor at。\",\"be interested in（〜に興味がある）／be famous for（〜で有名だ）。\",\"be afraid of（〜をこわがる）／be full of（〜でいっぱいだ）／be proud of（〜を誇りに思う）。\",\"be different from（〜とちがう）／be kind to（〜に親切だ）／be late for（〜におくれる）。\",\"前置詞の後ろに動詞を置くときは必ず -ing にする。\",\"be動詞は主語と時制に合わせて変える（am / is / are / was / were）。\"],\"sections\":[{\"heading\":\"よく出る「be動詞＋形容詞＋前置詞」\",\"body\":\"形容詞ごとに、決まった前置詞が付く。組み合わせで覚えるしかない。\\n\\n■ at をとるもの\\nbe good at（〜が得意だ）／be poor at, be bad at（〜が苦手だ）／be surprised at（〜に驚く）\\n例）She is good at swimming.（彼女は泳ぐのが得意だ。）\\n例）I was surprised at the news.（その知らせに驚いた。）\\n\\n■ in をとるもの\\nbe interested in（〜に興味がある）\\n例）I am interested in science.（理科に興味があります。）\\n\\n■ for をとるもの\\nbe famous for（〜で有名だ）／be late for（〜におくれる）／be ready for（〜の準備ができている）\\n例）Kyoto is famous for its old temples.（京都は古い寺で有名だ。）\\n例）Don't be late for school.（学校におくれないように。）\\n\\n■ of をとるもの\\nbe afraid of（〜をこわがる）／be full of（〜でいっぱいだ）／be proud of（〜を誇りに思う）／be fond of（〜が好きだ）\\n例）My sister is afraid of dogs.（姉は犬をこわがる。）\\n例）The box is full of books.（箱は本でいっぱいだ。）\\n\\n■ from / to をとるもの\\nbe different from（〜とちがう）／be kind to（〜に親切だ）／be good to（〜によくしてくれる）\\n例）My idea is different from yours.\\n例）He is kind to everyone.（彼はだれにでも親切だ。）\\n\\n★ ポイント：be famous for（有名な理由）と be famous as（〜としての有名さ）を区別する。\\n例）He is famous as a singer.（彼は歌手として有名だ。）\",\"figureId\":\"xf_eigo_s372\"},{\"heading\":\"前置詞の後ろは名詞か -ing\",\"body\":\"前置詞の後ろに動詞を置きたいときは、必ず -ing の形（動名詞）にする。ここが最大の落とし穴である。\\n\\n■ 正しい形\\nI am good at playing tennis.（テニスをするのが得意だ。）\\nShe is interested in learning English.（英語を学ぶことに興味がある。）\\nThank you for helping me.（手伝ってくれてありがとう。）\\nHe is afraid of making mistakes.（まちがえるのをこわがっている。）\\n\\n■ まちがえやすい形\\n× I am good at play tennis.\\n× I am good at to play tennis.\\n\\n★ ポイント：「前置詞の後ろは名詞か -ing」と一つの規則にまとめる。この規則が働く場面は多い。\\n・be good at ＋ -ing\\n・be interested in ＋ -ing\\n・be afraid of ＋ -ing\\n・Thank you for ＋ -ing\\n・How about ＋ -ing?（〜はどうですか）\\n・look forward to ＋ -ing\\n・before / after ＋ -ing（before going to bed）\\n\\n■ be動詞は主語と時制に合わせる\\nI am interested in music.／He is interested in music.／They are interested in music.\\nI was interested in music when I was a child.（子どものころは音楽に興味があった。）\\n\\n⚠ 注意：be interested in の interested は -ed の形。interesting（おもしろい）とまちがえやすい。\\nThis book is interesting.（この本はおもしろい。）\\nI am interested in this book.（この本に興味がある。）\\n人が「興味を持っている」なら -ed、ものが「興味を起こさせる」なら -ing と覚える。\",\"mangaId\":\"eigo_s372_xm\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を答えなさい。 My brother is good at （　） soccer.\",\"wrongAnswer\":\"play\",\"trapExplanation\":\"be good at を「〜が得意だ」という一つの意味のかたまりとして覚えているため、後ろに動詞の原形をそのまま置いてしまう。at が前置詞だと意識できていない。\",\"correctAnswer\":\"playing\",\"correctExplanation\":\"前置詞 at の後ろに動詞を置くときは -ing の形にする。My brother is good at playing soccer. となる。同じ規則が be interested in -ing、Thank you for -ing、How about -ing? にも働く。「前置詞の後ろは名詞か -ing」とまとめて覚える。\"},{\"question\":\"（　）に入る語を選びなさい。 I am （　） in Japanese history.　［interesting / interested］\",\"wrongAnswer\":\"interesting\",\"trapExplanation\":\"「興味がある」＝ interesting と覚えてしまっている。-ing と -ed の使い分けを、人が感じるのかものが感じさせるのかで区別していない。\",\"correctAnswer\":\"interested\",\"correctExplanation\":\"人が「興味を持っている」ときは -ed の形の interested を使い、be interested in … とする。ものが「興味を起こさせる＝おもしろい」ときは -ing の interesting を使う（This book is interesting.）。exciting / excited、surprising / surprised も同じ関係である。\"}]}",
"{\"id\":\"eigo_s373\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"前置詞の熟語②：場所を表す前置詞\",\"description\":\"in / on / at / under / by / between / among など、位置を表す前置詞を整理する\",\"intro\":\"かべにかかった絵は on the wall、天井の電灯も on the ceiling です。on は「上」ではなく「くっついている」を表すからです。in・on・at の三つは、日本語の訳ではなくイメージでつかむのが近道です。\",\"order\":873,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"in（囲まれた中に）／on（くっついて）／at（一点）が基本の三つ。\",\"on は「上」ではなく「接している」。かべの絵も天井の電灯も on。\",\"in は広い場所（in Tokyo）、at はせまい一点（at the station）。\",\"between は2つの間、among は3つ以上の間。\",\"over（真上・またぐ）／above（上方）／under（真下）／below（下方）。\",\"in front of ⇔ behind、next to ＝ beside。\"],\"sections\":[{\"heading\":\"in・on・at のイメージ\",\"body\":\"場所を表す前置詞は、日本語の「〜に」に全部あたるため、イメージでつかむ必要がある。\\n\\n■ in ＝ 囲まれた空間の中\\nin the box（箱の中に）／in the room（部屋の中に）／in Tokyo（東京に）／in Japan／in the water\\n広い場所（国・都市・部屋）には in を使う。\\n\\n■ on ＝ 面に接している\\non the desk（机の上に）／on the wall（かべに）／on the ceiling（天井に）／on the floor（ゆかに）\\n★ ポイント：on は「上」という意味ではなく「くっついている」という意味である。だから、かべに掛かった絵も天井の電灯も on を使う。\\n例）There is a picture on the wall.（かべに絵がかかっている。）\\n\\n■ at ＝ 一点\\nat the station（駅で）／at the door（ドアのところで）／at the bus stop／at school\\nせまい場所や、地図上の一点として見る場所には at を使う。\\n\\n■ in と at の使い分け\\nI live in Osaka.（大阪に住んでいる）← 広がりのある場所\\nI'll meet you at Osaka Station.（大阪駅で会おう）← 待ち合わせの一点\\nHe is in the classroom.（教室の中にいる）← 空間の中\\nHe is at school.（学校にいる）← 場所を一点としてとらえる\\n\\n⚠ 注意：in the tree（木の中＝葉のしげみの中の鳥など）と on the tree（実などが木に付いている）は使い分けがある。中学受験では in the box / on the desk / at the door の三つの型を確実にする。\",\"figureId\":\"lf_eigoext10_373\",\"mangaId\":\"eigo_s373_xm\"},{\"heading\":\"そのほかの位置の前置詞\",\"body\":\"位置関係を表す語は、地図問題・絵を見て答える問題で必ず使う。\\n\\n■ 上下\\nover（真上・接していない・またぐ）／above（〜より上のほうに）／under（真下）／below（〜より下のほうに）\\n例）A bird is flying over my head.（鳥が頭の上を飛んでいる。）\\n例）The cat is under the table.（ねこはテーブルの下にいる。）\\n例）The bridge is over the river.（橋が川にかかっている。）\\n\\n■ 前後\\nin front of（〜の前に）／behind（〜の後ろに）\\n例）There is a bus stop in front of the station.\\n例）The park is behind the school.\\n\\n■ 近く・となり\\nnear（〜の近くに）／by（〜のすぐそばに）／next to, beside（〜のとなりに）／across from（〜の向かいに）／around（〜のまわりに）\\n例）My house is near the park.／Sit by me.／The bank is next to the post office.\\n\\n■ 間\\nbetween A and B（2つのものの間に）\\namong（3つ以上のものに囲まれて）\\n例）The store is between the bank and the hospital.（店は銀行と病院の間にある。）\\n例）He is popular among his classmates.（彼はクラスメートの間で人気がある。）\\n\\n★ ポイント：between は2つ、among は3つ以上。「between の be は two の意味」と結びつけて覚えるとよい。\\n\\n■ 通り道\\nalong（〜に沿って）／through（〜を通りぬけて）／across（〜を横切って）／into（〜の中へ）／out of（〜の外へ）\\n例）Walk along this street.（この通りに沿って歩いてください。）\\n例）Go across the bridge.（橋をわたってください。）\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 There is a beautiful picture （　） the wall.　［in / on］\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「かべに」の「に」を、部屋の中を表す in だと考えてしまう。on を「上に」とだけ覚えていると、かべに使えることに気づかない。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"on は「上に」ではなく「面に接している」ことを表す前置詞である。だから、かべに掛かった絵も on the wall、天井の電灯も on the ceiling となる。in は「囲まれた空間の中」（in the box、in the room）に使う。\"},{\"question\":\"（　）に入る語を選びなさい。 The bank is （　） the post office and the hospital.　［between / among］\",\"wrongAnswer\":\"among\",\"trapExplanation\":\"「〜の間」という日本語だけを見て、どちらでもよいと考えてしまう。between と among の数のちがいを知らないのが原因。\",\"correctAnswer\":\"between\",\"correctExplanation\":\"between は2つのものの間、among は3つ以上のものに囲まれている場合に使う。ここは郵便局と病院の2つの間なので between … and … の形にする。among は He is popular among his friends. のように使う。\"}]}",
"{\"id\":\"eigo_s374\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"前置詞の熟語③：時を表す前置詞\",\"description\":\"in / on / at と for / during / since / until / by の使い分けを整理する\",\"intro\":\"2026年は in、5月5日は on、七時は at。時を表す前置詞は、指す時間の幅が大きいほど in で、小さくなるにつれて on、at と変わります。一つずつ暗記するより、幅の大小で並べたほうが確実に思い出せます。\",\"order\":874,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"時の in / on / at は「幅の大きさ」で決まる。in（年・月・季節）→ on（日付・曜日）→ at（時刻）。\",\"in the morning / in the afternoon / in the evening、ただし at night。\",\"for ＋ 期間の長さ（for two hours）／during ＋ 行事や期間の名前（during the vacation）。\",\"since ＝ 〜以来（起点）、from ＝ 〜から（出発点）。\",\"until (till) ＝ 〜までずっと（継続）、by ＝ 〜までには（期限）。\",\"before（〜の前に）／after（〜の後に）。後ろに動詞を置くときは -ing。\"],\"sections\":[{\"heading\":\"in・on・at は時間の幅で決まる\",\"body\":\"時を表す前置詞の in・on・at は、時間の幅の大きさで使い分ける。大きいほうから順に in → on → at と覚える。\\n\\n■ in ＋ 幅の広い時間\\nin 2026（年）／in April（月）／in summer（季節）／in the morning（午前中）／in the afternoon／in the evening／in the twentieth century（世紀）\\n\\n■ on ＋ 特定の日\\non Monday（曜日）／on May 5（日付）／on New Year's Day（記念日）／on Sunday morning（特定の日の朝）\\n★ ポイント：ふつうは in the morning だが、「日曜日の朝」のように日が決まると on Sunday morning となる。日が決まったら on が勝つ。\\n\\n■ at ＋ 時の一点\\nat seven（時刻）／at noon（正午）／at midnight（真夜中）／at night（夜に）／at that time（そのとき）\\n⚠ 注意：night だけは at を使う。in the morning / in the afternoon / in the evening と並べて、at night だけ仲間はずれと覚える。\\n\\n■ 前置詞を付けない語\\ntoday／tomorrow／yesterday／this morning／last night／next week／every day\\n例）I will go there tomorrow.（× on tomorrow）\\n例）I met him last Sunday.（× on last Sunday）\\nthis / last / next / every が付いたら前置詞は不要である。\",\"figureId\":\"lf_eigoext10_374\"},{\"heading\":\"for・during・since・until・by\",\"body\":\"期間を表す前置詞は、意味のちがいをはっきりさせておく。\\n\\n■ for ＋ 期間の長さ（数字で言える長さ）\\nfor two hours（2時間）／for three days／for a week／for a long time\\n例）I studied English for two hours.（2時間英語を勉強した。）\\n\\n■ during ＋ 行事・期間の名前\\nduring the summer vacation（夏休みの間）／during the class（授業中）／during the trip\\n例）I visited my grandmother during the winter vacation.\\n★ ポイント：後ろが「数字＋単位」なら for、「名前の付いた期間」なら during。\\n\\n■ since ＝ 〜以来（過去のある時点から今まで）\\nI have lived here since 2020.（2020年からここに住んでいる。）\\n※ 現在完了とともに使うことが多い。\\n\\n■ from ＝ 〜から（出発点）\\nThe store is open from nine to six.（店は9時から6時まで開いている。）\\nfrom A to B の形でよく使う。\\n\\n■ until (till) ＝ 〜までずっと\\nI waited until five.（5時までずっと待った。）\\n※ 動作や状態がその時まで続く。\\n\\n■ by ＝ 〜までには（期限）\\nCome home by five.（5時までには帰ってきなさい。）\\n※ その時までに一度すればよい。\\n⚠ 注意：until と by のちがいは頻出。「ずっと続く」なら until、「しめ切り」なら by。\\nPlease finish it by Friday.（金曜までに終わらせて）← しめ切り\\nI will stay here until Friday.（金曜までここにいる）← 継続\\n\\n■ before / after\\nbefore dinner（夕食前に）／after school（放課後に）\\n後ろに動詞を置くときは -ing にする。before going to bed（ねる前に）\"},{\"heading\":\"なぜ時間の幅で in・on・at が決まり、なぜ until と by がちがうのか\",\"mangaId\":\"eigo_s374_manga\",\"body\":\"in は「広い範囲の中に」、on は「その日に触れて」、at は「一点で」という前置詞の本来の意味です。年・月・季節は幅が広いので in、日付・曜日は一日という区切りなので on、時刻は針が一か所を指す点なので at。幅の大小で並べると、一つずつ暗記しなくても思い出せます。「日曜日の朝」で on が勝つのは、日が決まった時点で「その日に」という on の意味が優先されるからです。this・last・next・every が付いた語に前置詞を付けないのは、これらの語がすでに「いつ」を決めているからです。\\n\\nuntil と by のちがいは、**動作が続くか、一度で終わるか**です。until は「その時までずっと」と状態が続く（stay・wait）、by は「その時までには一度」と期限を示す（finish・come・send）。for と during は、うしろが「数字＋単位」（長さ）なら for、「名前の付いた期間」なら during です。\\n\\n■ 確かめのしかた\\n①幅の大小で選ぶ：年・月・季節・午前→in、日付・曜日→on、時刻・正午・夜→at。日が決まったら on（on Sunday morning）。\\n②this・last・next・every・today・tomorrow・yesterday に前置詞を付けていないか（× on last Sunday）。\\n③うしろが**数字＋単位**なら for（for three days）、**名前の付いた期間**なら during（during the vacation）。\\n④動作が**続く**なら until（stay until Friday）、**一度で終わる**なら by（finish by Friday）。since は「〜以来」で現在完了と。before・after のあとに動詞を置くなら -ing。\\n\\n★ ここがポイント：in は**幅**、on は**日**、at は**点**で、幅の大小で並べて覚える。until は**続く**、by は**期限**。for は**数字の長さ**、during は**名前の付いた期間**。\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 I will finish my homework （　） Friday.（金曜までには終わらせる）　［until / by］\",\"wrongAnswer\":\"until\",\"trapExplanation\":\"「〜まで」という日本語がどちらにもあてはまるため、先に習った until を選んでしまう。「終わらせる」が一回きりの動作であることに注意が向かない。\",\"correctAnswer\":\"by\",\"correctExplanation\":\"by は「〜までには」という期限を表し、その時までに一度すればよい動作に使う。until は「〜までずっと」という継続を表し、I will stay here until Friday. のように状態が続く場合に使う。finish・come・send のような一回きりの動作には by を使う。\"},{\"question\":\"（　）に入る語を選びなさい。 I stayed in Kyoto （　） three days.　［for / during］\",\"wrongAnswer\":\"during\",\"trapExplanation\":\"「〜の間」という日本語から during を選んでしまう。for と during の後ろに来る語のちがいを意識していない。\",\"correctAnswer\":\"for\",\"correctExplanation\":\"「数字＋単位」で長さを表すときは for を使う（for three days、for two hours、for a week）。during は the summer vacation、the class のように名前の付いた期間に使う。後ろの語が数字で始まるかどうかで判断する。\"}]}",
"{\"id\":\"eigo_s375\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"前置詞の熟語④：動詞＋前置詞のかたまり\",\"description\":\"listen to / wait for / arrive at / take care of など、前置詞まで含めて覚える動詞を整理する\",\"intro\":\"「音楽を聞く」は listen music ではなく listen to music です。日本語で「〜を」と言うから前置詞が要らない、とはかぎりません。逆に discuss や enter は前置詞が不要です。取りちがえやすい組を並べて確かめます。\",\"order\":875,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"listen to（〜を聞く）／wait for（〜を待つ）／look at（〜を見る）は前置詞が必要。\",\"日本語では「〜を」でも英語では前置詞が要るものに注意する。\",\"反対に、discuss・reach・enter・visit・marry は前置詞が不要。\",\"arrive at（せまい場所）／arrive in（広い場所）＝ get to ＝ reach。\",\"take care of ＝ look after／be able to ＝ can。\",\"ask ＋ 人 ＋ for ＋ もの（人にものをたのむ）／thank ＋ 人 ＋ for（〜のことで感謝する）。\"],\"sections\":[{\"heading\":\"前置詞が必要な動詞\",\"body\":\"日本語では「〜を」と言うのに、英語では前置詞が必要な動詞がある。書き取り・並べかえで必ず問われる。\\n\\n■ to をとる\\nlisten to（〜を聞く）／talk to（〜と話す）／speak to（〜に話しかける）／belong to（〜に所属する）／say to（〜に言う）\\n例）I listen to the radio every night.（毎晩ラジオを聞く。）\\n例）I belong to the tennis club.（テニス部に入っている。）\\n\\n■ for をとる\\nwait for（〜を待つ）／look for（〜をさがす）／ask for（〜を求める）／leave for（〜に向けて出発する）／care for（〜の世話をする）／thank ～ for（〜のことで感謝する）\\n例）I waited for the bus for ten minutes.（10分間バスを待った。）\\n例）Thank you for your help.（助けてくれてありがとう。）\\n\\n■ at をとる\\nlook at（〜を見る）／arrive at（〜に着く）／laugh at（〜を笑う）／be surprised at\\n例）We arrived at the station at six.\\n\\n■ of / on / with をとる\\ntake care of（〜の世話をする）／think of（〜のことを考える）／hear of（〜のうわさを聞く）／depend on（〜による）／agree with（〜に賛成する）／help ～ with（〜を手伝う）\\n例）Can you help me with my homework?（宿題を手伝ってくれますか。）\\n\\n★ ポイント：日本語の「〜を」につられて前置詞を落とす誤りが多い。listen the radio、wait the bus はどちらも誤りである。\",\"figureId\":\"xf_eigo_s375\",\"mangaId\":\"eigo_s375_xm\"},{\"heading\":\"前置詞がいらない動詞と、言いかえ\",\"body\":\"逆に、日本語では「〜に」と言うのに前置詞がいらない動詞もある。\\n\\n■ 前置詞が不要な動詞\\nreach（〜に着く）：We reached the station.（× reached at）\\nenter（〜に入る）：He entered the room.（× entered into）\\nvisit（〜を訪れる）：I visited my uncle.（× visited to）\\ndiscuss（〜について話し合う）：We discussed the problem.（× discussed about）\\nmarry（〜と結婚する）：She married him.（× married with）\\nanswer（〜に答える）：Answer the question.（× answer to）\\n\\n■ 「着く」のいろいろな言い方\\narrive at ＋ せまい場所（arrive at the station）\\narrive in ＋ 広い場所（arrive in Japan）\\nget to ＋ 場所（get to the station）\\nreach ＋ 場所（reach the station）※ 前置詞なし\\n例）We arrived at the airport at ten. ＝ We got to the airport at ten. ＝ We reached the airport at ten.\\n\\n■ よく出る言いかえ\\ntake care of ＝ look after（世話をする）\\nbe able to ＝ can（できる）\\nbe going to ＝ will（〜するつもりだ）\\na lot of ＝ many / much（たくさんの）\\nhave to ＝ must（〜しなければならない）\\nbe fond of ＝ like（好きだ）\\n\\n⚠ 注意：この言いかえは書きかえ問題で頻出。同じ意味でも形がちがうので、動詞の形（原形か、-ing か）に気をつける。\\nHe can swim. ＝ He is able to swim.（後ろは原形）\"}],\"trapExamples\":[{\"question\":\"「私は毎朝ラジオを聞きます。」を英語にしなさい。\",\"wrongAnswer\":\"I listen the radio every morning.\",\"trapExplanation\":\"日本語が「ラジオを聞く」と「を」で結ばれているため、英語でも前置詞なしで続けられると考えてしまう。listen を「〜を聞く」と一語で覚えているのが原因。\",\"correctAnswer\":\"I listen to the radio every morning.\",\"correctExplanation\":\"listen は「耳をかたむける」という意味の動詞で、聞く対象を示すには to が必要である。同じように wait for（待つ）、look at（見る）、look for（さがす）も前置詞まで含めて覚える。逆に reach、visit、discuss、enter は前置詞がいらない。\"},{\"question\":\"「私たちはその問題について話し合った。」を英語にしなさい。\",\"wrongAnswer\":\"We discussed about the problem.\",\"trapExplanation\":\"「〜について」という日本語から about を入れてしまう。talk about … を覚えている生徒ほど引っかかりやすい。\",\"correctAnswer\":\"We discussed the problem.\",\"correctExplanation\":\"discuss は「〜について話し合う」という意味をすでに含んでいるので、about を付けない。同じ仲間に reach（〜に着く）、enter（〜に入る）、visit（〜を訪れる）、answer（〜に答える）、marry（〜と結婚する）がある。about が必要なのは talk about、think about のほう。\"}]}",
"{\"id\":\"eigo_s376\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現①：あいさつと別れのことば\",\"description\":\"時間帯によるあいさつの使い分けと、別れ・お礼・おわびの決まり文句を身につける\",\"intro\":\"Good night は「こんばんは」ではありません。夜に会ったときは Good evening、別れるときが Good night です。この二つを取りちがえると、あいさつのつもりが「さようなら」になってしまいます。時間帯ごとに整理します。\",\"order\":876,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"Good morning（朝）／Good afternoon（昼〜夕方）／Good evening（夕方以降）。\",\"Good night は「おやすみなさい」で、別れのあいさつ。会ったときには使わない。\",\"How are you? — I'm fine, thank you. And you? が基本のやりとり。\",\"別れは See you.／See you later.／Good-bye.／Take care.\",\"お礼は Thank you. — You're welcome.／おわびは I'm sorry. — That's all right.\",\"初対面では Nice to meet you. — Nice to meet you, too.\"],\"sections\":[{\"heading\":\"時間帯によるあいさつ\",\"body\":\"英語のあいさつは時間帯で変わる。ここは会話問題でそのまま問われる。\\n\\n■ 会ったときのあいさつ\\nGood morning.（おはようございます）… 朝から正午ごろまで\\nGood afternoon.（こんにちは）… 正午から夕方まで\\nGood evening.（こんばんは）… 夕方から夜まで\\nHi.／Hello.（やあ・こんにちは）… 時間に関係なく使える\\n\\n⚠ 注意：Good night. は「こんばんは」ではなく「おやすみなさい」「さようなら（夜の別れ）」である。夜に会ったときは Good evening. を使う。ここは必ず出題される。\\n\\n■ 調子をたずねる\\nHow are you?（お元気ですか。）\\n— I'm fine, thank you. And you?（元気です。あなたは。）\\n— Pretty good.／Not so good.／So-so.（まあまあです。）\\nHow are you doing?／How's it going? もくだけた言い方。\\n\\n■ ひさしぶりのとき\\nLong time no see.／I haven't seen you for a long time.（おひさしぶりです。）\\n\\n■ 別れるとき\\nGood-bye.／Bye.／See you.／See you later.（またあとで）／See you tomorrow.（また明日）／Take care.（気をつけて）／Have a nice day.（よい一日を）\\n— You too.（あなたもね。）\\n\\n★ ポイント：Have a nice day. と言われたら、You too. と返すのが自然な受け答えである。\",\"figureId\":\"lf_eigoext10_376\",\"mangaId\":\"eigo_s376_xm\"},{\"heading\":\"お礼・おわび・返事\",\"body\":\"会話問題では「言われたことに何と返すか」が問われる。返事とセットで覚える。\\n\\n■ お礼\\nThank you (very much).／Thanks.（ありがとう）\\n— You're welcome.（どういたしまして）\\n— Not at all.／My pleasure.／No problem.（どういたしまして）\\nThank you for your help.（助けてくれてありがとう）\\nThank you for coming.（来てくれてありがとう）※ for の後ろは -ing\\n\\n■ おわび\\nI'm sorry.（ごめんなさい）\\n— That's all right.／That's OK.／Never mind.（気にしないで）\\nI'm sorry I'm late.（おくれてごめんなさい）\\nExcuse me.（すみません）※ 人に呼びかけるとき・前を通るとき\\n\\n★ ポイント：Excuse me. は話しかけるときの「すみません」、I'm sorry. はあやまるときの「すみません」。日本語では同じでも英語では別なので、場面で区別する。\\n\\n■ 初対面\\nNice to meet you.（はじめまして。）\\n— Nice to meet you, too.\\nHow do you do?（はじめまして。）※ ややかたい言い方\\nThis is my friend, Ken.（こちらは友達のケンです。）\\n\\n■ そのほかの返事\\nSure.／Of course.（もちろん）／No problem.（いいですよ）／I'd love to.（ぜひ）／I'm afraid not.（残念ですができません）\"}],\"trapExamples\":[{\"question\":\"夜7時に友達の家をたずねたとき、最初に言うあいさつとして正しいものを選びなさい。 ［Good night. / Good evening.］\",\"wrongAnswer\":\"Good night.\",\"trapExplanation\":\"「夜＝night」と結びつけて、夜のあいさつは Good night. だと考えてしまう。日本語の「こんばんは」に night という語が当てはまりそうに見えるのも原因。\",\"correctAnswer\":\"Good evening.\",\"correctExplanation\":\"Good night. は「おやすみなさい」「（夜の）さようなら」で、別れるときに使う。会ったときの「こんばんは」は Good evening. である。会ったとき＝morning / afternoon / evening、別れるとき＝night と整理する。\"},{\"question\":\"（　）に入る表現を選びなさい。 A: Thank you for helping me.　B: （　）　［You're welcome. / Nice to meet you.］\",\"wrongAnswer\":\"Nice to meet you.\",\"trapExplanation\":\"会話表現をまとめて暗記していると、場面と結びつけずにそれらしい表現を選んでしまう。お礼への返事という文脈を読み取れていない。\",\"correctAnswer\":\"You're welcome.\",\"correctExplanation\":\"Thank you. に対する返事は You're welcome.（どういたしまして）である。ほかに Not at all.、My pleasure.、No problem. も使える。Nice to meet you. は初対面のあいさつなので、この場面には合わない。会話問題は「直前の発言に対する返事」として自然かどうかで選ぶ。\"}]}",
"{\"id\":\"eigo_s377\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現②：自己紹介と人の紹介\",\"description\":\"名前・出身・好きなものを伝える自己紹介の型と、人を紹介する言い方を学ぶ\",\"intro\":\"英語で名前を言うとき、日本語のように姓から言うと相手を混乱させます。My name is Ken Sato. と、名前が先で姓があとです。名前・出身・好きなことという流れを型にしておけば、初対面でも言葉に詰まりません。\",\"order\":877,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"自己紹介は「名前 → 出身 → 学年・年齢 → 好きなこと → しめくくり」の順で作る。\",\"My name is Ken.／I'm Ken. どちらでもよい。My name is Ken Sato. と姓名の順に注意。\",\"出身は I'm from Osaka. ＝ I come from Osaka.\",\"「〜が好きです」は I like …、「〜が得意です」は I'm good at -ing。\",\"人を紹介するときは This is …. を使い、He is … とは言わない。\",\"しめくくりは Thank you.／Nice to meet you. で終える。\"],\"sections\":[{\"heading\":\"自己紹介の型\",\"body\":\"英語入試では「自己紹介を英語で書きなさい」という問題がよく出る。次の型に自分の情報を入れれば必ず書ける。\\n\\n■ ①名前\\nHello. My name is Ken Sato.／I'm Ken.\\n※ 英語では名（Ken）→ 姓（Sato）の順に言う。Please call me Ken.（ケンと呼んでください。）\\n\\n■ ②出身・住んでいる場所\\nI'm from Osaka.＝ I come from Osaka.\\nI live in Nara with my family.\\n\\n■ ③学年・年齢\\nI'm twelve years old.\\nI'm a sixth grader.／I'm in the sixth grade.（6年生です。）\\n\\n■ ④好きなこと・得意なこと\\nI like soccer very much.\\nMy favorite subject is science.\\nI'm good at swimming.\\nI play the piano every day.（楽器には the を付ける）\\nI'm in the tennis club.（テニス部に入っています。）\\n\\n■ ⑤家族・ペット\\nI have a brother and a dog.\\n\\n■ ⑥しめくくり\\nThank you.／Nice to meet you.\\n\\n★ ポイント：一文を短く、主語と動詞をはっきりさせる。長い文を書こうとすると誤りが増える。\\n\\n⚠ 注意：I'm twelve years old. の years は複数形。one year old だけが単数である。\",\"figureId\":\"xf_eigo_s377\"},{\"heading\":\"人を紹介する・相手にたずねる\",\"body\":\"自己紹介ができたら、人を紹介する言い方と、相手にたずねる言い方をそろえる。\\n\\n■ 人を紹介する\\nThis is my friend, Aya.（こちらは友達のアヤです。）\\nThis is Mr. Brown. He is our English teacher.\\n※ 紹介するときの最初の一言は必ず This is …。He is … から始めない。二文目からは He / She を使う。\\n\\n■ 相手にたずねる\\nWhat's your name?（お名前は。）— My name is Ken.\\nWhere are you from?（どちらの出身ですか。）— I'm from Canada.\\nHow old are you?（何歳ですか。）— I'm twelve.\\nWhat grade are you in?（何年生ですか。）— I'm in the sixth grade.\\nWhat do you like to do?（何をするのが好きですか。）— I like reading books.\\nDo you have any brothers or sisters?\\nWhat's your favorite food?（好きな食べ物は何ですか。）\\n\\n■ 敬称\\nMr.（男性）／Ms.（女性・結婚の有無を問わない）／Mrs.（結婚している女性）／Miss（未婚の女性）\\n※ 敬称の後ろには姓を続ける（Mr. Brown）。名前だけに付けない（× Mr. John）。今は Ms. を使うのがふつう。\\n\\n⚠ 注意：How are you?（元気ですか）と How old are you?（何歳ですか）、Who are you?（あなたはだれ）は混同しやすい。Who are you? は失礼にひびくので、初対面では使わない。\",\"mangaId\":\"eigo_s377_xm\"}],\"trapExamples\":[{\"question\":\"友達を先生に紹介するときの最初の一言として正しいものを選びなさい。 ［She is my friend, Aya. / This is my friend, Aya.］\",\"wrongAnswer\":\"She is my friend, Aya.\",\"trapExplanation\":\"女の子を指すので she を使うのが自然だと考えてしまう。日本語では「彼女は私の友達のアヤです」と言えるため、直訳すると she になる。\",\"correctAnswer\":\"This is my friend, Aya.\",\"correctExplanation\":\"英語では人を紹介するとき、最初の一言に This is … を使う決まりがある。二文目からは She is a good tennis player. のように he / she を使ってよい。電話で名乗るときも This is Ken speaking. と This を使う。\"},{\"question\":\"「私は12歳です。」を英語にしなさい。\",\"wrongAnswer\":\"I'm twelve year old.\",\"trapExplanation\":\"「12歳」という一つのまとまりで考えるため、year に -s を付け忘れる。日本語には複数形がないので、数と名詞の形をそろえる意識が働かない。\",\"correctAnswer\":\"I'm twelve years old.\",\"correctExplanation\":\"2以上の数の後ろでは名詞を複数形にするので twelve years old となる。1歳だけが one year old と単数になる。なお I'm twelve. と years old を省いてもよい。年齢をたずねる文は How old are you? である。\"}]}",
"{\"id\":\"eigo_s378\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現③：電話での言い方\",\"description\":\"電話をかける・受ける・取り次ぐ・伝言を残すときの決まり文句を身につける\",\"intro\":\"電話で「わたしはケンです」と言うとき、I am Ken. とは言いません。This is Ken. が正しい言い方です。相手に姿が見えない電話には、専用の言い回しがいくつもあります。かける・受ける・取り次ぐ場面ごとに覚えます。\",\"order\":878,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"電話で名乗るときは This is Ken (speaking).（I am Ken. とは言わない）\",\"相手を確かめるときは Is this Aya?／Who's calling, please?\",\"取り次ぎは Just a moment, please.／Hold on, please.\",\"不在は He is not here now.／She is out now.\",\"伝言は Can I take a message?（受ける側）／Can I leave a message?（かける側）\",\"かけまちがいは I think you have the wrong number.\"],\"sections\":[{\"heading\":\"電話をかける・受ける\",\"body\":\"電話の場面は会話の並べかえ問題で頻出である。日常の英語と言い方が変わるところに注意する。\\n\\n■ 電話を受ける\\nHello.（もしもし）\\nHello. This is the Sato residence.（佐藤でございます。）※ ていねいな言い方\\n\\n■ 名乗る\\nHello. This is Ken (speaking).（もしもし、ケンです。）\\n★ ポイント：電話では I am Ken. とは言わず、This is Ken. と言う。自分を「この声の人」として示すためである。\\n\\n■ 相手を確かめる\\nIs this Aya?（アヤさんですか。）\\nWho's calling, please?（どちらさまですか。）\\nMay I ask who's calling?（どちらさまでしょうか。）\\n\\n■ 話したい相手を伝える\\nMay I speak to Aya, please?（アヤさんをお願いします。）\\nCan I talk to Mr. Brown?\\n※ speak to / talk to を使う。\\n\\n■ 取り次ぐ\\nJust a moment, please.／Hold on, please.（少々お待ちください。）\\nI'll get him.（彼を呼んできます。）\\nSpeaking.（私です。）← 本人が出ているとき\\n\\n⚠ 注意：May I speak to Aya? に対して本人が出たときの返事は Speaking. または This is she. である。Yes, I am. とは言わない。\",\"figureId\":\"xf_eigo_s378\",\"mangaId\":\"eigo_s378_xm\"},{\"heading\":\"不在・伝言・かけまちがい\",\"body\":\"相手がいないときのやりとりも、そのまま出題される。\\n\\n■ 不在を伝える\\nI'm sorry, but he is not here now.（あいにく彼は今おりません。）\\nShe is out now.（今、外出しています。）\\nHe is at school now.\\nHe will be back at six.（6時にもどります。）\\n\\n■ 伝言\\nCan I take a message?（伝言をうかがいましょうか。）← 受ける側\\nWould you like to leave a message?（伝言を残されますか。）\\nCan I leave a message?（伝言をお願いできますか。）← かける側\\nPlease tell him to call me back.（折り返し電話するよう伝えてください。）\\nPlease ask him to call me later.\\n\\n★ ポイント：take a message は「伝言を受け取る」、leave a message は「伝言を残す」。どちらの立場かで動詞が変わる。borrow と lend の関係に似ている。\\n\\n■ かけ直す\\nI'll call back later.（あとでかけ直します。）\\nShall I call you back?（かけ直しましょうか。）\\n\\n■ かけまちがい\\nI think you have the wrong number.（番号がちがうようです。）\\n— Oh, I'm sorry.\\n\\n■ 聞き取れないとき\\nI'm sorry, I can't hear you well.（よく聞こえません。）\\nCould you speak more slowly, please?（もっとゆっくり話していただけますか。）\"}],\"trapExamples\":[{\"question\":\"電話で「もしもし、ケンです。」と名乗るとき、正しい言い方を選びなさい。 ［I am Ken. / This is Ken.］\",\"wrongAnswer\":\"I am Ken.\",\"trapExplanation\":\"「私はケンです」という日本語をそのまま英語にしてしまう。ふだんの自己紹介で I'm Ken. と習っているため、電話でも同じでよいと考える。\",\"correctAnswer\":\"This is Ken.\",\"correctExplanation\":\"電話では自分を名乗るとき This is Ken (speaking). と言う。相手を確かめるときも Is this Aya? と this を使う。顔が見えず、声だけで「この人」と示す言い方だと考えるとよい。人を紹介するときの This is … と同じ発想である。\"},{\"question\":\"（　）に入る表現を選びなさい。 A: May I speak to Ken, please?　B: Sorry, he is out now. （　）（伝言をうかがいましょうか）\",\"wrongAnswer\":\"Can I leave a message?\",\"trapExplanation\":\"message を含む表現をまとめて覚えているため、take と leave の区別をせずに選んでしまう。どちらの立場が話しているかを読み取れていない。\",\"correctAnswer\":\"Can I take a message?\",\"correctExplanation\":\"電話を受けた側が「伝言をうかがいましょうか」と言うときは take a message（伝言を受け取る）を使う。かけた側が「伝言をお願いできますか」と言うときは leave a message（伝言を残す）である。話しているのがどちらかを確かめてから選ぶ。\"}]}",
"{\"id\":\"eigo_s379\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現④：買い物での言い方\",\"description\":\"店員と客のやりとり、値段・大きさ・色を伝える表現を身につける\",\"intro\":\"店員の May I help you? は、そのまま訳せば「お手伝いしましょうか」ですが、実際は「いらっしゃいませ」にあたります。見ているだけのときは No, thank you. I am just looking. と返します。買い物の型を覚えます。\",\"order\":879,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"店員の第一声は May I help you?／Can I help you?（いらっしゃいませ）\",\"客の答えは Yes, please. I'm looking for …／No, thank you. I'm just looking.\",\"値段は How much is it? — It's 1,500 yen.\",\"試着は Can I try it on?、サイズは Do you have a bigger one?\",\"買うと決めたら I'll take it.（これをください）\",\"one は前に出た名詞のくり返しをさける語。a red one（赤いの）。\"],\"sections\":[{\"heading\":\"店でのやりとりの型\",\"body\":\"買い物の会話は、次の流れをそのまま覚えておけば得点できる。\\n\\n■ ①店員が声をかける\\nMay I help you?／Can I help you?（いらっしゃいませ・何かおさがしですか。）\\n\\n■ ②客が答える\\nYes, please. I'm looking for a T-shirt.（Tシャツをさがしています。）\\nNo, thank you. I'm just looking.（見ているだけです。）\\n\\n■ ③商品について\\nDo you have this in blue?（これの青はありますか。）\\nDo you have a bigger one?（もっと大きいのはありますか。）\\nCan I try it on?（試着してもいいですか。）\\n— Sure. The fitting room is over there.\\n\\n■ ④値段\\nHow much is it?（いくらですか。）\\n— It's 1,500 yen.\\nHow much are these shoes?（このくつはいくらですか。）\\nThat's too expensive.（高すぎます。）\\nIt's cheap.（安いです。）\\n\\n■ ⑤決める\\nI'll take it.（これをください。）\\nI'll take two.（2つください。）\\nHere you are.（はい、どうぞ。）\\nHere's your change.（おつりです。）\\nThank you. Come again.（ありがとうございました。またどうぞ。）\\n\\n★ ポイント：買うと決めたときは I'll take it. または I'll buy it. と言う。I want it. は子どもっぽく、ていねいではない。\"},{\"heading\":\"one の使い方と値段の言い方\",\"body\":\"買い物の会話では、同じ名詞をくり返さずに one を使う。\\n\\n■ one ＝ 前に出た名詞の代わり\\nI like this bag, but I don't like that one.（このかばんは好きだが、あれは好きではない。）← one ＝ bag\\nDo you have a smaller one?（もっと小さいのはありますか。）\\nThis one is nice.（これがいいですね。）\\n複数なら ones を使う。I like the red ones.\\n\\n★ ポイント：it と one のちがい\\nit … まったく同じもの（あのかばんそのもの）\\none … 同じ種類の別のもの（同じ型の別のかばん）\\n例）I lost my pen, so I bought a new one.（ペンをなくしたので新しいのを買った。）← 別のペン\\n例）I like this pen. I'll take it.（このペンが気に入った。これをください。）← そのペン\\n\\n■ 値段の言い方\\nIt's 500 yen.（500円です。）※ yen は複数形にしない（× 500 yens）\\nIt's three dollars.（3ドルです。）※ dollar は複数形になる\\nHow much is this in total?（全部でいくらですか。）\\nDo you take credit cards?（クレジットカードは使えますか。）\\n\\n■ 数量を言う\\na bottle of juice（1本のジュース）／two kilos of meat（肉2キロ）／a dozen eggs（卵1ダース）\\nI'd like two hamburgers, please.（ハンバーガーを2つください。）\\n※ I'd like ＝ I would like で、I want よりていねい。\\n\\n⚠ 注意：注文するときは I'd like …, please. の形が最もていねいで、入試の英作文でも安全である。\",\"figureId\":\"xf_eigo_s379\",\"mangaId\":\"eigo_s379_xm\"}],\"trapExamples\":[{\"question\":\"「これはいくらですか。」を英語にしなさい。\",\"wrongAnswer\":\"How many is this?\",\"trapExplanation\":\"How many と How much を「たくさん」でひとまとめに覚えているため、値段にも many を使ってしまう。値段は数ではなく量だという感覚がない。\",\"correctAnswer\":\"How much is this?\",\"correctExplanation\":\"値段をたずねるときは How much …? を使う。How many は数えられる名詞の数をたずねるときに使い、後ろに複数形の名詞が続く（How many apples …?）。値段は How much is it? / How much are these shoes? と主語の数で be動詞を変える。\"},{\"question\":\"（　）に入る語を選びなさい。 I lost my umbrella, so I bought a new （　）.　［it / one］\",\"wrongAnswer\":\"it\",\"trapExplanation\":\"前に出た umbrella を指すのだから it でよいと考えてしまう。it が「そのものずばり」を指す語だということを理解していない。\",\"correctAnswer\":\"one\",\"correctExplanation\":\"なくしたかさとは別の新しいかさなので、同じ種類の別のものを表す one を使う。it は「まさにそのもの」を指すので、なくしたかさを買い直すことになってしまう。a new one、a bigger one、the red ones のように形容詞と組み合わせて使う。\"}]}",
"{\"id\":\"eigo_s380\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現⑤：道案内\",\"description\":\"道をたずねる言い方と、道順を説明する表現を地図の場面で使いこなす\",\"intro\":\"道案内は、たずねる側より答える側のほうが難しいものです。「二つ目の角を右」を英語で言うには、序数を使って at the second corner と表します。Go straight や Turn right とあわせ、地図の上で使えるようにします。\",\"order\":880,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"たずね方は Excuse me. How can I get to …?／Where is …?\",\"Go straight（まっすぐ行く）／Turn right (left)（右／左に曲がる）。\",\"「2つ目の角を」は at the second corner と序数を使う。\",\"「左手に見えます」は You'll see it on your left.\",\"距離・時間は It's about five minutes on foot.／It takes ten minutes.\",\"答えられないときは I'm sorry, I'm a stranger here.（この辺りは不案内です）\"],\"sections\":[{\"heading\":\"道をたずねる・答える\",\"body\":\"道案内は地図を見て答える形で出題される。決まり文句を覚えれば必ず解ける。\\n\\n■ たずねる\\nExcuse me. How can I get to the station?（駅にはどう行けばよいですか。）\\nWhere is the post office?（郵便局はどこですか。）\\nCould you tell me the way to the library?（図書館への道を教えていただけますか。）\\nIs there a hospital near here?（この近くに病院はありますか。）\\n\\n★ ポイント：知らない人に話しかけるときは、必ず Excuse me. から始める。\\n\\n■ 道順を説明する\\nGo straight (down this street).（この道をまっすぐ行ってください。）\\nTurn right at the second corner.（2つ目の角を右に曲がってください。）\\nTurn left at the traffic light.（信号を左に曲がってください。）\\nGo straight for two blocks.（2ブロックまっすぐ行ってください。）\\nCross the street.（道をわたってください。）\\nYou'll see it on your right.（右手に見えます。）\\nIt's on your left.（左手にあります。）\\nIt's next to the bank.（銀行のとなりです。）\\nIt's across from the school.（学校の向かいです。）\\n\\n■ 距離・時間\\nIt's about five minutes on foot.（歩いて5分ほどです。）\\nIt takes ten minutes by bus.（バスで10分かかります。）\\nIt's not far from here.（ここから遠くありません。）\\n\\n■ お礼と返事\\nThank you very much. — You're welcome.／My pleasure.\\n\\n⚠ 注意：答えられないときは I'm sorry, I'm a stranger here.（この辺りは不案内です。）と言う。「見知らぬ人」ではなく「この土地に不案内な人」の意味である。\",\"figureId\":\"lf_eigoext10_380\"},{\"heading\":\"地図問題の解き方\",\"body\":\"地図を見て「どこに着くか」を答える問題は、次の手順で解く。\\n\\n■ 手順\\n①出発点（You are here. の位置）と、向いている方向を確認する。\\n②Go straight … で進む距離（ブロック数）を数える。\\n③Turn right / left で向きを変える。地図の上を向いているときの right は地図上の右、下を向いているときの right は地図上の左になることに注意する。\\n④on your right / left で最後の位置を決める。\\n\\n■ 使われる語\\nblock（区画）／corner（角）／traffic light, signal（信号）／crossing, intersection（交差点）／bridge（橋）／street, road（通り）／first, second, third（1つ目、2つ目、3つ目）\\n\\n例）Go straight for two blocks and turn left at the corner. You'll see the library on your right. It's next to the park.\\n（2ブロックまっすぐ行き、角を左に曲がってください。右手に図書館が見えます。公園のとなりです。）\\n\\n★ ポイント：角の数え方は序数を使う。at the first corner（1つ目の角で）／at the second traffic light（2つ目の信号で）。first・second・third を正確に読み取ることが得点の分かれ目になる。\\n\\n⚠ 注意：on your right（あなたの右手に）の your を落とさない。on the right とも言うが、on right とは言わない。\"},{\"heading\":\"なぜ答える側が難しく、なぜ序数を使うのか\",\"mangaId\":\"eigo_s380_manga\",\"body\":\"たずねる側は Excuse me. How can I get to 〜? と決まり文句一つで足りますが、答える側は**相手の位置から見た向き**で道順を組み立てなければなりません。Turn right の right は、説明する自分ではなく、歩く相手から見た右です。だから地図問題では、出発点と向いている方向を確認し、曲がるたびに指でたどります。頭の中だけで回すと、下を向いているときの right が地図上の左になることを忘れて、右と左が入れかわります。\\n\\n「2つ目の角」を the second corner と序数で言うのは、角を**数えるのではなく順番で指している**からです。two corners は「角が二つ」という数であって、どの角かを指せません。first・second・third を正確に読み取ることが、目的地を決める鍵です。序数の前には the を付けます。\\n\\n■ 確かめのしかた\\n①たずねるときは **Excuse me.** から始める。How can I get to 〜?／Where is 〜?／Is there a 〜 near here?\\n②道順の語を順にたどる：Go straight（for two blocks）→Turn right/left at the 〇th corner→It's on your right/left・next to・across from。\\n③「〇つ目」は**序数＋the**（at the second corner）。× at the two corner。\\n④距離・時間は It's about five minutes on foot.／It takes ten minutes by bus. 答えられないときは I'm sorry, I'm a stranger here.（この土地に不案内）。\\n\\n★ ここがポイント：道案内は**歩く相手から見た向き**で組み立てるので、地図の上で指でたどる。「〇つ目の角」は**順番なので序数（the second corner）**。最初は Excuse me.、終わりは You're welcome.。\"}],\"trapExamples\":[{\"question\":\"「2つ目の角を右に曲がってください。」を英語にしなさい。\",\"wrongAnswer\":\"Turn right at the two corner.\",\"trapExplanation\":\"「2つ目」を数の two で表してしまう。順番を表すには序数が必要だという意識が働かず、日本語の「2つ目」を「2」と処理してしまう。\",\"correctAnswer\":\"Turn right at the second corner.\",\"correctExplanation\":\"順番を表すときは序数を使い、the second corner とする。同じように the first traffic light（1つ目の信号）、the third street（3本目の通り）となる。序数の前には the を付けることも合わせて確認する。\"},{\"question\":\"（　）に入る表現を選びなさい。 A: Excuse me. Where is the city hall?　B: （　） I don't know this area well.　［I'm a stranger here. / I'm fine, thank you.］\",\"wrongAnswer\":\"I'm fine, thank you.\",\"trapExplanation\":\"あいさつの決まり文句を暗記しているため、場面を読まずにそれらしい表現を選んでしまう。後ろの文（この辺りをよく知らない）とのつながりを確かめていない。\",\"correctAnswer\":\"I'm a stranger here.\",\"correctExplanation\":\"道をたずねられて答えられないときは I'm sorry, I'm a stranger here.（この辺りは不案内です。）と言う。stranger は「見知らぬ人」ではなく「その土地に不案内な人」の意味である。後ろの I don't know this area well. とつながることを確かめれば選べる。\"}]}",
"{\"id\":\"eigo_s381\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話表現⑥：依頼・許可・提案・さそい\",\"description\":\"Can you …? / May I …? / Shall we …? / How about …? の使い分けを身につける\",\"intro\":\"Can you open the window? と Can I open the window? は、たった一語のちがいで意味が正反対になります。前者は相手にお願いし、後者は自分がしてよいかをたずねています。だれが動くのかで形を選び分けます。\",\"order\":881,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"依頼（相手にしてもらう）は Can you …?／Could you …?（よりていねい）\",\"許可（自分がする）は Can I …?／May I …?（よりていねい）\",\"さそいは Let's …／Shall we …?／How about …?／Why don't we …?\",\"How about の後ろは名詞か -ing。How about going to the movies?\",\"申し出は Shall I …?（〜しましょうか）\",\"断るときは I'm sorry, I can't. と理由を添える。\"],\"sections\":[{\"heading\":\"依頼と許可を区別する\",\"body\":\"Can you …? と Can I …? は形が似ているが、動作をする人がちがう。\\n\\n■ 依頼＝相手にしてもらう（主語は you）\\nCan you open the window?（窓を開けてくれますか。）\\nCould you help me?（手伝っていただけますか。）← よりていねい\\nWill you pass me the salt?（塩を取ってくれますか。）\\nWould you say that again?（もう一度言っていただけますか。）\\n— Sure.／All right.／OK.／I'm sorry, I can't.\\n\\n■ 許可＝自分がする（主語は I）\\nCan I use your pen?（ペンを使ってもいいですか。）\\nMay I come in?（入ってもいいですか。）← よりていねい\\n— Sure.／Of course.／Go ahead.（どうぞ。）\\n— I'm sorry, you can't.\\n\\n★ ポイント：Could / Would / May はていねいな形。目上の人や知らない人には Could you …?／May I …? を使う。\\n\\n■ 申し出＝自分がしてあげる\\nShall I open the window?（窓を開けましょうか。）\\nShall I carry your bag?\\n— Yes, please.／No, thank you.\\n\\n⚠ 注意：Can you …? と Can I …? は、日本語ではどちらも「〜してもいいですか／くれますか」となりやすい。主語を見て、動作をするのがどちらかを確かめる。\",\"figureId\":\"xf_eigo_s381\",\"mangaId\":\"eigo_s381_xm\"},{\"heading\":\"さそい方と答え方\",\"body\":\"いっしょに何かをしようとさそう言い方は、いくつもある。形のちがいに注意する。\\n\\n■ Let's ＋ 動詞の原形\\nLet's play tennis.（テニスをしましょう。）\\n— Yes, let's.／OK.／Sounds good.／That's a good idea.\\n— I'm sorry, I can't.\\n\\n■ Shall we ＋ 動詞の原形?\\nShall we go to the park?（公園に行きましょうか。）\\n— Yes, let's.\\n\\n■ How about ＋ 名詞・-ing?\\nHow about a cup of tea?（お茶はいかがですか。）\\nHow about going to the movies?（映画に行くのはどうですか。）\\n⚠ 注意：about は前置詞なので、後ろに動詞を置くときは -ing にする。How about go … は誤り。\\n\\n■ Why don't we …? / Why don't you …?\\nWhy don't we have lunch together?（いっしょに昼食を食べませんか。）\\nWhy don't you come with us?（いっしょに来ませんか。）\\n※ 「なぜ〜しないのか」ではなく、さそいの表現である。\\n\\n■ Would you like …?（すすめる）\\nWould you like some coffee?（コーヒーはいかがですか。）\\n— Yes, please.／No, thank you.\\nWould you like to come to my party?（パーティーに来ませんか。）\\n— I'd love to.（ぜひ。）\\n\\n★ ポイント：さそいを断るときは、I'm sorry, I can't. と言ってから理由を付けるとよい。\\n例）I'm sorry, I can't. I have to help my mother.\"}],\"trapExamples\":[{\"question\":\"「映画に行くのはどうですか。」を英語にしなさい。\",\"wrongAnswer\":\"How about go to the movies?\",\"trapExplanation\":\"How about を「〜はどうですか」という決まり文句として覚えているため、後ろに動詞の原形をそのまま続けてしまう。about が前置詞であることを意識していない。\",\"correctAnswer\":\"How about going to the movies?\",\"correctExplanation\":\"about は前置詞なので、後ろに動詞を置くときは -ing の形にする。How about going …? となる。同じさそいでも Let's go to the movies.／Shall we go to the movies? は動詞の原形を使うので、形のちがいをセットで確認する。\"},{\"question\":\"（　）に入る表現を選びなさい。 A: （　） help me with my homework?　B: Sure. What's the problem?　［Can you / Can I］\",\"wrongAnswer\":\"Can I\",\"trapExplanation\":\"「手伝ってもらえますか」という日本語から、自分が主語だと考えて Can I を選んでしまう。動作をするのがだれかを確認していない。\",\"correctAnswer\":\"Can you\",\"correctExplanation\":\"宿題を手伝うのは相手なので、依頼の Can you …? を使う。Can I …? は「私が〜してもよいですか」という許可を求める形で、Can I use your pen? のように使う。答えの Sure. What's the problem? からも、相手が手伝う側だと読み取れる。\"}]}",
"{\"id\":\"eigo_s382\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まぎらわしい語①：see / look / watch\",\"description\":\"「見る」を表す三つの動詞を、意識の強さと対象の動きで使い分ける\",\"intro\":\"テレビを見るのは watch、黒板を見るのは look at、星が見えるのは see。日本語ではどれも「見る」ですが、英語は意識の強さと、相手が動くかどうかで三つに分けます。この感覚をつかめば選びまちがえません。\",\"order\":882,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"see ＝ 自然に目に入る（見える）。意識して見ようとしなくてよい。\",\"look (at) ＝ 意識して視線を向ける。動かないものを見るときに使う。\",\"watch ＝ 動くものをじっと見続ける。テレビ・試合・動物の動き。\",\"look は前置詞 at が必要。see・watch は前置詞なしで目的語をとる。\",\"テレビは watch TV、映画館の映画は see a movie。\",\"「〜に会う」も see を使う。I saw Ken yesterday.\"],\"sections\":[{\"heading\":\"三つの「見る」のちがい\",\"mangaId\":\"eigo_s382_manga\",\"body\":\"英語では「見る」を表す動詞が三つあり、意識の強さと対象の動きで使い分ける。\\n\\n■ see ＝ 目に入る・見える\\n自分から見ようとしなくても、自然に視界に入ることを表す。\\n例）I can see Mt. Fuji from my window.（窓から富士山が見える。）\\n例）Can you see the bird in that tree?（あの木の鳥が見えますか。）\\n※ 「見える」という状態なので、ふつう進行形にしない（× I am seeing …）。\\n\\n■ look (at) ＝ 意識して視線を向ける\\n「そちらに目を向ける」という動作を表す。動かないものによく使う。\\n例）Look at the blackboard.（黒板を見なさい。）\\n例）Look at this picture.\\n⚠ 注意：look の後ろに見る対象を置くときは必ず at が必要である（× Look the blackboard.）。\\n\\n■ watch ＝ 動くものをじっと見続ける\\n時間をかけて動きを追うことを表す。\\n例）I watch TV after dinner.（夕食後にテレビを見る。）\\n例）We watched a soccer game.（サッカーの試合を見た。）\\n例）Watch your step.（足元に気をつけて。）\\n\\n★ ポイント：整理すると次のようになる。\\n・自然に目に入る → see\\n・止まっているものに視線を向ける → look at\\n・動いているものを追い続ける → watch\",\"figureId\":\"lf_eigoext10_382\"},{\"heading\":\"まぎらわしい組み合わせ\",\"body\":\"実際の入試では、次の組み合わせがくり返し問われる。\\n\\n■ テレビと映画\\nwatch TV（テレビを見る）… 家で動く画面を見続けるので watch\\nsee a movie（映画を見る）… 映画館へ「見に行く」ので see\\n※ 家でテレビ放送の映画を見るときは watch a movie on TV とも言う。中学受験では「watch TV」「see a movie」の二つを覚えておけばよい。\\n\\n■ 「会う」の see\\nsee には「（人に）会う」という意味もある。\\n例）I saw Ken at the station yesterday.（昨日、駅でケンに会った。）\\n例）See you tomorrow.（また明日。）← 別れのあいさつも「また会おう」の意味\\n※ 約束して会うときは meet を使う。\\n例）I met her at the library at three.（3時に図書館で彼女と待ち合わせた。）\\n初対面は meet。Nice to meet you.\\n\\n■ look の別の意味\\nlook ＋ 形容詞（〜に見える）：You look tired.\\nlook for（さがす）／look after（世話をする）／look like（〜に似ている）\\n\\n■ 過去形\\nsee → saw ／ look → looked ／ watch → watched\\n※ see は不規則変化。過去分詞は seen。\\n\\n⚠ 注意：Look! と一語で「見て！」と言うことはできるが、対象を続けるときは at が必要になる。Look! There is a rainbow.（見て！ にじが出ている。）\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を選びなさい。 I （　） TV for two hours yesterday.　［saw / watched］\",\"wrongAnswer\":\"saw\",\"trapExplanation\":\"「見た」＝ see の過去形 saw と、日本語から一対一で置きかえてしまう。テレビが「動くものを見続ける」対象だという区別ができていない。\",\"correctAnswer\":\"watched\",\"correctExplanation\":\"テレビのように動く画面を時間をかけて見続けるときは watch を使う。see は「自然に目に入る」ことを表すので、I can see Mt. Fuji. のように使う。映画館で映画を見るときは see a movie となるので、watch TV とセットで覚える。\"},{\"question\":\"「あの絵を見なさい。」を英語にしなさい。\",\"wrongAnswer\":\"Look that picture.\",\"trapExplanation\":\"日本語の「絵を見る」に「を」があるので、look の後ろに直接目的語を置いてしまう。see や watch では前置詞が不要なので、look も同じだと考えてしまう。\",\"correctAnswer\":\"Look at that picture.\",\"correctExplanation\":\"look は「視線を向ける」という動詞で、見る対象を示すには at が必要である。see と watch は前置詞なしで目的語をとる（see a movie、watch TV）。listen to（聞く）も同じく前置詞が要るので、look at / listen to をセットで覚える。\"}]}",
"{\"id\":\"eigo_s383\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まぎらわしい語②：hear / listen to と、その仲間\",\"description\":\"「聞く」を表す動詞の使い分けと、感覚を表す動詞のきまりを整理する\",\"intro\":\"音楽を聞くと言うとき、hear music と listen to music では意味がちがいます。前者は自然に耳に入ってくること、後者は自分から耳をかたむけることです。しかも listen には to が要ります。「聞く」の使い分けを整理します。\",\"order\":883,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"hear ＝ 自然に耳に入る（聞こえる）。listen (to) ＝ 意識して聞く。\",\"listen には to が必要。hear は前置詞なしで目的語をとる。\",\"see / hear は「見える・聞こえる」という状態なので、ふつう進行形にしない。\",\"can see / can hear の can は「〜できる」と訳さないことが多い。\",\"hear from（〜から便りがある）／hear of, hear about（〜のうわさを聞く）。\",\"感覚を表す動詞：feel（感じる）・smell（においがする）・taste（味がする）＋形容詞。\"],\"sections\":[{\"heading\":\"hear と listen to\",\"mangaId\":\"eigo_s383_manga\",\"body\":\"「聞く」も、意識するかどうかで動詞が変わる。see と look at の関係とまったく同じである。\\n\\n■ hear ＝ 自然に耳に入る\\n例）I can hear a bird singing.（鳥が鳴いているのが聞こえる。）\\n例）Did you hear that noise?（あの音が聞こえましたか。）\\n※ 前置詞は不要。hear the news、hear a sound。\\n\\n■ listen (to) ＝ 意識して耳をかたむける\\n例）I listen to music every night.（毎晩音楽を聞く。）\\n例）Listen carefully.（よく聞きなさい。）\\n⚠ 注意：聞く対象を置くときは to が必要（× listen music）。対象を言わないときは Listen! だけでよい。\\n\\n★ ポイント：see ⇔ look at と hear ⇔ listen to は同じ関係にある。\\n自然に入ってくる → see / hear（前置詞なし）\\n意識して向ける → look at / listen to（前置詞あり）\\n\\n■ 進行形にしない\\nsee・hear は「見える・聞こえる」という状態を表すので、ふつう進行形にしない。\\n例）I can hear you.（あなたの声が聞こえます。）\\n× I am hearing you.\\n一方 look・listen・watch は動作なので進行形にできる。\\n例）He is listening to the radio.\\n\\n■ can の使い方\\nsee・hear といっしょに使う can は「〜できる」と強く訳さなくてよい。\\n例）I can see the sea from here.（ここから海が見えます。）\",\"figureId\":\"xf_eigo_s383\"},{\"heading\":\"hear の熟語と、感覚を表す動詞\",\"body\":\"hear は前置詞と組んでいろいろな意味になる。\\n\\n■ hear の熟語\\nhear from ＋ 人（〜から便り・連絡がある）\\n　例）I heard from my friend in America.（アメリカの友達から便りがあった。）\\nhear of ／ hear about（〜のうわさを聞く・〜について耳にする）\\n　例）I've never heard of that singer.（その歌手のことは聞いたことがない。）\\nhear ＋ 人 ＋ 動詞の原形／-ing（人が〜するのが聞こえる）\\n　例）I heard someone call my name.（だれかが私の名前を呼ぶのが聞こえた。）\\n\\n■ 感覚を表す動詞＋形容詞\\nfeel（感じる）／smell（においがする）／taste（味がする）／sound（聞こえる）／look（見える）\\nこれらは後ろに形容詞を置いて「〜のように感じる・思われる」と使う。\\n例）I feel sick.（気分が悪い。）\\n例）This flower smells good.（この花はよいにおいがする。）\\n例）This soup tastes salty.（このスープはしょっぱい。）\\n例）That sounds good.（それはよさそうだね。）← さそいへの返事に使う\\n例）You look tired.（つかれているようだね。）\\n\\n★ ポイント：後ろが名詞のときは like を付ける。\\n例）It sounds like a good idea.／It tastes like chicken.\\n形容詞なら like なし、名詞なら like あり。look / look like と同じきまりである。\\n\\n■ 過去形\\nhear → heard（つづりに注意。heared とはしない）／listen → listened／feel → felt\"}],\"trapExamples\":[{\"question\":\"「私は毎晩、音楽を聞きます。」を英語にしなさい。\",\"wrongAnswer\":\"I listen music every night.\",\"trapExplanation\":\"日本語の「音楽を聞く」の「を」につられて、listen の後ろに直接目的語を置いてしまう。hear the news では前置詞が不要なので、同じでよいと考えてしまう。\",\"correctAnswer\":\"I listen to music every night.\",\"correctExplanation\":\"listen は「耳をかたむける」という動詞で、聞く対象を示すには to が必要である。hear は前置詞なしで目的語をとる（hear a sound）。look at / listen to は前置詞あり、see / hear / watch は前置詞なし、と対にして覚える。\"},{\"question\":\"（　）に入る語を選びなさい。 That sounds （　）. Let's do it!　［good / like good］\",\"wrongAnswer\":\"like good\",\"trapExplanation\":\"sounds like という形を覚えているため、後ろの語が形容詞か名詞かを確かめずに like を付けてしまう。look like の形に引きずられるのも原因。\",\"correctAnswer\":\"good\",\"correctExplanation\":\"good は形容詞なので like を付けず、That sounds good. とする。like が必要なのは後ろに名詞が来るときだけである（It sounds like a good idea.）。look / look like、taste / taste like も同じきまりで判断する。\"}]}",
"{\"id\":\"eigo_s384\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まぎらわしい語③：speak / talk / say / tell\",\"description\":\"「言う・話す」を表す四つの動詞を、後ろに来る語の形で使い分ける\",\"intro\":\"「英語を話す」は speak English、「友だちと話す」は talk with my friend、「さようならと言う」は say goodbye、「わたしに話す」は tell me。日本語では同じ「話す・言う」でも、うしろに来る語の形で四つに分かれます。\",\"order\":884,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"speak ＝ 声を出して話す。言語とともに使う（speak English）。\",\"talk ＝ 会話する。talk with / talk to ＋ 人、talk about ＋ 話題。\",\"say ＝ 言った「内容」を言う。say ＋ 内容（人を直接置かない）。\",\"tell ＝ 人に伝える。tell ＋ 人 ＋ 内容 の順に置く。\",\"say to ＋ 人、tell ＋ 人（to は不要）という語順のちがいが最重要。\",\"tell a lie（うそをつく）／tell the truth（本当のことを言う）／say hello to（よろしく伝える）。\"],\"sections\":[{\"heading\":\"四つの動詞の語順\",\"mangaId\":\"eigo_s384_manga\",\"body\":\"「話す・言う」を表す動詞は、後ろに何を置くかが動詞ごとに決まっている。語順で覚えるのがいちばん確実である。\\n\\n■ speak ＋ 言語 ／ speak to ＋ 人\\nHe speaks English very well.（彼は英語を上手に話す。）\\nMay I speak to Mr. Brown?（ブラウンさんとお話しできますか。）\\n※ 一方的に声を出す・言語を話す、というイメージ。\\n\\n■ talk with / to ＋ 人 ／ talk about ＋ 話題\\nI talked with my friend for an hour.（友達と1時間話した。）\\nWe talked about our summer vacation.（夏休みについて話した。）\\n※ おたがいに会話するイメージ。\\n\\n■ say ＋ 内容（人を直接置かない）\\nHe said, \\\"Good morning.\\\"（彼は「おはよう」と言った。）\\nShe said that she was tired.（彼女はつかれていると言った。）\\n人を入れたいときは to を使う。\\nHe said to me, \\\"Hello.\\\"（× He said me …）\\n\\n■ tell ＋ 人 ＋ 内容（to は不要）\\nHe told me the story.（彼は私にその話をした。）\\nPlease tell me your name.（名前を教えてください。）\\nTell him to call me.（彼に電話するように伝えて。）\\n※ tell の後ろにはまず「だれに」が来る。\\n\\n★ ポイント：say と tell の語順のちがいが最大の要点である。\\nsay to ＋ 人 ＋ 内容 ／ tell ＋ 人 ＋ 内容（to なし）\",\"figureId\":\"lf_eigoext10_384\"},{\"heading\":\"熟語と使い分けの練習\",\"body\":\"それぞれの動詞には決まった言い方がある。\\n\\n■ say の熟語\\nsay hello to ＋ 人（〜によろしくと伝える）\\n　例）Please say hello to your mother.（お母さんによろしく。）\\nsay good-bye（さようならを言う）\\nSay it again, please.（もう一度言ってください。）\\nHow do you say this in English?（これは英語で何と言いますか。）\\n\\n■ tell の熟語\\ntell a lie（うそをつく）／tell the truth（本当のことを言う）／tell a story（話をする）／tell ＋ 人 ＋ the way（道を教える）\\n　例）Could you tell me the way to the station?（駅への道を教えていただけますか。）\\n　例）Don't tell a lie.（うそをついてはいけない。）\\n\\n■ speak の熟語\\nspeak English / Japanese（英語・日本語を話す）\\nspeak slowly（ゆっくり話す）\\nCould you speak more slowly?（もっとゆっくり話していただけますか。）\\n\\n■ talk の熟語\\ntalk about（〜について話す）／talk with（〜と話す）／talk on the phone（電話で話す）\\n\\n■ 使い分けの見分け方\\n①後ろに言語がある → speak\\n②後ろに人だけ、または about がある → talk\\n③後ろに「言った内容」だけがある → say\\n④後ろに「人＋内容」がある → tell\\n\\n⚠ 注意：「私に教えて」は tell me、「私に言った」は said to me。日本語では区別しにくいので、英語の語順で判断する。\"}],\"trapExamples\":[{\"question\":\"「彼は私にその話をしてくれた。」を英語にしなさい。\",\"wrongAnswer\":\"He said me the story.\",\"trapExplanation\":\"say を「言う」と覚えているため、「私に言った」をそのまま said me としてしまう。tell との語順のちがいを整理していないのが原因。\",\"correctAnswer\":\"He told me the story.\",\"correctExplanation\":\"say の後ろには人を直接置けない。人を入れるときは said to me のように to が必要である。「人＋内容」の順に置けるのは tell で、He told me the story. となる。say ＋ 内容／tell ＋ 人 ＋ 内容、と語順で覚える。\"},{\"question\":\"（　）に入る語を選びなさい。 My father can （　） three languages.　［talk / speak］\",\"wrongAnswer\":\"talk\",\"trapExplanation\":\"「話す」＝ talk と一対一で覚えているため、言語が後ろに来ても talk を選んでしまう。talk が「会話する」という意味だと理解していない。\",\"correctAnswer\":\"speak\",\"correctExplanation\":\"言語を話す能力を表すときは speak を使う（speak English、speak three languages）。talk は人と会話することを表し、talk with my friend、talk about the movie のように使う。後ろに言語があれば speak、と判断する。\"}]}",
"{\"id\":\"eigo_s385\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"まぎらわしい語④：borrow / lend と bring / take\",\"description\":\"貸し借りと持ち運びの動詞を、動きの向きから正しく選べるようにする\",\"intro\":\"「消しゴムを借りていい？」を Can I rent your eraser? と言うと、お金を払う話になってしまいます。無料で持っていくなら borrow、その場で使うだけなら use です。貸し借りと持ち運びの動詞を、向きと場面で選び分けます。\",\"order\":885,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"borrow ＝ 借りる（自分のほうへ来る）／lend ＝ 貸す（自分から出ていく）。\",\"borrow ＋ もの ＋ from ＋ 人／lend ＋ 人 ＋ もの。\",\"bring ＝ 話し手のほうへ持ってくる／take ＝ 話し手から離れて持っていく。\",\"come / go と同じく、話し手を基準にした向きで決まる。\",\"use は「その場で使う」。電話やトイレは borrow ではなく use。\",\"teach（教える）と tell（伝える）、learn（習う）と study（勉強する）も対で確認する。\"],\"sections\":[{\"heading\":\"borrow と lend\",\"mangaId\":\"eigo_s385_manga\",\"body\":\"貸し借りの動詞は、ものが動く向きで決まる。\\n\\n■ borrow ＝ 借りる（相手から自分へ）\\nCan I borrow your eraser?（消しゴムを借りてもいいですか。）\\nI borrowed two books from the library.（図書館で本を2冊借りた。）\\n※ 形：borrow ＋ もの ＋ from ＋ 人・場所\\n\\n■ lend ＝ 貸す（自分から相手へ）\\nCan you lend me your pen?（ペンを貸してくれますか。）\\nI lent him my bike.（彼に自転車を貸した。）\\n※ 形：lend ＋ 人 ＋ もの、または lend ＋ もの ＋ to ＋ 人\\n※ 過去形は lent。\\n\\n★ ポイント：主語がどちらの立場かを見る。「私が借りる」なら I borrow …、「私が貸す」なら I lend …。日本語の「貸して」を英語にするときは、たのむ相手（you）が貸すので Can you lend me …? となる。\\n\\n■ use（使う）との区別\\nその場で使うだけで持ち去らないものには use を使う。\\n例）May I use your phone?（電話をお借りしてもいいですか。）\\n例）May I use the restroom?（トイレをお借りしてもいいですか。）\\n⚠ 注意：日本語では「借りる」と言うが、持ち去らないものに borrow は使わない。電話・トイレ・机は use である。\\n\\n■ そのほかの対\\nbuy（買う）⇔ sell（売る）／teach（教える）⇔ learn（習う）／give（与える）⇔ receive（受け取る）\",\"figureId\":\"lf_eigoext10_385\"},{\"heading\":\"bring と take\",\"body\":\"「持っていく・持ってくる」も、話し手を基準にした向きで決まる。come と go の関係と同じである。\\n\\n■ bring ＝ 話し手（または話題の中心）のいる場所へ持ってくる\\nBring your textbook to school tomorrow.（明日、教科書を学校に持ってきなさい。）← 先生が学校で言う\\nPlease bring some snacks to the party.（パーティーにおかしを持ってきてください。）\\nBring me the newspaper.（新聞を持ってきて。）\\n\\n■ take ＝ 話し手のいる場所から離れたところへ持っていく\\nTake this umbrella with you.（このかさを持っていきなさい。）\\nDon't forget to take your lunch.（弁当を持っていくのを忘れないで。）\\nHe took his dog to the park.（彼は犬を公園に連れていった。）\\n\\n★ ポイント：come / go と同じ考え方である。\\n自分のほう・相手のほうへ → come / bring\\n自分から離れて → go / take\\n\\n例）Can I bring my friend to your party?（あなたのパーティーに友達を連れていってもよいですか。）\\n※ 相手のいるパーティーへ向かうので bring を使う。日本語では「連れていく」だが英語では bring になる。ここが最大の注意点である。\\n\\n■ 人を連れていく・連れてくる\\ntake ＋ 人 ＋ to ＋ 場所（連れていく）\\nbring ＋ 人 ＋ to ＋ 場所（連れてくる）\\n例）My mother took me to the hospital.（母は私を病院へ連れていった。）\\n\\n■ 過去形\\nbring → brought ／ take → took ／ borrow → borrowed ／ lend → lent\\n※ brought のつづりは要注意。bringed とはしない。\"}],\"trapExamples\":[{\"question\":\"「ペンを貸してくれますか。」を英語にしなさい。\",\"wrongAnswer\":\"Can you borrow me your pen?\",\"trapExplanation\":\"「貸して」という日本語が「借りたい」という気持ちを表すため、borrow を選んでしまう。主語が you（貸す側）であることに注意が向かない。\",\"correctAnswer\":\"Can you lend me your pen?（または Can I borrow your pen?）\",\"correctExplanation\":\"動作をするのは you なので「貸す」の lend を使い、Can you lend me your pen? とする。自分を主語にするなら Can I borrow your pen? となる。主語がどちらの立場かを確かめてから動詞を選ぶ。borrow ＋ もの ＋ from ＋ 人、lend ＋ 人 ＋ もの の語順も合わせて覚える。\"},{\"question\":\"「あなたのパーティーに友達を連れていってもいいですか。」を英語にしなさい。\",\"wrongAnswer\":\"Can I take my friend to your party?\",\"trapExplanation\":\"日本語が「連れていく」なので take を選んでしまう。bring / take が話し手ではなく「向かう先にだれがいるか」で決まることを理解していない。\",\"correctAnswer\":\"Can I bring my friend to your party?\",\"correctExplanation\":\"相手（you）のいるパーティーへ向かうので、相手のほうへ近づく bring を使う。take は話し手からも相手からも離れた場所へ持っていく・連れていくときに使う。I'm coming!（今行きます）で come を使うのと同じ考え方である。\"}]}",
"{\"id\":\"eigo_s386\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"読解の基本姿勢①：設問を先に読む\",\"description\":\"本文を読む前に設問に目を通し、「何を探すのか」を決めてから読み始める\",\"intro\":\"長文を最初から丁寧に読み、読み終えてから設問を見る——多くの人がこの順で解いています。ところが本文の内容はもう頭から消えていて、結局もう一度読み直すことになります。先に設問を読むだけで、読む目的がはっきりします。\",\"order\":886,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"本文より先に設問を読む。何を探すか決まっていない読み方は、読み終わってからもう一度読み直すことになる。\",\"設問の疑問詞をチェックする。What time なら時刻、How many なら数、Why なら理由が答え。\",\"設問に出てくる固有名詞（人名・曜日・場所）に印をつけ、本文でその語を見つけたら周りを丁寧に読む。\",\"設問はふつう本文の順番どおりに並んでいる。第1問の答えは前半、最後の問いは後半にある。\",\"選択肢まで全部先に読む必要はない。設問文だけで十分（選択肢を覚えようとすると混乱する）。\"],\"sections\":[{\"heading\":\"なぜ設問を先に読むのか\",\"mangaId\":\"eigo_s386_manga\",\"body\":\"長文問題で時間が足りなくなる人のほとんどは、「本文を最初から最後まで読んでから設問を見る」という順で解いている。この順だと、読んでいる間じゅう何が問われるか分からないので、全部を同じ強さで読むことになる。そして設問を見た瞬間に「どこに書いてあったっけ」となり、もう一度本文をさがす。つまり本文を2回読んでいることになる。\\n\\n■ 正しい手順\\n①設問文だけを読む（選択肢は読まない）\\n②何を探すのかをメモする（時刻・人数・理由・気持ち など）\\n③本文を頭から1回読む。②で決めたものが出てきたら線を引く\\n④設問に戻って、線を引いた場所を確かめながら答える\\n\\n例）設問が What time does Ken leave home? なら、探すのは「時刻」である。本文を読みながら数字と時刻表現（at seven, before breakfast など）にだけ印をつければよい。\\n\\n★ ポイント：設問を先に読むのは「答えを先に知る」ためではなく、本文を読むときの目のはたらかせ方を変えるためである。探し物が決まっている人は、決まっていない人の半分の時間で見つけられる。\\n\\n⚠ 注意：設問の先読みは30秒以内で終える。設問文を丁寧に和訳していたら本末転倒になる。疑問詞と固有名詞だけを拾えばよい。\",\"figureId\":\"xf_eigo_s386\"},{\"heading\":\"実際の英文でやってみる\",\"body\":\"次の英文を読む前に、下の設問に目を通すこと。\\n\\nKen is a junior high school student. He gets up at six thirty every morning. Before breakfast, he walks his dog, Momo, for twenty minutes. He leaves home at seven forty and takes the bus to school. School starts at eight thirty. After school, he practices tennis with his friends until five. He usually gets home at six and does his homework before dinner. On Sunday, he does not practice tennis. He goes to the library and reads books about animals. He wants to be a vet in the future.\\n\\n設問\\n(1) What time does Ken leave home?\\n(2) What does Ken do on Sunday?\\n(3) What does Ken want to be?\\n\\n■ 先読みでわかること\\n(1)は「時刻」を探す → 数字に印。\\n(2)は「日曜日」を探す → On Sunday という語に印。\\n(3)は「将来の夢」を探す → want to be という語に印。\\n\\nこの3つだけを意識して読めば、本文は1回読むだけで足りる。実際、答えはそれぞれ at seven forty（7時40分）／He goes to the library and reads books about animals.／He wants to be a vet.（獣医）で、いずれも印をつけた場所のすぐそばにある。\\n\\n★ ポイント：(2)のように On Sunday と本文に書いてあるとき、その前後は「ふだんの日」ではなく「日曜日だけの行動」である。曜日・季節・時を表す語は、本文の内容が切りかわる合図になる。\"}],\"trapExamples\":[{\"question\":\"上の英文について、What time does Ken get to school? に答えなさい。\",\"wrongAnswer\":\"At eight thirty.（8時30分）\",\"trapExplanation\":\"School starts at eight thirty. の 8:30 という数字が目に入り、「学校＝8時30分」と結びつけて答えてしまう。設問の get to school（学校に着く）と、本文の School starts（授業が始まる）を同じ意味だと思いこんでいる。\",\"correctAnswer\":\"本文に書かれていない（答えられない）\",\"correctExplanation\":\"本文にあるのは「家を7時40分に出る」「授業は8時30分に始まる」の2つだけで、学校に到着した時刻は書かれていない。バスに何分乗ったかも書かれていないので計算もできない。設問の先読みで「時刻」と決めても、その時刻が本当にその出来事の時刻かどうかは英語をきちんと読んで確かめること。\"},{\"question\":\"上の英文について、How long does Ken walk his dog? に答えなさい。\",\"wrongAnswer\":\"For thirty minutes.\",\"trapExplanation\":\"six thirty（6時30分）の thirty が残っていて、「30分」と答えてしまう。時刻の thirty と、時間の長さの twenty minutes を区別せずに数字だけを拾ったための誤り。\",\"correctAnswer\":\"For twenty minutes.（20分間）\",\"correctExplanation\":\"How long は「どのくらいの長さ」を聞く疑問詞なので、答えは時刻ではなく期間である。本文の he walks his dog, Momo, for twenty minutes に for が付いていることに注目する。at＋時刻は「〜時に」、for＋期間は「〜の間」と、前置詞で見分けられる。\"}]}",
"{\"id\":\"eigo_s387\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"読解の基本姿勢②：返り読みをしない\",\"description\":\"意味のかたまりごとに前から理解し、日本語の語順に直さずに読み進める\",\"intro\":\"英文を「わたしは 昨日 買った 本を 読んだ」と日本語の順に組み直して読んでいませんか。この読み方は時間が二倍かかり、長い文ほど途中で迷子になります。英語は前から順に、かたまりのまま理解できます。読み方を切りかえます。\",\"order\":887,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"返り読み＝英文の後ろから前へ戻って訳す読み方。時間が2倍かかるうえ、長い文ほど途中で意味を見失う。\",\"英語は「意味のかたまり（チャンク）」ごとに、前から順に理解する。\",\"かたまりの切れ目は、前置詞（in／on／with）・接続詞（that／when／because）・関係代名詞（who／which）の直前。\",\"訳すのではなく「情景を思い浮かべる」。日本語に直すのは答えを書くときだけでよい。\",\"音読の練習でも、かたまりごとに区切って読むと語順のまま理解する力がつく。\"],\"sections\":[{\"heading\":\"返り読みが読解をおそくする\",\"body\":\"英語を日本語らしく訳そうとすると、どうしても文の後ろから前へ戻ることになる。これを返り読みという。\\n\\n例）The boy who is playing the guitar under the big tree in the park is my brother.\\n返り読み：「公園の／大きな木の下で／ギターを弾いている／少年は／私の兄です」\\n→ 目が右端から左へ何度も往復している。1文でこれをやると、20文の長文では往復が数百回になる。\\n\\n■ 前から読む（チャンク読み）\\nThe boy ／ who is playing the guitar ／ under the big tree ／ in the park ／ is my brother.\\n「その少年は → ギターを弾いている → 大きな木の下で → 公園の中の → 私の兄だ」\\n情報が出てきた順に足していくだけで、戻る必要がない。\\n\\n★ ポイント：チャンクの切れ目は、①前置詞の前（under, in）②関係代名詞の前（who, which, that）③接続詞の前（when, because, if）④カンマの所、の4つがほとんどである。\\n\\n⚠ 注意：チャンク読みは「訳さない」練習ではなく「戻らない」練習である。意味は取る。ただし日本語の語順に並べかえる作業を最後まで先送りにする。\"},{\"heading\":\"実際の英文で区切ってみる\",\"body\":\"次の英文を、スラッシュ（／）の位置で区切りながら前から読む。\\n\\nLast Saturday, I went to the city museum with my father. We saw a special show about old Japanese houses. The show started at ten and finished at noon. I liked the small model of a farmhouse the best. Its roof was made of straw, and it looked very warm. My father told me that his grandmother lived in a house like that. After we left the museum, we had lunch at a small restaurant near the station. I ate curry and rice, and my father had noodles. It was a wonderful day.\\n\\n■ 区切り方の例\\nLast Saturday, ／ I went to the city museum ／ with my father.\\nWe saw a special show ／ about old Japanese houses.\\nMy father told me ／ that his grandmother lived in a house ／ like that.\\nAfter we left the museum, ／ we had lunch ／ at a small restaurant ／ near the station.\\n\\n■ 前から意味を足していく\\n「この前の土曜日 → 私は市立博物館に行った → 父と」\\n「父は私に言った → 祖母がある家に住んでいたと → そんな家に」\\n\\n★ ポイント：told me that … の that は「〜ということ」で、ここから文が1つ始まる合図。that を見たら「ここから新しい文が始まる」と考えて区切ればよい。\\n\\n⚠ 注意：区切りすぎもよくない。a small restaurant を a ／ small ／ restaurant のように切ると、かえって意味がつながらない。「1つのまとまった意味」になる長さで切ること。\"},{\"heading\":\"なぜ前から読めるのか、なぜ切れ目が4か所なのか\",\"mangaId\":\"eigo_s387_manga\",\"body\":\"英語は「中心の語を先に言い、説明をあとから足す」ことばです。The boy（少年は）→who is playing（弾いている）→under the tree（木の下で）→in the park（公園の）→is my brother（兄だ）と、**情報が出てくる順に足していけば意味がつながる**ようにできています。日本語の順に並べ直すと、右端から左へ戻る往復が必要になり、長文では数百回になります。返り読みは時間が二倍かかるだけでなく、戻っている間に前の内容を忘れて迷子になります。\\n\\n切れ目が前置詞・関係代名詞・接続詞・カンマの前なのは、これらの語が**「ここから説明を足します」という合図**だからです。前置詞は場所や時の説明、関係代名詞は名詞の説明、接続詞（that・when・because）は新しい文の始まり。told me that の that を見たら「ここから別の主語と動詞が始まる」と考えれば、lived の主語が his grandmother だとすぐ分かります。\\n\\n■ 確かめのしかた\\n①英文にスラッシュを入れる：**前置詞の前・関係代名詞の前・接続詞の前・カンマ**。My father told me ／ that his grandmother lived in a house ／ like that.\\n②切ったかたまりを**前から順に日本語で足す**。「父は私に言った→祖母が家に住んでいたと→そんな家に」。戻らない。\\n③that のあとに主語と動詞のセットがもう一つあるか。told の主語と lived の主語を分けて言えるか。\\n④切りすぎていないか。a small restaurant は一つのまとまり。Its のような代名詞は、直前の名詞のかたまりの中で「意味が通る語」を指す（Its roof→屋根があるのは farmhouse）。\\n\\n★ ここがポイント：英語は**情報が出た順に足せばつながる**ので前から読む。切れ目は**前置詞・関係代名詞・接続詞・カンマ**という「ここから説明」の合図。that のあとは主語と動詞をもう一組数える。\",\"figureId\":\"xf_eigo_s387\"}],\"trapExamples\":[{\"question\":\"上の英文について、Who lived in an old Japanese house? に答えなさい。\",\"wrongAnswer\":\"My father.（筆者の父）\",\"trapExplanation\":\"My father told me that … の文で、文頭の My father だけを見て「父が住んでいた」と読んでしまう。that の後ろに his grandmother という別の主語があることを見落とした典型的な返り読みのミス。\",\"correctAnswer\":\"The writer's great-grandmother.（＝父の祖母）\",\"correctExplanation\":\"My father told me ／ that his grandmother lived in a house like that. と区切れば、told の主語は My father、lived の主語は his grandmother だとすぐわかる。that の前と後ろで主語と動詞のセットが2組あることを意識する。前から順にかたまりで読めば取りちがえない。\"},{\"question\":\"上の英文について、What was made of straw? に答えなさい。\",\"wrongAnswer\":\"The model.（模型）\",\"trapExplanation\":\"直前の文に the small model of a farmhouse があるため、Its を「模型の」と取ってしまう。しかし Its roof（その屋根）とあるので、指しているのは屋根を持つもの＝農家である。\",\"correctAnswer\":\"The roof of the farmhouse.（農家の屋根）\",\"correctExplanation\":\"Its roof was made of straw の Its は直前の名詞のかたまり a farmhouse を指す。model of a farmhouse のうち中心の名詞は model だが、「屋根がある」のは家のほうだと意味で判断する。be made of 〜（〜でできている）は材料が見た目でわかるときに使う表現で、straw は「わら」。\"}]}",
"{\"id\":\"eigo_s388\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"読解の基本姿勢③：わからない語で止まらない\",\"description\":\"知らない単語が出ても読み飛ばし、文全体・段落全体の意味をつかむ\",\"intro\":\"入試の長文には、知らない単語が必ず数個まぎれています。全部わかるようには作られていないのです。そこで止まってしまうと最後まで読めません。飛ばしてよい語と、飛ばしてはいけない語の見分け方を身につけます。\",\"order\":888,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"入試の長文には、必ず知らない単語が数個入っている。全部わかるようには作られていない。\",\"知らない語は、まず「読み飛ばして先へ進む」。設問で問われていなければ意味を知らなくても解ける。\",\"同じ語がくり返し出てくる語（キーワード）は飛ばさず、周りの文からおおよその意味を決める。\",\"語の意味より、その語が「よいこと・わるいこと」のどちらかを判断できれば足りることが多い。\",\"注（＊印の語注）は本文を読む前に必ず確認する。難語はたいてい注がついている。\"],\"sections\":[{\"heading\":\"知らない語との付き合い方\",\"body\":\"英語の長文で、1語もわからない語がないという状態はまずない。入試問題は、受験生が知らない語をいくつか含んだうえで、それでも内容がつかめるように作られている。だから「知らない語で止まる」ことこそが最大の失点原因になる。\\n\\n■ 3段階のふるい分け\\n①1回しか出てこない語 → 飛ばす。前後の意味がつながればそれでよい。\\n②2回以上出てくる語 → 飛ばさない。その文章の中心の語（キーワード）である可能性が高い。\\n③設問に出ている語 → 必ず意味を決める。周りの文からの推測が必要。\\n\\n■ 「よい・わるい」だけ決める\\nたとえば The weather was terrible, so we could not go out. の terrible がわからなくても、so we could not go out（だから外出できなかった）から「わるい天気」だとわかる。細かい意味（ひどい）まで出す必要はない。\\n\\n★ ポイント：語注（＊がついた語の日本語訳）は問題用紙の下や本文のあとにある。本文を読み始める前に語注に目を通しておくと、その語で止まらずにすむ。\\n\\n⚠ 注意：知らない語を「たぶんこういう意味だろう」と決めたら、必ずそれを本文にあてはめて意味が通るか確かめる。決めっぱなしにすると、そこから先の読み方が全部ずれる。\"},{\"heading\":\"実際の英文で試す\",\"body\":\"次の英文には、多くの小学生が知らない語 hibernation／hibernate が出てくる。\\n\\nMany animals sleep through the winter. This long sleep is called hibernation. Bears, frogs, and some kinds of squirrels hibernate. Before winter comes, they eat a lot of food and become fat. When the weather gets cold, they go into a hole or a cave. Their bodies become cool, and their hearts beat very slowly. In this way, they use only a little energy. They do not need to look for food in the snow. When spring comes, they wake up and come out. They are thin and very hungry, so they start looking for food at once.\\n\\n■ hibernation の意味を決める手順\\n①直前の文：Many animals sleep through the winter.（多くの動物は冬の間ずっと眠る）\\n②次の文：This long sleep is called hibernation.（この長い眠りは hibernation と呼ばれる）\\n→ This long sleep ＝ hibernation。つまり「冬眠」である。\\n\\nこのように、知らない語のすぐ前後に「＝」の関係を作る表現があることが非常に多い。\\n・A is called B（AはBと呼ばれる）\\n・A, or B（AつまりB）\\n・A means B（AはBを意味する）\\n・A, that is, B（Aすなわち B）\\n\\n★ ポイント：is called の直前の文には、必ずその語の説明がある。called を見たら前の文へ1文だけ戻る。\\n\\n⚠ 注意：hibernate（動詞）と hibernation（名詞）は形がちがうだけで同じ内容。-tion で終わる語は名詞だと知っておくと、品詞のちがいで混乱しなくなる。\",\"figureId\":\"xf_eigo_s388\",\"mangaId\":\"eigo_s388_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、Why do animals eat a lot before winter? に答えなさい。\",\"wrongAnswer\":\"Because they are very hungry.（とてもおなかがすいているから）\",\"trapExplanation\":\"本文の最後に very hungry という語があるので、それを理由として引いてきてしまう。しかし very hungry なのは「春に目覚めたあと」で、冬の前の話ではない。時をあらわす語（Before winter／When spring comes）を無視して語句だけを拾うと起こるミス。\",\"correctAnswer\":\"エネルギーをたくわえて（太って）冬の間の長い眠りに備えるため。冬の間は雪の中で食べ物をさがす必要がないようにするため。\",\"correctExplanation\":\"Before winter comes, they eat a lot of food and become fat. のあと、In this way, they use only a little energy. They do not need to look for food in the snow. と続く。つまり「先に食べて太る → 眠っている間はエネルギーをほとんど使わない → 雪の中でえさをさがさずにすむ」という流れである。理由を問われたら、その文の前後3文の範囲で因果関係を確かめる。\"},{\"question\":\"上の英文について、下線部 Their bodies become cool. の cool の意味として正しいものを選びなさい。\",\"wrongAnswer\":\"かっこいい\",\"trapExplanation\":\"cool を「かっこいい」という日本語のカタカナ語の意味で覚えているため、そのまま当てはめてしまう。英語の cool の基本の意味は「冷たい・すずしい」で、「かっこいい」は後からできたくだけた意味である。\",\"correctAnswer\":\"（体温が下がって）冷たくなる\",\"correctExplanation\":\"直後に and their hearts beat very slowly（心臓の動きがとてもゆっくりになる）と続き、さらに they use only a little energy（エネルギーをほとんど使わない）とある。体を冷やして活動を落とすという冬眠の説明なので、cool は「冷たい」である。カタカナになっている英語（cool・スマート smart＝賢い、ナイーブ naive＝世間知らず）は、日本語の意味と英語の意味がずれていることが多いので要注意。\"}]}",
"{\"id\":\"eigo_s389\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語と動詞を見つける①：文の骨組みをつかむ\",\"description\":\"どんな長い文も「だれが・どうする」の2つに絞れば読める\",\"intro\":\"一行以上ある長い文を前にすると、どこから手をつけてよいか分からなくなります。しかしどんな文にも「だれが・どうする」の骨組みが必ず一組あり、残りはすべて飾りです。まず二語を見つける——それだけで文は立ち上がります。\",\"order\":889,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"英語の文には必ず主語（S）と動詞（V）が1組以上ある。まずこの2つを丸で囲む。\",\"語順は S → V → O → M（修飾語）で固定されている。日本語のように入れかえられない。\",\"文の2番目のかたまりが動詞。be動詞（am/is/are/was/were）か一般動詞のどちらかである。\",\"前置詞（in／on／at／with／for）が付いたかたまりは修飾語なので、骨組みから外してよい。\",\"骨組みだけ取り出して意味が通れば、その読み取りは正しい。\"],\"sections\":[{\"heading\":\"英語の語順は動かない\",\"body\":\"日本語は「私は昨日公園で本を読んだ」も「昨日私は公園で本を読んだ」も同じ意味になる。助詞（は・を・で）が役割を示すので、語の順番を変えられるからである。\\n\\n英語には助詞がない。そのかわり「置かれた場所」が役割を決める。だから語順を変えると意味が変わってしまう。\\n\\n例）The cat chased the dog.（ネコがイヌを追いかけた）\\n　　The dog chased the cat.（イヌがネコを追いかけた）\\n同じ4語なのに、置き場所だけで意味が正反対になる。\\n\\n■ 基本の並び方\\nS（主語）→ V（動詞）→ O（目的語）→ M（修飾語）\\n例）I ／ read ／ a book ／ in the park ／ yesterday.\\n　　私は／読んだ／本を／公園で／昨日\\n\\n日本語に訳すときは、修飾語（in the park, yesterday）を前へ回して「私は昨日公園で本を読んだ」とする。この「回す」作業があるから、日本語話者は英語を後ろから読みたくなる。だが読むときは英語の順のまま理解し、答案を書くときだけ回せばよい。\\n\\n★ ポイント：長文で迷ったら「2番目のかたまりが動詞」と考える。動詞が見つかれば、その左が主語、右が目的語や補語である。\\n\\n⚠ 注意：文頭に修飾語が置かれることはよくある（Yesterday, I read a book.）。カンマがあればそこまでが修飾語なので、カンマの後ろから S を探す。\",\"figureId\":\"lf_eigoext11_389\",\"mangaId\":\"eigo_s389_xm\"},{\"heading\":\"骨組みを取り出す練習\",\"body\":\"次の各文から、主語（S）と動詞（V）だけを取り出す。\\n\\n① In our school, all the students clean their classrooms after lunch.\\n→ 文頭 In our school は前置詞 In で始まるので修飾語。カンマの後ろから探す。\\nS＝all the students　V＝clean\\n骨組み：The students clean.（生徒たちがそうじをする）\\n\\n② There are twenty desks in this room.\\n→ There is／There are は「〜がある」の形。この文の本当の主語は be動詞の後ろの twenty desks。\\nS＝twenty desks　V＝are\\n\\n③ My father, who works at a hospital, comes home very late.\\n→ カンマにはさまれた who works at a hospital は My father の説明。外す。\\nS＝My father　V＝comes\\n骨組み：My father comes home very late.（父はとても遅く帰ってくる）\\n\\n④ Playing the piano is a lot of fun.\\n→ 動詞の -ing 形が文頭に来ると「〜すること」という主語になる。\\nS＝Playing the piano　V＝is\\n\\n★ ポイント：動詞を見つけるときは「三単現の -s」「be動詞」「過去形の -ed」を手がかりにする。works も comes も -s が付いているので動詞だとすぐわかる。\\n\\n⚠ 注意：③の works は who の動詞であって、文全体の動詞ではない。1つの文に動詞が2つ以上あるときは、接続詞や関係代名詞（who・which・that・when・because）が必ずそばにある。それが「おまけの文」の目印である。\"}],\"trapExamples\":[{\"question\":\"There are many books in my brother’s room. の主語（S）を答えなさい。\",\"wrongAnswer\":\"There\",\"trapExplanation\":\"英語の文は主語で始まるという思いこみから、文頭の There をそのまま主語だと考えてしまう。しかし There are 〜 の There は「そこに」という意味を持たない、形だけの語である。\",\"correctAnswer\":\"many books\",\"correctExplanation\":\"There is／There are 〜 は「〜がある・いる」を表す決まった形で、本当の主語は be動詞の後ろに来る。主語が複数なら are、単数なら is を使うのもそのため（There is a book. ／ There are many books.）。「〜がある」と訳す文を見たら be動詞の右側を主語とみなす。\"},{\"question\":\"The girl talking with my mother is my sister. の動詞（V）を答えなさい。\",\"wrongAnswer\":\"talking\",\"trapExplanation\":\"文の前のほうにある talking を見て、これが動詞だと考えてしまう。しかし -ing だけの形（動詞のing形）は、そのままでは文の動詞になれない。動詞として働くには be動詞（is talking のように）が必要である。\",\"correctAnswer\":\"is\",\"correctExplanation\":\"talking with my mother は直前の The girl を後ろから説明しているかたまり（「私の母と話している」）で、文の骨組みには入らない。これを外すと The girl is my sister. となり、動詞は is だとわかる。-ing の前に be動詞があるかどうかを必ず確かめること。\"}]}",
"{\"id\":\"eigo_s390\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語と動詞を見つける②：長い主語を切り離す\",\"description\":\"主語のうしろに説明がくっついて長くなった文の骨組みを見抜く\",\"intro\":\"The boy playing the piano over there is my brother. どれが動詞か分かりますか。playing に見えて、実は is です。主語のうしろに説明がくっついて長くなっているだけ。かたまりを外して骨組みを取り出す練習をします。\",\"order\":890,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"主語が長くなるのは、主語の後ろに説明のかたまりがくっついているから。\",\"説明のかたまりの目印は who／which／that／-ing／過去分詞／前置詞（of・in・with）。\",\"説明のかたまりを外すと、必ず「名詞1語＋動詞」の骨組みが残る。\",\"主語が長くても、動詞の形（is か are か）を決めるのは主語の中心の名詞1語だけ。\",\"長い主語の文では、動詞は「かたまりが終わったあと」に現れる。動詞が出てきたところが主語の切れ目。\"],\"sections\":[{\"heading\":\"主語はどこまでか\",\"body\":\"入試の長文でいちばん読みにくいのは、主語が長い文である。\\n\\n例）The girl who plays the piano every Sunday is my sister.\\n\\n主語を「The girl」だけだと思って読み進めると、plays が動詞に見え、「その少女は毎週日曜日にピアノを弾く」で文が終わったように感じる。ところがそのあとに is my sister が残ってしまい、意味が取れなくなる。\\n\\n■ 正しい切り分け\\n① The girl（主語の中心）\\n② who plays the piano（①を説明する部分）\\n③ every Sunday（②の中の修飾語）\\n④ is my sister（文全体の動詞＋補語）\\n\\n②③をカッコに入れて外すと、The girl is my sister.（その少女は私の姉だ）という骨組みが残る。\\n\\n■ 「動詞が2つあったら片方はおまけ」\\n上の文には plays と is の2つの動詞がある。1つの文に動詞は1つが原則なので、2つあるときは片方が「おまけの文」の動詞である。おまけの文の目印になるのが who／which／that などである。\\n\\n★ ポイント：who や that を見たら、そこから「もう1つの文が始まる」と考える。そしてその文がどこで終わるか（次の動詞が出てくる直前まで）を確かめる。\\n\\n⚠ 注意：主語が長くても、be動詞を is にするか are にするかを決めるのは中心の名詞1語である。The books on the desk are mine.（主語の中心は books なので are）。on the desk の desk（単数）につられて is にしてはいけない。\",\"figureId\":\"lf_eigoext11_390\",\"mangaId\":\"eigo_s390_xm\"},{\"heading\":\"長い主語のいろいろな形\",\"body\":\"主語を長くする方法は、大きく分けて4つしかない。\\n\\n■ ①前置詞のかたまりが後ろに付く\\nThe book on the desk in the living room is mine.\\n→ 主語の中心は The book。on the desk も in the living room も外す。\\n\\n■ ②-ing のかたまりが後ろに付く（〜している…）\\nThe boy standing near the gate is my friend.\\n→ 主語の中心は The boy。standing near the gate（門の近くに立っている）を外す。\\n\\n■ ③過去分詞のかたまりが後ろに付く（〜された…）\\nThe letter written in English was from Australia.\\n→ 主語の中心は The letter。written in English（英語で書かれた）を外す。\\n\\n■ ④who／which／that のかたまりが後ろに付く\\nThe students who joined the club last year cleaned the river.\\n→ 主語の中心は The students。who joined the club last year を外す。\\n骨組み：The students cleaned the river.\\n\\n■ さらに、主語そのものが動詞から作られることもある\\nPlaying soccer with my friends is a lot of fun.（友達とサッカーをすることはとても楽しい）\\nTo read many books is important.（多くの本を読むことは大切だ）\\nこの場合、主語は「〜すること」でひとまとまり。動詞は必ず単数扱いで is を使う。\\n\\n★ ポイント：どの型でも、外すべきかたまりは「名詞の直後から、文全体の動詞の直前まで」である。だから「次に出てくる動詞」をさがせば、主語の終わりが自動的に決まる。\"}],\"trapExamples\":[{\"question\":\"The pictures taken by my father in Kyoto ( is / are ) very beautiful. 正しいほうを選びなさい。\",\"wrongAnswer\":\"is\",\"trapExplanation\":\"動詞のすぐ前にある Kyoto（単数）や father（単数）につられて is を選んでしまう。長い主語の文では、動詞の直前の名詞が主語だと勘違いしやすい。\",\"correctAnswer\":\"are\",\"correctExplanation\":\"主語の中心は文頭の The pictures（複数）である。taken by my father in Kyoto は「父が京都で撮った」という説明のかたまりなので、いったん外して The pictures are very beautiful. と考える。長い主語の文では、いちばん前の名詞に○をつけてから動詞を決めること。\"},{\"question\":\"The man reading a newspaper on the bench is my uncle. を日本語にしなさい。\",\"wrongAnswer\":\"その男の人はベンチで新聞を読んでいて、私のおじです。\",\"trapExplanation\":\"reading を文の動詞ととらえ、「読んでいる」と「おじです」を2つの述語として並べてしまう。実際には reading 〜 bench は主語の説明にすぎず、文の述語は is だけである。\",\"correctAnswer\":\"ベンチで新聞を読んでいるその男の人は、私のおじです。\",\"correctExplanation\":\"reading a newspaper on the bench は直前の The man を後ろから説明するかたまりで、日本語にするときは前へ回す。骨組みは The man is my uncle. の1文だけである。-ing のかたまりの前に be動詞がなければ、それは動詞ではなく修飾語だと判断する。\"}]}",
"{\"id\":\"eigo_s391\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語と動詞を見つける③：文の切れ目を見つける\",\"description\":\"接続詞・関係代名詞を目印に、1文の中の「2つの文」を分ける\",\"intro\":\"一つの文の中に「主語＋動詞」が二組あることがあります。そんなときは、必ずどこかにつなぎ役の語がひそんでいます。and・because・when・who・which、そしてカンマ。この目印を見つければ、長い文も割って読めます。\",\"order\":891,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"1つの文に「主語＋動詞」の組が2つ以上あるとき、必ずつなぎ役の語がある。\",\"つなぎ役は3種類：接続詞（and／but／because／when／if／that）、関係代名詞（who／which／that）、カンマ。\",\"when／if／because で始まるかたまりは、文の前半にも後半にも置ける。前半に置いたときはカンマで区切る。\",\"that は「〜ということ」（接続詞）と「〜する…」（関係代名詞）の2つの働きがあり、前が動詞なら接続詞。\",\"つなぎ役の語に印をつけてから読むと、長い文が短い文の足し算に見えてくる。\"],\"sections\":[{\"heading\":\"切れ目の目印を覚える\",\"body\":\"英語の1文が長くなるのは、短い文が接続詞でつながれているからである。だからつなぎ役の語を見つけて、そこで線を引けば、必ず短い文に分解できる。\\n\\n■ 目印になる語（これだけ覚えればよい）\\n・and／but／or／so … 対等につなぐ\\n・when（〜のとき）／while（〜する間）／before／after／until\\n・because（〜だから）／if（もし〜なら）／though（〜だけれども）\\n・that（〜ということ）\\n・who／which／that（〜する（人・もの））\\n\\n例）When the bell rang, the students stopped talking and opened their books.\\nWhen ／ the bell rang, ／ the students stopped talking ／ and opened their books.\\n→ 「ベルが鳴った」＋「生徒たちは話すのをやめた」＋「（そして）本を開いた」の3つ。\\n\\n■ 前半に置いたらカンマ、後半に置いたらカンマなし\\nIf it rains tomorrow, we will stay home.\\nWe will stay home if it rains tomorrow.\\nどちらも同じ意味。前半に置くときだけカンマが必要になる。\\n\\n★ ポイント：カンマは「ここで意味が切れる」という合図である。長い文に出会ったら、まずカンマの位置に縦線を引く。\\n\\n⚠ 注意：when・if・before・after のかたまりの中では、未来のことでも will を使わず現在形で書く（If it rains tomorrow が正しく、If it will rain は誤り）。これは英作文でも読解でもよく問われる。\",\"figureId\":\"xf_eigo_s391\"},{\"heading\":\"that の2つの働きを見分ける\",\"body\":\"切れ目の目印の中でいちばんまぎらわしいのが that である。that には大きく3つの使い方がある。\\n\\n■ ①「あの・それ」（指示語）\\nThat is my bike.（あれは私の自転車だ）\\n→ that が主語や目的語そのものになっている。\\n\\n■ ②「〜ということ」（接続詞）\\nI know that he is a good player.（私は彼がよい選手だということを知っている）\\n→ that の直前が動詞（know・think・say・hope・believe など）。that の後ろは「主語＋動詞」がそろった完全な文。\\n※ この that は省略できる。I know he is a good player. も正しい。\\n\\n■ ③「〜する（人・もの）」（関係代名詞）\\nThis is the book that I bought yesterday.（これは私が昨日買った本だ）\\n→ that の直前が名詞（the book）。that の後ろは主語か目的語が欠けた不完全な文（bought の目的語がない）。\\n\\n■ 見分け方のまとめ\\nthat の直前が【動詞】→ ②接続詞（〜ということ）\\nthat の直前が【名詞】→ ③関係代名詞（〜する…）\\n\\n★ ポイント：どちらの that も「ここから新しい文が始まる」という点は同じ。読むときは、まず that に印をつけて区切るだけで十分である。\\n\\n⚠ 注意：I think that … の that は省略されることが非常に多い。I think he is right. のように that がなくても、think のあとに主語＋動詞が続いていれば「〜ということ」だと判断する。\",\"mangaId\":\"eigo_s391_xm\"}],\"trapExamples\":[{\"question\":\"I will call you when I ( arrive / will arrive ) at the station. 正しいほうを選びなさい。\",\"wrongAnswer\":\"will arrive\",\"trapExplanation\":\"「駅に着いたら」は未来のことなので、will を使いたくなる。前半に I will call you と will があることも、その気持ちを強めてしまう。\",\"correctAnswer\":\"arrive\",\"correctExplanation\":\"when／if／before／after／until などが作るかたまりの中では、未来の内容でも現在形で表すという決まりがある。だから when I arrive が正しい。前半の主文（I will call you）には will をきちんと入れる点にも注意する。\"},{\"question\":\"I heard that the man that lives next door is a famous singer. の下線 that はそれぞれ何か。\",\"wrongAnswer\":\"どちらも関係代名詞\",\"trapExplanation\":\"同じ形の that が2回出てくるので、同じ働きだと決めつけてしまう。that の働きは形ではなく、直前にある語の品詞で決まる。\",\"correctAnswer\":\"1つ目は接続詞（〜ということ）、2つ目は関係代名詞（〜する）\",\"correctExplanation\":\"1つ目の that は直前が heard（動詞）なので「〜ということ」の接続詞。2つ目の that は直前が the man（名詞）なので「〜する（人）」の関係代名詞である。全体の意味は「私は、となりに住んでいるその男の人が有名な歌手だということを聞いた」。that の直前が動詞か名詞かを見る、という一点で必ず区別できる。\"}]}",
"{\"id\":\"eigo_s392\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語と動詞を見つける④：後ろから修飾する形\",\"description\":\"前置詞句・-ing・過去分詞・to不定詞・関係代名詞が名詞を後ろから説明する\",\"intro\":\"名詞のうしろに、前置詞句・ing・過去分詞・to不定詞・関係代名詞のどれかがくっついて説明する——英語の後ろからの修飾は、この五つに集約されます。形はちがって見えても、はたらきは全部同じ。まとめて処理できるようにします。\",\"order\":892,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"1語の修飾語は名詞の前、2語以上のかたまりは名詞の後ろに置く。これが英語の大原則。\",\"後ろから修飾する形は5つ：前置詞句／-ing（〜している）／過去分詞（〜された）／to不定詞（〜するための）／関係代名詞。\",\"-ing は「する側」、過去分詞は「される側」。boy playing＝弾いている少年、song sung＝歌われた歌。\",\"something／anything／nothing を修飾する形容詞は、必ず後ろに置く（something cold to drink）。\",\"日本語にするときは、後ろのかたまりを前へ回して訳す。\"],\"sections\":[{\"heading\":\"名詞の前と後ろ\",\"body\":\"英語では、名詞をくわしく説明する語をどこに置くかが決まっている。\\n\\n■ 前に置くもの（1語）\\na book／the book（冠詞）\\na new book（形容詞）\\nmy new book（所有）\\n→ 短い1語は名詞の前。\\n\\n■ 後ろに置くもの（2語以上のかたまり）\\n① 前置詞句：the book on the desk（机の上の本）\\n② -ing：the boy playing the guitar（ギターを弾いている少年）\\n③ 過去分詞：the letter written in English（英語で書かれた手紙）\\n④ to不定詞：something to drink（飲むための何か＝飲み物）\\n⑤ 関係代名詞：the man who lives next door（となりに住んでいる男の人）\\n\\n日本語はすべて前から修飾する（「机の上の本」）ので、②〜⑤は訳すときに前へ回すことになる。この「回す」感覚が身につくと、長文の意味がすっと通るようになる。\\n\\n★ ポイント：名詞のすぐ後ろに前置詞・-ing・過去分詞・to・who/which/that のどれかが来ていたら、そこから修飾のかたまりが始まっていると考える。かたまりの終わりは、文全体の動詞が現れる直前まで。\\n\\n⚠ 注意：something・anything・nothing・everything を形容詞で修飾するときは、必ず後ろに置く。cold something ではなく something cold が正しい。さらに to不定詞も付ける場合は something cold to drink の順になる。\",\"figureId\":\"lf_eigoext11_392\"},{\"heading\":\"-ing と過去分詞の使い分け\",\"body\":\"後置修飾でいちばんまちがえやすいのが、-ing と過去分詞の使い分けである。\\n\\n■ -ing＝その名詞が「する側」\\nthe girl singing on the stage（ステージで歌っている少女）\\n→ 少女が歌う。少女は「する側」。\\n\\n■ 過去分詞＝その名詞が「される側」\\nthe song sung by the girl（その少女によって歌われた歌）\\n→ 歌は歌われる。歌は「される側」。\\n\\n■ 練習\\n・a boy called Ken（ケンと呼ばれている少年）※少年は呼ばれる側 → 過去分詞\\n・a man carrying a big bag（大きなかばんを運んでいる男の人）※男の人は運ぶ側 → -ing\\n・the pictures taken in Kyoto（京都で撮られた写真）※写真は撮られる側 → 過去分詞\\n・the students studying in the library（図書館で勉強している生徒たち）※生徒は勉強する側 → -ing\\n\\n■ to不定詞の後置修飾\\nI have a lot of homework to do today.（今日やるべき宿題がたくさんある）\\nHe is looking for a house to live in.（彼は住むための家をさがしている）\\n※ live in a house なので in が最後に残る点に注意。\\n\\n★ ポイント：迷ったら「その名詞は自分でするのか、されるのか」と声に出して確かめる。写真は自分で撮らないので taken、少年は自分で運ぶので carrying。\\n\\n⚠ 注意：a sleeping baby（眠っている赤ちゃん）のように、-ing が1語だけのときは名詞の前に置く。a baby sleeping in the bed のように2語以上になると後ろへ移る。位置は「語数」で決まる。\",\"mangaId\":\"eigo_s392_xm\"}],\"trapExamples\":[{\"question\":\"「英語で書かれた本」を英語にしなさい。\",\"wrongAnswer\":\"a writing book in English\",\"trapExplanation\":\"「書かれた」を writing としてしまい、さらに日本語の語順のまま名詞の前に置いてしまう。-ing は「〜している（する側）」なので、a writing book では「書いている本」という意味不明の表現になる。\",\"correctAnswer\":\"a book written in English\",\"correctExplanation\":\"本は「書かれる側」なので過去分詞 written を使う。しかも written in English は2語以上のかたまりなので、名詞 a book の後ろに置く。「される側なら過去分詞」「2語以上なら後ろ」という2つの原則を両方あてはめること。\"},{\"question\":\"I want ( cold something / something cold ) to drink. 正しいほうを選びなさい。\",\"wrongAnswer\":\"cold something\",\"trapExplanation\":\"「冷たい何か」という日本語の順や、a cold drink のように形容詞は名詞の前という原則にひきずられて、cold を前に置いてしまう。\",\"correctAnswer\":\"something cold\",\"correctExplanation\":\"-thing で終わる語（something／anything／nothing／everything）だけは例外で、形容詞を必ず後ろに置く。さらに to drink のような to不定詞も付ける場合は「something → 形容詞 → to不定詞」の順で something cold to drink となる。この語順は入試の並べかえ問題の定番である。\"}]}",
"{\"id\":\"eigo_s393\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"代名詞①：it と they が指すものをつかむ\",\"description\":\"英語が同じ名詞をくり返さない性質を利用して、指示内容を正確にたどる\",\"intro\":\"英語は同じ名詞をくり返すのをきらい、二度目からは代名詞に変えます。そのぶん読み手のほうが「これは何を指すのか」をたどらなければなりません。入試で下線が引かれるのもここです。指示内容をたどる手順を作ります。\",\"order\":893,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"英語は同じ名詞のくり返しをきらう。2回目からは代名詞に変える。\",\"it＝単数の物や動物、they＝複数の人・物、he／she＝単数の人。数と種類で候補をしぼる。\",\"代名詞は必ず「自分より前」に出た名詞を指す。後ろの語を指すことはまずない。\",\"答えを書くときは、代名詞の位置に候補の名詞を入れて読み、意味が通るか必ず確かめる。\",\"指示語の設問では、本文の語をそのまま抜き出す（勝手に言いかえない）。\"],\"sections\":[{\"heading\":\"代名詞は「前にもどる矢印」\",\"body\":\"英語は、同じ名詞を何度も出すことをきらう言語である。1回目は名詞、2回目からは代名詞に置きかえる。だから代名詞は必ず「前にもどる矢印」だと考えればよい。\\n\\n■ 代名詞の種類と、指せるもの\\n・it … 単数の物・動物・こと（前に出た単数名詞1つ）\\n・they／them … 複数の人・物\\n・he／him … 単数の男性\\n・she／her … 単数の女性\\n・one … 「同じ種類の別のもの」\\n・this／that … 直前の文全体や内容\\n\\n■ 探し方の手順\\n①その代名詞が単数か複数か、人か物かを決める。\\n②直前の文にもどり、条件に合う名詞を探す。\\n③見つかったら、代名詞の場所にその名詞を入れて読み直す。意味が通れば正解。\\n\\n例）Mika bought a new dictionary. She uses it every day.\\n　　She → Mika（単数の女性）\\n　　it → a new dictionary（単数の物）\\n入れかえると She uses a new dictionary every day. となり、意味が通る。\\n\\n★ ポイント：③の「入れかえて読み直す」を必ずやること。ここを飛ばすと、条件は合っているが意味が通らない名詞を選んでしまう。\\n\\n⚠ 注意：本文で問われたら、必ず本文にある語のまま書く。a new dictionary とあるのに「辞書」とだけ書いたり、the dictionary と勝手に変えたりすると減点されることがある。\",\"figureId\":\"xf_eigo_s393\"},{\"heading\":\"実際の英文でたどる\",\"body\":\"次の英文で、下線部の代名詞が指すものを確かめる。\\n\\nYuki has a small brown rabbit. She got it two years ago. Its name is Coco. Coco likes carrots very much, and she eats them every morning. Yuki cleans the cage every Sunday because it becomes dirty in a week. Yuki's brother, Taku, also likes Coco. He often puts her on his knees and talks to her. Their mother says that they must take care of Coco together. Yuki and Taku agree, and they never forget to give her fresh water.\\n\\n■ ひとつずつたどる\\n・She got it two years ago. の She＝Yuki、it＝a small brown rabbit\\n・Its name is Coco. の Its＝the rabbit（＝Coco）\\n・she eats them every morning. の she＝Coco、them＝carrots\\n・because it becomes dirty の it＝the cage（ケージ）※ Coco ではない\\n・He often puts her on his knees. の He＝Taku、her＝Coco\\n・they must take care of Coco の they＝Yuki and Taku\\n\\n★ ポイント：同じ it でも指すものが変わる。2文目の it はウサギ、5文目の it はケージである。「一度決めたら最後まで同じ」ではないので、出てくるたびに確かめる。\\n\\n⚠ 注意：she eats them の she を Yuki だと考えると「ユキがニンジンを毎朝食べる」になってしまう。直前が Coco likes carrots very much なので、and でつながれた後半の主語も Coco である。and でつながれた文は、前半と同じ主語のことを話し続けていることが多い。\",\"mangaId\":\"eigo_s393_xm\"}],\"trapExamples\":[{\"question\":\"上の英文の Yuki cleans the cage every Sunday because it becomes dirty in a week. の it は何を指すか。\",\"wrongAnswer\":\"Coco（ウサギ）\",\"trapExplanation\":\"この文章の中心はウサギの Coco なので、it といえばウサギだろうと決めつけてしまう。また前の文で it がウサギを指していたことも、思いこみを強める。\",\"correctAnswer\":\"the cage（ケージ・かご）\",\"correctExplanation\":\"入れかえて確かめる。「Coco becomes dirty in a week（ココは1週間でよごれる）」よりも「the cage becomes dirty in a week（ケージは1週間でよごれる）」のほうが、そうじをする理由として自然である。代名詞は直前の名詞を指すのが原則で、この文でも直前の名詞は the cage である。必ず入れかえて意味を確かめること。\"},{\"question\":\"上の英文の they never forget to give her fresh water. の they と her はそれぞれ何を指すか。\",\"wrongAnswer\":\"they＝Yuki and Taku and their mother／her＝their mother\",\"trapExplanation\":\"直前の文に Their mother says … とあるため、いちばん近い名詞である mother を her だと考えてしまう。また「みんなで」という気持ちから、母親まで they に入れてしまう。\",\"correctAnswer\":\"they＝Yuki and Taku／her＝Coco\",\"correctExplanation\":\"直前の文は Yuki and Taku agree で、その and のあとが they never forget … なので、they は Yuki and Taku である。her は「水をもらう側」なので、母親ではなくウサギの Coco。この文章では Coco を she／her で受けているので、女性を指す代名詞が2つの候補（mother と Coco）にあることになる。そういうときこそ、入れかえて意味が通るほうを選ぶ。\"}]}",
"{\"id\":\"eigo_s394\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"代名詞②：直前を探す原則と数の一致\",\"description\":\"代名詞の候補を「数」と「人か物か」でしぼり、いちばん近い名詞から確かめる\",\"intro\":\"下線の it が指すものをさがすとき、段落の最初まで戻っていませんか。答えはたいてい直前の一、二文の中にあります。しかも単数か複数か、人か物かで候補はさらにしぼれます。遠くを探す前に、確かめる順番を決めます。\",\"order\":894,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"代名詞の指示内容は、原則として「直前の1〜2文」の中にある。段落をまたいで遠くを指すことは少ない。\",\"単数の代名詞（it／he／she）は単数名詞を、複数の代名詞（they／them）は複数名詞を指す。\",\"候補が複数あるときは、数の一致 → 人か物か → 意味が通るか、の順にしぼる。\",\"主語の位置の代名詞（he／she／it／they）と目的語の位置の代名詞（him／her／it／them）は形がちがう。\",\"所有を表す代名詞（his／her／its／their）は「〜の」なので、直後の名詞とセットで考える。\"],\"sections\":[{\"heading\":\"数と種類で候補をしぼる\",\"body\":\"代名詞の設問で迷うのは、候補になる名詞が2つ以上あるときである。そういうときは順番にふるいにかける。\\n\\n■ ふるい①：数\\nTom bought two books and a pen. He read them on the train.\\nthem は複数なので、a pen（単数）は候補から外れる。答えは two books。\\n\\n■ ふるい②：人か物か\\nMy sister and her dog went to the park. She was very happy.\\nShe は人を指す代名詞なので、her dog（物・動物）ではなく My sister。\\n※ ペットを she／he で受けることもあるが、その場合は文章の中でずっとそう扱われている。\\n\\n■ ふるい③：意味が通るか\\nKen gave Mika a letter, and she read it at once.\\nshe＝Mika（Ken は男性なので he になるはず）、it＝a letter。\\n\\n■ 形の一覧\\n主語の位置：I／you／he／she／it／we／they\\n目的語の位置：me／you／him／her／it／us／them\\n「〜の」：my／your／his／her／its／our／their\\n「〜のもの」：mine／yours／his／hers／ours／theirs\\n\\n★ ポイント：主語の位置か目的語の位置かは、動詞の前か後ろかで決まる。動詞の後ろにあれば him／her／them の形になる。\\n\\n⚠ 注意：its（それの）と it's（it is の短縮形）はまったく別物。its にアポストロフィは付かない。Its name is Coco.（その名前はコロだ）／It's a rabbit.（それはウサギだ）。読解でも英作文でも問われる。\",\"figureId\":\"lf_eigoext11_394\",\"mangaId\":\"eigo_s394_xm\"},{\"heading\":\"距離のルール\",\"body\":\"代名詞は、原則として自分にいちばん近い、条件に合う名詞を指す。これを「直前の原則」という。\\n\\n例文の流れで確かめる。\\n① Ken wanted a new bike.\\n② His father took him to a shop last Sunday.\\n③ Ken found a red one and liked it very much.\\n④ However, he did not have enough money.\\n⑤ His father said, \\\"I will buy it for your birthday.\\\"\\n\\n・② His＝Ken、him＝Ken\\n・③ one＝bike（「同じ種類の別のもの」なので a red bike）、it＝the red bike\\n・④ he＝Ken（直前の③の主語で、話の中心人物でもある）\\n・⑤ it＝the red bike\\n\\n■ 候補が二人いる場面\\n同じ性別の人が二人出てくる文章では、近さだけでは決められないことがある。②には his father も出てくるが、④の he は、直前の③の主語であり話の中心人物でもある Ken を指す。文章全体でだれの話をしているかを頭に入れておくと迷わない。\\n\\n★ ポイント：候補が2人いる（Ken と his father の両方が男性）ときは、入れかえて意味を確かめるしかない。④で「父は十分なお金を持っていなかった」とすると、⑤で父が買ってあげることと矛盾する。だから he＝Ken。\\n\\n⚠ 注意：代名詞が後ろの名詞を指す形（When he came home, Ken was very tired.）もまれにあるが、中学入試ではほとんど出ない。まず前を探すこと。\"}],\"trapExamples\":[{\"question\":\"My mother made a cake and some cookies. I ate them after dinner. の them は何を指すか。\",\"wrongAnswer\":\"a cake\",\"trapExplanation\":\"いちばん近い名詞を探すという原則だけを機械的にあてはめて、直前に近い a cake を選んでしまう。しかし a cake は単数なので、複数の them では受けられない。\",\"correctAnswer\":\"some cookies（または a cake and some cookies）\",\"correctExplanation\":\"them は複数を指す代名詞なので、単数の a cake は候補から外れる。残る候補は some cookies、あるいは a cake and some cookies（ケーキとクッキーの両方）である。「近さ」より先に「数の一致」でふるいにかけること。文脈上「作ったものを全部食べた」と読むなら a cake and some cookies が答えになる。\"},{\"question\":\"Its a very old temple. この英文のまちがいを直しなさい。\",\"wrongAnswer\":\"まちがいはない\",\"trapExplanation\":\"Its も It’s も音は同じで見た目もよく似ているため、まちがいに気づかない。日本語には同じ区別がないので、意識しないと見のがしてしまう。\",\"correctAnswer\":\"It’s a very old temple.（＝It is a very old temple.）\",\"correctExplanation\":\"It’s は It is の短縮形で「それは〜です」、its はアポストロフィなしで「それの」という意味の所有を表す語である。この文は「それはとても古い寺です」なので It’s が正しい。its を使うなら Its roof is very old.（その屋根はとても古い）のように、直後に必ず名詞が来る。\"}]}",
"{\"id\":\"eigo_s395\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"代名詞③：this と that が指す「内容」\",\"description\":\"名詞1語ではなく、前の文や段落全体の内容を指す指示語を読み取る\",\"intro\":\"指示語の答えが、名詞一語では書けないことがあります。this や that は、前の文まるごとの内容を指すことがあるからです。そのときの答えは「〜すること」の形でまとめます。内容を指す指示語の見分け方を学びます。\",\"order\":895,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"this／that／it は、名詞1語だけでなく「前の文の内容ぜんたい」を指すことがある。\",\"This is why 〜（こういうわけで〜）は、前が理由・後ろが結果。This is because 〜 は、前が結果・後ろが理由。\",\"内容を指す指示語の答えは、「〜すること」「〜ということ」の形の日本語でまとめる。\",\"that は前の文の内容、this はこれから述べる内容も指せる（That is a good idea. ／ This is my plan: …）。\",\"設問「下線部が指す内容を日本語で説明しなさい」は、必ず前の1〜2文を要約して答える。\"],\"sections\":[{\"heading\":\"文の内容をまるごと受ける指示語\",\"body\":\"代名詞は名詞1語を指すのが基本だが、this／that／it は「前の文の内容そのもの」を指すことがある。これが読解の設問で最もよく問われる。\\n\\n例）Ken practiced the piano for two hours every day. This made him a very good player.\\nThis ＝「毎日2時間ピアノを練習したこと」\\n名詞1語では答えられない。前の文全体を「〜こと」の形にまとめる必要がある。\\n\\n例）Many students said that the test was too difficult. The teacher heard this and made a new test.\\nthis ＝「テストが難しすぎたと多くの生徒が言ったこと」\\n\\n■ 答え方のきまり\\n・日本語で書くときは「〜こと」「〜ということ」で終える。\\n・英語で抜き出すときは、前の文をそのまま書くのではなく、設問の指示（何語以内など）に従う。\\n\\n■ よく出る型\\n・This is why 〜　こういうわけで〜だ　→ 前が【理由】、後ろが【結果】\\n　It rained a lot last night. This is why the game was canceled.\\n・This is because 〜　これは〜だからだ　→ 前が【結果】、後ろが【理由】\\n　The game was canceled. This is because it rained a lot last night.\\n\\n★ ポイント：why と because で、理由と結果が前後どちらにあるかが入れかわる。この2つはセットで覚えること。\\n\\n⚠ 注意：「下線部 this の指す内容を答えよ」で、直前の名詞1語だけを書くと不正解になることが多い。まず「これは1語で答えられるものか、内容ぜんたいか」を判断する。\",\"figureId\":\"xf_eigo_s395\"},{\"heading\":\"内容を指す指示語の練習\",\"body\":\"次の英文で、下線を引いた指示語の内容を確かめる。\\n\\nSome people throw away food that they do not eat. In Japan, about six million tons of food are thrown away every year. This is a serious problem. First, making food uses a lot of water and energy. Second, burning food waste produces a lot of carbon dioxide. That is why some supermarkets now sell food that is close to its \\\"best before\\\" date at a lower price. Shoppers can buy it cheaply, and the shops do not have to throw it away. This is good for both sides.\\n\\n■ ひとつずつ確かめる\\n・This is a serious problem. の This\\n　＝「日本で毎年およそ600万トンの食べ物が捨てられていること」\\n　※ food（食べ物）という名詞1語ではない。「捨てられていること」という内容である。\\n・That is why some supermarkets … の That\\n　＝「食べ物を作るのに大量の水とエネルギーを使い、食品ごみを燃やすと大量の二酸化炭素が出ること」\\n　※ That is why なので、その前が理由、後ろが結果。\\n・This is good for both sides. の This\\n　＝「賞味期限が近い食品を安く売り、客は安く買え、店は捨てずにすむこと」\\n\\n★ ポイント：First, … Second, … と並んだあとの That is why は、first と second の両方をまとめて受ける。指示語の範囲は1文とはかぎらない。\\n\\n⚠ 注意：both sides（両方の側）とは「客と店」のこと。数を表す語（both／each／all）が出たら、何と何を指すのかを必ず確かめる。\",\"mangaId\":\"eigo_s395_xm\"}],\"trapExamples\":[{\"question\":\"上の英文の This is a serious problem. の This が指す内容を日本語で答えなさい。\",\"wrongAnswer\":\"食べ物（food）\",\"trapExplanation\":\"指示語といえば名詞を指すものだと思いこみ、直前の文にある名詞 food をそのまま答えてしまう。しかし「食べ物は深刻な問題だ」では意味が通らない。\",\"correctAnswer\":\"日本で毎年およそ600万トンの食べ物が捨てられていること。\",\"correctExplanation\":\"This を入れかえて「食べ物は深刻な問題だ」と読むと不自然だが、「毎年600万トンの食べ物が捨てられていることは深刻な問題だ」なら自然につながる。指示語の答えは、入れかえて読んで自然かどうかで決める。日本語で書くときは「〜こと」で結ぶ。\"},{\"question\":\"The bus did not come. This is because there was a big accident. 下線部の関係として正しいのはどちらか。（ア）前が理由・後ろが結果（イ）前が結果・後ろが理由\",\"wrongAnswer\":\"（ア）前が理由・後ろが結果\",\"trapExplanation\":\"This is why 〜 と This is because 〜 を混同して、「This is 〜」ならすべて「こういうわけで」だと覚えてしまっている。\",\"correctAnswer\":\"（イ）前が結果・後ろが理由\",\"correctExplanation\":\"This is because 〜 は「これは〜だからだ」で、後ろに理由が来る。ここでは「バスが来なかった（結果）。それは大きな事故があったからだ（理由）」となる。逆に This is why 〜 は「こういうわけで」で、前が理由・後ろが結果。because＝理由が後ろ、why＝結果が後ろ、と覚えるとよい。\"}]}",
"{\"id\":\"eigo_s396\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"代名詞④：one と it のちがい・言いかえの連鎖\",\"description\":\"同じものを指す it と、同じ種類の別のものを指す one を区別する\",\"intro\":\"I lost my pen, so I bought a new one. の one を it に変えると、なくしたペンをもう一度買ったことになってしまいます。it は同じもの、one は同じ種類の別のもの。この一線を知らないと、細部を問う設問で落とします。\",\"order\":896,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"it＝まったく同じもの（その物そのもの）。one＝同じ種類の別のもの。\",\"ones は複数形。the one／the ones は「その中の特定のもの」を指す。\",\"英語は同じ語のくり返しをさけるため、the boy → he → him → the student のように言いかえていく。\",\"言いかえの連鎖をたどれば、その文章の中心人物・中心の話題（キーワード）が見える。\",\"the other／another／some … others … も指示のはたらきをするので、何を指すか確かめる。\"],\"sections\":[{\"heading\":\"it と one の決定的なちがい\",\"body\":\"it と one はどちらも「それ」と訳せるが、指しているものがまったくちがう。\\n\\n■ it＝そのもの自身\\nI lost my umbrella. I looked for it everywhere.\\n（かさをなくした。私はそれをあちこちさがした）\\n→ さがしているのは、なくしたそのかさ。\\n\\n■ one＝同じ種類の別のもの\\nI lost my umbrella, so I bought a new one.\\n（かさをなくしたので、新しいのを買った）\\n→ 買ったのは別のかさ。one＝umbrella という「種類」だけを受けている。\\n\\n■ 見分け方\\n「そのもの」で意味が通るなら it、「別の同じ種類のもの」なら one。\\n・This cap is too big. Do you have a smaller one?（もっと小さいの＝別の帽子）\\n・This cap is too big. I don't like it.（この帽子そのものが好きでない）\\n\\n■ 複数の場合\\nThese shoes are too small. I want bigger ones.（ones＝shoes）\\n\\n■ the one／the ones\\nWhich is your bag? — The one on the chair.（いすの上のもの）\\n→ the が付くと「その中の特定の1つ」を指す。\\n\\n★ ポイント：one の直前にはよく形容詞（new／small／red）が付く。形容詞＋one を見たら「別のもの」と判断してよい。\\n\\n⚠ 注意：数えられない名詞は one で受けられない。I want some water. — I'll get some. のように some を使う（× a new one）。\",\"figureId\":\"xf_eigo_s396\",\"mangaId\":\"eigo_s396_xm\"},{\"heading\":\"言いかえの連鎖を追う\",\"body\":\"英語の文章は、同じものをいろいろな語に言いかえながら進む。この連鎖を追えると、文章の中心がつかめる。\\n\\n例）\\n① A young man named Sadao Takahashi lived in a small village.\\n② He was a doctor, and he worked at the only hospital there.\\n③ The doctor visited sick people even in the middle of the night.\\n④ Everyone in the village loved him.\\n⑤ They called him \\\"the doctor who never sleeps.\\\"\\n\\n・① A young man named Sadao Takahashi（初めて出す → 名前をきちんと出す）\\n・② He（代名詞に変える）\\n・③ The doctor（別の名詞に言いかえる。the が付くのは「もう話に出た人」だから）\\n・④ him（目的語の位置なので him）\\n・⑤ They＝Everyone in the village、him＝the doctor\\n\\n■ the の合図\\n初めて出てくる名詞には a／an、2回目以降には the が付く。だから the が付いた名詞は「前に出た何かの言いかえ」である可能性が高い。\\n\\n■ 説明文でも同じ\\n① Plastic bags are used all over the world.\\n② These bags are cheap and light.\\n③ However, this useful material does not break down in nature.\\n→ Plastic bags → These bags → this useful material と言いかえられている。\\n\\n★ ポイント：this／these＋名詞（These bags／this material）は、指示語と名詞がセットになった形で、前に出たものを指し直すはたらきをする。指示語の設問でねらわれやすい。\\n\\n⚠ 注意：some … others … は「一部は〜、別の一部は〜」の意味。Some students like math, and others like English. の others は「（生徒のうちの）ほかの人たち」で、全員ではない。\"}],\"trapExamples\":[{\"question\":\"I have a red pen and a blue pen. May I use ( it / one ) ? という文で、「（どちらでもいいので）1本使ってもいいですか」という意味にするにはどちらか。\",\"wrongAnswer\":\"it\",\"trapExplanation\":\"日本語では「それを使ってもいい？」と言うので、it を選んでしまう。しかし it は「そのもの」を指すので、2本のうちどちらか特定できていない場面では使えない。\",\"correctAnswer\":\"one\",\"correctExplanation\":\"one は「同じ種類のもののうちの1つ」を指す。ここでは2本のペンのうちどちらでもよいので one が正しい。もし「その赤いペンを使ってもいい？」と特定するなら May I use it? となる。it＝そのもの、one＝同じ種類のどれか、という使い分けを覚える。\"},{\"question\":\"Plastic bags are used all over the world. However, this useful material does not break down in nature. の this useful material は何を指すか。\",\"wrongAnswer\":\"the world（世界）\",\"trapExplanation\":\"直前にある名詞 the world を機械的に選んでしまう。しかし「世界は自然の中で分解しない」では意味が通らない。material（材料・素材）という語の意味を確かめずに、位置だけで判断したための誤り。\",\"correctAnswer\":\"plastic（プラスチック。プラスチック製のふくろの素材）\",\"correctExplanation\":\"material は「材料・素材」の意味なので、指すのは「素材にあたるもの」でなければならない。前の文の Plastic bags のうち、素材にあたるのは plastic である。this＋名詞の形では、その名詞（ここでは material）が「どんな種類のものを指しているか」を教えてくれる。this problem なら問題、this idea なら考え、this animal なら動物を前から探せばよい。\"}]}",
"{\"id\":\"eigo_s397\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つなぎ語①：but・however で主張を見つける\",\"description\":\"逆接のつなぎ語の直後に筆者の言いたいことがある、という原則を使う\",\"intro\":\"筆者がいちばん言いたいことは、どこに書かれているでしょうか。実は but や however の直後にあることがほとんどです。前の内容をわざわざひっくり返してまで書くのですから、そこが主張なのです。設問もそこから作られます。\",\"order\":897,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"but／however／yet／though は逆接。直前の内容をひっくり返す合図。\",\"逆接のつなぎ語の【直後】に筆者の主張が来る。設問はほぼそこから作られる。\",\"however は副詞なので、ふつう文の先頭に置きカンマを付ける（However, …）。but は文と文の間に置く。\",\"though／although は「〜だけれども」で、そのかたまりのほうが「ゆずる部分」。主張は主文のほう。\",\"「多くの人は〜と思う（Many people think …）」で始まったら、次に However が来ると予想する。\"],\"sections\":[{\"heading\":\"逆接は主張の合図\",\"body\":\"説明文の書き方には型がある。いちばん多いのが次の型である。\\n\\n【一般に言われていること】→ However（しかし）→【筆者が本当に言いたいこと】\\n\\n例）Many people think that reading on paper is old-fashioned. However, several studies show that we remember more when we read on paper.\\n（多くの人は紙で読むのは時代おくれだと思っている。しかし、紙で読むほうがよく覚えられるという研究がいくつかある）\\n筆者が言いたいのは後半である。前半はあくまで「よくある考え」を紹介しただけ。\\n\\n■ 逆接の語と使い方\\n・but … 文の中で2つをつなぐ。It was cold, but I went out.\\n・however … 文の先頭。カンマを付ける。It was cold. However, I went out.\\n・though／although … 「〜だけれども」。Though it was cold, I went out.\\n・yet … 「それでも」。文語的。\\n・on the other hand … 「一方で」。対比を示す。\\n\\n■ 大切な原則\\n逆接のあとが「言いたいこと」。逆接の前は「ゆずっている部分」。\\nだから設問で「筆者の考えとして正しいものを選べ」と問われたら、However の後ろを見る。\\n\\n★ ポイント：長文を読むとき、However／But／Yet に○をつけ、その直後の文に線を引くだけで、主張の位置が地図のように見えてくる。\\n\\n⚠ 注意：but と however は意味は同じでも、使い方がちがう。× It was cold, however I went out.（カンマでつなげない）。○ It was cold; however, I went out. または It was cold. However, I went out.\",\"figureId\":\"lf_eigoext11_397\"},{\"heading\":\"though と but を同時に使わない\",\"body\":\"日本語では「寒かったけれども、でも私は出かけた」のように、「けれども」と「でも」を重ねて言うことがある。英語ではこれをしない。\\n\\n× Though it was cold, but I went out.\\n○ Though it was cold, I went out.\\n○ It was cold, but I went out.\\n\\nこれは日本人が非常によくまちがえる形なので、入試でもねらわれる。\\n\\n■ though のかたまりはどちらが主張か\\nThough he was very tired, he finished his homework.\\n（とても疲れていたけれども、彼は宿題を終えた）\\n→ 言いたいのは「宿題を終えた」ほう。though のかたまりは、それをきわだたせるための背景である。\\n\\n順番を入れかえても主張は変わらない。\\nHe finished his homework though he was very tired.\\n\\n■ 実際の英文で確かめる\\nStudying with a smartphone looks easy. You can look up any word in a second. However, many teachers say that students who use a paper dictionary remember words better. When you turn the pages, you also see other words near the word you are looking for. In this way, you learn more than you planned. Of course, a smartphone is useful when you are in a hurry. Still, if you want to remember new words for a long time, a paper dictionary may be a better choice.\\n\\n・However, many teachers say … ← ここが主張の中心\\n・Of course, a smartphone is useful … ← ゆずっている部分\\n・Still, … a paper dictionary may be a better choice. ← 最終的な主張\\n\\n★ ポイント：Of course（もちろん）／It is true that（たしかに〜だ）のあとには、必ず But や Still が続く。「いったん認めてから、しかし」と展開するのが説明文の定番である。\",\"mangaId\":\"eigo_s397_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、筆者の考えとして最も適切なものを選びなさい。（ア）スマートフォンで調べるほうがよい（イ）紙の辞書のほうが語を長く覚えていられる\",\"wrongAnswer\":\"（ア）スマートフォンで調べるほうがよい\",\"trapExplanation\":\"本文の冒頭に Studying with a smartphone looks easy. とあり、さらに Of course, a smartphone is useful … と2度もスマートフォンの良さが書かれているため、こちらが主張だと思ってしまう。\",\"correctAnswer\":\"（イ）紙の辞書のほうが語を長く覚えていられる\",\"correctExplanation\":\"looks easy（簡単そうに見える）は「見かけ」を述べる表現で、そのあとに However が来ている。さらに Of course のあとには Still（それでも）が続き、最後に a paper dictionary may be a better choice と結ばれている。「Of course …, Still …」の型では、Still の後ろが結論である。逆接の直後に線を引く習慣をつけること。\"},{\"question\":\"Though it was raining, ( but we played soccer / we played soccer ). 正しいほうを選びなさい。\",\"wrongAnswer\":\"but we played soccer\",\"trapExplanation\":\"日本語の「雨が降っていたけれども、でもサッカーをした」をそのまま英語に置きかえて、though と but を両方使ってしまう。日本語では自然でも、英語では接続詞の重複になり誤りである。\",\"correctAnswer\":\"we played soccer\",\"correctExplanation\":\"though（〜だけれども）はそれ自体が2つの文をつなぐ接続詞なので、もう1つの接続詞 but は不要である。Though it was raining, we played soccer. か、It was raining, but we played soccer. のどちらか一方にする。同じく Because …, so … の重ね使いも誤りで、Because it rained, we stayed home. か It rained, so we stayed home. とする。\"}]}",
"{\"id\":\"eigo_s398\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つなぎ語②：for example が示す「具体例」\",\"description\":\"具体例のかたまりを見抜き、その前にある「言いたいこと」に戻る\",\"intro\":\"for example のあとに続く長い部分を、必死に読み込んでいませんか。具体例は主張ではありません。読むべきなのは、その例が支えている前の一文のほうです。例のかたまりを見抜いて、素早く戻る読み方を身につけます。\",\"order\":898,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"for example／for instance／such as／like は具体例の合図。\",\"具体例は主張ではない。具体例の【前】に、その例が支えている主張がある。\",\"such as は名詞のあとに直接つなぐ（fruits such as apples）。for example は文の先頭でカンマを付ける。\",\"具体例が長く続いても、要旨をまとめるときには例そのものを書かない。\",\"設問に固有名詞（国名・人名・数字）が出たら、それは具体例の部分から作られている。\"],\"sections\":[{\"heading\":\"具体例は主張の下働き\",\"body\":\"説明文で、筆者は主張を1つ述べたあと、それを納得させるために例を並べる。読み手はこの「主張」と「例」を区別しなければならない。\\n\\n■ 具体例の合図\\n・for example, ／ for instance, （たとえば）※文の先頭、カンマ付き\\n・such as 〜（〜のような）※名詞のすぐ後ろ\\n・like 〜（〜のような）※ such as よりくだけた言い方\\n・One example is 〜（一例は〜だ）\\n・In Japan, 〜 ／ In 2020, 〜（国名や年号で例を出すこともある）\\n\\n例）Some animals can use tools. For example, some birds use small sticks to get insects from trees.\\n→ 主張は前半「道具を使える動物がいる」。後半は例にすぎない。\\n\\n■ such as と for example の使い分け\\n○ I like fruits such as apples and oranges.（名詞に直接つなぐ）\\n○ I like fruits. For example, I often eat apples.（文の先頭）\\n× I like fruits for example apples and oranges.（for example を名詞の後ろにそのままつなぐ形はしない。コンマで区切った挿入の形は文法上まちがいではないが、「〜のような」と言うときは such as が安全）\\n\\n★ ポイント：段落の要旨を答える問題では、具体例を書いてはいけない。「たとえば〜」を消して残った文が答えになる。\\n\\n⚠ 注意：例が3つ4つと続くと、読んでいるうちに主張を忘れる。For example が出たら、いったん前の文に戻って主張に線を引いてから読み進めるとよい。\",\"mangaId\":\"eigo_s398_xm\"},{\"heading\":\"具体例をカッコに入れて読む\",\"body\":\"次の英文を、具体例の部分をカッコに入れながら読む。\\n\\nSmall changes in our daily life can save a lot of energy. For example, if you turn off the light when you leave a room, you can save about 100 yen a month. Also, using a fan instead of an air conditioner on a cool summer evening uses much less electricity. Even the way you boil water is important. Boiling only the water you need, such as one cup instead of a full pot, saves both time and energy. These small actions may look too small to matter. However, if everyone in a city does them, the total amount becomes very large.\\n\\n■ 骨組みだけ取り出す\\n主張①：Small changes in our daily life can save a lot of energy.\\n（例：電気を消す／扇風機を使う／必要な分だけ湯をわかす）\\n主張②：These small actions may look too small to matter. However, if everyone in a city does them, the total amount becomes very large.\\n\\n■ 要旨\\n「日常のささいな行動でも省エネになる。1つ1つは小さく見えるが、みんなが行えば全体としては大きくなる。」\\n\\n★ ポイント：Also（また）は「例をもう1つ追加する」合図。Even（〜さえ）は「意外なものまで例に入れる」合図。どちらも例の続きなので、主張ではない。\\n\\n⚠ 注意：数字（about 100 yen a month）は例の中にあるが、設問ではよく問われる。「例は要旨には書かないが、細かい内容を問う設問では答えになる」という二面性を意識する。\",\"figureId\":\"xf_eigo_s398\"}],\"trapExamples\":[{\"question\":\"上の英文の要旨として最も適切なものを選びなさい。（ア）部屋を出るときに電気を消すと月に約100円節約できる（イ）日常のささいな行動でも、みんなで行えば大きな省エネになる\",\"wrongAnswer\":\"（ア）部屋を出るときに電気を消すと月に約100円節約できる\",\"trapExplanation\":\"数字が入っていて具体的なので「大事なこと」に見えてしまう。しかしこれは For example に続く1つの例にすぎず、文章全体をまとめた内容ではない。\",\"correctAnswer\":\"（イ）日常のささいな行動でも、みんなで行えば大きな省エネになる\",\"correctExplanation\":\"要旨は「例をのぞいて残るもの」である。第1文の主張と、最後の However の後ろの結論を合わせると（イ）になる。（ア）は For example の中の1例で、要旨としては範囲がせますぎる。要旨問題では、For example・such as・Also の後ろを消してから選択肢と見比べるとよい。\"},{\"question\":\"「私はりんごやみかんのような果物が好きです」を英語にしなさい。\",\"wrongAnswer\":\"I like fruits for example apples and oranges.\",\"trapExplanation\":\"「〜のような」を「たとえば」と読みかえて for example を使ってしまう。for example は文の先頭に置いて文全体を導く語なので、名詞の後ろに直接つなぐことはできない。\",\"correctAnswer\":\"I like fruits such as apples and oranges.\",\"correctExplanation\":\"such as は名詞のすぐ後ろに置いて「〜のような」と例を並べる。for example を使うなら、I like fruits. For example, I often eat apples and oranges. のように文を分ける。like を使って I like fruits like apples and oranges. とすることもできるが、like が2回出て読みにくいので such as のほうがよい。\"}]}",
"{\"id\":\"eigo_s399\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つなぎ語③：because・so で原因と結果を結ぶ\",\"description\":\"理由を問う設問に確実に答えるため、原因と結果の向きを正しくつかむ\",\"intro\":\"「なぜですか」と問われて、見つけた文をそのまま抜き出したら不正解——よくある失敗です。because のうしろが原因、so のうしろが結果と、向きが正反対だからです。取りちがえない読み方をここで確かめます。\",\"order\":899,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"because の後ろが【原因】、so の後ろが【結果】。向きが正反対なので混同しない。\",\"Why 〜? には Because 〜. または To 〜.（〜するため）で答える。\",\"because と so を1つの文で同時に使わない（Because …, so … は誤り）。\",\"That is why 〜（だから〜）／That is because 〜（それは〜だからだ）の向きも区別する。\",\"理由は because のない文にも書かれている。前後の文の内容から因果関係を読み取る力が必要。\"],\"sections\":[{\"heading\":\"原因と結果の向き\",\"body\":\"理由を問う設問（Why …?／なぜか）は、長文問題で必ず出る。答えを外さないために、つなぎ語の向きを正確に覚える。\\n\\n■ because … 後ろが原因\\nI stayed home because it rained.\\n　【結果】I stayed home ／【原因】it rained\\n\\n■ so … 後ろが結果\\nIt rained, so I stayed home.\\n　【原因】It rained ／【結果】I stayed home\\n\\n■ 図で覚える\\n　（原因）→ so →（結果）\\n　（結果）← because ←（原因）\\n矢印の向きが逆になる。\\n\\n■ 同じ内容の言いかえ\\n・Because it rained, I stayed home.（because を前に出すとカンマが必要）\\n・It rained, so I stayed home.\\n・It rained. That is why I stayed home.\\n・I stayed home. That is because it rained.\\n4つとも同じ内容である。\\n\\n■ 理由を表すそのほかの語\\n・since 〜／as 〜（〜なので）\\n・because of ＋名詞（〜のせいで）※ because of は後ろに名詞、because は後ろに文\\n　because of the rain ／ because it rained\\n\\n★ ポイント：Why did he stay home? と聞かれたら、Because it rained. と答える。「To …」で答えるのは目的を聞かれたとき（Why did you go there? — To meet my friend.）。\\n\\n⚠ 注意：Because …, so … は誤り。日本語の「〜なので、だから〜」につられやすいので、どちらか一方だけを使うこと。\",\"figureId\":\"xf_eigo_s399\",\"mangaId\":\"eigo_s399_xm\"},{\"heading\":\"つなぎ語のない因果関係を読む\",\"body\":\"入試の英文では、because や so がなくても因果関係が示されていることが多い。理由を問う設問では、そのつながりを自分で見つける必要がある。\\n\\n例）\\n① Ken did not go to school yesterday.\\n② He had a high fever and stayed in bed all day.\\n③ His mother took him to the hospital in the afternoon.\\n\\nWhy didn't Ken go to school yesterday? という設問の答えは②の He had a high fever（高熱があったから）である。because はどこにも書かれていないが、②が①の理由になっている。\\n\\n■ 因果関係を示すそのほかの表現\\n・Thanks to 〜（〜のおかげで）※よい結果\\n・Because of 〜／Due to 〜（〜のせいで）\\n・As a result,（その結果）\\n・therefore（それゆえ）\\n・This led to 〜（これが〜につながった）\\n・make ＋人＋形容詞（人を〜な気持ちにさせる）\\n　The news made her happy.（その知らせが彼女をうれしくさせた＝知らせを聞いてうれしかった）\\n\\n★ ポイント：Why の設問で答えを本文から抜き出すときは、because があればその後ろを、なければ「その出来事の直前の文」をまず疑う。\\n\\n⚠ 注意：日本語で答えるときは「〜から。」「〜ため。」で結ぶ。英語で答えるときは Because ＋主語＋動詞 の形にし、主語を代名詞に直す（Because he had a high fever.）。\"}],\"trapExamples\":[{\"question\":\"Why did she open the window? に対する答えとして正しいのはどちらか。\",\"wrongAnswer\":\"So the room was very hot.\",\"trapExplanation\":\"「だから部屋が暑かった」と so を理由の語だと思いこんでいる。so の後ろは結果なので、この答えでは「窓を開けた、だから部屋が暑かった」という逆の因果になってしまう。\",\"correctAnswer\":\"Because the room was very hot.\",\"correctExplanation\":\"Why 〜? に対する答えは Because ＋原因 で表す。「部屋がとても暑かったから窓を開けた」という因果の向きが正しい。so を使って答えるなら The room was very hot, so she opened the window. と、原因を先に置いた1つの文にする。because は後ろが原因、so は後ろが結果、と向きを固定して覚える。\"},{\"question\":\"「雪がたくさん降ったので、電車が止まりました」を英語にしなさい。\",\"wrongAnswer\":\"Because it snowed a lot, so the trains stopped.\",\"trapExplanation\":\"日本語の「〜ので、だから〜」の形をそのまま英語に移して、because と so を両方入れてしまう。英語では接続詞を重ねて使わない。\",\"correctAnswer\":\"Because it snowed a lot, the trains stopped.（または It snowed a lot, so the trains stopped.）\",\"correctExplanation\":\"because か so のどちらか一方だけを使う。because を前に置く場合はカンマで区切り、後ろに主文を続ける。so を使う場合は「原因，so 結果」の順にする。なお because of を使うなら後ろは名詞なので、The trains stopped because of the heavy snow. となる（× because of it snowed）。\"}]}",
"{\"id\":\"eigo_s400\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"つなぎ語④：also・first・finally で順序を追う\",\"description\":\"追加と順序を示す語を手がかりに、いくつの内容が並んでいるかを数える\",\"intro\":\"「筆者があげている理由をすべて答えなさい」という設問では、数え落としが命取りになります。手がかりは first・second・finally・also といった語です。これらに印をつけていけば、いくつ並んでいるか一目で分かります。\",\"order\":900,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"also／too／in addition／besides は「追加」。前と同じ方向の内容がもう1つ足される。\",\"first／second／third／finally は「順序」。いくつ並ぶか先に数えられる。\",\"also は動詞の前（またはbe動詞の後ろ）、too は文の最後に置く。\",\"finally／in conclusion／in short のあとは結論なので、要旨問題の答えになりやすい。\",\"「理由は3つある（There are three reasons.）」と書かれたら、3つそろうまで読む。\"],\"sections\":[{\"heading\":\"追加と順序の語\",\"body\":\"説明文では、同じ方向の内容がいくつも並ぶ。その並びを見失わないための語が「追加」と「順序」のつなぎ語である。\\n\\n■ 追加（同じ方向にもう1つ）\\n・also（〜もまた）… 動詞の前、be動詞の後ろ\\n　He also plays the guitar. ／ He is also a good singer.\\n・too（〜もまた）… 文の最後、カンマを付けることが多い\\n　He plays the guitar, too.\\n・in addition,（さらに）／besides,（そのうえ）… 文の先頭\\n・not only A but also B（AだけでなくBも）\\n\\n■ 順序（数えられる並び）\\n・First, … Second, … Third, … Finally, …\\n・At first,（最初は）※あとで変化があることを示す\\n・Then,（それから）／After that,（そのあと）\\n・Finally,（最後に）／In conclusion,（結論として）／In short,（要するに）\\n\\n例）There are three reasons why I like this book. First, the story is exciting. Second, the pictures are beautiful. Finally, I can learn about other countries.\\n→ 「3つある」と予告してから、First／Second／Finally で3つ並べている。\\n\\n★ ポイント：There are three reasons. のように数を予告する文が出たら、その数だけ内容を探す。設問で「3つ書きなさい」と問われることが多い。\\n\\n⚠ 注意：at first と first はちがう。first は「まず第一に」（列挙）、at first は「最初のうちは」（あとで変わる）。At first, I did not like him. But now he is my best friend. のように使う。\"},{\"heading\":\"実際の英文で並びを数える\",\"body\":\"次の英文には、いくつの内容が並んでいるか。\\n\\nVolunteer work is popular among students in our town. There are three main activities. First, some students clean the river on the first Sunday of every month. They collect cans and plastic bottles. Second, other students visit an old people's home and sing songs there. The old people always look forward to it. Finally, a few students teach Japanese to foreign children on Saturday afternoons. In addition, our school gives each student a small card. When you join an activity, you get a stamp on the card. In short, our town tries to make volunteer work fun and easy to start.\\n\\n■ 並びを整理する\\n予告：There are three main activities.（3つ）\\n①First → 川そうじ（毎月第1日曜日）\\n②Second → 老人ホームを訪ねて歌を歌う\\n③Finally → 土曜の午後に外国の子どもに日本語を教える\\n追加：In addition → カードにスタンプをもらえる仕組み\\n結論：In short → 町はボランティアを楽しく始めやすいものにしようとしている\\n\\n■ 設問になりやすい所\\n・「3つの活動を答えなさい」→ ①②③\\n・「本文の要旨を選べ」→ In short の文\\n・「川そうじはいつ行われるか」→ the first Sunday of every month\\n\\n★ ポイント：In addition は4つ目の活動ではない。「活動は3つ」と予告されているので、In addition の内容は活動ではなく別の情報（しくみ）である。予告の数を覚えておくと、こういう引っかけを避けられる。\\n\\n⚠ 注意：In short（要するに）／In conclusion（結論として）のあとは、それまでの内容をまとめた文である。要旨問題の答えがそのまま書かれていることが多いので、見つけたら必ず線を引く。\",\"figureId\":\"xf_eigo_s400\",\"mangaId\":\"eigo_s400_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、本文で述べられているボランティア活動はいくつか。\",\"wrongAnswer\":\"4つ\",\"trapExplanation\":\"First／Second／Finally に加えて In addition があるので、これも1つの活動だと数えてしまう。しかし In addition の後ろに書かれているのはスタンプカードのしくみであり、活動そのものではない。\",\"correctAnswer\":\"3つ\",\"correctExplanation\":\"本文の2文目に There are three main activities. と数が予告されている。そして First／Second／Finally で3つが並べられている。In addition のあとは、活動を続けやすくするための工夫の説明である。数を予告する文（There are three 〜.）は必ず○で囲み、その数どおりに数えること。\"},{\"question\":\"「彼はサッカーもします」を also を使って英語にしなさい。\",\"wrongAnswer\":\"He plays also soccer.\",\"trapExplanation\":\"日本語の「サッカーも」の「も」が soccer に付いているので、also も soccer の直前に置いてしまう。also の位置は語ではなく文の構造で決まる。\",\"correctAnswer\":\"He also plays soccer.\",\"correctExplanation\":\"also は一般動詞の前に置く（He also plays soccer.）。be動詞や助動詞があるときはその後ろに置く（He is also kind. ／ He can also swim.）。文末に置きたいときは also ではなく too を使い、He plays soccer, too. とする。位置をまちがえやすい語なので、「also は動詞の前、too は文の最後」と型で覚える。\"}]}",
"{\"id\":\"eigo_s401\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"段落①：主題文（topic sentence）を見つける\",\"description\":\"段落の中心の1文を見つけ、残りをその支えとして読む\",\"intro\":\"段落は文がたくさん並んでいるように見えますが、言いたいことは一つだけです。それを書いた一文を主題文といい、多くは段落の先頭にあります。残りの文は、その一文を支える材料。読む重さを変えると読解は速くなります。\",\"order\":901,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"1つの段落には言いたいことが1つだけある。それを書いた文を主題文（topic sentence）という。\",\"主題文は段落の1文目にあることが最も多い。まず1文目を読む。\",\"主題文以外の文（支持文）は、理由・具体例・数字など、主題文を支える材料である。\",\"主題文には具体的すぎる語（固有名詞・細かい数字）が入らない。入っていたらそれは支持文。\",\"各段落の主題文をつなぐと、文章全体の要約になる。\"],\"sections\":[{\"heading\":\"段落は「1つの言いたいこと」でできている\",\"body\":\"英語の文章は段落（paragraph）ごとに、言いたいことを1つだけ述べるという書き方をする。この決まりのおかげで、段落の1文目を読むだけで内容の見当がつく。\\n\\n■ 段落の3つの部品\\n①主題文（topic sentence）… その段落で言いたいこと。ふつう1文目。\\n②支持文（supporting sentences）… ①を支える理由・具体例・数字・体験。\\n③まとめ文（concluding sentence）… ①を言いかえて結ぶ。ないこともある。\\n\\n例）\\n（①）Reading aloud is a good way to learn English.（音読は英語を学ぶよい方法だ）\\n（②）When you read aloud, you use your eyes, your mouth, and your ears at the same time.\\n（②）Studies show that students who read aloud every day get better scores in listening tests.\\n（③）So, try to read your textbook aloud for ten minutes every day.\\n\\n■ 主題文の見分け方\\n・その段落のほかの文が、すべてその文の説明になっているか。\\n・具体的すぎないか（Studies show that … は支持文。証拠を出しているから）。\\n・つなぎ語で始まっていないか（For example／Second などで始まる文は支持文）。\\n\\n★ ポイント：主題文だけを読んでいけば、長い文章も3〜5文の要約になる。時間が足りないときは、各段落の1文目だけ読んで全体像をつかんでから設問に取りかかるとよい。\\n\\n⚠ 注意：段落の1文目が話の導入（Last summer, I went to Hokkaido.）で終わっていることもある。物語文では主題文の考え方は使わない。主題文は説明文・意見文の読み方である。\",\"figureId\":\"lf_eigoext11_401\"},{\"heading\":\"主題文と支持文を分ける\",\"body\":\"次の段落で、主題文がどれかを考える。\\n\\nDogs are useful to people in many ways. Some dogs help people who cannot see well. These dogs are called guide dogs, and they learn how to walk safely with their owners. Other dogs work with the police and find things by using their noses. There are also dogs that visit hospitals and make sick people feel better. In these ways, dogs are not only pets but also our partners.\\n\\n■ 分け方\\n主題文：Dogs are useful to people in many ways.（1文目）\\n支持文①：盲導犬の説明（Some dogs …）\\n支持文②：警察犬の説明（Other dogs …）\\n支持文③：病院を訪れる犬の説明（There are also dogs …）\\nまとめ文：In these ways, dogs are not only pets but also our partners.\\n\\n■ 目印になった語\\n・Some 〜 … Other 〜 … There are also 〜（例を並べる形）\\n・In these ways（まとめの合図）\\n・not only A but also B（AだけでなくBも）\\n\\n★ ポイント：Some 〜, Other 〜 という並べ方が出たら、それは主題文を支える例の列挙である。「いくつかの犬は」で始まる文は、段落全体をまとめる文にはなりえない。\\n\\n⚠ 注意：この段落の要旨を「盲導犬は目の不自由な人を助ける」と書くと不正解。それは3つの例のうちの1つにすぎない。要旨は必ず「全部の例をふくむ広さ」でなければならない。\",\"mangaId\":\"eigo_s401_xm\"}],\"trapExamples\":[{\"question\":\"上の段落の主題文（topic sentence）として最も適切な1文を選びなさい。\",\"wrongAnswer\":\"These dogs are called guide dogs, and they learn how to walk safely with their owners.\",\"trapExplanation\":\"「盲導犬」という具体的な内容がくわしく説明されているため、いちばん重要な文に見えてしまう。しかしこれは3つ並んだ例の1つ目の説明にすぎない。\",\"correctAnswer\":\"Dogs are useful to people in many ways.\",\"correctExplanation\":\"主題文はその段落のすべての文をふくむ広さでなければならない。in many ways（さまざまな点で）とあるからこそ、盲導犬・警察犬・病院を訪れる犬という3つの例が続けられる。具体的な名前（guide dogs）や細かい説明が入った文は支持文だと判断する。\"},{\"question\":\"上の段落について、In these ways, dogs are not only pets but also our partners. の意味として正しいのはどちらか。（ア）犬はペットではなく仲間である（イ）犬はペットであるだけでなく仲間でもある\",\"wrongAnswer\":\"（ア）犬はペットではなく仲間である\",\"trapExplanation\":\"not only の not だけを見て「〜ではない」と否定文として読んでしまう。not only A but also B は1つのまとまった表現で、A を打ち消しているわけではない。\",\"correctAnswer\":\"（イ）犬はペットであるだけでなく仲間でもある\",\"correctExplanation\":\"not only A but also B は「AだけでなくBもまた」という意味で、AもBも両方あてはまる。ここでは「ペットでもあり、さらに仲間でもある」となる。似た形に not A but B（AではなくB）があり、こちらは A を打ち消す。only と but also があるかどうかで区別すること。\"}]}",
"{\"id\":\"eigo_s402\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"段落②：支持文の役割を見抜く\",\"description\":\"理由・具体例・数字・体験という4種類の支えを区別して読む\",\"intro\":\"主題文を支える文には、理由・具体例・数字・体験の四種類があります。どれがいくつ並んでいるかを数えると、段落の作りがそのまま見えてきます。とくに数字は設問になりやすいので、見つけたら必ず印をつけます。\",\"order\":902,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"支持文には4種類ある：理由（because）／具体例（for example）／数字・調査（studies show）／体験（When I was 〜）。\",\"支持文がいくつあるかを数えると、段落の構造がそのまま見える。\",\"数字が出てきたら必ず印をつける。細かい内容を問う設問はほぼ数字から作られる。\",\"体験談は説明文の中でも使われる。「私の場合は」で始まる部分は主張ではない。\",\"支持文だけを読んで答えを書くと、範囲がせまい誤答になる。\"],\"sections\":[{\"heading\":\"支えの4つの型\",\"body\":\"主題文を支える文（支持文）は、次の4つの型のどれかである。型がわかると、その段落がどう展開するか先読みできる。\\n\\n■ ①理由（なぜそう言えるのか）\\n主題：Walking to school is good for students.\\n支持：Because they can wake up their bodies before the first class.\\n合図：because／since／The reason is that 〜\\n\\n■ ②具体例（実際にはこうだ）\\n支持：For example, students in a school in Nagano walk about two kilometers every morning.\\n合図：for example／such as／One example is 〜\\n\\n■ ③数字・調査（証拠を出す）\\n支持：A study found that 70 percent of them said they felt better in class.\\n合図：A study shows／According to 〜／percent／about 〜\\n\\n■ ④体験（自分の場合）\\n支持：When I was in the fourth grade, I started walking to school, and I stopped falling asleep in class.\\n合図：When I was 〜／In my case／I remember 〜\\n\\n★ ポイント：According to 〜（〜によれば）は、情報の出どころを示す表現。According to the graph（グラフによれば）は図表つき読解で必ず出る。\\n\\n⚠ 注意：④の体験は、書き手にとっては強い根拠でも、「みんなにあてはまること」ではない。要旨をまとめるときは体験そのものを書かない。\",\"figureId\":\"xf_eigo_s402\"},{\"heading\":\"構造をメモしながら読む\",\"body\":\"次の段落を、主題文と支持文に分けてメモを取る。\\n\\nSleeping well is more important than studying late at night. When you sleep, your brain keeps working and saves what you learned during the day. According to a study in the United States, students who slept for eight hours got higher scores than students who slept for five hours and studied longer. I tried this myself before my last test. I stopped studying at ten and went to bed early. The next morning, I could remember more words than usual. If you want better scores, go to bed early instead of studying until midnight.\\n\\n■ メモの取り方\\n主題：よく眠ることは夜おそくまで勉強するより大切\\n　支①（理由）：眠っている間に脳が働き、その日に学んだことを保存する\\n　支②（調査）：アメリカの研究。8時間眠った生徒＞5時間で長く勉強した生徒\\n　支③（体験）：筆者は10時に勉強をやめて早く寝たら、翌朝いつもより単語を思い出せた\\n結論：よい点を取りたいなら、夜中まで勉強せず早く寝よ\\n\\nこのメモがそのまま要約になる。設問「筆者の主張は何か」には主題または結論を、「アメリカの研究では何がわかったか」には支②を答える。\\n\\n★ ポイント：支持文が3つ以上並ぶ段落では、必ず番号をふってメモを取る。頭の中だけで整理しようとすると必ず取りこぼす。\\n\\n⚠ 注意：instead of 〜ing（〜するかわりに）は入試頻出。go to bed early instead of studying until midnight は「夜中まで勉強するかわりに早く寝る」。instead of の後ろは名詞か -ing 形になる。\",\"mangaId\":\"eigo_s402_xm\"}],\"trapExamples\":[{\"question\":\"上の段落について、筆者の主張として最も適切なものを選びなさい。（ア）筆者は前回のテスト前に10時に勉強をやめた（イ）夜おそくまで勉強するより、よく眠るほうが大切だ\",\"wrongAnswer\":\"（ア）筆者は前回のテスト前に10時に勉強をやめた\",\"trapExplanation\":\"I tried this myself … と一人称で書かれているので、筆者が言いたいことのように見える。しかしこれは主張を支えるための体験談（支持文）にすぎない。\",\"correctAnswer\":\"（イ）夜おそくまで勉強するより、よく眠るほうが大切だ\",\"correctExplanation\":\"1文目の Sleeping well is more important than studying late at night. が主題文で、最後の If you want better scores, go to bed early … がその言いかえの結論である。体験談は「筆者にも効果があった」という証拠であって主張ではない。I や my で始まる文が主張かどうかは、その段落の1文目と見比べて判断する。\"},{\"question\":\"上の段落について、「8時間眠った生徒のほうが点数が高かった」という内容はどの支えにあたるか。\",\"wrongAnswer\":\"筆者自身の体験\",\"trapExplanation\":\"同じ段落の中に筆者の体験談もあるため、区別せずにまとめて「筆者の経験」としてしまう。しかしこの部分には According to a study in the United States という出どころが示されている。\",\"correctAnswer\":\"調査・研究の結果（数字による証拠）\",\"correctExplanation\":\"According to 〜（〜によれば）は情報の出どころを示す表現で、続く内容は筆者の体験ではなく客観的なデータである。筆者の体験は次の I tried this myself 〜 から始まる。「だれが述べていることか」を示す表現（According to／A study shows／My teacher says）に印をつけると、支えの種類をまちがえない。\"}]}",
"{\"id\":\"eigo_s403\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"段落③：主題文が最後にある型・段落ごとの要約\",\"description\":\"結論が段落末に置かれる型を知り、段落ごとに一言メモを作る\",\"intro\":\"一文目を読んでも主張が見当たらない段落があります。具体例や問いかけから始めて、結論を最後に置く型だからです。So や Therefore で始まる最後の文が、その段落の中心になります。二つの型を見分けられるようにします。\",\"order\":903,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"主題文は段落の最初にあることが多いが、最後に置かれることもある（結論あとおき型）。\",\"1文目が具体例・体験・問いかけで始まっていたら、主題文は最後にあると考える。\",\"So／Therefore／In this way／This means that 〜 で始まる最後の文は主題文の可能性が高い。\",\"段落ごとに日本語で一言メモ（10〜20字）を作ると、内容一致問題を解く時間が半分になる。\",\"問いかけ（Do you know 〜?）で始まる段落は、その答えが主題文である。\"],\"sections\":[{\"heading\":\"主題文が最後に来る型\",\"body\":\"主題文は段落の最初にあるのが基本だが、書き手が読者を引きこみたいときは、具体例や体験から始めて最後に主張を置く。これを結論あとおき型という。\\n\\n■ 1文目が次のような形なら、結論は最後にある\\n・問いかけ：Do you know how many languages are spoken in the world?\\n・体験：Last summer, I visited a small village in Nagano.\\n・意外な事実：A cat sleeps for about thirteen hours a day.\\n・数字：In Japan, about 30 percent of people live alone.\\n\\n■ 最後の主題文の目印\\nSo, …／Therefore, …／In this way, …／This means that …／We should …／I think that …\\n\\n例）\\nDo you know how many kinds of insects live on the earth? Scientists have found about one million kinds, and they say there may be many more. Some of them live only in one small forest. When that forest is cut down, those insects disappear forever. This means that protecting forests is protecting many lives we have never seen.\\n\\n主題文は最後の This means that 〜 の文である。\\n\\n★ ポイント：段落の1文目を読んで「これは例だな」と思ったら、すぐ最後の1文に目を移す。そこに答えがあることが多い。\\n\\n⚠ 注意：段落の途中に主題文がある型もまれにある。その場合はたいてい However のあとに置かれている。「1文目 → 最終文 → However の後ろ」の順にさがせば、ほぼ確実に見つかる。\",\"figureId\":\"lf_eigoext11_403\"},{\"heading\":\"段落ごとの一言メモを作る\",\"body\":\"長文問題では、段落ごとに日本語で短いメモを取ると、あとで設問の答えをさがす時間が大きく減る。\\n\\n■ メモのきまり\\n・1段落につき10〜20字。長く書かない。\\n・主語と述語がある形にする（「〜は〜だ」）。\\n・段落番号を必ず書く。\\n\\n例）4段落の説明文なら\\n①ペットボトルは世界中で使われている\\n②しかし多くが海に流れこむ\\n③海の生き物が食べてしまう危険\\n④私たちにできる3つのこと\\n\\nこのメモがあれば、設問「海の生き物への影響が書かれているのは何段落か」に一瞬で答えられる。\\n\\n■ メモを作るタイミング\\n段落を1つ読み終えるたびに作る。全部読んでからまとめて作ろうとすると、前半を忘れている。\\n\\n■ 設問との対応\\n・内容一致問題 → メモを見て、どの段落を読み返せばよいか決める\\n・要旨・タイトル問題 → メモを全部つないで一文にする\\n・段落の要旨問題 → その段落のメモがそのまま答えになる\\n\\n★ ポイント：メモは日本語でよい。英語で書こうとすると時間がかかるうえ、書くこと自体が目的になってしまう。\\n\\n⚠ 注意：メモに具体例や数字を書かないこと。「①ペットボトルは年間4000億本作られる」のように数字を書くと、メモが段落の一部の情報になってしまい、全体像がわからなくなる。数字は本文に線を引くだけでよい。\"},{\"heading\":\"なぜ結論を最後に置く段落があり、なぜメモは日本語で短く書くのか\",\"mangaId\":\"eigo_s403_manga\",\"body\":\"書き手が問いかけ・体験・意外な数字から段落を始めるのは、**読者を引きこんでから結論を言いたい**からです。「昆虫は何種類いるか知っていますか」と問い、100万種という数字で驚かせ、森が切られると消えると示したあとで、This means that 〜（これは〜を意味する）と主張を置く。だから1文目が例や問いかけなら、主題文は最後にあります。So・Therefore・In this way・This means that は「ここまでをまとめます」という合図です。\\n\\n段落ごとのメモを日本語で10〜20字にするのは、メモの目的が**「その段落が何の話か」を思い出すこと**だからです。英語で書くと書くこと自体に時間を取られ、数字を入れると段落の一部の情報になって全体像がぼやけます。設問「海の生き物への影響はどの段落か」に一瞬で答えるには、段落全体をおおう広さのメモが要ります。数字は本文に線を引いておけば、メモで段落を特定してから見に行けます。\\n\\n■ 確かめのしかた\\n①1文目が**問いかけ・体験・意外な事実・数字**なら、最後の1文を見る。So／Therefore／This means that／We should があれば主題文。\\n②見つからなければ However のあと。探す順は「1文目→最終文→However の後ろ」。\\n③段落を読み終えるたびに**日本語で10〜20字、主語と述語のある形、段落番号つき**でメモする。数字は書かず本文に線。\\n④設問に対応させる：内容一致→メモで段落を決めて読み返す。要旨・タイトル→メモをつないで一文に。段落の要旨→そのメモ。\\n\\n★ ここがポイント：問いかけや例から始まる段落は**読者を引きこんでから結論を置く**ので、主題文は最後（So・This means that）。メモは**段落が何の話かを思い出すため**なので、日本語で短く、数字は入れない。\"}],\"trapExamples\":[{\"question\":\"上の昆虫についての段落の主題文として最も適切なものを選びなさい。\",\"wrongAnswer\":\"Scientists have found about one million kinds, and they say there may be many more.\",\"trapExplanation\":\"「約100万種」という具体的な数字が入っていて重要そうに見えるため、これを中心の文だと考えてしまう。主題文は段落の最初にあるという思いこみも、この誤りを強める。\",\"correctAnswer\":\"This means that protecting forests is protecting many lives we have never seen.\",\"correctExplanation\":\"この段落は Do you know 〜? という問いかけで始まっているので、結論あとおき型である。数字は主題を支える材料にすぎない。最後の This means that 〜（これは〜ということを意味する）は、それまでの内容をまとめる典型的な主題文の形である。1文目が問いかけ・体験・数字なら最終文を見る、と決めておくとよい。\"},{\"question\":\"段落ごとの一言メモとして適切なのはどちらか。（ア）ペットボトルは年間約4000億本作られる（イ）ペットボトルは世界中で大量に使われている\",\"wrongAnswer\":\"（ア）ペットボトルは年間約4000億本作られる\",\"trapExplanation\":\"数字が入っているほうが正確で役に立つメモだと考えてしまう。しかしメモの目的は「その段落が何の話か」を思い出すことなので、細かすぎる情報はかえって全体像をぼやけさせる。\",\"correctAnswer\":\"（イ）ペットボトルは世界中で大量に使われている\",\"correctExplanation\":\"メモは段落全体をおおう広さで書く。数字は支持文の中の情報なので、メモではなく本文に線を引いて残す。設問で数字が問われたときは、メモでどの段落かを特定し、線を引いた場所を見に行けばよい。メモと線引きは役割が別だと考えること。\"}]}",
"{\"id\":\"eigo_s404\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"物語文①：登場人物と場面をつかむ\",\"description\":\"だれが・いつ・どこで・何をしたのかを最初の数文で確定させる\",\"intro\":\"物語文でまず起こる事故は、登場人物の取りちがえです。だれが何人いるのかを確定しないまま読み進めると、気持ちも行動も混ざってしまいます。人物・時・場所を最初の数文でおさえる読み方から始めます。\",\"order\":904,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"物語文はまず「登場人物」を丸で囲む。名前が出るたびに丸をつけ、何人いるかを確定する。\",\"次に「いつ（時）」と「どこで（場所）」を四角で囲む。物語は時と場所が変わるところで場面が切りかわる。\",\"登場人物の関係（家族・友だち・先生と生徒）を最初の段落でつかむ。my sister／my friend Aya など。\",\"会話（引用符で囲まれた部分）はだれのせりふかを必ず確かめる。said の主語がその話し手。\",\"説明文と違い、物語文には主題文がない。出来事の流れそのものが内容になる。\"],\"sections\":[{\"heading\":\"最初の3文で場面を確定する\",\"body\":\"物語文は、最初の2〜3文に「だれが・いつ・どこで」がまとめて書かれていることが多い。ここを読み落とすと、あとの内容が全部あいまいになる。\\n\\n例）Last summer, Aya visited her grandmother in a small village in Akita. She stayed there for two weeks.\\n・だれ：Aya（と grandmother）\\n・いつ：Last summer（去年の夏）、2週間\\n・どこ：秋田の小さな村\\n\\n■ 印のつけ方\\n・人名 → ○で囲む\\n・時を表す語（Last summer／One morning／The next day／At last）→ 四角で囲む\\n・場所を表す語（in the village／at the station／in front of the school）→ 下線\\n\\n■ 登場人物の関係をつかむ表現\\n・my sister Yuki（姉のユキ）※名前の前に関係が書かれる\\n・her friend, Ken（彼女の友だちのケン）\\n・a boy named Taro（タロウという名前の少年）\\n・Mr. Sato, our English teacher（英語の先生の佐藤先生）\\n\\n★ ポイント：日本語の物語文と違い、英語の物語文では主語がはっきり書かれる。だれが何をしたかは必ず文の先頭にある。主語を追うだけで話の流れが追える。\\n\\n⚠ 注意：物語文では「主題文をさがす」読み方は使えない。かわりに「出来事を順に並べる」読み方をする。説明文と物語文で読み方を切りかえること。\",\"figureId\":\"xf_eigo_s404\"},{\"heading\":\"せりふのだれが話しているか\",\"body\":\"物語文では会話が多く出てくる。だれのせりふかを取りちがえると、内容一致問題を落とす。\\n\\n例）\\n\\\"Where are you going?\\\" asked Ken.\\n\\\"I'm going to the library,\\\" Mika answered.\\n\\\"Can I come with you?\\\" he said.\\n\\\"Of course,\\\" she said with a smile.\\n\\n■ 話し手の見つけ方\\n・せりふの直後に asked Ken／Mika answered のように書かれている。\\n・he said／she said と代名詞で書かれているときは、直前に出た人物を確かめる。\\n・せりふが2つ続いているときは、話し手が交互に入れかわるのがふつう。\\n\\n■ 会話に使われる動詞\\nsaid（言った）／asked（たずねた）／answered（答えた）／replied（返事をした）／\\nshouted（さけんだ）／whispered（ささやいた）／cried（泣いた・さけんだ）\\n※ shouted・whispered などは、その人の気持ちを表す手がかりになる。\\n\\n★ ポイント：会話文の順番を追うときは、せりふの横に「ケ」「ミ」のように話し手の頭文字を書きこむとよい。あとで読み返すときに一目でわかる。\\n\\n⚠ 注意：英語では「〜と言った」の部分がせりふの前に来ることも後ろに来ることもある。Ken said, \\\"Let's go.\\\" と \\\"Let's go,\\\" said Ken. はどちらも正しく、意味は同じである。said Ken のように動詞が主語より前に来ても、主語は Ken である。\"},{\"heading\":\"なぜ最初の3文で人物・時・場所を確定するのか、なぜ said Ken の主語が Ken なのか\",\"mangaId\":\"eigo_s404_manga\",\"body\":\"英語の物語文は、最初の2〜3文に「だれが・いつ・どこで」をまとめて書くのがふつうです。ここで登場人物の数と関係（my sister Yuki・her friend Ken）を確定しておかないと、あとで he・she が出たときにだれを指すか決められず、気持ちも行動も混ざります。説明文の「主題文を探す」読み方が物語文に使えないのは、物語には主張がなく、**出来事の流れそのものが内容**だからです。\\n\\n\\\"Let's go,\\\" said Ken. で主語が Ken なのは、これがせりふのあとに「〜と言った」を置くときの**決まった語順の入れかえ**だからです。意味は Ken said, \\\"Let's go.\\\" と同じです。代名詞のときは入れかえず he said とします。he・she が出たら、**性別**と**会話が交互に入れかわるリズム**の二つで話し手を決めます。\\n\\n■ 確かめのしかた\\n①最初の3文で、**人名に○、時を表す語に□、場所に下線**を引く。人物が何人いるかを言えるか。\\n②人物の関係を表す語（my sister 〇〇、her friend 〇〇、a boy named 〇〇）から関係をつかむ。\\n③せりふのあとの asked Ken／Mika answered／said Ken で話し手を決める。代名詞なら性別（he＝男性）と交互のリズムで確かめる。\\n④shouted・whispered・cried は気持ちの手がかり。せりふの横に話し手の頭文字を書きこむ。\\n\\n★ ここがポイント：物語文は**出来事の流れが内容**なので、最初の3文で**人物・時・場所を確定**してから追う。said Ken は**語順を入れかえた決まった形**で主語は Ken、代名詞は性別と交互のリズムで決める。\"}],\"trapExamples\":[{\"question\":\"\\\"Can I come with you?\\\" he said. の he はだれか。上の会話文から答えなさい。\",\"wrongAnswer\":\"Mika\",\"trapExplanation\":\"直前の文が \\\"I'm going to the library,\\\" Mika answered. なので、いちばん近い名前である Mika を選んでしまう。しかし he は男性を指す代名詞なので、女性である Mika は候補にならない。\",\"correctAnswer\":\"Ken\",\"correctExplanation\":\"この会話に出てくるのは Ken（男性）と Mika（女性）の2人だけ。he は男性なので Ken である。会話文では話し手が交互に入れかわるという原則からも確かめられる（Ken → Mika → Ken → Mika）。代名詞の性別と、会話の交互のリズムの2つで判断する。\"},{\"question\":\"\\\"Let's go,\\\" said Ken. の主語（だれが言ったのか）を答えなさい。\",\"wrongAnswer\":\"said が主語（または主語がない）\",\"trapExplanation\":\"英語の文は「主語＋動詞」の順という原則にとらわれ、said が先に来ているこの形を特別な文だと思って混乱してしまう。\",\"correctAnswer\":\"Ken\",\"correctExplanation\":\"せりふの後ろに置く said Ken は、Ken said の語順を入れかえた形で、物語文でよく使われる。意味は Ken said, \\\"Let's go.\\\" とまったく同じである。代名詞の場合は入れかえず said he ではなく he said とするのがふつう。この語順の入れかえは物語文の読解でしか出てこないので、形として覚えておく。\"}]}",
"{\"id\":\"eigo_s405\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"物語文②：出来事の流れとつながり\",\"description\":\"起こったことを順に追い、ある出来事が次の出来事を引き起こす関係をつかむ\",\"intro\":\"物語は、出来事が順に並んでいるだけではありません。ある出来事が次の出来事を引き起こす、という「だから」の関係でつながっています。過去形の動詞を追いかけながら、その原因と結果のつながりをつかむ練習をします。\",\"order\":905,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"物語文は「出来事①→②→③」の連なりでできている。動詞（過去形）を追えば流れがわかる。\",\"出来事のつながりには「そのあと」だけでなく「だから」の関係がある。\",\"suddenly（突然）／at that time（そのとき）／just then（ちょうどそのとき）は場面が動く合図。\",\"物語文の設問「なぜ〜したのか」は、その出来事の直前の文に答えがある。\",\"最後の1〜2文には、主人公が得た気づきが書かれることが多い。\"],\"sections\":[{\"heading\":\"過去形の動詞を拾う\",\"body\":\"物語文は過去の出来事を述べる文章なので、動詞はほとんどが過去形である。過去形の動詞だけを順に拾えば、あらすじがそのまま出てくる。\\n\\n例）\\nOne Saturday morning, Taro went to the park with his dog. He threw a ball, and the dog ran after it. Suddenly, the dog stopped and looked at a small tree. Taro walked to the tree and found a bird on the ground. The bird could not fly. Taro carried it home carefully and gave it some water. Three days later, the bird flew away from his window.\\n\\n■ 動詞だけ拾う\\nwent → threw → ran → stopped → looked → walked → found → carried → gave → flew away\\nこれを日本語にすると\\n「行った→投げた→追いかけた→止まった→見た→歩いた→見つけた→運んだ→やった→飛び去った」\\nこれだけであらすじが完成する。\\n\\n■ 不規則動詞の過去形（物語文頻出）\\ngo-went／come-came／see-saw／find-found／run-ran／take-took／give-gave／\\nfly-flew／throw-threw／catch-caught／bring-brought／think-thought／feel-felt\\n\\n★ ポイント：過去形がわからない動詞があると、その出来事だけ飛んでしまう。不規則動詞は「原形・過去形・過去分詞」の3つをセットで覚えること。\\n\\n⚠ 注意：could not fly のように助動詞が入ると、動詞は原形に戻る（× could not flew）。過去の内容でも、助動詞の後ろは必ず原形である。\",\"figureId\":\"xf_eigo_s405\"},{\"heading\":\"出来事のつながり方\",\"body\":\"出来事は「そのあと」だけでなく「だから」でつながっていることがある。この違いが理由を問う設問で効いてくる。\\n\\n■ ただの順序（そのあと）\\nHe finished his homework. Then he watched TV.\\n→ 宿題を終えたから見たわけではない。順に起こっただけ。\\n\\n■ 因果（だから）\\nThe dog stopped and looked at a small tree. So Taro walked to the tree.\\n→ 犬が止まったから、タロウが木のところへ行った。\\n\\n■ 場面が動く合図の語\\n・Suddenly,（突然）／All of a sudden,（突然）\\n・Just then,（ちょうどそのとき）／At that moment,（その瞬間）\\n・After a while,（しばらくして）／A few minutes later,（数分後）\\n・Finally,（ついに）／At last,（ようやく）\\n\\nこれらの語のあとには、必ず物語が動く出来事が来る。設問はここから作られることが多いので、印をつける。\\n\\n■ 物語の最後に注目する\\n物語文の最後の1〜2文には、主人公の気づきや変化が書かれる。\\n例）Since that day, Taro has looked at small living things more carefully.\\n（あの日以来、タロウは小さな生き物をより注意深く見るようになった）\\nこのような文が「この物語から筆者が伝えたいこと」を問う設問の答えになる。\\n\\n★ ポイント：Since that day（あの日以来）／From that time on（そのときから）は、物語の締めくくりの決まり文句。見つけたら必ず線を引く。\",\"mangaId\":\"eigo_s405_xm\"}],\"trapExamples\":[{\"question\":\"上の物語について、Why did Taro walk to the tree? に答えなさい。\",\"wrongAnswer\":\"Because he found a bird on the ground.（地面に鳥を見つけたから）\",\"trapExplanation\":\"木のところへ行った直後の内容（鳥を見つけた）を理由にしてしまう。しかし鳥を見つけたのは木のところへ行った「結果」であって、行く前の理由ではない。理由は必ずその出来事より前にある。\",\"correctAnswer\":\"Because his dog stopped and looked at a small tree.（犬が立ち止まって小さな木を見ていたから）\",\"correctExplanation\":\"理由を問われたら、その出来事が書かれた文より前を見る。ここでは Suddenly, the dog stopped and looked at a small tree. が直前の文で、これが原因である。「なぜ」の答えは前、「どうなった」の答えは後ろ、と向きを決めておくと迷わない。\"},{\"question\":\"The bird could not ( fly / flew ). 正しいほうを選びなさい。\",\"wrongAnswer\":\"flew\",\"trapExplanation\":\"物語全体が過去の話なので、動詞もすべて過去形にすべきだと考えて flew を選んでしまう。時制をそろえようとする気持ちが、かえってまちがいを生む。\",\"correctAnswer\":\"fly\",\"correctExplanation\":\"could はそれ自体が can の過去形なので、過去を表す仕事はもう終わっている。助動詞（can／could／will／would／must／should）の後ろは、いつでも動詞の原形である。同じように He could not come. ／ She would not answer. のように、後ろは原形になる。\"}]}",
"{\"id\":\"eigo_s406\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"物語文③：時系列を並べ直す\",\"description\":\"書かれている順と起こった順がちがう文章を、時を表す語で整理する\",\"intro\":\"書かれている順と、実際に起こった順がちがう文章があります。今の場面から始めて過去を思い出す、回想という書き方です。three years ago や later といった時のことばを全部ぬき出して、正しい順に並べ直します。\",\"order\":906,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"英語の物語文は、今の場面から始めて過去にさかのぼることがある（回想）。\",\"時を表す語（now／three years ago／last spring／this spring／later）を全部ぬき出して並べ直す。\",\"ago は「今から〜前」、before は「そのときより前」。基準がちがう。\",\"「出来事を起こった順に並べかえなさい」という設問は、時を表す語だけで解ける。\",\"過去のさらに前を表すときは had ＋過去分詞（過去完了）を使うことがある。\"],\"sections\":[{\"heading\":\"書かれた順と起こった順\",\"body\":\"物語文の設問でよく出るのが「次の出来事を起こった順に並べかえなさい」である。これは、英語の物語が必ずしも時間の順に書かれていないためである。\\n\\n次の英文を読む。\\n\\nKen is the captain of the soccer team now. He was not always a good player. His family moved to this town three years ago, and he did not know anyone here. Last spring, he joined the soccer team because his classmate asked him to. In the summer, the team played in a big game, and Ken scored his first goal. However, he broke his leg last winter and could not play for three months. He came back to the team this spring. His teammates chose him as their captain because he never gave up.\\n\\n■ 書かれている順\\n今キャプテン → 3年前に引っこし → 去年の春に入部 → その夏に初ゴール → 去年の冬にけが → 今年の春に復帰\\n\\n■ 起こった順に並べ直す\\n①three years ago：この町に引っこしてきた\\n②last spring：サッカー部に入った\\n③in the summer：初めてゴールを決めた\\n④last winter：脚を折って3か月プレーできなかった\\n⑤this spring：チームに復帰した\\n⑥now：キャプテンになっている\\n\\n★ ポイント：時を表す語だけを○で囲み、その順に番号をふる。本文を読み返さなくても並べかえ問題が解ける。\\n\\n⚠ 注意：1文目の now（今）が、時間の上ではいちばん最後である。冒頭の文が最初の出来事とはかぎらない。\",\"figureId\":\"lf_eigoext11_406\",\"mangaId\":\"eigo_s406_xm\"},{\"heading\":\"時を表す語のまとめ\",\"body\":\"時系列を整理するために、時を表す語を正確に覚えておく。\\n\\n■ 過去を表す語\\n・three years ago（3年前）／a week ago（1週間前）※ ago は「今から〜前」\\n・last spring／last winter／last night（この前の〜）\\n・yesterday（きのう）／the day before yesterday（おととい）\\n・when I was a child（子どものころ）\\n・in 2020（2020年に）\\n\\n■ 現在・これから\\n・now（今）／these days（このごろ）／today（きょう）\\n・this spring（今年の春）／next week（来週）／tomorrow（あす）\\n\\n■ 順序を表す語\\n・then（それから）／after that（そのあと）／later（あとで）\\n・soon（まもなく）／at last（ついに）／finally（最後に）\\n・a few days later（数日後）／three days later（3日後）\\n\\n■ ago と before のちがい\\n・ago … 今を基準にして「今から〜前」。過去形と使う。\\n　I met him three days ago.（3日前に会った）\\n・before … 過去のあるときを基準にして「そのときより前」。\\n　When I arrived, he had left an hour before.（着いたとき、彼はその1時間前に出ていた）\\n\\n★ ポイント：ago は必ず「数＋期間＋ago」の形で使い、文の最後に置く。× ago three days。\\n\\n⚠ 注意：過去のさらに前の出来事は had ＋過去分詞（過去完了）で表す。難関校では出るので、had left＝「（そのときより前に）出てしまっていた」と読めるようにしておく。\"}],\"trapExamples\":[{\"question\":\"上の英文について、次の出来事のうち、いちばん先に起こったものはどれか。（ア）Ken がサッカー部に入った（イ）Ken の家族がこの町に引っこしてきた\",\"wrongAnswer\":\"（ア）Ken がサッカー部に入った\",\"trapExplanation\":\"本文で先に読んだ内容が先に起こったと思いこんでしまう。しかし引っこしは three years ago、入部は last spring なので、時間の上では引っこしのほうが先である。\",\"correctAnswer\":\"（イ）Ken の家族がこの町に引っこしてきた\",\"correctExplanation\":\"時を表す語で比べる。three years ago（3年前）と last spring（この前の春＝1年以内）なら、3年前のほうが古い。並べかえ問題では、本文の順ではなく ago・last・this・now の順に並べ直すこと。\"},{\"question\":\"「私は3日前に彼に会いました」を英語にしなさい。\",\"wrongAnswer\":\"I meet him before three days.\",\"trapExplanation\":\"「〜前」を before と覚えていること、また日本語の「3日前に彼に会いました」の語順をそのまま移すことから、before three days としてしまう。動詞を過去形にしていない点も誤り。\",\"correctAnswer\":\"I met him three days ago.\",\"correctExplanation\":\"「今から〜前」は ago を使い、「数＋期間＋ago」の順で文の最後に置く。また ago は必ず過去形の動詞と使うので meet ではなく met。before は「そのときより前」を表す語で、three days before は「（過去のある時点の）3日前」という意味になり、この文には合わない。\"}]}",
"{\"id\":\"eigo_s407\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"物語文④：気持ちの変化と、その理由\",\"description\":\"主人公の気持ちがどこで動いたかと、動かしたきっかけを結びつける\",\"intro\":\"物語文の設問は、結局「どう思ったか」と「なぜそう思ったか」の二つに集まります。しかも気持ちは、glad や sad と直接書かれるとはかぎりません。泣いた、笑った、眠れなかった——行動から読み取る練習をします。\",\"order\":907,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"物語文の設問の中心は「気持ち」と「その理由」の2つ。\",\"気持ちを表す語（glad／sad／worried／surprised／nervous／proud）を全部○で囲む。\",\"気持ちは直接書かれないこともある。行動（cried／smiled／could not sleep）から読み取る。\",\"気持ちが変わった直前の出来事が、変化のきっかけ（設問の答え）である。\",\"物語の最後には、いちばん大きな気持ちの動きが置かれることが多い。\"],\"sections\":[{\"heading\":\"気持ちを表す語を覚える\",\"body\":\"気持ちを問う設問に答えるには、まず気持ちを表す英語を知っていなければならない。\\n\\n■ よい気持ち\\nglad／happy（うれしい）／excited（わくわくした）／proud（誇らしい）／\\nrelieved（ほっとした）／satisfied（満足した）／thankful（感謝している）\\n\\n■ よくない気持ち\\nsad（悲しい）／worried（心配な）／nervous（緊張した）／afraid／scared（こわい）／\\ndisappointed（がっかりした）／angry（怒った）／lonely（さびしい）／shy（はずかしい）\\n\\n■ どちらともいえない\\nsurprised（おどろいた）／confused（こんがらがった）／curious（知りたがっている）\\n\\n■ 気持ちを表す形の注意\\n・be surprised at 〜（〜におどろく）※ 前置詞とセット\\n・be interested in 〜（〜に興味がある）\\n・be worried about 〜（〜を心配している）\\n・feel ＋形容詞（I felt sad.）\\n・look ＋形容詞（He looked happy.＝うれしそうに見えた）\\n\\n★ ポイント：-ed の形（surprised／excited／interested）は「人がその気持ちになる」、-ing の形（surprising／exciting／interesting）は「物事がその気持ちにさせる」。The news was surprising. ／ I was surprised. と区別する。\\n\\n⚠ 注意：日本語の「〜させられた」に引きずられて I was excited. を「私は興奮させられた」と訳す必要はない。「私はわくわくした」でよい。\"},{\"heading\":\"気持ちの上がり下がりを追う\",\"body\":\"次の物語を読み、主人公の気持ちがどこで動いたかを確かめる。\\n\\nLast month, our class had a chorus contest. I was chosen as the pianist, and at first I was very happy. But the music was harder than I expected. Two weeks before the contest, I made many mistakes, and some of my classmates looked worried. I began to think that I could not do it. One day after school, my friend Aya stayed with me and sang while I played. We practiced together every day. On the day of the contest, my hands were shaking, but I played the whole piece without stopping. Our class did not win, but everyone smiled at me and said, \\\"Thank you.\\\" I have never been so glad.\\n\\n■ 気持ちの流れ\\n①I was very happy（ピアノ係に選ばれてうれしい）\\n②some of my classmates looked worried／I began to think that I could not do it（不安・自信をなくす）\\n③my friend Aya stayed with me（きっかけ）→ We practiced together every day（前向きに）\\n④my hands were shaking（緊張）→ I played the whole piece without stopping（やりとげた）\\n⑤I have never been so glad.（これまでで最高にうれしい）\\n\\n■ 気持ちが直接書かれていない部分\\n・my hands were shaking（手がふるえていた）→ 緊張していた\\n・everyone smiled at me（みんながほほえんだ）→ 認めてもらえた\\n行動や体の様子から気持ちを読み取る問題は、上位校でよく出る。\\n\\n★ ポイント：気持ちが変わった直前の文を見る。②から③に変わるきっかけは「友だちのアヤが残って、自分の伴奏で歌ってくれたこと」である。\\n\\n⚠ 注意：最後の I have never been so glad. は現在完了で「今までに一度もこんなにうれしかったことはない」＝「今がいちばんうれしい」という意味。never を見て「うれしくない」と読まないこと。\",\"figureId\":\"lf_eigoext11_407\"},{\"heading\":\"なぜ気持ちは行動から読み、なぜ never so がいちばんうれしいになるのか\",\"mangaId\":\"eigo_s407_manga\",\"body\":\"物語の書き手は、気持ちを glad・sad と直接書くより、**手がふるえた・みんながほほえんだ**という行動や体の様子で示すことを好みます。そのほうが読者が場面を思いうかべられるからです。だから気持ちを問う設問では、気持ちの語を○で囲むだけでなく、行動から気持ちを読み取ります。気持ちが変わった**直前の出来事**がきっかけなのは、心が動くには必ず原因があり、書き手はそれを変化の直前に置くからです。「優勝したから前向きになった」と想像で答えると、本文の did not win と矛盾します。\\n\\nI have never been so glad. が「これまででいちばんうれしい」になるのは、「こんなにうれしかったことは一度もない」＝「今がいちばん」という**最上級の言いかえ**だからです。never だけを見て「うれしくない」と読むと、結末が逆になります。-ed（surprised）は人がその気持ちになる、-ing（surprising）は物事がその気持ちにさせる、という区別も、主語が人か物事かで決めます。\\n\\n■ 確かめのしかた\\n①気持ちの語（glad・sad・worried・nervous・proud・surprised）を○で囲み、**行動や体の様子**（hands were shaking・smiled・could not sleep）も気持ちとして読む。\\n②気持ちの流れを①→②→③と番号で追い、変わった**直前の文**をきっかけとする。想像（優勝した）で答えていないか、本文と矛盾しないか。\\n③never＋so／such は**最上級の言いかえ**：I have never seen such a beautiful sunset.＝これまででいちばん美しい。\\n④-ed は人（I was excited.）、-ing は物事（The game was exciting.）。be surprised at・be interested in・be worried about は前置詞とセット。\\n\\n★ ここがポイント：書き手は気持ちを**行動や体の様子で示す**ので、行動から読む。きっかけは**変化の直前の出来事**。never so／such は**最上級の言いかえ**（今がいちばん）。\"}],\"trapExamples\":[{\"question\":\"上の物語について、筆者の気持ちが前向きに変わったきっかけは何か。\",\"wrongAnswer\":\"合唱コンクールで自分のクラスが優勝したこと。\",\"trapExplanation\":\"「気持ちが上向く＝よい結果が出た」と思いこんでしまう。しかし本文には Our class did not win（優勝しなかった）とはっきり書かれている。読まずに想像で答えた典型例。\",\"correctAnswer\":\"友だちのアヤが放課後に残って、自分の伴奏に合わせて歌ってくれたこと。\",\"correctExplanation\":\"気持ちが変わった直前の文を見る。I began to think that I could not do it.（もうむりだと思い始めた）の次に One day after school, my friend Aya stayed with me and sang while I played. が来て、そのあと We practiced together every day. と前向きな行動に変わっている。気持ちの変化のきっかけは、変化の直前の出来事である。\"},{\"question\":\"上の物語の最後の I have never been so glad. の意味として正しいのはどちらか。（ア）まったくうれしくなかった（イ）これまででいちばんうれしかった\",\"wrongAnswer\":\"（ア）まったくうれしくなかった\",\"trapExplanation\":\"never（一度も〜ない）という否定の語だけを見て、文全体を「うれしくない」と読んでしまう。優勝しなかったという内容も、この誤読を後押しする。\",\"correctAnswer\":\"（イ）これまででいちばんうれしかった\",\"correctExplanation\":\"have never been so 〜 は「これまで一度もこんなに〜だったことはない」という意味で、結果として「今がいちばん〜だ」という最上級の内容になる。同じ型に I have never seen such a beautiful sunset.（あんなに美しい夕日は見たことがない＝これまででいちばん美しい）がある。never＋so／such は最上級の言いかえだと覚えること。\"}]}",
"{\"id\":\"eigo_s408\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"説明文①：事実と意見を区別する\",\"description\":\"確かめられる事実と、書き手の考えである意見を読み分ける\",\"intro\":\"「日本の首都は東京だ」と「日本はもっと外国語を教えるべきだ」。前者はだれが調べても同じですが、後者は書き手の考えです。この二つを混ぜて読むと、筆者の主張がぼやけます。見分けるための目印を覚えます。\",\"order\":908,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"事実（fact）＝だれが調べても同じ結果になること。数字・年号・出来事。\",\"意見（opinion）＝書き手の考え。I think／should／must／best／important などが目印。\",\"should／must／had better は「〜すべきだ」という意見の合図。\",\"内容一致問題では、本文の事実と選択肢の意見をすりかえた選択肢が出る。\",\"筆者の主張を問われたら意見の文を、本文の内容を問われたら事実の文をさがす。\"],\"sections\":[{\"heading\":\"事実と意見の見分け方\",\"body\":\"説明文には、事実（fact）と意見（opinion）の2種類の文が混ざっている。設問はこの区別を前提に作られているので、読みながら分けておく必要がある。\\n\\n■ 事実の文（確かめられる）\\n・Japan has about 6,800 islands.（日本にはおよそ6,800の島がある）\\n・The Tokyo Skytree is 634 meters tall.（東京スカイツリーは634メートルだ）\\n・About 30 percent of the students walk to school.\\n\\n目印：数字／年号／固有名詞／調査結果（According to 〜）／過去の出来事\\n\\n■ 意見の文（人によって変わる）\\n・I think that we should use fewer plastic bags.\\n・Reading books is the best way to learn new words.\\n・It is important to talk with old people.\\n\\n目印：I think／I believe／In my opinion／should／must／had better／\\n　　　best／important／wonderful／difficult などの評価する語\\n\\n■ 見分ける質問\\n「これはだれが調べても同じ結果になるか？」\\nYES → 事実　NO → 意見\\n\\n★ ポイント：数字が入っていても意見のことがある。Three hours of study a day is enough.（1日3時間の勉強で十分だ）は「十分」という評価が入っているので意見である。\\n\\n⚠ 注意：It is said that 〜（〜と言われている）は、事実とも意見ともつかない表現。「そう言われているだけで、確かめられてはいない」というニュアンスなので、事実として断定しないこと。\"},{\"heading\":\"実際の英文で分ける\",\"body\":\"次の英文を、事実の文と意見の文に分ける。\\n\\nJapan is one of the countries that use a lot of paper. According to one report, each person in Japan uses about 200 kilograms of paper in a year. This is more than the average in the world. Making paper needs many trees and a lot of water. Of course, paper is useful, and we cannot live without it. However, I think we can use less paper if we try. For example, we should print on both sides of the paper at school. Small changes like this are important, and every student can start today.\\n\\n■ 事実の文\\n・Japan is one of the countries that use a lot of paper.\\n・According to one report, each person in Japan uses about 200 kilograms of paper in a year.\\n・This is more than the average in the world.\\n・Making paper needs many trees and a lot of water.\\n\\n■ 意見の文\\n・I think we can use less paper if we try.（I think）\\n・we should print on both sides of the paper at school.（should）\\n・Small changes like this are important（important）\\n\\n★ ポイント：この文章の主張は「意見の文」のほうにある。事実の部分は、その主張を納得させるための土台である。\\n\\n⚠ 注意：Of course, paper is useful, and we cannot live without it. は、いったん相手の言い分を認める文（ゆずり）である。この文だけを取り出して「筆者は紙をどんどん使うべきだと考えている」とするのは誤り。次の However を必ず見ること。\",\"figureId\":\"xf_eigo_s408\",\"mangaId\":\"eigo_s408_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、筆者の意見として最も適切なものを選びなさい。（ア）日本人1人あたり年間約200キログラムの紙を使う（イ）努力すれば紙の使用量を減らせる\",\"wrongAnswer\":\"（ア）日本人1人あたり年間約200キログラムの紙を使う\",\"trapExplanation\":\"具体的な数字が入っていて重要そうに見えるうえ、本文にそのまま書かれているので正しいと感じてしまう。しかし「筆者の意見は何か」と問われているので、事実の文は答えにならない。\",\"correctAnswer\":\"（イ）努力すれば紙の使用量を減らせる\",\"correctExplanation\":\"（ア）は According to one report で始まる調査結果、つまり事実である。（イ）は I think we can use less paper if we try. に対応する意見の文である。設問が「意見」を問うているのか「本文の内容」を問うているのかを読み分け、I think／should／important などの語のある文をさがす。\"},{\"question\":\"Of course, paper is useful, and we cannot live without it. の役割として正しいのはどちらか。（ア）筆者の結論（イ）反対の立場をいったん認める部分\",\"wrongAnswer\":\"（ア）筆者の結論\",\"trapExplanation\":\"Of course（もちろん）という強い語が付いているため、筆者がいちばん言いたいことのように見えてしまう。しかしこの語は「たしかにそのとおりだが」と前置きするための語である。\",\"correctAnswer\":\"（イ）反対の立場をいったん認める部分\",\"correctExplanation\":\"Of course／It is true that 〜／Certainly のあとには、必ず However／But／Still が続き、そのあとに筆者の本当の主張が来る。この文章でも次の文が However, I think we can use less paper … となっている。Of course を見たら「この次に But が来る」と予測して読むこと。\"}]}",
"{\"id\":\"eigo_s409\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"説明文②：比較・対比の読み取り\",\"description\":\"2つのものを比べる文章の型と、比較の英語表現を正確に読む\",\"intro\":\"説明文でよく出るのは、二つのものを並べて比べる型です。ところが「AはBより大きい」を読みまちがえ、逆に取ってしまう答案が後を絶ちません。than のうしろが比べる相手——この一点をここで確実にします。\",\"order\":909,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"対比の合図：On the other hand（一方で）／while（〜する一方）／in contrast（対照的に）／unlike（〜と違って）。\",\"比較級（-er／more）＋than、最上級（the -est／the most）を正確に読み取る。\",\"比べているものが「何と何か」を必ず確かめる。than の後ろが比べる相手。\",\"A is twice as large as B（AはBの2倍の広さ）など、倍数表現も出る。\",\"対比の文章は表にして整理する。左右2列に分けて書き出すと取りちがえない。\"],\"sections\":[{\"heading\":\"比較の英語を正確に読む\",\"body\":\"説明文では、2つのものを比べる文がよく出る。比較表現を読みちがえると、内容が正反対になる。\\n\\n■ 比較級（2つを比べる）\\n・Tom is taller than Ken.（トムはケンより背が高い）\\n・This book is more interesting than that one.\\n※ than の後ろが「比べる相手」。\\n\\n■ 最上級（3つ以上の中でいちばん）\\n・Tom is the tallest in his class.（クラスでいちばん背が高い）\\n・This is the most beautiful park in the city.\\n※ in ＋場所や集団、of ＋複数（of the three）。\\n\\n■ 同じくらい\\n・Tom is as tall as Ken.（トムはケンと同じくらい背が高い）\\n・Tom is not as tall as Ken.（トムはケンほど背が高くない＝ケンのほうが高い）\\n※ not as 〜 as は「〜ほどではない」。ここを取りちがえると意味が逆になる。\\n\\n■ 倍数\\n・A is twice as large as B.（AはBの2倍の広さだ）\\n・A is three times as long as B.（AはBの3倍の長さだ）\\n\\n■ 少ない・小さい\\n・less than 〜（〜より少ない）／fewer than 〜（数が〜より少ない）\\n・the least（いちばん少ない）／the fewest（数がいちばん少ない）\\n\\n★ ポイント：than や as の後ろに注目する。「だれと比べているか」を確定してから、どちらが上かを判断する。\\n\\n⚠ 注意：not as tall as は「同じくらい高くない」ではなく「〜ほど高くない」。つまり後ろのほうが高い。日本語に直すときに主語と比較相手が入れかわりやすいので、必ず「どちらが上か」を口に出して確かめる。\",\"mangaId\":\"eigo_s409_xm\"},{\"heading\":\"対比の文章を2列に整理する\",\"body\":\"次の英文を読む。動物の睡眠時間を比べた説明文である。\\n\\nHow long do animals sleep? Humans sleep about eight hours a day, but some animals sleep much longer. Koalas sleep about twenty hours. They eat only the leaves of one kind of tree, and those leaves do not give them much energy. Therefore, they must rest for a long time. Cats also sleep well; they sleep for about thirteen hours. On the other hand, large animals sleep less. Elephants sleep for only about four hours, and giraffes sleep for about two hours. Big animals need a lot of food, so they must spend many hours eating. Sleeping is also dangerous for animals that other animals hunt.\\n\\n■ 2列に整理する\\n【長く眠る】koala 20時間／cat 13時間\\n　理由：ユーカリの葉はエネルギーが少ないので休む必要がある\\n【あまり眠らない】elephant 4時間／giraffe 2時間\\n　理由①：体が大きく大量の食物が必要なので、食べる時間が長い\\n　理由②：ねらわれる動物にとって眠ることは危険\\n\\n境目にあるのが On the other hand（一方で）である。\\n\\n★ ポイント：対比の文章は必ず「合図の語」で2つに分かれる。その語の位置に大きく線を引き、左右（前後）を別々にまとめる。\\n\\n⚠ 注意：human（8時間）は基準として先に出されているだけで、どちらのグループでもない。基準になるものと、比べられるものを混同しないこと。\",\"figureId\":\"lf_eigoext11_409\"}],\"trapExamples\":[{\"question\":\"Ken is not as tall as Tom. の意味として正しいのはどちらか。（ア）ケンのほうが背が高い（イ）トムのほうが背が高い\",\"wrongAnswer\":\"（ア）ケンのほうが背が高い\",\"trapExplanation\":\"文頭の Ken が主語なので「ケンのほうが上」と感じてしまう。また as 〜 as を「同じくらい」と覚えているため、not が付いても「だいたい同じ」と読んでしまう。\",\"correctAnswer\":\"（イ）トムのほうが背が高い\",\"correctExplanation\":\"not as 〜 as … は「…ほど〜ではない」という意味なので、Ken is not as tall as Tom. は「ケンはトムほど背が高くない」＝トムのほうが高い。同じ内容を Tom is taller than Ken. とも書ける。比較の文は必ず「どちらが上か」を日本語で言い直して確かめること。\"},{\"question\":\"上の英文について、Why do koalas sleep for a long time? に答えなさい。\",\"wrongAnswer\":\"Because they are large animals.（大きな動物だから）\",\"trapExplanation\":\"本文に large animals についての説明があるため、そこから理由を引いてきてしまう。しかし large animals の段は On the other hand のあとにあり、コアラとは反対のグループの話である。\",\"correctAnswer\":\"Because they eat only the leaves of one kind of tree, and those leaves do not give them much energy.（1種類の木の葉しか食べず、その葉ではエネルギーが多く得られないから）\",\"correctExplanation\":\"コアラの理由は、コアラについて述べている部分（On the other hand より前）に書かれている。Therefore, they must rest for a long time. の直前の文がその理由である。対比の文章では、合図の語をはさんだ左右のどちらの情報かを必ず確かめてから答えを取ること。\"}]}",
"{\"id\":\"eigo_s410\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"説明文③：列挙・分類・定義を読む\",\"description\":\"「〜には3種類ある」「〜とは…である」という説明の型をつかむ\",\"intro\":\"「〜には三種類ある」と書かれていたら、そのあと必ず三つ並びます。一つ目、二つ目までは拾えても、三つ目を落とす答案が目立ちます。one・another・the other の使い分けもあわせて整理します。\",\"order\":910,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"定義の型：A is 〜／A is called B／A means 〜／A is a kind of 〜。知らない語の意味はここでわかる。\",\"分類の型：There are three kinds of 〜／One is …, another is …, the other is …。\",\"one／another／the other の使い分け：2つなら one と the other、3つ以上なら one／another／the others。\",\"列挙されたものの数を数えて、設問で問われたら全部書けるようにする。\",\"分類の説明文では、それぞれの特徴を1語ずつメモしておく。\"],\"sections\":[{\"heading\":\"定義と分類の決まった型\",\"body\":\"説明文には「これは何か」を述べる部分（定義）と「何種類あるか」を述べる部分（分類）がある。どちらも決まった型で書かれる。\\n\\n■ 定義の型\\n・A is 〜.（Aは〜である）\\n・A is called B.（AはBと呼ばれる）→ B の説明が A に書かれている\\n・A means 〜.（Aは〜を意味する）\\n・A, or B（AつまりB）※ この or は「または」ではなく「言いかえ」\\n・A is a kind of 〜.（Aは〜の一種だ）\\n\\n例）A tsunami is a very large wave caused by an earthquake.\\n　（津波とは、地震によって引き起こされるとても大きな波である）\\n\\n■ 分類の型\\n・There are three kinds of 〜.（〜には3種類ある）\\n・〜 can be divided into two groups.（〜は2つのグループに分けられる）\\n・One is …, another is …, and the other is …\\n\\n■ one／another／the other の使い分け\\n【2つのとき】one … the other …\\n　I have two dogs. One is white, and the other is black.\\n【3つのとき】one … another … the other …\\n【たくさんあるとき】some … others …\\n\\n★ ポイント：the other が出たら「残りは1つだけ」という意味である。the others なら「残り全部」。the が付くかどうかで意味が変わる。\\n\\n⚠ 注意：A, or B の or は「言いかえ」で使われることがある。The largest animal, or the blue whale, lives in the sea. は「最大の動物、つまりシロナガスクジラ」という意味で、2つのものを並べているのではない。\",\"mangaId\":\"eigo_s410_xm\"},{\"heading\":\"分類の説明文を整理する\",\"body\":\"次の英文を読み、分類を整理する。\\n\\nClouds can be divided into three groups by their height. The first group is the high clouds. They are found more than 6,000 meters above the ground, and they are made of very small pieces of ice. The second group is the middle clouds. They are found between 2,000 and 6,000 meters, and they often cover the whole sky. The last group is the low clouds. They are found below 2,000 meters, and they sometimes bring rain or snow. If you know these three groups, you can guess tomorrow's weather by looking at the sky.\\n\\n■ 整理する\\n①high clouds：6,000mより上／とても小さな氷のつぶでできている\\n②middle clouds：2,000m〜6,000m／空全体をおおうことが多い\\n③low clouds：2,000mより下／雨や雪をもたらすことがある\\n\\n型：Clouds can be divided into three groups.（分類の予告）\\n　→ The first group is 〜／The second group is 〜／The last group is 〜\\n\\n■ 数字に注意\\nmore than 6,000 meters（6,000mより上）\\nbetween 2,000 and 6,000 meters（2,000mから6,000mの間）\\nbelow 2,000 meters（2,000mより下）\\n\\n★ ポイント：more than／less than／between A and B／over／under は、範囲を表す語である。設問では「何メートル以上か」がそのまま問われる。\\n\\n⚠ 注意：日本語の「〜以上」は、その数をふくむ。英語の more than 6,000 は 6,000 をふくまない（6,000より多い）。細かい違いだが、算数と組み合わせた問題では差が出る。\",\"figureId\":\"xf_eigo_s410\"}],\"trapExamples\":[{\"question\":\"上の英文について、雲は何によって3つのグループに分けられるか。\",\"wrongAnswer\":\"雲の形によって\",\"trapExplanation\":\"「雲を分類する」と聞くと形（積乱雲・巻雲など）で分けるものだと知識で判断してしまい、本文を読まずに答えてしまう。本文には形についての記述はない。\",\"correctAnswer\":\"高さ（by their height）によって\",\"correctExplanation\":\"1文目に Clouds can be divided into three groups by their height. とはっきり書かれている。by 〜 は「〜によって・〜を基準にして」という意味で、分類の基準を示す。分類の説明文では、1文目に「何を基準に分けるか」が必ず書かれているので、そこに線を引く。自分の知識で答えないこと。\"},{\"question\":\"I have two cats. One is white, and ( another / the other ) is black. 正しいほうを選びなさい。\",\"wrongAnswer\":\"another\",\"trapExplanation\":\"「もう1匹」という日本語から another（もう1つの）を選んでしまう。しかし another は「たくさんある中のもう1つ」で、残りが1つに決まっているときには使えない。\",\"correctAnswer\":\"the other\",\"correctExplanation\":\"2つのうち1つを one と言ったら、残りは1つに決まる。決まっているものには the を付けるので the other になる。3つ以上あって残りがまだ複数あるときは another、残り全部をまとめて言うときは the others を使う。「残りが1つに決まっているか」で判断する。\"}]}",
"{\"id\":\"eigo_s411\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"説明文④：筆者の主張と結論を取り出す\",\"description\":\"文章全体の結論がどこにあるかを見つけ、主張を一文でまとめる\",\"intro\":\"文章全体で筆者が言いたいことは、たいてい最後の段落にあります。とくに In conclusion や We should で始まる文が目印です。問題提起から提案へ、という説明文の流れを知っておくと、探す場所が決まります。\",\"order\":911,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"結論は最終段落にある。とくに最後の2〜3文に注意する。\",\"結論の合図：In conclusion／In short／So／Therefore／This is why／We should。\",\"「問題提起 → 現状 → 原因 → 提案」という型が最も多い。提案の部分が主張。\",\"should／must／need to／It is important to 〜 が出たら、そこが筆者の言いたいこと。\",\"主張を一文でまとめる練習をしておくと、要旨・タイトル問題に強くなる。\"],\"sections\":[{\"heading\":\"説明文の全体構造\",\"body\":\"中学入試の説明文は、次の4段構成でできていることが多い。\\n\\n①問題提起：Do you know 〜? ／ Have you ever thought about 〜?\\n②現状・事実：数字や調査結果を出す\\n③原因・理由：Why does this happen? ／ There are two reasons.\\n④提案・結論：We should 〜 ／ In conclusion, 〜\\n\\nだから、設問「筆者の主張は何か」の答えはほぼ④にある。時間がないときは、最終段落だけ先に読んで主張をつかむという方法も使える。\\n\\n■ 結論の合図になる語\\n・In conclusion,（結論として）\\n・In short,（要するに）\\n・So,／Therefore,（だから）\\n・This is why 〜（こういうわけで〜）\\n・We should 〜／We need to 〜／It is important to 〜（〜すべきだ）\\n・What can we do?（私たちに何ができるか）※ この問いのあとが提案\\n\\n★ ポイント：What can we do? という問いかけが出てきたら、その後ろが提案（＝主張）である。設問「筆者は何をすべきだと言っているか」の答えはここから取る。\\n\\n⚠ 注意：最終段落に具体例が置かれることもある。For example で始まる文は、たとえ最後にあっても主張ではない。\"},{\"heading\":\"主張を一文にまとめる\",\"body\":\"次の英文を読み、主張を一文でまとめる。\\n\\nDo you know how much water we use every day? One person in Japan uses about 220 liters of water a day. That is more than a hundred large plastic bottles. Most of it is used for baths, toilets, and washing. Clean water does not come from nowhere. It is carried through long pipes and cleaned at a water plant, and this uses a lot of energy. What can we do? First, we can turn off the water while we brush our teeth. Second, we can use the water from the bath to wash clothes. These are small actions, but if we keep doing them, we can save a lot of water and energy. Saving water is not only for us but also for the people who will live after us.\\n\\n■ 構造\\n①問題提起：Do you know how much water we use every day?\\n②現状：1人1日約220リットル。おもに風呂・トイレ・洗濯\\n③理由：きれいな水は長い管で運ばれ浄水場で処理され、大量のエネルギーを使う\\n④提案：What can we do? → 歯みがき中に水を止める／風呂の水を洗濯に使う\\n⑤結論：小さな行動でも続ければ多くの水とエネルギーを節約できる。これは未来の人のためでもある\\n\\n■ 一文でまとめる\\n「水をつくるには多くのエネルギーがかかるので、私たちは日常の小さな工夫で節水を続けるべきだ。」\\n\\n★ ポイント：まとめの一文は「理由＋主張」の形にすると過不足がない。「〜なので、〜すべきだ」と書く。\\n\\n⚠ 注意：最後の文の not only for us but also for the people who will live after us（私たちのためだけでなく、これから後に生きる人々のためでもある）は、主張に「未来の人のため」という広がりを与えている部分である。要旨をまとめるときは入れなくてもよいが、内容一致問題ではここが選択肢になりやすい。\",\"figureId\":\"xf_eigo_s411\",\"mangaId\":\"eigo_s411_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、筆者の主張として最も適切なものを選びなさい。（ア）日本人1人が1日に使う水は約220リットルである（イ）日常の小さな工夫を続けて水とエネルギーを節約すべきだ\",\"wrongAnswer\":\"（ア）日本人1人が1日に使う水は約220リットルである\",\"trapExplanation\":\"数字が入っていて本文にそのまま書かれているので、正しい内容だと感じる。実際に内容としては正しいが、それは「現状を示す事実」であって「主張」ではない。設問が何を問うているかを読み落としている。\",\"correctAnswer\":\"（イ）日常の小さな工夫を続けて水とエネルギーを節約すべきだ\",\"correctExplanation\":\"What can we do? のあとに提案が並び、These are small actions, but if we keep doing them, we can save a lot of water and energy. で結論が述べられている。主張を問う設問では、should／can／What can we do? の後ろをさがす。事実として正しくても、主張でなければ答えにはならない。\"},{\"question\":\"上の英文について、Where is most of the water used? に答えなさい。\",\"wrongAnswer\":\"At a water plant.（浄水場で）\",\"trapExplanation\":\"本文に a water plant という語があるため、そこを答えにしてしまう。しかし浄水場は「水をきれいにする場所」であって、水が使われる場所ではない。設問の used（使われる）を読み落としている。\",\"correctAnswer\":\"For baths, toilets, and washing.（風呂・トイレ・洗濯に）\",\"correctExplanation\":\"Most of it is used for baths, toilets, and washing. という文が本文にある。it は water を指す。設問の疑問詞（Where／What／Why）と、本文のどの文が対応しているかを、キーワード（most／used）で結びつけて確かめること。同じ語が出てくる場所を全部見比べるのが確実である。\"}]}",
"{\"id\":\"eigo_s412\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"図表読解①：棒グラフつきの英文\",\"description\":\"棒グラフの高さと英語の表現（the most popular／second）を対応させて読む\",\"intro\":\"グラフつきの英文で、いきなり本文から読み始めていませんか。先に表題とたて軸・よこ軸・単位を確かめるほうが速く解けます。the most popular はいちばん高い棒、came second は二番目。表現と棒を対応させます。\",\"order\":912,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"図表つき読解では、英文を読む前にグラフの表題・たて軸・よこ軸・単位を確かめる。\",\"合計が問題文の人数と合うかを必ず検算する。合えば読み取りは正しい。\",\"the most popular＝いちばん高い棒、came second＝2番目、the least popular／only＝いちばん低い棒。\",\"順位を表す表現：first／second／third／the last。数を表す表現：twice as many as（2倍）。\",\"設問はグラフと英文の両方を見ないと解けないように作られている。片方だけで答えない。\"],\"sections\":[{\"heading\":\"グラフを先に読む\",\"body\":\"図表つき読解は、英文とグラフを行ったり来たりしながら解く。順番を決めておくと速い。\\n\\n■ 手順\\n①グラフの表題を読む（何について調べたものか）\\n②たて軸・よこ軸が何を表すか、単位は何かを確かめる\\n③いちばん高い所・低い所に印をつける\\n④それから英文を読み、英語の表現とグラフを結びつける\\n\\n■ グラフを説明する英語\\n・the most popular（いちばん人気がある）＝いちばん高い棒\\n・came second／was second（2番目だった）\\n・the least popular（いちばん人気がない）／only 〜（〜だけ）＝いちばん低い棒\\n・twice as many as 〜（〜の2倍）\\n・more than 〜（〜より多い）／less than 〜（〜より少ない）\\n・the same as 〜（〜と同じ）\\n\\n■ 検算のしかた\\nたとえば「30人に聞いた」と書いてあるなら、棒の値を全部足して30になるかを確かめる。合わなければ読みちがえている。\\n\\n★ ポイント：グラフの数値は英文に全部は書かれていない。英文にある数値だけを頼りにすると解けない設問がある。必ずグラフ自体からも読む。\\n\\n⚠ 注意：たて軸が「人数」なのか「パーセント」なのかを最初に確かめる。人数だと思ってパーセントを足すと100を超えて混乱する。\",\"mangaId\":\"eigo_s412_xm\"},{\"heading\":\"実際の図表つき英文\",\"body\":\"右の棒グラフを見ながら、次の英文を読む。\\n\\nMr. Tanaka asked his 30 students, \\\"What sport do you like the best?\\\" Soccer was the most popular. Eleven students chose it. Baseball came second with seven students, and basketball was third with six. Four students liked swimming, and only two students chose tennis. Mr. Tanaka was surprised because tennis was the most popular sport in his class last year. He thinks the World Cup on TV last summer changed the students' minds. He is going to ask the same question again next year.\\n\\n■ グラフと英文の対応\\nsoccer 11 ← the most popular／Eleven students chose it\\nbaseball 7 ← came second with seven students\\nbasketball 6 ← was third with six\\nswimming 4 ← Four students liked swimming\\ntennis 2 ← only two students chose tennis\\n\\n■ 検算\\n11＋7＋6＋4＋2＝30 → 質問した人数と一致する。読み取りは正しい。\\n\\n■ 設問になりやすい所\\n・How many students chose baseball?（7人）\\n・Which sport was the least popular?（tennis）\\n・Why was Mr. Tanaka surprised?（去年はテニスがいちばん人気だったから）\\n・How many more students chose soccer than baseball?（11−7＝4人多い）\\n\\n★ ポイント：How many more 〜 than …?（…より何人多いか）は引き算を求める設問。図表つき読解では計算を伴う設問が必ず1問は出る。\\n\\n⚠ 注意：Mr. Tanaka がおどろいた理由は、グラフではなく英文にしか書かれていない。グラフだけ見て答えを出そうとすると必ず落とす。\",\"figureId\":\"lf_eigoext11_412\"}],\"trapExamples\":[{\"question\":\"上の英文とグラフについて、How many students chose tennis? に答えなさい。\",\"wrongAnswer\":\"Eleven students.\",\"trapExplanation\":\"本文の Eleven students chose it. の chose という語だけを目印にして答えを探し、it が soccer を指していることを確かめずに答えてしまう。設問の tennis と本文の it を結びつけてしまった誤り。\",\"correctAnswer\":\"Two students.\",\"correctExplanation\":\"テニスについて述べているのは only two students chose tennis の部分である。グラフでも tennis の棒はいちばん低く、値は2になっている。同じ動詞（chose）が何度も使われるときは、その目的語が何かを必ず確かめること。グラフの値と照らし合わせれば確実である。\"},{\"question\":\"上の英文とグラフについて、Which sport was the most popular in Mr. Tanaka’s class last year? に答えなさい。\",\"wrongAnswer\":\"Soccer.\",\"trapExplanation\":\"グラフでいちばん高いのが soccer なので、そのまま答えてしまう。しかし設問には last year（去年）とある。グラフは今年の結果であって、去年の結果ではない。\",\"correctAnswer\":\"Tennis.\",\"correctExplanation\":\"本文に Mr. Tanaka was surprised because tennis was the most popular sport in his class last year. と書かれている。図表つき読解では「グラフはいつのものか」を必ず確かめること。設問に last year／ten years ago などの語があれば、答えはグラフではなく英文の中にある。\"}]}",
"{\"id\":\"eigo_s413\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"図表読解②：折れ線グラフつきの英文\",\"description\":\"増える・減る・いちばん高いを表す英語と、グラフの山や谷を対応させる\",\"intro\":\"「増えた」を表す英語は go up・rise・increase といくつもあり、「減った」も同じだけあります。折れ線の山と谷を、この語群と結びつけて読むのが図表読解です。変化のはげしさを表す語まで押さえておきます。\",\"order\":913,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"増加：go up／rise／increase／grow。減少：go down／fall／drop／decrease。\",\"最高点：the highest／reach（〜に達する）。最低点：the lowest。\",\"変化のはげしさ：quickly／slowly／little by little（少しずつ）／suddenly（急に）。\",\"折れ線の山と谷には必ず理由が書かれている。because／so を目印にさがす。\",\"よこ軸が「月」なのか「年」なのかを確かめる。単位を読みちがえると全部ずれる。\"],\"sections\":[{\"heading\":\"変化を表す英語\",\"body\":\"折れ線グラフつきの読解では、増減を表す動詞を知っているかどうかで差がつく。\\n\\n■ 増える\\ngo up／rise（rose-risen）／increase／grow\\n例）The number went up from 120 to 150.（120から150に増えた）\\n\\n■ 減る\\ngo down／fall（fell-fallen）／drop／decrease\\n例）It fell to only 90.（わずか90まで減った）\\n\\n■ 変わらない\\nstay the same／remain the same／do not change\\n\\n■ 最高・最低\\nthe highest（いちばん高い）／the lowest（いちばん低い）\\nreach 〜（〜に達する）：In July it reached 260.\\n\\n■ 前置詞の使い分け（重要）\\n・from A to B（AからBへ）… go up from 120 to 150\\n・to 〜（〜まで）… fell to 90（90まで下がった）\\n・by 〜（〜だけ）… increased by 30（30だけ増えた）\\n※ to は「到達した値」、by は「変化した量」。ここを取りちがえると数値が合わなくなる。\\n\\n★ ポイント：グラフの読解では、まず山（いちばん高い点）と谷（いちばん低い点）に印をつけ、その理由が書かれた文をさがす。設問はほぼそこから作られる。\\n\\n⚠ 注意：increased to 150 と increased by 150 はまったく別。to なら結果が150、by なら150増えたので結果は「もとの数＋150」になる。\"},{\"heading\":\"実際の折れ線グラフつき英文\",\"body\":\"次の英文を、グラフと見比べながら読む。\\n\\nThis graph shows the number of students who used our school library each month. In April, 120 students used it. The number went up little by little, and in July it reached 260. That was the highest number of the year. In August, however, it fell to only 90 because the summer vacation was long and few students came to school. In September, the number rose again to 180. Our librarian says that many students borrow books before tests. In fact, tests are held in July and in September.\\n\\n■ グラフとの対応\\n4月 120 ← In April, 120 students used it\\n5月 150／6月 210 ← went up little by little\\n7月 260 ← it reached 260／the highest number\\n8月 90 ← fell to only 90\\n9月 180 ← rose again to 180\\n\\n■ 山と谷の理由\\n山（7月260）：テストが7月にあるから多くの生徒が本を借りる\\n谷（8月90）：夏休みが長く、学校に来る生徒が少なかったから\\n\\n■ 設問になりやすい所\\n・Which month had the highest number?（July）\\n・Why did the number fall in August?（夏休みで学校に来る生徒が少なかったから）\\n・How many more students used the library in July than in April?（260−120＝140人）\\n\\n★ ポイント：few students（ほとんど生徒がいない）は否定の意味を持つ。a few students（何人かの生徒）とは意味がちがうので注意。\\n\\n⚠ 注意：In fact,（実際に）は前の文を補強する語。tests are held in July and in September が、7月と9月に利用が多い理由を裏づけている。「9月に増えた理由」を問われたらこの文を使う。\",\"figureId\":\"lf_eigoext11_413\",\"mangaId\":\"eigo_s413_xm\"}],\"trapExamples\":[{\"question\":\"上の英文とグラフについて、Why did the number of students fall in August? に答えなさい。\",\"wrongAnswer\":\"Because tests were held in August.（8月にテストがあったから）\",\"trapExplanation\":\"本文に tests are held in July and in September とあるのを読み飛ばし、「テスト＝図書館利用」という結びつきだけで8月にもテストがあったと考えてしまう。しかも「テストがあると増える」のだから、減った理由の説明にもなっていない。\",\"correctAnswer\":\"Because the summer vacation was long and few students came to school.（夏休みが長く、学校に来る生徒がほとんどいなかったから）\",\"correctExplanation\":\"8月について述べた文に because がそのまま書かれている。理由を問う設問では、まずその月・その出来事について述べた文をさがし、その中の because を見る。テストが行われるのは7月と9月であって8月ではない、という点も本文に明記されている。\"},{\"question\":\"The number increased ( to / by ) 30 and became 180. 正しいほうを選びなさい。\",\"wrongAnswer\":\"to\",\"trapExplanation\":\"「30に増えた」という日本語をあてはめて to を選んでしまう。しかし後半に became 180 とあるので、結果は180であって30ではない。to と by の使い分けを知らないと矛盾に気づけない。\",\"correctAnswer\":\"by\",\"correctExplanation\":\"by 〜 は「〜だけ（変化した量）」を表すので、increased by 30 は「30だけ増えた」＝もとが150で結果が180となり、became 180 と一致する。to 〜 は「〜まで（到達した値）」なので increased to 180 なら結果が180になる。グラフの読解ではこの2語の区別が計算の正誤を分ける。\"}]}",
"{\"id\":\"eigo_s414\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"図表読解③：円グラフと割合の表現\",\"description\":\"パーセントを人数に直す計算と、half／twice などの割合表現を読む\",\"intro\":\"円グラフの割合は、足すと必ず百パーセントになります。合わなければどこかで読みちがえています。しかも入試では「では何人か」と人数に直させる問題がよく出ます。half や twice といった割合の表現も確かめます。\",\"order\":914,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"円グラフの合計は必ず100パーセント。足して100にならなければ読みちがえている。\",\"percent を人数に直す：全体の人数×パーセント÷100。図表読解では必ず問われる。\",\"half（半分）／a quarter（4分の1）／one third（3分の1）／twice（2倍）を覚える。\",\"the largest group（いちばん大きい部分）／the smallest group（いちばん小さい部分）。\",\"A and B together make up 〜 percent（AとBを合わせて〜パーセント）という足し算の表現。\"],\"sections\":[{\"heading\":\"割合を表す英語\",\"body\":\"円グラフつきの読解では、割合の表現が読めることが前提になる。\\n\\n■ 分数・割合\\n・half of 〜（〜の半分）：Half of the students walk to school.\\n・a quarter of 〜（〜の4分の1）\\n・one third of 〜（〜の3分の1）／two thirds of 〜（3分の2）\\n・three quarters of 〜（4分の3）\\n※ 分子が2以上のときは分母に s を付ける（two thirds）。\\n\\n■ 倍数\\n・twice as many as 〜（〜の2倍の数）\\n・three times as many as 〜（〜の3倍の数）\\n\\n■ パーセント\\n・Forty-five percent of the students walk.（45パーセントが歩く）\\n※ percent は複数でも s を付けない。\\n・about 〜（およそ）／almost 〜（ほぼ）／more than 〜（〜より多い）／less than 〜（〜より少ない）\\n\\n■ 大きさの比較\\n・the largest group（いちばん大きい部分）／the smallest group\\n・A and B together make up 〜 percent（AとBを合わせて〜パーセント）\\n\\n■ パーセントを人数に直す\\n全体200人で15パーセントなら 200×15÷100＝30人。\\nこの計算は図表つき読解の定番なので、必ずできるようにしておく。\\n\\n★ ポイント：円グラフの数値を全部足して100になるか確かめる。合わなければ「その他（others）」の部分を見落としている。\\n\\n⚠ 注意：percent の前の数は英語のつづりで書かれることがある（forty-five percent）。数字の英語（thirteen と thirty、fifteen と fifty）を聞きまちがえ・読みまちがえないこと。\"},{\"heading\":\"実際の円グラフつき英文\",\"body\":\"次の英文を、円グラフと見比べながら読む。\\n\\nOur class asked 200 students, \\\"How do you come to school?\\\" The answers are shown in the graph. Forty-five percent of the students walk to school. This is the largest group. Thirty percent come by bicycle, and fifteen percent take a bus. Only ten percent come by train, and most of them live in other towns. Walking and riding a bicycle together make up seventy-five percent. Our teacher says this is good for our health. However, on rainy days, more students take a bus, so the buses in the morning become very crowded.\\n\\n■ グラフとの対応\\nwalk 45％（the largest group）／bicycle 30％／bus 15％／train 10％\\n合計 45＋30＋15＋10＝100 → 正しい\\n\\n■ 人数に直す\\n全体200人なので\\n・walk：200×45÷100＝90人\\n・bicycle：200×30÷100＝60人\\n・bus：200×15÷100＝30人\\n・train：200×10÷100＝20人\\n合計 90＋60＋30＋20＝200人 → 検算が合う\\n\\n■ 設問になりやすい所\\n・How many students come to school by train?（20人）\\n・What is the largest group?（walk）\\n・Why do more students take a bus on rainy days?（雨だと歩いたり自転車に乗ったりできないから）\\n\\n★ ポイント：Walking and riding a bicycle together make up seventy-five percent. のような「合わせて〜」の文は、必ず自分で足し算して確かめる（45＋30＝75）。\\n\\n⚠ 注意：most of them の them は train を使う10パーセントの生徒を指す。「生徒の大部分」ではなく「電車通学の生徒の大部分」である。この取りちがえは頻出。\",\"figureId\":\"lf_eigoext11_414\",\"mangaId\":\"eigo_s414_xm\"}],\"trapExamples\":[{\"question\":\"上の英文とグラフについて、How many students come to school by bus? に答えなさい。\",\"wrongAnswer\":\"Fifteen students.（15人）\",\"trapExplanation\":\"本文の fifteen percent take a bus という数字をそのまま人数として答えてしまう。パーセントと人数を区別していないための誤りで、図表つき読解でいちばん多い失点である。\",\"correctAnswer\":\"Thirty students.（30人）\",\"correctExplanation\":\"全体は200人なので、15パーセントは 200×15÷100＝30人である。設問が How many students（何人）と聞いているのか What percent（何パーセント）と聞いているのかを最初に確かめる。人数を聞かれたら必ず全体の人数を本文からさがして計算すること。\"},{\"question\":\"上の英文の most of them live in other towns. の them は何を指すか。\",\"wrongAnswer\":\"the 200 students（200人の生徒全員）\",\"trapExplanation\":\"文章全体が200人の調査についてなので、them も全員を指すと考えてしまう。しかしそれでは「生徒の大部分がほかの町に住んでいる」ことになり、45パーセントが歩いて通っているという内容と矛盾する。\",\"correctAnswer\":\"the students who come to school by train（電車で通学する10パーセントの生徒）\",\"correctExplanation\":\"them は直前の Only ten percent come by train を受けている。入れかえると「電車通学の生徒の大部分はほかの町に住んでいる」となり、電車を使う理由の説明として自然である。代名詞は直前の部分を指すのが原則であり、入れかえて意味が通るかを確かめれば防げる。\"}]}",
"{\"id\":\"eigo_s415\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"図表読解④：時刻表・料金表を読む\",\"description\":\"表つきの英文で、時間と料金の条件を整理して答えを出す\",\"intro\":\"時刻表の問題を頭の中だけで計算して、待ち時間を数え落とす——よくある失点です。乗車時間、歩く時間、待ち時間をすべて足す必要があります。料金表では大人と子ども、平日と週末といった条件の行も見落とせません。\",\"order\":915,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"時刻表の問題は、必ず時間軸を書いてから考える。頭の中だけで計算しない。\",\"「所要時間」をすべて足す（乗車時間＋歩く時間＋待ち時間）。\",\"料金表では「大人・子ども」「平日・週末」「団体割引」など条件の行を必ず確かめる。\",\"leave（出発する）／arrive（到着する）／take（時間がかかる）／It takes 〜 minutes to …。\",\"条件が2つ以上あるときは、条件を1つずつ○×で確かめて候補を消していく。\"],\"sections\":[{\"heading\":\"時間の英語と計算\",\"body\":\"時刻表つきの読解では、時間に関する英語を正確に読めることが必要である。\\n\\n■ 出発・到着\\n・leave 〜（〜を出発する）：The train leaves at 9:30.\\n・leave for 〜（〜へ向けて出発する）：He left for Tokyo.\\n・arrive at 〜（〜に到着する。せまい場所）／arrive in 〜（広い場所）\\n・get to 〜（〜に着く）\\n\\n■ かかる時間\\n・It takes twenty minutes to walk to the station.（駅まで歩いて20分かかる）\\n・The trip takes forty minutes.（その移動は40分かかる）\\n・How long does it take?（どのくらいかかりますか）\\n\\n■ 時刻の表し方\\n・at seven thirty（7時30分に）／at half past seven（同じ意味）\\n・a quarter to eight（8時15分前＝7時45分）／a quarter past eight（8時15分）\\n・in the morning／in the afternoon／in the evening／at night\\n\\n■ 計算の手順\\n①待ち合わせ（着かなければならない）時刻を書く\\n②かかる時間を全部足す\\n③引き算で「何時に出ればよいか」を出す\\n④時刻表の中から、それより前で最も遅い便を選ぶ\\n\\n★ ポイント：④の「それより前で最も遅い便」というのが答えになることが多い。早すぎる便を選ぶと「長く待つことになる」という条件に反する。\\n\\n⚠ 注意：a quarter to eight は「8時に向かってあと15分」＝7時45分。to は「〜前」、past は「〜過ぎ」。日本語と逆に感じるので、必ず声に出して確認する。\"},{\"heading\":\"実際の時刻表つき英文\",\"body\":\"次の英文を、時間軸の図と見比べながら読む。\\n\\nEmi and her friends are going to visit the science museum on Saturday. They will meet in front of the museum at eleven o'clock. Trains from their town leave at 8:30, at 9:30, and at 10:30. The trip takes forty minutes, and it takes ten more minutes to walk from the station to the museum. Emi wants to arrive a little early, but she does not want to wait for a long time. The museum opens at ten.\\n\\n■ 整理する\\n待ち合わせ：11:00（博物館の前）\\nかかる時間：電車40分＋徒歩10分＝50分\\n・8:30発 → 9:10 駅着 → 9:20 博物館着（1時間40分も早い。待ちすぎ）\\n・9:30発 → 10:10 駅着 → 10:20 博物館着（40分前。少し早めでちょうどよい）\\n・10:30発 → 11:10 駅着 → 11:20 博物館着（20分遅刻）\\n\\n答え：Emi は 9:30 の電車に乗るべきである。\\n\\n■ 条件を1つずつ確かめる\\n条件①11時までに着く → 8:30便○／9:30便○／10:30便×\\n条件②長く待ちたくない → 8:30便×（1時間40分待ち）／9:30便○\\n→ 両方○なのは 9:30 だけ。\\n\\n★ ポイント：条件が2つあるときは表を作り、○×で消していく。頭の中だけで考えると、片方の条件を忘れる。\\n\\n⚠ 注意：The museum opens at ten. という情報も条件の1つ。もし 9:20 に着いてしまうと博物館はまだ開いていない。この一文があるおかげで、8:30 の便がさらに不適切だとわかる。図表つき読解では、一見関係なさそうな1文が条件になっていることが多い。\",\"figureId\":\"lf_eigoext11_415\",\"mangaId\":\"eigo_s415_xm\"}],\"trapExamples\":[{\"question\":\"上の英文について、Which train should Emi take? に答えなさい。\",\"wrongAnswer\":\"The 10:30 train.\",\"trapExplanation\":\"「11時の待ち合わせだから、その少し前の10:30に出ればよい」と、電車の発車時刻と到着時刻を同じものとして考えてしまう。所要時間を足していないための誤り。\",\"correctAnswer\":\"The 9:30 train.\",\"correctExplanation\":\"電車40分＋徒歩10分で合計50分かかるので、10:30発では博物館に着くのは11:20になり、11:00の待ち合わせに遅れる。9:30発なら10:20に着き、少し早めで条件に合う。8:30発では9:20に着いてしまい、博物館が開く10:00より前で長く待つことになる。時刻表の問題は必ず「発車時刻＋所要時間＝到着時刻」を書き出すこと。\"},{\"question\":\"The train leaves at a quarter to eight. は何時何分か。\",\"wrongAnswer\":\"8時15分\",\"trapExplanation\":\"a quarter（4分の1＝15分）と eight（8時）だけを見て、「8時15分」としてしまう。to と past の区別を知らないと、15分前と15分過ぎが逆になる。\",\"correctAnswer\":\"7時45分\",\"correctExplanation\":\"a quarter to eight は「8時まであと15分」という意味なので7時45分。逆に a quarter past eight なら「8時を15分過ぎた」で8時15分になる。同じように half past nine は9時30分。to＝〜前、past＝〜過ぎ、と対で覚える。時刻表の問題ではこの1語で答えが変わる。\"}]}",
"{\"id\":\"eigo_s416\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話文①：電話の会話\",\"description\":\"電話特有の言い回しを覚え、だれがだれと話しているかを正確につかむ\",\"intro\":\"電話の会話文では、まず話しているのがだれとだれかを確定します。This is Ken speaking. のように、電話でしか使わない決まった言い方があるからです。取り次ぎや伝言の場面も同じ。定型を知れば一気に読みやすくなります。\",\"order\":916,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"電話では「私は〜です」を This is 〜 speaking. と言う（I am 〜 とは言わない）。\",\"「〜さんをお願いします」は May I speak to 〜?／Can I talk to 〜?\",\"「どちらさまですか」は Who’s calling, please? 「少々お待ちください」は Just a moment, please.\",\"「（本人が）私です」は Speaking. または This is he／she.\",\"「伝言を承りましょうか」は Can I take a message? 「伝言をお願いできますか」は Can I leave a message?\"],\"sections\":[{\"heading\":\"電話の決まり文句\",\"body\":\"電話の会話は、使われる表現がほぼ決まっている。丸ごと覚えてしまえば確実に得点できる。\\n\\n■ かける側\\n・Hello. This is Ken. May I speak to Mika, please?（もしもし、ケンです。ミカさんをお願いします）\\n・Can I leave a message?（伝言をお願いできますか）\\n・I'll call back later.（あとでかけ直します）\\n・Sorry, I have the wrong number.（すみません、番号をまちがえました）\\n\\n■ 受ける側\\n・Who's calling, please?（どちらさまですか）\\n・Just a moment, please. ／ Hold on, please.（少々お待ちください）\\n・Speaking.（私です）※本人が出たとき\\n・She's out now. ／ He isn't here right now.（今、外出しています）\\n・Can I take a message?（伝言を承りましょうか）\\n・Shall I tell her to call you back?（折り返し電話するよう伝えましょうか）\\n\\n★ ポイント：This is Ken. の This is は「こちらは〜です」の意味。電話では自分のことも This is 〜 と言う。I am Ken. とは言わないので、選択肢問題でねらわれる。\\n\\n⚠ 注意：Speaking. だけで「私です」を表す（本人が出たとき）。名のるときに I am Mika. と言うのは不自然で、This is Mika. が正しい（Who's calling? への答えも同じ）。\",\"mangaId\":\"eigo_s416_xm\"},{\"heading\":\"実際の電話の会話\",\"body\":\"次の会話を読む。\\n\\nMika's mother: Hello.\\nKen: Hello. This is Ken Sato. May I speak to Mika, please?\\nMika's mother: I'm sorry, Ken. She is at her piano lesson now. She will be back around six.\\nKen: I see. Can I leave a message?\\nMika's mother: Sure. Go ahead.\\nKen: We are going to meet at the station at nine tomorrow morning, but the trains will be late because of some work on the railway line. Could you tell her to come at nine thirty instead?\\nMika's mother: At nine thirty. All right, I'll tell her.\\nKen: Thank you very much. Goodbye.\\n\\n■ だれがだれと話しているか\\n電話をかけたのは Ken、出たのは Mika の母親。Mika 本人は不在。\\n\\n■ 内容の整理\\n・ミカは今ピアノのレッスン中で、6時ごろ帰る\\n・ケンの伝言：明日の待ち合わせを9時から9時30分に変更したい\\n・理由：線路の工事のため電車が遅れる\\n\\n■ 設問になりやすい所\\n・Why did Ken call Mika?（待ち合わせ時刻の変更を伝えるため）\\n・What time will they meet tomorrow?（9時30分）\\n・Where is Mika now?（ピアノのレッスン）\\n\\n★ ポイント：Could you tell her to come at nine thirty instead? の instead（そのかわりに）が変更の合図。9時ではなく9時30分になる。\\n\\n⚠ 注意：会話の中に3つの時刻（six／nine／nine thirty）が出てくる。それぞれ何の時刻かを区別する。six はミカが帰る時刻で、待ち合わせとは関係ない。\",\"figureId\":\"xf_eigo_s416\"}],\"trapExamples\":[{\"question\":\"上の会話について、What time are Ken and Mika going to meet tomorrow? に答えなさい。\",\"wrongAnswer\":\"At nine.（9時）\",\"trapExplanation\":\"会話の中に We are going to meet at the station at nine tomorrow morning という文がそのまま出てくるので、それを答えにしてしまう。しかしそのあとに instead（そのかわりに）を使った変更の依頼がある。\",\"correctAnswer\":\"At nine thirty.（9時30分）\",\"correctExplanation\":\"but 以下で「電車が遅れる」と述べ、Could you tell her to come at nine thirty instead? と時刻の変更を頼んでいる。会話文では「もともとの予定 → 変更後の予定」という流れが定番で、設問は必ず変更後を問う。instead／How about 〜?／Let’s make it 〜 は変更の合図なので印をつける。\"},{\"question\":\"電話で「（お電話代わりました）私です」と言うとき、正しいのはどちらか。\",\"wrongAnswer\":\"I am Mika.\",\"trapExplanation\":\"日本語の「私がミカです」をそのまま英語にして I am Mika. としてしまう。文法としてはまちがいではないが、電話の場面ではこの言い方をしない。\",\"correctAnswer\":\"Speaking.（または This is Mika.）\",\"correctExplanation\":\"電話では、自分を名のるときも This is 〜 を使う。本人が呼び出しに応じるときは Speaking. の一語で「私です」を表す。同じく「どちらさまですか」は Who is it? ではなく Who’s calling, please? を使う。電話特有の表現はそのまま暗記するのが確実である。\"}]}",
"{\"id\":\"eigo_s417\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話文②：買い物の会話\",\"description\":\"店員と客のやりとりの型を覚え、値段と個数の計算を確実にする\",\"intro\":\"買い物の会話では、店員と客のどちらのせりふかを取りちがえると、答えが全部ずれます。May I help you? は店員、I am looking for … は客です。値段と個数の計算も出るので、数字にも印をつけながら読みます。\",\"order\":917,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"店員の第一声は May I help you? ／ Can I help you?（いらっしゃいませ）。\",\"客の返事は Yes, please. I’m looking for 〜. ／ No, thank you. I’m just looking.\",\"値段：How much is it? ／ How much are they? 答えは It’s 1,200 yen.\",\"試着：May I try it on?（試着してもいいですか）／ It’s too big. Do you have a smaller one?\",\"会計：I’ll take it.（それをください）／ Here you are.（はいどうぞ）／ Here’s your change.（おつりです）\"],\"sections\":[{\"heading\":\"買い物の会話の型\",\"body\":\"買い物の会話は「入店 → さがす → 選ぶ → 試す → 買う → 支払い」という順に進む。それぞれの場面の表現を覚える。\\n\\n■ ①店員が声をかける\\nMay I help you? ／ Can I help you?（いらっしゃいませ・何かお探しですか）\\n→ 買う気があるなら Yes, please. ／ ないなら No, thank you. I'm just looking.\\n\\n■ ②さがしているものを言う\\nI'm looking for a T-shirt.（Tシャツをさがしています）\\nDo you have this in blue?（これの青はありますか）\\n\\n■ ③大きさ・色を選ぶ\\nIt's too big／small／expensive.（大きすぎる／小さすぎる／高すぎる）\\nDo you have a smaller one?（もっと小さいのはありますか）※ one＝同じ種類の別のもの\\n\\n■ ④試す\\nMay I try it on?（試着してもいいですか）\\nSure. The fitting room is over there.\\n\\n■ ⑤買う・支払う\\nI'll take it.（それをください）／ How much is it?（いくらですか）\\nHere you are.（はいどうぞ）／ Here's your change.（おつりです）\\nThat will be 1,800 yen.（1,800円になります）\\n\\n★ ポイント：How much is it?（単数）と How much are they?（複数）を使い分ける。答えも It's 〜 と They're 〜 で対応する。\\n\\n⚠ 注意：値段の答えに数字だけを書かないこと。1,200 yen のように単位を必ず付ける。また Here you are.（差し出すとき）と Here's your change.（おつりを渡すとき）は場面がちがう。\"},{\"heading\":\"実際の買い物の会話と計算\",\"body\":\"右の値段表を見ながら、次の会話を読む。\\n\\nClerk: May I help you?\\nEmi: Yes, please. I'm looking for a T-shirt for my brother.\\nClerk: How about this blue one? It's 1,200 yen.\\nEmi: It looks nice. Do you have a bigger one?\\nClerk: Yes. Here you are. This is a large size, and the price is the same.\\nEmi: Great. I'll take it. And I need two pairs of socks, too.\\nClerk: The socks are 300 yen a pair. So that will be 1,800 yen in all.\\nEmi: Here's 2,000 yen.\\nClerk: Thank you. Here's your change, 200 yen.\\n\\n■ 計算を確かめる\\nTシャツ 1,200円 ×1 ＝ 1,200円\\nくつ下 300円 ×2 ＝ 600円\\n合計 1,200＋600 ＝ 1,800円\\n2,000円出したので、おつりは 2,000−1,800 ＝ 200円\\n\\n■ 注意すべき表現\\n・a pair of socks（くつ下1足）／two pairs of socks（2足）※ socks は2枚で1足\\n・300 yen a pair（1足300円）※ a＝「〜につき」\\n・in all（全部で）／in total（合計で）\\n\\n★ ポイント：数量の表現（a pair of／two pairs of／a bottle of／a cup of）を見落とすと計算がずれる。個数を表す語には必ず○をつける。\\n\\n⚠ 注意：The price is the same.（値段は同じ）という一文があるので、大きいサイズにしても1,200円のままである。この一文がないと、大きいサイズは高いのではないかと迷うことになる。会話文の細かい一文が計算の条件になっている。\",\"figureId\":\"lf_eigoext11_417\",\"mangaId\":\"eigo_s417_xm\"}],\"trapExamples\":[{\"question\":\"上の会話について、How much did Emi pay in all? に答えなさい。\",\"wrongAnswer\":\"1,500 yen.\",\"trapExplanation\":\"くつ下を1足だけと考えて 1,200＋300＝1,500円としてしまう。two pairs of socks の two pairs（2足）を見落としたための誤り。数量の語は小さく目立たないので読み飛ばしやすい。\",\"correctAnswer\":\"1,800 yen.\",\"correctExplanation\":\"Tシャツ1,200円と、くつ下300円×2足＝600円で、合計1,800円。会話の中でも So that will be 1,800 yen in all. と確認されている。買い物の会話では、必ず「何を・いくつ」に○をつけてから計算し、会話の中に出てくる合計額と一致するか確かめること。\"},{\"question\":\"店員の May I help you? に対し、買う気はないが店内を見たいときの返事として正しいのはどれか。\",\"wrongAnswer\":\"No, you may not.\",\"trapExplanation\":\"May I 〜? は許可を求める文だと習っているので、断るときは No, you may not.（だめです）と答えてしまう。文法としては形が合っているが、実際の場面では非常に失礼な返事になる。\",\"correctAnswer\":\"No, thank you. I'm just looking.\",\"correctExplanation\":\"店での May I help you? は「いらっしゃいませ・何かお探しですか」という決まったあいさつで、許可を求めているわけではない。買う気がないときは No, thank you. I’m just looking.（けっこうです、見ているだけです）と答える。会話文では、文字どおりの意味ではなく「その場面での決まった返事」を選ぶ問題がよく出る。\"}]}",
"{\"id\":\"eigo_s418\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話文③：道案内\",\"description\":\"道順の表現を地図と対応させ、目的地を正しく特定する\",\"intro\":\"道案内の会話文には、たいてい地図がついています。曲がるたびに指でたどらず頭の中だけで解くと、右と左が入れかわってしまいます。Turn right や on your left を地図の上で動かしながら、目的地を確定させます。\",\"order\":918,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"道をたずねる：Could you tell me how to get to 〜? ／ Where is 〜? ／ How can I get to 〜?\",\"道順：Go straight（まっすぐ行く）／Turn right［left］at 〜（〜で右［左］に曲がる）。\",\"位置：on your right［left］（右手［左手］に）／next to 〜（〜のとなり）／across from 〜（〜の向かい）／between A and B。\",\"block（ブロック・区画）は交差点と交差点の間。two blocks＝2つ目の角まで。\",\"道案内の会話は必ず地図を書きながら読む。頭の中で回転させない。\"],\"sections\":[{\"heading\":\"道案内の表現\",\"body\":\"道案内の会話は、使う表現が限られている。地図を書きながら読むのが最も確実である。\\n\\n■ たずねる\\n・Excuse me. Could you tell me how to get to the post office?\\n・Where is the station? ／ How can I get to the museum?\\n・Is there a bank near here?\\n\\n■ 道順を説明する\\n・Go straight for two blocks.（2ブロックまっすぐ行く）\\n・Turn right at the second corner.（2つ目の角を右に曲がる）\\n・Turn left at the traffic light.（信号で左に曲がる）\\n・Go along this street.（この通り沿いに行く）\\n・Cross the street.（通りを渡る）\\n\\n■ 位置を言う\\n・It's on your right［left］.（右手［左手］にあります）\\n・It's next to the flower shop.（花屋のとなり）\\n・It's across from the park.（公園の向かい）\\n・It's between the bank and the library.（銀行と図書館の間）\\n・It's in front of the station.（駅の前）／behind the school（学校の裏）\\n・It's at the corner of First Street and Green Street.（〜通りの角）\\n\\n■ 距離・時間\\n・It takes about five minutes on foot.（歩いて約5分）\\n・It's about 300 meters from here.\\n\\n★ ポイント：block は「建物」ではなく「交差点から次の交差点までの区画」。two blocks は2つ目の交差点までという意味である。\\n\\n⚠ 注意：on your right（右手に）の your は聞き手（歩く人）から見た方向である。説明する人から見た方向ではない。\"},{\"heading\":\"実際の道案内の会話\",\"body\":\"右の地図を見ながら、次の会話を読む。\\n\\nTourist: Excuse me. Could you tell me how to get to the post office?\\nWoman: Sure. Go straight along this street for two blocks. You'll see a bank on the corner.\\nTourist: Two blocks. All right.\\nWoman: Turn right at the bank and walk for one more block. The post office is on your left, next to the flower shop.\\nTourist: I see. How long does it take?\\nWoman: About five minutes on foot. If you walk past the post office and turn right again, you'll find the library. But you don't need to go that far.\\nTourist: Thank you very much.\\nWoman: You're welcome.\\n\\n■ 地図に書きこむ\\n①駅（現在地）から2ブロックまっすぐ\\n②銀行の角で右に曲がる\\n③1ブロック進むと、左手に郵便局（花屋のとなり）\\n④郵便局を通り過ぎてさらに右に曲がると図書館\\n\\n■ 設問になりやすい所\\n・Where is the post office?（銀行の角を右に曲がって1ブロック、左手・花屋のとなり）\\n・How long does it take?（歩いて約5分）\\n・What is next to the post office?（the flower shop）\\n\\n★ ポイント：説明を聞いた人が Two blocks. All right. とくり返している。会話文では、聞き手のくり返しが大事な情報の目印になる。\\n\\n⚠ 注意：最後の If you walk past the post office 〜, you'll find the library. は「行きすぎた場合」の説明であって、目的地の道順ではない。But you don't need to go that far.（そこまで行く必要はない）という一文で、これが余分な情報だとわかる。\",\"figureId\":\"lf_eigoext11_418\"},{\"heading\":\"なぜ地図に書きこみ、なぜ最初の発言に戻るのか\",\"mangaId\":\"eigo_s418_manga\",\"body\":\"道案内の会話には Turn right・on your left のように向きの語が何度も出ます。向きは**歩く人から見たもの**なので、地図の上で進行方向が変わるたびに右と左の意味が変わります。頭の中で回転させると必ずどこかで入れかわるので、出発点から指でたどり、曲がるたびに印をつけます。block が「建物」ではなく「交差点から次の交差点までの区画」なのは、英語の block が町を道で区切ったひとつのかたまりを指す語だからです。two blocks は角を二つ通り過ぎた所です。\\n\\n目的地を答えるときに最初の発言に戻るのは、会話文では**最初の1〜2文に話題が書かれる**からです。あとから出る the library は「行きすぎた場合」の説明で、But you don't need to go that far. がそれを示しています。最後に出た語を答えにするのは典型的な誤りです。\\n\\n■ 確かめのしかた\\n①出発点と向きを確認し、Go straight for 〇 blocks で角を数え、Turn 〇 で向きを変え、on your 〇 で位置を決める。**曲がるたびに指でたどる**。\\n②block は**交差点の区画**。two blocks＝2つ目の角まで。\\n③「何を探しているか」は**最初の発言**（Could you tell me how to get to the post office?）に戻る。最後に出た建物を答えにしない。\\n④聞き手のくり返し（Two blocks. All right.）は大事な情報の目印。「〜する必要はない」と断られた情報は目的地の道順ではない。\\n\\n★ ここがポイント：向きは**歩く人から見たもの**なので、地図の上で指でたどる。block は**交差点の区画**。目的地は**最初の発言**にあり、最後に出た語で答えない。\"}],\"trapExamples\":[{\"question\":\"上の会話について、What is the tourist looking for? に答えなさい。\",\"wrongAnswer\":\"The library.（図書館）\",\"trapExplanation\":\"会話の最後に the library が出てくるので、それが目的地だと思ってしまう。しかし図書館は「通り過ぎたときに着く場所」として説明されているだけで、探している場所ではない。最後に出た語を答えにしてしまう典型的なミス。\",\"correctAnswer\":\"The post office.（郵便局）\",\"correctExplanation\":\"最初の発言に Could you tell me how to get to the post office? とある。会話文では、最初の1〜2文に「何が話題か」が必ず書かれている。あとから出てくる地名や建物は、道順の目印か、行きすぎたときの説明であることが多い。会話は最初の発言に戻って確かめること。\"},{\"question\":\"Go straight for two blocks. の two blocks の意味として正しいのはどちらか。（ア）建物2つ分（イ）交差点2つ分\",\"wrongAnswer\":\"（ア）建物2つ分\",\"trapExplanation\":\"block を「ブロック（かたまり・建物）」という日本語のカタカナ語で覚えているため、建物の数だと考えてしまう。日本語のブロックと英語の block は指すものがちがう。\",\"correctAnswer\":\"（イ）交差点2つ分\",\"correctExplanation\":\"英語の block は「交差点から次の交差点までの区画」を指す。two blocks なら交差点を2つ通り過ぎた所、つまり2つ目の角までまっすぐ進むことになる。地図問題では、この数だけ角を数えて印をつければ位置が確定する。日本語のカタカナ語と意味がずれる語（block／mansion／smart）に注意する。\"}]}",
"{\"id\":\"eigo_s419\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話文④：レストランの会話\",\"description\":\"注文のやりとりと、営業時間・予約などの条件を読み取る\",\"intro\":\"レストランの会話には、決まったやりとりの順序があります。注文を聞かれ、選び、追加をたずねられ、最後に会計です。For here or to go? のような、その場面にしか出ない表現も多いので、型ごと覚えてしまいます。\",\"order\":919,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"注文：Are you ready to order? ／ I’ll have the curry. ／ I’d like a hamburger.\",\"確認：Anything else?（ほかに何か）／ For here or to go?（店内か持ち帰りか）\",\"会計：Check, please. ／ The bill, please.（お会計をお願いします）\",\"営業時間の設問が多い。open at 〜／close at 〜／be closed on Mondays を正確に読む。\",\"「今は開いているか」「何時なら食べられるか」は、時間軸を書いてから答える。\"],\"sections\":[{\"heading\":\"レストランの決まり文句\",\"body\":\"レストランの会話も、場面ごとに表現が決まっている。\\n\\n■ 席につく\\n・How many people? ／ A table for three, please.（3名でお願いします）\\n・Do you have a reservation?（ご予約はありますか）\\n・We're full now. Could you wait for about ten minutes?\\n\\n■ 注文する\\n・Are you ready to order?（ご注文はお決まりですか）\\n・I'll have the spaghetti. ／ I'd like a hamburger and a salad.\\n・What do you recommend?（おすすめは何ですか）\\n・Anything to drink?（お飲み物は）／ Anything else?（ほかに何か）\\n・That's all, thank you.（以上です）\\n\\n■ 食事中・会計\\n・How is everything?（お味はいかがですか）\\n・Check, please. ／ The bill, please.（お会計をお願いします）\\n・Can I pay by card?（カードで払えますか）\\n\\n■ 持ち帰り\\n・For here or to go?（店内でお召し上がりですか、お持ち帰りですか）\\n・To go, please.\\n\\n★ ポイント：I'd like 〜 は I would like 〜 の短縮形で「〜がほしいのですが」というていねいな言い方。I want 〜 よりも礼儀正しい。注文の場面では I'd like を使う。\\n\\n⚠ 注意：I'll have 〜 の have は「食べる」の意味。I'll have the curry. は「カレーにします」であって「カレーを持っています」ではない。have＝「食べる・飲む」の用法は会話文頻出。\"},{\"heading\":\"営業時間を読み取る\",\"body\":\"右の時間軸の図を見ながら、次の会話を読む。\\n\\nMan: Excuse me. Are you open now? It's three o'clock.\\nWaiter: I'm sorry, sir. We're closed between two and five. We open again at five for dinner.\\nMan: I see. What time do you close at night?\\nWaiter: At nine. The last order is at eight thirty.\\nMan: All right. Can I make a reservation for six thirty tonight? There will be four of us.\\nWaiter: Certainly. May I have your name and phone number?\\nMan: My name is Brown. My number is 090-1234-5678.\\nWaiter: Thank you, Mr. Brown. We'll see you at six thirty.\\n\\n■ 時間を整理する\\nランチ：11:00〜14:00（本文からは「2時に閉まる」ことがわかる）\\n休み：14:00〜17:00\\nディナー：17:00〜21:00（ラストオーダー20:30）\\n予約：今夜6時30分、4名、Brown さん\\n\\n■ 設問になりやすい所\\n・Why can't the man eat now?（14時から17時まで店が閉まっているから）\\n・What time does the restaurant close at night?（21時）\\n・How many people will come?（4人）\\n\\n★ ポイント：There will be four of us.（私たちは4人になります）は人数を伝える表現。four of us で「私たちのうち4人」ではなく「私たち4人」を表す。\\n\\n⚠ 注意：The last order is at eight thirty. は「注文できる最後の時刻」であって閉店時刻ではない。閉店は9時。似た2つの時刻が出てきたら、それぞれ何の時刻かを書き分ける。\",\"figureId\":\"lf_eigoext11_419\",\"mangaId\":\"eigo_s419_xm\"}],\"trapExamples\":[{\"question\":\"上の会話について、What time does the restaurant close at night? に答えなさい。\",\"wrongAnswer\":\"At eight thirty.（8時30分）\",\"trapExplanation\":\"The last order is at eight thirty. の時刻を閉店時刻だと考えてしまう。会話の中に9時と8時30分の2つの時刻が近い場所に出てくるため、混同しやすい。\",\"correctAnswer\":\"At nine.（9時）\",\"correctExplanation\":\"What time do you close at night? という問いに At nine. と答えている。8時30分はラストオーダー（last order）の時刻であって閉店時刻ではない。時刻が複数出てくる会話文では、それぞれの時刻の横に「開店」「閉店」「ラストオーダー」「予約」と書き入れてから設問に取りかかること。\"},{\"question\":\"ウェイターの Are you ready to order? に対する返事として自然なのはどちらか。（ア）Yes, I am ready.（イ）Yes. I’ll have the curry, please.\",\"wrongAnswer\":\"（ア）Yes, I am ready.\",\"trapExplanation\":\"Are you 〜? の疑問文なので Yes, I am. と答えるのが文法どおりだと考えてしまう。しかし会話文では、文法上正しくても場面に合わない返事は正解にならない。\",\"correctAnswer\":\"（イ）Yes. I’ll have the curry, please.\",\"correctExplanation\":\"Are you ready to order? は「ご注文はお決まりですか」という決まり文句なので、答えるときは注文の内容まで言うのが自然である。まだ決まっていなければ Just a moment, please.（もう少し待ってください）と答える。会話文の空所補充では、「文法的に正しいか」だけでなく「その場面で会話が続くか」を必ず確かめること。\"}]}",
"{\"id\":\"eigo_s420\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話文⑤：空所に入る発言を選ぶ\",\"description\":\"前後のやりとりから、空所に入る一文を論理的に決める\",\"intro\":\"空所に入る発言を選ぶ問題で、前のせりふだけを見て決めると必ず外します。手がかりは、空所のうしろにもあるからです。返事が Yes なら空所は疑問文、Sure. なら依頼か提案。後ろから決める解き方を身につけます。\",\"order\":920,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"空所補充は「前の発言」と「後ろの発言」の両方を見る。片方だけ見ると必ずまちがえる。\",\"空所の後ろが Yes／No なら、空所には疑問文が入る。\",\"空所の後ろが Sure.／Of course.／All right. なら、空所には依頼や提案が入る。\",\"空所の後ろが理由（Because 〜）なら、空所には Why 〜? が入る。\",\"選んだ文を実際に入れて、前後を通して声に出して読み、自然かどうか確かめる。\"],\"sections\":[{\"heading\":\"空所の前後から型を決める\",\"body\":\"会話文の空所補充は、当てずっぽうではなく手がかりから論理的に決められる。\\n\\n■ 後ろの返事から空所の型を決める\\n・後ろが Yes, I do.／No, I don't. → 空所は Do you 〜? の疑問文\\n・後ろが Yes, please.／No, thank you. → 空所は Would you like 〜?／Shall I 〜? の申し出\\n・後ろが Sure.／Of course.／All right. → 空所は Can you 〜?／Could you 〜? の依頼\\n・後ろが Because 〜. → 空所は Why 〜?\\n・後ろが 時刻・場所・人 → 空所は What time／Where／Who の疑問文\\n・後ろが That's a good idea. → 空所は Let's 〜／How about 〜? の提案\\n\\n■ 前の発言から空所の型を決める\\n・前が I have a headache. → 空所は That's too bad.（お気の毒に）\\n・前が I passed the test! → 空所は Congratulations!（おめでとう）\\n・前が Thank you very much. → 空所は You're welcome.\\n・前が I'm sorry I'm late. → 空所は That's all right.（気にしないで）\\n\\n★ ポイント：空所の後ろの1語（Sure／Because／Yes）を見るだけで、選択肢を2つくらいに減らせる。まずそこを見る。\\n\\n⚠ 注意：疑問文の形だけで選ばないこと。Do you 〜? と Are you 〜? はどちらも Yes／No で答えるので、後ろの返事が Yes, I do. なら Do you 〜?、Yes, I am. なら Are you 〜? と、答えの動詞まで見て決める。\"},{\"heading\":\"実際の空所補充問題\",\"body\":\"次の会話の空所①②③に入る文を、下のア〜オから選ぶ。\\n\\nKen: Hi, Lucy. You look tired. （　①　）\\nLucy: I couldn't sleep well last night. My little brother had a fever, and my mother took care of him all night.\\nKen: That's too bad. Is he all right now?\\nLucy: Yes, he is much better this morning. Thank you.\\nKen: （　②　）\\nLucy: Yes, I do. I have a lot of science homework, and there is a test tomorrow, but I couldn't study at all yesterday.\\nKen: （　③　）\\nLucy: Really? That would be a great help. Thank you, Ken.\\n\\nア Do you have any homework today?\\nイ What's wrong?\\nウ Shall I help you study for the test?\\nエ I'm fine, thank you.\\nオ Where did you go last night?\\n\\n■ 解き方\\n①後ろの返事は I couldn't sleep well last night.（理由の説明）。前は You look tired.（疲れているようだね）。→ 具合をたずねる イ What's wrong?（どうしたの）が入る。\\n②後ろの返事は Yes, I do. → 空所は Do you 〜? の疑問文。選択肢で Do you で始まるのは ア。しかも後ろで「明日理科のテストがある」と続くので自然。\\n③後ろの返事は That would be a great help.（それはとても助かる）→ 空所は申し出の文。ウ Shall I help you study for the test? が入る。\\n\\nエは How are you? のように調子をたずねられたときの返事なので、この位置には入らない（①は Ken の発言で、Ken は相手の様子をたずねる側）。オは「昨夜どこへ行ったか」で、話の内容と合わない。\\n\\n★ ポイント：Yes, I do. の do が決め手。Are you 〜? なら Yes, I am. になるので、do と am のどちらかを見れば疑問文の形が決まる。\\n\\n⚠ 注意：選び終わったら、必ず空所に入れて最初から読み直すこと。1か所だけ見て決めると、残りの選択肢が入らなくなることがある。\",\"figureId\":\"xf_eigo_s420\",\"mangaId\":\"eigo_s420_xm\"}],\"trapExamples\":[{\"question\":\"上の会話の空所①に入る文として、イ What’s wrong? のかわりにエ I’m fine, thank you. を選ぶとどうなるか。\",\"wrongAnswer\":\"エ I’m fine, thank you. でも自然につながる\",\"trapExplanation\":\"You look tired.（疲れているようだね）と言われたら「大丈夫だよ」と答えるのが自然だと考えてしまう。しかし空所①を話しているのは Ken であって Lucy ではない。だれの発言かを取りちがえたための誤り。\",\"correctAnswer\":\"ケンが自分の調子を答えることになり、話がつながらない\",\"correctExplanation\":\"空所①は Ken の発言の中にある。ケンはルーシーの様子を見て You look tired. と言ったのだから、続くのは相手を気づかう言葉である。I’m fine, thank you. は自分の調子を答える文なので、この位置には入らない。空所補充では、まず「この空所はだれの発言か」を確かめること。\"},{\"question\":\"空所の後ろの返事が Sure. のとき、空所に入る文として適切なのはどれか。（ア）What time is it?（イ）Can you help me?\",\"wrongAnswer\":\"（ア）What time is it?\",\"trapExplanation\":\"疑問文ならどれでも入ると考えてしまう。しかし What time is it? に対する返事は It’s three o’clock. のような時刻であって、Sure. ではない。\",\"correctAnswer\":\"（イ）Can you help me?\",\"correctExplanation\":\"Sure.（もちろん）は依頼や許可を求める文への承諾の返事である。Can you 〜?／Could you 〜?／May I 〜? に対して使われる。疑問詞（What／Where／When／Why／How）で始まる疑問文には、Yes／No や Sure では答えられず、具体的な内容で答える。返事の形から、疑問詞疑問文か Yes/No 疑問文かを見分けること。\"}]}",
"{\"id\":\"eigo_s421\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未知語①：語の作りから意味を推測する\",\"description\":\"接頭辞・接尾辞・複合語から、知らない単語のおおよその意味を出す\",\"intro\":\"知らない単語 unhappy に出会っても、happy が分かれば意味は見当がつきます。un- が反対の意味を作るからです。英語の単語は部品の組み合わせでできていて、その部品を知っていれば初めて見る語も推測できます。\",\"order\":921,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"un-／in-／im-／dis- は「反対・否定」を作る（happy → unhappy）。\",\"re- は「もう一度」（write → rewrite）、pre- は「前に」（preview）。\",\"-er／-or は「〜する人」、-ist は「〜の専門家」、-tion／-ment は「〜すること」（名詞）。\",\"-ful は「〜に満ちた」、-less は「〜がない」。careful と careless は正反対。\",\"複合語は2つの語に分ける（waterfall＝water＋fall＝滝、newspaper＝news＋paper）。\"],\"sections\":[{\"heading\":\"意味を反対にする接頭辞\",\"body\":\"知らない単語でも、語の頭や終わりについている部分から意味を推測できることが多い。\\n\\n■ 否定・反対を作る接頭辞\\n・un- … happy→unhappy（不幸な）／kind→unkind／usual→unusual（ふつうでない）／able→unable\\n・in-／im- … possible→impossible（不可能な）／correct→incorrect／polite→impolite\\n・dis- … like→dislike（きらう）／appear→disappear（消える）／agree→disagree\\n・non- … stop→nonstop（止まらない）\\n\\n■ その他の接頭辞\\n・re- …「もう一度」：write→rewrite（書き直す）／use→reuse（再利用する）／cycle→recycle\\n・pre- …「前に」：view→preview（下見）\\n・over- …「〜しすぎ」：sleep→oversleep（寝すごす）／eat→overeat\\n\\n例）The old man disappeared into the forest. の disappear を知らなくても、appear（現れる）＋dis（反対）＝「消える」と推測できる。\\n\\n★ ポイント：im- は b／m／p の前で使われる（impossible／impolite）。ir- は r の前（irregular＝不規則な）。音の並びで決まっているだけなので、意味はすべて「否定」である。\\n\\n⚠ 注意：すべての un- が否定とはかぎらない。understand（理解する）は under＋stand であって「立たない」ではない。推測した意味を必ず文にあてはめて確かめること。\",\"figureId\":\"xf_eigo_s421\"},{\"heading\":\"品詞を作る接尾辞と複合語\",\"body\":\"語の終わりの部分（接尾辞）は、その語の品詞を教えてくれる。品詞がわかると、文の中での役割がわかる。\\n\\n■ 人を表す\\n・-er／-or …「〜する人」：teach→teacher／play→player／act→actor／visit→visitor\\n・-ist …「〜の専門家」：science→scientist／art→artist／piano→pianist\\n・-ian … music→musician\\n\\n■ 名詞を作る\\n・-tion／-sion …「〜すること」：act→action／invent→invention／decide→decision\\n・-ment … move→movement／develop→development\\n・-ness … kind→kindness（親切）／happy→happiness\\n・-th … long→length／grow→growth\\n\\n■ 形容詞を作る\\n・-ful …「〜に満ちた」：care→careful（注意深い）／use→useful／beauty→beautiful\\n・-less …「〜がない」：care→careless（不注意な）／use→useless／home→homeless\\n・-y … rain→rainy／sun→sunny／cloud→cloudy\\n・-ous … danger→dangerous／fame→famous\\n\\n■ 複合語（2語をくっつけた語）\\nwaterfall＝water＋fall（滝）／newspaper＝news＋paper（新聞）／\\ngrandfather＝grand＋father（祖父）／earthquake＝earth＋quake（地震）／\\nsunflower＝sun＋flower（ひまわり）／firefighter＝fire＋fighter（消防士）\\n\\n★ ポイント：-ful と -less は正反対。careful（注意深い）と careless（不注意な）は入試で必ず区別を問われる。\\n\\n⚠ 注意：接尾辞から品詞がわかると、その語を飛ばしても文の構造がつかめる。The invention changed the world. の invention を知らなくても、-tion なので名詞＝主語だとわかり、「何かが世界を変えた」と読める。\",\"mangaId\":\"eigo_s421_xm\"}],\"trapExamples\":[{\"question\":\"careless の意味として正しいのはどちらか。（ア）注意深い（イ）不注意な\",\"wrongAnswer\":\"（ア）注意深い\",\"trapExplanation\":\"care（注意）という語が入っているので、「注意する」というよい意味だと考えてしまう。-less という接尾辞を見落とすと、意味が正反対になる。\",\"correctAnswer\":\"（イ）不注意な\",\"correctExplanation\":\"-less は「〜がない」という意味の接尾辞なので、careless は「注意がない＝不注意な」となる。反対に -ful は「〜に満ちた」なので careful は「注意深い」。同じように useful（役に立つ）と useless（役に立たない）、homeless（家のない）も同じ仕組みである。語の終わりまで必ず読むこと。\"},{\"question\":\"His answer was incorrect. の incorrect の意味を推測しなさい。\",\"wrongAnswer\":\"完全な・とても正しい\",\"trapExplanation\":\"correct（正しい）に何かが付いて意味が強まったと考え、「とても正しい」と読んでしまう。接頭辞 in- を「中に」という前置詞 in と同じだと考えるのもよくある誤り。\",\"correctAnswer\":\"まちがっている（正しくない）\",\"correctExplanation\":\"in-／im-／un-／dis- はすべて「否定・反対」を作る接頭辞なので、incorrect は correct の反対で「正しくない」となる。impossible（不可能な）＝possible の反対、unhappy（不幸な）＝happy の反対も同じ仕組み。前置詞の in と、接頭辞の in- は別のものである。\"}]}",
"{\"id\":\"eigo_s422\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未知語②：文脈の手がかりから意味を出す\",\"description\":\"言いかえ・対比・例示・原因結果という4つの手がかりを使う\",\"intro\":\"語の作りから見当がつかないときは、まわりの文が助けになります。言いかえ・対比・例示・原因結果——この四つの手がかりのどれかで、筆者はたいてい意味を補ってくれています。その手がかりの見つけ方を練習します。\",\"order\":922,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"手がかり①言いかえ：A is called B／A, or B／A means 〜／that is（すなわち）。\",\"手がかり②対比：but／however／unlike／on the other hand の反対側に、反対の意味の語がある。\",\"手がかり③例示：such as／for example のあとに具体例が並び、そこから上位の意味がわかる。\",\"手がかり④原因結果：so／because でつながれた文から、その語の意味を逆算する。\",\"推測した意味は必ず本文に入れ直して、文全体が自然になるか確かめる。\"],\"sections\":[{\"heading\":\"4つの手がかり\",\"body\":\"知らない単語の意味は、その語の前後に必ず手がかりがある。入試の英文は、そう作られている。\\n\\n■ ①言いかえ（＝の関係）\\n・A is called B.：This long sleep is called hibernation.（hibernation＝冬眠）\\n・A, or B：a tsunami, or a huge wave（tsunami＝巨大な波）\\n・A means B：Recycle means using things again.\\n・that is（すなわち）：the largest animal, that is, the blue whale\\n\\n■ ②対比（反対の関係）\\n・Some students are diligent, but others are lazy.\\n　→ lazy がわからなくても、diligent（勤勉な）の反対だとわかる。\\n・Unlike his brother, he is very quiet.（兄と違って、彼はとても静かだ）\\n　→ 兄はにぎやかだとわかる。\\n\\n■ ③例示（下に例が並ぶ）\\n・He plays several instruments, such as the piano, the violin, and the flute.\\n　→ instrument＝楽器だとわかる。\\n\\n■ ④原因・結果\\n・It was so humid that my shirt got wet.（とても humid なのでシャツがぬれた）\\n　→ humid＝しめっぽい、とわかる。\\n\\n★ ポイント：手がかりは知らない語の「すぐ前の文」か「すぐ後ろの文」にある。3文以上離れていることはまずない。\\n\\n⚠ 注意：推測した意味は必ず本文に入れて読み直す。「なんとなくこんな感じ」で先へ進むと、その語がキーワードだった場合に文章全体を誤読する。\"},{\"heading\":\"実際の英文で推測する\",\"body\":\"次の英文には、多くの小学生が知らない語が3つ入っている。手がかりを使って意味を出す。\\n\\nIn many cities, the air is not clean. Cars and factories produce gases that are bad for our health. This is called air pollution. In some places, the sky looks brown, and people cannot see the mountains near their town. Unlike cities, small villages in the mountains usually have fresh air. However, even in those villages, the number of cars is increasing. Some cities have started to use electric buses. They are quiet and they do not produce harmful gases. If more cities use them, the air will become cleaner.\\n\\n■ ①air pollution\\n直前の文：Cars and factories produce gases that are bad for our health.\\nThis is called air pollution. → 「これは air pollution と呼ばれる」\\n→ air pollution＝大気汚染\\n\\n■ ②fresh\\nUnlike cities, small villages in the mountains usually have fresh air.\\n→ Unlike（〜と違って）があるので、都市の空気（not clean）の反対。\\n→ fresh＝新鮮な・きれいな\\n\\n■ ③harmful\\nThey are quiet and they do not produce harmful gases.\\n→ 前の部分で gases that are bad for our health（健康に悪い気体）とあった。\\n→ harmful＝有害な（harm＋-ful＝害に満ちた）\\n\\n★ ポイント：③は接尾辞（-ful）と文脈の両方から確かめられた。手がかりは1つより2つのほうが確実である。\\n\\n⚠ 注意：increasing（増えている）を「減っている」と読みちがえると、However（しかし）の意味が通らなくなる。「山あいの村は空気がきれい。しかし、その村でも車の数が増えている」という流れになって初めて However が生きる。つなぎ語と語の意味は、たがいに手がかりになる。\",\"figureId\":\"xf_eigo_s422\",\"mangaId\":\"eigo_s422_xm\"}],\"trapExamples\":[{\"question\":\"上の英文の harmful gases の harmful の意味を推測しなさい。\",\"wrongAnswer\":\"役に立つ・有益な\",\"trapExplanation\":\"-ful を「〜に満ちた」＝よい意味だと思いこみ、useful（役に立つ）や beautiful（美しい）からの連想で「有益な」としてしまう。-ful 自体はよい意味も悪い意味も作る。\",\"correctAnswer\":\"有害な（健康に悪い）\",\"correctExplanation\":\"harm は「害」という意味なので、harmful は「害に満ちた＝有害な」となる。文脈からも確かめられる。電気バスの説明で they do not produce harmful gases（有害な気体を出さない）とあり、前半に gases that are bad for our health（健康に悪い気体）と書かれている。-ful は「〜に満ちた」であって「よい」ではない、と正確に覚える。\"},{\"question\":\"Unlike his brother, Ken is very quiet. からわかることとして正しいのはどちらか。（ア）ケンの兄も静かだ（イ）ケンの兄はにぎやかだ\",\"wrongAnswer\":\"（ア）ケンの兄も静かだ\",\"trapExplanation\":\"Unlike の like（〜のような）だけを見て「兄のようにケンも静かだ」と読んでしまう。un- という否定の接頭辞を見落としたための正反対の読みちがえ。\",\"correctAnswer\":\"（イ）ケンの兄はにぎやかだ\",\"correctExplanation\":\"Unlike 〜 は「〜と違って」という意味なので、「兄とは違ってケンはとても静かだ」となり、兄は静かではないとわかる。like（〜のように）と unlike（〜と違って）は正反対なので、頭の un- を必ず見ること。この対比の表現は、知らない語の意味を推測する強い手がかりにもなる。\"}]}",
"{\"id\":\"eigo_s423\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未知語③：品詞を見抜いて読み飛ばす\",\"description\":\"意味がわからなくても、品詞と役割がわかれば文の骨組みは読める\",\"intro\":\"意味が分からなくても、その語が名詞か動詞かさえ分かれば読み進められます。名詞なら「何か」、動詞なら「何かをする」と置きかえればよいからです。a や the のうしろは名詞、といった形の手がかりを使います。\",\"order\":923,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"未知語が名詞なら「何か」、動詞なら「何かをする」、形容詞なら「どんなか」と置きかえて読み進める。\",\"品詞の見分け方：a／the の後ろは名詞、主語の直後は動詞、名詞の直前は形容詞、-ly で終われば副詞。\",\"未知語が形容詞や副詞なら、飛ばしても文の骨組みは変わらない。\",\"未知語が動詞のときだけは飛ばせない。前後の文から動作の向きを推測する。\",\"設問で問われていない未知語には時間をかけない。\"],\"sections\":[{\"heading\":\"品詞を見抜く方法\",\"body\":\"未知語に出会ったとき、意味の前にまず品詞を判断する。品詞がわかれば、その語が文の中でどんな仕事をしているかがわかり、飛ばしてよいかどうかも決まる。\\n\\n■ 名詞の目印\\n・a／an／the／my／this のすぐ後ろ：a glacier ／ the drought\\n・複数の s が付いている：glaciers\\n・前置詞のすぐ後ろ：in the valley\\n\\n■ 動詞の目印\\n・主語のすぐ後ろ：The river flooded the town.\\n・-s／-ed／-ing が付いている\\n・助動詞（can／will／must）のすぐ後ろ\\n\\n■ 形容詞の目印\\n・名詞のすぐ前：a huge building\\n・be動詞のすぐ後ろ：The building was huge.\\n\\n■ 副詞の目印\\n・-ly で終わる：quickly／carefully／suddenly\\n・動詞や文全体を説明する位置にある\\n\\n■ 置きかえて読む\\nThe scientist examined the strange object carefully.\\nexamined と object を知らないとしても\\n「その科学者は（何かをした）その奇妙な（何か）を注意深く」\\n→ 「科学者が奇妙な何かを注意深く調べた」と、おおよその意味が取れる。\\n\\n★ ポイント：形容詞と副詞は「くわしくする語」なので、飛ばしても文の骨組みは残る。まず飛ばしてよい品詞かどうかを判断する。\\n\\n⚠ 注意：動詞だけは飛ばせない。動詞が抜けると「何が起きたか」がわからなくなる。動詞が未知語のときは、前後の文の内容から動作を推測する。\"},{\"heading\":\"飛ばしてよい語・いけない語\",\"body\":\"実際の英文で、どの語を飛ばしてよいか判断する。\\n\\nLong ago, a terrible drought hit the village. For three months, no rain fell. The rice fields became dry and hard, and the plants withered. The villagers walked for hours to a distant river and carried water in heavy buckets. An old woman named Sato taught the children to save every drop. Thanks to her advice, the village survived that difficult summer.\\n\\n■ 未知語になりやすい語と、その扱い\\n・drought（干ばつ）… a のあとなので名詞。「何か悪いもの」。ただし次の文に For three months, no rain fell.（3か月間、雨が降らなかった）とあるので、意味が確定できる。飛ばさず確かめる価値がある。\\n・withered（しおれた）… plants のあとの動詞。前に became dry and hard（かわいて固くなった）とあるので、「植物がだめになった」と推測できる。動詞なので飛ばさない。\\n・distant（遠い）… river の前なので形容詞。飛ばしても「川へ歩いて水を運んだ」という骨組みは変わらない。\\n・survived（生きのびた）… village のあとの動詞。Thanks to her advice（彼女の助言のおかげで）とあるので、よい結果だとわかる。動詞なので飛ばさない。\\n\\n■ まとめ\\n飛ばしてよい：distant（形容詞）\\n飛ばせない：drought・withered・survived（名詞・動詞で内容の中心）\\n\\n★ ポイント：Thanks to 〜（〜のおかげで）はよい結果を導く語。Because of 〜 は良し悪しどちらにも使う。この違いも意味推測の手がかりになる。\\n\\n⚠ 注意：飛ばすかどうかは「その語が設問に関係するか」でも決まる。設問に survive という語が出ていたら、必ず意味を確定させる。まず設問を先読みしておくのは、このためでもある。\",\"figureId\":\"xf_eigo_s423\",\"mangaId\":\"eigo_s423_xm\"}],\"trapExamples\":[{\"question\":\"上の英文の a terrible drought hit the village. の drought の品詞は何か。\",\"wrongAnswer\":\"動詞\",\"trapExplanation\":\"すぐ後ろに hit（打つ）という動詞があるので、その前の drought も動作を表す語のように感じてしまう。品詞は意味ではなく、前後の語の並びで決まる。\",\"correctAnswer\":\"名詞\",\"correctExplanation\":\"a terrible drought の並びを見る。a（冠詞）＋terrible（形容詞）＋drought となっているので、drought は名詞である。この文の骨組みは「a terrible drought（主語）＋hit（動詞）＋the village（目的語）」で、「ひどい干ばつが村をおそった」となる。冠詞のあとは必ず名詞、という並びの規則で判断できる。\"},{\"question\":\"未知語がある文の読み方として正しいのはどちらか。（ア）辞書のように意味を1つに決めるまで先へ進まない（イ）品詞を見抜き、飛ばしてよい語かどうかを判断して読み進める\",\"wrongAnswer\":\"（ア）辞書のように意味を1つに決めるまで先へ進まない\",\"trapExplanation\":\"「わからないままにしてはいけない」というふだんの勉強の姿勢を、試験中にもそのまま持ちこんでしまう。ふだんの学習では正しい態度だが、限られた時間で解く試験では致命的になる。\",\"correctAnswer\":\"（イ）品詞を見抜き、飛ばしてよい語かどうかを判断して読み進める\",\"correctExplanation\":\"入試の長文には、受験生が知らない語が必ず数個ふくまれている。それでも解けるように作られているので、形容詞や副詞なら飛ばし、名詞や動詞なら前後の手がかりからおおよその意味を出して先へ進む。意味を確定させるのは、設問で問われている語だけでよい。ふだんの学習と試験本番で、読み方を切りかえること。\"}]}",
"{\"id\":\"eigo_s424\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"内容一致問題の解き方\",\"description\":\"選択肢と本文を1語ずつ照合し、言いすぎ・すりかえの誤答を見抜く\",\"intro\":\"内容一致問題の選択肢は、本文の語をそのまま使ってはくれません。言いかえてあるので、見た目の一致だけで選ぶと引っかかります。しかも誤答の作り方には型があります。言いすぎ、すりかえ——その型を先に知っておきます。\",\"order\":924,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"選択肢は本文の語をそのまま使わず、言いかえてあることが多い。意味で照合する。\",\"誤答の型は4つ：①言いすぎ（all／always／never）②すりかえ（人・時・場所を入れかえ）③本文にない内容④一部だけ正しい。\",\"選択肢の中の数字・人名・時を表す語には必ず○をつけ、本文と1つずつ照合する。\",\"「本文に書かれていないこと」は、たとえ常識的に正しくても誤答である。\",\"正しい選択肢は、必ず本文の「どの1文」に対応しているかを言えなければならない。\"],\"sections\":[{\"heading\":\"誤答の4つの型\",\"body\":\"内容一致問題（本文の内容に合うものを選べ）は、誤答の作り方が決まっている。型を知っていれば、消去法で確実にしぼれる。\\n\\n■ ①言いすぎ（強すぎる語）\\n本文：Some students walk to school.（一部の生徒は歩いて通う）\\n誤答：All students walk to school.（全員が歩く）\\n目印：all／every／always／never／only／the best／must\\n→ 強い語が入っている選択肢は、まず疑う。\\n\\n■ ②すりかえ（人・時・場所を入れかえる）\\n本文：Ken’s sister went to Canada last year.\\n誤答：Ken went to Canada last year.（行ったのは妹）\\n誤答：Ken’s sister went to Canada this year.（時がちがう）\\n→ 選択肢の主語・時・場所に○をつけて照合する。\\n\\n■ ③本文にない内容\\n常識的に正しくても、本文に書かれていなければ誤答。\\n本文に「猫は13時間眠る」とあるとき、「猫は夜行性である」は本文にない。\\n\\n■ ④一部だけ正しい\\n選択肢の前半は本文どおりだが、後半がちがう。長い選択肢ほどこの型が多い。\\n→ 選択肢は最後まで読む。前半だけ見て○をつけない。\\n\\n★ ポイント：まず選択肢を読み、①の強い語に○、②の人名・時・場所に○をつける。そのうえで本文を照合すると、目のつけどころが定まる。\\n\\n⚠ 注意：「本文に合わないものを選べ」という設問もある。設問文の「合うもの」「合わないもの」を必ず確認する。ここを読みちがえると全部落とす。\"},{\"heading\":\"実際に照合する\",\"body\":\"次の英文と選択肢で、照合のしかたを確かめる。\\n\\nSea turtles lay their eggs on the beach at night. A mother turtle digs a hole in the sand and lays about a hundred eggs. Then she goes back to the sea. About two months later, the baby turtles come out and move toward the sea. However, only a few of them become adults. Many are eaten by birds and fish. In some countries, people protect the beaches where turtles lay eggs. Thanks to this work, the number of sea turtles has increased in those areas.\\n\\n選択肢\\nア A mother turtle stays with her eggs until they come out.\\nイ All the baby turtles reach the sea and become adults.\\nウ Sea turtles lay their eggs on the beach during the night.\\nエ The number of sea turtles is decreasing everywhere in the world.\\n\\n■ 照合する\\nア：本文は Then she goes back to the sea.（産んだあと海に戻る）→ 卵のそばにいるのは誤り。②すりかえ・③本文にない。\\nイ：本文は only a few of them become adults（成体になるのはごく一部）→ All が言いすぎ。①言いすぎ。\\nウ：本文は lay their eggs on the beach at night → at night と during the night は同じ意味。○\\nエ：本文は the number of sea turtles has increased in those areas（それらの地域では増えている）→ decreasing everywhere は逆かつ言いすぎ。①言いすぎ。\\n\\n答え：ウ\\n\\n★ ポイント：正解のウは、本文の at night が during the night に言いかえられている。正解の選択肢ほど、本文とは違う語で書かれている。語が同じかどうかではなく、意味が同じかどうかで判断する。\\n\\n⚠ 注意：a few（少しはある）と only a few（ごくわずかしかない）と few（ほとんどない）は意味の強さがちがう。本文の only a few を「けっこういる」と読むと、イを選んでしまう。\",\"figureId\":\"xf_eigo_s424\"},{\"heading\":\"なぜ正解は言いかえてあり、なぜ誤答は4つの型で作られるのか\",\"mangaId\":\"eigo_s424_manga\",\"body\":\"内容一致問題で正解が本文と同じ語で書かれていたら、本文を探すだけで解けてしまい、**意味を理解しているか**を測れません。だから出題者は正解を言いかえ（at night→during the night）、誤答には本文と同じ語をわざと残します。見た目の一致で選ぶと、誤答に引きよせられます。判断は「語が同じか」ではなく「意味が同じか」です。\\n\\n誤答の作り方が4つの型に決まっているのは、本文の一部を**少しだけ変える**のがもっとも作りやすく、もっとも引っかかるからです。some→all と強める（言いすぎ）、妹→ケンと主語を入れかえる（すりかえ）、常識で正しそうなことを足す（本文にない）、前半だけ本文どおりにする（一部だけ正しい）。型を知っていれば、選択肢の強い語・人名・時・場所に○をつけるだけで、見るべき所が定まります。\\n\\n■ 確かめのしかた\\n①設問文の「合うもの」「合わないもの」に線を引く。ここを読みちがえると全部落とす。\\n②選択肢の**強い語**（all・every・always・never・only・must）と**人名・時・場所・数字**に○をつける。\\n③本文の該当する1文と突き合わせる。正解は**本文のどの1文に対応するか**を言えるか。語がちがっても意味が同じなら○。\\n④選択肢は**最後まで読む**。a few（少しある）・only a few（ごくわずか）・few（ほとんどない）の強さのちがいを本文で確かめる。\\n\\n★ ここがポイント：正解は**意味を測るために言いかえてある**ので、語ではなく意味で照合する。誤答は**言いすぎ・すりかえ・本文にない・一部だけ**の4型で、強い語と人名・時・場所に○をつけて見破る。\"}],\"trapExamples\":[{\"question\":\"上の英文について、選択肢イ All the baby turtles reach the sea and become adults. が誤りである理由を答えなさい。\",\"wrongAnswer\":\"本文に「子ガメが海に向かう」と書かれているので、この選択肢は正しい\",\"trapExplanation\":\"本文の the baby turtles come out and move toward the sea という部分だけを見て、選択肢の前半と一致するので正しいと判断してしまう。選択肢の後半（become adults）と、All という語を確かめていない。\",\"correctAnswer\":\"本文には only a few of them become adults（成体になるのはごく一部だけ）とあり、All（すべて）ではないから。\",\"correctExplanation\":\"all／every／always／never／only などの強い語が入った選択肢は、まず疑ってかかる。本文の However, only a few of them become adults. と真っ向から矛盾している。選択肢は最後まで読み、前半が正しくても後半で切られていないかを必ず確かめること。\"},{\"question\":\"「本文の内容に合わないものを1つ選びなさい」という設問で、本文と一致する選択肢を選んでしまうのはなぜか。また、どう防ぐか。\",\"wrongAnswer\":\"合っている選択肢を選ぶのが正解だから、まちがいではない\",\"trapExplanation\":\"内容一致問題は「合うものを選ぶ」ものだと思いこんでいるため、設問文の「合わないもの」を読み飛ばしてしまう。読解の力ではなく、設問文の読み方の問題である。\",\"correctAnswer\":\"設問文の「合わない」を読み落としているため。設問文の「合う」「合わない」に必ず印をつけ、選択肢ごとに○×を書きこんでから、求められているほうを選ぶ。\",\"correctExplanation\":\"設問文には「合うもの」「合わないもの」「合うものをすべて」など、いくつかの型がある。まず設問文の該当部分に線を引く。そして選択肢ア〜エそれぞれに○（本文と一致）か×（一致しない）を書きこむ。最後に、設問が求めているのが○のほうか×のほうかを確認して答える。この手順を守れば、確実に防げる失点である。\"}]}",
"{\"id\":\"eigo_s425\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"要旨把握とタイトル選び\",\"description\":\"文章全体を一文にまとめ、ふさわしい題名を選ぶ\",\"intro\":\"タイトル選びでよく起こる失敗は、ある一つの段落だけの内容を選んでしまうことです。逆に、本文に書かれていない大きすぎる一般論も誤りです。せますぎず広すぎない一文をどう決めるか、その基準をはっきりさせます。\",\"order\":925,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"要旨＝文章全体をおおう内容。段落ごとのメモをつないで一文にする。\",\"タイトルは「せますぎず・広すぎず」。1つの段落だけの内容も、本文にない一般論も誤り。\",\"結論の合図（In conclusion／In short／We should）の文が、要旨にいちばん近い。\",\"具体例・数字・体験談は要旨に入れない。\",\"選択肢のタイトルは、本文の全段落に対応しているかを確かめる。\"],\"sections\":[{\"heading\":\"要旨のまとめ方\",\"body\":\"要旨（main idea）とは、文章全体をおおう「言いたいこと」である。ある段落だけの内容や、具体例は要旨にならない。\\n\\n■ まとめる手順\\n①各段落の一言メモを作る（10〜20字）\\n②メモを見て、全部に共通する内容をさがす\\n③結論の段落（最終段落）の文を確かめる\\n④「〜なので、〜だ」の形で一文にする\\n\\n例）4段落の説明文\\n①ペットボトルは世界中で使われている\\n②多くが海に流れこむ\\n③海の生き物が食べてしまう危険がある\\n④私たちにできることが3つある\\n→ 要旨「ペットボトルのごみが海の生き物に害をあたえているので、私たちは減らす努力をすべきだ」\\n\\n■ 要旨に入れないもの\\n・具体例（For example のあと）\\n・数字（約200キログラム、45パーセント など）\\n・体験談（When I was 〜）\\n・ゆずりの部分（Of course, 〜）\\n\\n★ ポイント：要旨は「理由＋主張」の形にすると、必要な要素がそろう。主張だけだと理由が抜け、事実だけだと主張が抜ける。\\n\\n⚠ 注意：物語文の場合、要旨は「教訓・主人公が学んだこと」になる。最後の1〜2文（Since that day, 〜／I learned that 〜）に必ず書かれている。説明文とは探す場所がちがう。\"},{\"heading\":\"タイトルの選び方\",\"body\":\"タイトル（題名）を選ぶ問題は、要旨問題の変形である。「せますぎず・広すぎず」が判断の基準になる。\\n\\n■ 誤答の型\\n①せますぎる：1つの段落・1つの例しか表していない\\n　本文が「犬の役割いろいろ」なのに、タイトルが「盲導犬の訓練」\\n②広すぎる：本文の範囲を超えている\\n　本文が「犬の役割いろいろ」なのに、タイトルが「動物と人間」\\n③本文にない：内容と関係のない題名\\n④一部だけ正しい：前半は合っているが後半が本文にない\\n\\n■ 判断のしかた\\n選んだタイトルを見て、「この題名の文章なら、この段落は入るか」を各段落について確かめる。\\n・全部の段落が入る → 正解\\n・入らない段落がある → せますぎる\\n・本文にない内容まで入ってしまう → 広すぎる\\n\\n■ 例で確かめる\\n本文：①犬は人の役に立つ ②盲導犬 ③警察犬 ④病院を訪れる犬 ⑤犬は仲間だ\\nア The Training of Guide Dogs（盲導犬の訓練）→ ②だけ。せますぎる。\\nイ Dogs That Help People（人を助ける犬）→ ①〜⑤すべてに対応。○\\nウ Animals in Our Life（生活の中の動物）→ 犬以外もふくむ。広すぎる。\\nエ How to Keep a Dog（犬の飼い方）→ 本文にない。\\n\\n答え：イ\\n\\n★ ポイント：英語のタイトルは名詞のかたまりで書かれることが多い（Dogs That Help People／The Story of a Small Village）。文の形（Dogs help people.）にはならないのがふつうである。\\n\\n⚠ 注意：タイトルにいちばん多く出てくる語（キーワード）が入っているとはかぎらないが、入っていることが多い。文章全体で何度もくり返される語を数えておくと、選択肢をしぼる助けになる。\",\"figureId\":\"xf_eigo_s425\",\"mangaId\":\"eigo_s425_xm\"}],\"trapExamples\":[{\"question\":\"「犬は人の役に立つ／盲導犬／警察犬／病院を訪れる犬／犬は仲間だ」という5段落の文章のタイトルとして、ウ Animals in Our Life が誤りである理由を答えなさい。\",\"wrongAnswer\":\"犬は動物なので、このタイトルでも正しい\",\"trapExplanation\":\"本文の内容がすべてこのタイトルにあてはまるので、正しいと感じてしまう。しかしタイトルは「本文の範囲とぴったり合う」必要があり、本文より広い題名は誤りになる。\",\"correctAnswer\":\"本文は犬だけを扱っているのに、このタイトルは犬以外の動物もふくむ広さになっているから（広すぎる）。\",\"correctExplanation\":\"タイトルは本文の範囲とちょうど同じ広さでなければならない。Animals in Our Life という題名なら、猫や馬の話が入っていてもおかしくないが、本文には犬の話しかない。逆に The Training of Guide Dogs は②の段落だけしか表せないのでせますぎる。「全段落が入り、しかも余分な内容が入らない」ものを選ぶ。\"},{\"question\":\"説明文の要旨をまとめるとき、「日本人1人が1日に約220リットルの水を使う」という内容を入れるべきか。\",\"wrongAnswer\":\"入れるべき。本文にある具体的な数字なので重要である。\",\"trapExplanation\":\"数字は本文にはっきり書かれていて確かな情報なので、要旨にも入れるべきだと考えてしまう。しかし数字は主張を支えるための材料であって、主張そのものではない。\",\"correctAnswer\":\"入れない。数字は主張を支える具体的な材料（支持文）だから。\",\"correctExplanation\":\"要旨は文章全体をおおう「言いたいこと」なので、具体例・数字・体験談は入れない。この文章なら「水をつくるには多くのエネルギーがかかるので、日常の小さな工夫で節水を続けるべきだ」が要旨になる。数字は、内容の細部を問う設問（How much water does one person use?）で使うものだと役割を分けて考える。\"}]}",
"{\"id\":\"eigo_s426\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"和文英訳①：日本語を「英語の型」に置きかえる\",\"description\":\"日本語をそのまま訳さず、だれが・どうする・何を、の順に組み立て直す手順を身につける\",\"intro\":\"和文英訳でいきなり日本語の頭から訳し始めると、たいてい途中で行きづまります。日本語は動詞が最後、英語は動詞が二番目という順番のちがいがあるからです。訳すのではなく、英語の型に置きかえる手順を身につけます。\",\"order\":926,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"和文英訳は「訳す」のではなく「英語の型に置きかえる」作業である。\",\"英語の語順は必ず ①だれが ②どうする ③何を ④どこで・いつ の順。\",\"日本語は動詞が最後、英語は動詞が二番目。まず動詞をさがす。\",\"「〜です」につられて be動詞と一般動詞を重ねない（I am like ~ は誤り）。\",\"文の後ろの修飾語は「場所→時」の順に置く。\"],\"sections\":[{\"heading\":\"三つのステップ\",\"body\":\"和文英訳の問題は、日本語を頭から順に英語に置きかえようとすると必ず失敗する。日本語と英語では語を並べる順序がまったくちがうからである。次の三つのステップで組み立てる。\\n\\n■ ステップ1　骨組みをさがす\\n日本語の文を読み、「だれが」「どうする（どんなだ）」「何を」の三つに印をつける。日本語では動詞（述語）が文の最後にあるので、まず文末を見る。\\n例）きのう、弟が公園でサッカーをした。\\n　　だれが＝弟　／　どうする＝した（play）　／　何を＝サッカーを\\n\\n■ ステップ2　英語の順に並べる\\n骨組みを ①だれが → ②どうする → ③何を の順に置く。\\n　My brother played soccer\\n\\n■ ステップ3　残りをつける\\n「どこで」「いつ」は文の後ろに、場所→時の順で置く。\\n　My brother played soccer in the park yesterday.\\n\\n★ ポイント：日本語では「きのう、公園で」が前にあるが、英語では後ろに回る。しかも「公園で（場所）→きのう（時）」の順である。日本語の順のまま I yesterday played ... と書くのがもっとも多い失点である。\",\"figureId\":\"lf_eigoext12_426\"},{\"heading\":\"動詞は一つの文に一つ\",\"mangaId\":\"eigo_s426_manga\",\"body\":\"日本語の「〜です」は、英語では be動詞になる場合と、ならない場合がある。ここを取りちがえると、一つの文に動詞が二つ入ってしまう。\\n\\n■ be動詞になる「です」\\n「A＝B」「Aは〜という状態だ」を表すとき。\\n例）私は中学生です。→ I am a junior high school student.\\n　　この本はおもしろいです。→ This book is interesting.\\n\\n■ be動詞にならない「です」\\n文末が「〜します」「〜が好きです」「〜を持っています」のように動作や心の働きを表すとき。この場合は一般動詞だけを使い、be動詞は入れない。\\n例）私は英語が好きです。→ I like English.（I am like English. は誤り）\\n　　姉はピアノをひきます。→ My sister plays the piano.\\n\\n■ 見分け方\\n「です」の直前の語を英語にしたとき、名詞か形容詞（中学生・おもしろい・いそがしい）になるなら be動詞を使う。「好き」「持っている」「ひく」のように、「好む」「持つ」「ひく」という動作や気持ちを表す動詞で言える語なら、その一般動詞だけを使う。「英語が好きです」は「私＝英語」という意味ではないので be動詞は要らず、like English となる。\\n\\n⚠ 注意：一つの文に動詞が二つ並んだら、その時点でほぼ誤りである。書き終えたら「動詞は一つか」を必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"「私はきのう公園へ行きました」を英語にしなさい。\",\"wrongAnswer\":\"I yesterday went to the park.\",\"trapExplanation\":\"日本語の「きのう」が文の前のほうにあるので、そのままの順で英語に置きかえてしまう。日本語は時を表す語を先に言い、英語は後ろに回すという差に気づいていない。\",\"correctAnswer\":\"I went to the park yesterday.\",\"correctExplanation\":\"まず骨組み I went（だれが・どうする）を作り、そのあとに「どこで→いつ」の順で to the park yesterday を続ける。英語では主語と動詞の間に yesterday のような時を表す語を割りこませない。\"},{\"question\":\"「私は music が好きです」の下線部にならい、「私は理科が好きです」を英語にしなさい。\",\"wrongAnswer\":\"I am like science.\",\"trapExplanation\":\"日本語の文末「です」を機械的に be動詞に置きかえ、さらに「好き」に like を当てたため、一つの文に動詞が二つ入ってしまった。「〜です」＝ be動詞という思いこみが原因。\",\"correctAnswer\":\"I like science.\",\"correctExplanation\":\"「好きです」は「好む」という動作を表すので、一般動詞 like だけで表す。be動詞を使うなら I am interested in science. のように like を消さなければならない。動詞は一文に一つ、が原則である。\"}]}",
"{\"id\":\"eigo_s427\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"和文英訳②：動詞と時制を決める\",\"description\":\"日本語の文末表現から、過去・現在・未来・進行形・現在完了のどれを使うかを判断する\",\"intro\":\"「毎朝六時に起きます」と「今起きたところです」では、使う動詞の形がちがいます。手がかりは日本語の文末にあります。〜します、〜しています、〜しました——文末を見るだけで時制はほぼ決まります。その対応を整理します。\",\"order\":927,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"時制は日本語の文末（〜した／〜している／〜するつもり）で決まる。\",\"「毎日〜します」のような習慣は現在形。今この瞬間の動作は be動詞＋ing。\",\"「〜から…しています」は from ではなく現在完了＋for / since。\",\"「〜でした」が天気・時刻・寒暖のときは主語に it を立てる。\",\"時を表す語（yesterday, now, next week）は時制の合図なので必ず先に見る。\"],\"sections\":[{\"heading\":\"文末が時制を決める\",\"body\":\"日本語は文末の形に時間の情報が入っている。英訳するときは、まず文末だけを取り出して時間軸のどこに置くかを決める。\\n\\n■ 対応の一覧\\n・〜した／〜だった　　　　→ 過去形（played, was）\\n・〜する／〜します（習慣）→ 現在形（plays, play）\\n・（今）〜している　　　　→ 現在進行形（is playing）\\n・〜するつもりだ／〜だろう→ will または be going to\\n・〜していた　　　　　　　→ 過去進行形（was playing）\\n・（ずっと）〜している　　→ 現在完了（have played / have been ~）\\n\\n例）弟は毎日サッカーをします。→ My brother plays soccer every day.\\n　　弟は今サッカーをしています。→ My brother is playing soccer now.\\n　　弟はあすサッカーをするつもりです。→ My brother is going to play soccer tomorrow.\\n\\n★ ポイント：「〜しています」は二種類ある。「今この瞬間」なら進行形、「毎日の習慣」なら現在形である。「父は銀行で働いています」は習慣なので My father works at a bank. が正しく、is working とすると「今まさに働いている最中だ」の意味になる。\",\"figureId\":\"lf_eigoext12_427\"},{\"heading\":\"「〜から」「〜でした」の落とし穴\",\"mangaId\":\"eigo_s427_manga\",\"body\":\"日本語の助詞を直訳すると誤りになる代表例が二つある。\\n\\n■ 「〜から…しています」\\n「三年前から住んでいます」を from three years ago と訳したくなるが、英語ではこの言い方をしない。「三年間ずっと」と言いかえて現在完了を使う。\\n例）私は三年間大阪に住んでいます。→ I have lived in Osaka for three years.\\n　　私は子どものころからこの町に住んでいます。→ I have lived in this town since I was a child.\\nfor のあとには長さ（three years, ten minutes）、since のあとには始まりの時点（2020, last year, I was a child）が来る。\\n\\n■ 天気・時刻・寒暖の「〜でした」\\n日本語では主語を言わないが、英語では必ず主語が要る。天気・気温・時刻・曜日・明暗・距離は主語を it にする。\\n例）きのうは雨でした。→ It was rainy yesterday.（または It rained yesterday.）\\n　　今日は寒いです。→ It is cold today.\\n　　六時です。→ It is six o'clock.\\n\\n⚠ 注意：Yesterday was rain. と書く答案が非常に多い。日本語の「きのうは」を主語だと思ってしまうためだが、天気を言う文の主語は it にする。また rain は名詞なので、was のあとにそのまま置くことはできない（rainy と形容詞にする）。\"}],\"trapExamples\":[{\"question\":\"「私は三年前から大阪に住んでいます」を英語にしなさい。\",\"wrongAnswer\":\"I live in Osaka from three years ago.\",\"trapExplanation\":\"「〜から」を from、「三年前」を three years ago と一語ずつ置きかえた直訳。さらに日本語の「住んでいます」を現在形のまま使ったため、「今も続いている三年間」という幅が表せていない。\",\"correctAnswer\":\"I have lived in Osaka for three years.\",\"correctExplanation\":\"過去のある時点から今まで続いていることは現在完了で表す。続いた長さを言うときは for、始まりの時点を言うときは since を使う。「三年前から」は「三年間ずっと」と言いかえて for three years とするのが定型である。\"},{\"question\":\"「きのうは雨でした」を英語にしなさい。\",\"wrongAnswer\":\"Yesterday was rain.\",\"trapExplanation\":\"日本語の「きのうは」を主語だと考え、「雨」という名詞をそのまま補語に置いてしまった。日本語の「〜は」が必ず主語になるとはかぎらないことに気づいていない。\",\"correctAnswer\":\"It was rainy yesterday.\",\"correctExplanation\":\"天気を表す文は主語を it にする。rain は名詞なので、形容詞の rainy に変えて It was rainy yesterday. とするか、rain を動詞として使って It rained yesterday. とする。yesterday は文の最後に置く。\"}]}",
"{\"id\":\"eigo_s428\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"和文英訳③：難しい日本語をやさしい日本語に言いかえる\",\"description\":\"知っている単語だけで書けるように、日本語のほうを先にやさしく作り直す技術を学ぶ\",\"intro\":\"「祖父は畑を耕しています」を英語にしようとして、「耕す」が分からず手が止まる——よくある場面です。ここで必要なのは辞書ではなく、日本語を作り直す力です。「野菜を作っています」なら書けます。言いかえの技術を学びます。\",\"order\":928,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"知らない単語は使わない。日本語のほうをやさしく言いかえてから訳す。\",\"難しい名詞は「だれが どうする」の文に開くと書きやすくなる。\",\"「〜することが好きだ」「趣味は〜だ」は動名詞（〜ing）か to 不定詞を使う。\",\"前置詞のあとに動詞を置くときは必ず ing 形にする（good at playing）。\",\"一文を短く切る。長い日本語は二文に分けてよい。\"],\"sections\":[{\"heading\":\"やさしい日本語に作り直す\",\"body\":\"入試の和文英訳には、小学生が英語を知らない語がまざっていることがある。そこで大切なのが「日本語のほうを、自分が知っている英語で書ける日本語に作り直す」技術である。\\n\\n■ 難しい名詞は文に開く\\n例）弟は好き嫌いが多い。\\n　　→「弟はいろいろな食べ物が好きではない」と言いかえる。\\n　　→ My brother does not like many kinds of food.\\n例）祖母は健康に気をつけている。\\n　　→「祖母は毎日野菜を食べ、よく歩く」と言いかえる。\\n　　→ My grandmother eats vegetables every day and walks a lot.\\n\\n■ 難しい形容詞は説明にする\\n例）この町はにぎやかだ。→「この町にはたくさんの人と店がある」\\n　　→ There are many people and shops in this town.\\n\\n■ 一文が長ければ二文に切る\\n例）私は昨日、母と買い物に行って、新しいくつを買いました。\\n　　→ I went shopping with my mother yesterday. I bought new shoes.\\n\\n★ ポイント：採点されるのは「英語として正しいか」であって「難しい語を使ったか」ではない。やさしい単語で正確に書いた答案のほうが得点は高い。\",\"figureId\":\"xf_eigo_s428\",\"mangaId\":\"eigo_s428_xm\"},{\"heading\":\"「〜すること」の表し方\",\"body\":\"日本語の「〜すること」は、英語では動詞に ing を付けた形（動名詞）か、to ＋動詞の原形（to 不定詞）で表す。動詞をそのまま置いてはいけない。\\n\\n■ 動名詞（〜ing）を使う場所\\n①主語　　　Reading books is fun.（本を読むことは楽しい）\\n②be動詞のあと　My hobby is reading books.（私の趣味は読書です）\\n③前置詞のあと　He is good at playing the piano.（彼はピアノをひくのが上手だ）\\n④enjoy, finish, like, stop のあと　I enjoyed playing soccer.\\n\\n■ to 不定詞を使う場所\\n①want, hope, try, decide のあと　I want to be a doctor.\\n②「〜するために」　I went to the park to play tennis.\\n③「〜するための」　I have a lot of homework to do.\\n\\n⚠ 注意：③の前置詞のあとがいちばんまちがえやすい。at, in, of, about, before, after はすべて前置詞なので、そのあとに動詞を置くなら必ず ing 形にする。He is good at play the piano. は誤りである。\"}],\"trapExamples\":[{\"question\":\"「弟は好き嫌いが多い」を英語にしなさい。\",\"wrongAnswer\":\"My brother has many likes and dislikes.\",\"trapExplanation\":\"「好き嫌い」という日本語を辞書のとおりに名詞へ置きかえ、そのまま並べてしまった。英語としては何を言いたいのかが伝わらず、内容点がもらえない。\",\"correctAnswer\":\"My brother does not like many kinds of food.\",\"correctExplanation\":\"まず日本語を「弟はいろいろな食べ物が好きではない」とやさしく作り直し、それから訳す。My brother is a picky eater. のような語を知らなくても、知っている語だけで正確に書ける。\"},{\"question\":\"「私の趣味は本を読むことです」を英語にしなさい。\",\"wrongAnswer\":\"My hobby is read books.\",\"trapExplanation\":\"「読むこと」という日本語につられて動詞 read をそのまま置いてしまった。is と read で動詞が二つ並んでいることにも気づいていない。\",\"correctAnswer\":\"My hobby is reading books.\",\"correctExplanation\":\"「〜すること」は動名詞（〜ing）か to 不定詞にする。be動詞のあとでは reading books とするのがふつうで、to read books も可。I like reading books. と言いかえてもよい。\"}]}",
"{\"id\":\"eigo_s429\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語を補う：日本語は主語を省く\",\"description\":\"日本語で言わない主語を、英語では必ず立てるという原則と、その見つけ方を学ぶ\",\"intro\":\"「昨日、公園へ行きました」——この日本語には主語がありません。それでも日本語では通じます。ところが英語は、主語がないと文になりません（命令文だけが例外です）。省かれた主語を見つけて立てる手順を確かめます。\",\"order\":929,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"英語の文には必ず主語が要る（命令文だけが例外）。\",\"主語がない日本語文は「だれが？」と自分に問いかけて補う。\",\"会話文では、前後のせりふから I / you / we のどれかを決める。\",\"天気・時刻・寒暖・明暗・距離は主語を it にする（形式的な主語）。\",\"「〜しなさい」「〜してください」は主語を書かない命令文にする。\"],\"sections\":[{\"heading\":\"省かれた主語を見つける\",\"body\":\"日本語は、話し手と聞き手にわかっていることばを省く言語である。とくに主語はよく省かれる。英語ではそれが許されないので、和文英訳では「消えている主語を拾う」ことが最初の仕事になる。\\n\\n■ 「だれが？」と問いかける\\n例）とてもうれしかった。→ だれが？→ 私が → I was very happy.\\n例）今日はいそがしいですか。→ だれが？→ あなたが → Are you busy today?\\n例）来週、京都へ行きます。→ だれが？→ 私（たち）が → I am going to go to Kyoto next week.\\n\\n■ 会話文では前後を見る\\nＡ：How was the movie?\\nＢ：（とてもおもしろかったです）→ It was very interesting.\\nここでの主語はＢ自身ではなく「映画」なので it になる。「おもしろかった」の主語がだれ（何）なのかを、直前のせりふから判断する。\\n\\n■ 「〜と思います」の主語\\n「あした雨が降ると思います」は、思うのは私、降るのは雨。主語が二つある文になる。\\n　→ I think (that) it will rain tomorrow.\\n\\n★ ポイント：主語を補うときは、日本語の中に答えが書いていないことが多い。文全体の場面を思いうかべて決める。\",\"figureId\":\"xf_eigo_s429\"},{\"heading\":\"主語がない文・it を立てる文\",\"mangaId\":\"eigo_s429_manga\",\"body\":\"主語をどうしても言えない、あるいは言う必要がない場合の型を覚えておく。\\n\\n■ 命令文（主語を書かない）\\n「〜しなさい」「〜してください」「〜しよう」は動詞の原形で始める。\\n例）このドアを開けてください。→ Please open this door.（Open this door, please. も可）\\n例）ここで走ってはいけません。→ Don't run here.\\n例）公園へ行きましょう。→ Let's go to the park.\\n\\n■ it を主語にする文\\n天気・気温・時刻・曜日・日付・明暗・距離には it を使う。この it は「それ」とは訳さない。\\n例）暑いですね。→ It is hot, isn't it?\\n　　九時半です。→ It is nine thirty.\\n　　今日は水曜日です。→ It is Wednesday today.\\n　　ここから駅まで一キロあります。→ It is one kilometer from here to the station.\\n\\n■ 「〜することは…だ」の it\\n主語が長くなるときも it を立てて、本当の主語をうしろに回す。\\n例）毎日英語を勉強することは大切です。→ It is important to study English every day.\\n\\n⚠ 注意：「暑いですね」を I am hot. とすると「私は（体が）暑い」の意味になり、気温の話にならない。天気・気温は必ず it を主語にする。\"}],\"trapExamples\":[{\"question\":\"暑い日に外で友達に「暑いですね」と言うときの英語を書きなさい。\",\"wrongAnswer\":\"I am hot.\",\"trapExplanation\":\"日本語の「暑いですね」に主語がないので、話しているのは自分だと考えて I を立ててしまう。英語の I am hot. は「私は（体が）ほてっている」という意味になり、天気の話にならない。\",\"correctAnswer\":\"It is hot today, isn't it?\",\"correctExplanation\":\"天気・気温・寒暖は主語を it にするのが英語の決まりである。この it は「それ」と訳さない形式的な主語で、時刻の It is six o'clock. や曜日の It is Monday. と同じ働きをする。\"},{\"question\":\"「（あなたに）この仕事を手伝ってほしいのです」を英語にしなさい。\",\"wrongAnswer\":\"Want you to help me with this work.\",\"trapExplanation\":\"日本語に主語がないため、そのまま動詞で書き始めてしまった。動詞で始まる文は命令文になるので、これでは「あなたに手伝ってほしいと思え」という意味不明の命令文になる。\",\"correctAnswer\":\"I want you to help me with this work.\",\"correctExplanation\":\"「ほしい」と思っているのは私なので、主語 I を補って I want you to ~ の型にする。命令文以外の英文は必ず主語で始まる、と覚えておく。ていねいに言うなら Could you help me with this work? でもよい。\"}]}",
"{\"id\":\"eigo_s430\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"主語を変える：There is 構文と have の使い分け\",\"description\":\"「〜がある・いる」を英語らしく言うために、主語を選び直す方法を学ぶ\",\"intro\":\"「わたしの家には犬がいます」を There is a dog in my house. と書いても正しいのですが、I have a dog. のほうが自然です。There is で言うか、その名詞を主語にして言うかは、聞き手がもう知っているものかどうかで決まります。持ち主がはっきりしているときは have も使えます。使い分けを学びます。\",\"order\":930,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"There is / There are は「相手が知らないものが存在する」ことを伝える型。\",\"There のあとに the, my, this のついた特定の名詞は置けない。\",\"be動詞の形はうしろの名詞の数で決める（There are five balls.）。\",\"「（人が）〜を持っている・いる」は have で表せる（I have two sisters.）。\",\"日本語の「〜は」が主語とはかぎらない。英語で言いやすい主語を選び直す。\"],\"sections\":[{\"heading\":\"There is / There are の型\",\"body\":\"日本語の「〜がある」「〜がいる」は、英語では There is ～ / There are ～ の型で表すことが多い。この there は「そこに」とは訳さない。\\n\\n■ 形\\nThere ＋ be動詞 ＋ 名詞 ＋ 場所を表す語句\\n例）机の上に本が三冊あります。→ There are three books on the desk.\\n　　公園に犬が一匹います。→ There is a dog in the park.\\n　　冷蔵庫に牛乳が少しあります。→ There is some milk in the refrigerator.\\n\\n■ be動詞はうしろの名詞に合わせる\\nThere のうしろの名詞が単数なら is、複数なら are。数えられない名詞（milk, water, money）は単数扱いで is。\\n過去なら was / were を使う。\\n例）教室には生徒が二十人いました。→ There were twenty students in the classroom.\\n\\n■ 疑問文と否定文\\nIs there a park near your house? — Yes, there is. / No, there isn't.\\nThere are not any chairs in this room.（There are no chairs in this room. も可）\\n\\n★ ポイント：There is ～ は「聞き手がまだ知らないものを初めて話題に出す」ときの型である。だから a, some, three のような「初めて出てくる印」のついた名詞と相性がよい。\"},{\"heading\":\"the がつくものは There を使わない\",\"mangaId\":\"eigo_s430_manga\",\"body\":\"There is のうしろに、the / my / your / this / that のついた名詞や、人名を置くことはできない。これらは「相手がもう知っているもの」を指すからである。\\n\\n■ すでに知っているものの居場所を言うとき\\nその名詞自身を主語にする。\\n例）私のかばんはいすの上にあります。→ My bag is on the chair.（There is my bag on the chair. は誤り）\\n例）お母さんは台所にいます。→ My mother is in the kitchen.\\n例）その本は机の上にあります。→ The book is on the desk.\\n\\n■ have で言いかえられる場合\\n持ち主がはっきりしているときは have を使うと自然になる。\\n例）私には妹が二人います。→ I have two sisters.\\n例）この町には大きな公園があります。→ There is a big park in this town.\\n　　（My town has a big park. も可だが、中学受験では There is の型で書くのが安全）\\n\\n■ 主語を選び直す練習\\n日本語の「〜は」につられないこと。\\n例）この問題は私には難しいです。→ This question is difficult for me.\\n　　（I am difficult. は「私は気難しい人だ」の意味になり誤り）\\n\\n⚠ 注意：There is my bag ~ のような誤りは、日本語の「〜があります」をすべて There is に置きかえてしまうことから起きる。「初めて出す話題か、もう知っているものか」で使い分ける。\",\"figureId\":\"xf_eigo_s430\"}],\"trapExamples\":[{\"question\":\"「私のかばんはいすの上にあります」を英語にしなさい。\",\"wrongAnswer\":\"There is my bag on the chair.\",\"trapExplanation\":\"日本語の「〜があります」を機械的に There is に置きかえてしまった。There is は初めて話題に出すものに使う型なので、すでに持ち主のわかっている my bag とはいっしょに使えない。\",\"correctAnswer\":\"My bag is on the chair.\",\"correctExplanation\":\"the, my, your, this, その人の名前がついた名詞は、それ自身を主語にして be動詞で場所を言う。There is が使えるのは a や some や数詞のついた「初めて出てくるもの」だけだと覚える。\"},{\"question\":\"「箱の中にボールが五個入っています」を英語にしなさい。\",\"wrongAnswer\":\"There is five balls in the box.\",\"trapExplanation\":\"There is をひとまとまりの決まり文句だと思いこみ、うしろの名詞の数を見ずに書いてしまった。日本語では単数と複数を区別しないので気づきにくい。\",\"correctAnswer\":\"There are five balls in the box.\",\"correctExplanation\":\"be動詞の形は、うしろに来る名詞の数で決める。five balls は複数なので are。逆に数えられない名詞は単数あつかいで There is some water in the glass. となる。書いたあとに必ず名詞の数を確かめる。\"}]}",
"{\"id\":\"eigo_s431\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"並べかえ①：骨組みを先に作る\",\"description\":\"語群から動詞をさがし、主語・動詞・目的語の骨組みを組んでから残りを入れる手順を学ぶ\",\"intro\":\"並べかえ問題で、語群を先頭から順に組み立てていくと迷います。先にすることは動詞さがしです。動詞が決まれば主語が決まり、主語が決まれば目的語も決まります。骨組みを作ってから飾りを入れる——この順番で解きます。\",\"order\":931,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"並べかえは①動詞をさがす②主語を決める③目的語を置く、の順で解く。\",\"文の最後は「場所→時」の順に置く。\",\"show / give / tell / teach は「人→物」の順（show me the way）。\",\"語群の中の to, ing, 冠詞は「どの型を使うか」の目印になる。\",\"組み終えたら語をすべて使い切ったか、余りがないかを数えて確かめる。\"],\"sections\":[{\"heading\":\"解く順序\",\"body\":\"並べかえ問題は、語群をながめて意味の通りそうな順に置いていくと、時間がかかるうえに誤りやすい。次の順序で機械的に解く。\\n\\n■ ステップ1　動詞をさがす\\n語群の中で動詞になれる語に印をつける。be動詞（am, is, are, was, were）や助動詞（can, will, would, must）があれば、それが文の骨になる。\\n\\n■ ステップ2　主語を決める\\n日本語訳の「だれが」にあたる語を先頭に置く。疑問文なら Do / Does / Did / Is / Can などが先頭に来る。\\n\\n■ ステップ3　目的語・補語を置く\\n「何を」にあたる語をつづける。\\n\\n■ ステップ4　残りを後ろに\\n場所を表す語句 → 時を表す語句の順で並べる。\\n\\n例題）[ soccer / in / played / the park / I / yesterday ]\\n①動詞＝played　②主語＝I　③目的語＝soccer　④場所＝in the park　⑤時＝yesterday\\n→ I played soccer in the park yesterday.\\n\\n★ ポイント：最後に語群の語数と、できた英文の語数が一致するかを必ず数える。一語余る、一語足りないはこの確認で防げる。\",\"figureId\":\"lf_eigoext12_431\"},{\"heading\":\"「人→物」の順になる動詞\",\"body\":\"目的語を二つとる動詞では、置く順序が決まっている。日本語の順とは逆になることが多いので、型ごと覚える。\\n\\n■ ＜動詞＋人＋物＞の型\\ngive（あげる）、show（見せる・教える）、tell（伝える）、teach（教える）、send（送る）、buy（買ってあげる）、make（作ってあげる）\\n例）駅への道を教えてくれませんか。→ Can you show me the way to the station?\\n例）父は私に新しい自転車を買ってくれた。→ My father bought me a new bike.\\n例）彼女は私たちに英語を教えています。→ She teaches us English.\\n\\n■ 前置詞を使って言いかえる型\\n「人」を後ろに回すときは to または for が必要になる。\\n　give / show / tell / teach / send → to\\n　buy / make / cook → for\\n例）My father bought a new bike for me.\\n　　She teaches English to us.\\n\\n⚠ 注意：Can you show the way to the station me? のように「人」を最後に置くのは誤り。人を後ろに回すなら to me が必要である。語群に to や for が入っているかどうかで、どちらの型を作るかを判断する。\",\"mangaId\":\"eigo_s431_xm\"}],\"trapExamples\":[{\"question\":\"[ is / how / it / long ] を並べかえて「それはどのくらいの長さですか」という意味の英文にしなさい。\",\"wrongAnswer\":\"How is it long?\",\"trapExplanation\":\"疑問詞 How を先頭に置いたあと、be動詞と主語をひっくり返す形だけを覚えていて、long が How とひとまとまりになることに気づいていない。\",\"correctAnswer\":\"How long is it?\",\"correctExplanation\":\"How は long, many, much, old, tall などとくっついて一つの疑問詞のかたまりを作る。かたまりを先頭に置いてから be動詞→主語の順にする。How long is it? / How old are you? / How many books do you have? はすべて同じ組み立てである。\"},{\"question\":\"[ me / show / can / you / to the station / the way ] を並べかえなさい（「駅への道を教えてくれませんか」）。\",\"wrongAnswer\":\"Can you show the way to the station me?\",\"trapExplanation\":\"日本語の「駅への道を（私に）教えて」の順に置いてしまい、show のあとに物を先に出した。人を表す me が行き場を失って文末に取り残されている。\",\"correctAnswer\":\"Can you show me the way to the station?\",\"correctExplanation\":\"show, give, tell, teach などは＜動詞＋人＋物＞の順に置く。人を後ろに回したいときは to が必要で Can you show the way to the station to me? となるが、この形には to が余分に1つ必要である。この語群の to は to the station の1つだけなので作れない。語群に to や for が余っているかどうかで、どちらの型を作るかを決める。\"}]}",
"{\"id\":\"eigo_s432\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"並べかえ②：修飾語をどこに置くか\",\"description\":\"形容詞・副詞・前置詞句がどの位置に入るかを、長さと種類で判断できるようにする\",\"intro\":\"語群に a・very・long・book が入っていたら、どう並べるか決められますか。一語の形容詞は名詞の前、二語以上のかたまりは名詞のうしろ、頻度の副詞は一般動詞の前——修飾語の位置には決まりがあります。それを型にします。\",\"order\":932,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"一語の形容詞は名詞の前、二語以上のかたまりは名詞の後ろに置く。\",\"頻度を表す副詞（always, usually, often, sometimes, never）は一般動詞の前・be動詞の後ろ。\",\"very, really などは形容詞・副詞のすぐ前に置く。\",\"場所と時が並ぶときは「場所→時」の順。\",\"前置詞のかたまり（in the park, on the desk）は必ず前置詞から始めて動かす。\"],\"sections\":[{\"heading\":\"名詞を説明する語の位置\",\"body\":\"名詞を説明する語は、長さによって前に置くか後ろに置くかが決まる。\\n\\n■ 一語なら名詞の前\\n例）a big park（大きな公園）／an interesting book（おもしろい本）／three red apples\\n\\n形容詞が二つ以上並ぶときは、数→大きさ→色の順が基本。\\n例）three big red apples\\n\\n■ 二語以上のかたまりなら名詞の後ろ\\n前置詞のかたまり、動詞の ing 形のかたまり、to 不定詞のかたまりは、名詞の後ろから説明する。\\n例）the book on the desk（机の上の本）\\n　　the boy running over there（あそこで走っている少年）\\n　　something cold to drink（何か冷たい飲み物）\\n　　a girl with long hair（長い髪の女の子）\\n\\n例）あそこで走っている少年は私の兄です。\\n　　→ The boy running over there is my brother.\\n日本語では「あそこで走っている」が先に来るが、英語では the boy のあとに回る。\\n\\n★ ポイント：-thing で終わる語（something, anything, nothing）は、一語の形容詞でも後ろに置く。something cold であって cold something ではない。\",\"figureId\":\"xf_eigo_s432\",\"mangaId\":\"eigo_s432_xm\"},{\"heading\":\"副詞の位置\",\"body\":\"副詞は種類によって置き場所が決まっている。\\n\\n■ 頻度を表す副詞（always / usually / often / sometimes / never）\\n一般動詞の前、be動詞・助動詞の後ろに置く。\\n例）彼はいつも忙しい。→ He is always busy.（be動詞の後ろ）\\n　　彼女はいつも早起きする。→ She always gets up early.（一般動詞の前）\\n　　私は決してうそをつきません。→ I never tell a lie.\\n　　あなたはときどきテニスをしますか。→ Do you sometimes play tennis?\\n\\n■ 様子を表す副詞（well / fast / slowly / hard）\\nふつう文の最後、または動詞のすぐ後ろに置く。\\n例）彼は速く走る。→ He runs fast.\\n　　彼女は上手に英語を話す。→ She speaks English well.（speaks well English は誤り）\\n\\n■ 場所と時\\n場所→時の順で文末に置く。\\n例）私は昨日図書館で英語を勉強した。→ I studied English in the library yesterday.\\n\\n⚠ 注意：目的語（English など）と動詞の間に副詞を割りこませない。She speaks well English. のような答案が多いが、目的語のあとに置いて She speaks English well. とする。\"}],\"trapExamples\":[{\"question\":\"「あそこで走っている少年は私の兄です」を英語にしなさい。\",\"wrongAnswer\":\"The running over there boy is my brother.\",\"trapExplanation\":\"日本語の「あそこで走っている少年」の順をそのまま英語にしたため、二語以上のかたまりを名詞の前に押しこんでしまった。一語の形容詞と同じあつかいにしてよいと思いこんでいる。\",\"correctAnswer\":\"The boy running over there is my brother.\",\"correctExplanation\":\"説明が二語以上のかたまりになるときは、名詞の後ろから説明する。running over there が the boy を後ろから修飾している。The boy who is running over there ~ と関係代名詞で書いてもよい。\"},{\"question\":\"「彼はいつも忙しい」を英語にしなさい。\",\"wrongAnswer\":\"He always is busy.\",\"trapExplanation\":\"「頻度の副詞は動詞の前」とだけ覚えているため、be動詞の場合も前に置いてしまった。一般動詞と be動詞で位置が逆になることを区別していない。\",\"correctAnswer\":\"He is always busy.\",\"correctExplanation\":\"頻度を表す副詞は、be動詞と助動詞の後ろ、一般動詞の前に置く。He is always busy. / He always studies hard. / He can always help us. の三つを並べて覚えるとまちがえない。\"}]}",
"{\"id\":\"eigo_s433\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"並べかえ③：疑問文・不定詞・比較の型\",\"description\":\"入試の並べかえで頻出する、間接疑問・不定詞・比較の語順を型として覚える\",\"intro\":\"入試の並べかえで落としやすいのは、間接疑問・不定詞・比較の三つです。とくに間接疑問は、文の中に入ると疑問文の語順ではなくなります。where he is を where is he と書いてしまう——この失点をここでなくします。\",\"order\":933,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"間接疑問（文の中の疑問詞）は＜疑問詞＋主語＋動詞＞の肯定文の語順に戻す。\",\"How many ＋ 名詞の複数形、How much ＋ 数えられない名詞。\",\"比較級は er / more、最上級は est / the most。high の最上級は highest。\",\"＜too ～ to …＞＜so ～ that …＞＜It is ～ to …＞は型ごと覚える。\",\"語群に that や to があれば、どの型を使わせたいかの合図と考える。\"],\"sections\":[{\"heading\":\"間接疑問：語順が肯定文に戻る\",\"mangaId\":\"eigo_s433_manga\",\"body\":\"疑問詞で始まる文が、別の文の中に入りこむと、語順が肯定文と同じに戻る。これを間接疑問という。並べかえの頻出項目である。\\n\\n■ もとの疑問文\\nWhere does he live?（彼はどこに住んでいますか）\\nWhat time does the movie start?（映画は何時に始まりますか）\\n\\n■ 文の中に入れると\\nDo you know where he lives?（彼がどこに住んでいるか知っていますか）\\nDo you know what time the movie starts?\\nI don't know where he lives.\\nPlease tell me where the station is.\\n\\ndoes や do は消え、動詞は主語に合わせた形（lives, starts）になる。\\n\\n■ よく使う導入部分\\nDo you know ~ / I don't know ~ / Please tell me ~ / I want to know ~\\n\\n★ ポイント：疑問詞のあとに do, does, did, is が来ていたら、そこで一度止まって「これは文の中に入っている疑問文ではないか」を疑う。入っているなら＜疑問詞＋主語＋動詞＞に直す。\",\"figureId\":\"xf_eigo_s433\"},{\"heading\":\"不定詞と比較の型\",\"body\":\"並べかえで問われる型は数が限られている。次の型を、語群を見た瞬間に思い出せるようにする。\\n\\n■ 不定詞の型\\n・It is ～ for 人 to 動詞　　（人が…するのは〜だ）\\n　例）It is easy for me to swim.\\n・too ～ to 動詞　　（…するには〜すぎる／〜すぎて…できない）\\n　例）This box is too heavy to carry.\\n・want 人 to 動詞　　（人に…してほしい）\\n　例）I want you to come to my house.\\n・something ＋ 形容詞 ＋ to 動詞\\n　例）I want something cold to drink.\\n\\n■ 比較の型\\n・比較級 ＋ than　　例）He runs faster than I do.\\n・the ＋ 最上級 ＋ in / of　　例）Mt. Fuji is the highest mountain in Japan.\\n・as ～ as　　例）She is as tall as her mother.\\n・Which do you like better, A or B?　　（AとBではどちらが好きですか）\\n\\n■ 長い語につく比較級・最上級\\nbeautiful, interesting, difficult, popular, important のような長い語は more / most を使う。\\n例）This book is more interesting than that one.\\n　　Soccer is the most popular sport in this school.\\n\\n⚠ 注意：good — better — best、bad — worse — worst、many/much — more — most は不規則に変化する特別な語である。high のような短い語は more high とはせず、high — higher — highest と er／est をつける。\"}],\"trapExamples\":[{\"question\":\"[ know / where / do / you / lives / he ] を並べかえなさい（「彼がどこに住んでいるか知っていますか」）。\",\"wrongAnswer\":\"Do you know where does he live?\",\"trapExplanation\":\"「どこに住んでいますか」という疑問文をそのまま文の後ろにつなげようとして does を補ってしまう。語群に does がないことにも気づいていない。\",\"correctAnswer\":\"Do you know where he lives?\",\"correctExplanation\":\"疑問詞が文の中に入ると＜疑問詞＋主語＋動詞＞の語順に戻り、does は消えて動詞が lives になる。語群に does がないことは「間接疑問で解きなさい」という出題者からの合図である。\"},{\"question\":\"「富士山は日本でいちばん高い山です」を英語にしなさい。\",\"wrongAnswer\":\"Mt. Fuji is the most high mountain in Japan.\",\"trapExplanation\":\"「いちばん〜」を the most と覚えているため、短い語にも most をつけてしまった。high の最上級が highest であることを確かめずに書いている。\",\"correctAnswer\":\"Mt. Fuji is the highest mountain in Japan.\",\"correctExplanation\":\"短い語は est、長い語（beautiful, interesting, difficult など）は most を使う。high, tall, large, old, young, fast はすべて短い語なので est をつける。最上級には the を忘れないこと。\"}]}",
"{\"id\":\"eigo_s434\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"条件英作文①：指定された語句を使う\",\"description\":\"（　）内の語を使う、書き出しが決まっているなどの条件を正しく満たす答案の書き方\",\"intro\":\"条件英作文では、内容が正しくても指定された語を使っていなければ零点になります。逆に言えば、条件を守るだけで確実に点が残ります。語を使う、書き出しに続ける、形を変えてよいか——条件の読み取り方を確かめます。\",\"order\":934,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"指定語は必ず使う。使わなければ内容が正しくても0点になる。\",\"指定語は必要に応じて形を変えてよい（go → went）。「そのままの形で」と書いてあるときだけ変えない。\",\"書き出しが与えられているときは、その続きだけを書く。書き出しをもう一度書かない。\",\"enjoy, finish, stop のあとは ing 形。want, hope のあとは to 不定詞。\",\"書き終えたら、条件を一つずつ指さして確認する。\"],\"sections\":[{\"heading\":\"指定語の使い方\",\"body\":\"条件英作文とは、「（　）内の語を使って」「〜語以内で」「Because で書き始めて」のような条件つきの英作文である。内容が正しくても条件を破れば得点にならないので、条件の確認が最優先になる。\\n\\n■ 指定語は形を変えてよいのが原則\\n例）次の日本語を、（　）内の語を使って英語にしなさい。\\n　　「私は昨日図書館へ行きました」（go）\\n　　→ I went to the library yesterday.\\n指定語 go は、文に合わせて went に変える。「（　）内の語をそのままの形で使うこと」と書かれている場合だけ、形を変えてはいけない。\\n\\n■ 指定語が接続詞のとき\\n　「私は忙しかったので、テレビを見ませんでした」（because）\\n　→ I didn't watch TV because I was busy.\\n　　（Because I was busy, I didn't watch TV. も可）\\n\\n■ 指定語が二つ以上のとき\\n　「彼はとても疲れていたので、早く寝ました」（so, that）\\n　→ He was so tired that he went to bed early.\\n\\n★ ポイント：指定語は「この型で書きなさい」という出題者の指示である。because があれば理由の文、when があれば時の文、to があれば不定詞の型を作る、と読み取る。\",\"figureId\":\"xf_eigo_s434\",\"mangaId\":\"eigo_s434_xm\"},{\"heading\":\"書き出し・書き終わりが決まっている問題\",\"body\":\"書き出しの語句が与えられている問題では、その続きだけを解答らんに書く。与えられた部分をもう一度書くと語数がずれ、減点されることがある。\\n\\n■ 例\\n問）「私はサッカーをすることが好きです」\\n　　I like （　　　　　　）.\\n　　→ playing soccer（または to play soccer）\\n\\n問）あなたが将来なりたいものを英語で答えなさい。\\n　　I want to be （　　　　　　）.\\n　　→ a teacher\\n\\n■ 動詞の形に注意する書き出し\\n・I enjoyed （　）. → playing soccer with my friends（enjoy のあとは ing）\\n・I want （　）. → to visit Kyoto（want のあとは to 不定詞）\\n・I am good at （　）. → playing the piano（前置詞 at のあとは ing）\\n・My dream is （　）. → to be a doctor（be動詞のあとは to 不定詞でも ing でもよい）\\n\\n■ 解答らんの句読点\\n書き出しの部分に大文字があるので、続きは小文字で書き始める。文の終わりのピリオドを忘れない。\\n\\n⚠ 注意：enjoy の直後に to 不定詞は置けない。I enjoyed to play soccer. は誤りで、I enjoyed playing soccer. とする。enjoy / finish / stop / practice のあとは ing、want / hope / decide / try のあとは to、とセットで覚える。\"}],\"trapExamples\":[{\"question\":\"（enjoy）を使って「私は昨日サッカーをして楽しみました」を英語にしなさい。\",\"wrongAnswer\":\"I enjoyed to play soccer yesterday.\",\"trapExplanation\":\"「〜することを楽しむ」という日本語から、「〜すること」を to 不定詞で表そうとしてしまう。want to ~ の型を覚えているために、同じ形が使えると思いこむ。\",\"correctAnswer\":\"I enjoyed playing soccer yesterday.\",\"correctExplanation\":\"enjoy のあとに置けるのは動名詞（ing 形）だけである。同じ仲間に finish, stop, practice がある。反対に want, hope, decide, try のあとは to 不定詞。指定語が enjoy なら、うしろは必ず ing だと即断できる。\"},{\"question\":\"（go）を使って「私は昨日図書館へ行きました」を英語にしなさい。\",\"wrongAnswer\":\"I go to the library yesterday.\",\"trapExplanation\":\"「指定された語をそのまま使わなければならない」と思いこみ、go を原形のまま書いてしまった。yesterday という過去を表す語があるのに時制を合わせていない。\",\"correctAnswer\":\"I went to the library yesterday.\",\"correctExplanation\":\"指定語は文に合うように形を変えてよい。「そのままの形で使うこと」と明記されている場合だけ変えない。yesterday があるので過去形 went にする。指定語を見たら、まず時制と主語に合わせて形を整える。\"}]}",
"{\"id\":\"eigo_s435\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"条件英作文②：語数指定を守る\",\"description\":\"語数の数え方の決まりを覚え、指定語数にぴったり合わせる調整のしかたを学ぶ\",\"intro\":\"「十語以内」と言われたとき、I'm は一語でしょうか、二語でしょうか。答えは一語です。e-mail のようにハイフンでつないだ語も一語、ice cream のように離して書く語は二語。数え方の決まりを先に固めておきます。\",\"order\":935,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"短縮形（I'm, don't）は1語、離して書けば2語（I am, do not）。\",\"ハイフンでつないだ語（e-mail, twenty-five）は1語。\",\"ice cream, high school のように離して書く語は2語。\",\"コンマ・ピリオド・クエスチョンマークは語数に数えない。\",\"語数が足りないときは形容詞・副詞・理由を足し、多いときは短縮形にして削る。\"],\"sections\":[{\"heading\":\"語数の数え方\",\"body\":\"「五語以上で」「六語以内で」といった語数指定は、数え方を知らないと守れない。次の決まりを覚える。\\n\\n■ 1語と数えるもの\\n・短縮形：I'm（1語）／don't（1語）／it's（1語）／can't（1語）\\n・ハイフンでつないだ語：e-mail（1語）／twenty-five（1語）／T-shirt（1語）\\n・冠詞：a, an, the も1語として数える\\n\\n■ 2語と数えるもの\\n・短縮しない形：I am（2語）／do not（2語）／it is（2語）\\n・離して書く名詞：ice cream（2語）／high school（2語）／post office（2語）\\n\\n■ 数えないもの\\nコンマ、ピリオド、クエスチョンマーク、引用符などの記号は数えない。\\n\\n■ 数え方の練習\\nI'm going to visit my aunt tomorrow.\\n　→ I'm(1) going(2) to(3) visit(4) my(5) aunt(6) tomorrow(7)　＝7語\\n\\n★ ポイント：語数が足りないときは、短縮形をやめて I am, do not と離して書くだけで1語ずつ増やせる。逆に多いときは短縮形にして減らせる。\",\"figureId\":\"lf_eigoext12_435\",\"mangaId\":\"eigo_s435_xm\"},{\"heading\":\"語数を調整する技術\",\"body\":\"語数がぴったり合わないときは、次の方法で増減させる。内容を変えずに調整できるので、覚えておくと安心である。\\n\\n■ 増やす方法\\n①形容詞・副詞を足す　　I like dogs. → I really like small dogs.\\n②理由をつける　　　　　I like summer. → I like summer because I can swim in the sea.\\n③場所や時を足す　　　　I play tennis. → I play tennis with my friends every Sunday.\\n④短縮形をやめる　　　　I'm a student. → I am a student.\\n\\n■ 減らす方法\\n①短縮形にする　　　　　I do not like it. → I don't like it.\\n②くり返しを消す　　　　I like soccer and I like baseball. → I like soccer and baseball.\\n③代名詞に変える　　　　My brother plays soccer, and my brother is good at it. → My brother plays soccer, and he is good at it.\\n\\n■ 語数の条件の読み分け\\n・「五語以上で」＝5, 6, 7語…はよいが、4語は不可\\n・「五語以内で」＝1〜5語はよいが、6語は不可\\n・「五語で」＝ちょうど5語\\n\\n⚠ 注意：語数が一語でも条件から外れると、内容が正しくても0点になる採点が多い。書き終えたら必ず指で語を押さえながら数える。数えた語数を答案の横に小さくメモしておくと見直しが速い。\"}],\"trapExamples\":[{\"question\":\"次の英文は何語か答えなさい。I'm going to visit my aunt tomorrow.\",\"wrongAnswer\":\"8語\",\"trapExplanation\":\"I'm を「I」と「am」に分けて2語と数えてしまった。短縮形は見た目が二つの語からできているので、つい二つに分けたくなる。\",\"correctAnswer\":\"7語\",\"correctExplanation\":\"アポストロフィでつないだ短縮形は1語と数える。I'm(1) going(2) to(3) visit(4) my(5) aunt(6) tomorrow(7) で7語。もし I am going to ~ と離して書けば8語になる。この一語の差で条件を満たせるかどうかが決まる。\"},{\"question\":\"「あなたはなぜ英語を勉強するのですか」という問いに、五語以上の英語で答えなさい。\",\"wrongAnswer\":\"Because it is fun.\",\"trapExplanation\":\"内容としては理由になっているが、Because(1) it(2) is(3) fun(4) で4語しかない。答えの中身に気を取られ、語数を数えないまま書き終えてしまう。\",\"correctAnswer\":\"Because I want to talk with people from other countries.\",\"correctExplanation\":\"語数が足りないときは理由をくわしくする。この文は Because(1) I(2) want(3) to(4) talk(5) with(6) people(7) from(8) other(9) countries(10) で10語あり、条件を満たす。書いたら必ず語を指で押さえて数える。\"}]}",
"{\"id\":\"eigo_s436\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"条件英作文③：対話文の空所を埋める\",\"description\":\"前後のせりふから、空所に入る文の種類（質問か答えか）を決めて書く手順を学ぶ\",\"intro\":\"対話文の空所を埋める問題では、空所のうしろの返事がいちばんの手がかりです。答えが時刻なら What time、値段なら How much を入れればよいからです。返事から逆算して質問を作る、この解き方を練習します。\",\"order\":936,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"空所の直後の返事を見れば、入るべき質問の種類がわかる。\",\"答えが時刻なら What time、場所なら Where、理由なら Why、値段なら How much。\",\"Yes, please. / No, thank you. と答える相手は Would you like ~ ? などの勧誘。\",\"提案（How about ~ ? / Shall we ~ ?）には Yes, I do. ではなく Sure. や That sounds good. で答える。\",\"会話特有の決まり文句（Here you are. / Just a moment. など）は丸ごと覚える。\"],\"sections\":[{\"heading\":\"返事から質問を逆算する\",\"body\":\"対話文の空所補充では、空所そのものを考える前に、空所の前後のせりふを読む。とくに直後の返事が最大のヒントになる。\\n\\n■ 返事の種類と質問の対応\\n・It's ten thirty.　　　　→ What time is it (now)?\\n・It's five hundred yen.　→ How much is it?\\n・For two hours.　　　　　→ How long ~ ?\\n・Three times a week.　　 → How often ~ ?\\n・By bus.　　　　　　　　 → How do you go to ~ ?\\n・Because I was busy.　　 → Why ~ ?\\n・It's on the second floor. → Where is ~ ?\\n・Yes, please.　　　　　　→ Would you like ~ ? / Shall I ~ ?\\n・Sure. / All right.　　　→ Can you ~ ? / Will you ~ ?（依頼）\\n\\n■ 例題\\nＡ：（　　　　　　　）\\nＢ：It's ten thirty.\\nＡ：Oh, we have to hurry.\\n【解法】\\n【何を聞かれているか】Ａの空所に、どんな質問が入るか。\\n【なぜこの考え方か】対話文では、答え（返事）の中身から、もとの質問がたどれる。質問と答えは、必ず内容がぴったり合っているからである。\\n【ステップ1】Ｂの返事 It's ten thirty.（十時三十分です）を見る。これは「時刻」を答えている。\\n【ステップ2】時刻を答えるのだから、たずねた質問は時刻をきく文である。\\n【ステップ3】時刻をきく形は What time is it now?（今何時ですか）である。\\n【ステップ4】そのあとのＡのせりふ Oh, we have to hurry.（ああ、急がなくちゃ）を読む。時刻を知って急ぐ気持ちになったので、つながりが自然である。\\n【答え】What time is it now?\\n【確かめ】空所に入れて通して読む。Ａ：What time is it now? Ｂ：It's ten thirty. Ａ：Oh, we have to hurry. 質問・答え・感想が一本の流れになる。\\n【よくあるまちがい】How is the weather? のように、Ｂの返事の形を見ずに入れる。返事が時刻なら、きく文も時刻でなければ合わない。\\n\\n★ ポイント：Ｂの返事だけでなく、そのあとのＡのせりふも読む。「急がなくちゃ」と続いているので、時刻をたずねていることが確かめられる。\",\"figureId\":\"xf_eigo_s436\",\"mangaId\":\"eigo_s436_xm\"},{\"heading\":\"会話の決まり文句\",\"body\":\"対話文には、直訳では意味の取れない決まり文句が出る。型ごと覚えておくと、空所補充でも会話文の並べかえでも使える。\\n\\n■ 店・電話・道案内\\n・May I help you? — Yes, please. I'm looking for a red T-shirt.（店員と客）\\n・Here you are. — Thank you.（はい、どうぞ）\\n・Hello. This is Ken speaking. May I speak to Tom?（電話）\\n・Just a moment, please.（少々お待ちください）\\n・Could you tell me the way to the station?（道をたずねる）\\n・Go straight and turn right at the second corner.（道案内）\\n\\n■ さそう・提案する\\n・How about going to the movies? — That sounds good.\\n・Shall we play tennis after school? — Yes, let's.\\n・Why don't you come to my house? — Thank you. I will.\\n\\n■ ことわる・あやまる\\n・I'm sorry, but I have to go home now.\\n・That's too bad.（それは残念だ）\\n\\n⚠ 注意：How about ~ ? は Do you ~ ? の形をしていないので、Yes, I do. とは答えられない。Sure. / That sounds good. / Yes, let's. のような応答を使う。答え方の形が質問の形に合っているかを必ず確かめる。\"}],\"trapExamples\":[{\"question\":\"Ａ：（　　　）　Ｂ：Yes, please.　空所に入る英文として適切なものを書きなさい。\",\"wrongAnswer\":\"Do you like tea?\",\"trapExplanation\":\"Yes という語だけを見て、Yes / No で答えられる疑問文なら何でも入ると考えてしまった。Yes, please. は「はい、お願いします」という意味で、好みをたずねる質問への答えにはならない。\",\"correctAnswer\":\"Would you like some tea?\",\"correctExplanation\":\"Yes, please. / No, thank you. と答えるのは、物をすすめたり手助けを申し出たりする文である。Would you like ~ ? / Shall I open the window? / Do you want some water? などが入る。Do you like tea? への答えは Yes, I do. になる。\"},{\"question\":\"Ａ：How about going to the movies this afternoon?　Ｂ：（　　　）　空所に入る応答を書きなさい。\",\"wrongAnswer\":\"Yes, I do.\",\"trapExplanation\":\"疑問文だから Yes か No で答えると考え、do を使う形で応じてしまった。How about ~ ? は do を使った疑問文ではないので、Yes, I do. では答えられない。\",\"correctAnswer\":\"That sounds good.\",\"correctExplanation\":\"How about ~ ? / Shall we ~ ? / Why don't we ~ ? はさそいの表現なので、Sure. / That sounds good. / Yes, let's. / I'm sorry, but I can't. のように応じる。答えの形は質問の形に合わせる、という原則を守る。\"}]}",
"{\"id\":\"eigo_s437\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自由英作文①：意見＋理由二つの型\",\"description\":\"立場をはっきり決め、理由を二つ並べて書く定型を身につける\",\"intro\":\"自由英作文で「どちらも好きです」と書くと、正直なのに減点されます。立場をはっきり決めることが求められているからです。意見、理由二つ、まとめ——四文の型を持っておけば、白紙のまま悩む時間がなくなります。\",\"order\":937,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"型は「意見→理由①→理由②→まとめ」の四文。\",\"立場は必ずどちらかに決める。「どちらも好き」は減点される。\",\"First, ~ . Second, ~ . で理由を二つに区切ると読みやすい。\",\"まとめは意見をくり返すだけでよい（That is why ~ . / So ~ .）。\",\"難しい語を使わず、確実に正しい英文を書くほうが点になる。\"],\"sections\":[{\"heading\":\"四文の型\",\"body\":\"自由英作文は「何を書くか」で迷うと時間がなくなる。あらかじめ型を決めておき、そこに内容を流しこむ。中学受験の英語では、四文・四十語程度が標準である。\\n\\n■ 型\\n①意見　I think ~ . / I like ~ better.\\n②理由①　First, ~ .\\n③理由②　Second, ~ .\\n④まとめ　So I think ~ . / That is why I like ~ .\\n\\n■ 例題と模範解答\\n問）Which do you like better, summer or winter? Write about 40 words.\\n\\nI like summer better than winter. First, I can swim in the sea with my family. Second, we have a long vacation in summer, so I can read many books. That is why I like summer better.\\n\\n（語数＝40語程度。文の数＝4文）\\n\\n【解法】\\n【何を聞かれているか】夏と冬のどちらが好きかを、四十語程度の英語で書く。\\n【なぜこの考え方か】自由英作文は、何を書くかで迷うと時間がなくなる。だから「意見→理由①→理由②→まとめ」の四文の型に内容を流しこむ。型に合わせれば、設問の条件（立場を決める・理由が二つ）を自然に満たせるからである。\\n【ステップ1】日本語でメモを作る。「夏。理由①海で泳げる。理由②休みが長い」。先に決めておくと、書くときに迷わない。\\n【ステップ2】①意見。I like summer better than winter.（立場を一つに決めるので、どちらも好きとは書かない）\\n【ステップ3】②理由①。First, I can swim in the sea with my family.（First で一つ目だと読み手に伝える）\\n【ステップ4】③理由②。Second, we have a long vacation in summer, so I can read many books.（理由①とはちがう角度の理由にする）\\n【ステップ5】④まとめ。That is why I like summer better.（①をくり返して終わるので、新しい内容を考えずにすむ）\\n【答え】上の四文。語数は約40語で、四文になっている。\\n【確かめ】①立場は一つか ②理由は角度のちがうものが二つあるか ③四文あるか ④語数が足りているか、を順に指でたどる。\\n【よくあるまちがい】理由②が「海が好きだから」で、理由①と同じ内容になってしまう。理由は別の角度にする。\\n\\n★ ポイント：①と④はほとんど同じ内容でよい。書く前に日本語で「夏。理由は海で泳げる、休みが長い」とメモしておけば、あとは型に流しこむだけで書き終わる。\",\"figureId\":\"lf_eigoext12_437\"},{\"heading\":\"立場を決めるということ\",\"body\":\"日本語の作文では「どちらにもよさがある」と書くのが上手な書き方とされることがあるが、英語の自由英作文ではこれは減点になる。設問が「どちらが好きか」「賛成か反対か」を聞いている以上、答えは一つに決めなければならない。\\n\\n■ 決めるときのコツ\\n好きかどうかではなく「英語で理由が二つ書けるほう」を選ぶ。本当は冬が好きでも、夏の理由のほうが英語で書きやすいなら夏を選んでよい。作文の内容は採点者に確かめようがないので、書きやすさで決める。\\n\\n■ 使える理由の引き出し\\n・時間　I have more free time. / I can get up late.\\n・友達や家族　I can play with my friends. / I can talk with my family.\\n・体験　I went there last year, and it was a lot of fun.\\n・気持ち　It makes me happy. / I feel excited.\\n・役に立つ　It is good for my health. / It helps me study.\\n\\n■ 賛成・反対を書くとき\\nI agree with this idea.（賛成です）／ I do not agree with this idea.（反対です）\\nそのあとは同じく First, ~ . Second, ~ . で理由を並べる。\\n\\n⚠ 注意：理由が一つしかないのに二つに分けて書こうとすると、同じことのくり返しになって内容点が下がる。「楽しいから」と「おもしろいから」は同じ理由である。角度の違う理由を二つ用意する。\",\"mangaId\":\"eigo_s437_xm\"}],\"trapExamples\":[{\"question\":\"Which do you like better, dogs or cats? 理由を二つ入れて、四十語程度の英語で書きなさい。\",\"wrongAnswer\":\"I like both dogs and cats. They are very cute. I want to have them.\",\"trapExplanation\":\"「どちらも好き」と書いて立場を決めなかったため、設問の条件（どちらが好きか）に答えていない。さらに理由が「かわいい」の一つしかなく、二つという条件も満たしていない。\",\"correctAnswer\":\"I like dogs better than cats. First, I can take a walk with a dog every day. It is good for my health. Second, dogs can learn many things, so I can play with them. That is why I like dogs better.\",\"correctExplanation\":\"まずどちらか一方に決め、First, ~ . Second, ~ . で角度の違う理由を二つ並べる。「散歩ができて健康によい」と「芸を覚えるので遊べる」は別の理由になっている。最後に意見をくり返して締めくくる。\"},{\"question\":\"Do you like studying English? 理由を二つ入れて英語で書きなさい。\",\"wrongAnswer\":\"Yes, I do. First, it is fun. Second, I enjoy it.\",\"trapExplanation\":\"形の上では First と Second を使っているが、「楽しい」と「楽しんでいる」は同じ内容である。理由を二つ書いたつもりで、実際には一つしか書けていない。\",\"correctAnswer\":\"Yes, I do. First, I can talk with people from other countries when I travel. Second, I can enjoy movies and songs in English. That is why I like studying English.\",\"correctExplanation\":\"理由は「角度」を変える。この解答では「外国の人と話せる」と「英語の映画や歌を楽しめる」という別の場面を挙げている。理由を書いたら、二つを並べて読み直し、言いかえただけになっていないかを確かめる。\"}]}",
"{\"id\":\"eigo_s438\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自由英作文②：理由をふくらませる\",\"description\":\"理由に具体例や自分の体験を足して、内容点の取れる答案にする\",\"intro\":\"「賛成です。楽しいからです。」——これでは理由が一文で終わり、点が伸びません。そこに具体例か自分の体験を一文足すだけで、答案の厚みは変わります。For example や去年の出来事を、どう足すかを練習します。\",\"order\":938,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"理由は「一文で終わらせず、具体例か体験を一文足す」と厚みが出る。\",\"For example, ~ . / I went ~ last year. が具体化の合図。\",\"体験を書くときは過去形、いつものことは現在形。時制を混ぜない。\",\"接続詞 so（だから）、because（なぜなら）、but（しかし）で文をつなぐ。\",\"知っている言い回しの引き出し（It is fun to ~ . / It helps me ~ .）を用意しておく。\"],\"sections\":[{\"heading\":\"理由をふくらませる二つの型\",\"body\":\"理由を一文書いただけでは、四十語には届かないことが多い。理由のあとに一文足す型を覚えると、語数と内容点の両方が上がる。\\n\\n■ 型A　具体例を足す\\n理由 → For example, ~ .\\n例）I like summer. First, I can do many things outside. For example, I can swim in the sea and go camping with my family.\\n\\n■ 型B　自分の体験を足す\\n理由 → 過去の体験（過去形）\\n例）Second, summer vacation is long. Last summer, I went to my grandmother's house in Nagano and stayed there for a week.\\n\\n■ so と because のつなぎ方\\nso（だから）は結果を後ろに、because（なぜなら）は理由を後ろに置く。\\n例）It was rainy, so we stayed home.\\n　　We stayed home because it was rainy.\\n\\n★ ポイント：型Bの体験は本当のことでなくてよい。ただし書くと決めたら、その一文の中で時制をそろえる。「去年」と書いたのに現在形で続けると減点になる。\",\"figureId\":\"xf_eigo_s438\",\"mangaId\":\"eigo_s438_xm\"},{\"heading\":\"使い回せる言い回しの引き出し\",\"body\":\"自由英作文は本番でゼロから作る時間がない。次のような言い回しをあらかじめ覚えておき、内容だけを入れかえて使う。\\n\\n■ 気持ち・評価\\nIt is fun to play soccer.（サッカーをするのは楽しい）\\nIt makes me happy.（それは私を幸せにする）\\nI am interested in science.（理科に興味がある）\\nI enjoyed talking with my friends.（友達と話すのが楽しかった）\\n\\n■ できる・役に立つ\\nI can learn many things.（多くのことを学べる）\\nIt helps me study English.（英語の勉強の助けになる）\\nIt is good for my health.（健康によい）\\nI want to be a doctor in the future.（将来医者になりたい）\\n\\n■ 時・頻度\\nevery day / every Sunday / once a week / three times a month\\nafter school / on weekends / during summer vacation\\n\\n■ 数と量\\na lot of books / many friends / a few people / some water\\n\\n⚠ 注意：覚えた言い回しをそのまま使うときも、主語に合わせて動詞を変える必要がある。It helps me study English. の主語が複数なら They help me study English. になる。丸暗記した文をそのまま貼りつけて三単現をまちがえる答案が非常に多い。\"}],\"trapExamples\":[{\"question\":\"「去年の夏、私は京都へ行き、とても楽しかったです」を自由英作文の一文として書きなさい。\",\"wrongAnswer\":\"Last summer, I go to Kyoto and it was fun.\",\"trapExplanation\":\"文の後半は was と過去形にできているのに、前半の動詞 go を現在形のままにしてしまった。書きなれた I go to ~ という形が手が覚えていて、時制の確認が抜ける。\",\"correctAnswer\":\"Last summer, I went to Kyoto, and it was a lot of fun.\",\"correctExplanation\":\"Last summer という過去を表す語がある以上、その文の動詞はすべて過去形にそろえる。and でつないだ二つの動詞（went と was）が同じ時制になっているかを、書いたあとに必ず確かめる。\"},{\"question\":\"「例えば、私は友達とサッカーをすることができます」を英語で書きなさい。\",\"wrongAnswer\":\"For example, I can playing soccer with my friends.\",\"trapExplanation\":\"「〜すること」という日本語につられ、can のあとに ing 形を置いてしまった。動名詞を使う場所と助動詞のあとの形を混同している。\",\"correctAnswer\":\"For example, I can play soccer with my friends.\",\"correctExplanation\":\"can, will, must, should などの助動詞のあとは必ず動詞の原形が来る。ing 形を使うのは、前置詞のあと（good at playing）、enjoy などのあと、主語や補語になるときだけである。\"}]}",
"{\"id\":\"eigo_s439\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自由英作文③：見直しで減点を防ぐ\",\"description\":\"書き終えたあと三十秒で行う、決まった順序の見直し手順を身につける\",\"intro\":\"書き終えた瞬間に手を止めてはいけません。減点の多くは、内容ではなく三単現の s や冠詞といった小さなミスから生まれるからです。見直す順番を決めておけば、三十秒で数点を拾えます。その順序を身につけます。\",\"order\":939,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"見直しは「三単現→複数のs→冠詞→時制→つづり」の順で行う。\",\"主語が he / she / it などの単数なら、現在形の動詞に s がつく。\",\"数えられる名詞が二つ以上なら s、一つなら a か an が必要。\",\"by bike, by bus, go to school のように冠詞をつけない決まり文句がある。\",\"大文字で書き始め、ピリオドで終わっているかも点になる。\"],\"sections\":[{\"heading\":\"見直しの順序を決めておく\",\"body\":\"見直しは「なんとなく読み返す」のではなく、見る項目を決めて一項目ずつ通す。そのほうが速く、見落としがない。\\n\\n■ 手順（各五〜六秒、五項目で三十秒）\\n①三単現の s\\n　主語が I, you, 複数以外で、現在の話なら、動詞に s がついているか。\\n　My brother like soccer.（誤）→ My brother likes soccer.（正）\\n②名詞の s\\n　二つ以上あるものに s がついているか。逆に一つなのに s をつけていないか。\\n　I have two brother.（誤）→ I have two brothers.（正）\\n③冠詞\\n　数えられる名詞が一つのとき、a / an / the / my などがついているか。\\n　My father is teacher.（誤）→ My father is a teacher.（正）\\n④時制\\n　yesterday, last year があるのに現在形になっていないか。\\n⑤つづり\\n　friend, because, beautiful, favorite, restaurant など、まちがえやすい語を確かめる。\\n\\n★ ポイント：この五項目で失点のほとんどが防げる。内容を書き直そうとすると時間が足りなくなるので、見直しでは内容には手を入れない。\",\"figureId\":\"xf_eigo_s439\"},{\"heading\":\"冠詞をつけない決まり文句\",\"body\":\"冠詞は「つけ忘れ」だけでなく「つけすぎ」も誤りになる。次の場合は a や the をつけない。\\n\\n■ 交通手段の by\\nby bike / by bus / by train / by car / by plane\\n例）私は自転車で学校へ行きます。→ I go to school by bike.（by a bike は誤り）\\n　　ただし「歩いて」は on foot。\\n\\n■ 建物を本来の目的で使うとき\\ngo to school（勉強しに学校へ行く）／go to bed（寝る）／go to church\\n例）I go to school at eight.（校舎に用があって行くなら go to the school）\\n\\n■ 食事の名前\\nhave breakfast / have lunch / have dinner\\n例）私は七時に朝食を食べます。→ I have breakfast at seven.\\n\\n■ スポーツ名\\nplay soccer / play tennis / play baseball（the はつけない）\\n一方、楽器には the をつける。play the piano / play the guitar\\n\\n■ 教科・言語・季節\\nstudy English / like math / in summer\\n\\n⚠ 注意：play the soccer と play piano は、どちらもよくある誤り。「スポーツは冠詞なし、楽器は the」と対にして覚える。\",\"mangaId\":\"eigo_s439_xm\"}],\"trapExamples\":[{\"question\":\"「私の町にはたくさんの人が住んでいます」を There で始めて英語にしなさい。\",\"wrongAnswer\":\"There is many people in my town.\",\"trapExplanation\":\"people という語に s がついていないため単数だと思ってしまう。people は語形が変わらないだけで、意味は複数（人々）である。\",\"correctAnswer\":\"There are many people in my town.\",\"correctExplanation\":\"people は person の複数形にあたる語で、つねに複数あつかいをする。同じように children, men, women も s がつかないが複数である。be動詞は are、動詞に三単現の s はつけない。\"},{\"question\":\"「私は自転車で学校へ行きます」を英語にしなさい。\",\"wrongAnswer\":\"I go to school by a bike.\",\"trapExplanation\":\"「数えられる名詞には冠詞が要る」という規則を覚えたばかりのため、by のあとの bike にも a をつけてしまった。冠詞は「つけすぎ」も誤りになると知らない。\",\"correctAnswer\":\"I go to school by bike.\",\"correctExplanation\":\"交通手段を表す by のあとの名詞には冠詞をつけない。by bus, by train, by car も同じ。「歩いて」は on foot である。逆に自転車そのものを話題にするときは I have a new bike. のように冠詞が必要になる。\"}]}",
"{\"id\":\"eigo_s440\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"絵の描写①：だれが何をしているかを書く\",\"description\":\"絵を見て英文を作る問題で、現在進行形を使って動作を正確に描写する\",\"intro\":\"絵を見て英文を作る問題では、まず「だれが何をしているか」を書きます。今まさにしている動作なので、現在進行形を使います。ing の付け方でつまずくことが多く、run は running と n を重ねます。書きながら確かめます。\",\"order\":940,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"絵の中の動作は現在進行形（be動詞＋ing）で表す。\",\"be動詞は主語の数に合わせる（A boy is ~ . / Two girls are ~ .）。\",\"ing のつけ方に注意（run → running, swim → swimming, write → writing）。\",\"have（持っている）, like, know, want は進行形にしない。\",\"目立つものから順に、一文ずつ短く書く。\"],\"sections\":[{\"heading\":\"現在進行形で描写する\",\"body\":\"絵や写真を見て英語で説明する問題は、帰国子女入試や英語選択入試でよく出る。書き方の型は決まっている。\\n\\n■ 型\\n＜主語＋be動詞＋動詞のing形＋（目的語）＋（場所）＞\\n例）A boy is playing soccer in the park.\\n　　Two girls are talking under the tree.\\n　　A man is reading a book on the bench.\\n　　A dog is sleeping by the door.\\n\\n■ be動詞の選び方\\n主語が一人・一つなら is、二つ以上なら are。\\n例）A girl is running. / Three children are running.\\n\\n■ ing のつけ方\\n・ふつうは ing をつける　　play → playing, read → reading, eat → eating\\n・e で終わる語は e を取る　make → making, write → writing, ride → riding\\n・短い語で子音を重ねる　　run → running, swim → swimming, sit → sitting, get → getting\\n\\n■ 書く順序\\n絵の中でいちばん大きく描かれているもの、中央にあるものから書く。一文に二つも三つも詰めこまず、一文一動作にする。\\n\\n★ ポイント：絵の描写では、名前のわからないものを無理に書かない。「ベンチ」がわからなければ、そこは書かずに A man is reading a book. だけにすればよい。\",\"figureId\":\"lf_eigoext12_440\"},{\"heading\":\"進行形にしない動詞\",\"mangaId\":\"eigo_s440_manga\",\"body\":\"動作ではなく「状態」を表す動詞は、進行形にしない。絵の描写でよくまちがえるので注意する。\\n\\n■ 進行形にしない代表的な動詞\\nhave（持っている・飼っている）／like（好きだ）／know（知っている）／want（ほしい）／see（見える）／hear（聞こえる）／belong（属している）\\n例）女の人が赤いかばんを持っている。→ A woman has a red bag.（is having は誤り）\\n　　男の子がねこを飼っている。→ A boy has a cat.\\n\\n■ have が進行形になる場合\\n「食べる・飲む・（時を）過ごす」の意味なら進行形にできる。\\n例）They are having lunch.（昼食を食べているところだ）\\n　　We are having a good time.（楽しい時を過ごしている）\\n\\n■ 「身につけている」の言い分け\\nwear は「身につけている」という状態、put on は「身につける」という動作。\\n例）A girl is wearing a red cap.（赤い帽子をかぶっている状態）\\n　　A girl is putting on her shoes.（今くつをはこうとしている動作）\\n「〜を持って・身につけて」を with で表すこともできる。\\n例）a girl with long hair（長い髪の女の子）／a boy with a blue bag\\n\\n⚠ 注意：wear は「状態」を表す動詞だが、進行形にできる例外である。「着ている最中」ではなく「着ている状態」を表すので、絵の描写では is wearing がよく使われる。\"}],\"trapExamples\":[{\"question\":\"絵の中で男の子がサッカーをしている。この様子を英語で書きなさい。\",\"wrongAnswer\":\"A boy is play soccer.\",\"trapExplanation\":\"be動詞を置くところまでは覚えていたが、動詞を ing 形にするのを忘れた。日本語の「している」という一つの表現が、英語では be動詞と ing の二つで表されることが意識できていない。\",\"correctAnswer\":\"A boy is playing soccer.\",\"correctExplanation\":\"現在進行形は be動詞と ing 形の二つがそろって初めて成り立つ。どちらか一方だけでは誤りになる。A boy plays soccer. だと「習慣としてサッカーをする」の意味になり、絵の説明にならない。\"},{\"question\":\"絵の中の女の人が赤いかばんを持っている。この様子を英語で書きなさい。\",\"wrongAnswer\":\"A woman is having a red bag.\",\"trapExplanation\":\"「絵の描写はすべて現在進行形」と機械的に覚えたため、状態を表す have まで進行形にしてしまった。「持っている」という日本語の「〜ている」につられている。\",\"correctAnswer\":\"A woman has a red bag.\",\"correctExplanation\":\"「持っている・所有している」の have は状態を表すので進行形にしない。同じ仲間に like, know, want, see がある。ただし「食べる」の意味の have は They are having lunch. のように進行形にできる。\"}]}",
"{\"id\":\"eigo_s441\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"絵の描写②：位置を表す前置詞\",\"description\":\"in / on / under / by / between などを使い分けて、ものの位置を正確に説明する\",\"intro\":\"机の上のノートは on、引き出しの中は in、頭の上にかかった時計は above。絵の描写では、位置を表す前置詞をまちがえると意味が変わってしまいます。ふれているかいないか、という基準で選び分けます。\",\"order\":941,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"ふれていれば on、中に入っていれば in、離れて上なら over / above。\",\"「二つの間」は between、「三つ以上の中」は among。\",\"in front of（〜の前に）と behind（〜の後ろに）は対で覚える。\",\"by / near / next to はどれも「そば」だが、next to は「すぐとなり」。\",\"前置詞のあとには必ず名詞（または代名詞の目的格）が来る。\"],\"sections\":[{\"heading\":\"位置の前置詞\",\"mangaId\":\"eigo_s441_manga\",\"body\":\"位置を表す前置詞は、日本語の「上・下・中」と一対一で対応しない。ふれているかどうか、囲まれているかどうかで選ぶ。\\n\\n■ 基本の使い分け\\n・in　　中に入っている　　The pen is in the box.\\n・on　　ふれている　　　　The book is on the desk. / A picture is on the wall.\\n・over / above　離れて上　A bird is flying over the house.\\n・under　真下　　　　　　The cat is under the table.\\n・by / near　そば　　　　He is standing by the window.\\n・next to　すぐとなり　　The post office is next to the bank.\\n・in front of　前に　　　A car is in front of the house.\\n・behind　後ろに　　　　　A boy is hiding behind the tree.\\n・between A and B　AとBの間に\\n・across from　向かい側に\\n\\n■ 「壁に」は on\\n日本語では「壁に絵がかかっている」と言うが、絵は壁にふれているので on the wall である。同じように「天井に」は on the ceiling。\\n例）There is a picture on the wall.\\n\\n★ ポイント：in と on の判断は「中に入っているか、表面にふれているか」。in the box（箱の中）と on the box（箱の上）はまったく違う位置になる。\",\"figureId\":\"lf_eigoext12_441\"},{\"heading\":\"between と among、その他の注意\",\"body\":\"数によって使い分ける前置詞、形が変わる前置詞に注意する。\\n\\n■ between と among\\n・between … 二つ（二人）の間\\n　例）There is a bench between the two trees.\\n　　　I sat between Ken and Tom.\\n・among … 三つ（三人）以上の中\\n　例）He is popular among the students.\\n\\n■ 前置詞のあとの代名詞は目的格\\nbetween you and I は誤りで、between you and me が正しい。前置詞のあとに来る代名詞は me, him, her, us, them の形になる。\\n例）Please sit next to me.\\n　　The dog ran to him.\\n\\n■ 場所と時をつなげるとき\\n場所→時の順に置く。\\n例）I met her in front of the station at five.\\n\\n■ よくある位置の言い方\\n・on the second floor（二階に）\\n・in the middle of the room（部屋の真ん中に）\\n・at the corner（角に）\\n・on the left / on the right（左に／右に）\\n\\n⚠ 注意：「〜の間に」を日本語でひとくくりにして among を使うと誤りになる。二つなら必ず between。between the two trees のように、二つであることを the two ~ と示すと確実である。\"}],\"trapExamples\":[{\"question\":\"「壁に絵がかかっています」を There で始めて英語にしなさい。\",\"wrongAnswer\":\"There is a picture in the wall.\",\"trapExplanation\":\"日本語の「壁に」という助詞「に」から、内部を表す in を選んでしまった。in を使うと「絵が壁の内部に埋めこまれている」という意味になる。\",\"correctAnswer\":\"There is a picture on the wall.\",\"correctExplanation\":\"on は「表面にふれている」ことを表す前置詞で、上下や向きは関係ない。壁にかかった絵、天井の照明、顔についた汚れもすべて on を使う。in は「囲まれた内部」に入っているときだけ使う。\"},{\"question\":\"「二本の木の間にベンチがあります」を英語にしなさい。\",\"wrongAnswer\":\"There is a bench among two trees.\",\"trapExplanation\":\"「〜の間」という日本語をひとまとめに覚え、数による使い分けを意識していない。among と between のどちらでもよいと思いこんでいる。\",\"correctAnswer\":\"There is a bench between the two trees.\",\"correctExplanation\":\"between は二つのものの間、among は三つ以上の中に囲まれているときに使う。two trees とはっきり二つと書かれているので between しか使えない。「木々の間を歩いた」なら I walked among the trees. となる。\"}]}",
"{\"id\":\"eigo_s442\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"絵の描写③：数量と様子をつけ加える\",\"description\":\"数えられる名詞と数えられない名詞の量の表し方、色や様子の加え方を学ぶ\",\"intro\":\"絵に牛乳のコップが三つあっても、three milks とは書けません。milk は数えられない名詞だからです。数えられるものと数えられないもので、量の表し方が変わります。色や様子を足して描写を豊かにする方法も学びます。\",\"order\":942,\"studyPeriod\":\"小6前半\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"数えられる名詞は many / a few、数えられない名詞は much / a little。\",\"a lot of と some はどちらにも使える。\",\"water, milk, bread, money, paper, homework は数えられない名詞。\",\"不規則な複数形（children, men, women, feet, teeth）を覚える。\",\"色や大きさは名詞の前、様子を表す副詞は文の後ろに置く。\"],\"sections\":[{\"heading\":\"数えられる名詞と数えられない名詞\",\"body\":\"英語の名詞は「一つ二つと数えられるもの」と「数えられないもの」に分かれる。絵の描写では量を表す語を使うので、この区別が必要になる。\\n\\n■ 数えられない名詞の代表\\nwater（水）／milk（牛乳）／juice／bread（パン）／rice（米）／money（お金）／paper（紙）／homework（宿題）／music／time（時間）／information\\n\\nこれらには a をつけず、複数形の s もつけない。\\n例）テーブルの上に水がたくさんあります。→ There is a lot of water on the table.\\n　　（There are many waters ~ は誤り）\\n\\n■ 量を数える言い方\\n数えられない名詞を数えるときは、入れ物や単位を使う。\\na glass of water（コップ一杯の水）／two glasses of milk\\na cup of tea（カップ一杯の紅茶）／a piece of paper（一枚の紙）／two pieces of cake\\n\\n■ many / much / a lot of\\n・many ＋ 数えられる名詞の複数形　many books\\n・much ＋ 数えられない名詞　much water（否定文・疑問文で使うことが多い）\\n・a lot of ＋ どちらでも可　a lot of books / a lot of water\\n・a few ＋ 数えられる名詞（少しの）／ a little ＋ 数えられない名詞（少しの）\\n\\n★ ポイント：迷ったら a lot of と some を使う。どちらの名詞にも使えるので、誤りになりにくい。\",\"mangaId\":\"eigo_s442_xm\"},{\"heading\":\"不規則な複数形と、様子の加え方\",\"body\":\"複数形は s をつけるのが基本だが、形が変わるものがある。絵の描写で人数を書くときによく使う。\\n\\n■ 不規則な複数形\\nchild → children（子ども）／man → men（男の人）／woman → women（女の人）\\nfoot → feet（足）／tooth → teeth（歯）／mouse → mice（ねずみ）\\nfish → fish（魚：単複同形）／sheep → sheep（羊：単複同形）\\nまた people（人々）はそれ自体が複数である。\\n\\n■ s の付け方が変わるもの\\n・s, x, ch, sh で終わる語 → es　bus → buses, box → boxes, watch → watches\\n・子音＋y → y を i に変えて es　city → cities, country → countries\\n・f, fe → ves　leaf → leaves, knife → knives\\n\\n■ 様子をつけ加える\\n色・大きさ・材質は名詞の前に置く。\\n例）a big brown dog（大きな茶色い犬）／a small red car\\n様子を表す副詞は文の後ろに置く。\\n例）The children are running happily in the park.\\n\\n■ 服装の表し方\\nA girl in a blue dress is singing.（青い服の女の子が歌っている）\\nA boy wearing glasses is reading a book.（めがねをかけた男の子が本を読んでいる）\\n\\n⚠ 注意：three childs, two mans のような答案が多い。不規則な複数形は数が限られているので、まとめて覚えてしまう。\",\"figureId\":\"xf_eigo_s442\"}],\"trapExamples\":[{\"question\":\"「テーブルの上に水がたくさんあります」を英語にしなさい。\",\"wrongAnswer\":\"There are many waters on the table.\",\"trapExplanation\":\"「たくさん」という日本語から many を選び、さらに複数だから s が要ると考えて waters としてしまった。water が数えられない名詞であることを意識していない。\",\"correctAnswer\":\"There is a lot of water on the table.\",\"correctExplanation\":\"water は数えられない名詞なので複数形にせず、many も使わない。a lot of か much を使い、be動詞は is にする。数えたいときは two glasses of water のように入れ物で数える。\"},{\"question\":\"「公園に三人の子どもがいます」を英語にしなさい。\",\"wrongAnswer\":\"There are three childs in the park.\",\"trapExplanation\":\"複数形は s をつけると覚えているため、child にもそのまま s をつけてしまった。不規則な複数形の存在を思い出せていない。\",\"correctAnswer\":\"There are three children in the park.\",\"correctExplanation\":\"child の複数形は children で、s はつかない。man → men、woman → women、foot → feet、tooth → teeth も同じく不規則である。数の少ない例外なので、まとめて暗記しておく。\"}]}",
"{\"id\":\"eigo_s443\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"誤文訂正①：三単現と複数形の s\",\"description\":\"誤りを見つける問題の解き方と、s のつけ忘れ・つけすぎの直し方\",\"intro\":\"誤りをさがす問題では、どこから見ていくかを決めておくと速くなります。いちばん多いのは s のつけ忘れとつけすぎです。主語が三人称単数で現在なら動詞に s、名詞が二つ以上なら名詞に s。まずここを確かめます。\",\"order\":943,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"主語が三人称単数で現在の話なら、動詞に s / es がつく。\",\"does や doesn't を使ったら、動詞は原形に戻す。\",\"have の三単現は has、go は goes、study は studies。\",\"主語が複数（my parents, Ken and I）なら動詞に s はつかない。\",\"誤文訂正は「主語を丸で囲む→動詞を確かめる」の順で見る。\"],\"sections\":[{\"heading\":\"誤文訂正の手順\",\"body\":\"誤りを一か所見つけて直す問題は、やみくもに読み返すのではなく、見る順番を決めて解く。答案でよく見かける誤りの半分以上は三単現と冠詞なので、そこから確かめる。\\n\\n■ 手順\\n①主語を丸で囲む　　だれが、いくつか\\n②動詞を四角で囲む　主語に合っているか、時制は合っているか\\n③名詞を見る　　　　s は要るか、冠詞は要るか\\n④前置詞を見る　　　抜けていないか、余分ではないか\\n\\n■ 三単現の s がつく条件\\n・主語が I と you 以外の一人・一つ（he, she, it, my brother, Ken, this book）\\n・現在のことを表している（過去形・未来形ならつかない）\\n例）My brother plays tennis every Sunday.\\n　　Ken goes to school by bus.\\n　　This book looks interesting.\\n\\n■ s / es のつけ方\\n・ふつうは s　　plays, likes, reads\\n・s, x, ch, sh, o で終わる語は es　goes, watches, teaches, washes\\n・子音＋y は y を i に変えて es　study → studies, cry → cries\\n・have は has（特別）\\n\\n★ ポイント：主語が長いときは、その中心になる語を見る。The boy with two dogs is my friend. の主語は The boy なので is になる。\",\"figureId\":\"lf_eigoext12_443\"},{\"heading\":\"does を使ったら動詞は原形\",\"mangaId\":\"eigo_s443_manga\",\"body\":\"疑問文や否定文で does を使うと、s の働きは does が引き受ける。だから動詞は原形に戻さなければならない。\\n\\n■ 正しい形\\n・He plays tennis.（肯定文：動詞に s）\\n・He does not play tennis.（否定文：does not ＋ 原形）\\n・Does he play tennis?（疑問文：Does ＋ 主語 ＋ 原形）\\n・He doesn't play tennis.（短縮形）\\n\\n■ よくある誤り\\nDoes he plays tennis?（誤）→ Does he play tennis?\\nMy brother don't like natto.（誤）→ My brother doesn't like natto.\\nShe don't go to school by bus.（誤）→ She doesn't go to school by bus.\\n\\n■ 過去形も同じ\\ndid を使ったら動詞は原形になる。\\nDid you went to the park?（誤）→ Did you go to the park?\\nI didn't watched TV.（誤）→ I didn't watch TV.\\n\\n■ 名詞の複数形のつけ忘れ\\n数を表す語のあとの名詞は必ず複数形にする。\\nI have two brother.（誤）→ I have two brothers.\\nThere are many book in the library.（誤）→ There are many books in the library.\\n\\n⚠ 注意：一つの文に s は一回だけ、という覚え方は誤り。My brothers play soccer.（名詞に s、動詞には s なし）と My brother plays soccer.（名詞に s なし、動詞に s）は、s の位置がちょうど入れかわる。主語と動詞をセットで見る。\"}],\"trapExamples\":[{\"question\":\"次の英文の誤りを一か所直しなさい。My brother don't like natto.\",\"wrongAnswer\":\"My brother don't likes natto.\",\"trapExplanation\":\"三単現の s が足りないと考え、動詞の like に s をつけてしまった。誤っているのは動詞ではなく don't のほうであることに気づいていない。\",\"correctAnswer\":\"My brother doesn't like natto.\",\"correctExplanation\":\"主語 My brother は三人称単数なので、否定文では doesn't を使う。そして doesn't のあとの動詞は原形の like のままにする。s は doesn't の中の does が引き受けている。\"},{\"question\":\"次の英文の誤りを一か所直しなさい。Does he plays tennis every Sunday?\",\"wrongAnswer\":\"Do he plays tennis every Sunday?\",\"trapExplanation\":\"動詞に s がついているのを見て、Does を Do に変えてしまった。三単現の s は動詞ではなく Does のほうに現れる、という関係が理解できていない。\",\"correctAnswer\":\"Does he play tennis every Sunday?\",\"correctExplanation\":\"Does で始まる疑問文では、うしろの動詞は必ず原形になる。主語 he は三人称単数なので Do には変えられない。Does を残し、plays を play に直すのが正しい。\"}]}",
"{\"id\":\"eigo_s444\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"誤文訂正②：冠詞のつけ忘れ・つけすぎ\",\"description\":\"a / an / the の使い分けと、冠詞をつけない決まり文句を整理する\",\"intro\":\"a hour と書くと誤りで、正しくは an hour です。h を発音しないからです。逆に university は u で始まるのに a university。a と an は、つづりではなく最初の音で決まります。冠詞の落とし穴を確かめます。\",\"order\":944,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"a と an の使い分けは、つづりではなく発音の最初の音で決める。\",\"an hour, an honest man は h を発音しないので an。\",\"a university, a uniform は「ユ」の音で始まるので a。\",\"二度目に出てくるもの、一つしかないものには the をつける。\",\"スポーツ名に the はつけず、楽器名には the をつける。\"],\"sections\":[{\"heading\":\"a と an は音で決める\",\"mangaId\":\"eigo_s444_manga\",\"body\":\"a と an の使い分けは「次の語が母音字（a, i, u, e, o）で始まるかどうか」ではなく、「母音の音で始まるかどうか」で決まる。\\n\\n■ an を使う例\\nan apple / an orange / an egg / an umbrella / an old man / an interesting book\\nan hour（アワー：h を発音しない）\\nan honest boy（オネスト：h を発音しない）\\n\\n■ a を使う例（母音字だが子音の音で始まる）\\na university（ユニバーシティ：ユの音）\\na uniform（ユニフォーム）\\na useful book（ユースフル）\\na European country（ユーロピアン）\\na one-day trip（ワンデイ）\\n\\n■ 形容詞がつくときは、形容詞の音で決める\\nan apple → a red apple（red はレの音）\\na book → an interesting book（interesting はイの音）\\n\\n★ ポイント：迷ったら声に出して読み、a の次に来る音が「ア・イ・ウ・エ・オ」なら an にする。hour は「アワー」と読むので an、university は「ユ」と読むので a になる。\",\"figureId\":\"xf_eigo_s444\"},{\"heading\":\"the をつけるとき・つけないとき\",\"body\":\"the は「どれのことか、話し手と聞き手の両方がわかっている」ときにつける。\\n\\n■ the をつける場合\\n①二度目に出てくるもの\\n　I have a dog. The dog is very big.\\n②世界に一つしかないもの\\n　the sun / the moon / the earth / the sky\\n③あとから説明がついて特定されるもの\\n　the book on the desk / the girl I met yesterday\\n④最上級・序数のあと\\n　the highest mountain / the first day\\n⑤楽器\\n　play the piano / play the guitar\\n\\n■ the をつけない場合\\n①スポーツ　play soccer / play tennis（play the soccer は誤り）\\n②教科・言語　study English / like math\\n③食事　have breakfast / have lunch\\n④交通手段の by　by bus / by train\\n⑤本来の目的で使う建物　go to school / go to bed\\n⑥固有名詞　Japan / Osaka / Mt. Fuji（ただし the Pacific Ocean のように例外もある）\\n\\n■ 数えられない名詞と冠詞\\nwater, milk, music, homework には a をつけない。\\nI have a homework.（誤）→ I have homework. / I have a lot of homework.\\n\\n⚠ 注意：日本語には冠詞がないので、つけ忘れは意識しないと絶対に減らない。名詞を書いたら、そのたびに「一つか、複数か、数えられないか」を心の中で確かめる習慣をつける。\"}],\"trapExamples\":[{\"question\":\"次の英文の誤りを一か所直しなさい。I waited for a hour at the station.\",\"wrongAnswer\":\"I waited for a hours at the station.\",\"trapExplanation\":\"「一時間」を複数だと思って s をつけてしまった。本当の誤りは冠詞のほうで、hour の発音を意識していないことが原因である。\",\"correctAnswer\":\"I waited for an hour at the station.\",\"correctExplanation\":\"hour は h を発音せず「アワー」と読むので、母音の音で始まる語として an を使う。同じく an honest man も h を発音しない。逆に a university は「ユ」と読むので a になる。つづりではなく音で決める。\"},{\"question\":\"次の英文の誤りを一か所直しなさい。He plays the soccer every Sunday.\",\"wrongAnswer\":\"He play the soccer every Sunday.\",\"trapExplanation\":\"動詞のほうを疑って s を取ってしまった。主語 He は三人称単数なので plays が正しく、誤っているのはスポーツ名についた the のほうである。\",\"correctAnswer\":\"He plays soccer every Sunday.\",\"correctExplanation\":\"スポーツ名には冠詞をつけない。一方、楽器名には the をつけて play the piano, play the guitar とする。「スポーツは冠詞なし、楽器は the」と対にして覚えると、両方の誤りを同時に防げる。\"}]}",
"{\"id\":\"eigo_s445\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"誤文訂正③：時制のずれと前置詞の抜け\",\"description\":\"時を表す語と動詞の形が合っているか、前置詞が過不足なく置かれているかを確かめる\",\"intro\":\"I have finished it yesterday. はどこが誤りでしょうか。現在完了は yesterday のような、過去の一点を表す語と組めません。時を表す語と動詞の形が合っているか、前置詞が抜けていないか。二つの観点で見直します。\",\"order\":945,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"現在完了は yesterday, last year などの過去の一点を表す語と使えない。\",\"when や if で始まる文の中では、未来のことも現在形で表す。\",\"listen to, wait for, look for, arrive at は前置詞まで一組で覚える。\",\"home, here, there, abroad は副詞なので to をつけない。\",\"時を表す語の前の前置詞（at six / on Monday / in April）を使い分ける。\"],\"sections\":[{\"heading\":\"時制のずれを見つける\",\"body\":\"英文の中には、時制を決める手がかりになる語が必ずある。それと動詞の形が食いちがっていないかを確かめる。\\n\\n■ 手がかりになる語\\n・yesterday, last week, ~ ago, then → 過去形\\n・now, right now, at present → 現在形か現在進行形\\n・tomorrow, next week, someday → will / be going to\\n・for ~ , since ~ , just, already, yet, ever, never → 現在完了\\n\\n■ 現在完了と過去の一点は共存できない\\n現在完了は「過去のある時点から今まで」という幅を表す。だから yesterday や last year のような一点を指す語といっしょには使えない。\\nI have visited Kyoto last year.（誤）\\n→ I visited Kyoto last year.（過去形にする）\\n→ I have visited Kyoto three times.（回数なら現在完了でよい）\\n\\n■ 時・条件を表す文の中では未来も現在形\\nif や when で始まる文の中は、未来のことでも will を使わない。\\n例）If it is sunny tomorrow, we will go to the park.（If it will be sunny ~ は誤り）\\n　　I will call you when I get home.\\n\\n★ ポイント：文の中に時を表す語を見つけたら、まずそれに線を引く。そのうえで動詞の形が合っているかを確かめる、という順で見ると速い。\",\"figureId\":\"lf_eigoext12_445\",\"mangaId\":\"eigo_s445_xm\"},{\"heading\":\"前置詞の抜けと余分\",\"body\":\"動詞と前置詞は一組で覚える。日本語では助詞が一つなのに、英語では前置詞が要る場合と要らない場合がある。\\n\\n■ 前置詞が必要な動詞（抜けやすい）\\nlisten to ~（〜を聞く）　　I listened to the radio.\\nwait for ~（〜を待つ）　　I waited for the bus.\\nlook for ~（〜をさがす）　I am looking for my key.\\nlook at ~（〜を見る）　　 Look at that bird.\\narrive at ~（〜に着く）　 We arrived at the station.\\ntalk to / talk with ~（〜と話す）\\nbe good at ~（〜が得意だ）\\n\\n■ 前置詞が不要な語（つけすぎやすい）\\nhome, here, there, abroad, downtown は副詞なので to をつけない。\\nI went to home.（誤）→ I went home.\\nCome to here.（誤）→ Come here.\\nまた discuss や enter は日本語に「について」「に」があっても前置詞をとらない場合がある。\\n\\n■ 時を表す前置詞\\n・at ＋ 時刻　at six, at noon\\n・on ＋ 曜日・日付　on Monday, on May 5\\n・in ＋ 月・季節・年　in April, in summer, in 2026\\n・yesterday, tomorrow, last night, next week には前置詞をつけない\\n　例）I met him last night.（in last night は誤り）\\n\\n⚠ 注意：get to ~（〜に着く）は前置詞が要るが、get home は要らない。arrive も arrive at the station だが arrive home となる。home が特別だと覚えておく。\"}],\"trapExamples\":[{\"question\":\"次の英文の誤りを一か所直しなさい。I have visited Kyoto last year.\",\"wrongAnswer\":\"I have visited to Kyoto last year.\",\"trapExplanation\":\"visit のあとに to が要ると思いこみ、そこを直してしまった。visit は前置詞をとらない動詞であり、本当の誤りは現在完了と last year がいっしょに使われていることである。\",\"correctAnswer\":\"I visited Kyoto last year.\",\"correctExplanation\":\"現在完了は「過去から今まで」の幅を表すので、last year のような過去の一点を表す語とは使えない。last year を残すなら過去形の visited にする。現在完了を残すなら I have visited Kyoto three times. のようにする。\"},{\"question\":\"次の英文の誤りを一か所直しなさい。I went to home at six yesterday.\",\"wrongAnswer\":\"I went to my home at six yesterday.\",\"trapExplanation\":\"「to のあとに名詞が必要だ」と考えて my を足してしまった。home がこの文では名詞ではなく「家へ」という意味の副詞であることに気づいていない。\",\"correctAnswer\":\"I went home at six yesterday.\",\"correctExplanation\":\"home, here, there, abroad は「〜へ」の意味をすでに含んだ副詞なので to をつけない。同じく get home, come home も前置詞なしで使う。一方 go to school, go to the park は名詞なので to が必要である。\"}]}",
"{\"id\":\"eigo_s446\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"リスニング①：先読みと設問の型\",\"description\":\"放送が始まる前に選択肢を読み、何を聞き取るべきかを決めておく方法\",\"intro\":\"リスニングは、放送が始まってから考えていては間に合いません。勝負は始まる前です。選択肢を先に読み、時刻が並んでいるのか場所なのかを見ておけば、何を待ちかまえて聞けばよいかが決まります。その準備のしかたを学びます。\",\"order\":946,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"放送前に選択肢を読み、共通点と相違点に印をつける。\",\"選択肢が時刻なら時間、場所なら場所、人物なら人名を待ちかまえて聞く。\",\"会話では予定が途中で変わることが多い。最初に出た数字に飛びつかない。\",\"数量の問題は「かけ算・たし算をさせる」ことが多い。\",\"一問終わったらすぐ次の設問を先読みする。\"],\"sections\":[{\"heading\":\"先読みでやること\",\"body\":\"リスニングは、放送が始まってから考えていては間に合わない。放送前の数十秒でどれだけ準備できるかで得点が決まる。\\n\\n■ 選択肢の共通点と相違点に印をつける\\nア 3:00　イ 3:30　ウ 4:00　エ 4:30\\n→ すべて時刻なので「時刻を聞き取る問題」だとわかる。しかも三時台と四時台が並んでいるので、放送の中で「時刻が変更される」可能性が高い。\\n\\nア at the station　イ at the library　ウ at school　エ at the park\\n→ 場所を聞き取る問題。場所を表す語が出たら印をつける。\\n\\n■ 設問文があるなら必ず先に読む\\nWhat time will they meet?（何時に会うか）\\nWhere will they go first?（最初にどこへ行くか）\\nHow many pens did she buy?（何本買ったか）\\nWhy was Ken late?（なぜ遅れたか）\\n設問の疑問詞を見れば、聞き取るべき情報の種類が一つに決まる。\\n\\n■ 聞きながらメモする\\n選択肢の横に、聞こえた数字や語をそのまま書く。頭の中だけで処理しようとしない。\\n\\n★ ポイント：選択肢がすべて同じ種類（全部時刻、全部場所）なら、その情報だけを待ちかまえて聞けばよい。それ以外の部分は聞き取れなくてもかまわない。\",\"figureId\":\"xf_eigo_s446\"},{\"heading\":\"会話は「途中で変わる」\",\"body\":\"リスニングの会話問題は、最初に出た情報がそのまま答えになることはほとんどない。必ずどこかで変更や修正が入る。\\n\\n■ 予定が変わる型\\nＡ：Let's meet at three.\\nＢ：Sorry, I have a piano lesson until three thirty. How about four?\\nＡ：OK. See you then.\\n問）What time will they meet?\\n→ 答えは 4:00。最初に聞こえた three に飛びつくと誤る。\\n\\n■ 変更の合図になる語\\nbut / sorry / actually / How about ~ ? / Let's ~ instead / I changed my mind\\nこれらが聞こえたら、その直後に本当の答えがある。\\n\\n■ 計算させる型\\nＡ：I bought two pens. Each pen was 150 yen.\\n問）How much did she pay?\\n→ 150 × 2 ＝ 300円。放送の中に 300 という数字は出てこない。\\n\\nＡ：The movie starts at two and it is two hours long.\\n問）What time will the movie end?\\n→ 4時。\\n\\n⚠ 注意：数字が二つ以上聞こえたら、たし算・かけ算・引き算のどれかを求められている可能性を疑う。メモには数字だけでなく「2本」「1本150円」のように単位も書いておく。\",\"mangaId\":\"eigo_s446_xm\"}],\"trapExamples\":[{\"question\":\"放送を聞いて答えなさい。Ａ：Let's meet at three. Ｂ：Sorry, I have a piano lesson until three thirty. How about four? Ａ：OK.　問：What time will they meet?\",\"wrongAnswer\":\"3時\",\"trapExplanation\":\"最初に聞こえた at three をそのまま答えにしてしまった。会話の後半で予定が変更されていることを聞き逃している。放送の早い段階で答えが決まると思いこむのが原因。\",\"correctAnswer\":\"4時\",\"correctExplanation\":\"Sorry や How about ~ ? は予定変更の合図である。三時にはピアノのレッスンがあるので、Ｂが提案した four に決まり、Ａが OK と答えている。時刻を表す語が二つ以上出てきたら、最後に合意された時刻を答える。\"},{\"question\":\"放送を聞いて答えなさい。Ａ：I bought two pens at the shop. Each pen was 150 yen.　問：How much did she pay?\",\"wrongAnswer\":\"150円\",\"trapExplanation\":\"放送の中に聞こえた数字 150 をそのまま答えにしてしまった。two pens という数を聞き取っていても、かけ算が必要だと気づいていない。\",\"correctAnswer\":\"300円\",\"correctExplanation\":\"each は「一つあたり」という意味なので、150円が一本の値段である。二本買っているので 150 × 2 ＝ 300円。数字が二つ聞こえたら計算を疑い、メモに「2本」「1本150円」と単位まで書いておくとまちがえない。\"}]}",
"{\"id\":\"eigo_s447\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"リスニング②：数字と固有名詞のメモ\",\"description\":\"聞きまちがえやすい数字の聞き分けと、人名・地名を取りちがえないメモの取り方\",\"intro\":\"thirteen と thirty は、聞き分けられますか。ちがいはアクセントの位置で、thirteen は後ろ、thirty は前が強く読まれます。14と40、15と50も同じ関係です。数字と名前をどうメモするかまで含めて練習します。\",\"order\":947,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"moshi\",\"keyPoints\":[\"thirteen は後ろ、thirty は前にアクセントがある。\",\"14と40、15と50、16と60 も同じ形で聞き分ける。\",\"メモは英語で書かず、日本語と数字で速く書く。\",\"人名は頭文字（K, T）だけ書けば十分。\",\"だれが何をしたのかを取りちがえないよう、人名と情報を線で結ぶ。\"],\"sections\":[{\"heading\":\"数字の聞き分け\",\"body\":\"リスニングでもっとも失点しやすいのが数字である。とくに「十三と三十」型の聞き分けは、毎年どこかの学校で出る。\\n\\n■ アクセントの位置で聞き分ける\\n・thirteen（サーティーン）… 後ろが強い　thir-TEEN\\n・thirty（サーティ）… 前が強い　THIR-ty\\n同じ関係が次の組にもある。\\nfourteen / forty　　fifteen / fifty　　sixteen / sixty\\nseventeen / seventy　　eighteen / eighty　　nineteen / ninety\\n\\n■ 語尾の音でも見分けられる\\n-teen は最後まで「ティーン」と長くのばす。-ty は「ティ」と短く切れる。\\n\\n■ 時刻の言い方\\n・seven thirty ＝ 7時30分\\n・seven fifteen ＝ 7時15分\\n・a quarter past seven ＝ 7時15分\\n・half past seven ＝ 7時30分\\n・ten to eight ＝ 8時10分前（7時50分）\\n・a quarter to eight ＝ 8時15分前（7時45分）\\n\\n■ 値段・電話番号\\n・one thousand five hundred yen ＝ 1500円\\n・電話番号は一けたずつ読む（090-1234-5678 は zero nine zero, one two three four ~）\\n\\n★ ポイント：放送で数字が聞こえたら、意味を考える前にまず数字だけをメモする。意味づけはあとでできる。\",\"mangaId\":\"eigo_s447_xm\"},{\"heading\":\"メモの取り方\",\"body\":\"メモを英語で書こうとすると、書いている間に次の情報を聞き逃す。メモは自分だけがわかればよいので、日本語と数字と記号で書く。\\n\\n■ メモの原則\\n①英語で書かない　　　　「サッカー」ではなく「サ」でもよい\\n②人名は頭文字だけ　　　Ken → K、Tom → T、Emily → E\\n③矢印と記号を使う　　　「K → 図書館」「T ×来ない」\\n④数字は必ず単位つき　　「150円/本」「2本」\\n\\n■ だれが何をするのかを取りちがえない\\nＡ：I'm going to Osaka this weekend. How about you?\\nＢ：I'm going to Okayama to see my grandmother.\\nメモ例）Ａ→大阪　Ｂ→岡山（祖母）\\nOsaka と Okayama は音が似ているうえ、二人の行き先が入れかわりやすい。話し手ごとに行を分けて書く。\\n\\n■ 聞き取れなかったところは飛ばす\\n一語にこだわると、そのあと全部が聞こえなくなる。空欄のままにして先へ進む。\\n\\n■ 二回放送されるとき\\n一回目は全体をつかみ、二回目でメモの空欄を埋める。一回目からすべて書き取ろうとしない。\\n\\n⚠ 注意：メモは答えではない。放送が終わったら、メモを見ながら設問の疑問詞（What time / Where / How many）に合う情報を選んで答える。\",\"figureId\":\"xf_eigo_s447\"}],\"trapExamples\":[{\"question\":\"放送を聞いて答えなさい。The next bus leaves at seven thirty.　問：バスは何時に出発するか。\",\"wrongAnswer\":\"7時13分\",\"trapExplanation\":\"thirty と thirteen の音が似ているため、聞き分けられずに thirteen だと思ってしまった。数字は意味がわかった気になりやすく、確かめずに書いてしまう。\",\"correctAnswer\":\"7時30分\",\"correctExplanation\":\"thirty は前を強く読む（THIR-ty）、thirteen は後ろを強く読む（thir-TEEN）。また -teen はのばし、-ty は短く切れる。時刻として言うときは seven thirty ＝ 7時30分。7時13分なら seven thirteen になる。\"},{\"question\":\"放送を聞いて答えなさい。Ａ：I'm going to Osaka this weekend. Ｂ：Really? I'm going to Okayama to see my grandmother.　問：Where will Ｂ go?\",\"wrongAnswer\":\"大阪\",\"trapExplanation\":\"Osaka と Okayama は音が似ているうえ、最初に聞こえた地名の印象が強く残る。だれがどちらへ行くのかを分けてメモしていないため、二人の情報が混ざってしまう。\",\"correctAnswer\":\"岡山\",\"correctExplanation\":\"設問は Ｂ の行き先を聞いている。Ｂのせりふ I am going to Okayama ~ が答えの根拠になる。話し手ごとに行を分けて「Ａ→大阪／Ｂ→岡山（祖母に会う）」とメモすれば取りちがえない。\"}]}",
"{\"id\":\"eigo_s448\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"総合実戦演習①：英語選択入試（標準）\",\"description\":\"語形変化・並べかえ・和文英訳・条件英作文を通しで解き、答案の作り方を確かめる\",\"intro\":\"ここまで学んだ語形変化・並べかえ・和文英訳・条件英作文は、実際の入試では一枚の問題用紙に並んで出てきます。一つずつなら解けても、通しで解くと時間が足りなくなるものです。本番と同じ形で力を確かめてみましょう。\",\"order\":948,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"語形変化の問題は、まず時制の手がかり語をさがす。\",\"並べかえは動詞→主語→目的語→修飾語の順で組む。\",\"和文英訳は知っている語だけで書く。難しい語は言いかえる。\",\"条件英作文は条件を指さして一つずつ確認してから書き始める。\",\"解き終えたら三単現・冠詞・複数形の三点だけを見直す。\"],\"sections\":[{\"heading\":\"第1問・第2問（語形変化と並べかえ）\",\"body\":\"■ 第1問　（　）内の語を正しい形に直しなさい。\\n(1) My sister （go） to school by bus every day.\\n(2) I （visit） my uncle in Tokyo last summer.\\n(3) Look! The children （play） in the park now.\\n(4) He is good at （swim）.\\n(5) Kyoto is one of the most beautiful （city） in Japan.\\n\\n【解答】\\n(1) goes　… every day があるので現在形。主語 My sister は三人称単数なので es をつける。\\n(2) visited　… last summer があるので過去形。\\n(3) are playing　… Look! と now があるので現在進行形。主語 The children は複数なので are。\\n(4) swimming　… 前置詞 at のあとなので動名詞。m を重ねる。\\n(5) cities　… one of the ~ のあとは複数形。y を i に変えて es。\\n\\n■ 第2問　［　］内の語を並べかえなさい。\\n(1)「私はきのう公園で野球をしました」\\n　［ baseball / in / played / the park / I / yesterday ］\\n(2)「彼がどこに住んでいるか知っていますか」\\n　［ know / where / do / you / lives / he ］\\n(3)「この箱は重すぎて私には運べません」\\n　［ heavy / this box / to / is / carry / too ］\\n\\n【解答】\\n(1) I played baseball in the park yesterday.（場所→時の順）\\n(2) Do you know where he lives?（間接疑問なので肯定文の語順）\\n(3) This box is too heavy to carry.（too ～ to … の型）\",\"figureId\":\"xf_eigo_s448\"},{\"heading\":\"第3問・第4問（和文英訳と条件英作文）\",\"body\":\"■ 第3問　次の日本語を英語にしなさい。\\n(1) 私の父は毎朝六時に起きます。\\n(2) その本は机の上にあります。\\n(3) あなたは何時に夕食を食べますか。\\n(4) きのうは雨だったので、私たちは家にいました。\\n\\n【解答例】\\n(1) My father gets up at six every morning.\\n　　… 習慣なので現在形。三人称単数なので gets。at ＋ 時刻。\\n(2) The book is on the desk.\\n　　… the がついているので There is は使えない。名詞自身を主語にする。\\n(3) What time do you have dinner?\\n　　… What time ＋ do ＋ 主語 ＋ 原形。dinner に the はつけない。\\n(4) It was rainy yesterday, so we stayed home.\\n　　… 天気は it が主語。so で結果をつなぐ。home に to は不要。\\n\\n■ 第4問　次の問いに、五語以上の英語で答えなさい。\\nWhat do you usually do on Sundays?\\n\\n【解答例】\\nI usually play soccer with my friends in the park.\\n　… I(1) usually(2) play(3) soccer(4) with(5) my(6) friends(7) in(8) the(9) park(10) で10語。条件を満たす。\\n\\n⚠ 注意：第4問で I play soccer.（3語）と書くと、内容は正しくても語数不足で0点になる。答えを書いたら必ず語を数え、条件を満たしているかを確かめてから次へ進む。\",\"mangaId\":\"eigo_s448_xm\"}],\"trapExamples\":[{\"question\":\"第1問(5)　Kyoto is one of the most beautiful （city） in Japan. の（　）内を正しい形に直しなさい。\",\"wrongAnswer\":\"city\",\"trapExplanation\":\"「京都は一つの都市だ」と考えて単数のままにしてしまった。one of ~ という型が「〜のうちの一つ」という意味であることを読み取れていない。\",\"correctAnswer\":\"cities\",\"correctExplanation\":\"one of ＋ the ＋ 最上級 ＋ 複数名詞、で「もっとも〜な…のうちの一つ」を表す。複数あるものの中の一つを指すので、名詞は必ず複数形になる。city は子音＋y なので y を i に変えて cities とする。\"},{\"question\":\"第3問(4)　「きのうは雨だったので、私たちは家にいました」を英語にしなさい。\",\"wrongAnswer\":\"Yesterday was rain, so we stayed at home.\",\"trapExplanation\":\"「きのうは」を主語だと考えて Yesterday was ~ としてしまった。また rain という名詞をそのまま補語に置いている。stayed at home は誤りではないが、前半の誤りで大きく減点される。\",\"correctAnswer\":\"It was rainy yesterday, so we stayed home.\",\"correctExplanation\":\"天気を表す文の主語は it にし、rain は形容詞の rainy に変える。yesterday は文の後ろに置く。stay home でも stay at home でもよいが、go home には to をつけない点と混同しないこと。\"}]}",
"{\"id\":\"eigo_s449\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"総合実戦演習②：帰国子女入試（記述中心）\",\"description\":\"まとまった量の英作文と読解記述が出る入試を想定し、書く量と正確さを両立させる\",\"intro\":\"帰国子女入試では、六十語程度の英作文や、本文にもとづく記述が求められます。短い答えを積み上げる入試とは、必要な力がちがいます。書く量と正確さを両立させるには型が要ります。その型を実際の問題で試します。\",\"order\":949,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"六十語程度の英作文は「意見→理由①＋具体例→理由②＋具体例→まとめ」の五〜六文。\",\"読解の記述は本文の語をそのまま借りて答えると正確になる。\",\"設問が英語なら英語で、日本語なら日本語で答える。\",\"書き出しの語（First, Second, For example, However）で流れを見せる。\",\"時間の半分で書き上げ、残りで見直す配分にする。\"],\"sections\":[{\"heading\":\"第1問　英作文（六十語程度）\",\"body\":\"問）Some people say that students should study at home. Others say that students should study at the library. Which do you think is better? Write about 60 words.\\n\\n【模範解答】\\nI think studying at the library is better than studying at home. First, the library is quiet, so I can concentrate on my homework. At home, my little brother often talks to me, and I cannot finish my work. Second, there are many books in the library. When I do not understand something, I can look for the answer right away. For these reasons, I like studying at the library.\\n\\n（約70語。文の数＝6文）\\n\\n【組み立て】\\n①意見　I think studying at the library is better ~ .\\n②理由①　First, the library is quiet, so ~ .\\n③理由①の具体例　At home, my little brother often talks to me ~ .\\n④理由②　Second, there are many books in the library.\\n⑤理由②の具体例　When I do not understand something, ~ .\\n⑥まとめ　For these reasons, ~ .\\n\\n★ ポイント：六十語は四文では足りない。理由それぞれに具体例を一文ずつ足して六文にすると、ちょうどよい長さになる。\",\"figureId\":\"xf_eigo_s449\"},{\"heading\":\"第2問　読解と記述\",\"body\":\"【本文】\\nKen is a junior high school student. Last summer, he went to Australia and stayed with the Smith family for two weeks. At first, he could not speak English well, and he was very nervous. But Mr. Smith always spoke to him slowly and helped him. After a few days, Ken began to enjoy talking with the family. When he came back to Japan, he decided to study English harder.\\n\\n【設問と解答】\\n(1) How long did Ken stay in Australia?\\n　→ He stayed there for two weeks.\\n　… 本文の for two weeks をそのまま使う。答えの文は He で始める。\\n\\n(2) Why was Ken nervous at first?\\n　→ Because he could not speak English well.\\n　… Why には Because で答える。本文の語をそのまま借りる。\\n\\n(3) ケンが日本に帰ってから決めたことを、日本語で答えなさい。\\n　→ 英語をもっと一生けんめい勉強しようということ。\\n　… 設問が日本語なので日本語で答える。harder は「もっと一生けんめいに」。\\n\\n(4) 本文の内容に合うものを一つ選びなさい。\\n　ア Ken went to Australia with his family.\\n　イ Mr. Smith spoke to Ken slowly.\\n　ウ Ken could speak English well from the beginning.\\n　→ イ　… 本文の Mr. Smith always spoke to him slowly and helped him. に対応する。アは家族と行ったとは書かれていない。ウは本文と反対。\\n\\n⚠ 注意：英語で答える設問に日本語で答える、日本語で答える設問を英語で答える、という取りちがえは毎年多い。設問文の書かれている言語をまず確かめる。\",\"mangaId\":\"eigo_s449_xm\"}],\"trapExamples\":[{\"question\":\"第2問(1)　How long did Ken stay in Australia? に英語で答えなさい。\",\"wrongAnswer\":\"Last summer.\",\"trapExplanation\":\"How long を「いつ」の意味だと取りちがえ、本文の Last summer をそのまま答えにしてしまった。How long は期間の長さをたずねる表現である。\",\"correctAnswer\":\"He stayed there for two weeks.\",\"correctExplanation\":\"How long は期間、When は時期をたずねる。本文の for two weeks が答えの根拠になる。For two weeks. とだけ答えてもよいが、He stayed there for two weeks. と一文で書くほうが確実に得点できる。\"},{\"question\":\"第2問(3)　ケンが日本に帰ってから決めたことを、日本語で答えなさい。\",\"wrongAnswer\":\"He decided to study English harder.\",\"trapExplanation\":\"本文の英語をそのまま抜き出して答えてしまった。前後の設問が英語で答える形式だったため、設問文が日本語に変わったことに気づいていない。\",\"correctAnswer\":\"英語をもっと一生けんめい勉強しようということ。\",\"correctExplanation\":\"設問が日本語で書かれているときは日本語で答える。根拠は本文最終文の he decided to study English harder である。harder は hard の比較級で「もっと一生けんめいに」の意味になる。\"}]}",
"{\"id\":\"eigo_s450\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"総合実戦演習③：直前総まとめと時間配分\",\"description\":\"入試当日の解く順序・時間配分・見直しの手順を決め、点を落とさない答案にする\",\"intro\":\"同じ実力でも、解く順番と時間配分で点数は変わります。リスニングだけは自分で時間を選べないので、それ以外をどう並べるかが勝負です。英作文と見直しの時間をどう確保するか、当日の段取りをここで決めておきます。\",\"order\":950,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"nyushi\",\"keyPoints\":[\"リスニングは自分で時間を調整できない。それ以外で配分を作る。\",\"解く順序は「語彙・文法→リスニング→読解→英作文」が基本。\",\"英作文には必ず十分、見直しには五分を残す。\",\"わからない問題は空欄にせず、必ず何か書く。\",\"見直しは三単現・冠詞・複数形・時制・つづりの五点だけ。\"],\"sections\":[{\"heading\":\"当日の時間配分\",\"body\":\"試験時間五十分の入試を想定した配分の目安を決めておく。当日その場で考えると必ず時間が足りなくなる。\\n\\n■ 配分の目安\\n・リスニング　10分（放送の時間で決まる。調整できない）\\n・語彙・文法　 5分（短時間で確実に取る）\\n・読解　　　　20分\\n・英作文　　　10分\\n・見直し　　　 5分\\n\\n■ 解く順序\\n①放送前に、語彙・文法の問題を一気に片づける（放送が始まったら中断する）\\n②リスニング\\n③読解\\n④英作文\\n⑤見直し\\n\\nリスニングは開始直後に放送されることが多いので、その前の待ち時間に問題冊子全体をながめ、英作文にどんな問題が出ているかだけ確かめておく。頭の片すみで考えながら他の問題を解ける。\\n\\n■ 時間が足りなくなったら\\n英作文を捨ててはいけない。配点が大きいので、一文でも書く。逆に読解の最後の一問は捨ててもよい。\\n\\n★ ポイント：時計は問題を解き始める前に見る。「読解に入るのは何時何分か」を先に決めておくと、遅れに気づける。\",\"figureId\":\"lf_eigoext12_450\",\"mangaId\":\"eigo_s450_xm\"},{\"heading\":\"最後の見直しリスト\",\"body\":\"見直しは項目を決めて、機械的に通す。内容を考え直すと時間が足りなくなる。\\n\\n■ 英作文の見直し五点\\n①三単現の s　　主語が he / she / it / 単数の人名で現在の話なら、動詞に s\\n②名詞の s　　　二つ以上なら s、一つなら a / an / the\\n③冠詞　　　　　by bike, play soccer, go to school には冠詞をつけない\\n④時制　　　　　yesterday があるのに現在形になっていないか\\n⑤つづり　　　　friend / because / beautiful / favorite / restaurant / school\\n\\n■ 形式の見直し三点\\n・文の最初は大文字か\\n・文の終わりにピリオドがあるか（疑問文はクエスチョンマーク）\\n・語数指定を満たしているか\\n\\n■ 空欄を作らない\\n選択問題は必ずどれかを選ぶ。記号問題で迷ったら、本文に出てきた語をそのまま含む選択肢は誤りであることが多い（言いかえてある選択肢が正解になりやすい）。\\n英作文は、短くてもよいので必ず一文書く。I like summer because I can swim. だけでも部分点がつく。\\n\\n■ 前日と当日にやること\\n前日は新しい問題に手を出さず、これまで書いた英作文の型と、覚えた言い回しの引き出しを読み返す。当日の朝は、不規則動詞の変化表と、まちがえやすいつづりを見る。\\n\\n⚠ 注意：見直しで英文をまるごと書き直すと、新しい誤りが生まれることが多い。直すのは明らかな誤りだけにとどめる。\"}],\"trapExamples\":[{\"question\":\"試験終了五分前になり、英作文がまだ書けていない。どうすべきか。\",\"wrongAnswer\":\"時間が足りないので英作文は空欄のままにし、読解の残りの設問を解く。\",\"trapExplanation\":\"解ける問題から片づけるという考え方は正しいが、英作文は配点が大きく、部分点もつきやすい。空欄では必ず0点になるという点を見落としている。\",\"correctAnswer\":\"短くてもよいので、意見と理由を一つずつ、二文だけでも書く。\",\"correctExplanation\":\"英作文は語数が足りなくても、正しい英文が書けていれば部分点がつくことが多い。I like summer. I can swim in the sea. のような二文でも0点にはならない。読解の一問より英作文の部分点のほうが大きい。\"},{\"question\":\"見直しの時間に、自分の英作文 I have two brother and they plays soccer. を読み返した。どこを直すべきか。\",\"wrongAnswer\":\"I have two brothers and they plays soccer.（brother だけを直す）\",\"trapExplanation\":\"名詞の複数形の誤りに気づいて満足し、そこで見直しをやめてしまった。一文に誤りが二つ以上あることを想定していない。\",\"correctAnswer\":\"I have two brothers, and they play soccer.\",\"correctExplanation\":\"誤りは二か所ある。two のあとの名詞は複数形 brothers、主語 they は複数なので動詞に s はつけず play にする。見直しは「一か所直したら終わり」ではなく、五つの項目をすべて通す。\"}]}",
"{\"id\":\"eigo_s451\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音と文字①：二文字で一つの音（sh・ch・th・ph・wh）\",\"description\":\"二つの文字が合わさって別の音になる組み合わせを覚える\",\"intro\":\"アルファベットは一文字ずつ音をもっていますが、二文字が合わさると、まったくちがう音になることがあります。覚える組み合わせは6つだけです。\",\"order\":951,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"sh は「シュ」に近い音。ship、fish、she。\",\"ch は「チ」に近い音。chair、lunch、cheese。\",\"th には二つの音がある。this のにごる音と、think のにごらない音。\",\"ph は f と同じ音になる。phone、elephant。\",\"wh は「ホワ」に近い音。white、what、when。\",\"ck は語の終わりで k の音になる。black、duck。\"],\"sections\":[{\"heading\":\"おぼえる組み合わせ\",\"body\":\"■ sh\\nシュに近い音。\\nship（船）／fish（魚）／she（かのじょ）／shop（店）／wash（あらう）\\n\\n■ ch\\nチに近い音。\\nchair（いす）／lunch（昼食）／cheese（チーズ）／chicken（にわとり）／teacher（先生）\\n\\n■ th\\n二つの音がある。\\n・にごる音：this（これ）／that（あれ）／they（かれら）／mother（お母さん）\\n・にごらない音：think（考える）／three（3）／month（月）／bath（ふろ）\\nどちらも、舌の先を上と下の歯ではさんで出す音である。\\n\\n■ ph\\nf と同じ音になる。\\nphone（電話）／photo（写真）／elephant（ぞう）／alphabet（アルファベット）\\n\\n■ wh\\nホワに近い音。たずねる言葉の多くがこれで始まる。\\nwhat（何）／when（いつ）／where（どこ）／which（どちら）／white（白い）／why（なぜ）\\n※ who（だれ）だけは「フー」と読む。w の音が出ない。\\n\\n■ ck\\n語の終わりで k の音になる。\\nblack（黒い）／duck（あひる）／clock（時計）／rock（岩）／back（うしろ）\\n\\n★ ポイント：二文字で一つの音になる組み合わせは、切りはなして読まない。sh を「エス・エイチ」ではなく、まとめて一つの音として読む。\",\"figureId\":\"xf_eigo_s451\"},{\"heading\":\"練習と気をつけること\",\"mangaId\":\"eigo_s451_manga\",\"body\":\"■ 読む練習\\n次の語を、二文字のかたまりに気をつけて読む。\\nshop／chair／think／phone／white／clock\\n\\n■ 書く練習\\n音を聞いて、どの組み合わせかを選ぶ。\\n・「シュ」の音が聞こえたら sh\\n・「チ」の音が聞こえたら ch\\n・「フ」の音でも、f のときと ph のときがある\\n\\n■ まちがえやすいところ\\n・ch は「チ」だが、school、Christmas では「ク」の音になる\\n・th の二つの音は、日本語にない音なので、口の形をまねて練習する\\n・wh の who だけは例外\\n\\n■ 語のはじめと終わり\\n・sh、ch は語のはじめにも終わりにも来る（ship、fish／chair、lunch）\\n・ck は語のはじめには来ない（語の終わりに来ることが多く、chicken のように語の中に来ることもある）\\n・ph は語のどこにでも来る（phone、alphabet、graph）\\n\\n■ おぼえ方\\n同じかたまりをもつ語を、3つずつ並べて書くと覚えやすい。\\nsh：ship、shop、fish\\nch：chair、chicken、lunch\\nth：this、think、three\\n\\n⚠ 注意：th を「ス」や「ズ」だけで覚えると、think と sink、this と ジス の区別がつかなくなる。舌を歯ではさむ、という動きをセットで覚えること。\"}],\"trapExamples\":[{\"question\":\"who の wh は、white や what と同じ音ですか。\",\"wrongAnswer\":\"同じ音である。どちらも wh で始まるから。\",\"trapExplanation\":\"同じつづりなら同じ音だと考えてしまう。who だけは例外である。\",\"correctAnswer\":\"ちがう。who は「フー」と読み、w の音が出ない。\",\"correctExplanation\":\"wh で始まる語の多くは white、what、when のように「ホワ」に近い音になるが、who だけは「フー」と読む。同じように whose、whole も「フ」の音で始まる。例外として一つずつ覚えておくこと。\"},{\"question\":\"school の ch は「チ」の音ですか。\",\"wrongAnswer\":\"ch なので「チ」の音である。\",\"trapExplanation\":\"ch はいつも「チ」だと決めつけてしまう。語によっては「ク」の音になる。\",\"correctAnswer\":\"ちがう。school の ch は「ク」の音である。\",\"correctExplanation\":\"ch は chair や lunch のように「チ」と読むことが多いが、school、Christmas、stomach などでは「ク」の音になる。数は多くないので、出てきたときに一つずつ覚えるとよい。\"}]}",
"{\"id\":\"eigo_s452\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音と文字②：r のついた母音（ar・er・ir・or・ur）\",\"description\":\"母音の後ろに r が来たときの、日本語にない音を身につける\",\"intro\":\"母音の後ろに r が来ると、音が変わります。car、bird、turn の音は、日本語にはありません。まとまりごと覚えるのがいちばん速い方法です。\",\"order\":952,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"ar は「アー」に近い音。car、park、star。\",\"or は「オー」に近い音。short、morning、fork。\",\"er、ir、ur は同じ「アー」に近い音になる。\",\"er の例：teacher、sister、water。\",\"ir の例：bird、girl、first。\",\"ur の例：turn、nurse、Thursday。\"],\"sections\":[{\"heading\":\"おぼえる組み合わせ\",\"body\":\"■ ar\\n「アー」に近い音。口を大きく開ける。\\ncar（車）／park（公園）／star（星）／card（カード）／farm（農場）／dark（暗い）\\n\\n■ or\\n「オー」に近い音。\\nshort（短い）／morning（朝）／fork（フォーク）／sport（スポーツ）／north（北）／horse（馬）\\n\\n■ er・ir・ur は同じ音\\n三つとも、あいまいな「アー」の音になる。つづりがちがっても、音は同じである。\\n・er：teacher（先生）／sister（姉妹）／water（水）／winter（冬）／computer\\n・ir：bird（鳥）／girl（女の子）／first（一番目の）／shirt（シャツ）／thirty（30）\\n・ur：turn（まわる）／nurse（看護師）／Thursday（木曜日）／purple（むらさき）\\n\\n同じ音なのにつづりが三通りあるので、書くときはつづりを一つずつ覚えるしかない。\\n\\n■ 語の終わりの er\\n人を表すことが多い。\\nteach（教える）→ teacher（先生）\\nplay（遊ぶ）→ player（選手）\\nsing（歌う）→ singer（歌手）\\nfarm（農場）→ farmer（農場主）\\n\\n■ 気をつけること\\n・r は日本語のラ行とはちがう音。舌を口の中で丸めるようにする\\n・ar と or の区別は、口の開け方でつける\\n\\n★ ポイント：er・ir・ur は音が同じ。聞いただけではつづりが決まらないので、語ごとに書いて覚える。\",\"figureId\":\"xf_eigo_s452\",\"mangaId\":\"eigo_s452_xm\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 読む練習\\ncar／park／short／teacher／bird／turn\\n\\n■ 書く練習\\n同じ音の語を、つづりのグループに分けて書く。\\ner：teacher、sister、water\\nir：bird、girl、first\\nur：turn、nurse、Thursday\\n\\n■ 意味とセットで覚える\\n・park（公園）と part（部分）\\n・first（一番目）と fast（速い）\\n・short（短い）と shot（打つこと）\\nつづりが似ている語は、意味もいっしょに覚えると混ざらない。\\n\\n■ 数を表す語\\nthirteen（13）／thirty（30）／thirty-one（31）\\nどれも ir を使う。three（3）とつづりがちがうので注意する。\\n\\n■ 曜日\\nThursday（木曜日）の ur。Tuesday（火曜日）とまちがえやすい。\\n・Tuesday は火曜日\\n・Thursday は木曜日\\nどちらも T で始まるので、2番目の文字で見分ける。\\n\\n⚠ 注意：er・ir・ur は音が同じなので、聞いて書く問題では正しいつづりを選べない。語ごとに形を覚えておくこと。\"}],\"trapExamples\":[{\"question\":\"bird、girl、first はどのつづりのなかまですか。\",\"wrongAnswer\":\"er のなかま。音が「アー」だから。\",\"trapExplanation\":\"音が同じなのでつづりも同じだと考えてしまう。er・ir・ur は音が同じでつづりがちがう。\",\"correctAnswer\":\"ir のなかま\",\"correctExplanation\":\"bird、girl、first、shirt、thirty はすべて ir を使う。teacher、sister、water は er、turn、nurse、Thursday は ur である。音は三つとも同じなので、語ごとにつづりを覚えるしかない。書いて覚えるのがいちばん確実である。\"},{\"question\":\"thirteen（13）と three（3）は、同じつづりの部分をもっていますか。\",\"wrongAnswer\":\"どちらも th で始まる数なので、つづりの部分も同じである。\",\"trapExplanation\":\"どちらも th で始まる数なので、つづりも同じだと思ってしまう。母音の部分がちがう。\",\"correctAnswer\":\"ちがう。three は ee、thirteen は ir を使う。\",\"correctExplanation\":\"three は th＋r＋ee、thirteen は th＋ir＋teen である。13、30 は ir を使い、3 は ee を使う。thirteen と thirty は ir でそろっているので、この二つをセットで覚えると混ざらない。\"}]}",
"{\"id\":\"eigo_s453\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音と文字③：二つの母音がならぶとき\",\"description\":\"oi・oy・ou・ow・au・aw などの組み合わせを音でとらえる\",\"intro\":\"母音が二つならぶと、一つの音になったり、すべるような音になったりします。よく出る組み合わせを、語といっしょに覚えましょう。\",\"order\":953,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"oi と oy は「オイ」に近い音。coin、boy。\",\"ou と ow は「アウ」に近い音になることがある。house、cow。\",\"ow は「オウ」に近い音になることもある。snow、window。\",\"au と aw は「オー」に近い音。autumn、saw。\",\"oo には長い音と短い音がある。food と book。\",\"同じつづりでも語によって音がちがうことがあるので、語ごとに覚える。\"],\"sections\":[{\"heading\":\"おぼえる組み合わせ\",\"body\":\"■ oi・oy\\n「オイ」に近い音。\\n・oi は語の中に：coin（コイン）／point（点）／oil（油）／voice（声）\\n・oy は語の終わりに：boy（男の子）／toy（おもちゃ）／enjoy（楽しむ）\\n\\n■ ou・ow（アウの音）\\nhouse（家）／mouse（ねずみ）／out（外へ）／about（〜について）\\ncow（牛）／now（今）／how（どのように）／flower（花）／town（町）\\n\\n■ ow（オウの音）\\n同じ ow でも、別の音になることがある。\\nsnow（雪）／window（まど）／yellow（黄色）／know（知っている）／slow（おそい）\\nどちらの音かは、語ごとに覚える。\\n\\n■ au・aw\\n「オー」に近い音。\\nautumn（秋）／August（8月）\\nsaw（のこぎり、see の過去形）／draw（絵をかく）／straw（ストロー）\\n\\n■ oo\\n二つの音がある。\\n・長い「ウー」：food（食べ物）／school（学校）／moon（月）／room（部屋）\\n・短い「ウ」：book（本）／look（見る）／good（よい）／foot（足）\\n\\n■ ea\\n・長い「イー」：eat（食べる）／read（読む）／sea（海）／teacher（先生）\\n・短い「エ」：bread（パン）／head（頭）／ready（準備ができた）\\n\\n★ ポイント：同じつづりでも二つの音があるものがある。oo と ea と ow の三つがその代表である。\",\"figureId\":\"xf_eigo_s453\",\"mangaId\":\"eigo_s453_xm\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 音で分ける練習\\noo の長い音と短い音を、二つのグループに分けて書く。\\n長い：food、school、moon、room\\n短い：book、look、good、foot\\n\\n■ 読みまちがえやすい語\\n・cow（牛、アウ）と snow（雪、オウ）\\n・read の現在形（イー）と過去形（エ）は、つづりが同じで音がちがう\\n・live は「住む」なら短い音、「生きている」の意味の形容詞なら長い音\\n\\n■ セットで覚える語\\n・house と mouse（アウ）\\n・boy と toy（オイ）\\n・book と look と good（短いウ）\\n・snow と window と yellow（オウ）\\n同じ音の語をまとめて書くと、つづりも覚えやすい。\\n\\n■ 日本語にすると消える音\\n・oi の「オイ」は日本語にもあるので覚えやすい\\n・au、aw の「オー」は、日本語ののばす音とは少しちがう\\n\\n⚠ 注意：ow は「アウ」にも「オウ」にもなる。cow（アウ）と snow（オウ）を必ずセットで覚えて、どちらの音かを語ごとに確かめること。\"}],\"trapExamples\":[{\"question\":\"book と food の oo は同じ音ですか。\",\"wrongAnswer\":\"同じ oo なので、どちらも長い「ウー」の音である。\",\"trapExplanation\":\"同じつづりなら同じ音だと考えてしまう。oo には長い音と短い音がある。\",\"correctAnswer\":\"ちがう。book は短い「ウ」、food は長い「ウー」の音である。\",\"correctExplanation\":\"oo には二つの音がある。短い音は book、look、good、foot など。長い音は food、school、moon、room など。数が多くないので、それぞれのグループを3〜4語ずつ覚えておけば判断できる。\"},{\"question\":\"cow と snow の ow は同じ音ですか。\",\"wrongAnswer\":\"同じ ow なので、どちらも「オウ」である。\",\"trapExplanation\":\"つづりが同じなら音も同じだと思ってしまう。ow は語によって音が変わる。\",\"correctAnswer\":\"ちがう。cow は「アウ」、snow は「オウ」の音である。\",\"correctExplanation\":\"ow には「アウ」の音（cow、now、how、town、flower）と「オウ」の音（snow、window、yellow、know、slow）がある。つづりだけでは決まらないので、語ごとに覚える。cow と snow を対にして覚えておくと、どちらの音かを思い出しやすい。\"}]}",
"{\"id\":\"eigo_s454\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数字③：順番を表す言い方と日付\",\"description\":\"1番目・2番目という言い方を覚え、日付が言えるようにする\",\"intro\":\"「1つ」と「1番目」は、英語ではちがう言い方をします。日付を言うときはこの「1番目」の形を使うので、あわせて覚えてしまいましょう。\",\"order\":954,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"順番を表す言い方は、多くの場合 数字に th をつける。\",\"1番目・2番目・3番目だけは形がちがう。first、second、third。\",\"5番目は fifth、9番目は ninth、12番目は twelfth と、つづりが変わる。\",\"20番目は twentieth、30番目は thirtieth。y を ie に変えて th をつける。\",\"日付は、この順番の言い方を使う。\",\"数字で書くときは 1st、2nd、3rd、4th のように、最後の2文字をそえる。\"],\"sections\":[{\"heading\":\"言い方をおぼえる\",\"body\":\"■ 基本は th をつける\\nfour → fourth（4番目）\\nsix → sixth（6番目）\\nseven → seventh（7番目）\\nten → tenth（10番目）\\neleven → eleventh（11番目）\\n\\n■ 形が変わるもの\\none → first（1番目）\\ntwo → second（2番目）\\nthree → third（3番目）\\nfive → fifth（5番目）\\neight → eighth（8番目）\\nnine → ninth（9番目。e が消える）\\ntwelve → twelfth（12番目。ve が f に変わる）\\ntwenty → twentieth（20番目。y が ie になる）\\nthirty → thirtieth（30番目）\\n\\n■ 21番目から\\n一の位だけを順番の形にする。\\ntwenty-one → twenty-first（21番目）\\ntwenty-two → twenty-second（22番目）\\ntwenty-three → twenty-third（23番目）\\nthirty-one → thirty-first（31番目）\\n\\n■ 数字で書くとき\\n1st、2nd、3rd、4th、5th、…、11th、12th、13th、…、21st、22nd、23rd、…、31st\\n最後の2文字をそえる。11th、12th、13th は first、second、third の形にならないので th をつける。\\n\\n■ 日付の言い方\\n月 → 日 の順で言う。\\n・May 5th（5月5日）\\n・July 20th（7月20日）\\n・January 1st（1月1日）\\n書くときは May 5 のように数字だけでもよいが、読むときは fifth と読む。\\n\\n■ たずね方と答え方\\nWhat's the date today?（今日は何日ですか）\\nIt's October 10th.（10月10日です）\\n\\n★ ポイント：1・2・3だけ特別、あとは th。この一言で、ほとんどの数がつくれる。\",\"figureId\":\"xf_eigo_s454\"},{\"heading\":\"練習と気をつけること\",\"mangaId\":\"eigo_s454_manga\",\"body\":\"■ 言ってみる\\n・自分のたん生日を英語で言う\\n　My birthday is April 3rd.\\n・今日の日付を言う\\n　Today is June 15th.\\n\\n■ 順番を使う言い方\\n・the first day（最初の日）\\n・the second floor（2階）\\n・the third question（3番目の問題）\\n順番を表す語の前には、ふつう the をつける。\\n\\n■ 月の名前\\nJanuary（1月）／February（2月）／March（3月）／April（4月）／May（5月）／June（6月）\\nJuly（7月）／August（8月）／September（9月）／October（10月）／November（11月）／December（12月）\\n月の名前は、いつも大文字で書き始める。\\n\\n■ まちがえやすいところ\\n・ninth は nine から e が消える\\n・twelfth は twelve の ve が f に変わる\\n・twentieth は twenty の y が ie になる\\n・13th は thirteenth（thirteen ＋ th）\\n\\n■ 曜日との組み合わせ\\nSunday, May 5th（5月5日 日曜日）\\n曜日 → 月 → 日 の順に書くことが多い。\\n\\n⚠ 注意：日本語は「5月5日」と月から言うが、日付の数字は順番の形（fifth）で読む。「ファイブ」ではなく「フィフス」と読むこと。\"}],\"trapExamples\":[{\"question\":\"9番目を英語で書きなさい。\",\"wrongAnswer\":\"nineth\",\"trapExplanation\":\"nine にそのまま th をつけてしまった。9番目は e が消える。\",\"correctAnswer\":\"ninth\",\"correctExplanation\":\"nine から e を取って th をつけ、ninth となる。同じように形が変わるのは、five → fifth、twelve → twelfth、twenty → twentieth である。この4つだけ特別だと覚えておけばよい。\"},{\"question\":\"「4月21日」を英語で書きなさい。\",\"wrongAnswer\":\"April 21th\",\"trapExplanation\":\"一の位が1なのに th をつけてしまった。21は first の形になる。\",\"correctAnswer\":\"April 21st\",\"correctExplanation\":\"21は twenty-first なので、数字では 21st と書く。同じように 22nd（twenty-second）、23rd（twenty-third）、31st（thirty-first）となる。ただし 11th、12th、13th は例外で、th をつける。一の位だけを見て決めること。\"}]}",
"{\"id\":\"eigo_s455\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時こくの言い方\",\"description\":\"何時何分をたずねる言い方と、答え方の型を覚える\",\"intro\":\"時こくの言い方には、数字をそのまま読む言い方と、「〜分すぎ」「〜分前」という言い方があります。まずは数字をそのまま読む形から覚えましょう。\",\"order\":955,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"時こくをたずねるときは What time is it?。\",\"答えは It's で始める。It's seven.（7時です）\",\"ちょうどの時こくは o'clock をつけてもよい。It's seven o'clock.\",\"何時何分は、時 → 分 の順に数字を読む。It's seven thirty.\",\"30分は half past ~、15分は a quarter past ~ とも言う。\",\"「〜時に」は at をつける。at seven（7時に）\"],\"sections\":[{\"heading\":\"言い方をおぼえる\",\"body\":\"■ たずね方\\nWhat time is it?（今、何時ですか）\\nWhat time is it now? と now をつけてもよい。\\n\\n■ 答え方（基本）\\nIt's で始める。\\n・It's seven.（7時です）\\n・It's seven o'clock.（7時ちょうどです）\\no'clock はちょうどの時こくのときだけ使う。7時30分に o'clock はつけない。\\n\\n■ 何時何分\\n時 → 分 の順に、数字をそのまま読む。\\n・It's seven thirty.（7時30分）\\n・It's eight fifteen.（8時15分）\\n・It's nine forty-five.（9時45分）\\n・It's ten oh five.（10時5分）\\n　分が1けたのときは、0を oh（オウ）と読む。\\n\\n■ 別の言い方\\n・half past seven（7時半）\\n・a quarter past eight（8時15分）\\n・a quarter to nine（9時15分前＝8時45分）\\npast は「すぎ」、to は「前」。小4のうちは、まず数字をそのまま読む形を確実にする。\\n\\n■ 時こくを表す文\\n・I get up at six.（わたしは6時に起きます）\\n・School starts at eight thirty.（学校は8時30分に始まります）\\n・Let's meet at three.（3時に会いましょう）\\n「〜時に」と言うときは at をつける。\\n\\n■ 午前と午後\\n・in the morning（午前中に）\\n・in the afternoon（午後に）\\n・at night（夜に）\\n・a.m.（午前）／p.m.（午後）\\n\\n★ ポイント：答えはいつも It's で始める。時こくの it は「それ」という意味ではなく、決まった言い方である。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 読む練習\\n6:00 → It's six.（It's six o'clock.）\\n7:15 → It's seven fifteen.\\n8:30 → It's eight thirty.\\n9:45 → It's nine forty-five.\\n10:05 → It's ten oh five.\\n\\n■ 一日の生活を言ってみる\\nI get up at six thirty.（6時30分に起きます）\\nI have breakfast at seven.（7時に朝ごはんを食べます）\\nI go to school at eight.（8時に学校へ行きます）\\nI go to bed at nine thirty.（9時30分にねます）\\n\\n■ たずね方いろいろ\\n・What time do you get up?（何時に起きますか）\\n　→ I get up at six.\\n・What time does the movie start?（映画は何時に始まりますか）\\n　→ It starts at four.\\n\\n■ まちがえやすいところ\\n・o'clock はちょうどのときだけ\\n・答えの主語は it。I is ~ や This is ~ とはしない\\n・「〜時に」は at。in や on は使わない\\n\\n■ 曜日・日付との前置詞のちがい\\n・時こく → at（at seven）\\n・曜日・日付 → on（on Monday、on May 5th）\\n・月・年・季節 → in（in May、in 2026、in summer）\\nこの三つは、次の単元でもくわしく学ぶ。\\n\\n⚠ 注意：7時30分を It's seven thirty o'clock. とは言わない。o'clock はちょうどの時こくだけにつける。\"},{\"heading\":\"なぜ答えは It's で始め、なぜ o'clock はちょうどのときだけなのか\",\"mangaId\":\"eigo_s455_manga\",\"body\":\"英語の文には必ず主語が要ります。「7時です」には「何が」にあたることばがないので、**形をそろえるための It** を主語に置きます。この It は「それ」という意味ではなく、天気や曜日を言うときと同じ決まった言い方です。I is 〜 や This is 〜 とはしません。「〜時に」に at を使うのは、時こくが時計の針が一か所を指す**点**だからで、幅のある月や季節には in、日には on を使います。\\n\\no'clock は「〜時ちょうど」という意味のことばです。だから分があるとき（seven thirty）には付けられません。分が1けたのときに 0 を oh と読む（ten oh five）のは、時こくを数字の並びとして読む決まりです。past・to の言い方は、まず数字をそのまま読む形を確実にしてから覚えます。\\n\\n■ 確かめのしかた\\n①答えが **It's** で始まっているか。What time is it?→It's seven.\\n②**ちょうどのときだけ o'clock**。It's seven o'clock.／It's seven thirty.（× seven thirty o'clock）。\\n③時→分の順に数字を読む。分が1けたなら oh（It's ten oh five.）。\\n④「〜時に」は **at**（I get up at six.）。曜日・日付は on、月・年・季節は in。× I get up in seven.\\n\\n★ ここがポイント：時こくの文は**主語が無いので It's で形をそろえる**。o'clock は**ちょうどのときだけ**。「〜時に」は時こくが**点**なので at。\",\"figureId\":\"xf_eigo_s455\"}],\"trapExamples\":[{\"question\":\"「8時45分です」を英語で言いなさい。\",\"wrongAnswer\":\"It's eight forty-five o'clock.\",\"trapExplanation\":\"o'clock をいつでもつけられると考えてしまう。o'clock はちょうどの時こくだけに使う。\",\"correctAnswer\":\"It's eight forty-five.\",\"correctExplanation\":\"o'clock は「ちょうど〜時」という意味なので、分があるときにはつけない。It's eight forty-five. または a quarter to nine（9時15分前）と言う。ちょうど8時なら It's eight o'clock. と言える。\"},{\"question\":\"「わたしは7時に起きます」を英語で言いなさい。\",\"wrongAnswer\":\"I get up in seven.\",\"trapExplanation\":\"時を表す語をすべて in だと考えてしまう。時こくには at を使う。\",\"correctAnswer\":\"I get up at seven.\",\"correctExplanation\":\"時こくには at、曜日や日付には on、月や年や季節には in を使う。at seven（7時に）、on Monday（月曜日に）、in May（5月に）と、それぞれ対にして覚えること。\"}]}",
"{\"id\":\"eigo_s456\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"英語を書くときのきまり\",\"description\":\"大文字・ピリオド・語と語の間など、書き方の決まりを覚える\",\"intro\":\"英語の文には、日本語にない決まりがあります。文の最初は大文字、終わりはピリオド。数は少ないので、ここで覚えてしまえば一生使えます。\",\"order\":956,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"文の最初の文字は、必ず大文字で書く。\",\"文の終わりにはピリオド（.）をつける。\",\"たずねる文の終わりにはクエスチョンマーク（?）をつける。\",\"I（わたしは）は、文のどこにあっても大文字で書く。\",\"人の名前・地名・曜日・月の名前は、いつも大文字で書き始める。\",\"語と語の間は、必ず一つ分あける。\"],\"sections\":[{\"heading\":\"書き方のきまり\",\"body\":\"■ 大文字で書き始めるもの\\n・文の最初の文字\\n　This is my book.\\n・I（わたしは）\\n　Tom and I are friends.（文のとちゅうでも大文字）\\n・人の名前\\n　Ken／Mary／Mr. Brown\\n・地名・国名\\n　Japan／Tokyo／America\\n・曜日\\n　Sunday／Monday／Tuesday\\n・月の名前\\n　January／February／March\\n・言語や国の人を表す語\\n　English／Japanese\\n\\n日本語では曜日や月を特別に書き分けないので、忘れやすい。\\n\\n■ 文の終わりの記号\\n・ふつうの文 → ピリオド（.）\\n　I like dogs.\\n・たずねる文 → クエスチョンマーク（?）\\n　Do you like dogs?\\n・強い気持ちを表す文 → エクスクラメーションマーク（!）\\n　Look!／Wow!\\n\\n■ 語と語の間\\n必ず一つ分あける。日本語のようにつめて書かない。\\n誤：Ilikedogs.\\n正：I like dogs.\\n\\n■ コンマ（,）\\n・三つ以上ならべるとき\\n　I like apples, oranges, and bananas.\\n・呼びかけのあと\\n　Hello, Ken.\\n・曜日と日付の間\\n　Sunday, May 5th\\n\\n■ アポストロフィ（'）\\n・短くした形\\n　I am → I'm／is not → isn't／it is → it's\\n・「〜の」を表すとき\\n　Ken's book（ケンの本）\\n\\n★ ポイント：「文の最初は大文字、終わりはピリオド」。この二つを外すと、正しく書けていても減点される。\",\"figureId\":\"xf_eigo_s456\",\"mangaId\":\"eigo_s456_xm\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 直してみる\\n誤：i like music\\n正：I like music.\\n（I を大文字に、最後にピリオド）\\n\\n誤：do you play soccer\\n正：Do you play soccer?\\n（最初を大文字に、最後にクエスチョンマーク）\\n\\n誤：my birthday is may 5th\\n正：My birthday is May 5th.\\n（最初と月の名前を大文字に）\\n\\n■ 4本線に書くとき\\n・大文字は上の3本を使う\\n・小文字は多くが真ん中の2本の中に入る\\n・b、d、f、h、k、l、t は上にのびる\\n・g、j、p、q、y は下にのびる\\n\\n■ まちがえやすい文字\\n・b と d（丸の向きがちがう）\\n・p と q\\n・大文字の I と小文字の l（アイとエル）\\n・数字の1と小文字の l\\n\\n■ 見直しのしかた\\n書き終えたら、次の順で確かめる。\\n①文の最初は大文字か\\n②最後にピリオドかクエスチョンマークがあるか\\n③I は大文字か\\n④名前・曜日・月の名前は大文字か\\n⑤語と語の間はあいているか\\n\\n⚠ 注意：たずねる文にピリオドをつけてしまう失点が多い。Do や What で始まる文は、クエスチョンマークで終わる。\"}],\"trapExamples\":[{\"question\":\"「わたしはケンです」を英語で正しく書きなさい。\",\"wrongAnswer\":\"i am ken\",\"trapExplanation\":\"大文字とピリオドの決まりを両方落としている。I と人の名前は必ず大文字である。\",\"correctAnswer\":\"I am Ken.\",\"correctExplanation\":\"I は文のどこにあっても大文字、人の名前 Ken も大文字で書き始める。そして文の終わりにはピリオドをつける。この3点を確かめる習慣をつけると、書く問題での失点がなくなる。\"},{\"question\":\"「あなたはサッカーが好きですか」を英語で正しく書きなさい。\",\"wrongAnswer\":\"Do you like soccer.\",\"trapExplanation\":\"文の最初は大文字にできているが、終わりの記号がちがう。たずねる文はクエスチョンマークで終わる。\",\"correctAnswer\":\"Do you like soccer?\",\"correctExplanation\":\"Do や Does、What や Where で始まるたずねる文は、終わりにクエスチョンマーク（?）をつける。ピリオドをつけると、たずねる文であることが伝わらない。書き終えたら、文の種類と記号が合っているかを確かめること。\"}]}",
"{\"id\":\"eigo_s457\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞①：「〜します」の文\",\"description\":\"be動詞ではない動きを表す語で、ふつうの文をつくれるようにする\",\"intro\":\"「わたしは学生です」は be動詞の文でした。「わたしはサッカーをします」のように、動きを表す文は別の形になります。ならべる順番は同じです。\",\"order\":957,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"動きや気持ちを表す語を一般動詞という。play、like、go、eat など。\",\"文の形は 主語 → 動詞 → そのほか の順にならべる。\",\"I play soccer.（わたしはサッカーをします）\",\"be動詞（am・is・are）と一般動詞は、同じ文の中にならべない。\",\"「〜が好きです」は like を使う。I like dogs.\",\"日本語と語順がちがう。英語は「だれが → どうする → 何を」の順。\"],\"sections\":[{\"heading\":\"文のつくり方\",\"body\":\"■ 一般動詞とは\\n動きや気持ちを表す語。\\nplay（する・遊ぶ）／like（好きだ）／go（行く）／eat（食べる）／read（読む）／study（勉強する）／have（持っている）／want（ほしい）／run（走る）／swim（泳ぐ）\\n\\n■ ならべる順番\\n主語 → 動詞 → そのほか\\n・I play soccer.（わたしはサッカーをします）\\n・I like music.（わたしは音楽が好きです）\\n・You study English.（あなたは英語を勉強します）\\n・We eat lunch at twelve.（わたしたちは12時に昼食を食べます）\\n\\n日本語は「わたしは サッカーを します」の順だが、英語は「わたしは します サッカーを」の順になる。ここが最初のつまずきどころである。\\n\\n■ be動詞との区別\\n・be動詞（am・is・are）は「〜です」「〜がいる」を表す\\n　I am a student.（わたしは学生です）\\n・一般動詞は「〜します」を表す\\n　I play tennis.（わたしはテニスをします）\\n\\n同じ文の中に両方を入れてはいけない。\\n誤：I am play tennis.\\n正：I play tennis.\\n\\n■ よく使う文\\n・I like ~.（わたしは〜が好きです）\\n・I have ~.（わたしは〜を持っています）\\n・I want ~.（わたしは〜がほしいです）\\n・I go to ~.（わたしは〜へ行きます）\\n　go のあとには to をつける。go to school、go to the park\\n\\n■ 主語が you、we、they のとき\\n形は I のときと同じ。\\n・You like dogs.\\n・We play baseball.\\n・They study math.\\n\\n★ ポイント：英語は「だれが → どうする → 何を」。この順番を声に出しながら並べると、まちがえにくい。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 日本語から英語へ\\n・わたしはピアノをひきます。→ I play the piano.\\n　楽器には the をつける。\\n・わたしは犬が好きです。→ I like dogs.\\n　「犬が好き」は、ふつう複数形にする。\\n・わたしは毎日本を読みます。→ I read a book every day.\\n\\n■ 「〜へ行く」\\ngo のあとに to を入れる。\\n・I go to school.（学校へ行く）\\n・I go to the library.（図書館へ行く）\\nただし home には to をつけない。\\n・I go home.（家へ帰る）\\n\\n■ まちがえやすいところ\\n・be動詞と一般動詞を両方入れてしまう（I am play ~）\\n・語順を日本語のままにしてしまう（I soccer play）\\n・go to の to を落としてしまう\\n\\n■ よく使う語のならび\\n・at school（学校で）／at home（家で）\\n・every day（毎日）／every morning（毎朝）\\n・after school（放課後に）\\nこれらは文の終わりに置くことが多い。\\n・I play soccer after school.（放課後にサッカーをします）\\n\\n■ 3人称のときは形が変わる\\nHe や She が主語のときは、動詞の形が変わる。これは次の単元で学ぶ。\\n\\n⚠ 注意：like のあとに来る動物や食べ物は、ふつう複数形にする。I like dog. だと「犬の肉が好き」という意味になってしまう。I like dogs. が正しい。\"},{\"heading\":\"なぜ英語は「だれが→どうする→何を」の順で、なぜ am と play を並べないのか\",\"mangaId\":\"eigo_s457_manga\",\"body\":\"日本語は「わたしは サッカーを します」と、動作を最後に言います。英語は「わたしは します サッカーを」と、**だれが何をするかを先に言い、そのあとに相手を足す**ことばです。だから語順は主語→動詞→そのほか。この順を声に出しながら並べると、日本語のまま I soccer play と書く誤りが減ります。\\n\\nam・is・are（be動詞）は「〜です・〜がいる」を表す語で、play・like（一般動詞）は「〜します」を表す語です。一つの文には動詞が一つなので、I am play tennis. のように両方入れると、「です」と「します」が重なって意味が通りません。「です」の文なら be動詞、「します」の文なら一般動詞と分けます。go のあとに to が要るのは、go が「行く」という動きだけを表し、「どこへ」を表す語が別に必要だからです。home は「家へ」という意味をすでに持つので to を付けません。\\n\\n■ 確かめのしかた\\n①**だれが→どうする→何を**の順か。I play soccer.（× I soccer play.）\\n②文の中に動詞が一つか。× I am play tennis.→I play tennis.「です」なら be動詞、「します」なら一般動詞。\\n③go のあとに **to** があるか（go to school／go to the park）。home には付けない（go home）。\\n④楽器には the（play the piano）、好きなものは複数形（I like dogs. ／ I like dog. は犬の肉）。at school・every day・after school は文の終わりに。\\n\\n★ ここがポイント：英語は**だれが何をするかを先に言う**ので、主語→動詞→そのほか。**一つの文に動詞は一つ**なので be動詞と一般動詞を並べない。go は「どこへ」の to が要る（home は不要）。\",\"figureId\":\"xf_eigo_s457\"}],\"trapExamples\":[{\"question\":\"「わたしはサッカーをします」を英語で書きなさい。\",\"wrongAnswer\":\"I am play soccer.\",\"trapExplanation\":\"be動詞と一般動詞をならべてしまった。「〜します」の文に am は必要ない。\",\"correctAnswer\":\"I play soccer.\",\"correctExplanation\":\"be動詞（am・is・are）は「〜です」を表す語なので、「〜します」という動きの文には使わない。同じ文の中に be動詞と一般動詞を両方入れることはできない。「です」の文なら be動詞、「します」の文なら一般動詞、と分けて考えること。\"},{\"question\":\"「わたしは学校へ行きます」を英語で書きなさい。\",\"wrongAnswer\":\"I go school.\",\"trapExplanation\":\"go のあとの to を落としてしまった。「〜へ」を表す語が必要である。\",\"correctAnswer\":\"I go to school.\",\"correctExplanation\":\"go は「行く」という意味だけなので、「どこへ」を表すには to が必要である。go to school、go to the park、go to bed のように使う。ただし home は「家へ」という意味をすでにもっているので、go home と言い、to はつけない。\"}]}",
"{\"id\":\"eigo_s458\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞②：he・she のときは s がつく\",\"description\":\"主語が1人の他人のとき、動詞の形が変わることを覚える\",\"intro\":\"主語が he や she のとき、動詞のおしりに s がつきます。理由を考えるより、「he・she・it なら s」と形で覚えるのが近道です。\",\"order\":958,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が he、she、it、または1人・1つのものなら、動詞に s をつける。\",\"I、you、we、they のときは s をつけない。\",\"s、x、ch、sh、o で終わる動詞には es をつける。go → goes、watch → watches。\",\"子音字＋y で終わる動詞は、y を i に変えて es をつける。study → studies。\",\"have だけは形が変わる。have → has。\",\"名前（Ken、my father など）1人も、he や she と同じあつかいになる。\"],\"sections\":[{\"heading\":\"形の変え方\",\"mangaId\":\"eigo_s458_manga\",\"body\":\"■ s をつける主語\\nhe（かれ）／she（かのじょ）／it（それ）\\nそして、1人・1つを表す名前やもの。\\n・Ken plays tennis.（ケンはテニスをします）\\n・My mother cooks dinner.（母は夕食を作ります）\\n・The dog runs fast.（その犬は速く走ります）\\n\\n■ s をつけない主語\\nI／you／we／they、そして2人以上・2つ以上のもの。\\n・I play tennis.\\n・They play tennis.\\n・My friends play tennis.\\n\\n■ つけ方の決まり\\n①ふつうは s をつける\\n　play → plays／like → likes／run → runs／read → reads\\n\\n②s、x、ch、sh、o で終わる語は es をつける\\n　go → goes／do → does／watch → watches／wash → washes／teach → teaches\\n\\n③子音字＋y で終わる語は、y を i に変えて es\\n　study → studies／try → tries／carry → carries\\n　※母音字＋y はそのまま s。play → plays／enjoy → enjoys\\n\\n④have だけ特別\\n　have → has\\n\\n■ 例文\\n・He goes to school at eight.（かれは8時に学校へ行きます）\\n・She studies English every day.（かのじょは毎日英語を勉強します）\\n・My father watches TV after dinner.（父は夕食のあとテレビを見ます）\\n・Ken has a dog.（ケンは犬を飼っています）\\n\\n★ ポイント：「he・she・it なら s」。主語が1人か2人以上かを先に見てから、動詞を書く。\",\"figureId\":\"xf_eigo_s458\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 形を変える練習\\nplay → plays／go → goes／study → studies／have → has\\nwatch → watches／like → likes／teach → teaches／run → runs\\ncarry → carries／enjoy → enjoys／wash → washes／do → does\\n\\n■ 主語を見分ける練習\\n次の主語は s がつくか、つかないか。\\n・my brother → つく（1人）\\n・my brothers → つかない（2人以上）\\n・Tom and Ken → つかない（2人）\\n・the cat → つく（1ぴき）\\n・you → つかない\\n\\n■ まちがえやすいところ\\n・play は母音字＋y なので plays（playies としない）\\n・study は子音字＋y なので studies\\n・go は o で終わるので goes（gos としない）\\n・have は has（haves としない）\\n\\n■ 見直しのしかた\\n文を書いたら、次の順に確かめる。\\n①主語は1人・1つか\\n②そうなら動詞に s がついているか\\n③s か es か、y を i に変えるかは合っているか\\n\\n■ 日本語にはないきまり\\n日本語では「わたしはします」も「かれはします」も同じ形だが、英語では変わる。ここは英語特有のきまりなので、書くたびに確かめるくせをつける。\\n\\n⚠ 注意：主語が2人以上のときに s をつけてしまう誤りが多い。My friends plays ~ ではなく My friends play ~ である。主語の数を先に確かめること。\"}],\"trapExamples\":[{\"question\":\"「かのじょは毎日英語を勉強します」を英語で書きなさい。\",\"wrongAnswer\":\"She studys English every day.\",\"trapExplanation\":\"y をそのままにして s をつけてしまった。子音字＋y は、y を i に変えて es にする。\",\"correctAnswer\":\"She studies English every day.\",\"correctExplanation\":\"study は d（子音字）＋y なので、y を i に変えて es をつけ studies となる。同じ形は try → tries、carry → carries。一方 play は a（母音字）＋y なので、そのまま plays となる。y の前が母音字か子音字かを見ること。\"},{\"question\":\"「わたしの兄弟たちはサッカーをします」を英語で書きなさい。\",\"wrongAnswer\":\"My brothers plays soccer.\",\"trapExplanation\":\"主語が1人だと思って s をつけてしまった。brothers は2人以上なので s はつけない。\",\"correctAnswer\":\"My brothers play soccer.\",\"correctExplanation\":\"動詞に s をつけるのは、主語が1人・1つのときだけである。brothers は複数なので play のままでよい。主語のおしりに s がついているときは、動詞には s がつかない、と覚えておくと見分けやすい。\"}]}",
"{\"id\":\"eigo_s459\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞③：「〜しません」の文\",\"description\":\"don't と doesn't の使い分けと、動詞をもとの形にもどす決まりを学ぶ\",\"intro\":\"「しません」と言うときは、動詞の前に一語たすだけです。ただし、その一語のうしろでは、動詞がもとの形にもどります。ここがひっかかりやすいところです。\",\"order\":959,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が I、you、we、they のときは don't を動詞の前に置く。\",\"主語が he、she、it、1人・1つのときは doesn't を置く。\",\"don't や doesn't のうしろでは、動詞はもとの形になる（s をつけない）。\",\"don't は do not、doesn't は does not を短くした形。\",\"be動詞の文では not を be動詞のうしろに置く。I am not ~.\",\"一般動詞の文に am not や isn't は使わない。\"],\"sections\":[{\"heading\":\"文のつくり方\",\"mangaId\":\"eigo_s459_manga\",\"body\":\"■ 置く場所\\n動詞の前に置く。\\n・I don't play soccer.（わたしはサッカーをしません）\\n・You don't like natto.（あなたは納豆が好きではありません）\\n・We don't go to school on Sunday.（日曜日は学校へ行きません）\\n・He doesn't play soccer.（かれはサッカーをしません）\\n・She doesn't study math.（かのじょは数学を勉強しません）\\n\\n■ どちらを使うか\\n・I、you、we、they → don't\\n・he、she、it、1人・1つ → doesn't\\n\\n■ うしろの動詞はもとの形\\ndoesn't のうしろでは、s のついた形にしない。\\n誤：He doesn't plays soccer.\\n正：He doesn't play soccer.\\n誤：She doesn't studies English.\\n正：She doesn't study English.\\n\\ns は doesn't の中の does がすでに引き受けているので、動詞にはつけない。\\n\\n■ be動詞の文とのちがい\\nbe動詞の文では、be動詞のうしろに not を置く。\\n・I am not a student.（I'm not ~ とも書く）\\n・He is not a teacher.（He isn't ~）\\n・They are not students.（They aren't ~）\\n\\n一般動詞の文に isn't を使ってはいけない。\\n誤：He isn't play soccer.\\n正：He doesn't play soccer.\\n\\n■ 短くしない形\\n・don't ＝ do not\\n・doesn't ＝ does not\\nどちらで書いてもよいが、話すときは短くした形をよく使う。\\n\\n★ ポイント：doesn't のうしろの動詞は、s なしのもとの形。s の役目は does が引き受けているので、動詞に二重にはつけない。\",\"figureId\":\"xf_eigo_s459\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 文を作る練習\\n・わたしはピアノをひきません。→ I don't play the piano.\\n・かれは牛乳を飲みません。→ He doesn't drink milk.\\n・わたしたちはテレビを見ません。→ We don't watch TV.\\n・かのじょは犬を飼っていません。→ She doesn't have a dog.\\n　have は has にせず、そのまま have を使う。\\n\\n■ 見分けの練習\\n次の文に入るのは don't か doesn't か。\\n・I （　） like carrots. → don't\\n・My sister （　） like carrots. → doesn't\\n・They （　） like carrots. → don't\\n・Ken （　） like carrots. → doesn't\\n\\n■ まちがえやすいところ\\n・doesn't のうしろに s をつけてしまう\\n・一般動詞の文に isn't を使ってしまう\\n・have を has のままにしてしまう（doesn't have が正しい）\\n\\n■ 答え方で使う\\n・Do you like dogs? → No, I don't.\\n・Does he play tennis? → No, he doesn't.\\nたずねる文の答えでも使うので、セットで覚えておく。\\n\\n⚠ 注意：I'm not と I don't はちがう。I'm not a student.（学生ではありません）は be動詞の文、I don't study.（勉強しません）は一般動詞の文である。「です」の否定か「します」の否定かで使い分ける。\"}],\"trapExamples\":[{\"question\":\"「かれはテニスをしません」を英語で書きなさい。\",\"wrongAnswer\":\"He doesn't plays tennis.\",\"trapExplanation\":\"doesn't のうしろの動詞に s を残してしまった。doesn't がすでに s の役目をしている。\",\"correctAnswer\":\"He doesn't play tennis.\",\"correctExplanation\":\"doesn't の中の does が、主語が1人であることを表している。そのため、うしろの動詞はもとの形（play）にもどす。同じように He doesn't study ~、She doesn't have ~ となる。s の役目は does が引き受けているので、動詞に二重につけないこと。\"},{\"question\":\"「わたしは学生ではありません」を英語で書きなさい。\",\"wrongAnswer\":\"I don't a student.\",\"trapExplanation\":\"「です」の文なのに don't を使ってしまった。be動詞の文では not を be動詞のうしろに置く。\",\"correctAnswer\":\"I am not a student.（I'm not a student.）\",\"correctExplanation\":\"「〜です」の文は be動詞の文なので、am のうしろに not を置く。don't を使うのは「〜します」という一般動詞の文である。「です」の否定なら be動詞＋not、「します」の否定なら don't／doesn't、と分けて覚えること。\"}]}",
"{\"id\":\"eigo_s460\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一般動詞④：「〜しますか」とたずねる文\",\"description\":\"Do と Does を文の先頭に置き、答え方まで型で覚える\",\"intro\":\"たずねる文は、文の先頭に一語たすだけです。答え方も決まった形があるので、質問と答えをセットで覚えてしまいましょう。\",\"order\":960,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"主語が I、you、we、they のときは Do を文の先頭に置く。\",\"主語が he、she、it、1人・1つのときは Does を置く。\",\"Does のうしろでは、動詞はもとの形になる（s をつけない）。\",\"答えは Yes, ~ do. / No, ~ don't. の形にする。\",\"he、she のときは Yes, he does. / No, he doesn't. になる。\",\"文の終わりにはクエスチョンマーク（?）をつける。\"],\"sections\":[{\"heading\":\"文のつくり方\",\"body\":\"■ たずねる文の形\\nDo（Does）＋主語＋動詞 ＋そのほか ?\\n\\n・Do you like dogs?（あなたは犬が好きですか）\\n・Do they play baseball?（かれらは野球をしますか）\\n・Does he like dogs?（かれは犬が好きですか）\\n・Does your sister play the piano?（あなたのお姉さんはピアノをひきますか）\\n\\n■ どちらを使うか\\n・I、you、we、they → Do\\n・he、she、it、1人・1つ → Does\\n\\n■ うしろの動詞はもとの形\\nDoes のうしろでは s をつけない。\\n誤：Does he likes dogs?\\n正：Does he like dogs?\\n\\n■ 答え方\\nたずねる文で使った語をそのまま使って答える。\\n・Do you like dogs?\\n　→ Yes, I do.／No, I don't.\\n・Do they play baseball?\\n　→ Yes, they do.／No, they don't.\\n・Does he like dogs?\\n　→ Yes, he does.／No, he doesn't.\\n・Does your sister play the piano?\\n　→ Yes, she does.／No, she doesn't.\\n\\n答えるときは、名前ではなく he、she、they などに変える。\\n・Does Ken like soccer? → Yes, he does.\\n\\n■ be動詞の文とのちがい\\nbe動詞の文では、be動詞を先頭に出す。\\n・Are you a student? → Yes, I am.／No, I'm not.\\n・Is he a teacher? → Yes, he is.／No, he isn't.\\n\\n一般動詞の文に Are や Is を使ってはいけない。\\n誤：Are you like dogs?\\n正：Do you like dogs?\\n\\n★ ポイント：質問で Do を使ったら答えも do、Does を使ったら答えも does。形をそろえる。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 文を作る練習\\n・あなたはピアノをひきますか。→ Do you play the piano?\\n・かれは英語を勉強しますか。→ Does he study English?\\n・あなたのお母さんは料理をしますか。→ Does your mother cook?\\n・かれらは学校へ歩いて行きますか。→ Do they walk to school?\\n\\n■ 答える練習\\n・Do you have a dog? → Yes, I do.／No, I don't.\\n・Does she play tennis? → Yes, she does.／No, she doesn't.\\n・Do your friends like music? → Yes, they do.／No, they don't.\\n\\n■ まちがえやすいところ\\n・Does のうしろの動詞に s を残してしまう\\n・一般動詞の文に Are や Is を使ってしまう\\n・答えの do と does をそろえ忘れる\\n・クエスチョンマークを忘れる\\n\\n■ 名前を代名詞に変える\\n答えるときは、名前を he、she、they、it に変える。\\n・Does Ken like soccer? → Yes, he does.\\n・Does Mary play the piano? → Yes, she does.\\n・Do Ken and Mary study English? → Yes, they do.\\n\\n■ 少しくわしくたずねる\\n・Do you like dogs or cats?（犬とねこ、どちらが好きですか）\\n　この形には Yes／No では答えず、I like dogs. のように答える。\\n\\n⚠ 注意：Does he likes ~? としてしまう誤りが最も多い。Does を書いた時点で、うしろの動詞はもとの形と決まっている。\"},{\"heading\":\"なぜ Do のうしろは s なしで、なぜ答えの語をそろえるのか\",\"mangaId\":\"eigo_s460_manga\",\"body\":\"be動詞の文は、be動詞を先頭に出せばたずねる文になります（Are you 〜?）。一般動詞は先頭に出せないので、**「これからたずねます」という合図の語 Do を先頭に置きます**。主語が he・she・it・1人・1つのときは、その s の役目を Do が引き受けて Does になります。だから Does のうしろの動詞にはもう s は要りません。Does he likes 〜? は s が二重になっています。\\n\\n答えの語をそろえるのは、答えが**質問の動詞をくり返している**からです。Do you like music? への Yes, I do. は「Yes, I (like music)」の do です。Are you 〜? への Yes, I am. は am をくり返しています。Do でたずねられたのに Yes, I am. と答えると、何をくり返しているのか分からなくなります。答えるときに名前を he・she・they に変えるのも、同じ人を二度名前で呼ばないためです。\\n\\n■ 確かめのしかた\\n①主語が I・you・we・they→**Do**、he・she・it・1人・1つ→**Does**。\\n②Does のうしろの動詞が**もとの形**か。× Does she plays→Does she play。\\n③答えの語が質問とそろっているか。Do→do／don't、Does→does／doesn't、Are→am／are、Is→is。× Do you like music?→Yes, I am.\\n④答えでは名前を代名詞に（Does Ken 〜?→Yes, he does.）。文末に ? があるか。A or B? には Yes/No で答えない。\\n\\n★ ここがポイント：Do／Does は**たずねる合図の語**で、Does が s の役目を引き受けるので動詞は**もとの形**。答えは**質問の語をくり返す**ので Do→do、Are→am とそろえる。\",\"figureId\":\"xf_eigo_s460\"}],\"trapExamples\":[{\"question\":\"「かのじょはピアノをひきますか」を英語で書きなさい。\",\"wrongAnswer\":\"Does she plays the piano?\",\"trapExplanation\":\"Does を使ったのに、動詞に s を残してしまった。Does がすでに s の役目をしている。\",\"correctAnswer\":\"Does she play the piano?\",\"correctExplanation\":\"Does を文の先頭に置いたら、うしろの動詞はもとの形（play）にする。否定文の doesn't と同じ決まりである。答えは Yes, she does. または No, she doesn't. となる。\"},{\"question\":\"「Do you like music?」への答えとして正しいものはどれですか。\",\"wrongAnswer\":\"Yes, I am.\",\"trapExplanation\":\"be動詞の答え方を使ってしまった。Do でたずねられたら do で答える。\",\"correctAnswer\":\"Yes, I do.（または No, I don't.）\",\"correctExplanation\":\"たずねる文で使った語と、答えで使う語をそろえる。Do → do、Does → does、Are → am／are、Is → is である。Are you a student? なら Yes, I am. が正しい。何でたずねられたかを見てから答えること。\"}]}",
"{\"id\":\"eigo_s461\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"命令する文・さそう文\",\"description\":\"主語をつけずに始める文と、Let's の使い方を覚える\",\"intro\":\"「立ちなさい」「見て」のような文には、主語がありません。動詞から始めるだけです。いっしょにやろうとさそうときは、前に一語つけます。\",\"order\":961,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"命令する文は、主語を書かずに動詞から始める。Stand up.\",\"「〜しないで」と言うときは、動詞の前に Don't を置く。Don't run.\",\"ていねいに言うときは please をつける。Please sit down.\",\"please は文の終わりにつけてもよい。Sit down, please.\",\"「いっしょに〜しよう」は Let's ＋動詞のもとの形。Let's play soccer.\",\"be動詞の命令文は Be から始める。Be quiet.\"],\"sections\":[{\"heading\":\"文のつくり方\",\"body\":\"■ 命令する文\\n主語を書かず、動詞のもとの形から始める。\\n・Stand up.（立ちなさい）\\n・Sit down.（すわりなさい）\\n・Open your book.（本を開きなさい）\\n・Look at me.（わたしを見なさい）\\n・Listen carefully.（よく聞きなさい）\\n\\n■ 「〜しないで」\\n動詞の前に Don't を置く。\\n・Don't run.（走らないで）\\n・Don't talk.（話さないで）\\n・Don't be late.（おくれないで）\\n\\n■ ていねいに言う\\nplease をつける。\\n・Please open the window.（まどを開けてください）\\n・Open the window, please.（同じ意味。コンマをつける）\\n\\n■ be動詞の命令文\\nBe から始める。\\n・Be quiet.（静かにしなさい）\\n・Be careful.（気をつけて）\\n・Be kind to others.（人に親切にしなさい）\\nam・is・are ではなく、もとの形の be を使う。\\n\\n■ さそう文\\nLet's ＋動詞のもとの形。\\n・Let's play soccer.（サッカーをしよう）\\n・Let's go to the park.（公園へ行こう）\\n・Let's start.（始めよう）\\nLet's は Let us を短くした形である。\\n\\n答え方\\n・Yes, let's.（そうしよう）\\n・Sounds good.（いいね）\\n・Sorry, I can't.（ごめん、できない）\\n\\n■ 教室でよく使う言い方\\n・Stand up.／Sit down.\\n・Open your textbook.（教科書を開いて）\\n・Close your book.（本を閉じて）\\n・Raise your hand.（手をあげて）\\n・Repeat after me.（あとについて言って）\\n・Look at the blackboard.（黒板を見て）\\n\\n★ ポイント：命令する文は主語を書かない。動詞から始まっていたら、命令する文だと見分けられる。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 文を作る練習\\n・まどを閉めなさい。→ Close the window.\\n・ここで遊ばないで。→ Don't play here.\\n・静かにしてください。→ Please be quiet.\\n・いっしょに歌おう。→ Let's sing together.\\n\\n■ 命令する文とふつうの文のちがい\\n・You open the window.（あなたはまどを開けます）… ふつうの文\\n・Open the window.（まどを開けなさい）… 命令する文\\n主語があるかないかで見分ける。\\n\\n■ まちがえやすいところ\\n・命令する文に You をつけてしまう\\n・be動詞の命令文で Are quiet. としてしまう（正しくは Be quiet.）\\n・Let's のあとに to を入れてしまう（誤：Let's to play。正：Let's play）\\n・Don't のあとに s のついた形を使ってしまう\\n\\n■ ていねいさの順\\n・Open the window.（開けて）\\n・Please open the window.（開けてください）\\n・Can you open the window?（開けてもらえますか）\\n下にいくほどていねいになる。\\n\\n■ 標識やお知らせでもよく使う\\n・Don't touch.（さわらないで）\\n・Keep out.（入らないで）\\n・Be quiet.（お静かに）\\n\\n⚠ 注意：Let's のあとは、必ず動詞のもとの形が来る。Let's playing や Let's to play は誤りである。\"},{\"heading\":\"なぜ命令する文に主語がなく、なぜ Be quiet. なのか\",\"mangaId\":\"eigo_s461_manga\",\"body\":\"命令する文は、**目の前の相手（you）に向かって言う**ので、だれに言っているかは分かりきっています。だから主語を書かず、動詞から始めます。逆に言えば、動詞から始まる文を見たら命令する文だと分かります。動詞が「もとの形」なのは、主語が無いので主語に合わせて形を変える必要がないからです。be動詞のもとの形は be なので、「静かにしなさい」は Be quiet. です。am・is・are は主語に合わせて変わった形なので、主語のない命令文では使いません。\\n\\nLet's のあとに動詞のもとの形が来るのは、Let's が Let us（私たちに〜させて）を短くした形で、let のあとには動詞のもとの形を置く決まりがあるからです。Let's to play や Let's playing は誤りです。「〜しないで」は動詞の前に Don't を置き、Don't のあとも動詞のもとの形です。\\n\\n■ 確かめのしかた\\n①命令する文に **You** を付けていないか。動詞（もとの形）から始まっているか。\\n②be動詞の命令文は **Be**（Be quiet.／Be careful.）。× Are quiet.\\n③Let's のあとが**もとの形**か。Let's play soccer.（× Let's to play、× Let's playing）。\\n④ていねいさ：Open the window.→Please open the window.／Open the window, please.→Can you open the window? の順にていねいになる。Don't のあとももとの形。\\n\\n★ ここがポイント：命令する文は**目の前の you に言うので主語を書かず**、動詞は**もとの形**（be動詞は Be）。Let's は Let us なので、あとは**もとの形**。\",\"figureId\":\"xf_eigo_s461\"}],\"trapExamples\":[{\"question\":\"「静かにしなさい」を英語で書きなさい。\",\"wrongAnswer\":\"Are quiet.\",\"trapExplanation\":\"be動詞をそのまま使ってしまった。命令する文では、be動詞はもとの形の Be になる。\",\"correctAnswer\":\"Be quiet.\",\"correctExplanation\":\"命令する文では、動詞はいつももとの形を使う。be動詞のもとの形は be なので Be quiet. となる。同じように Be careful.（気をつけて）、Be kind.（親切にしなさい）となる。am・is・are は主語に合わせて変わった形なので、命令する文では使わない。\"},{\"question\":\"「いっしょにサッカーをしよう」を英語で書きなさい。\",\"wrongAnswer\":\"Let's playing soccer.\",\"trapExplanation\":\"Let's のあとの動詞の形をまちがえた。Let's のあとは、必ずもとの形が来る。\",\"correctAnswer\":\"Let's play soccer.\",\"correctExplanation\":\"Let's は Let us を短くした形で、そのあとには動詞のもとの形が続く。Let's playing や Let's to play とはしない。同じように Let's go.、Let's start.、Let's eat lunch. となる。\"}]}",
"{\"id\":\"eigo_s462\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"場所を表す語：in・on・under・by・near\",\"description\":\"ものがどこにあるかを表す語を、位置の絵で区別する\",\"intro\":\"「はこの中」「つくえの上」「いすの下」。日本語では「の」でつなぎますが、英語では場所ごとにちがう語を使います。位置で覚えましょう。\",\"order\":962,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"in は「〜の中に」。in the box、in the room。\",\"on は「〜の上に（くっついて）」。on the desk、on the wall。\",\"under は「〜の下に」。under the chair。\",\"by と near は「〜のそばに」。by the window、near the station。\",\"between は「〜の間に」、in front of は「〜の前に」。\",\"場所を表す語は、名詞の前に置く。\"],\"sections\":[{\"heading\":\"位置でおぼえる\",\"body\":\"■ in（〜の中に）\\nin the box（はこの中に）／in the bag（かばんの中に）／in the room（部屋の中に）／in Japan（日本に）\\n・The cat is in the box.（ねこははこの中にいます）\\n\\n■ on（〜の上に）\\n面にくっついているときに使う。\\non the desk（つくえの上に）／on the wall（かべに）／on the ceiling（天じょうに）\\n・The book is on the desk.（本はつくえの上にあります）\\nかべや天じょうも、くっついているので on を使う。\\n\\n■ under（〜の下に）\\nunder the chair（いすの下に）／under the tree（木の下に）\\n・The ball is under the chair.（ボールはいすの下にあります）\\n\\n■ by・near（〜のそばに）\\nby the window（まどのそばに）／near the station（駅の近くに）\\nby のほうが近く、near は少しはなれていてもよい。\\n\\n■ そのほか\\n・in front of（〜の前に）：in front of the school\\n・behind（〜のうしろに）：behind the door\\n・between（〜の間に）：between the chair and the desk\\n・over（〜の上のほうに、はなれて）：over the table\\n・next to（〜のとなりに）：next to the post office\\n\\n■ 文の中での使い方\\n・My pencil is in my pencil case.\\n・There is a cat under the table.（テーブルの下にねこがいます）\\n・Where is my bag? — It's on the chair.\\n\\n★ ポイント：in は中、on はくっついた面、under は下。この三つをまず確実にする。\",\"figureId\":\"xf_eigo_s462\"},{\"heading\":\"練習と気をつけること\",\"mangaId\":\"eigo_s462_manga\",\"body\":\"■ 言ってみる\\n・つくえの上に本があります。→ There is a book on the desk.\\n・かばんの中にペンがあります。→ There is a pen in my bag.\\n・いすの下にねこがいます。→ There is a cat under the chair.\\n\\n■ たずね方\\nWhere is ~?（〜はどこにありますか）\\n・Where is my cap? — It's on the bed.\\n・Where is the station? — It's near the park.\\n\\n■ まちがえやすいところ\\n・「かべに」は on the wall（in ではない）\\n・「木の下に」は under the tree\\n・「日本に住んでいます」は I live in Japan.\\n・「バスに乗って」は by bus（乗り物の手段は by）\\n\\n■ on のいろいろな使い方\\n・on the desk（つくえの上に）\\n・on Monday（月曜日に）\\n・on May 5th（5月5日に）\\n場所だけでなく、曜日や日付にも使う。\\n\\n■ in のいろいろな使い方\\n・in the box（はこの中に）\\n・in May（5月に）\\n・in summer（夏に）\\n・in 2026（2026年に）\\n\\n⚠ 注意：「つくえの上」を in the desk と書かない。in the desk だと「つくえの引き出しの中」という意味になる。表面にのっているなら on である。\"}],\"trapExamples\":[{\"question\":\"「本はつくえの上にあります」を英語で書きなさい。\",\"wrongAnswer\":\"The book is in the desk.\",\"trapExplanation\":\"in と on を取りちがえた。in は「中に」なので、引き出しの中という意味になってしまう。\",\"correctAnswer\":\"The book is on the desk.\",\"correctExplanation\":\"on は面にくっついていることを表すので、つくえの上にのっている場合は on を使う。in は「中に」なので、in the desk だと引き出しの中という意味になる。in は中、on はくっついた面、と絵で覚えること。\"},{\"question\":\"「かべに絵があります」の「かべに」は、in と on のどちらですか。\",\"wrongAnswer\":\"in。絵はかべの中にあるように見えるから。\",\"trapExplanation\":\"上にのっていないので in だと考えてしまう。on は「上」ではなく「くっついている」ことを表す。\",\"correctAnswer\":\"on（on the wall）\",\"correctExplanation\":\"on は面にくっついていることを表す語なので、かべや天じょうにも使う。There is a picture on the wall. が正しい。「上」という日本語にとらわれず、「くっついているか」で判断すること。\"}]}",
"{\"id\":\"eigo_s463\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"時を表す語：at・on・in\",\"description\":\"時こく・曜日・月で使い分ける三つの語を、大きさの順で覚える\",\"intro\":\"時を表す語は三つだけです。時こくは at、曜日と日付は on、月や季節や年は in。「せまい順に at・on・in」と覚えると忘れません。\",\"order\":963,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"at は時こくに使う。at seven、at noon。\",\"on は曜日と日付に使う。on Monday、on May 5th。\",\"in は月・季節・年に使う。in May、in summer、in 2026。\",\"範囲がせまい順に at → on → in となる。\",\"in the morning（午前中に）、at night（夜に）は決まった言い方。\",\"every day、tomorrow、today には、これらの語をつけない。\"],\"sections\":[{\"heading\":\"三つの使い分け\",\"body\":\"■ at（時こく・一点）\\n・at seven（7時に）\\n・at eight thirty（8時30分に）\\n・at noon（正午に）\\n・at night（夜に）\\n\\n■ on（曜日・日付）\\n・on Monday（月曜日に）\\n・on Sunday morning（日曜日の朝に）\\n・on May 5th（5月5日に）\\n・on my birthday（わたしのたん生日に）\\n\\n■ in（月・季節・年・長い時間）\\n・in May（5月に）\\n・in summer（夏に）\\n・in 2026（2026年に）\\n・in the morning（午前中に）\\n・in the afternoon（午後に）\\n\\n■ せまい順にならべる\\nat（時こく）→ on（日）→ in（月・季節・年）\\n指し示す時間が短いほど at、長いほど in になる。\\n\\n■ 決まった言い方\\n・in the morning（午前中に）\\n・in the afternoon（午後に）\\n・in the evening（夕方に）\\n・at night（夜に）\\nnight だけ at を使う。ここは例外として覚える。\\n\\n■ 語をつけないもの\\nevery day（毎日）／today（今日）／tomorrow（明日）／yesterday（きのう）／this morning（今朝）／next week（来週）\\nこれらには at、on、in をつけない。\\n誤：in every day\\n正：every day\\n\\n■ 例文\\n・I get up at six.（6時に起きます）\\n・I play tennis on Saturday.（土曜日にテニスをします）\\n・My birthday is in June.（たん生日は6月です）\\n・It's cold in winter.（冬は寒いです）\\n・I study English every day.（毎日英語を勉強します）\\n\\n★ ポイント：「at は時こく、on は日、in は月から上」。三段階で覚える。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 入れてみる\\n・I go to bed （　） nine. → at\\n・We have a party （　） Sunday. → on\\n・It snows （　） winter. → in\\n・School starts （　） April. → in\\n・I have a piano lesson （　） Wednesday. → on\\n・I eat lunch （　） twelve. → at\\n\\n■ 組み合わさるとき\\n日付と曜日がいっしょに出るときは on を使う。\\n・on Sunday, May 5th\\n\\n朝・昼・夜でも、日付がつくと on になる。\\n・in the morning（朝に）\\n・on Monday morning（月曜日の朝に）\\n\\n■ まちがえやすいところ\\n・at night（夜に）だけ at。in the night とはあまり言わない\\n・every day には何もつけない\\n・on time（時間どおりに）、in time（間に合って）は決まった言い方\\n\\n■ 場所を表す at・on・in との関係\\n場所でも同じ考え方が使える。\\n・at the station（駅で。一点）\\n・on the desk（つくえの上に。面）\\n・in the room（部屋の中に。空間）\\n時でも場所でも「点 → 面 → 中」の順になっている。\\n\\n⚠ 注意：日本語の「〜に」はすべて同じだが、英語では at・on・in を使い分ける。時こくか、日か、月かを先に決めてから語を選ぶこと。\"},{\"heading\":\"なぜ「せまい順に at・on・in」なのか\",\"mangaId\":\"eigo_s463_manga\",\"body\":\"at・on・in は、場所を表すときの意味がそのまま時にも使われています。at は「一点で」（at the station）、on は「面に触れて」（on the desk）、in は「中に」（in the room）。時に当てはめると、時こくは時計の針が一か所を指す**点**なので at、日は一日という**面**なので on、月・季節・年は**中に入っている広い幅**なので in。だから「点→面→中」の順に at・on・in と並び、せまい順に覚えると忘れません。\\n\\nnight だけ at なのは、昔から夜を「活動する幅」ではなく一日の区切りの「点」のように扱ってきた習慣です。every day・today・tomorrow に前置詞を付けないのは、これらの語がそれ自体で「いつ」を表しているからです。日本語の「〜に」はどれも同じですが、英語では時こくか、日か、月かを先に決めてから語を選びます。\\n\\n■ 確かめのしかた\\n①「〜に」の中身が**時こく（点）か、日（面）か、月から上（幅）か**を言う。at nine／on Sunday／in April。\\n②朝・午後・夕方は in the 〜、夜だけ at night。日が決まると on が勝つ（on Monday morning）。\\n③every day・today・tomorrow・yesterday・this morning・next week に前置詞を付けていないか（× in every day）。\\n④場所でも同じ順（at the station／on the desk／in the room）。決まった言い方（on time・in time）は形ごと覚える。\\n\\n★ ここがポイント：at は**点**、on は**面**、in は**中**で、場所と同じ意味が時にも使われている。だから**時こく→日→月**の順に at・on・in。every day には付けない。\",\"figureId\":\"xf_eigo_s463\"}],\"trapExamples\":[{\"question\":\"「わたしは日曜日に公園へ行きます」の「日曜日に」に入る語はどれですか。\",\"wrongAnswer\":\"in（in Sunday）\",\"trapExplanation\":\"時を表す語をすべて in だと考えてしまう。曜日には on を使う。\",\"correctAnswer\":\"on（on Sunday）\",\"correctExplanation\":\"曜日と日付には on を使う。I go to the park on Sunday. が正しい。時こくなら at seven、月なら in May である。「at は時こく、on は日、in は月から上」と三段階で覚えること。\"},{\"question\":\"「わたしは毎日英語を勉強します」の「毎日」に前置詞は必要ですか。\",\"wrongAnswer\":\"必要である。in every day と書く。\",\"trapExplanation\":\"時を表す言葉には必ず前置詞がつくと考えてしまう。every day にはつけない。\",\"correctAnswer\":\"必要ない。I study English every day. と書く。\",\"correctExplanation\":\"every day、today、tomorrow、yesterday、this morning、next week などには、at・on・in をつけない。これらの語自体がすでに「いつ」を表しているためである。I study English every day. が正しい。\"}]}",
"{\"id\":\"eigo_s464\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"たずねる言葉：what・where・when・who・how\",\"description\":\"何を知りたいかによって、文の先頭に置く語を選べるようにする\",\"intro\":\"Yes か No で答えられない質問には、先頭に「何を知りたいか」を表す語を置きます。答え方もそれぞれ決まっているので、セットで覚えましょう。\",\"order\":964,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"what は「何」。What is this?、What do you have?\",\"where は「どこ」。Where is my bag?\",\"when は「いつ」。When is your birthday?\",\"who は「だれ」。Who is that boy?\",\"how は「どのように・どれくらい」。How are you?、How old are you?\",\"これらの質問には Yes / No で答えない。内容を答える。\"],\"sections\":[{\"heading\":\"たずね方と答え方\",\"body\":\"■ what（何）\\n・What is this? — It's a pen.（これは何ですか — ペンです）\\n・What do you have? — I have a book.（何を持っていますか — 本です）\\n・What time is it? — It's three.（何時ですか — 3時です）\\n・What color do you like? — I like blue.（何色が好きですか — 青です）\\n\\n■ where（どこ）\\n・Where is my bag? — It's on the chair.\\n・Where do you live? — I live in Tokyo.\\n・Where is the station? — It's near the park.\\n\\n■ when（いつ）\\n・When is your birthday? — It's May 5th.\\n・When do you study? — I study after dinner.\\n\\n■ who（だれ）\\n・Who is that boy? — He is my brother.\\n・Who is your teacher? — Ms. Sato is.\\n\\n■ how（どのように・どれくらい）\\n・How are you? — I'm fine, thank you.\\n・How do you go to school? — By bus.\\n・How old are you? — I'm ten years old.\\n・How many books do you have? — I have five.\\n・How much is it? — It's 500 yen.\\n\\n■ 文のならべ方\\nたずねる語 ＋ ふつうのたずねる文\\n・What do you like?（What ＋ do you like）\\n・Where does he live?（Where ＋ does he live）\\nDoes を使ったら、うしろの動詞はもとの形にする。\\n\\n■ 答え方\\nYes／No では答えない。聞かれた内容を答える。\\n誤：Where do you live? — Yes, I do.\\n正：Where do you live? — I live in Osaka.\\n\\n★ ポイント：what・where・when・who・how。この5つで、たずねたいことのほとんどがまかなえる。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ たずねる語を選ぶ\\n・（　）is your birthday? — It's July 3rd. → When\\n・（　）is your father? — He is a doctor. → What（職業をたずねるとき）\\n・（　）do you live? — I live in Kyoto. → Where\\n・（　）is that girl? — She is my sister. → Who\\n・（　）old is your dog? — It's three years old. → How\\n\\n■ how の組み合わせ\\n・How old（何才）\\n・How many（いくつ。数えられるもの）\\n・How much（いくら。お金や量）\\n・How long（どれくらい長い・長い時間）\\n・How tall（どれくらい高い・背）\\nhow のあとに語をつけて、たずねる内容をくわしくする。\\n\\n■ まちがえやすいところ\\n・Yes／No で答えてしまう\\n・What と Who を取りちがえる（人なら Who）\\n・How many のあとは複数形（How many books、How many pencils）\\n・Does を使ったのに、動詞に s を残してしまう\\n\\n■ 答えを聞いて質問を作る練習\\n答え：I go to school by bike.\\n質問：How do you go to school?\\n\\n答え：My birthday is in August.\\n質問：When is your birthday?\\n\\n⚠ 注意：職業をたずねるときは What を使う。What is your father? は「お父さんの仕事は何ですか」という意味になる。Who is your father? は「どの人がお父さんですか」という意味である。\"},{\"heading\":\"なぜたずねる語は先頭で、なぜ Yes／No で答えないのか\",\"mangaId\":\"eigo_s464_manga\",\"body\":\"what・where・when・who・how は、**知りたいことそのもの**を表す語です。英語ではいちばん知りたいことを文の先頭に置き、そのあとにふつうのたずねる文（do you like／does he live）を続けます。だから「たずねる語＋ふつうのたずねる文」の形になり、Does を使えばうしろの動詞はもとの形です。\\n\\nYes／No で答えないのは、これらの質問が「はい・いいえ」を聞いているのではなく、**中身（何・どこ・いつ・だれ・どのように）を聞いている**からです。Where do you live? に Yes, I do. と答えても、どこに住んでいるかは伝わりません。Yes／No で答えるのは Do・Are で始まる質問だけです。職業を What でたずねるのは、What が「何（をする人）か」を聞く語で、Who は「どの人か」を聞く語だからです。\\n\\n■ 確かめのしかた\\n①知りたいことを言う：何→what、どこ→where、いつ→when、だれ→who、どのように・どれくらい→how。**先頭**に置く。\\n②うしろが**ふつうのたずねる文**の形か。Where does he live?（Does のあとは live）。\\n③答えが**中身**になっているか。Where do you live?→I live in Tokyo.（× Yes, I do.）。\\n④how の組み合わせ：How old／How many（＋複数形）／How much／How long／How tall。職業→What is your father?、どの人→Who。\\n\\n★ ここがポイント：たずねる語は**知りたいことそのもの**なので先頭。**中身を聞いている**ので Yes／No では答えない。How many のあとは複数形、職業は What。\",\"figureId\":\"xf_eigo_s464\"}],\"trapExamples\":[{\"question\":\"「Where do you live?」への答えとして正しいものはどれですか。\",\"wrongAnswer\":\"Yes, I do.\",\"trapExplanation\":\"たずねる文の形だけを見て Yes／No で答えてしまった。where は場所をたずねているので、内容を答える。\",\"correctAnswer\":\"I live in Tokyo.（場所を答える）\",\"correctExplanation\":\"what、where、when、who、how で始まる質問には、Yes／No では答えられない。聞かれている内容（何・どこ・いつ・だれ・どのように）を答える。Yes／No で答えるのは、Do や Are で始まる質問である。\"},{\"question\":\"「あなたは本を何さつ持っていますか」を英語で書きなさい。\",\"wrongAnswer\":\"How many book do you have?\",\"trapExplanation\":\"How many のあとの名詞を単数のままにしてしまった。数をたずねるので複数形にする。\",\"correctAnswer\":\"How many books do you have?\",\"correctExplanation\":\"How many のあとには、数えられる名詞の複数形が来る。How many books、How many pencils、How many students のようになる。数えられないもの（水、お金）の量をたずねるときは How much を使う。\"}]}",
"{\"id\":\"eigo_s465\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語彙①：まちの中の建物と場所\",\"description\":\"まちにある建物の名前と、そこで何をするかをセットで覚える\",\"intro\":\"まちの中の建物の名前は、道案内でも自己しょうかいでも使います。名前だけでなく、そこで何をするかもいっしょに覚えると忘れません。\",\"order\":965,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"school（学校）、library（図書館）、hospital（病院）、park（公園）。\",\"station（駅）、post office（郵便局）、bank（銀行）、museum（博物館）。\",\"supermarket（スーパー）、bookstore（書店）、restaurant（レストラン）。\",\"zoo（動物園）、aquarium（水族館）、stadium（競技場）。\",\"「〜へ行く」は go to ~。「〜で」は at ~。\",\"go to bed（寝る）には to がつく。go home（家に帰る）は、home が「家へ」の意味を含むので to をつけない。\"],\"sections\":[{\"heading\":\"まとめておぼえる\",\"body\":\"■ 学校・勉強に関係する場所\\nschool（学校）／classroom（教室）／library（図書館）／gym（体育館）／playground（運動場）／music room（音楽室）\\n\\n■ 買い物の場所\\nsupermarket（スーパーマーケット）／convenience store（コンビニ）／bookstore（書店）／flower shop（花屋）／bakery（パン屋）／department store（デパート）\\n\\n■ 公共の場所\\nstation（駅）／post office（郵便局）／bank（銀行）／hospital（病院）／police station（けいさつ署）／fire station（消防署）／city hall（市役所）\\n\\n■ 楽しむ場所\\npark（公園）／zoo（動物園）／aquarium（水族館）／museum（博物館・美術館）／stadium（競技場）／restaurant（レストラン）／movie theater（映画館）\\n\\n■ そこで何をするか\\n・I study at school.（学校で勉強します）\\n・I read books in the library.（図書館で本を読みます）\\n・I buy food at the supermarket.（スーパーで食べ物を買います）\\n・I see animals at the zoo.（動物園で動物を見ます）\\n・I take a train at the station.（駅で電車に乗ります）\\n\\n■ 「〜へ行く」\\ngo to ＋ 場所\\n・I go to school.（学校へ行く。to のあとに the をつけない）\\n・I go to the park.（公園へ行く。the をつける）\\n学校・教会など「そこで活動する場所」には the をつけないことが多い。\\n\\n■ to をつけない言い方\\n・go home（家へ帰る）\\n・go there（そこへ行く）\\n\\n★ ポイント：場所の名前と「そこで何をするか」を対にして覚えると、会話でも使えるようになる。\",\"figureId\":\"xf_eigo_s465\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 言ってみる\\n・I go to the library on Saturday.（土曜日に図書館へ行きます）\\n・My father works at a bank.（父は銀行で働いています）\\n・There is a park near my house.（家の近くに公園があります）\\n\\n■ たずねる\\n・Where do you go on Sunday? — I go to the park.\\n・Where is the post office? — It's near the station.\\n・What do you do at the library? — I read books.\\n\\n■ まちがえやすいところ\\n・go to school の to を落とす\\n・go home に to をつけてしまう（誤：go to home）\\n・post office は2語で書く\\n・movie theater、convenience store も2語\\n\\n■ 二語の建物名\\npost office／police station／fire station／convenience store／department store／movie theater／city hall\\nどれも2語なので、間をあけて書く。\\n\\n■ 建物の中の場所\\n・in the classroom（教室の中で）\\n・on the playground（運動場で）\\n・at the station（駅で）\\n場所の広さによって in・on・at を使い分ける。\\n\\n⚠ 注意：go to home とは言わない。home は「家へ」という意味をすでにもっているので、go home と言う。同じく go there、come here も to をつけない。\",\"mangaId\":\"eigo_s465_xm\"}],\"trapExamples\":[{\"question\":\"「わたしは家に帰ります」を英語で書きなさい。\",\"wrongAnswer\":\"I go to home.\",\"trapExplanation\":\"「〜へ」をすべて to で表すと考えてしまう。home はそれ自体で「家へ」という意味をもつ。\",\"correctAnswer\":\"I go home.\",\"correctExplanation\":\"home は「家へ」という意味をふくむ語なので、to をつけない。同じように there（そこへ）、here（ここへ）にも to をつけない。一方、go to school、go to the park のように、ふつうの場所には to が必要である。\"},{\"question\":\"「郵便局」を英語で書きなさい。\",\"wrongAnswer\":\"postoffice\",\"trapExplanation\":\"2語をつなげて1語にしてしまった。post office は間をあけて書く。\",\"correctAnswer\":\"post office\",\"correctExplanation\":\"post office は2語で書く。同じように police station、fire station、convenience store、department store、movie theater も2語である。英語では語と語の間を必ずあけて書く決まりがあるので、つなげて書くと別のつづりになってしまう。\"}]}",
"{\"id\":\"eigo_s466\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語彙②：スポーツと楽器\",\"description\":\"play の使い方と、the をつけるかどうかの決まりを覚える\",\"intro\":\"スポーツも楽器も play を使いますが、一つだけちがいがあります。楽器には the をつけて、スポーツにはつけません。ここが問題でよく出ます。\",\"order\":966,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"スポーツには the をつけない。play soccer、play tennis。\",\"楽器には the をつける。play the piano、play the guitar。\",\"swim（泳ぐ）、ski（スキーをする）、run（走る）は play を使わない。\",\"do judo、do karate のように do を使うものもある。\",\"「〜が得意です」は I am good at ~ と言う。\",\"「〜をしよう」は Let's play ~ と言う。\"],\"sections\":[{\"heading\":\"まとめておぼえる\",\"body\":\"■ play を使うスポーツ（the をつけない）\\nplay soccer（サッカー）／play baseball（野球）／play tennis（テニス）／play basketball（バスケットボール）／play volleyball（バレーボール）／play badminton（バドミントン）／play table tennis（たっきゅう）\\n\\n■ play を使う楽器（the をつける）\\nplay the piano（ピアノ）／play the guitar（ギター）／play the violin（バイオリン）／play the recorder（リコーダー）／play the drums（ドラム）／play the flute（フルート）\\n\\n■ play を使わない運動\\n・swim（泳ぐ）：I swim in summer.\\n・run（走る）：I run every morning.\\n・ski（スキーをする）／skate（スケートをする）\\n・ride a bike（自転車に乗る）\\n・do judo／do karate／do kendo（日本の武道は do を使う）\\n\\n■ 「〜が好きです」「得意です」\\n・I like soccer.（サッカーが好きです）\\n・I like playing the piano.（ピアノをひくのが好きです）\\n・I am good at tennis.（テニスが得意です）\\n・I can play the piano.（ピアノがひけます）\\n\\n■ たずねる\\n・Do you play any sports? — Yes, I play soccer.\\n・Can you play the piano? — Yes, I can.\\n・What sport do you like? — I like basketball.\\n\\n★ ポイント：スポーツは the なし、楽器は the あり。この一点だけを覚える。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 入れてみる\\n・I play （　） soccer. → 何も入れない\\n・I play （　） piano. → the\\n・I play （　） tennis. → 何も入れない\\n・I play （　） guitar. → the\\n\\n■ 言ってみる\\n・I play soccer after school.（放課後にサッカーをします）\\n・My sister plays the violin.（姉はバイオリンをひきます）\\n・I swim in the pool in summer.（夏はプールで泳ぎます）\\n・I do karate on Saturday.（土曜日に空手をします）\\n\\n■ まちがえやすいところ\\n・play the soccer としてしまう（the は不要）\\n・play piano としてしまう（the が必要）\\n・swim に play をつけてしまう（誤：play swimming）\\n・judo に play を使ってしまう（do judo が自然）\\n\\n■ スポーツを見る・する\\n・play soccer（サッカーをする）\\n・watch soccer（サッカーを見る）\\n・a soccer game（サッカーの試合）\\n・a soccer player（サッカー選手）\\n\\n■ 好きなスポーツを言う練習\\nMy favorite sport is soccer.（好きなスポーツはサッカーです）\\nI am on the soccer team.（サッカー部に入っています）\\n\\n⚠ 注意：「テレビを見る」は watch TV で、TV に the をつけない。一方「ラジオを聞く」は listen to the radio で the をつける。決まった言い方として覚えること。\"},{\"heading\":\"なぜ楽器には the が付き、スポーツには付かないのか\",\"mangaId\":\"eigo_s466_manga\",\"body\":\"楽器は、**ピアノという種類の楽器そのもの**を指して「その楽器をひく」と言う習慣があり、the を付けて play the piano とします。スポーツは「サッカーという活動をする」という意味で、活動の名前には冠詞を付けません。理屈より、英語の長い習慣で決まった形なので、「楽器は the あり、スポーツは the なし」の一点で覚えます。\\n\\nswim・run・ski に play を使わないのは、これらが**それ自体で「泳ぐ・走る」という動作を表す動詞**だからです。play は「ボールなどを使うスポーツをする」「楽器をひく」ときの動詞で、動作そのものが動詞になっているものには要りません。柔道や空手のような武道は do を使います。\\n\\n■ 確かめのしかた\\n①楽器→**play the 〇〇**（play the piano／the guitar／the violin）。スポーツ→**play 〇〇**（play soccer／tennis）。× play piano、× play the soccer。\\n②動作そのものが動詞のもの（swim・run・ski・skate・ride a bike）には play を付けない。× play swimming。\\n③武道は do（do judo／do karate／do kendo）。\\n④「見る」は watch soccer、「サッカー選手」は a soccer player。watch TV（the なし）、listen to the radio（the あり）は決まった言い方。\\n\\n★ ここがポイント：**楽器は the あり、スポーツは the なし**の一点。swim・run は**それ自体が動詞**なので play を付けず、武道は do。\",\"figureId\":\"xf_eigo_s466\"}],\"trapExamples\":[{\"question\":\"「わたしはピアノをひきます」を英語で書きなさい。\",\"wrongAnswer\":\"I play piano.\",\"trapExplanation\":\"楽器の前の the を落としてしまった。スポーツと同じ形にしてしまいやすい。\",\"correctAnswer\":\"I play the piano.\",\"correctExplanation\":\"楽器の前には the をつける。play the piano、play the guitar、play the violin となる。一方スポーツには the をつけず、play soccer、play tennis と言う。「楽器は the あり、スポーツは the なし」と対にして覚えること。\"},{\"question\":\"「わたしは夏に泳ぎます」を英語で書きなさい。\",\"wrongAnswer\":\"I play swimming in summer.\",\"trapExplanation\":\"運動はすべて play を使うと考えてしまった。swim は play を使わない。\",\"correctAnswer\":\"I swim in summer.\",\"correctExplanation\":\"swim はそれ自体が「泳ぐ」という動詞なので、play は必要ない。同じように run（走る）、ski（スキーをする）、skate（スケートをする）も play を使わない。play を使うのは、ボールなどを使うスポーツと楽器である。\"}]}",
"{\"id\":\"eigo_s467\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語彙③：季節と行事\",\"description\":\"四つの季節と、一年の行事を英語で言えるようにする\",\"intro\":\"季節と行事は、自己しょうかいや作文でよく使います。「わたしは夏が好きです。なぜなら…」と言えるようにしておきましょう。\",\"order\":967,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"季節は spring（春）、summer（夏）、fall または autumn（秋）、winter（冬）。\",\"季節には in をつける。in summer（夏に）。\",\"行事：New Year's Day（元日）、Christmas（クリスマス）、sports day（運動会）。\",\"天気は It's で始める。It's sunny.（晴れています）\",\"「〜が好きです、なぜなら〜」は I like ~ because ~ と言う。\",\"季節の名前は、ふつう小文字で書き始める。\"],\"sections\":[{\"heading\":\"まとめておぼえる\",\"body\":\"■ 季節\\nspring（春）／summer（夏）／fall（秋。autumn とも言う）／winter（冬）\\n・in spring（春に）／in summer（夏に）\\n・My favorite season is summer.（好きな季節は夏です）\\n\\n季節の名前は小文字で書き始める。月の名前や曜日は大文字なので、ここがちがう。\\n\\n■ 天気\\nsunny（晴れ）／cloudy（くもり）／rainy（雨）／snowy（雪）／windy（風が強い）／hot（暑い）／cold（寒い）／warm（あたたかい）／cool（すずしい）\\n・How's the weather? — It's sunny.（天気はどうですか — 晴れです）\\n・It's hot in summer.（夏は暑いです）\\n\\n■ 一年の行事\\n・New Year's Day（元日）\\n・the Doll Festival（ひな祭り）\\n・the entrance ceremony（入学式）\\n・Children's Day（こどもの日）\\n・the Star Festival（七夕）\\n・the summer festival（夏祭り）\\n・sports day（運動会）\\n・the school trip（修学旅行）\\n・Halloween（ハロウィン）\\n・Christmas（クリスマス）\\n・New Year's Eve（大みそか）\\n\\n行事の名前で、決まった名前になっているものは大文字で書き始める。\\n\\n■ 季節と行事を結びつける\\n・In spring, we have the entrance ceremony.（春には入学式があります）\\n・In summer, we have the summer festival.（夏には夏祭りがあります）\\n・In fall, we have sports day.（秋には運動会があります）\\n・In winter, we have Christmas.（冬にはクリスマスがあります）\\n\\n■ 理由を言う\\nI like summer because I can swim.（泳げるので夏が好きです）\\nbecause のあとに理由をつづける。\\n\\n★ ポイント：季節は小文字、行事の決まった名前は大文字。書くときに気をつける。\",\"figureId\":\"xf_eigo_s467\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 言ってみる\\n・My favorite season is winter.（好きな季節は冬です）\\n・I like winter because I can ski.（スキーができるので冬が好きです）\\n・It's cold in winter.（冬は寒いです）\\n・We have sports day in fall.（秋に運動会があります）\\n\\n■ たずねる\\n・What season do you like? — I like spring.\\n・How's the weather today? — It's rainy.\\n・What do you do in summer? — I go to the sea.\\n\\n■ まちがえやすいところ\\n・季節を大文字で書いてしまう（Summer ではなく summer）\\n・天気の文の主語を忘れる（It's sunny. の It が必要）\\n・fall と autumn はどちらでもよい\\n\\n■ 季節と月\\n・spring：March、April、May\\n・summer：June、July、August\\n・fall：September、October、November\\n・winter：December、January、February\\n\\n■ 作文で使える形\\nMy favorite season is ~.\\nI like ~ because ~.\\nIn ~, I ~.\\nこの三つを組み合わせると、短い作文が書ける。\\n\\n⚠ 注意：天気を言うときは、必ず It's で始める。The weather is sunny. とも言えるが、ふつうは It's sunny. と言う。主語を落として Sunny. だけにしないこと。\",\"mangaId\":\"eigo_s467_xm\"}],\"trapExamples\":[{\"question\":\"「夏が好きです」の「夏」は、大文字と小文字のどちらで書き始めますか。\",\"wrongAnswer\":\"大文字。Summer と書く。\",\"trapExplanation\":\"曜日や月が大文字なので、季節も大文字だと考えてしまう。季節は小文字である。\",\"correctAnswer\":\"小文字。summer と書く。\",\"correctExplanation\":\"曜日（Monday）と月（May）は大文字で書き始めるが、季節（spring、summer、fall、winter）は小文字である。I like summer. が正しい。ただし文の最初に来るときは、文の決まりとして大文字になる。\"},{\"question\":\"「今日は晴れです」を英語で書きなさい。\",\"wrongAnswer\":\"Today is sunny weather.\",\"trapExplanation\":\"日本語のままの形にしてしまった。天気を言うときは It's で始める決まった言い方がある。\",\"correctAnswer\":\"It's sunny today.\",\"correctExplanation\":\"天気を言うときは It's で始める。It's sunny.、It's rainy.、It's cold. のようになる。この it は「それ」という意味ではなく、天気や時こくを言うときの決まった主語である。today は文の終わりにつける。\"}]}",
"{\"id\":\"eigo_s468\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"語彙④：気持ちを表す語\",\"description\":\"うれしい・悲しい・つかれたなどを、文の形で言えるようにする\",\"intro\":\"気持ちを表す語は、be動詞といっしょに使います。I am happy. の形を覚えれば、あとは語を入れかえるだけです。\",\"order\":968,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"気持ちを表す語は、be動詞（am・is・are）といっしょに使う。\",\"happy（うれしい）、sad（悲しい）、angry（おこっている）。\",\"tired（つかれた）、sleepy（ねむい）、hungry（おなかがすいた）、thirsty（のどがかわいた）。\",\"excited（わくわくしている）、surprised（おどろいた）、nervous（きんちょうしている）。\",\"程度を表すときは very や a little をつける。I am very happy.\",\"「〜して…な気持ちだ」は I am happy to ~ と言う。\"],\"sections\":[{\"heading\":\"まとめておぼえる\",\"body\":\"■ 基本の気持ち\\nhappy（うれしい）／sad（悲しい）／angry（おこっている）／fine（元気だ）／good（よい）／bad（悪い）\\n\\n■ 体の感じ\\ntired（つかれた）／sleepy（ねむい）／hungry（おなかがすいた）／thirsty（のどがかわいた）／sick（具合が悪い）／hot（暑い）／cold（寒い）\\n\\n■ 気持ちの動き\\nexcited（わくわくしている）／surprised（おどろいた）／nervous（きんちょうしている）／scared（こわい）／bored（たいくつだ）／glad（うれしい）\\n\\n■ 文の形\\nI am ＋ 気持ちを表す語\\n・I am happy.（うれしいです）\\n・I am hungry.（おなかがすいています）\\n・She is tired.（かのじょはつかれています）\\n・They are excited.（かれらはわくわくしています）\\n\\n■ 程度をつける\\n・very（とても）：I am very happy.\\n・a little（少し）：I am a little tired.\\n・so（とても）：I am so happy.\\n\\n■ たずねる\\n・How are you? — I'm fine, thank you.／I'm tired.\\n・Are you hungry? — Yes, I am.／No, I'm not.\\n・What's wrong? — I'm sick.（どうしたの — 具合が悪いんです）\\n\\n■ 理由を言う\\n・I am happy because it's my birthday.（たん生日なのでうれしいです）\\n・I am tired because I played soccer.（サッカーをしたのでつかれました）\\n\\n★ ポイント：気持ちの語は be動詞とセット。I happy. のように be動詞を落とさない。\",\"figureId\":\"xf_eigo_s468\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 言ってみる\\n・I am hungry. Let's have lunch.（おなかがすきました。昼食にしましょう）\\n・She is sad because her dog is sick.（犬の具合が悪いので、かのじょは悲しんでいます）\\n・Are you sleepy? — Yes, a little.\\n\\n■ 顔の様子と結びつける\\n・smile（ほほえむ）→ happy\\n・cry（泣く）→ sad\\n・yawn（あくびをする）→ sleepy\\n\\n■ まちがえやすいところ\\n・be動詞を落とす（誤：I happy。正：I am happy）\\n・hungry と angry を見まちがえる（つづりが似ている）\\n・「のどがかわいた」を I want water. とだけ言ってしまう（I'm thirsty. が自然）\\n\\n■ hungry と angry\\n・hungry（ハングリー）：おなかがすいた\\n・angry（アングリー）：おこっている\\nどちらも ngry の部分は同じで、はじめの hu と a がちがうだけなので、意味を取りちがえないよう注意する。\\n\\n■ あいさつの中で使う\\nA: How are you?\\nB: I'm fine, thank you. And you?\\nA: I'm good, thanks.\\n\\n■ 相手を気づかう言い方\\n・Are you OK?（だいじょうぶ？）\\n・That's too bad.（それは残念だね）\\n・I'm glad to hear that.（それを聞いてうれしいです）\\n\\n⚠ 注意：気持ちを表す語は形容詞なので、一般動詞とはならべない。I am play happy. のような文にはならない。\",\"mangaId\":\"eigo_s468_xm\"}],\"trapExamples\":[{\"question\":\"「わたしはおなかがすいています」を英語で書きなさい。\",\"wrongAnswer\":\"I hungry.\",\"trapExplanation\":\"be動詞を落としてしまった。気持ちや体の感じを表す語には be動詞が必要である。\",\"correctAnswer\":\"I am hungry.（I'm hungry.）\",\"correctExplanation\":\"happy、hungry、tired などは「〜な状態だ」を表す語なので、be動詞（am・is・are）といっしょに使う。日本語では「おなかがすいた」と一語で言えるが、英語では I am hungry. と be動詞が必要である。主語に合わせて am・is・are を選ぶこと。\"},{\"question\":\"angry の意味は何ですか。\",\"wrongAnswer\":\"おなかがすいた\",\"trapExplanation\":\"hungry とつづりが似ているので取りちがえた。はじめの部分がちがうだけで意味が変わる。\",\"correctAnswer\":\"おこっている\",\"correctExplanation\":\"angry は「おこっている」、hungry は「おなかがすいた」である。つづりは、はじめの hu と a がちがうだけなので、意味とセットで覚える。I am angry.（おこっています）、I am hungry.（おなかがすいています）と、例文で区別するとよい。\"}]}",
"{\"id\":\"eigo_s469\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話①：買い物\",\"description\":\"店で使う言い方を、店員とお客のやりとりの形で覚える\",\"intro\":\"買い物の会話は、聞かれることも答えることも決まっています。やりとりの形ごと覚えてしまえば、そのまま使えます。\",\"order\":969,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"店員の言い方：May I help you?（いらっしゃいませ）\",\"お客の言い方：I want ~, please. / I'd like ~, please.\",\"値段をたずねるときは How much is it?\",\"答えは It's ~ yen. / It's ~ dollars.\",\"手わたすときは Here you are.（はいどうぞ）\",\"買うと決めたら I'll take it.（それをください）\"],\"sections\":[{\"heading\":\"やりとりの形\",\"body\":\"■ 店に入る\\n店員：May I help you?（いらっしゃいませ／何かおさがしですか）\\nお客：Yes, please. I want a T-shirt.（はい。Tシャツがほしいです）\\n　　　または No, thank you. I'm just looking.（いいえ、見ているだけです）\\n\\n■ ほしいものを言う\\n・I want a cap, please.（ぼうしがほしいです）\\n・I'd like a hamburger, please.（ハンバーガーをお願いします）\\n　I'd like は I want よりていねいな言い方。\\n\\n■ 値段をたずねる\\nお客：How much is it?（いくらですか）\\n店員：It's 500 yen.（500円です）\\n\\n複数のものなら\\n・How much are they?（それらはいくらですか）\\n・They are 1,000 yen.\\n\\n■ 買うと決める\\n・I'll take it.（それをください）\\n・I'll take two.（2つください）\\n\\n■ お金をわたす・受け取る\\nお客：Here you are.（はいどうぞ）\\n店員：Thank you. Here's your change.（ありがとうございます。おつりです）\\nお客：Thank you.\\n\\n■ そのほかの言い方\\n・Do you have a bigger one?（もっと大きいのはありますか）\\n・Can I try it on?（試着してもいいですか）\\n・What color do you want?（何色がほしいですか）\\n・That's too expensive.（高すぎます）\\n\\n■ ファストフード店で\\n店員：What would you like?（何になさいますか）\\nお客：I'd like a hamburger and a small drink, please.\\n店員：For here or to go?（店内でめしあがりますか、お持ち帰りですか）\\nお客：For here, please.\\n\\n★ ポイント：How much is it? と It's ~ yen. の一往復が、買い物の会話の中心である。\",\"figureId\":\"xf_eigo_s469\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 役になって言ってみる\\n店員：May I help you?\\nお客：Yes, please. I want a notebook.\\n店員：Here you are. It's 200 yen.\\nお客：Here you are.\\n店員：Thank you.\\n\\n■ 値段の言い方\\n・500 yen（500円）\\n・1,000 yen（1000円）\\n・three dollars（3ドル）\\nyen は複数でも s をつけない。three hundred yen（300円）と言い、yens とは書かない。\\n\\n■ まちがえやすいところ\\n・How much のあとを is にするか are にするか（1つなら is、2つ以上なら are）\\n・Here you are. と Here it is. はどちらも「はいどうぞ」\\n・「ください」を Give me ~. と言うと、ていねいでない。please をつけるか I'd like ~ を使う\\n\\n■ ていねいさの順\\n・I want a cap.（ほしい）\\n・I want a cap, please.（ほしいです、お願いします）\\n・I'd like a cap, please.（いただきたいのですが）\\n下にいくほどていねいになる。\\n\\n■ お礼と返事\\n・Thank you. — You're welcome.\\n・Thanks. — No problem.\\n\\n⚠ 注意：Give me ~. は命令する言い方なので、店では使わない。I want ~, please. か I'd like ~, please. を使うこと。\",\"mangaId\":\"eigo_s469_xm\"}],\"trapExamples\":[{\"question\":\"「いくらですか」を英語で書きなさい。\",\"wrongAnswer\":\"How many is it?\",\"trapExplanation\":\"How many と How much を取りちがえた。値段をたずねるときは How much を使う。\",\"correctAnswer\":\"How much is it?\",\"correctExplanation\":\"How much は「いくら」「どれくらいの量」をたずねる言い方で、値段には必ずこちらを使う。How many は「いくつ」と数をたずねる言い方で、うしろに複数形の名詞が来る。How many books do you have? のように使う。\"},{\"question\":\"店で「ぼうしをください」と言うとき、最もていねいな言い方はどれですか。\",\"wrongAnswer\":\"Give me a cap.\",\"trapExplanation\":\"「ください」をそのまま英語にしてしまった。Give me ~ は命令する言い方で、店では使わない。\",\"correctAnswer\":\"I'd like a cap, please.\",\"correctExplanation\":\"Give me ~. は「よこしなさい」に近い強い言い方なので、店では使わない。I want a cap, please. でもよいが、I'd like a cap, please. のほうがていねいである。please をつけるだけでも、ずいぶんやわらかくなる。\"}]}",
"{\"id\":\"eigo_s470\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話②：道をたずねる・教える\",\"description\":\"行き方をたずねる言い方と、道順を伝える言い方を覚える\",\"intro\":\"道案内は、使う言い方が数えるほどしかありません。まっすぐ行って、曲がって、右にある。この三つで、たいていの道は説明できます。\",\"order\":970,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"たずね方：Where is ~? / How can I get to ~?\",\"Go straight.（まっすぐ行ってください）\",\"Turn right.（右に曲がってください）／Turn left.（左に曲がってください）\",\"It's on your right.（右側にあります）\",\"目印を言うときは at the corner（角で）、at the second light（二つ目の信号で）。\",\"お礼は Thank you.、返事は You're welcome.\"],\"sections\":[{\"heading\":\"やりとりの形\",\"body\":\"■ たずねる\\n・Excuse me.（すみません）\\n・Where is the station?（駅はどこですか）\\n・How can I get to the library?（図書館へはどう行けばいいですか）\\n・Is there a post office near here?（この近くに郵便局はありますか）\\n\\n■ 道順を伝える\\n・Go straight.（まっすぐ行ってください）\\n・Go straight for two blocks.（2ブロックまっすぐ行ってください）\\n・Turn right at the corner.（角を右に曲がってください）\\n・Turn left at the second light.（二つ目の信号を左に曲がってください）\\n・You can see it on your right.（右側に見えます）\\n・It's next to the bank.（銀行のとなりです）\\n・It's in front of the park.（公園の前です）\\n\\n■ どれくらいかかるか\\n・How long does it take?（どれくらいかかりますか）\\n・It takes about five minutes.（5分くらいです）\\n・It's about 300 meters from here.（ここから300メートルくらいです）\\n\\n■ 交通手段\\n・How do you go to school? — By bus.（バスで）\\n・by train（電車で）／by bike（自転車で）／by car（車で）／on foot（歩いて）\\nby のあとには a や the をつけない。「歩いて」だけ on foot となる。\\n\\n■ 会話の例\\nA: Excuse me. Where is the hospital?\\nB: Go straight for two blocks, and turn left at the corner. It's on your right.\\nA: Thank you very much.\\nB: You're welcome.\\n\\n★ ポイント：Go straight、Turn right／left、It's on your right。この三つで道案内はできる。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 言ってみる\\n・Excuse me. How can I get to the station?\\n・Go straight and turn right at the second corner.\\n・It's next to the bookstore.\\n\\n■ 目印を表す語\\ncorner（角）／traffic light（信号）／crossing（こうさ点）／bridge（橋）／bus stop（バス停）\\n\\n■ 位置を表す語\\n・next to ~（〜のとなりに）\\n・in front of ~（〜の前に）\\n・behind ~（〜のうしろに）\\n・between A and B（AとBの間に）\\n・across from ~（〜の向かいに）\\n\\n■ まちがえやすいところ\\n・by bus に the をつけてしまう（誤：by the bus）\\n・「歩いて」を by foot としてしまう（正：on foot）\\n・Turn に to をつけてしまう（誤：Turn to right。正：Turn right）\\n\\n■ 分からないときの言い方\\n・I'm sorry. I don't know.（ごめんなさい、わかりません）\\n・I'm not from here.（この辺の者ではありません）\\n\\n■ 聞き返す\\n・Pardon?（もう一度お願いします）\\n・Could you say that again?（もう一度言っていただけますか）\\n\\n⚠ 注意：Turn right のあとに to は入れない。ただし「右へ行く」は go to the right と言うこともある。turn のときは to をつけない、と覚えること。\"},{\"heading\":\"なぜ三つの言い方で道案内ができるのか、なぜ Turn に to が要らないのか\",\"mangaId\":\"eigo_s470_manga\",\"body\":\"道順は、どんなに複雑でも「**まっすぐ進む・曲がる・着く**」の三つの動きの組み合わせです。だから Go straight（進む）、Turn right／left at 〜（曲がる）、It's on your right／next to 〜（着く）の三つの言い方があれば、たいていの道を説明できます。目印（corner・traffic light・bridge）を at 〜 で足せば、どこで曲がるかも伝わります。\\n\\nTurn right に to が要らないのは、right が「右に」という**向きを表す副詞**で、それだけで動詞 turn を説明できるからです。to を付けると「右という場所へ」となって不自然です。「歩いて」が on foot なのは、by のあとに置けるのが乗り物の名前だけで、足は乗り物ではないからです。\\n\\n■ 確かめのしかた\\n①たずねるときは **Excuse me.** から。Where is 〜?／How can I get to 〜?／Is there a 〜 near here?\\n②道順を三つの動きで組み立てる：Go straight (for two blocks)→Turn right at the corner→It's on your right／next to the bank。\\n③× Turn to right→Turn right。× by the bus→by bus。× by foot→on foot（または I walk to school.）。\\n④分からないときは I'm sorry. I don't know.／I'm not from here.、聞き返すときは Pardon?／Could you say that again?\\n\\n★ ここがポイント：道順は**進む・曲がる・着く**の三つの動きなので、Go straight・Turn right／left・It's on your right で説明できる。right は向きの副詞なので **Turn right（to なし）**、歩くのは **on foot**。\",\"figureId\":\"xf_eigo_s470\"}],\"trapExamples\":[{\"question\":\"「歩いて学校へ行きます」を英語で書きなさい。\",\"wrongAnswer\":\"I go to school by foot.\",\"trapExplanation\":\"交通手段をすべて by で表すと考えてしまった。「歩いて」だけは on を使う。\",\"correctAnswer\":\"I go to school on foot.\",\"correctExplanation\":\"by bus、by train、by bike、by car のように乗り物には by を使うが、「歩いて」は on foot と言う。また I walk to school.（歩いて学校へ行きます）と言うこともでき、こちらのほうがよく使われる。\"},{\"question\":\"「右に曲がってください」を英語で書きなさい。\",\"wrongAnswer\":\"Turn to right.\",\"trapExplanation\":\"「〜に」をそのまま to にしてしまった。turn のあとに to はつけない。\",\"correctAnswer\":\"Turn right.\",\"correctExplanation\":\"Turn right.、Turn left. のように、turn のあとには to をつけない。命令する文なので主語も書かない。ていねいに言うなら Please turn right. または Turn right, please. となる。\"}]}",
"{\"id\":\"eigo_s471\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話③：自己しょうかいと友だちづくり\",\"description\":\"名前・好きなもの・できることを、順序立てて話せるようにする\",\"intro\":\"自己しょうかいは、話す順番を決めておけば、その場で考えなくてすみます。名前、好きなもの、できること。この三つで十分です。\",\"order\":971,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"名前は I'm ~. または My name is ~.\",\"I like ~.（〜が好きです）で好きなものを言う。\",\"I can ~.（〜ができます）でできることを言う。\",\"I want to be ~.（〜になりたいです）で夢を言う。\",\"Nice to meet you.（はじめまして）と言われたら Nice to meet you, too. と返す。\",\"最後に Thank you. で終える。\"],\"sections\":[{\"heading\":\"話す順番\",\"body\":\"■ 基本の形\\n①あいさつ\\nHello. / Hi.\\n②名前\\nI'm Ken. / My name is Ken Sato.\\n③好きなもの\\nI like soccer. / My favorite food is curry.\\n④できること\\nI can play the piano. / I can swim fast.\\n⑤したいこと・夢\\nI want to be a teacher.\\n⑥しめくくり\\nThank you.\\n\\n■ 例\\nHello. My name is Yuki.\\nI like music and reading books.\\nMy favorite subject is English.\\nI can play the piano.\\nI want to be a singer.\\nThank you.\\n\\n■ 相手にたずねる\\n・What's your name? — I'm Ken.\\n・How old are you? — I'm ten years old.\\n・What sport do you like? — I like tennis.\\n・Where are you from? — I'm from Osaka.\\n・What subject do you like? — I like science.\\n\\n■ はじめましてのやりとり\\nA: Hello. I'm Ken. Nice to meet you.\\nB: Hi, Ken. I'm Mary. Nice to meet you, too.\\nA: How are you?\\nB: I'm fine, thank you. And you?\\nA: I'm good, thanks.\\n\\n■ 別れるとき\\n・Goodbye. / Bye. / See you.\\n・See you tomorrow.（また明日）\\n・Have a nice day.（よい一日を）\\n\\n★ ポイント：名前・好きなもの・できることの三つを用意しておけば、どんな場面でも自己しょうかいができる。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 自分のことを書いてみる\\nHello. My name is ______.\\nI like ______.\\nMy favorite ______ is ______.\\nI can ______.\\nI want to be ______.\\nThank you.\\n\\n空らんをうめて、声に出して読む練習をする。\\n\\n■ 使える語\\n・favorite（お気に入りの）：My favorite color is blue.\\n・subject（教科）：math、science、English、Japanese、music、P.E.\\n・job（仕事）：teacher、doctor、nurse、vet（じゅう医）、pilot、singer、soccer player\\n\\n■ まちがえやすいところ\\n・I'm ten years old. の years に s をつけ忘れる\\n・Nice to meet you. への返事で too を落とす\\n・「〜になりたい」を I want be ~ としてしまう（正：I want to be ~）\\n\\n■ 相手の話を聞く\\n・Really?（ほんとう？）\\n・Me too.（わたしも）\\n・That's nice.（いいね）\\n・Sounds good.（よさそうだね）\\nあいづちを打てると、会話が続く。\\n\\n■ 発表のときの気をつけかた\\n・大きな声で、ゆっくり話す\\n・相手の顔を見る\\n・最後に Thank you. と言う\\n\\n⚠ 注意：Nice to meet you. は初めて会ったときだけに使う。二回目からは Nice to see you. または How are you? を使う。\"},{\"heading\":\"なぜ話す順番を決めておくのか、なぜ too を付けるのか\",\"mangaId\":\"eigo_s471_manga\",\"body\":\"自己しょうかいは、聞く側が**名前→好きなもの→できること**の順で情報を受け取ると、相手の人物像を組み立てやすくなります。話す側も順番が決まっていれば、その場で考えずに、空らんをうめるだけで話せます。「〜になりたい」が want to be なのは、want（〜したい）のあとに動作を続けるには to＋動詞のもとの形が要り、「〜である」の動詞が be だからです。I want be は to が抜けて文になりません。\\n\\nNice to meet you. に Nice to meet you, too. と返すのは、相手が先に言った「会えてうれしい」に「**私もです**」と気持ちを重ねるからです。too（〜も）が無いと、相手の言葉をただくり返しただけになります。初めて会ったときだけに使い、二回目からは Nice to see you. か How are you? です。\\n\\n■ 確かめのしかた\\n①**あいさつ→名前→好きなもの→できること→なりたいもの→Thank you.** の順で言えるか。\\n②I'm ten years old.（years に s）、I want **to** be a teacher.（to を落とさない）。\\n③Nice to meet you. と言われたら **Nice to meet you, too.**（コンマと too）。二回目以降は Nice to see you.\\n④あいづち（Really?／Me too.／That's nice.）を入れると会話が続く。発表は大きな声でゆっくり、相手の顔を見て、最後に Thank you.\\n\\n★ ここがポイント：**名前→好きなもの→できること**の順は、聞く側が人物像を組み立てやすい順。want のあとは **to＋もとの形**（want to be）。Nice to meet you. には**「私も」の too** を付けて返す。\",\"figureId\":\"xf_eigo_s471\"}],\"trapExamples\":[{\"question\":\"「わたしは先生になりたいです」を英語で書きなさい。\",\"wrongAnswer\":\"I want be a teacher.\",\"trapExplanation\":\"want のあとの to を落としてしまった。「〜したい」は want to ~ の形になる。\",\"correctAnswer\":\"I want to be a teacher.\",\"correctExplanation\":\"「〜したい」は want to ＋ 動詞のもとの形で表す。I want to be a teacher.、I want to play soccer.、I want to go to America. のようになる。to を落とすと文として成り立たない。\"},{\"question\":\"「Nice to meet you.」と言われたときの返事はどれですか。\",\"wrongAnswer\":\"Nice to meet you.\",\"trapExplanation\":\"同じ言葉をそのまま返してしまった。返すときは「わたしもです」を表す too をつける。\",\"correctAnswer\":\"Nice to meet you, too.\",\"correctExplanation\":\"相手が先に言ったのに対して返すときは、too をつけて Nice to meet you, too. と言う。コンマを忘れずに書く。同じように Thank you. — You're welcome.、See you. — See you. のように、返し方が決まっている言い方を覚えておくとよい。\"}]}",
"{\"id\":\"eigo_s472\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"会話④：教室で使う言い方\",\"description\":\"先生の指示と、自分から言うお願いの形を覚える\",\"intro\":\"教室で先生が使う言い方は決まっています。聞いて分かるようにしておけば、英語の授業がぐっと楽になります。\",\"order\":972,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"先生の指示は命令する文の形。Open your book.\",\"Stand up.（立って）／Sit down.（すわって）\",\"Listen.（聞いて）／Repeat after me.（あとについて言って）\",\"お願いするときは Can I ~? または May I ~? を使う。\",\"分からないときは I don't know. / I don't understand.\",\"もう一度言ってほしいときは Pardon? または One more time, please.\"],\"sections\":[{\"heading\":\"よく使う言い方\",\"body\":\"■ 先生の指示\\n・Stand up.（立ちなさい）\\n・Sit down.（すわりなさい）\\n・Open your textbook to page ten.（教科書の10ページを開きなさい）\\n・Close your book.（本を閉じなさい）\\n・Look at the blackboard.（黒板を見なさい）\\n・Listen carefully.（よく聞きなさい）\\n・Repeat after me.（あとについて言いなさい）\\n・Read aloud.（声に出して読みなさい）\\n・Write your name.（名前を書きなさい）\\n・Raise your hand.（手をあげなさい）\\n・Make pairs.（ペアになりなさい）\\n・Be quiet.（静かにしなさい）\\n\\n■ 自分から言う\\n・Can I go to the bathroom?（トイレに行ってもいいですか）\\n・May I come in?（入ってもいいですか）\\n・Can you help me?（手伝ってもらえますか）\\n・I have a question.（質問があります）\\n・How do you say this in English?（これは英語で何と言いますか）\\n・What does this mean?（これはどういう意味ですか）\\n・How do you spell it?（つづりはどう書きますか）\\n\\n■ 分からないとき\\n・I don't know.（わかりません）\\n・I don't understand.（理解できません）\\n・Pardon?（もう一度お願いします）\\n・One more time, please.（もう一度お願いします）\\n・Please speak slowly.（ゆっくり話してください）\\n\\n■ 答えるとき\\n・Yes.／No.\\n・I see.（なるほど）\\n・OK.／All right.\\n・Here you are.（はいどうぞ。ものをわたすとき）\\n\\n■ ほめられたとき\\n・Good job!（よくできました）\\n・Great!（すばらしい）\\n・Thank you. と返す。\\n\\n★ ポイント：先生の指示はすべて動詞から始まる。動詞から始まっていたら「〜しなさい」だと分かる。\",\"figureId\":\"xf_eigo_s472\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 聞いて動く練習\\nStand up. → 立つ\\nSit down. → すわる\\nOpen your book. → 本を開く\\nRaise your hand. → 手をあげる\\n体を動かしながら覚えると、忘れにくい。\\n\\n■ お願いの形\\n・Can I ~?（〜してもいいですか。自分がすること）\\n・Can you ~?（〜してくれますか。相手にお願いすること）\\nこの二つを取りちがえないようにする。\\n・Can I use your pen?（あなたのペンを使ってもいいですか）\\n・Can you open the window?（まどを開けてくれますか）\\n\\n■ 答え方\\n・Can I ~? — Sure.／Of course.／Sorry, you can't.\\n・Can you ~? — Sure.／OK.／Sorry, I can't.\\n\\n■ まちがえやすいところ\\n・Can I と Can you を取りちがえる\\n・Pardon? を Pardon me? と言う（どちらでも通じる）\\n・page ten の ten を序数にしてしまう（page ten でよい）\\n\\n■ 授業で使う語\\ntextbook（教科書）／notebook（ノート）／pencil case（筆箱）／eraser（消しゴム）／ruler（定規）／blackboard（黒板）／desk（つくえ）／chair（いす）\\n\\n■ 相手を助ける言い方\\n・Let me help you.（手伝わせて）\\n・Don't worry.（心配しないで）\\n・Take your time.（ゆっくりでいいよ）\\n\\n⚠ 注意：Can I ~? は自分がすること、Can you ~? は相手にお願いすること。主語がちがうだけで意味が大きく変わるので、言う前に確かめること。\",\"mangaId\":\"eigo_s472_xm\"}],\"trapExamples\":[{\"question\":\"「まどを開けてくれますか」を英語で書きなさい。\",\"wrongAnswer\":\"Can I open the window?\",\"trapExplanation\":\"主語を取りちがえた。これでは「わたしが開けてもいいですか」という意味になる。\",\"correctAnswer\":\"Can you open the window?\",\"correctExplanation\":\"相手にしてもらいたいときは Can you ~? を使う。自分がしてよいかたずねるときは Can I ~? である。Can I open the window? は「わたしが開けてもいいですか」という意味になるので、意味が変わってしまう。だれがするのかを確かめてから主語を選ぶこと。\"},{\"question\":\"先生が「Repeat after me.」と言いました。何をすればよいですか。\",\"wrongAnswer\":\"先生の顔を見る\",\"trapExplanation\":\"意味を知らないと動けない。repeat は「くり返して言う」という意味である。\",\"correctAnswer\":\"先生のあとについて、同じことを言う\",\"correctExplanation\":\"Repeat after me. は「わたしのあとについて言いなさい」という意味である。教室でよく使われる指示なので、Look at ~（〜を見なさい）、Listen（聞きなさい）、Read aloud（声に出して読みなさい）とあわせて覚えておくと、英語の授業についていきやすくなる。\"}]}",
"{\"id\":\"eigo_s473\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"短い英文を読む①：自己しょうかいの文\",\"description\":\"知っている語だけの短い文を、意味をとりながら読む練習をする\",\"intro\":\"単語を覚えても、文になると読めないことがあります。一語ずつ訳すのではなく、かたまりで区切って読む。これが読む力の第一歩です。\",\"order\":973,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"文は「だれが」「どうする」「何を」のかたまりに区切って読む。\",\"知らない語があっても、前後から意味を考えてみる。\",\"大文字で始まる語は、人の名前や地名であることが多い。\",\"and、but、because のつなぎ言葉に印をつけると、文の流れが見える。\",\"一度で分からなくても、二回三回と読み返す。\",\"読んだあとに、日本語で内容を一言で言えるか確かめる。\"],\"sections\":[{\"heading\":\"読んでみる\",\"body\":\"■ 読み方の手順\\n①大文字で始まる語（名前・地名）に丸をつける\\n②主語（だれが）に線を引く\\n③動詞（どうする）を探す\\n④かたまりで区切って読む\\n\\n■ 英文1\\nHello. My name is Aya.\\nI am ten years old.\\nI live in Osaka.\\nI like dogs and cats.\\nI have a dog. His name is Shiro.\\nI play with Shiro every day.\\n\\n読み取ること\\n・名前：Aya\\n・年令：10才\\n・住んでいるところ：大阪\\n・好きなもの：犬とねこ\\n・飼っている犬の名前：Shiro\\n\\n■ 英文2\\nThis is my friend Ken.\\nHe is eleven years old.\\nHe likes soccer very much.\\nHe plays soccer after school.\\nHe can run very fast.\\nHe wants to be a soccer player.\\n\\n読み取ること\\n・だれのことか：友だちのケン\\n・年令：11才\\n・好きなもの：サッカー\\n・いつするか：放課後\\n・できること：速く走れる\\n・夢：サッカー選手\\n\\n■ 気をつけて読むところ\\n・He likes ~ の s は、主語が he だからついている\\n・He can run ~ の can は「できる」\\n・He wants to be ~ は「〜になりたい」\\n\\n★ ポイント：一語ずつ日本語にしない。「だれが」「どうする」のかたまりで読むと、速く正確になる。\",\"figureId\":\"xf_eigo_s473\",\"mangaId\":\"eigo_s473_xm\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 答えてみる（英文1について）\\n・What is her name? — Her name is Aya.\\n・How old is she? — She is ten years old.\\n・Where does she live? — She lives in Osaka.\\n・Does she have a cat? — No, she doesn't. She has a dog.\\n\\n■ 答えてみる（英文2について）\\n・What sport does Ken like? — He likes soccer.\\n・When does he play soccer? — He plays soccer after school.\\n・What does he want to be? — He wants to be a soccer player.\\n\\n答えるときは、英文の言葉をそのまま使うと正確になる。\\n\\n■ 知らない語があったとき\\n①その語を飛ばして読んでみる\\n②前後から意味を考える\\n③それでも分からなければ、あとで辞書を引く\\n一語で止まらないことが大切である。\\n\\n■ 音読の効果\\n声に出して読むと、意味のかたまりが自然に分かるようになる。一日に一つ、短い文章を音読するとよい。\\n\\n■ まちがえやすいところ\\n・he と she を取りちがえる\\n・likes の s を見落として、主語をまちがえる\\n・his（かれの）と he（かれは）を取りちがえる\\n\\n⚠ 注意：問題に答えるときは、英文の中の言葉をそのまま使う。自分の知っている別の言い方に変えると、まちがいのもとになる。\"}],\"trapExamples\":[{\"question\":\"「He likes soccer.」の likes に s がついているのはなぜですか。\",\"wrongAnswer\":\"soccer が一つだけだから\",\"trapExplanation\":\"うしろの語に合わせていると考えてしまう。s がつくかどうかを決めるのは主語である。\",\"correctAnswer\":\"主語が He（1人）だから\",\"correctExplanation\":\"動詞に s がつくのは、主語が he、she、it、または1人・1つのときである。うしろに来る語の数とは関係がない。I like soccer.、They like soccer. では s がつかない。文を読むときも、s を見たら主語が1人だと分かる手がかりになる。\"},{\"question\":\"英文を読んでいて知らない語が出てきたとき、まず何をすればよいですか。\",\"wrongAnswer\":\"そこで止まって、辞書を引くまで先に進まない\",\"trapExplanation\":\"一語ずつ完全に分かろうとしてしまう。読む練習では、まず全体をつかむほうが大切である。\",\"correctAnswer\":\"その語を飛ばして読み進め、前後から意味を考える\",\"correctExplanation\":\"知らない語で止まると、文全体の流れが分からなくなる。まず飛ばして最後まで読み、前後の内容から意味を考える。それでも分からなければあとで調べる。この読み方ができると、初めて見る文章でも内容をつかめるようになる。\"}]}",
"{\"id\":\"eigo_s474\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"短い英文を読む②：一日の生活と手紙\",\"description\":\"時こくや曜日が出てくる文を読み、内容を表に整理する\",\"intro\":\"一日の生活を書いた文には、時こくがたくさん出てきます。何時に何をするかを表にしながら読むと、頭の中が整理されます。\",\"order\":974,\"studyPeriod\":\"小4\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"時こく（at seven）や曜日（on Sunday）に印をつけながら読む。\",\"何時に何をするかを、順に書き出して整理する。\",\"usually（たいてい）、always（いつも）、sometimes（ときどき）に注意する。\",\"手紙の文には、書き出しとむすびの決まった言い方がある。\",\"Dear ~,（〜さんへ）で始め、Your friend, ~（友だちの〜より）で終える。\",\"読み終えたら、内容を日本語で一言でまとめる。\"],\"sections\":[{\"heading\":\"読んでみる\",\"body\":\"■ 英文1：一日の生活\\nI get up at six thirty.\\nI have breakfast at seven.\\nI go to school at eight.\\nI study English, math, and science.\\nI have lunch at twelve.\\nI go home at four.\\nI do my homework after dinner.\\nI go to bed at nine thirty.\\n\\n表に整理すると\\n6:30 起きる\\n7:00 朝ごはん\\n8:00 学校へ行く\\n12:00 昼ごはん\\n4:00 家へ帰る\\n夕食のあと 宿題\\n9:30 ねる\\n\\n■ 英文2：週末のこと\\nI usually get up at seven on Sunday.\\nI sometimes play soccer with my friends in the park.\\nI always help my mother in the afternoon.\\nI like Sunday very much.\\n\\n読み取ること\\n・usually（たいてい）：日曜は7時に起きる\\n・sometimes（ときどき）：友だちと公園でサッカー\\n・always（いつも）：午後は母を手伝う\\n\\n■ 英文3：手紙\\nDear Mary,\\nHello. How are you?\\nI am fine. I am in the fifth grade now.\\nMy favorite subject is music. I can play the piano.\\nPlease write to me soon.\\n\\nYour friend,\\nKen\\n\\n手紙の形\\n・Dear ~,（〜さんへ）で始める\\n・本文\\n・Your friend,（友だちの〜より）\\n・自分の名前\\n\\n★ ポイント：時こく・曜日・always などの語に印をつけながら読むと、内容が整理される。\"},{\"heading\":\"練習と気をつけること\",\"body\":\"■ 答えてみる（英文1について）\\n・What time does he get up? — He gets up at six thirty.\\n・What time does he go to bed? — He goes to bed at nine thirty.\\n・When does he do his homework? — After dinner.\\n\\n■ 答えてみる（英文2について）\\n・What does he do on Sunday afternoon? — He helps his mother.\\n・Does he always play soccer? — No, he sometimes plays soccer.\\n\\n■ ひんどを表す語\\nalways（いつも、100パーセント）\\nusually（たいてい）\\noften（よく）\\nsometimes（ときどき）\\nnever（一度も〜ない）\\nこれらの語は、ふつう一般動詞の前に置く。\\n・I sometimes play tennis.\\n・I never eat natto.\\n\\n■ 手紙で使う言い方\\n・Dear ~,（〜さんへ）\\n・How are you?（お元気ですか）\\n・I am fine.（元気です）\\n・Please write to me soon.（お返事ください）\\n・Your friend, ~（友だちの〜より）\\n・See you soon.（また近いうちに）\\n\\n■ まちがえやすいところ\\n・always と never を取りちがえる（意味が正反対）\\n・ひんどを表す語を動詞のうしろに置いてしまう\\n・手紙の Dear のあとのコンマを忘れる\\n\\n⚠ 注意：never は「一度も〜ない」という意味で、それだけで打ち消しを表す。I never don't eat ~ のように don't を重ねてはいけない。\"},{\"heading\":\"なぜ表に整理しながら読み、なぜ never には don't を重ねないのか\",\"mangaId\":\"eigo_s474_manga\",\"body\":\"一日の生活の文には時こくが次々に出てくるので、読みながら「何時に何をするか」を表にすると、あとで What time does he get up? と聞かれたときに表を見るだけで答えられます。時こく・曜日・ひんどの語（always・usually・sometimes）に印をつけるのは、設問がそこを聞くからです。\\n\\nnever が「一度も〜ない」で don't を重ねないのは、never が**それ自体に打ち消しの意味を持つ語**だからです。I never don't eat 〜 と書くと打ち消しが二重になります。ひんどの語が一般動詞の前に置かれるのは、動詞の「どれくらいの頻度で」を説明する語だからで、be動詞のときはそのうしろ（I am always busy.）に置きます。always→usually→often→sometimes→never の順に少なくなります。\\n\\n■ 確かめのしかた\\n①読みながら**時こく・曜日・ひんどの語に印**をつけ、「何時に何を」を表にする。\\n②ひんどの語の位置：**一般動詞の前**（I sometimes play tennis.）、**be動詞のあと**（I am always busy.）。× I play sometimes tennis。\\n③never は単独で打ち消し（I never eat natto.＝一度も食べない）。× I never don't eat。always（いつも）と取りちがえていないか。\\n④手紙の形：Dear 〇〇,（コンマ）→本文→Your friend,→自分の名前。Please write to me soon.\\n\\n★ ここがポイント：時こく・ひんどの語に**印をつけて表にする**と設問にすぐ答えられる。never は**それ自体が打ち消し**なので don't を重ねず、ひんどの語は**一般動詞の前・be動詞のあと**。\",\"figureId\":\"xf_eigo_s474\"}],\"trapExamples\":[{\"question\":\"「I never eat natto.」の意味は何ですか。\",\"wrongAnswer\":\"わたしはいつも納豆を食べます。\",\"trapExplanation\":\"never を always と取りちがえた。never は打ち消しの意味をもつ語である。\",\"correctAnswer\":\"わたしは一度も納豆を食べません。\",\"correctExplanation\":\"never は「一度も〜ない」という意味で、それ自体が打ち消しを表す。always（いつも）とは正反対である。ひんどを表す語は always → usually → often → sometimes → never の順に少なくなる、と並べて覚えるとよい。\"},{\"question\":\"「ときどきテニスをします」を英語で書きなさい。\",\"wrongAnswer\":\"I play sometimes tennis.\",\"trapExplanation\":\"ひんどを表す語の置き場所をまちがえた。ふつうは一般動詞の前に置く。\",\"correctAnswer\":\"I sometimes play tennis.\",\"correctExplanation\":\"always、usually、often、sometimes、never は、一般動詞の前に置く。I sometimes play tennis. が正しい。ただし be動詞のときは、be動詞のうしろに置く（I am always busy.）。動詞の種類によって位置が変わる点に注意する。\"}]}",
"{\"id\":\"new20_e4_eigo_01\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数字①：1〜20の数え方\",\"description\":\"one から twenty までの数字の読み方と、発音でまちがえやすい語を整理する\",\"intro\":\"英語の数字は日本語の「いち・に・さん」のように規則的ではなく、1から20までは1つずつ形がちがう。特に13〜19の「〜teen」と、11・12・15はつづりも音も独特なので、耳と口で慣れることが大切だ。\",\"order\":6080,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 1〜10：まず基本の10個\",\"body\":\"英語の数字はまず1〜10をしっかり覚えることがスタート地点。\\n\\n1 one（ワン）\\n2 two（トゥー）\\n3 three（スリー）\\n4 four（フォー）\\n5 five（ファイブ）\\n6 six（シックス）\\n7 seven（セブン）\\n8 eight（エイト）\\n9 nine（ナイン）\\n10 ten（テン）\\n\\n★ 発音のポイント\\n・three は th の音（舌を上の前歯の裏に軽く当てて「スリー」に近い息の音）。sea（海）と混同しないよう注意。\\n・eight は g と h を発音しない。「エイト」で、日本語の「エイト」に近いがtで止める。\\n・four と for（〜のために）は同じ発音（フォー）。書くときのつづりを間違えないようにする。\\n\\n⚠ よくある間違い\\n・nine を「ナイン」ではなく「ニネ」と読んでしまう→ i は「アイ」の音になる（nine と mine は同じ音の仲間）。\\n・one の発音は「オネ」ではなく「ワン」。o なのに w の音から始まる、英語特有の読み方なので丸ごと覚える。\"},{\"heading\":\"2. 11〜20：teenがつく数字\",\"body\":\"11から19までは、多くが「数字＋teen」の形になる。teen（ティーン）は「10」を表す部分だ。\\n\\n11 eleven（イレブン）※ teen がつかない特別な形\\n12 twelve（トゥエルブ）※ teen がつかない特別な形\\n13 thirteen（サーティーン）\\n14 fourteen（フォーティーン）\\n15 fifteen（フィフティーン）\\n16 sixteen（シックスティーン）\\n17 seventeen（セブンティーン）\\n18 eighteen（エイティーン）\\n19 nineteen（ナインティーン）\\n20 twenty（トゥエンティ）\\n\\n★ つづりが変化する語（テストで狙われやすい）\\n・three→thirteen（ee が ir に変わって thir になる）\\n・five→fifteen（v が f に変わる）\\n・eight→eighteen（t が1つだけ、eightのtとteenのtが重なって1つになる）\\n・nine→nineteen（そのままnine+teenで作れる）\\n\\n⚠ 発音のちがいに注意\\n13（thirteen）と30（thirty）、14（fourteen）と40（forty）は、アクセントの位置がちがうだけで似た音になる。\\n・thirTEEN（後ろを強く）＝13　／　THIRty（前を強く）＝30\\n会話でこの2つを聞き分けるときは、どこを強く言っているかに耳をすませる。\",\"figureId\":\"xf_new20_e4_eigo_01\",\"mangaId\":\"new20_e4_eigo_01_xm\"},{\"heading\":\"3. 数字を使った会話\",\"body\":\"数字は答えるだけでなく、たずねる表現とセットで覚えると使える力になる。\\n\\n【年れいをたずねる】\\nHow old are you?（あなたは何さいですか）\\n— I'm ten.（10さいです） / I'm ten years old.（10さいです）\\n★ years old は省略してもよい。数字のあとにつけるのが基本の形。\\n\\n【個数をたずねる】\\nHow many apples do you have?（りんごをいくつ持っていますか）\\n— I have five apples.（5個持っています）\\n⚠ 名詞（apples）は複数のときに s をつけ忘れやすいので注意。\\n\\n【電話番号や順番を1つずつ読む】\\n電話番号などは数字を1つずつ読む。\\n例）080-1234 → oh eight oh, one two three four\\n★ 0 は zero だけでなく、電話番号では oh（オー）と読むことも多い。\"}],\"keyPoints\":[\"1〜10：one, two, three, four, five, six, seven, eight, nine, ten\",\"11と12は特別な形：eleven, twelve（teenがつかない）\",\"13〜19は「数字＋teen」。thirteen・fifteen・eighteenはつづりが少し変化する\",\"20はtwenty。thirteen(13)とthirty(30)はアクセントの位置で区別する\",\"How old are you? には I'm 数字（years old）. で答える\",\"複数の名詞にはsをつける（five apples）\"]}",
"{\"id\":\"new20_e4_eigo_02\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"数字②：21〜100の数え方\",\"description\":\"20より大きい数字の作り方の規則と、100までの言い方を身につける\",\"intro\":\"21以上の数字は、11〜19のような特別な形はほとんどなく、「10のかたまり」＋「1〜9」を組み合わせるだけで作れる。規則さえわかれば99まですべて自分で作れるようになる。\",\"order\":6081,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 10のかたまり（20・30・40…）\",\"body\":\"10ごとの数字は次の8個を覚える。\\n\\n20 twenty（トゥエンティ）\\n30 thirty（サーティ）\\n40 forty（フォーティ）※ four なのに u が入らない、つづりの例外\\n50 fifty（フィフティ）※ five の v が f に変わる\\n60 sixty（シックスティ）\\n70 seventy（セブンティ）\\n80 eighty（エイティ）\\n90 ninety（ナインティ）\\n100 one hundred（ワン ハンドレッド）\\n\\n⚠ つづりの注意\\n・forty は four + ty ではなく、u を1つとった forty。「フォーティ」なのに u がないことに気をつける。\\n・eighty は eight のtが1つのまま + y なので eighty。eightty のように t を重ねない。\"},{\"heading\":\"2. 21〜99の作り方：ハイフンでつなぐ\",\"body\":\"21以上は「10のかたまり」と「1〜9」をハイフン（-）でつなぐだけ。\\n\\n21 twenty-one（トゥエンティ ワン）\\n25 twenty-five（トゥエンティ ファイブ）\\n32 thirty-two（サーティ トゥー）\\n48 forty-eight（フォーティ エイト）\\n57 fifty-seven（フィフティ セブン）\\n99 ninety-nine（ナインティ ナイン）\\n\\n★ ルール：「10のかたまり」＋「-（ハイフン）」＋「1の位」\\n一の位が0のとき（20, 30, 40…）はハイフン以下は不要。\\n書くときは twentyone のようにくっつけて書かないこと（twenty-one が正しい）。\\n\\n⚠ よくある間違い\\n・「52」を fifty two と書くつもりが順番を逆にして two fifty としてしまう→英語は必ず「大きい位が先」。\\n・ハイフンを忘れて twenty one と離して書いてしまう（会話では問題ないが、書く問題では正確に）。\",\"figureId\":\"xf_new20_e4_eigo_02\",\"mangaId\":\"new20_e4_eigo_02_xm\"},{\"heading\":\"3. 100とキリのいい数、値段の言い方\",\"body\":\"■ 100：one hundred（またはa hundred）\\n101のように「100＋端数」のときは、間にandを入れることもある（特にイギリス英語）。\\n例）101 → one hundred and one（アメリカ英語ではandを省くことも多い）\\n\\n■ 値段のたずね方・答え方\\nHow much is it?（それはいくらですか）\\n— It's one hundred yen.（100円です）\\n— It's fifty dollars.（50ドルです）\\n\\n■ 買い物ごっこでよく使う数字表現\\nI have twenty dollars.（20ドル持っています）\\nTwo apples, please.（りんごを2つください）\\n\\n★ ポイントまとめ\\n・10ごとの数字8個（twenty〜ninety）＋hundred を覚えれば、あとはハイフンでつなぐだけで99まで自由に作れる。\\n・値段や個数の会話では、数字のあとに何のもの・お金の単位（yen/dollars）を忘れずにつける。\"}],\"keyPoints\":[\"10ごとの数字：twenty(20)〜ninety(90)、100はone hundred\",\"fortyはuが入らない、fiftyはvがfに変わる、eightyはtが1つ（つづりの例外）\",\"21以上は「10のかたまり-1の位」をハイフンでつなぐ（twenty-one）\",\"英語の数字は必ず大きい位から先に言う\",\"How much is it? には It's 数字＋単位（yen/dollars）. で答える\"]}",
"{\"id\":\"new20_e4_eigo_03\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"色の名前と言い方\",\"description\":\"基本的な色を表す単語と、色をたずねる・答える表現を身につける\",\"intro\":\"「これは何色？」は日常でとてもよく使う会話。色の単語をたくさん知っていると、絵や持ち物についての話がぐっと広がる。ここでは基本の色の単語と、色をたずねる決まった言い方を覚えよう。\",\"order\":6082,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 基本の色の単語\",\"body\":\"まずは日常でよく使う色の単語を覚えよう。\\n\\nred（レッド）＝赤\\nblue（ブルー）＝青\\nyellow（イエロー）＝黄色\\ngreen（グリーン）＝緑\\norange（オレンジ）＝オレンジ色\\npurple（パープル）＝紫\\npink（ピンク）＝ピンク\\nbrown（ブラウン）＝茶色\\nblack（ブラック）＝黒\\nwhite（ホワイト）＝白\\ngray（グレー）※イギリス英語ではgrey＝灰色\\n\\n★ 発音のポイント\\n・orange は「オレンジ」ではなく「オーレンジ」に近い音で、最初のオを強く長めに言う。\\n・purple は語尾の le を「プル」と軽く発音する。「パーポー」のようにならないよう気をつける。\\n・yellow の -ow は「オウ」の音（Hello や window と同じ響き）。\"},{\"heading\":\"2. 色をたずねる・答える表現\",\"body\":\"■ 色をたずねる決まり文句\\nWhat color is it?（それは何色ですか）\\nWhat color do you like?（あなたは何色が好きですか）\\n\\n■ 答え方\\nIt's red.（それは赤です）\\nI like blue.（私は青が好きです）\\n\\n■ 色＋名詞の順番\\n英語では「色（形容詞）＋名詞」の順番になる。日本語の「赤いりんご」と同じ順番だが、a の位置に気をつける。\\n例）a red apple（赤いりんご）\\n例）a blue pen（青いペン）\\n⚠ 注意：a red apple の a は「色」の前に置く。× red a apple のように途中に入れない。\\n\\n■ 複数の色を並べて言うとき\\nI like red and blue.（赤と青が好きです）\\nThis bag is black and white.（このかばんは黒と白です）\"},{\"heading\":\"3. 色を使った会話の練習\",\"body\":\"【対話例】\\nA: What color is your bag?（あなたのかばんは何色ですか）\\nB: It's green.（緑です）\\nA: What color do you like the best?（一番好きな色は何ですか）\\nB: I like pink the best.（一番ピンクが好きです）\\n\\n■ 色にまつわる決まった言い方\\n・traffic light（信号機）：red（止まれ）／yellow（注意）／green（進め）\\n・rainbow（レインボー＝虹）の色：red, orange, yellow, green, blue, purple の順で覚えるとよい。\\n\\n⚠ よくある間違い\\n・green を「グリン」と短く言ってしまう→「グリーン」と e を長く伸ばす音。\\n・「オレンジ色」と「オレンジ（果物）」はどちらも orange で同じつづり・同じ発音。文脈で意味が変わる。\"},{\"heading\":\"なぜ色は名詞の前に置き、a は色の前に置くのか\",\"mangaId\":\"new20_e4_eigo_03_manga\",\"body\":\"英語では、名詞を説明する語（形容詞）は**名詞の前**に置きます。「赤いりんご」は a red apple で、日本語の「赤い→りんご」と同じ順です。ただし a（一つの）は「どのりんごか」を決める語なので、説明の語よりさらに前の**列の先頭**に置きます。red a apple のように a を途中に入れると、a が何を指すのか分からなくなります。\\n\\n色をたずねる文が What color is it? と What color で始まるのは、「何色か」という知りたいことを先頭に置く英語のきまりだからです。答えは It's red. のように、聞かれた中身（色）を答えます。orange が色にも果物にも使われるのは、果物のオレンジの色をそのまま色の名前にしたからで、文脈で意味が決まります。\\n\\n■ 確かめのしかた\\n①色を名詞の**前**に置いたか。a red apple／a blue pen。\\n②a・the は**列の先頭**か。× red a apple→a red apple。\\n③What color is it?→It's 〇〇.、What color do you like?→I like 〇〇. と中身で答えているか。\\n④発音：orange は最初の「オ」を強く長め、purple の le は軽く「プル」、green は e を長く。gray（米）／grey（英）。\\n\\n★ ここがポイント：形容詞は**名詞の前**、a・the は**列の先頭**（a red apple）。色をたずねる文は**知りたいことを先頭**に置く What color 〜?。\",\"figureId\":\"xf_new20_e4_eigo_03\"}],\"keyPoints\":[\"基本の色：red, blue, yellow, green, orange, purple, pink, brown, black, white\",\"色をたずねる文は What color is it? / What color do you like?\",\"色（形容詞）は名詞の前に置く：a red apple\",\"orangeは色にも果物にも使う語（つづり・発音は同じ）\",\"好きな色を答えるときは I like 色. の形を使う\"]}",
"{\"id\":\"new20_e4_eigo_04\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"形の名前と言い方\",\"description\":\"基本図形の英単語と、形を説明する簡単な表現を身につける\",\"intro\":\"丸・三角・四角といった形の名前は、算数の授業とも結びつく身近な単語だ。ここでは基本の形の単語と、「これは丸です」のように形を説明する言い方を練習する。\",\"order\":6083,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 基本の形の単語\",\"body\":\"よく使う形の英単語をまとめて覚えよう。\\n\\ncircle（サークル）＝円・丸\\ntriangle（トライアングル）＝三角形\\nsquare（スクエア）＝正方形\\nrectangle（レクタングル）＝長方形\\nstar（スター）＝星形\\nheart（ハート）＝ハート形\\ndiamond（ダイアモンド）＝ひし形\\n\\n★ 単語のつくりから覚えるコツ\\n・triangle の tri は「3」を表す部分（tricycle=三輪車のtriと同じ）。「3つの角」というイメージで覚えると忘れにくい。\\n・rectangle の rect は「まっすぐ」を意味する部分。角がまっすぐな四角形、というイメージ。\\n\\n⚠ square と rectangle のちがい\\n・square：辺の長さがすべて同じで、角もすべて直角な四角形（正方形）\\n・rectangle：たてとよこの長さがちがう四角形（長方形）\\n日本語ではどちらも「四角」とまとめがちだが、英語では区別して使う。\"},{\"heading\":\"2. 形を説明する表現\",\"body\":\"■ 「これは〜です」で形を伝える\\nThis is a circle.（これは丸です）\\nIt's a triangle.（これは三角形です）\\n\\n■ 形をたずねる\\nWhat shape is it?（それはどんな形ですか）\\n— It's a square.（それは正方形です）\\n\\n■ 形＋色を組み合わせる\\n色と同じように、形も名詞の前に置いて説明を加えることができる。\\n例）a red triangle（赤い三角形）\\n例）a big circle（大きな丸）※ big（大きい）・small（小さい）もよく一緒に使う形容詞\\n\\n【対話例】\\nA: What shape is this?（これは何の形ですか）\\nB: It's a star.（星の形です）\\nA: I like stars.（私は星が好きです）\"},{\"heading\":\"3. 身のまわりのものと形\",\"body\":\"身近なものを形で説明する練習をしよう。\\n\\nA ball is round.（ボールは丸い）※roundは「丸い」という形容詞（circleは名詞）\\nA book is rectangular.（本は長方形をしている）\\nThe moon looks like a circle.（月は丸に見える）\\n\\n★ round と circle のちがい\\n・circle：名詞で「円（そのもの）」\\n・round：形容詞で「丸い（様子を表す）」\\n例）Draw a circle.（円を描いて）／The plate is round.（お皿は丸い）\\n\\n⚠ よくある間違い\\n・triangle のつづりで tri のあとを angle（アングル＝角度）と混同して triangel と書いてしまう→ triangle が正しいつづり。\\n・square を「スクウェア」と最後まで強く読みすぎない。最初の音（スク）をやや短めに、全体をなめらかにつなげて発音する。\"},{\"heading\":\"なぜ square と rectangle を分け、なぜ circle と round を分けるのか\",\"mangaId\":\"new20_e4_eigo_04_manga\",\"body\":\"日本語では「四角」でまとめてしまう形も、英語では**辺の長さが全部同じ**なら square（正方形）、**たてとよこがちがう**なら rectangle（長方形）と、別の語で呼びます。算数で正方形と長方形を分けるのと同じ考え方です。triangle の tri は「3」（tricycle＝三輪車の tri）で「3つの角」、rectangle の rect は「まっすぐ」で「角がまっすぐな四角形」と、語のつくりから覚えると忘れにくくなります。\\n\\ncircle と round を分けるのは、**品詞がちがう**からです。circle は「円そのもの」を指す名詞（Draw a circle.）、round は「丸い」という様子を表す形容詞（The plate is round.）。日本語ではどちらも「丸」で済みますが、英語では「円を描く」と「丸い」を別の語で言います。\\n\\n■ 確かめのしかた\\n①四角形なら、**辺が全部同じか**を見る。同じ→square、たてよこがちがう→rectangle。\\n②「円」そのものなら **circle**（名詞）、「丸い」様子なら **round**（形容詞）。A ball is round.／Draw a circle.\\n③形をたずねる：What shape is it?→It's a star. 形容詞は名詞の前（a red triangle、a big circle）。\\n④つづり：triangle（× triangel）。tri＝3、rect＝まっすぐ。\\n\\n★ ここがポイント：square は**辺が全部同じ**、rectangle は**たてよこがちがう**。circle は**名詞（円）**、round は**形容詞（丸い）**。語のつくり（tri＝3、rect＝まっすぐ）で覚える。\",\"figureId\":\"xf_new20_e4_eigo_04\"}],\"keyPoints\":[\"基本の形：circle, triangle, square, rectangle, star, heart, diamond\",\"squareは正方形（辺が全部同じ長さ）、rectangleは長方形（たてよこがちがう）\",\"形をたずねる文は What shape is it?\",\"形（名詞）と round（丸い、形容詞）の使い分けに注意\",\"形容詞は名詞の前に置く：a red triangle, a big circle\"]}",
"{\"id\":\"new20_e4_eigo_05\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動物の名前①：ペットや身近な動物\",\"description\":\"家庭や学校で見かける身近な動物の単語と、複数形の作り方を身につける\",\"intro\":\"「犬を飼っています」「猫が好きです」のように、動物の話題は自己紹介や日常会話でとてもよく出てくる。ここではまず身近な動物の単語から始めよう。\",\"order\":6084,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. ペット・身近な動物の単語\",\"body\":\"家や近所でよく見る動物の名前を覚えよう。\\n\\ndog（ドッグ）＝犬\\ncat（キャット）＝猫\\nrabbit（ラビット）＝うさぎ\\nhamster（ハムスター）＝ハムスター\\nbird（バード）＝鳥\\nfish（フィッシュ）＝魚\\nturtle（タートル）＝カメ\\n\\n★ 発音のポイント\\n・rabbit は最初の「ラ」を強く言い、「ビット」は弱く短く言うと自然。\\n・fish の複数形はそのままfish（形が変わらない特別な語）。× fishes とは基本的に言わない。\\n\\n⚠ ペットについて話すときの表現\\nI have a dog.（私は犬を飼っています）\\nMy cat is white.（私の猫は白いです）\\nDo you have any pets?（何かペットを飼っていますか）\\n— Yes, I have a rabbit.（はい、うさぎを飼っています）\"},{\"heading\":\"2. 動物の複数形\",\"body\":\"動物の名前も、名詞の複数形のルールにしたがって形が変わる。\\n\\n■ ふつうに -s をつける動物\\ndog → dogs（犬たち）\\ncat → cats（猫たち）\\nbird → birds（鳥たち）\\nrabbit → rabbits（うさぎたち）\\n\\n■ 形が変わらない・特別な複数形\\nfish → fish（そのまま。1匹でも複数でも fish）\\nsheep → sheep（羊。そのまま）\\n\\n★ ポイント\\n・「魚を3匹見た」は I saw three fish.（× three fishes ではない）。\\n・数をたずねるときは How many dogs do you have?（何匹犬を飼っていますか）のように名詞を複数形にする。\\n\\n⚠ よくある間違い\\n・fish に s をつけて fishes としてしまう。fish は「特別な複数形（形が変わらない語）」の代表例として覚えておく。\",\"figureId\":\"xf_new20_e4_eigo_05\",\"mangaId\":\"new20_e4_eigo_05_xm\"},{\"heading\":\"3. 動物についての簡単な会話\",\"body\":\"【対話例】\\nA: Do you have a pet?（ペットを飼っていますか）\\nB: Yes, I have a dog and a cat.（はい、犬と猫を飼っています）\\nA: What's your dog's name?（あなたの犬の名前は何ですか）\\nB: His name is Pochi.（名前はポチです）\\n\\n■ 好きな動物を伝える\\nI like dogs.（私は犬が好きです）\\n※「犬全般」が好きなときは複数形（dogs）を使うのが自然。1匹の特定の犬の話なら a dog / my dog のように単数で表す。\\n\\n■ よく使う動作とのセット\\nwalk a dog（犬を散歩させる）\\nfeed a cat（猫にえさをやる）\\n例）I walk my dog every morning.（私は毎朝犬を散歩させます）\"}],\"keyPoints\":[\"身近な動物：dog, cat, rabbit, hamster, bird, fish, turtle\",\"fishとsheepは複数形でも形が変わらない特別な名詞\",\"I have a 動物. でペットを飼っていることを伝えられる\",\"「〜が好き」と動物全般について言うときは複数形（I like dogs.）を使う\",\"Do you have any pets? で相手にペットの有無をたずねる\"]}",
"{\"id\":\"new20_e4_eigo_06\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動物の名前②：動物園の動物と鳴き声\",\"description\":\"動物園でよく見る動物の単語と、動物の鳴き声を表す英語の音を身につける\",\"intro\":\"動物園に行くと、犬や猫とはちがう大きな動物にたくさん出会う。また、日本語と英語では動物の「鳴き声」の表し方がまったくちがうことが多く、比べてみるととてもおもしろい。\",\"order\":6085,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 動物園でよく見る動物\",\"body\":\"動物園でよく見かける動物の単語を覚えよう。\\n\\nlion（ライオン）＝ライオン\\ntiger（タイガー）＝トラ\\nelephant（エレファント）＝ゾウ\\ngiraffe（ジラフ）＝キリン\\nmonkey（モンキー）＝サル\\nbear（ベア）＝クマ\\npanda（パンダ）＝パンダ\\npenguin（ペンギン）＝ペンギン\\nzebra（ズィーブラ）＝シマウマ\\nkoala（コアラ）＝コアラ\\n\\n★ 発音のポイント\\n・giraffe はつづりの見た目と発音の差が大きい語。「ジラフ」と平らに言わず、2つ目の「ラフ」（raf）を強く「ジ・ラフ」に近く発音する。\\n・elephant はアクセントが最初のe（エ）にある。「エレファント」の「エ」を強く。\\n\\n⚠ 動物の名前の頭文字は大文字にしない（固有名詞ではないため）。文の最初以外は小文字で書く。\"},{\"heading\":\"2. 動物の鳴き声を表す英語\",\"body\":\"日本語と英語では、同じ動物の鳴き声でもまったくちがう音で表すことが多い。比べて楽しもう。\\n\\n■ 犬（dog）\\n日本語：ワンワン　→　英語：Woof! woof!（ウーフ ウーフ）／Bow-wow!\\n■ 猫（cat）\\n日本語：ニャーニャー　→　英語：Meow!（ミャーオ）\\n■ 牛（cow）\\n日本語：モーモー　→　英語：Moo!（ムー）\\n■ ぶた（pig）\\n日本語：ブーブー　→　英語：Oink oink!（オインク オインク）\\n■ にわとり（rooster）\\n日本語：コケコッコー　→　英語：Cock-a-doodle-doo!（コッカドゥードゥルドゥー）\\n\\n★ ポイント\\n鳴き声の表し方が国によって全然ちがうのは、実際の音の聞こえ方が言語によって変わって聞こえるから。英語の擬音語（動物の鳴き声）は日本語とセットで覚えると印象に残りやすい。\",\"figureId\":\"xf_new20_e4_eigo_06\",\"mangaId\":\"new20_e4_eigo_06_xm\"},{\"heading\":\"3. 好きな動物・動物の様子を伝える表現\",\"body\":\"■ 好きな動物をたずねる・答える\\nWhat animal do you like?（どんな動物が好きですか）\\n— I like lions.（ライオンが好きです）\\n— My favorite animal is a panda.（一番好きな動物はパンダです）\\n\\n■ 動物の様子を表す形容詞とセットで使う\\nLions are strong.（ライオンは強い）\\nGiraffes are tall.（キリンは背が高い）\\nElephants are big.（ゾウは大きい）\\nRabbits are cute.（うさぎはかわいい）\\n\\n【対話例】\\nA: What animal do you like the best?（一番好きな動物は何ですか）\\nB: I like pandas the best. They are cute.（パンダが一番好きです。かわいいから）\\n\\n⚠ よくある間違い\\n・「動物全般」について話すときは複数形（lions, giraffes）を使う。単数（a lion）は「1頭のライオン」を指すので、意味がずれてしまう。\"}],\"keyPoints\":[\"動物園の動物：lion, tiger, elephant, giraffe, monkey, bear, panda, penguin, zebra, koala\",\"動物の名前は文の最初以外は小文字で書く\",\"鳴き声は日本語と英語で音の表し方がちがう（dog: Woof! / cat: Meow! / cow: Moo!）\",\"好きな動物をたずねる文は What animal do you like?\",\"動物全般について話すときは複数形を使う（I like lions.）\"]}",
"{\"id\":\"new20_e4_eigo_07\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"くだもの・やさいの単語\",\"description\":\"身近な果物・野菜の英単語と、好き嫌いを伝える表現を身につける\",\"intro\":\"給食や買い物でよく出てくる果物・野菜の名前は、覚えるとすぐに会話で使える身近な単語だ。数えられる・数えられないの区別もここで少しずつ慣れておこう。\",\"order\":6086,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. くだものの単語\",\"body\":\"身近な果物の英単語をまとめて覚えよう。\\n\\napple（アップル）＝りんご\\nbanana（バナナ）＝バナナ\\norange（オレンジ）＝オレンジ\\nstrawberry（ストロベリー）＝いちご\\ngrape（グレープ）＝ぶどう（1粒はa grape、ふつう複数形grapesで使う）\\nmelon（メロン）＝メロン\\npeach（ピーチ）＝もも\\nwatermelon（ウォーターメロン）＝すいか\\n\\n★ 発音のポイント\\n・strawberry は音が長い語。straw（ストロー）+ berry（ベリー）の組み合わせと考えると覚えやすい。\\n・banana はアクセントが真ん中（ba-NA-na）にある。「バナーナ」に近い感覚で真ん中を強く。\\n\\n⚠ apple・orange は母音で始まる語なので、1つのときは an をつける（an apple / an orange）。\"},{\"heading\":\"2. やさいの単語\",\"body\":\"給食や食卓でよく出てくる野菜の英単語を覚えよう。\\n\\ncarrot（キャロット）＝にんじん\\npotato（ポテト）＝じゃがいも\\ntomato（トメイト）＝トマト\\nonion（アニオン）＝たまねぎ\\ncabbage（キャベジ）＝キャベツ\\ncucumber（キューカンバー）＝きゅうり\\ncorn（コーン）＝とうもろこし\\n\\n★ 複数形に注意する語\\npotato → potatoes（esをつける）\\ntomato → tomatoes（esをつける）\\n※ o で終わる語の一部は es をつける（詳しくは他の単元で学ぶ複数形のルールと同じ）。\\n\\n⚠ onion のつづりで o の後の n の位置を間違えやすい（× oinon）。オニオンリング（onion rings）のような外来語で見た形と結びつけて覚えるとよい。\",\"figureId\":\"xf_new20_e4_eigo_07\"},{\"heading\":\"3. 好き嫌いをたずねる・答える\",\"body\":\"■ 好きかどうかをたずねる\\nDo you like carrots?（にんじんは好きですか）\\n— Yes, I do. I like carrots.（はい、好きです）\\n— No, I don't. I don't like carrots.（いいえ、好きではありません）\\n\\n■ 一番好きなものを伝える\\nMy favorite fruit is strawberries.（私の一番好きな果物はいちごです）\\nMy favorite vegetable is corn.（私の一番好きな野菜はとうもろこしです）\\n\\n【対話例】\\nA: What fruit do you like?（どんな果物が好きですか）\\nB: I like apples and bananas.（りんごとバナナが好きです）\\nA: Do you like tomatoes?（トマトは好きですか）\\nB: No, I don't. I don't like tomatoes.（いいえ、トマトは好きではありません）\\n\\n★ ポイント：果物・野菜の名前は「好きなものの種類全体」を言うときは複数形にすることが多い（I like apples.）。\",\"mangaId\":\"new20_e4_eigo_07_xm\"}],\"keyPoints\":[\"果物：apple, banana, orange, strawberry, grape, melon, peach, watermelon\",\"野菜：carrot, potato, tomato, onion, cabbage, cucumber, corn\",\"potato・tomatoの複数形はesをつける（potatoes, tomatoes）\",\"好き嫌いは Do you like 〜? / I like 〜. / I don't like 〜. でたずね・答える\",\"一番好きなものは My favorite fruit/vegetable is 〜. で伝える\"]}",
"{\"id\":\"new20_e4_eigo_08\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"家族について話す：This is my ~.\",\"description\":\"家族を紹介するときの基本表現と、写真を見せながら家族を説明する言い方を身につける\",\"intro\":\"家族の写真を見せながら「これは私のお父さんです」と紹介する場面は、英語の授業でもよくある活動だ。This is my ~. という形はとても使い道が広く、家族以外にも応用がきく便利な表現。\",\"order\":6087,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 家族を表す単語のおさらいと紹介の形\",\"body\":\"家族の呼び方はすでに知っている人も多いはず。ここではその単語を使って「紹介する」練習をする。\\n\\nfather（ファーザー）＝お父さん　／　mother（マザー）＝お母さん\\nbrother（ブラザー）＝兄・弟　／　sister（シスター）＝姉・妹\\ngrandfather（グランドファーザー）＝おじいさん　／　grandmother（グランドマザー）＝おばあさん\\n\\n■ This is my ~. の形\\n「これは私の〜です」と紹介する、もっとも基本的な形。\\nThis is my father.（これは私のお父さんです）\\nThis is my sister.（これは私の姉／妹です）\\n\\n★ ポイント：写真や絵を指さしながら This is 〜. を使うと、自然な紹介になる。This（これ）は「近くにあるもの・今見せているもの」を指すときに使う。\"},{\"heading\":\"2. 家族のことを説明する表現\",\"body\":\"■ 名前を紹介する\\nThis is my mother. Her name is Yuki.（これは私の母です。名前はゆきです）\\nThis is my brother. His name is Ken.（これは私の兄／弟です。名前はけんです）\\n★ 男の人には his（彼の）、女の人には her（彼女の）を使う。\\n\\n■ 様子や特ちょうを説明する\\nMy father is tall.（私の父は背が高いです）\\nMy sister is kind.（私の姉／妹は優しいです）\\nMy grandmother is 70 years old.（私の祖母は70さいです）\\n\\n■ 家族の人数を伝える\\nThere are four people in my family.（私の家族は4人です）\\nI have one brother.（私には兄・弟が1人います）\\n\\n⚠ よくある間違い\\n・his と her を逆に使ってしまう→his=男の人の、her=女の人の、と覚えるときは「彼」「彼女」の日本語訳とセットにするとよい。\"},{\"heading\":\"3. 家族紹介の会話練習\",\"body\":\"【対話例】\\nA: Who is this?（これはだれですか）\\nB: This is my father.（これは私の父です）\\nA: What does he do?（お父さんの仕事は何ですか）\\nB: He is a teacher.（先生です）\\n\\n■ 家族全員を順番に紹介する\\nThis is my family. This is my father. This is my mother. This is my sister.\\n（これは私の家族です。これが父、これが母、これが姉です）\\n\\n■ ペットも家族の一員として紹介できる\\nThis is my dog. His name is Pochi.（これは私の犬です。名前はポチです）\\n\\n★ 発表のコツ：This is my ~. を1文ずつ区切って、ゆっくりはっきり言うと聞き手に伝わりやすい。\"},{\"heading\":\"なぜ This is my 〜. で紹介でき、なぜ his と her を分けるのか\",\"mangaId\":\"new20_e4_eigo_08_manga\",\"body\":\"This は「近くにあるもの・今見せているもの」を指す語です。写真や絵を指さしながら This is my father. と言えば、「今指しているこの人が私の父です」と自然に伝わります。家族以外にも This is my dog.／This is my friend Ken. と使えるので、使い道の広い形です。\\n\\nhis（彼の）と her（彼女の）を分けるのは、英語では**その人が男性か女性か**で「〜の」の形が変わるからです。日本語の「名前は」には性別の区別がありませんが、英語では His name is Ken.／Her name is Yuki. と必ず選びます。家族の人数を There are four people in my family. と言うのは、family が「まとまり」であって人数ではなく、人数を言うなら people を数えるからです。\\n\\n■ 確かめのしかた\\n①紹介は **This is my 〇〇.** 指さしながら言う。Who is this?→This is my father.\\n②名前を言うときは**男性→His name is 〇〇.、女性→Her name is 〇〇.**\\n③様子は My father is tall.／My sister is kind.、人数は There are 〇 people in my family.／I have one brother.\\n④仕事をたずねる What does he do?→He is a teacher. ペットも This is my dog. His name is Pochi. で紹介できる。\\n\\n★ ここがポイント：This は**今見せているもの**を指すので、指さしながら **This is my 〜.**。「〜の」は**男性なら his、女性なら her**。人数は people を数える。\",\"figureId\":\"xf_new20_e4_eigo_08\"}],\"keyPoints\":[\"This is my 〜. で「これは私の〜です」と紹介できる\",\"家族の単語：father, mother, brother, sister, grandfather, grandmother\",\"男の人にはhis（彼の）、女の人にはher（彼女の）を使う\",\"There are 〜 people in my family. で家族の人数を伝える\",\"Who is this? — This is my 〜. で紹介の会話ができる\"]}",
"{\"id\":\"new20_e4_eigo_09\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"職業の単語とWhat do you want to be?\",\"description\":\"身近な職業を表す単語と、将来なりたい職業をたずねる・答える表現を身につける\",\"intro\":\"「将来何になりたい？」は自己紹介の定番の話題。職業の単語をいくつか知っておくと、自分の夢や周りの人の仕事について話せるようになる。\",\"order\":6088,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 身近な職業の単語\",\"body\":\"よく話題になる職業の英単語を覚えよう。\\n\\nteacher（ティーチャー）＝先生\\ndoctor（ドクター）＝医者\\nnurse（ナース）＝看護師\\npolice officer（ポリス オフィサー）＝警察官\\nfirefighter（ファイアーファイター）＝消防士\\ncook（クック）＝料理人\\nsinger（シンガー）＝歌手\\nsoccer player（サッカー プレイヤー）＝サッカー選手\\nvet（ベット）＝獣医（veterinarianの短い言い方）\\n\\n★ つくりから覚えるコツ\\n・動詞＋erで「〜する人」を表す語が多い（teach→teacher、sing→singer、play→player）。\\n・「〜選手」は sport（スポーツ名）+ player の組み合わせで作れる（baseball player, tennis playerなど）。\\n\\n⚠ police officer は2語で1つの職業を表す語。間にスペースを忘れずに書く。firefighter は1語で書く（fire fighter と離さない）。\"},{\"heading\":\"2. 職業をたずねる・答える表現\",\"body\":\"■ 相手の職業をたずねる\\nWhat do you do?（お仕事は何をされていますか）\\n— I'm a teacher.（私は先生です）\\n★ 職業を答えるときは a/an を忘れずにつける（I'm teacher. とは言わない）。\\n\\n■ 家族の職業を紹介する\\nMy father is a doctor.（私の父は医者です）\\nMy mother is a nurse.（私の母は看護師です）\\n\\n■ 将来の夢をたずねる・答える\\nWhat do you want to be?（あなたは将来何になりたいですか）\\n— I want to be a vet.（私は獣医になりたいです）\\n— I want to be a singer.（私は歌手になりたいです）\\n\\n★ want to be 〜 は「〜になりたい」という気持ちを表す決まった言い方。be のあとには職業（名詞）が続く。\",\"figureId\":\"xf_new20_e4_eigo_09\",\"mangaId\":\"new20_e4_eigo_09_xm\"},{\"heading\":\"3. 職業についての会話練習\",\"body\":\"【対話例】\\nA: What do you want to be in the future?（将来何になりたいですか）\\nB: I want to be a soccer player.（サッカー選手になりたいです）\\nA: Why?（どうしてですか）\\nB: Because I like soccer.（サッカーが好きだからです）\\n\\n■ Because を使って理由を伝える\\nI want to be a doctor because I want to help people.\\n（人を助けたいので、医者になりたいです）\\n\\n■ 職業＋様子を表す形容詞\\nFirefighters are brave.（消防士は勇かんです）\\nNurses are kind.（看護師さんは優しいです）\\n\\n⚠ よくある間違い\\n・What do you want to be? を「あなたは何が欲しいですか」と訳してしまう→ want to be は「〜になりたい」という意味のまとまりで覚える。want（欲しい）だけの意味とは区別する。\"}],\"keyPoints\":[\"職業の単語：teacher, doctor, nurse, police officer, firefighter, cook, singer, soccer player, vet\",\"職業を答えるときは a/anを忘れずにつける（I'm a teacher.）\",\"相手の職業は What do you do? でたずねる\",\"将来の夢は What do you want to be? — I want to be a 〜. でやりとりする\",\"Because 〜. で理由をつけ加えられる\"]}",
"{\"id\":\"new20_e4_eigo_10\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"曜日の言い方と一週間の言い方\",\"description\":\"月曜日から日曜日までの英単語と、何曜日かをたずねる・答える表現を身につける\",\"intro\":\"「今日は何曜日？」「日曜日は何をする？」という会話は、学校でも日常生活でもとてもよく出てくる。曜日の名前は7つとも覚えると、予定を伝えるときにとても役立つ。\",\"order\":6089,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 曜日の単語7つ\",\"body\":\"一週間の7つの曜日を月曜日から順番に覚えよう。\\n\\nMonday（マンデー）＝月曜日\\nTuesday（テューズデー）＝火曜日\\nWednesday（ウェンズデー）＝水曜日\\nThursday（サーズデー）＝木曜日\\nFriday（フライデー）＝金曜日\\nSaturday（サタデー）＝土曜日\\nSunday（サンデー）＝日曜日\\n\\n★ 大文字のルール\\n曜日の名前は文の途中でも必ず最初の文字を大文字で書く（固有名詞のあつかい）。\\n○ I like Monday.　× I like monday.\\n\\n⚠ つづりの注意\\n・Wednesday は「ウェンズデー」と読むが、つづりには d の音が読まれない部分がある（Wed-nes-dayと3つに分けて覚えると書きやすい）。\\n・Tuesday の発音は「テューズデー」に近く、日本語の「チューズデー」とは少しちがう音。\"},{\"heading\":\"2. 曜日をたずねる・答える表現\",\"body\":\"■ 今日が何曜日かをたずねる\\nWhat day is it today?（今日は何曜日ですか）\\n— It's Monday.（月曜日です）\\n\\n■ 曜日にすることを伝える\\nI have English on Monday.（月曜日に英語の授業があります）\\nI play soccer on Saturday.（土曜日にサッカーをします）\\n★ 曜日の前には on を使う（前置詞のセットで覚える：on Monday, on Sunday）。\\n\\n■ 複数の曜日をまとめて言うとき\\nI have music on Tuesday and Friday.（火曜日と金曜日に音楽があります）\\n\\n⚠ よくある間違い\\n・曜日の前の前置詞を in や at にしてしまう→曜日には on を使うと決まっている（in the morning のように「時の中で幅がある」ものは in、時刻は at、日付・曜日は on と整理する）。\"},{\"heading\":\"3. 一週間についての会話練習\",\"body\":\"【対話例】\\nA: What do you do on Sundays?（あなたは日曜日にいつも何をしますか）\\nB: I play with my friends on Sundays.（日曜日は友達と遊びます）\\n\\n■ 「毎週〜曜日に」というときは曜日を複数形にすることが多い\\non Sundays（毎週日曜日に）\\nI clean my room on Saturdays.（毎週土曜日に部屋を掃除します）\\n\\n■ 週末・平日という言い方\\nweekend（ウィークエンド）＝週末\\nweekday（ウィークデー）＝平日\\nI like weekends.（週末が好きです）\\n\\n★ 覚え方のコツ：Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sundayを歌のリズムに乗せて声に出す練習をすると、順番も発音も自然に身につく。\"},{\"heading\":\"なぜ曜日は大文字で、なぜ on を使うのか\",\"mangaId\":\"new20_e4_eigo_10_manga\",\"body\":\"英語の曜日は、Sunday（太陽の日）・Monday（月の日）のように**神や天体の名前から作られた固有名詞**です。固有名詞は文のとちゅうでも大文字で始めるきまりなので、I like monday. は誤りで I like Monday. と書きます。Wednesday のつづりに読まない d が残っているのも、昔の名前（ウォーデンの日）の形がそのまま残っているからで、Wed-nes-day と三つに分けて覚えます。\\n\\n曜日に on を使うのは、曜日が「一日」という**面**だからです。時こく（点）は at、月（幅）は in で、曜日と日付は on と整理します。「毎週日曜日に」を on Sundays と複数形にするのは、日曜日が何度もくり返されるからです。\\n\\n■ 確かめのしかた\\n①曜日の**最初の文字が大文字**か（Monday）。× monday。\\n②つづり：Wed-nes-day、Tuesday（Tues＋day）、Thursday（th で始まる）、Saturday（u がある）。\\n③曜日の前は **on**（on Monday）。× in Monday、× at Monday。「毎週」なら on Sundays。\\n④What day is it today?→It's Monday. 平日は weekday、週末は weekend。\\n\\n★ ここがポイント：曜日は**神や天体の名前から来た固有名詞**なので大文字。一日という**面**なので **on**。毎週なら複数形（on Sundays）。\",\"figureId\":\"xf_new20_e4_eigo_10\"}],\"keyPoints\":[\"曜日：Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday\",\"曜日の最初の文字は文の途中でも必ず大文字\",\"今日の曜日は What day is it today? — It's 〜. でやりとりする\",\"曜日の前には前置詞 on を使う（on Monday）\",\"「毎週〜曜日に」というときは曜日を複数形にする（on Sundays）\"]}",
"{\"id\":\"new20_e4_eigo_11\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"月の名前と誕生日の伝え方\",\"description\":\"1月から12月までの英単語と、誕生日をたずねる・答える表現を身につける\",\"intro\":\"誕生日について話すのは友達づくりの定番の話題。月の名前を覚えると、自分や友達の誕生日、行事の時期などを英語で伝えられるようになる。\",\"order\":6090,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 1月〜12月の単語\",\"body\":\"12か月の英単語を順番に覚えよう。\\n\\nJanuary（ジャニュアリー）＝1月\\nFebruary（フェブラリー）＝2月\\nMarch（マーチ）＝3月\\nApril（エイプリル）＝4月\\nMay（メイ）＝5月\\nJune（ジューン）＝6月\\nJuly（ジュライ）＝7月\\nAugust（オーガスト）＝8月\\nSeptember（セプテンバー）＝9月\\nOctober（オクトーバー）＝10月\\nNovember（ノーベンバー）＝11月\\nDecember（ディセンバー）＝12月\\n\\n★ 大文字のルール\\n月の名前も曜日と同じで、文の途中でも最初の文字は必ず大文字で書く。\\n\\n⚠ つづりの注意\\n・February は発音でよく r の音が抜け落ちる（「フェブラリー」に近いが「フェビュアリー」のように聞こえることもある）。つづりでは Febr- と r が入っていることを忘れないようにする。\\n・August（8月）と august（形容詞「威厳のある」）はつづりが同じだが、月の意味では必ず大文字で始める。\"},{\"heading\":\"2. 誕生日をたずねる・答える表現\",\"body\":\"■ 誕生日をたずねる\\nWhen is your birthday?（あなたの誕生日はいつですか）\\n\\n■ 「月＋日」の順番で答える\\nMy birthday is April 5th.（私の誕生日は4月5日です）\\n★ 英語では「月→日」の順番。日本語の「4月5日」と同じ順番に感じるが、書くときは April 5 のように書き、5thのように「5番目」を表す序数（じょすう）の形で読むのが基本。\\n\\n■ 日付の読み方（序数）の代表例\\n1st（first）／2nd（second）／3rd（third）／4th（fourth）／5th（fifth）\\n※ 詳しい序数の作り方は別の単元でくわしく学ぶが、日付を読むときによく使われることをここで知っておこう。\\n\\n【対話例】\\nA: When is your birthday?（誕生日はいつですか）\\nB: My birthday is October 10th.（10月10日です）\\nA: Oh, that's next month!（あ、それは来月ですね）\"},{\"heading\":\"3. 月を使った他の表現\",\"body\":\"■ 行事の時期を伝える\\nWe have a school trip in June.（6月に修学旅行があります）\\n★ 「〜月に」というときは前置詞 in を使う（曜日はon、月はinと区別する）。\\n\\n■ 今何月かをたずねる\\nWhat month is it?（今は何月ですか）\\n— It's May.（5月です）\\n\\n■ 季節と月を結びつける\\nspring（春）：March, April, May\\nsummer（夏）：June, July, August\\nfall / autumn（秋）：September, October, November\\nwinter（冬）：December, January, February\\n★ 春は3〜5月、夏は6〜8月のように3か月ずつ区切る。日本の気象の区切り方と同じで、英語圏でもよく使われる区切り方。\\n\\n⚠ よくある間違い\\n・月の前の前置詞をonにしてしまう→月には in を使う（in April）。曜日はon、月・年はinと覚え分ける。\"},{\"heading\":\"なぜ月には in を使い、なぜ日付は序数で読むのか\",\"mangaId\":\"new20_e4_eigo_11_manga\",\"body\":\"月は約30日という**幅のある期間**なので、「その中に」という in を使います（in April）。曜日や日付は一日という面なので on、時こくは点なので at。この三つは「幅→面→点」で整理します。月の名前も曜日と同じく固有名詞なので、文のとちゅうでも大文字で始めます。February の r が発音で抜けやすいのは、つづりが昔の形のまま残っているからで、Febr- と r があることを覚えておきます。\\n\\n日付を序数（5th＝fifth）で読むのは、日付が「その月の**5番目の日**」という順番を表すからです。April 5 と書いても、読むときは April fifth と順番で読みます。季節を3か月ずつに区切る（春＝3・4・5月）のは、日本でも英語圏でも一般的な区切り方なので、そのまま覚えます。\\n\\n■ 確かめのしかた\\n①月の前は **in**（in April）。曜日・日付は on、時こくは at。× on April。\\n②月の**最初の文字が大文字**か。February は Febr- の r を落としていないか。\\n③誕生日は When is your birthday?→My birthday is 月＋日（April 5th）。日は**序数**で読む（1st・2nd・3rd・4th・5th）。\\n④季節：spring＝March・April・May、summer＝June・July・August、fall／autumn＝September・October・November、winter＝December・January・February。\\n\\n★ ここがポイント：月は**幅のある期間**なので **in**、日付は**その月の何番目の日か**なので**序数**で読む。月名も固有名詞なので大文字。\",\"figureId\":\"xf_new20_e4_eigo_11\"}],\"keyPoints\":[\"12か月：January〜December（順番も含めて覚える）\",\"月の名前は文の途中でも必ず大文字で始める\",\"誕生日は When is your birthday? — My birthday is 月+日. でやりとりする\",\"日付は「月→日」の順で言い、日は序数（1st, 2nd, 3rd, 4th…）で読む\",\"「〜月に」は前置詞 in を使う（in April）。曜日のonとの違いに注意\"]}",
"{\"id\":\"new20_e4_eigo_12\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"天気の言い方：It's sunny. など\",\"description\":\"天気を表す基本の単語と、天気をたずねる・答える決まった表現を身につける\",\"intro\":\"天気の話は英語でも日本語でも会話の始まりによく使われる話題。「今日は晴れ」「明日は雨」のように、天気を伝える表現は日常でとても出番が多い。\",\"order\":6091,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 天気を表す単語\",\"body\":\"よく使う天気の単語をまとめて覚えよう。\\n\\nsunny（サニー）＝晴れの\\ncloudy（クラウディ）＝くもりの\\nrainy（レイニー）＝雨の\\nsnowy（スノウィ）＝雪の\\nwindy（ウィンディ）＝風の強い\\nhot（ホット）＝暑い\\ncold（コールド）＝寒い\\nwarm（ウォーム）＝暖かい\\ncool（クール）＝涼しい\\n\\n★ つくりから覚えるコツ\\nsun（太陽）→sunny、cloud（雲）→cloudy、rain（雨）→rainy、snow（雪）→snowy、wind（風）のように、名詞に -y をつけると「〜の（天気）」の形容詞になるものが多い。\\n\\n⚠ よくある間違い\\n・rain（雨・名詞、雨が降る・動詞）と rainy（雨の・形容詞）を混同する→It rains.（雨が降る）と It's rainy.（雨だ）はどちらも使うが、形がちがうことに注意。\"},{\"heading\":\"2. 天気をたずねる・答える表現\",\"body\":\"■ 天気をたずねる決まり文句\\nHow's the weather today?（今日の天気はどうですか）\\nWhat's the weather like today?（今日の天気はどんな様子ですか）\\n\\n■ It's 〜. で答える\\nIt's sunny today.（今日は晴れです）\\nIt's rainy.（雨です）\\nIt's cold today.（今日は寒いです）\\n★ 天気を言うときの主語は必ず it（それ）を使う。「空が」「天気が」という意味を持つ特別な主語で、日本語には訳さない。\\n\\n■ 天気と気持ちをセットで伝える\\nIt's hot today. I want to swim.（今日は暑いです。泳ぎたいです）\\nIt's cold. I want to drink hot tea.（寒いです。温かいお茶が飲みたいです）\",\"figureId\":\"xf_new20_e4_eigo_12\",\"mangaId\":\"new20_e4_eigo_12_xm\"},{\"heading\":\"3. 天気を使った会話練習\",\"body\":\"【対話例】\\nA: How's the weather today?（今日の天気はどうですか）\\nB: It's cloudy and windy.（くもりで風が強いです）\\nA: Do you have an umbrella?（かさは持っていますか）\\nB: No, but it's not rainy yet.（いいえ、でもまだ雨は降っていません）\\n\\n■ 明日の天気について話す\\nIt will be sunny tomorrow.（明日は晴れるでしょう）\\n★ 未来のことを言うときは will（〜だろう）を使う。今の天気（It's 〜.）と、これからの天気（It will be 〜.）の形のちがいに注目しよう。\\n\\n■ 天気にあわせた持ち物・服装の話\\nTake an umbrella. It's rainy.（かさを持っていって。雨だから）\\nWear a coat. It's cold.（コートを着て。寒いから）\\n\\n⚠ 発音のポイント：cloudy の cl は「クラ」ではなく、cとlをなめらかにつなげた「クラウディ」の音。1つずつ区切らず、すべるように発音する。\"}],\"keyPoints\":[\"天気の単語：sunny, cloudy, rainy, snowy, windy, hot, cold, warm, cool\",\"天気をたずねる文は How's the weather today?\",\"天気を言うときの主語は必ず it（It's sunny.）\",\"天気の単語の多くは名詞+yの形（sun→sunny, rain→rainy）\",\"明日以降の天気には will を使う（It will be sunny tomorrow.）\"]}",
"{\"id\":\"new20_e4_eigo_13\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"あいさつの表現：Hello / Good morning など\",\"description\":\"時間帯や場面に応じたあいさつの言い方と、別れのあいさつを身につける\",\"intro\":\"英語の授業やALTの先生との会話は、いつもあいさつから始まる。「おはよう」「こんにちは」を時間帯によって正しく使い分けられると、自然な会話のスタートが切れるようになる。\",\"order\":6092,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 時間帯によるあいさつの使い分け\",\"body\":\"英語のあいさつは、日本語と同じように時間帯によって形が変わる。\\n\\nGood morning.（グッド モーニング）＝おはようございます　※朝、昼くらいまで\\nGood afternoon.（グッド アフタヌーン）＝こんにちは　※昼から夕方まで\\nGood evening.（グッド イブニング）＝こんばんは　※夕方から夜\\nGood night.（グッド ナイト）＝おやすみなさい　※寝る前・夜遅くの別れ際\\n\\n★ ポイント：Good night. は「こんばんは」のあいさつではなく、「おやすみなさい」という別れ・寝る前のあいさつ専用。Good evening.（会ったときのあいさつ）と混同しないように区別する。\\n\\n■ どの時間帯でも使えるあいさつ\\nHello.（ハロー）＝こんにちは\\nHi.（ハイ）＝やあ、こんにちは（Helloよりくだけた言い方）\",\"figureId\":\"xf_new20_e4_eigo_13\",\"mangaId\":\"new20_e4_eigo_13_xm\"},{\"heading\":\"2. あいさつに続くやりとり\",\"body\":\"■ 調子をたずねる・答える\\nHow are you?（元気ですか）\\n— I'm fine, thank you. And you?（元気です、ありがとう。あなたは？）\\n— I'm good.（元気です）\\n— I'm great.（すごく元気です）\\n— I'm tired.（疲れています）\\n\\n★ And you? を付け加えると、相手にも同じ質問を返せる。会話をキャッチボールにするための便利な言い方。\\n\\n■ 天気やあいさつを組み合わせた会話\\nGood morning! How are you today?（おはよう！今日の調子はどう？）\\n— I'm fine. It's a nice day, isn't it?（元気です。いい天気ですね）\"},{\"heading\":\"3. 別れのあいさつと1日の会話の流れ\",\"body\":\"■ 別れるときのあいさつ\\nGoodbye.（グッバイ）＝さようなら\\nBye.（バイ）＝じゃあね（くだけた言い方）\\nSee you.（シー ユー）＝またね\\nSee you tomorrow.（シー ユー トゥモロー）＝また明日\\nTake care.（テイク ケア）＝気をつけてね\\n\\n■ あいさつの一連の流れの例\\nA: Good morning!（おはよう！）\\nB: Good morning! How are you?（おはよう！元気？）\\nA: I'm fine, thank you. And you?（元気です。あなたは？）\\nB: I'm good, thanks.（元気です、ありがとう）\\nA: See you later!（またあとでね！）\\nB: Bye!（バイバイ！）\\n\\n★ あいさつは「時間帯のあいさつ→調子をたずねる→別れのあいさつ」という流れで練習すると、実際の会話の流れがつかみやすい。\\n\\n⚠ よくある間違い：Good night. を人と会ったときのあいさつとして使ってしまう→Good night. は別れるとき・寝るときだけに使う。\"}],\"keyPoints\":[\"時間帯のあいさつ：Good morning / Good afternoon / Good evening（会うとき）\",\"Good night. は別れ・寝る前だけに使うあいさつ\",\"How are you? には I'm fine, thank you. And you? のように答えて返す\",\"別れのあいさつ：Goodbye, Bye, See you, See you tomorrow, Take care\",\"あいさつ→調子をたずねる→別れのあいさつ、という会話の流れで練習する\"]}",
"{\"id\":\"new20_e4_eigo_14\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"自己紹介の言い方：I'm ~. / My name is ~.\",\"description\":\"名前・出身・好きなものを伝える自己紹介の基本表現を身につける\",\"intro\":\"英語の授業の最初の大きな山場が「自己紹介」。名前、出身、好きなものの3つを言えるようになるだけで、立派な自己紹介ができるようになる。\",\"order\":6093,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 名前を伝える2つの言い方\",\"body\":\"自己紹介でまず使うのが名前を伝える表現。2つの言い方を覚えよう。\\n\\nI'm 〜.（アイム〜）＝私は〜です\\n例）I'm Yuki.（私はゆきです）\\n\\nMy name is 〜.（マイ ネーム イズ〜）＝私の名前は〜です\\n例）My name is Yuki.（私の名前はゆきです）\\n\\n★ I'm は I am の短縮形。会話ではI amよりI'mを使うことが多い。\\n★ どちらの言い方も自己紹介では自然に使えるが、My name is 〜. の方がやや丁寧で、初めて会う人への自己紹介に向いている。\\n\\n⚠ よくある間違い\\n・My name is I'm Yuki. のように2つの形を混ぜて言ってしまう→どちらか1つの形にそろえる。\"},{\"heading\":\"2. 出身・住んでいる場所を伝える\",\"body\":\"■ 出身をたずねる・答える\\nWhere are you from?（あなたはどこの出身ですか）\\n— I'm from Japan.（私は日本出身です）\\n— I'm from Osaka.（私は大阪出身です）\\n★ I'm from 〜. の 〜 には国名・都市名を入れる。\\n\\n■ 住んでいる場所を伝える\\nI live in Tokyo.（私は東京に住んでいます）\\n★ 出身（from）と現在住んでいる場所（live in）は形がちがうことに注意。\\n\\n【対話例】\\nA: Where are you from?（どこの出身ですか）\\nB: I'm from Kyoto.（京都出身です）\\nA: Do you live in Kyoto now?（今も京都に住んでいますか）\\nB: Yes, I do.（はい、そうです）\"},{\"heading\":\"3. 好きなものを伝えて自己紹介を完成させる\",\"body\":\"■ 好きなものを伝える\\nI like soccer.（私はサッカーが好きです）\\nI like dogs.（私は犬が好きです）\\nMy favorite color is blue.（私の一番好きな色は青です）\\n\\n■ 自己紹介をひとつの流れにまとめる例\\nHello. My name is Yuki. I'm ten years old. I'm from Osaka. I like soccer and dogs. Nice to meet you.\\n（こんにちは。私の名前はゆきです。10さいです。大阪出身です。サッカーと犬が好きです。よろしくお願いします）\\n\\n■ Nice to meet you. の使い方\\nNice to meet you.（はじめまして）は自己紹介の最後にそえる決まり文句。初めて会う相手にだけ使う（2回目以降に会うときは Nice to see you again. のように少し変える）。\\n\\n★ 自己紹介の型：あいさつ→名前→年れい→出身→好きなもの→Nice to meet you. の順で組み立てると、まとまりのある自己紹介になる。\"},{\"heading\":\"なぜ二つの言い方があり、なぜ from と live in を分けるのか\",\"mangaId\":\"new20_e4_eigo_14_manga\",\"body\":\"I'm 〜. は「私は〜です」と自分をそのまま言う形、My name is 〜. は「私の名前は〜です」と名前を主語にした形です。どちらも自己紹介で使えますが、My name is 〜. のほうがややていねいで、初めて会う人向きです。二つを混ぜて My name is I'm Yuki. とすると、主語が二つになって文がこわれます。どちらか一つの形にそろえます。\\n\\nI'm from 〜（出身）と I live in 〜（住んでいる所）を分けるのは、**生まれ育った場所と今住んでいる場所がちがう**ことがあるからです。from は「〜から来た」という出発点、live in は「〜の中に住んでいる」という今の場所。Where are you from? には I'm from Kyoto.、Do you live in Kyoto now? には Yes, I do. と、聞かれた形で答えます。\\n\\n■ 確かめのしかた\\n①名前は **I'm 〇〇.** か **My name is 〇〇.** のどちらか一つ。混ぜていないか。\\n②出身→**I'm from 〇〇.**（国・都市）、住まい→**I live in 〇〇.** Where are you from? には from で答える。\\n③型の順：あいさつ→名前→年れい→出身→好きなもの→Nice to meet you.\\n④Nice to meet you. は初めて会う相手だけ。二回目以降は Nice to see you again.\\n\\n★ ここがポイント：I'm 〜. と My name is 〜. は**どちらか一つ**（混ぜない）。**from は出身、live in は今の住まい**で、聞かれた形で答える。\",\"figureId\":\"xf_new20_e4_eigo_14\"}],\"keyPoints\":[\"名前を伝える形：I'm 〜. / My name is 〜.\",\"出身は Where are you from? — I'm from 〜. でやりとりする\",\"住んでいる場所は I live in 〜. で伝える（fromとの違いに注意）\",\"好きなものは I like 〜. / My favorite 〜 is … で伝える\",\"自己紹介の最後は Nice to meet you.（はじめまして）で締める\"]}",
"{\"id\":\"new20_e4_eigo_15\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"How are you?とその答え方いろいろ\",\"description\":\"調子・気持ちをたずねる How are you? への多様な答え方を身につける\",\"intro\":\"How are you? はあいさつの単元でも登場した基本の質問だが、答え方は I'm fine. だけではない。うれしいとき、疲れているとき、体調が悪いときなど、気持ちにあわせた答え方を増やしてみよう。\",\"order\":6094,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. How are you?へのいろいろな答え方\",\"body\":\"気持ちや調子を表す形容詞を使って、答えのバリエーションを増やそう。\\n\\nI'm fine.（元気です）\\nI'm good.（元気です）\\nI'm great.（すごく元気です）\\nI'm happy.（うれしいです）\\nI'm OK.（まあまあです）\\nI'm tired.（疲れています）\\nI'm sleepy.（眠いです）\\nI'm sad.（悲しいです）\\nI'm hungry.（お腹がすいています）\\nI'm sick.（具合が悪いです）\\n\\n★ ポイント：I'm のあとに気持ち・様子を表す形容詞を1つ入れるだけで答えが完成する、とてもシンプルな形。\"},{\"heading\":\"2. 理由を付け加える言い方\",\"body\":\"気持ちだけでなく、その理由もセットで伝えられるようになると会話が広がる。\\n\\nI'm happy because it's my birthday today.（今日は誕生日なのでうれしいです）\\nI'm tired because I ran a lot.（たくさん走ったので疲れています）\\nI'm hungry because I didn't eat breakfast.（朝ごはんを食べなかったのでお腹がすいています）\\n\\n★ because（〜だから）を使うと、「気持ち＋理由」の2つの情報を1つの文で伝えられる。\\n\\n【対話例】\\nA: How are you today?（今日の調子はどう？）\\nB: I'm a little tired.（ちょっと疲れています）\\nA: Why?（どうして？）\\nB: Because I practiced soccer this morning.（今朝サッカーを練習したから）\",\"figureId\":\"xf_new20_e4_eigo_15\",\"mangaId\":\"new20_e4_eigo_15_xm\"},{\"heading\":\"3. 相手の様子をたずねる・気づかう表現\",\"body\":\"■ 相手が元気なさそうなときの声かけ\\nAre you OK?（大丈夫ですか）\\nWhat's wrong?（どうしたの？）\\n— I have a headache.（頭が痛いです）\\n— I don't feel well.（気分がよくないです）\\n\\n■ 元気づける・励ます一言\\nTake care.（お大事に）\\nGet well soon.（早くよくなってね）\\n\\n★ How are you? の答えは1つに決まっているわけではなく、そのときの本当の気持ちを表現していい。fine 以外の言葉もたくさん覚えておくと、より自分らしい受け答えができるようになる。\\n\\n⚠ よくある間違い：I'm fine. とだけ覚えて、どんなときも同じ答えを繰り返してしまう→場面に合わせていろいろな形容詞を使い分ける練習をしよう。\"}],\"keyPoints\":[\"How are you? への答え：I'm fine/good/great/happy/OK/tired/sleepy/sad/hungry/sick.\",\"because 〜 で気持ちの理由を付け加えられる\",\"相手を気づかう表現：Are you OK? / What's wrong? / Take care.\",\"体調がよくないときは I don't feel well. / I have a headache. と伝える\",\"How are you? の答えはfine以外にも場面に合わせて使い分ける\"]}",
"{\"id\":\"new20_e4_eigo_16\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"What's this?でものをたずねる\",\"description\":\"身近なものについてたずねる What's this? / What's that? の使い方を身につける\",\"intro\":\"見たことのないものや名前がわからないものを見せられたとき、英語では What's this?（これは何？）とたずねる。クイズやゲームのような感覚で楽しく練習できる、とても実用的な表現だ。\",\"order\":6095,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. What's this? / What's that? の使い分け\",\"body\":\"■ What's this?（近くにあるもの）\\nWhat's this?（これは何ですか）\\n— It's an apple.（りんごです）\\n★ this（これ）は自分の近くにあるものを指すときに使う。\\n\\n■ What's that?（遠くにあるもの）\\nWhat's that?（あれは何ですか）\\n— It's a bird.（鳥です）\\n★ that（あれ）は自分から離れた場所にあるものを指すときに使う。\\n\\n★ What's は What is の短縮形。会話ではWhat is thisよりWhat's thisの方がよく使われる。\\n\\n⚠ よくある間違い：thisとthatを距離に関係なく使い分けずに使ってしまう→近くならthis、遠くならthatと、距離のイメージで覚える。\"},{\"heading\":\"2. 答え方のバリエーション\",\"body\":\"■ It's a/an 〜. で答える基本形\\nIt's a pen.（ペンです）\\nIt's an orange.（オレンジです）※母音で始まる語にはan\\n\\n■ 複数のものについてたずねる：What are these? / What are those?\\nWhat are these?（これらは何ですか）\\n— They are apples.（りんごです）\\n★ 複数のものについてたずねるときは、this→these、that→those、it's→they areのように、単数と複数で形がすべて変わる。\\n\\n■ 対応表（単数・複数）\\nthis（これ）⇔ these（これら）\\nthat（あれ）⇔ those（あれら）\\nIt's 〜.（それは〜です）⇔ They are 〜.（それらは〜です）\"},{\"heading\":\"3. クイズ形式の会話練習\",\"body\":\"【対話例（近くのもの）】\\nA: What's this?（これは何？）\\nB: It's a pencil.（えんぴつだよ）\\n\\n【対話例（遠くのもの）】\\nA: What's that?（あれは何？）\\nB: It's a car.（車だよ）\\n\\n【対話例（複数のもの）】\\nA: What are these?（これらは何？）\\nB: They are books.（本だよ）\\n\\n■ このやりとりを使ったクイズ遊び\\nかばんの中のものを見せて What's this? と友達にたずねる、絵カードを使って What's that? で当てっこをする、といった活動を通じて、ものの名前と一緒に自然にこの表現が身につく。\\n\\n★ ポイントまとめ：this/that、these/thoseは「近い・遠い」と「単数・複数」の2つの区別が同時に関わってくる。表にして整理しながら覚えると混乱しにくい。\"},{\"heading\":\"なぜ this と that、these と those を分けるのか\",\"mangaId\":\"new20_e4_eigo_16_manga\",\"body\":\"英語では、ものを指すときに**話し手からの距離**と**数**の二つを言葉で区別します。近くにあれば this、離れていれば that。日本語の「これ・あれ」と同じ区別です。さらに、指すものが二つ以上なら these・those と形が変わり、答えの It's 〜. も They are 〜. に変わります。日本語では「これ」と「これら」をあまり使い分けませんが、英語では単数と複数で文の形が全部変わるので、対応表で整理しておきます。\\n\\nWhat's が What is の短縮形なのは、会話では短く言うほうが自然だからです。答えの a と an は、次の語が母音（a・i・u・e・o の音）で始まるかどうかで決まります（an apple・an orange）。\\n\\n■ 確かめのしかた\\n①指すものが**近いか遠いか**：近い→this／these、遠い→that／those。\\n②**一つか二つ以上か**：一つ→What's this?→It's a 〇〇.、二つ以上→What are these?→They are 〇〇s.\\n③答えの a／an は次の語の**最初の音**で決める（a pen、an orange）。\\n④対応表で確かめる：this⇔these、that⇔those、It's⇔They are。\\n\\n★ ここがポイント：英語は**距離（this／that）と数（単数／複数）の二つ**を言葉で区別する。**複数になると質問も答えも形が変わる**（What are these?→They are 〜.）。\",\"figureId\":\"xf_new20_e4_eigo_16\"}],\"keyPoints\":[\"近くのものは What's this? — It's a/an 〜.\",\"遠くのものは What's that? — It's a/an 〜.\",\"複数のものは What are these? / What are those? — They are 〜.\",\"this→these、that→those、it's→they areと単数複数で形が変わる\",\"What'sはWhat isの短縮形\"]}",
"{\"id\":\"new20_e4_eigo_17\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"教室でよく使う先生の指示表現\",\"description\":\"授業中に先生がよく使う指示のことばと、それに応じた動作を結びつけて覚える\",\"intro\":\"英語の授業は先生の指示も英語で行われることが多い。Stand up.（立って）やListen.（聞いて）のような短い指示を聞いてすぐ動けるようになると、授業がぐっと楽しくなる。\",\"order\":6096,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 動作を表す基本の指示\",\"body\":\"先生がよく使う、動作をうながす指示のことばを覚えよう。これらはすべて「命令文」という、主語を省いて動詞から始める文の形。\\n\\nStand up.（スタンド アップ）＝立ちなさい\\nSit down.（シット ダウン）＝座りなさい\\nListen.（リスン）＝聞きなさい\\nLook at me.（ルック アット ミー）＝私を見なさい\\nRepeat after me.（リピート アフター ミー）＝私のあとについて言いなさい\\nRaise your hand.（レイズ ユア ハンド）＝手を挙げなさい\\nCome here.（カム ヒア）＝ここに来なさい\\n\\n★ 命令文の形：動詞をそのまま文の最初に置く（主語Youは言わない）。日本語の「〜しなさい」「〜して」にあたる。\\n\\n⚠ Listen. のあとに to をつけて聞く対象を言うこともある（Listen to me.＝私の話を聞いて）。ただ Listen. だけでも「聞いて」という指示として使える。\",\"figureId\":\"xf_new20_e4_eigo_17\",\"mangaId\":\"new20_e4_eigo_17_xm\"},{\"heading\":\"2. 教材・持ち物に関する指示\",\"body\":\"授業中の道具や教材に関する指示も、よく使われるので覚えておこう。\\n\\nOpen your textbook.（オープン ユア テキストブック）＝教科書を開きなさい\\nClose your book.（クローズ ユア ブック）＝本を閉じなさい\\nTake out your notebook.（テイク アウト ユア ノートブック）＝ノートを出しなさい\\nWrite your name.（ライト ユア ネーム）＝名前を書きなさい\\nTurn to page 10.（ターン トゥ ページ テン）＝10ページを開きなさい\\n\\n★ page＋数字 で「〜ページ」を表す。Turn to page 10.（10ページを開く）のように、指示の中でよく数字と組み合わさる。\\n\\n⚠ Open your textbook. と Close your book. のように、textbook（教科書）とbook（本）が言いかえられることもあるが、意味はほぼ同じと考えてよい。\"},{\"heading\":\"3. 指示に応じるときの表現\",\"body\":\"■ 指示がわからなかったときにたずねる表現\\nPardon?（もう一度言ってください）\\nOne more time, please.（もう一度お願いします）\\nI don't understand.（わかりません）\\n\\n■ 指示に従った・理解したことを伝える\\nOK.（わかりました）\\nI see.（わかりました）\\nSure.（了解です）\\n\\n【授業の流れの例】\\nTeacher: Stand up, please.（立ってください）\\nStudents: (立ち上がる)\\nTeacher: Open your textbook to page 5.（教科書の5ページを開いてください）\\nStudents: OK.（わかりました）\\n\\n★ ポイント：命令文には please をつけると、少していねいな言い方になる（Stand up, please.）。先生の指示にもよくpleaseがついている。\"}],\"keyPoints\":[\"動作の指示：Stand up. / Sit down. / Listen. / Look at me. / Raise your hand.\",\"教材の指示：Open your textbook. / Close your book. / Take out your notebook.\",\"命令文は主語を省いて動詞から文を始める形\",\"pleaseをつけると指示がていねいになる（Stand up, please.）\",\"わからないときは Pardon? / One more time, please. とたずねてよい\"]}",
"{\"id\":\"new20_e4_eigo_18\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"教室でよく使うお願い・返事の表現\",\"description\":\"授業中に自分から使う「貸して・トイレに行きたい」などのお願い表現と、その返事の仕方を身につける\",\"intro\":\"前の単元では先生からの指示を学んだが、今度は自分から先生や友達に伝える表現。「消しゴムを貸して」「トイレに行ってもいいですか」など、教室で毎日使える実用的な言い回しを身につけよう。\",\"order\":6097,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. 物を貸してほしいときの表現\",\"body\":\"■ Can I borrow 〜?（〜を借りてもいいですか）\\nCan I borrow your eraser?（消しゴムを借りてもいいですか）\\n— Sure. Here you are.（いいよ。どうぞ）\\n— Sorry, I don't have one.（ごめん、持っていません）\\n\\n■ Can I use 〜?（〜を使ってもいいですか）\\nCan I use your pencil?（えんぴつを使ってもいいですか）\\n\\n★ borrow（借りる）と use（使う）のちがい：borrowは「持ち帰ってもよいくらい借りる」、useは「その場で使う」というニュアンスのちがいがあるが、教室ではどちらもよく使われる。\\n\\n⚠ Here you are.（どうぞ）は物を手渡すときの決まり文句。物を受け取るときの Thank you. とセットで覚えておく。\"},{\"heading\":\"2. 先生に許可を求める表現\",\"body\":\"■ Can I 〜?（〜してもいいですか）\\nCan I go to the restroom?（トイレに行ってもいいですか）\\nCan I drink water?（水を飲んでもいいですか）\\nCan I open the window?（窓を開けてもいいですか）\\n\\n■ 先生の返事\\nYes, you can.（はい、いいですよ）\\nSure, go ahead.（もちろん、どうぞ）\\nSorry, not now.（ごめんなさい、今はだめです）\\nWait a minute, please.（少し待ってください）\\n\\n★ Can I 〜? は「許可を求める」ときの決まった形。友達に対しても先生に対しても使える便利な表現。\\n\\n⚠ May I 〜? という、Can I 〜?よりもややていねいな言い方もある（中学以降でくわしく学ぶ）。小学校ではまずCan I 〜?を使いこなせるようにしよう。\",\"figureId\":\"xf_new20_e4_eigo_18\",\"mangaId\":\"new20_e4_eigo_18_xm\"},{\"heading\":\"3. 助けを求める・困ったときの表現\",\"body\":\"■ わからない・困ったときに伝える表現\\nI don't know.（わかりません）\\nHelp me, please.（助けてください）\\nCan you help me?（手伝ってもらえますか）\\nI need a pencil.（えんぴつが必要です）\\n\\n■ 相手を助けるときの返事\\nSure, I'll help you.（もちろん、手伝うよ）\\nNo problem.（いいよ〈問題ないよ〉）\\n\\n【教室での会話例】\\nA: Can I borrow your ruler?（じょうぎを借りてもいいですか）\\nB: Sure. Here you are.（いいよ。どうぞ）\\nA: Thank you.（ありがとう）\\nB: You're welcome.（どういたしまして）\\n\\n★ You're welcome.（どういたしまして）は Thank you. への決まった返事。あいさつと同じくらいよく使うので、セットで覚えておこう。\"}],\"keyPoints\":[\"物を借りるときは Can I borrow 〜? / Can I use 〜?\",\"許可を求めるときは Can I 〜? （Can I go to the restroom?など）\",\"許可の返事：Yes, you can. / Sure, go ahead. / Sorry, not now.\",\"助けを求めるときは Help me, please. / Can you help me?\",\"Thank you. への返事は You're welcome.\"]}",
"{\"id\":\"new20_e4_eigo_19\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"好きなものを伝える：I like ~. / Do you like ~?\",\"description\":\"I like ~. の基本の形と、好きかどうかをたずねる質問文の作り方を身につける\",\"intro\":\"「好き」を伝える I like ~. は、英語の授業でもっとも早く出会う文の形の1つ。スポーツ、食べ物、教科など、いろいろな名詞と組み合わせて使ってみよう。\",\"order\":6098,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. I like ~. の基本の形\",\"body\":\"■ 好きなものを伝える\\nI like soccer.（私はサッカーが好きです）\\nI like apples.（私はりんごが好きです）\\nI like music.（私は音楽が好きです）\\n\\n★ like（好き）のあとには「好きなもの（名詞）」をそのまま続ける。日本語の「〜が好き」のように「が」にあたる語は英語にはいらない。\\n\\n■ 好きではないものを伝える\\nI don't like natto.（私は納豆が好きではありません）\\n★ don't（do not の短縮形）をlikeの前に置くと「好きではない」という否定の意味になる。\\n\\n⚠ よくある間違い：I not like 〜. のように don't を使わずに not だけを置いてしまう→一般動詞（like）を否定するときは必ず don't（またはdoesn't）を使う。\",\"mangaId\":\"new20_e4_eigo_19_xm\"},{\"heading\":\"2. Do you like ~?でたずねる\",\"body\":\"■ 好きかどうかをたずねる形\\nDo you like dogs?（あなたは犬が好きですか）\\n— Yes, I do.（はい、好きです）\\n— No, I don't.（いいえ、好きではありません）\\n\\n★ 疑問文の形：Do you 〜? の形にして、文の最後に ? をつける。答えるときは Yes, I do. / No, I don't. の決まった形を使う。\\n\\n■ 何が好きかをたずねる\\nWhat sport do you like?（どんなスポーツが好きですか）\\n— I like basketball.（バスケットボールが好きです）\\nWhat food do you like?（どんな食べ物が好きですか）\\n— I like pizza.（ピザが好きです）\\n\\n★ What＋名詞＋do you like? の形で「どんな〜が好き？」という具体的な質問ができる。\",\"figureId\":\"xf_new20_e4_eigo_19\"},{\"heading\":\"3. いろいろな話題でI like ~.を使う練習\",\"body\":\"■ いろいろな名詞と組み合わせる\\nI like English.（英語が好きです）※教科\\nI like summer.（夏が好きです）※季節\\nI like rainy days.（雨の日が好きです）※少し変わった好み\\n\\n■ 理由をつけ加える\\nI like soccer because it's fun.（サッカーは楽しいので好きです）\\nI like dogs because they are cute.（犬はかわいいので好きです）\\n\\n【対話例】\\nA: Do you like sports?（スポーツは好きですか）\\nB: Yes, I do. I like swimming.（はい、好きです。水泳が好きです）\\nA: Me too!（私も！）\\n\\n★ Me too!（私も！）は相手と同じ意見や好みだったときに使う便利な一言。会話にリズムを生む決まり文句として覚えておこう。\"}],\"keyPoints\":[\"好きを伝える形：I like 〜.（likeのあとに好きな名詞をそのまま続ける）\",\"好きではないときは I don't like 〜.\",\"たずねるときは Do you like 〜? — Yes, I do. / No, I don't.\",\"What＋名詞＋do you like? で具体的な好みをたずねられる\",\"Me too!（私も！）は相手と同じ好みのときに使う決まり文句\"]}",
"{\"id\":\"new20_e4_eigo_20\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"できることを伝える：I can ~. / Can you ~?\",\"description\":\"「〜できる」を表すI can ~.の形と、相手にできるかたずねるCan you ~?の使い方を身につける\",\"intro\":\"「泳げる」「自転車に乗れる」のように、自分ができることを伝える表現は、友達と自己紹介し合うときの人気の話題。canという短い語1つで「できる」という意味を加えられる、とても便利な言い方だ。\",\"order\":6099,\"studyPeriod\":\"小4\",\"sections\":[{\"heading\":\"1. I can ~. でできることを伝える\",\"body\":\"■ 基本の形\\nI can swim.（私は泳げます）\\nI can ride a bike.（私は自転車に乗れます）\\nI can play the piano.（私はピアノをひけます）\\nI can cook.（私は料理ができます）\\n\\n★ can（〜できる）のあとには動詞の原形（そのままの形）を続ける。三人称単数のsをつけない、というのが大事なポイント（He can swim. も swims にしない）。\\n\\n■ できないことを伝える\\nI can't swim.（私は泳げません）※ can't は cannot の短縮形\\nI can't ski.（私はスキーができません）\\n\\n⚠ よくある間違い：canのあとの動詞にsやingをつけてしまう→canのあとは必ず動詞の原形（動詞そのままの形）にする。\"},{\"heading\":\"2. Can you ~?でたずねる\",\"body\":\"■ 相手ができるかどうかをたずねる\\nCan you swim?（あなたは泳げますか）\\n— Yes, I can.（はい、できます）\\n— No, I can't.（いいえ、できません）\\n\\n★ 疑問文の形：canを主語の前に出す（Can you 〜?）。答えは Yes, I can. / No, I can't. の決まった形。\\n\\n■ できることをたずね合う会話\\nWhat can you do?（あなたは何ができますか）\\n— I can play soccer well.（サッカーが上手にできます）\\n★ well（上手に）のような副詞をcanの文につけ加えると、できる程度も伝えられる。\"},{\"heading\":\"3. できることを使った会話練習とまとめ\",\"body\":\"【対話例】\\nA: Can you play the guitar?（ギターをひけますか）\\nB: No, I can't. But I can play the recorder.（いいえ、できません。でもリコーダーはふけます）\\nA: That's great!（すごいね！）\\n\\n■ 友達を紹介するときの表現\\nMy friend can run very fast.（私の友達はとても速く走れます）\\nHe can speak English well.（彼は英語を上手に話せます）\\n\\n■ できること探しゲームの言い方\\nFind a friend who can whistle.（口笛をふける友達を見つけよう）のような活動では、Can you whistle? とたずねながら教室を回る。\\n\\n★ ポイントまとめ\\n・I can 〜.：できることを伝える\\n・I can't 〜.：できないことを伝える\\n・Can you 〜?：たずねる（答えはYes, I can. / No, I can't.）\\n・canのあとの動詞は必ず原形のまま\"},{\"heading\":\"なぜ can のあとは原形で、なぜ Can you? に can で答えるのか\",\"mangaId\":\"new20_e4_eigo_20_manga\",\"body\":\"can は「〜できる」という意味を動詞に**足す**語（助動詞）です。主語に合わせて形を変える役目は can が引き受けるので、あとの動詞はそのままの形（原形）でよく、He can swim. のように三人称でも s を付けません。s や ing を付けるのは、can が「動詞のかわりに形を担当している」ことを忘れているからです。\\n\\nたずねる文が Can you swim? と can を主語の前に出す形なのは、be動詞の疑問文（Are you 〜?）と同じ作り方です。答えは、質問に使った can をくり返して Yes, I can. / No, I can't. と言います。can't は cannot の短縮形で、それ自体に打ち消しが入っています。\\n\\n■ 確かめのしかた\\n①can のあとの動詞が**原形**か。He can swim.（× can swims、× can swimming）。\\n②たずねる文は **can を主語の前**に：Can you swim?\\n③答えは **Yes, I can. / No, I can't.**（質問の can をくり返す）。\\n④できないことは I can't 〇〇.、程度は well（I can play soccer well.）、広くたずねるなら What can you do?\\n\\n★ ここがポイント：can は動詞に「できる」を**足す語**で、形の変化を can が引き受けるので**あとは原形**。たずねるときは can を前に出し、答えは **can をくり返す**。\",\"figureId\":\"xf_new20_e4_eigo_20\"}],\"keyPoints\":[\"できることは I can 動詞の原形. で伝える（I can swim.）\",\"できないことは I can't（cannot）〜.\",\"たずねるときは Can you 〜? — Yes, I can. / No, I can't.\",\"canのあとの動詞にはsやingをつけない（原形のまま）\",\"What can you do? で相手ができることを広くたずねられる\"]}",
"{\"id\":\"new20_e5_eigo_01\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"体調を伝える表現：I have a headache.\",\"description\":\"頭が痛い・お腹が痛い・熱があるなど、体調がよくないことを伝える言い方をまとめる\",\"intro\":\"学校で「頭が痛い」「おなかが痛い」と伝えたいとき、日本語では体の部分を主語にして「〜が痛い」と言いますが、英語では I を主語にして I have a headache. のように「持っている」という言い方をします。ここでは体調を伝えるときの決まった型を身につけます。\",\"order\":6580,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"I have a headache.（頭が痛いです）のように、〈I have +症状の名詞〉で体調不良を伝える。\",\"headache（頭痛）・stomachache（腹痛）・toothache（歯痛）・backache（腰痛・背中の痛み）はどれも -ache（痛み）が付く。\",\"a cold（かぜ）・a fever（熱）・a cough（せき）にも have を使う：I have a cold. / I have a fever.\",\"「気分が悪い」は I feel sick. または I don't feel well.。feel（感じる）＋形容詞の形。\",\"相手を気づかうときは What's wrong? / What's the matter? （どうしたの？）と聞き、Are you OK? と続けるのが自然。\",\"「お大事に」は Take care. または Get well soon.。\"],\"sections\":[{\"heading\":\"〈have＋症状〉で体調の悪さを伝える\",\"body\":\"日本語では「頭が痛い」のように体の部分を主語にしますが、英語では I（私）を主語にして、have（持っている）を使って症状を「持っている」という言い方をします。まずこの発想の切りかえが第一歩です。\\n\\n■ 基本の型：I have a(n) 〜.\\n・I have a headache.（頭が痛いです）ヘッド＋エイク＝「頭の痛み」\\n・I have a stomachache.（おなかが痛いです）スタマック＋エイク\\n・I have a toothache.（歯が痛いです）トゥース＋エイク\\n・I have a backache.（背中・腰が痛いです）バック＋エイク\\n・I have a fever.（熱があります）フィーヴァー\\n・I have a cold.（かぜをひいています）\\n・I have a cough.（せきが出ます）コーフ、gh は f の音になる点に注意\\n・I have a runny nose.（鼻水が出ます）\\n\\nache（エイク）は「ジーンとする痛み」を表す語で、体の部分の名前とくっついて一語になります。header, stomacher のように -er を付けるのではなく -ache であることに注意しましょう。つづりを覚えるときは head＋ache、stomach＋ache と分けて考えると混同しません。\\n\\n■ 冠詞 a を忘れない\\nhave a headache のように a を付けるのがふつうです。ただし have a fever（熱がある）は「熱」という状態を一つ持つイメージ、have a cold（かぜをひいている）も同じく a が必要です。「風邪」を無冠詞で have cold としないよう注意しましょう。\",\"figureId\":\"xf_new20_e5_eigo_01\"},{\"heading\":\"「気分が悪い」を伝える feel の使い方\",\"mangaId\":\"new20_e5_eigo_01_manga\",\"body\":\"症状の名前がはっきりしないときや、全体的な気分の悪さを伝えるときは feel（感じる）を使います。feel は動詞のあとに形容詞をそのまま置く点が特徴です。\\n\\n■ feel＋形容詞\\n・I feel sick.（気分が悪いです）\\n・I don't feel well.（体調がよくありません）well はここでは「元気な」という形容詞として使われている\\n・I feel tired.（疲れています）\\n・I feel dizzy.（めまいがします）ディズィー\\n\\n⚠ よくある間違い：I feel sickly. のように -ly を付けてしまうミスがあります。sickly は「病弱な」という別の意味の形容詞になってしまうので、症状を伝えるときは feel sick（気分が悪い）のままで使いましょう。\\n\\n■ 相手の体調を気づかう表現\\n・What's wrong?（どうしたの？）／What's the matter?（どうかしたの？）\\n・Are you OK? / Are you all right?（大丈夫？）\\n・You should see a doctor.（お医者さんに診てもらったほうがいいよ）should（〜すべきだ）を使った助言の言い方\\n・Take care.（お大事に）／Get well soon.（早くよくなってね）\\n\\n会話の流れとしては、A: What's wrong? → B: I have a stomachache. → A: That's too bad. You should go home and rest.（それは大変。家に帰って休んだほうがいいよ）のように、症状を聞く→答える→助言する、という順番で進むことが多く、長文の対話問題でもこの流れをつかんでおくと解きやすくなります。\"}],\"trapExamples\":[{\"question\":\"「私は頭が痛いです。」を英語にしなさい。\",\"wrongAnswer\":\"My head is hurt.\",\"trapExplanation\":\"日本語の「頭が痛い」につられて head を主語にし、「痛める」という意味の hurt を無理に使ってしまう。My head is hurt. は「私の頭がけがをさせられた」という不自然な文になる。\",\"correctAnswer\":\"I have a headache.\",\"correctExplanation\":\"英語では体調の悪さは I を主語にし、have＋症状名の形で表すのが基本。My head hurts.（頭が痛む）という言い方も可能だが、その場合も主語は my head、動詞は hurt（自動詞・現在形は hurts）であり、is hurt という受け身にはしない。まずは I have a headache. の型を確実に覚えることが優先。\"}]}",
"{\"id\":\"new20_e5_eigo_02\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"誕生日と年齢をたずねる・答える表現\",\"description\":\"How old are you? / When is your birthday? など、年齢・誕生日にまつわる会話表現をまとめる\",\"intro\":\"自己紹介や会話文の読解でよく出てくるのが、年齢や誕生日についてのやり取りです。「あなたは何歳ですか」「誕生日はいつですか」という質問と、それに対する自然な答え方をセットで身につけましょう。数字と月の名前の復習にもなります。\",\"order\":6581,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"年齢をたずねる：How old are you?→答え：I'm eleven years old. または I'm eleven.\",\"誕生日をたずねる：When is your birthday?→答え：My birthday is May 5th.（日付は序数で読む）\",\"「〜歳になる」は turn を使う：I'll turn twelve next month.（来月12歳になります）\",\"年齢は years old を省略してもよいが、単に I'm eleven years. とは言えない点に注意。\",\"日付は月→日の順（アメリカ式）：May 5th, October 21st のように読む。序数（-th, -st, -nd, -rd）を使う。\",\"How old is he/she?（彼・彼女は何歳ですか）にも同じ形で答える：He is ten years old.\"],\"sections\":[{\"heading\":\"年齢をたずねる・答える\",\"mangaId\":\"new20_e5_eigo_02_manga\",\"body\":\"年齢をたずねるときは How old are you?（あなたは何歳ですか）という決まった疑問文を使います。old は「古い」という意味だけでなく「〜歳の」という意味でも使われる点がポイントです。\\n\\n■ たずね方と答え方\\n・How old are you?（あなたは何歳ですか）\\n・I'm eleven years old.（私は11歳です）／短く I'm eleven. だけでも通じる\\n・How old is your brother?（あなたのお兄さんは何歳ですか）\\n・He is fourteen years old.（彼は14歳です）\\n\\n⚠ よくある間違い：I'm eleven years. と years old の old を落としてしまうミス。years だけでは「11年間」という意味になり、年齢の言い方として不自然になります。years old をワンセットで覚えましょう。ただし I'm eleven. のように years old を丸ごと省略するのは問題ありません。\\n\\n■ 「〜歳になる」turn の使い方\\n誕生日が来て年齢が変わることを表すときは turn（〜に変わる）を使います。\\n・I'll turn twelve next month.（私は来月12歳になります）\\n・She turned ten last week.（彼女は先週10歳になりました）\\nhave my birthday（誕生日を迎える）という言い方も使われますが、「何歳になる」を直接言いたいときは turn が便利です。\"},{\"heading\":\"誕生日をたずねる・日付の読み方\",\"body\":\"誕生日をたずねるときは When is your birthday?（あなたの誕生日はいつですか）を使います。where（どこ）と間違えないよう注意しましょう。\\n\\n■ たずね方と答え方\\n・When is your birthday?（誕生日はいつですか）\\n・My birthday is May 5th.（私の誕生日は5月5日です）\\n・My birthday is on May 5th. と on を付けることもできる（特定の日を表すので on）\\n\\n■ 日付の読み方（序数を使う）\\n英語で日付を言うときは、1日・2日ではなく「1番目の日・2番目の日」という序数（じゅんばんを表す形）で読みます。\\n・1st＝first（ファースト）／2nd＝second（セカンド）／3rd＝third（サード）\\n・4日〜20日はふつう -th を付ける：4th＝fourth、5th＝fifth（発音に注意、フィフスに近い）、9th＝ninth（eを一つ落とす）、12th＝twelfth\\n・21st＝twenty-first、22nd＝twenty-second、23rd＝twenty-third のように、一の位が1・2・3のときは first・second・third の形にもどる\\n\\n■ 月と日の順番\\nアメリカ式では「月→日」の順で書くのがふつうです（May 5 のように）。日本語の「5月5日」と同じ感覚で「月、日」の順に読めば大丈夫です。会話文読解では、誕生日パーティーの招待やカレンダーの話題でこの表現がよく登場するので、序数の読み方とセットで慣れておきましょう。\",\"figureId\":\"xf_new20_e5_eigo_02\"}],\"trapExamples\":[{\"question\":\"「私は来月12歳になります。」を英語にしなさい。\",\"wrongAnswer\":\"I become twelve years old next month.\",\"trapExplanation\":\"「〜になる」を機械的に become に訳してしまう。become は間違いではないが、誕生日で年齢が変わることを表す場合は turn を使うのが自然な言い方であり、中学受験でもそちらが好まれる。\",\"correctAnswer\":\"I'll turn twelve next month.\",\"correctExplanation\":\"年齢が一つ上がることを表すときは turn を使うのが標準的な言い方。「来月」という未来のことなので will（短縮形 'll）も忘れずに付ける。become は職業や状態の変化（become a teacherなど）でよく使われる語であり、年齢にはturnがより自然。\"}]}",
"{\"id\":\"new20_e5_eigo_03\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"得意・不得意を伝える：good at / poor at\",\"description\":\"I'm good at swimming. のように、be good at / be poor at を使って得意・不得意を伝える表現を学ぶ\",\"intro\":\"「私は水泳が得意です」「私は歌が苦手です」というように、自分の得意なこと・苦手なことを伝える表現は自己紹介や作文でとてもよく使われます。be good at と be poor at（be bad at）の使い方、そして後ろに続く動詞の形に注目して学びましょう。\",\"order\":6582,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「〜が得意だ」は be good at 〜。at のあとに名詞または動詞のing形（動名詞）を置く。\",\"I'm good at swimming.（私は泳ぐのが得意です）／I'm good at math.（私は算数が得意です）\",\"「〜が苦手だ」は be poor at 〜 または be bad at 〜。意味はほぼ同じだが poor at の方がやわらかい響きになる。\",\"at のあとに動詞を置くときは必ず ing形にする：good at play ✕ → good at playing ○。\",\"「〜するのが得意」は be good at のほかに、be a good 〜er（〜する人として上手）の言い方もある：He is a good singer.（彼は歌うのが上手だ＝彼は上手な歌い手だ）\",\"比較して伝えたいときは、better at（〜の方が得意）という比較級も使える：I'm better at math than English.\"],\"sections\":[{\"heading\":\"be good at / be poor at の基本の形\",\"mangaId\":\"new20_e5_eigo_03_manga\",\"body\":\"「〜が得意だ」を表す最も基本的な言い方が be good at 〜 です。at は「〜の点において」という意味を持つ前置詞で、good at で「〜の点において上手だ」というイメージになります。\\n\\n■ at のあとに名詞を置く場合\\n・I'm good at math.（私は算数が得意です）\\n・She is good at soccer.（彼女はサッカーが得意です）\\n・He is good at English.（彼は英語が得意です）\\n教科・スポーツ・楽器などの名詞をそのまま at のあとに置くだけで文が完成します。\\n\\n■ at のあとに動詞を置く場合はing形にする\\n「泳ぐのが得意」「料理をするのが得意」のように動作を表したいときは、動詞をそのままの形（原形）で置いてはいけません。at は前置詞なので、あとに動詞が来るときは必ず ing形（動名詞）にします。\\n・I'm good at swimming.（私は泳ぐのが得意です）swim → swimming\\n・He is good at cooking.（彼は料理をするのが得意です）cook → cooking\\n・They are good at dancing.（彼らはおどるのが得意です）dance → dancing、eを取ってing\\n\\n⚠ よくある間違い：I'm good at swim. のように動詞の原形のままにしてしまうミスが非常に多い。「前置詞のあとの動詞はing形」というルールは不定詞（to swim）と混同しやすいので、be good at のときは to ではなく ing、と声に出して覚えておきましょう。\",\"figureId\":\"xf_new20_e5_eigo_03\"},{\"heading\":\"「苦手」の言い方と、似た表現とのちがい\",\"body\":\"「苦手だ」「下手だ」を伝えるときは be poor at 〜 または be bad at 〜 を使います。意味はほぼ同じですが、poor at の方が少しやわらかく、bad at ははっきりと「下手」という印象を与えます。\\n\\n■ 苦手を伝える表現\\n・I'm poor at swimming.（私は泳ぐのが苦手です）\\n・I'm not good at math.（私は算数が得意ではありません）not good at という否定の形もよく使われ、poor at より遠回しでやわらかい響きになる\\n・I'm bad at drawing.（私は絵をかくのが下手です）\\n\\n■ 「上手な〜する人」で表す言い方\\nbe good at のほかに、be a good 〜er（〜する人）という名詞を使った表現もあります。\\n・She is a good cook.（彼女は料理が上手です＝彼女は上手な料理人です）\\n・He is a good singer.（彼は歌が上手です）\\n・They are good dancers.（彼らはダンスが上手です）\\nこの形では -er／-or の付いた「〜する人」を表す名詞（cook, singer, dancer, player, swimmer など）を使い、a good のあとに置きます。\\n\\n■ 比較して得意さを伝える\\n・I'm better at math than science.（私は理科より算数の方が得意です）better（good の比較級）＋ at ＋ than\\n・Who is the best at running in your class?（あなたのクラスでだれが走るのが一番得意ですか）best（good の最上級）\\n自己紹介文やアンケート形式の読解問題では、複数の人物の得意・不得意を比べる文章がよく出るので、good at・poor at・better at・best at をセットで整理しておくと読み取りがスムーズになります。\"}],\"trapExamples\":[{\"question\":\"「彼は絵をかくのが得意です。」を英語にしなさい。\",\"wrongAnswer\":\"He is good at draw.\",\"trapExplanation\":\"at のあとに動詞の原形をそのまま置いてしまう。不定詞（to＋原形）の感覚と混同し、前置詞のあとに原形の動詞を置けると誤解しやすい。\",\"correctAnswer\":\"He is good at drawing.\",\"correctExplanation\":\"at は前置詞であり、前置詞のあとに動詞を置くときは必ずing形（動名詞）にするというルールがある。draw → drawing とing形にすることで正しい文になる。「前置詞＋動詞はing」という原則は be interested in playing（〜することに興味がある）など他の前置詞表現にも共通するので、ここでしっかり定着させておくとよい。\"}]}",
"{\"id\":\"new20_e5_eigo_04\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"好きな理由を答える：I like ~ because ~.\",\"description\":\"好きなものを伝えるだけでなく、becauseを使って理由まで説明する文の作り方を学ぶ\",\"intro\":\"「私はサッカーが好きです」だけでなく、「なぜなら楽しいからです」まで言えると、英作文や面接でぐっと表現の幅が広がります。becauseを使って理由をつなげる文の作り方と、理由を答える会話の流れをここで身につけましょう。\",\"order\":6583,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「〜が好きです。なぜなら…だからです」は I like 〜. Because …. または I like 〜 because ….（1文につなげる）の2通りで書ける。\",\"because のあとには〈主語＋動詞〉を含む完全な文が続く：because it is fun. because I can meet my friends.\",\"because of 〜 は「〜という理由で」の意味だが、あとに名詞（句）だけを置く点が because とちがう：because of the rain（雨のせいで）。\",\"理由をたずねるときは Why do you like 〜? を使う。答えは Because 〜. だけで文を始めてもよい（会話では自然）。\",\"理由を並べるときは First, ... Second, ... Also, ... のようなつなぎ語を使うと文章が整理されて読みやすくなる。\"],\"sections\":[{\"heading\":\"becauseで理由をつなぐ文の作り方\",\"mangaId\":\"new20_e5_eigo_04_manga\",\"body\":\"好きな理由を説明するときの基本の形は「I like 〜.（私は〜が好きです）」のあとに「because ….（なぜなら…だからです）」を続ける形です。because は「なぜなら〜だから」という意味の接続詞で、あとには〈主語＋動詞〉のそろった文が続きます。\\n\\n■ 基本の型\\n・I like soccer because it is fun.（私はサッカーが好きです。なぜなら楽しいからです）\\n・I like dogs because they are cute.（私は犬が好きです。なぜならかわいいからです）\\n・I like summer because I can swim in the sea.（私は夏が好きです。なぜなら海で泳げるからです）\\n\\nbecause の前にコンマは付けません。I like soccer, because it is fun. とはせず、I like soccer because it is fun. とそのまま続けます。\\n\\n■ 文を2つに分けて書くこともできる\\n会話では、Because で文を始めて理由だけを答える形もよく使われます。\\n・Why do you like summer?（なぜ夏が好きなのですか）\\n・Because I can swim in the sea.（なぜなら海で泳げるからです）\\nこのように、質問の答えとして Because 〜. だけで答えるのは自然な会話表現です。作文で理由を1文にまとめるときは I like 〜 because …. の形、対話文で理由だけ答えるときは Because …. の形、と使い分けましょう。\\n\\n⚠ よくある間違い：because のあとに動詞だけを置いて主語を忘れてしまうミス（because fun. のように）。because のあとは必ず〈主語＋動詞〉のそろった文にすることを意識しましょう。\"},{\"heading\":\"because of との違いと、理由を並べる表現\",\"body\":\"because とよく似た形に because of があります。どちらも「〜のせいで・〜という理由で」という意味ですが、あとに続く形がちがいます。\\n\\n■ because と because of のちがい\\n・because のあとには〈主語＋動詞〉の文が続く：I stayed home because it rained.（雨が降ったので家にいました）\\n・because of のあとには名詞（句）だけが続く：I stayed home because of the rain.（雨のせいで家にいました）\\nof があるかないかで、あとに文が来るか名詞が来るかが変わると覚えておくと、書きかえ問題にも対応できます。\\n\\n■ 理由を複数並べるときのつなぎ語\\n自由英作文や自己紹介の文章で理由を2つ、3つと並べたいときは、順番を示すつなぎ語を使うと文章が整理されて読みやすくなります。\\n・First, I like soccer because it is exciting.（第一に、サッカーはわくわくするから好きです）\\n・Second, I can play it with my friends.（第二に、友達と一緒にプレーできます）\\n・Also, it is good exercise.（また、よい運動にもなります）\\nfirst（第一に）・second（第二に）・also（また）・too（〜も）といった語を文の初めや終わりに置くだけで、理由を並べた説明的な文章が作れます。\\n\\n会話文読解では、Why do you like 〜? という質問に対して、Because 〜. で答えたあとに、さらに details（具体的な説明）が続くことが多いので、because のあとの内容が「理由」を表しているという意識を持って読み進めると、内容一致問題にも強くなります。\",\"figureId\":\"xf_new20_e5_eigo_04\"}],\"trapExamples\":[{\"question\":\"「雨のせいで、私たちはサッカーができませんでした。」を英語にしなさい。（because または because of を使う）\",\"wrongAnswer\":\"We couldn't play soccer because the rain.\",\"trapExplanation\":\"because のあとに動詞を含む文ではなく、名詞（the rain）だけを置いてしまう。becauseとbecause ofの使い分けを意識せず、両方とも「名詞を置いてよい」と誤解している。\",\"correctAnswer\":\"We couldn't play soccer because of the rain.\",\"correctExplanation\":\"あとに名詞だけを置きたい場合は because of を使う。because を使いたい場合は because it rained.（雨が降ったので）のように主語＋動詞の文にする必要がある。of の有無で後ろの形が変わることをセットで覚えておくと、この種の書きかえ問題で失点しない。\"}]}",
"{\"id\":\"new20_e5_eigo_05\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一日の日課を語る：起きてから寝るまでの言い方\",\"description\":\"朝起きる・顔を洗う・学校へ行く・寝るなど、一日の生活の流れを表す動詞と時刻表現をまとめる\",\"intro\":\"「私は毎朝7時に起きます」というように、一日の生活の流れを順番に説明できるようになると、自己紹介や日記の作文で大きな武器になります。ここでは日課を表す動詞のかたまり（熟語）を、朝→昼→夜の順に整理して覚えていきます。\",\"order\":6584,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"日課はふつう現在形（習慣）で表す：I get up at seven.（私は7時に起きます）\",\"朝の動作：get up（起きる）→wash my face（顔を洗う）→brush my teeth（歯をみがく）→have breakfast（朝食を食べる）→leave home（家を出る）\",\"昼〜夕方：go to school（学校へ行く）→have lunch（昼食を食べる）→come home（家に帰る）→do my homework（宿題をする）\",\"夜：have dinner（夕食を食べる）→take a bath（お風呂に入る）→go to bed（寝る）\",\"動作の順番は and や then（それから）でつなぐと、流れのある文章になる：I get up and wash my face.\",\"時刻をつけ加えるときは at＋時刻：I have dinner at seven thirty.\"],\"sections\":[{\"heading\":\"朝の動作を表す熟語\",\"mangaId\":\"new20_e5_eigo_05_manga\",\"body\":\"一日の日課を説明する文章では、決まった動詞のかたまり（熟語）が次々に出てきます。まず朝の動作から順番に整理しましょう。日課はふだんくり返される習慣なので、現在形の文で表すのが基本です。\\n\\n■ 朝の流れ\\n・get up（起きる、ベッドから出る）— I get up at six thirty.（私は6時半に起きます）\\n・wash my face（顔を洗う）— I wash my face after I get up.\\n・brush my teeth（歯をみがく）— brush（ブラシでみがく）、teeth は tooth（歯）の複数形\\n・put on my uniform（制服を着る）— put on（身につける）\\n・have breakfast（朝食を食べる）— eat breakfast も同じ意味で使われる\\n・leave home（家を出る）— leave for school（学校に向けて出発する）という形もよく使う\\n\\nこれらは一つひとつ独立した文にすることもできますが、and でつないで一続きの文章にすると自然な日記文になります。\\n例）I get up at seven, wash my face, and have breakfast.（私は7時に起き、顔を洗い、朝食を食べます）\\nこのように動作をコンマとand で並べる書き方は、動作が3つ以上続くときによく使われます。\\n\\n⚠ よくある間違い：get up を wake up（目が覚める）と混同するミス。wake up は「目が覚める（意識がもどる）」こと、get up は「ベッドから出て起き上がる」ことを指します。I wake up at six, but I get up at six thirty.（6時に目は覚めるが、起き上がるのは6時半）のように、両方使い分ける文もよく出題されます。\"},{\"heading\":\"昼から夜までの動作と、順序を表すつなぎ語\",\"body\":\"続いて、学校に行ってから寝るまでの流れを見ていきましょう。\\n\\n■ 昼〜夕方の流れ\\n・go to school（学校へ行く）\\n・have lunch（昼食を食べる、school lunch＝給食）\\n・come home（家に帰る）— go home（家に帰る）とほぼ同じだが、come home は「（話し手のいる）家に帰ってくる」という視点\\n・do my homework（宿題をする）\\n・play with my friends（友達と遊ぶ）\\n\\n■ 夜の流れ\\n・have dinner（夕食を食べる）\\n・take a bath（お風呂に入る）— bath（バス、風呂）、take a shower（シャワーを浴びる）\\n・watch TV（テレビを見る）\\n・read a book（本を読む）\\n・go to bed（寝る、ベッドに入る）— sleep（眠る）とのちがいに注意。go to bed は「寝床に入る」動作、sleep は「実際に眠っている」状態。I go to bed at nine, but I can't fall asleep right away.（9時に寝床に入るが、すぐには眠れない）のように区別される。\\n\\n■ 順序を表すつなぎ語\\n一日の流れを文章として説明するときは、時間の順番を示す語を使うと分かりやすくなります。\\n・First, I get up at seven.（まず、7時に起きます）\\n・Then, I wash my face and have breakfast.（それから、顔を洗って朝食を食べます）\\n・After that, I go to school.（そのあと、学校へ行きます）\\n・Finally, I go to bed at nine.（最後に、9時に寝ます）\\nfirst（まず）・then（それから）・after that（そのあと）・finally（最後に）という4つの語をこの順番で覚えておくと、日課を説明する英作文でも、日課を説明した長文を読むときにも役立ちます。\",\"figureId\":\"xf_new20_e5_eigo_05\"}],\"trapExamples\":[{\"question\":\"「私は毎晩9時に寝ます。」を英語にしなさい。\",\"wrongAnswer\":\"I sleep at nine every night.\",\"trapExplanation\":\"「寝る」を sleep（眠る）と訳してしまう。sleep は「眠っている」という状態や「眠りに落ちる」ことを表す語で、「寝床に入る」という日課としての動作を表すには適さない場合が多い。\",\"correctAnswer\":\"I go to bed at nine every night.\",\"correctExplanation\":\"日課として「寝る（寝床に入る）」ことを言うときは go to bed を使うのが自然。sleep はI sleep for eight hours.（8時間眠ります）のように「眠っている時間の長さ」を表すときに向いている。go to bed とsleepは日本語ではどちらも「寝る」と訳されるため混同しやすいが、動作なのか状態なのかで使い分けることを意識する。\"}]}",
"{\"id\":\"new20_e5_eigo_06\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"週末・休日の過ごし方を伝える表現\",\"description\":\"What do you do on weekends? など、週末の予定や過ごし方をたずね合う会話表現をまとめる\",\"intro\":\"「週末は何をしますか」「たいてい家族と出かけます」というやり取りは、自己紹介文や会話文読解の定番です。ここでは週末をたずねる疑問文の形と、usually（たいてい）・sometimes（ときどき）などの頻度を表す語の使い方をあわせて整理します。\",\"order\":6585,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"週末の過ごし方をたずねる：What do you do on weekends? （ふだんの習慣なので do を使う一般動詞の疑問文）\",\"「週末に」は on weekends または on the weekend。on を使うのは曜日と同じ扱いだから。\",\"頻度を表す語：always（いつも）＞usually（たいてい）＞often（よく）＞sometimes（ときどき）＞never（決して〜ない）\",\"「予定がある」は have plans / be going to 〜（〜する予定だ）を使う：I'm going to visit my grandmother this weekend.\",\"過去の週末をたずねるときは How was your weekend?（週末はどうでしたか）と過去形で聞く。\"],\"sections\":[{\"heading\":\"週末の過ごし方をたずねる・答える\",\"mangaId\":\"new20_e5_eigo_06_manga\",\"body\":\"週末の過ごし方をたずねるときは What do you do on weekends?（あなたは週末に何をしますか）という言い方をします。日課をたずねるときと同じく、ふだんの習慣について聞いているので、現在形の一般動詞の疑問文（Do you 〜? / What do you 〜?）を使います。\\n\\n■ たずね方と答え方\\n・What do you do on weekends?（週末は何をしますか）\\n・I usually play soccer with my friends.（たいてい友達とサッカーをします）\\n・I often go shopping with my family.（よく家族と買い物に行きます）\\n・On weekends, I clean my room and do my homework.（週末は部屋をそうじして宿題をします）\\n\\n■ 「週末に」の言い方\\n「週末に」は on weekends（複数形、週末というものを一般的に指す）または on the weekend（今度の週末、または「週末には」という一般的な意味の両方で使われる）と言います。曜日と同じように on を使う点に注意しましょう。in weekends とは言いません（イギリス英語では at the weekend と言うこともあります）。\\n\\n■ 未来の週末の予定をたずねる\\n「今度の週末は何をする予定ですか」とたずねるときは What are you going to do this weekend? のように be going to（〜する予定だ）を使います。答えるときも同じ形にそろえます。\\n・I'm going to visit my grandmother this weekend.（今度の週末、祖母を訪ねる予定です）\\n・I have plans to go to the zoo.（動物園に行く予定があります）have plans（予定がある）\"},{\"heading\":\"頻度を表す語で過ごし方をくわしく伝える\",\"body\":\"週末の過ごし方を説明するときは、どれくらいの頻度でその行動をするかを表す語（頻度の副詞）をあわせて使うと、より自然でくわしい説明になります。\\n\\n■ 頻度の順番（多い→少ない）\\n・always（いつも、100%）\\n・usually（たいてい、80%くらい）\\n・often（よく、60%くらい）\\n・sometimes（ときどき、40%くらい）\\n・rarely / seldom（めったに〜ない、10%くらい）\\n・never（決して〜ない、0%）\\n\\nこれらの語は一般動詞の前、be動詞のあとに置くのが基本の位置です。\\n・I usually play video games on Saturdays.（土曜日はたいていゲームをします）— 一般動詞 play の前\\n・I'm always busy on Sundays.（日曜日はいつも忙しいです）— be動詞 am のあと\\n\\n■ 過去の週末をたずねる How was your weekend?\\nすでに終わった週末について話すときは、過去形の疑問文 How was your weekend?（週末はどうでしたか）を使います。\\n・How was your weekend?（週末はどうでしたか）\\n・It was great. I went to the beach with my family.（最高でした。家族と海に行きました）\\n・It was so-so. I just stayed home and read books.（まあまあでした。ただ家にいて本を読んでいました）\\n\\n会話文読解では、「ふだんの週末（現在形）」の話と「先週末（過去形）」の話が同じ文章の中で切りかわることがあるため、動詞の時制に注目しながら「これは習慣の話か、それとも過去の1回だけの出来事か」を見分ける練習をしておくと読み取りやすくなります。\",\"figureId\":\"xf_new20_e5_eigo_06\"}]}",
"{\"id\":\"new20_e5_eigo_07\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"天気予報を読み取る英文読解\",\"description\":\"It will be sunny tomorrow. のような天気予報の英文を読み取り、天気・気温・服装のアドバイスを結びつける\",\"intro\":\"テレビや新聞の天気予報を英語にすると、It will be sunny tomorrow.（明日は晴れるでしょう）のような未来を表す文がよく使われます。ここでは天気を表す語と、天気予報でよく使われる決まった言い回しをセットにして、読解問題に強くなる練習をします。\",\"order\":6586,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"天気予報は未来の予測なので will を使う：It will be rainy tomorrow.（明日は雨でしょう）\",\"天気を表す形容詞：sunny（晴れの）・cloudy（くもりの）・rainy（雨の）・snowy（雪の）・windy（風の強い）\",\"気温は degrees（度）を使う：It will be 25 degrees.（気温は25度でしょう）\",\"「暑い／寒い／あたたかい／涼しい」：hot・cold・warm・cool。It's cold today.（今日は寒いです）のように It を主語にする。\",\"天気予報の助言表現：You should bring an umbrella.（傘を持って行った方がいいですよ）\",\"天気によって行動が変わる文をつなげる読解がよく出る：If it rains, we will stay home.（もし雨が降ったら、家にいます）\"],\"sections\":[{\"heading\":\"天気を伝える文の基本形と天気を表す語\",\"mangaId\":\"new20_e5_eigo_07_manga\",\"body\":\"天気を表す文では、天候そのものを主語にするのではなく、It（それ）を主語にした特別な形を使います。この It は「それ」という意味を持たない、天候・時刻・明暗などを表すときだけに使う特別な it です。\\n\\n■ 天気を表す基本の文\\n・It is sunny today.（今日は晴れです）\\n・It is cloudy.（くもりです）\\n・It is rainy.（雨です）／It is raining now.（今、雨が降っています＝現在進行形）\\n・It is snowy.（雪です）／It is snowing.（雪が降っています）\\n・It is windy.（風が強いです）\\n\\n天気を表す形容詞（sunny, cloudy, rainy, snowy, windy）はどれも、天気を表す名詞（sun, cloud, rain, snow, wind）に -y を付けた形になっています。名詞と形容詞をセットで覚えると、つづりも覚えやすくなります。\\n\\n■ 気温・暑さ寒さを伝える表現\\n・It is hot today.（今日は暑いです）／It is cold.（寒いです）\\n・It is warm.（あたたかいです）／It is cool.（涼しいです）\\n・The temperature is 25 degrees.（気温は25度です）temperature（気温）、degree（度）\\n・It will be 30 degrees Celsius.（セ氏30度になるでしょう）Celsius（セ氏、℃）\"},{\"heading\":\"天気予報の未来表現と、助言・行動の読み取り\",\"body\":\"天気予報は「これから先どうなるか」という予測を伝えるものなので、未来を表す will（〜だろう）がひんぱんに使われます。\\n\\n■ willを使った天気予報の文\\n・It will be sunny tomorrow.（明日は晴れるでしょう）\\n・It will rain this afternoon.（今日の午後は雨が降るでしょう）\\n・It won't be cold tomorrow.（明日は寒くならないでしょう）won't＝will not\\n・Will it be sunny this weekend?（今週末は晴れますか）— Yes, it will. / No, it won't. で答える\\n\\n■ 天気予報でよく使われる助言表現\\n天気予報のあとには、聞いている人への助言が続くことがよくあります。\\n・You should bring an umbrella.（傘を持って行った方がいいですよ）should（〜すべきだ）\\n・Don't forget your umbrella.（傘を忘れないでね）命令文\\n・You'd better wear a warm coat.（あたたかいコートを着た方がいいですよ）had better（強めの助言）\\n\\n■ 「もし〜なら」で天気と行動を結びつける if\\n天気予報を読んで、その天気によって人がどんな行動をとるかを説明する文章では、if（もし〜なら）がよく使われます。\\n・If it rains tomorrow, we will stay home.（もし明日雨が降ったら、私たちは家にいます）\\n・If it is sunny, we will go on a picnic.（もし晴れたら、ピクニックに行きます）\\nif のあとの文は未来のことでも現在形で書く（if it rains であって if it will rain ではない）という点は、中学受験でもよくねらわれるポイントです。天気予報の読解問題では、①天気の種類、②気温、③そのあとの人物の行動、の3つを順番に結びつけて読み取る練習をしておきましょう。\",\"figureId\":\"xf_new20_e5_eigo_07\"}]}",
"{\"id\":\"new20_e5_eigo_08\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"手紙・メールの書き出しと結びの言い方\",\"description\":\"Dear 〜, から始まり Your friend, で終わる、英語の手紙・メールの基本の型を学ぶ\",\"intro\":\"海外の友達に手紙を書く場面や、手紙形式の読解問題は中学受験の英語でよく出題されます。日本語の手紙にも「拝啓」「敬具」のような決まった型があるように、英語の手紙にも Dear 〜, から始まり、最後に自分の名前で終わるという決まった形があります。この型を覚えておきましょう。\",\"order\":6587,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"手紙の書き出しは Dear＋名前, で始める（例：Dear Emily,）。Dear のあとにコンマを付ける。\",\"手紙の最初の文でよく使う決まり文句：Thank you for your letter.（お手紙をありがとう）／How are you?（お元気ですか）\",\"結びの言葉（クロージング）：Your friend, / Best wishes, / See you soon, のあとに自分の名前を書く。\",\"メール（email）も手紙とほぼ同じ型を使うが、より簡単に Hi 〜, で始めることも多い。\",\"手紙の日付や場所は、書き出しの前の右上に書くのが一般的（本文の型としては後回しでよい）。\",\"返事を書くときは I'm writing back to your letter.（あなたの手紙への返事を書いています）のような表現も使われる。\"],\"sections\":[{\"heading\":\"手紙の基本の型：書き出しから本文へ\",\"mangaId\":\"new20_e5_eigo_08_manga\",\"body\":\"英語の手紙には、日本語の「拝啓」「敬具」のような決まった型があります。中学受験の読解問題では、この型を知っているだけで文章の構成がすばやくつかめるようになります。\\n\\n■ 書き出し（あいさつ）\\n手紙は Dear＋相手の名前, というあいさつから始まります。Dear は「親愛なる」という意味ですが、実際には堅い意味を持たず、手紙のあいさつとして機械的に使われます。\\n・Dear Emily,（エミリーへ）\\n・Dear Grandma,（おばあちゃんへ）\\nDear のあとには必ずコンマ（,）を付けます。ピリオドではない点に注意しましょう。\\n\\n■ 本文の始め方\\n書き出しのあいさつのあと、本文の最初の文には決まった言い回しがよく使われます。\\n・Thank you for your letter.（お手紙をありがとう）— 返事を書くときの定番\\n・How are you?（お元気ですか）— 相手の様子をたずねる\\n・I hope you are doing well.（あなたが元気にしていることを願っています）少し丁寧な言い方\\n・I'm writing to tell you about my school trip.（学校の旅行についてお伝えするために書いています）用件を切り出す言い方\\n\\n本文では、伝えたいことを段落に分けて書きます。自己紹介・近況報告・お願いごと・お礼など、目的によって内容が変わりますが、「あいさつ→用件→むすび」という流れは共通しています。\",\"figureId\":\"xf_new20_e5_eigo_08\"},{\"heading\":\"手紙の結び（クロージング）とメールとのちがい\",\"body\":\"手紙の最後には、本文を締めくくる決まり文句（クロージング）と、自分の名前を書きます。\\n\\n■ 結びの言葉の例\\n・Your friend,（あなたの友達より）— 友達へのカジュアルな手紙でよく使う\\n・Best wishes,（幸運を祈って）／Best regards,（よろしくお願いします）— 少し丁寧\\n・See you soon,（また近いうちに会いましょう）\\n・Love,（愛をこめて）— 家族や親しい人への手紙\\nこれらの言葉のあとにもコンマを付け、次の行に自分の名前を書きます。\\n例）\\n　Your friend,\\n　Kenta\\n\\n■ メール（email）との共通点とちがい\\nメールも基本の流れは手紙と同じですが、よりくだけた言い方で始まることが多いです。\\n・Hi Emily,（やあ、エミリー）— Dear より気軽なあいさつ\\n・Hello everyone,（みなさん、こんにちは）— 複数の人にあてたメール\\n本文の途中で写真や添付ファイルについて触れる表現（I attached a photo.＝写真を添付しました）もメールでは使われますが、あいさつと結びの基本の型は手紙と共通しています。\\n\\n■ 読解問題での手紙・メールの解き方のコツ\\n手紙形式の読解問題では、①だれからだれへの手紙か（Dear のあとの名前と、結びのあとの名前）、②いつ書かれたか（日付があれば確認する）、③本文の用件は何か、の3点を最初に確認すると、設問に答えやすくなります。特に「だれが書いたか」を取りちがえるミスが多いので、必ず結びの名前も確認する習慣をつけましょう。\"}]}",
"{\"id\":\"new20_e5_eigo_09\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"感情を表す形容詞：happy・sad・angry・excited・tired\",\"description\":\"気持ちを伝える形容詞をまとめ、-ed形と-ing形のちがい（tired と tiring 等）にも触れる\",\"intro\":\"「うれしい」「悲しい」「疲れた」など、気持ちを伝える言葉は日記や作文でとてもよく使われます。ここでは感情を表す形容詞をまとめて覚えるとともに、interested（興味を持っている）と interesting（興味深い）のように似た形でも意味が正反対になる語のちがいにも注目します。\",\"order\":6588,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"基本の感情形容詞：happy（うれしい）・sad（悲しい）・angry（怒っている）・surprised（驚いた）・excited（わくわくしている）・tired（疲れた）・scared / afraid（こわい）・nervous（緊張している）\",\"気持ちの原因を伝えるときは because や with を使う：I'm happy because I got a good grade.\",\"-ed形（人の気持ち）と-ing形（人に感情を起こさせるもの）のちがい：I am interested in soccer.（私はサッカーに興味がある）／The movie was interesting.（その映画はおもしろかった）\",\"同じペアの語：excited／exciting、bored／boring、surprised／surprising、tired／tiring\",\"「〜そうに見える」は look＋形容詞：You look happy today.（今日はうれしそうだね）\"],\"sections\":[{\"heading\":\"基本の感情形容詞とその使い方\",\"body\":\"気持ちを伝える形容詞は be動詞（am, is, are）のあとに置くのが基本の形です。まずはよく使う語を整理しましょう。\\n\\n■ 基本の感情形容詞\\n・happy（うれしい、幸せな）— I'm happy.（うれしいです）\\n・sad（悲しい）— I'm sad.（悲しいです）\\n・angry（怒っている）— He is angry.（彼は怒っています）\\n・surprised（驚いた）— We were surprised.（私たちは驚きました）\\n・excited（わくわくしている）— I'm excited about the trip.（旅行のことでわくわくしています）\\n・tired（疲れた）— I'm tired.（疲れました）\\n・scared / afraid（こわがっている）— She is scared of dogs.（彼女は犬をこわがっています）\\n・nervous（緊張している）— I'm nervous before the test.（テストの前は緊張します）\\n\\n■ 気持ちの原因をつけ加える\\n気持ちを伝える文には、なぜそう感じるのかという原因をつけ加えることがよくあります。\\n・I'm happy because I passed the test.（テストに合格したのでうれしいです）because＋文\\n・I'm excited about the school trip.（修学旅行のことでわくわくしています）about＋名詞\\n・She is angry with her brother.（彼女は弟に怒っています）with＋人\\n・I'm afraid of the dark.（私は暗いのがこわいです）of＋名詞\\n\\nこのように、感情の形容詞のあとに続く前置詞（about, with, of など）は形容詞によって決まっているものが多いため、セットで覚えるのが効率的です。\"},{\"heading\":\"-ed形と-ing形のちがい：interested と interesting\",\"mangaId\":\"new20_e5_eigo_09_manga\",\"body\":\"感情を表す語の中には、interested／interesting のように -ed で終わる形と -ing で終わる形の両方がある一群があります。この2つは似ているようで、使う相手がまったく違います。\\n\\n■ -ed形＝「（人が）〜と感じる」\\n-ed の形は、人がその感情を「持っている」ことを表します。主語は人（または動物）になります。\\n・I'm interested in soccer.（私はサッカーに興味を持っています）\\n・I was excited about the game.（私はその試合にわくわくしていました）\\n・I was bored during the class.（私は授業の間、退屈していました）\\n・I was tired after the trip.（私は旅行のあと疲れていました）\\n\\n■ -ing形＝「（ものごとが）〜という感情を人に起こさせる」\\n-ing の形は、そのものごと自体がどんな性質を持っているかを表します。主語はもの・こと・出来事になります。\\n・Soccer is interesting.（サッカーはおもしろい＝人を興味を持たせる性質がある）\\n・The game was exciting.（その試合はわくわくするものだった）\\n・The class was boring.（その授業は退屈だった）\\n・The trip was tiring.（その旅行は疲れるものだった）\\n\\n■ 主語で見分けるコツ\\n主語が人であれば-ed形、主語がもの・こと（映画・授業・試合など）であれば-ing形、と覚えると迷いにくくなります。\\n⚠ よくある間違い：I'm boring. と言うと「私は（人を）退屈させるつまらない人間だ」という意味になってしまい、「私は退屈している」という意図とは正反対の失礼な文になってしまいます。「私は退屈している」は I'm bored. が正解です。この I'm boring. と I'm bored. のミスは非常によく出るひっかけなので、必ず主語をチェックする習慣をつけましょう。\",\"figureId\":\"xf_new20_e5_eigo_09\"}],\"trapExamples\":[{\"question\":\"「私はその話に興味があります。」を英語にしなさい。\",\"wrongAnswer\":\"I'm interesting in the story.\",\"trapExplanation\":\"「興味がある」を、-ing形の interesting で表してしまう。interesting は「（ものが）興味深い」という意味であり、「私」という人がその性質を持っているという誤った文になってしまう。\",\"correctAnswer\":\"I'm interested in the story.\",\"correctExplanation\":\"「（人が）興味を持っている」は-ed形の interested を使う。主語が人（I）のときは-ed形、主語がもの・こと（the story）のときは-ing形と覚えておけば、The story is interesting.（その話はおもしろい）と I'm interested in the story.（私はその話に興味がある）を正しく使い分けられる。\"}]}",
"{\"id\":\"new20_e5_eigo_10\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"さそいを受ける・断る表現：Let's ~. への返事\",\"description\":\"Let's ~. や Why don't we ~? などのさそいの文への、受ける・断るときの自然な返事のしかたを学ぶ\",\"intro\":\"友達にさそわれたとき、どう返事をすればよいか困ったことはありませんか。ここでは Let's ~.（〜しましょう）というさそいの文に対して、受けるときの言い方と、丁寧に断るときの言い方をセットで学びます。断り方には理由をそえるのがマナーです。\",\"order\":6589,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"さそいの文：Let's ~.（〜しましょう）／Why don't we ~?（〜しませんか）／Shall we ~?（〜しましょうか）\",\"受けるときの返事：Yes, let's. / Sure. / That sounds good. / OK, let's do that.\",\"断るときの返事：Sorry, I can't. / I'd love to, but I can't. のように、まず気持ちを伝えてから理由を続ける。\",\"断る理由の言い方：I have to study. / I'm busy today. / I already have plans.\",\"個人に対するさそいには Do you want to ~? / Would you like to ~? も使われる（Would you like to のほうが丁寧）。\"],\"sections\":[{\"heading\":\"さそいの文の種類と、受けるときの返事\",\"mangaId\":\"new20_e5_eigo_10_manga\",\"body\":\"友達を何かにさそうときには、いくつかの決まった言い方があります。まずはさそいの文の形を確認しましょう。\\n\\n■ さそいの文\\n・Let's play soccer.（サッカーをしましょう）Let's＝Let us、動詞は原形\\n・Why don't we go to the park?（公園に行きませんか）直訳は「なぜ私たちは〜しないのか」だが、実際はさそいの意味\\n・Shall we go shopping?（買い物に行きましょうか）\\n・Do you want to watch a movie?（映画を見たいですか＝見に行きませんか）1対1の親しいさそい\\n・Would you like to join us?（私たちに加わりませんか）Would you like to は丁寧なさそい\\n\\n■ さそいを受けるときの返事\\nさそわれてOKするときは、次のような表現を使います。\\n・Yes, let's.（はい、そうしましょう）Let's ~.に対する決まった受け方\\n・Sure. / OK. / Sounds good.（いいですよ／いいですね）\\n・That sounds like fun.（楽しそうですね）\\n・I'd love to!（ぜひそうしたいです！）would love to（とても〜したい）\\n\\nYes, let's. は Let's ~. や Shall we ~? に対する決まった答え方で、Why don't we ~? にも使えます。ただし、Sure. や Sounds good. のほうがより自然に幅広く使えます。\"},{\"heading\":\"丁寧に断るときの言い方\",\"body\":\"さそいを断るときは、いきなり No. とだけ言うと相手にそっけない印象を与えてしまいます。英語では「残念な気持ちを伝える」→「断る」→「理由を言う」という順番で答えるのが自然でていねいなマナーとされています。\\n\\n■ 断るときの基本の型\\n・Sorry, I can't.（ごめんなさい、できません）\\n・I'd love to, but I can't.（ぜひそうしたいのですが、できません）I'd love to はさそいを受けたい気持ちを表す前置き\\n・I'm sorry, but I have other plans.（すみませんが、他に予定があります）\\n\\n■ 断る理由をつけ加える\\n断るときには理由を続けるとより丁寧で自然な会話になります。\\n・I have to study for a test.（テストのために勉強しなければなりません）have to（〜しなければならない）\\n・I'm busy today.（今日は忙しいです）\\n・I already have plans.（すでに予定があります）already（すでに）\\n・Maybe next time.（また今度にしましょう）今回は断るが今後は受けたいという気持ちを伝える表現\\n\\n■ 会話のやり取りの例\\nA: Let's play basketball after school.（放課後バスケをしましょう）\\nB: I'd love to, but I can't. I have to help my mom today.（ぜひしたいけど、できないの。今日は母を手伝わないといけなくて）\\nA: OK, maybe next time.（わかった、また今度ね）\\n\\nこのように、さそい→受ける／断る→（断る場合は）理由→相手の反応、という一連の流れは会話文読解でも頻出です。会話の中でだれが何をさそわれ、結局どうすることになったのかを正確に読み取る練習をしておきましょう。\",\"figureId\":\"xf_new20_e5_eigo_10\"}]}",
"{\"id\":\"new20_e5_eigo_11\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"誕生日パーティーの招待状を読む\",\"description\":\"You are invited to ~ のような招待状の決まった書き方と、日時・場所を読み取る練習をする\",\"intro\":\"英語の招待状（invitation）には、いつ・どこで・何のパーティーがあるかを伝えるための決まった書き方があります。ここでは招待状によく使われる表現を整理し、日時・場所・持ち物などの情報を正確に読み取る練習をします。\",\"order\":6590,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"招待の決まり文句：You are invited to my birthday party!（私の誕生日パーティーにご招待します！）\",\"日時の表し方：Date（日付）・Time（時刻）・Place（場所）の3項目が並ぶことが多い。\",\"「参加する」は come または join us：Please come to my party. / Please join us.\",\"出欠の返事を求める表現：Please let me know if you can come.（来られるかどうか教えてください）／RSVP（返事をお願いします、フランス語由来の略語）\",\"持ち物・服装の指示：Please bring a gift.（プレゼントを持ってきてください）／Wear something blue.（青いものを身につけてください）\"],\"sections\":[{\"heading\":\"招待状の基本の型\",\"body\":\"招待状（invitation）は、パーティーやイベントに人をさそうために送る短い文書です。決まった型があるので、その型を知っておくと初めて見る招待状でもすばやく情報を読み取れます。\\n\\n■ 招待の書き出し\\n・You are invited to my birthday party!（私の誕生日パーティーにご招待します！）be invited to（〜に招待される）の受け身の形\\n・Please come to my birthday party.（私の誕生日パーティーに来てください）\\n・Join us for a party!（パーティーに参加してください！）\\n\\n■ 日時・場所を伝える3つの項目\\n招待状の本文には、たいてい次の3つの情報がまとめて書かれています。\\n・Date:（日付）— 例）Date: Saturday, May 10（5月10日土曜日）\\n・Time:（時刻）— 例）Time: 2:00 p.m. to 4:00 p.m.（午後2時から午後4時まで）\\n・Place:（場所）— 例）Place: my house（私の家）／Place: ABC Park（ABC公園）\\nこの3項目は箇条書きで並んでいることが多く、読解問題ではここを正確に拾えるかがそのまま得点につながります。落ち着いて一行ずつ確認しましょう。\",\"figureId\":\"xf_new20_e5_eigo_11\"},{\"heading\":\"出欠の返事と持ち物・服装の指示\",\"body\":\"招待状には、日時や場所だけでなく、参加できるかどうかの返事を求める文や、持ち物・服装についての指示が加えられることもあります。\\n\\n■ 出欠の返事を求める表現\\n・Please let me know if you can come.（来られるかどうか教えてください）if（〜かどうか）\\n・Can you come?（来られますか）\\n・RSVP by May 5.（5月5日までにご返事ください）RSVPはフランス語 répondez s'il vous plaît（お返事をください）の略で、招待状の返事を求めるときの決まった記号として使われる\\n\\n■ 持ち物・服装の指示\\n・Please bring a gift.（プレゼントを持ってきてください）bring（持ってくる）\\n・You don't have to bring anything.（何も持ってこなくていいですよ）\\n・Wear something blue.（青いものを身につけてきてください）wear（身につける）\\n・It's a costume party!（仮装パーティーです！）\\n\\n■ 招待状読解のコツ\\n招待状の読解問題では、次の順番で情報を整理すると解きやすくなります。\\n①だれが、だれを招待しているか（招待状の送り主と、宛先）\\n②何のイベントか（誕生日パーティー、卒業パーティーなど）\\n③いつ・どこで開かれるか（Date・Time・Place）\\n④参加するために必要な準備は何か（返事の期限、持ち物、服装）\\nこの4点をメモしながら読む練習をしておくと、細かい日時のひっかけ問題（時刻を書きかえて間違えさせる問題など）にも対応できるようになります。\",\"mangaId\":\"new20_e5_eigo_11_xm\"}]}",
"{\"id\":\"new20_e5_eigo_12\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"好き嫌い・食べられないものを伝える表現\",\"description\":\"I don't like ~. や I can't eat ~. など、食べ物の好き嫌いやアレルギーを伝える表現をまとめる\",\"intro\":\"外国の人と食事をするときや、給食・レストランの会話文で「〜が苦手です」「〜が食べられません」と伝える表現はとても実用的です。単なる好き嫌いと、体質的に食べられないアレルギーとでは伝え方が少しちがう点にも注目しましょう。\",\"order\":6591,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「〜が好きではない」は I don't like ~.、「〜が大きらい」は I hate ~. や I really don't like ~.\",\"「〜が食べられない（アレルギー）」は I'm allergic to ~. や I can't eat ~ because I'm allergic to it.\",\"好き嫌いの程度を表す語：love（大好き）＞like（好き）＞don't like much（あまり好きではない）＞don't like（好きではない）＞hate（大きらい）\",\"味を表す形容詞：sweet（甘い）・sour（すっぱい）・bitter（苦い）・spicy（辛い）・salty（塩からい）\",\"「〜を試してみる」は try：I've never tried natto.（私は納豆を食べたことがありません）\"],\"sections\":[{\"heading\":\"好き嫌いを伝える表現と味を表す語\",\"body\":\"食べ物の好き嫌いを伝えるときは、まず like（好き）・don't like（好きではない）を基本にして、程度を表す語を加えていきます。\\n\\n■ 好き嫌いの程度\\n・I love natto.（納豆が大好きです）loveはlikeより強い「大好き」\\n・I like carrots.（にんじんが好きです）\\n・I don't like carrots very much.（にんじんはあまり好きではありません）very muchを付けると「あまり」という控えめな否定になる\\n・I don't like green peppers.（ピーマンが好きではありません）\\n・I hate mushrooms.（きのこが大きらいです）hateは強い「きらい」なので使う場面に注意\\n\\n■ 味を表す形容詞\\nなぜ好き・きらいなのか理由を伝えるときは、味を表す形容詞がよく使われます。\\n・sweet（甘い）・sour（すっぱい）・bitter（苦い）・spicy（辛い）・salty（塩からい）\\n例）I don't like green peppers because they are bitter.（ピーマンは苦いのできらいです）\\n・It tastes good.（おいしいです）taste（〜の味がする）＋good/badの形もよく使われる：It tastes bad.（まずいです）\\n\\n■ 「〜を食べたことがある・ない」try\\n初めて食べるものについては、try（試す）を使った現在完了の文がよく使われます。\\n・I've never tried natto.（私は納豆を食べたことがありません）have never tried（一度も試したことがない）\\n・Have you ever tried sushi?（お寿司を食べたことがありますか）\",\"figureId\":\"xf_new20_e5_eigo_12\"},{\"heading\":\"アレルギーを伝える表現と、レストランでの会話\",\"body\":\"単なる好き嫌いとちがい、体質的に食べられないアレルギーがある場合は、はっきりとそれを伝える表現を使う必要があります。\\n\\n■ アレルギーを伝える表現\\n・I'm allergic to eggs.（私は卵アレルギーです）be allergic to（〜にアレルギーがある）\\n・I can't eat peanuts because I'm allergic to them.（ピーナッツはアレルギーがあるので食べられません）\\n・Does this have any nuts in it?（これにナッツは入っていますか）レストランで確認するときの表現\\nallergic（アラージック）はallergy（アレルギー）の形容詞形で、アレルギーの対象（食べ物）はtoのあとに置きます。\\n\\n■ 好き嫌いとアレルギーのちがいを意識する\\ndon't likeは「好みとして食べたくない」という意味であるのに対し、allergic toやcan't eat because of an allergyは「食べると体に害がある」という意味であり、レストランや給食の場面ではこの区別が重要な情報になります。会話文読解で登場人物が食べ物を断っている場面では、その理由が「好みの問題」なのか「アレルギー」なのかを注意深く読み分けましょう。\\n\\n■ レストランでの確認のやり取りの例\\nA: Is there anything you can't eat?（何か食べられないものはありますか）\\nB: Yes, I'm allergic to shrimp. Does this dish have shrimp in it?（はい、エビアレルギーです。この料理にエビは入っていますか）\\nA: No, it doesn't. It's safe for you.（いいえ、入っていません。大丈夫ですよ）\\nこのようなやり取りは海外での食事や、給食のアレルギー対応を説明する読解文でもよく登場する重要な場面です。\",\"mangaId\":\"new20_e5_eigo_12_xm\"}]}",
"{\"id\":\"new20_e5_eigo_13\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"家族それぞれの一日を紹介する英文を読む\",\"description\":\"複数の家族の日課を比較しながら説明する文章を読み、主語ごとに動作を正確に対応させる読解練習\",\"intro\":\"お父さんは7時に起き、お母さんは6時半に起きる、というように、一つの文章の中で家族それぞれの日課がまとめて紹介されることがあります。ここでは、複数の人物の似た内容が並ぶ文章を読むときに、だれの話がどこまで続くのかを正確につかむ読解の技術を練習します。\",\"order\":6592,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"複数人の日課を比べる文章では、主語（My father / My mother / I など）が変わるたびに新しい人物の話に切りかわる。\",\"「一方で」を表す語 while（〜する一方で）や on the other hand（他方では）に注目すると、対比の構造がつかみやすい。\",\"三人称単数（he, she）の文では動詞に-sが付くことを、家族紹介文では特に頻繁に確認する必要がある。\",\"時刻や動作を表で整理する（だれが・何時に・何をするか）と、内容一致問題を解きやすくなる。\",\"「〜もまた」を表す too / also が出てきたら、直前の人物と同じ動作を別の人物もすることを表している。\"],\"sections\":[{\"heading\":\"主語の切りかわりに注目して読む\",\"body\":\"家族それぞれの一日を紹介する文章では、段落や文が変わるごとに主語（だれの話か）が変わることがよくあります。この主語の切りかわりを見落とすと、だれの行動なのかを取りちがえてしまい、内容一致問題で失点しやすくなります。\\n\\n■ 例文で確認する\\nMy father gets up at six. He goes jogging every morning. My mother gets up at six thirty. She makes breakfast for the family. I get up at seven and have breakfast with my family.\\n（父は6時に起きます。彼は毎朝ジョギングに行きます。母は6時半に起きます。彼女は家族のために朝食を作ります。私は7時に起きて家族と朝食を食べます。）\\n\\nこの文章では、My father→He、My mother→Sheのように、一度名前が出たあとは代名詞（he, she）に置きかわって話が続いています。代名詞が「だれを指しているか」を正確にたどることが、この種の文章を読むコツです。\\n\\n■ 三人称単数の-sを見落とさない\\n家族の話では he・she を主語にした文が連続するため、動詞に-sが付く三人称単数現在の形が集中して出てきます。gets up（起きる）、goes（行く）、makes（作る）のように、-sの有無や、go→goes、make→makesのようなつづりの変化にも注意しながら読み進めましょう。動詞の形を正確に読み取れないと、いつ・だれの動作かを誤解する原因になります。\",\"figureId\":\"xf_new20_e5_eigo_13\",\"mangaId\":\"new20_e5_eigo_13_xm\"},{\"heading\":\"対比を表す語と、内容整理のコツ\",\"body\":\"複数の人物の日課を比べる文章では、対比を表す言葉に注目すると文章全体の構造がつかみやすくなります。\\n\\n■ 対比を表す語\\n・while（〜する一方で）— My father cooks dinner while my mother does the laundry.（母が洗たくをする一方で、父は夕食を作ります）\\n・on the other hand（他方では）— My brother likes soccer. On the other hand, I like swimming.（兄はサッカーが好きです。他方、私は水泳が好きです）\\n・but（しかし）— My sister gets up early, but I get up late.（姉は早起きですが、私は遅く起きます）\\n\\n■ 「〜もまた」too / alsoで共通点をつかむ\\n・My father likes fishing. My brother likes it, too.（父は釣りが好きです。兄も好きです）too は文末に置かれることが多い\\n・My mother is a teacher. My aunt is a teacher, too.（母は先生です。おばも先生です）\\ntooやalsoが出てきたときは、直前に述べられた人物と同じ動作・状態が別の人物にもあてはまることを示しているので、「だれとだれが同じなのか」を確認しましょう。\\n\\n■ 表にまとめて整理する読み方\\nこのような文章を読むときは、頭の中で簡単な表を作るつもりで、「だれが・何時に・何をするか」を順番に整理しながら読むと、細かい内容一致問題にも対応しやすくなります。\\n例）父：6時に起きる／ジョギング　母：6時半に起きる／朝食を作る　私：7時に起きる／家族と朝食\\nこのように整理してから設問を見ると、「お母さんが6時に起きるのは正しいか」といったひっかけ選択肢（実際は6時半）にもすぐに気づけるようになります。\"}]}",
"{\"id\":\"new20_e5_eigo_14\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"学校行事のお知らせを読む：運動会・遠足の案内文\",\"description\":\"Sports Day や Field Trip のお知らせプリントに出てくる決まった表現と、日時・持ち物の読み取り方をまとめる\",\"intro\":\"学校のお知らせプリントを英語にした読解問題では、運動会（Sports Day）や遠足（Field Trip）のお知らせがよく題材になります。ここでは行事の案内文に出てくる決まった表現を整理し、必要な情報（日時・集合場所・持ち物・注意事項）を素早く見つける練習をします。\",\"order\":6593,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"行事名：Sports Day（運動会）・Field Trip（遠足）・School Festival（学園祭・文化祭）・Graduation Ceremony（卒業式）\",\"案内文の基本項目：When（いつ）・Where（どこで）・What to bring（何を持ってくるか）・What to wear（何を着るか）\",\"「〜が中止になる」cancel：The event will be canceled if it rains.（雨の場合、行事は中止になります）\",\"「〜に集合する」meet：Please meet at the school gate at 8:30.（8時30分に校門に集合してください）\",\"注意事項の表現：Please don't forget to ~.（〜するのを忘れないでください）／Make sure to ~.（必ず〜してください）\"],\"sections\":[{\"heading\":\"行事の案内文の基本構成\",\"body\":\"学校行事のお知らせは、招待状と同じように決まった型で書かれることが多く、必要な情報が箇条書きで整理されています。まずは行事名と、案内文によく出てくる基本項目を確認しましょう。\\n\\n■ よく出る学校行事の名前\\n・Sports Day（運動会）\\n・Field Trip（遠足、校外学習）\\n・School Festival（学園祭、文化祭）\\n・Music Festival（音楽会）\\n・Graduation Ceremony（卒業式）\\n\\n■ 案内文の基本項目\\n・When:（いつ）— 例）When: Friday, October 10（10月10日金曜日）\\n・Where:（どこで）— 例）Where: the school playground（学校の校庭）\\n・What to bring:（何を持ってくるか）— 例）What to bring: a lunch box, a water bottle, a towel（お弁当、水筒、タオル）\\n・What to wear:（何を着るか）— 例）What to wear: your gym clothes（体操服）\\n\\nこのように、When・Where・What to bring・What to wearという見出し（heading）ごとに情報が整理されているため、見出しを頼りに必要な箇所だけをすばやく探す「スキャニング」の読み方が特に有効です。\",\"figureId\":\"xf_new20_e5_eigo_14\"},{\"heading\":\"集合・持ち物・注意事項の表現\",\"body\":\"行事の案内文には、当日の集合方法や、持ち物・服装についての注意、そして天候によって行事がどうなるかという情報が続くことが多くあります。\\n\\n■ 集合を伝える表現\\n・Please meet at the school gate at 8:30.（8時30分に校門に集合してください）meet（集合する）\\n・We will leave school at 9:00.（学校を9時に出発します）\\n\\n■ 持ち物・注意事項の表現\\n・Please bring your lunch and a water bottle.（お弁当と水筒を持ってきてください）\\n・Don't forget to bring a hat.（帽子を持ってくるのを忘れないでください）don't forget to ~（〜するのを忘れない）\\n・Make sure to wear comfortable shoes.（歩きやすい靴をはくようにしてください）make sure to ~（必ず〜する）\\n・Students should not bring money.（生徒はお金を持ってきてはいけません）should not（〜すべきでない）\\n\\n■ 天候による変更を伝える表現\\n運動会や遠足は天気に左右されるため、案内文には天候による中止・延期の情報がよく含まれます。\\n・The event will be canceled if it rains.（雨の場合、行事は中止になります）\\n・If it rains, Sports Day will be held on the next day.（雨の場合、運動会は翌日に開催されます）be held（開催される）\\n・In case of rain, please check the school website.（雨天の場合は、学校のウェブサイトを確認してください）\\n\\n■ 読解のコツ\\nこのような案内文の読解問題では、「いつ」「どこで」「何を持っていくか」「天気が悪い場合どうなるか」の4点をチェックリストのように確認しながら読むと、細かい設問にも落ち着いて対応できます。特に「雨天時の対応」は見落とされがちなので、案内文の後半まで丁寧に目を通しましょう。\",\"mangaId\":\"new20_e5_eigo_14_xm\"}]}",
"{\"id\":\"new20_e5_eigo_15\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"禁止・注意を表す掲示・看板の英語\",\"description\":\"No smoking. や Please do not touch. など、街や施設でよく見る掲示・看板の英語表現をまとめる\",\"intro\":\"街や公園、博物館などでよく見かける英語の看板には、「〜しないでください」「〜禁止」を伝える決まった書き方があります。ここでは短い掲示によく使われる表現を整理し、意味を素早く正確に読み取る練習をします。\",\"order\":6594,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"禁止を表す最も簡単な形：No＋動詞のing形（No smoking.＝禁煙、No parking.＝駐車禁止、No photos.＝撮影禁止）\",\"「〜しないでください」の命令文：Please do not ~. / Don't ~.（Please do not touch.＝おさわりにならないでください）\",\"「〜してはいけません」は You must not ~. または You are not allowed to ~.（〜することは許可されていません）\",\"案内・許可の掲示：Please use the door on your left.（左のドアをお使いください）、Open（開いています）／Closed（閉まっています）\",\"「立入禁止」Keep out. / No entry.、「非常口」Emergency Exit、「故障中」Out of order\"],\"sections\":[{\"heading\":\"禁止を表す看板の表現\",\"body\":\"街中や施設でよく見る「禁止」を表す看板には、短くて覚えやすい決まった型があります。\\n\\n■ No＋動詞のing形（〜禁止）\\n看板でもっともよく使われる形が No＋動詞のing形です。動詞の原形にingを付けた形（動名詞）を使う点に注意しましょう。\\n・No smoking.（禁煙、たばこを吸うことは禁止）\\n・No parking.（駐車禁止）\\n・No swimming.（遊泳禁止）\\n・No photos. / No photography.（撮影禁止）※photosは名詞なのでingではない点に注意\\n・No littering.（ゴミの投げ捨て禁止）litter（ゴミを散らかす）\\n\\n■ Please do not ~. / Don't ~.（〜しないでください）\\n標識やお知らせの中でも、少し丁寧に伝えたいときはPlease do not ~.の形がよく使われます。\\n・Please do not touch.（おさわりにならないでください）博物館や美術館の展示品によくある表示\\n・Please do not feed the animals.（動物にえさをあげないでください）動物園でよく見る表示\\n・Don't run in the hallway.（廊下を走らないでください）学校内の掲示\\n\\n■ You must not ~. / You are not allowed to ~.（〜してはいけません）\\nより公式で強い禁止を伝えるときはmust not（〜してはならない）や、be allowed to（〜することを許されている）の否定形が使われます。\\n・You must not enter this room.（この部屋に入ってはいけません）\\n・Visitors are not allowed to bring food.（来場者は食べ物を持ちこむことを許可されていません）\",\"figureId\":\"xf_new20_e5_eigo_15\",\"mangaId\":\"new20_e5_eigo_15_xm\"},{\"heading\":\"案内・許可の掲示と、覚えておきたい定型表現\",\"body\":\"禁止だけでなく、案内や許可、施設の状態を伝える短い掲示表現もあわせて覚えておくと、街の英語表示を読み取る問題全般に強くなります。\\n\\n■ 案内を表す表現\\n・Please use the door on your left.（左のドアをお使いください）\\n・Please wait here.（ここでお待ちください）\\n・Push（押す）／Pull（引く）— ドアによく貼られている表示\\n・Please take off your shoes.（くつを脱いでください）\\n\\n■ 施設の状態を表す表現\\n・Open（営業中、開いています）／Closed（閉まっています、休業中）\\n・Out of order（故障中）\\n・Sold out（売り切れ）\\n\\n■ 特に重要な決まった掲示語\\n・Keep out. / No entry.（立入禁止）\\n・Emergency Exit（非常口）\\n・Caution! / Watch your step!（注意！足元に気をつけて！）\\n・Wet floor.（ゆか、ぬれています）\\n・Fragile.（われもの注意）荷物のラベルなどによく使われる\\n\\nこれらの掲示語は、ふつうの文とちがい、主語や動詞が省略された「決まり文句」として使われることが多いのが特徴です。文法的に文を分析しようとするより、看板の絵や場所と組み合わせて「意味のかたまり」としてそのまま覚えてしまうのが効率的です。読解問題では、看板の絵やイラストとセットで出題されることも多いので、日常でこのような英語表示を見かけたときに意味を思い出す習慣をつけておくとよいでしょう。\"}]}",
"{\"id\":\"new20_e5_eigo_16\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"クラスアンケートの結果を読み取る：favoriteの集計\",\"description\":\"What's your favorite ~? のアンケート結果をグラフや表で示した英文を読み取る練習をする\",\"intro\":\"クラスで「好きな教科」「好きなスポーツ」についてアンケートを取り、その結果を英語で発表する、という場面は読解問題でもよく登場します。ここではアンケートをたずねる表現と、結果を数や割合で伝える言い方をまとめて練習します。\",\"order\":6595,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"アンケートをたずねる表現：What's your favorite subject?（好きな教科は何ですか）／What sport do you like the best?（一番好きなスポーツは何ですか）\",\"結果の人数を伝える表現：Ten students like math the best.（10人の生徒が算数を一番好きです）\",\"「一番人気がある」は the most popular：Soccer is the most popular sport in our class.（サッカーはクラスで一番人気のスポーツです）\",\"割合を伝える表現：Half of the students like summer.（生徒の半分は夏が好きです）／Most students（ほとんどの生徒）\",\"順位を伝える表現：The second most popular subject is science.（2番目に人気の教科は理科です）\"],\"sections\":[{\"heading\":\"アンケートをたずねる表現と結果の伝え方\",\"body\":\"クラスの好みを調べるアンケートでは、まず「一番好きなものは何か」をたずねる表現がよく使われます。\\n\\n■ アンケートのたずね方\\n・What's your favorite subject?（あなたの好きな教科は何ですか）favorite（お気に入りの、一番好きな）\\n・What sport do you like the best?（一番好きなスポーツは何ですか）like ~ the best（一番〜が好きだ）\\n・Which season do you like the best, spring, summer, fall, or winter?（春・夏・秋・冬のうち、どの季節が一番好きですか）\\n\\n■ 集計結果を人数で伝える表現\\nアンケートの結果は、多くの場合「〜人が…が好きだ」という形で発表されます。\\n・Ten students like math the best.（10人の生徒が算数を一番好きです）\\n・Five students chose science.（5人の生徒が理科を選びました）chose（chooseの過去形、選んだ）\\n・Nobody chose social studies.（社会科を選んだ人はだれもいませんでした）nobody（だれも〜ない）\\n\\n■ グラフや表とあわせて読む\\nこのような文章はグラフ（graph）や表（chart, table）とセットで出題されることが多く、Look at the graph.（グラフを見てください）という指示のあとに、グラフの内容を説明する文が続きます。数字（人数）と項目（教科名やスポーツ名）を対応させながら読む練習をしておきましょう。\",\"figureId\":\"xf_new20_e5_eigo_16\"},{\"heading\":\"一番人気・順位・割合を表す表現\",\"body\":\"アンケート結果の発表では、単に人数を並べるだけでなく、「一番人気があるのは何か」「2番目に多いのは何か」という順位や、「半分」「ほとんど」といった割合を伝える表現もよく使われます。\\n\\n■ 一番人気を表す the most popular\\n・Soccer is the most popular sport in our class.（サッカーはクラスで一番人気のスポーツです）the most popular（一番人気のある）＝popularの最上級\\n・Math is the most popular subject among boys.（算数は男子の間で一番人気の教科です）among（〜の間で）\\n\\n■ 順位を表す表現\\n・The second most popular subject is science.（2番目に人気の教科は理科です）the second most popular（2番目に人気のある）\\n・English comes in third place.（英語は3位です）come in ~ place（〜位になる）\\n\\n■ 割合を表す表現\\n・Half of the students like summer the best.（生徒の半分は夏が一番好きです）half of ~（〜の半分）\\n・Most students like P.E.（ほとんどの生徒は体育が好きです）most（ほとんどの）\\n・A few students like social studies.（少数の生徒は社会科が好きです）a few（少数の）\\n・No one likes it.（だれもそれが好きではありません）\\n\\n■ グラフ読解のコツ\\nこのタイプの読解問題では、「一番多い項目」「一番少ない項目」「2位の項目」「全体の何割か」という4つの角度から質問されることが多いです。文章中に出てくる数字と項目名を丁寧にメモしながら読み、the most popular（最も人気）とthe second most popular（2番目に人気）を取りちがえないように注意しましょう。\"},{\"heading\":\"なぜ人数・順位・割合の三つの言い方を分けて覚えるのか\",\"mangaId\":\"new20_e5_eigo_16_manga\",\"body\":\"アンケートの結果は、**人数**（Ten students like math the best.）、**順位**（Soccer is the most popular.／The second most popular is science.）、**割合**（Half of the students 〜／Most students 〜／A few students 〜）の三つの言い方で発表されます。設問は四つの角度（一番多い項目・一番少ない項目・2位の項目・全体の何割か）から作られるので、三つの言い方を分けて覚えておくと、どの表現がどの設問に対応するかがすぐ分かります。\\n\\nthe most popular と the second most popular を取りちがえやすいのは、どちらも most を含むからです。second が付けば「2番目」です。グラフや表とセットで出るときは、文の数字（人数）と項目（教科名）を一つずつ対応させながら読みます。\\n\\n■ 確かめのしかた\\n①たずね方：What's your favorite 〇〇?／What 〇〇 do you like the best?／Which 〇〇 do you like the best, A, B, or C?\\n②**人数**：〇 students like 〜 the best.／〇 students chose 〜.／Nobody chose 〜.\\n③**順位**：the most popular（1位）、the second most popular（2位）、comes in third place（3位）。second を見落としていないか。\\n④**割合**：half of（半分）、most（ほとんど）、a few（少数）、no one（だれも〜ない）。数字と項目名をメモしながら読む。\\n\\n★ ここがポイント：結果は**人数・順位・割合**の三つの言い方で発表され、設問もそれに対応して出る。**the most popular（1位）と the second most popular（2位）**を取りちがえない。\"}]}",
"{\"id\":\"new20_e5_eigo_17\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ほしいものを伝える表現：I want ~. / I'd like ~.\",\"description\":\"ほしいものやしたいことを伝える want to と I'd like to の使い方、誕生日プレゼントなどの場面での応用をまとめる\",\"intro\":\"「これがほしい」「あれをしたい」という気持ちを伝えるのはとても基本的で大切な表現です。ここではwantを使った基本の言い方から、より丁寧なI'd like（〜がほしいのですが）まで、場面に応じた使い分けを練習します。\",\"order\":6596,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"「〜がほしい」は I want ~.（名詞をそのまま置く）：I want a new bike.（新しい自転車がほしいです）\",\"「〜したい」は I want to ~.（動詞の原形を置く）：I want to go to Australia.（オーストラリアに行きたいです）\",\"丁寧な言い方：I'd like ~. / I'd like to ~.（I would like の短縮形）。店やお願いごとの場面では want より I'd like が好まれる。\",\"「何がほしいですか」What do you want? / What would you like?（後者の方が丁寧）\",\"「〜がほしいものはありません」I don't want anything. / Nothing in particular.（特にありません）\"],\"sections\":[{\"heading\":\"I want ~. の基本の使い方\",\"body\":\"「〜がほしい」「〜したい」という気持ちを伝えるもっとも基本的な語がwant（望む）です。wantのあとに何を置くかで意味が変わります。\\n\\n■ 名詞を置く：「〜がほしい」\\n・I want a new bike.（新しい自転車がほしいです）\\n・What do you want for your birthday?（誕生日に何がほしいですか）\\n・I want a video game.（ゲームソフトがほしいです）\\n\\n■ to＋動詞の原形を置く：「〜したい」\\nwantのあとに動作（〜すること）を続けたいときは、to＋動詞の原形（不定詞）を使います。\\n・I want to go to Australia.（オーストラリアに行きたいです）\\n・I want to be a doctor.（医者になりたいです）\\n・I want to play the piano.（ピアノをひきたいです）\\n\\n⚠ よくある間違い：I want go to Australia. のようにtoを落としてしまうミスが非常に多い。動作を望むときはwantとgoの間に必ずtoを入れる必要があります。「wantのあとに動詞が続くときはto」という形は不定詞の代表的な使い方の一つとして、特に意識して覚えておきましょう。\\n\\n■ 人に何かをしてほしいとき：want＋人＋to\\n「〜に…してほしい」と人に望む動作を伝えるときは、want＋人＋to＋動詞の原形という形を使います。\\n・I want you to help me.（あなたに手伝ってほしいです）\\n・My mother wants me to study more.（母は私にもっと勉強してほしいと思っています）\",\"figureId\":\"xf_new20_e5_eigo_17\",\"mangaId\":\"new20_e5_eigo_17_xm\"},{\"heading\":\"より丁寧なI'd like ~. の使い方\",\"body\":\"wantはとても便利な語ですが、目上の人に対して使ったり、お店で注文したりするときには、少し直接的すぎる印象を与えることがあります。そこで使われるのが I'd like ~.（〜がほしいのですが）という、より丁寧な言い方です。I'd like は I would like の短縮形です。\\n\\n■ I'd like ~. / I'd like to ~. の基本\\n・I'd like a hamburger, please.（ハンバーガーをお願いします）レストランでの注文\\n・I'd like to try this on.（これを試着したいのですが）お店での表現\\n・I'd like to visit Kyoto someday.（いつか京都を訪れたいです）\\n\\nwantと同じように、I'd likeのあとに名詞を置けば「〜がほしいのですが」、to＋動詞の原形を置けば「〜したいのですが」という意味になります。形はwantと同じですが、響きがより丁寧になります。\\n\\n■ たずねるときもWould you like ~?で丁寧に\\n相手にほしいものをたずねるときも、What do you want?よりWhat would you like?の方が丁寧な響きになります。\\n・What would you like for lunch?（昼食に何がよろしいですか）\\n・Would you like something to drink?（何かお飲み物はいかがですか）\\n\\n■ 「特にほしいものはない」と答える表現\\n・I don't want anything special.（特にほしいものはありません）\\n・Nothing in particular, thanks.（特にありません、ありがとう）in particular（特に）\\n\\n誕生日プレゼントについて話す会話文では、What do you want for your birthday?（誕生日に何がほしい？）とたずねられ、I want ~. またはI'd like ~. で答える、という流れが定番です。話し相手との関係（友達どうしか、目上の人に対してか）によってwantとI'd likeを使い分ける意識を持っておくと、会話文の空所補充問題でも自然な表現を選べるようになります。\"}],\"trapExamples\":[{\"question\":\"「私はケーキを作りたいです。」を英語にしなさい。\",\"wrongAnswer\":\"I want make a cake.\",\"trapExplanation\":\"wantのあとに動詞を続けるときにtoを入れ忘れてしまう。wantは「名詞」または「to＋動詞の原形」を目的語にとる動詞であり、動詞の原形をそのまま続けることはできない。\",\"correctAnswer\":\"I want to make a cake.\",\"correctExplanation\":\"wantのあとに動作を続けるときは必ずto＋動詞の原形にする。I want to make a cake.のtoを忘れると文法的に誤りになる。同じ形をとる動詞にはlike to、hope to、try toなどがあり、これらもすべてtoが必要になることをあわせて確認しておくとよい。\"}]}",
"{\"id\":\"new20_e5_eigo_18\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"ペンフレンドへの手紙の返事を書く\",\"description\":\"海外のペンフレンドからの手紙に対して、質問に答えながら自分のことを紹介する返信文の組み立て方を学ぶ\",\"intro\":\"手紙・メールの基本の型を学んだら、次は実際に「返事を書く」練習です。ペンフレンド（外国の文通相手）からの手紙には、たいてい相手からの質問が含まれています。ここでは、相手の質問に一つずつ答えながら、自分のことも伝える返信文の組み立て方を学びます。\",\"order\":6597,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"返事を書き出すときの表現：Thank you for your letter.（お手紙をありがとう）／I was happy to hear from you.（あなたから便りをもらってうれしかったです）\",\"相手の質問に答えるときは、質問と同じ形の文で答えると自然：You asked me about my hobby. My hobby is reading.（趣味について聞かれましたね。私の趣味は読書です）\",\"自分からも質問を返すと会話が続く：How about you? / What about you?（あなたはどうですか）\",\"返信の締めくくり：I hope to hear from you soon.（すぐにまたお便りをもらえるとうれしいです）／Please write back soon.（また早く返事をください）\",\"手紙の話題を変えるときのつなぎ語：By the way,（ところで）\"],\"sections\":[{\"heading\":\"相手の手紙に答える返信文の組み立て方\",\"body\":\"ペンフレンドからの手紙には、自己紹介のほかに「あなたの趣味は何ですか」「あなたの国の食べ物について教えてください」のような質問が含まれていることがよくあります。返事を書くときは、この質問に一つずつ丁寧に答えていくことが大切です。\\n\\n■ 書き出しの決まり文句\\n・Thank you for your letter.（お手紙をありがとう）\\n・I was happy to hear from you.（あなたから便りをもらってうれしかったです）hear from ~（〜から便りをもらう）\\n・I enjoyed reading your letter.（あなたの手紙を読んで楽しかったです）\\n\\n■ 相手の質問に答える\\n相手の手紙で聞かれた内容を確認してから答えると、話がかみ合った自然な返信文になります。\\n・You asked me about my favorite subject. My favorite subject is science.（好きな教科について聞かれましたね。私の好きな教科は理科です）\\n・In your letter, you asked what I do on weekends. I usually play soccer with my friends.（お手紙で週末に何をするか聞かれましたね。私はたいてい友達とサッカーをします）\\nこのように、You asked me about ~.（〜について聞かれましたね）という形を使うと、質問への応答であることがはっきり伝わります。\",\"figureId\":\"xf_new20_e5_eigo_18\",\"mangaId\":\"new20_e5_eigo_18_xm\"},{\"heading\":\"自分から質問を返す・話題を変える・締めくくる\",\"body\":\"手紙のやり取りを続けていくためには、自分の答えを伝えるだけでなく、相手にも質問を返すことが大切です。また、話題を変えるときや、手紙を締めくくるときにも決まった表現があります。\\n\\n■ 相手にも質問を返す\\n・How about you? / What about you?（あなたはどうですか）自分の答えのあとに付け加えるのが定番\\n・Do you have any pets?（ペットは飼っていますか）新しい質問を投げかける\\n\\n■ 話題を変えるときのつなぎ語\\n一つの話題について答え終わり、別の話題に移るときは、By the way,（ところで）というつなぎ語がよく使われます。\\n・By the way, do you like Japanese food?（ところで、あなたは日本食が好きですか）\\n\\n■ 返信の締めくくり方\\n手紙の最後には、次の手紙を楽しみにしていることを伝える決まり文句と、結びの言葉、自分の名前を書きます。\\n・I hope to hear from you soon.（すぐにまたお便りをもらえるとうれしいです）\\n・Please write back soon.（また早く返事をください）write back（返事を書く）\\n・Take care,（お元気で、）\\n・Your friend, Kenta（あなたの友達、ケンタより）\\n\\n■ 返信文全体の流れ\\nペンフレンドへの返信文は、①お礼のあいさつ→②相手の質問への答え→③自分からの質問→④（必要なら話題を変える）→⑤締めくくりの言葉、という流れで組み立てるのが基本です。この流れを意識しておくと、自分で返信文を書く英作文問題でも、他人の返信文を読んで内容を整理する読解問題でも役に立ちます。\"}]}",
"{\"id\":\"new20_e5_eigo_19\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"一週間の予定表（スケジュール）を読み取る\",\"description\":\"曜日ごとの予定が並ぶ時間割・スケジュール表の英文を読み取り、質問された曜日や活動を正確に見つける練習\",\"intro\":\"「月曜日はピアノのレッスンがある」「水曜日はサッカーの練習がある」というように、曜日ごとの予定が一覧になった表（スケジュール表）は、読解問題の資料としてよく使われます。曜日の名前と活動の名前を素早く対応させて読み取る練習をしましょう。\",\"order\":6598,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"曜日の確認：Monday・Tuesday・Wednesday・Thursday・Friday・Saturday・Sunday（曜日名は必ず大文字で始める）\",\"予定をたずねる表現：What do you do on Mondays?（月曜日はいつも何をしますか）／What are you doing this Saturday?（今度の土曜日は何をする予定ですか）\",\"習い事を表す表現：have a piano lesson（ピアノのレッスンがある）・have soccer practice（サッカーの練習がある）・go to swimming school（水泳教室に行く）\",\"「〜曜日ごとに」を表す複数形：on Mondays（毎週月曜日に）はふだんの習慣、on Monday（この月曜日に）は特定の1回を指す。\",\"「予定がない、ひまな日」は free：I'm free on Sundays.（日曜日はひまです）\"],\"sections\":[{\"heading\":\"曜日と予定を対応させて読む\",\"body\":\"スケジュール表を使った読解問題では、曜日と活動を正確に対応させることが何より大切です。まず曜日の名前と、予定・習い事を表す表現を確認しましょう。\\n\\n■ 曜日の名前（必ず大文字で始める）\\nMonday（月）・Tuesday（火）・Wednesday（水）・Thursday（木）・Friday（金）・Saturday（土）・Sunday（日）\\n\\n■ 予定・習い事を表す表現\\n・have a piano lesson（ピアノのレッスンがある）\\n・have soccer practice（サッカーの練習がある）\\n・go to swimming school（水泳教室に行く）\\n・go to cram school（塾に行く）cram school（塾）\\n・have a club activity（クラブ活動がある）\\n\\n■ スケジュール表の読み方の例\\nOn Mondays, I have a piano lesson after school. On Wednesdays, I go to swimming school. I have soccer practice on Fridays. I'm free on Sundays.\\n（月曜日は放課後ピアノのレッスンがあります。水曜日は水泳教室に行きます。金曜日はサッカーの練習があります。日曜日はひまです。）\\n\\nこのような文章を読むときは、Monday→piano lesson、Wednesday→swimming school、Friday→soccer practice、Sunday→freeというように、曜日と活動を一つずつペアにしてメモしながら読むと、あとの設問（例：「水曜日に何がありますか」）に素早く正確に答えられます。\",\"figureId\":\"xf_new20_e5_eigo_19\"},{\"heading\":\"onの使い方のちがいと、予定をたずねる表現\",\"body\":\"曜日を使った予定の文では、on Monday（この月曜日に、特定の1回）とon Mondays（毎週月曜日に、習慣として）のちがいに注意が必要です。\\n\\n■ on＋曜日（単数）と on＋曜日s（複数）のちがい\\n・I have a piano lesson on Monday.（（今週の）月曜日にピアノのレッスンがあります）特定の1回の予定\\n・I have a piano lesson on Mondays.（毎週月曜日にピアノのレッスンがあります）習慣としての予定、everyの意味を含む\\nスケジュール表を説明する文章では、ふだんの習慣について述べていることが多いため、曜日の複数形（Mondays, Fridaysなど）がよく使われます。単数形か複数形かによって「毎週のことなのか、今回だけのことなのか」が変わるので、細かい部分ですが読み落とさないようにしましょう。\\n\\n■ 予定をたずねる表現\\n・What do you do on Mondays?（月曜日はいつも何をしますか）習慣をたずねる、現在形\\n・What are you doing this Saturday?（今度の土曜日は何をする予定ですか）現在進行形で近い未来の予定をたずねる\\n・Are you free on Sunday?（日曜日はひまですか）free（ひまな、予定のない）\\n\\n■ 予定がないことを伝える表現\\n・I'm free on Sundays.（日曜日はひまです）\\n・I don't have any plans on Saturday.（土曜日は何も予定がありません）\\n\\n■ スケジュール表読解のコツ\\nスケジュール表の読解問題では、①曜日ごとの活動を一つずつ確認する、②on＋曜日（単数・複数）のちがいに注意する、③「ひまな日」を聞かれたときはfreeやdon't have any plansという表現を手がかりに探す、という3つのポイントを意識すると、正確に、そして素早く答えを見つけられるようになります。\",\"mangaId\":\"new20_e5_eigo_19_xm\"}]}",
"{\"id\":\"new20_e5_eigo_20\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"動物園の案内図・パンフレットを読み取る\",\"description\":\"Zoo Map やパンフレットに出てくる動物の位置・展示時間の表現を読み取り、道案内表現とあわせて練習する\",\"intro\":\"遠足で動物園に行く場面や、動物園のパンフレットを読む問題は、位置を表す前置詞と道案内の表現をまとめて確認できる題材としてよく使われます。ここでは案内図（map）から動物の場所を探し、展示・エサやりの時間を読み取る練習をします。\",\"order\":6599,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"場所をたずねる：Where is the lion?（ライオンはどこにいますか）／Where can I find the elephants?（ゾウはどこで見られますか）\",\"案内図での位置の説明：The lion is next to the tiger.（ライオンはトラのとなりにいます）／The monkey house is between the zoo shop and the entrance.（サル舎はお店と入口の間にあります）\",\"道順の説明：Go straight and turn right at the panda house.（まっすぐ行ってパンダ舎で右に曲がってください）\",\"時間の案内：Feeding time is at 2:00 p.m.（エサやりの時間は午後2時です）／The zoo is open from 9 a.m. to 5 p.m.（動物園は午前9時から午後5時まで開いています）\",\"案内図の記号：You are here（現在地）・Entrance（入口）・Exit（出口）・Restroom（トイレ）・Gift Shop（売店）\"],\"sections\":[{\"heading\":\"案内図で動物の場所をたずねる・説明する\",\"body\":\"動物園のパンフレットに載っている案内図（zoo map）を使った読解問題では、動物の名前と、その位置を表す前置詞をセットで読み取る力が試されます。\\n\\n■ 場所をたずねる表現\\n・Where is the lion?（ライオンはどこにいますか）\\n・Where can I find the elephants?（ゾウはどこで見られますか）where can I find ~（〜はどこで見つけられますか）は、道をたずねるときのやや丁寧な言い方\\n\\n■ 位置を説明する表現（前置詞の復習と応用）\\n・The lion is next to the tiger.（ライオンはトラのとなりにいます）next to（〜のとなりに）\\n・The monkey house is between the zoo shop and the entrance.（サル舎はお店と入口の間にあります）between A and B（AとBの間に）\\n・The panda house is across from the restaurant.（パンダ舎はレストランの向かいにあります）across from（〜の向かいに）\\n・The bird cage is behind the elephant area.（鳥かごはゾウのエリアの後ろにあります）behind（〜の後ろに）\\n\\n■ 案内図でよく使われる記号・語\\n・You are here（現在地、案内図の中で自分の場所を示す印）\\n・Entrance（入口）／Exit（出口）\\n・Restroom（トイレ）／Gift Shop（売店）／Restaurant（レストラン）\\nこれらは案内図の中に短い単語やアイコンとして書かれていることが多いので、文章だけでなく図の中の表示もあわせてチェックする習慣が大切です。\",\"figureId\":\"xf_new20_e5_eigo_20\",\"mangaId\":\"new20_e5_eigo_20_xm\"},{\"heading\":\"道順・展示時間の案内を読み取る\",\"body\":\"動物園のパンフレットには、地図上の位置だけでなく、入口からの道順や、エサやり・ショーの時間についての案内文もよく含まれます。\\n\\n■ 道順を説明する表現\\n・Go straight and turn right at the panda house.（まっすぐ行ってパンダ舎で右に曲がってください）go straight（まっすぐ進む）、turn right / turn left（右／左に曲がる）\\n・Walk past the gift shop, and you will see the lion area on your left.（売店を通り過ぎると、左手にライオンのエリアが見えます）walk past ~（〜を通り過ぎる）\\n・The elephant area is a five-minute walk from the entrance.（ゾウのエリアは入口から歩いて5分です）a ~-minute walk（歩いて〜分）\\n\\n■ 開園時間・展示時間の案内\\n・The zoo is open from 9 a.m. to 5 p.m.（動物園は午前9時から午後5時まで開いています）from A to B（AからBまで）\\n・Feeding time is at 2:00 p.m.（エサやりの時間は午後2時です）feeding time（エサやりの時間）\\n・The panda show starts at 11 a.m.（パンダのショーは午前11時に始まります）\\n・The zoo is closed on Mondays.（動物園は月曜日は休園です）be closed（閉まっている）\\n\\n■ 総合的な読解のコツ\\nこのタイプの読解問題では、①地図から動物の位置を見つける問題、②道順の説明にそって正しいルートを選ぶ問題、③時間の案内から「何時に何が見られるか」を答える問題、の3パターンがよく出題されます。案内図・道順・時間の3つの情報を混同しないよう、それぞれ別の観点として整理しながら読み進めることが高得点のコツです。前置詞（次に・間に・後ろに）の理解と、時刻・時間の表現の理解を組み合わせた総合問題として、落ち着いて取り組みましょう。\"}]}",
"{\"id\":\"new20_e6_eigo_01\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"過去形で自分のことを話す：昨日・先週にしたこと\",\"description\":\"規則動詞と不規則動詞の過去形を混ぜて、実際に自分の一日を語る・書く練習\",\"intro\":\"「文法は覚えたのに、いざ自分のことを英語で話そうとすると詰まってしまう」——これは過去形の暗記あるあるだ。ここでは play→played のような規則動詞と go→went のような不規則動詞をいっしょに使いながら、実際に「昨日したこと」を一つの文章にまとめる練習をする。ゴールは「正しい過去形が言える」ではなく「昨日の自分をそのまま英語で話せる」ことだ。\",\"order\":7080,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"過去形は主語が何であっても形が変わらない（I played／She played、どちらも played）\",\"規則動詞は原形＋ed、不規則動詞は go-went、eat-ate のように形をまるごと覚える\",\"否定文・疑問文は did を使い、そのあとの動詞は必ず原形にもどす（didn't went ✕ → didn't go ○）\",\"時を表す語（yesterday／last night／last week／two days ago／this morning）は文の最後か最初に置く\",\"過去の一日を語るときは時間の流れの順に動詞を並べると聞き手が理解しやすい\"],\"sections\":[{\"heading\":\"1. 過去のことを語る文の型\",\"mangaId\":\"new20_e6_eigo_01_manga\",\"body\":\"英語で「〜した」と過去のことを言うときは、動詞を過去形に変えるだけでよい。日本語の「食べる→食べた」のように主語によって形が変わることは一切ない。\\n\\n■ 基本の形\\n　主語＋動詞の過去形＋（目的語）＋（時を表す語句）\\n　例）I played tennis yesterday.（私は昨日テニスをした）\\n　例）She watched a movie last night.（彼女は昨夜映画を見た）\\n　例）We visited Kyoto last summer.（私たちは去年の夏、京都を訪れた）\\n\\n★ ポイント：主語が I でも She でも We でも、動詞の形は played／watched／visited のまま変わらない。現在形の「三単現の s」に慣れていると、つい過去形にも s をつけたくなるが、過去形には三単現のルールは存在しない。\\n\\n■ 時を表す語句の位置\\n「いつ」を表す語句（yesterday、last night、last week、two days ago、this morning）は文末に置くのが基本だが、強調したいときは文の最初に置いてコンマで区切ることもできる。\\n　例）Yesterday, I cleaned my room.（昨日、私は部屋を掃除した）\\n\\n■ 否定文・疑問文の作り方（did を使う）\\n過去の一般動詞の否定文・疑問文は、現在形の do/does の代わりに did を使う。didを使ったら、あとの動詞は必ず原形にもどす。\\n　肯定文：I played soccer.\\n　否定文：I didn't play soccer.（× I didn't played）\\n　疑問文：Did you play soccer? — Yes, I did. / No, I didn't.\\n⚠ 注意：did を使った時点で「過去」を表す仕事は終わっているので、動詞にもう一度 -ed をつけると二重に過去形にしてしまう間違いになる。「did が過去の目印を1つ持っている」とイメージすると防げる。\",\"figureId\":\"xf_new20_e6_eigo_01\"},{\"heading\":\"2. 規則動詞と不規則動詞を混ぜて一日を語る\",\"body\":\"実際の入試や検定のスピーキングでは、1つの文だけでなく「一日の流れ」をひとまとまりの英語で話す・書く力が求められる。次のモデル文で、規則動詞（-ed）と不規則動詞（形が変わる）がどう混ざって使われるかを見てみよう。\\n\\n■ モデル文\\nYesterday I woke up at seven. I ate breakfast with my family, and then I studied math for an hour. After that, I played soccer with my friends in the park. In the evening, I watched TV and did my homework. I went to bed at ten.\\n（昨日、私は7時に起きた。家族と朝食を食べ、それから1時間算数を勉強した。そのあと、公園で友達とサッカーをした。夕方、テレビを見て宿題をした。10時に寝た。）\\n\\n■ 使われている動詞の原形と過去形\\n　wake→woke（不規則）／eat→ate（不規則）／study→studied（規則・yをiに変えてed）\\n　play→played（規則）／watch→watched（規則）／do→did（不規則）／go→went（不規則）\\n\\n■ よく使う不規則動詞リスト（一日の話でよく登場するもの）\\n　get up→got up（起きる）／have→had（食べる・持つ）／go→went（行く）／come→came（来る）\\n　see→saw（見る・会う）／read→read（発音が「レッド」に変わる）／make→made（作る）\\n　buy→bought（買う）／meet→met（会う）／run→ran（走る）／swim→swam（泳ぐ）\\n\\n★ ポイント：話す順番は必ず時間の流れ通りにする。first（まず）、then／after that（それから）、finally（最後に）といったつなぎ語を使うと、聞いている人が場面をイメージしやすくなる。\\n\\n⚠ よくある間違い：不規則動詞にも -ed をつけてしまう（goed、eated、buyed など）。不規則動詞は「音でセットのまま丸ごと覚える」しかない。原形・過去形をペアで声に出して繰り返すのが一番の近道。\"},{\"heading\":\"3. 週末日記を書いてみる\",\"body\":\"覚えた表現を実際に使ってみよう。次のテンプレートを使えば、自分の週末を英語の日記にできる。\\n\\n■ テンプレート\\nLast Saturday, I ＿＿＿（動詞の過去形）in the morning. In the afternoon, I ＿＿＿ with ＿＿＿（人）. It was ＿＿＿（形容詞）. In the evening, I ＿＿＿. I went to bed at ＿＿＿.\\n\\n■ 記入例\\nLast Saturday, I got up late in the morning. In the afternoon, I went shopping with my mother. It was fun. In the evening, I cooked dinner with my sister. I went to bed at eleven.\\n（先週の土曜日、朝は寝坊した。午後は母と買い物に行った。楽しかった。夕方は姉と夕食を作った。11時に寝た。）\\n\\n■ 感想を1文加えるコツ\\n「楽しかった／疲れた／驚いた」などの感想は It was ~. や I was ~. の形で最後に足すと、ただの事実の羅列ではなく気持ちが伝わる文章になる。\\n　例）It was a good day.（いい一日だった）\\n　例）I was very tired.（とても疲れた）\\n\\n⚠ 注意：was と were の使い分けを忘れずに。主語が I／he／she／it のときは was、you／we／they のときは were。\\n　例）My friends were happy.（私の友達はうれしそうだった）\\n\\n★ ポイント：日記や作文では同じ動詞ばかり使わず、study／play／watch／read／cook／clean のように動作を変えると文章にリズムが出て、語彙力があることも伝わる。\"}]}",
"{\"id\":\"new20_e6_eigo_02\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"思い出を伝える①：夏休みの思い出を英語で書く\",\"description\":\"過去形を使って、旅行や体験を「時系列＋感想」の型で伝える作文の練習\",\"intro\":\"「楽しかった」だけでは伝わらないのが英作文の難しさ。夏休みの思い出のような「過去の体験」を書くには、いつ・どこで・何をしたか（時系列）と、それについてどう感じたか（感想）の2つを組み合わせる必要がある。ここではその型を身につけて、実際に自分の思い出を英語にしてみよう。\",\"order\":7081,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"思い出の文章は「導入（いつ・どこへ）→出来事（何をしたか）→感想（どう感じたか）」の3段構成が基本\",\"出来事を並べるときは first／next／then／after that／finally の順序語を使う\",\"感想は It was ~.（それは〜だった）／I was ~.（私は〜だった）／I enjoyed ~ing.（〜して楽しかった）の3パターンで表せる\",\"「一番よかったこと」を伝えるときは My favorite part was ~. や The best thing was ~. が便利\",\"過去のことを書くので、動詞はすべて過去形にそろえる（現在形が混ざらないよう注意）\"],\"sections\":[{\"heading\":\"1. 思い出の文章の組み立て方\",\"body\":\"思い出を伝える文章には、日本語でも英語でも共通する「型」がある。いきなり出来事を並べるのではなく、次の3つのブロックで組み立てるとまとまりのある文章になる。\\n\\n■ 3段構成\\n①導入：いつ・どこへ行ったか\\n　例）Last summer, I went to Okinawa with my family.（去年の夏、私は家族と沖縄に行った）\\n②出来事：そこで何をしたか（2〜4個の行動を時間順に）\\n　例）First, we went to the beach. Then, we swam in the sea. After that, we ate shaved ice.\\n③感想：全体を通してどう感じたか\\n　例）It was one of the best days of my life.（人生で最高の一日の1つだった）\\n\\n■ 順序を示すつなぎ語\\n　first（まず）／next／then（次に）／after that（そのあと）／finally／in the end（最後に）\\nこれらを使うと、動詞を並べるだけの単調な文章ではなく、「流れ」が読み手に伝わる文章になる。\\n\\n★ ポイント：出来事を詰め込みすぎない。3〜4個の行動にしぼり、それぞれに簡単な感想（It was fun. など）を添えるほうが、10個の事実を並べるより採点者に伝わりやすい。\",\"figureId\":\"xf_new20_e6_eigo_02\"},{\"heading\":\"2. 感想を伝える3つの表現パターン\",\"body\":\"思い出を語るうえで最も大切なのは「事実」だけでなく「気持ち」を伝えることだ。次の3パターンを覚えておけば、どんな体験にも感想を添えられる。\\n\\n■ パターン①：It was ~.（それは〜だった）\\n　形容詞を1つ入れるだけの最も簡単な形。\\n　例）It was exciting.（わくわくした）／It was amazing.（すごかった）／It was a little scary.（少し怖かった）\\n\\n■ パターン②：I was ~.（私は〜な気持ちだった）\\n　自分の感情そのものを言う形。\\n　例）I was so happy.（とてもうれしかった）／I was surprised.（驚いた）／I was nervous at first.（最初は緊張した）\\n\\n■ パターン③：I enjoyed ~ing.（〜して楽しかった）\\n　動詞を動名詞（-ing）にして「〜すること」を楽しんだと伝える形。enjoy のあとは to ではなく必ず -ing。\\n　例）I enjoyed swimming in the sea.（海で泳いで楽しかった）\\n　例）I enjoyed talking with my cousins.（いとこたちと話せて楽しかった）\\n\\n■ 一番の思い出を強調する表現\\n　My favorite part was ~.（一番よかったのは〜だった）\\n　The best thing about the trip was ~.（旅行で一番よかったのは〜だった）\\n　例）My favorite part was watching the fireworks.（一番よかったのは花火を見たことだった）\\n\\n⚠ 注意：enjoy のあとに to不定詞を置く「I enjoyed to swim.」は誤り。enjoy は動名詞だけをとる動詞（他に finish、stop、give up なども同じグループ）。\",\"mangaId\":\"new20_e6_eigo_02_xm\"},{\"heading\":\"3. 実際に書いてみる：完成モデルと自分の思い出\",\"body\":\"ここまでの型を使って、実際にひとまとまりの文章にしてみよう。\\n\\n■ 完成モデル文\\nLast summer, I went to my grandmother's house in Nagano with my family. First, we hiked in the mountains. Next, we caught insects in the forest. Then, we made curry for dinner together. It was a lot of fun, and the curry was delicious. My favorite part was seeing so many stars at night. I was really surprised because I had never seen so many stars in the city. It was one of my best memories.\\n（去年の夏、私は家族と長野の祖母の家に行った。まず山でハイキングをした。次に森で虫を捕まえた。それから夕食に一緒にカレーを作った。とても楽しくて、カレーもおいしかった。一番よかったのは夜にたくさんの星を見たことだった。街ではあんなに星を見たことがなかったのでとても驚いた。私の一番の思い出の1つになった。）\\n\\n■ 自分で書くときのチェックリスト\\n①動詞はすべて過去形になっているか（現在形が混ざっていないか）\\n②出来事は3〜4個にしぼり、順序語（first／then／after thatなど）でつないでいるか\\n③最後に感想の文（It was ~. / I was ~. / My favorite part was ~.）を入れたか\\n④主語と動詞の対応（I went、We swam など）が正しいか\\n\\n★ ポイント：入試の自由英作文では「何をしたか」より「どう感じたか・なぜそう感じたか」を書けているかで差がつく。事実の羅列で終わらせず、必ず理由や感想を1文加える習慣をつけよう。\"}]}",
"{\"id\":\"new20_e6_eigo_03\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"思い出を伝える②：学校行事の思い出をスピーチする\",\"description\":\"運動会・修学旅行などの学校行事について、話の構成を意識してスピーチ形式で伝える\",\"intro\":\"入試の面接や英語スピーチコンテストでは「学校行事の思い出」を聞かれることが多い。原稿を丸暗記するのではなく、「聞き手を引きつける組み立て方」を知っていれば、どんな行事についても自分の言葉で話せるようになる。ここでは運動会・修学旅行を例に、スピーチの型を練習する。\",\"order\":7082,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"スピーチは「聞き手への呼びかけ→話題の紹介→出来事→感想・学んだこと→締めの一言」の順で組み立てる\",\"出来事を語るときは「その場にいるような描写」（見たもの・聞いたもの・感じたこと）を1つ加えると印象が強くなる\",\"「大変だったこと→乗り越えたこと」の流れを入れると、単なる楽しい話より説得力が増す\",\"I learned that ~.（〜だと学んだ）／I realized that ~.（〜だと気づいた）で経験から得たことを伝えられる\",\"スピーチの最後は Thank you for listening. で締めるのが基本マナー\"],\"sections\":[{\"heading\":\"1. スピーチの組み立て方\",\"body\":\"作文と違い、スピーチは「聞いている人」を意識した組み立てが必要になる。次の5つのブロックを意識しよう。\\n\\n①呼びかけ・自己紹介\\n　例）Hello, everyone. Today I want to talk about my school trip.（みなさん、こんにちは。今日は修学旅行について話します）\\n②話題の紹介（いつ・どこで・何の行事か）\\n　例）Last October, my class went to Kyoto and Nara for two days.\\n③出来事（2〜3個の場面を選ぶ）\\n　例）On the first day, we visited an old temple. On the second day, we made traditional sweets.\\n④感想・学んだこと\\n　例）I learned that Kyoto has a very long history.\\n⑤締めの一言\\n　例）This trip is one of my best memories. Thank you for listening.\\n\\n★ ポイント：作文と違い、声に出して読んだときのリズムを意識する。1文を長くしすぎず、区切りのよいところで文を切ると聞き取りやすいスピーチになる。\\n\\n⚠ 注意：出来事を全部話そうとしない。3日間の行事なら「最も印象に残った場面」を2〜3個に絞るほうが、聞き手の記憶に残るスピーチになる。\",\"figureId\":\"xf_new20_e6_eigo_03\"},{\"heading\":\"2. その場にいるような描写を加える\",\"body\":\"ただ「楽しかった」と言うだけでなく、「何を見て・何を聞いて・何を感じたか」を1つ描写に加えると、聞き手がその場面を想像できるスピーチになる。\\n\\n■ 見たものを伝える\\n　I saw a lot of beautiful autumn leaves.（たくさんのきれいな紅葉を見た）\\n■ 聞いたものを伝える\\n　I heard a lot of interesting stories from the guide.（ガイドさんからたくさん面白い話を聞いた）\\n■ 感じたことを伝える（五感＋気持ち）\\n　The mochi we made was very sticky, but it was delicious.（作ったおもちはとても伸びたが、おいしかった）\\n\\n■ 「大変だったこと→乗り越えたこと」の型\\n運動会や修学旅行では、うまくいかなかったことを正直に話し、そこから何を得たかを伝えるとスピーチに深みが出る。\\n　例）Before the relay, I was very nervous because I am not a fast runner. But my friends cheered for me, and I did my best. I was so happy when we finished the race together.\\n　（リレーの前、走るのが速くないのでとても緊張した。でも友達が応援してくれて、全力を出した。一緒にゴールできてとてもうれしかった。）\\n\\n★ ポイント：完璧な結果（1位になった、成功した）でなくてもよい。「不安だったけれど、こう乗り越えた」という流れのほうが、聞き手の共感を得やすい。\",\"mangaId\":\"new20_e6_eigo_03_xm\"},{\"heading\":\"3. 学んだことを伝える表現と締めの言葉\",\"body\":\"行事から何を学んだかを伝える表現は、スピーチの説得力を大きく高める。\\n\\n■ 学び・気づきを伝える表現\\n　I learned that ~.（〜だと学んだ）\\n　　例）I learned that teamwork is very important.（チームワークがとても大切だと学んだ）\\n　I realized that ~.（〜だと気づいた）\\n　　例）I realized that I can do more than I thought.（自分が思っていたよりできることに気づいた）\\n　Thanks to ~, I could ...（〜のおかげで…できた）\\n　　例）Thanks to my classmates, I could finish the marathon.（クラスメートのおかげでマラソンを完走できた）\\n\\n■ スピーチの締め方\\n最後は行事全体をひとことでまとめ、聞いてくれた人へのお礼で終えるのが基本マナー。\\n　例）This event taught me a lot, and I will never forget it. Thank you for listening.\\n　（この行事はたくさんのことを教えてくれ、私は決して忘れません。聞いてくれてありがとうございました。）\\n\\n■ 覚えておきたい行事語彙\\n　sports day（運動会）／school trip（修学旅行）／chorus contest（合唱コンクール）／\\n　relay（リレー）／tug-of-war（綱引き）／graduation ceremony（卒業式）\\n\\n⚠ 注意：Thank you for listening. は発表の最後に言う決まり文句。Thank you for listen. のように動詞をそのまま置かない（前置詞forのあとは -ing形）。\"}]}",
"{\"id\":\"new20_e6_eigo_04\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来の予定を伝える①：週末の予定を友達と相談する\",\"description\":\"will と be going to、Are you free? などを使い、実際の予定を決める会話を組み立てる\",\"intro\":\"「will と be going to の違い」は文法問題として習っただけでは、実際の会話でとっさに使い分けるのは難しい。ここでは「週末に何をする？」という自然な会話の流れの中で、予定を提案し、都合を聞き、返事をするという一連のやり取りを練習する。\",\"order\":7083,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"相手の予定をたずねるときは Are you free ~? / What are you doing ~? / Do you have any plans ~? を使う\",\"前から決めている予定は be going to、その場で決めた予定は will で表す\",\"誘う表現：Would you like to ~? / How about ~ing? / Let's ~.、それぞれ丁寧さと形（動詞の原形か-ing）が違う\",\"誘いを受ける：Sure. / Sounds good. / I'd love to.、断る：I'm sorry, I can't. I already have plans.\",\"予定を決めたら日時・場所を確認し合う一言（What time should we meet? など）を忘れない\"],\"sections\":[{\"heading\":\"1. 相手の予定をたずねる・都合をたずねる\",\"body\":\"友達を何かに誘うときは、まず相手の予定や都合をたずねるところから始まる。使える表現を場面別に整理しよう。\\n\\n■ 空いているかをたずねる\\n　Are you free this Saturday?（今週の土曜日は空いている？）\\n　Are you free after school?（放課後は空いている？）\\n■ 予定があるかをたずねる\\n　Do you have any plans for the weekend?（週末に何か予定はある？）\\n　What are you doing this Sunday?（今度の日曜日、何か予定は？）※現在進行形で近い未来を表す\\n\\n■ 答え方\\n　空いているとき：I'm free. / I don't have any plans.\\n　予定があるとき：I'm going to visit my grandmother. / I have a piano lesson.\\n\\n★ ポイント：What are you doing this Sunday? のように、現在進行形（be動詞+ing）で近い未来の予定を表すことがある。これは「もう決まっている予定」を表すときによく使われる自然な言い方。\\n\\n⚠ 注意：疑問文の形を間違えやすい。Are you free? は be動詞の疑問文なので Do を使わない（× Do you free?）。\",\"figureId\":\"xf_new20_e6_eigo_04\"},{\"heading\":\"2. will と be going to を会話の中で使い分ける\",\"mangaId\":\"new20_e6_eigo_04_manga\",\"body\":\"文法では「will＝その場の意志、be going to＝前からの予定」と習うが、実際の会話ではこの違いがそのまま表れる。\\n\\n■ その場で決める・提案に答える → will\\n友達に誘われて「じゃあ〜しよう」とその場で決めるときは will を使う。\\n　A: Let's go to the new bakery this weekend.\\n　B: OK, I will go with you!（うん、一緒に行くよ！）※その場で決めた\\n\\n■ すでに決めていた予定を伝える → be going to\\n誘われる前から決まっていた予定を答えるときは be going to を使う。\\n　A: Are you free this Saturday?\\n　B: Sorry, I'm going to have a piano lesson.（ごめん、ピアノのレッスンがあるんだ）※前から決まっている\\n\\n■ 天気などの根拠ある予測 → be going to\\n　Look at the sky. It's going to rain soon.（空を見て。もうすぐ雨が降りそうだ）\\n\\n■ 誘う表現とその返事\\n　誘う：Would you like to come with us?／How about coming with us?／Let's go together.\\n　　※ Would you like to のあとは動詞の原形、How about のあとは動名詞（-ing）\\n　受ける：Sure, I'd love to. / That sounds fun. / OK, let's go.\\n　断る：I'm sorry, I can't. I already have plans that day.\\n\\n⚠ 注意：Would you like to のあとに -ing を置いてしまう間違い（× Would you like to going）が多い。to のあとは常に動詞の原形。\"},{\"heading\":\"3. 会話をまとめる：日時・場所を決める\",\"body\":\"誘いを受けたら、最後に日時・場所を具体的に確認し合う一言があると、実際に使える自然な会話になる。\\n\\n■ 会話のモデル\\nA: Are you free this Sunday?\\nB: Yes, I'm free in the afternoon. Why?\\nA: Do you want to go to the new aquarium with me?\\nB: Sounds great! What time should we meet?\\nA: Let's meet at the station at ten.\\nB: OK, see you then!\\n（A：今度の日曜日空いてる？　B：うん、午後は空いてるよ。どうして？　A：新しい水族館に一緒に行かない？　B：いいね！　何時に待ち合わせる？　A：10時に駅で待ち合わせよう。　B：OK、じゃあね！）\\n\\n■ 待ち合わせでよく使う表現\\n　What time should we meet?（何時に待ち合わせる？）\\n　Where should we meet?（どこで待ち合わせる？）\\n　Let's meet at ~.（〜で待ち合わせよう）\\n　See you then!（じゃあその時にね！）\\n\\n★ ポイント：実際の会話は「誘う→都合を確認→受ける・断る→詳細を決める」という流れが自然。この4つのステップを覚えておけば、旅行や買い物など話題が変わっても同じ型で会話が組み立てられる。\"}]}",
"{\"id\":\"new20_e6_eigo_05\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"未来の予定を伝える②：お知らせ文・予告文を読む\",\"description\":\"イベント案内・天気予報など、未来のことが書かれた実用文を正確に読み取る練習\",\"intro\":\"入試の読解問題には、学校のお知らせや天気予報のような「未来の予定が書かれた実用文」がよく出る。物語文とは違い、日付・時間・場所などの「情報」を正確に拾う読み方が必要になる。ここではポスターやアナウンス文を題材に、その読み方を練習する。\",\"order\":7084,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"お知らせ文は「何が・いつ・どこで・持ち物や注意」の情報を素早く見つける読み方をする\",\"will はお知らせや予報での「予定」を表すのによく使われる（The event will be held ~.）\",\"be held（開催される）、take place（行われる）はイベント告知でよく使う受け身表現\",\"天気予報では It will be sunny/rainy/cloudy. や高気温・低気温の数字表現が頻出\",\"「持ち物」「注意事項」は Please bring ~. / Don't forget to ~. のパターンで表される\"],\"sections\":[{\"heading\":\"1. お知らせ文の読み方：情報を素早くつかむ\",\"body\":\"学校行事やイベントのお知らせ文は、感情を読み取る物語文と違い、「事実」を正確に拾う読み方が必要になる。次の5つの質問を頭に置きながら読むと、情報を取りこぼさない。\\n\\n①What（何が行われるか）\\n②When（いつ）\\n③Where（どこで）\\n④Who（誰が対象か・誰が主催か）\\n⑤持ち物・注意事項は何か\\n\\n■ モデル文\\nSchool Festival Notice\\nOur school festival will be held on Saturday, November 14th. It will start at nine a.m. and end at three p.m. All students and their families are welcome. Please bring your own lunch. If it rains, the event will be held in the gym instead of the schoolyard.\\n（学校祭のお知らせ：学校祭は11月14日土曜日に開催されます。午前9時に始まり午後3時に終わります。全生徒とご家族が参加できます。お弁当をご持参ください。雨天の場合、校庭ではなく体育館で行われます。）\\n\\n■ 上のモデル文から5つの情報を抜き出す\\n　What：school festival　When：Saturday, November 14th, 9 a.m.–3 p.m.\\n　Where：schoolyard（雨天時は gym）　Who：all students and their families\\n　持ち物：lunch\\n\\n★ ポイント：入試のお知らせ文問題は「本文のどこに書いてあるか」を探す力を試している。最初から全訳しようとせず、質問文で聞かれているキーワード（日時・場所・持ち物など）を先に探すつもりで読むと速く正確に解ける。\",\"figureId\":\"xf_new20_e6_eigo_05\"},{\"heading\":\"2. お知らせでよく使う未来表現\",\"body\":\"お知らせ文・アナウンス文・予報文では、be going to よりも will のほうがよく使われる。これは「話し手個人の予定」ではなく「公式に決まっていること・客観的な予測」を伝える場面が多いためだ。\\n\\n■ 開催を伝える表現\\n　The concert will be held on May 5th.（コンサートは5月5日に開催されます）\\n　The event will take place in the park.（イベントは公園で行われます）\\n　※ be held と take place はどちらも「（イベントが）行われる」という意味で、受け身の形 be held に注意。\\n\\n■ 変更・中止を伝える表現\\n　The trip will be canceled if it rains.（雨天の場合、遠足は中止になります）\\n　The date has been changed to June 2nd.（日付は6月2日に変更されました）\\n\\n■ 持ち物・注意を伝える表現\\n　Please bring your umbrella.（傘をお持ちください）\\n　Don't forget to bring your ID card.（IDカードを忘れずにお持ちください）\\n　Students should arrive by eight thirty.（生徒は8時30分までに到着してください）\\n\\n⚠ 注意：be held は「held」で終わる受け身の形。うっかり The concert will hold ~. と能動態にしてしまうミスが多いが、コンサート自身が「開催する」のではなく「開催される」ので受け身が正しい。\",\"mangaId\":\"new20_e6_eigo_05_xm\"},{\"heading\":\"3. 天気予報の読み取り方\",\"body\":\"天気予報も入試のリスニング・読解でよく出る「未来の情報」の文章。決まった型を覚えてしまえば、聞き取り・読み取りのスピードが上がる。\\n\\n■ 天気予報の基本パターン\\n　It will be sunny tomorrow.（明日は晴れるでしょう）\\n　It will be cloudy in the morning and rainy in the afternoon.（午前は曇り、午後は雨でしょう）\\n　The high will be 25 degrees, and the low will be 15 degrees.（最高気温は25度、最低気温は15度でしょう）\\n\\n■ 天気を表す語\\n　sunny（晴れ）／cloudy（曇り）／rainy（雨）／snowy（雪）／windy（風が強い）／foggy（霧）\\n\\n■ モデル文の読み取り\\nGood morning. Here is today's weather. It will be cloudy in the morning, but it will clear up in the afternoon. The high will be 20 degrees. Don't forget your umbrella just in case.\\n（おはようございます。今日の天気です。午前中は曇りですが、午後は晴れるでしょう。最高気温は20度です。念のため傘をお忘れなく。）\\n→ 午前＝曇り、午後＝晴れ、最高気温＝20度、持ち物＝傘（念のため）という4つの情報が読み取れる。\\n\\n★ ポイント：clear up（晴れる・天気が回復する）のような、天気予報特有の表現もセットで覚えておくと、初見の予報文でも慌てずに読める。\"}]}",
"{\"id\":\"new20_e6_eigo_06\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"将来の夢①：What do you want to be? に答える\",\"description\":\"将来なりたい職業とその理由を、不定詞（want to be）を使って正確に伝える練習\",\"intro\":\"「将来の夢は何ですか」は英語の面接・作文で最も聞かれる質問の1つ。単語（doctor、teacherなど）だけを答えるのではなく、「なぜそうなりたいのか」まで文にできると、ぐっと説得力のある答えになる。ここでは職業名の言い方と、理由を添える型をセットで身につける。\",\"order\":7085,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"将来の夢をたずねる基本文：What do you want to be in the future?（あなたは将来何になりたいですか）\",\"答えの基本形：I want to be a ~.（私は〜になりたい）、職業名の前には必ず a／an をつける\",\"理由を加える形：I want to be a ~ because ~.（〜だから…になりたい）\",\"すでにしていることを加える：I am interested in ~. / I like ~ing. で興味を補足できる\",\"まだ決まっていない場合の答え方：I haven't decided yet, but I'm interested in ~.（まだ決めていないけど〜に興味がある）\"],\"sections\":[{\"heading\":\"1. 将来の夢をたずねる・答える基本の型\",\"body\":\"将来の夢についての会話は、決まった質問と答えのパターンさえ覚えれば、誰でも自分の言葉で話せるようになる。\\n\\n■ たずねる表現\\n　What do you want to be in the future?（あなたは将来何になりたいですか）\\n　What is your dream?（あなたの夢は何ですか）\\n　What do you want to do in the future?（将来何をしたいですか）※職業に限らず「したいこと」全般\\n\\n■ 答える基本の型\\n　I want to be a ＋ 職業名.\\n　例）I want to be a doctor.（私は医者になりたい）\\n　例）I want to be an English teacher.（私は英語の先生になりたい）\\n⚠ 注意：a と an の使い分けを忘れない。doctor は子音の音で始まるので a doctor、English teacher は母音の音（エ）で始まるので an English teacher。\\n\\n■ よく使う職業名\\n　doctor（医者）／nurse（看護師）／teacher（先生）／vet（獣医）／scientist（科学者）／\\n　pilot（パイロット）／astronaut（宇宙飛行士）／soccer player（サッカー選手）／\\n　cook（コック）／vlogger（動画配信者）／game creator（ゲームクリエイター）／\\n　pastry chef（パティシエ）／firefighter（消防士）／police officer（警察官）\\n\\n★ ポイント：I want to become a ~. も同じ意味で使えるが、中学入試レベルでは be を使う形が最も一般的。become を使う場合も、その後ろには名詞を置く点は同じ。\",\"figureId\":\"xf_new20_e6_eigo_06\"},{\"heading\":\"2. 理由を添えて、説得力のある答えにする\",\"mangaId\":\"new20_e6_eigo_06_manga\",\"body\":\"「I want to be a doctor.」だけで終わらせず、because を使って理由を1文加えると、聞き手に自分の考えが伝わる答えになる。\\n\\n■ 理由を加える型\\n　I want to be a ＋ 職業 ＋ because ＋ 主語＋動詞 ~.\\n　例）I want to be a vet because I love animals.（動物が大好きだから獣医になりたい）\\n　例）I want to be a doctor because I want to help sick people.（病気の人を助けたいから医者になりたい）\\n　例）I want to be a scientist because I am interested in space.（宇宙に興味があるから科学者になりたい）\\n\\n■ 理由をふくらませるつなぎ表現\\n　because のあとに1文だけでなく、具体的なエピソードを足すとさらによい答えになる。\\n　例）I want to be a teacher because my teacher was very kind to me. She always listened to my problems.\\n　（先生になりたいのは、私の先生がとても親切だったから。いつも私の悩みを聞いてくれた。）\\n\\n■ 興味・関心を補足する表現\\n　I am interested in ~.（〜に興味がある）\\n　　例）I am interested in science.（理科に興味がある）\\n　I like ~ing.（〜することが好き）\\n　　例）I like taking care of animals.（動物の世話をするのが好き）\\n　I am good at ~ing.（〜することが得意）\\n　　例）I am good at drawing pictures.（絵を描くのが得意）\\n\\n⚠ 注意：because のあとは「主語＋動詞」の完全な文が続く。becauseのあとに名詞だけを置く（because animal のような形）はミス。理由が名詞句のときは because of を使う（例：because of my grandmother）が、話し言葉ではbecauseで文を作る形のほうが自然でよく使われる。\"},{\"heading\":\"3. まだ決まっていないときの答え方・スピーチにまとめる\",\"body\":\"将来の夢がまだ決まっていない場合も、正直にそう答える表現を知っておくと安心だ。\\n\\n■ 決まっていない場合の答え方\\n　I haven't decided yet.（まだ決めていません）\\n　I don't know yet, but I'm interested in a lot of things.（まだわからないけど、いろいろなことに興味がある）\\n　I have some dreams, but I haven't chosen one yet.（夢はいくつかあるけど、まだ1つに絞っていない）\\n\\n■ 複数の夢を伝える表現\\n　I have two dreams. One is to be a doctor, and the other is to be a scientist.\\n　（夢が2つある。1つは医者になること、もう1つは科学者になることだ）\\n　※ to be a doctor のように不定詞の名詞的用法を使うと「〜になること」を表せる。\\n\\n■ 短いスピーチにまとめる\\n　My dream is to be a vet. I want to be a vet because I love animals very much. I have a dog, and I take care of him every day. In the future, I want to help sick animals and their owners. I will study hard to make my dream come true.\\n　（私の夢は獣医になることです。動物が大好きだから獣医になりたいです。私は犬を飼っていて、毎日世話をしています。将来は病気の動物とその飼い主を助けたいです。夢をかなえるために一生懸命勉強します。）\\n\\n★ ポイント：make my dream come true（夢をかなえる）は将来の夢スピーチの締めによく使われる決まり文句。「夢」を語る作文・面接では、この一言で結ぶと印象がまとまる。\"}]}",
"{\"id\":\"new20_e6_eigo_07\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"将来の夢②：夢について理由をそえてスピーチする\",\"description\":\"将来の夢のスピーチを「夢→理由→今していること→将来したいこと」の型で組み立てる\",\"intro\":\"将来の夢についての会話ができるようになったら、次は1分程度のまとまったスピーチに発展させよう。ここでは「今、夢のために何をしているか」「将来、夢を通して何をしたいか」まで踏み込んだ、より深いスピーチの型を練習する。\",\"order\":7086,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"スピーチの型：夢の発表→理由→今している努力・準備→将来したいこと→締めの一言\",\"今していることを伝えるには現在形、または現在進行形を使う（I study ~. / I am practicing ~.）\",\"将来やりたいことを伝えるには I want to ~. のほかに I hope to ~.（〜したいと願っている）も使える\",\"「〜な人になりたい」と人物像を伝えるときは I want to be someone who ~.（〜する人になりたい）が便利\",\"スピーチの結びには I will do my best. / I will never give up. のような決意の一言を添えると印象が強まる\"],\"sections\":[{\"heading\":\"1. スピーチの型：夢とその理由を深く語る\",\"body\":\"1分程度のスピーチにするには、「夢＋理由」の2文だけでなく、その夢を持ったきっかけまで語ると内容に深みが出る。\\n\\n■ きっかけを語る表現\\n　When I was ~ years old, ...（〜歳のとき…）\\n　　例）When I was seven years old, I visited a hospital with my grandmother. The doctors were very kind, and I decided to be a doctor too.\\n　　（7歳のとき、祖母と病院に行った。医師たちがとても優しくて、私も医者になろうと決めた。）\\n　I started to think about this dream when ...（…したときにこの夢を考え始めた）\\n\\n■ 夢の発表から理由までの流れ（モデル）\\nMy dream is to be an elementary school teacher. I decided this dream when I was in the fourth grade. My teacher always made classes fun, and I wanted to make other children smile like she did.\\n（私の夢は小学校の先生になることです。この夢を決めたのは4年生のときでした。私の先生はいつも授業を楽しくしてくれて、私も彼女のように他の子どもたちを笑顔にしたいと思いました。）\\n\\n★ ポイント：抽象的な理由（「かっこいいから」など）よりも、「いつ・何がきっかけで」その夢を持ったかという具体的なエピソードのほうが、聞き手の心に残るスピーチになる。\",\"figureId\":\"xf_new20_e6_eigo_07\"},{\"heading\":\"2. 今していること・準備を伝える\",\"body\":\"夢とその理由だけでなく、「今、その夢のために何をしているか」を加えると、スピーチに現実味と説得力が生まれる。\\n\\n■ 今していることを伝える表現\\n　現在形（習慣）：I study English every day.（毎日英語を勉強している）\\n　現在進行形（続けていること）：I am practicing the piano for my dream of becoming a musician.\\n\\n■ 具体例を交えたモデル文\\nTo make my dream come true, I read books about animals every week. I also help my mother take care of our dog. I want to learn more about animal medicine in the future.\\n（夢をかなえるために、私は毎週動物についての本を読んでいます。また、母が犬の世話をするのを手伝っています。将来はもっと動物の医学について学びたいです。）\\n\\n■ 将来やりたいことを広げる表現\\n　I hope to ~.（〜したいと願っている）※want to より少しやわらかい願望の表現\\n　　例）I hope to work at a zoo someday.（いつか動物園で働きたいと願っている）\\n　I want to be someone who ~.（〜する人になりたい）※人物像を伝える便利な形\\n　　例）I want to be someone who can help people in need.（困っている人を助けられる人になりたい）\\n\\n⚠ 注意：someone who のあとには「主語のはたらきをする文」が続く。someone who help ではなく someone who helps（または someone who can help）のように、動詞の形にも注意する（who が主語の役割をするので、動詞は who の後ろにそのまま続き、三人称単数なら s がつく）。\",\"mangaId\":\"new20_e6_eigo_07_xm\"},{\"heading\":\"3. スピーチをまとめる：完成モデルと締めの表現\",\"body\":\"これまで学んだ要素を1つのスピーチにまとめてみよう。\\n\\n■ 完成モデル（約1分程度）\\nHello, everyone. Today I want to talk about my dream. My dream is to be a vet. When I was eight years old, my dog got sick, and a kind vet helped him. Since then, I have wanted to help animals like that vet did. Now, I study science hard, and I read books about animals every week. In the future, I hope to work at an animal hospital and help many animals and their owners. I will study hard and never give up on my dream. Thank you for listening.\\n（みなさん、こんにちは。今日は私の夢についてお話しします。私の夢は獣医になることです。8歳のとき、私の犬が病気になり、優しい獣医さんが助けてくれました。それ以来、私もその獣医さんのように動物を助けたいと思っています。今、私は理科を一生懸命勉強し、毎週動物についての本を読んでいます。将来は動物病院で働き、多くの動物とその飼い主を助けたいです。一生懸命勉強し、夢を決してあきらめません。聞いてくれてありがとうございました。）\\n\\n■ スピーチを締める決意の表現\\n　I will do my best.（全力を尽くします）\\n　I will never give up on my dream.（夢を決してあきらめません）\\n　I believe I can make it.（きっとできると信じています）\\n\\n★ ポイント：スピーチの最後に「今の努力」と「決意」をセットで語ると、聞き手に本気度が伝わる。単なる憧れの職業名を並べるのではなく、「今している行動」があることが、良いスピーチと単なる作文の違いになる。\"}]}",
"{\"id\":\"new20_e6_eigo_08\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"趣味を語る：like ~ing・enjoy ~ing・be good at ~ingで自己紹介\",\"description\":\"動名詞（-ing）を使った趣味の表現をまとめて使いこなし、自己紹介文を組み立てる\",\"intro\":\"「趣味は何ですか」に答えるとき、My hobby is soccer. だけでは単調になりがちだ。like ~ing、enjoy ~ing、be good at ~ing など、動名詞を使った表現を使い分けられると、趣味についてもっと豊かに語れるようになる。ここでは表現を整理し、自己紹介の中で自然に組み合わせる練習をする。\",\"order\":7087,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"動名詞（動詞のing形）は「〜すること」という意味の名詞のはたらきをする\",\"like ~ing／enjoy ~ing／be interested in ~ing／be good at ~ing はすべて動詞のあとに-ing形を置く\",\"like は to不定詞も -ing も使えるが、enjoy は -ing だけ。be good at・be interested inのあとは必ず-ing（前置詞のあとだから）\",\"how often（頻度）や how long（期間）を添えると趣味の説明に具体性が出る\",\"自己紹介では「趣味→理由・きっかけ→頻度→得意なこと」の順で話すとまとまりが良い\"],\"sections\":[{\"heading\":\"1. 趣味を伝える基本表現を整理する\",\"body\":\"趣味を伝える表現はいくつもあるが、それぞれ後ろに続く形にルールがあるので整理して覚えよう。\\n\\n■ 「〜することが好き」\\n　I like ~ing. ／ I like to ~.　※どちらも使える（ほぼ同じ意味）\\n　　例）I like playing video games. / I like to play video games.（テレビゲームをするのが好き）\\n■ 「〜することを楽しむ」\\n　I enjoy ~ing.　※enjoy のあとは -ing のみ、to不定詞は使えない\\n　　例）I enjoy reading manga.（漫画を読むのを楽しんでいる）\\n■ 「〜することに興味がある」\\n　I am interested in ~ing.　※in は前置詞なので、あとは必ず -ing\\n　　例）I am interested in cooking.（料理に興味がある）\\n■ 「〜することが得意」\\n　I am good at ~ing.　※at も前置詞なので、あとは必ず -ing\\n　　例）I am good at drawing.（絵を描くのが得意）\\n\\n★ ポイント：前置詞（in・at・for など）のあとに動詞を置くときは、必ず -ing形になる。「前置詞のあとの動詞はing」というルールをここでしっかり定着させよう。\\n\\n⚠ 注意：enjoy to play や good at draw のように、-ing を忘れて原形やto不定詞を置いてしまうミスが非常に多い。動詞ごとに「後ろに何を置けるか」をセットで覚えることが大切。\",\"figureId\":\"xf_new20_e6_eigo_08\",\"mangaId\":\"new20_e6_eigo_08_xm\"},{\"heading\":\"2. 頻度・期間を加えて説明を具体的にする\",\"body\":\"「好き」というだけでなく、どのくらいの頻度で・どのくらいの期間続けているかを加えると、自己紹介がぐっと具体的になる。\\n\\n■ 頻度を表す語\\n　always（いつも）／usually（たいてい）／often（よく）／sometimes（ときどき）／once a week（週に1回）\\n　例）I usually play the piano every day.（たいてい毎日ピアノを弾く）\\n　例）I play basketball twice a week.（週に2回バスケットボールをする）\\n\\n■ 期間を表す表現\\n　I have played the piano for six years.（6年間ピアノを弾いている）※現在完了の継続用法\\n　I started playing soccer when I was five.（5歳のときサッカーを始めた）\\n\\n■ きっかけを加える表現\\n　My father taught me how to ~.（父が〜のやり方を教えてくれた）\\n　I started ~ing because ~.（〜だから…を始めた）\\n　　例）I started playing tennis because my sister plays it too.（姉もテニスをするので、テニスを始めた）\\n\\n★ ポイント：頻度・期間・きっかけの3つの要素のうち1〜2個を加えるだけで、単に「好きです」と言うより情報量が増え、聞き手の印象に残る自己紹介になる。\"},{\"heading\":\"3. 趣味の自己紹介文を完成させる\",\"body\":\"学んだ表現を組み合わせて、1つの自己紹介文にまとめてみよう。\\n\\n■ 完成モデル\\nMy hobby is playing soccer. I started playing soccer when I was six years old. I practice with my team twice a week. I enjoy playing with my friends, and I am good at passing the ball. I am also interested in watching soccer games on TV. My favorite player is from Japan. I want to be a good soccer player like him someday.\\n（私の趣味はサッカーをすることです。6歳のときにサッカーを始めました。週に2回チームで練習しています。友達と一緒にプレーするのを楽しんでいて、パスをするのが得意です。テレビでサッカーの試合を見ることにも興味があります。お気に入りの選手は日本出身です。いつか彼のような良いサッカー選手になりたいです。）\\n\\n■ 使われている表現の整理\\n　started ~ing（〜し始めた）／enjoy ~ing（〜を楽しむ）／be good at ~ing（〜が得意）／\\n　be interested in ~ing（〜に興味がある）／want to be ~（〜になりたい）\\n\\n■ 自分で書くときのステップ\\n①趣味を1文で紹介する（My hobby is ~.／I like ~ing.）\\n②始めたきっかけ・時期を加える\\n③頻度を加える（〜回／週、毎日、など）\\n④得意なこと・好きな部分を enjoy／be good at で加える\\n⑤最後に一言、将来の目標やあこがれを加えるとよりよい\\n\\n★ ポイント：趣味の紹介は職業（将来の夢）の話ともつながりやすい。「好きなこと→得意なこと→将来やりたいこと」という流れは、面接や作文の様々な質問に応用できる万能パターンだ。\"}]}",
"{\"id\":\"new20_e6_eigo_09\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"友達や家族を比べる：比較表現で人を紹介するスピーチ\",\"description\":\"比較級・最上級を使い、身近な人やものを比べながら自己紹介・紹介文を組み立てる練習\",\"intro\":\"比較級・最上級の作り方（-er/-est、more/most）はすでに習っていても、実際に「誰かと誰かを比べて紹介する」ようなまとまった文章にするのは別のスキルだ。ここでは家族やペット、友達を題材に、比較表現を自然な紹介文の中で使う練習をする。\",\"order\":7088,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"2人（2つ）を比べるときは比較級＋than、3人以上の中で一番のときは the＋最上級\",\"「私と比べてどうか」を語るときは than I am／than me の形を使う（会話ではthan meが自然）\",\"同じくらいであることを伝えるには as ~ as を使う（否定文 not as ~ as は「〜ほどではない」）\",\"人を紹介するときは見た目・性格・特技をそれぞれ比較表現で説明すると具体性が増す\",\"比較級を強めるときは much／a lot／far を比較級の前に置く（very は比較級の前には使えない）\"],\"sections\":[{\"heading\":\"1. 家族やペットを比べて紹介する\",\"body\":\"比較表現は「AとBを比べる」だけでなく、「自分の家族やペットを紹介する」場面でとても自然に使われる。\\n\\n■ 2人（2つ）を比べる基本文\\n　My brother is taller than me.（兄は私より背が高い）\\n　My dog is bigger than my sister's dog.（うちの犬は妹の犬より大きい）\\n　This bag is more expensive than that one.（このかばんはあのかばんより高い）\\n\\n■ 3人以上の中で一番を伝える\\n　My father is the tallest in my family.（父は家族の中で一番背が高い）\\n　This is the most interesting book in my class.（これは私のクラスで一番おもしろい本だ）\\n\\n■ 同じくらいであることを伝える\\n　I am as tall as my mother.（私は母と同じくらいの背の高さだ）\\n　My cat is not as active as my dog.（うちの猫は犬ほど活発ではない）\\n\\n★ ポイント：家族紹介の作文では、単に「兄は背が高いです」だけでなく「私より背が高いです」「家族の中で一番背が高いです」のように比較の対象をはっきりさせると、文章に具体性が出る。\\n\\n⚠ 注意：than のあとに代名詞を置くとき、書き言葉では than I am（Iは主格）が文法的に正しいとされるが、会話では than me が一般的に使われる。中学入試では than me の形でも問題ないことが多いが、学校の文法問題では than I（am）の形も覚えておこう。\",\"figureId\":\"xf_new20_e6_eigo_09\"},{\"heading\":\"2. 性格・特技を比較表現で紹介する\",\"body\":\"見た目だけでなく、性格や特技も比較表現で紹介すると、より深みのある人物紹介文になる。\\n\\n■ 性格を比べる\\n　My sister is kinder than me.（妹は私より優しい）\\n　He is the funniest person in our class.（彼はクラスで一番おもしろい人だ）\\n　　※ funny → funniest（yをiに変えてest）のようなつづり変化も忘れずに確認する\\n\\n■ 得意なこと・能力を比べる\\n　My friend can run faster than me.（友達は私より速く走れる）\\n　She sings the best in our chorus club.（彼女は合唱部で一番歌がうまい）\\n　　※ good/well の最上級は best（不規則変化）\\n\\n■ 比較級を強める表現\\n　much・a lot・far を比較級の直前に置くと「ずっと〜」という意味を加えられる。\\n　　例）My brother is much taller than me.（兄は私よりずっと背が高い）\\n　　例）This question is far more difficult than that one.（この問題はあれよりずっと難しい）\\n⚠ 注意：very は比較級を直接強めることができない（× very taller）。「とても」を比較級で言いたいときは much／a lot／far を使う。\"},{\"heading\":\"3. 人物紹介文にまとめる\",\"body\":\"学んだ比較表現を使って、家族やペットの紹介文を完成させてみよう。\\n\\n■ 完成モデル：兄の紹介\\nI want to introduce my brother, Ken. He is three years older than me. He is taller than me, and he is the tallest in our family. He is very kind, and I think he is kinder than anyone else I know. He can run much faster than me, and he is the fastest runner in his class. I respect him a lot.\\n（私の兄、健を紹介します。彼は私より3歳年上です。彼は私より背が高く、家族の中で一番背が高いです。とても優しくて、私が知る誰よりも優しいと思います。彼は私よりずっと速く走ることができ、クラスで一番足が速いです。私は彼をとても尊敬しています。）\\n\\n■ 完成モデル：ペットの紹介\\nMy dog, Momo, is smaller than my friend's dog, but she is much smarter. She is the smartest dog I have ever seen. She is as friendly as a cat, and everyone in my family loves her the most.\\n（私の犬モモは友達の犬より小さいですが、ずっと賢いです。私が今まで見た中で一番賢い犬です。猫と同じくらい人懐っこくて、家族みんなが一番愛しています。）\\n\\n★ ポイント：than anyone else（他の誰よりも）、I have ever seen（今まで見た中で）は最上級を強めるときに便利な決まり文句。使いこなせると、比較表現の作文が一段レベルアップする。\"},{\"heading\":\"なぜ比較の対象をはっきりさせ、なぜ very で比較級を強められないのか\",\"mangaId\":\"new20_e6_eigo_09_manga\",\"body\":\"「兄は背が高い」だけでは、どれくらい高いのかが読み手に伝わりません。「私より高い」「家族の中で一番高い」と**比べる相手**を示してはじめて、兄の背の高さが具体的に分かります。比較級は二つを比べる形（taller than）、最上級は三つ以上の中で一番を言う形（the tallest in）、as 〜 as は同じくらいを言う形で、比べる相手や範囲（than me・in my family・of the three）をそろえて書きます。\\n\\nvery が比較級を強められないのは、very が「程度が高い」ことを表す語で、比較級が表す**二つの差**には付けられないからです。差を強めるには「差が大きい」と言う much・a lot・far を使います。than のあとに代名詞を置くとき、書き言葉では than I（am）、会話では than me が一般的で、入試では than me でも問題ないことが多いですが、文法問題では than I の形も覚えておきます。\\n\\n■ 確かめのしかた\\n①二つ→**比較級＋than**、三つ以上→**the＋最上級＋in／of**、同じくらい→**as 〜 as**。比べる相手・範囲が書かれているか。\\n②つづり：funny→funniest（y を i に）、good／well→best（不規則）。\\n③強めるときは much／a lot／far＋比較級（much taller）。× very taller。\\n④最上級を強める決まり文句：than anyone else（他の誰よりも）、I have ever seen（今まで見た中で）。見た目・性格・特技をそれぞれ比較で言うと紹介文に具体性が出る。\\n\\n★ ここがポイント：比較表現は**比べる相手や範囲をそろえて書く**ことで具体性が出る。very は程度の語なので**差の形（比較級）には much／a lot／far**。\"}]}",
"{\"id\":\"new20_e6_eigo_10\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"買い物の会話を組み立てる：店員とお客のロールプレイ\",\"description\":\"値段のたずね方・サイズや色の相談・会計まで、買い物の会話をひとまとまりで演じられるようにする\",\"intro\":\"買い物の場面では May I help you? や How much is it? のような1文ずつの表現はすでに知っていても、実際の会話は「声をかける→探す→相談する→会計する」という流れで進む。ここでは店員役とお客役、両方のせりふを練習し、買い物の会話をまるごと演じられるようにする。\",\"order\":7089,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"店員が声をかける決まり文句：May I help you? / Are you looking for something?\",\"欲しいものを伝える表現：I'm looking for ~. / Do you have ~? / I'd like ~, please.\",\"サイズ・色を相談する表現：Do you have a bigger one? / Can I try this on?（試着してもいいですか）\",\"値段をたずねる・答える：How much is it? — It's ~ yen. 複数のときは How much are they?\",\"会計を済ませる表現：I'll take this. / Here you are. / Here's your change.\"],\"sections\":[{\"heading\":\"1. 店に入って探しているものを伝える\",\"body\":\"買い物の会話は、店員の呼びかけから始まる。ここでの受け答えを自然にできると、その後の会話全体がスムーズになる。\\n\\n■ 店員からの声かけ\\n　May I help you?（いらっしゃいませ／お手伝いしましょうか）\\n　Are you looking for something?（何かお探しですか）\\n\\n■ お客の答え方\\n　I'm looking for a birthday present for my mother.（母への誕生日プレゼントを探しています）\\n　Do you have any T-shirts?（Tシャツはありますか）\\n　I'd like a cap, please.（帽子がほしいのですが）\\n　I'm just looking, thank you.（見ているだけです、ありがとう）※すぐに買う気がないとき\\n\\n■ 店員が案内する表現\\n　This way, please.（こちらへどうぞ）\\n　We have a lot of colors.（色々な色がございます）\\n　This one is very popular.（これはとても人気です）\\n\\n★ ポイント：I'd like ~, please. は I want ~. よりもていねいな表現で、お店や目上の人との会話でよく使われる。買い物の場面では I want を使うより自然に聞こえる。\",\"figureId\":\"xf_new20_e6_eigo_10\"},{\"heading\":\"2. サイズ・色・値段を相談する\",\"body\":\"商品を見つけたら、サイズや色、値段について相談する会話に進む。\\n\\n■ サイズについて\\n　Do you have a bigger one?（もっと大きいのはありますか）\\n　Do you have a smaller size?（もっと小さいサイズはありますか）\\n　Can I try this on?（これを試着してもいいですか）— Sure, the fitting room is over there.（もちろんです、試着室はあちらです）\\n\\n■ 色について\\n　Do you have this in blue?（これの青色はありますか）\\n　What colors do you have?（何色がありますか）\\n\\n■ 値段をたずねる・答える\\n　How much is it?（それはいくらですか）— It's 1,500 yen.\\n　How much are these shoes?（この靴はいくらですか）※複数のものはare/theyを使う — They're 3,000 yen.\\n　That's a little expensive.（それは少し高いですね）\\n　Do you have a cheaper one?（もっと安いのはありますか）\\n\\n⚠ 注意：値段をたずねるとき、単数のものには How much is it?、複数のもの（shoes、glassesなど）には How much are they? と、be動詞を使い分ける。ものの数に合わせるのを忘れないこと。\",\"mangaId\":\"new20_e6_eigo_10_xm\"},{\"heading\":\"3. 会計まで演じる：完成した会話\",\"body\":\"探す・相談する、の次は会計の会話。買い物のロールプレイを最後まで通してみよう。\\n\\n■ 完成モデル会話\\nClerk: May I help you?\\nCustomer: Yes, I'm looking for a cap for my brother.\\nClerk: How about this one? It's very popular.\\nCustomer: It looks nice. How much is it?\\nClerk: It's 2,000 yen.\\nCustomer: Do you have it in black?\\nClerk: Yes, we do. Here you are.\\nCustomer: Great, I'll take this one.\\nClerk: OK. That will be 2,000 yen.\\nCustomer: Here you are.\\nClerk: Thank you. Here's your change and your receipt.\\n（店員：いらっしゃいませ。　客：はい、弟の帽子を探しています。　店員：こちらはいかがですか？　とても人気です。　客：素敵ですね。いくらですか？　店員：2,000円です。　客：黒はありますか？　店員：はい、あります。どうぞ。　客：いいですね、これにします。　店員：かしこまりました。2,000円になります。　客：どうぞ。　店員：ありがとうございます。お釣りとレシートです。）\\n\\n■ 会計でよく使う表現\\n　I'll take this one.（これにします）\\n　That will be ~ yen.（〜円になります）\\n　Here you are.（はい、どうぞ）※ものを渡すときの決まり文句\\n　Here's your change.（お釣りです）／Keep the change.（お釣りはとっておいてください）\\n\\n★ ポイント：ペアで店員役・客役に分かれて声に出す練習が最も効果的。せりふを覚えるのではなく、「聞かれたら何を答えるか」の流れを体で覚えることが、実際のリスニング・会話問題での得点力につながる。\"}]}",
"{\"id\":\"new20_e6_eigo_11\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"道案内をスムーズに：地図を見ながら道順を説明する\",\"description\":\"曲がる・進む・目印を使った道案内の表現を、実際の地図問題形式で練習する\",\"intro\":\"道案内の表現（turn left、go straightなど）は単語としては覚えていても、実際に地図を見ながら順番に説明するのは意外と難しい。ここでは「目印→動作→距離・時間」の順に説明する型を身につけ、入試の地図付き問題にも対応できるようにする。\",\"order\":7090,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"道案内の基本動作：go straight（まっすぐ進む）／turn left/right（左右に曲がる）／cross the street（通りを渡る）\",\"目印を伝える前置詞：on your right/left（右手・左手に）／next to（〜の隣に）／across from（〜の向かいに）\",\"道のりをたずねる表現：How can I get to ~? / Could you tell me the way to ~?\",\"距離・時間を伝える表現：It's about five minutes on foot. / It's about 200 meters ahead.\",\"道案内の最後には You can't miss it.（すぐわかりますよ）で締めるのが自然\"],\"sections\":[{\"heading\":\"1. 道をたずねる・案内を始める\",\"body\":\"道案内の会話は、まず道をたずねる表現から始まる。ていねいさによって使う表現が変わる。\\n\\n■ 道をたずねる表現\\n　Excuse me. How can I get to the station?（すみません、駅へはどう行けばいいですか）\\n　Could you tell me the way to the library?（図書館への道を教えていただけますか）\\n　Is there a post office near here?（この近くに郵便局はありますか）\\n\\n■ 案内を始めるときの一言\\n　Sure. Let me show you.（もちろんです。案内しますね）\\n　OK, go straight and turn left at the second corner.（では、まっすぐ進んで2つ目の角を左に曲がってください）\\n\\n■ 案内できないときの返事\\n　Sorry, I'm not from around here.（すみません、この辺りの者ではないので）\\n　I'm not sure, but you can ask that police officer.（わかりませんが、あの警察官に聞いてみてください）\\n\\n★ ポイント：Could you tell me the way to ~? は How can I get to ~? よりもややていねいな表現。試験の会話文ではどちらも頻出なので、両方の形を使い分けられるようにしておく。\",\"figureId\":\"xf_new20_e6_eigo_11\"},{\"heading\":\"2. 動作と目印を組み合わせて説明する\",\"body\":\"道案内で大切なのは、「動作」だけでなく「目印」をセットで伝えること。目印がないと、聞いた人はどこで曲がればいいかわからない。\\n\\n■ 基本の動作表現\\n　Go straight.（まっすぐ進む）／Go straight for two blocks.（2区画まっすぐ進む）\\n　Turn left/right at the corner.（角を左／右に曲がる）\\n　Turn left at the second traffic light.（2つ目の信号を左に曲がる）\\n　Cross the street/bridge.（通り／橋を渡る）\\n\\n■ 目印を伝える前置詞句\\n　on your right/left（あなたの右手／左手に）\\n　　例）You will see the library on your right.（右手に図書館が見えます）\\n　next to ~（〜の隣に）\\n　　例）The bank is next to the bakery.（銀行はパン屋の隣にあります）\\n　across from ~（〜の向かいに）\\n　　例）The park is across from the school.（公園は学校の向かいにあります）\\n　between A and B（AとBの間に）\\n　　例）It's between the flower shop and the bookstore.（花屋と本屋の間にあります）\\n\\n■ 動作＋目印をつなげた例文\\n　Go straight for three blocks, and turn right at the bookstore. The museum is on your left, next to the park.\\n　（3区画まっすぐ進んで、本屋のところを右に曲がってください。美術館は左手、公園の隣にあります。）\\n\\n⚠ 注意：turn left at the corner のように、曲がる場所（角・信号・店の前など）を at のあとに置くのを忘れると、聞き手はどこで曲がればよいかわからなくなる。動作だけで終わらせず、必ず目印とセットで伝える。\",\"mangaId\":\"new20_e6_eigo_11_xm\"},{\"heading\":\"3. 距離・時間を添えて、道案内を完成させる\",\"body\":\"最後に「どのくらいの距離・時間で着くか」を加えると、より実用的で親切な道案内になる。地図問題ではこの情報が設問のヒントになることも多い。\\n\\n■ 距離・時間を伝える表現\\n　It's about five minutes on foot.（歩いて約5分です）\\n　It's about 200 meters ahead.（この先約200メートルです）\\n　It takes about ten minutes by bus.（バスで約10分かかります）\\n\\n■ 道案内を締める決まり文句\\n　You can't miss it.（見逃すことはありません＝すぐわかりますよ）\\n　It's right in front of you.（すぐ目の前にあります）\\n\\n■ 完成モデル会話（地図問題形式）\\nA: Excuse me. Could you tell me the way to the city library?\\nB: Sure. Go straight for two blocks and turn left at the flower shop. Go straight again, and you will see the library on your right, across from the park. It's about seven minutes on foot.\\nA: Turn left at the flower shop, and it's across from the park. Got it. Thank you!\\nB: You're welcome. You can't miss it.\\n（A：すみません。市立図書館への道を教えていただけますか？　B：もちろんです。2区画まっすぐ進み、花屋のところを左に曲がってください。またまっすぐ進むと、右手に図書館が見えます、公園の向かいです。歩いて約7分です。　A：花屋で左に曲がって、公園の向かいですね。わかりました。ありがとうございます！　B：どういたしまして。すぐわかりますよ。）\\n\\n★ ポイント：入試の道案内問題では、聞いた（読んだ）道順を実際に地図上でなぞりながら確認する練習が効果的。「動作→目印→距離」の3点セットを意識して聞く（読む）習慣をつけよう。\"}]}",
"{\"id\":\"new20_e6_eigo_12\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"レストランでの会話を組み立てる：入店から会計まで\",\"description\":\"席の希望・注文・会計まで、レストランでの一連の流れを会話としてまとめて練習する\",\"intro\":\"買い物の会話と同じように、レストランの会話にも「入店→注文→食事中→会計」という決まった流れがある。ここではその流れに沿って使う表現を整理し、実際の対話文として最後まで通して練習する。入試の会話文読解・リスニングでも頻出の場面だ。\",\"order\":7091,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"入店時の会話：How many people? / A table for two, please. で人数と席を伝える\",\"注文する表現：I'd like ~, please. / Can I have ~? / What would you like?（店員がたずねる）\",\"飲み物・追加をたずねる：What would you like to drink? / Anything else?\",\"会計を頼む表現：Check, please. / Can I have the bill, please?\",\"すすめる・答える定番：What do you recommend? / I recommend the ~.\"],\"sections\":[{\"heading\":\"1. 入店して席に案内されるまで\",\"body\":\"レストランに入ってから席に着くまでの会話は、人数を伝えるところから始まる。\\n\\n■ 入店時の会話\\n　Waiter: Good evening. How many people?（何名様ですか）\\n　Customer: A table for two, please.（2人用の席をお願いします）\\n　Waiter: This way, please.（こちらへどうぞ）\\n\\n■ 席の希望を伝える表現\\n　Can we have a table by the window?（窓際の席にできますか）\\n　We'd like a table for four, please.（4人用の席をお願いします）\\n\\n■ メニューを渡されたときの応答\\n　Waiter: Here is the menu. Take your time.（メニューです。ごゆっくりどうぞ）\\n　Customer: Thank you.\\n\\n★ ポイント：How many people? に対しては人数だけを答えるのではなく、A table for ~, please. の形で「〜人用の席を」と答えるのが自然な受け答え。数字だけ（Two.）でも通じるが、会話文としては文で答える練習をしておこう。\",\"figureId\":\"xf_new20_e6_eigo_12\"},{\"heading\":\"2. 注文する・すすめてもらう\",\"body\":\"席に着いたら、いよいよ注文の会話。丁寧な言い方と、店員とのやり取りのパターンを覚えよう。\\n\\n■ 注文する基本表現\\n　I'd like the hamburger steak, please.（ハンバーグステーキをお願いします）\\n　Can I have a salad, too?（サラダもいただけますか）\\n　What would you like?（何になさいますか）※店員が客にたずねる決まり文句\\n\\n■ 飲み物・追加をたずねられたときの応答\\n　Waiter: What would you like to drink?（お飲み物は何になさいますか）\\n　Customer: I'll have orange juice, please.\\n　Waiter: Anything else?（他に何かございますか）\\n　Customer: No, that's all, thank you.（いいえ、以上です）\\n\\n■ おすすめをたずねる・答える\\n　What do you recommend?（おすすめは何ですか）\\n　I recommend the beef curry. It's very popular here.（ビーフカレーがおすすめです。ここでとても人気です）\\n\\n⚠ 注意：I'd like ~. は I want ~. よりもていねいで、レストランでの注文にふさわしい表現。I want a hamburger. も間違いではないが、接客の会話文では I'd like ~. のほうが自然な選択として問われやすい。\",\"mangaId\":\"new20_e6_eigo_12_xm\"},{\"heading\":\"3. 会計まで：完成した会話\",\"body\":\"食事が終わったら会計の場面。最後まで通して1つの会話にしてみよう。\\n\\n■ 完成モデル会話\\nWaiter: How many people?\\nCustomer: A table for two, please.\\nWaiter: This way, please. Here is the menu.\\nCustomer: Thank you. What do you recommend?\\nWaiter: I recommend the beef curry. It's our most popular dish.\\nCustomer: OK, I'll have that. And can I have a salad, too?\\nWaiter: Sure. What would you like to drink?\\nCustomer: I'll have iced tea, please.\\n（食事が終わったあと）\\nCustomer: Excuse me, can I have the bill, please?\\nWaiter: Of course. That will be 1,800 yen.\\nCustomer: Here you are.\\nWaiter: Thank you very much. Have a nice day.\\n（店員：何名様ですか？　客：2人用の席をお願いします。　店員：こちらへどうぞ。メニューです。　客：ありがとうございます。おすすめは何ですか？　店員：ビーフカレーがおすすめです。当店で一番人気のメニューです。　客：ではそれにします。サラダもいただけますか？　店員：かしこまりました。お飲み物は？　客：アイスティーをお願いします。　（食後）　客：すみません、お会計をお願いします。　店員：かしこまりました。1,800円になります。　客：どうぞ。　店員：ありがとうございました。良い一日を。）\\n\\n■ 会計でよく使う表現\\n　Check, please. / Can I have the bill, please?（お会計をお願いします）\\n　That will be ~ yen.（〜円になります）\\n　Have a nice day.（良い一日を）\\n\\n★ ポイント：買い物の会話（新20単元第10課）とレストランの会話は、「入店→注文・相談→会計」というよく似た流れを持つ。1つの場面をしっかり覚えると、似た場面にも応用できることに気づこう。\"}]}",
"{\"id\":\"new20_e6_eigo_13\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"空港・旅行での会話：チェックインから入国審査までの基本表現\",\"description\":\"空港でよく使う表現を場面ごとに整理し、旅行の会話文読解・リスニングに備える\",\"intro\":\"海外帰国生入試や上位校のリスニングでは、空港や飛行機内の会話が題材になることがある。日常会話とは異なる専門的な言い回しも多いが、場面ごとに整理すれば決して難しくない。ここではチェックインから入国審査まで、旅行の会話表現を場面順にまとめる。\",\"order\":7092,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"チェックインの会話：May I see your passport and ticket? / Window or aisle seat?\",\"手荷物についての表現：How many bags are you checking in? / Is this within the weight limit?\",\"機内での表現：Would you like something to drink? / Please fasten your seatbelt.\",\"入国審査の会話：What's the purpose of your visit? / How long will you stay?\",\"旅行英語は「聞かれることが決まっている」場面が多く、答え方のパターンを覚えると得点しやすい\"],\"sections\":[{\"heading\":\"1. 空港のチェックインカウンターでの会話\",\"body\":\"空港での会話は、チェックインカウンターでのやり取りから始まる。決まった質問と答え方のパターンをセットで覚えよう。\\n\\n■ チェックインの基本会話\\n　Staff: May I see your passport and ticket, please?（パスポートとチケットを見せていただけますか）\\n　Passenger: Here you are.（どうぞ）\\n　Staff: Window or aisle seat?（窓側と通路側、どちらがよろしいですか）\\n　Passenger: Window seat, please.（窓側でお願いします）\\n\\n■ 手荷物についての会話\\n　Staff: How many bags are you checking in?（お預けになる荷物はいくつですか）\\n　Passenger: Just one, please.（1つだけです）\\n　Staff: Please put your bag on the scale.（かばんをはかりに乗せてください）\\n　Staff: I'm sorry, this is over the weight limit.（申し訳ございません、これは重量制限を超えています）\\n\\n■ 搭乗券を受け取るときの表現\\n　Here is your boarding pass. Your flight leaves from Gate 25 at 10:30.\\n　（こちらが搭乗券です。あなたの便は10時30分にゲート25から出発します）\\n\\n★ ポイント：check in（チェックインする）は「預ける」という意味の動詞句としても使われる（check in a bag＝かばんを預ける）。名詞としてのcheck-in（ハイフンあり）と混同しないよう注意。\",\"figureId\":\"xf_new20_e6_eigo_13\"},{\"heading\":\"2. 機内での会話\",\"body\":\"飛行機に乗ってからも、決まった会話パターンがいくつもある。\\n\\n■ 座席を探すときの会話\\n　Excuse me, where is seat 24A?（すみません、24Aの座席はどこですか）\\n　It's over there, next to the window.（あちらです、窓の隣です）\\n\\n■ 客室乗務員とのやり取り\\n　Flight Attendant: Would you like something to drink?（お飲み物はいかがですか）\\n　Passenger: Orange juice, please.\\n　Flight Attendant: Please fasten your seatbelt.（シートベルトをお締めください）\\n　Flight Attendant: We will be landing soon.（まもなく着陸いたします）\\n\\n■ 機内アナウンスでよく使う表現\\n　Please stay in your seat.（お席にお座りください）\\n　We are now beginning our descent.（ただいま降下を始めております）\\n　Thank you for flying with us.（ご搭乗ありがとうございました）\\n\\n⚠ 注意：Would you like ~? は「〜はいかがですか」とすすめるときの決まり文句。Do you want ~? よりもていねいで、接客の場面ではこちらがよく使われる。\"},{\"heading\":\"3. 入国審査での会話\",\"body\":\"旅行の最後の関門が入国審査。決まった質問への答え方を覚えておけば、リスニング問題でも落ち着いて対応できる。\\n\\n■ 入国審査の基本会話\\n　Officer: May I see your passport, please?（パスポートを見せていただけますか）\\n　Traveler: Here you are.\\n　Officer: What's the purpose of your visit?（訪問の目的は何ですか）\\n　Traveler: Sightseeing.（観光です）／I'm here on business.（仕事で来ています）\\n　Officer: How long will you stay?（どのくらい滞在しますか）\\n　Traveler: For one week.（1週間です）\\n　Officer: Where will you be staying?（どこに滞在しますか）\\n　Traveler: At a hotel in the city.（市内のホテルです）\\n\\n■ 完成モデル会話\\nOfficer: May I see your passport, please?\\nTraveler: Sure, here you are.\\nOfficer: What's the purpose of your visit?\\nTraveler: Sightseeing. I want to visit some museums and parks.\\nOfficer: How long will you stay in this country?\\nTraveler: For five days.\\nOfficer: Enjoy your stay.\\n（審査官：パスポートを見せていただけますか。　旅行者：はい、どうぞ。　審査官：訪問の目的は何ですか。　旅行者：観光です。美術館や公園を訪れたいと思っています。　審査官：この国にはどのくらい滞在しますか。　旅行者：5日間です。　審査官：良い滞在を。）\\n\\n★ ポイント：入国審査では What's the purpose of your visit?（目的）と How long will you stay?（期間）の2つがほぼ必ず聞かれる。この2つへの答え方さえ準備しておけば、リスニング問題でも慌てずに対応できる。\"},{\"heading\":\"なぜ旅行英語は場面ごとに覚えると得点しやすいのか\",\"mangaId\":\"new20_e6_eigo_13_manga\",\"body\":\"空港や機内の会話は、**聞かれることがほぼ決まっています**。チェックインでは「パスポートとチケット」「窓側か通路側か」「預ける荷物はいくつか」、機内では「飲み物はいかがですか」「シートベルトを締めて」、入国審査では「訪問の目的」「滞在期間」「滞在先」。決まった質問には決まった答え方があるので、場面順にセットで覚えれば、リスニングで知らない語が出ても、どの場面かが分かれば内容を推測できます。\\n\\nWould you like 〜? が Do you want 〜? よりていねいなのは、would が「もしよろしければ」というやわらかさを足す語だからで、接客の場面ではこちらが使われます。check in は「チェックインする・（荷物を）預ける」の動詞句、check-in（ハイフンあり）は名詞で、形で区別します。\\n\\n■ 確かめのしかた\\n①**チェックイン**：May I see your passport and ticket?→Here you are.／Window or aisle seat?／How many bags are you checking in?→Just one.\\n②**機内**：Would you like something to drink?→〇〇, please.／Please fasten your seatbelt.／We will be landing soon.\\n③**入国審査**：What's the purpose of your visit?→Sightseeing.／I'm here on business.、How long will you stay?→For one week.、Where will you be staying?→At a hotel.\\n④場面が分かれば、質問の中身を先に予想して聞く。Would you like 〜? は「いかがですか」（すすめる）。\\n\\n★ ここがポイント：旅行英語は**聞かれることが場面ごとに決まっている**ので、場面順に質問と答えをセットで覚える。入国審査は**目的と期間**の二つがほぼ必ず聞かれる。\"}]}",
"{\"id\":\"new20_e6_eigo_14\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"簡単な長文読解①：友達からの手紙を読む\",\"description\":\"手紙・メール形式の英文を題材に、書き手の気持ちや依頼を正確に読み取る練習\",\"intro\":\"入試の長文には、物語文や説明文だけでなく「友達からの手紙」のような、より個人的な文章が出ることもある。手紙特有の形式（呼びかけ・結び）を知っておくと、内容がぐっと読みやすくなる。ここでは手紙形式の英文を題材に、書き手の気持ちや依頼を読み取る練習をする。\",\"order\":7093,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"手紙の形式：Dear ~,（〜へ）で始まり、Your friend, / Love, などの結びと差出人の名前で終わる\",\"手紙では「近況報告」→「本題（伝えたいこと・お願い）」→「結びの言葉」という流れが多い\",\"お願いをする表現：Can you ~? / I was wondering if you could ~.（〜していただけないかと思っています）\",\"感謝や誘いの表現：Thank you for ~ing. / I hope you can come.（来てくれるとうれしいです）\",\"手紙の読解では「誰が・誰に・何を伝えたいか」を最初に確認してから読み進めると内容を追いやすい\"],\"sections\":[{\"heading\":\"1. 手紙の形式を知る\",\"body\":\"手紙・メール形式の英文には決まった型がある。この型を知っておくと、初めて見る手紙でもどこに何が書いてあるか予測しながら読める。\\n\\n■ 手紙の基本構成\\n①呼びかけ：Dear ＋ 相手の名前,（〜さんへ）\\n②本文：近況報告→本題→結びの言葉\\n③結びの表現：Your friend, / Best wishes, / Love, など\\n④差出人の名前\\n\\n■ よくある近況報告の表現\\n　How are you doing?（元気にしていますか）\\n　I hope you are doing well.（元気に過ごしていることを願っています）\\n　It's been a while since we last talked.（最後に話してからしばらく経ちますね）\\n\\n■ モデル文（冒頭部分）\\nDear Emily,\\nHow are you doing? It's been three months since I moved to Japan, and I miss you a lot. I hope you are doing well in Canada.\\n（エミリーへ、元気にしていますか。日本に引っ越してから3ヶ月経ちますが、あなたのことがとても恋しいです。カナダで元気にしていることを願っています。）\\n\\n★ ポイント：手紙の冒頭は「あいさつ＋近況」であることが多く、そこには本題（一番伝えたいこと）は書かれていない。設問を解くときは、本題が書かれている中盤〜終盤を重点的に読むと効率がよい。\",\"figureId\":\"xf_new20_e6_eigo_14\"},{\"heading\":\"2. 本題を読み取る：お願い・誘い・報告\",\"body\":\"手紙の中心となる「本題」には、いくつかの典型的なパターンがある。これを知っておくと、設問で問われやすい部分を素早く見つけられる。\\n\\n■ お願いをするパターン\\n　Can you send me some photos of your school?（学校の写真を送ってくれますか）\\n　I was wondering if you could visit me next summer.（来年の夏、私を訪ねてきてくれないかと思っています）\\n　　※ I was wondering if you could ~. は Can you ~? よりもていねいなお願いの表現。\\n\\n■ 誘うパターン\\n　Would you like to come to my birthday party?（私の誕生日パーティーに来ませんか）\\n　I hope you can come.（来てくれるとうれしいです）\\n\\n■ 報告・お知らせのパターン\\n　I just wanted to let you know that I got a new dog.（新しい犬を飼ったことを知らせたくて）\\n　Guess what? I made a new friend at school!（聞いて！学校で新しい友達ができたの！）\\n\\n■ モデル文（本題部分）\\nBy the way, I'm having a birthday party next Saturday. I was wondering if you could come. My other friends from Canada will be there, too. I really hope you can join us.\\n（ところで、来週の土曜日に誕生日パーティーをします。来てくれないかと思っています。カナダの他の友達も来ます。ぜひ一緒に来てほしいです。）\\n\\n★ ポイント：By the way（ところで）や Actually（実は）は、あいさつから本題に切り替わる合図の言葉。これらの語が出てきたら「ここから本題が始まる」と意識して読もう。\",\"mangaId\":\"new20_e6_eigo_14_xm\"},{\"heading\":\"3. 手紙全体を読んで設問に答える\",\"body\":\"ここまで学んだ知識を使って、手紙全体を読んでみよう。\\n\\n■ 完成モデル\\nDear Emily,\\nHow are you doing? It's been three months since I moved to Japan, and I miss you a lot. I hope you are doing well in Canada.\\nBy the way, I'm having a birthday party next Saturday. I was wondering if you could come. I know it's far, but I really hope you can join us, even online. My mother said we can have a video call during the party.\\nI also started learning Japanese calligraphy. It's difficult, but I enjoy it. I'll send you a photo of my work soon.\\nPlease write back and tell me about your school life.\\nYour friend,\\nYuki\\n（エミリーへ、元気にしていますか。日本に引っ越してから3ヶ月が経ち、あなたのことがとても恋しいです。カナダで元気に過ごしていることを願っています。ところで、来週の土曜日に誕生日パーティーをします。来てもらえないかと思っています。遠いのはわかっているけれど、オンラインでもいいのでぜひ一緒に参加してほしいです。パーティー中にビデオ通話ができると母が言っていました。また、私は書道を習い始めました。難しいけど楽しんでいます。作品の写真を近いうちに送ります。返事を書いて、あなたの学校生活について教えてください。あなたの友達、ユキより）\\n\\n■ 読解のチェックポイント\\n①差出人・宛先：Yuki が Emily に宛てた手紙\\n②本題：誕生日パーティーへの誘い（オンライン参加でもよいと伝えている）\\n③追加情報：書道を始めたこと\\n④結びの依頼：返事を書いて学校生活を教えてほしい\\n\\n★ ポイント：手紙の読解問題では「本題は何か」「相手に何をしてほしいと頼んでいるか」の2点が最も問われやすい。あいさつ文に惑わされず、By the way以降を重点的に確認する習慣をつけよう。\"}]}",
"{\"id\":\"new20_e6_eigo_15\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"簡単な長文読解②：動物・自然についての説明文を読む\",\"description\":\"生き物や自然現象を紹介する説明文を題材に、事実を正確につかむ読解の練習\",\"intro\":\"入試の説明文には、動物の生態や自然現象を紹介する文章がよく登場する。物語文のように気持ちを想像する必要はないが、その分「数字・特徴・比較」といった事実情報を正確に読み取る力が求められる。ここではその読み方を練習する。\",\"order\":7094,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"説明文は「話題の紹介→特徴の説明（複数）→まとめ・結論」の順に書かれることが多い\",\"数字・比較の情報（大きさ・速さ・数）は設問で問われやすいので下線や印をつけながら読む\",\"because／so（理由・結果）、but／however（対比）でつながる文は特に注意して読む\",\"They／It／These などの代名詞が何を指しているかを直前の文から確認する習慣をつける\",\"専門的な語がわからなくても、前後の文脈や具体例から意味を推測して読み進める\"],\"sections\":[{\"heading\":\"1. 説明文の組み立てとキーワードの見つけ方\",\"body\":\"動物・自然についての説明文は、多くの場合「話題の紹介→いくつかの特徴の説明→まとめ」という構成をとる。段落ごとの役割を意識すると、内容を整理しながら読める。\\n\\n■ よくある構成\\n①話題の紹介：この文章が何について書かれているか\\n②特徴①：見た目・大きさなど\\n③特徴②：行動・習性など\\n④特徴③：他の生き物との違いなど\\n⑤まとめ：全体の要点\\n\\n■ モデル文（冒頭）\\nHave you ever heard of the axolotl? It is a kind of salamander that lives in lakes in Mexico. Unlike other salamanders, axolotls usually keep their gills even after they become adults.\\n（ウーパールーパーについて聞いたことがありますか。それはメキシコの湖に生息するサンショウウオの一種です。他のサンショウウオと違い、ウーパールーパーは大人になってもえらを保持することが多いです。）\\n\\n■ 読み方のポイント\\nHave you ever heard of ~?（〜を聞いたことがありますか）という問いかけで始まる文章は、そのあとに「その生き物についての説明」が続くサインである。冒頭の問いかけを見たら、「これから何について説明されるか」を意識して読み進めよう。\\n\\n★ ポイント：Unlike ~（〜と違って）は対比を表す表現。「他の生き物と何が違うのか」という、その生き物の一番の特徴が続くことが多いので、見逃さず読む。\",\"figureId\":\"xf_new20_e6_eigo_15\"},{\"heading\":\"2. 数字・比較・理由をつかむ読み方\",\"body\":\"説明文の設問では、数字や比較、理由を表す部分がよく問われる。これらの情報が出てきたら、注意して読み、印をつける習慣をつけよう。\\n\\n■ 数字に関する表現\\n　Axolotls can grow up to 30 centimeters long.（ウーパールーパーは体長30センチまで成長することがある）\\n　They can live for more than 10 years.（10年をこえて生きることができる）\\n　→ 「up to（最大で）」「more than（〜より多い。ちょうどは入らない）」のような数の範囲を表す語に注意する。\\n\\n■ 比較を表す表現\\n　Axolotls are more unusual than other salamanders because they don't go through a full change into adults.\\n　（ウーパールーパーは、完全には大人の姿に変化しないため、他のサンショウウオよりも珍しいです）\\n　→ than（〜より）が出てきたら、何と何を比べているのかを明確にする。\\n\\n■ 理由・結果を表す表現\\n　Because axolotls keep their gills, they can breathe underwater their whole lives.\\n　（ウーパールーパーはえらを保持しているため、一生水中で呼吸することができます）\\n　→ Because（理由）、so（結果）でつながれた2つの文の関係を整理する。\\n\\n⚠ 注意：「30 centimeters」のような数字は読み飛ばしがちだが、設問で「体長は何センチ以上か」「何年生きるか」のようにピンポイントで問われることが多い。数字が出てきたら丸で囲むなど、目立たせて読む習慣が有効。\",\"mangaId\":\"new20_e6_eigo_15_xm\"},{\"heading\":\"3. 代名詞の指示内容と全体の読解\",\"body\":\"説明文では同じ生き物を何度も指すのに They や It のような代名詞が多く使われる。何を指しているかを取り違えると、文章全体の理解がずれてしまう。\\n\\n■ 代名詞の確認方法\\n代名詞が出てきたら、直前の文（多くは直前の1〜2文）から「単数か複数か」「人か物か」をヒントに指すものを探す。\\n　例）Axolotls live in only a few lakes in Mexico. They are now an endangered species.\\n　→ They は直前の Axolotls（複数）を指す。\\n\\n■ 完成モデル（全体）\\nHave you ever heard of the axolotl? It is a kind of salamander that lives in lakes in Mexico. Unlike other salamanders, axolotls usually keep their gills even after they become adults. Because of this, they can breathe underwater their whole lives. Axolotls can grow up to 30 centimeters long, and they can live for more than 10 years. However, axolotls now live in only a few lakes, and they are an endangered species. Many people are working hard to protect them.\\n（ウーパールーパーについて聞いたことがありますか。それはメキシコの湖に生息するサンショウウオの一種です。他のサンショウウオと違い、ウーパールーパーは大人になってもえらを保持することが多いです。このため、一生水中で呼吸することができます。ウーパールーパーは体長30センチまで成長することがあり、10年をこえて生きることができます。しかし、ウーパールーパーは今ではわずかな湖にしか生息しておらず、絶滅危惧種となっています。多くの人がウーパールーパーを守るために努力しています。）\\n\\n■ この文章から読み取れる要点\\n　①ウーパールーパーの特徴：えらを保持したまま大人になる\\n　②大きさ・寿命：最大30センチ、10年をこえて生きる\\n　③現状：however（しかし）以降で「絶滅危惧種」という転換が起きている\\n\\n★ ポイント：However（しかし）のあとには、それまでの説明と対照的な内容（多くは問題点や課題）が続く。この転換に気づけると、文章の要旨（何を最も伝えたいか）をつかみやすくなる。\"}]}",
"{\"id\":\"new20_e6_eigo_16\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"簡単な長文読解③：伝記文で人物の人生を読み取る\",\"description\":\"有名人の生涯を紹介する伝記文を題材に、出来事の順序と人物の考えを読み取る練習\",\"intro\":\"伝記文（人物の人生を紹介する文章）は、物語文と説明文の両方の性質を持つ、入試でよく出る長文の形式だ。時間の流れに沿って出来事が語られる一方で、その人物が何を成し遂げ、何を考えていたかという「事実」もつかむ必要がある。ここではその両方を読み取る練習をする。\",\"order\":7095,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"伝記文は「生まれ・幼少期→きっかけとなる出来事→努力・挑戦→成し遂げたこと」の順で書かれることが多い\",\"年号や年齢（When she was ~／In 19XX）は出来事の順序をつかむ手がかりになる\",\"「困難→乗り越えた方法」の流れは伝記文で必ずと言っていいほど出てくる重要な部分\",\"その人物の考え方や信念は、直接話法（\\\"~,\\\" she said.）や間接的な描写から読み取る\",\"文末の「今どう評価されているか」の部分に、文章全体のまとめ・筆者の伝えたいことが表れやすい\"],\"sections\":[{\"heading\":\"1. 伝記文の時間の流れをつかむ\",\"body\":\"伝記文は基本的に時間の流れに沿って書かれる。年号や年齢を表す語に印をつけながら読むと、出来事の順序を見失わずに読み進められる。\\n\\n■ 時間を表す表現\\n　When she was ten years old, ~（彼女が10歳のとき〜）\\n　In 1990, ~（1990年に〜）\\n　After graduating from ~, ~（〜を卒業したあと〜）\\n　Later in her life, ~（人生の後半で〜）\\n\\n■ モデル文（冒頭〜きっかけ）\\nWangari Maathai was born in Kenya in 1940. When she was a child, she loved nature and spent a lot of time in the forest near her home. Later, she studied biology in the United States and became the first woman in East Africa to earn a doctorate degree.\\n（ワンガリ・マータイは1940年にケニアで生まれました。子どものころ、彼女は自然が大好きで、家の近くの森で多くの時間を過ごしました。その後、アメリカで生物学を学び、東アフリカ出身の女性として初めて博士号を取得しました。）\\n\\n★ ポイント：年号や年齢を表す語句を見つけたら、それを軸に「この文章のどの時期の話か」を意識して読む。伝記文の設問では「〜のとき、何をしたか」という時系列の並べ替えや対応がよく問われる。\",\"figureId\":\"xf_new20_e6_eigo_16\"},{\"heading\":\"2. 困難と、それを乗り越えた方法を読み取る\",\"body\":\"伝記文でほぼ必ず描かれるのが「その人物が直面した困難」と「それをどう乗り越えたか」という部分。ここが文章の最も重要な山場になることが多い。\\n\\n■ 困難を表す表現\\n　It was not easy for her to ~.（彼女にとって〜するのは簡単ではなかった）\\n　Many people did not believe in her idea.（多くの人が彼女の考えを信じなかった）\\n　She faced a lot of difficulties.（彼女は多くの困難に直面した）\\n\\n■ 乗り越え方・行動を表す表現\\n　Despite these difficulties, she never gave up.（これらの困難にもかかわらず、彼女は決してあきらめなかった）\\n　She kept planting trees with local women.（彼女は地元の女性たちと木を植え続けた）\\n\\n■ モデル文（困難と行動）\\nWhen Wangari started planting trees to stop the forests from disappearing, many people did not understand why a woman would do such work. It was not easy for her, but she never gave up. She kept working with local women, and together they planted more than 30 million trees.\\n（ワンガリが森林の消失を止めるために木を植え始めたとき、多くの人はなぜ女性がそのような仕事をするのか理解しませんでした。彼女にとって簡単なことではありませんでしたが、決してあきらめませんでした。彼女は地元の女性たちと共に働き続け、共に3000万本以上の木を植えました。）\\n\\n★ ポイント：despite（〜にもかかわらず）、but（しかし）のあとに続く「あきらめなかった・続けた」という行動の部分に、その人物の一番伝えたい強さ・考え方が表れる。設問で「筆者が伝えたいことは何か」を問われたら、まずこの部分を確認しよう。\",\"mangaId\":\"new20_e6_eigo_16_xm\"},{\"heading\":\"3. 人物の考え方と文章全体のまとめを読み取る\",\"body\":\"伝記文の終わりには、その人物の考え方（信念）や、今どのように評価されているかがまとめられることが多い。ここに文章全体の要旨が集約されている。\\n\\n■ 考え方・信念を表す表現\\n　She believed that small actions could change the world.（彼女は小さな行動が世界を変えられると信じていた）\\n　\\\"You can start where you are,\\\" she said.（「あなたは今いる場所から始められる」と彼女は言った）\\n　　※直接話法（\\\"~\\\"と誰かが言った）は、その人物の考えがそのまま表れる重要な部分。\\n\\n■ 今の評価を表す表現\\n　Today, she is remembered as a great environmental leader.（今日、彼女は偉大な環境保護のリーダーとして記憶されている）\\n　Her work continues to inspire people around the world.（彼女の活動は今も世界中の人々を勇気づけている）\\n\\n■ 完成モデル（結び部分）\\nWangari Maathai believed that protecting nature and helping people were connected. In 2004, she became the first African woman to win the Nobel Peace Prize. Today, she is remembered as a great leader who showed that one person's small actions can change the world.\\n（ワンガリ・マータイは、自然を守ることと人々を助けることはつながっていると信じていました。2004年、彼女はアフリカ出身の女性として初めてノーベル平和賞を受賞しました。今日、彼女は一人の小さな行動が世界を変えられることを示した偉大なリーダーとして記憶されています。）\\n\\n■ 読解の手順まとめ\\n①時間表現に印をつけて出来事の順序をつかむ\\n②困難と、それを乗り越えた行動を確認する\\n③信念（believed that ~／said \\\"~\\\"）と、今の評価を確認する\\n④③をつなげると、文章全体の要旨が見えてくる\\n\\n★ ポイント：伝記文の要旨・タイトル選択問題では、途中の出来事の細かさよりも「その人物が何を信じ、何を成し遂げたか」という結びの部分が最大のヒントになる。\"}]}",
"{\"id\":\"new20_e6_eigo_17\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音の変化①：単語がつながって聞こえる音（リンキング）\",\"description\":\"リスニングで聞き取りにくい「音のつながり」の仕組みを理解し、正しく聞き取る耳を作る\",\"intro\":\"「単語は1つずつ知っているのに、リスニングになると聞き取れない」——その原因の多くは、実際の英語では単語同士の音がつながって発音される「リンキング（linking）」にある。ここではその仕組みを理解し、代表的なパターンを声に出して練習する。\",\"order\":7096,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"リンキングとは、前の単語の最後の音と、次の単語の最初の音がつながって聞こえる現象\",\"子音で終わる語＋母音で始まる語は特につながりやすい（例：an apple「アン・アップル」→「アナプル」）\",\"同じ子音、または似た子音が続くときは音が1つに重なって聞こえる（例：good day）\",\"t や d のあとに you が続くと、音が変化して「チュ」「ジュ」のように聞こえることがある（want you→ワンチュ）\",\"リンキングは「知らないと聞き取れない」だけで、書くとき・読むときのつづりは変わらない。音の変化だと理解して聞くことが大切\"],\"sections\":[{\"heading\":\"1. リンキングとは何か：子音＋母音のつながり\",\"body\":\"英語を話すとき、単語と単語の間に日本語のような「間（ま）」はほとんど置かれない。特に「子音で終わる単語」のあとに「母音で始まる単語」が続くと、2つの音がつながって、まるで1つの単語のように聞こえる。これがリンキング（linking）だ。\\n\\n■ 代表的な例\\n　an apple → 「アン・アップル」ではなく「ア・ナ・プル（アナプル）」のように聞こえる\\n　（an の n と apple の a がつながる）\\n　check it out → 「チェック・イット・アウト」ではなく「チェッキラウ（チェッキタウ）」のように聞こえる\\n　turn off → 「ターン・オフ」ではなく「ターノフ」のように聞こえる\\n　come on → 「カム・オン」ではなく「カモン」のように聞こえる（日常会話でもおなじみの音）\\n\\n■ なぜこの変化が起きるのか\\n英語は「息の流れを止めずに単語をつなげて発音する」言語だからだ。子音で終わったあと、すぐに母音が続くと、口の形が自然に次の音へ移り、2つの音が1つのかたまりに聞こえる。\\n\\n★ ポイント：come on（カモン）のように、日本語でもカタカナ語として定着している表現を思い出すと、リンキングは特別な現象ではなく、日常的に耳にしているものだと気づける。\\n\\n⚠ 注意：リンキングはあくまで「発音（音）」の変化であり、つづり（スペル）は変わらない。an apple は聞こえ方が「アナプル」でも、書くときは an apple のまま。リスニングと単語のつづりを混同しないようにしよう。\",\"figureId\":\"xf_new20_e6_eigo_17\",\"mangaId\":\"new20_e6_eigo_17_xm\"},{\"heading\":\"2. 同じ音が続くとき・t/dとyouがつながるとき\",\"body\":\"子音＋母音のつながり以外にも、覚えておくと聞き取りに役立つパターンがある。\\n\\n■ 同じ（似た）子音が続くとき：1つの音にまとまる\\n　good day → グッド・デイではなく、dの音が1つにまとまり「グッデイ」のように聞こえる\\n　big game → 「ビッグ・ゲーム」ではなく「ビゲーム」のように聞こえる\\nこのパターンでは、前の単語の最後の子音がほとんど発音されず、次の単語の最初の子音と1つに重なる。\\n\\n■ t/d のあとに you が続くとき：チュ・ジュに変化する\\n　want you → ワント・ユーではなく「ワンチュ」のように聞こえる\\n　did you → ディド・ユーではなく「ディジュ」のように聞こえる\\n　　例）What did you eat?（何を食べたの？）は「ワッ・ディジュ・イート」のように聞こえる\\nこのパターンは Did you ~? や What do you ~? のような疑問文で非常によく起こるため、リスニング問題の会話文で頻出。\\n\\n■ 練習フレーズ（声に出してみよう）\\n　Did you see it?（ディジュ・シー・イット）\\n　What do you want?（ワッダユー・ウォント）\\n　Nice to meet you.（ナイス・トゥ・ミーチュー）\\n\\n★ ポイント：Did you ~? や What do you ~? は会話でとても頻繁に使われる形。リンキングされた音（ディジュ、ワッダユー）を「そういう決まった音のかたまりだ」として耳と口で覚えてしまうのが最も効果的な対策。\"},{\"heading\":\"3. リンキングを聞き取る・自分でも発音する練習\",\"body\":\"知識として知るだけでなく、実際に声に出して練習することで、リスニングでも聞き取れるようになる。\\n\\n■ 練習：文章の中でリンキングを見つける\\n次の文を読んで、どこがつながって聞こえるか考えてみよう。\\n　I want to be an English teacher.\\n　→ want to は「ワナ」、an English は子音のnと母音のEがつながり「アニングリッシュ」のように聞こえやすい。\\n\\n■ よく出るリンキングのパターンまとめ\\n　want to → ワナ／going to → ゴナ／got to → ガラ（ガッタ）\\n　これらは特によく使われるため「発音が崩れた形」としてそのまま覚えてしまうと聞き取りやすい。\\n　例）I'm going to study.（アイム・ゴナ・スタディ）\\n\\n■ リスニング問題での活用法\\n①放送文を聞く前に、設問・選択肢にある単語を確認しておく\\n②Did you ~?、What do you ~?、want to、going to のような頻出パターンが聞こえたら、それを合図に次に続く内容に集中する\\n③1語1語を完璧に聞き取ろうとせず、「かたまり」で意味をつかむ\\n\\n★ ポイント：リンキングは「くずれた発音」ではなく、英語という言語の自然なリズムそのもの。単語を1つずつ区切って覚えるだけでなく、フレーズごと・かたまりごとに声に出す練習を重ねることが、リスニング力向上の一番の近道になる。\"}]}",
"{\"id\":\"new20_e6_eigo_18\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"音の変化②：弱く読まれる語と、音が変わる・消える変化\",\"description\":\"前置詞・冠詞などの弱形、音の脱落・同化の仕組みを理解し、聞き取りの精度を上げる\",\"intro\":\"リンキング（単元17）に続いて、ここでは「弱く読まれる語」と「音が消える・変わる変化」を学ぶ。英語には、文の中で意味の軽い単語（a、to、andなど）を弱く・短く発音する習慣があり、これを知らないと、知っている単語のはずなのに聞き取れないという現象が起きる。\",\"order\":7097,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"英語では意味の中心となる語（動詞・名詞など）は強く、a・the・to・and などの機能語は弱く短く読まれる\",\"弱形の代表例：to→タ、for→フォ、and→アン(ド)、a→ア（弱い母音）\",\"語尾の子音（特にt）は、次に子音が続くときにほとんど発音されない「脱落」が起こることがある\",\"2つの音が混ざり合って別の音に聞こえる「同化」もリンキングと合わせて理解しておくと聞き取りやすい\",\"弱形・脱落・同化は「正しい発音」であり、崩れているのではなく英語らしいリズムの一部だと理解する\"],\"sections\":[{\"heading\":\"1. 強く読む語・弱く読む語\",\"body\":\"英語の文には「強く読む語」と「弱く読む語」があり、そのリズムが英語らしい響きを作っている。\\n\\n■ 強く読まれる語（内容語）\\n意味の中心となる語：名詞・動詞・形容詞・副詞・疑問詞など\\n　例）I want to go to the park.（park や go のような意味の中心になる語が強く読まれる）\\n\\n■ 弱く読まれる語（機能語）\\n文法的な役割を持つ語：冠詞（a/the）、前置詞（to/for/of）、接続詞（and/but）、be動詞・助動詞など\\nこれらは意味の軽さゆえに、短く・弱く（あいまいな母音で）発音される。\\n　to → 「トゥー」ではなく軽く「タ」\\n　for → 「フォー」ではなく軽く「フォ」\\n　and → 「アンド」ではなく軽く「アン」または「ン」\\n　a → 「エイ」ではなく軽く「ア（あいまいな音）」\\n\\n■ モデル文で確認する\\n　I want to go to the park.\\n　→ 強く：want・go・park　弱く：to・to・the\\n　　実際の発音は「アイ・ワナ・ゴウ・タ・ザ・パーク」のように、to が2回とも弱く短くなる。\\n\\n★ ポイント：内容語（意味の中心）を強く、機能語（文法的な役目）を弱く読むというリズムは、英語のほぼすべての文に共通する。この強弱のリズムを意識して聞く・読むことが、自然な英語耳への第一歩になる。\",\"figureId\":\"xf_new20_e6_eigo_18\",\"mangaId\":\"new20_e6_eigo_18_xm\"},{\"heading\":\"2. 音が消える変化（脱落）と、音が変わる変化（同化）\",\"body\":\"弱形に加えて、英語には「音が消える」「音が変わる」という2つの変化がある。\\n\\n■ 脱落（音が消える）\\n語の最後の子音（特にtやd）のあとに、別の子音が続くと、その音がほとんど発音されなくなることがある。\\n　例）next day → nextのtがほとんど聞こえず「ネクス・デイ」のように聞こえる\\n　例）best friend → best のtが消えて「ベス・フレンド」のように聞こえる\\n\\n■ 同化（音が変わる）\\n隣り合う2つの音が影響しあって、別の音に変化して聞こえることがある。\\n　例）don't you → 「ドント・ユー」ではなく「ドンチュ」のように聞こえる（tとyouが混ざりチュになる）\\n　例）miss you → 「ミス・ユー」ではなく「ミシュ」のように聞こえる\\n\\n■ 脱落・同化が起こりやすい組み合わせのまとめ\\n　t/d＋子音 → tやdの音が消えやすい（next day、good morning など）\\n　t/d＋you → チュ・ジュに変化しやすい（don't you、would you など）\\n\\n⚠ 注意：これらの変化はネイティブスピーカーが「正しく」話している自然な発音であり、聞き取れないのは学習者側の耳がまだ慣れていないだけ。「知らない単語が出てきた」と焦らず、「これは音の変化かもしれない」と考え直す習慣をつけよう。\"},{\"heading\":\"3. 音の変化を意識した聞き取り練習\",\"body\":\"弱形・脱落・同化の知識を使って、実際の会話文を聞き取る練習をしてみよう。\\n\\n■ 練習文と聞こえ方の変化\\n　Would you like something to drink?\\n　→ Would you は「ウジュ」、to drink の to は弱く「タ・ドリンク」のように聞こえる。\\n　　全体では「ウジュ・ライク・サムシン・タ・ドリンク」のように聞こえる。\\n\\n　What would you like to eat?\\n　→ would you が「ウジュ」、like to が「ライク・タ」と弱形になり、全体として速く滑らかに聞こえる。\\n\\n■ リスニング本番での対策\\n①内容語（意味の中心の語）を聞き取ることに集中し、機能語（弱く読まれる語）は文法知識で補う\\n②not、don't のような否定を示す短い語は特に注意して聞く（脱落・同化で聞き逃しやすいが意味が正反対になるため）\\n③知っているはずの単語が聞き取れないときは「弱形・脱落・同化のどれかかもしれない」と考え、文脈から埋める\\n\\n■ 家庭でできる練習方法\\n①短い会話文をゆっくり音声で聞く→②同じ文をふつうの速さで聞く→③自分でも同じリズムをまねて声に出す、という3ステップを繰り返すと、耳と口の両方から音の変化に慣れていく。\\n\\n★ ポイント：音の変化はルールを覚えるだけでは身につかない。実際に声に出し、耳で確認する反復練習を積み重ねることで、初めて「自然に聞き取れる」段階に到達する。単元17（リンキング）とあわせて、日常的に音読・シャドーイングを取り入れよう。\"}]}",
"{\"id\":\"new20_e6_eigo_19\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"英検5級レベル総合演習：模擬問題で実力チェック\",\"description\":\"英検5級相当の筆記・会話文問題を実際に解きながら、頻出パターンと解法をまとめて確認する\",\"intro\":\"英検5級は中学初級程度のレベルで、小学6年生でも十分に合格を狙える。ここでは単語・文法の暗記ではなく、実際の試験形式に近い問題を解きながら「よく出るパターン」と「時間内に解くコツ」を整理する。総仕上げとして取り組もう。\",\"order\":7098,\"studyPeriod\":\"小6前半\",\"keyPoints\":[\"英検5級の筆記は「短文の語句・文法選択」「会話文の空所補充」「語句の並べかえ」の3パターンが中心\",\"語句選択問題は空所の前後（時制・単数複数・冠詞など）から手がかりを探す\",\"会話文の空所補充は、直前・直後の発言とのつながり（質問と答えが対応しているか）で選ぶ\",\"並べかえ問題は、まず動詞を探して文の骨組み（主語＋動詞）を決めてから残りを組み立てる\",\"リスニングは「絵を見て答える」「会話の最後の受け答えを選ぶ」形式が中心で、先に選択肢に目を通すのが鉄則\"],\"sections\":[{\"heading\":\"1. 短文の語句・文法選択問題を解く\",\"body\":\"英検5級の筆記1では、1つの英文の空所に合う語句を4択から選ぶ問題が出る。空所の前後にある「手がかり」を見つける練習をしよう。\\n\\n■ 例題①\\n　My sister ( ) to school every day.\\n　1. go　2. goes　3. going　4. went\\n　【何を聞かれているか】空所に入る、動詞の正しい形を選ぶ問題。\\n　【手がかり1】every day（毎日）があるので、「いつもしていること」を表す現在の文。過去形の went や、ing形だけの going は合わない。\\n　【手がかり2】主語は My sister（私の姉）で、I と you 以外の1人の人、つまり三人称単数。現在の文で主語が三人称単数のときは、動詞に -s や -es をつけるきまりがあるから、go だけでは誤り。\\n　【手順】go に -es をつけると goes になる（go は o で終わるので -es）。\\n　→ 答えは 2. goes。\\n　【確かめ】声に出して My sister goes to school every day. と読み、不自然でないかを確かめる。別の主語で I go to school every day. なら go でよいと比べると、-s が必要な理由がはっきりする。\\n　【よくあるまちがい】主語が My sister（1人）だと気づかず、複数の主語のつもりで go を選ぶこと。\\n\\n■ 例題②\\n　A: What time do you get up?　B: I get up ( ) seven.\\n　1. in　2. on　3. at　4. to\\n　【何を聞かれているか】時刻 seven（7時）の前に入る前置詞を選ぶ問題。\\n　【手がかり】What time ~?（何時に〜？）とたずねられ、「7時に起きる」と答える文。「〜時に」と時刻を言うときの前置詞を選ぶ。\\n　【なぜ at か】前置詞は、後ろに来る語の種類によって決まっている。時刻（seven、7:30 など）の前は at。曜日（Monday）の前は on、月や季節の前は in を使うので、ここでは in や on は合わない。to は「〜へ」と方向を表す語で、時刻の前には使わない。\\n　→ 答えは 3. at。（at seven で「7時に」という意味になる。）\\n　【確かめ】I get up at seven. と声に出して読み、「7時に起きる」という意味で自然に聞こえるかを確かめる。\\n　【よくあるまちがい】in the morning（朝に）のイメージから in を選ぶこと。in は「朝・午後・夜」「月」「年」の前で使い、時刻そのものの前は at です。\\n\\n■ 例題③\\n　There ( ) two cats under the table.\\n　1. is　2. are　3. was　4. am\\n　【何を聞かれているか】There ( ) ... の空所に入る be動詞を選ぶ問題。\\n　【手がかり】There is / There are の文では、be動詞は「あとに続く名詞」の数に合わせる。ここでは two cats（2ひきのねこ）で複数。\\n　【なぜ are か】is は1つのもの、are は2つ以上のものに使うから。was は過去形なので、時を表す語がないこの文では合わない。am は I のときだけ使う。\\n　→ 答えは 2. are。\\n　【確かめ】There is a cat under the table. なら a cat（1ぴき）なので is。two cats に変えると are になる、と並べて比べると、数と be動詞の対応がわかる。\\n　【よくあるまちがい】There が先に来ているので、There に合わせて is を選んでしまうこと。数を決めるのは、あとの名詞です。\\n\\n★ ポイント：語句選択問題は、空所の前後にある「時を表す語（every day、now）」「主語の数（三人称単数か複数か）」「決まった組み合わせ（at＋時刻）」の3つを手がかりに探すと、確実に絞り込める。\",\"figureId\":\"xf_new20_e6_eigo_19\"},{\"heading\":\"2. 会話文の空所補充問題を解く\",\"body\":\"筆記2では、2人の短い会話の空所に入る最も自然な発言を選ぶ問題が出る。直前・直後のやり取りとのつながりを確認することが最大のコツ。\\n\\n■ 例題①\\n　A: Would you like some tea?\\n　B: ( )\\n　1. Yes, please.　2. It's Monday.　3. See you.　4. Nice to meet you.\\n　【何を聞かれているか】Bの発言として、会話がいちばん自然につながるものを選ぶ問題。\\n　【手がかり】A の Would you like some tea? は「お茶はいかがですか」というすすめる言い方（申し出）。申し出には「はい、いただきます」か「いいえ、けっこうです」で答えるのが自然。\\n　【選択肢を1つずつ当てはめる】\\n　　1. Yes, please.（はい、お願いします）→ 申し出を受けている。自然。\\n　　2. It's Monday.（月曜日です）→ 曜日をたずねられたときの答え。お茶の話とつながらない。\\n　　3. See you.（またね）→ 別れるときのあいさつ。\\n　　4. Nice to meet you.（はじめまして）→ 会ったときのあいさつ。\\n　　だから、答えは 1. Yes, please.\\n　【確かめ】A と B を続けて読み、「お茶はいかが？」「はい、お願いします」と会話が成り立つことを確かめる。\\n　【よくあるまちがい】文法が正しい文なら何でも正解だと思い、It's Monday. のような文を選んでしまうこと。質問の種類と答えの種類が合っているかを見る。\\n\\n■ 例題②\\n　A: How was your weekend?\\n　B: ( ) I went to the zoo with my family.\\n　1. It was great.　2. It's Saturday.　3. I'm not free.　4. See you then.\\n　→ How was ~?（〜はどうでしたか）と感想をたずねられているので、感想を述べる It was great. が対応する。\\n\\n■ 会話文問題の解き方の手順\\n①空所の前の発言が「質問」か「提案」か「あいさつ」かを見極める\\n②質問なら、その質問に対応する答え（What→内容、How→様子・方法、Would you like→Yes/No）を選ぶ\\n③選択肢を全て空所に当てはめて読み、会話として自然につながるものを選ぶ\\n\\n⚠ 注意：文法的に正しい文でも、会話の流れに合わなければ不正解になる。「文法が正しいか」ではなく「会話としてつながるか」を基準に選ぶことを忘れずに。\",\"mangaId\":\"new20_e6_eigo_19_xm\"},{\"heading\":\"3. 並べかえ問題とリスニングのコツ\",\"body\":\"筆記3の並べかえ問題と、リスニングパートのコツをまとめて確認しよう。\\n\\n■ 並べかえ問題の解き方\\n①与えられた語の中から動詞を探す\\n②動詞をもとに文の骨組み（主語＋動詞、疑問文なら助動詞＋主語＋動詞）を決める\\n③残りの語（目的語・修飾語）を意味が通るように当てはめる\\n\\n■ 例題\\n　( is / your / this / bag / ) ?\\n　【何を聞かれているか】4つの語を並べかえて、意味の通る疑問文をつくる問題。\\n　【手順1】動詞を探す。与えられた語の中で動詞は is（be動詞）だけ。\\n　【手順2】骨組みを決める。最後に ? があるので疑問文。be動詞の疑問文は「Be動詞＋主語＋〜?」の順なので、is を文の最初に置く。主語は this。ここまでで Is this ~? になる。\\n　【手順3】残りを当てはめる。残りは your と bag。your は名詞 bag の前に置いて「あなたのかばん」になるから、your bag の順。\\n　→ 並べると Is this your bag? （これはあなたのかばんですか）。\\n　【確かめ】最初の語を大文字にして、声に出して読み、意味が通ることを確かめる。This is your bag. の文の is と this を入れかえた形になっている点も確認する。\\n　【よくあるまちがい】this を最初に置いて This is your bag? としてしまうこと。疑問文では、be動詞が主語の前に出ます。\\n\\n■ リスニング問題の種類と対策\\n　第1部：会話を聞き、最後の発言への応答として自然なものを選ぶ（イラストがヒントになる） → 会話文問題（本課2つ目）と同じ考え方で解く\\n　第2部：会話を聞き、その内容についての質問に答える → 数字・場所・人物名に集中して聞く\\n　第3部：英文を聞き、内容に合うイラストを選ぶ → 絵の中の人物・物・動作をあらかじめ確認しておく\\n\\n■ 試験全体を通じてのアドバイス\\n・時間配分：筆記は語句選択→会話文→並べかえの順に解くと、得意なところから確実に得点できる\\n・わからない問題は飛ばして、最後にまとめて考える\\n・リスニングは放送前に必ず選択肢に目を通し、聞くポイントを絞っておく\\n\\n★ ポイント：英検5級は基礎的な文法・語彙が中心。特別な難問はほとんど出ないため、これまで学んだ単元（be動詞・一般動詞・疑問詞・道案内・買い物など）の総復習をすれば、十分合格圏内に入る。\"}]}",
"{\"id\":\"new20_e6_eigo_20\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"英検4級レベル総合演習：模擬問題で実力チェック\",\"description\":\"英検4級相当の文法・読解・会話文問題を実際に解き、5級との違いと得点のコツを整理する\",\"intro\":\"英検4級は中学中級程度のレベルで、5級より扱う文法の範囲が広がり、短い長文問題も加わる。ここでは5級との違いを意識しながら、4級で問われるポイント（過去形・未来表現・比較・不定詞・動名詞・接続詞など）を模擬問題形式で確認する。\",\"order\":7099,\"studyPeriod\":\"小6後半・直前\",\"keyPoints\":[\"英検4級では不定詞・動名詞・比較・接続詞など、5級より広い文法範囲が問われる（現在完了・受動態・関係代名詞は3級から）\",\"長文問題（Eメール・掲示文形式）が加わり、複数の設問に答える形式に慣れておく必要がある\",\"語句整序問題は5級より語数が増え、不定詞・比較などを含む複雑な文型が出題される\",\"内容一致問題は本文の言い換え表現（同じ意味を別の語で言い換えた選択肢）に注意する\",\"リスニングは、5級より会話や英文が長くなり、問われる情報量も増える\"],\"sections\":[{\"heading\":\"1. 4級で新しく問われる文法を確認する\",\"body\":\"英検4級では、5級で学んだ基礎（be動詞・一般動詞・疑問詞など）に加えて、次のような文法が問われる。なお、現在完了・受動態・関係代名詞は英検3級の範囲なので、4級では中心になりません。\\n\\n■ 4級で問われる主な文法\\n　不定詞（to＋原形）：I want to be a doctor. / It's fun to swim.\\n　動名詞（-ing）：I enjoy playing soccer. / She is good at singing.\\n　比較級・最上級：This book is more interesting than that one.\\n　助動詞：You must wash your hands. / Can I use your pen?\\n　接続詞（when/if/because など）：I was happy when I saw you.\\n\\n■ 例題①（不定詞）\\n　My brother likes ( ) soccer on Sundays.\\n　1. play　2. plays　3. to play　4. played\\n　【何を聞かれているか】likes のあとに入る、play の正しい形を選ぶ問題。\\n　【手がかり】like（〜が好き）のあとに動詞を続けるときは、「to＋原形」か「-ing形」のどちらかの形にする。like は動詞のあとに動詞をそのまま並べることはできない。\\n　【選択肢を1つずつ考える】\\n　　1. play → 原形だけでは likes のあとに続けられない。\\n　　2. plays → likes と動詞が2つ並んでしまい、文として成り立たない。\\n　　3. to play → 「to＋原形」の形で「サッカーをすることが好き」になる。\\n　　4. played → 過去形も likes のあとには置けない。\\n　→ 答えは 3. to play。（likes playing とも言えるが、選択肢にあるのは to play だけ。）\\n　【確かめ】My brother likes to play soccer on Sundays.（兄は日曜日にサッカーをするのが好きです）と読み、意味が通ることを確かめる。\\n　【よくあるまちがい】主語が My brother（三人称単数）なので plays を選んでしまうこと。likes がすでに三人称単数の -s を受け持っているので、あとの動詞は to＋原形にする。\\n\\n■ 例題②（比較）\\n　This mountain is ( ) than that one.\\n　1. high　2. higher　3. highest　4. more high\\n　【何を聞かれているか】than の前に入る、high の正しい形を選ぶ問題。\\n　【手がかり】空所のあとに than（〜よりも）がある。「AはBより〜だ」と2つを比べる文では、形容詞を比較級にして、あとに than を置く。\\n　【なぜ higher か】high のような短い（1音節の）形容詞は、語の終わりに -er をつけて比較級にする。high → higher。\\n　【選択肢を1つずつ考える】\\n　　1. high → 比べていない形なので、than とは合わない。\\n　　3. highest → 最上級で、「いちばん高い」。than ではなく the highest in ~ の形で使う。\\n　　4. more high → more をつけるのは interesting や beautiful のような長い形容詞。high は短いので -er を使う。\\n　→ 答えは 2. higher。\\n　【確かめ】This mountain is higher than that one.（この山はあの山より高い）と読み、意味が通ることを確かめる。\\n　【よくあるまちがい】more interesting のように何でも more をつけると思い、more high と言ってしまうこと。短い語は -er、長い語は more です。\\n\\n★ ポイント：4級は5級の範囲がそのまま出題される土台の上に、新しい文法が積み重なる試験。5級レベルの基礎に不安があるまま4級の対策をしても、応用問題でつまずきやすいので、まず土台を固めることが大切。\",\"figureId\":\"xf_new20_e6_eigo_20\"},{\"heading\":\"2. Eメール・掲示形式の長文問題を解く\",\"body\":\"4級から加わる長文問題には、友達同士のEメールのやり取りや、掲示（お知らせ）を題材にしたものが多い。形式に慣れておくと落ち着いて取り組める。\\n\\n■ Eメール問題の特徴\\n2〜3通のメールのやり取りが提示され、それぞれの内容を正しく理解して答える設問が出る。件名（Subject）・差出人（From）・宛先（To）も情報として読み取る対象になる。\\n\\n■ 例題形式（要約）\\nSubject: About the school festival\\nFrom: Emma\\nTo: Yuki\\nHi Yuki, are you free next Saturday? Our school is having a festival, and I want to go with you. It starts at 10 a.m.\\n（件名：学校祭について　差出人：エマ　宛先：ユキ　やあユキ、今度の土曜日は空いてる？　学校で祭りがあって、一緒に行きたいの。午前10時に始まるよ。）\\n\\n設問例：What does Emma want to do?（エマは何をしたいか）\\n　→ 本文の I want to go with you. をそのまま探すのではなく、「学校祭に一緒に行きたい」という内容を選択肢の言い換え表現から探す。\\n\\n■ 掲示（notice）問題の特徴\\nイベントの日時・場所・注意事項など、単元5（お知らせ文の読み方）で学んだ読み方がそのまま活きる。What／When／Where／持ち物の5点を意識して読む。\\n\\n⚠ 注意：4級の内容一致問題では、本文の語句をそのまま使った選択肢よりも、同じ内容を別の言い方に言い換えた選択肢が正解になることが多い（例：本文の I want to go with you. → 選択肢では She wants to go to the festival with Yuki. のように言い換えられる）。\",\"mangaId\":\"new20_e6_eigo_20_xm\"},{\"heading\":\"3. 語句整序・リスニングの対策と学習の進め方\",\"body\":\"4級の語句整序問題とリスニングは、5級よりも一段レベルが上がる。仕上げとして対策のポイントを押さえよう。\\n\\n■ 語句整序問題（5級との違い）\\n5級では基本文型の並べかえが中心だったが、4級では不定詞・比較・接続詞を含む、やや長い文の並べかえが出題される。\\n　例）( to / want / I / be / a / doctor / in the future ).\\n　→ まず I want to be（私は〜になりたい）という骨組みを作り、そこに a doctor、in the future を組み合わせる。\\n\\n■ 語句整序のコツ\\n①主語と動詞をまず見つける\\n②不定詞（to＋動詞の原形）や比較（than、more、-er）のセットになる語をひとかたまりとして考える\\n③残りの語句（時・場所を表す語句）を文末に配置する\\n\\n■ リスニング対策（4級で変わる点）\\n5級よりも会話や英文が長くなり、問われる情報も増える。「誰が」「何を」「いつ」を聞き取るだけでなく、会話全体の流れ（提案→断る理由→代わりの案）まで追う必要がある。\\n\\n■ 総仕上げとしての学習の進め方\\n①これまでの新20単元・既存の全単元で学んだ文法・表現を横断的に復習する\\n②過去形・未来表現・比較・道案内・買い物・お知らせ文の読み方など、場面ごとの型を思い出しながら模擬問題を解く\\n③間違えた問題は「知らなかった」のか「わかっていたのに読み間違えた」のかを区別し、後者はもう一度同じような問題で確認する\\n\\n★ ポイント：英検4級は小学6年生にとって背伸びした目標に見えるかもしれないが、これまでの単元で学んだ文法・表現をつなぎ合わせれば十分に対応できるレベルである。焦らず、既習事項の「使い方」を確認する総仕上げのつもりで取り組もう。\"}]}",
"{\"id\":\"gap_gce_01\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"同音異義語：音が同じでつづりがちがう語\",\"description\":\"「see と sea」のように、読み方が同じでつづりと意味がちがう語を、文の中の働きで書き分ける\",\"intro\":\"I can see the sea.（私は海が見える）という文では、see と sea は読み方がまったく同じ「スィー」なのに、つづりも意味もちがいます。このように読み方が同じでつづりと意味がちがう語を、同音異義語（どうおんいぎご）といいます。耳で聞くだけでは区別できないので、書くときは文の中の働きを見て選びます。そのコツを身につけましょう。\",\"order\":20400,\"studyPeriod\":\"小5前半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"同音異義語は、読み方が同じで、つづりと意味がちがう語（see と sea、to・too・two など）。\",\"耳では区別できないので、書くときは「空所の前後の語」と「その語の働き（動詞か名詞か）」で決める。\",\"their（彼らの）は後ろに名詞が続く。they're は they are の短縮形。それ以外の「そこに」は there。\",\"to は「〜へ・〜すること」、too は「〜も・〜すぎる」、two は数の 2。\",\"write（書く）と right（正しい・右）、know（知っている）と no（いいえ）、hear（聞こえる）と here（ここに）はよく出る組。\",\"つづりのちがいは昔の発音の名残であり、意味を目で見分けるための役にも立っている。\",\"確かめは「その語を入れて日本語に訳し、意味が通るか」「they are に置きかえられるか」。\"],\"sections\":[{\"heading\":\"同じ音でちがう語のペアを知る\",\"body\":\"同音異義語（どうおんいぎご）とは、読み方（発音）が同じなのに、つづりと意味がちがう語のことです。入試では、文の空所に正しいつづりの語を入れる問題や、聞こえた音から単語を書く問題で出ます。\\n\\n■ 2語の組（よく出るもの）\\nsee（見る）／sea（海）　　どちらも「スィー」\\nknow（知っている）／no（いいえ・ない）　　どちらも「ノウ」\\nwrite（書く）／right（正しい・右）　　どちらも「ライト」\\nhear（聞こえる）／here（ここに）　　どちらも「ヒア」\\nmeet（会う）／meat（肉）　　どちらも「ミート」\\nweek（週）／weak（弱い）　　どちらも「ウィーク」\\nson（むすこ）／sun（太陽）　　どちらも「サン」\\nnew（新しい）／knew（know の過去形）　　どちらも「ニュー」\\nhour（1時間）／our（私たちの）　　どちらも「アウア」\\none（1）／won（win の過去形）　　どちらも「ワン」\\nwait（待つ）／weight（重さ）　　どちらも「ウェイト」\\nblue（青い）／blew（blow「ふく」の過去形）　　どちらも「ブルー」\\n\\n■ 3語の組\\nto（〜へ）／too（〜も・〜すぎる）／two（2）　　どれも「トゥー」\\nthere（そこに）／their（彼らの）／they're（they are の短縮形）　　どれも「ゼア」\\nbuy（買う）／by（〜のそばに）／bye（さようなら）　　どれも「バイ」\\n\\n例）I can see the sea from my room.（私の部屋から海が見える）\\n例）I know the answer.／No, I don't.（私は答えを知っている。／いいえ、知りません）\\n\\n★ ここがポイント：同音異義語は**読み方が同じでつづりと意味がちがう**語である。耳では区別できないので、書くときは**文の中での働き**を見て書き分ける。\",\"figureId\":\"xf_gap_gce_01\"},{\"heading\":\"なぜ同じ音のちがうつづりがあるのか\",\"body\":\"英語には、同じ音をちがうつづりで書く語がたくさんあります。なぜでしょうか。理由は二つあります。\\n\\n■ ①つづりは昔の発音を残している\\n英語のつづりは、昔の読み方をもとに決まりました。know や write の最初の k や w は、昔は実際に読まれていた文字です。その後、読み方だけが変わって音が消え、つづりはそのまま残りました。そのため、いまの音は同じでも、つづりがちがう語がいくつも生まれました。\\n\\n■ ②つづりがちがうと、目で意味を見分けられる\\nsee と sea が同じつづりだったら、I can see the sea. は読みにくくなります。つづりがちがうおかげで、読む人は目で見て「見る」と「海」を区別できます。つづりのちがいは、意味を伝えるための目印でもあるのです。\\n\\n■ だから、書くときの考え方\\n音から選ぶことはできません。かわりに、**その空所に入る語の役割**で選びます。空所の前後を見て、次の三つのどれが入るのかを決めてから、つづりを選びます。\\n①ものの名前（名詞）が入るのか\\n②動作（動詞）が入るのか\\n③数・場所・持ち主のどれかを表すのか\\n\\n例）I can ( ) the ( ).\\n　空所1：can のあとには動作の語が来る → see（見る）\\n　空所2：the のあとにはものの名前が来る → sea（海）\\n　答え：I can see the sea.\\n\\n★ ここがポイント：つづりは**昔の発音の名残**であり、意味を目で見分ける役目もある。選ぶときは音ではなく、**空所に入る語の役割**で決める。\"},{\"heading\":\"まぎらわしい組の見分け方（there・their・they're／to・too・two）\",\"body\":\"同音異義語の中でも、入試でとくにまちがえやすい組を整理します。\\n\\n■ there・their・they're\\nthere ＝「そこに」。There is 〜. / There are 〜. の形や、場所を表す。\\n　例）There is a cat under the table.（テーブルの下にねこがいる）\\n　例）I went there yesterday.（私はきのうそこへ行った）\\ntheir ＝「彼らの・それらの」。あとに名詞が続く。\\n　例）Their house is near the station.（彼らの家は駅の近くにある）\\nthey're ＝ they are をつづめた形。\\n　例）They're my friends.（彼らは私の友だちだ）\\n見分け方：they are に置きかえて意味が通れば they're。あとに名詞が続けば their。それ以外は there。\\n\\n■ to・too・two\\nto ＝「〜へ」「〜すること」。あとに場所（to school）か動詞（to play）が続く。\\ntoo ＝「〜も」「〜すぎる」。文の終わりや形容詞の前に置く。\\n　例）I like cats, too.（私もねこが好きだ）\\n　例）This bag is too heavy.（このかばんは重すぎる）\\ntwo ＝数の 2。\\n　例）I have two brothers.（私には兄弟が 2 人いる）\\n見分け方：数なら two。「〜も」「〜すぎる」の意味なら too。ほかは to。\\n\\n■ write・right、hear・here、know・no\\nwrite は動作（書く）、right は「正しい」「右」。　例）Write your name here.（ここに名前を書きなさい）\\nhear は耳に聞こえる、here は場所の「ここ」。　例）I can hear a bird.／Come here.\\nknow は動詞（知っている）、no は「いいえ」「ひとつも〜ない」。　例）I know him.／No, thank you.\\n\\n★ ここがポイント：**their はあとに名詞が続く、they're は they are に置きかえられる、それ以外が there**。数なら **two**、「〜も・〜すぎる」なら **too**、ほかは **to** と決める。\",\"mangaId\":\"gap_gce_01_xm\"},{\"heading\":\"例題：空所に入る語を選ぶ\",\"body\":\"次の（　）に入る語を選びます。まず空所の役割を決め、次に候補を当てはめて意味を確かめます。\\n\\n問1　( ) cat is very cute.（Their / There / They're）\\n　空所のあとに cat（名詞）が続いている。「彼らの」と持ち主を表す語が入る。\\n　答え：Their（「彼らのねこはとてもかわいい」）\\n\\n問2　I can ( ) the birds in the sky.（see / sea）\\n　can のあとには動作の語が入る。「鳥が見える」なので動詞。\\n　答え：see\\n\\n問3　Ken has ( ) sisters.（to / too / two）\\n　sisters の前に入るのは数。「ケンには姉か妹が 2 人いる」。\\n　答え：two\\n\\n問4　( ) in the park now.（There / Their / They're）\\n　they are に置きかえると They are in the park now.（彼らは今公園にいる）となり、意味が通る。\\n　答え：They're\\n\\n問5　She wants to ( ) a letter.（write / right）\\n　to のあとには動詞が入る。「手紙を書きたい」。\\n　答え：write\\n\\n問6　I ( ) the answer.（know / no）\\n　主語 I のあとには動詞が入る。「私は答えを知っている」。\\n　答え：know\\n\\n★ ここがポイント：まず**空所の役割（名詞・動詞・数・持ち主）**を決め、次に**置きかえて意味が通るか**を確かめる。この順番を守ると、音に迷わなくなる。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"答えを書いたあとに、次の四つの手順で確かめます。\\n\\n■ ①役割をもう一度言う\\n「ここには動詞が入る」「ここには数が入る」と声に出して言います。その役割と選んだ語が合っているかを見ます。\\n例）Ken has ( ) sisters. → 数が入る → two。to や too は数ではないので入らない。\\n\\n■ ②置きかえで確かめる\\nthey're は they are に、their は「彼らの」に置きかえてみます。\\n例）They're in the park. → They are in the park. ○（意味が通る）\\n例）They're cat is cute. → They are cat is cute. ×（文にならない）→ Their cat is cute.\\n\\n■ ③日本語に訳して意味が通るか\\n選んだ語を入れた文を日本語にして、おかしくないかを読みます。\\n例）I can sea the birds. →「私は海の鳥たち」？ → 意味が通らない。see に直す。\\n\\n■ ④つづりを 1 字ずつ見る\\nwrite は w から、know は k から書き始めます。昔の発音の名残で読まない文字があるので、書き落としやすいところです。\\n例）rite ×　→　write ○　／　now ×（意味がちがう）→ know ○\\n\\n★ ここがポイント：確かめは**役割 → 置きかえ → 日本語訳 → つづり**の順に行う。特に **they are に置きかえる**方法は、there・their・they're の区別にそのまま使える。\"}],\"trapExamples\":[{\"question\":\"次の（　）に入る語を選びなさい。「( ) is a library near my house.」（Their / There）\",\"wrongAnswer\":\"Their\",\"trapExplanation\":\"音は同じなので、感覚で選んでしまいやすい。Their か There かは、あとに名詞が続くかどうかで決まるのに、そこを見ていない。\",\"correctAnswer\":\"There\",\"correctExplanation\":\"is の前にあって「〜がある」という文をつくる語は there。their は「彼らの」の意味で、あとに名詞が続く（Their house）。ここでは is が続いているので There が入る。\"},{\"question\":\"「私も公園に行きたいです。」I want to go to the park, ( ).（to / too / two）\",\"wrongAnswer\":\"to\",\"trapExplanation\":\"文の中に to が何度も出てくるので、つられて to を選んでしまう。文の終わりに置く語の意味を考えていない。\",\"correctAnswer\":\"too\",\"correctExplanation\":\"「〜も」を表すときは、文の終わりに too を置く。to は「〜へ」や「〜すること」の語で、文の終わりには置かない。two は数なので意味が合わない。\"}]}",
"{\"id\":\"gap_gce_02\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"反対の意味の英語（反意語）：形容詞・動詞をペアで覚える\",\"description\":\"反意語（はんいご）は同じ「ものさし」の両はしにあることを手がかりに、形容詞・動詞・副詞のペアを整理する\",\"intro\":\"「hot の反対の意味の語を書きなさい」という問題は、中学入試の英語でとてもよく出ます。答えは cold ですが、では「short の反対」は何でしょうか。long と答えても tall と答えても、場合によっては正しいのです。反対の意味の語（反意語（はんいご））がどう決まるのかを知ると、ペアで覚えやすくなり、まちがいも減ります。\",\"order\":20401,\"studyPeriod\":\"小5後半\",\"targetLevel\":\"kiso\",\"keyPoints\":[\"反意語は、同じ「ものさし」（温度・長さ・速さ・時刻・気持ちなど）の両はしにある語どうし。\",\"形容詞の例：hot ⇔ cold、new ⇔ old、easy ⇔ difficult、fast ⇔ slow、early ⇔ late、heavy ⇔ light。\",\"動詞の例：open ⇔ close（shut）、come ⇔ go、buy ⇔ sell、start ⇔ finish、win ⇔ lose、borrow ⇔ lend。\",\"ものさしが変わると相手も変わる：short は長さなら long、背の高さなら tall。old は物なら new、人なら young。\",\"「not ＋ 語」は反意語とはかぎらない。not hot は cold ではなく warm かもしれない。\",\"反意語は同じ品詞どうしでペアにする（形容詞には形容詞、動詞には動詞）。\",\"答えたあとは、ペアを逆に読んで元の語にもどるか、文に入れて意味が通るかを確かめる。\"],\"sections\":[{\"heading\":\"反意語のペアを分けて覚える\",\"body\":\"反意語（はんいご）とは、意味が反対になる語のことです。入試では、「次の語の反対の意味の語を書きなさい」「（　）に反対の意味の語を入れなさい」という形で出ます。品詞ごとに分けると覚えやすくなります。\\n\\n■ 形容詞（ようすを表す語）\\nhot（あつい）⇔ cold（つめたい・さむい）\\nnew（新しい）⇔ old（古い）\\nold（年をとった）⇔ young（わかい）\\neasy（やさしい）⇔ difficult（むずかしい）\\nhappy（うれしい）⇔ sad（かなしい）\\nfast（速い）⇔ slow（おそい）\\nearly（早い）⇔ late（おそい）\\nheavy（重い）⇔ light（軽い）\\nstrong（強い）⇔ weak（弱い）\\nclean（きれいな）⇔ dirty（よごれた）\\nfull（いっぱいの）⇔ empty（からの）\\nnear（近い）⇔ far（遠い）\\n\\n■ 動詞（動作を表す語）\\nopen（開ける）⇔ close / shut（閉める）\\ncome（来る）⇔ go（行く）\\nbuy（買う）⇔ sell（売る）\\nstart / begin（始める）⇔ finish / end（終える）\\nwin（勝つ）⇔ lose（負ける）\\nborrow（借りる）⇔ lend（貸す）\\npush（押す）⇔ pull（引く）\\nremember（おぼえている）⇔ forget（わすれる）\\n\\n■ その他（副詞・前置詞・名詞など）\\nup ⇔ down／in ⇔ out／before ⇔ after／always ⇔ never／day ⇔ night／question ⇔ answer\\n\\n例）This bag is heavy, but that bag is light.（このかばんは重いが、あのかばんは軽い）\\n\\n★ ここがポイント：反意語は**品詞ごと**に、**ペアにして声に出して**覚える。文の形で（This bag is heavy, but that bag is light.）覚えると、使い方も同時に身につく。\",\"figureId\":\"xf_gap_gce_02\"},{\"heading\":\"なぜ反対になるのか：同じものさしの両はし\",\"body\":\"hot の反対が cold だとわかるのは、どうしてでしょうか。理由は、hot と cold が「温度」という同じものさしの両はしにあるからです。\\n\\n■ ものさしで考える\\n温度のものさしを横に引くと、左から順に cold（つめたい）、cool（すずしい）、warm（あたたかい）、hot（あつい）と並びます。いちばん端どうしの cold と hot が反意語です。\\n\\n■ 「まんなか」は反意語ではない\\ncool や warm は、ものさしのまんなか近くにあります。hot の反対に cool を書いたら、入試ではまちがいになります。反意語は「両はし」の語どうしです。\\n\\n■ not hot は cold とはかぎらない\\n「あつくない（not hot）」は、cold かもしれませんが、warm や cool かもしれません。ものさしのどこかが「あつくない」にあたるだけです。だから、not ＋ 語 を反意語として使ってはいけません。\\n\\n■ ものさしが変わると、相手も変わる\\n同じ語でも、どのものさしで使われているかで、反対の語がちがってきます。\\nshort（長さ）⇔ long　／　short（背・高さ）⇔ tall\\nold（物の古さ）⇔ new　／　old（人の年）⇔ young\\nlight（重さ）⇔ heavy　／　light（明るさ）⇔ dark\\nright（正しい）⇔ wrong　／　right（右）⇔ left\\n\\n例）My hair is short, but my sister's hair is long.（私の髪は短いが、姉の髪は長い）\\n例）Ken is short, but his brother is tall.（ケンは背が低いが、兄は背が高い）\\n\\n★ ここがポイント：反意語は**同じものさしの両はし**にある語どうし。**ものさしが変われば反対の語も変わる**ので、まず「何について言っているのか」を考える。\",\"mangaId\":\"gap_gce_02_xm\"},{\"heading\":\"品詞をそろえて、文の中で使う\",\"body\":\"反意語を答えるときには、品詞をそろえます。形容詞には形容詞、動詞には動詞を答えます。\\n\\n■ 品詞をそろえる\\n× hot ⇔ ice（ice は名詞で、品詞がちがう）\\n○ hot ⇔ cold（どちらも形容詞）\\n× buy ⇔ shop（shop は「店」「買い物をする」でペアにならない）\\n○ buy ⇔ sell（どちらも動詞）\\n\\n■ 文の形で覚える\\n反意語は、向かい合う二つの文にすると記憶に残ります。\\nThis box is heavy. / That box is light.\\nOpen the door. / Close the door.\\nI came here by bus. / I went home by train.\\nHe won the game. / She lost the game.\\n\\n■ 書きかえに使う\\n反意語を使うと、意味を変えずに言いかえることができます。\\nKen is taller than Tom. ＝ Tom is shorter than Ken.\\nThis question is easy. ＝ This question is not difficult.\\nただし、not を使う言いかえは「だいたい同じ」であり、「完全に反対」ではありません。\\n\\n■ 反対ではない組に注意\\nlearn（学ぶ）と teach（教える）、ask（たずねる）と answer（答える）は、行為が向かい合っているので問題でペアにされることがあります。ただし、短い語で聞かれたら、まず上の「ものさしの両はし」で確かめます。\\n\\n★ ここがポイント：**品詞をそろえる**。反意語は文にして**向かい合わせ**で覚え、**not ＋ 語は反意語とはかぎらない**ことを忘れない。\"},{\"heading\":\"例題：反対の意味の語を答える\",\"body\":\"手順は、①ものさしを考える ②同じ品詞で答える ③文に入れて読む、の三つです。\\n\\n問1　hot の反対の意味の語を書きなさい。\\n　ものさしは温度。いちばんはしの反対側は cold。\\n　答え：cold\\n\\n問2　heavy の反対の意味の語を書きなさい。\\n　ものさしは重さ。heavy（重い）の反対は light（軽い）。\\n　答え：light\\n\\n問3　early の反対の意味の語を書きなさい。\\n　ものさしは時刻・時期。early（早い）の反対は late（おそい）。\\n　答え：late\\n\\n問4　open の反対の意味の動詞を書きなさい。\\n　動詞なので、動詞で答える。開ける ⇔ 閉める。\\n　答え：close（または shut）\\n\\n問5　My bag is new, but his bag is ( ).（　）に入る語を書きなさい。\\n　bag（物）の new の反対。物の古さのものさしなので old。\\n　答え：old（「私のかばんは新しいが、彼のかばんは古い」）\\n\\n問6　Ken is tall, but Tom is ( ).（　）に入る語を書きなさい。\\n　背の高さのものさしなので、tall の反対は short。\\n　答え：short（「ケンは背が高いが、トムは背が低い」）\\n\\n問7　The shop opens at nine and ( ) at six.（　）に入る語を書きなさい。\\n　opens の反対の動作。主語が the shop（3人称単数）で現在なので s をつける。\\n　答え：closes\\n\\n★ ここがポイント：**ものさし → 品詞 → 文に入れて読む**の順で考える。問7のように、動詞の反意語は**あとの形（s・ed）も合わせる**のを忘れない。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"答えを書いたあとに、次の四つで確かめます。\\n\\n■ ①逆から読んでもどるか\\n答えの語の反対を言ってみて、もとの語にもどるかを見ます。\\n例）hot → cold。cold の反対は hot。○\\n例）heavy → light。light の反対は heavy（重さのとき）。○\\nもどらなければ、ものさしがずれている疑いがあります。\\n\\n■ ②品詞をそろえたか\\nもとの語が形容詞なら形容詞、動詞なら動詞を書いたかを見ます。\\n例）open → close は動詞どうし。○　／　open → door は品詞がちがう。×\\n\\n■ ③文に入れて意味が通るか\\nMy bag is new, but his bag is old.（私のかばんは新しいが、彼のかばんは古い）\\n「but（けれども）」でつながる前後が対比になっていれば、反対の意味の語が入っています。\\n\\n■ ④ものさしが二つある語は、問題文から決める\\nshort は、前後の語が hair や rope なら long、前後が人なら tall。light は、weight なら heavy、color や room なら dark。問題文の言葉をヒントに選びます。\\n\\n★ ここがポイント：確かめは**逆から読んでもどるか**・**品詞**・**文に入れて対比になるか**・**ものさしが合っているか**の四つ。**ものさしが二つある語は問題文から決める**。\"}],\"trapExamples\":[{\"question\":\"次の（　）に入る語を選びなさい。「Tom is young, but his grandfather is ( ).」（new / old）\",\"wrongAnswer\":\"new\",\"trapExplanation\":\"「old の反対は new」とだけ覚えていると、new を選んでしまう。ここでは人の年を言っているので、ものさしがちがう。\",\"correctAnswer\":\"old\",\"correctExplanation\":\"人の年についての young（わかい）の反対は old（年をとった）。new は物が新しいときの反対語。「トムはわかいが、祖父は年をとっている」となる。\"},{\"question\":\"「I am not hot.（私はあつくない）」は、必ず「I am cold.（私はさむい）」という意味になるか。\",\"wrongAnswer\":\"必ず I am cold. という意味になる。\",\"trapExplanation\":\"「あつくない＝さむい」と思いこんでしまうが、温度のものさしにはまんなかの warm や cool がある。\",\"correctAnswer\":\"ならない。warm や cool かもしれない。\",\"correctExplanation\":\"not hot は「あつくない」というだけで、温度が cold とはかぎらない。反意語はものさしの両はしの語（hot と cold）であり、not をつけた形とはちがう。\"}]}",
"{\"id\":\"gap_gce_03\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"使役・知覚の動詞：make・let・have と see・hear のあとの形\",\"description\":\"「〜させる」「〜するのを見る」を表す動詞のあとに、to のつかない動詞の原形が続く形を整理する\",\"intro\":\"My mother made me wash the dishes.（母は私に皿を洗わせた）。「洗う」の wash には、to がついていません。「〜するように言う」の tell や「〜してほしい」の want は to がいるのに、make には要らないのはなぜでしょうか。人に何かを「させる」動詞（使役（しえき）の動詞）と、見る・聞くの動詞（知覚（ちかく）の動詞）の形を、理由といっしょに整理します。\",\"order\":20402,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"〈make／let／have ＋ 人 ＋ 動詞の原形〉で「人に〜させる」。make は強制、let は許可、have は「たのんで〜してもらう」。\",\"〈see／hear／watch／feel ＋ 人 ＋ 動詞の原形〉で「人が〜するのを見る・聞く・感じる」。\",\"原形は「最初から最後まで」、〜ing は「している最中」を表す（I saw him cross / crossing the street.）。\",\"この形の動詞のあとには to をつけず、動詞に s・ed・ing もつけない。\",\"want・tell・ask のあとは〈人 ＋ to ＋ 原形〉。to がいるかどうかが見分けのポイント。\",\"make me happy のように、あとに形容詞が来る形とは別。原形が来るのは「させる」の make。\",\"受け身になると to が出てくる（I was made to clean the room.）。\"],\"sections\":[{\"heading\":\"make・let・have で「人に〜させる」\",\"body\":\"次の三つの動詞は、あとに〈人 ＋ 動詞の原形〉を置いて、「人に〜させる」という意味を作ります。このような動詞を使役（しえき）の動詞といいます。\\n\\n■ 形：〈make／let／have ＋ 人 ＋ 動詞の原形〉\\n動詞の原形とは、s も ed も ing もつかない、辞書にのっている形のことです。\\n\\n■ 三つの動詞のちがい\\nmake ＝ 無理にでもさせる（強制（きょうせい））\\n　例）My mother made me wash the dishes.（母は私に皿を洗わせた）\\nlet ＝ してもいいと許す（許可（きょか））\\n　例）My father let me use his computer.（父は私が自分のパソコンを使うのを許してくれた）\\nhave ＝ たのんで〜してもらう・当然のこととして〜させる\\n　例）I had my brother carry my bag.（私は弟にかばんを運んでもらった）\\n　例）The teacher had us read the story aloud.（先生は私たちにその話を音読させた）\\n\\n■ 動詞の形に注意\\n原形のままにします。人のあとの動詞に s や ed をつけてはいけません。\\n○ She made him laugh.（彼女は彼を笑わせた）\\n× She made him laughs. ／ × She made him laughed.\\n\\n■ 日本語でのつかまえ方\\n「〜に…させる」「〜が…するのを許す」と日本語で言えるときは、この形を使います。\\n\\n★ ここがポイント：**make は強制、let は許可、have は「たのんでしてもらう」**。どの動詞のあとも**〈人 ＋ 原形〉**で、to はつけない。\",\"figureId\":\"xf_gap_gce_03\"},{\"heading\":\"see・hear・watch で「〜するのを見る・聞く」\",\"body\":\"見る・聞く・感じるという感覚を表す動詞（知覚（ちかく）の動詞）も、同じ形を作ります。\\n\\n■ 形：〈see／hear／watch／feel ＋ 人 ＋ 動詞の原形〉\\n　例）I saw him cross the street.（私は彼が道を渡るのを見た）\\n　例）I heard her sing in the next room.（私は彼女がとなりの部屋で歌うのが聞こえた）\\n　例）We watched the children play soccer.（私たちは子どもたちがサッカーをするのを見ていた）\\n　例）I felt the house shake.（私は家がゆれるのを感じた）\\n\\n■ 原形と〜ing のちがい\\n知覚の動詞のあとには、原形のほかに〜ing の形も置けます。\\n　I saw him cross the street.　　→ 渡りはじめから渡りおわるまでを見た\\n　I saw him crossing the street.　→ 渡っている最中を見た\\n原形は「ひとまとまりの動作を、最初から最後まで」、〜ing は「その動作の途中」と考えます。\\n\\n■ help も同じ形\\nhelp ＋ 人 ＋ 動詞（to があってもなくてもよい）\\n　例）He helped me carry the box.（彼は私が箱を運ぶのを手伝ってくれた）\\n　　　He helped me to carry the box.（同じ意味）\\n\\n★ ここがポイント：see・hear・watch・feel も**〈人 ＋ 原形〉**。**原形は「最初から最後まで」、〜ing は「している最中」**と使い分ける。\"},{\"heading\":\"なぜ to がつかないのか／want・tell・ask とのちがい\",\"body\":\"want や tell のあとには to がつくのに、make や see のあとにはつきません。なぜでしょうか。\\n\\n■ to は「これから向かう」しるし\\nto は、もともと「〜に向かう」という意味の語です。\\n　I want to go.（行きたい）＝ まだ行っていない、これから行く方向へ気持ちが向かう\\n　He told me to wait.（待つように言った）＝ 待つことは、これからすること\\nwant・tell・ask は、あとで行われる動作をあとに続けるので、to が必要です。\\n\\n■ させる・見る・聞くは、動作が「同時」に起きる\\nmake・let・have や see・hear では、させる（許す・見る）という動作と、人がする動作がほぼ同時に起こります。「これから向かう」必要がないので、to を置かず、動詞の原形だけを置きます。これは覚えやすくするための考え方ですが、見分けるときの助けになります。\\n\\n■ 並べて整理する\\n〈人 ＋ to ＋ 原形〉をとる：want・tell・ask（望む・言う・たのむ）\\n〈人 ＋ 原形〉をとる：make・let・have・see・hear・watch・feel（させる・許す・見る・聞く）\\n\\n■ make のあとに形容詞が来る形とのちがい\\nThe news made me happy.（その知らせは私をうれしくさせた）のように、make のあとに形容詞が来る形もあります。あとの語が形容詞（happy）なら「〜の状態にする」、動詞の原形（laugh）なら「〜させる」です。\\n　The movie made me cry.（その映画は私を泣かせた）\\n\\n■ 受け身になると to が出てくる\\n　My mother made me clean my room.\\n　→ I was made to clean my room.（私は部屋をそうじさせられた）\\n受け身では、to がつくので注意します。\\n\\n★ ここがポイント：**to は「これから向かう」しるし**。want・tell・ask は to がいり、**make・let・have・see・hear は to がいらない**。ただし**受け身になると to が出る**。\",\"mangaId\":\"gap_gce_03_xm\"},{\"heading\":\"例題：形を決めて文を完成させる\",\"body\":\"手順は、①動詞が make・let・have・see・hear のどれかを見る ②人のあとの動詞を原形にする ③意味（強制・許可・たのむ）を確かめる、の三つです。\\n\\n問1　「先生は私たちに教室をそうじさせた。」\\n　The teacher made us ( ) the classroom.\\n　make ＋ 人 ＋ 原形。clean にする。cleaned や to clean ではない。\\n　答え：clean\\n\\n問2　「母は私が犬を飼うのを許してくれた。」\\n　My mother ( ) me have a dog.\\n　「許す」なので let。後ろの have は原形のまま。\\n　答え：let\\n\\n問3　「私は鳥が木で鳴くのが聞こえた。」\\n　I heard a bird ( ) in the tree.\\n　heard のあとは原形。鳴いている最中をとらえるなら singing も使える。\\n　答え：sing\\n\\n問4　「私は弟にその箱を運んでもらった。」\\n　I ( ) my brother carry the box.\\n　「たのんでしてもらう」は have。過去の文なので had にする。\\n　答え：had\\n\\n問5　次の文のまちがいを直しなさい。\\n　My father made me to wash his car.\\n　make のあとには to を置かない。\\n　答え：My father made me wash his car.\\n\\n★ ここがポイント：**make・let・have・see・hear のあとは、〈人 ＋ 原形〉**。問5のように、**to をつけてしまうのが典型的なまちがい**である。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"答えを書いたあとに、次の四つで確かめます。\\n\\n■ ①動詞はなにか\\nmake・let・have・see・hear・watch・feel のどれかなら、〈人 ＋ 原形〉の形。want・tell・ask なら〈人 ＋ to ＋ 原形〉の形。\\n\\n■ ②人のあとの動詞を見る\\nto・s・ed・ing がついていないか（原形か）を見ます。\\n例）She made him laughs. ×　→　She made him laugh. ○\\n\\n■ ③意味を確かめる\\n・無理にでもさせた → make\\n・許した → let\\n・たのんで／当然のこととしてしてもらった → have\\n・見た・聞いた → see・hear・watch\\n例）「父は私が行くのを許した」→ let。make にすると「無理に行かせた」になり、意味が変わる。\\n\\n■ ④時制は動詞のほうで表す\\n過去の文では、make・let・have は made・let・had にします。let は過去形も let で、形が変わらない。\\n例）My father let me go.（let は現在でも過去でも同じ形。前後の文で時を判断する）\\n\\n★ ここがポイント：確かめは**動詞の種類 → 人のあとが原形か → 意味 → 時制**の順。**let は過去形も let**であることも覚えておく。\"}],\"trapExamples\":[{\"question\":\"次の文のまちがいを直しなさい。「Our teacher let us to go home early.」\",\"wrongAnswer\":\"まちがいはない（to go でよい）\",\"trapExplanation\":\"allow us to go（allow は to がいる）などの形と混ざってしまい、let のあとにも to をつけてしまう。\",\"correctAnswer\":\"Our teacher let us go home early.\",\"correctExplanation\":\"let のあとは〈人 ＋ 原形〉で、to はつけない。「先生は私たちが早く帰るのを許した」。\"},{\"question\":\"次の（　）に入る形を書きなさい。「My mother told me ( ) the dishes.」（wash を適する形にする）\",\"wrongAnswer\":\"wash\",\"trapExplanation\":\"make や let の形（人のあとは原形）と同じだと思ってしまう。tell は to のいる動詞であることを見落としている。\",\"correctAnswer\":\"to wash\",\"correctExplanation\":\"tell は「言う」で、あとで行う動作をあとに続けるので〈人 ＋ to ＋ 原形〉の形になる。「母は私に皿を洗うように言った」。\"}]}",
"{\"id\":\"gap_gce_05\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"比較の書きかえ：同じ意味を表す三つの言い方\",\"description\":\"「いちばん〜」の文を、than any other や No other を使って、意味を変えずに書きかえる\",\"intro\":\"Lake Biwa is the largest lake in Japan.（琵琶湖は日本でいちばん大きい湖だ）。この文は、Lake Biwa is larger than any other lake in Japan. とも、No other lake in Japan is as large as Lake Biwa. とも言いかえられます。入試の書きかえ問題では、この三つの言い方を行き来できるかが問われます。なぜ other が必要なのか、なぜ lake は単数形なのかを、理由から確かめましょう。\",\"order\":20404,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"最上級の文は、〈比較級 ＋ than any other ＋ 単数名詞〉と〈No other ＋ 単数名詞 ＋ is as ＋ 原級 ＋ as〉に書きかえられる。\",\"any other のあとの名詞は単数形（any other lake。lakes は誤り）。\",\"other がないと、自分自身も比べる相手にふくまれてしまうので、必ず other をつける。\",\"A is taller than B ＝ B is not as tall as A ＝ B is shorter than A。\",\"低いほうを主語にするときは、not as ～ as または反対の意味の語（shorter）を使う。\",\"A is as old as B ＝ A and B are the same age（同じ程度）。\",\"書きかえたら、数字を入れて順位が同じかどうかを確かめる。\"],\"sections\":[{\"heading\":\"「いちばん」を三つの言い方で言う\",\"body\":\"比較の文は、同じ意味を別の形で書くことができます。入試では、「ほぼ同じ意味になるように（　）に入る語を書きなさい」という書きかえ問題で出ます。\\n\\n■ 最上級の文を三つの形で言う\\n① Lake Biwa is the largest lake in Japan.（最上級）\\n　（琵琶湖は日本でいちばん大きい湖だ）\\n② Lake Biwa is larger than any other lake in Japan.（比較級 ＋ than any other ＋ 単数名詞）\\n　（琵琶湖は日本のほかのどの湖よりも大きい）\\n③ No other lake in Japan is as large as Lake Biwa.（No other ＋ 単数名詞 ＋ as ～ as）\\n　（日本のほかのどの湖も、琵琶湖ほど大きくない）\\n③の形は、No other lake in Japan is larger than Lake Biwa. とも書けます。\\n\\n■ 上と下を入れかえて言う\\nKen is taller than Tom.（ケンはトムより背が高い）\\n＝ Tom is not as tall as Ken.（トムはケンほど背が高くない）\\n＝ Tom is shorter than Ken.（トムはケンより背が低い）\\n\\n■ 同じ程度を言う\\nAya is as old as Mika.（アヤはミカと同じ年だ）\\n＝ Aya and Mika are the same age.\\n\\n★ ここがポイント：最上級は**〈比較級 ＋ than any other ＋ 単数名詞〉**と**〈No other ＋ 単数名詞 ＋ as ～ as〉**で言いかえられる。低いほうを主語にするときは、**not as ～ as か反対の意味の語**を使う。\",\"figureId\":\"xf_gap_gce_05\"},{\"heading\":\"なぜ any other で、なぜ単数なのか\",\"body\":\"書きかえの形は、理由をつかむと忘れなくなります。\\n\\n■ なぜ other が必要なのか\\n「琵琶湖は日本でいちばん大きい」は、日本のほかの湖ぜんぶより大きい、という意味です。ここで other をつけずに、\\n　Lake Biwa is larger than any lake in Japan.\\nと書くと、「日本のどの湖よりも大きい」となり、「日本の湖」の中に琵琶湖自身がふくまれてしまいます。つまり「琵琶湖は琵琶湖より大きい」という、ありえない意味になります。そこで、琵琶湖をのぞく意味の other を入れて any other lake とします。\\n\\n■ なぜ単数形（lake）なのか\\nany は「どれか 1 つを取り出しても」という意味です。ほかの湖を 1 つずつ取り出して、琵琶湖と比べるイメージなので、あとの名詞は単数形になります。\\n　○ any other lake　／　× any other lakes\\n\\n■ なぜ低いほうは not as ～ as になるのか\\nas ～ as は「同じくらい」の形です。Tom is as tall as Ken. は「トムはケンと同じくらい背が高い」という意味です。これに not をつけると、「同じくらいではない（ケンのほうが高い）」になります。そこで、低いほうの人を主語にして、\\n　Tom is not as tall as Ken.\\nと言うと、「ケンのほうが高い」ことを表せます。\\n\\n■ 反対の意味の語を使う方法もある\\ntaller の反対の意味の語は shorter です。Ken is taller than Tom. を、主語を入れかえて Tom is shorter than Ken. とすれば、同じ意味になります。\\n\\n★ ここがポイント：**other がないと自分自身がふくまれてしまう**ので、any other とする。**any は「どれか 1 つ」なので単数**。**not as ～ as は「同じくらいではない」**という形である。\",\"mangaId\":\"gap_gce_05_xm\"},{\"heading\":\"データで確かめる：書きかえの手順\",\"body\":\"書きかえた文が正しいかどうかは、数字を入れて確かめることができます。\\n\\n■ 例：3人の身長\\nKen 160cm／Tom 150cm／Sam 140cm\\n・Ken is taller than Tom.（160 ＞ 150）\\n・Tom is taller than Sam.（150 ＞ 140）\\n・Ken is the tallest of the three.（3人の中でいちばん）\\n・Tom is not as tall as Ken.（150 は 160 ほど高くない）\\n・Sam is not as tall as Tom.（140 は 150 ほど高くない）\\n・Sam is the shortest of the three.（3人の中でいちばん低い）\\n\\n■ 最上級の使い分け\\n・場所や集まりを言うときは in：in Japan、in my class\\n・3つ以上の人やものの中から選ぶときは of：of the three、of all\\n\\n■ 書きかえの手順\\n①もとの文で、だれ（何）がどの順位かを数字で決める。\\n②主語をどちらにするかを決める。\\n③主語が上位なら〈比較級 ＋ than〉、下位なら〈not as ～ as〉か反対の語を使う。\\n④最上級を言いかえるときは、any other ＋ 単数名詞か No other ＋ 単数名詞を使う。\\n\\n■ 形容詞・副詞の形をそろえる\\ntall → taller → the tallest／large → larger → the largest／heavy → heavier → the heaviest\\nas ～ as の間は、原級（もとの形）。as taller as ではない。\\n\\n★ ここがポイント：書きかえは**数字で順位を決める → 主語を決める → 形を選ぶ**の順。**as ～ as の間は原級**、**最上級の言いかえは単数名詞**を忘れない。\"},{\"heading\":\"例題：（　）に入る語を答える\",\"body\":\"手順は、①順位を決める ②主語を決める ③形を選ぶ、の順です。\\n\\n問1　Mt. Fuji is the highest mountain in Japan.\\n　＝ Mt. Fuji is higher than ( ) ( ) mountain in Japan.\\n　「ほかのどの」は any other。mountain は単数形のまま。\\n　答え：any other\\n\\n問2　Mt. Fuji is the highest mountain in Japan.\\n　＝ No ( ) mountain in Japan is higher than Mt. Fuji.\\n　「ほかの」は other。\\n　答え：other\\n\\n問3　Tom is not as tall as Ken.\\n　＝ Ken is ( ) than Tom.\\n　トムはケンほど高くないので、ケンのほうが高い。\\n　答え：taller\\n\\n問4　This bag is lighter than that bag.\\n　＝ That bag is ( ) ( ) light as this bag.\\n　あのかばんのほうが重いので、「ほど軽くない」と言う。as ～ as の間は原級の light。\\n　答え：not as\\n\\n問5　Aya is as old as Mika.\\n　＝ Aya and Mika are the ( ) age.\\n　同じ年なので same。\\n　答え：same\\n\\n★ ここがポイント：**any other ＋ 単数名詞**、**No other ＋ 単数名詞**、**not as ～ as**、the same の四つが書きかえで使う中心の形。問4のように、主語が下位なら not as ～ as になる。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"書きかえた文が、もとの文と同じ意味かどうかを、次の三つで確かめます。\\n\\n■ ①数字を入れて、順位が変わらないか読む\\nKen 160cm／Tom 150cm のとき、\\n　Ken is taller than Tom.（160 ＞ 150）\\n　Tom is not as tall as Ken.（150 は 160 ほど高くない）\\nどちらも「ケンのほうが高い」で同じ順位になるか、1 文ずつ数字で読み返します。\\n\\n■ ②形のきまりを見る\\n・any other のあとは単数名詞か（any other boy ○、boys ×）\\n・other が入っているか（any boy は自分も入る）\\n・as ～ as の間は原級か（as tall as ○、as taller as ×）\\n・than と as をとりちがえていないか（taller than ○、taller as ×）\\n\\n■ ③反対の意味の語で言いかえて確かめる\\nKen is taller than Tom. ＝ Tom is shorter than Ken.\\n主語を入れかえて、反対の意味の語にすると同じ意味になる。これで自分の書きかえをもう一度チェックできます。\\n\\n★ ここがポイント：確かめは**数字で順位を読む → 形のきまり → 反対の語での言いかえ**の三つ。**any other の other と単数形**は、とくに見落としやすい。\"}],\"trapExamples\":[{\"question\":\"「Ken is the tallest boy in his class.」とほぼ同じ意味になるように（　）に入る語を書きなさい。Ken is taller than any ( ) ( ) in his class.\",\"wrongAnswer\":\"other boys\",\"trapExplanation\":\"ほかの男の子たちなので、複数形 boys が自然だと思ってしまう。any のあとは、ひとりずつ取り出して比べる意味なので単数になる。\",\"correctAnswer\":\"other boy\",\"correctExplanation\":\"any は「どれか 1 つ」の意味で、あとの名詞は単数形になる。any other boy が正しい。\"},{\"question\":\"「Lake Biwa is the largest lake in Japan.」を Lake Biwa is larger than any lake in Japan. と書きかえた。まちがいを指摘しなさい。\",\"wrongAnswer\":\"まちがいはない（larger than で比べているから）\",\"trapExplanation\":\"比較級の than を使っているので正しく見えるが、any lake の中に琵琶湖自身が入ってしまうことに気づかない。\",\"correctAnswer\":\"any のあとに other がない。Lake Biwa is larger than any other lake in Japan. にする。\",\"correctExplanation\":\"other がないと「琵琶湖は琵琶湖より大きい」という意味になってしまう。琵琶湖をのぞくために、any other lake と言う。\"}]}",
"{\"id\":\"gap_gce_06\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"（　）内の語を正しい形に直す：空所の前後から形を決める\",\"description\":\"（　）内の語を文に合う形に直す問題で、空所の前後の語と時を表す語から必要な形を決める手順を学ぶ\",\"intro\":\"「I (go) to the library yesterday.」のように、（　）の中の語を文に合う形に直して書く問題は、中学入試の英語でとてもよく出ます。go をそのまま書いてもまちがいで、went と書かなければなりません。どの形にするかは、じつは空所のまわりにある「合図」で決まります。その合図の見つけ方を、順番に学びます。\",\"order\":20405,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"形を決める合図は、①時を表す語（yesterday・every day）②空所の直前の語（to・can・enjoy）③主語の数（he・they）の三つ。\",\"主語が三人称単数で現在の文では、動詞に s／es をつける（plays・studies）。\",\"yesterday・last 〜・ago があれば過去形（went・bought・wrote）。\",\"to・can・will・must・do/does/did のあとは原形。enjoy・finish・前置詞のあとは〜ing。\",\"have／has のあとは過去分詞。am・is・are のあとは〜ing（している）か過去分詞（される）。\",\"two・three・many のあとは複数形（women・children）。than があれば比較級、the ... of/in があれば最上級。\",\"答えが 2 語になる場合もある（to be、most interesting）。つづりの変化も確かめる。\"],\"sections\":[{\"heading\":\"直す前に「何の形か」を決める\",\"body\":\"（　）内の語を直す問題は、いきなり形を書かず、まず「どんな形が必要か」を決めます。決める手がかりは、空所のまわりにあります。\\n\\n■ 空所の前後で形が決まる\\n・主語が he・she・it など単数で、現在の文 → 動詞に s／es（plays・studies）\\n・yesterday・last night・〜 ago がある → 過去形（went・bought）\\n・can・will・must・do/does/did のあと → 原形\\n・to のあと → 原形（want to be）\\n・enjoy・finish・stop・前置詞（of・about）のあと → 〜ing（enjoy talking）\\n・am・is・are のあと → 〜ing（している）／過去分詞（される）／形容詞\\n・have・has のあと → 過去分詞（has finished）\\n・two・three・many のあと → 複数形（women・children・boxes）\\n・than のある文 → 比較級（bigger）\\n・the ... in／of のある文 → 最上級（the biggest）\\n\\n■ 2語になることもある\\n問題の中には「2語になる場合もあります」と書いてあるものがあります。\\n　I want (be) a pilot. → to be（2語）\\n　This is the (interesting) book of the three. → most interesting（2語）\\n\\n■ 答えを書くとき\\n形を直して書き、もとの語は残さない。（　）の中の語そのものではなく、直した形を答えにします。\\n\\n★ ここがポイント：形を決める合図は**時を表す語・直前の語・主語の数**の三つ。2語になることもあるので、**文末まで読んで**から答える。\",\"figureId\":\"xf_gap_gce_06\"},{\"heading\":\"なぜ形が変わるのか：英語は「合図」で形を決める\",\"body\":\"go のままではなぜだめなのでしょうか。\\n\\n■ 辞書の形のままでは使えない\\n英語の動詞は、辞書にのっている形（原形）だけでは、文の中で使えないことが多いのです。時（過去か現在か）、主語の数（ひとりか、複数か）、前にある語（to や can など）によって、形が変わります。\\n\\n■ 三つの合図\\n①時の語：yesterday があれば、過去の話。go を went にする。\\n②直前の語：to のあとなら原形、enjoy のあとなら〜ing。\\n③主語の数：he・she・it なら、現在形の動詞に s をつける。\\n\\n■ enjoy には〜ing、want には to がつくのはなぜか\\n・enjoy・finish・stop のあとは〜ing：すでに起きている、または現実にしていることを表す。\\n　例）I enjoyed talking with her.（彼女と話して楽しかった）\\n・want・hope・decide のあとは to ＋ 原形：これからすること、まだしていないことを表す。\\n　例）I want to be a pilot.（パイロットになりたい）\\n「これから」の動作には to がつく、と考えると、見分けやすくなります。\\n\\n■ もう一つの合図：文の意味\\nam・is・are のあとが〜ing なら「している」、過去分詞なら「される」です。\\n　The boy is playing.（している）／ The window is broken.（こわされている）\\n　訳してみて、意味が合うほうを選びます。\\n\\n★ ここがポイント：形は**時・直前の語・主語**で決まる。**enjoy・finish は〜ing（すでにしていること）**、**want・hope・decide は to（これからすること）**と考える。\",\"mangaId\":\"gap_gce_06_xm\"},{\"heading\":\"つづりの変え方の確認\",\"body\":\"形を決めたら、つづりを正しく変えます。つづりのまちがいも失点になります。\\n\\n■ 三人称単数現在の s／es\\nplay → plays／study → studies（y を i に変えて es）／watch → watches／go → goes／have → has\\n\\n■ 過去形\\n規則動詞：play → played／study → studied／stop → stopped（p を重ねる）\\n不規則動詞：go → went／buy → bought／write → wrote／see → saw／eat → ate\\n\\n■ 〜ing\\nplay → playing／write → writing（e をとる）／run → running（n を重ねる）\\n\\n■ 過去分詞\\nfinish → finished／study → studied／write → written／see → seen／eat → eaten\\n\\n■ 比較級と最上級\\nbig → bigger → biggest（g を重ねる）／heavy → heavier → heaviest（y を i に）／large → larger → largest（e だけ足す）\\n長い語：interesting → more interesting → most interesting\\n\\n■ 複数形\\nchild → children／woman → women／box → boxes／city → cities／watch → watches\\n\\n■ 注意：不規則変化は覚えるしかない\\ngo → went → gone、write → wrote → written のように、形が大きく変わる動詞は、過去形と過去分詞を組にして覚えておきます。\\n\\n★ ここがポイント：つづりは**y → i、重ねる、e をとる、es をつける**の四つの型で確かめる。**不規則動詞は過去形と過去分詞を組**で覚える。\"},{\"heading\":\"例題：形を直して書く\",\"body\":\"手順は、①空所の前後と時を表す語を見る ②必要な形を決める ③つづりを確かめる、の順です。\\n\\n問1　Ken (play) soccer every Sunday.\\n　主語は Ken（単数）で、every Sunday は習慣を表す現在の文。動詞に s をつける。\\n　答え：plays\\n\\n問2　We saw two (woman) at the station.\\n　two のあとなので複数形。woman の複数形は women（不規則）。\\n　答え：women\\n\\n問3　She (write) a letter last night.\\n　last night があるので過去形。write の過去形は wrote。\\n　答え：wrote\\n\\n問4　This box is (heavy) than that one.\\n　than があるので比較級。heavy は y を i に変えて er をつける。\\n　答え：heavier\\n\\n問5　I enjoyed (talk) with her.\\n　enjoy のあとは〜ing。talk に ing をつける。\\n　答え：talking\\n\\n問6　I want (be) a pilot.\\n　want のあとは to ＋ 原形（2語）。\\n　答え：to be\\n\\n問7　He has (finish) his homework.\\n　has のあとは過去分詞。finish に ed をつける。\\n　答え：finished\\n\\n問8　This is the (interesting) book of the three.\\n　the ... of the three なので最上級。interesting は長い語なので most をつける（2語）。\\n　答え：most interesting\\n\\n★ ここがポイント：**時の語・直前の語・主語の数**で形を決める。問6・問8のように**2語になる**ことも多いので、答えを書く前に文全体を読み直す。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"書いた答えを、次の五つで確かめます。\\n\\n■ ①入れた形で文を声に出して読む\\nKen plays soccer every Sunday. のように、できあがった文全体を読み、おかしい所がないかを確かめます。\\n\\n■ ②日本語に訳して意味が合うか\\n「ケンは毎週日曜日にサッカーをする」と訳せれば、plays で合っています。過去の話なのに現在形、という食いちがいはここで見つかります。\\n\\n■ ③合図を指でさして確認する\\n「yesterday があるから過去形」「enjoy のあとだから〜ing」「two のあとだから複数形」のように、どの合図でその形にしたのかを、自分に説明できるかを見ます。説明できない答えは、まちがいの可能性があります。\\n\\n■ ④つづりを 1 字ずつ見る\\nheavier の y が i に変わっているか、running の n が重なっているか、women の o が e に変わっているか、のように、つづりの型で確かめます。\\n\\n■ ⑤2語になる答えを見落としていないか\\n「2語になる場合もあります」と書いてある問題では、to be や most interesting のように、2語の答えがないかを見直します。\\n\\n★ ここがポイント：確かめは**文を読む → 日本語訳 → 合図を説明する → つづり → 2語**の順。**合図を説明できない答えは疑う**。\"}],\"trapExamples\":[{\"question\":\"次の（　）内の語を適する形にしなさい。「I enjoyed (play) tennis with Ken.」\",\"wrongAnswer\":\"to play\",\"trapExplanation\":\"「〜すること」を表すときは to ＋ 原形と覚えていて、enjoy のあとでも to をつけてしまう。enjoy は〜ing だけをあとにとる動詞である。\",\"correctAnswer\":\"playing\",\"correctExplanation\":\"enjoy・finish・stop のあとは〜ing をとる。「ケンとテニスをして楽しんだ」。want や hope などの to をとる動詞とは区別する。\"},{\"question\":\"次の（　）内の語を適する形にしなさい。「She (go) to the library yesterday.」\",\"wrongAnswer\":\"goes\",\"trapExplanation\":\"主語が She（三人称単数）なので s をつけるとだけ考え、yesterday という時の語を見落としている。\",\"correctAnswer\":\"went\",\"correctExplanation\":\"yesterday があるので過去の文。go の過去形は不規則に変わって went になる。過去形では、主語が三人称単数でも s はつかない。\"}]}",
"{\"id\":\"gap_gce_07\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"title\":\"used to 〜：「以前は〜したものだ」と今とのちがい\",\"description\":\"「以前は〜だった（今はちがう）」を表す used to の意味と形、would や be used to とのちがいを整理する\",\"intro\":\"I used to play soccer every weekend, but now I play tennis.（以前は毎週末サッカーをしていたが、今はテニスをしている）。この used to は、今はもうしていないことを表します。ところが I am used to getting up early. のように、同じ used to でもまったく意味のちがう形があります。「以前は〜」の used to と、まぎらわしい形のちがいを、理由とともに整理します。\",\"order\":20406,\"studyPeriod\":\"小6後半・直前\",\"targetLevel\":\"oyo\",\"keyPoints\":[\"〈used to ＋ 動詞の原形〉は「以前は〜したものだ（習慣）」「以前は〜だった（状態）」。今はそうではない。\",\"動作にも状態にも使える（used to play、used to be、used to live）。\",\"否定・疑問は did を使い、used は use にもどる（didn't use to、Did you use to 〜?）。\",\"過去形（played）は「過去にした」だけ。used to は「今とはちがう」という対比がふくまれる。\",\"would も「以前は〜したものだ」を表すが、動作だけで、状態（be・live・like）には使えない。\",\"〈be動詞 ＋ used to ＋ 名詞／〜ing〉は「〜に慣れている」。まったく別の形。\",\"〈be動詞 ＋ used to ＋ 原形〉は「〜するために使われる」（受け身）。\"],\"sections\":[{\"heading\":\"used to の意味と形\",\"body\":\"used to は、今とくらべて「以前はそうだった」ということを表す言い方です。\\n\\n■ 形：〈used to ＋ 動詞の原形〉\\nused の読み方は「ユースト」です。to のあとは、動詞の原形が続きます。\\n\\n■ 意味\\n①以前は〜したものだ（過去の習慣）\\n　I used to play soccer every weekend, but now I play tennis.\\n　（以前は毎週末サッカーをしていたが、今はテニスをしている）\\n②以前は〜だった（過去の状態）\\n　There used to be a small shop at the corner.（角には以前、小さな店があった）\\n　He used to be shy.（彼は以前はおとなしかった）\\n　She used to live in Osaka.（彼女は以前、大阪に住んでいた）\\nどちらも、今はそうではない、という意味をふくんでいます。\\n\\n■ 否定文・疑問文\\n否定文や疑問文では did を使い、used は use にもどります。\\n　I didn't use to like fish.（私は以前は魚が好きではなかった）\\n　Did you use to walk to school?（あなたは以前は歩いて通学していましたか）\\n　— Yes, I did. / No, I didn't.\\n\\n■ よく使われる語句\\nwhen I was a child（子どものころ）、years ago（何年も前に）、but now（でも今は）\\n\\n★ ここがポイント：used to は**「以前は〜、でも今は〜ではない」**という対比を表す。**否定・疑問は did を使い、used は use にもどる**。\",\"figureId\":\"xf_gap_gce_07\"},{\"heading\":\"なぜ過去形ではなく used to なのか／would とのちがい\",\"body\":\"「以前は〜した」なら、過去形（played）でも言えそうです。なぜ used to を使うのでしょうか。\\n\\n■ 過去形は「過去にした」だけを言う\\nI played soccer. は、過去にサッカーをした、という事実を言うだけです。今もしているのか、やめたのかは、この文からはわかりません。\\n\\n■ used to は「今とはちがう」まで伝える\\nI used to play soccer. と言うと、「以前はしていたが、今はしていない」という意味まで伝わります。今と過去を比べて、変化を表したいときに使います。\\n\\n■ would とのちがい\\nwould も「以前は〜したものだ」（過去の習慣）を表すことができます。\\n　When I was a child, I would play soccer every weekend.\\n　= When I was a child, I used to play soccer every weekend.\\nただし would は、動作のくり返しだけに使います。状態を表す動詞（be・live・have・like）には使えません。\\n　○ I used to be shy.（私は以前はおとなしかった）\\n　× I would be shy.\\n　○ There used to be a shop here.（ここには以前、店があった）\\n　× There would be a shop here.\\n動作の習慣ならどちらでも言えますが、状態は used to だけです。また、would は when I was a child のように、いつのことかを示す語句といっしょに使うのがふつうです。\\n\\n■ 選び方のまとめ\\n・動作のくり返し（習慣）→ used to でも would でもよい\\n・状態（be・live・like など）→ used to だけ\\n・今との対比をはっきり示したい → used to\\n\\n★ ここがポイント：**過去形は「過去にした」だけ**、**used to は「今とはちがう」まで伝える**。**状態には would を使えない**。\"},{\"heading\":\"まぎらわしい形：be used to と used to\",\"body\":\"used to と形が似ていて、意味がまったくちがう言い方があります。\\n\\n■ ①〈used to ＋ 動詞の原形〉：以前は〜したものだ\\n　I used to get up late.（私は以前、おそく起きていた）\\n\\n■ ②〈be動詞 ＋ used to ＋ 名詞／〜ing〉：〜に慣れている\\n　I am used to getting up early.（私は早起きに慣れている）\\n　He is used to the cold weather.（彼は寒い天気に慣れている）\\n　この used は「慣れている」という意味の形容詞で、to は「〜に」の意味の前置詞です。前置詞のあとなので、動詞は〜ing の形になります。\\n\\n■ ③〈be動詞 ＋ used to ＋ 動詞の原形〉：〜するために使われる\\n　This knife is used to cut bread.（このナイフはパンを切るために使われる）\\n　これは use（使う）の受け身で、to は「〜するために」の意味です。\\n\\n■ 見分け方\\n1. used の前に be動詞（am・is・are・was）があるか\\n　なければ ① の used to（以前は〜）。\\n2. be動詞があるとき、to のあとが〜ing か名詞なら ② の「慣れている」\\n3. be動詞があるとき、to のあとが原形なら ③ の「〜するために使われる」\\n\\n■ 三つを並べて確かめる\\nI used to get up early.（以前は早起きしていた）\\nI am used to getting up early.（早起きに慣れている）\\nA bell is used to wake people up.（ベルは人を起こすために使われる）\\n\\n★ ここがポイント：**used の前に be動詞があるか**、**to のあとが原形か〜ingか**で見分ける。「以前は」「慣れている」「使われる」の三つの意味を区別する。\",\"mangaId\":\"gap_gce_07_xm\"},{\"heading\":\"例題：used to を使って文を完成させる\",\"body\":\"手順は、①今とはちがう話か ②be動詞があるか ③to のあとは原形か〜ingか、の順です。\\n\\n問1　「私は以前、毎日ここを走っていました（今は走っていません）。」\\n　I ( ) ( ) run here every day.\\n　「以前は〜」で今はしていないので used to。run は原形。\\n　答え：used to\\n\\n問2　「このへんには以前、大きな木がありました。」\\n　There ( ) ( ) be a big tree around here.\\n　状態を表す「以前は〜があった」。would は使えないので used to。\\n　答え：used to\\n\\n問3　「あなたは以前、歩いて通学していましたか。」\\n　( ) you ( ) ( ) walk to school?\\n　疑問文は did を使い、used は use にもどる。\\n　答え：Did / use to\\n\\n問4　「私は早起きに慣れています。」\\n　I am ( ) ( ) getting up early.\\n　be動詞があり、あとが〜ing なので「〜に慣れている」。\\n　答え：used to\\n\\n問5　「このナイフはパンを切るために使われる。」\\n　This knife is ( ) ( ) cut bread.\\n　be動詞があり、to のあとが原形（cut）なので「〜するために使われる」。\\n　答え：used to\\n\\n★ ここがポイント：問1・問2・問4・問5は、**答えはどれも used to という同じ2語**だが、**意味は be動詞の有無と to のあとの形**で決まる。問3のように**疑問文では use to**。\"},{\"heading\":\"確かめ（検算）のしかた\",\"body\":\"答えを書いたあとに、次の四つで確かめます。\\n\\n■ ①「今とはちがう」話かを考える\\n「以前は〜、今は〜ない」と日本語で言えるなら、used to ＋ 原形です。\\n例）私は以前ここで泳いだ（今は泳がない）→ I used to swim here.\\n\\n■ ②be動詞があるかを見る\\nbe動詞（am・is・are・was・were）があれば、used to は「以前は」の意味ではありません。「慣れている」か「使われる」のどちらかです。\\n\\n■ ③to のあとの形を見る\\n・原形 → 以前は〜した（be動詞なし）／〜するために使われる（be動詞あり）\\n・〜ing や名詞 → 〜に慣れている\\n\\n■ ④疑問文・否定文では use to になっているか\\nDid you used to 〜? や didn't used to 〜 のように、did を使うのに used のままにしていないかを見ます。\\n例）Did you use to walk to school? ○　／　Did you used to walk to school? ×\\n\\n★ ここがポイント：確かめは**「今とはちがう」か → be動詞があるか → to のあとの形 → 疑問文・否定文の use** の順。**did があるのに used のまま**は、よくあるまちがい。\"}],\"trapExamples\":[{\"question\":\"次の文のまちがいを直しなさい。「I am used to get up early.」（私は早起きに慣れています）\",\"wrongAnswer\":\"まちがいはない（used to のあとは原形だから）\",\"trapExplanation\":\"「used to のあとは原形」と覚えているため、be動詞があっても get をそのまま使ってしまう。be used to のときの to は前置詞で、あとは〜ing になる。\",\"correctAnswer\":\"I am used to getting up early.\",\"correctExplanation\":\"〈be動詞 ＋ used to〉は「〜に慣れている」の意味で、to は前置詞。前置詞のあとの動詞は〜ing の形にする。\"},{\"question\":\"次の文のまちがいを直しなさい。「She would be shy when she was young.」（彼女は若いころ、おとなしかった）\",\"wrongAnswer\":\"まちがいはない（would も「以前は」を表すから）\",\"trapExplanation\":\"would も used to と同じ意味だと覚えているため、be を使った文にもそのまま使ってしまう。would は動作のくり返しにしか使えない。\",\"correctAnswer\":\"She used to be shy when she was young.\",\"correctExplanation\":\"be は状態を表す動詞なので would は使えない。状態の「以前は〜だった」は used to を使って表す。\"}]}",
"{\"id\":\"nt_ntce_01\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"order\":30451,\"targetLevel\":\"oyo\",\"title\":\"聞き取りの型：thirteen と thirty、言い直しに気をつける\",\"description\":\"13と30、15と50などの聞き分けと、時刻・ねだんの聞き取り、言い直しのひっかけを学ぶ\",\"intro\":\"ホームの放送で「次の電車は6時15分です」と聞こえたのに、じつは6時50分だった。そんな聞きまちがいは、英語の聞き取りテストでもよく起こります。数字は、聞き取りで点を取りやすい分、まちがえると大きく失点します。聞き分けのコツと、言い直しのひっかけを身につけましょう。\",\"keyPoints\":[\"thirteen（13）は後ろの teen を強く長く、thirty（30）は前の thir を強く読む\",\"14 と 40、15 と 50、19 と 90 も同じ型。fourteen には u があるが、forty には u がない\",\"時刻（six fifteen と six fifty）やねだん（fifteen dollars と fifty dollars）も、分かれ目は後ろの音の強さ\",\"曜日は Tuesday（チューズデー）と Thursday（サーズデー）の最初の音で聞き分ける\",\"Oh, sorry.／I mean ...／Wait. は言い直しの合図。あとに言った数が答えになる\",\"聞こえた数は、ことばではなく数字ですぐにメモする\",\"メモは声に出して読み、強く読む場所が聞こえた音と合うか確かめる\"],\"sections\":[{\"heading\":\"1. 13 と 30 のちがい：強く読む場所で聞き分ける\",\"level\":\"oyo\",\"figureId\":\"xf_nt_ntce_01\",\"body\":\"聞き取りで、いちばん聞きまちがえやすいのが、13 と 30 のような組である。書くと thirteen と thirty で、どちらも「サーティ…」と聞こえる。ちがいは、強く読む場所である。\\n\\n■ 強く読む場所\\n　13（thirteen）：後ろの teen を強く、長く読む。「サーティーン」\\n　30（thirty）：前の thir を強く読み、ty は弱く短く読む。「サーティ」\\n\\n■ 同じ型の数\\n　14 fourteen と 40 forty\\n　15 fifteen と 50 fifty\\n　16 sixteen と 60 sixty\\n　19 nineteen と 90 ninety\\n\\n■ つづりにも気をつける\\nfourteen は u がある（four-teen）が、forty には u がない。ninety は e が残る。つづりが変わる数は、書き取りでも出やすい。\\n\\n★ ここがポイント：-teen は **後ろを強く長く**、-ty は **前を強く、後ろは弱く短く** 読む。聞くときは、数字の最後の音が **強く長いか、弱く短いか** に耳を向ける。\\n\\n⚠ 注意：13 から 19 の数は、どれも「後ろの -teen」が強い。「ティーン」が長く聞こえたら、-teen の数と考える。\"},{\"heading\":\"2. なぜ強く読む場所がちがうのか\",\"level\":\"oyo\",\"body\":\"■ 英語は「大切なところを強く言う」ことば\\n日本語は、ほとんどの音を同じ強さで読む。英語は、その言葉でいちばん大切な部分を強く、長く言う。そうすると、聞き手は大切な部分を聞きのがさない。\\n\\n■ なぜ teen と ty でちがうのか\\nteen は、「10をたした数」という意味をもつ大切な部分である。thirteen（3＋10）の中心は teen にあるので、ここを強く言って知らせる。いっぽう thirty の ty は、「10が3つ」を表すしるしにすぎない。大切なのは前の thir（3）なので、前を強く言って、ty は弱く短く言う。\\n\\n■ なぜ時刻やねだんでも同じなのか\\nsix fifteen（6時15分）と six fifty（6時50分）は、分のところが fifteen か fifty かだけがちがう。分の数字は、-teen か -ty かで強さが変わる。ねだんも同じで、fifteen dollars と fifty dollars は、後ろの音の強さで聞き分ける。\\n\\n■ 曜日の聞き分け\\nTuesday と Thursday は、最初の音がちがう。Tuesday は「チュー」、Thursday は「サー」と始まる。曜日は、最初の音に注目する。\\n\\n★ ここがポイント：英語は **大切な部分を強く長く** 言う。teen は大切な部分なので **後ろが強く**、ty は **前が強い**。この理由がわかれば、丸暗記しなくても聞き分けられる。\\n\\n⚠ 注意：強く読む場所は、文の中では少しわかりにくくなる。そのときは、前後の言葉（時刻なら o'clock や a.m. など）も手がかりにする。\"},{\"heading\":\"3. 時刻・ねだん・曜日の聞き取りの型\",\"level\":\"oyo\",\"body\":\"■ 時刻\\n　It is six fifteen.　→ 6:15\\n　It is six fifty.　→ 6:50\\n分のところで、-teen か -ty かを聞き分ける。「時」と「分」の2つの数を、続けて6:15のように数字で書く。\\n\\n■ ねだん\\n　It is fifteen dollars.　→ 15ドル\\n　It is fifty dollars.　→ 50ドル\\nねだんは、ほかの数と取りちがえやすい。聞こえたらすぐ、数字だけをメモする。\\n\\n■ 曜日\\n　Tuesday（火）と Thursday（木）、Saturday（土）と Sunday（日）はまぎらわしい。最初の音を聞いて、メモに書く。\\n\\n■ 聞き取りの手順\\n①放送の前に、問題文を読んで、何を聞かれるか（時刻・ねだん・曜日）を知る。\\n②放送では、その数や語が出たら、すぐメモする。\\n③放送が終わったら、メモを見て、選択肢を選ぶ。\\n\\n★ ここがポイント：聞き取りは **先に問題を読み**、聞かれることを知っておく。数は **ことばでなく数字で** 、すぐにメモする。\\n\\n⚠ 注意：メモを「thirteen」と英語で書くと、時間がかかって次の放送を聞きのがす。13 のように数字で書く。\"},{\"heading\":\"4. 言い直しのひっかけ：さいごの数が答え\",\"level\":\"oyo\",\"body\":\"■ 言い直しとは\\n放送では、話している人がまちがえて、すぐ言い直すことがある。入試では、これをひっかけに使う問題がよく出る。\\n\\n■ 言い直しの合図\\n　Oh, sorry.（あ、ごめんなさい）\\n　I mean ...（つまり…）\\n　Wait.（待って）\\n　No, ...（いいえ、…）\\nこれが聞こえたら、あとに言った数が、本当の答えである。\\n\\n■ 例\\n　The concert starts at six thirty. Oh, sorry. It starts at seven thirty.\\n前の six thirty は言いまちがいなので、答えは 7:30 である。\\n\\n■ なぜこのひっかけが出るのか\\nふつうの会話では、人はよく言いまちがえて、すぐ直す。聞き取りで本当に大切なのは、数を聞き取ることではなく、最後に伝えたかった数を聞き取ることだからである。先に聞こえた数だけを書くと、まちがいになる。\\n\\n★ ここがポイント：言い直しの合図が聞こえたら、**前の数に線を引き**、**あとの数を書く**。答えは **最後に言った数** である。\\n\\n⚠ 注意：合図が聞こえないのに、前の数をすぐ消さないこと。合図があったときだけ、あとの数に切りかえる。\"},{\"heading\":\"5. 声に出して確かめる手順\",\"level\":\"oyo\",\"body\":\"英語の聞き取りには、計算の検算のかわりになる「声に出して確かめる手順」がある。\\n\\n■ 手順\\n①メモの数字を、英語で声に出して読む。（例：6:15 → six fifteen）\\n②-teen の数は後ろを強く、-ty の数は前を強く読んでみる。\\n③その読み方が、耳に残っている放送の音と同じかどうかを思い出す。\\n④ちがう気がしたら、もう一方の数でも読んでみて、どちらが近いかをくらべる。\\n⑤言い直しがあったかどうかも、思い出して確かめる。\\n\\n■ なぜ声に出すのか\\n耳で聞いた音と、自分の口で出した音を比べると、強さのちがいがはっきりわかるからである。目で見ただけでは、どちらの数か判断できない。\\n\\n■ ふだんの練習\\n13 と 30、14 と 40 のように、組になった数を、手をたたきながら読む。-teen は後ろで手をたたき、-ty は前で手をたたく。強さの場所が体でわかるようになる。\\n\\n★ ここがポイント：メモした数は、**声に出して** 強さを確かめる。**手をたたきながら** 練習すると、-teen と -ty の強さの場所が体でわかる。\\n\\n⚠ 注意：テスト中は、小さく口を動かすだけでもよい。大声で読まないように注意する。\"}],\"trapExamples\":[{\"question\":\"放送：The bus leaves at four fifty. Oh, sorry. I mean four fifteen. バスは何時何分に出ますか。\",\"wrongAnswer\":\"4時50分\",\"trapExplanation\":\"先に聞こえた four fifty をメモして、そのままにしてしまう。放送の中の Oh, sorry. I mean ... は言い直しの合図で、あとに言った数が本当の答えになる。\",\"correctAnswer\":\"4時15分\",\"correctExplanation\":\"話した人は、four fifty と言いまちがえて、Oh, sorry. I mean four fifteen. と言い直した。答えは、あとに言った four fifteen（4:15）である。確かめとして、4:15 を声に出して読むと、fifteen は teen が強く長く聞こえる。\"},{\"question\":\"放送：It is fifteen dollars. 「ティーン」の部分が強く長く聞こえました。ねだんはいくらですか。数字で答えなさい。\",\"wrongAnswer\":\"50ドル\",\"trapExplanation\":\"fifteen と fifty を同じ音だと思って、聞きまちがえる。強く読む場所がちがうことを知らないと、取りちがえる。\",\"correctAnswer\":\"15ドル\",\"correctExplanation\":\"-teen は後ろを強く長く読むので、「ティーン」が強く長く聞こえたら fifteen（15）である。fifty（50）は前の fif を強く読み、ty は弱く短い。\"}]}",
"{\"id\":\"nt_ntce_02\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"order\":30452,\"targetLevel\":\"oyo\",\"title\":\"環境とSDGsの英文：reduce・reuse・recycle と身近な行動\",\"description\":\"3つのRの意味、SDGsの目標、レジ袋有料化を使って、環境を守る行動を英語で言う\",\"intro\":\"スーパーでレジ袋をもらわず、自分のエコバッグを持っていく。そんな行動は、英語で説明できるでしょうか。最近の入試では、環境やSDGsについての短い英文が出ることがふえています。むずかしい言葉は使わず、身近な行動を、短い文で言えるようにしましょう。\",\"keyPoints\":[\"reduce は「へらす」、reuse は「くり返し使う」、recycle は「作り直す」\",\"ごみ対策は reduce が最初。出さないことがいちばん大切\",\"SDGs は2015年に国連で決まった、2030年までの17の目標\",\"Goal 12 は「つくる責任 つかう責任」、Goal 14 は「海の豊かさを守ろう」\",\"日本では2020年7月から、プラスチック製のレジ袋が有料になった\",\"自分の行動は、「行動」と「なぜよいか」の2文で言う\",\"plastic bag（レジ袋）、bottle（びん・ペットボトル）、trash（ごみ）などの語彙を覚える\"],\"sections\":[{\"heading\":\"1. 3つのR：reduce・reuse・recycle\",\"level\":\"oyo\",\"figureId\":\"xf_nt_ntce_02\",\"body\":\"ごみを少なくするための行動は、英語で「3つのR」と言う。\\n\\n■ 3つの意味\\n　reduce（リデュース）：へらす。ごみになる物を、そもそも使わない、もらわない。\\n　reuse（リユース）：くり返し使う。すてずに、もう一度使う。\\n　recycle（リサイクル）：作り直す。使い終わった物をとかして、別の物にする。\\n\\n■ 英文の例\\n　I bring my own bag.　（自分のふくろを持っていく）→ reduce\\n　We use old T-shirts as cloths.　（古いシャツをぞうきんにする）→ reuse\\n　We recycle cans and bottles.　（かんやびんを作り直す）→ recycle\\n\\n■ 動詞を見れば、どのRかがわかる\\n文の中の動詞（bring・use・recycle）と、何をどうするかを見れば、どのRなのかがわかる。\\n\\n★ ここがポイント：**reduce はへらす**、**reuse はくり返し使う**、**recycle は作り直す**。英文は、動詞を見てどのRかを見分ける。\\n\\n⚠ 注意：reuse と recycle はよく取りちがえる。形を変えずにもう一度使うのが reuse、形を変えて別の物にするのが recycle である。\"},{\"heading\":\"2. なぜ reduce が最初なのか\",\"level\":\"oyo\",\"body\":\"■ 3つには順番がある\\nごみ対策では、reduce → reuse → recycle の順に大切だと考えられている。\\n\\n■ なぜ reduce がいちばんなのか\\nごみを出さなければ、ごみを集めたり、運んだり、処理したりする手間が、そもそも必要ないからである。出てしまったごみを後から片づけるより、出さないほうが、むだがない。\\n\\n■ なぜ reuse が2番目なのか\\nreuse は、ごみにする前に、もう一度使う方法である。物の形を変えずに使うので、作り直すための手間や電気がかからない。\\n\\n■ なぜ recycle が最後なのか\\nrecycle は、使い終わった物を集めて運び、とかして、別の物に作り直す。この間にも、運ぶ燃料や、作り直す電気が必要になる。だから、recycle はとても大切だが、reduce や reuse ができるときは、そちらを先に考える。\\n\\n■ 日本のレジ袋の話\\n日本では、2020年7月から、プラスチック製のレジ袋が有料になった。目的は、あたり前のようにもらっていたレジ袋が本当に必要か、考え直すきっかけにするためである。これは reduce の第一歩である。英語では、In July 2020, Japan started charging for plastic shopping bags. と言える。charge は「お金を取る」の意味である。\\n\\n★ ここがポイント：ごみは **出さないことがいちばん** 。出してしまったら **くり返し使い**、それでも使えなくなったら **作り直す**。\\n\\n⚠ 注意：「recycle すればごみを出しても大丈夫」という考えはまちがいである。作り直すときにも、電気や燃料を使う。\"},{\"heading\":\"3. SDGsの英文を読む\",\"level\":\"oyo\",\"body\":\"■ SDGsとは\\nSDGs（エス・ディー・ジーズ）は、2015年に国連で決まった、世界共通の目標である。2030年までに達成することを目ざしていて、目標は全部で17ある。\\n\\n■ ごみや海に関係の深い目標\\n　Goal 12：Responsible Consumption and Production（つくる責任 つかう責任）\\n　Goal 14：Life Below Water（海の豊かさを守ろう）\\n　Goal 13：Climate Action（気候変動に具体的な対策を）\\n\\n■ 英文の例\\n　Plastic bags can hurt sea animals.　（プラスチックのふくろは、海の動物をきずつけることがある）\\n　We should reduce plastic trash.　（わたしたちはプラスチックごみをへらすべきだ）\\n\\nshould は「〜すべきだ」という意味で、あとの動詞は原形になる。\\n\\n■ なぜ Goal 12 が reduce に関係するのか\\n「つくる責任 つかう責任」は、物をつくる人も、使う人も、むだを出さないように責任をもとう、という目標である。使う人の責任として、必要な分だけ使うことは、reduce につながる。\\n\\n★ ここがポイント：SDGs は **2015年に国連で決まり**、**2030年まで**の **17の目標** である。ごみは Goal 12、海は Goal 14 に関係が深い。\\n\\n⚠ 注意：should のあとには、動詞の原形が来る。We should reduce ... は正しく、We should reduces ... とは書かない。\"},{\"heading\":\"4. 自分の行動を2文で言う型\",\"level\":\"oyo\",\"body\":\"■ 型\\nスピーキングや英作文では、自分の行動を、2つの文で言うと伝わりやすい。\\n　1文目：何をしているか（行動）\\n　2文目：なぜよいか（よさ）\\n\\n■ 例\\n　I bring my own bag. It helps the sea.\\n　（わたしは自分のふくろを持っていきます。それは海のためになります。）\\n\\n　We recycle cans. It saves resources.\\n　（わたしたちはかんを作り直します。それは資源を守ります。）\\n\\nhelp は「助ける・役に立つ」、save は「守る・ためる」の意味である。\\n\\n■ なぜ2文にするのか\\n行動だけを言っても、聞いた人は「なぜそれをするの？」と思う。2文目でよさを足せば、行動の意味まで伝わる。2文とも短くてよい。\\n\\n■ 理由を述べるとき\\nbecause を使うと、1文で言える。\\n　I bring my own bag because it reduces plastic trash.\\n（プラスチックごみをへらすので、わたしは自分のふくろを持っていきます。）\\n\\n★ ここがポイント：行動は **「行動」＋「なぜよいか」の2文** で言う。**短い文を2つ** 並べれば十分に伝わる。\\n\\n⚠ 注意：it は、1文目の行動全体を指す。2文目の主語を it にして、動詞に三単現の s をつける（It helps ...）のを忘れない。\"},{\"heading\":\"5. 声に出して確かめる手順\",\"level\":\"oyo\",\"body\":\"英文を書いたり話したりしたあとは、声に出して確かめる。\\n\\n■ 手順\\n①文を、声に出して読む。つっかえた所があれば、その語を確かめる。\\n②1文目の動詞は何か（bring・use・recycle など）を指で押さえる。\\n③2文目の主語が it のとき、動詞に s がついているかを確かめる。\\n④reduce・reuse・recycle のどれの行動かを、日本語で言いかえてみる。\\n⑤長すぎる文は、2つに切って言い直す。\\n\\n■ なぜ声に出すのか\\n目だけで見ると、s のぬけや、動詞のまちがいに気づきにくい。口に出すと、読みにくいところが、文のまちがいの手がかりになる。\\n\\n■ ふだんの練習\\n自分がふだんしている行動を、1日に1つ、英語で言ってみる。「bag」「bottle」「trash」の3語は、いつも使えるようにしておく。\\n\\n★ ここがポイント：文は **声に出して** 確かめ、**動詞** と **主語に合った s** を見直す。長い文は **2つに切る**。\\n\\n⚠ 注意：知らない語は、無理に使わない。知っている語で言いかえるほうが、まちがいが少ない。\"}],\"trapExamples\":[{\"question\":\"「古いシャツをぞうきんにして、もう一度使う」ことを表す語は、reduce・reuse・recycle のどれですか。\",\"wrongAnswer\":\"recycle\",\"trapExplanation\":\"「何かに作り直す」と考えて、recycle を選んでしまう。しかし、シャツをとかして別の物に作り直したわけではない。\",\"correctAnswer\":\"reuse\",\"correctExplanation\":\"古いシャツの形を大きく変えず、ぞうきんとして、もう一度使っているので reuse である。recycle は、使い終わった物を、とかすなどして、材料から別の物に作り直すことである。\"},{\"question\":\"次の英文の意味を答えなさい。We should reduce plastic trash.\",\"wrongAnswer\":\"わたしたちはプラスチックごみを作り直しました。\",\"trapExplanation\":\"reduce を、reuse や recycle と取りちがえ、should を過去の意味と考えてしまう。\",\"correctAnswer\":\"わたしたちはプラスチックごみをへらすべきです。\",\"correctExplanation\":\"reduce は「へらす」、should は「〜すべきだ」の意味で、あとの動詞は原形になる。「作り直す」は recycle である。\"}]}",
"{\"id\":\"nt_ntce_03\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"order\":30453,\"targetLevel\":\"oyo\",\"title\":\"学校のICTの英文：tablet・online・password を使った表現\",\"description\":\"タブレットやオンラインに関する語と、動詞とのセット、ルールの命令文を学ぶ\",\"intro\":\"授業でタブレットを使って調べたり、遠くの人とビデオ通話で話したりする学校がふえました。英語の入試でも、こうした学校のくらしが話題になる文章が出ています。道具の名前と、いっしょに使う動詞を、セットで覚えましょう。\",\"keyPoints\":[\"tablet（タブレット）・online（つながっている）・password（合言葉）・screen（画面）・camera（カメラ）・video call（ビデオ通話）\",\"道具は use、写真は take、メールは send、ファイルは open を使う\",\"日本では2019年12月にGIGAスクール構想が発表され、小・中学生に1人1台の端末を用意する考えが示された\",\"each（ひとりひとり）のあとの名詞は単数：Each student has a tablet.\",\"Don't ～. は「〜してはいけない」、Please ～. は「〜してください」\",\"パスワードは家のかぎと同じ。人に教えてはいけない\",\"look up は「（辞書やインターネットで）調べる」\"],\"sections\":[{\"heading\":\"1. 学校のICTの語彙：道具と動詞をセットで\",\"level\":\"oyo\",\"figureId\":\"xf_nt_ntce_03\",\"body\":\"ICT（アイ・シー・ティー）は、パソコンやタブレット、インターネットなど、情報や通信に関する道具や技術のことである。学校で使う道具の英語を、まず確かめよう。\\n\\n■ 道具・ことばの一覧\\n　tablet：タブレット\\n　online：インターネットにつながっている\\n　password：合言葉（本人だけが知る文字の並び）\\n　screen：画面\\n　camera：カメラ\\n　video call：顔を見ながらする通話\\n\\n■ いっしょに使う動詞\\n　use a tablet：タブレットを使う\\n　take a picture：写真をとる\\n　send an e-mail：メールを送る\\n　open a file：ファイルを開く\\n　click the button：ボタンをクリックする\\n　look up a word：言葉を調べる\\n\\n■ 英文の例\\n　We use tablets in class.　（授業でタブレットを使います。）\\n　I take pictures of plants.　（わたしは植物の写真をとります。）\\n\\n★ ここがポイント：道具の名前は **動詞とセット** で覚える。**use a tablet**、**take a picture**、**send an e-mail**、**open a file** のように、決まった動詞を使う。\\n\\n⚠ 注意：「写真をとる」を、catch や get などにしない。決まった動詞は take である。\"},{\"heading\":\"2. なぜ動詞が決まっているのか\",\"level\":\"oyo\",\"body\":\"■ なぜ tablet には use を使うのか\\n道具は「使う」ものなので、動詞は use になる。see は「目に入る」、look at は「目を向けて見る」で、タブレットを動かして使う意味にはならない。\\n\\n■ なぜ写真は take なのか\\n英語では、take は「手に取る・自分のものにする」という意味がもとになっている。景色を自分のものとして切り取るので、写真は take a picture と言う。make や do は、この意味に合わないので使えない。\\n\\n■ なぜメールは send、ファイルは open なのか\\nメールは、相手へ向けて送り出すものなので send を使う。ファイルは、とじてあるものを開いて中身を見るので open を使う。動詞は、その動作の意味に合うものが選ばれている。\\n\\n■ 動詞と名詞のセットを覚えるとよいわけ\\n単語を1つずつ覚えると、文を作るとき、どの動詞を合わせればよいかがわからなくなる。「use a tablet」のように、セットのまま口に出して覚えると、そのまま文に使える。\\n\\n■ GIGAスクール構想と英文\\n日本では2019年12月に、GIGAスクール構想が発表された。小学生と中学生に、1人1台の端末を用意する考えである。英語では、Each student has a tablet. と言う。each は「ひとりひとり」の意味で、あとの名詞は単数になり、動詞には三単現の s がつく。\\n\\n★ ここがポイント：動詞は **その動作の意味に合うもの** が決まっている。**セットのまま覚える** と、そのまま文に使える。each のあとは **単数名詞＋has**。\\n\\n⚠ 注意：each student（単数）に対しては has を使う。Each student have ... とは書かない。\"},{\"heading\":\"3. ルールを表す英文：Don't と Please\",\"level\":\"oyo\",\"body\":\"■ ルールの文は命令文が中心\\n学校のICTのルールを英語で言うときは、命令文を使う。命令文は、主語を言わず、動詞の原形から始める。\\n\\n■ 3つの型\\n　Don't tell your password.　（パスワードを教えてはいけません。）\\n　Please turn off the tablet.　（タブレットの電源を切ってください。）\\n　Ask a teacher first.　（まず先生に聞きましょう。）\\n\\n　Don't ～.：〜してはいけない\\n　Please ～.：〜してください\\n　～ first.：まず〜しなさい\\n\\n■ 例文\\n　Don't use the tablet during lunch.　（昼食の間はタブレットを使ってはいけません。）\\n　Please close the file.　（ファイルを閉じてください。）\\n\\n■ なぜ Don't のあとは動詞の原形なのか\\n命令文は、相手に直接話しかけるので、主語（you）を言わない。主語がないので、動詞は何も変化せず、原形のままになる。\\n\\n★ ここがポイント：Don't のあとは **動詞の原形**。**Please** をつけると、ていねいな言い方になる。\\n\\n⚠ 注意：Don't のあとに、動詞に s をつけたり、ing をつけたりしない。Don't uses ... や Don't using ... はまちがい。\"},{\"heading\":\"4. なぜパスワードは教えてはいけないのか\",\"level\":\"oyo\",\"body\":\"■ パスワードは家のかぎと同じ\\nパスワードは、自分のタブレットやアカウントを守るための、自分だけが知る合言葉である。家のかぎと同じ役目をしている。\\n\\n■ なぜ友だちにも教えてはいけないのか\\n教えてしまうと、他の人があなたの名前でログインして、あなたのファイルを見たり、書きかえたりできてしまうからである。また、その人が悪いことをしたとき、あなたがしたと思われてしまう。\\n\\n■ 英文の例\\n　Don't tell your password to others.　（パスワードを他の人に教えてはいけません。）\\n　A password is like a key.　（パスワードはかぎのようなものです。）\\n\\nlike は「〜のような」の意味である。\\n\\n■ 困ったときは\\n忘れてしまったときは、1人で悩まず、先生や家の人にたずねる。英語では、Ask a teacher first. と言える。\\n\\n★ ここがポイント：パスワードは **家のかぎと同じ**。**自分だけが知る** ものであり、**だれにも教えない**。\\n\\n⚠ 注意：「友だちならいいだろう」と思って教えてはいけない。いっしょに使いたいときは、先生にことわる。\"},{\"heading\":\"5. 声に出して確かめる手順\",\"level\":\"oyo\",\"body\":\"ICTの英文を書いたり話したりしたら、次の手順で声に出して確かめる。\\n\\n■ 手順\\n①文を、はじめから声に出して読む。\\n②動詞と名詞が、セットで正しいか確かめる。（use a tablet か、see a tablet ではないか）\\n③each のあとの名詞が単数か、has になっているかを確かめる。\\n④命令文のとき、Don't のあとに動詞の原形が来ているか確かめる。\\n⑤読み終わったら、日本語で言いかえてみて、意味が合っているか確かめる。\\n\\n■ なぜ声に出すのか\\nセットになった言い方は、口に出すと、リズムよく言えるかどうかで、正しいかがわかるからである。まちがえたセットは、つっかえて言いにくい。\\n\\n■ ふだんの練習\\n1日に1つ、学校でしたICTの行動を、英語で言ってみる。たとえば、I used a tablet in science class.（理科の授業でタブレットを使いました。）のようにする。\\n\\n★ ここがポイント：文は **声に出して読み**、**動詞と名詞のセット**、**each の単数**、**命令文の動詞の原形** の3か所を確かめる。\\n\\n⚠ 注意：日本語のままに直訳すると、動詞がちがってしまうことが多い。決まったセットを覚えて使う。\"}],\"trapExamples\":[{\"question\":\"「わたしたちは授業でタブレットを使います。」を表すように、（　）に入る語を答えなさい。We（　）tablets in class.（see・use・watch から選ぶ）\",\"wrongAnswer\":\"see\",\"trapExplanation\":\"「見る」ことに注目して、see を選んでしまう。しかし、タブレットは見るだけでなく、動かして使う道具である。\",\"correctAnswer\":\"use\",\"correctExplanation\":\"道具を使うときの動詞は use である。see は「目に入る」、watch は「動くものをじっと見る」の意味で、タブレットを使う意味にはならない。\"},{\"question\":\"次の英文の意味を答えなさい。Don't tell your password to others.\",\"wrongAnswer\":\"パスワードを他の人に教えなさい。\",\"trapExplanation\":\"tell を見て「教える」だけを読み取り、Don't（〜してはいけない）の意味を見落としてしまう。\",\"correctAnswer\":\"パスワードを他の人に教えてはいけません。\",\"correctExplanation\":\"Don't ～. は「〜してはいけない」の意味である。tell your password to others は「あなたのパスワードを他の人に教える」なので、全体で「教えてはいけません」の意味になる。\"}]}",
"{\"id\":\"nt_ntce_04\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"order\":30454,\"targetLevel\":\"oyo\",\"title\":\"日本の文化を英語で紹介する：festival・和食・給食\",\"description\":\"日本の行事や食べ物を、外国の人に3つの文で紹介する型と、必要な語や言い方を学ぶ\",\"intro\":\"外国から来た友だちに、「たなばたって何？」と聞かれたら、英語で答えられるでしょうか。日本のことを英語で紹介する問題は、最近の入試でも出ています。知らない人に話すつもりで、短い文を3つ重ねる型を身につけましょう。\",\"keyPoints\":[\"行事の紹介は「何か」「何をする」「どう思う」の3文で言う\",\"月だけなら in July、日付まで言うなら on July 7\",\"日本語の名前は、This is called ～.（これは〜と呼ばれる）で教える\",\"知らない語は、Onigiri is a rice ball. のように、やさしい英語で言いかえる\",\"2013年12月に、和食がユネスコの無形文化遺産に登録された\",\"「いただきます」は Thank you for the food. と言うと意味が伝わる\",\"festival（祭り・行事）、fireworks（花火）、rice ball（おにぎり）、school lunch（給食）を覚える\"],\"sections\":[{\"heading\":\"1. 行事を紹介する3つの文\",\"level\":\"oyo\",\"figureId\":\"xf_nt_ntce_04\",\"body\":\"日本の行事を英語で紹介するとき、3つの文で言うと、聞く人にわかりやすく伝わる。\\n\\n■ 3つの文\\n　1文目：何かを言う（名前と種類）\\n　2文目：何をするかを言う\\n　3文目：自分の気持ちを言う\\n\\n■ 例：たなばた\\n　Tanabata is a festival. （たなばたは行事です。）\\n　People write wishes. （人々はねがいごとを書きます。）\\n　It is fun. （それは楽しいです。）\\n\\n■ ほかの行事の例\\n　Setsubun is a spring event. People throw beans. It is exciting.\\n　（節分は春の行事です。人々は豆をまきます。わくわくします。）\\n　New Year's Day is on January 1. We eat special food. It is delicious.\\n　（元日は1月1日です。特別な食べ物を食べます。おいしいです。）\\n\\n■ なぜ3つの文が必要なのか\\n外国の人は、たなばたを知らないかもしれない。1文目で「行事だ」と教え、2文目で様子を想像してもらい、3文目で気持ちを伝えれば、初めて聞く人にも伝わる。\\n\\n★ ここがポイント：紹介は **「何か」→「何をする」→「どう思う」** の順で、**短い文を3つ** 並べる。\\n\\n⚠ 注意：2文目の主語が people（複数）のときは、動詞に s をつけない。People write ... が正しく、People writes ... とは書かない。\"},{\"heading\":\"2. なぜ in と on を使い分けるのか\",\"level\":\"oyo\",\"body\":\"■ 月は in、日付は on\\n　Tanabata is in July.　（たなばたは7月です。）\\n　Tanabata is on July 7.　（たなばたは7月7日です。）\\n\\n■ なぜ使い分けるのか\\nin は「広い入れ物の中」というイメージで、1か月のように長い期間に使う。on は「表面にぴったりついている」というイメージで、1日のように、ピンポイントで決まる日に使う。だから、月だけなら in、日付まで言うなら on になる。\\n\\n■ 曜日・日付の言い方\\n　on Sunday（日曜日に）\\n　on January 1（1月1日に）\\n　in summer（夏に）\\n　in 2013（2013年に）\\n\\n■ 出来事には年をそえる\\n和食の話をするときは、年も言うと、話がはっきりする。\\n　Washoku became a UNESCO Intangible Cultural Heritage in 2013.\\n　（和食は2013年に、ユネスコの無形文化遺産になりました。）\\nbecame は become（〜になる）の過去形である。\\n\\n★ ここがポイント：**月・季節・年は in**、**日付・曜日は on**。範囲が広ければ in、ピンポイントなら on と考える。\\n\\n⚠ 注意：on July 7 を in July 7 としない。日付まで言うときは on である。\"},{\"heading\":\"3. 日本の食べ物を紹介する：called と言いかえ\",\"level\":\"oyo\",\"body\":\"■ This is called ～.\\n日本語の名前は、外国の人には知らないことが多い。called は「と呼ばれている」という意味で、名前を教える言い方になる。\\n　This is called onigiri.　（これは onigiri と呼ばれています。）\\n　We call it onigiri.　（わたしたちはそれを onigiri と呼びます。）\\n\\n■ やさしい言いかえをそえる\\n名前のあとに、知っている語で説明を足すと、もっとよく伝わる。\\n　Onigiri is a rice ball.　（おにぎりは、ごはんのボールです。）\\n　Miso soup is a soup with miso.　（みそ汁は、みそを入れたスープです。）\\n　Natto is fermented soybeans.　（なっとうは、発酵させた大豆です。）\\n\\n■ なぜ called を使うのか\\n「This is onigiri.」だけでは、onigiri が名前なのか、食べ物の種類なのかが、相手にはわからない。「called」をつけると、名前だと伝わる。called は「呼ばれている」という受け身の形である。\\n\\n■ 和食の話\\n2013年12月に、「和食：日本人の伝統的な食文化」が、ユネスコの無形文化遺産に登録された。英語で紹介するときは、年をそえて言う。\\n\\n★ ここがポイント：**This is called ～.** で名前を教え、**やさしい英語の言いかえ** をそえる。\\n\\n⚠ 注意：called の ed をつけ忘れて、This is call onigiri. としない。「呼ばれている」と受け身の意味なので、called にする。\"},{\"heading\":\"4. 学校の紹介：給食とあいさつ\",\"level\":\"oyo\",\"body\":\"■ 給食を紹介する\\n日本の学校の給食は、外国の人にめずらしがられる話題である。\\n　In many Japanese schools, students serve school lunch.\\n　（日本の多くの学校では、生徒が給食を配ります。）\\n　We eat lunch in the classroom.\\n　（わたしたちは教室で昼食を食べます。）\\n\\nserve は「配る・出す」の意味である。\\n\\n■ 「いただきます」の伝え方\\n日本語の「いただきます」を、そのまま英語にする言葉はない。意味が伝わるように、気持ちを言いかえる。\\n　Thank you for the food.　（食べ物に感謝します。）\\n\\n■ なぜ言いかえるのか\\n言葉は、国によって、使う場面がちがう。「いただきます」のように、意味をそのまま訳しにくい言葉は、「何のためにその言葉を言うのか」という気持ちを伝えると、通じやすくなる。\\n\\n■ 3文での紹介の例\\n　School lunch is a Japanese school custom. Students serve the food. I like it.\\n　（給食は日本の学校の習慣です。生徒が配ります。わたしは好きです。）\\n\\n★ ここがポイント：訳しにくい言葉は、**気持ちや意味** で言いかえる。Thank you for the food. のように、**何のために言うか** を伝える。\\n\\n⚠ 注意：日本語を英語に一語ずつ置きかえようとすると、不自然になる。意味が伝わる、やさしい言い方を選ぶ。\"},{\"heading\":\"5. 声に出して確かめる手順\",\"level\":\"oyo\",\"body\":\"日本の文化を紹介する英文を書いたり話したりしたら、声に出して確かめる。\\n\\n■ 手順\\n①3つの文を、はじめから声に出して読む。\\n②1文目が「何か」、2文目が「何をする」、3文目が「どう思う」になっているか確かめる。\\n③月や日付の前の in・on が合っているか確かめる。\\n④日本語の名前に、This is called ～. や言いかえをつけたか確かめる。\\n⑤聞く人が、知らなくてもわかるか、考えて読み直す。\\n\\n■ なぜ声に出すのか\\n声に出して読むと、文と文のつながりが自然かどうかがわかるからである。長すぎる文や、聞きとりにくい言葉に気づける。\\n\\n■ ふだんの練習\\n家族に、日本の行事を1つ選んで、3つの文で紹介してみる。相手が「もっと知りたい」と言ったら、成功である。\\n\\n★ ここがポイント：**3つの文**、**in と on**、**called と言いかえ** の3か所を、声に出して確かめる。\\n\\n⚠ 注意：覚えた文を、すらすら言うことがゴールではない。相手に伝わることが大切である。\"}],\"trapExamples\":[{\"question\":\"（　）に入る語を答えなさい。Tanabata is（　）July 7.（in・on・at から選ぶ）\",\"wrongAnswer\":\"in\",\"trapExplanation\":\"「7月」だから in だと思ってしまう。しかし、July 7 は月ではなく、日付まで言っている。\",\"correctAnswer\":\"on\",\"correctExplanation\":\"日付や曜日には on を使う。July だけなら in July、July 7 のように日付まで言うなら on July 7 である。\"},{\"question\":\"「これはおにぎりと呼ばれています。」を表す英文として正しいものを選びなさい。（This is call onigiri. ／ This is called onigiri.）\",\"wrongAnswer\":\"This is call onigiri.\",\"trapExplanation\":\"「呼ぶ」の call をそのまま使ってしまう。「呼ばれている」という受け身の意味には、call の形では合わない。\",\"correctAnswer\":\"This is called onigiri.\",\"correctExplanation\":\"「呼ばれている」は、be 動詞のあとに called を置く。This is called ～. で、名前を教える言い方になる。\"}]}",
"{\"id\":\"nt_ntce_05\",\"subject\":\"eigo\",\"examType\":\"chugaku\",\"studyPeriod\":\"小6後半・直前\",\"order\":30455,\"targetLevel\":\"oyo\",\"title\":\"スピーキングの型：先生の質問に「答え＋ひとこと」で答える\",\"description\":\"面接形式のスピーキングで、Yes・Noのあとにひとこと足す型と、聞き返しの言い方を学ぶ\",\"intro\":\"「Do you like sports?」と聞かれて、「Yes.」とだけ答えて、そのまま黙ってしまった。そんな経験はありませんか。話す力を見る試験がふえ、短く答えるだけでなく、自分の文をひとこと足す練習が大切になっています。答えやすい型を身につけましょう。\",\"keyPoints\":[\"Yes, I do. で終わらず、ひとこと足す：Yes, I do. I play soccer on Sundays.\",\"質問のはじめの語に合わせて答える：Do → do、Can → can、Are → am・are\",\"No のときは、No, I don't. But I like ～. のように、But でつなぐ\",\"What で聞かれたら、Yes・No ではなく、文で答える\",\"Why? と聞かれたら、Because ～. で理由を言う。理由は1つで十分\",\"聞こえなかったら、Pardon? や Could you say that again, please? と聞き返す\",\"知らない語は、I don't know the word. と伝え、知っている語で言いかえる\"],\"sections\":[{\"heading\":\"1. 「答え」＋「ひとこと」の2文\",\"level\":\"oyo\",\"figureId\":\"xf_nt_ntce_05\",\"body\":\"先生の質問に答えるときは、短く答えるだけでなく、ひとこと足すと、話がよく伝わる。\\n\\n■ 例\\n　先生：Do you like sports?（スポーツは好きですか。）\\n　あなた：Yes, I do. I play soccer on Sundays.\\n　（はい、好きです。日曜日にサッカーをします。）\\n\\n■ No のとき\\n　先生：Do you like dogs?（犬は好きですか。）\\n　あなた：No, I don't. But I like cats.\\n　（いいえ。でも、ねこは好きです。）\\n\\n■ ひとこと足す文は、短くてよい\\n　I play ～.（〜をします）\\n　I like ～.（〜が好きです）\\n　I have ～.（〜を持っています）\\nこうした文なら、小学生がふだん使っている語で足せる。\\n\\n★ ここがポイント：Yes・No のあとに **ひとこと足す**。足す文は **短く、やさしい文** でよい。\\n\\n⚠ 注意：No のあとは、そのまま黙らない。No, I don't. で終わらず、But ～. で、好きなものを言うと話が続く。\"},{\"heading\":\"2. なぜひとこと足すのか、なぜ質問の語に合わせるのか\",\"level\":\"oyo\",\"body\":\"■ なぜひとこと足すのか\\nYes, I do. だけでは、「好き」ということしか伝わらない。何をするのか、どんなふうに好きなのかは、相手にはわからない。話す力を見る場面では、自分で考えた文が出せるかが大切になる。ひとこと足せば、話が広がり、聞いている人も話しやすくなる。\\n\\n■ なぜ質問の語に合わせて答えるのか\\n英語の質問は、文のはじめの語（Do・Can・Are）が、何をたずねているかを示している。同じ語で答えると、質問にきちんと答えたことが、すぐ相手に伝わる。\\n　Do you like dogs?　→　Yes, I do. / No, I don't.\\n　Can you swim?　→　Yes, I can. / No, I can't.\\n　Are you from Osaka?　→　Yes, I am. / No, I'm not.\\n\\n■ なぜ答えの I は変わらないのか\\n質問の you は、あなた（相手）のことである。答えるのは自分なので、you は I に変わる。この入れかえは、人称の変化のきまりである。\\n\\n■ What や Why の質問\\nWhat で聞かれたら、Yes・No では答えられない。文で答える。\\n　What is your favorite food?　→　I like curry.\\nWhy? と聞かれたら、Because ～. で理由を言う。\\n　Why?　→　Because it is spicy.（辛いからです。）\\n理由は、1つ言えれば十分である。\\n\\n★ ここがポイント：質問の **はじめの語** が、答えの形を決める。**Do → do、Can → can、Are → am・are**。**What は文で、Why は Because で** 答える。\\n\\n⚠ 注意：Do you ～? に Yes, I like. と答えない。質問の語（do）をそのまま使う。\"},{\"heading\":\"3. 質問のタイプ別の答え方\",\"level\":\"oyo\",\"body\":\"■ Yes・No で答える質問\\n　Do you ～?　→　Yes, I do. / No, I don't.\\n　Can you ～?　→　Yes, I can. / No, I can't.\\n　Are you ～?　→　Yes, I am. / No, I'm not.\\nどれも、答えのあとに、ひとこと足す。\\n\\n■ 文で答える質問\\n　What do you do on weekends?（週末は何をしますか。）\\n　→ I play with my friends.（友だちと遊びます。）\\n　What is your favorite subject?（好きな教科は何ですか。）\\n　→ I like science.（理科が好きです。）\\n\\n■ 理由をたずねる質問\\n　Why do you like science?（なぜ理科が好きですか。）\\n　→ Because experiments are fun.（実験が楽しいからです。）\\nbecause のあとは、主語と動詞のある文を続ける。\\n\\n■ 組み合わせの例（3文）\\n　What is your favorite food?\\n　I like curry. It is spicy. I eat it every week.\\n　（カレーが好きです。辛いです。毎週食べます。）\\n\\n★ ここがポイント：質問が **Yes・No** か、**What** か、**Why** かを、まず聞き分ける。聞き分けたら、その型に合った答えを返す。\\n\\n⚠ 注意：Why? の答えに、Because だけで終わらせない。Because のあとに、主語と動詞のある文を続ける。\"},{\"heading\":\"4. 聞こえなかったとき・言葉が出ないとき\",\"level\":\"oyo\",\"body\":\"■ 聞き返す\\n質問が聞き取れなかったら、だまらずに聞き返してよい。\\n　Pardon?　（もう一度お願いします。）\\n　Could you say that again, please?　（もう一度言っていただけますか。）\\n　Could you speak more slowly, please?　（もう少しゆっくりお願いします。）\\n\\n■ 言葉が出ないとき\\n　I don't know the word.　（その言葉がわかりません。）\\nそのあと、知っている語で言いかえる。たとえば、「あじさい」という語を知らなくても、It is a blue flower. と言えば伝わる。\\n\\n■ なぜ聞き返してよいのか\\n会話は、おたがいにわかり合うために行うものだからである。聞き取れないまま、まちがえた答えをするより、聞き返して正しく答えるほうが、よい会話になる。\\n\\n■ つなぎの言葉\\n考える時間がほしいときは、Well, ...（ええと）と言うと、だまらずに時間をかせげる。\\n\\n★ ここがポイント：**聞こえなければ聞き返す**。言葉が出なければ、**知っている語で言いかえる**。だまってしまうのがいちばんよくない。\\n\\n⚠ 注意：聞き返すときも、小さな声でなく、相手に聞こえる声で言う。Pardon? の最後は、少し上げて言う。\"},{\"heading\":\"5. 声に出して確かめる手順\",\"level\":\"oyo\",\"body\":\"スピーキングは、頭で考えるだけでなく、声に出す練習で上達する。\\n\\n■ 手順\\n①質問を1つ決めて、声に出して答えてみる。\\n②1文目が、質問のはじめの語に合っているか確かめる。（Do → do）\\n③ひとこと足す文が、短くて、言いやすいか確かめる。\\n④Why? と聞かれた場合の Because の文も、あわせて言ってみる。\\n⑤最後に、聞き返しの言葉（Pardon?）も、声に出して言ってみる。\\n\\n■ なぜ声に出すのか\\nスピーキングのテストは、声に出さなければ点にならない。ふだんから口を動かしておくと、本番で言葉が出やすくなる。\\n\\n■ ふだんの練習\\n家族に先生役をしてもらい、5つの質問に答える。1日1回、3分でよい。答えるたびに、必ず「ひとこと」を足すと決めておく。\\n\\n★ ここがポイント：**質問の語に合わせた答え**、**ひとこと**、**Because の理由**、**聞き返し** の4つを、声に出して練習する。\\n\\n⚠ 注意：覚えた文を暗記して言うだけでは、質問が変わったときに対応できない。質問を聞いて、自分で文を作る練習をする。\"}],\"trapExamples\":[{\"question\":\"Do you like dogs? に「はい、好きです。」と答える英文を選びなさい。（Yes, I like. ／ Yes, I do.）\",\"wrongAnswer\":\"Yes, I like.\",\"trapExplanation\":\"日本語の「好きです」に引きずられて、like をそのまま使ってしまう。しかし、質問のはじめの語は do である。\",\"correctAnswer\":\"Yes, I do.\",\"correctExplanation\":\"Do you ～? とたずねられたら、do を使って Yes, I do. と答える。そのあとに、I have a dog. のようにひとこと足すと、話が伝わる。\"},{\"question\":\"Are you from Osaka? に「はい、そうです。」と答える英文を選びなさい。（Yes, I am. ／ Yes, I do.）\",\"wrongAnswer\":\"Yes, I do.\",\"trapExplanation\":\"Yes の答えは Yes, I do. だと覚えてしまい、質問のはじめの語を見ない。\",\"correctAnswer\":\"Yes, I am.\",\"correctExplanation\":\"質問が Are you ～? のときは、be 動詞で答える。I のときの be 動詞は am なので、Yes, I am. が正しい。\"}]}"
];

export const lessons: Lesson[] = rows.map((r) => JSON.parse(r) as Lesson);
